INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-gokhan-bozdogan-j1kif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni seviyorum demek,

hiçbir zaman bu kadar güzel olmamıştı.

hiçbir zaman böylesine,

sevip sevilmemişti bu yürek.

yüreğinde bana ve sevgime yer varmı?

yer var mı aşka ve umuda?

o zaman yukarıya bak,

ben ordayım her zaman yanındayım.

gündüz güneşi''mle gece ay''ımla,

kimsenin kucaklayamayacağı kadar

kucakladım seni.

bazen bir umut olmalıyım yüreğinde

güzel yarınlarda gerçekleşmeyi bekleyen.

sonra bir hayal düşüncelerinde,

seni başka alemlere görüren.

karanlık düşüncelerinde ki

son yaprak olmalıyım ben,

hiç solmayan bir yaprak.

seni yaşamalıyım duygularda,

seni hissetmeliyim her nefes alışında.

yağmur olup üstüne yağmalıyım,

her damla benim sana olan sevgimdir.

ıslanmalısın sevgi yağmurlarında.

aydınlığın olmalıyım sonra,

buğday sarısı güneşimle.

kar''a kartanesi''ne ne dersin 

bembeyaz saf aşklar yaşamak için.

ben senin vazgeçemediğin 

gökyüzün olmalıyım.

ne sen beni unutmalısın,

ne de ben ben sensiz evreni kucaklamalıyım.

seni seviyorum demek

hiçbir zaman bu kadar güzel olmamıştı.

hiçbir zaman böylesine 

sevip sevilmemişti bu yürek.

şimdi ben o güzeli seninle yaşıyorum,

ve

seni çok seviyorum.', 'seni seviyorum demek, hiçbir zaman bu kadar güzel olmamıştı. hiçbir zaman böylesine, sevip sevilmemişti bu yürek. yüreğinde bana ve sevgime ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Şeyler', 'i-mkansiz-seyler-umit-yasar-oguzcan-irgo0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İmkansız olan şeyler vardır bilirsin

Yaşlanmamak gibi, ölmemek gibi

Ve seni sevmemek çigan gözlüm

Mümkün degil ki

Çıkarıp atamam içimden

Neyleyim yer etmişsin bir kere

Ne zaman elime bir kagıt alsam

Siner güzelligin kelimelere

Yumsam gözlerimi seni seyrederim

Devamlı bir musiki kulaklarımda sesin

Mevsimler seninle başlar, seninle biter

Yıl oniki ay benimlesin

Ne zaman bir gemi görsem limanda

Alıp başımı seninle gitmek isterim

Umurumda degil bu oyunlar, bu düzenler

Anlasana; seni arıyor ellerim

İmkansız düşünmemek gecelerce seni

Ve sevmemek ömür boyunca, bir gün degil

''Başka çaremiz yok, beni unut'' demiştin

Mümkün degil çigan gözlüm, mümkün degil.', 'İmkansız olan şeyler vardır bilirsin Yaşlanmamak gibi, ölmemek gibi Ve seni sevmemek çigan gözlüm Mümkün degil ki Çıkarıp atamam içimden Ney...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/imkansiz-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Bir Kere Ölür', 'i-nsan-bir-kere-olur-umit-yasar-oguzcan-grdoo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her bulunduğum yerde yitiriyorum seni

Yanıbaşımda öldüğün oluyor kimi gün

Ya da ben ölüyorum sessizce gözlerinde

Bir yaprak kımıldıyor hafiften

Bu sessizlik bir kasırga başlangıcı

Kükremeye hazırlanışı denizin

Bu, aslanların sarı, vahşi gözlerindeki ölüm parıltısı

Bu bir yerde erimek

Apansız yok olmak belki de

Ve sonra susmak, susmak yüzyıllar boyu

Beni unuttuğun bir uzak çizgide

Tuvale sürdüğüm boya değil artık

Kırmızı kan rengidir gözlerimin

En karadan daha kara yok

Oysa en beyazdın sen gecelerimde

O bana en yakın renkti tüy gibi

Buram buram sıcaklığını çizerdim duvarlara

Kokun bir tuhaftı çocuksu

Sonra katmerli bir gül gibiydi baygın

Gecenin en koyulaştığı o yerde

Düşerdi ellerime darmadağın.

Öten bir ishak kuşudur şimdi

Haber getirir ölümlerden, dinle

Yaşamak bir manga asker karşımda

Ateş etmeyin diyorum

Bir diyeceğim var

Gözlerimi bağlamayın

Son defa görmek istiyorum insanı

Göğü, güneşi, denizleri

Ve bu son ölümün olsun diyorum

Bir daha öldürmeyin beni.

Kibritim ıslak

Sigaram yanmıyor

Ne olur bir ateş verin

Bu ilk aldanışım değil

Bu ilk sönüşü değil umutlarımın

Ben bu denizin son kıyısıyım.

Bir cam kırıldı uzakta

Ta uzakta, içimde bir cam kırıldı

Bütün şiirlerim anlamsız şimdi

Resimler renksiz, şarkılar ruhsuz

Hiç bir şey artık avutamaz beni

Bakın, bir çağ devriliyor içimde sersefil

Son şair de kırdı son kelemini

İlk meşaleyi kim yaktı bu karanlıkta

Kimdi aydınlatan benim zindan gözlerimi

Sevilmek mi

O son artığı en ilkel çağların

Bir mağara duvarındaki en eski resim

Ya sevmek

Hiç sönmeden bir ömür boyu

O en güzel huy benimsediğim

Yıkıldıkça tutunduğum dal bu boşlukta

O en insancıl gerçeğim benim

Ben hep böyle yüzyıllar boyu sevdim

Çağlar boyu

Kopkoyu bir geceydi yaşadığım sevince

Ellerimi arardım, bulamazdım çoğu gün

Bir saklayan vardı beni

Bir tutan vardı

Sana yaklaşamazdım

Anlayamadığım korkular vardı içimde

Hep böyle seninle sensiz kalırdım ben

Bir kıvılcım sönerken

Bir yanardağ patlardı içimde.

Ko şimdi ben yalnız öleyim

Vur ellerimi ekmeğimi al

Tiksinir beni kim görse sensiz

Utanır yalnızlığım bana baktıkça

Aynalar mı

Hani nerdeler

Kimbilir kaç yüzyıl oldu kendimi görmeyeli

Adım mı neydi

Besbelli unutmuşum

Hadi vur

Hadi öldür

Kurtar beni ezilmekten çürümekten

Hadi gel, açtım kollarımı

Bir zaman

Ölmeye vaktim mi vardı seni sevmekten

Sen büyüyen bir sessizliktin içimde

Beni ben eden en duru ırmaktın

En güzeliydin mozaiklerin

Seninle maviydi gökyüzüm

Çiçeklerim sende yeşerirdi

Sen bambaşka bir evren yaratırdın

Sularımdan güneşimden rüzgarımdan

Bak! Nasıl da her şey değişiverdi apansız

Şimdi bu karanlıklarda yapayalnız

Mavi mavi bir resim ağlar duvarlarımdan

Ben bir tohumum

Al beni toprağa ek yeniden

Neredesin hani ne oldun

Antik bir kadın başı mıydın

Yoksa bir deniz miydin eskiden

Yosunların kurudu mu öldü mü balıkların

Hani bir Nefertiti yaşamıştı eski Mısır''da

Yoksa o muydun sen

Hadi, anlat bana neydin

Belki de uzak belirsiz bir noktaydın sen

Öyküme girmeseydin

İnsan bir kere ölür

Her gün ölen umutlarımızdır içimizdeki

Paramparça olmuş sevgilerdir

Her aldanış

Yeni bir aldanışa hazırlar bizi

Zamanla renkler değişir

Donuklaşır anılar

Silinir usumuzdan

Güzel olan ne varsa

Görür içindeki bütün hayallerin öldüğünü

İnsan yaşarsa.

Ve bir gün insan da ölür

Çimen gibi yaprak gibi

Sarsılır yeryüzü yerinden

Devrilen koca bir ağaçtır sanki

Durur atışları yorgun kalbimizin

El, ayak kesilir

Göz ölür, dudak ölür, kan ölür

Susar ta içimizde

Yıllardır çalan çalgı

Bütün teller ses vermez olur

Acılar diner

Ve bir gün biter bu çirkin oyun

Perde iner...', 'Her bulunduğum yerde yitiriyorum seni Yanıbaşımda öldüğün oluyor kimi gün Ya da ben ölüyorum sessizce gözlerinde Bir yaprak kımıldıyor hafif...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/insan-bir-kere-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SaNa SiTeM', 'sana-sitem-harun-kesik-ojukm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana sitem ettim yıllarca

Sana sitem ettim ömrüm boyunca

Sen beni anlamadın

Ben ne yapayım be zalim

Sen Kalktın gece yataktan

Uyku aradın kuşluğa

Gelmedi bulamadın 

Sana sitem ettim yıllarca

Ömür boyu bi kaşık suya

Muhtaç oldun yıllarca

Sen benim değerimi bilmedim

Sana sitem ettim yıllarca

Kör gözünle kalktın ayaza

Yat uyu dedim bahara

Sen beni deli ettin yaza

Sana sitem ettim yıllarca

Tencere tava baklava

Gözün doymaz pazara

Al sok gözüne gözüne 

Sana sitem ettim yıllarca', 'Sana sitem ettim yıllarca Sana sitem ettim ömrüm boyunca Sen beni anlamadın Ben ne yapayım be zalim Sen Kalktın gece yataktan Uyku aradın ku...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli Çağ', 'kirli-cag-umit-yasar-oguzcan-q24ik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl da degişiyor kişi zamanla

Güç o güç degil hız o hız degil

İnançlar sarsılmış, umutlar yitik

Bu kirli çag bizim çagımız degil

Yeşiller, maviler kapkara olmuş

Yorgun eller, ayaklar, yollarsa yokuş

Ne açan güller var, ne öten bir kuş

Güneş o güneş degil, yıldız o yıldız degil

Kökünden bir kurt girmiş agaca

Yapraklar perişan, dal paramparça

Daha çok aldanacagız yaşadıkça

Anlasana bu ilk aldanışımız degil', 'Nasıl da degişiyor kişi zamanla Güç o güç degil hız o hız degil İnançlar sarsılmış, umutlar yitik Bu kirli çag bizim çagımız degil Yeşiller,...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirli-cag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaparo', 'kaparo-harun-kesik-r234t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaporasız olmaz dedin

Başımın etini yedin

Kaporasız olmaz arkadaş

Her şey parayla yok bedava

Gittim matbaya 

Çıkamadım öbür aya

Niye dersen bana 

Kapora ver dedi bana

Canım yanmaz paradan puldan

Eşim dostum geçilmez eurodan dolardan

Ah şu kapora da olmasa

Avrupaya kaçacam valla', 'Kaporasız olmaz dedin Başımın etini yedin Kaporasız olmaz arkadaş Her şey parayla yok bedava Gittim matbaya  Çıkamadım öbür aya Niye dersen ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaparo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Var', 'olum-var-harun-kesik-imao6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her zaman  yanı başımızda

Zaman tanımazki bir saat daha

Ben bulamadım çaresini 

Bulan varsa akıl versin bana

Bir dost dedi ki bana

Bu derde tek deva

Gel kardeşim kur''an a

Kurtul derdi bana

Başka çare yokmudur 

Tek çare bu mudur?

Vardır bir derman daha

Namaz a gel Namaz a

Zaman geçiyor zaman

Haydi başla Zekat a

Geri kalma Oruç tan

Sonra bulamazsın derde deva', 'Her zaman  yanı başımızda Zaman tanımazki bir saat daha Ben bulamadım çaresini  Bulan varsa akıl versin bana Bir dost dedi ki bana Bu derde ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümdü O', 'olumdu-o-umit-yasar-oguzcan-moy34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümdü o, beni aldatmayın

Soguk nefesiydi yüzümde duydugum

Öyle sessizce öldum ki defalarca

Hiç bir zaman anlaşılmadı yoklugum

Hayatın omuzunda bir yük oldugu

Nice yalnız geceler, nice akşamlar

Tanrı biliyor ya kaç kere öldügümü

İnandım ölüme, aşka inandıgım kadar

Satır satır yaşadım yazdıklarımı

Ne saadetin ne güzel günün şairiyim

Kimse acımasın bana, istemem

Ben aşkın ve ölümün şairiyim.', 'Ölümdü o, beni aldatmayın Soguk nefesiydi yüzümde duydugum Öyle sessizce öldum ki defalarca Hiç bir zaman anlaşılmadı yoklugum Hayatın omuzu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumdu-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazoz Kapağı', 'gazoz-kapagi-harun-kesik-otetu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açtım kapağı kör delik

Kuyu Gibi alaşık bulaşık

Nedir bu coca cola

Ayran nerde süt nerde

Özledim ben sılamı

Nerde o eski perde

Her kez bir delik

Nedir bu coca cola

Fanta ne sprayt ne

Ben anlamam coca cola

Özledim ben sılamı 

Ayran nerde süt nerde

Ben ayrılamam sılamdan

Ayrılda gel istanbul dan

Bit artık köylünün işi

Makinalar geldi iş bitti

Ucu delikli Gazoz Kapağı', 'Açtım kapağı kör delik Kuyu Gibi alaşık bulaşık Nedir bu coca cola Ayran nerde süt nerde Özledim ben sılamı Nerde o eski perde Her kez bir d...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gazoz-kapagi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmez Kanun', 'degismez-kanun-harun-kesik-o3w6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Değişmez kanunu dünyanın 

Ölüm var arkadaş bitti işin

Sende geçeceksin sıradan bir gün

Çok yakın biliyorsun o gün

Elini atsan pislik

Yok mu aklı paklı işin 

Ben bulamadım arkadaş 

Nedir bu sırrı-işin

El atma her şeye 

Çıkar altından bir pire

Seni de yakar ötekini de

Yok mu aklı paklı işin

Boş ver gitme o yoldan

Senin yolun bu taraftan

Ben bulamadım arkadaş

Nedir sırrı-işin', 'Değişmez kanunu dünyanın  Ölüm var arkadaş bitti işin Sende geçeceksin sıradan bir gün Çok yakın biliyorsun o gün Elini atsan pislik Yok mu ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degismez-kanun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Ne Olmuş !!!', 'kim-ne-olmus-harun-kesik-b3439', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbulun taşı toprağı altınmış

Geldim gördüm altını bakırı gümüşü

Ben anlamadım mı sandım bu işi

Bende uyanığım arkadaş

İşi bitmiş istanbul un 

Gelmiş yetmiş iş bitmiş

Sende düzeltemezsin bende

Uğraşma arkadaş yorulursun sende

Gidiyordum istanbul da

Önüme çıktı bir Honda

Ulan nerdeyse ezdi geçti

Yaş gemiş iş bitmiş istanbul da

Ne lem bu kanalizasyon

Nerdeyse düşüyodum yolda

Bu tümsek ne çukur ne 

Anlamadım arkadaş 

Yaşşş yetmiş iş bitmiş istanbul da', 'İstanbulun taşı toprağı altınmış Geldim gördüm altını bakırı gümüşü Ben anlamadım mı sandım bu işi Bende uyanığım arkadaş İşi bitmiş istanbu...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kim-ne-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Gelmişse', 'boyle-gelmisse-harun-kesik-7sarh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımın baharında

Yaz geldi kışında

Bende tükendim arkadaş 

Ya al canımı kurtulayım Allahım

Nedir bu cahil insanlar

Biri neneye teyze

Biri yengeye teyze

Bende tükendim arkadaş

Saba kaltım uykumda

Gittim dolaba

Aç kaldı bu garip şair

Neden dersen bekle

İş yoksa bu garibe

Ne yapsın zarife fakire

O da istemez mi zengin e

Öldümü kaldımı bekle', 'Hayatımın baharında Yaz geldi kışında Bende tükendim arkadaş  Ya al canımı kurtulayım Allahım Nedir bu cahil insanlar Biri neneye teyze Biri...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boyle-gelmisse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey yolcu tutan mı var tutsak', 'ey-yolcu-tutan-mi-var-tutsak-i-lhan-yuksel-j0xqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu tahtada yatan hediye 

Ucuz bir ata bindirilmiş 

Dönüp geri gelmesin diye 

Soyunmuşta giyindirilmiş

Kalkıp yürü desek yürür mü 

Davet mi var esaret mi var 

Bu son gidiş bilse ölür mü 

Yoksa gider cesaret mi var 

Çağıran mı var gel diyen mi 

Gördüm gidiyor ağır aksak 

Aldığın bu yük hediyen mi 

Ey yolcu tutan mı var tutsak 

Niçin gidersin be hey yolcu 

Nasıl bu yolculuk zoru ne 

Bu fani hayatın ipucu 

Yahut cevabi ne soru ne', 'Bu tahtada yatan hediye  Ucuz bir ata bindirilmiş  Dönüp geri gelmesin diye  Soyunmuşta giyindirilmiş Kalkıp yürü desek yürür mü  Davet mi v...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-yolcu-tutan-mi-var-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamak Bulunmaz Kayda Geçilir', 'kacamak-bulunmaz-kayda-gecilir-i-lhan-yuksel-udwlh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah uyandim hayatin bittigini 

Anladim tüm yollar gider Allaha 

Ayagin gidip elin ettigini 

Taşlar dile gelip söyler Allaha 

Kaçamak bulunmaz kayda geçilir 

Isterse uzatilir günler geceler 

Bir günlük yol uzar ayda geçilir 

Kul olur hamallar beyler Allaha 

Ol denirse hemen olur olmazlar 

Görürsün küçülmüş önünde her sey 

Ne çoklar tükenmiş çogalmiş azlar 

Diz çöker o gün devler Allaha 

Sürtünür dik başlar varir secdeye 

Egmezsen egerler başini hemen 

Denilir geç oldu dövünmek niye 

Hiç gelir varlik degerler Allaha', 'Sabah uyandim hayatin bittigini  Anladim tüm yollar gider Allaha  Ayagin gidip elin ettigini  Taşlar dile gelip söyler Allaha  Kaçamak bulun...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kacamak-bulunmaz-kayda-gecilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun peşine Koşma Bedenim', 'ruhumun-pesine-kosma-bedenim-i-lhan-yuksel-rhkie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşılmaz yolları aşar yürütür 

Ruhumun peşine koşma bedenim 

Beşikten mezara besler büyütür 

Sonra terk ederse şaşma bedenim 

Bir yanda hakikat yalan bir yanda 

Yazın kışı yaşa kışınsa yazı 

Yolcu ol göğe yaşayıp zamanda 

Gece rüyalarda oldur olmazı 

Boş işler peşinde koşup yorulma 

Olma be ruhum böyle dengesiz 

Dalıp hülyalara tahta kurulma 

Olur, olmazları geçiştir sessiz 

Her gün değişir o renkten bu renge 

Gece alıp gider çıkmaz yollara 

Gün başlayınca çağırı cenge 

Kendine bu yolda başka dost ara', 'Aşılmaz yolları aşar yürütür  Ruhumun peşine koşma bedenim  Beşikten mezara besler büyütür  Sonra terk ederse şaşma bedenim  Bir yanda hakik...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruhumun-pesine-kosma-bedenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiği günden beri 2', 'gittigi-gunden-beri-2-huseyin-cayikli-32zh8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gittiğin gün yıldızlardan nefret ettim.

yıldızımızı tutmuştuk beraber

gittiğin gün otobüslerden,gazetelerden,insanlardan sıkıldım.

sen giderken ben arkama dönüp bakmadım.

Artık gitmiştin,

öylece kala kalmıştım

öylece vefasız öylede acımasız gitmiştin.

beni bırakıp gitmek kolaydı.

Bu şehri bu kokuyu bırakıp gitmek kolaydı

şimdi gittin 

artık olamayacaksın 

artık o çocuk sevgilim yanımda olmayacak mı?

yani gittin,

nasıl yaptın.

bilmiyorum...

ama yaptın.

demek şimdi gidiyorsun ve bana bir şey bırakmadan

hatıraları yok ederek 

hiç anmadan gidiyorsun

başka birisini buldum diye söyleyeceksen 

alçaksın.

şimdi git ve bana birşey

bırakarak o da yüreğin olsun

öyle git...', 'gittiğin gün yıldızlardan nefret ettim. yıldızımızı tutmuştuk beraber gittiğin gün otobüslerden,gazetelerden,insanlardan sıkıldım. sen gider...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittigi-gunden-beri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikayem', 'hikayem-huseyin-cayikli-qqsy1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birkaç gündür şiir yazamıyorum

kalemim bana küsmüş sevdam

hatıralarda kaybolmuş.

sıkıldım gidiyorum demek kolaydı aslında

ama yapamadım.

senin kadar vefasız olamadım.

Limanlardayım

bilirsin tek dostum deniz olduğu için.

Arada sırada çarşıya takılıyorum 

canım sıkılıyor bara gidiyorum.balıkçılar zaten açılmıyorlar.

İzmitin hayatı böyle endişe içinde devam ediyor.

yakışıyorda bu körfeze.

bu körfeze en çok yakışan marina kenarında ki sevgililerdir.

ben daha hiç gitmedim oraya. ne zaman sevgilim olduysa çok çabuk terkediyorlar.

hata da yok ya bende.

ahhhhhhhhhhhh be 

bide şimdi para olacaktı cepte çıkcaktın boğaza

anasını satayım.

anasının ne günahı var ki.

var aslında 

öyle bi karıdıki o musubet

Allah onun diline düşürmesin.

para ganimetti ama kızını vermedi bana.

olsun dedim unuturum dedim

bu arada  kızını harbiden sevdim

çatlaktı falan ama salaktıda

ama iyi kızdı

birazda para budalasıydı 

yoksa beni terkedermiydi.

ne şiirler karın doyururdu ne sözcükler.

en sonunda o da gitti

kaldık biz körfezle başbaşa.

Birgün diyordum birgün geçer

geçecekte biraz geç oluyo be 

en iyisi bu körfezi bu akşamlık fener ışıklarında yakıyorum.

iyi geceler...', 'birkaç gündür şiir yazamıyorum kalemim bana küsmüş sevdam hatıralarda kaybolmuş. sıkıldım gidiyorum demek kolaydı aslında ama yapamadım. sen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hikayem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Doğasın Sevdiceğim', 'sen-dogasin-sevdicegim-levent-karadag-p240g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kır çiçeğisin 

              yeşil vadilerin . 

Özlem damlacığısın  

            uçsuz bucaksız   çöllerin . 

Şairlerin karanfilisin

             buram buram sevda kokan  .

Nilüfersin 

             durgun akan bataklık nehirlerin  .

Bebeksisin 

            hiç bozulmamış masumuiyetin ve şirinliğinle.

Akvaryum balığısın 

             mercan kayalıklı berrak sularının.

Buğday başağısın

             yaz sıcağında tarlaları süsleyen .

Mevsim Kelebeğisin

             rengarenk yaban çiçeklerinin .

Ateş böceğisin .

              çam kokulu yayların yıldızsız gecelerinde', 'Kır çiçeğisin                yeşil vadilerin .  Özlem damlacığısın               uçsuz bucaksız   çöllerin .  Şairlerin karanfilisin        ...', ARRAY['Türk Edebiyatı','Şiir','Levent Karadağ']::text[], 8.5, '{"poet":"Levent Karadağ","poet_slug":"levent-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-dogasin-sevdicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Sabah', 'kac-sabah-celal-kabadayi-pzxmm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaç sabah uyandım erken

gündoğumu ince bir hançer

yüreğimi parçalarken

sabah yeli düşmanım gibi

şakaklarıma asılmışken

kaç sabah uyandım erken

gök deniz doğa sen

sen denize girerken

sevda yorgunu gözlerim

yüzünü göğe çizerken

kaç sabah uyandım erken

bütün ağızlar kapalı gözler yumuk

bütün kulaklar sağırken

boğazımda kızgın çığlığı aşkın

ellerim ellerini çağırırken

kaç sabah uyandım erken

dilimde unutmak türküleri

içimden kavuşmak geçerken

ölüm olsan içerdim seni

gözyaşlarım izinsiz akarken

kaç sabah uyandım erken

bütün düşler sona yakın

ben bitmeyen düşlerime başlarken

allahsız kuşlar sürüsü 

geçmişin ölüsünü taşırken

kaç sabah uyandım erken

şiirin topraksız ülkesinde

özlemin çiçekleri açarken

ben fırtınayı boranı seçtim

sen yağmurdan bile kaçarken', 'kaç sabah uyandım erken gündoğumu ince bir hançer yüreğimi parçalarken sabah yeli düşmanım gibi şakaklarıma asılmışken kaç sabah uyandım erk...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kac-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fukaralar Gibi', 'fukaralar-gibi-gulay-atilay-a0rm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fukaralar gibi kapında uzatsam ellerimi 

Ne istiyorsun diye sorarmısın?

Darılırmısınki bana almak istesem yüreğindeki

sevgiyi?

Sevgi paylaşmaktır sevgi özveride bulunmaktır 

kişinin hayata karşı olan güveni ruhunun ihtiyacıdır.

Yaşamak sevgi ile güzelleşir,renklenir ve hayat 

yaşanır hale gelir.

Sevgi insan hayatında hiç değerini kaybetmeyen,

eksilmeyen  gün begün katlanarak ,artan tek servetidir.

Desem...    servetime servet katarmısın?

Çok Sevilene...

10/Ağustos/2000', 'Fukaralar gibi kapında uzatsam ellerimi  Ne istiyorsun diye sorarmısın? Darılırmısınki bana almak istesem yüreğindeki sevgiyi? Sevgi paylaşm...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fukaralar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemin', 'yasemin-murat-cicek-jzl0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaseminler toprakta açar sanma

Açtı şu gönlümde bu gazel çiçek

Sokulsam aşkımı yine örtecek

Ezanım okundu girdin kanıma 

Muhtacım yasemin çiçeklerine

İçimi sızlatan hasret derdini

Nasılda bıraktın sevgi yerine', 'Yaseminler toprakta açar sanma Açtı şu gönlümde bu gazel çiçek Sokulsam aşkımı yine örtecek Ezanım okundu girdin kanıma  Muhtacım yasemin çi...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasemin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak', 'yaprak-duygu-yildiz-n5ksr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susmuş mu, inliyor mu belli değil

Bir yaprak

Kısmışmı, açılmışmı kendini

Toprak

Tutmuşmu , bırakmışmı toprağı 

Kök 

Vurmuş mu, sıyırmışmı yaprağı

Rüzgar

Tam bizim evin karşı bahçesinde

Ara ara

Sallanan bir yaprak var.

Ağaç yorgun 

Susuz toprak

En kuru sıcakta bile

Ağlayan yaprak

Acı bir rüzgar eliyle

Düştü kuru soğuk yere

Parlak boyalı ayaklar

Üzerine bastılar

Ezildi.

Oysa o kendi yerinde

Ağaçtan bile güzeldi.

	Ezildi.

Oysa o ağaçtaki  herbir yerden

Yeşildi.

	Ezildi.

Oysa o bütün yapraklardan güçlü

Bütün dallardan nazik

Bütün köklerden sağlam

Bütün kuşlardan özgür

Bütün evrenden özeldi	

	Ezildi

Her mükemmel şeye olduğu gibi.', 'Susmuş mu, inliyor mu belli değil Bir yaprak Kısmışmı, açılmışmı kendini Toprak Tutmuşmu , bırakmışmı toprağı  Kök  Vurmuş mu, sıyırmışmı ya...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yıldız']::text[], 8.5, '{"poet":"Duygu Yıldız","poet_slug":"duygu-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yaprak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-adem-altan-qkmf7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni koklamak bana olsada ölüm;

Olsun sana değer BEE gülüm', 'Seni koklamak bana olsada ölüm; Olsun sana değer BEE gülüm...', ARRAY['Türk Edebiyatı','Şiir','Adem Altan']::text[], 8.5, '{"poet":"Adem Altan","poet_slug":"adem-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gulum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-adem-altan-xo72f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güller bahçesinde geçsede ömrüm,

Senin üstüne gül koklamam gülüm, 

Seni koklamak bana olsada ölüm,

Olsun sana değer BEE gülüm', 'Güller bahçesinde geçsede ömrüm, Senin üstüne gül koklamam gülüm,  Seni koklamak bana olsada ölüm, Olsun sana değer BEE gülüm...', ARRAY['Türk Edebiyatı','Şiir','Adem Altan']::text[], 8.5, '{"poet":"Adem Altan","poet_slug":"adem-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guller-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni', 'al-beni-tolga-baydar-uhrpc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ta şurama geldi hayattan bezmişliğim

Her gün birisi bana

Kendimi küçülttüğümü söyler

Aklıma ölümü getiriyorum hep

Haykırıyorum

Sesim boşlukta yankılanıyor

Geçmişim ayaklanıyor

Yüzüm kararıyor

Seviyorum

Seni seviyorum ölüm

Gel artık al beni

Yolunu gözlüyorum

Gerdeğe girelim yeni gelin gibi

Sevişelim doyasıya

Birbirini bekleyen sevgililer gibi

Suyu özlemiş toprak gibi

Sararım ben seni

Sen sar beni

Sımsıkı

Bırakma buralarda

Hazırım bak

Al beni

Alsana beni

Ziyaret olmasın bu seferki

Ne olur

Ne olur al beni........', 'Ta şurama geldi hayattan bezmişliğim Her gün birisi bana Kendimi küçülttüğümü söyler Aklıma ölümü getiriyorum hep Haykırıyorum Sesim boşlukt...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/al-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Aşk', 'platonik-ask-tolga-baydar-5a2ef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi

Söylemek istiyorum

Olmuyor

Yapamıyorum

Kendimde o cesareti

Bulamıyorum

İçim yanıyor

Seni başkaları ile görünce

Ruhum bir tuhaf oluyor

Ama haklısın

Bilmiyorsun seni sevdiğimi

Ah keşke bilseydin

Belki de böyle olmazdı

Bu garip sevdalının hali

Belki

Şans verirdin bana

Gezerdik

Bir yerlere giderdik

Elimi tutardın belki de

Ama olmadı işte

Olmuyor işte

Bunların hepsi hayal

Olsun

Seninle ilgili hayal görmek bile güzel

Hayalimdeki aşkımsın

Ve hiç çıkmayacaksın', 'Seni sevdiğimi Söylemek istiyorum Olmuyor Yapamıyorum Kendimde o cesareti Bulamıyorum İçim yanıyor Seni başkaları ile görünce Ruhum bir tuha...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/platonik-ask-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gözüm İstanbul da', 'bir-gozum-i-stanbul-da-harun-kesik-jp2sd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakınca doğusuna batısına

Sarıldım yazına baharına 

Saadet yolu istanbul da

Dolmabahçesine Ayasofyasına

Gezdim gördüm geldim

Pisliğine arısına pakına

Gördüm güzelim çamlıca

Saadet yolu istanbul da

Sarı çizmeli mehmetağa

Bulamadım sert gümüşlü kaya

Bende istemezmiyim istanbul a

Saadet yolu istanbul da

Yetti bana istanbul

Ben sılama gideceğim sılama

Ama gözüm yine istanbul da

Saadet yolu istanbul da', 'Bakınca doğusuna batısına Sarıldım yazına baharına  Saadet yolu istanbul da Dolmabahçesine Ayasofyasına Gezdim gördüm geldim Pisliğine arısı...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gozum-istanbul-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Denen Şey', 'sevda-denen-sey-dervise-guneyyeli-5s9kx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda nedir bilmedim,

Ağlamadım hiç umutsuzca, hıçkıra hıçkıra.

Gönlüm kanamadı durmadan,

Aramadım ilacını geceler boyu.

Hasretlikle yanmadı, kanamadı hiç yüreğim

Semaya bakmadım hiç

Aramadım denizlerde gözlerini

Uzanıp tutmak istemedim ellerini.

Mazlum kalmadım hiç köşelerde

Zincirlerle bağlanmadı ellerim

Körelmedi gözlerim gurubla

Adını kazımadım yıldızlara.

Ben, ben hiç sevmedim.', 'Sevda nedir bilmedim, Ağlamadım hiç umutsuzca, hıçkıra hıçkıra. Gönlüm kanamadı durmadan, Aramadım ilacını geceler boyu. Hasretlikle yanmadı...', ARRAY['Türk Edebiyatı','Şiir','Dervişe Güneyyeli']::text[], 8.5, '{"poet":"Dervişe Güneyyeli","poet_slug":"dervise-guneyyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevda-denen-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Vazgeçtim Sevmekten', 'ben-vazgectim-sevmekten-dervise-guneyyeli-dvogr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben vazgeçtim sevmekten

Tüm yeminlerimi bozuyorum

Ve herşeyi siliyorum bir kalemde.

Ne söylenenler ne yaşananlar

Ne de geçmiş kalacak bu sahnede.

İyi ve kötü, herşeyi bırakıyorum.

Alın, tüm çocukluğum sizin olsun.

Yıldızlara aksi vurmuş umudum,

Eli güneşe uzanmış sevgim; 

Güzele dair ne varsa alın.

Sizin olsun huzurum, kederim,

Vuslatı beklerken ağlayan yüreğim,

Bitmek bilmeyen hicran dolu gecelerde

Çiçeklere umut olsun diye serptiğim gözyaşlarım.

Huzurum, evet huzurum da sizin olsun,

Kırık dökük mutluluğum da.

O da yetmezse,

Benden kalan ne varsa hepsini alın.

.

.

.

.

.

....Yalan söylüyorum...', 'Ben vazgeçtim sevmekten Tüm yeminlerimi bozuyorum Ve herşeyi siliyorum bir kalemde. Ne söylenenler ne yaşananlar Ne de geçmiş kalacak bu sah...', ARRAY['Türk Edebiyatı','Şiir','Dervişe Güneyyeli']::text[], 8.5, '{"poet":"Dervişe Güneyyeli","poet_slug":"dervise-guneyyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-vazgectim-sevmekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Elvermedi', 'gonlum-elvermedi-dervise-guneyyeli-68swo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün kokan bir çiçek buldum bugün,

Gönlüm elvermedi,

              uzanıp aldım yerden.

Besbelli taze koparılmıştı dalından

Sırtında hüznü,

              sürüklenmişti buralara kadar.

Gözleri çökmüş, saçları dağınık,

Yüzünde kurumuş gözyaşları;

Gönlüm elvermedi,

              birkaç damla su koyverdim dalına

Kımıldar gibi oldu hafiften

Besbelli suya hasretti dalı,

Yaprağı okşanmaya, yüreği sevgiye.', 'Hüzün kokan bir çiçek buldum bugün, Gönlüm elvermedi,               uzanıp aldım yerden. Besbelli taze koparılmıştı dalından Sırtında hüznü,...', ARRAY['Türk Edebiyatı','Şiir','Dervişe Güneyyeli']::text[], 8.5, '{"poet":"Dervişe Güneyyeli","poet_slug":"dervise-guneyyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonlum-elvermedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-dervise-guneyyeli-vgdbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte

Sus, hiçbirşey söyleme

Sonra,

Bahar yağmurları düşer de gözlerime 

dayanamaz yüreğim,

dayanamam.', 'Gidiyorum işte Sus, hiçbirşey söyleme Sonra, Bahar yağmurları düşer de gözlerime  dayanamaz yüreğim, dayanamam....', ARRAY['Türk Edebiyatı','Şiir','Dervişe Güneyyeli']::text[], 8.5, '{"poet":"Dervişe Güneyyeli","poet_slug":"dervise-guneyyeli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gidiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldıza Yaklaşır Düşüncelerim', 'yildiza-yaklasir-dusuncelerim-seyit-ahmet-kutuzman-eyaud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ceyhan gün boyunca bulandı gene

bir sevda kımıldar ağaçtan ayrı

eski düşlerinden uyanır gönül

zaman bir incecik dala dokunup 

rüzgar o türküyü ezberlemese

içimden geçeni bilmezdi dağlar

bir siyah entari giyer tabiat

sesizce düşünür gece yapraklar

çalılar adama benzer nedense

karanlık kurtarır ak çiçekleri

sonra serinlerken korkunun kalbi

üç defa yüzüme çarpar yarasa

ancak aşıkların hürdür yüreği

ve ancak bu sırrı şairler bilir

ay doğar hafifce esner karanlık

durulur durulur durulur gece

bir peri uyanır sabaha karşı

beriki elinde fil dişi tarak

öteki dizinde ayna sevinir

saçını ceyhana tarar derinden

heyecan yüzümde damla damladır

bir tel dalgalanır nefes nefese

o çizgi aniden gözümden kayıp

bir hayal dalardı soğuk sulara

acı acı gelir bir ses uzaktan

meşakkat boynunu sallar öküzün

uyku bastırdıkca yumuşar taşlar

ve hüznünü işler yüreğe kağnı

üç ayrı kayaya çarpar ızdırap

aşıklar kendini atar bir yere

içimin sesinden ayrılır hüzün

bütün dakikalar bana yönelir

karanlık geceye sığınmam gerek

yarı sevdalıyım taşa yazarlar

ömrümü yıllarca yerken o hayal

benim teranemi balıklar okur

yıldıza yaklaşır düşüncelerim

güneş karanlığı ortadan yarar 

gözlerim uykusuz kalmıştır belli

o hayal düşüme girer yeniden

kuşlar şarkısını eşine söyler

ben akşam olmadan uyanacağım

dalıp kaldığımda ceyhan nehrine

dalları o rüzgar okşayacaktır

on onbeş yirmi yıl eskir düşüncem

bir kavak devrilir sulara doğru

çatırdar ömrümün her neyi varsa

beni o rüzgara anlatan olmaz

kimseler görmez ki gördüklerimi

ben bana küsmüşüm kim avutacak

yıllardır yalnızım su kenarında

aşkımı yavrusuz kuşlar bilmesin

unutsun bu toprak yaşadığımı

göz yaşı görürsen çiğ tanesi de

çimenler üstünde hayal mi yaşar

ırmak bu türküyü bellemeseydi

her bahar yeniden rüzgarla ağlar

ağıtmı söylerdi sabah vaktinde

ve işte her gece böylece geçer

bülbüller nerede susar bilinmez

aşıklar her seher dinler ezanı

şairler bir bardak efsane süzmüş

bir gül yanaklının hikayesinden

kapkara o gözler ay ortasında

saçlar iki metre uzarmış meğer

benim gençliğimin hesabını sor

ben sevda çekmeye hazır değilim

ya da sözlerimi unut arkadaş

benden hiç bir masal dinlemedin ki

kahvede rast geldik öyle değil mi

karanlık geceye sığınmam gerek

yarı sevdalıyım taşa yazarlar

ömrümü yıllarca yerken o hayal

benim teranemi balıklar okur

yıldıza yaklaşır düşüncelerim.

yalnız,toprak kadar zekidir hayat

sanki gizli gizli sürecek sevda

duydum ki leylalar habersiz yaşar

elbette doğrudur Fuzuli amma

bir ince dal gibi salındığında

ne bilsin pınara taşlar dökülmüş

ne bilsinbulanan gönüller nerde

her lafı uzatmak gerekmez amma

her gece ay batar tam tepemizde', 'ceyhan gün boyunca bulandı gene bir sevda kımıldar ağaçtan ayrı eski düşlerinden uyanır gönül zaman bir incecik dala dokunup  rüzgar o türkü...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Kutuzman']::text[], 8.5, '{"poet":"Seyit Ahmet Kutuzman","poet_slug":"seyit-ahmet-kutuzman","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/yildiza-yaklasir-dusuncelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedem Korkut Der ki', 'dedem-korkut-der-ki-mehmet-ali-kalkan-05ow2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dinle beni be hey oğul,

                               Söz söyleme boş üstüne.

                               Varımlığın bır gün değil,

                               Doğruyu bil düş üstüne.

                               Ozansız öksüz kopuzlar,

                               At koşmazsa çayır sızlar,

                               Hayır bilmez hayırsızlar,

                               Taş koyar mı taş üstüne?

                               Gerekende yardan geçin,

                               Yardan geçin,serden geçin,

                               Ata ölür oğul için,

                               Bahar döner kış üstüne.

                               Gece gündüzde aklanır,

                               Yaşlı ağaç budaklanır,

                               Sevdaya düşen oklanır,

                               Göz değirme kaş üstüne.

                               Deniz için kulaç gerek,

                               Meyva için ağaç gerek,

                               Boğa için boğaç gerek,

                               Şahin gitmez leş üstüne.

                               Yay gerdiren hocayı bil,

                               Ak sakallı kocayı bil,

                               Ocağı bil,bacayı bil,

                               Tok getirme aş üstüne.

                               Kocamışlar fer gözetir,

                               Korkak sapa yer gözetir,

                               Yiğitler zafer gözetir,

                               Vur namerdin döş üstüne.

                             

                               Öğünmekle er olunmaz,

                               Döğünmekle yer alınmaz,

                               Vatan değilse kalınmaz,

                               Devlet olmaz yaş üstüne.

               

                               At ölende tayı kalır,

                               Çeri ölür beyi kalır,

                               Üç-ok,Boz-ok boyu kalır,

                               Oğuz soyu baş üstüne.', 'Dinle beni be hey oğul,                                Söz söyleme boş üstüne.                                Varımlığın bır gün değil,     ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dedem-korkut-der-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülere Kıymayın', 'turkulere-kiymayin-ahmet-cansiz-gullu-xj2cp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'türkülerle kardeş bacı anayız

aman dostlar türkülere kıymayın

türkü bizden biz türküden yanayız

aman dostlar türkülere kıymayı

her yörede ayrı atrı süslenir

asırlardır gönlümüzce seslenir

sevgilidir sevgimizle beslenir

aman dostlar türkülere kıymayın

kızılırmak olur ayşen içinde

tarak olur zeynebimin saçında

sevgimizin sevabında suçunda

aman dostlar türkülere kıymayın

dağda sümbül bahçelerde gül olur

turnaların kanadında tel olur

bizi bize kavuşturan el olur

aman dostlar türkülere kıymayın

çamlıbelde kervan bozar yol keser

dertlerle dost olur dermana küser

dilden dile kalmış ölmez bir eser

aman dostlar türkülere kıymayın

eginlinin terkisinde hasrettir

dağarcıkta tükenmeyen kısmettir

sevdadır sevgidir aşkdır hikmettir

aman doslar türkülere kıymayın

uzun hava bozlak hoyrat mayadır

bazan hakikattır bazan rüyadır

kimi bedduadır kimi duadır

aman dostlar türkülere kıymayın

sitem etme al kalemi destine

selam söyle yarenine dostuna

CANSIZ titrer türkülerin üstüne

aman dostlar türkülere kıymayın', 'türkülerle kardeş bacı anayız aman dostlar türkülere kıymayın türkü bizden biz türküden yanayız aman dostlar türkülere kıymayı her yörede ay...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Cansız Güllü']::text[], 8.5, '{"poet":"Ahmet Cansız Güllü","poet_slug":"ahmet-cansiz-gullu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turkulere-kiymayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Gözleriniz Vardı', 'paris-gozleriniz-vardi-omer-sevincgul-jzf6o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'beni sürüklerdiniz. 

sizi izlemekten lezzet alırdım. 

halden hale hızlı dönşümler yaşardınız.

ardınızda dizi dizi benlikler bırakırdınız. 

ben onları toplar hayal odamda biriktirirdim. 

günleriniz tıpkı mevsimlerdi. 

yüzünüzdeki karçiçekleri birdenbire yaz meyvelerine bırakırdı yerini. 

hasat zamanını beklemezdiniz. 

güz esintileriyle dökülen sarı yapraklar sererdiniz önüme. 

basmamaya özen gösterirdim. siz usulca gülümserdiniz. 

birden hüzün bulutları kaplardı yüzünüzü. 

yağmur damlalarını beklerken karla aklanırdı alnınız.

 her türlü güzeldiniz. keskin bakardınız. 

bir mermer heykel kadar kımıltısız susardınız. 

baharı beklerdim, 

bilirdim kar bahardan haber verirdi. 

mevsimleri sizinle hissederdim. 

ömrümün günleri sizi izlerken eriyen dakikalardı. 

gönlüm sizin takviminizdi. 

takvime aldırmazdınız. 

yıllarda asırları yaﬂardınız. 

siz ömür sürerdiniz ben yaprak yaprak tükenirdim. 

siz beni yok sayarak kendinizi yaﬂardınız. 

ben sizde yaﬂamak için fasılasız ölürdüm. 

sizce yalnız an vardı dün yoktu yarın yoktu. 

gurbet türküleri mırıldanırdınız. 

sılanızı özlerdiniz. sonsuz bir an arardınız. 

mevsimsiz bir mevsim... 

siz onun peﬂindeydiniz ben sizin. buldunuz mu? 

konuﬂmuyorsunuz. 

hep susardınız. 

susmanızda bile bir üslup vardı. 

size siz dememi isterdiniz.

şanzelizede mösyölerle matmazeller gelirdi hatırıma size söylerdim. 

paris gözlerinizle gülerdiniz. 

ama melâliniz istanbuldu. ''

melâli anlamayan nesle 

âﬂina'' olmadınız asla. 

siz yoksunuz ya mevsimler aylarla sıralı müselles. 

sene mevsimlerle murabba. 

ben herkesle birim. 

murabba hücremdeyim. 

duvarda takvimim var! ''günler gelip geçmekteler, 

kuﬂlar gibi uçmaktalar.'' sayıyorum!', 'beni sürüklerdiniz.  sizi izlemekten lezzet alırdım.  halden hale hızlı dönşümler yaşardınız. ardınızda dizi dizi benlikler bırakırdınız.  b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/paris-gozleriniz-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamela', 'karamela-haydar-ergulen-81vjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanık şekerim sert, hayatsa daha berbat,

ikisinin de aynı kağıttan çıktığını unuturdum

unutmasına da, ben tuttum birini sevdim,

hayatı nasıl sevdiysem onu da öyle sevdim:

Tarçın Kokulu Kız, Carmen, Ay Carmela...

O nane likörüne bayılırdı ama, ben onu 

sıcacık bir kahvenin dumanına benzettim,

o da beni birine benzetmiş olmalı ki, tuttu

aşk derdine düştü, şimdiyse terketme sevdasında!

Aşk dünyaya bizden önce gelmiş de erkenden

açmış gibi dükkanını, onun kokusuyla tanıdım

aktarları, acı sözlerini aşkın tuzu biberi saydım,

onun huylarıyla karşılaştım eski tuhafiyelerde:

Aynalı Pasaj, Bonmarşe ve Altın Düğme...

Biri birine uymayan binbir huy, binbir çeşit,

bir dükkana rastladım duvar taş, kapı kilit,

ne tatlı sözlerim açabildi ne iyi huylu şiirim,

karamela dükkanı olduğunu en sonunda öğrendim!

Şimdi yanık şekerim sert, hayat ondan da dert,

ben zaten tiryakiyim, ayrılık aşktan da berbat!

Ah karamela şekerim, aşk tatlı da insanlar berbat!', 'Yanık şekerim sert, hayatsa daha berbat, ikisinin de aynı kağıttan çıktığını unuturdum unutmasına da, ben tuttum birini sevdim, hayatı nasıl...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karamela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mavi Gecedir Zaman', 'bir-mavi-gecedir-zaman-omer-sevincgul-29wlu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'engelsiz ufuklarla çevrili bir sahradayım 

bir öte dünya bu hayatsız

hafif bir yel esiyor gönlünce

ürpertilerle dolu bir mavi gecedir zaman

nazlı bir ay doğuyor kum tepelerinin arasından

uzaklardan tanımlanamaz sesler geliyor derin

sığınak yok

barınak yok

sen yoksun

uzanıyorum gündüz güneşi emen kumlara

gözlerim yıldızlarda

gönlüm ayda

tenim de yanmakta gönlüm gibi

hayalin kandırmıyor sultanım!

kendimi nasıl anlatsam sana

demir yerle bakır gök arasında

rüyalarla yaşayan

hayallerle avunan

kum sayısınca kaygılı

bir damla hayat!

çöl nasıl beklerse yağmuru

kızaran gül nasıl özlerse suyu

seni öyle bekliyorum.

seraplar var kum tepelerinde

ayla yarışan yüzünü görüyorum

beyazlar içindesin

bir hayalsin ki hakikat kadar güzel

ve umut kadar tatlı

bilmiyorum sen 

sen misin

gelmedin 

gelmiyorsun

ve ölüme gider gibi gidiyorum ben sana

iradem lâl 

mahkumum 

sana yürüyor ayaklarım

sen hayatsın biliyorum

ölüm ol istersen 

sende ölürüm toprakta habbe gibi

ve sende can bulurum yeniden

senin gözlerinle bakacaksa melek

vermeye hazırım ne isterse

seve seve

ıssız bir sahrada yapayalnız yaşamaktansa

ödüldür sende ölmek

her şey zıddını içinde taşır

ölümün annesi hayat

hayatın önsözü vefat

ve toplamı

aşk!

tebessümün gibiyse ölüm!

razıyım gülüm!

al beni

kalbin canıma kabir olsun!', 'engelsiz ufuklarla çevrili bir sahradayım  bir öte dünya bu hayatsız hafif bir yel esiyor gönlünce ürpertilerle dolu bir mavi gecedir zaman ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/bir-mavi-gecedir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Öpsün Dudakların', 'gunesi-opsun-dudaklarin-omer-sevincgul-b23gs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hakikat haykırır bazan, 

ünlemli konuşur, 

dayanamaz zayıf kulaklar. 

Der, tam insan olun ey insancıklar!

Bedence özürlüdür kimileri

daha beteri de var,

onlar ruh kötürümleri!

Cılızdırlar

korkarlar da yaşamaktan

siperlerde saklanırlar. 

Büyük gerçekler barınamaz küçük canlarda, 

görkemli saraylar ister o nazenin

emelleri kocaman

duyguları azmanlar ister 

tam insanlar! 

Usta süvariler, derler:

doludizgin koşan küheylandır nefs

binektir o, gemlemeyi bilene! 

Dizgin tutmayı biliyorsa istem kudretin

doru atlar gibi salıver arzularını

korkakların işidir dermansız atlarla yetinmek, 

uzak hedefleri göze alamayanların. 

Mangalların dibinde pinekler de

mırmır ederler 

uysal ev kedileri gibi 

yitirilmiş ve unutulmuş nesnedir yeleleri. 

Şeytan kanı damlasın pençelerinden, 

Baksın da cihanı ayna yapsın sana

ilkeliyse gözlerin. 

Uzay arılarının vızıltılarını işitsin

ve kürenin merkezinde yanan ateşin 

sesini duysun kulakların. 

Güneşi öpsün dudakların! 

Yanmayı bil!

Yakmayı bil!

Devasa haramlar vardır kefede 

ve helaller, 

güçlü kolların olsun tartacak

büyük olmalı terazin.

Haramı küçüktür küçük adamların, 

elbet helali de. 

Büyük olanı daha da büyük olanı iste sen. 

Büyük oyuncular kazanır büyük oyunları!

Atıver yapay zırhını üstünden, 

soyun gösteren ama oldurmayan giysilerinden,

yalan olma 

yalın ol!

Kendini oturtacaksın kendi önüne

ve diyeceksin

Ey azgın köle!

Bu tokat 

bu kırbaç 

bu sille... 

Melekler diyecek

bu inilti de ne bu acı nida?

İntibah verir sana böyle bir yara 

acı cehennem dilidir

ham ruhları pişirir. 

Dünya güz elmasıdır ancak bilen görür

Dişle onu 

çiğne 

ve tükür! 

Bir şeytan topudur kürre

oyna onunla, 

şeytanınla,

idmanlı olsun kalbin,

duru gıdalarla beslen

ve güçlen! 

güçlen de yen! 

Yakıp kavurmalı tutkular cehennem dili gibi

yüksek olmalı hararetin,

tüm ırmakları içmek istemelisin! 

Küçük sularda boğulmak yakışmaz sana, 

okyanuslar olsun mezarın,

iyisi mi, 

denizlerde yürümeyi öğren sen, 

veyl ıslanırsa ayakların!

Gaybın ummanları vardır bilir misin!

Zirvelerde olur görünmezin denizi

ilham iplerine tutun da yüksel!

Ötelere erenler derler

izle bizi

seni bekler yüceler

rehberindir sezgiler!

Büyük avcı olanlar

büyük avlar

ebediyyen senindir

yedi katlar

ve sonsuz hakikatlar. 

Küçüksün der yalan söyler aynalar

oysa büyüktür sendeki sen 

yokla kendini

emin olmak istersen

gözün dönsün içine, 

bakıver ruh cebine... 

Eğer yitirmediysen!', 'Hakikat haykırır bazan,  ünlemli konuşur,  dayanamaz zayıf kulaklar.  Der, tam insan olun ey insancıklar! Bedence özürlüdür kimileri daha be...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/gunesi-opsun-dudaklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portekiz Soneleri', 'portekiz-soneleri-elizabes-barrett-brovvning-d78ta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ki benim yüzümün zaman yağmurlarıyla

Solan şu maskenin arkasını görecek

Ve orada ruhumun en gerçek çehresini

Hayat yarışmasının yorgun seyircisini

Seçebilecek güce sahipsin.

Sen ki ruhun bezgin yorgunluğu içinde

Yepyeni cennetlerde kendince yer bekleyen

O sabırlı meleği tanıyıp anlıyacak

Kadar büyük sevgiye ve inanca sahipsin

                                                     1850', 'Sen ki benim yüzümün zaman yağmurlarıyla Solan şu maskenin arkasını görecek Ve orada ruhumun en gerçek çehresini Hayat yarışmasının yorgun s...', ARRAY['Türk Edebiyatı','Şiir','Elizabeş Barrett Brovvning']::text[], 8.5, '{"poet":"Elizabeş Barrett Brovvning","poet_slug":"elizabes-barrett-brovvning","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/portekiz-soneleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Gündelik', 'elveda-gundelik-tarik-emre-t0ds6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen;

Biçimi içeriğine fark atmış,

Toy bir şiir denemesisin...

Eyvallahım;

Özgünlüğümde

Elveda!

Meğer;

Tedavülden kaldırılacak

Ne çok şey varmış

Gündeliğimde!', 'Sen; Biçimi içeriğine fark atmış, Toy bir şiir denemesisin... Eyvallahım; Özgünlüğümde Elveda! Meğer; Tedavülden kaldırılacak Ne çok şey var...', ARRAY['Türk Edebiyatı','Şiir','Tarık Emre']::text[], 8.5, '{"poet":"Tarık Emre","poet_slug":"tarik-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/elveda-gundelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Yıldızlar', 'kaybolan-yildizlar-feyzi-ulukaya-dkjvx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbulda aradıgım yıldızları buldum

                          Bu   yıldızlar   artisler   degil

                          İsten dumandan görmeyi unuttugumuz

                          Sahildeki sarhoşların bizim dedigi

                          Yıldızları saklanmış olarak buldum

                          Her zaman görünmeyen bulunmayan

                          Tutunacak  gibi  ama  tutulamayan

                          Sevilecek   gibi   ama  sevilemeyen

                          Kimisinin  tutunacak  dalı  olan

                          Yıldızları saklanmış olarak buldum

                          Belki   benim   için   özlemdi

                          Belkide geçmişimi yakalayacak yoldu

                          Bilemiyorum hayatımın sırrıda olabilir

                          Arayanların bulamadıgını köyümde buldum

                          Yıldızları saklanmış olarak buldum', 'İstanbulda aradıgım yıldızları buldum                           Bu   yıldızlar   artisler   degil                           İsten dumandan g...', ARRAY['Türk Edebiyatı','Şiir','Feyzi Ulukaya']::text[], 8.5, '{"poet":"Feyzi Ulukaya","poet_slug":"feyzi-ulukaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaybolan-yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-celal-kabadayi-s201t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'herkes sevdiğiyle yatsaydı

mutluluk olurdu

herkes yattığını sevseydi

yine mutluluk olurdu', 'herkes sevdiğiyle yatsaydı mutluluk olurdu herkes yattığını sevseydi yine mutluluk olurdu...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mutluluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-celal-kabadayi-0powa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonbahar yıkılmaz duvarlarını yokluyor yalnızlığın

şiirin barikatlarını zorluyor yağmur orduları

hep bir yolunu buluyor esintileri sonbaharın

yüreğin derinliklerinde fırtınalar yaratmanın

bir ılık bir soğuk yapıyor havalar

üşütmenin tam zamanı aşk salgını da var

sevgiler acı sarmalından geçip geliyor

yine solgun yine sensiz yaşanıyor sonbahar

yeşil bir yapraktın erken koptun dalından

korkup birgün sonbaharda kurumaktan

keşke dalında kalsaydın,sararsaydın,solsaydın

sonbahar sokakları gibi aklımda kalsaydın

anılar yırtıyor unutuşun sisli perdesini

her yaprak benimle düşüyor dalından

bir buruk acı duyuruyor geçmişin özlemini

her yaprak seninle düşüyor dalından', 'sonbahar yıkılmaz duvarlarını yokluyor yalnızlığın şiirin barikatlarını zorluyor yağmur orduları hep bir yolunu buluyor esintileri sonbaharı...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaz', 'bogaz-sinem-ors-tc36q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boğaz''ın en dar yeridir gözlerin

çift akıntılıdır

nereye götüreceğini kim bilir...', 'Boğaz''ın en dar yeridir gözlerin çift akıntılıdır nereye götüreceğini kim bilir......', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bogaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
