INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pabuçsuz Aşık', 'pabucsuz-asik-sinem-ors-uxvr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben aşık olunca

pabuçlarım daha kolay yırtılır

daha çabuk çatlar ellerim

soğuktan

ben aşık olunca

daha çabuk şiir yazarım

şiir yazınca 

daha çabuk aşık', 'ben aşık olunca pabuçlarım daha kolay yırtılır daha çabuk çatlar ellerim soğuktan ben aşık olunca daha çabuk şiir yazarım şiir yazınca  daha...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pabucsuz-asik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercih', 'tercih-sinem-ors-u8zfm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yuvarlakları severim

beni kendime döndüren

çizgileri sevmem

beni boşa akıtan', 'yuvarlakları severim beni kendime döndüren çizgileri sevmem beni boşa akıtan...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tercih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolmuş', 'dolmus-sinem-ors-1k9gn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bindiği dolmuşların 

deri koltuklarına kazıdı aşkını

kazırken kazırken

başka bir aşk buldu', 'bindiği dolmuşların  deri koltuklarına kazıdı aşkını kazırken kazırken başka bir aşk buldu...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dolmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-sinem-ors-pseyk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kanatlarımdan çıkan ateşle

yakıyordum seni

uçtukça ruhuna 

şimşek çakıyordum

dayanamadın bunca talana

vazgeçtin

gittin

yangının bol olsun', 'kanatlarımdan çıkan ateşle yakıyordum seni uçtukça ruhuna  şimşek çakıyordum dayanamadın bunca talana vazgeçtin gittin yangının bol olsun...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kevgir', 'kevgir-sinem-ors-wtoqk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayatı didikleye didikleye

kevgire çevirdim sanırım

her yerinden rüzgar alıyor şimdi

boşluklarından yağmur giriyor', 'hayatı didikleye didikleye kevgire çevirdim sanırım her yerinden rüzgar alıyor şimdi boşluklarından yağmur giriyor...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kevgir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabut', 'tabut-sinem-ors-l3iud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kendine gömülmek 

en büyük densizliği

ruhun

güvensizliğinden takındığı 

o yıkıcı tavır

kuyruğuna basılmışlığı

                   mağrurluğunun', 'kendine gömülmek  en büyük densizliği ruhun güvensizliğinden takındığı  o yıkıcı tavır kuyruğuna basılmışlığı                    mağrurluğun...', ARRAY['Türk Edebiyatı','Şiir','Sinem Örs']::text[], 8.5, '{"poet":"Sinem Örs","poet_slug":"sinem-ors","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tabut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-mehmet-emin-komurcu-c6owv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_Öğretmedin_

Sen aşkı gözbebeklerimden mi öğrendin

Hasreti yüreğime sen mi gömüp gittin

Elbette eldin

Hem de yaban eldin

Dermeye fırsat mı verdin

Gülleri avuçlarıma 

Sen mi ekip gittin

Düşlerime sen mi geldin

Kabuslarımı sen mi terkettin

Unutulmayı sen mi öğrettin

Yazık 

Unutmayı öğretmedin', '_Öğretmedin_ Sen aşkı gözbebeklerimden mi öğrendin Hasreti yüreğime sen mi gömüp gittin Elbette eldin Hem de yaban eldin Dermeye fırsat mı v...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Kömürcü']::text[], 8.5, '{"poet":"Mehmet Emin Kömürcü","poet_slug":"mehmet-emin-komurcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göklerden Süzüldüm Tertemiz indim', 'goklerden-suzuldum-tertemiz-indim-gulay-atilay-2paj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Goklerden suzuldum tertemiz indim 

Yere indim yedi renge boyandim 

Boz bulanik bir sel oldum yurudum 

Cesit cesit turlu renge boyandim 

Azgin azgin caglayarak akarak 

Insafsizca tahrip edip yikarak 

Ne utandim ne kimseden korkarak 

Kusur gunah kirli renge boyandim 

Bir kuru sevdanin pesine dustum 

Nice kayalardan taslardan uctum 

Irmaga kavustum kendimden gectim 

Utandimda kirli renge boyandim 

Yuzlerimi yere vurdum surundum 

Cok dolandim irmak oldum gorundum 

Eleklerden gectim yundum arindim 

Kamilane ka^rli renge boyandim 

Irmak olup kavusunca denize 

Dalgalandik costuk tastik biz bize

Cok zaman seyrettim aya yildiza 

Aydin parlak nurlu renge boyandim 

Veysel yoktan geldim yok olup gectim 

Ben deyenler yalan gercegi sectim

 Bir buhar halinde goklere uctum 

Kayboldum o sirli renge boyandim. 

ASIK VEYSEL(1894-1973)', 'Goklerden suzuldum tertemiz indim  Yere indim yedi renge boyandim  Boz bulanik bir sel oldum yurudum  Cesit cesit turlu renge boyandim  Azgi...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/goklerden-suzuldum-tertemiz-indim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ele Seviremki!', 'seni-ele-seviremki-gulay-atilay-nhp0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni ele sevirem ki...

Diyirsen ki, niye? 

Ne bilim işte ele! 

Seni görende bir hoş olir, ölür ölür ölirem...

Ahşam olir davar, nahır, mal gelir.

Komlar, ahırlar dolir

Sayiram sayiram biri eskig

Bi daha sayiram

Bi de bahiram ki, tamam.

Ama üzülirem; 

Çünki sen gelmirsen.

Diyacahsan niye? 

Bennam, işte ele! 

Yassi olir; 

Sekide ekmek yiyeceğam

Civil lavaşi dürüm edir, tamkıtliram,

Sen ahlıma gelirsen, yiyemirem.

Sen ahlıma gelirsen, boğazımda dügümlenir.

Gene diyirsen ki, niye? 

İşde ele...

Anam örtüleri sarir...

Gendi gendimi yiyirem.

O da gidir, kalli biçare galiram.

Gözlerim süzülir, yuyicağam, uyiyamiram.

Gafam garişir, yüreğim sığışir, yatamiram.

Gene diyirsen niye? 

İş de ele! 

Guşluğa doğri daliram

Hayal, hülya görirem, sanki yanıbdasan

Sevinir, sevinir bir hoş oliram,

Bir de ayıliram ki, yasdığa sarılmışam

Diyacaksın ki, niye? 

Amaan, iş de ele.

Sabah olir, horozlar ötir, gün doğir...

Gahiram tavuhlara, culuhlara yem verirem...

Culuhlari dutir dutir öpirem; 

Onlari bile sene benzedirem.

Saggın deme niye? 

Ne bilim, iş de ele! 

Gün gibi gelir,ay gibi gidirsen.

Beni yiye yiye bitirirsen.

Hep ömrümden götirirsen.

Seni sevdigimi de çoh ey bilirsen.

Diyirsen ki, niye? 

Bilirsen, iş de ele! 

Babam beni gapiya goymir diyirsen.

Ey helt yiyirsen.

Gomşulara, emin, bibin, ezen gile gidirsen...

Madem ele çıh cama, tırhıca gel! 

Yüzün görim, bu da bene yeter

Saggın deme niye! 

İş de ele...

Erzurum''lu  Şair..Zinnur Tiryaki', 'Seni ele sevirem ki... Diyirsen ki, niye?  Ne bilim işte ele!  Seni görende bir hoş olir, ölür ölür ölirem... Ahşam olir davar, nahır, mal g...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/seni-ele-seviremki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Dünyalara Savruldu Parçalarım', 'kayip-dunyalara-savruldu-parcalarim-omer-sevincgul-3zlyg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen okuyacaksın diye şiir yazardım

seninle güzeldi masallarım

bilirim

sağanak yağmurlar misali 

kesilecek ilhamlarım

yanarım eriyen ümitlerime

solan güllerime yanarım

bir mavi dünyam vardı dünyadan beri

senden alırdı rengini

gittin

ve bir alem götürdün

koptu kıyamet

kaldım ben

ben karayım

dünya karanlık

kırıldı artık ruhumu gösteren ayna

yittim

kayıp dünyalara savruldu parçalarım

son söz:

her son bir ilke gebedir', 'sen okuyacaksın diye şiir yazardım seninle güzeldi masallarım bilirim sağanak yağmurlar misali  kesilecek ilhamlarım yanarım eriyen ümitleri...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kayip-dunyalara-savruldu-parcalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ki İnsandın', 'sen-ki-i-nsandin-omer-sevincgul-ell4u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardeşim,

Sana derim:

Dik tut başını,

Yüksek sesle konuş,

Söyle fikrini.

Ben böyle düşünüyorum, de.

Bence, de.

Bana göre, de.

Ben buyum, de.

Sen, sen ol

Anlat kendini.

Bak, onlar da insan.

Bak, onlar da aciz.

Yemek yerler, su içerler,

Ağlarlar, gülerler.

Değer ver onlara, 

İnsanlara,

Ama korkma.

Onun korkusuyla doldur kalbini.       

Yer kalmasın başka korkulara.

Korkarsan eğer,

Korkuturlar seni.

Sultan olmak isterler,

Teba ararlar.

Tokatlayacak ense,

Ezilecek böcek ararlar.

Boyun bükme,

Yere bakma sakın,

Gösterme enseni,

Hükmederler,

Ezerler seni.

Onlar ki,

Ezilerek büyüdüler,

Hakaretlerle beslendiler.

Sus, derler, 

Düşünme, derler.

Onlar,

Pısanlar,

Susanlar,

Seni de kendilerine benzetirler.

Vakarı kibir,

İzzeti gurur sanırlar.

Sapı samana karıştırırlar.

Sen ki insansın,

Varlıklara sultansın!

Bak,

Yağmur senin için yağar,

Güneş senin için doğar,

Dünya senin için döner,

Pervanendir melekler.

Tanı kendini,

Tanıt kendini!

Bir O var, bir de sen,

Gerisi senin gibi.

Sen, sen ol.

Ben buyum, de

Böyle düşünüyorum, de.

Farket hürriyetini,

Kullan iradeni.

Kula kulluk edilmez,

O ne diyor,

O önemli.

Ne derler?

Ne derlerse desinler,

Senin gibiler!', 'Kardeşim, Sana derim: Dik tut başını, Yüksek sesle konuş, Söyle fikrini. Ben böyle düşünüyorum, de. Bence, de. Bana göre, de. Ben buyum, de....', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/sen-ki-insandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargı', 'yargi-omer-sevincgul-i3g58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vakit gece yarısı

başlamakta bir mücrimin yargısı

ve ben adliye muhabiriyim

bir mahkeme gördüm kendimde

haberler veriyorum yasak bölgemden

dinlesinler sabun kokan insanlar

bir kez daha anlasınlar temiz olduklarını!

öyle ya kimine göre

güzel gösteren ayna olmalı sanat adamı

işte itirafım ediyorum 

cürüm işledim

düştüm kendi gözümden

söylemeye utanırım yaptıklarımı

söylemezsem utanırım...

yazılar yazdım mavi yeşil sulara

kahramanı oldum söylenmedik masalların

rüyalar gördüm gün ortasında

hayal sinemasında roller oynadım

onaylanmış normallere meydan okudum...

bine böldüm kendimi

ben eşittir ben artı ben artı ben...

bin ben vardır bende 

toplamı ben

insanım ve suçluyum!

kendimi ihbar ediyorum 

bir mahkeme kurdum orta yerimde

davacıyım kendimden

sanık benim

yargıç ben

savcı benim

tanık ben

kendini yargılayan

hüküm verenim

yazdım karar metnini

kanımla mühürledim 

bir hapishane oldum kendime

benim kendini bekleyen gardiyan 

ben her gece ceza çekenim

memnu meyvelere uzanan ellerim kelepçeli

yasak beldelere yürüyen ayaklarımda prangalar

ruhumu kemirirken gecenin ifritleri

izliyor yarasalar

uzun bir gecedir ömrüm

sürecek kabre kadar', 'vakit gece yarısı başlamakta bir mücrimin yargısı ve ben adliye muhabiriyim bir mahkeme gördüm kendimde haberler veriyorum yasak bölgemden d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yargi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümrük Han', 'gumruk-han-nevzat-gurmen-4k9v2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gümrük handa bir odaya kapattılar

arasız geçmişi sorguladılar

ne ekmek ne su ne görüşme

korkuya yalnızlığa ellemediler

sevdayı ayla büyütmediler

gurura ekine hiç yetmediler

hayali gerçeği bilmediler

ne beyin ne yürek ne sevişme

her sorguda bir yanım düşüyor

biri kaçıp yalnızlığa gidiyor

bir diğeri ihaneti seçiyor

pencereden içeri bir bulut düşüyor

ne yağmur ne bulut ne üşüme

her tavan farklı bir diğerinden

sırtüstü yatakta göz kırpmadan

arasız umut sorgulanmadan

hastane tavanı beter hücreden

ne pembe ne kırmızı ne vişne

aylardan temmuz ayrılık sarısında

rüzgar esmiyor fırtına saatinde

elektrik verseler oniki nöbetinde

bana mısın demiyor kırkı geçince

ne saçıma ne tırnağıma ne dişime

gümrük handa bir odaya kapattılar

arasız benliğimi sorguladılar

ne günüme ne geceme ne düşüme

	(İstanbul - 10.7.2000)', 'gümrük handa bir odaya kapattılar arasız geçmişi sorguladılar ne ekmek ne su ne görüşme korkuya yalnızlığa ellemediler sevdayı ayla büyütmed...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gumruk-han-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırıklar', 'hickiriklar-nurullah-genc-zk3k8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saatler bitmiyor yapayalnızım

Gülmek istiyorum,gülemiyorum

Sensiz olmak mıdır hep alınyazım

Bilmek istiyorum,bilemiyorum.

Esirgedin nazlı,hilal kaşını

Harap ettin çiçek kokan başını

Yüreğime akan gözüm yaşını

Silmek istiyorum,silemiyorum.

Sanki her şey efsaneydi,masaldı

Ayrılık ruhumu elimden aldı

Gözlerim yollara takılıp kaldı

Gelmek istiyorum,gelemiyorum.

Göğüs germek için acılarıma

Titreyişlerime,sancılarıma

Seni bir kez olsun avuçlarıma

Almak istiyorum,alamıyorum.

Saçılan bir köpük olmak dilinde

Boğulmak saçının ince telinde

Sır gibi sonsuza değin kalbinde

Kalmak istiyorum,kalamıyorum.

Unutuyor beni sırlı gözlerin

İçimde bir yara işliyor derin

Kulakların,dudakların,ellerin

Olmak istiyorum,olamıyorum.

Bölerek uykunu rüyalarına

O kucak dolusu hülyalarına

Gece gündüz uçup aynalarına

Konmak istiyorum,konamıyorum.

Deli gibi aşık olsa da güle

Kim acır çöllerde öten bülbüle

Bir gün alev alev yanıp da küle

Dönmek istiyorum,dönemiyorum.

Hıçkıra hıçkıra ağlamaktansa

Başına karalar bağlamaktansa

Bu yüreği her gün dağlamaktansa

Ölmek istiyorum ölemiyorum.', 'Saatler bitmiyor yapayalnızım Gülmek istiyorum,gülemiyorum Sensiz olmak mıdır hep alınyazım Bilmek istiyorum,bilemiyorum. Esirgedin nazlı,hi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hickiriklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçücük Bileklerimizle', 'kucucuk-bileklerimizle-cemil-yesildag-35qsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçücük bileklerimizle

Kocaman

Aha

Bu kadar yürekler yaratırdıkda

Birileri hayallerimizi çalıyordu

Birileri rüyalarımıza kusuyordu

Bize

Her keresinde soframıza

Kusulmuş olanı 

Temizlemek kalıyordu

Küfrettiğimiz 

Yüzüne tükürmeye bile tenezül etmediğimiz

Birileri kaderimizi çizerdi de

Biz yinede aldırmazdık

Herkeresinde 

Yasak olan kavramları 

Birbirimize sorar

Yasak olan şiirleri

Yine ezberlerdik

Küçücük bileklerimizle 

Kocaman 

Aha 

Bu kadar 

Yürekler yarattık', 'Küçücük bileklerimizle Kocaman Aha Bu kadar yürekler yaratırdıkda Birileri hayallerimizi çalıyordu Birileri rüyalarımıza kusuyordu Bize Her ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kucucuk-bileklerimizle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koymuyor Artık', 'koymuyor-artik-i-lker-gulec-utllr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alıştım artık biliyormusun?

Sen vardın senden öncesi vardı

Ondanda öncesi,önceleri vardı

Sesini duymayışım koymuyor artık.', 'Alıştım artık biliyormusun? Sen vardın senden öncesi vardı Ondanda öncesi,önceleri vardı Sesini duymayışım koymuyor artık....', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/koymuyor-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emel Var', 'emel-var-i-lker-gulec-vngpm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyuyormusun gaibten gelen sesi

Adı ruhani çağırıyorlar beni

Arıyorum orda ruhani ruhani seni

Adının altında bir emel var

***************

İnanmıyorum sen misin bu?

Hangi güzelliği düşünsem aldığın,

Şekil,gelincik,zambak yada mehtap

Güzel sözün altında bir emel var

***************

Elimden tutarak götürüyorsun beni

Sevgimdeki yerini anlamışsın gibi

Gösteriyorsun bana ruhaniliğin sırrını

Gözlerinin içinde bir emel var.', 'Duyuyormusun gaibten gelen sesi Adı ruhani çağırıyorlar beni Arıyorum orda ruhani ruhani seni Adının altında bir emel var *************** İn...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/emel-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlarmısın?', 'hatirlarmisin-i-lker-gulec-z3y13', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine şiir yine söz duygularımın kardeşi

Geceler,yıldızlar,tabiat ,uygularımın sesi

Hep arıyorum Dünya dışında bir yeri

Ömrüm bitti bulamadım senden başkasını

Kader değilmiş bekle mahşerde beni

           Gözlerinin içinde eridiğim anlar

           Buluştuğumuz sahil,koylar

           Yemek yediğimiz o mekanlar

           Tarih olmuş eskimiş topraklar

           Gelecek eskimeyen duygularım mahşere kadar

Hiç tasalanma alamaz kimse senin yerini

Beni unut gitsin gelsin iyi olduğun haberi

Reddetme rüyanda gülveren elleri

Kendi sesini duyduğun zaman

Reddetme kulağına gelen şiirleri

Bir an aklına geldiğim zaman

Hatırlarmısın mahşerde bekleyen şairi', 'Yine şiir yine söz duygularımın kardeşi Geceler,yıldızlar,tabiat ,uygularımın sesi Hep arıyorum Dünya dışında bir yeri Ömrüm bitti bulamadım...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatirlarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın Şair', 'saskin-sair-i-lker-gulec-5dw2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gecenin sabahı gibi

Aşırı duygusal olduğum gibi

Biliyordum seninde gideceğini

Çünkü,Orhan  Veli derki;

Şairler aşıklardanda beter

Benim kahrımı Güneşim,Denizler

Geceler,yediverenler çeker

Şimdi yediverenler

Nasıl görünüyor biliyormusun?

Ne söylüyor?Bizim dilimizden 

Sen anlıyorsun bizi derdimizi

Dinliyorsun,hey be şaşkın şair!

Sende bizim gibi kendi dilinden

Anlayanı bulsana', 'Her gecenin sabahı gibi Aşırı duygusal olduğum gibi Biliyordum seninde gideceğini Çünkü,Orhan  Veli derki; Şairler aşıklardanda beter Benim ...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/saskin-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dal', 'son-dal-i-lker-gulec-0jtcj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat tecrübe sen ise bir dal

Duygu selinde tutunacağım bir dal

Ama bitti artık bu ağacında son dalına geldim', 'Hayat tecrübe sen ise bir dal Duygu selinde tutunacağım bir dal Ama bitti artık bu ağacında son dalına geldim...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/son-dal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan', 'uyan-i-lker-gulec-dyed0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aç gözünü diyor içimdeki çocuk

Verdiğin sözleri hatırla çabuk

Hani olmayacaktı sevgi,dildar,aşk

Olmayacaktı hani ruhun keş

Bak kendine doğrul sarhoş

İdealini hatırla ona doğru koş.', 'Aç gözünü diyor içimdeki çocuk Verdiğin sözleri hatırla çabuk Hani olmayacaktı sevgi,dildar,aşk Olmayacaktı hani ruhun keş Bak kendine doğru...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim', 'gelecegim-i-lker-gulec-6zqgt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde güllerle geleceğim

Okyanusların her dalgasından

Sana sevgiler getireceğim

**********

Aldığım havada içtiğim suda

Güneşin her bir ışık hüzmesinde

Seni gördüğümü göstereceğim

**********

Ormanlarda yeşilin her tonuyla

Ağaçların her yaprağında

Mutluluğu yoluna sereceğim

**********

Düşün her kum tanesini

Düşün her yağmur damlasını

Her birinden bir mutluluk getireceğim

**********

Bak sağanak yağan yağmura

Bak bütün sahillere

Sonsuz mutluluğu şimdi vereceğim

**********

Ormanlık güneşlik bir havada

Okyanusların sahil kenarında

Bir elimde menekşelerle geleceğim

**********

Bir elimde bütün sevenlerin bulunduğu ada

En üstünde sen,ben hemen karşında

Bütün yüreğimle benliğimle sana geleceğim', 'Elimde güllerle geleceğim Okyanusların her dalgasından Sana sevgiler getireceğim ********** Aldığım havada içtiğim suda Güneşin her bir ışık...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Aleme', 'sanal-aleme-i-lker-gulec-ex7bo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gül bir gelincik elimde

Umuda doğru yolculuk

Klavuzum gündüzleri güneş

Klavuzum geceleri yıldızlar

***************

Engellerim hep karabulutlar

Yardımıma koşuyor rüzgarlar

Ya tek tarafı yosun tutan ağaçlar

Yön bu tarafa dön diyor

************

Yardımıma koşan okyanuslar

Bak bize her zerremizden sevgiler

Gittiğin sanal umut aleminde

Herkese sevgilerimizi götür diyor

************

Her zerrenizden kendi duygularımla

SAhillerdeki her kum tanesiyle

Sevgilerimi getirdim sanal aleme

Almazmısınız sevenler sevilenlere', 'Bir gül bir gelincik elimde Umuda doğru yolculuk Klavuzum gündüzleri güneş Klavuzum geceleri yıldızlar *************** Engellerim hep karabu...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanal-aleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğüm Zaman', 'oldugum-zaman-i-lker-gulec-sm1k5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakarken ışıldayan güneşe

Hatırlatıyor bana  geceyi

Söylerken son sözlerimi

Hatırlıyorum gerçek alemi

***************

Geceleri mehtapla yıldızlarla

Gün ortasında güneşle bulutlarla

Sabahları her tan ağırışında

Yüzünü çiziyorum gökyüzüne

****************

Gece olunca güneşi

Gündüz olunca yıldızları

Öldüğüm zaman ruhumu

Arayacağım yüreğinde', 'Bakarken ışıldayan güneşe Hatırlatıyor bana  geceyi Söylerken son sözlerimi Hatırlıyorum gerçek alemi *************** Geceleri mehtapla yıld...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oldugum-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-cemil-yesildag-5lpjj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Anneme işaf olunur-

Penceremde yağmur taneleri

İçimde korku

Heyecan

Binbir telaş 

Bu sabah anne

Bu sabah

Sevgi üstüne 

Sevgili üstüne 

Türküler dizerdin de

Anlayalım diye seni

Baharlar koklatırdın bize...', '- Anneme işaf olunur- Penceremde yağmur taneleri İçimde korku Heyecan Binbir telaş  Bu sabah anne Bu sabah Sevgi üstüne  Sevgili üstüne  Tür...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anne-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyebilirmiyim?', 'soyleyebilirmiyim-i-lker-gulec-iycgh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söyleyebilirmiyim sana karşı olan hislerimi

Her gecemde yıldızlarla süslü yüzünü

Söyleyebilirmiyim sana her zaman seni gördüğümü

Sadece gecelerde değil esen rüzgarda doğan güneşte

Hep göz ucumda durmana rağmen dokunamayışımı....', 'Söyleyebilirmiyim sana karşı olan hislerimi Her gecemde yıldızlarla süslü yüzünü Söyleyebilirmiyim sana her zaman seni gördüğümü Sadece gece...', ARRAY['Türk Edebiyatı','Şiir','İlker Güleç']::text[], 8.5, '{"poet":"İlker Güleç","poet_slug":"i-lker-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/soyleyebilirmiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavramlar', 'kavramlar-cemil-yesildag-r515f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sigara daha

günahlarıma ekliyorum

ardından günahlarıma 

bir set çekiyorum

kavramlar karıştı

yılan bir kavis çizerek ilerliyor

cinayet dolu bir gece geçiriyorum

adını hain diye nitelendirdiğim

bulvarda

bir akşan üstü

yürüyüşe çıkıyorum

isteksiz ağır ve yapayalnız

buruk bir yürek taşıyarak', 'Bir sigara daha günahlarıma ekliyorum ardından günahlarıma  bir set çekiyorum kavramlar karıştı yılan bir kavis çizerek ilerliyor cinayet do...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kavramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açılın Ha Dostlar', 'acilin-ha-dostlar-mennan-cokhizli-knrdx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarın bugünü olsun yarın

Karın geceyle gündüzü büyüsün karın

Sarın güneşi gökyüzne tut o senin sarın

Varın ufuk çizgisine çizgi-ötesi yargısına varın

(Foça-10 Haz.1994)', 'Yarın bugünü olsun yarın Karın geceyle gündüzü büyüsün karın Sarın güneşi gökyüzne tut o senin sarın Varın ufuk çizgisine çizgi-ötesi yargıs...', ARRAY['Türk Edebiyatı','Şiir','Mennan Çokhızlı']::text[], 8.5, '{"poet":"Mennan Çokhızlı","poet_slug":"mennan-cokhizli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/acilin-ha-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-cemil-yesildag-r7e1p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bırak

bugün de gözlerin 

çiçek açsın

ve 

sarksın yanaklarına

bilinmezliklere

gebe bir caddede

bir akşam üstünde

bir kıraşane ününde

bir demet 

kankırmızısı çiçek

iki damla gözyaşı

sunayım sana', 'bırak bugün de gözlerin  çiçek açsın ve  sarksın yanaklarına bilinmezliklere gebe bir caddede bir akşam üstünde bir kıraşane ününde bir deme...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜL', 'gul-mennan-cokhizli-cne99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülse Gül

Güldür Güldür

Gülsün gülde

Gülen Gül

Gülle

Gülegüle

Gülüm güldür

Gülden güle', 'Gülse Gül Güldür Güldür Gülsün gülde Gülen Gül Gülle Gülegüle Gülüm güldür Gülden güle...', ARRAY['Türk Edebiyatı','Şiir','Mennan Çokhızlı']::text[], 8.5, '{"poet":"Mennan Çokhızlı","poet_slug":"mennan-cokhizli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-cemil-yesildag-hkcrp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'pierraya atf olunur

ay küçük

  gece zifiri karanlık

    su haşin

      ateş kor kesilmiş

        pierra uzak

          bütün telefonlar yasak', 'pierraya atf olunur ay küçük   gece zifiri karanlık     su haşin       ateş kor kesilmiş         pierra uzak           bütün telefonlar yasa...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Olan Ne?', 'yanlis-olan-ne-mennan-cokhizli-c6hlu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep bir çizgi üzerinde yürüdük

Çizgi çatladı

Sel oldu yarınlar 

Sandal yapıp buluşamadık

Koro halinde masal anlattık,dimağımıza

Ancak susuyınca uyandık 

Bir arpa boyu gittiğimizi sandık

Arpa tanesine takılarak düştük

Yılan önce güldü dost sandık

Lakin denizde değildik Niye? yılana sarıldık

(Tuzla/istanbul 5 aralık 1993)', 'Hep bir çizgi üzerinde yürüdük Çizgi çatladı Sel oldu yarınlar  Sandal yapıp buluşamadık Koro halinde masal anlattık,dimağımıza Ancak susuyı...', ARRAY['Türk Edebiyatı','Şiir','Mennan Çokhızlı']::text[], 8.5, '{"poet":"Mennan Çokhızlı","poet_slug":"mennan-cokhizli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanlis-olan-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldi!', 'geldi-melek-midikoglu-75b9q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığın dudağından

Pırlantalar yağdı ışıl ışıl gözlere

O güzel ruh gelmişti

Neredeydin dedi gönüller

Kapılardaki uğultular 

Neşe cıvıltılarına dönüştü

Sevgi bahçesi sunan

Bir çift göz, bir dil, bir kalp

Hoşgeldin sana hasret yuvamıza

Son noktamız aşk olsun

Sonsuz kere sürsün dursun

Öperim sözlerimi gören

Yıldız gözlerinden

Güzel ruh! 

Konuş, açıl ve çoğal...

(31.5.2000)', 'Karanlığın dudağından Pırlantalar yağdı ışıl ışıl gözlere O güzel ruh gelmişti Neredeydin dedi gönüller Kapılardaki uğultular  Neşe cıvıltıl...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkınla', 'askinla-huseyin-nihal-atsiz-vxp6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkınla senin bunca gönül etmede nale...

Uğrunda akan gözyaşımız oldu şelale.

Onmaz kara sevdamızı kan söndürecektir...

O füsunkar ve güzel gözleri her kalbi deşen 

Öyle bir nazlı kızın aşkına düştüm ben ki...

Ey bir eşi bulunmaz fedakar,mert arkadaş!

Kıskandırdın bizi sen,bak ölümün ne kadar şanlı!

Arkadaşımızın mert ve şan dolu göğsünde

Şehitliğin nişanı kızıl bir gül açıldı....', 'Aşkınla senin bunca gönül etmede nale... Uğrunda akan gözyaşımız oldu şelale. Onmaz kara sevdamızı kan söndürecektir... O füsunkar ve güzel ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlak Seveceksin', 'mutlak-seveceksin-huseyin-nihal-atsiz-xzidg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda gibi bir gizli emel ruhuna sinmiş; 

Bir haz ki hayalden bile üstün ve derinmiş.

Gökten gelerek gönlüne rüzgar gibi inmiş,

Bir sır ki bu,ölsen bile açamazsın...

Anlatması imkansız olan öyle bir an ki,

Hülyadaki ses varlığının gayesi sanki...

Bak emrediyor:Daldığın alemden uyan ki,

Mutlak seveceksin beni, bundan kaçamazsın...

Kalbin benim olsun diyorum,çünkü mukadder...

Cismin sana yetmez mi? Çabuk kalbini sök,ver! 

Yoktur öte alemde de kurtulmaya bir yer! 

Mutlak seveceksin beni,bundan kaçamazsın...

Ram ol bana,ruhun yeni bir aleme girsin...

Yazmış kaderin:Aşkıma ömrünce esirsin! 

Aklınla,şuurunla,hayalinle bilirsin.

Mutlak seveceksin beni,bundan kaçamazsın...', 'Sevda gibi bir gizli emel ruhuna sinmiş;  Bir haz ki hayalden bile üstün ve derinmiş. Gökten gelerek gönlüne rüzgar gibi inmiş, Bir sır ki b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlak-seveceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerde Yoncaydı', 'yerde-yoncaydi-omer-sevincgul-osn4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceleyindi. 

derin vadiden indim de ovada oyalandımdı. 

bir yılan kıvrıla kıvrıla belime dolandıydı. 

yerde yoncaydı semada aydı. 

gözleri karaydı ayla aydındı. 

pulları yıldız yıldızdı. 

rengini ayırdedemediydim. 

görünmez uzaklardan nidalar geldiydi. 

kulaklarımla da görmedeydim. 

bedenim alev alevdi. 

yılan ısınmak istiyor gibiydi. 

ben sönmeliydim.

 nefesimi dinlemedeydi.

 uzaktan rüzgar kanatlı atların nal sesleri gelmedeydi. 

iki dallı dili yüzümü yaladıydı. 

dilini dudaklarımla tutuverdiydim. 

dilime doladımdı. 

geceleyindi. 

yılanın dilini emdiydim. 

kıvranıyor ve sarıyordu. ısınıyordu. 

serinlik yayıyordu dili. 

ay söndüydü. 

nida sustuydu. 

yer kaydıydı.

 iki zıt birbirini tüketmedeydi. 

ovanın cinleri oradaydı. 

yel cince sesler taşımadaydı. 

ben benim yanımdaydım. 

ben beni ve yılanı seyirdeydim. 

dili yetmediydi. 

gözlü kafasını emmedeydim.

 içime kar suları akmadaydı. 

yılanı eme eme yutmadaydım. 

dudaklarımın önünde son titreyen ince sonuydu. 

serinlediydim serinlik bendeydi. 

yılan dediydi seninim sendenim seninleyim. 

bendim bendendi benimdi. 

evvelinde de benimdi sonrasında da benimdi. 

yılan benimle bedenim arasına kıvrılıp yattıydı. 

halkalandıydı başı bedeninin üstündeydi. 

gözlerini kapadıydı. 

uyuyor gibiydi uyumamaktaydı. 

yılan hakikatte yalandı. 

yılan hakikaten yılandı. 

ama geceydi yerde yoncaydı semada aydı.', 'geceleyindi.  derin vadiden indim de ovada oyalandımdı.  bir yılan kıvrıla kıvrıla belime dolandıydı.  yerde yoncaydı semada aydı.  gözleri ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yerde-yoncaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-umit-yasar-oguzcan-xawit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen degiştin, resimlerin hiç degişmedi

Nasıl seviyorum bilmezsin şu albümü

Resimler yalancı degil, resimler ölmüyor,

Aslında acı olan şey; sevgilerin ölümü

Sahte renkler yerini gölgelere bırakmış

Resimlerde siyah beyaz gözlerin, dudakların

İşte bak! ellerin ellerimi arıyor

Resimlerde besbelli anlatamadıkların

Şimdi bir çerçeveden gülümsüyorsun bana

Hatırlıyor musun bu resmin çekildiği günü

Bakışların ne kadar duygulu, ne kadar sıcak

Anlıyorum neler düşündüğünü.

Bir başka resimde biraz kederlisin

Hüzünlü bir şarkı dökülüyor dudağından

Şimdi senden çok uzak bir şehirde

Seni seyrediyorum bir albüm yaprağında

Bu karanlık yoktu, bir zaman sen vardın

Yaşamak cömertçe sunduğun bir ışıktı

Sen değiştin, onlar hiç değişmedi

Resimlerin senden vefalı çıktı', 'Sen degiştin, resimlerin hiç degişmedi Nasıl seviyorum bilmezsin şu albümü Resimler yalancı degil, resimler ölmüyor, Aslında acı olan şey; s...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/resimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, Ağlama', 'sen-aglama-umit-yasar-oguzcan-fgjjj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ağlayan şairim

Bana gülmesini ögretmediler

Egil de bir bak mahzun yüzüme

Anlatır sana çektiklerimi

Birer bıçak yarası gibi

Alnımdaki çizgiler

Ben mutluluk nedir bilemedim

Saçlarım okşanmaya alışık degil

Hep böyle dalıp gider gözlerim

Ve ne zaman düşünsem geçen günleri

Bir karanlık basar içimi

Aydınlık degil

Seni nasıl severim bilirsin

Nasıl yanarım özlemler içinde

Bastıgın yerler cennet olur

Bilirim en serin rüzgarlar gelirsin

Yine de yanar tutuşurum ben

Cehennemler içinde.

En mutlu sandıgın yerde kederliyim

Ben seninle sensizligi düşünürüm

Bir korku düşer içime apansız

Burkulur yüregim

Seni şiirlerimde bin yıl yaşatır da

Ben bin defa ölürüm

Bir gün yoklugum bir gölge gibi

Düşüverirse gözlerine

Unutma aglayan şairini

Unutma o günde kapanıp dizlerine

Kendi yokluguma kendim aglarım

Sen aglama e mi

Sen aglama e mi?', 'Ben ağlayan şairim Bana gülmesini ögretmediler Egil de bir bak mahzun yüzüme Anlatır sana çektiklerimi Birer bıçak yarası gibi Alnımdaki çiz...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Orada Ben Burada', 'sen-orada-ben-burada-umit-yasar-oguzcan-ybyvq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben orada öldüm en çok orada bilmezsin

Orada zaman buruşmuş bir eski resimdi

Orada sen yoktun, gözlerin belli belirsiz

Koptum oradan, bir kırık heykelim şimdi

Bir kolum derin denizlerde tek başına

Ayaklarım çöllerde kum tepelerinde gömülü

Alıp götürür saçlarımı bir soguk rüzgar

Ben orada öldüm, en çok orada bir başka türlü

Hiç bende degilsin, burada yoksun ki

Orada var mısın, ya da ben yok muyum

Tek degiliz seninle, bütün olmadık hiç

Şimdi nerdeyiz nasılız bilmiyorum

Orada akşamlar daha çok serin

Ben bu kadar degilim, bu kadar yıkık

Sarhoşum, kederliyim, yoksulum, sensizim

Orası sisler içinde orası karanlık.

Bensiz oldugun yerde degil mi en güzelsin

Bensiz oldugun yerde şöyle şarkılarını aşkını

Bir mermeri al, yont, şekil ver ona benden

Bir günah işlercesine sessiz ve dalgın

En iyisi sen burada kal, hep burada

Ellerinle kal, dudaklarınla, gözlerinle

Tut ki bütün renkler senin mavi kırmızı

Burada her şey sen nasıl istersen öyle

Bir büyük ayna duvarlar çok büyük

Orayı düşünme hiç burada soyun

Utandır duvarları pencereleri, kapıları

İki yalnızız şimdi anlıyor musun

Var sandıgın sen sen degilsin bir başkası

Benim anlasana benim o yok dedigin

Sabahları bir serin havayım içine dolan

Benim akşamları pencerende bekledigin

Hiç bir şey bilmiyorum, sen anlıyorsun

Senin bilmediklerini anladıgım gibi

Güzel, parmaklarının degdigi bir şey

Sensizlikler içinde seninle olmak iyi

Orada bulutlar yagıyor paramparça

Orada aglayan daglardır göge en yakın

Orada sen yoksun, orada bir şey yok

Orada kan ve ölüm, orada yangın', 'Ben orada öldüm en çok orada bilmezsin Orada zaman buruşmuş bir eski resimdi Orada sen yoktun, gözlerin belli belirsiz Koptum oradan, bir kı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-orada-ben-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olmak', 'sensiz-olmak-umit-yasar-oguzcan-q28ya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nerde o denizim benim, lekesiz gökyüzüm?

hani o içtikce susuzlugumu arttıran çeşme?

kim götürdü bakışlarımı, ne oldu gözlerime?

hani benim ellerim, ayaklarım, saçlarım, yüzüm?

bu ben degilim besbelli, bu bir başkası!

gözlerim yabancı bakıyor gözlerime aynadan

o kim? böyle durup durup beni aldatan?

besbelli bir oyuna gelmişim açıkcası

birini sevmişim besbelli, beni koyup gitmiş,

ondan şimdi aradıgım hep o, hep ben!

o ikisi kırmış beni, yıkmış , incitmiş

şimdi bilmedigim bir şarki her yerde söylenen;

sevinçten , mutluluktan , sevgiden uzak.

ne acı! senin olmak , sende olmak , sensiz olmak!', 'nerde o denizim benim, lekesiz gökyüzüm? hani o içtikce susuzlugumu arttıran çeşme? kim götürdü bakışlarımı, ne oldu gözlerime? hani benim e...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Çıkmazı', 'sevgi-cikmazi-umit-yasar-oguzcan-1qsdf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O artık benim için bir ölüdür demişsin

Seni bunca sevene acı bir sitem mi bu

Ayrılıklar içinde taş mı kesildi kalbin

Hiç unutmam dedigin günleri unuttun mu

Bir ev hatırlıyorum sonra küçük bir oda

Ve hazdan yeryüzünde kaybolmuş iki kişi

Ellerini sürdügün her şey güzel olmalı

İnan her gün yeniden yaşıyorum geçmişi

Degil seviştigimiz o essiz birkac ayı

Bir elmas parçasını ustaca işler gibi

Bir bir düşünüyorum geçen her dakikayı

Dilerim yeniden dog gel de güneşler gibi

Mahzun dudaklarımda aşkın ateşini yak

Sevenler için degil yaşarken ölü olmak', 'O artık benim için bir ölüdür demişsin Seni bunca sevene acı bir sitem mi bu Ayrılıklar içinde taş mı kesildi kalbin Hiç unutmam dedigin gün...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman İçinde', 'zaman-i-cinde-umit-yasar-oguzcan-379no', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak! İşte gizleri yaşamın, işte mutluluk

Gülümsüyor bir kapı aralıgından

Ellerimizi uzatsak tutabiliriz belki

Şimdi ya da hiç bir zaman

Unuttugum bir şarkı mı? neydi o

Çok eskilerde düşmezdi agzımdan

Birlikte yine söyleyebiliriz belki

Şimdi ya da hiç bir zaman

Gülen bir çocuk vardı yıllarca önce

Düşleriyle bulutlar üstünde yaşayan

Belki bir kez daha yaşarız o günleri

Şimdi ya da hiç bir zaman

Nasıl da yandı bir anda. Görüyor musun?

Dev agaçlarıyla o içimizdeki orman

Yanmamış bir yer buluruz belki, ararsak

Şimdi ya da hiç bir zaman

Kişi sımsıkı sarılıyor bulduklarına

Umutların bir rüzgarla savruldugu an

Yine de bir şeyler kurtarabiliriz belki

Şimdi ya da hiç bir zaman

Her şey bize biz kadar yabancı artık

Giderek yitiyor zaman içinde insan

Oysa ki, çagları aşabiliriz birlikte, gel

Şimdi ya da hiç bir zaman', 'Bak! İşte gizleri yaşamın, işte mutluluk Gülümsüyor bir kapı aralıgından Ellerimizi uzatsak tutabiliriz belki Şimdi ya da hiç bir zaman Unut...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zaman-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Savaşçının Şiiri', 'yorgun-savascinin-siiri-umit-yasar-oguzcan-ogb7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan bir açmaza düşmeye görsün

Başlamasın bir çöküntü yürekte

Ölümdür o yerde düşündügün

Sevilmek de boştur artık sevmek de

Gün ortası karanlık diz boyudur

Acıdır hep geçmişten ne kalmışsa

Yaşamak! O yanıtsız bir sorudur

Huzur bitmiş, hayaller dagılmışsa

Nefes almak yitirir anlamını

Bogazına dizilirken lokmalar

Bir çaresizlik sarar dört yanını

Sesler uzaklaşır, söner lambalar

İsyanın yüregine sıgmaz olur

Hep kader gelmişse sevinç yerine

Ölümün kara gölgesini bulur

Şimdi bakanlar yorgun gözlerine

Bir bozgun başlamıştır ki amansız

Düşmüştür kalelerin birer birer

Bak! Savaşcıların yatıyor cansız

Onlar ki hep sevdiler, hep verdiler

Yitirdin neyin varsa, anla artık

Tek başına kalan sensin ortada

Düşlerin toz duman, umutlar kırık

Dün anlamsız, yarınlar paramparça

Yapayalnızsın koca bir evrende

Uzakta, taparcasına sevdigin

Gelmiyecek, ne kadar gel desen de

Ondan böyle bir yangın yeri için

Ondan böyle yıkılan bir dünyanın

Altında bak tek başına kalmışsın

Uzagında özledinin bir anın

Çökmüşsün, devrilmişsin, yıkılmışsın

Sarmış kollarını boynuna ölüm

Ne yapsan boş, kurtulamazıin artık

De ki:-- Hep yalanmış, bitiyor öyküm--

Bak! Can kuşun havalarda çıglık çıglık...', 'İnsan bir açmaza düşmeye görsün Başlamasın bir çöküntü yürekte Ölümdür o yerde düşündügün Sevilmek de boştur artık sevmek de Gün ortası kara...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yorgun-savascinin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Her Dakika Ölüm Demek Gitme Kal', 'yoklugun-her-dakika-olum-demek-gitme-kal-umit-yasar-oguzcan-txrz3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğun her dakika ölüm demek gitme kal

Hasretim daha yüz yıl dinmeyecek gitme kal

Yetişir senden uzak yıllardır kahroldugum

Ayrılma hiç yanımdan mahşere dek gitme kal', 'Yokluğun her dakika ölüm demek gitme kal Hasretim daha yüz yıl dinmeyecek gitme kal Yetişir senden uzak yıllardır kahroldugum Ayrılma hiç ya...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoklugun-her-dakika-olum-demek-gitme-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayanlar İçin', 'yasayanlar-i-cin-umit-yasar-oguzcan-hgnfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açlara ekmekle bir sıcak çorba

Susamışlara bir yudum su verin

Biraz serinlesin çatlak dudaklar

Dinsin kazıntısı aç midelerin

Uykusuz olana bir yatak serin

Evinizde geçelerce uyusun

Ateşler yakın ki üşüyenlere

Sıcak ayakları, elleri olsun

Kimi bacaktan, kimi gözden yoksun

Bir dünya üstünde yaşamak için

Çıplakla giyimli, güzelle çirkin

Çıplagı giydirin, çirkini sevin

Ölüm kapınızı çaldıgı zaman

Bir sevginiz olsun dünyada kalan', 'Açlara ekmekle bir sıcak çorba Susamışlara bir yudum su verin Biraz serinlesin çatlak dudaklar Dinsin kazıntısı aç midelerin Uykusuz olana b...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasayanlar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Ölü', 'yasayan-olu-umit-yasar-oguzcan-cqyd9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ölü gelecek evine yarın

Gözlerinde yarım kalmış arzular

Dalıp hayaline hatıraların

Duracak kapıda sabaha kadar

Duyunca kapını çaldıgını

Korkulu gözlerle dışarı bakma

Bütün odaların yak ışıgını

Bir benim kaldıgım odayı yakma.

Siyahlar giyin de pencereye çık

Aç kapıyı korkma yabancı degil

Bir ölü ki yaşıyor, gözleri açık

Ölüm seni sevmekten acı degil

Aradı bu ölü hayatı sende

Öldü artık, sevsen de sevmesen de', 'Bir ölü gelecek evine yarın Gözlerinde yarım kalmış arzular Dalıp hayaline hatıraların Duracak kapıda sabaha kadar Duyunca kapını çaldıgını ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasayan-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış Hatıralar', 'yasanmamis-hatiralar-umit-yasar-oguzcan-m5vqm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Yaşanmamış hatıralar bilirim

Büyülü sonbahar akşamlarında

Bulutlar üstünde su kenarında

Yalnız hayal edilen hatıralar

İşte; en ürpertici nagmelerle

Bizim şarkımızı söyleyen rüzgar

Sen dudagında gülümsemelerle

Ben gözyaşlarımla, bu alemdeyim

Fakat yine bizbize, başbaşayız

Duymasan düşünmesen de; unutma

Bir daha bu anı yaşayamayız.

II

Görülmemiş manzaralar bilirim

Karda, kışta, belki de ilkbaharda

Hür denizlerde, kuytu ormanlarda

Sadece hissedilen manzaralar

Bak. Dinle, neler anlatıyor yagmur

Üşüyorum üşüyorum beni sar

Karanlık başladı, gitme ne olur

İnan degişen manzaralar degil

Kiletreler ayıramadı bizi

Fakat bir gün gelir de birleştirir

Beyaz bir güvercin kanadı bizi

III

Söylenilmemiş mısralar bilirim

Hüzün dolu yagmurlu gecelerde

Alev çalgıların sustugu yerde

Yalnız, yalnız düşünülen mısralar

Bilinmeyen şeyler huzur içinde

Bilmenin bilinmez bir korkusu var

Bak bütün rüyalarım nur içinde

Çünkü, bugün havasını kokladıgın

Denizaşırı bir diyar bilirim

Ve o diyarda seninle beraber

Yaşanmamış hatıralar bilirim', 'I Yaşanmamış hatıralar bilirim Büyülü sonbahar akşamlarında Bulutlar üstünde su kenarında Yalnız hayal edilen hatıralar İşte; en ürpertici n...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yasanmamis-hatiralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bertiyanım', 'bertiyanim-nogay-yaren-nfliz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oy Bertiyan çiçek kokulum

Dağımın eteklerinde kekik kokanım..

Oy.. Nerdesin

Hangi güneş seni görmez kılar.. 

Hangi çamur  sıçrar üzerine

Oy Bertiyanım...

Ah edemem bertiyan 

Zavallıdır Aklım

Şaşar be bertiyan..

Nedendir Çiçekler kokmaz ...

Onlarda senin gibi bana küsmü 

Neden bertiyanım

Oy çiçek kokulum

Dağımda kekik kokanım

Yalnızlık seninle ceza kılındı bana 

Rüzgarda savrulan toprak olayım 

Olayım ki Bertiyan çöldeki her kum 

tanesi gibi.. 

Seni sarayım,

Oy bertiyanım 

Aklımın bekçisi nerdesin ?', 'Oy Bertiyan çiçek kokulum Dağımın eteklerinde kekik kokanım.. Oy.. Nerdesin Hangi güneş seni görmez kılar..  Hangi çamur  sıçrar üzerine Oy ...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bertiyanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüdünmü', 'usudunmu-mustafa-gokalp-yildirim-jvnv1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üşüdünmü

Yok sadece yüreğim üşüdü

Hep böyle olur zaten

Yalnızken

Yalnızlığımı yendiğimi düşündüğüm

saatlerde hep yüreğim üşür

Kortuğumdanmı nedir kendimden

Yada,

Yada yüzleşmekten çekindiğimemi bilmem

Senin hiç yüreğin üşüdümü?

ne bileyim ben

korktunmu gelecekten

yada sevmekten

yani böyle şeylerden

Ben bazen kaçağı olurum

sevginin

hayatın

sudan bile kaçarım

yansımada yüzüm görünür diye', 'Üşüdünmü Yok sadece yüreğim üşüdü Hep böyle olur zaten Yalnızken Yalnızlığımı yendiğimi düşündüğüm saatlerde hep yüreğim üşür Kortuğumdanmı ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökalp Yıldırım']::text[], 8.5, '{"poet":"Mustafa Gökalp Yıldırım","poet_slug":"mustafa-gokalp-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/usudunmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırmak I', 'haykirmak-i-cemil-yesildag-57c1u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessiz ve ansızın çıkıverirse

Hırçın duygularım

Ve yumruklayıverirse

Taş binaların

Beton duvarlarını

Unutma belki zulum vardır

Ademin çocuklarına

Muhammedin ümmetine', 'Sessiz ve ansızın çıkıverirse Hırçın duygularım Ve yumruklayıverirse Taş binaların Beton duvarlarını Unutma belki zulum vardır Ademin çocukl...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haykirmak-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırmak II', 'haykirmak-ii-cemil-yesildag-9hdte', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haykırmak gerekmezmi sanırsın

sen ey içimdeki

Benliği arayan kişi

Varlık aleminin farkına

Düşünerek varıyorsak

Delili değilmidir

Yırtık ayakkabılar

Ve yamalı gömlek

Üşüyen nine 

Ve aç kalan çocuk', 'Haykırmak gerekmezmi sanırsın sen ey içimdeki Benliği arayan kişi Varlık aleminin farkına Düşünerek varıyorsak Delili değilmidir Yırtık ayak...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/haykirmak-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Cinayet İşlerim', 'ben-bir-cinayet-i-slerim-cemil-yesildag-2rwjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir cinayet işlerim

İçimdeki duygulara

Beynimdeki düşüncelere

Başkalarının inadına

İnatlarına karşı

Ben bir cinayet işlerim

Körpe çocuklara

Aç bebeye

Üşüyen nineye

Bacımın çığlığına

Çığlıklarına karşı

Ben bir cinayet işlerim

Yosma caddelere

Boyalı duvarlara

Anlamsız slıgana

Sıloganlara karşı

Ben bir cinayet işlerim

Benliğime

Bedenime

Başkalarının inadına

inatlarına karşı', 'Ben bir cinayet işlerim İçimdeki duygulara Beynimdeki düşüncelere Başkalarının inadına İnatlarına karşı Ben bir cinayet işlerim Körpe çocukl...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-bir-cinayet-islerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaygı Besliyorum', 'kaygi-besliyorum-cemil-yesildag-zkw31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaygı besliyorum

Ta ruhumun derinliklerinden

Geniş coğrafyama

Umutlarımız

Yarınlarımız

Ve

Cenin halindeki

Çocuklarımız için

Kaygı besliyorum

Özümüz

Benliğimiz

Sevgimiz

Şiirimiz

Ve

Geleceğimiz için

Kaygı besliyorum

Bizi biz eden 

Tarih için', 'Kaygı besliyorum Ta ruhumun derinliklerinden Geniş coğrafyama Umutlarımız Yarınlarımız Ve Cenin halindeki Çocuklarımız için Kaygı besliyorum...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kaygi-besliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'intihar', 'intihar-cemil-yesildag-cq3gj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kopmuş

  bir

      ip

Motatmış

  bir

     boğaz

Donuk

  bir

     yüz

Cansız

  bir

     ceset

Ve

  bir 

     çığlık', 'Kopmuş   bir       ip Motatmış   bir      boğaz Donuk   bir      yüz Cansız   bir      ceset Ve   bir       çığlık...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/intihar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize', 'bize-bora-zihni-j2xxq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünün bulutsuz,o sonsuz maviliği altında

İçimizin sabırsız, bakışlarımızın anlamsız,

Dilimizin tutuk olduğu o  kahbe  cumartesinden sonra,

Oturmuş senden kalanlarla içiyorum bu akşam.

Gece tüm içtenliği ile zifiri.

Sokakta ise bir çocuk

Benim yerime,bana ortak,

Doya doya ağlıyor ,habersiz.

Bense onun gözyaşları ile tatmin oluyorum.

Ne kadar isterdim onun gibi ağlamayı.

İçten ve çekinmeden.

Unuttu gözlerim ağlamayı.

Oysa kalbim,

Her aklıma gelişinde,

Yani her saniye,içimde mahkum olan aşkıma,bize ağlıyor.', 'Gökyüzünün bulutsuz,o sonsuz maviliği altında İçimizin sabırsız, bakışlarımızın anlamsız, Dilimizin tutuk olduğu o  kahbe  cumartesinden son...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-gulay-atilay-zkkm2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlüyorum seni.

Gücüm yetmiyor unutmaya

Özlüyorum

Elini tutmayı sesini duymayı

Boynuna sarılıp omuzunda ağlamayı

Nedensiz sevinçleri

Hasret dolu sevgi dolu sımsıcak düşlerimi

Özlüyorum

Gücüm yetmiyor unutmaya 

Seni aramazsam unuturum sanmıştım

Girmez sanmıştım hayalin beynime

Geceleri düşlerimde

Gündüz baktığım heryerde seni

Özlüyorum..

Renkler gitmenle soldu

Kırmızı kırmızılığını unuttu

Mavi maviliğinin farkında değil

Beyaz yanlız sen giydiğinde

güzelliğini haykırıyormuş

Özlüyorum

Bu özlem bu bekleyiş hiç bitmiyecek

Ruhumda sana açan eflatun renkli çiçekler 

solmayacak

Olmasanda sensiz sensizliği yaşatacağım 

Sensiz seninle olmayı başaracağım

Sonun yaklaştığını hissettiğim gün 

Beyaz ,bembeyaz mendilimi sallayarak

Sensiz yaşamın kahrediciliğine veda ederek

Seninle sonsuzluğa kavuşacağım..

/ Erenköy

08/08/2000', 'Özlüyorum seni. Gücüm yetmiyor unutmaya Özlüyorum Elini tutmayı sesini duymayı Boynuna sarılıp omuzunda ağlamayı Nedensiz sevinçleri Hasret ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ozluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık Yaprakları', 'sarmasik-yapraklari-cemil-yesildag-uxidz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim bilir 

Sarmaşık yapraklarını 

Kör ve sağır duvarları

Ya konuşursa masa ve sandalye

Bilirim

Bilirim kaybetme korkusunu

Ondandır acelem

Ve resmi konuşmam

Ondandır zamansız fikirler

Kalem susar

Ben susarım

Ve kağıt ağlar

Ama 

Kim bilir

Sarmaşık yapraklarının ne konuştuğunu

Kim bilir

Kaç sigara içtiğimi

Kaç cinayet işlediğimi

Kime sorsam

Bu şehir kirlidir 

Gitme...

Havasız solunmaz der

Kime sorsam

Bilmez

Sarmaşık yapraklarının ne konuştuğunu

Tahminayı 

                  Tamarayı

Tamara bir şiirde geçer

Tahmina büyük bir destan

Büyük bir aşkın başlangıcı

Ve kendi oğlunun katili

Üzülüyor Tamaraya çay çiçekleri

Cam üzüntüsünden çatlıyor

Tahmina için

Bir taş çatlıyor 

Sabırsızlıktan

Ama kime sorsam  bilmez

Sarmaşık yapraklarının ne konuştuğunu

Kim bilir

Kaç sigara içtiğimi

Kaç cinayet işlediğimi

Kim bilir ne kadar beklediğimi 

Ve ne kadar bekleyeceğimi....', 'Kim bilir  Sarmaşık yapraklarını  Kör ve sağır duvarları Ya konuşursa masa ve sandalye Bilirim Bilirim kaybetme korkusunu Ondandır acelem Ve...', ARRAY['Türk Edebiyatı','Şiir','Cemil Yeşildağ']::text[], 8.5, '{"poet":"Cemil Yeşildağ","poet_slug":"cemil-yesildag","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sarmasik-yapraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Tarihi', 'bir-askin-tarihi-celal-kabadayi-27xpv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşkların da tarihi vardır

kimileyin kum çöllerinde

kimileyin beton çöllerde

düşlerle yalnızlıklarla yazılır

acı tarihin en sevgili çocuğudur

unutulmaz ne gözyaşı ne kan

sevinçler yaşandığı yerde kalır

hüzündür şiirlere damgasını vuran

yaşamın kendisidir benim bildiğim

yaşanmayan ne varsa gerçekte

bir aşkın tarihidir işte o

gizli gizli birikir yürekte

başlamaz bitmez birşey bu

biçim değişir öz gelişir

tarihin çöplüğü doldu mu

üstünde gerçeğin gülleri yetişir', 'aşkların da tarihi vardır kimileyin kum çöllerinde kimileyin beton çöllerde düşlerle yalnızlıklarla yazılır acı tarihin en sevgili çocuğudur...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-askin-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erdal Eren,Kardeşim', 'erdal-eren-kardesim-celal-kabadayi-2gjiz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'rüzgarlara adını yazdım

yapraklar uğuldar şimdi

geceye yıldız çaldım

gözlerin parlar şimdi

acını yüreğime kazdım

ağıtlar susar şimdi

Erdal Eren,yiğit kardeşim

susuşuna yağmur

düşlerine güller yağsın

dağlar son sözlerinle

uçurumlar gülüşünle yankılansın

güneşli bakışların

ülkemin şafaklarına kalsın

Erdal Eren,güzel kardeşim

bir halkı astılar bir sabah

ölümü geçirirken senin boynuna

generaller küçüldü sen büyüdün

yarınların özgürlüğü adına

küçük yaşta büyük ölümle öldün

yaşasaydın ağabey diyecektim sana

Erdal Eren,ölümsüz kardeşim', 'rüzgarlara adını yazdım yapraklar uğuldar şimdi geceye yıldız çaldım gözlerin parlar şimdi acını yüreğime kazdım ağıtlar susar şimdi Erdal E...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/erdal-eren-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Bana Bağırma', 'baba-bana-bagirma-akgun-akova-jc64q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yol ıslanmasın diye

          şemsiye açanlara...

baba bana bağırma

bülbülleri kaçırdın ormanlarımdan

kulaklarımın kapılarını havalara uçurdun

kapılar baba kapılar pencereleri alıp gittiler

tenorlar kaçtı ses tellerinden

çevreye saçıldı yavru diktatörler

seni ne sopranolar istedi de vermedik baba 

baba bana bağırma

bayrak direklerine konan kartalları anlat

uzun uzadıya

nasıl da göremediler avcıları

o keskin gözleriyle vah hah ha

şans yıldızlara özgü bir yalan baba

yıldızlara tükürüp tükürüp onları gezegen yaptınız

savaşan halklar taktınız dünyanın boynuna

yalanları yazdım defterime hiç unutmadım

radyasyonu radyo istasyonu sanan Bakanları

çiğleri, Meclis tavanını çiğ köftelerle çiğneyen

doğum sonrası acılarını cüce ülkeler doğuran kadınların

hiç unutmadım

sakallarını yüzlerinde

yüzlerini sakallarında unutan adamları

ve ısırgan tarlalarındaki parçalarını

Uğur Mumcu''yu biz yapan bombanın

hiç unutmadım

uzak yakın tüm tuzakları baba

yolun ezdiği oyuncak bir kamyonsun sen

bir gam ağacısın

kar yüküne dayanamayıp kırılan

ilkbaharı gerzeklere ödünç verdin

geri getirmediler

güneşin başına gelenleri

biz ilkbaharsız nasıl anlarız baba

baba bana bağırma

bir kulağımdan giriyor sözlerin

öbür kulağımı tıkıyor

Buenos Aires''te olsaydım diyorum içimden

Eva''nın peronunda

karanlıktan kuşlar çalan bir tren

bir bıçak kaçağı

tangonun bacaklarını havaya kaldırdığı kentte

ama iyi ki buradayım, burada hiçbir şeyi unutmadan

burada

bilginin bilgisizlikten daha çok acı verdiği yerde

burada, tam karşında

hapisanelerde hintyağı gibi bir şeydi zaman

hastanelerde pıhtılaşmış kan gemisi gibi

yol alırdı saatler

karılarının namuslarını dillerinde saklayan

adamlar vardı bir taraflarda

televizyon kanallarında yitirilen çocuklar

gökyüzüne düşmemek için denize yapışan balıklar

ve depolara indirilen Lenin heykelleri vardı

Sovyet Rusya''da

kafandaki duvarları

niye cebine koymuyorsun sen baba

baba bana bağırma

farkında değilsin

arkasını ezilenlerin yaladığı

bir posta puludur dünya

bir karadelik yutana kadar uzayda bizi

asansör boşluğuna itilen bir kedisin sen

söylemenin tam sırası

ülkeyi bu duruma senin oy verdiğin

partiler getirdi baba

ama ben buradayım, burada hiçbir şeyi unutmadan

bir yaşamlık kaygı duruşundayım

yakın tarihimiz için

baba bana bağırma

bacağından vurulursa bir şiir

nereye kadar gidebilir

bana bağırma baba

kendine bağır

yoksa her şey bitebilir', 'yol ıslanmasın diye           şemsiye açanlara... baba bana bağırma bülbülleri kaçırdın ormanlarımdan kulaklarımın kapılarını havalara uçurd...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/baba-bana-bagirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azadîxwaz im', 'azad-xwaz-im-cigerxw-n-qrblc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tîp û lekên kurd ketin zinaran

    Li hawîr bumba bû gullebaran

    Êrîşdibin der komên neyaran

        De rabe ser xwe, kurê min rabe! 

    Şev ta sipîdê me nîne qet xew

    Cihan li ber me dibîte rew - rew

    Nêrkew nexwenî, çi bêyî mêkew? 

        De rabe ser xwe, kurê min rabe! 

    Bavê te çû şer, şêr e li meydan

    Êrîş dibin ser Îran û Tûran

    Destên xwe dan hev kurmanc û dostan

        De rabe ser xwe, kurê min rabe! 

    Kengî mezin bû, divêm bixwênî

    Rewşa cîhanê tu xweş bibênî

    Ji nû tu karî dijmin derênî

        De rabe ser xwe, kurê min rabe! 

    Keç û kurên kurd hemî şîyar bin

    Ji bo serbestî hemî li kar bin

    Ji hev re dost bin, dijê neyar bin

        De rabe ser xwe, kurê min rabe! 

    Dijware dijmin, Tûran û Firs e

    Gernas û mêr be, ji wan metirse

    Sibê şiyarbû, li min mepirse

        De rabe ser xwe, kurê min rabe! 

    Ji bo xweş bin dem û gevên te

    Ezê sipîdê bighê bavê te

    Bere ziwabin herdu çavên te

        De rabe ser xwe, kurê min rabe! 

    Milên xwe bidme milên berane

    Di şer da en tev xûşk û birane

    Êrîş bikin em, lê şer girane

        De rabe ser xwe, kurê min rabe! 

    Bizane, xwendin ji bo we derman

    Da ku bizanin qanûn û ferman

    Derxin ji dil em van tirs û şerman

        De rabe ser xwe, kurê min rabe! 

    Destên xwe bidne destên çepên rom

    Bibin partîzan bi leshker û kom

    Carek metirsin ji ''hok'' û ''fantom''

        De rabe ser xwe, kurê min rabe! 

    Dibî bavê te di şer de bimrî

    Zinhar kurê min nebî tu bigrî

    Em têne kuştin ji bo tu nemrî

        De rabe ser xwe, kurê min rabe! 

    Dijmin naçî der bi lav û gazê

    Xwînê nerêjî naghê daxwazê

    Siba diçim şer divêm tu razê

        De rabe ser xwe, kurê min rabe! 

    Şêx û melan em tev kirne derwêş 

    Ev bû du sed sal, em bûne berbêş 

    Ba bêne kuştin, nemêni ev êş 

        De rabe ser xwe, kurê min rabe! 

    Şîn tê bi xwînê dara serbestî

    Îdî naxwazin dîlî, bindestî

    Ev êlperestî, ev olperestî

        De rabe ser xwe, kurê min rabe! 

    Mirovperestim mîna Cigerxwîn

    Serbest bijîn tev, ne wek ''Mem'' û ''Zîn''

    Jîna serbestî, divê me ev jîn

        De rabe ser xwe, kurê min rabe! 

        (Cigerxwîn, Dîwana 7a, Hêvî)', 'Tîp û lekên kurd ketin zinaran     Li hawîr bumba bû gullebaran     Êrîşdibin der komên neyaran         De rabe ser xwe, kurê min rabe!     ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/azadixwaz-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilbil û Gul', 'bilbil-gul-cigerxw-n-2y0w0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilbilê dilkul dinalî,

Her li ser dêmên gulê,

Gul çi zanî ku li ser kê,

Wer dinalî bilbil e? 

          

Pertewa dêmên sipî

Carek li dil ku ew nedî

Çend bikî qêrîn û zarî

Kî dizanî dil kul e? 

          

Dilgirê wek bilbilê

Herdem bi nalîn û girî

Girtiyê benda evînê

Dil li benda sunbil e.

          

Dilbijê bê çare çibkî

Bil ji qêrîn û girî

Ê di benda dil revînê

Kî dizanî bê dil e? 

          

Ev xem û derd û elem

Ku min di dil de pir civîn

Tev ji pêt û pertewa

Şaha bi tac û sunbil e

          

Ew kesê sewdan li ser

Naçî rêza dilgiran

Her çiqasî ew bi gazî

Rengê dengê zengil e

          

Ger ji dêmên sorgulî

Pertew nedî nêv can û dil

Nakevî nêv bend û dava

Zulfê mest û fulfil e

          

Ez di benda dilrevayê

Tîr ji birhan têne dil

Lêw me dil herdem bi destê

Nazika reş-kakile

          

Ew kesê carek diye

Derdê evînê wî bi dil

Jar û sergerdan û meste

Xweş dizanî ''moşkil e''

          

Pertewa dîdariyê

Ku mêxolî ez kirim

Laleş a min ser li ber

Danî li sîng û paşilê

          

Bûye çil sal ku cigerxwîn

Bû ji tîrên ebriwan

Lew me dermanê birînê

Lêv û sêvên paxile

Cigerxwîn', 'Bilbilê dilkul dinalî, Her li ser dêmên gulê, Gul çi zanî ku li ser kê, Wer dinalî bilbil e?             Pertewa dêmên sipî Carek li dil ku ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bilbil-u-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben(de) Düş', 'ben-de-dus-mustafa-eryilmaz-b0sis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin ölüm diyor

yaşıyorum

gözlerin yaşam diyor 

ölüyorum

hergün silme acılar yüklü beden

savuruyorum

bir köşeye acı sürüp

yalnızlığına uzanıyorum

paramparça aynalar doğuruyorum

yaldızlı gölgelerin düşüyor üstüme

paramparça aynalar doğuruyorum

paramparça gövdemden

ellerimi kana buluyorum

sivri uçlarını şah damarıma sürüyorum

acıyı bilirsin 

acıyorum

iklimler boşalıyor takvimden

simi dökülüyor rahmimin

korkuyorum

ölüm beni alamaz diyorum

boğaza karşı ağlıyorum

ölüm beni alamaz diyorum

üstüme geliyor koşar adım

apansız gömülüyorum

nedenlerim kayboluyor

sukut yokuşuna sürülüyorum

sürülüyorum yalnızlar ülkesine

karnım tok

acıkıyorum

acıyı bilirsin 

acıyorum', 'gözlerin ölüm diyor yaşıyorum gözlerin yaşam diyor  ölüyorum hergün silme acılar yüklü beden savuruyorum bir köşeye acı sürüp yalnızlığına u...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Eryılmaz']::text[], 8.5, '{"poet":"Mustafa Eryılmaz","poet_slug":"mustafa-eryilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-de-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götür', 'gotur-feramuz-gorel-njbhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Al beni uzaklara götür

Küfrün olmadığı yerlere

Sevgimle sevdiğimle baş başa

Şükredeceğim yerlere beni götür

Bırakma beni buralarda

Allah kimseyi bırakmaz darda

İnsanların gözü servette, malda

Al beni maneviyat diyarına götür

Hakkı zikredeyim kana kana

Hakkım helal size benden yana

Küfrün içinde faydam olmaz sana

Al beni uzaklara götür

Yalancılıkla Allah diyenden bıktım

Gönlümün sarayını küfürle yıktım

Özgürlük ateşin ben daha yeni yaktım

Al beni gerçek özgürlüğe götür

Düşürme Feramuz''u derde

Çekme gözlerime sakın perde

Bilmiyorlar hak ve hakikat nerde

Hakkın hakikatin olduğu yerlere götür', 'Al beni uzaklara götür Küfrün olmadığı yerlere Sevgimle sevdiğimle baş başa Şükredeceğim yerlere beni götür Bırakma beni buralarda Allah kim...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gotur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-harun-kesik-o4sel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağladım bende arkadaş

Sessiz kuyularda istanbul da

Hep ezildim sömürüldüm 

Bende acılıyım arkadaş

Sende mi gidiyorsun ?

Yanlızlığa acıya kedere

Senide mi kaybediyoruz

Bende acılıyım arkadaş

Ben istanbul çocuğuyum 

Ama mutsuzum arkadaş

Sen gel istanbul a

Beni bırakın gideyim sılama

Garip kaldım kocaa istanbul da

Hani neresi iyi neresi

Ben bulamıyorum zevki kederi istanbul da

Beni bırakın gideyim sılama', 'Ağladım bende arkadaş Sessiz kuyularda istanbul da Hep ezildim sömürüldüm  Bende acılıyım arkadaş Sende mi gidiyorsun ? Yanlızlığa acıya ked...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agladim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardında', 'ardinda-faruk-nafiz-camlibel-tgn8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaktı yanardağ gibi can yurdunu son bakış,

Ve gönlüm koşmaz oldu maceralar ardında.

Önünde dün beyazlar giyinirken karakış

Bugün sensiz kalan yaz kar
..........
..........', 'Yaktı yanardağ gibi can yurdunu son bakış, Ve gönlüm koşmaz oldu maceralar ardında. Önünde dün beyazlar giyinirken karakış Bugün sensiz kala...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-faruk-nafiz-camlibel-c9o1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağzında şarkılıktan çıkmış iniltilerle

Dağ, taş deme, arkadaş, gün batmadan ilerle! 

Yara açsın kayalar ayaklarında, varsın,

Varsın omuz başların kamçılardan kızarsın,

Bu ağrılar duyurmaz sana yalnızlığını.

Kızıl dudaklarından bırakma ıslığını,

Ağzında şarkılıktan çıkmış iniltilerle

Dağ, taş deme, arkadaş, gün batmadan iler
..........
..........', 'Ağzında şarkılıktan çıkmış iniltilerle Dağ, taş deme, arkadaş, gün batmadan ilerle!  Yara açsın kayalar ayaklarında, varsın, Varsın omuz baş...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemeç', 'donemec-necip-fazil-kisakurek-bh2y6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gündü, hava ılık

                         Ve cadde kalabalık

Bir kadın sapıverdi önümden dönemece; 

Yalnız bir endam gördüm, arkasından, ipince.

Ve görmeden sevdiğim, işte bu kadın dedim,

                                 Çarpıldım sendeledim.

                                        Bir gündü mevsim bayat

                                        Ve esnemekte hayat.....

Dönemeçten bir tabut çıktı ve üç beş adam; 

Yalnız bir ahenk sezdim, çerçevede bir endam.

Ve tabutta, incecik, o kadın var, anladım; 

                                             Bir köşede ağladım.....', 'Bir gündü, hava ılık                          Ve cadde kalabalık Bir kadın sapıverdi önümden dönemece;  Yalnız bir endam gördüm, arkasından,...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/donemec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım Var', 'i-htiyacim-var-feramuz-gorel-fa4ut', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşlar birikti gözlerimde

Sızı çoğaldı dizlerimde

İslamı yaşasa kızlarımda

Benim Kurana ihtiyacım var

Kuran resul gözümde tüter

Bu alemde bunca yaşadım artık yeter

Kurana hasretlik ölümden beter

Benim Muhammede ihtiyacım var

Birileri olsa yanıma gelse

Buğlu gözlerimden kalbimi bilse

Kurandan birkaç ayet dese

Hayır duanıza ihtiyacım var

Hep bekledim ezan sesini

Yıllarca tuttum Hüseyn yasını

Ziyaret ettim Şah-ı Horasanı

Ehli beytin şefaatine ihtiyacım var

Yine hüzünlendim doldu gözlerim

İnsanlarda bulamadım doğru sözleri

Yavaş yavaş kapanıyor buğlu gözlerim

Resulullah şefaatine ihtiyacım var...', 'Yaşlar birikti gözlerimde Sızı çoğaldı dizlerimde İslamı yaşasa kızlarımda Benim Kurana ihtiyacım var Kuran resul gözümde tüter Bu alemde bu...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ihtiyacim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Söyle', 'selam-soyle-feramuz-gorel-snbpp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolun düşerse Iğdır iline

Ne olur benden de selam söyle

Kokusu burnumda tüter ilimin

Pamuğuna pancarına selam söyle

Gez dolaş bütün köyleri

Sana canını verir Meleklilin beyleri

Üç gün sürer salavatlı düğünleri

Salavat çeviren gençlerime selam söyle

Kavunu karpuzu narı

Unutulmaz kışı baharı

Gezen bilir bu diyarı

Bütün köylerime selam söyle

Feramuz’um döktüm kaleme

Merhem olsun toprağıma yarama

Üzümünü armudunu gelde yeme

Iğdır ovasına selam söyle', 'Yolun düşerse Iğdır iline Ne olur benden de selam söyle Kokusu burnumda tüter ilimin Pamuğuna pancarına selam söyle Gez dolaş bütün köyleri ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/selam-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-feramuz-gorel-7hxta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni düşünme git güle güle

İman olmayan yerde olurmuş hile

Zillete boyun eğmedi Zeynep bile

Haktan ayrılmayacağım baba

Saçlarımdan tutup sürükleseler

Zeynep gibi toprağa bürüseler

Hürüyenler yine hürüseler

Haktan ayrılmayacağım baba

Fıratın suyunu kurutsalar

Zindana atıp bedenimi çürütseler

Ruhum haktan ayrılmayacak

Sen hiç üzülme sakın baba

Bırak ahırlar onların olsun

İçine hayvanlar dolsun

Örtüm bana kefen olsun

Haktan ayrılmayacağım baba', 'Beni düşünme git güle güle İman olmayan yerde olurmuş hile Zillete boyun eğmedi Zeynep bile Haktan ayrılmayacağım baba Saçlarımdan tutup sür...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-feramuz-gorel-1b7k0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözün ela kaşın ela

Olmuşsun sen başıma bela

Sanki yurdumda bir lale

Gel sana gurban olum

Gözlerin ceylan kimin

Güzelsen gız anan kimin

Sende olasan menim kimin

Gel sene gurban olum

Gülüşün gız ne güzel

Bakışın gelbim ezer

Gözlerin kimi süzer

Gel sene gurban olum

Feramuzam yanmışam

Seni şirin sanmışam

Ot tutup vallah yanmışam

Gel sene gurban olum', 'Gözün ela kaşın ela Olmuşsun sen başıma bela Sanki yurdumda bir lale Gel sana gurban olum Gözlerin ceylan kimin Güzelsen gız anan kimin Send...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-feramuz-gorel-dh3yr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalın ayak başım açık

Kerpiç evim yıkık dökük

Yetimlik elinden boynum bükük

O günleri unutamam

Bir göz oda kapı kırık

Kapımız çalınmaz boynumuz bükük

Hep alırdık beyden buyruk

Aç yattığım günleri unutamam

Defter kalem yok ne yazım

Veresiye yazmaktan bıktı Kazım

Ölen babama kefen lazım

Borca aldığım kefeni unutamam

Hocaya verecek paramız yok

Dert ararsan bizde çok

Mezarı kapatacak odun yok

Komşuların verdiği tahtayı unutamam', 'Yalın ayak başım açık Kerpiç evim yıkık dökük Yetimlik elinden boynum bükük O günleri unutamam Bir göz oda kapı kırık Kapımız çalınmaz boynu...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılılk', 'ayrililk-feramuz-gorel-oncov', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık çok acı ölümden beter

Hislerime dokunur dur diyemiyorum artık yeter

Alem gülüp eğleniyor bu nasıl kader

Hasretlik beni etti derbeder

Ölüm kurtuluştur ayrılık yıkılış

Bu nasıl sevgi uzaktan bakış

Ben eriyorum için için

Ne zaman bitecek bu yakarış

Önce benim kollarımdaydın şimdi ellerin

İntizar ediyorum sana derin dedin

Hala boştur kalbimdeki yerin

Ayrılık yarası derindir çok derin

Bende insanım bende severim

Sana ne zaman yarim diğeceğim

Senin yüzünden tükendi malım servetim

Feramuzum gece gündüz seni ararım', 'Ayrılık çok acı ölümden beter Hislerime dokunur dur diyemiyorum artık yeter Alem gülüp eğleniyor bu nasıl kader Hasretlik beni etti derbeder...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrililk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakan Gözler', 'yakan-gozler-gokalp-burlukkara-ydrj2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçenlerde yine sendin ruyamda gezinen...

Değişmiştin, 

Sanki geçmişteki günahlarının izlerini yüklemiştin sırtına...

Ama birşey vardı ki sende tarifi mümkün olmayan

Ruhundadır herhalde diye düşündüm başta ama

Esasında şeytanın günaha davet edişini dahi

Kıskandıracak gözlerindi bu

Nice kor gönüleri alevlendiren

Nice mutlu aileleri yıkan o mutlu güzel

Ama bir okadar melun gözlerindi

Büyüsü nerede saklıydı

Kimin elindeydi...

Gönül yakıp gitmeyi seven sen

Şeytana ruhunu,

Bedenini ucuz içki sofralarında ciğersizlere,

Ama gözlerini ilahi mevlaya söz vermiş gibi dikiyordun.

Utandım, sıkıldım, bakamadım o gözlerine

Son bir kez daha

Bir nefes kadar kısa

Ama kabir azabı kadar uzun geldi bakışın

Ve ardından gidişin

Ve bu son olmayacaktı

Düşlerime tecavüz edişin

Bu son olmayacaktı

Ruhumu hançerleyişin', 'Geçenlerde yine sendin ruyamda gezinen... Değişmiştin,  Sanki geçmişteki günahlarının izlerini yüklemiştin sırtına... Ama birşey vardı ki se...', ARRAY['Türk Edebiyatı','Şiir','Gökalp Bürlükkara']::text[], 8.5, '{"poet":"Gökalp Bürlükkara","poet_slug":"gokalp-burlukkara","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yakan-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-harun-kesik-v8h2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yağdı o gece

Bambaşka duygularla boşaldı taa tepeden

Ben yine yatağımda şırıltılarla dolu o gecede

Yine aklıma geldi o çocukluk anıları bir kalemde

Ama geri gelmez akan yağmurla o gece

Mutluyum geçti kötü günler 

Mutsuzum bitti artık o güzel günler

Yağmur yağdı o gece

Bir kalemde atıp gitti sadece

Ben düşünüyordum o gece

Gökten indi rahmet yağmurla götürdü 

Kederi tasayı hüzünü

Ama geri gelmez akan yağmurla o gece', 'Yağmur yağdı o gece Bambaşka duygularla boşaldı taa tepeden Ben yine yatağımda şırıltılarla dolu o gecede Yine aklıma geldi o çocukluk anıla...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yagmur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Ağıtı', 'sairin-agiti-harun-kesik-ezgxl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şair ağlar akar mı yaşlar gözünden

Düşer mi boncuk boncuk hüzün

Gözlerinden sadece ağıt yağar 

Kaleminden bazen öğüt bazen keder

Geçmişten geliyor geleceğe gidiyor

Şairin kalemi mısralarda hedef bilgi 

Şair ağlar akar mı yaşlar gözünden 

Akmaz arkadaş o öğretir çirkini güzeli

Şair ağlar mı akar mı yaşlar gözünden 

Ağlar arkadaş bir ağlar ,

Öğretemediği yetiştiremediği zaman AĞLAR', 'Şair ağlar akar mı yaşlar gözünden Düşer mi boncuk boncuk hüzün Gözlerinden sadece ağıt yağar  Kaleminden bazen öğüt bazen keder Geçmişten g...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sairin-agiti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıkların Arkasından', 'isiklarin-arkasindan-nergiz-kartal-myjt0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yakın gecenin bütün ışıklarını yakın

hüzün çökmesin yeşil ovalara mavi sulara

söyleyin ayçiçekleri başın eğmesin 

aman vermesin gökyüzü yıldızlara

yakın yakın gecenin bütün ışıklarını

papatyalardan taçlar yapılsın 

küsmesin gelincikler düne yarına

gülsün bütün ağaçların tomurcukları gülsün

bu gece son kez benim için

güne dönüşşün

yakın yakın gecenin bütün ışıklarını

göreyim renk veren kelebekleri menekşeleri

göreyim seher vakti mis kokulu gülleri 

evet ben gülleride pek severim

yedi veren gülleri ile süsleyin ebedi mabedimi

                      

              22.mart.1995

                Kurucaşile', 'yakın gecenin bütün ışıklarını yakın hüzün çökmesin yeşil ovalara mavi sulara söyleyin ayçiçekleri başın eğmesin  aman vermesin gökyüzü yıld...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isiklarin-arkasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluktayım', 'bosluktayim-harun-kesik-mni74', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir boşluktayım yalnız başımayım

Hedefsiz bir şekilde düşüyorum yalnızlığa

Tutan yok kenardan köşeden düşüyorum yalnızlığa

Uçsuz bucaksız derin delik kuyulara 

Belki hiç çıkamam beni yer hasret 

Bir boşluktayım yalnız başımayım 

Çıkamadım kurtulamadım 

Bir boşluk hissediyorum kalbimin derinliklerinde

Dolduramıyorum o boşluğu açık yara gibi

Acıyor ama hissetmiyorum', 'Bir boşluktayım yalnız başımayım Hedefsiz bir şekilde düşüyorum yalnızlığa Tutan yok kenardan köşeden düşüyorum yalnızlığa Uçsuz bucaksız de...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bosluktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-umit-yasar-oguzcan-tdpdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölürsem şaşırma

Ölebilirim

Ölürsem aglama

Yine gelirim

Ölürsem seslenme

Uyuyacagım

Ölürsem üzülme

Yaşayacagım

Ölürsem bekleme

Geri dönemem

Ölürsem ölme

Sensiz edemem', 'Ölürsem şaşırma Ölebilirim Ölürsem aglama Yine gelirim Ölürsem seslenme Uyuyacagım Ölürsem üzülme Yaşayacagım Ölürsem bekleme Geri dönemem Ö...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiiristan', 'siiristan-umit-yasar-oguzcan-wbh50', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yer var orada ikimiz için

Orada, bildigin gibi şiiristanda

Evler Yunus''un evleri

Yollar Emrah''ın yolları

ve Hayyam''dan birer rubai gemiler limanda

Deniz bildigin gibi Orhan Veli''den kalma

Mevsimse Yahya Kemal''in sonbaharı

Nedim''dir seyreyledigin bir elde mey, bir elde gül

Çeşmeler Karacaoglan''ın

Daglar Köroglu''nun dagları

Tarancı''nın kuşları havada dönen

Kadınlar Haşim''in kadınları görüyormusun?

Yeter bir nabız gibi vurdugun bende

Bana bir şiir ver güzelliginden

Bütün şiirler senin olsun

Şiiristan sultanı, devletlu gönlüm emreylesin yeter ki

Güzelliginden nice ülkeler kurulur

Yoksan gece ve ölüm

Varsan el sürdügün herşey şiir

Ayak bastıgın her yer şiiristan olur.', 'Bir yer var orada ikimiz için Orada, bildigin gibi şiiristanda Evler Yunus''un evleri Yollar Emrah''ın yolları ve Hayyam''dan birer rubai gemil...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siiristan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlara Açılan Pencere', 'yarinlara-acilan-pencere-umit-yasar-oguzcan-jaxpj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden geldik, nerdeyiz biliyor musun

Yüzyılar öncesi mi seviştik seninle

İlk tanıştıgımızdan bu yana çaglar mi geçti

Nasıl şimdi bir yerlere gidiyoruz elele

Anımsıyorum gözlerini, Babilde belki

Belkisin dillere destan asma bahcelerinde

Belki de yitik bir Ege Uygarlıgının

O Akdeniz mavisi sonsuz gecelerinde

Sen! En yakın olan bana, kanım gibi

Beni her gün bir kez daha doguran kadınım

Gül behçem, ormanım, suyum, topragım, gögüm

Sen! Dünya kurulalı beri aradıgım

Yeni dogmuş bir çocuk kadar tenhayım seninle

Enginlerde kanat çırpan bir martı gibi hürüm

Durmadan bir agaç büyüyor sevgimizden

Ta sonsuzlara dek uzuyor ömrüm

Seninle çaglar yaşadık biz, dünde degil

Zamanın ölümsüzlükle birleştigi yerdeyiz

Su gibi avuçlarımızdan akıp gidiyor günler

Doruklarında kar eksilmeyen tepelerdeyiz

Seni andıkça bir ışık vuruyor yüzüme

Yosunların yeşilinden, dalgaların köpügünden

Denizler çekiliyor, daglar egiliyor ve yollar

Kısalıyor, yaşadıgımız aşkın büyüklügünden

Bu coşkun umutlar boşuna degil sevdigim

Boşuna degil solan yaprakların bir bir yeşermesi

Bak! Bütün aydınlıgıyla duruyor karşımızda

Bu günün yarınlara açılan penceresi.', 'Nerden geldik, nerdeyiz biliyor musun Yüzyılar öncesi mi seviştik seninle İlk tanıştıgımızdan bu yana çaglar mi geçti Nasıl şimdi bir yerler...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarinlara-acilan-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanan Gül', 'yanan-gul-umit-yasar-oguzcan-5chu8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne kadar saklasan özlediğin belli

Söndüremezsin içindeki yangını

Başlamışsa zamanların en güzeli

Artık susturamazsın dudaklarını

Anlatır özlemini bana derinden

Yanan alnınla, terleyen avuçların

Alevler taşarken gözbebeklerinden

Yakar degdigi yeri parmak uçların

Çok geç bu sevdadan dönebilmek icin

bak! şimdi seninle dopdolu aynalar

Bu özlemli halinle daha güzelsin

Benimde saçımdan tırnagıma kadar

Tutuşan, yanan bir şey var her yerimde

Sen şimdi alevden bir gülsün ellerimde.', 'Ne kadar saklasan özlediğin belli Söndüremezsin içindeki yangını Başlamışsa zamanların en güzeli Artık susturamazsın dudaklarını Anlatır özl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yanan-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-umit-yasar-oguzcan-9e2bx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangi cennetten geldim bu cehenneme

Ki her yokluk bendedir, her acı benim

Baltalar kıyasıya inmiş govdeme

Bak! Şu devrilen hayat agacı benim

Bir gün beni de unut her yalan gibi

Adımı sokaklara tükür kan gibi

Oysaki yaşadıkça bir çıban gibi

İçinde sızlayacak o sancı benim

Terkedilmiş eski bir şehircesine

Sensiz yaşıyor o can verircesine

Tutuşmuş özleminle erircesine

Bir zaman sevdigin bu yabancı benim', 'Hangi cennetten geldim bu cehenneme Ki her yokluk bendedir, her acı benim Baltalar kıyasıya inmiş govdeme Bak! Şu devrilen hayat agacı benim...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yabanci-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutların Bittiği Yerde', 'umutlarin-bittigi-yerde-umit-yasar-oguzcan-8nbyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir düş gibi başladı her şey, o sonsuz

Ve el degmemiş güzelliginde aşkın

Uzaklarda arayıp da buldugumuz

Belki de bizdik, sesiz ve dalgın

Her yer yeşile kesmişti yaprak yaprak

Büyülü sesizliginde ormanların

Elele, daglar ve denizler aşarak

Bir yere vardık, mutluluga en yakın

Öyle yükseldik, göge degdi başımız

Tüm mesafelerini aştık dünyanın

Öylesine hür ve öyle yapayalnız

Ve sonra bir yere geldik ki ıpıssız

Çaresizlik bir tek hançer gibi yalın

Saplandı bagrına bütün umutların', 'Bir düş gibi başladı her şey, o sonsuz Ve el degmemiş güzelliginde aşkın Uzaklarda arayıp da buldugumuz Belki de bizdik, sesiz ve dalgın Her...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umutlarin-bittigi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamamak', 'unutamamak-umit-yasar-oguzcan-rgycx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bilemezsin, paslı hançerdir yalnızlık

Gelir, en can alacak yerimden vurur

Sen bilemezsin, gecenin en uzak bir saatinde

Bir böcek nasıl girer beynime, kımıldar durur?

Sen bilemezsin, çaresizlik nasıl bogar insanı?

Yaşamak bir yerde nasıl çekilmez olur?

Tutunacak bir dal aramaktan, koşmaktan, özlemekten

El yorulur, ayak yorulur, yürek yorulur.

Sen bilemezsin bu türlüsünü ölümün

Bilemezsin, bir tek kibritin cılız aleviyle

Benzine bulanmış bir insan nasıl tutuşur?

Bu belki sevmektir bir yerde, belki unutamamak

Bu, kişinin kendi içinde eriyip, yok olmasıdır

Bilmesen de anlamaya çalış biraz, ne olur.', 'Sen bilemezsin, paslı hançerdir yalnızlık Gelir, en can alacak yerimden vurur Sen bilemezsin, gecenin en uzak bir saatinde Bir böcek nasıl g...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz Aşklar İçin', 'umitsiz-asklar-i-cin-umit-yasar-oguzcan-2p6ku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ümitsiz aşklar için yaratılmışım

Ayrılıklar için, sonsuz kederler için

Ne zaman ta derinden sevsem birini

Ezilmeli yeni açmış gülleri kalbimin

En güçlü zehir olmalı aşk dedigin

Alkol gibi damarlarıma yürümeli

Sarmalı her yanımı gece olunca

İçimde bir çıbansa  büyümeli

İnsan sevince her gün bir kez ölmeli

Her gün bir başka yerine saplanmalı o kursun

Yollara düşmeli, perişan deli divane

Erimeli potasında o garip var oluşun

Artık uzak bir anıdır huzur ve sukun

O büyük yangın başlamışsa yürekte

Bir gün gelir de bu çaresizligin

Aranır bütün tesellisi ölmekte

Oyerde sevilmek de yalan sevmekte

Nereye baksan dizboyu karanlık

Boşuna bir ışık arama göklerde

Her şeyinle aşkın içindesin artık

Böyle gitgide derinlere çeker o bataklık

Orada ölümsüz olur nice kara sevdalı

Sevmek, hiç sevilmeden; korkunç güzel

Aşk dedigin karşılıksız olmalı', 'Ben ümitsiz aşklar için yaratılmışım Ayrılıklar için, sonsuz kederler için Ne zaman ta derinden sevsem birini Ezilmeli yeni açmış gülleri ka...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umitsiz-asklar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sensizlik Ölmekse', 'ya-sensizlik-olmekse-umit-yasar-oguzcan-k2cq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar sen vardın ya ben böyle yok degildim

Düşünürdüm neyi mi? Hep seni odalarda

Kimdi bana benziyen baktıgım aynalarda

Senden başkası mıydı o sessiz bekledigim

Bir zamanlar sen vardın ya ben böyle degildim

Kim bilir aglamayö olup kendi kabrinde

Sensizligi bu türlü benim kadar kim bilir

Akşam karanlıgında herkes gider o gelir

En sevdigim çiçekler çürümüş ellerinde

Kim bilir aglamayı olup kendi kabrinde

Ya sensizlik ölmekse her gün bir baska türlü

Ya bir şey olmamaksa sen olmak o yerlerde

Yaşamak nerde hani yaşamak gücü nerde

Bilinmez sensiz kalan yaşıyor mu ölü mü

Ya sensizlik ölmekse her gün bir başka türlü.', 'Bir zamanlar sen vardın ya ben böyle yok degildim Düşünürdüm neyi mi? Hep seni odalarda Kimdi bana benziyen baktıgım aynalarda Senden başkas...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ya-sensizlik-olmekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Çünkü', 'seni-seviyorum-cunku-gokhan-bozdogan-w1ovo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni seviyorum çünkü

her günüm senin sesinle doğuyor,seninle sürüyor

gecem ise seninle son buluyor.

seni seviyorum çünkü

kilometrelerce uzakta olsan bile,

buluşma gününü özlemle beklemek hoşuma gidiyor.

seni seviyorum çünkü

yanımda olmasan bile,

yüreğinin benimle olduğunu biliyor

her an yanında olduğumu biliyorsun.

seni seviyorum çünkü

bu mesafelere ragmen

yaşanmamışı yaşatabiliyorsun,

duygularımda var olabiliyorsun.

seni seviyorum çünkü

sesinle dünyama bir anda girip,

sürprizlerinle beni kendine

tekrar tekrar aşık edebiliyorsun.

seni seviyorum çünkü

yüreğimin tam ortasında varolabiliyorsun.

beni hayallere götürebiliyor,

umutlarımı geleceğimi düşündürebiliyorsun.

şiir yazdırıp,şarkılarda hissettirebiliyorsun kendini.

seni seviyorum çünkü

ikimize dair bir yaşamı düşündürebiliyorsun,

mutluluğun,aşkın varlığına inandırabiliyorsun.

engellerin aşılacağını,

mücadelenin hırsını,

birlikteliğin tek yürek olmanın ve

güvenin aşamayacağının olmadığını gösteriyorsun.

seni seviyorum çünkü

sen hayatıma vazgeçilmez bir anlam katıyorsun.

seni seviyorum çünkü

sen benimle bende yaşıyor,

ben seninle sende varoluyorum.', 'seni seviyorum çünkü her günüm senin sesinle doğuyor,seninle sürüyor gecem ise seninle son buluyor. seni seviyorum çünkü kilometrelerce uzak...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/seni-seviyorum-cunku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batış', 'batis-sezai-karakoc-l6xye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneştir düşen turuncusunda menekşeler sunarım

Gece artık hiç dönülmeyecek yerlerdeki o sevgiliye 

Çocuklara kekik toplıyan o sevgiliye

Bir kekik uzatan çocuk anne deyince

Deniz dibinden çatı çeken

Çocuk üstüne arkadaş üstüne

Güneştir düşen yeşilinde bir yüz döner

Değişmiyen o gençliğiyle sevgili

Ölümden sonraki kurtulma gibi

Döner döner de gelir karşıma

Deniz dibinden cıkan ahtapot ölüleri

Eski utanmaları çeker su yüzüne

Güneştir kırmızı ve ben en çömezi bir rengin

Altın hatıralar hükümetinin

Bitmeyen sultanı o sevgiliye adanmış

Soy utanc soy anış soy sevgi

Gel artmaz azalmaz ey sevgi', 'Güneştir düşen turuncusunda menekşeler sunarım Gece artık hiç dönülmeyecek yerlerdeki o sevgiliye  Çocuklara kekik toplıyan o sevgiliye Bir ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/batis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kandan Elbise Giydim Hiç Değiştirsinler İstemezdim''', 'ben-kandan-elbise-giydim-hic-degistirsinler-i-stemezdim-sezai-karakoc-styy6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendinden birşeyler kattın

Güzelleştirdin ölümü de

Ellerinin içiyle aydınlattın

Ölüm ne demektir anladım

Yer değiştiren ben değildim

Farklılaşan sendin

Sendin bana gelen aynalarla

Sendin bana gelen sendin

Artık ölebilirdim 

Bütün İstanbul şahidim

Ben kandan elbiseler giydim

Bundan senin haberin var mı', 'Kendinden birşeyler kattın Güzelleştirdin ölümü de Ellerinin içiyle aydınlattın Ölüm ne demektir anladım Yer değiştiren ben değildim Farklıl...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-kandan-elbise-giydim-hic-degistirsinler-istemezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşmeler', 'cesmeler-sezai-karakoc-bo4r4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I.

Benim yalnızlığımdan 

Damıtılmış çeşmeler

Kurumuş unutulmuş

Ceşmelerin akışıyım 

İnsanlık içinde

Ay görmez onları onlar ayı görür

Aydan haberlidirler

Söylediklerinin çoğu

Ay hakkındadır

Aya dair

Ayın tarihine ait

Fındıklılı Mehmet Ağa 

Çeşmesi

Silahtar Tarihinin yazarı

Yenilmez karpuzlar 

Acı salatalıklar yıkamıştım suyunda

İçilmez

Bozuk suyunda

Gece yarısı

Ayışığında

Yaz ay ve ben

Silinmeye yüz tutmuş yazı

Ölümü hecelemiştik

Ortalığı dolduran sesinde

Ta... aşağılarda olan yatıra

Bir türkü söylüyordu

Ölüm ötesinde açmış 

Menekşeler kimliğinde

Ölüydü insanlar

Yalnız yaşıyordu o yatır

Ve o çeşme

Ben de 

Sıratı andıran bir çizgide

Soluyordum devrildim devrileceğimi

Hayatı ve ölümü birlikte

Aynı geçmezlik ve değişmezlikte

Aynı yenilik ve tazelikte

Ürpererek geçiyordu yarasalar

Uzaklardan

Beyoğlu''nu bir telgraf gibi

İleterek birbirine', 'I. Benim yalnızlığımdan  Damıtılmış çeşmeler Kurumuş unutulmuş Ceşmelerin akışıyım  İnsanlık içinde Ay görmez onları onlar ayı görür Aydan h...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cesmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Kentini Yaktım', 'denizin-kentini-yaktim-sezai-karakoc-q549a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin kentini yaktım

Vızıldayıp duran kafamın ortasında

Denizin kentini yaktım

Hurma şırıltılarıyla

Denizin kentini yaktım

Beni çocukluğumdan koparan

Denizin kentini yaktım

Bir kent kadın kabuklarından

Denizin kentini yaktım

Miras kalmış bir alevle

Denizin kentini yaktım

Veli ağaçlarla kalbi atan mermerle

Tanrıyı anarak kalbi atan

Cami sütunları boğdu

Sararmış gözyaşlarıyla

Kararmış denizin kentini

İstanbul ey sevgili şehir

Dön dön karadan gelen sesime

Son veren zaman yatırında 

Denizden getirilen biçimine', 'Denizin kentini yaktım Vızıldayıp duran kafamın ortasında Denizin kentini yaktım Hurma şırıltılarıyla Denizin kentini yaktım Beni çocukluğum...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/denizin-kentini-yaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-sezai-karakoc-e72or', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Leyla''nin doğumu için Mecnun''un sonradan söylediği)

I.

Çiğ düştü göklerden

Ve bir bahar günü doğdun sen

Güvercinler geçti menekşelerden

Ve bir bahar günü doğdun sen

Kendi kendine ayna olan nergislerden

Leylakların gün doğuşu ürperişinden

Zambakların kıyı kıyı bakışından

Geldin sen

Ve rüzgarlar karları süpürdüğünde

Ve insanı çıldırtan kuş sesleri işitildiğinde

Birdenbire aydınlandı annenin yüzü

Ve bir bahar günü doğdun sen

İlkin horozların gözüne göründün

Dünyaya haber verdiler ötelerden

Baban yeni dönmüştü eve ıraklardan

Birden aydınlandı annenin yüzü

Ve bir bahar günü doğdun sen

Marta bakan biliyordu geleceğini

Nisana bakan görüyordu alaca renklerini

Kızıl ve yeşil seherini

Mayısa bakan buldu seni

Ve bir bahar günü doğdun sen

Sana Leyla dedim Suna dedim şiirlerde şarkılarda

Gerçek adın bir fısıltı gibi kaldı ağızlarda dudaklarda

Çatlar yüreğim bir nar gibi o sırrı anar da

Avunurum doğumundan gelen muştulu armağanlarla

Melekler gökten geldi armağanlarla

Ve bir bahar günü doğdun sen

Bir bahar günü doğdun sen

Baharın ta kendisi oldun sen

Şimdi her baharda doğan çocuklarla

Sen en aşılmaz boya tenlerinde saçlarında

Sen görünür görünmez ufuklarda

Karlar erir erir kaçar kaçar da

Gökler yağmur biçiminde güler ağlar ağlar da

Güneş öğünerek yansır yansır da sularda

Gelirsin her baharda

Bir diriliş gibi ölü dünyaya

Ölüler gölgenden ateş ala ala

Ekilip biçilip yankı yapa yapa

Yaz sıcaklığından arta arta

Birer birer çıktılar gönlümüzün aynasına tarlasına

Ki bir bahar günü doğdun sen

Güller dönüştüler yatak çarşaflarına

Leylaklar yaklaştılar korka korka

Nergisler benliğimizin ortasından baka

Gelip fon oldular insanın

Bir kere daha

Sende yeniden yaratılışına

Bir bahar hali yaratışına

Bir bahar günü doğdun sen

Baharın ta kendisi oldun sen

II.

Sonbahar benim ölümüm kırmızı kırmızı yanışım karaağaçlarda

Senin ak doğumunu daha çok ortaya koymak için

Toplayıp gelişim güzü bütün sarılarımla loşluklarımla

Çürüyen solan evrenin karşı koyuşu

Senin baharda doğusunun anısına

Ah o ne sıtmadır güneşteki sıtma baharda

Her an senin doğumun yaşamaktan gelen

Ve güzün güneşte bir kuruyuş bir dağılma

Benim ölümümden gelen haykırış ve ağlayışlarla

Bir ömür boyu oldum salt ölüm kemiği

Parlamak için senin doğumundan gelen fosforlarla

Eve girmekte geç kalan çocuklar görecektir geceleri

Aşk baharının sessiz direnişini

yanıp duran ışıklarda

Yaz güneşi biriktirdi biriktirdi

Sonbahar yapraklarda delirdi

Kış derin çizgileriyle devrildi

Bahar gül tanklarıyla çiçek çağlayanlarıyla belirdi

Ve bir bahar günü doğdun sen', '(Leyla''nin doğumu için Mecnun''un sonradan söylediği) I. Çiğ düştü göklerden Ve bir bahar günü doğdun sen Güvercinler geçti menekşelerden Ve ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/dogum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktorun Karşısında', 'doktorun-karsisinda-sezai-karakoc-qdvpj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doktor bir kavisim var bir kavisim var

Geçen günden beri bir kavisim var

Ondan bir akıntı mıdır yarasalar

Bir kavis önünde linç mi demek kurtarılacak bir kent ki

Yeşil bir toprak selameti

Bir kabrin bir cihanlık cömertliği cesareti

Kitaplardan kitaplara

Atılarak erişilmiş bir saygı saati

Bir kırağı yaprağında son direniş çiçekleri

Ölen bir hristiyanda bir yahudi zambak sesi

Çarşıların boşluğunda ben bir eski çeşme yası

Affedersiniz doktor siz süryani misiniz

(Hayır ben süryani değilim ama arkadaşım süryani) 

Ben çok İncil gördüm çıkmamış boyaları

Biraz daha gerilmiş yazıldığı ceylan derisi

Ama silinmiş ölüme karşı dayatan

Lazarı ayağa kaldıran muştu defnesi

Bütün defnelerı kırdık bir güveç neşesi

Fırınlar açıldı narlar kurudu

Kuyu deştik sular çekildi

Doğ ey kuyruklu yıldızı ülker kümesi

Bilirim en çorak toprağın bile var bir kehaneti

Bir kerameti

Bir gelecek zaman ticareti

Demet demet muştuları

Demet demet nimetleri

Doktor siz süryani misiniz

Yani eski bir süryani

(Hayır ben süryani değilim ama arkadaşım süryani) 

Bilirim bilirim incilden yola çıktınız

Ama yolu çabuk şaşırdınız

İncilden kendinize bir şeyler katacağınıza

Kendinizden incile çok şeyler kattınız

Sevdiniz öyle sevdiniz ki sevdiğinizi tutup mermere işlediniz

Ama sonra tutup mermere taptınız

Mermeri kadeh kadeh

Bir alacakaranlık gibi içtiniz

Sonra kustunuz mermeri

Çağlarca kustunuz mermeri

Ey mermer kusan ırk

Ey oruçsuz tiyatro

Acıkmış iftarsız acıkmışlar

Güneşten başka ne bulmuşsa yemiş olanlar

Doğuya hücum demek doğuya hücum var

İşte size bir kent ki

Yanlış yanan bir linç ampulünden

Size eşsiz bir şölen var

Kemiklerimin ışıklarından

İyi sanat doğrusu misyonerlik

Doktorluk gibi doktor

(Hayır ben süryani değilim ama bir arkadaşım var) 

Siz Çin diyorsunuz anlıyorum

Bir pirinç hastalığı falan

Geçiyorsunuz da bengisulardan

Bir hızır hızarından

Bir tabut pınarından

Gözümün hastalığından

Nasıl ki Meryem de bir çocuk sezmişti Cebrail sularından

Nasıl ki yeşil sancaklar inmişti bir gün Diyarbekir surlarından

Kurtarıyordunuz beni

Bana bir gemi gibi yaklaşan

Üsküdar akşamlarından

Fatih camii gibi aydınlıktınız

Bir fakir ölüsü kadar sessiz ve sade

Sağımda kırgın solumda çılgın

Önümde Yakup Yusuf ve İshaktınız

Arkada kaynak sular kadar berraktınız

Dün akşam üzeri güneşi siz batırdınız

Başkası değil doktor güneşi siz batırdınız

Ama inandım ki doktorsunuz değilsiniz süryani

Doktorsunuz doktordan başka bir şey değilsiniz yani', 'Doktor bir kavisim var bir kavisim var Geçen günden beri bir kavisim var Ondan bir akıntı mıdır yarasalar Bir kavis önünde linç mi demek kur...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/doktorun-karsisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci Dakikaları', 'i-nci-dakikalari-sezai-karakoc-1fj9h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bana yeni yılsın her dakika

Her dakika bir yaşıma daha giriyorum

Sen benim üstüne titrediğim güzel ve yeni

Saatim kadar saadetimin gözbebeği zamansın

Ben bin parçaya bölündüm her parçasında 

Her parçasındayım kırkayak sesli boğuk arkadaşlığın

Çalkantısız Üniversitenin yalnızlığın ve ağlamanın

Erkek ağlar mı diyeceksin

Hayberin kapısı ağlar mı erkek ağlar mı

Ben yel gibi erkekler ağlar diyorum

Bir dakika ağlar yılbaşı dakikasında

Daha gözlerimin gerçek yaşları belirmeden

Ağlamak diye bir şey yoktur diye bir şey

Yüzme bilmeyen bir uyurgezer yüzer ya

Çürük ve havada asılı tahtalar üstünde 

Hafif kedi ayaklarıyla yürür gerçekten yürür ya

Sen benim ağlamamı erkeklığıme

Uyanan ölmeyen yenilenen

Azgın kışlar içinde keskin baharlar bulan

Seni bulan yeniden bulan tekrar tekrar bulan erkekliğime say

Bütün bir yıl bütün bir yaşama boyu

Gizli heybelere binbir gece eşyası doldurduğuma say

Ben otomobilleri böylesine yankısız sağır komam

Öyle bir isyan şiiri var ki ben onu yakalayacağım

Bu yunan şehrinin düzenini öper ve yalvarırım

Şehrin ölümünü yanlış anlama

Gözleri kör oldu doğrudur ama o kadar

Ve şehrin gözlerini geri verme dakikalarıdır bu yılgın çanlar

Senin odan günışığı en güzel müzik bana

Farklılıklar odası

Giden tren buharları içinde örümcek ağı

Sen güzel örümcek ağı yaşamakla yaşamamak

Doğduğumuz şüpheyle öldüğümüz şüphe arasına gerilmiş

Garip bulut farklı müzik güzel örümcek ağı

Ben bir yabancı buğunun kokusunu alıyorum

Bu kokuyu alıyorsam onulmaz kıskançlık yaramdandır

Benim garipliğime bakma benim kıskançlığıma bakma benim

İncilerin ilk gerçek ve yeni yorumunu bulur gibi oluyorum

Bu inciler denizlerin en karanlık noktalarında bile yoktur

Benim ak ve kara kayalar içinde bulduğum inciler

Bu inciler sen olmasan bende bile yoktur

Oldukları yerde bile', 'Sen bana yeni yılsın her dakika Her dakika bir yaşıma daha giriyorum Sen benim üstüne titrediğim güzel ve yeni Saatim kadar saadetimin gözbe...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/inci-dakikalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşaret', 'i-saret-sezai-karakoc-2k5zu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman yandi elin

Ne zaman yakti ellerini hatiram

Ne zaman bir yuzuk gibi takti hatiram

Bu gizli ve aci isareti, gelin', 'Ne zaman yandi elin Ne zaman yakti ellerini hatiram Ne zaman bir yuzuk gibi takti hatiram Bu gizli ve aci isareti, gelin...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/isaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Çarşı', 'kapali-carsi-sezai-karakoc-uiozx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendi yastıklarına gölge salmasın 

Çocuklarının öpüşleri onlara anlat 

Onlara anlat yağmur karşılıklı yağar 

Ruhların içindeki müzikle karşılıklı 

Kapalı çarşı içinde bir sigara 

Bir keman kılıfı senin saçlarına sürünen yağ 

Onlara anlat kadınların gözlerinin içinden geçer 

Kapalı Çarşı ve Kapalı Çarşı’yı götüren saat 

Bir inci gerdanlık dumanları içinde kapkara 

Anlamağa başladığı ağır ve çekilmez kelimeler içinde dağ 

Senin resmin ince gerdanlığın siyah parlaklığı içinde ışıklı 

Işıklı ışıksız yandan ve önden ışıksız arkadan ve içten ışıklı 

Onlara anlat ki insan kelimelerden ve şiirden yaratılmadı 

Tüyler içinde gelen yeni dünya 

Bir sandalye kadar hür olduğu gün 

Sen cuma gününün hürriyet kadar kutsal olduğunu onlara anlat 

Benim aynamı küçültüp büyülten onlar 

Benim aynamı aynalıktan çıkaran 

Kapalı çarşılar içinde fikre ve gerçeğe 

Neler neler etti anlarsın onlar 

Şemsiyeler gibi 

Felaketlerin en şakacısına açılıveren onlar 

Kendi yastıklarına düşmesin 

Dostlarının kadınları üstündeki gölgesi onlara anlat 

Kapalı çarşılar içinde 

Aslanların ağaç kabuğuna yazdığı şiir 

Kapalı çarşı içerisinde 

Açık ve keskin yumuşak ve güzel Kur''an sesleri 

Kapalı çarşı içinde kapalı rüya çarşıları 

Kapalı çarşı içinde öfke ve af çarşıları 

Kapalı Çarşı’ya gittiğin zaman 

Bir yangın sonrasının gazetelerini okudun 

Bir gazete uzun ve kul olmuş bir gazeteydi Kapalı Çarşı 

Mavi gözlü bir gazete 

Kapalı Çarşı içinde bulutların en senin olanı 

Sen bana kapalı çarşı 

Şüphesiz o kadar satılan ve alınanlar var ki 

Şüphesiz bir harita kırığı 

Bir yapma deniz parçasıyla kapalı Kapalı Çarşı 

Sen kapalı çarşılar üstüne yağmur yağanı 

Yağmurun iyi ve doğru yağmadığını 

onlara anlat', 'Kendi yastıklarına gölge salmasın  Çocuklarının öpüşleri onlara anlat  Onlara anlat yağmur karşılıklı yağar  Ruhların içindeki müzikle karşı...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kapali-carsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşe', 'kose-sezai-karakoc-91f7l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

Saçlarını kimler için bölük bölük yapmışsın

Saçlarını ruhumun evliyalarınca örülen

Tarif edilmez güllerin yankısı gözlerin

Gözlerin kaç kişinin gözlerinde gezinir

Sen kaç köşeli yıldızsın

Fabrika dumanlarında resmin

Kirli ve temiz haritaları doldurmuşsun

Hâtırasız ve geleceksiz bir iç deniz gibi

Aşka veda etmiş topraklarda durmuşsun

Benim geçmiş zaman içinde yan gelip yattığıma bakma

Ben geleceğin kara gözlü zalimlerindenim

Bir tek köşen bile ayrılmamışken bana

Var olan ve olacak olan bütün köşelerinin sahibi benim

Ben geleceğin kara gözlü zalimlerindenim

Sen kaç köşeli yıldızsın

(1954, Nisan) 

2.

Evlerinin içi ayna döşeli

Ayna hâtıra gözler ve sevmek

Benim aşkım bin bir köşeli ah bin bir köşeli

Bir köşe gidince bin köşe yeniden gelecek

Ayna hâtıra gözler ve sevmek

Evlerinin içi kabartma bahar

Köşelerinde keklik gibi bakıp duran saksılar

Halıları öpe öpe nakış yapar nakış gibi ayaklar

Siz söyleyin insan seve seve ölmez ne yapar

Köşelerde keklik gibi bakıp duran saksılar

Evlerinin içi yeni güllerden

Görülmemiş güneşleri görülmemiş gözlerine getiren

Sağ köşedeki entari sol köşedeki şapka

Beni katil suların ortasına bıraka

Katil sular güneşi gözlerinden götüren

Evlerinin içi gurur döşeli

Benim aşkım bin bir köşeli ah bin bir köşeli

(1954, Mayıs) 

3.

Sen geldin ve benim deli köşemde durdun

Bulutlar geldi ve üstünde durdu

Merhametin ta kendisiydi gözlerin

Merhamet saçlarını ıslatan sessiz bir yağmurdu

Bulutlar geldi altında durduk

Konuştun güneşi hatırlıyordum

Gariptin yepyeni bir sesin vardı

Bu ses öyle benim öyle yabancı

Bu ses saçlarımı ıslatan sessiz bir kardı

Dişlerin öpülen çocuk yüzleri

Güneşe açılan küçük aynalar

Sert içkiler keskin kokular dişlerin

İçinden geçilen küçük aynalar

Ve güldün rengârenk yağmurlar yağdı

İnsanı ağlatan yağmurlar yağdı

Yaralı bir ceylan gözleri kadar sıcak

Yaralı bir ceylan kalbi gibi içli bir sesin vardı

Sen geldin benim deli köşemde durdun

Bulutlar geldi üstünde durdu

Merhametin ta kendisiydi gözlerin

(1954, Mayıs) 

4.

Taşların ortasında Leylâ''nın gözleri

Leylâ köşe köşe göz göz şiirin ortasında

Ben Leylâ''yı bulduğumdan yahut kaybettiğimden beri

Leylâ ya o adamın bardağında ya o dağın ortasında

Ben Leylâ gibi güneş doğarken uyanamam

Şehir gece gündüz benim içime uyur

Leylâ''yı götürüp Londra’nın ortasında bıraksam

Bir bülbül gibi yaşamasını değiştirmez çocuktur

Leylâ diyorsam kesik yanaklarıyla Leylâ

Üç köşeli dünyasıyla

Okuyla yayıyla yaylasıyla acımasıyla

Leylâ diyorsam şu bizim gerçek Leylâ

Biz seni işte böyle seviyoruz Leylâ

O gitti bize ağlamak kaldı kala kala

(1954, Aralık) 

5.

Beni yeraltı sularına karşı iyi savun

Tırnağını taşa sürten yitik keçilere karşı

Bu çeşmenin üç köşesinden hangisinden su içecek

Senin bahtsız ve mesut Eyyub''un

Atların en güzel biçimini sessizce kalbime indiriyor

İçimde İstanbul çalkanırken bozbulanık çeşme

Bir dans için can vermeğe hazır bekliyorum

Sen orda gelirayak kuklalara insan gibi konuşmasını öğretme

Su akıyor birikiyor kan lekeleri

Kurtulsam diyorum bir eser buna engel

Öyle büyüyor öyle çoğalıyorsun

İstanbul kalmıyor

Hangi köşesinde huzur o köşesinde sen

Hangi köşesinde yeni çağlara uygun odalar

Ben bölünmez bir şairsem

Sen bölünmez bir anne

Bir çeşme

(1956, Haziran)', '1. Saçlarını kimler için bölük bölük yapmışsın Saçlarını ruhumun evliyalarınca örülen Tarif edilmez güllerin yankısı gözlerin Gözlerin kaç k...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/kose-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hayatta En Çok Babamı Sevdim', 'ben-hayatta-en-cok-babami-sevdim-can-yucel-hxs9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatta ben en çok babamı sevdim

Karaçalılar gibi yardan bitme bir çocuk

Çarpık bacaklarıyla -ha düştü, ha düşecek-

Nasıl koşarsa ardından bir devin 

O çapkın babamı ben öyle sevdim

Bilmezdi ki oturduğumuz semti

Geldi mi de gidici-hep, hep acele işi! -

Çağın en güzel gözlü maarif müfettişi

Atlastan bakardım nereye gitti

Öyle öyle ezberledim gurbeti

Sevinçten uçardım hasta oldum mu

40''ı geçerse ateş, çağrırlar İstanbul''a

Bir helalleşmek ister elbet, diğ''mi, oğluyla! 

Tifoyken başardım bu aşk oyununu

Ohh dedim, göğsüne gömdüm burnumu

En son teftişine çıkana değin

Koştururken ardından o uçmaktaki devin

Daha başka tür aşklar, geniş sevdalar için

Açıldı nefesim, fikrim, canevim

Hayatta ben en çok babamı sevdim.', 'Hayatta ben en çok babamı sevdim Karaçalılar gibi yardan bitme bir çocuk Çarpık bacaklarıyla -ha düştü, ha düşecek- Nasıl koşarsa ardından b...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-hayatta-en-cok-babami-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perili Şiir', 'perili-siir-sezai-karakoc-jmgfl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Leyla''nın doğumunda bir gök yaratığının söylediği)

Bir peri miydi bir peri miydi

Sevgilim bir peri miydi

Diriliş dedim diriliş dedi

Kav dedim kav dedi

Gözleri yumulu bir peri miydi

Gözleri yumulu bir peri miydi

Bir uyurgezer gibi

Bir uyurgezer gibi

Çeşmelerin yankısı mıydı

Çeşmelerin yankısı mıydı

Aldı bıraktı beni

Aldı bıraktı beni

Baharın gözleri miydi

Baharın gözleri miydi

Kırlardan bana baktı

Kırlardan bana baktı

Işığın kardeşi miydi

Işığın kardeşi miydi

Kirpiklerimi gördü

Kirpiklerimi gördü

Ruhumun şebnemi miydi

Ruhumun şebnemi miydi

Gözyaşlarıma yağdı 

Gözyaşlarıma yağdı 

Öldüğümü bildi

Öldüğümü bildi

Dirildiğimi bildi

Dirildiğimi bildi

Bir peri miydi bir peri miydi

Sevgilim bir peri miydi

Diriliş dedim diriliş dedi

Kav dedim kav dedi', '(Leyla''nın doğumunda bir gök yaratığının söylediği) Bir peri miydi bir peri miydi Sevgilim bir peri miydi Diriliş dedim diriliş dedi Kav ded...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/perili-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ping-pong Masası', 'ping-pong-masasi-sezai-karakoc-ytr2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...............................

Beyaz iplik sert iplik ve tak tak

Yuvarlak top küçük top ve tak tak

Ping-pong masası varla yok arası

Ben ellerim kesik varla yok arası

...... Öpüçüğüne eyvallah ve tak tak

Beraber sinemaya ... evet ... ve tak tak

Ping-pong masası varla yok arası

Öküzün gözü veya dananın kuyruğu

Kadifekale veya Sen nehri

Ha Sezai ha ping-pong masası

Ha ping-pong masası ha boş tüfek

Bir el işareti eyvallah ve tak tak

Gözlerin ne kadar güzel ne kadar iyi

Ne kadar güzel ne kadar sıcak

Tak tak tak tak tak tak tak', '............................... Beyaz iplik sert iplik ve tak tak Yuvarlak top küçük top ve tak tak Ping-pong masası varla yok arası Ben ell...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ping-pong-masasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Monna Rosa -III- Pişmanlık ve Çileler', 'monna-rosa-iii-pismanlik-ve-cileler-sezai-karakoc-im39h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar eser, yağmur yağar, tilkiler üşür; 

Bir odun parçası aydınlatır ocağı.

Anne ateşin önünde perişan,

Anne ateşin içinde hür...

Rüzgar eser, yağmur yağar, tilkiler üşür.

Yağmurlar sırtıyla sırtımın arasındadır; 

Şarkılar dudaklarıyla dudaklarımın.

Bin parçaya böldü beni bir divane sır,

Sesi geliyor sesi günahkar çocukların; 

Şarkılar dudaklarıyla dudaklarımın arasındadır.

Gönüller yanarak kavuşacaktı; 

Yüzdeki ıstırap, çile ocağı,

Onun bu ocakta yanan toprağı,

Bir gece rüyamda avuçlarımı yaktı,

Gönüller yanarak kavuşacaktı.

Benim gözlerim yeşildir, onun gözleri kara; 

Ben günah kadar beyazım, o tövbe kadar kara.

Annenin başı elleri arasında,

Parmağında aydınlık günlerden kalma yüzük.

Bir fotoğraf asılıdır duvarda:

Aynaya, geceye, maziye dönük,

Annenin başı elleri arasında,

Bir tüfeğin burnu havadadır,

Ateş almak üzredir, mermisiz.

Ben bir küçük kızım, ben bir deli kızım,

Siz beni ne anlarsınız siz! 

Bir tüfek ateş almak üzredir, mermisiz...

Bir saman çöpüne tutunmuş kızların

Eteğini ben çektim.

NEyleyim göğsümü kara dağın sert rüzgarı doldurmuş,

Annemden ilk sütü Gülce''de içtim.

Ankara''ya, çatal dağa biz zindandan gün vurmuş:

Az kalsın yerine ben ölecektim

Bir saman çöpüne tutunmuş kızların...

Kediler halıları parçalıyor,

Kırmızı bir ışık düşüyor yere.

Annenin dizinde derman yok,

Annenin kafası iki parçadır.

Hükmedemiyor insan ruhuna ateş,

Rüzgar hükmedemiyor incecik perdelere; 

Kediler halıları parçalıyor.

Ateşte sarı gül açan saksılar,

Kızarmış bir ekmek gibi duruyor; 

Kulağıma garip sesler geliyor.

Kuş yumurtasından çıkan insanlar

Ahırda bir ata eğer vuruyor,

Kulağıma garip sesler geliyor.

Ben bir şarkı, ben bir tüyüm; 

Ben Meryemin yanağındaki tüyüm.

Beni bir azizin nefesi uçurur,

Kalbimde Allahın elleri durur.

Cici ayaklarım iplikle bağlı,

Ben onun sılası, kendimin gurbetiyim; 

Ben bir azizin hasreti,

Ben Meryem''in yanağındaki tüyüm.

Benim gözlerim yeşildir, evet evet, onun gözleri kara; 

Ben günah kadar beyazım, o tövbe kadar kara...

Ocak sönüyor, ateş kül oluyor.

Annenin saçları beyaz,

Anne saçlarını yoluyor.

Ateşin içinde gül açar, servi büyür, ardıç büyür, çocuk büyür; 

Ocak sönüyor, ateş kül oluyor,

Anne ruhunda ruhuma eğiliyor.

Yaralı kuş kanadını ısıtan

Bir güneş toprağı yarıp çıkacak.

Kadınlar sansa da yaşadığını,

Şarkısız kaldıkça yaşamayacak.

Kadınları şarkılar, geceler aydınlatır.

Kadınları şarkılar, akrepler aydınlatır.

Kadınları şarkılar, zehirler aydınlatır...

Artık ben gideceğim, ata eğer vuruyorlar.

Hatıralarımı birer birer yakacağım.

Entarimi parça parça edip

Zehirli kirpilere bırakacağım.

Beyaz bir kayanın üstüne çıkıp

Göğsüme siyah bir gül takacağım.

Batan güne doğru kurşunlar sıkıp

Kendimi boşluğa bırakacağım.

Ayaklarımın altından geçiyor bir deniz...

Ben bir küçük kızım, ben bir deli kızım,

Siz beni ne anlarsınız siz! 

Artık ben gideceğim atım kişniyor; 

Bir bebek mum istiyor, bir ölü şarkı istiyor,

Ayaklarımın altından geçiyor bir deniz, bir deniz; 

Beni onun gözleri çağırıyor, duramam duramam.

Benim gözlerim yeşildir, ah, onun gözleri kara; 

Ben günah kadar beyazım, o tövbe kadar kara...

1952, Güz', 'Rüzgar eser, yağmur yağar, tilkiler üşür;  Bir odun parçası aydınlatır ocağı. Anne ateşin önünde perişan, Anne ateşin içinde hür... Rüzgar e...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/monna-rosa-iii-pismanlik-ve-cileler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabun Yaşı', 'sabun-yasi-sezai-karakoc-8vc51', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Kadın azaltır çocukları için

Kullanmasını yabancıları genç gördükçe

Adam konuşurken eli kaybolur kızlarla

Neden getirmeyi unutmasın

Nişanlı sabun demesini

Bilmeyenlere denir

Ben yaşarken kirli 

Ne kirli adamlar vardı

Yıkadılar sonra anladım

Ölü olduğumu

II.

Yıkadılar sonra anladık ölü olduğunu

Alıp götürdük gelin gibi öğleyin

Kesip durduk geyikleri

Kuşları balıkları eski çiçekleri

Nişanlı ölü nedir

Bilmeyenlere denir

Dalgın bir vaktinizde

Bozmayasınız diye geleneği

Taşlara bağladığımız

Siz yunmuş ölüleri

Ne aşkı ne neşesiyle

Dünya

Onmakta bizi

Gelin gömün bari', 'I. Kadın azaltır çocukları için Kullanmasını yabancıları genç gördükçe Adam konuşurken eli kaybolur kızlarla Neden getirmeyi unutmasın Nişan...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sabun-yasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahdamar', 'sahdamar-sezai-karakoc-ywsfq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz hürsünüz; siz şartsız ve kayıtsızsınız 

Bir balığın, bir siyah, bir kara balığın 

İncecik kılçığı üzerine yemin edersiniz; 

(K)  harfi üzerine yemin edersiniz. 

Rakı içen kadınların, çiçek yiyen kızların 

İyilikleri, günahları ve çeyizleri üzerine yemin edersiniz. 

İstakozların, kırmızı ve mavi istakozların 

Bir mavzerlik peygamberlikleri üzerine, 

Küçük ve büyük, acılı ve acısız 

Yeminler yeminler yeminler edersiniz. 

Siz siz üzre yeminler edersiniz. 

Biz hayret eder, kuvvet eder, dudağımızı bükeriz; 

Dudağımızı kör makaslarla dilim dilim ederiz 

İki tane elimiz var deriz; 

Bin tane elimiz olsaydı 

Bini birbirinin aynı olurdu deriz. 

999 elimiz kağıt gibi yansın, 

Bir elimiz güneş gibi dursun.. 

Biz elbette dudak büker, hayret ederiz. 

Biz inkar eder, inkarı severiz; 

Bayram hediyenizi iade ederiz 

Biz mahcup ve onurlu çocuklarız 

Başımızı kaldırıp bir bakmayız 

Siz rüyalarınızda yaşayıp durursunuz 

Siz güvercinleri gözlerinden vurursunuz 

Siz ekmeğin hamurunu, aşkın hamurunu samandan yoğurursunuz 

Siz rüyalarınızda yaşayıp durursunuz 

Toprağı zindana koyduk biz 

Üzerine yedi kilit vurduk biz 

Kaç gelinin alnında kaç yumurta kırdık biz 

Varsın yarın takılsın benim çene kemiğim 

Bir köpeğin ön dişlerine 

Ve Fahriye''nin kürek kemiği tam ortasından kırılsın 

Biz inkar eder, şah inkarlar severiz. 

Kafamızı kaldırıp bir bakmayız 

........................................... 

Ruhumuzun içinde kar yağar 

Anamızdan doğduğumuz geceden beri 

Heybemizi emektar makinelere yükleriz 

Fikirlerimizi tifil vinçlere 

İri buğday tanelerinin trenleri yürüttügünü bilmeyiz 

Biz yangında koşuyu kaybeden atlarız 

Biz kirli ve temiz çamaşırları 

Aynı zaman aynı minval üzere katlarız 

Biz koşu bittikten sonra da koşan atlarız 

Siz kalbe hançer gibi giren 

Siz kalpten ağaç gibi çıkan 

Siz bize şahdamarımızdan yakın 

Siz yüzükler içindeki kan 

Siz inançların sedef kabuğunu 

Ebabil kuşlarının gagalarıyla kıran 

Bununla beraber üzülmediğinizi biliyoruz 

Gün gelecek toprağın altına uzanacağız 

Her gece saat beş sularında sizi 

Toplardamarlarımızın içinde bekliyeceğiz', 'Siz hürsünüz; siz şartsız ve kayıtsızsınız  Bir balığın, bir siyah, bir kara balığın  İncecik kılçığı üzerine yemin edersiniz;  (K)  harfi ü...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/sahdamar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samanyolunda Veba', 'samanyolunda-veba-sezai-karakoc-y32di', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önceden bilen oluş şartlarını çocuklarının

Elleriyle değen koklayan hazırlayan adeta

Sebebine ermeden erişmeden

Korkan ilerdeki korkularla

Noldu zarif latif anneler noldular

Nerde çocuklar gece yarılarından sonra

Çıkıp samanyoluna bakan

Bakarak çocukluğu uzatmaya çalışan

İşleri güneşin doğuşunu yayınlamak

Bütün o çocuklar nerdeler

Kalan ne

Kızların kollarının arasından gözlenen

Samanyollarından

Bakısları benekleyen yalnız ölüm

Ölüm geçti canlı ehram ölüm geçti

O taklar geçip gitti insan üstüne kurulu

Ve bağbozumları bizden bozulan

Artık kendimize bile o kadar yakın değiliz

Gece yarıları samanyolu yok

Gün doğmuş doğmamış

Bütün elmalar çürüdü

Çocukluğumuzun dürbünleri içinden

Geçen siyah halkalı kutsal şehirlerden

Birini bulamadım gezdim bütün karaları

Aşk siyahın beyazdan ayrıldığı

Samanyolunda yürüyen bir karınca

En onulmaz vebayı kutlayan bir güvercin

İki katlı bir arabada

Bu bize yaklaşan bir deniz arabası

Sen ırakta samanyolu ırakta

Ve ay başka bir ay

Sarısı beyazına akmış

Bulaşmış bir yumurta', 'Önceden bilen oluş şartlarını çocuklarının Elleriyle değen koklayan hazırlayan adeta Sebebine ermeden erişmeden Korkan ilerdeki korkularla N...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/samanyolunda-veba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sepet', 'sepet-sezai-karakoc-2rdku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir vakitler niçin

Böyle büyük tutulmuş ölçüleri

Çocuklar bile biliyor

Filistinin ekmek sepetleri

Anne ne koysun içine

Ekmek mi çocuk mu

Düşmanın ilk baktığı 

Ekmek sepetleri

Dolmayı bekleyen

Ekmek sepetleri

Ve boşalmayı

Ekmek sepetleri

Her eşya gitse 

Kalacak tek eşya 

İnsana en aykırı

Filistinde ekmek sepetleri', 'Bir vakitler niçin Böyle büyük tutulmuş ölçüleri Çocuklar bile biliyor Filistinin ekmek sepetleri Anne ne koysun içine Ekmek mi çocuk mu Düş...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sepet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut', 'tut-sezai-karakoc-inlv6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son kaya iniyor kuyu aydınlanıyor

Ses insanın derinlerde parlayan

Son isyan denemesi oluyor güzel

İçimde yaman tutuk bir şair doğuyor

Tut elimden

Dosta düşmana karşı bir iyi konuşayım

Tut

Kulede saat kırılmasın

Geyikler sağır

Rüyalar boğuk olmasın

Son kıral ağlıyor, üstünde son kuş yoruluyor

Halkın kayıp annelere karşı saygısı yok

Tut elimden

Düşen tüyleri toplayalım

Tut

İsimsiz çocuk ağlamasın

Kuyuda ışık sönmesin

Kırk oda içiçe dönmesin

Halayıklar sağır

Dualar boğuk olmasın

Son insan yürüyor

Tut elimden kaçalım

Kaçalım kaçalım

Bizi kimseler görmesin

Arıyanlar bulmasın

Tren duvarları sarsmasın

Yürek bu kadar hızlı çarpmasın

Kan böylesine hızlı akmasın

Askın kulakları sağır 

Sesi boğuk olmasın', 'Son kaya iniyor kuyu aydınlanıyor Ses insanın derinlerde parlayan Son isyan denemesi oluyor güzel İçimde yaman tutuk bir şair doğuyor Tut el...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-sezai-karakoc-5f09l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Silahlara veda

Geceye rüyaya ve sana

Yalnızlığın geyik gözlü köşesinden

Düzenlerin çıkmazına

Çizdiğim resmin 

Saat kulesi ağlıyor

Ağzım o çeşit yok

Şişe bu çeşit var

Sen bir gece gelsen

Güneş doğmasa

Gitmeden yine gelsen

Bu yeni geleni

Bu bize bakanı

Sana bir anlatsam

Güneş doğmasa

Sandıkların içini göstersem sana

Çizdiğim resmin

Yalnızlığın geyik gözlü köşesinde 

Bir rafa koyabilsen

Olup biteni ve onları

Sabaha kadar konuşsak

O ürkek ürkek bakanı sana bir anlatsam

Ateşi karı tüfeği çeksem

Ocağa pencereye kapıya 

Kemana veda

Yağmurda şeytan ve şapkası

Silahın ölümünü kutluyorum

Tren kaçırmış gibiyim

Sana veda', 'Silahlara veda Geceye rüyaya ve sana Yalnızlığın geyik gözlü köşesinden Düzenlerin çıkmazına Çizdiğim resmin  Saat kulesi ağlıyor Ağzım o çe...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/veda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla Köşesi', 'leyla-kosesi-sezai-karakoc-ngme7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir de bakalım Leyla köşesinden

Aşkın kadın adlı penceresinden

Bırakmıştı kendini yazılmış olana

Susmak ve konuşmamak denen cana

Evlenmişti ve görünüşte mutlu

Şimdiden memnun ve gelecekten umutlu

Fakat bir eksiklik ufacık bir nokta

Kalbi kurcalıyordu hala

Mecnun ne olmuştu neredeydi

Nasıldı ne yapıyordu hali neydi

Geceleri loş gölgeler arasında

Kum tepelerinde ay yarasında

Mecnuna benzeyen hayaller olurdu

Bu anlarda sanki kalbi dururdu

Bitmiş olan bir daha mı başlayacak

Ne çare başlayan başlamamış

Bitmiş bitmemiş olacak

Gibi gelirdi Ona

Ürküntü geçmiş ama erememişti huzura

Karanlık bitmiş fakat erememişti huzura

Ay tutulmuş tutulmuş kurtulmuştu

Gçnlu zaman zaman tutmuştu mustu

Gün kırmıştı siyah çerçevesini

Yarmıştı ışıkta ötesini berisini

Baskın korkusuyla ürperen çadırların

Bugün düzen ve güven, ama yarın!!

Yarına bir güvence olmayan

Neye yarar böyle bir şimdiki zaman

Acıyla da olsa dopdolu olan hayat

Boşalmıştı zemberegi boşalmış bir saat

Gibi. Dönmüştü bomboş bir kagıda

Agızdaki tad benzemiyor eski tada

Irmak kurumuş rüzgar esmiyor

Yakıcı güneşi bir parçacık bulut örtmüyor

Arzu ve korku iki karanlık duygu

Yüreginde birbirini kovalayıp duruyordu

Ya bir gün geri dönerse Mecnun

Yine altüst olursa ortalık bütün

Daha mi iyi olur daha mi kötü bilmiyordu

Bir umut vardı gönlünde eksilmiyordu

Sonra kızıyordu kendine kınıyordu kendini

Kapamak istiyordu içinde eskinin kepengini

Eski oldu diyelim ama neydi yeni

Ve nasıl eskitmeli eskimiyeni

Nasıl öldürmeli ölmeyeni

Nasıl diri sayarsın ölü olanı

Eski bir zehirdi belki ama yeni

Andırıyordu tatsız tuzsuz bir yemegi

Beklemek neyi bekledigini bilmeden

Gün günü ay ayı kovalarken

Beklemek bir vaktin dolusunu

Öç alan kaderin zalim oyunu

Her şey akılla kurulu akılla düzgün

Ama aklın içinde olmalı baharat gibi

Bir parça delilik

Oysa mecnun almış bütün deliligi gitmiş

Kupkuru bir hayat kalmış ve adeta oyun bitmiş

Arzulanan zenginlik, at kumaş ve ziyafet

Yetmez olur insana bir gün elbet

İnsan hep birşey umar bekler

Ne oldugunu bilmez fakat

Fakat sonradan duruldu Leyla

Tevekkülle huzuru buldu Leyla

Ruhta kopan fırtınalar dindi

Gökten gönle sükunet indi

Anladı ki acı tatlı soguk sıcak

Geçmiş ve gelecek ayrılmak ve kavuşmak

Hep aynı varoluşun dönüşümleri

Aydınlanışları ve sönüşümleri

Her şey havada döner durur

Sonunda Tanrı varlıgında yok olur

Ruh hürdür vücut esir

Ruh baldır beden zehir

Ruh hürdür Tanrı aşkıyla

Baglı degil yer ve zaman kaydıyla

Farketmez gelse gelmese Kays (Mecnun) Ona

Gitse gitmese Ona Leyla

Tanrı katında buluşmuşlardır

Hakikat yurduna kavuşmuşlardır', 'Bir de bakalım Leyla köşesinden Aşkın kadın adlı penceresinden Bırakmıştı kendini yazılmış olana Susmak ve konuşmamak denen cana Evlenmişti ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/leyla-kosesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O ve Ben', 'o-ve-ben-sait-faik-abasiyanik-l0lik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana koşuyorum bir vapurun içinde 

Ölmemek, delirmemek için.

Yaşamak; bütün adetlerden uzak

Yaşamak....

Hayır değil, değil sıcak

Dudakların hatırası; 

Değil saçlarının kokusu

Hiçbiri değil.

Dünyada büyük fırtınaların koptuğu böyle günlerde

Ben onsuz edemem.

Eli elimin içinde olmalı,

Gözlerine bakmalıyım,

Sesini işitmeliyim.

Beraber yemek yemeliyiz

Ara sıra gülmeliyiz.

Yapamam onsuz edemem.

Bana su, bana ekmek, bana zehir; 

Bana tad, bana uyku

Gibi gelen çirkin kızım.

Sensiz edemem.', 'Sana koşuyorum bir vapurun içinde  Ölmemek, delirmemek için. Yaşamak; bütün adetlerden uzak Yaşamak.... Hayır değil, değil sıcak Dudakların ...', ARRAY['Türk Edebiyatı','Şiir','Sait Faik Abasıyanık']::text[], 8.5, '{"poet":"Sait Faik Abasıyanık","poet_slug":"sait-faik-abasiyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkân İçin', 'turk-n-i-cin-oktay-rifat-arnc4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulunmaz sevdazede Fuzulî,Nedim

Kanayan aşklarıyla yaşarlar bende 

Sevdiğim devletli sultanım efendim

Emreyle şiirler söyleyeyim kapında

Duyulmadık şiirler ağır ve güzel

Ki misli bulunmasın acemde bile

Gitsin kulaktan kulağa elden ele

Bir zaman gözlerin için  yazdığım gazel 

   

Ve kalbinde sevda diye yandığı zaman

Ayın on dördüne karşı pencerede

Saçların çıplak omuzların gecede

Mısralarım dökülsün dudaklarından

Sen faydalı nisan yağmuru gibisin

Bereket ve huzur getirirsin şiire

Ebediyet çığrını açtın kadere

Bu baharın ve bu gönlün sahibisin', 'Bulunmaz sevdazede Fuzulî,Nedim Kanayan aşklarıyla yaşarlar bende  Sevdiğim devletli sultanım efendim Emreyle şiirler söyleyeyim kapında Duy...', ARRAY['Türk Edebiyatı','Şiir','Oktay Rifat']::text[], 8.5, '{"poet":"Oktay Rifat","poet_slug":"oktay-rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turkan-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-orhan-veli-kanik-xly9n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün olur, alır başımı giderim,

Denizden yeni çıkmış ağların kokusunda

Şu ada senin, bu ada benim,

Yelkovan kuşlarının peşi sıra.

Dünyalar vardır, düşünemezsiniz;

Çiçekler gürültüyle açar;

Gürültüyle çıkar duman topraktan.

Hele martılar, hele martılar,

Her bir tüyünde ayrı bir telaş!

Gün olur, başıma kadar mavi; 

Gün olur, başıma kadar güneş;

Gün olur, deli gibi...', 'Gün olur, alır başımı giderim, Denizden yeni çıkmış ağların kokusunda Şu ada senin, bu ada benim, Yelkovan kuşlarının peşi sıra. Dünyalar va...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-ahmet-muhip-diranas-5cuut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardır yağan üstümüze geceden,

Yağmurlu, karanlık bir düşünceden,

Ormanın uğultusuyla birlikte

Ve dörtnala dümdüz bir mavilikte

Kar yağıyor üstümüze, inceden.

Sesin nerde kaldı, her günkü sesin,

..........
..........', 'Kardır yağan üstümüze geceden, Yağmurlu, karanlık bir düşünceden, Ormanın uğultusuyla birlikte Ve dörtnala dümdüz bir mavilikte Kar yağıyor ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-mehmet-peker-bj2m1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz seninle bir çift göz gibiyiz

Aynı şeye bakan, ama birbirine bakamayan

iki göz...

Korkuları aynı, acıları ayrı

Tek yumurta ikizleri ama yabancı

Sen ve ben...

Ölüme beraber gidecek kadar yakın

Bakışmayacak, tanışmayacak, konuşmayacak kadar uzak

Aynı yüzde iki göz

Ateş kadar sıcak

Güneş kadar parlak

Yağmur kadar serin

Derya kadar derin

İki göz...

Sen ve ben...bir çift göz gibiyiz

Kıyamete kadar yanyana, buluşamayacak kadar ayrı...

                                9. 11. 1999 - Ankara', 'Biz seninle bir çift göz gibiyiz Aynı şeye bakan, ama birbirine bakamayan iki göz... Korkuları aynı, acıları ayrı Tek yumurta ikizleri ama y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Peker']::text[], 8.5, '{"poet":"Mehmet Peker","poet_slug":"mehmet-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ve-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-feramuz-gorel-tloi9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık çok acı ölümden beter

Hislerime dokunur dur diyemiyorum artık yeter

Alem gülüp eğleniyor bu nasıl kader

Hasretlik beni etti derbeder

Ölüm kurtuluştur ayrılık yıkılış

Bu nasıl sevgi uzaktan bakış

Ben eriyorum için için

Ne zaman bitecek bu yakarış

Önce benim kollarımdaydın şimdi ellerin

İntizar ediyorum sana derin dedin

Hala boştur kalbimdeki yerin

Ayrılık yarası derindir çok derin

Bende insanım bende severim

Sana ne zaman yarim diğeceğim

Senin yüzünden tükendi malım servetim

Feramuzum gece gündüz seni ararım', 'Ayrılık çok acı ölümden beter Hislerime dokunur dur diyemiyorum artık yeter Alem gülüp eğleniyor bu nasıl kader Hasretlik beni etti derbeder...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ogul', 'ogul-feramuz-gorel-qbxcn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün sende yaşlanırsın

Belin bükülür

Yaşlar dolar gözlerine

Gözlerinden yaşlar dökülür oğul

Gözlerine çekilir perde

Bilmezsin aydınlık nerede

Eşin dostun artık sevmez seni

Düşersin çekilmez derde oğul

Yüzün kırışır dizin tutmaz

Boğazın lokmayı yutmaz

Kimse gelip elinden tutmaz

Bilmezsin takatin nerde oğul

Beklersin azrail gele

Gelipte canını ala

Öldüğünü dostlar bile

Uğurlarlar seni güle güle oğul', 'Bir gün sende yaşlanırsın Belin bükülür Yaşlar dolar gözlerine Gözlerinden yaşlar dökülür oğul Gözlerine çekilir perde Bilmezsin aydınlık ne...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-feramuz-gorel-1gb5q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir başı var iki ayağı

Yüzünde yoktur insanın yağı

Başından karın eksilmesin ağrının dağı

Eridi bitti yüreğim yağı

İki gözü var iki kulağı

Hasta eder vallahı sağı

Eridi bitti vallahi yüreğim yağı

Ağzı burnu dişleri

İnsandır diyorsun

Gel gör insan hani

Tarumar oldu uzvunun her yanı

Botada çıktı garibin yağı', 'Bir başı var iki ayağı Yüzünde yoktur insanın yağı Başından karın eksilmesin ağrının dağı Eridi bitti yüreğim yağı İki gözü var iki kulağı H...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürün Çocukları', 'oldurun-cocuklari-feramuz-gorel-qz43w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öldürün çocukları 

Kimini ana rahminde

Kimini bölekteyken

Yaşatmayın öldürün çocukları

Kimini emeklerken

Kimini anne baba derken

Kimini okul zilini beklerken

Kimini çöplükte ekmek ararken

Yaşatmayın öldürün çocukları

Kimini orta mektepte

Kimini sınır beklerken

Kimini vatan savunurken

Durmayın öldürün çocukları

Yok edin geleceği bu günden

Mahrum edin çocukları düğünden

Ayırın kardeşleri bir birinden

Yaşatmayın öldürün çocukları', 'Öldürün çocukları  Kimini ana rahminde Kimini bölekteyken Yaşatmayın öldürün çocukları Kimini emeklerken Kimini anne baba derken Kimini okul...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oldurun-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-feramuz-gorel-nn81h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En büyük medeniyet ahlaksızlık

Çağdaşlık imansızlık

Fakirlik kuransızlık

Makam istersen işte yolsuzluk

En büyük eser zulüm

Garip kalan sevgi

Yükseliş yalancılık

En büyük vurgun talancılık

Dinlenme yeri zindan

Unutamazsın yanlızlığı bir an

Yetim kalan kuran

Akrabası çok varlıklı şeytan

Mezar ebedi mekan

Onu iki yoksul kazar

Yatak yorganın üç beş metre bez

Hoca seslenir tez gömün tez...', 'En büyük medeniyet ahlaksızlık Çağdaşlık imansızlık Fakirlik kuransızlık Makam istersen işte yolsuzluk En büyük eser zulüm Garip kalan sevgi...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seslenis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl İnanayım Sana', 'nasil-i-nanayim-sana-feramuz-gorel-cqkjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık olmuşum sana

Bakmıyorsun sen bana

Bıraktın beni yana yana

Nasıl inanayım sana

Gözlerim kan ile dolu

Karanlık aşkımın yolu

Kalbim sevginle dolu

Nasıl inanayım sana

Önceleri benimdin

Yalan sevgine kandım

Aşkınla inan yandım

Nasıl inanayım sana

Sevmek suçmu bana

Nasıl bağlandım ben sana

Bıraktın beni yana yana

Nasıl inanayım sana', 'Aşık olmuşum sana Bakmıyorsun sen bana Bıraktın beni yana yana Nasıl inanayım sana Gözlerim kan ile dolu Karanlık aşkımın yolu Kalbim sevgin...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-inanayim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gariplik Var', 'bir-gariplik-var-feramuz-gorel-3mzb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güllerin açışında

Bülbülün seslenişinde

Baykuşun ötüşünde

Korkarım bir gariplik var

Bu selanın verilişinde

Hocanın talkin deyişinde

Milleti soyup yeyişinde

Andolsun bir gariplik var

Alim islamı niçin sevmez

Müslümana islam demez

Kuran okur tecvit bilmez

Bu hocanın imanında bir gariplik var

Camide insanlar ikiye bölündü

Yönetime yol göründü

İnsanlar şeytan postuna büründü

Vallahi bu camide bir gariplik var...', 'Güllerin açışında Bülbülün seslenişinde Baykuşun ötüşünde Korkarım bir gariplik var Bu selanın verilişinde Hocanın talkin deyişinde Milleti ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gariplik-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadım', 'yasamadim-feramuz-gorel-pl0iv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günde bir gün yaşamadım

Direndim engelleri aşamadım

Pınar oldum çoğaldım

Irmakları aşamadım

Yalan dünya inan boş

Herşey kulağa gelir hoş

Diyor hadi durma koş

Bir milim bile koşamadım', 'Günde bir gün yaşamadım Direndim engelleri aşamadım Pınar oldum çoğaldım Irmakları aşamadım Yalan dünya inan boş Herşey kulağa gelir hoş Diy...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme', 'mahkeme-feramuz-gorel-lplq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuran sanık oldu şeytan müşteki

Faiz savcı oldu fuhuş hakim

Kumarhane de katip oldu

Meyhane mübaşir

Yargı başladı...

Mübaşir seslendi sanık Kuran

Kuran boynu bükük gözü yaşlı

Ağır adımlar ile mahsun bakışlı

Sanık sandalyesine oturdu Kuran

Mübaşir seslendi  müşteki şeytan

Koşar adımlarla geldi bir an

Yargıya geçildi hemen 

Savcı suçları saydı kurana

Neden saldırdın sen şeytana

Bir ucuda dokundu bana

Katip yazmaya başladı aklına geleni

Hakim dedi yasakladın sen insanı eğlendireni

Söz birliği yapmışcasına karar verildi

Atın zindana bu kuranı

Sormadılar hiç arzu halini

Hemen oracıkta kırdılar kuranın belini

Savunmasız kaldı kuran

Artık mahkum olmuştu

Cezasını çekmeliydi

Çile dolduruyor kuran

Özgürlüğü bekliyor 

Yeniden doğacak günü...', 'Kuran sanık oldu şeytan müşteki Faiz savcı oldu fuhuş hakim Kumarhane de katip oldu Meyhane mübaşir Yargı başladı... Mübaşir seslendi sanık ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mahkeme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-feramuz-gorel-3qgi6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Garip insana sövüp sayarlar

Fırsat düşse gözlerini oyarlar

Her yerde kötüler adını yayarlar

Süslü püslü söz eder onu boyarlar

Kulaktan dolma sözlere kanırlar

Garipi hep kötü anırlar

Kendileri yedi  bitirdiler

Garibi canavar sanırlar

Garibin derdi arşa yükseldi

Vicdansızlar bağrını deldi

Yetimliğide tattı fakirliği de

Garibi alaya alır gülerler

Çile keder ızdırap

Garibin dostu sensin yarab

İnsanlar zalim insanlar vefasız

Garibin günü geçmez rabbim sensiz....', 'Garip insana sövüp sayarlar Fırsat düşse gözlerini oyarlar Her yerde kötüler adını yayarlar Süslü püslü söz eder onu boyarlar Kulaktan dolma...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Cenaze', 'bir-garip-cenaze-gokalp-burlukkara-q5m78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belli ki bir ölen var yine mahallemizde...

Hava ayaz mevsim kış

Sela okunur

Kimdir ki bu ebedi yolculuğa doğru yol alan?

Sorarım eşe dosta...

Neden cevapsız kalır sorular?

Canım kardeşim, benimle ölümlere,

göz kırpmadan gelen can yoldaşım,

Neden ağlarsınınz şiddetle?

Benden neden saklarsınız?

ayaz üşütmez oldu, korkudur

ruhumu soğutan

Kartpostallardaki bebek yüzlü kız düştü aklıma,

Bir gözünde yaş, 

diğerinde siyah beyazlığı hüznün.

Endişedir beni böyle yalpalandıran...Nereye,

gidiyorsunuz böyle sessizce hıçkırarak?

Neden susarsınız hala?

ağlamaktır içimden gelen, ancak

ağlayamaz oldum

Neden durursunuz? Hocaefendi ya sen

kime okursun bu dualarını?

Sen neden  gülersin bana dua okuyarak

ötekileri ağlarken?

Durun...

Gitmeyin

Nereye böyle şimdi?

Benide götürün yanınızda,

Neden söylemediniz kimin ölgüğünü?

YOKSAA...?', 'Belli ki bir ölen var yine mahallemizde... Hava ayaz mevsim kış Sela okunur Kimdir ki bu ebedi yolculuğa doğru yol alan? Sorarım eşe dosta.....', ARRAY['Türk Edebiyatı','Şiir','Gökalp Bürlükkara']::text[], 8.5, '{"poet":"Gökalp Bürlükkara","poet_slug":"gokalp-burlukkara","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-garip-cenaze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker', 'asker-ersan-i-coz-wlvgx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarın acıklı bir türkü söylediği,

Bulutların bu türküye ağladığı bir günde

Damatlığıyla çıktı geldi askerim

Ne güzelde yakışmıştı askerime

''ay yıldızlı damatlığı''', 'Rüzgarın acıklı bir türkü söylediği, Bulutların bu türküye ağladığı bir günde Damatlığıyla çıktı geldi askerim Ne güzelde yakışmıştı askerim...', ARRAY['Türk Edebiyatı','Şiir','Ersan İçöz']::text[], 8.5, '{"poet":"Ersan İçöz","poet_slug":"ersan-i-coz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Umutlar', 'derin-umutlar-gokalp-burlukkara-6sfis', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerime sıkıldı kurşunlar,

bir sağnaktır bu hücum,

düşlerime

Sendeleyen bir sandalın içinde

hayallerin son kırıntıları

çoktan su alır sandalın dibi

Ve ben geçmişin gölgsinde

bir zincirin paslı halkasıyım...

Etrafı çevrili bir kum tanesinden farksız,

Çaresizce ama korkusuzca...

Her adımda ölüm kadehini yudumlayarak

bir hilkat garibesine saldırırcasına,

eğilmeden, gevşemeden, ilerleyerek,

Bunun adını koyabilene ne söz?

Kelimelerin bir balyoz''un

örs''e inmesi misali

ağzımdan çıktığı anda,

büyür gözlerimdeki umudun

son kırıntıları...

Bu umut bir ayrılığın habercisidir,

Ruhumun bedenimden

ayrılışının

Müjdecisidir', 'Düşlerime sıkıldı kurşunlar, bir sağnaktır bu hücum, düşlerime Sendeleyen bir sandalın içinde hayallerin son kırıntıları çoktan su alır sand...', ARRAY['Türk Edebiyatı','Şiir','Gökalp Bürlükkara']::text[], 8.5, '{"poet":"Gökalp Bürlükkara","poet_slug":"gokalp-burlukkara","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/derin-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-nergiz-kartal-9d9nb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bebeğim

ilk çığlığı dünyaya gelişinin bilinçsizce

Sende katılacaksın bu hayat kervanına

İstemeden...

Gün olur elden ele dolaşacaksın

Gün olur sevilip okşanacaksın

Gün olur gülücükler saracak etrafını

ama kanma

Bu hayat kervanının yolları hep düz değildir

büyüdükçe anlayacaksın 

Sen büyüdükçe seni saran eller küçülecektir

büyüdükçe tadacaksın yaşam savaşını

sen bebeğim sen

bir gün büyüdüğünde 

Tek başına 

Buhayat kervanının yolcusu olacaksın

                                               28.10.l990', 'Sen bebeğim ilk çığlığı dünyaya gelişinin bilinçsizce Sende katılacaksın bu hayat kervanına İstemeden... Gün olur elden ele dolaşacaksın Gün...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yolcu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklara', 'cocuklara-nergiz-kartal-q52rr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözleri özlem mavisi

özlemi sevda yeşili

sevdası barış beyazı

Yurdumun çocuklarının

Her bir bakışlarında özgürlük var

Her bir bakışlarında sevgi ve huzur

Durun der yurdumun çocukları

Durun!

Kardeşliği değil kavgayı vurun.

Suskun yüreği çocuklarımın

Suskun

Ayakları yalınayak

Koşmuyor,koşamıyor

Kırık kanatları umutlarının

Uçmuyor,uçamıyor

Omuzları çökük dağlara doğru...

                                   16.0l.l995', 'Gözleri özlem mavisi özlemi sevda yeşili sevdası barış beyazı Yurdumun çocuklarının Her bir bakışlarında özgürlük var Her bir bakışlarında s...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Şiirim', 'benim-siirim-nurullah-genc-s65c1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakmayın çevremi kuşatanlara

Hüznün,yalnızlığın şairiyim ben

Issız ovaların nehiriyim ben

İçimde işliyor derin bir yara

Aşkın öldürmeyen zehiriyim ben

Bakmayın çevremi kuşatanlara

Hüznün,yalnızlığın şairiyim ben

Kapattım kalbimin son kapısını

Dokunun;boşlukta bir taş gibiyim

Hafızası ölü nakkaş gibiyim

Çekiyorum mutsuzluğun yasını

Ayaklara mahkum bir baş gibiyim

Kapattım kalbimin son kapısını

Dokunun;boşlukta bir taş gibiyim

Ölümü yaşadım ölmeden önce

Bana sonsuzluğu beklemek düştü

Mazide benim de yüzüm gülmüştü

Uyandım,mutsuzluk geri dönünce

Ölümü yaşadım ölmeden önce

Bana sonsuzluğu beklemek düştü

Gelsene,nerdesin,ey sessiz ölüm

Adını yazsana dudaklarıma

Zaman kan süzüyor kulaklarıma

Hıçkırığa mahkum biçare gönlüm

Haydi takılıver ayaklarıma

Gelsene,nerdesin,ey sessiz ölüm

Adını yazsana dudaklarıma

Bulsam Kafdağı''nın eteklerini

Başımı çevirip gitsem mi bilmem

Ben ki yaranamam,şakaya gelmem

Kuruttum bengisu peteklerini

Karanlık dolu bir dünyada gülmem

Bulsam Kafdağı''nın eteklerini

Başımı çevirip gitsem mi bilmem

Umutlar sultanı anlayamadı

Sizler beni asla anlamazsınız

Biraz sevdasınız,biraz nazsınız

Kimse benim gibi ağlayamadı

Belki gülersiniz,inanmazsınız

Umutlar sultanı anlayamadı

Sizler beni asla anlamazsınız', 'Bakmayın çevremi kuşatanlara Hüznün,yalnızlığın şairiyim ben Issız ovaların nehiriyim ben İçimde işliyor derin bir yara Aşkın öldürmeyen zeh...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/benim-siirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekçe', 'cicekce-nergiz-kartal-e6i2t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni ruhumun çiçeklerinden ayırmayın

ki;

kardelenler zoru aşacak

Ulaşılmaz dağlarımda...

Ayçiçecleri boy verecek karış karış

İnsanlar başın kaldıracak gün ışığında

Gelincikler küskünlüğünü haykıracak

Düşmanlıklara...

Beni ayırmayın gönlümün çiçeklerinden

Papatyalarım taç olacak

bütün insanlara

Bütün insanlar Kral olacak

Güller sevgi dağıtacak tüm dünyaya

insanlar aşkı  yaşayacak', 'Beni ruhumun çiçeklerinden ayırmayın ki; kardelenler zoru aşacak Ulaşılmaz dağlarımda... Ayçiçecleri boy verecek karış karış İnsanlar başın ...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cicekce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-nergiz-kartal-1sdtf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine yangınlarda yüreğim

Yine suskun,yine dağınık

Ve yine ağlamaklı...

Çocuk olmayı özlüyorum şu günlerde

Elimde hiç olmayan uçurtmam

Maviliklerde gezmeyi özlüyorum.

Kucağımda hiç benim olmayan bebeğim

bebeğime elbiseler dikmeyi

Uçurtmamım kopan kuyruğunu tamir etmeyi özlüyorum

Koşmalıyım diyorum çocukça

Koşup düşmeliyim dizlerim paramparça

Ve ağlamalıyım

Evet ben çocuklar gibi masum ve hür

ağlamayı özlüyorum

...

koşuyor yüreğim bilinmezlere doğru

Yine dargın,yine kederli

ve yine çaresiz...

Etrafımda dünyanın bütün çiçekleri

Ama ben leylakları,nergisleri

yasemenleri,ortancaları

dağlarımda mor menekşeleri özlüyorum.

Yeşili,kırmızıyı,maviyi,sarıyı

Ben çiçeklerimden de öte renklerini

Kokularını,özgürlüklerini özlüyorum.

Yine hayallerde yüreğim

ve yine kırgın...

hesap etmediği üçe beşe rağmen

yine eksilerde.

dağ boylarının hırçınlığı vurmuş yüzümde 

yine kaşlarım çatık

Ama ben hep güleç yüzümü özlüyorum

Özlüyorum işte sevilmeyi

Sevdimi tam sevmeyi

delicesine

Hasreti özlüyorum engin engin

hasreti hasret gibi çekmeyi

ve Kavuşmayı özlüyorum

Kavuşmak gibi...

                                             26.ll.1998

                                           kurucaşile', 'Yine yangınlarda yüreğim Yine suskun,yine dağınık Ve yine ağlamaklı... Çocuk olmayı özlüyorum şu günlerde Elimde hiç olmayan uçurtmam Mavili...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ozleyis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söküp Atacağım', 'sokup-atacagim-gulay-atilay-v1bny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzellikler seninle başladı seninle bitti

Kalbim acı, ızdırap,kahır, selinde yitti

Bedenim isyan etti hafızam iflas

Duymadın feryadımı ben biçare ben niçaz

Derdime derman aradım kalbime ferman

Ne olur BİRTANEM dedim beni duy biran

Bana gülmeyi öğrettin vede sevmeyi

Unutmayıda öğret ve sonra terket.

Belki diyorum, belki.......

Seni kalbimden söküp atacağım

Gözlerinin rengini unutacağım

Birgün sen sevdinmi hiç ?dediklerinde

Belki...buruk bir a''nı hatırlayacağım

Verdiğin güzellikleri unutmayacağım

Kırdığın gururumla saptayacağım

Şimdi hala elimde resmin olsada

Mendilime sarıp saklayacağım.....

Hayatın anlamı nedir?

Sevip sevip üzmek mi?

Sevenleri gözüyaşlı bırakıp

Terkedipte gitmek mi?', 'Güzellikler seninle başladı seninle bitti Kalbim acı, ızdırap,kahır, selinde yitti Bedenim isyan etti hafızam iflas Duymadın feryadımı ben b...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sokup-atacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-kadri-gul-7t41o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımın izlerini taşıyor kır saçlarım

Yalan,riya ,üçkağıt, çatılıyor kaşlarım

Ocağıma dikilmiş,yüzlerce incir ağacı

Kuyularım kazılıyor, çatılıyor kaşlarım.

Renkli camlar ardından, bakılıyor dünyaya

Kadir, kıymet de neymiş, verilir mi sevdaya ?

Açlığı paylaşmayan,malını nasıl paylaşır ?

Dünya ne olmuş artık, bir leğen kirli çamaşır ?

Ey,zor şafaklarımın rüzgar saçlı perisi

Sevgidir gerçek olan, yalandır hep gerisi

Hesaplı olsun adımın, ömür bir gün bitecek

Mal yalan, mülk yalan,Ölüm ise hep GERÇEK...', 'Hayatımın izlerini taşıyor kır saçlarım Yalan,riya ,üçkağıt, çatılıyor kaşlarım Ocağıma dikilmiş,yüzlerce incir ağacı Kuyularım kazılıyor, ç...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hayat', 'i-ste-hayat-kadri-gul-xj5uy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalem kırmış Yaratan,kaderimi yazarken

Yitmiş gitmiş soluğum,dertlerimi sayarken

Melekler bile üzgün, ağlamaklı, biçare

Bela,lanet, gözyaşı, yüreğime dolarken....', 'Kalem kırmış Yaratan,kaderimi yazarken Yitmiş gitmiş soluğum,dertlerimi sayarken Melekler bile üzgün, ağlamaklı, biçare Bela,lanet, gözyaşı,...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iste-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevdam Bir Yer Eder mi Bilmem', 'bu-sevdam-bir-yer-eder-mi-bilmem-kadri-gul-n3ba1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çektiğim acılar kader mi bilmem

Dert mi,elem mi, keder mi bilmem

Yaban ellere gider mi bilmem

Bu sevdam bir yer eder mi bilmem ?

Korkuyorum aşkım heder olacak

Bu garip gönlüm beter olacak

Zavallı kalbim keder dolacak

Bu sevdam bir yer eder mi bilmem ?,

En güzel şeyler hep sende saklı

Birazcık aşk, gönlümün hakkı

Aşkım,aşklardan inan çok farklı

Bu sevdam bir yer eder mi bilmem ?

Seni bensiz yaşama, beni de sensiz

Yaşanmaz ki dünyada aşksız ,sevgisiz

Nedir ki bir gönül, hiçtir alevsiz ?

Bu sevdam bir yer eder mi bilmem ?....', 'Çektiğim acılar kader mi bilmem Dert mi,elem mi, keder mi bilmem Yaban ellere gider mi bilmem Bu sevdam bir yer eder mi bilmem ? Korkuyorum ...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sevdam-bir-yer-eder-mi-bilmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ölümcül Bir Hülyadır', 'ask-olumcul-bir-hulyadir-nurullah-genc-zx1vt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hülya tatlı bir andır

Süzülür dibine selvi ağaçlarının

Zambakların, sevda çimenlerinin.

Dağlarda duman duman tütüyor sıla

Sıla da garibin omuzlarına

Güvercin gibi konan

Sadağında mumçiçeği serzeniş

Mızrakları cazibesiyle kıran

Saçları darmadağın

Bitişik bir hicrandır.

Ne fettan sarayların

Bitişik cilvekar yalnızlığı

Ne de bezirganları küçümseyen sultandır.

Gezinir içimizde hülya tatlı bir andır.

Ne gün başımı alıp gitsen karanlıklara

Çıkıyor bir köşeden karşıma kelebekler

Onlar da bir derbeder gibi mahrum öteden

Onlar da tanyerine bakıp hülyayı bekler.

Beyhude hekimlerin ülkesinde bir şehir

Çıkmaz sokaklarını düşlerimize açan

Bir sahura yıldızı gibi göklerde uçan

Köpüksüz anıların sihriyle akan nehir

Varlığı bestenigar, yokluğun deniz gibi

Gönül,safkan bir vefa atlasında şahlanır.

Asil fırtınalarda kaybolan bir iz gibi

Çölde aşk suretinde bir ahu peydahlanır.

Kum,yaldızlı giysiler içinde meşhur güzel 

Ay öper eğilerek çölün yanaklarını

Ufukların delisi, soluk bir deniz gibi

Bir sayeban altında yürür hazinesine

Kah takılır uzaktan bir belanın sesine

Kah yüzü yıldızlara benzeyen bir rüyadır.

Bin tepede bayrağı dalgalanır Leyla''nın

Oysa aşk,karanlıkta ölümcül bir hülyadır.', 'Hülya tatlı bir andır Süzülür dibine selvi ağaçlarının Zambakların, sevda çimenlerinin. Dağlarda duman duman tütüyor sıla Sıla da garibin om...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ask-olumcul-bir-hulyadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkına Varamadık Bu Bile Yanlış', 'farkina-varamadik-bu-bile-yanlis-kadri-gul-snmev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanlışlar içindeyiz biz bu alemde

Beraber olmamız büyük bir yanlış

Çok büyük günaha girdik bazen de

farkına varamadık, bu bile yanlış...

Zaten tutmuyordu ki bizim burcumuz

Bitti birbirimize olan borcumuz

biraz da hasret olsun ,orucumuz

Farkına varamadık bu bile yanlış...

Sevmek güzel şey, aşk kutsal diye

Nedir bu tutkular,ihtiras niye ?

Aman be ! Boşverelim, biz diye diye

Farkına varamadık ,bu bile yanlış...

Herşeyden önce mutlu yuvalarımız var

Dünyalar tatlısı çocuklarımız var

Tanrı katında büyük günahımız var

Farkına varamadık, bu bile yanlış......', 'Yanlışlar içindeyiz biz bu alemde Beraber olmamız büyük bir yanlış Çok büyük günaha girdik bazen de farkına varamadık, bu bile yanlış... Zat...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farkina-varamadik-bu-bile-yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlaç', 'i-lac-kadri-gul-uvlf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün hastalandım, doktora gittim

Doktor dedi ki ; durumun çok vahim,

Sana vereceğim bu ilaç

Haftada sadece bir içim...

Hayretler içinde kaldım, 

Açıp bakınca reçeteye

Vücudum hasret kalmış

Bir yudumcuk sevgiye

Sensin benim ilacım

Sensin tek dermanım

İzin vermese de imanım

İçeceğim seni,İLAÇım...

Haydi Yavrucuğum,uzan yanıma

Başlıyalım artık haftalık seansa

Bayılırım, ölürüm,böyle nüansa

Keşke bu ilaç bir de her gün olsa !.......', 'Dün hastalandım, doktora gittim Doktor dedi ki ; durumun çok vahim, Sana vereceğim bu ilaç Haftada sadece bir içim... Hayretler içinde kaldı...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarınla Bir Can Ver', 'dudaklarinla-bir-can-ver-kadri-gul-4bjgr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgini vereceksen eğer

Aşkı tadacaksak beraber

Gözlerinle öldürdün

Dudaklarınla bir can ver....

Sevda çiçeğim solmak üzere

Gözyaşından rahmet ver

Soldurduğun aşk gülüme

Dudaklarınla bir can ver...

İstemem sensiz dünyayı

Parayı, malı ,mülkü

Gel, sevindir gönlümü

Dudaklarınla bir can ver.......', 'Sevgini vereceksen eğer Aşkı tadacaksak beraber Gözlerinle öldürdün Dudaklarınla bir can ver.... Sevda çiçeğim solmak üzere Gözyaşından rahm...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dudaklarinla-bir-can-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazidekilere Kalan Nedir?', 'mazidekilere-kalan-nedir-fatih-karacelik-5tfv4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir virane iskeleden

Köhne bir vapur

Ağır ağır demir alır.

Taşır ufuğun ucundaki

Ulaşılması zor menzile;

Yüreği hüzün dolu,

Uğurlayanı olmayan

Bir yalnız yolcuyu.

Sevinçler iskelede,

Acılar menzilde bekler.

Elveda yalnız yolcu!

Seni kim teskin eder?

Bir kırık yürekten

Kara bir sevda 

Yavaş yavaş kayıp gider.

Götürür aşkın ardındaki

Yolu bitmez hiran kervanına;

Yüreği hınç dolu

Maşuğa yüz vermeyen

Bir zalim sevgiliyi.

Umutlar yürekte,

Hayaller atide bekler.

Elveda zalim sevgili!

Seni kim tatmin eder?

Bir çift dudaktan

Densiz bir söz

Buğu buğu uçup çıkar.

İncitir de birden bire;

Şaire en ağır cezayı veren,

Yüreği intikam dolu,

Affı mazisinde unutan

Bir garip dostu.

Özür dudakta,

Hata kalpte bekler.

Elveda garip dost!

Seni kim memnun eder?

07/Ekim/1999-İZMİR', 'Bir virane iskeleden Köhne bir vapur Ağır ağır demir alır. Taşır ufuğun ucundaki Ulaşılması zor menzile; Yüreği hüzün dolu, Uğurlayanı olmay...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/mazidekilere-kalan-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlüm', 'yagmur-gozlum-kadri-gul-3gnwv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava sanki birden kapattı

Ağlıyor mu ne güzelim gözün

Üzülmeni istemem,kıyamam sana

Sen ağlama benim biricik yağmur gözlüm...

Anlıyorum halinden ne acılar çektiğini

Acımasız yılların aman vermediğini

Gönül tarlasını ekip biçemediğini

Biliyorum benim biricik yağmur gözlüm

Gülsün artık gözlerin, güneşin açsın

Enaz sen de benim kadar aşka açsın

Başındaki belalar cehenneme kaçsın

Diliyorum Allah''tan Canım YAğmur Gözlüm

Gel üzme beni, sil gözlerini

Gel çabuk,bitir hasretini

Beraber aşkın birinci dersini

Okuyalım gel, gel yağmur gözlüm....', 'Hava sanki birden kapattı Ağlıyor mu ne güzelim gözün Üzülmeni istemem,kıyamam sana Sen ağlama benim biricik yağmur gözlüm... Anlıyorum hali...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Ezgisi', 'sabah-ezgisi-fatih-karacelik-836r8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah ruhumda duyduğum ezgi,

Rüzgar bekleyen bayrak gibi yaslı.

Hatıralarıma çekilen çizgi,

Kıpkızıl renge boyalıdır,kanlı.

Hep aynıdır...Senelerdir gördüğüm,

''Sana revadır!'' denilen işkence.

Hayatım başından beri kördüğüm..

Hayatım çözemediğim bilmece.

Beynimi paramparça eden kader;

Önümdeki sis perdesini kaldır.

Yüreğime arsızca giren keder;

Öldürene kadar durmadan saldır.

23/Nisan/2000-İZMİR', 'Her sabah ruhumda duyduğum ezgi, Rüzgar bekleyen bayrak gibi yaslı. Hatıralarıma çekilen çizgi, Kıpkızıl renge boyalıdır,kanlı. Hep aynıdır....', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sabah-ezgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel Gözlerin', 'ecel-gozlerin-kadri-gul-i7m09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıldız yıldız parlıyor

Çisil çisil yağıyor

Volkan gibi patlıyor

Beni yakan gözlerin...

Aşka davet ediyor

Sonra da vazgeçiyor

Beni deli ediyor

Senin ela gözlerin

Bakmaya kıyamam

Öpmeye doyamam 

Ben onlarsız olamam

Senin ECEL GÖZLERİN....', 'Yıldız yıldız parlıyor Çisil çisil yağıyor Volkan gibi patlıyor Beni yakan gözlerin... Aşka davet ediyor Sonra da vazgeçiyor Beni deli ediyo...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ecel-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Nazardan Saklasın', 'allah-nazardan-saklasin-kadri-gul-7v4yd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herşeyi paylaştık, bu yabanlık niye ?

Ben seni sevmedim mi, varlığım diye ?

Karasevdam sığmaz evrene bile

Çok güzelsin yavrucuğum

               Allah nazardan saklasın...

Sen de aç gönlünü, bu sonsuz sevgiye

Yetmedi mi ikimizin de çektiği bunca çile

Bir dalda iki tomurcuk güle

Benzeyelim yavrucuğum,

               Allah nazardan saklasın...

Kelebekler kadar özgürsün

Aşk bahçemde açan bir gülsün

Acayip, mühhiş, felaket güzelsin

Bebeğim seni

                Allah nazardan saklasın.....', 'Herşeyi paylaştık, bu yabanlık niye ? Ben seni sevmedim mi, varlığım diye ? Karasevdam sığmaz evrene bile Çok güzelsin yavrucuğum           ...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/allah-nazardan-saklasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Yıllar', 'vefasiz-yillar-kadri-gul-lbo1j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine çalıyor bak bizim şarkımız

Canlandı gözümde o hatıralar

Hani bitmezdi yüce aşkımız

Bize yalan söylemiş ,vefasız yıllar.....', 'Yine çalıyor bak bizim şarkımız Canlandı gözümde o hatıralar Hani bitmezdi yüce aşkımız Bize yalan söylemiş ,vefasız yıllar........', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vefasiz-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesbih Gibi', 'tesbih-gibi-kadri-gul-tcadh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertlerimi dizerken iplere bir bir

Tesbih gibi, çileleri çekerken

İçimdekileri kim bilebilir ?

Hayatıma bunca şimşek çakarken.....', 'Dertlerimi dizerken iplere bir bir Tesbih gibi, çileleri çekerken İçimdekileri kim bilebilir ? Hayatıma bunca şimşek çakarken........', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tesbih-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-kadri-gul-fu9d7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sensiz yaşamak ne demek bilir misin ?

Yanımdasın, içimdesin yine de özlemimsin

Seni benim kadar sen bile sevemez 

Sen bile benim kadar ÖZLEYEMEZSİN.......', 'Seni sensiz yaşamak ne demek bilir misin ? Yanımdasın, içimdesin yine de özlemimsin Seni benim kadar sen bile sevemez  Sen bile benim kadar ...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim''e', 'esim-e-kadri-gul-7odv4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana yaşımı sorma;

Yeterince yaşadım hayatı

Belki yüz yaşındayım

Belki de bin yirmi

Şarkılarla dağıtırım efkarımı

Şiirler dert ortağım

Beni nerede düşünürsen ,

Ben hep oradayım

Seni nerede düşünürsem

Sen hep oradasın

Şu hayatta gerçek olan;

Bir sevda, bir ölüm,bir de SEN

Seni nasıl sevdiğimi

Ah bir bilebilsen ?

Bir seni sevdim

Bir tek seni seviyorum

Sen; aşkımın kıblesi

Sen; oğlumun annesi

Seni sevmemin olamaz bahanesi

Ben seni,sen olduğun için sevdim

Seni sen olduğun için seveceğim

Ey, sevdamın GÖK KUBBESİ......', 'Bana yaşımı sorma; Yeterince yaşadım hayatı Belki yüz yaşındayım Belki de bin yirmi Şarkılarla dağıtırım efkarımı Şiirler dert ortağım Beni ...', ARRAY['Türk Edebiyatı','Şiir','Kadri Gül']::text[], 8.5, '{"poet":"Kadri Gül","poet_slug":"kadri-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/esim-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Olacak', 'guzel-olacak-gulay-atilay-a542w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana kavuşma saati yaklaşıyorsa 

Sensizliğin burkluğunu yaşayan kalbim

Sabırsızca çarpıyorsa. 

Ellerim düşüncelerime hakim olup 

Tüm şiirlerde  yanlız seni yazıyorsa 

Bil ki sonsuz özlem kaplamıştır içimi. 

Ellerin ellerime değdi mi, 

Büyük bir sıcaklık sardı mı benliğimi 

Her ne yana dönsem görebiliyorsam

gözlerini 

Duyabiliyorsam sesini 

Hissedebiliyorsam nefesini 

Demek tüm benliğimle senleyim. 

Vedalaşma zamanı yaklaştıkça 

Her şey yer değiştirir kahroluşlarla. 

Seninle geçen her an ayrı güzeldir ama 

Bir dahaki buluşmanın özlemiyle dolu 

O vedalaşma faslı olmasa. 

Senden ayrıldıktan sonra 

Özlem sarıverir her yanımı bir anda. 

İnan ki, içim kanar yaşamıyorum.

Elim elinde olmadıkça. 

Seni düşündüğümde 

Dertlerim geçit yapar birbiri peşi sıra. 

Tüm dertlerim sıkışır 

Kısacık anlara. 

Kahroluşları yaşarım 

Bir anda. 

Tutku dolu sıcaklığıyla 

Özlemiyle, bekleyişiyle 

Sevinciyle, hüznüyle 

Kısacası herşeyiyle 

Evet SEVGİLİM inan..

Bizim aşkımız varoluş kadar 

Güzel  olacak ...', 'Sana kavuşma saati yaklaşıyorsa  Sensizliğin burkluğunu yaşayan kalbim Sabırsızca çarpıyorsa.  Ellerim düşüncelerime hakim olup  Tüm şiirler...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/guzel-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıştan Sonra', 'ayrilistan-sonra-fatih-karacelik-wqe30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezinmişken yıllarca senin yamaçlarında,

Şimdi o günleri unutmaya çalışmak gaf olur.

Hayat bulurken hafızamdaki hatıralarında,

Vefasızlık cezası gönlüme atılan acı bir gam olur.

Ayrılık dolaşırken beynimin damarlarında,

Adımladığımız yamaçlar vuslatı beklediğim gar olur.

Gerçeği ararken söylediğin latif yalanlarında,

Yaşanılanlara isyan etmek için şimdi çok geç olur.

Bir zamanlar deli coşarken bile hülyalarında,

Gururum,onurum hislerime vurulan birer gem olur.

Yakalamışken tarifsiz duyguları sülün saçlarında,

Anılar saklanır saçlarındaki dalgalara, giz olur.

Firakı yaşatırken hayatımın en mes''ut anlarında,

Bana son sözün adeta ''ölüme koşarak git!'' olur.

Hüznü görünce garip sevdamın kara ufuklarında,

Kalbimde hiç umulmayan bir büyük göç olur.

Görünce hicranlı demleri gül misali yanaklarında,

Gözyaşım ceyhun olup coşar, etrafım göl olur.

Yürek acısı tomurcuklanırken hayat ağacımın dallarında,

Tomurcuklar meyvaya duramaz, onlar hep gök olur.

Yavaş yavaş hasret gösterirken kendini ati aynalarında,

Sevdamızın üzerinde bir kem bakışlı göz olur.

Mutsuzluğa alışırken sevdamın nahoş sıkıntılarında,

Artık geriye dönmek bu halden, bilsen ne kadar güç olur.

Ararken mutluluğu çiçeklerin günahsız tomurcuklarında,

Maşuk; gülizarımda açan bir kan kırmızısı gül olur.

Vuslatı hayal ederken kasvetin hırçın deryalarında,

Hayallerimdeki çark edişin belki güneşli bir gün olur.

Umutlarımı yaşatırken karasevdamın beyaz yarınlarında,

Yeşerip boy verir ümitlerim, görsen nasıl da gür olur.

Ey biçare!Yıllar var ki tutulduğun tüm sevdalarında,

Mazide olduğu gibi atide de yaşayacağın bir ayaz güz olur.

16/Haziran/1999-AHLAT', 'Gezinmişken yıllarca senin yamaçlarında, Şimdi o günleri unutmaya çalışmak gaf olur. Hayat bulurken hafızamdaki hatıralarında, Vefasızlık ce...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayrilistan-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedenlerin Arkasından', 'nedenlerin-arkasindan-fatih-karacelik-5ev2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir girdapdayım ki her yer ''neden?''.

''Nihayetb sonuna yaklaştım!'' derken,

Yenileri beydahlanıveriyor aniden,

Yıldızlar umutların üzerine düşerken.

Acılarımdan kopup gelen bir büyük çığlık,

Alıp götürdü düşlerimde her ne varsa meftalık.

Ufukların da arkasından görünen aydınlık,

Ulaşamadı umutlardaki yıldızlara bir anlık.

Kahrolup erisem de her defasında,

İsmimi görsem de semadaki idam tahtasında,

Umudumu hep saklarım yüreğimin ortasında;

Boğulsam da ''tarifsiz duygular'' deryasında.

27/Mayıs/1995-İZMİR', 'Bir girdapdayım ki her yer ''neden?''. ''Nihayetb sonuna yaklaştım!'' derken, Yenileri beydahlanıveriyor aniden, Yıldızlar umutların üzerine düş...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nedenlerin-arkasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Şehr-i Ramazan', 'ey-sehr-i-ramazan-fatih-karacelik-61289', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasip olur mu bir daha kavuşmak ey şehr-i ramazan?

İnanları bırakıp gidiyor musun ey şehr-i ramazan?

Müslümanlar, camiye seller gibi akıp dolarken,

Onları dertlendirip gidiyor musun ey şehr-i ramazan?

Nefesler günlerdir, cennetler gibi kokarken,

Nefesleri kesip gidiyor musun ey şehr-i ramazan?

Gönüller Yaradan''ı hatırlayıp deliler gibi ağlarken,

Ağıtlara aldırmayıp gidiyor musun ey şehr-i ramazan?

Diller, Sen''in hürmetine mahkumlar gibi kelepçelenirken,

Kelepçeleri kırıp gidiyor musun ey şehr-i ramazan?

Bülbüller her daim aleme rahmet ismini şakıyorken,

Bülbülleri susturup gidiyor musun ey şehr-i ramazan?

Güller mübarek ismini tomur tomur açıyorken,

Gülleri soldurup gidiyor musun ey şehr-i ramazan?

Seccadeler gözyaşlarıyla ıslanıp adeta yıkanıyorken,

Seccadeleri kaldırıp gidiyor musun ey şehr-i ramazan?

Zalimler de korkularından susmuş dururlarken,

Zalimleri coşturup gidiyor musun ey şehr-i ramazan?

Şeytan utancından fizanlara kaçıp giderken,

Şeytanı çağırıp gidiyor musun ey şehr-i ramazan?

Geceler zamanın en güzel Nurlarıyla aydınlanırken,

Ortalığı karartıp gidiyor musun ey şehr-i ramazan?

İnsanlar kendilerini yeni yeni bulmuşken,

Herşeyi tersine çevirip gidiyor musun ey şehr-i ramazan?

Eller gece-gündüz dua etmekten karıncalanırken,

Elleri indirip gidiyor musun ey şehr-i ramazan?

Evler Kutsal Şifa ile her gün şenlenirken,

Evleri mahsun edip gidiyor musun ey şehr-i ramazan?

Melekler başımızın üzerinde pervane olurken,

Melekleri kovup gidiyor musun ey şehr-i ramazan?

Kalplerimiz İslam''ı yeni yeni iştimal ederken,

Kalpleri burkup gidiyor musun ey şehr-i ramazan?

Peygamber sevdası garip gönlümüzü sararken,

Karasevdaya düşürüp gidiyor musun ey şehr-i ramazan?

Yaradan korkusu kan diye damarlarda  dolaşırken,

Damarları koparıp gidiyor musun ey şehr-i ramazan?

Yer ve gök, ins ve cin Yaradan''a yalvarırken,

Bizleri bırakıp gidiyor musun ey şehr-i ramazan?

Divane Fatih hüznünü kağıda dökerken,

Sen, Yaradan''ın yanına mı gidiyor ey şehr-i ramazan?

24/Şubat/1996-İZMİR', 'Nasip olur mu bir daha kavuşmak ey şehr-i ramazan? İnanları bırakıp gidiyor musun ey şehr-i ramazan? Müslümanlar, camiye seller gibi akıp do...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ey-sehr-i-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atim Gelir', 'atim-gelir-fatih-karacelik-sohyd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah gençliğim!Efsaneydik nasıl yıkıldık?

Gül-i zarda güllerdik haince yakıldık.

Kıyamdaydık da sanki yerlere çakıldık.

Bir devrin yaralarından hala kan gelir!

Boğuldu medeniyet çukurunda millet.

Medniyet uğruna hep cefa hep zillet...

Yenen dayaklara feryadımız pek kıllet.

Mazlumun da konuşacağı bir an gelir!

Bizdendiler de bize düşmandı özleri.

Karanlığa aşina ettiler gözleri.

Dudaktayken daha boğdular sözleri.

Atim! Yine de aklıma hüsn-ü zan gelir!

Susar da ecdad sanırsın sanki bi-karar.

Bu sukunet beynimi kıvrım kıvrım sarar.

Bir ömür boyu ağlasam neye yarar.

Ülkemin gecesine seninle tan gelir!

Bitsin artık yıllarca çektiğimiz elem.

Yeter olsun zuhruna duyduğumuz özlem.

Görsün Altın Nesli, çamurda yüzen alem.

Elbette bir gün hayallerime can gelir!

Sökün et; kalmasın ülkemde ziftli bozkır.

Dimdik dur ayakta, bütün gerçeği haykır!

Boynumdaki altın laleli tasmayı kır.

Asım!Atime ancak sizinle şan gelir!

16/Kasım/1999-İZMİR', 'Ah gençliğim!Efsaneydik nasıl yıkıldık? Gül-i zarda güllerdik haince yakıldık. Kıyamdaydık da sanki yerlere çakıldık. Bir devrin yaralarında...', ARRAY['Türk Edebiyatı','Şiir','Fatih Karaçelik']::text[], 8.5, '{"poet":"Fatih Karaçelik","poet_slug":"fatih-karacelik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/atim-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Sevdalı', 'yorgun-sevdali-nergiz-kartal-cs220', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yorgun sevdalıyım

kopmak isterim şu erin geceden

karşımda yorgun deniz 

bir şeyler anlatır istemeden

bir yaprak hışırtısı bir dalga sesi

uyandırır beni daldığım düşünceden

ben yorgun sevdalı 

karşımda yorgun kelimeler

adını ararım her bir heceden 

ve 

bulmak isterim gece bitmeden

                                           1988

                                       kurucaşile', 'Bir yorgun sevdalıyım kopmak isterim şu erin geceden karşımda yorgun deniz  bir şeyler anlatır istemeden bir yaprak hışırtısı bir dalga sesi...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yorgun-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim', 'secim-poet-of-the-darkness-u3oca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur oldum aktım yeryüzüne

Çaresiz bir yalvarıştım belki de

Ben, boşluğu tatmayı

Ben, ağlayabilmeyi istedim bu gece.

*

Söz verdim umut dolu düşlere

Ve sadece sarıldım kendime

Ben, unutmayı

Ben, gerçeği bekledim bu gece.

*

Bir kayalığın tepesinde yöneldim gökyüzüne

Çiviler çakıldı suçlu ellerime

Ben, yaşam yalanını

Ben, gölgeleri anladım bu gece.

*

Bu gece, yeni bir sayfa açıldı önüme

Ve kanımı akıttım üstüne

Ben, ben olmayı

Ben, ölmeyi seçtim bu gece.', 'Yağmur oldum aktım yeryüzüne Çaresiz bir yalvarıştım belki de Ben, boşluğu tatmayı Ben, ağlayabilmeyi istedim bu gece. * Söz verdim umut dol...', ARRAY['Türk Edebiyatı','Şiir','Poet Of The Darkness']::text[], 8.5, '{"poet":"Poet Of The Darkness","poet_slug":"poet-of-the-darkness","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/secim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Anlamı', 'hayatin-anlami-poet-of-the-darkness-7grle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçekler kokmaz gibi gelir hani 

Gözlerin görmez, kulaklarin da duymaz. 

Sadece rüzgarin yüzüne çarpisini hissedersin. 

Ayaklarina hakim olamazsin hani 

Seni alip huzura götürüsünü seyredersin. 

Insanlara uzanirsin ama kimse seni farketmez, 

Haykirmak istersin sesin kisilir, 

Yalvarirsin ama kimse seni istemez. 

Iste o zaman hayatin anlamini anlayacaksin 

Ve o günün gelmesi için diz çökeceksin. 

Sen de gölge olacak, bir bedene saplanacaksin 

Ve kabus olacak her saniyen 

Tipki benim sen, senin de ben olman gibi...', 'Çiçekler kokmaz gibi gelir hani  Gözlerin görmez, kulaklarin da duymaz.  Sadece rüzgarin yüzüne çarpisini hissedersin.  Ayaklarina hakim ola...', ARRAY['Türk Edebiyatı','Şiir','Poet Of The Darkness']::text[], 8.5, '{"poet":"Poet Of The Darkness","poet_slug":"poet-of-the-darkness","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayatin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Cok Seviyorum', 'seni-cok-seviyorum-bundy-burak-29rzi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kulagina usulca ''seni seviyorum'' diye fisildarsin,

O an senden mutlusu yoktur...

Hani ayrilik vakti gelir ya,

Gozlerin yasla dolar,

Seni istemedigini haykirir,

O an tipki bir yasayan olusundur,

Bir daha onu goremeyecegini anlarsin,

Telefonda sabahlayamiyacaginiz anlar gelmistir,

O artik seni umursamiyor,sevmiyor.

Daha ne burda duruyorsun ki artik bu hayat anlamsiz,

Hadi daha fazla bekleme burda isin kalmadi....

Seni cok seviyorum Zeynep Yilmaz!!!', 'Kulagina usulca ''seni seviyorum'' diye fisildarsin, O an senden mutlusu yoktur... Hani ayrilik vakti gelir ya, Gozlerin yasla dolar, Seni ist...', ARRAY['Türk Edebiyatı','Şiir','Bundy Burak']::text[], 8.5, '{"poet":"Bundy Burak","poet_slug":"bundy-burak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-emin-acikgoz-d0dsc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni son kez alnından öptüm İstanbul

Giderken bir dolunay vardı peşimde

Yağdıkca gözlerime yağmur

Hasret vurmaya başladı pencereme

Her çizgi bir bitiş yada başlangıç

Her yalanda bir doğruydu aslında

Yıllarca bir tutku için yaşadım

Kendime bir sır verdim onuda tutamadım', 'Seni son kez alnından öptüm İstanbul Giderken bir dolunay vardı peşimde Yağdıkca gözlerime yağmur Hasret vurmaya başladı pencereme Her çizgi...', ARRAY['Türk Edebiyatı','Şiir','Emin Açıkgöz']::text[], 8.5, '{"poet":"Emin Açıkgöz","poet_slug":"emin-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-fatih-avci-gxtam', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşk bahçesinde

sen bir bülbülsün

bülbüllerin içinde sen en güzel ötenisin

cennet bahçesinde

sen bir hurisin

hurilerin içinde 

sen en güzelisin

benim minik bahçemde

sen bir gülsün

koparmaya kıyamadığım

koklamaya korktuğum

bir gülsün sen.....', 'aşk bahçesinde sen bir bülbülsün bülbüllerin içinde sen en güzel ötenisin cennet bahçesinde sen bir hurisin hurilerin içinde  sen en güzelis...', ARRAY['Türk Edebiyatı','Şiir','Fatih Avcı']::text[], 8.5, '{"poet":"Fatih Avcı","poet_slug":"fatih-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Dedim de Seni Hatırladım', 'i-stanbul-dedim-de-seni-hatirladim-umit-yasar-oguzcan-54qzn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte İstanbul

yorgun şehir

işte canından bezmiş boğaz vapurları

kederli tramvaylar

ve Galata Köprüsü''nden

telaşlı insanlar geçmektedir

bir gizli sevinç mahzun gözbebeklerimde

eriyen bir sükun kaldırımlarda adım adım

işte İstanbul

İstanbul dedim de seni hatırladım.

Balıkçı tepsilerinde gümüş balıkları

tekir,barbunya,canım uskumru,levrek

işte İstanbul

kulaklarımda bir derin uğultu

hiç bitmeyecek

karşıda kızkulesi

gözleri yaşlı bir kadın gibi

ve minareler çaresizliğimizi haykırmakta Allah''a

caddelerinde başım dönüyordu

gecelerinde ağladım

İstanbul,o büyük şehir

o mahzun şehir

İstanbul dedim de seni hatırladım.

Boğaz içinden bir vapur geçer

benim aklımdan senin gözlerin geçiyordu

-Bebek, dediler indim

nereye baksam denizdi

mavi mavi bir hüzündü ayaklarımın altında

işte İstanbul

Haliç,

Çiçek Pasajı,

Beyoğlu...

Beyoğlu''nun daracık sokaklarında seni aradım.

İçim ürpertilerle dolu,amansız korkularla

İstanbul dedim de seni hatırladım.', 'İşte İstanbul yorgun şehir işte canından bezmiş boğaz vapurları kederli tramvaylar ve Galata Köprüsü''nden telaşlı insanlar geçmektedir bir g...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/istanbul-dedim-de-seni-hatirladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım', 'sultanim-ozcan-unlu-jr7gj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi bu şehrin çatılarında

Yağmur damlalarıyla dansediyor hayalin

Bulanık sulardaki resmini

Hatıralara uğurluyorum.

Sensizlik,ah sensizlik soğuk bir duş

Gibi yokluyor adımlarımı

Nefesimi bağışlıyorum,kabul etmiyor

Dilencilere sığınan aşkımı istiyor

Gri şehrin balkonlarına asılmış

Bir çift güvercin gözü.

Minareler susuyor seni,ben konuşuyorum

Har olup kükrüyorum yalnızlığıma

Hani elin,kızgınlığımı okşayan

Yüzümü yalayan eşsiz nefesin.

Bu şehri sevmiyorum sultanım

Sokaklarını,evlerini,balkonlarını

Sevmiyorum aşktan mahrum bakışlarını.', 'Şimdi bu şehrin çatılarında Yağmur damlalarıyla dansediyor hayalin Bulanık sulardaki resmini Hatıralara uğurluyorum. Sensizlik,ah sensizlik ...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sultanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuyan Sevgili', 'uyuyan-sevgili-adil-koruyan-kys0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün doğuşunu izledim,

Karanlıktan aydınlığa geçişi.

Alacakaranlıkta önce düşledim,

Dağların ardındaki güneşi

Ve bir de seni.

Tepelerin ışıkla kucaklaştığı yerde,

Önce belirsizlikler şekillendi,

Ağır ağır ağardı tan yeri.

Yer gök renklendi.

O saatlerde uyuyordun belki,

Melekler gibi.

Gri gökyüzü dönüştü maviye,

Dağların üzerinde daha güneş yoktu.

Ama geleceğini bildiği için kaçışıyordu.

Karanlıklar, önce maviyi karşılıyordu.

Sevgili hala uyuyordu

26 Temmuz 2000', 'Gün doğuşunu izledim, Karanlıktan aydınlığa geçişi. Alacakaranlıkta önce düşledim, Dağların ardındaki güneşi Ve bir de seni. Tepelerin ışıkl...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uyuyan-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gün', 'o-gun-adil-koruyan-5tgtt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her zamanki gibi bir gündü, o gün.

Hala gözlerimin önünde,

İpeksi saçların ve yüzün.

Benliğimi esir alan gözlerinle

Sen diğerlerinden farklıydın.

Seni ilk gördüğüm andı, o an.

Kaçıramadım gözlerimi gözlerinden.

Bir şeyler söylüyordu gönülden,

Sadece sevenlerin  anladığı dilden. 

Konuşuyordu gözlerimiz içten,

Senin ben, benim sen olduğumdu o an.

O an, benim için durmuştu zaman.

Haykırmak istermişçesine bakışın,

Benim içimde kopan fırtınaların,

Savurduğu sevgi tohumlarının, 

Yeşerdiği andı o an.

Ben mi ulaşılamazdım senin için,

Yoksa sen mi ulaşılamazdın benim için.

                                   13 Ağustos 2000', 'Her zamanki gibi bir gündü, o gün. Hala gözlerimin önünde, İpeksi saçların ve yüzün. Benliğimi esir alan gözlerinle Sen diğerlerinden farklı...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/o-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer mi?', 'deger-mi-adil-koruyan-y47ar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevginle bir başına kalmak istiyorsun.

Düşündün mü hiç, değer mi?

Neden anlatamıyorum diyorsun?

Belki kaybetmekten korkuyorsun.

Mutluluğu hep acılarda  arıyorsun

Oysa sen sevmeyi seviyorsun.

Sevilmeyi, dostluğu, dürüstlüğü. 

Belki gerçek sevgiyi bulamıyorsun.

Göremiyorsun, o’na  uzanamıyorsun.

Üzülmeye değer mi sanıyorsun.

Sevgide, sevgiyi yaşamak varken,

Değer mi? Hiç düşünüyor musun?', 'Sevginle bir başına kalmak istiyorsun. Düşündün mü hiç, değer mi? Neden anlatamıyorum diyorsun? Belki kaybetmekten korkuyorsun. Mutluluğu he...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deger-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihçe', 'tarihce-serhan-serhan-7q66s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynı sabahın

ilk sıcak çayı gibi ferah

bir karşılaşma...

-Merhaba!

sonra güzel

ve en sıcak gülüşmelerin ev sahibi

bir yüz...

-Görüşürüz!

derken

sanki elin elimde

kem gözlere keder

dünya güzeli sohbetler

-Ara beni!

ardından

derimizin altına sızan

hani katiyen rakı içme mecburiyeti çağrıştıran

bir korku ki

-Eyvah!

ve şimdi

kalbimi karanlıklarda hançerleyen

aklımı başımdan eyleyen

çok uzun yollarda

hiç uykulu otobüs saatleri gibi

acıtan

kanatan

yani korktuğumuz

yani başımıza gelen

büyüdükçe büyüleyen

aşk...

-Seni seviyorum!

şimdi sen

kalbimin közünde kıvılcım kıvamında

ağrıyan...', 'aynı sabahın ilk sıcak çayı gibi ferah bir karşılaşma... -Merhaba! sonra güzel ve en sıcak gülüşmelerin ev sahibi bir yüz... -Görüşürüz! der...', ARRAY['Türk Edebiyatı','Şiir','Serhan Serhan']::text[], 8.5, '{"poet":"Serhan Serhan","poet_slug":"serhan-serhan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tarihce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir''im', 'siir-im-serhan-serhan-kyjee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siirim diyorum ona....

Bu sözü bir fazla hak ediyor

      bütün siirlerimden...

Yaban gülüm diyorum

  çılgınlığım

     vazgeçemediğim........

Birden güvercinli güvercinli

   Gülüyorum bak!!..............

Sevdamıza bir numara dar geliyor sanki simdi yeryüzü........

sanki......', 'Siirim diyorum ona.... Bu sözü bir fazla hak ediyor       bütün siirlerimden... Yaban gülüm diyorum   çılgınlığım      vazgeçemediğim..........', ARRAY['Türk Edebiyatı','Şiir','Serhan Serhan']::text[], 8.5, '{"poet":"Serhan Serhan","poet_slug":"serhan-serhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siir-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır', 'sifir-serhan-serhan-feycj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çember çizilse

Merkezinde ben

Kenarında sen

Sen döndükçe beni

Ben döndülçe seni görsem

Öyle bir an gelse ki

Yarı çap sıfır olsa.......!!!!!!!!!!!!!!!!!!!!!', 'Bir çember çizilse Merkezinde ben Kenarında sen Sen döndükçe beni Ben döndülçe seni görsem Öyle bir an gelse ki Yarı çap sıfır olsa.......!!...', ARRAY['Türk Edebiyatı','Şiir','Serhan Serhan']::text[], 8.5, '{"poet":"Serhan Serhan","poet_slug":"serhan-serhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sifir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Saklayacagım', 'seni-saklayacagim-serhan-serhan-q6n45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni saklayacağım inan

Yazdıklarımda, çizdiklerimde,

Şarkılarımda, sözlerimde.

Sen kalacaksın kimse bilmeyecek

Ve kimseler görmiyecek seni,

Yaşayacaksın gözlerimde.

Sen göreceksin, duyacaksın

Parıldayan bir sevi sıcaklığı,

Uyuyacak, uyanacaksın.

Bakacaksın, benzemiyor

Gelen günler geçenlere,

Dalacaksın.

Bir seviyi anlamak

Bir yaşam harcamaktır,

Harcayacaksın.

Seni yaşayacağım, anlatılmaz,

Yaşayacağım gözlerimde;

Gözlerimde saklayacağım.

Bir gün, tam anlatmaya...

Bakacaksın,

Gözlerimi kapayacağım...

Anlayacaksın.', 'Seni saklayacağım inan Yazdıklarımda, çizdiklerimde, Şarkılarımda, sözlerimde. Sen kalacaksın kimse bilmeyecek Ve kimseler görmiyecek seni, ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Serhan']::text[], 8.5, '{"poet":"Serhan Serhan","poet_slug":"serhan-serhan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-saklayacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimizi Unuttuk', 'kendimizi-unuttuk-elif-gultekin-zhnp9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir yaşanan bu karmaşa,

Nereye koşuyoruz?

Bu yolun sonunda ne var söyleyin bana,

Yaşamayı bile unutturacak ne olabilir?

Siz çimlerde yuvarlanmanın ne olduğunu bilir misiniz?

Ya geceleri yıldızları izlemenin?

Ne zamandır bir bir gülü koklamıyorsun?

Ne zamandır çıplak ayalarınla toprağa basıyorsun?

İçine egzoz gazını çekerek,

Komşuna selam bile vermeden,

Yıldızları izlemeden,

Kara topğrağa gidiyorsun

Sen hiiiç yaşamıyorsun 

Git gide ölüyorsun.', 'Nedir yaşanan bu karmaşa, Nereye koşuyoruz? Bu yolun sonunda ne var söyleyin bana, Yaşamayı bile unutturacak ne olabilir? Siz çimlerde yuvar...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kendimizi-unuttuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Çocuk', 'i-cimdeki-cocuk-elif-gultekin-ho6ts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimdeki çocuk,

Ben büyüdükçe yaramazlaşıyor,

Daha bi hırçın oluyordu sanki

Ben büyüdükçe içimdeki çocuk küçülüyor,

Kalbim yerinde duramıyordu.

Ama ben yaşlanınca o da beni ter etti

Tıpkı diğerleri gibi...', 'İçimdeki çocuk, Ben büyüdükçe yaramazlaşıyor, Daha bi hırçın oluyordu sanki Ben büyüdükçe içimdeki çocuk küçülüyor, Kalbim yerinde duramıyor...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icimdeki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-elif-gultekin-wke7l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir çift sevgili görsem,

İçim sevinçle dolar  sen aklıma gelirdin.

Ne zaman bir ayrılık görsem,

İçim suçluluk dolar ben aklıma gelirdim.', 'Ne zaman bir çift sevgili görsem, İçim sevinçle dolar  sen aklıma gelirdin. Ne zaman bir ayrılık görsem, İçim suçluluk dolar ben aklıma geli...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşların Akmasın', 'gozyaslarin-akmasin-aziz-pinar-ns6d4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudağında öpülsün akarsa gözyaşların.

Kederi,ızdırabı görmesin bakışların. 

Mutluluk senin için,sevgiler senin için.

Dudağında öpülsün akarsa gözyaşların.

Düşmesin saçlarına sonbahar yaprakları,

Değmesin yanağına acının rüzgarları,

Doyurmasın kolların o soğuk toprakları,

Dudağında öpülsün akarsa gözyaşların.

Güneş aydınlığında parlak yolların olsun.

Gölgeler,karanlıklar ışığında boğulsun.

Çiçeklerden bir demet rüyalarına dolsun

Dudağında öpülsün akarsa gözyaşların.', 'Dudağında öpülsün akarsa gözyaşların. Kederi,ızdırabı görmesin bakışların.  Mutluluk senin için,sevgiler senin için. Dudağında öpülsün akars...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozyaslarin-akmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Rüzgarı', 'col-ruzgari-sedat-yukseker-kmr3o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi tohumları ektim

kalbin çölüne,

kin büyüdü.

Hasadı perişan olmuş

her kalpte kendini bulur

çöl rüzgarı.

Kurutur benliğini

Ve geriye kahrolası bir aşkın,

sevgi kırıntıları kalır.', 'Sevgi tohumları ektim kalbin çölüne, kin büyüdü. Hasadı perişan olmuş her kalpte kendini bulur çöl rüzgarı. Kurutur benliğini Ve geriye kahr...', ARRAY['Türk Edebiyatı','Şiir','Sedat Yükseker']::text[], 8.5, '{"poet":"Sedat Yükseker","poet_slug":"sedat-yukseker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/col-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''e', 'deniz-e-sedat-yukseker-05zwe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana, 

seni binlerce kez seviyorum

demek isterdim 

ama söyleyemedim.

öyle bir hal olduki

bir yanardağ gibisin,

yaklaşsam ateşin beni sarıyor,

uzaklaşsam üşüyorum.

Ve ben hala

seni seviyorum', 'Sana,  seni binlerce kez seviyorum demek isterdim  ama söyleyemedim. öyle bir hal olduki bir yanardağ gibisin, yaklaşsam ateşin beni sarıyor...', ARRAY['Türk Edebiyatı','Şiir','Sedat Yükseker']::text[], 8.5, '{"poet":"Sedat Yükseker","poet_slug":"sedat-yukseker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deniz-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın Daraltı', 'yangin-daralti-necdet-yildiz-wjp6l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmezsin sen, noksandır benim ağzım

Boğuk az ve kırıktır sevdalarım

Katran içre şımarık daraltı ve boğaz

yaz!

Ne varsa çaresiz ciğerlerimde eksik

Hava delik, gırtlağım yenik, yangınlarda tenim

sar biraz!

Suretim çeyrek, nefesin vadeli

Muhtacım, tamamla beni!

yan biraz!', 'Bilmezsin sen, noksandır benim ağzım Boğuk az ve kırıktır sevdalarım Katran içre şımarık daraltı ve boğaz yaz! Ne varsa çaresiz ciğerlerimde...', ARRAY['Türk Edebiyatı','Şiir','Necdet Yıldız']::text[], 8.5, '{"poet":"Necdet Yıldız","poet_slug":"necdet-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yangin-daralti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Bulutu', 'kus-bulutu-metin-vural-4nyd9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden bahar

Yine seninleyim işte,

Dağıldı kara bulutlar

Hayır varmış bekleyişte.

Düşlerim mavi bugün

Umudum yeşil

Yedi renk üstüne dünyam

Siyah umurumda değil.

Başımın üstünde bir kuş bulutu

Buluta değiyor başım

Mutluluktan uçuyorum

Pembe umutlar yoldaşım

Bir an bile sürse bu düş

Bir ömre bedeldir bence,

Aradığım bir tek gülüş

Bir olmak değil bedence', 'Bugün günlerden bahar Yine seninleyim işte, Dağıldı kara bulutlar Hayır varmış bekleyişte. Düşlerim mavi bugün Umudum yeşil Yedi renk üstüne...', ARRAY['Türk Edebiyatı','Şiir','Metin Vural']::text[], 8.5, '{"poet":"Metin Vural","poet_slug":"metin-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kus-bulutu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Olduk İkimiz', 'bir-olduk-i-kimiz-metin-vural-c4kwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel, gözümden içeri

Süzüldü, gönlüme girdi

İçimdeki karanlığı

Gökkuşağına çevirdi.

Aydınlığı tuttum biraz

Avcuma sığmadı taştı,

Bunca sevgi, bunca niyaz

Sonunda dağları aştı.

Sevişirken eridik biz

Sevdaların potasında,

Artık bir olduk ikimiz

Cennetin tam ortasında.', 'Güzel, gözümden içeri Süzüldü, gönlüme girdi İçimdeki karanlığı Gökkuşağına çevirdi. Aydınlığı tuttum biraz Avcuma sığmadı taştı, Bunca sevg...', ARRAY['Türk Edebiyatı','Şiir','Metin Vural']::text[], 8.5, '{"poet":"Metin Vural","poet_slug":"metin-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-olduk-ikimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam İletişim', 'tam-i-letisim-omer-sevincgul-iyqkk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle iletişimim tek yönlü olmadı. 

Bunu bir örnekle anlatayım istersen. 

Ben bir merkezim, sen de küresin. 

Senin tam ortandayım, ya da sen beni tamamen kuşatmışsın. 

Küreyi, yani seni oluşturan her noktadan sesleniyorsun, sesin bana, merkeze geliyor, her yönden. 

Her yönden mi? Yön yok ki artık. 

Sana nasıl arkamı dönebilirim, ne yana dönsem yönüm yine sana dönük olacak. 

Ya da, sen topraksın, ben denizim. 

Çırpınıyor, coşuyor, dinmeyen bir tutkuyla sana atılıyor, dalga parmaklarımla hep sana dokunmak için çabalıyorum.', 'Seninle iletişimim tek yönlü olmadı.  Bunu bir örnekle anlatayım istersen.  Ben bir merkezim, sen de küresin.  Senin tam ortandayım, ya da s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tam-iletisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dehliz', 'dehliz-omer-sevincgul-08utw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ardarda kapılar

derunumdalar

en dipte bir kapı

ardında sırrım saklı

kimselere söyleyemem

söylersem

önce sen!

yanarım

içim duman

kıvranırım

halim yaman

dil suskun

gözlerimse dil

konuşur damla damla

ve zaman zaman

dehlizlerinde kaybolmuşum ruhumun

sezilmedik duygular 

keder belli

nedir kader

nerde bekler

bilmiyorum', 'ardarda kapılar derunumdalar en dipte bir kapı ardında sırrım saklı kimselere söyleyemem söylersem önce sen! yanarım içim duman kıvranırım h...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dehliz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak İstiyorum', 'unutmak-i-stiyorum-gulay-atilay-26ro8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allahım feryadımı artık duysan diyorum

Yaşadığım kadere yeterrrr!! isyan ediyorum

Bağlanmışım aşk zinciriyle ben çözemiyorum

Ölmek istiyorum bir türlü ölemiyorum

Revamı? sadece sevdim ne günah işledim?

Kaderimmi elem tasa gam kasvet dedim.

Böylemi gelmiş hep böylemi gider?

Elbet bir gün diyecektim artık yeterrr!!!!!

Dünyanın kanunumu nizammı töremi bu?

Biiçare gönlümü perişan derbeder eden

Bir gün bende sevilirim diye beklerken

Bak ölüyorum coşkuyla yaşamak isterken

Birini çok sevdim o hiç sevmedi

Birini özledim o özlemedi

Üzüldüm incindim o incinmedi

Var olmak istedim hep onun için

Yok olmak istiyorum  acı verdiği için..

Bırakıpta giti mutlu mu bilmem 

Mesut olsun yeter inşizar etmem 

Kapkara oldu dünyam yokluğunun ardından

Ne zaman akşam olsa bu son gecem diyorum

Vazgeçtim yalan dünyanın sahte dostluklarından

Yeterrr!! bunca  keder bunca elem diyorum

Yitirdim tüm umut kırıntılarımı

Sevincimi neş''emi tüm mutluluğumu

Sonsuz bir boşluğun içindeyim ben

Yenik düştüm sevdiceğim neyleyim.

İçip bir kupa zehir

Vadettiğin mutluluğumu

Yitirdiğim umutlarımı 

Çektirdiğin acılarımı ..

UNUTMAK İSTİYORUM!!!!!....

15 AĞUSTOS 2000 /ERENKÖY', 'Allahım feryadımı artık duysan diyorum Yaşadığım kadere yeterrrr!! isyan ediyorum Bağlanmışım aşk zinciriyle ben çözemiyorum Ölmek istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/unutmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karış Karış Mukaddes', 'karis-karis-mukaddes-i-lhan-yuksel-lyoa9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mukaddessin toprağim kariş kariş mukaddes

bayrağinla ta arşa yükselen hilal gibi

kan gibi kirmizi bayrak üstünde al gibi

senin için savaş mukaddes bariş mukaddes 

erzurumda sivasta doğan güneş mukaddes

yükselen minareler ta Edirne''den Kars''a

herşeyin mukades vatan herşeyin ne varsa

yerde yatan şehit topragini des mukaddes', 'mukaddessin toprağim kariş kariş mukaddes bayrağinla ta arşa yükselen hilal gibi kan gibi kirmizi bayrak üstünde al gibi senin için savaş mu...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karis-karis-mukaddes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ki Geceydi', 'tut-ki-geceydi-osman-erdal-erturan-2icid', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tut ki geceydi

ve sonbahar

ve sen yağmurdun

(15-08-2000 Bartın)', 'tut ki geceydi ve sonbahar ve sen yağmurdun (15-08-2000 Bartın)...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tut-ki-geceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Düş Olsun Ki', 'oyle-bir-dus-olsun-ki-tolga-baydar-reuly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yemyeşil bir bahçe düşle hayatında ey sevdiceğim

Rengarenk çiçekler olsun yanında, kıyısında, köşesinde

Bir de Kevser misali akan derecik olsun olmuşken

Düşle ki gerçek olsun, seninle birlikte gezeceğim

Kuşlar en güzel şarkılarını okurken bu bahçede cananlarına

Düşle ki ben can oldum geldim yanına

Ve gökyüzü en güzel parıltısını sunarken ikimize

Lezzetini tadalım kokladığımız havanın

Sen bana, ben sana yaslanıp

Düşlere dalalım

Öyle bir düş olsun ki bu sevdiceğim

Seni sevdiğimi söyleyebileyim...', 'Yemyeşil bir bahçe düşle hayatında ey sevdiceğim Rengarenk çiçekler olsun yanında, kıyısında, köşesinde Bir de Kevser misali akan derecik ol...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oyle-bir-dus-olsun-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldir Aydınlık', 'ne-guzeldir-aydinlik-tolga-baydar-jwmar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökkubbe neden mavi olsun ki

Çevrelensin simsiyah bir çerçeve ile

Bembeyaz akan ırmak

Suladığı çam ormanı

Karalara bürünsün

Mor bulutlar sarsın her tarafı

Yağan yağmur bile koyu bir renk

Simsiyah

Karanlık.....

Söyleyin güneşe doğmasın bu gün

Ay da saklansın, çıkmasın ortaya

Şavkını vurmasın yeryüzüne

Santraller sussun, çalışmasın

Üretilmesin bilmem kaç kilovatsaat elektrik

Üretilmesin ki yanmasın evlerde ampul

Sokak lambaları da çalışmasın

Simsiyah

Karanlık....

Suratını assın insanlar, gülmesinler

Merhabalaşmasınlar hiç bir zaman

Hal hatır sormasınlar, ne var ki

Komşu bilmesin komşusunu

Beriki görsün, ötekinin somurttuğunu

Dizi üzeri oturup acısını hissetsin

Farketsin sandalyenin yokluğunu

Simsiyah

Karanlık.....

Üzüldün mü, darıldın mı, gücendin mi

Söylese be insan sıfatı taşıyan ben

Sana soruyorum hey ben, kalemimden çıkan

Yoksa yüzleşmek ağırına mı gitti

Sen yazdın bunları kendi yüzün gibi siyah ve yazdın ki

Anlaşılsın güzelin ne güzel olduğu

Ve sarsılıp kendine dönsün insanoğlu

Simsiyah

Karanlık....

Bembeyaz

Ne güzeldir aydınlık........', 'Gökkubbe neden mavi olsun ki Çevrelensin simsiyah bir çerçeve ile Bembeyaz akan ırmak Suladığı çam ormanı Karalara bürünsün Mor bulutlar sar...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ne-guzeldir-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'paronayak', 'paronayak-atilhan-buyuksel-sqi49', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben paronayak vatanda&şorn;

nedense yılanlara düşmanım

severim gökte leyleği

yerde kurt ciğerim canım

korur toprağımı domuzdan

şu insafsız avcının itine

daha serttir çoğumuzdan

aç sabırlı ve hürdür yine

ne bir tefecinin itini

ne yeraltında yılanı hoşgörür

hem bunu tanır hem ötekini

dağda bin yil yaşamış hür

ne yılanlarin demokrasi yalanı

ne bekciliği itlerin

ne ite teslim talanı

ne hokkabazlığı kandırır

ucuz kahraman yiğitlerin

aç kalır sabırlı ve hürdür yine', 'ben paronayak vatanda&şorn; nedense yılanlara düşmanım severim gökte leyleği yerde kurt ciğerim canım korur toprağımı domuzdan şu insafsız a...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/paronayak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marallar Oymağında Bir Ceylanla Oturup Ağlamak', 'marallar-oymaginda-bir-ceylanla-oturup-aglamak-hasan-ejderha-5o0t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüznünü dağlara savuran

senin kırılgan

ürkekliğin yok mu ceylan

ruhumu kanatlandıran

an be an kaçmaya hazır haline

ne aşklar susadı

Ahh ceylan

ürkek aşkların zarif sultanı

karanlıkları silen aydınlığını

saklama dağlardan

senin gözlerinden kopan

bir deniz boğulur bende

merhametin ziyası sende parlar

güzellik sende kanat açar göklere

Beni böyle koşturan arkandan

bir avcılık halidir sanma n''olur

aşka uçan turnalar içimde kanat vurur

denizler içimde kudurur

okyanuslar içimde durulur

sana aşık her avcı içimde vurulur

İn ovalara ceylan

bu yürekle sana haykıran

en soylu ağıtları sunmalıyım

Bir tel hıçkırır derinden

gözlerinden kopan bir damla yaş aşkına

bir yiğit ölür pusuda haybeden

yapılar yükselir göğe şehirlerden

ağır yükler altında sokaklar erir

binlerce insan binlerce yalnızlığı emzirir

İn ovalara ceylan

buralarda yaşanmaz  sensiz

şehirler kurmalıyız ceylanlar gezinen

kuşlar uçmalı göklerinde şehrimizin

marallar olmalı sokak başlarında

körpe yavrularını emziren

şaşırıp kalmalı avcılar iz sürerken

Ay ceylan

Boynumda bir vebaldir çağın insanı

kirlerinden oluşmuş zamanın lisanı

her şeyin üstünde işgal var

bunalıyorum ay ceylan

içinden çıkamadığım bir hal var

ya sen balalar balası

yüreğinde ateş, gözlerinde hilal var

Sen ve ben ceylan

cerenler bizi izlerken yükseklerden

asrın çizgilerini çizmek üzre

hayatı hüznolan turnaların

aşkına denk bir aşkla

çeteleler tutmalıyız yine aşklara dair

Ceylan ceylan

hüznünde beni an

senden aldığım yaralardandır

yüreğimden sızan kan

Sen sultansın nazlan ceylan

Yürekler kanatan naz var sende

Kıtalara yayılan yaz var sende

Bir kurşunla hazan olan güz var sende

Her hücremde gezinen iz var sende

Yüreğime sürekli batan biz var sende

Sen sultansın nazlan ceylan

Senden aldığım yaralardandır

Yüreğimden sızan kan.', 'Hüznünü dağlara savuran senin kırılgan ürkekliğin yok mu ceylan ruhumu kanatlandıran an be an kaçmaya hazır haline ne aşklar susadı Ahh ceyl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/marallar-oymaginda-bir-ceylanla-oturup-aglamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuh(a.s)Duası', 'nuh-a-s-duasi-atilhan-buyuksel-wnh2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nefer nefer kırdırıyor

kahbe bizans ama görki

yobaz bile hain diyor

bir iftira ediyorki

derin derin devleti var

hürriyeti bile yalan

bir asrı böyle oyalar

kıpti fravundan kalan

kaba softasın ham yobaz 

ruma oyuncak gibisin

alim geçinen hokkabaz

bizansa bitim bitimsin

her safta sen en ön safta

ahkam senindir senin laf

her vakitte sen her hafta

uyanık geçin bu halk saf

bize karşı savaşçısın

cıfıta suskun bırakcı

en ağırdan yavaşçısın

tefeciye ayakçısın

hain deyip sataşmaya

hazır bombalı itlisin

cıfıta kibrit çakmaya

eli bağlı kilitlisin

mezhebini sor yörükten

valide nesep arama

cıfıt tefeci sülükten

cumayı olsun sorama

fahşa arar nefsimizde

benim avanah yobazım

manukyanda değil bizde 

kusurmu var bah yobazım

birimizde kusur bulsa 

tatmin olur keyiflenir

uyananı ya bulursa 

artar kini hayıflanır

gerek imiş nefsi ıslah

nefis ıslah olsa deki

bulurmu ya bu halk felah

cıfıt mason başta peki

katil olduk öldü nefis

kerhanecisi ölürmü

nefsi ıslah diyerek biz 

daha geçsin bin ömürmü

beş bin yıldır fahişeye 

tapan millet arapmıydı

rum kültürü diyen niye

fars kültürü serapmıydı

fuhuş tefe fitne deki

türkün kürdün içindenmi

kerhane işleten peki

meslek bizans piçindenmi

en zehirsiz kerhaneci

zehirlisi müsteşardır

daha zehirlisi elçi

hain brokrati vardır

pontus savcı kuvvetiyle

fahişenin emniyeti

derin derin devletiyle 

galata bizansın iti

bekçi olaıdın akile

öne geçmeyip yobazım 

akllımı bile bile

kırdılar kış oldu yazım

bunları diyemedin de 

samimi olduğun bilem

yetmiş yıl nefis dedinde

yetmiş yıldır yine elem

sanma bu millet değişmiş 

Nuhtan beri değişmeyiz

şu içimize siiğişmiş 

ne sodom değişmiş ne biz

o millet nuh(nebi) duasında

demiş deyyar olmasın rab

fesat vardır doğasında

kainatı eder harab

kim bu nesil deyyar olur

fuhuş fucur fitne tefe

doğsa sülbü kuffar olur

halef tabidir selefe', 'nefer nefer kırdırıyor kahbe bizans ama görki yobaz bile hain diyor bir iftira ediyorki derin derin devleti var hürriyeti bile yalan bir asr...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/nuh-a-s-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğin Duası', 'cicegin-duasi-ferah-guneri-bircan-62zb2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Her çiçeğin bir duası vardır tanrıdan)  

Gariptir,

Kimsesizdir,

Yapayalnızdır,

Meçhule uzanan tarlada; 

Uzanacak kolu,

Yürümesi için bacakları,

Hiç olmadı; 

Sulanmazsa kuruyabilir,

Çiğnense ezilebilir,

Su baskınında ise,

Çürüyebilirdi; 

Ama olsun,

Kıymeti yoktu bunların,

Bir tek duası vardı tanrıdan:

O arı! 

Bir tek ona,

Sonsuza dek,

Ona konsun.', '(Her çiçeğin bir duası vardır tanrıdan)   Gariptir, Kimsesizdir, Yapayalnızdır, Meçhule uzanan tarlada;  Uzanacak kolu, Yürümesi için bacakl...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cicegin-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namaste', 'namaste-ferah-guneri-bircan-bljh8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Aşkıma....)  

Sendeki sen:

Tez canlılığın,

Zihninde; 

Üretkenliğin, 

Tevekkülünde; 

Sevgin,

Diyalektiğinde; 

Bedenin,

Ekmeğinde; 

Sabrın,

Ademden ötede; 

Yakıtın,

Yaşadığın çağın,

Unutulan değerlerinde; 

Geleceğin ise,

Yalnızca,

Yüreğinde! 

Anlaşılman ise,

Familyan bireylerinin,

İkra nispetinde; 

Ya bendeki sen,

Her karşılaşma ve vedalaşmada,

Eller önde kavuşturulup,

Denilse de:

Hindistan’da NAMASTE! 

Diğer bir değişle,

“İçinde olan,

Ve tüm evrenin yaşadığı,

O yeri! 

İçimde olan,

Ve tüm evrenin yaşadığı,

O yerden! 

Saygıyla selamlarım,”

Türkçe’siyle; 

Ben! 

Ellerimi açarak, 

Bir ömür,

Tüm evrenin,

Yaşadığı o yerleri,

Bir’e indirerek,

Yaşamak isterim,

Seninle.', '(Aşkıma....)   Sendeki sen: Tez canlılığın, Zihninde;  Üretkenliğin,  Tevekkülünde;  Sevgin, Diyalektiğinde;  Bedenin, Ekmeğinde;  Sabrın, A...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/namaste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-ferah-guneri-bircan-4d3fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(tebessümsüz yaşayanlara...) 

Okyanus kadar yalnız,

Ada kadar ıssız,

Bir gemi kadar kalabalık,

Yaşamak uğruna verdiğin,

Savaş için; 

Gülümse! 

Toprak kadar üretken,

Arı kadar çalışkan,

Bir tohum kadar sade,

Hayat verdiğin,

Tabiat için; 

Gülümse! 

Bulut kadar yoğun, 

Rüzgar kadar sert,

Bir buz kadar soğuk,

Yaşayan,

Dört mevsim için; 

Gülümse! 

Martı kadar özgür,

Şeytan kadar sinsi,

Bir tilki kadar kurnaz,

Yaşama şansı vermediğin,

Kendin için,

Gülümse.', '(tebessümsüz yaşayanlara...)  Okyanus kadar yalnız, Ada kadar ıssız, Bir gemi kadar kalabalık, Yaşamak uğruna verdiğin, Savaş için;  Gülümse...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulumse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Dağ', 'yorgun-dag-ferah-guneri-bircan-39fbp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Her birey gibi,her ideolojiler gibi,dağlarda yorulur birgün...) 

Bilirim,

Uzun ve meçhul yılların,

Yorgunluğu var benliğinde,

Bir türlü,

Kükreyemezsin; 

Müsaade edersen,

Anlatayım bilmeyenlere: 

Birçok, 

Cahiller geldi,

Geçti üstünden,

Savaştılar,

Barıştılar,

Yaktılar,

Yıktılar,

Ama nafile,

Başaramadılar,

Kalıcı olmayı; 

Öylesine istedi ki,

Tabiat ana:

Ölümü verdi,

Sıcağı verdi,

Seli verdi...

Verdi de,

Verdi! 

Bıkmadan usanmadan; 

İşte dostlar:

Geleni karşılamak,

Geçeni uğurlamak,

Yorgun düşürdü,

Onu.', '(Her birey gibi,her ideolojiler gibi,dağlarda yorulur birgün...)  Bilirim, Uzun ve meçhul yılların, Yorgunluğu var benliğinde, Bir türlü, Kü...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yorgun-dag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Zaman', 'i-ste-o-zaman-ferah-guneri-bircan-v0vxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Bir çiçek nasıl beklenir....)

Her,

Telefon çaldığında,

Duyabileceksem,

O! 

İçimi ısıtan,

Sesini; 

Her sabah,

Gözlerimi açtığımda,

Görebileceksem,

O! 

Meleklere özgü,

Çehreni; 

Her,

Güneş batışında,

Öpebileceksem,

O! 

Süt beyaz,

Tenini; 

İşte o zaman! 

Yudum yudum,

İçmek için,

Bir ömür,

Sabırla beklerim,

Seni! 

Bilesin ki.', '(Bir çiçek nasıl beklenir....) Her, Telefon çaldığında, Duyabileceksem, O!  İçimi ısıtan, Sesini;  Her sabah, Gözlerimi açtığımda, Görebilec...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/iste-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bana', 'gel-bana-ferah-guneri-bircan-7v316', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(öyle bir gel ki bana...) 

Gündüzleri,

Giydiğin elbise,

Bedenini sıktığında,

Nefes almakta,

Zorlandığında:

Koşarak! 

Olmasa da,

Gel bana; 

Gün yerini,

Karanlığa bıraktığında,

Kalbin ile mantığın,

Çelişki yaşadığında,

Bir tebessüm eyle,

Zihninle:

Gel bana; 

Aradığının,

Huzur,

Ve sevgi olduğuna,

İnandığında,

Duygularından,

Emin olduğunda,

Mesafeleri unut! 

Dönmemek üzere,

Gel bana.', '(öyle bir gel ki bana...)  Gündüzleri, Giydiğin elbise, Bedenini sıktığında, Nefes almakta, Zorlandığında: Koşarak!  Olmasa da, Gel bana;  G...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balım', 'balim-ferah-guneri-bircan-53xgt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufkumda sen varsın,

Yalnızlığımın ötesinde,

Gölgemin önümde; 

Nesin ve neredesin,

Bunu bana sorma,

Soramazsında; 

Sen,

Dağların zirvesinde,

Denizlerin dibinde,

Sen gönlümde,

Gönlümün,

Derinliklerindesin; 

Gel! 

Yargılamadan,

Yargılanmadan,

Toprağın suya,

İnsanın sevdasına,

Kavuşurcasına,

Ölümsüzlüğe koşarcasına.', 'Ufkumda sen varsın, Yalnızlığımın ötesinde, Gölgemin önümde;  Nesin ve neredesin, Bunu bana sorma, Soramazsında;  Sen, Dağların zirvesinde, ...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/balim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye Diye', 'diye-diye-ferah-guneri-bircan-l800v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni,

Yaşamak istiyorum,

Yarın,

Ölecekmişim gibisine; 

Seni,

Sevmek istiyorum,

Hiç,

Ölmeyecekmişim gibisine; 

Gözlerini istiyorum,

Bakmaktan,

Yorgun düşeyim diye; 

Kulaklarını istiyorum,

Sevdamı,

Anlatabileyim diye; 

Dudaklarını istiyorum,

Kızgın toprağın,

Suyu istercesine; 

Seni istiyorum,

Seni! 

Uğruna,

Öleyim diye.', 'Seni, Yaşamak istiyorum, Yarın, Ölecekmişim gibisine;  Seni, Sevmek istiyorum, Hiç, Ölmeyecekmişim gibisine;  Gözlerini istiyorum, Bakmaktan...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diye-diye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-ferah-guneri-bircan-amlcu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprağı sevdim,

Geldiğim yer,

Gideceğim,

Mekan olacağından; 

Suyu sevdim,

Canlara,

Can kattığından,

Bedenimin,

Dörtte üçünü,

Kapsadığından; 

Havayı sevdim,

Yaşadığım gezegende,

Aldığım,

Nefes olduğundan; 

Sevdim doğayı,

Kendisini,

Benimle paylaştığından,

İmkanlarını tepsi de,

Bana sunduğundan; 

Sevdim yaşamı,

Beş duyumla alabileceğim,

Bir değil, bin değil, n tane rengi,

Bana yaşattığından; 

Ben sevdim,

Ben toprağı sevdim,

Ben suyu sevdim,

Ben havayı sevdim,

Ben doğayı sevdim,

Ben yaşamı sevdim,

Ama ben:

Hiçbir şeyi,

Seni sevdiğim kadar,

Sevmedim,

Ben,özüm kadar:

Seni sevdim.', 'Toprağı sevdim, Geldiğim yer, Gideceğim, Mekan olacağından;  Suyu sevdim, Canlara, Can kattığından, Bedenimin, Dörtte üçünü, Kapsadığından; ...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'soz', 'soz-gokmen-dursun-oishh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimdeki yerinin degismeyecegine...

Seni bir ömür sevecegime... 

Kelebeklerin renklerinin insani büyülemesi gibi,

bugünüm gibi, yarinimda da

hep sevginle yasayacagima...

Her bakisinda okudugun o gözleri, her zaman 

yaninda görecegine, en yakin dostun, 

en yakin sirdasin, en yakin arkadasin olacagima...

Sikintinin sikintim, üzüntünün üzüntüm olacagina... 

Her kizgin anini çiçege dönüstürecegime...

Her üzgün aninda tebessümünün geri gelmesi için 

elimden geleni yapacagima...

Asla ve asla soguktan da, yalnizliktan da 

üsümeyecegime...

Seni bir ömür sevecegime... 

Yaninda olamadigim ve varligima ihtiyacin oldugu

her anda bir rüzgar olup seni saracagima...

Gözümün gözüne degdigi her an,sana yeniden 

asik olup seni bir Prens''e dönüstürecegime...

Bir yasam...

Ve her sabah sana asik olarak uyanacagima...

Sen uyurken sana bakip,

sen ve ben için dualar edecegime...

Hasta oldugun zaman sana 

sicacik bir çorba yapacagima... 

Seni asla üzmeyecegime...

Seni kizdirirsam bunu bilmeden yapacagimdan 

hemen özür dileyecegime...

Beni tanidigin gün, bende gördügün neyse,

ömrümce ayni beni görecegine...

Sevgimin asla degismeyecegine... 

Sevgimin asla azalmayacagina...

Bilakis, her gün büyüyen bir sevgiyi görüp, 

seni mutluluk ormanlarina tasiyacagima...

Senin her seyin önünde oldugun gerçeginin 

asla degismeyecegine...', 'gözlerimdeki yerinin degismeyecegine... Seni bir ömür sevecegime...  Kelebeklerin renklerinin insani büyülemesi gibi, bugünüm gibi, yarinimd...', ARRAY['Türk Edebiyatı','Şiir','Gökmen Dursun']::text[], 8.5, '{"poet":"Gökmen Dursun","poet_slug":"gokmen-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılış', 'yikilis-feramuz-gorel-wj8gt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sokaklar sessizdi

İnsanlar durgun 

Hepsi keder, hepsi hüzünlü

Belli felekten yemişler vurgun

İnsanlar imana susamıştı

Toprağın suya susadığı gibi

Kapkaranlık görünmüyor kuyunun dibi

Kiprikleri ıslanmış ağlıyor biri

Biri seslendi... ağla, ağla diyordu

Sözcükler boğazında düğümleniyordu

Sanki kendisi ağlıyormuş gibi

O da hüzünlü o da yaslıydı

Bir ana yavrusunun elinden tutmuştu

Ürkek tedirgindi

Biri çok içmiş yürüyemiyordu

Bir insandı, sormadım acaba kimdi

İnsanlar koşuşturmaktaydı bir yerlere

Ezan vakti gelmişti

Caminin kapısına yaklaştım cami boştu

Başımı kaldırdım karşımda meyhane

Meyhaneler dolmuş, herkes sarhoş olmuştu

Konuşmalar anlaşılmıyordu

Belli herkes bir hoş olmuştu

Ama insanlar, insanlar kahrolmuştu', 'Sokaklar sessizdi İnsanlar durgun  Hepsi keder, hepsi hüzünlü Belli felekten yemişler vurgun İnsanlar imana susamıştı Toprağın suya susadığı...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yikilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Var', 'biri-var-feramuz-gorel-nhomy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri şeytan olur 

Biri şeytana eş

Mümin görünür

Sana der kardeş

Bir elinde şarap

Kalbini yoklarsan harap

Adını dersen kıyamet kopar

Sana saldırır ya rab!

Desem yüzü benzer maymuna

Faydası yok zaten birine

Adını söyleme, inme derine

Kar getirmez hep çalışır zararına

Doğdu doğalı doğru konuşmadı

Yıldızı islamla hiç barışmadı

Hak yolunda hiç yarışmadı

Hep aldı vermeye alışmadı', 'Biri şeytan olur  Biri şeytana eş Mümin görünür Sana der kardeş Bir elinde şarap Kalbini yoklarsan harap Adını dersen kıyamet kopar Sana sal...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biri-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-feramuz-gorel-a76nx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık vakti geldi çattı

Hüzünlendim ben yürekten

Gözlerinden yaşlar aktı

Sizlerin mahsun bakışı beni yaktı

Yakında ayrılacağım yayladan

Temiz arkadaşlardan hoş havadan

Bana ilim, kültür veren

Hem anadan hem babadan

Haklarınızı helal edin

Batılda değil hak yolda gidin

Boş durma arkadaşım

Karınca gibi çalış didin

İyi kötü anılarımız oldu

Yine hüzünlendim gözlerim doldu

Sizlerden ayrıldım mutsuzum

Gönlüm sizlerde kaldı', 'Ayrılık vakti geldi çattı Hüzünlendim ben yürekten Gözlerinden yaşlar aktı Sizlerin mahsun bakışı beni yaktı Yakında ayrılacağım yayladan Te...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istemem', 'istemem-feramuz-gorel-1ii31', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstemem bayramlar olmasın

Kapım çalınmaz gelenim olmaz

Hep hüzünlenirim çilem dolmaz

Hiç gülmeyen yüzüm bayramda gülmez

Ne eş arar nede kardeş

Gözümde dinmez hep akar yaş

Anladım ki yaşamışım bomboş

Baharım hep olur kış

Aranıp sorulmaz isem

Bayramda aranmaz isem

Bu dünyada hiç gülmez isem

İstemem bayramlar olmasın

Her gün boynum bükük gözümde yaş

Arayıp sormaz kavim kardeş

Bağrıma bastığım nedendir hep taş

İstemem bayramlarım olmasın

Gözlerimden yaşlar akmasın....', 'İstemem bayramlar olmasın Kapım çalınmaz gelenim olmaz Hep hüzünlenirim çilem dolmaz Hiç gülmeyen yüzüm bayramda gülmez Ne eş arar nede kard...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlık', 'aydinlik-feramuz-gorel-4q6bf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aydınım diyorsun aydınlık nerende

Yargıçmısın, olabilirsin

İnsanım diyorsun insanlık nerende

Karanlığa bürünmüş mülkün temeli

Karanlık belli aydınlık belli

Yasalarım bozuk hepsi hileli

Aydınım diyorsun aydınlık nerende

Kabahat sende değil, sana oy verende

Kara yasa karanlık içinde

Sende vurdun bizi seçimde

Bizi hatırlarsın dört yılda bir

O da oy istersin, bak geldi seçimde', 'Aydınım diyorsun aydınlık nerende Yargıçmısın, olabilirsin İnsanım diyorsun insanlık nerende Karanlığa bürünmüş mülkün temeli Karanlık belli...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurun', 'vurun-feramuz-gorel-3ocfo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir akşam üstü kapım çalındı

Kim o diye seslendim

Kapı kırıldı ben alındım

Ayak yalın başı açık

Kimsiniz nesiniz, sormadım

Gerillamı kontra gerillamı bilemedim

Gözümü karanlık bir hücrede açtım

Yoksulluk bu ya halen açtım

Hücrenin kapısı açıldı

Komserin tokatı şimşek gibi yüzüme çakıldı

Burnumdan oluk oluk kan açıldı

Ne kadar suç işlemişim meğer...', 'Bir akşam üstü kapım çalındı Kim o diye seslendim Kapı kırıldı ben alındım Ayak yalın başı açık Kimsiniz nesiniz, sormadım Gerillamı kontra ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vurun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yeter', 'yeter-feramuz-gorel-xr3mp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayvanlarımı sevsem insanlarımı 

Bunca insan ölüyor delimi

Ölm belli öldüren yok

Buda türkiyenin kaderimi

Açmısın tokmusun sormadın

Dilimi ırkımı töremi bilmedin

Sen güldün eğlendin

Ben yaşadığımı bile bilmedim

Kuş sesine hasret kaldım

Hep baykuş sesini dinledim

Vurdun! Vurdun sen bana

Sen vurdukça ben inledim', 'Hayvanlarımı sevsem insanlarımı  Bunca insan ölüyor delimi Ölm belli öldüren yok Buda türkiyenin kaderimi Açmısın tokmusun sormadın Dilimi ı...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün', 'birgun-feramuz-gorel-6h3xh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün gelir sende yaşlanırsın

Belin bükülür

Yaşlar dolar gözlerine

Gözlerinden yaş dökülür

Gözlerine çekilir perde

Bilmezsin oğul, aydınlık nerde

Eşin dostun sevmez seni

Düşersin çekilmez derde

Yüzün kırışır dizin tutmaz

Boğazın oğul, lokmayı yutmaz

Kimse gelip elinden tutmaz

Bilemezsin takat nerde

Beklersin Azrail gele

Gelipte canını ala

Öldüğünü dostlar bile

Uğurlarlar seni güle güle', 'Birgün gelir sende yaşlanırsın Belin bükülür Yaşlar dolar gözlerine Gözlerinden yaş dökülür Gözlerine çekilir perde Bilmezsin oğul, aydınlık...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vatan Kimin', 'bu-vatan-kimin-feramuz-gorel-jpv2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu vatan ne senindir ne benimdir

Yüreğimde vatan yarası derindir

Bu vatan soyguncunun vurguncunundur

Bu vatan ne senindir ne benim

Bu vatan batakçının kumarcınındır

Bu vatan ne senin ne benimdir

Bu vatan hayali ihracatçınındır

Bu vatan düzenbazın hokkabazındır

Bu vatan ne senindir ne benimdir

Kuranı kaldıran başörtüsünü yıkanlarındır

Bu vatan körpe çocukları sokağa atanlarındır

Bu vatan karnı tok, sırtı pek yatanlarındır.

Bu vatan ne senin ne benimdir

Bu vatanhavyar yeyip şampanya içenlerindir

Bu vatan kurana gerici diyenlerindir

Bu vatan domuz eti yiyenlerindir

Bu vatan ne senindir ne benimdir

Bu vatan devleti soyanlarındır

Milletin sırtından milyarlar vuranlarındır

Aç gözünü bu vatan ne senin ne benimdir

Bu vatan ne senin ne de benimdir

Bu vatan faizcinin tefecinindir

Bu vatan el etek öpenlerindir

Bu vatan gerden bükenlerindir...', 'Bu vatan ne senindir ne benimdir Yüreğimde vatan yarası derindir Bu vatan soyguncunun vurguncunundur Bu vatan ne senindir ne benim Bu vatan ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-vatan-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşa Geçen Yıl', 'bosa-gecen-yil-feramuz-gorel-nywpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gene bir yıl geldi geçti

Dostlar bağrım deşti

Gözlerimden yaşlar düştü

Yeni yılınız kutlu olsun

Saçlarımın ağı çoğaldı

Sevdiklerimin ismi derde saldı

Ellerim koynumda kaldı

Yeni yılınız kutlu olsun

Yüzüm kırıştı belim büküldü

Ömür bağrımdan yapraklar döküldü

Sineme hep dert ekildi

Yeni yılınız kutlu olsun

Gelen vurdu giden vurdu

Dost düşman oldu kudurdu

Bu yetim boynunu yine burdu

Yeni yılınız kutlu olsun

Canım dedim canım gitti

Dostlar çektiğim vallah yetti

Bir yıl daha dertli bitti

Yeni yılınız kutlu olsun

Kul Feramuz hüzünlendim

Sanmayın ben dinlendim

Bir yıl boyu daha kederlendim

Yeni yılınız kutlu olsun...

( 29-12-1994 Cuma )', 'Gene bir yıl geldi geçti Dostlar bağrım deşti Gözlerimden yaşlar düştü Yeni yılınız kutlu olsun Saçlarımın ağı çoğaldı Sevdiklerimin ismi de...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bosa-gecen-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ve Çevre', 'i-nsan-ve-cevre-feramuz-gorel-qqm70', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan çevreyi korumalı

İnsanlar insan olduğunu bilmeli

Temiz çevre temiz toplum

İnsan insanca gülmeli

İnsan çevreyi kirletmemeli

İnsan geleceği düşünmeli

İnsan temiz çevrede gülmeli

Kirli havada insan ölmemeli

Çevreyi temiz tutmalıyız

Kirli hava yutmamalıyız

Cehaleti unutmalıyız

Çevreyi insanız temiz tutmalıyız', 'İnsan çevreyi korumalı İnsanlar insan olduğunu bilmeli Temiz çevre temiz toplum İnsan insanca gülmeli İnsan çevreyi kirletmemeli İnsan gelec...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-ve-cevre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm Kaldı', 'gozum-kaldi-feramuz-gorel-nuvc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözüm kaldı gözüm kaldı

Güzel sende gözüm kaldı

Gözlerin aklımı aldı

Gözlerinde gözüm kaldı

Gözüm kaldı gözüm kaldı

Saçlarında gözüm kaldı

Diyemedim derdimi

Ağzımda sözüm kaldı

Cemalin aklımı aldı

Beni hülyalara saldı

Ellerim yanımda kaldı

Gidişinde gözüm kaldı', 'Gözüm kaldı gözüm kaldı Güzel sende gözüm kaldı Gözlerin aklımı aldı Gözlerinde gözüm kaldı Gözüm kaldı gözüm kaldı Saçlarında gözüm kaldı D...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozum-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı', 'yilbasi-feramuz-gorel-tsgt7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün yine yılbaşı

Viskiler su oldu sanki akıyor

Bosnalı çeçenli çocuk

Nefes yok gözler bakıyor

Hava soğuk kar yağıyor

Beyazlar arama kardı

Kar  kara bulaşmış

Ama bugün yılbaşı

Zehir olsun küfrün aşı

Yine çatladı islamın kaşı

Bugün yine yılbaşı

Ağaçlar kesildi çamlar dikildi

İslamın beli büküldü

Yavrular aç perişan bağrı söküldü

Bugün yine yılbaşı

Kesilmeli küfrün başı

Dinmeli, dinmeli bu gözyaşı

Zehir olmalı bu yılbaşı

Bugün yine yılbaşı...', 'Bugün yine yılbaşı Viskiler su oldu sanki akıyor Bosnalı çeçenli çocuk Nefes yok gözler bakıyor Hava soğuk kar yağıyor Beyazlar arama kardı ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yilbasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-feramuz-gorel-r4dhj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlıyormusun çocuğum 

Üşüyormusun yoksa

Bedenin titriyor

Rengin solmuş

Açmısın çocuğum?

Kimin kimsen yokmu

Karnın açmı yoksa tokmu

Ayakların yaın

Nedir senin bu perişan halin

Sahipsizmisin çocuğum

Laik düzenin demokrat evladımısın

Belli vatan aşkıyla üşüyorsun

Sen vatandaşsın

Sen vatanda bir taşsın

Sen laik vatandaşsın

Ağlama üşüme acıkma

Çalış demokratlar senden can bekliyor

Ver kurtul çocuğum

Hakkın verilmez alacaksın

Önce kendini insan sanacaksın

Kanın akacak üzülme

Birgün sende güleceksin çocuğum...', 'Ağlıyormusun çocuğum  Üşüyormusun yoksa Bedenin titriyor Rengin solmuş Açmısın çocuğum? Kimin kimsen yokmu Karnın açmı yoksa tokmu Ayakların...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Bayramı', 'kurban-bayrami-feramuz-gorel-hharc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adımız islam bizim

Özümüz ne bilmem

İnsanlar her gün kurban edilir

Neden bunu bilmem

İnsanlar hayvandan kurban seçer

Ya dana ya inek ya koyun

Yıllardır bitmiyor düzendeki oyun

İnsanlar boğazlanır sanki koyun

İnsanlar hergün kurban edilir

Hayvanlar halimize gülerler

İnsanların kurban bayramı hergün

Hayvanların ise işte bugün', 'Adımız islam bizim Özümüz ne bilmem İnsanlar her gün kurban edilir Neden bunu bilmem İnsanlar hayvandan kurban seçer Ya dana ya inek ya koyu...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kurban-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeyiz', 'bilmeyiz-feramuz-gorel-af5hy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adımız islam ya islamı bilmeyiz

Hacısıyla hocasıyla doğruyu demeyiz

Kim diyor haram yemeyiz

Adımız islam kuran bilmeyiz

Fitne fesat hepsi bizde

Saklıdır fesatlık nefsimizde

Acep böylemiydi dedelerimizde

Yoldan çıkmış camidekiler bilmeyiz...', 'Adımız islam ya islamı bilmeyiz Hacısıyla hocasıyla doğruyu demeyiz Kim diyor haram yemeyiz Adımız islam kuran bilmeyiz Fitne fesat hepsi bi...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elden Gider', 'elden-gider-feramuz-gorel-e22d7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanma her sakallıya

Aldanma emmi dayıya

Güvenme düzende ayıya

Sonra imanın elden gider

Her mekke gezen hacı değildir

Her vaaz veren hoca değildir

Sen haktan sakın ayrılma

Sonra dinin elden gider

Yemin etme Kur’an’a

Umutla bak yarına

Aldanma dünya varına

Sonra namusun elden gider

Kanma her mollanın sözüne

Caminizi tapular sonra özüne

Kül savurur resulün gözüne

Sonra camiler elden gider

Türküm der İranda okur

İşine gelmeyince çorap dokur

Tecvit bilmez Kuran okur

Sonra namazın elden gider...', 'İnanma her sakallıya Aldanma emmi dayıya Güvenme düzende ayıya Sonra imanın elden gider Her mekke gezen hacı değildir Her vaaz veren hoca de...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elden-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedbaht', 'bedbaht-feramuz-gorel-ctl47', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne Allah’ı bildi nede kulu

Bulamadım hakka giden yolu

Garibin gözleri yaş ile doldu

Unuttun ahireti dost bildin pulu

Şeytan oldun çıktın minbere

Açtın islamın kalbinde yara

Düşman oldun islama

Hayasızca gidiyorsun sen hara? 

Hizbullaha kafir dedin

Fitre zekatı kendin yedin

Hakkı diyene terörist dedin

İşte o zaman ayvayı yedin

Bir bilsen yaradan Allah’ı

İman yok sende vallahi

Nerden gördüm böyle bedbahtı

Tutacak bir gün Kur’an’ın ahı', 'Ne Allah’ı bildi nede kulu Bulamadım hakka giden yolu Garibin gözleri yaş ile doldu Unuttun ahireti dost bildin pulu Şeytan oldun çıktın min...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bedbaht-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Deyim', 'ne-deyim-feramuz-gorel-100lw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Makam istedin şan istedin

İslam’a terörist dedin

Fakir fukara hakkını yedin

Bilmem sana ne deyim

Nefsin için yakarsın ahretini

Görmedim sende hayayı

Kendi başıma aldım ben belayı

Bilmem sana ne deyim

Emir, Sultan oldun  başımıza

Zehir kattın sen aşımıza

Kötüledin eşimize dostumuza

Bilmem sana ne deyim

Utanırım adını yazam

Sana nasıl sözler dizem

Nasip ola mezarını ben kazam

Bilmem sana ne deyim

Yiyin ağalar yiyin beyler

Allah Hizbullah’ı met eyler

Bizim dinsizler küfreyler

Bilmem dinsize ne deyim...', 'Makam istedin şan istedin İslam’a terörist dedin Fakir fukara hakkını yedin Bilmem sana ne deyim Nefsin için yakarsın ahretini Görmedim send...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-deyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bilim', 'ne-bilim-feramuz-gorel-4r76y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ev verdim iş verdim

Yemedim sıcak aş verdim

İnsan bildim gardaş dedim

İmansızmış ne bilim

Adını yazdım özgürce

Korudum onu gündüz gece

Yemin etti Kur’an’a nece

İmansızmış ne bilim.

Eledim özünü boş

Taş oldu çıkardı gözümden yaş

Yanlış yorumladı hak sözümü

İmansızmış ne bilim

Kuran okur Allah bilmez

Helal lokma bulup yemez

İşi gücü gıybet hakkı bilmez

İmansızmış ne bilim

Feramuzum oldum beçare

İnanmıştım alçakmışta ne çare

Yüreğime açtı vallah bir yara

İmansızmış ne bilim...', 'Ev verdim iş verdim Yemedim sıcak aş verdim İnsan bildim gardaş dedim İmansızmış ne bilim Adını yazdım özgürce Korudum onu gündüz gece Yemin...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-bilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmayın', 'yanmayin-feramuz-gorel-w5ye6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her Allah diyene inanmayın

Bazı mollalara kanmayın

Ben yandım siz yanmayın

Sakın sizde aldanmayın

Sizi de el bastırır kurana

İmanı yok ki inana

Fikri şeytandan yana

Özü küfür, görünür islamdan yana

Yalanı şeytandan çoktur

Sözleri yalan hak sözü yoktur

Her sözü islama bir oktur

Onun için küfür haktır

Sevinir her gün insanlar ölsün

İster ki cebi para dolsun

Godoşları ölü yusun

Deyme dur, yesin kudursun...', 'Her Allah diyene inanmayın Bazı mollalara kanmayın Ben yandım siz yanmayın Sakın sizde aldanmayın Sizi de el bastırır kurana İmanı yok ki in...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Oluyor', 'neler-oluyor-feramuz-gorel-on0xh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazık ki islamın kanı akıyor

Feryatlar yüreğimi yakıyor

Rasulün minberinde bu ne okuyor

İslama, kurana mümine beddua okuyor

Çıkmış resulün minberine

İnşallah çıkamaz olur yarına

Göz dikmiş dünya varına

Doymaz haram karına

Feramuz aldandı yezide

Bütün yollar inşallah hüseyne gide

Çoban ola küfrü güde

Nemrud elinden kime gide...', 'Yazık ki islamın kanı akıyor Feryatlar yüreğimi yakıyor Rasulün minberinde bu ne okuyor İslama, kurana mümine beddua okuyor Çıkmış resulün m...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neler-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Olma', 'saf-olma-feramuz-gorel-j7swz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İmanlı gördüm aldandım

Yalan yeminine kandım

Kelli felli insan sandım

Şeytanmış onu bilemedim

Bu adam elinden imanım gitti

Çektirdikleri inanın yetti

Tükendi servetim gitti 

Şeytanmış onu bilemedim

Siz siz olun aldanmayın

Her kuran okuyana kanmayın

Kendiniz okuyun yanmayın

Kuran bilmezmiş onu bilmedim

Muska yazar asarsın boynuna

Sakın düşme şeytanın oyununa

Dul karıyı alır koynuna

İmansızmış onu bilmedim

İşi gücü muska yazmak

Ona buna kuyu kazmak

Yalandan sözler dizmek

Yezitmiş onu bilmedim...', 'İmanlı gördüm aldandım Yalan yeminine kandım Kelli felli insan sandım Şeytanmış onu bilemedim Bu adam elinden imanım gitti Çektirdikleri ina...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saf-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ne?!!!', 'sana-ne-feramuz-gorel-ycf3v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunma yıkılsın kâbe

Filistine acıma

Çeçenistan yansın sanane

Sakın konuşma haktan yana

Afganistan ağlasın

Azerbaycan kara bağlasın

Deyme bosna inlesin sana ne

Irak yerle bir olsun

Amerika emir buyursun

Kaldır kuran rafta dursun

Minberde islamdan söz etme

Başı örtülü okula gitme

Bırak cezayir yansın

Değme molla yesin kudursun

İslama düşman yahudiye dost olsun

Doğruyu deme eğriyi konuş

O zaman sen mümin olursun

Müminlik buysa ol safta senin olsun

Yalandan sarıl kurana

Seyret alemi bıraktın yana yana

Resululllahın yanında geleceğiz yan yana

Allah diyeni çekin dar ağacına

Secde et inandığın hacına

Saldır islama neme lazım kuran

Ölünce okurlar mezarında

Birde yemek verirler

Cennet yer alırsın

Köşk saray kurarsın...', 'Dokunma yıkılsın kâbe Filistine acıma Çeçenistan yansın sanane Sakın konuşma haktan yana Afganistan ağlasın Azerbaycan kara bağlasın Deyme b...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sana-ne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberi Yok', 'haberi-yok-feramuz-gorel-d3u7x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İslam düşmanları çoğaldı

Kuran prangalara bağlandı

Resulün yüreği dağlandı

Kimsenin kurandan haberi yok

Ehli beyti doğrandı

Yalandan mersiyede ağlandı

Çok islamın yüreği dağlandı

Bunların kerbeladan haberi yok

Resulullahın minberine yezitler çıktı

İslamın kanı su gibi aktı

İsrail bile kudüsü yaktı

Hayvan feryadından insanın haberi yok

Kuran muska oldu satıldı

İnsanlar zindana atıldı

Müşrikler vatan satına atıldı

Kimsenin imansızdan haberi yok', 'İslam düşmanları çoğaldı Kuran prangalara bağlandı Resulün yüreği dağlandı Kimsenin kurandan haberi yok Ehli beyti doğrandı Yalandan mersiye...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haberi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oral Beye', 'oral-beye-feramuz-gorel-kblrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oda bir erdi

Ama gezerdi

Sevgisini şefkatini

İnsanlara verdi

Yüzüne bakmak ibadet bence

Sevgisi şefkati dağlarca ya bahtı

Bahtı gezer

Çünkü kendi Gezererdi.

Bütün varlıklar kutsaldır

Severim diyor oda bir candır

Biz yolcuyuz dünya bir handır

Gezererdir oda bir candır.

Hukukçudur hukuk onun işidir

İnsanlık özü hayali düşüdür.

Kendi candır er kişidir

Çünkü o bir erdir, Gezerer’dir.', 'Oda bir erdi Ama gezerdi Sevgisini şefkatini İnsanlara verdi Yüzüne bakmak ibadet bence Sevgisi şefkati dağlarca ya bahtı Bahtı gezer Çünkü ...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oral-beye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığındım', 'sigindim-feramuz-gorel-wrhpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şeytanın şerrinden Allah’a sığındım

Bulanıktım şimdi duruldum

Bene yıllarca küfre kandım

Tövbe ettim Allah’a sığındım

Tövbe kapısı açıktır sende gel

Hak nedir batıl nedir onu bil

Hep ağladın bir gün gül

Ben gıybetçi elinden Allah’a sığındım

Milleti birbirine düşürmeyin

Kimsenin günahını almayın

Işık varken karanlığa dalmayın

Fitnecilerin elinden Allah’a sığındım

Gördüğüne duyduğuna inan

Sana yetmiyor mu o azim Kuran

Sana islamı dememiş ise baban

Babanın şerrinden Allah’a sığındım...', 'Şeytanın şerrinden Allah’a sığındım Bulanıktım şimdi duruldum Bene yıllarca küfre kandım Tövbe ettim Allah’a sığındım Tövbe kapısı açıktır s...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sigindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-feramuz-gorel-snt35', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dediğine amel etmeyen insan olurmu

Hakkı bilmeyen huzur bulurmu

Halbura su koysan dolarmı

Bedbaht olma insan oğlu

Yezit çıktı resulün makamına

Kerbelada girdi Hüseyin’in kanına

Doğruluk yakışır insanın şanına

Dön kendine insanoğlu

Nemrut olma başımıza

Zehir katma aşımıza

Kötüleme eşimize dostumuza

Hakkı söyle insanoğlu

Kardeşi kardeşe düşürme

Benden rütbe alma

Mervan gibi meydana dalma

Ruh bendenden ayrılır insanoğlu', 'Dediğine amel etmeyen insan olurmu Hakkı bilmeyen huzur bulurmu Halbura su koysan dolarmı Bedbaht olma insan oğlu Yezit çıktı resulün makamı...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevin Dedi', 'sevin-dedi-feramuz-gorel-hcm9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmedin ki sevmeyi bilemezsin

Sevmezsen insanı bilemezsin

Sevmezsen yaşadım diyemezsin

Çünkü Allah sevin dedi.

Ne Allah’ı bildin ne de kulu

Bulamadın hakka giden yolu

Neden gözlerin yaş ile dolu

Çünkü Allah sevin dedi.

Taş kalpliysen sana ne diyeyim

Hal hatır soruyorsun şimdi iyiyim

İnan yalnız seni seviyorum

Çünkü Allah sevin dedi.

Gel Feramuzu düşürme derde

Seven gözlere çekilmesin perde

Ömrünce kalmayasın darda

Çünkü Allah sevin dedi.', 'Sevmedin ki sevmeyi bilemezsin Sevmezsen insanı bilemezsin Sevmezsen yaşadım diyemezsin Çünkü Allah sevin dedi. Ne Allah’ı bildin ne de kulu...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevin-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuk', 'unuttuk-feramuz-gorel-uxkmm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz özümüzü unuttuk

Hakkı unuttuk batılın yolunu tuttuk

Noel babası hoş geldin dedik

Andolsun navruzu unuttuk

İngilizi, Fransız’ı dost edindik

Yunanı bilirsiniz Ege’de yendik

İsrail’e can gardaş dedik

Çeçenistan’ı Bosna’yı Azerbaycan’ı unuttuk

Roma kanunları girdi mekteplere

Türk adı bulamadık bebelere

Moruk dedik asırlık dedelere

İslam’ız yalnız kuranı unuttuk

Darvini jakı bildik

Öz halimize özümüz güldük

Bir birimizin etini yedik

Dede korkutu, şeyh Şamil’i Şehriyarı unuttuk

Dün köylüydük bu gün şehirli

Kot pantolon mini etekli

Yes okey mösyö madam derken

Öz dilimizi unuttuk

Yumurtaları boyamıştık

Yedi nevinde almıştık

Ev ev gezip bayramlaşmıştık

İndi selamlaşmayı unuttuk

Bugün yeni bir gündür

Toprağın suyun düğünüdür

Azerimin mutlu günüdür

Geleceğe koşuyoruz geçmişi unuttuk

Çıkarcılar saldı bizi birbirimez

Hem ölümüze söydüler hem dirimize

Sahip olamadık biz dinimize

Resulullah’ı bile unuttuk...', 'Biz özümüzü unuttuk Hakkı unuttuk batılın yolunu tuttuk Noel babası hoş geldin dedik Andolsun navruzu unuttuk İngilizi, Fransız’ı dost edind...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unuttuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moda Ya...', 'moda-ya-feramuz-gorel-og54c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes modaya uydu gidiyor

Bu insanlar yalan ehliyim diyor

Ne Allah bilir ne de Kuran

Olacak elbet bir gün sesimzi duyan

Gece müslüman gündüz laik

Yatan yok ahmak herkes ayık

Ne sakal kaldı nede bıyık

Buda modaya uyup gidiyor

Bu zalım herkesi gönderdi cennete

Buhtan etti bu mazlum millete

Bekliyor uyananlar yata

Yatanlarda uydu modaya

İrtica mirtica dem vurdu durdu

Yoksa bu zalim mi kudurdu

Mığmığa mozalana selam durdu

Tosbağa kurbağa uydu modaya

Mollada abayı kaldırdı attı

Gece gündüz korumayla yattı

İslamı bir koltuğa sattı

Mollada uydu modaya...', 'Herkes modaya uydu gidiyor Bu insanlar yalan ehliyim diyor Ne Allah bilir ne de Kuran Olacak elbet bir gün sesimzi duyan Gece müslüman gündü...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/moda-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Bey', 'hakim-bey-feramuz-gorel-8h2cd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim dava ne oldu hakim bey

Gurban olum uzatma tez kutar

Camiide adam galmadı getti

Galanlarada ancak fitre nezrimiz yetti

Hakim bey yeni korumalara pul gerek

Burda demokrasi yok kralımız tek

Yığdı elemi, neziri, evine döktü

Milletin başına goyduğu börktü

Hakim bey üç aya dört aya atma

Gurban olum bu davayı uzatma

Dene bu ite guranı pula satma

Gomşun açtır sen tok yatma

Hakim bey gece hizbullahi gündüz hizbu şeytan

Budu milleti bir birine gatan

Yoktu bu milletin elinden tutan

Tez gutar davayı gurban olum hakim bey', 'Bizim dava ne oldu hakim bey Gurban olum uzatma tez kutar Camiide adam galmadı getti Galanlarada ancak fitre nezrimiz yetti Hakim bey yeni k...', ARRAY['Türk Edebiyatı','Şiir','Feramuz Görel']::text[], 8.5, '{"poet":"Feramuz Görel","poet_slug":"feramuz-gorel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hakim-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığımın En Romatizmalı Günlerindeyken..', 'yanlizligimin-en-romatizmali-gunlerindeyken-tugba-ucar-n8hkc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yanlızlığımın en romatizmalı günlerinde

sokaklarda sana dair parçalar aramak 

hiçte mutlu etmiyordu beni.

donuk  ve kırbaca maruz kalmış anılarım tek saklanılacak yerdi

yanlızlığım yanlız bırakılmıyacak kadar yanlızken

ben telefondaki seslere sarılıyordum

seslerin içinde sesini arıyor

çatlak tınılara aşık oluyordum

yaralı bir ruh çabuk aşık olamıyor

şüphe dorukta !

 sızlanamıyorsun,

 bariton bir öfke usulcana yanına varır 

ve sen olur böyle anlarda

dolu ama boş olan bu şehirde

sacmalıkların sapanlığına tırmanıyor

hayatın malzemesınden calıyorum

annem dokuz memeli peri, babam balkabağı

bir masala sokulmuş

beni kemiriyorlar

bense seslerin içinde benim nefesim

senin sesini arıyorum

yanlızlığımın en romatizmalı günlerinde

düşlerim sana saldırdığında

söz veriyorum yanlızlığım,

seni yanlız bırakmıcam!!', 'yanlızlığımın en romatizmalı günlerinde sokaklarda sana dair parçalar aramak  hiçte mutlu etmiyordu beni. donuk  ve kırbaca maruz kalmış anı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanlizligimin-en-romatizmali-gunlerindeyken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burası Neresi?', 'burasi-neresi-tugba-ucar-1ghm8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sokaklarda bitirgen oğlanlar 

aşk için ezilmeye hazır kadınlar

şehre inat sevişiyor..

şehir ise kıskanç ve  parlak ışıklarla onları seyrediyor..

kaçık otobüs soförleri, geveze pazarlamacılar,

çok bilmiş büyükler...

korkak bir tarihi satıyorlar gözlerinde..

sabahları ise geriye kalan tek şey 

bir deri bir kemik olmus yatakları..

karamsarlık çiçekleri kirlenmiş saksılarda,

pencere önlerinde duruyor.

kedilerse ayaklarımıza sarılyor  bir parca et için

mavi mavi

çırılçıplak ....

öykü dolu bu şehir.

hemde en sarsılmazlarından,

en inanılmazlarından...

kekeme tartışmalar yükseliyor kahvelerden.

yaşlılar coktan bugünü unutmus,

anılara sarılmış.

gençler pişpirik oynar,

kadınlarsa yemek yapar bu şehirde.

ve bakışlarda satılmıs bir tarih cirit atar.

bitirgen oğlanlar

ve ezik kadınlar

şehre inat sevişiyorlar

en yanlız sokaklarda..

burası neresi?', 'sokaklarda bitirgen oğlanlar  aşk için ezilmeye hazır kadınlar şehre inat sevişiyor.. şehir ise kıskanç ve  parlak ışıklarla onları seyrediy...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/burasi-neresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-gokhan-bozdogan-3nrw5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'öyle bir sevda,

öyle bir aşş

öyle bir hayal ve umut ki bu;

her anım seni düşünmekle,

seni yaşamakla geçer.

öyle bir işledinki benliğime,

öylesine yerleştin ki yüreğime,

gözlerimin baktığı her yer

yüreğimin hissettiği her şey,

seni hatırlatır,seni yaşatır oldu.

belki sensizim,uazktasın fakat

yüreğimin tam ortasındasın.

sensizliği bile seninle yaşıyorum

bu sensizliklerde,

seni hergün biraz daha seviyorum

hergün biraz daha özlüyorum', 'öyle bir sevda, öyle bir aşş öyle bir hayal ve umut ki bu; her anım seni düşünmekle, seni yaşamakla geçer. öyle bir işledinki benliğime, öyl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-ferah-guneri-bircan-k1rx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir deli rüzgar eser,

Gönlünden gönlüme,

Taşır! 

Seni  bana; 

Bazen taşırlar,

Sarılma talebini,

Adeta! 

Bir daha,

Bırakmamacasına; 

Bazen taşırlar,

Kaçma talebini,

Adeta! 

Bir daha,

Karşılaşmamacasına; 

Bazen taşırlar,

Söylenenleri okumak için,

Gösterdiğin gayreti; 

Adeta! 

Kedilerin insanlara,

İhtiyaçlarını,

Anlattığı gibi; 

Bazen de  taşırlar,

Kendi içindeki  kararsızlıklarını,

Anlatsam mı? 

Yaşadıklarımı,

Düşündüklerimi,

Korkuları mı...

Yaşasam mı? 

Beni,

Onu,

Belki de bizi...

Özeti:

Bazen değil de,

Daima! 

Ne yapsamları.', 'Bir deli rüzgar eser, Gönlünden gönlüme, Taşır!  Seni  bana;  Bazen taşırlar, Sarılma talebini, Adeta!  Bir daha, Bırakmamacasına;  Bazen ta...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bazen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Misin?', 'i-yi-misin-ferah-guneri-bircan-hp5sx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Masalarda,

Karşımda oturduğun saatlerde,

Geceleri,

Telefonun diğer ucunda,

Soruyorum:

İyi misin diye; 

Ruhla bedenin,

Kaldığında baş başa,

Kendini kendinle,

Paylaştığın  yatağında,

Soruyorum:

İyi misin diye; 

İnşa ettiğin,

Şato gibi  yüreğinde,

Benimle beraberliğinde,

Soruyorum:

İyi misin diye; 

Sen! 

Bana soracak olursan:

İyi misin diye:

Haykırarak söylerim,

Beş  duyumla,

Sana tapıyorum diye.', 'Masalarda, Karşımda oturduğun saatlerde, Geceleri, Telefonun diğer ucunda, Soruyorum: İyi misin diye;  Ruhla bedenin, Kaldığında baş başa, K...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iyi-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzde Unutulmuş', 'guzde-unutulmus-pablo-neruda-ztult', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat yedi buçuğuydu güzün

Ve ben bekliyordum

Kimi beklediğim önemli değil.

Günler, saatler, dakikalar

Bıktılar benle olmaktan

Çekip gittiler azar azar

Kaldım ortada, tek başıma

Kala kala kumla kaldım

Günlerin kumuyla, suyla

Bir haftanın artıklarıyla kaldım

Vurulmuş ve hüzünlü

Ne var, dediler bana Paris''in yaprakları

Kimi bekliyorsun? 

Kaç kez burun kıvırdılar bana 

Önce ışık, çekip giden

Sonra kediler, köpekler,  jandarmalar

Kalakaldım tek başıma

Yalnız bir at gibi

Otların üstünde ne gece, ne gündüz

Sadece kışın tuzu

Öyle kimsesiz kaldım ki

Öyle bomboş

Yapraklar ağladılar bana

Sonra, tıpkı bir gözyaşı gibi

Düştüler son yapraklar

Ne önceleri, ne de sonra

Hiç böyle yalnız kalmamıştım

Bu kadar

Ve kimi beklerken olmuştu

Hiç mi hiç hatırlamam.

Saçma ama bu böyle

Bir çırpıda oldu bunlar

Apansız bir yalnızlık

Belirip yolda kaybolan

Ve ansızın kendi gölgesi gibi

Sonsuz bayrağına doğru koşan.

Çekip gittim, durmadım

Bu çılgın sokağın kıyısından

Usul usul, basarak ayak uçlarıma

Sanki geceden kaçıyor gibiydim

Ya da karanlık, kükreyen taşlardan

Bu anlattıklarım hiç bir şey değil

Ama başıma geldi bütün bunlar

Birini beklerken bilmediğim

Bir zamanlar.', 'Saat yedi buçuğuydu güzün Ve ben bekliyordum Kimi beklediğim önemli değil. Günler, saatler, dakikalar Bıktılar benle olmaktan Çekip gittiler...', ARRAY['Türk Edebiyatı','Şiir','Pablo Neruda']::text[], 8.5, '{"poet":"Pablo Neruda","poet_slug":"pablo-neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/guzde-unutulmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanıyorum', 'kiskaniyorum-ferah-guneri-bircan-ewjzo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(seni can''lardan değil havadan,sudan ve topraktan kıskanırım...)

Havayı,

Toprağı ve suyu ; 

Kıskanıyorum !

Havayı kıskanıyorum !

Çünkü :

Teninle her an,

İç içe diye ;

Toprağı kıskanıyorum ! 

Çünkü :

Her  an senin,

Ayaklarının,

Altında diye ;

Suyu kıskanıyorum !

Çünkü :

Kimi zaman,

Dudaklarının arasından,

Yüreğine, 

Kimi zaman,

Başından aşağı,

Tüm bedenine,

Sana !

Hayat  veriyor diye ;

Ateşinle !

Terbiye ederek kendimi,

Bekliyorum !

Gel demeni .', '(seni can''lardan değil havadan,sudan ve topraktan kıskanırım...) Havayı, Toprağı ve suyu ;  Kıskanıyorum ! Havayı kıskanıyorum ! Çünkü : Ten...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kiskaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-pablo-neruda-uk5ql', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acılardan daha büyük bir yer yoktur

Bir tek evren var, o da kanayan bir evren.', 'Acılardan daha büyük bir yer yoktur Bir tek evren var, o da kanayan bir evren....', ARRAY['Türk Edebiyatı','Şiir','Pablo Neruda']::text[], 8.5, '{"poet":"Pablo Neruda","poet_slug":"pablo-neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-ferah-guneri-bircan-pt8xb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soramaz kimse! 

Hangi oranda,

Kime,

Ne verdin diye,

Sakın sorma sende,

Bana vereceğin,

Ne diye; 

Bugüne kadar,

Yaşamadım cananı,

Ama tanırım canı,

Bilirim ki can:

Bircan yarısı; 

Dün veya bugün! 

Hak etmese de,

Yaşattığıma değil de,

Yaşatana verdim,

Yarımı; 

Can! 

İnan canım sözcüğü,

Çok yabancı bana,

Sözcük olarak,

Çıktıysa da dudaktan,

Yaşam vizesi,

Verilmedi,

Benim ortaklardan; 

Sana verilmek üzere,

Ben istesem onlardan,

Sorarlar bana:

Gün gelirde giderse,

Ne koyacaksın,

Yerine diye; 

Asla! 

Önlerini görmeden,

Vermezler,

Canımı kimseye.', 'Soramaz kimse!  Hangi oranda, Kime, Ne verdin diye, Sakın sorma sende, Bana vereceğin, Ne diye;  Bugüne kadar, Yaşamadım cananı, Ama tanırım...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlelebet', 'i-lelebet-ferah-guneri-bircan-mh9q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldığım,

Nefes gibi,

Hem dışımda,

Hem de içimde; 

Gündüzümde,

Ve gecemde,

Ama daima,

Yaşamak isterim,

Ben seninle; 

Mekanım,

Toprak gibi,

Hem gelişimde,

Hem de gidişimde; 

Çiğnediğimde,

Ve yediğimde,

Ama daima,

Yaşamak isterim,

İlelebet! 

Ben seninle.', 'Aldığım, Nefes gibi, Hem dışımda, Hem de içimde;  Gündüzümde, Ve gecemde, Ama daima, Yaşamak isterim, Ben seninle;  Mekanım, Toprak gibi, He...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ilelebet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim', 'yarim-ferah-guneri-bircan-1hoia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biran tutmak için,

O şirin ellerini,

Gerekse bir ömür,

Beklemek seni:

Tereddüt etmeden,

İlelebet beklerim,

Ben yine,

Tüm varlığımla,

Yarim seni; 

Tek bir kare,

Rüyamda göreceğime,

İnansam çehreni,

Kapalı gözlerim ile,

Görmeden bedenini,

Uyandıramaz,

Hiç kimse beni; 

Yürekten bir defa:

Seni! 

Seni seviyorum! 

Bilsem diyeceğini; 

Şuuraltı aklıma,

Astığım gibi,

Yeryüzünün,

Tüm yüzeylerine,

Çerçevelettirir,

Astırırım! 

Senin,

Tüm portrelerini.', 'Biran tutmak için, O şirin ellerini, Gerekse bir ömür, Beklemek seni: Tereddüt etmeden, İlelebet beklerim, Ben yine, Tüm varlığımla, Yarim s...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-ferah-guneri-bircan-0gwtf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '( Bilemezsin seninle bir ömrü beraber ne kadar yaşamak istediğimi...... ? )

Sen :

Gözlerinde doğa, 

Bakışlarında derya,

Sevdamı yazmak isterim,

Yarınlara ;

Gel,

Gitmemek üzere,

Bir daha,

Anlatayım,

Anlatayım,

Yalnızca sana, 

Bir ömür yaşamak,

Bir ömür,

Yaşatmak uğruna ;

Irmak,

Irmak olmak isterdim,

Vadileri yararcasına,

Kızgın toprağın,

Suya kavuşurcasına,

Mümkün olsa,

Gitmek ister miyim,

Sensiz yarınlara ;

Koşmak !

Koşmak istemedim, 

İstemezdim de ışığa,

Kelebeğin ölüme koşarcasına ;

Uçmak !

Uçmak da istemezdim,

Avcılar görürde,

Belki vururlar diye,

Yalnızca,

Yalnızca !

Yaşamak istiyorum,

Seninle bir ömrü,

Doyasıya .', '( Bilemezsin seninle bir ömrü beraber ne kadar yaşamak istediğimi...... ? ) Sen : Gözlerinde doğa,  Bakışlarında derya, Sevdamı yazmak ister...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşey...', 'birsey-i-lksen-gunay-1q0r2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birşey var sende

Çözemediğim

Yüreğimde saplı bıçak gibi

Çekip alacağım,sonra öleceğim

Seni her andığımda

Yeni bir deftere başlayan

Küçük okul çocuklarının sevinci yüreğimde

Sevgin öyle taze,kıpır kıpır sevdam

Acıyan yanlarım yok değil!

Olsun,yine de güzel sevdan

Bir ağaç gölgesisin belki

Ulu bir ağaçsın benim için

Sırtımı yasladığım daim dostum

Huzur bulduğum

Benden önce doğmuş

Benim için doğmuş,dal vermiş büyümüş

Benimle ölecek ağaç,sensin gülüm

( 04.11.99 )', 'Birşey var sende Çözemediğim Yüreğimde saplı bıçak gibi Çekip alacağım,sonra öleceğim Seni her andığımda Yeni bir deftere başlayan Küçük oku...', ARRAY['Türk Edebiyatı','Şiir','İlksen Günay']::text[], 8.5, '{"poet":"İlksen Günay","poet_slug":"i-lksen-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birsey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünü...', 'bugunu-i-lksen-gunay-8jt66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugünü yarına ertelerken kaybettim herşeyi

Çabayı,aşkı,hayatı erteledim

Yarın olsun dedim

Kaybettim

Oysa,

Hiçbirşey zamanından sonra olmazdı

Herşey yaşandığı an güzeldi

Varolan herşeyin mükemmeli

Varolduğu anda saklı

Daha mükemmeli asla yaşanmıyor...

( 13.12.98 )', 'Bugünü yarına ertelerken kaybettim herşeyi Çabayı,aşkı,hayatı erteledim Yarın olsun dedim Kaybettim Oysa, Hiçbirşey zamanından sonra olmazdı...', ARRAY['Türk Edebiyatı','Şiir','İlksen Günay']::text[], 8.5, '{"poet":"İlksen Günay","poet_slug":"i-lksen-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hoscakal', 'hoscakal-i-lksen-gunay-06d1j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hoşçakal,

Bırakıp giderken seni ardımda

Hala beni sevdiğini ümid ediyorum

Ve beni özleyeceğini

Hiç düşünmüyorum bile

Karşılıksız sevdiğimi,tükendiğimi

Hatta kendime yalan söylediğimi

Bir çocuk saflığında

Nefreti aşka dönüştürecek bir yürek

Göğsümde taşıdığım

Benim bildiğim gibi...

Hoşçakal...

(25.03.99)', 'Hoşçakal, Bırakıp giderken seni ardımda Hala beni sevdiğini ümid ediyorum Ve beni özleyeceğini Hiç düşünmüyorum bile Karşılıksız sevdiğimi,t...', ARRAY['Türk Edebiyatı','Şiir','İlksen Günay']::text[], 8.5, '{"poet":"İlksen Günay","poet_slug":"i-lksen-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hoscakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Uyan Artık....', 'hadi-uyan-artik-sair-bogac-zlkn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hadi uyan,

