INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Hatırlatan Kadın', 'olumu-hatirlatan-kadin-faruk-nafiz-camlibel-rf5kd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayalıklarda gördüm seni, bir sisli günde,

Fırtınadan saçların çözülmüş bir demetti.

O kayalıklarda ki bir yıl evvel üstünde

Çöllerden aşık dönen bir genç intihar etti...

Seni her nerde, artık, her ne suretle görsem

Bir gölgenin duyarım ruhuma düştüğünü.

Ben de o aşık gibi bir kayada ölürsem

Rabb''im m
..........
..........', 'Kayalıklarda gördüm seni, bir sisli günde, Fırtınadan saçların çözülmüş bir demetti. O kayalıklarda ki bir yıl evvel üstünde Çöllerden aşık ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumu-hatirlatan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-faruk-nafiz-camlibel-sl5fj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorsun ki,oğlum,ortada ne sen varsın,

Ne seni yeryüzüne getirecek bir anne:

Bir gün cihana gelmen mukadderse,anlarsın,

Bu gelişten gözümü,gönlümü yıldıran ne?

Her gün saban başında topladığın kederler

Seni yorgun çıkarır sabahın altısına

Çalışkan ellerine bakanlar kirli derler,

Leke derler alnında güneş karaltısına.

İnce belin bükü
..........
..........', 'Biliyorsun ki,oğlum,ortada ne sen varsın, Ne seni yeryüzüne getirecek bir anne: Bir gün cihana gelmen mukadderse,anlarsın, Bu gelişten gözüm...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ogluma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçü Senin', 'ucu-senin-mustafa-i-pek-8pdep', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin en karanlık

İstanbul''un en aydınlık yerindeyim

Güllerin yedisi-kırmızıları-ellerimde

Üçü-solmuşları-ellerimin derinlerinde

İstanbul''un ve gecenin derinlerinde

Bekliyorum

Böyle yıllardır ayaktayım,yorgunum

Sadece gülleri vermek için

Sadece görmen için

Güllerin seni nasıl beklediğini

Bekliyorum

Gücünü ve sabrını nerden alıyor

Bilmiyorum

Bu güller

Bu benim ellerim

Ah gideceğim,gideceğim de

Ne güller soluyor ellerimde

Ne ellerim vazgeçiyor

Ne sen geliyorsun

Ne de ben ölüyorum

Canım İstanbul''da..', 'Gecenin en karanlık İstanbul''un en aydınlık yerindeyim Güllerin yedisi-kırmızıları-ellerimde Üçü-solmuşları-ellerimin derinlerinde İstanbul''...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İpek']::text[], 8.5, '{"poet":"Mustafa İpek","poet_slug":"mustafa-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ucu-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Size', 'benden-size-muzaffer-tayyip-uslu-sqem2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnız ben mi inkâr ediyorum Allahı

Mevsimler benden kafir

Ya kuşlar ve ağaçlara

Ne buyurulur

Uzun söze lüzum yok

Şahidimdir

Beş parasız gezindiğim sokak

Bir zaman yaşadığıma

Ve bir hatıra olsun diye

Benden size

Hiç sıkılmadan söyleyebilirim

Sarışın kızlara bayıldığımı', 'Yalnız ben mi inkâr ediyorum Allahı Mevsimler benden kafir Ya kuşlar ve ağaçlara Ne buyurulur Uzun söze lüzum yok Şahidimdir Beş parasız gez...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benden-size-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gramer Dersi', 'gramer-dersi-muzaffer-tayyip-uslu-8u60u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek'''' bir kelimedir

``Sarı saçlı'''' dersem bir kız için

Sıfat söylemiş olurum

``Ben sarı saçlı bir kız sevdim''''

Bir cümledir. Sevda dolu bir cümle

Nokta koymalı, durmalı zira

Zira ``açlık'''' da bir kelime

Cümleye gelmez sarı saçlı kız gibi

Ah elbet dolaşırsa ölüm sık sık dilime

``Öleceğim, ölüyorum, öldüm''''

Diyeceğim bir gün', 'Sevmek'''' bir kelimedir ``Sarı saçlı'''' dersem bir kız için Sıfat söylemiş olurum ``Ben sarı saçlı bir kız sevdim'''' Bir cümledir. Sevda dolu b...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gramer-dersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan', 'kan-muzaffer-tayyip-uslu-coy29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce öksürüverdim

Öksürüverdim hafiften,

Derken ağzımdan kan geldi

Bir ikindi üstü durup dururken

Meseleyi o saat anladım

Anladım ama, iş işten geçmiş ola

Şöyle bir etrafıma baktım,

Baktım ki yaşamak güzeldi hâlâ

Mesela gökyüzü,

Maviydi alabildiğince

İnsanlar dalıp gitmişti

Kendi alemine', 'Önce öksürüverdim Öksürüverdim hafiften, Derken ağzımdan kan geldi Bir ikindi üstü durup dururken Meseleyi o saat anladım Anladım ama, iş iş...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldükten Sonra', 'oldukten-sonra-muzaffer-tayyip-uslu-2mqnr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diyecekler ki arkamdan

Ben öldükten sonra

O, yalnız şiir yazardı

Ve yağmurlu gecelerde

Elleri cebinde gezerdi

Yazık diyecek

Hatıra defterimi okuyan

Ne talihsiz adammış

İmanı gevremiş parasızlıktan', 'Diyecekler ki arkamdan Ben öldükten sonra O, yalnız şiir yazardı Ve yağmurlu gecelerde Elleri cebinde gezerdi Yazık diyecek Hatıra defterimi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oldukten-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Düşünmek', 'olumu-dusunmek-muzaffer-tayyip-uslu-arat4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mümkün mü ağlasın annem

Mezarımın başucunda

Ben sesimi çıkarmıyayım

Hayırsız bir evlat gibi

Bir bulut uçsun da

Ben başımı kaldırmıyayım

Yağmur dindikten sonra

Gezinmiyeyim caddelerde

Ah, mümkün mü bir güzel kadın

Geçsin de yanımdan

Ben seyretmiyeyim

İçimi çekerek', 'Mümkün mü ağlasın annem Mezarımın başucunda Ben sesimi çıkarmıyayım Hayırsız bir evlat gibi Bir bulut uçsun da Ben başımı kaldırmıyayım Yağm...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumu-dusunmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüştü''den Gelen Mektup', 'rustu-den-gelen-mektup-muzaffer-tayyip-uslu-iigrk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-OKTAY RİFAT''A-

Önce bütün şairlere selam

Sonra şunu söylemek isterim

Ölüm hiçte güzel değil

Ne sabah var ne akşam

Sokakların ellerinden öperim

Bana yaşamasını öğretmişlerdi

Dost olsun düşman olsun

İnsanlara iyi günler dilerim

Söyle sarı saçlı daktiloya

Ben yokum artık

Vefasız dostlara hatırlat

Kimseye kalmaz o dünya

Nasıl unuturum güzeldi yaşamak

Fakat hakkı varmış Oktay''ın

"Hatıralar da dal istiyor

Kuşlar gibi konacak"', '-OKTAY RİFAT''A- Önce bütün şairlere selam Sonra şunu söylemek isterim Ölüm hiçte güzel değil Ne sabah var ne akşam Sokakların ellerinden öpe...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Tayyip Uslu']::text[], 8.5, '{"poet":"Muzaffer Tayyip Uslu","poet_slug":"muzaffer-tayyip-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/rustu-den-gelen-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Her Zaman Dostumsun', 'sen-her-zaman-dostumsun-susan-polis-schutz-f6ehm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen her zaman dostumsun

Mutluyken

Ya da üzgünken

Yanlızken

Ya da insanlarla beraberken

Sen her zaman dostumsun

Seni bu gün

Yada bir yıl sonra görsem

Seninle şimdi

Yada bir yıl sonra konuşsam

Ve yıllar gheçtikçe

Değişecek olsa bile

Benim ne yaptığımın

Yada senin ne yaptığının hiç önemi yok

Yaşamımız boyunca

Sen her zaman dostumsun

( Susan Polis Schutz''den )

	    Özlen Tuncer', 'Sen her zaman dostumsun Mutluyken Ya da üzgünken Yanlızken Ya da insanlarla beraberken Sen her zaman dostumsun Seni bu gün Yada bir yıl sonr...', ARRAY['Türk Edebiyatı','Şiir','Susan Polis Schutz']::text[], 8.5, '{"poet":"Susan Polis Schutz","poet_slug":"susan-polis-schutz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-her-zaman-dostumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayça', 'ayca-caglar-varol-doslf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni düşünmek kolay olsaydı Ayça

gecelerim böyle uzun sürer miydi

gözlerim dalıp gider miydi uzaklara

seni düşünmek kolay olsaydı

ölmek bu kadar zor gelir miydi bana

son yapraklarıyla bölüştüm seni

kibirli bir iklimden arda kalan güzün

ve dağıtır gibi saçlarımı

o esrik rüzgarda hüzün

seni düşünmek kolay olsaydı

savrulur muydum hayalinin ayazında

böyle esmer, böyle buruk

hiçbir zaman yağmayacak bir yağmurun

düşümdeki son bir kaç damlasında tutsak

anılarımın kıyısında bir evde

çakılıp kalır mıydım sence

seni düşünmek kolay olsaydı

sakinliğim yalancı bir kum tanesi ellerinde

vurup sırtıma çocukluğumu

yollara düşer miydim Ayça

ölmek bu kadar zor gelir miydi bana', 'seni düşünmek kolay olsaydı Ayça gecelerim böyle uzun sürer miydi gözlerim dalıp gider miydi uzaklara seni düşünmek kolay olsaydı ölmek bu k...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-samsunlu-birindar-4d50w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gidiyorum bende gidiyorum artık

bitmesini istemediğim bir aşkın son perdesi bu

elimde ayrılığın çiçekleri

gözümde yaşlarla gidiyorum 

yüreğimde derin bir acı

kalbimde kazılı isminle gidiyorum

yüreğimde derin bir acı var

bende gidiyorum artık

nereye gittiğimi hiç bilmeden 

ıssız ve karanlık sokaklardan geçiyorum

kabus dolu gecelerde

ismini sayıklayacağımı bilerek gidiyorum

artık ellerin ellerime değmeyecek

o güzelim saçlarını okşayamayacak

artık gözlerin gözlerime bakamayacak

bir daha dudağım dudağına dokunamayacak

artık bende gidiyorum

sana yazdığım bu son şiirimle 

sana veda ediyorum

artık bende gidiyorum 

ELVEDA SEVGİLİM...!!!', 'gidiyorum bende gidiyorum artık bitmesini istemediğim bir aşkın son perdesi bu elimde ayrılığın çiçekleri gözümde yaşlarla gidiyorum  yüreği...', ARRAY['Türk Edebiyatı','Şiir','Samsunlu Birindar']::text[], 8.5, '{"poet":"Samsunlu Birindar","poet_slug":"samsunlu-birindar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidiyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Küsersin Ya', 'sen-kusersin-ya-caglar-varol-jnqrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'El değmemiş acılar getir bana

Kederimle, boyumdan büyük olmalıyım

Zemheriden bir bulut çal bana

Yağdım mı, tane tane yağmalıyım

Sonbahar bitmez, sen küsersin ya

Depremidir sahipsiz heveslerin

Gitmelerin hazanlar çizer yüzüme

Sen gidersin ya, yetim kalırım

Sebepsiz ağlayan çocuklar getir bana

Hani duyurmak için açlığını

Sorarlarsa ''öpmeye'' dersin

Dudaklarında hiç bilmediğim 

                                 bir şarkı getir bana...', 'El değmemiş acılar getir bana Kederimle, boyumdan büyük olmalıyım Zemheriden bir bulut çal bana Yağdım mı, tane tane yağmalıyım Sonbahar bit...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-kusersin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayça - Gidersen', 'ayca-gidersen-caglar-varol-odo3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen renksiz

ve ümitsiz

bir kelebeği andırsan da

ellerimde

Düşünmedin Ayça

Gidersen

ne özgürlüğüm

ne tutsaklığım aynı

Yalnızca yüzün kalır bende

onyedisinde bir kente benzettiğim

Yalnızca yüzün kalır,

Bir de her dinleyişinde 

ağladığın o şarkılar

Sen bende değil

kendinde kaldın Ayça

Bense hep beyazı sevdim

Elllerine tutundukça..

Sen düşerken

her akşam

çocukluğumun gölgesi gibi

aklıma

anlamadın Ayça

unutursan

akdeniz yaralar beni

Yalnızca bir kaç sözcük

cümle cümle kanayan içimde

yalnızca sensin

uykusuzluğum..

Artık anla beni!

Sen benim dağlarıma

eylülden ayazlar ektin

Ben seni o dağlarda 

üşür gibi sevdim', 'Sen renksiz ve ümitsiz bir kelebeği andırsan da ellerimde Düşünmedin Ayça Gidersen ne özgürlüğüm ne tutsaklığım aynı Yalnızca yüzün kalır be...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ayca-gidersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gül', 'beyaz-gul-caglar-varol-d8cw0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Sonbahar geldi ve yapraklar, yavaş yavaş vedalaştı dallarıyla. Tıpkı senin gibi, onlarda kopacak yuvalarından; kuruyup gidecekler...

 Herşey değişti sen gidince. Kuşlar ötmez oldu. Güneş ağlamaklı bakıyor tepelerin ardından. Akşam rüzgarı savuramıyor saçlarımı eskisi gibi.

 Ve ben artık gülemiyorum...''

Çekip gitmek üzereyken buralardan

Yeşil gözlerinle ansızın karşıma çıktın

Zemheri ayazı esiyordu kentin sokaklarında

Rüzgarın sesini duyamıyordum ben

Üstüme yürüyordu çatlamış duvarlar

Ve senin adın yankılanıyordu kulaklarımda

Sigaramın son nefesinde sen vardın

Duyduğum her seste gördüğüm her yüzde

Kavgam olmuştun bir kere

Vazgeçemediğim sevdam olmuştun

Gittin gideli ben yaşamadım zaten

Aşımdın suyumdun ekmeğimdin

Damarlarımda akan kanım özgürlüğüm

Söylemeye kıyamadığım türkümdün sen

Beyaz Gül...', '''Sonbahar geldi ve yapraklar, yavaş yavaş vedalaştı dallarıyla. Tıpkı senin gibi, onlarda kopacak yuvalarından; kuruyup gidecekler...  Herşe...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyaz-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Synallagma', 'synallagma-caglar-varol-otl98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-gitme-

Öylesine söylenmiş her sözün

ardındaki kuşku sensin

sevgilim...

terkedilmiş bir hazan gibi

çırpınan hislerimde

güzelliğinden belki

belki de uzak bir şehirde

unuttuğundan

yüzündeki gülümsemeyi

Sen devirirken vakitsiz

bir sonbaharı üzerime

Ben yalnızlıklar üleştim 

ağlamaklı kent çocuklarıyla

Avuçlarına bıraktığım

o solmuş gül için gitme...

Çünkü bilemezsin

esrik bir ayrılık şiiridir gidişin

her dizesi ayrı ölümler çağrıştıran

sen unutsanda

her tökezleyişimde

dizlerinin dibine düştüğümü

unutsanda 

başımı omzuna dayayıp

gecelerce ağladığımı

Ne benim

ne de ellerin

kendinin olmak için gitme...', '-gitme- Öylesine söylenmiş her sözün ardındaki kuşku sensin sevgilim... terkedilmiş bir hazan gibi çırpınan hislerimde güzelliğinden belki b...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/synallagma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkibinden Habersiz', 'i-kibinden-habersiz-caglar-varol-nvv85', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Nazım Hikmet''e-

Titriyordu aç bir çocuk ıssız kuytularda

Bir dilim ekmeğin hayaliyle ısınıyordu

İlk o varmalıydı karşıki otelin çöplüğüne

ilk o almalıydı nasibini akşamki ziyafetten

Titriyordu, kentin ışıklarına tutunuyordu

-ikibinden habersiz

Yeni bir binyıldan bahsediyordu haber bültenleri

Umuttan, mutluluktan...

Lüks arabalarıyla beyfendilerimiz

Çoktan dağılmıştı ülkemin beş yıldızlı otellerine

kollarında medyatik fahişelerle

Milyarlar ekleniyordu, birilerinin milyarlarına

Dolarlar saçılıyordu gökyüzüne

Vur patlasın, çal oynasındı gece

Bastırıyordu yükselen kahkahalar

aç insanların feryatlarını.

Yeni bir binyıldan bahsediyordu haber bültenleri

Umuttan, mutluluktan...

Lüks arabalarıyla beyfendilerimiz

Dönüyordu yavaş yavaş

Saray yavrusu evlerine

gözlerinde alkolün perdesiyle

Ve artıkları toplamak için, çöpleri yoklayan çocuk

yumuyordu gözlerini hayata; E-5''in ortasında

Ömründe gördüğü en lüks arabanın altında ezilerek

-ikibinden habersiz

Ve mavi gözleriyle Nazım Hikmet

Süzülerek gökyüzünden usulca

Kucaklıyordu yolun ortasında cansız yatan çocuğu

Öperek onu kanayan yaralarından

Savuruyordu hiç ölmeyecek dizelerine

-ikibin, umrunda değil!..', '-Nazım Hikmet''e- Titriyordu aç bir çocuk ıssız kuytularda Bir dilim ekmeğin hayaliyle ısınıyordu İlk o varmalıydı karşıki otelin çöplüğüne i...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ikibinden-habersiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklık Ne Halına', 'asiklik-ne-halina-namdar-rahmi-karatay-ln046', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül sen ne sersemsin, ne körsün, ne sakarsın,

Yulaksız bir su gibi her güzele akarsın,

Neye sebepsiz yere yüreğini yakarsın,

Göz koymaktan ne çıkar elin günün malına

Çapıtına çuluna, aşıklık ne halına.

Bu kara bahtını sen kambur gibi taşırsın,

Bir de topal eşekle kervana karışırsın,

Eller arabasını dağdan dağa aşırsın,

Senin her gün bir kambur yüklenirken dalına,

Çapıtına çuluna, aşıklık ne halına.

Bunca yıl uma uma eridin bir mum gibi,

Bu umut mabudunu bekledin kayyum gibi,

Karardıkça karardı kara baht kurum gibi,

Bundan sonra devam et yine bakla falına,

Çapıtına çuluna, aşıklık ne halına.

Eller aştı denizi, oturdun mu sen şapa,

Herkesin yolu düz de seninki neden sapa,

Kulaklarını tıka gözlerini de kapa,

Bakma elin etine, kaymağına, balına,

Çapıtına çuluna, aşıklık ne halına.

Birisi yakalamış suna gibi bir kızı,

Öteki her gün sarar başka güzel yıldızı,

Senin içinde yanar hiç olmıyan bir sızı,

Güzeller geçer gider hep salına salına

Çapıtına çuluna, aşıklık ne halına.

Bu atalar sözüdür: Kim kazana kim yiye,

Gönül bağlamamalı bu dünyada her şeye,

Ah şu güzelin kaşı, vay gözü diye diye,

Ömrün dönüp gidecek bir yılan masalına

Çapıtına çuluna, aşıklık ne halına.', 'Gönül sen ne sersemsin, ne körsün, ne sakarsın, Yulaksız bir su gibi her güzele akarsın, Neye sebepsiz yere yüreğini yakarsın, Göz koymaktan...', ARRAY['Türk Edebiyatı','Şiir','Namdar Rahmi Karatay']::text[], 8.5, '{"poet":"Namdar Rahmi Karatay","poet_slug":"namdar-rahmi-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/asiklik-ne-halina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Geldik Gidiyoruz...', 'i-ste-geldik-gidiyoruz-namdar-rahmi-karatay-p3vzx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne beklerdin, ne buldun sen yeryüzünde hey serseri? 

Bilinir mi böyle yerde bir kimsenin öz değeri? 

Unut artık bunca yıldır tükettiğin emekleri,

Devlet kuşu konsa bile istemem ben bundan geri,

İşte geldik gidiyoruz, şen olasın Halep şehri.

Sen pişirdin, sen yoğurdun, elin hamur karnın açtır,

Kursağına düşen en son tuzsuz, yağsız bulamaçtır,

Kimse bilmez kim kazanır bu oyunda, bu bir maçtır,

Yediğimiz ekmek aşı, içtiğimiz alın teri,

İşte geldik gidiyoruz, şen olasın Halep şehri.

Uğraşırsın, çabalarsın, parasını eller alır,

Bir gölgeye benzer umut, bir uzanır bir kısalır,

Çok umuda düşen kişi karanlıkta yaya kalır,

Bir oyuncak sanmış idik bir zamanlar koca dehri,

İşte geldik gidiyoruz, şen olasın Halep şehri.

Yüze geldi düne kadar köşesinde keyf çatanlar,

Vatansever oldu çıktı başımıza kaltabanlar,

Bizler bugün buyruk kulu, onlar ise kahramanlar,

Biz batakta köprü olduk, başkaları geçti nehri,

İşte geldik gidiyoruz, şen olasın Halep şehri.

Bir kılkuyruk gelir sana çalım satar, kafa tutar.

Birer birer toplarsın sen, o binleri birden yutar,

Binbir çeşit ezgi hergün aşımıza ağı katar,

Bir boğazı tokluğuna çekiyorsun bunca kahrı,

İşte geldik gidiyoruz, şen olasın Halep şehri.

Dinlenmeden bir gün başım gençlik böyle geldi geçti,

Olan işler yüreğimde birer birer yara açtı,

Neden sonra alık gönül karanlıkta akı seçti,

Kutlu olsun gelenlere bu uğursuz konuk yeri

İşte geldik gidiyoruz, şen olasın Halep şehri.', 'Ne beklerdin, ne buldun sen yeryüzünde hey serseri?  Bilinir mi böyle yerde bir kimsenin öz değeri?  Unut artık bunca yıldır tükettiğin emek...', ARRAY['Türk Edebiyatı','Şiir','Namdar Rahmi Karatay']::text[], 8.5, '{"poet":"Namdar Rahmi Karatay","poet_slug":"namdar-rahmi-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iste-geldik-gidiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamanın Koyunu', 'karamanin-koyunu-namdar-rahmi-karatay-wvs0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oğul sana bir öğüt vereyim, dinle beni,

Ağzını açma sakın açarsan aç keseni,

En candan bildiklerin tefe koyarlar seni,

Birer birer denedik olgununu toyunu,

Karaman’ın koyunu sonra çıkar oyunu.

El oğlunu bilmezsin, o ne hin oğlu hindir,

Pamuk gibi görünür, granitten çetindir,

Arkandan kuyu kazar, dibi yoktur, derindir,

Açılma el oğluna anlamadan soyunu,

Karaman’ın koyunu sonra çıkar oyunu

Senin aybını arar el oğlu bir iş gibi,

Arkanda dolaşırlar sanki müfettiş gibi,

Bırakırlar ortada seni bir ibiş gibi,

Öğretirler dünyanın körfezini koyunu,

Karaman’ın koyunu sonra çıkar oyunu.

Doğruyu görürsen de ulu orta anlatma,

Bağır, çağır, nara at, fakat sakın taş atma,

Elini uzat amma, boynunu hiç uzatma,

Sana ölçü verirler, uzatırsan boynunu,

Karaman’ın koyunu sonra çıkar oyunu.

Ne tilkiye eğri bak, ne de kurtlarla yarış,

Ne etlisinden bahset, ne sütlüsüne karış,

Ağzını açık korlar sonra senin bir karış,

Nene gerek elin üç keçi, beş koyunu,

Karaman’ın koyunu sonra çıkar oyunu.', 'Oğul sana bir öğüt vereyim, dinle beni, Ağzını açma sakın açarsan aç keseni, En candan bildiklerin tefe koyarlar seni, Birer birer denedik o...', ARRAY['Türk Edebiyatı','Şiir','Namdar Rahmi Karatay']::text[], 8.5, '{"poet":"Namdar Rahmi Karatay","poet_slug":"namdar-rahmi-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karamanin-koyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poker Destanı', 'poker-destani-namdar-rahmi-karatay-uyb2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşiş’in eteğinde yasadım keşiş gibi

Bir lokma, bir hırkaya hu! diyen derviş gibi,

Arasıra destanlar yazarım bir iş gibi,

Bu aleme maksatsız, seyr-için gelmiş gibi

Harcadım hayatımı beş paralık fiş gibi.

Bu hayat pokerinde bize ancak pas düştü

Elime per gelmedi, ellere fulas düştü,

Şimdi artık mahvolan ömrüm için yas düştü,

Yoksulluk, kimsesizlik çöktü kara kış gibi,

Harcadım hayatımı beş paralık fiş gibi.

Bu oyunda ben neyim? Tam mahvolmuş bir adam,

Kiminde kare-vale, kiminde var kare-dam,

Bir blöfle rest dedim, yıkıldı başıma dam,

Umutlarım önümde devrildi kiriş gibi,

Harcadım hayatımı beş paralık fiş gibi.

Ne kazançlar ummuştum girerken bu oyuna,

Üstün eller vurdular, hiç durmadan boyuna

Şimdi tamam benzedim kurbanlık bir koyuna,

Herkes tapınıyorken kendine fetiş gibi,

Harcadım hayatımı beş paralık fiş gibi.

Hep zarara uğradım, oynadımsa kaç seans,

Ben pot dedim, başkası yaptı beş misli rölans,

Kör olsun, uğramadı bir kerecik kahpe şans,

Bütün meziyetlerim battı bana şiş gibi,

Harcadım hayatımı beş paralık fiş gibi.

Saadet uma uma geçti ömrün yarısı

Bilmem niçin düşmüyor başımıza darısı,

Balarısı olmadım, oldum eşek arısı,

Herkes çalım satarken canlı bir afiş gibi,

Harcadım hayatımı beş paralık fiş gibi.', 'Keşiş’in eteğinde yasadım keşiş gibi Bir lokma, bir hırkaya hu! diyen derviş gibi, Arasıra destanlar yazarım bir iş gibi, Bu aleme maksatsız...', ARRAY['Türk Edebiyatı','Şiir','Namdar Rahmi Karatay']::text[], 8.5, '{"poet":"Namdar Rahmi Karatay","poet_slug":"namdar-rahmi-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/poker-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maki', 'maki-sunay-akin-5izbv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir an önce görülsün

diye Akdeniz

Toroslar''da ağaçlar

hep çocuk

kalır', 'Bir an önce görülsün diye Akdeniz Toroslar''da ağaçlar hep çocuk kalır...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/maki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kurusu', 'kiz-kurusu-sunay-akin-r55vs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pulsuz zarf gibisin 

üstünde adresi 

