INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Kasideleri', 'yasamak-kasideleri-nazim-hikmet-ran-tgj78', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağıldı birdenbire

alnına düsen saclar.

Birdenbire toprakta bir şeyler kımıldadı.

Bir şeyler konuyor

karanlıkta ağaçlar.

Çıplak kolların üşüyecek.

Uzaklarda

göremediğimiz bir yerde

ay doğuyor demek.

O daha yapraklardan inip

senin omsuzunu aydınlatarak

gelmedi bize kadar.

Rüzgar çıkar ay doğarken.

Ağaçlar konuyor.

Kolların üşüyecek.

Yukardan

karanlıkta kaybolan dallardan

bir 
..........
..........', 'Dağıldı birdenbire alnına düsen saclar. Birdenbire toprakta bir şeyler kımıldadı. Bir şeyler konuyor karanlıkta ağaçlar. Çıplak kolların üşü...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamak-kasideleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabirde', 'kabirde-sebat-mercek-8s7zf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fani dünyadan ne getirdin? 

Artık o dünyanı yitirdin.

Cevap ver bakalım, soru: bir,

“Sen ömrünü nasıl geçirdin? ”

Geldin dört tahta kollarda,

Ne çıkar aradın kullarda? 

Haydi cevap ver, soru: iki,

“Giden gençlik hangi yollarda? ”

Bazen hesap edip yazandın,

Bazen beleş bulup azandın.

Cevap ver bakalım, soru: üç,

“Malını nasıl kazandın? ”

Kaybettin elinden dalını,

Kimler getirdi şu salını.

Cevap ver bakalım, soru: dört,

“Nereye harcadın malını? ”

Ruh ve beden... kemiktin, ettin.

Bir akılla dünyaya yettin.

Cevap ver bakalım, soru: beş,

“Şu ilminle ne amel ettin? ”', 'Fani dünyadan ne getirdin?  Artık o dünyanı yitirdin. Cevap ver bakalım, soru: bir, “Sen ömrünü nasıl geçirdin? ” Geldin dört tahta kollarda...', ARRAY['Türk Edebiyatı','Şiir','Sebat Mercek']::text[], 8.5, '{"poet":"Sebat Mercek","poet_slug":"sebat-mercek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kabirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Memleketim Üstüne Söylenmiştir', 'yine-memleketim-ustune-soylenmistir-nazim-hikmet-ran-4crrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Memleketim, memleketim, memleketim, 

ne kasketim kaldı senin ora işi

ne yollarını taşımış
..........
..........', 'Memleketim, memleketim, memleketim,  ne kasketim kaldı senin ora işi ne yollarını taşımış .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yine-memleketim-ustune-soylenmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Dair', 'yasamaya-dair-nazim-hikmet-ran-g2tjx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1

Yaşamak şakaya gelmez, 

büyük bir ciddiyetle yaşayacaksın

bir sincap gibi mesela, 

yani, yaşamanın dışında ve ötesinde hiçbir şey beklemeden, 

yani bütün işin gücün yaşamak olacak.

Yaşamayı ciddiye alacaksın, 

yani o derecede, öylesine ki, 

mesela, kolların bağlı arkadan, sırtın duvarda, 

yahut kocaman gözlüklerin, 

beyaz gömleğinle bir laboratuarda

insanlar için ölebileceksin, 

hem de yüzünü bile görmediğin insanlar için, 

hem de hiç kimse seni buna zorlamamışken, 

hem de en güzel en gerçek şeyin

yaşamak olduğunu bildiğin halde.

Yani, öylesine ciddiye alacaksın ki yaşamayı, 

yetmişinde bile, mesela, zeytin dikeceksin, 

hem
..........
..........', '1 Yaşamak şakaya gelmez,  büyük bir ciddiyetle yaşayacaksın bir sincap gibi mesela,  yani, yaşamanın dışında ve ötesinde hiçbir şey beklemed...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasamaya-dair-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Misal', 'masal-misal-sebat-mercek-3fafi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meselâ diyelim, anlatalım bir masal; 

Hem anlatalım hem de bulalım bir misal.

Yalnız dikkat edelim ki, olmalı  yasal,

                                        Balta taşa kaçmasın.

                                         İt ağzını açmasın, 

                                         Salyaları saçmasın.

                                         Aman ite dalaşma,

                                         Çalıyı da dolaşma.

Kendini beğenmiş, bilgiçlik taslayan göz; 

Ne görse anlatmış, bir türlü bitmemiş söz.

Ne kömür bırakmış anlatmadık ne de köz.

                                          Kulak duymadım demiş,

                                          Burun kokmadı demiş.

                                          Dil de tatmadım demiş.

                                          Göze  “deli”  demişler,

                                          Alay edip gülmüşler.

Kulak duyduklarını anlatmak istemiş,

Ona göre bütün bilgiler seste imiş.

Çok gürültü çekmiş, sanki kafeste imiş.

                                         Göz görmeden inanmaz.

                                         Dil içerden tadamaz,

                                         Burun da ses koklamaz.

                                         “Yalancısın” demişler,

                                         Alay edip gülmüşler.

Burun koku anlatmış, inandıramamış; 

Dil de tadı anlatmış, inandıramamış.

Akıllarınca onları kandıramamış.

                                         Fikir yok ki, yarışsın.

                                         Saygı yok ki, kanışsın.

                                         Beyin yok ki danışsın.

                                         Ben diyeyim masallık,

                                         Siz deyin ki misallik.', 'Meselâ diyelim, anlatalım bir masal;  Hem anlatalım hem de bulalım bir misal. Yalnız dikkat edelim ki, olmalı  yasal,                       ...', ARRAY['Türk Edebiyatı','Şiir','Sebat Mercek']::text[], 8.5, '{"poet":"Sebat Mercek","poet_slug":"sebat-mercek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/masal-misal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
