INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '5 Kasım 1945', '5-kasim-1945-nazim-hikmet-ran-pkj3n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçekli badem ağaçlarını unut.

Değmez,

bu bahiste

geri gelmesi mü
..........
..........', 'Çiçekli badem ağaçlarını unut. Değmez, bu bahiste geri gelmesi mü .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/5-kasim-1945-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asya Afrika Yazarlarına...', 'asya-afrika-yazarlarina-nazim-hikmet-ran-9p9fh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kardeşlerim 

bakmayın sarı saçlı olduğuma 

ben Asyalıyım 

bakmayın mavi gözlü olduğuma 

ben Afrikalıyım 

ağaçlar kendi dibine gölge vermez benim orda 

sizin ordakiler gibi tıpkı 

benim orda arslanın ağzındadır ekmek 

ejderler yatar başında çeşmelerin 

ve ölünür benim orda ellisine basılmadan 

sizin ordaki gibi tıpkı 

ba
..........
..........', 'Kardeşlerim  bakmayın sarı saçlı olduğuma  ben Asyalıyım  bakmayın mavi gözlü olduğuma  ben Afrikalıyım  ağaçlar kendi dibine gölge vermez b...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/asya-afrika-yazarlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağa Kalkın Efendiler', 'ayaga-kalkin-efendiler-nazim-hikmet-ran-y8czd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Behey! kaburgalarında ateş bir yürek yerine

idare lambası yanan adam! 

Behey armut satar gibi

san''atı okkayla satan san''atkar! 

Ettiğin kâr

kalmayacak yanına! 

soksan da kafanı
..........
..........', 'Behey! kaburgalarında ateş bir yürek yerine idare lambası yanan adam!  Behey armut satar gibi san''atı okkayla satan san''atkar!  Ettiğin kâr ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayaga-kalkin-efendiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senden Önce Ölmek İsterim', 'ben-senden-once-olmek-i-sterim-nazim-hikmet-ran-y7nve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben 

senden önce ölmek isterim. 

Gidenin arkasından gelen 

gideni bulacak mı zannediyorsun? 

Ben zannetmiyorum bunu. 

İyisi mi, beni yaktırırsın, 

odanda ocağın üstüne korsun 

                    içinde bir kavanozun. 

Kavanoz camdan olsun, 

şeffaf, beyaz camdan olsun 

                    ki içinde beni görebilesin... 

Fedakârlığımı anlıyorsun: 

vazgeçtim toprak olmaktan, 

vazgeçtim çiçek olmaktan 

                        senin yanında kalabilme
..........
..........', 'Ben  senden önce ölmek isterim.  Gidenin arkasından gelen  gideni bulacak mı zannediyorsun?  Ben zannetmiyorum bunu.  İyisi mi, beni yaktırı...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-senden-once-olmek-isterim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hazin Hürriyet...', 'bir-hazin-hurriyet-nazim-hikmet-ran-fzkkm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Satarsın gözlerinin dikkatini, ellerinin nurunu, bir lokma bile tatmadan 

yoğurursun 

bütün nimetlerin hamurunu. 

Büyük hürriyetinle çalışırsın el kapısında, ananı ağlatanı 

Karun etmek hürriyetiyle hürsün! 

Sen doğar doğmaz dikilirler tepene, 

işler ömrün boyunca durup dinlenmeden yalan 

değirmenleri, 

büyük hürriyetinle parmağın şakağında düşünürsün vicdan
..........
..........', 'Satarsın gözlerinin dikkatini, ellerinin nurunu, bir lokma bile tatmadan  yoğurursun  bütün nimetlerin hamurunu.  Büyük hürriyetinle çalışır...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-hazin-hurriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Küvet Hikayesi...', 'bir-kuvet-hikayesi-nazim-hikmet-ran-ai6w6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1 

Süleyman''a karısı telefon etti: 

— Konuşan ben, 

ben, Fahire. 

Tanımadın mı sesimden? 

Demek çok bağırdım birdenbire. 

Çığlık mı? 

Belki... 

Hayır, 

çocuklar hasta değil. 

Dinle beni: 

İşini bırak da gel, 

çabuk ol ama. 

Telefonda anlatamam, 

olmaz. 

Daha kıyamet kadar vakit var akşama. 

Saatlar, saatlar, 

kıyamet kadar. 

Sorma. 

Dinle beni... 

Hemen vapur bulamazsan 

Üsküdar''a kayıkla geç. 

Bir taksiye atla. 

Paran yoksa 

patrondan avans al. 

Yolda hiçbir şey düşünme, 

mümkün mertebe yalansız gelmeye çalış. 

Yalan kuvvetliye söylenir 

ben kuvvetsizim. 

Alay etme kuzum. 

Evet kar yağacak, 

evet 

hava güzel. 

Koynuna girdiğim adam gibi 

kocam gibi değil, 

büyüğüm, akıllım, 

babam gibi gel... 

2 

Geldi Süleyman, 

Fahire, kocası Süleyman''a sordu: 

— Doğru mu? 

— Evet. 

— Teşekkür ederim Süleyman. 

Bak işte rahatladım. 

Bak işte ağlamıyorum artık. 

Nerde buluşuyordunuz? 

— Bir otelde. 

— Beyoğlu tarafında mı? 

— Evet. 

— Kaç defa? 

— Ya üç, ya dört. 

— Üç mü, dört mü? 

— Bilmiyorum. 

— Bunu hatırlamak bu kadar mı güç Süleyman? 

— Bilmiyorum. 

— Demek ki bir otel odasında. 

Kim bilir çarşaflar nasıl kirliydi. 

Bir İngiliz romanında okudum, 

bu işlere yarayan otellerde 

kırık küvetler varmış. 

Sizinkinde de var mıydı Süleyman? 

— Bilmiyorum. 

— Hele düşün, 

toz pembe çiçekli, kırık bir küvet? 

— Evet. 

— Hiç hediye verdin mi? 
..........
..........', '1  Süleyman''a karısı telefon etti:  — Konuşan ben,  ben, Fahire.  Tanımadın mı sesimden?  Demek çok bağırdım birdenbire.  Çığlık mı?  Belki....', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/bir-kuvet-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük İnsanlık...', 'buyuk-i-nsanlik-nazim-hikmet-ran-t033d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük insanlık gemide güverte yolcusu

tirende üçüncü mevki

şosede yayan

büyük insanlık.

Büyük insanlık sekizinde işe gider

yirmisinde
..........
..........', 'Büyük insanlık gemide güverte yolcusu tirende üçüncü mevki şosede yayan büyük insanlık. Büyük insanlık sekizinde işe gider yirmisinde .........', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyuk-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çankırı Hapishanesinden (Mektuplar-1)', 'cankiri-hapishanesinden-mektuplar-1-nazim-hikmet-ran-ao7y6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat dört 

yoksun 

Saat beş 

yok 

Altı, yedi, 

ertesi gün, daha ertesi 

ve belki 

kim bilir... 

Hapisane avlusunda 

bir bahçemiz vardı. 

Sıcak bir duvar dibinde on beş adım kadardı. 

Gelirdin, 

yan yana otururduk, 

kırmızı ve kocaman 

muşamba torban dizlerinde... 

Kelleci Memedi hatırlıyor musun? 

Sübyan koğuşundan. 

Başı dört köşe, 

bacakları kı
..........
..........', 'Saat dört  yoksun  Saat beş  yok  Altı, yedi,  ertesi gün, daha ertesi  ve belki  kim bilir...  Hapisane avlusunda  bir bahçemiz vardı.  Sıc...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cankiri-hapishanesinden-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
