INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinize Ve Yalana Dair', 'ellerinize-ve-yalana-dair-nazim-hikmet-ran-ja026', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün taşlar gibi vakarlı, 

hapiste sÖylenen bütün tÜrkÜler gibi kederli, 

bütün yük hayvanları gibi battal, ağır

ve aç çocukların dargın yüzlerine benzeyen elleriniz.

Arılar gibi hünerli, hafif, 

sütlü memeler gibi yuklu, 

tabiat gibi cesur

ve dost yumuşaklıklarını haşin derilerinin altında gizleyen elleriniz.

Bu dünya öküzün boynuzunda değil, 

bu dünya ellerinizin üstünde duruyor.

Ve insanlar, ah, benim insanlarım, 

yalanla besliyorlar sizi, 

halbuki açsınız, 

etle, ekmekle beslenmeğe muhtaçsınız.

Ve beyaz sofrada bir kere b
..........
..........', 'Bütün taşlar gibi vakarlı,  hapiste sÖylenen bütün tÜrkÜler gibi kederli,  bütün yük hayvanları gibi battal, ağır ve aç çocukların dargın yü...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ellerinize-ve-yalana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Mühim Mesele', 'en-muhim-mesele-nazim-hikmet-ran-gmp6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprak doyurası gözleri doymuyor

Çok para kazanmak istiyorlar;

öldürmemiz, ölmemiz lazım geliyor

çok para kazanmaları için.

Elbet de aşikare yapmıyor
..........
..........', 'Toprak doyurası gözleri doymuyor Çok para kazanmak istiyorlar; öldürmemiz, ölmemiz lazım geliyor çok para kazanmaları için. Elbet de aşikare...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-muhim-mesele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum Ve Sivas Kongreleri', 'erzurum-ve-sivas-kongreleri-nazim-hikmet-ran-3cinj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz ki İstanbul şehriyiz, 

iste, arz ederiz halimizi

Türk halkının yüce katına.

Mevsim yazdır, 

919''dur.

Ve teşrinlerinde gecen yılın

dört düvele teslim ettiler bizi, 

gözü kanlı dört düvele

anadan doğma çırılçıplak.

Ve kurumuştu

ve kan içindeydi memelerimiz.

Biz ki İstanbul şehriyiz, 

Fransız, İngiliz, İtalyan, Amerikan

bir de Yunan, 

bir de zavallı Afrika zencileri

yer bitirir bizi bir yandan, 

bir yandan da kendi köpek döllerimiz: 

Vahdettin Sultan, 

ve Damat Ferit

ve
..........
..........', 'Biz ki İstanbul şehriyiz,  iste, arz ederiz halimizi Türk halkının yüce katına. Mevsim yazdır,  919''dur. Ve teşrinlerinde gecen yılın dört d...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/erzurum-ve-sivas-kongreleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin...', 'gozlerin-nazim-hikmet-ran-ui8g9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerin gözlerin, 

ister hapisaneme, ister hastaneme gel, 

gözlerin gözlerin gözlerin hep güneşte, 

şu Mayıs ayı sonlarında öyledir işte 

Antalya tarafında ekinler seher vakti. 

Gözlerin gözlerin gözlerin, 

kaç defa karşımda ağladılar 

çırılçıplak
..........
..........', 'Gözlerin gözlerin gözlerin,  ister hapisaneme, ister hastaneme gel,  gözlerin gözlerin gözlerin hep güneşte,  şu Mayıs ayı sonlarında öyledi...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
