INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yaraları', 'gonul-yaralari-halil-kaytazoglu-653kg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey gönül kendine gel ,aldanma tatlı söze.

Bir dirhem zevkin için niye gelirsin dize?

Hayat dediğin ne ki ,kaşla göz arasında;

Bin bir acı var dostum ,bir gönül yarasında.

Gönül sakın aldanma bu dünya tos pembedir.

En tatlı tebessümü bile insan ürpertir.

İşte hayat böyledir doğdun ölene kadar;

Gönül yaralarına bin bir yaralar katar.', 'Ey gönül kendine gel ,aldanma tatlı söze. Bir dirhem zevkin için niye gelirsin dize? Hayat dediğin ne ki ,kaşla göz arasında; Bin bir acı va...', ARRAY['Türk Edebiyatı','Şiir','Halil Kaytazoğlu']::text[], 8.5, '{"poet":"Halil Kaytazoğlu","poet_slug":"halil-kaytazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonul-yaralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-vedat-kamer-14fpa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığının bitişinin mutluluğu

Dönüştü yıldızların ışığına

Kan gözyaşları ise bitmişti

Rüzgarın onları uzağa götürmesiyle

Umutlar yeşermişti kuzey yıldızının ışığıyla

Gümüş bir ağacın gölgesi kadar huzurlu

Sessizliğin sözcüklere dönüşmesi kadar güzel

Ve dostluğumuz kadar ölümsüz', 'Yalnızlığının bitişinin mutluluğu Dönüştü yıldızların ışığına Kan gözyaşları ise bitmişti Rüzgarın onları uzağa götürmesiyle Umutlar yeşermi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Kamer']::text[], 8.5, '{"poet":"Vedat Kamer","poet_slug":"vedat-kamer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umutlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç-Güç-Hiç', 'gec-guc-hic-refet-altan-ft01z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''''Geç'''' di bir zamanlar,

Şimdi,

''''Güç'''' oldu söylediklerim.

Bir gün gelecek belki,

''''Hiç'''' olacak

bütün düşündüklerim....

27.08.1972', '''''Geç'''' di bir zamanlar, Şimdi, ''''Güç'''' oldu söylediklerim. Bir gün gelecek belki, ''''Hiç'''' olacak bütün düşündüklerim.... 27.08.1972...', ARRAY['Türk Edebiyatı','Şiir','Refet Altan']::text[], 8.5, '{"poet":"Refet Altan","poet_slug":"refet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gec-guc-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay-Zor', 'kolay-zor-pinar-altanoglu-c11cl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anımsamak kolay

yaşanmıştır anımsananlar.

Hayal etmek zor

belki hiç yaşanmaz onlar.

yaşanamayacağından

yaşananı hayal etmek,

yaşanmayanı anımsamaksa

hepsinden zor olsa gerek...

(27.05.1988 İstanbul)', 'Anımsamak kolay yaşanmıştır anımsananlar. Hayal etmek zor belki hiç yaşanmaz onlar. yaşanamayacağından yaşananı hayal etmek, yaşanmayanı anı...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kolay-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-pinar-altanoglu-i45tm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey bir oyundu sanki,

gitmelerle kalmalar

arasında....

Her oyunda bir baş

bir son

vardı hani....

başlamalarla

bitmeler

diyarında...

Sonra,

sonra sen çıktın karşıma,

ilkle sonun,

doğruyla yanlışın,

gitmekle kalmanın

anlamını kaybettim....

Başlıyorum derken

bitirdim,

gidiyorum derken

hep sana 

hep sana geldim...

(Nisan 92  İstanbul)', 'Her şey bir oyundu sanki, gitmelerle kalmalar arasında.... Her oyunda bir baş bir son vardı hani.... başlamalarla bitmeler diyarında... Sonr...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-pinar-altanoglu-j1ars', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çift gördüm,

bir araba

yol parke...

Kadındaki sır

hayatın içinde,

gün güneşle aydınlık

güz şahane,

yaşananda geçikmişlik sadece....

İki ayrı yaşam rengi

birleşmiş,

güneş doğmuş

ay yerine çekilmiş,

yeşil maviyle sevişmiş,

sevdaları şiir kadar

gerçekmiş.

(Ocak 92 Yalova)', 'Bir çift gördüm, bir araba yol parke... Kadındaki sır hayatın içinde, gün güneşle aydınlık güz şahane, yaşananda geçikmişlik sadece.... İki ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Yelekleri Tavandadır'' Dan', 'can-yelekleri-tavandadir-dan-ozdemir-i-nce-965du', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '[ . . ]

Karada, denizde ve havada, kutlu olsun,

yeşil gözlerde, hokka ağızda, tas memelerde;

Her zaman ve her yerde, kutlu olsun,

ömrümüzün şarapları dolarken seher vaktinde;

Senlikte, bollukta, zenginlikte, kutlu olsun,

engin göz halkalarında, mavi ve lacivertte;

Savaşta ve barışta, harp ve sulhta, kutlu olsun,

tek bir atlı, yek süvari mürur edip geçerken de;

Karakolda, morgda, mezarlıkta kutlu olsun,

şehit ve gazilerde, temsili düşman kuvvetlerinde;

Bankalarda, faizlerde, batik kredilerde kutlu olsun,

Tarabya''da, dinamizm ve konforda, Etilerde;

Eşcinsellikte, ablacılıkta, oğlancılıkta, kutlu olsun,

hakem oyunlarında, Ermeni ve Yunan lobilerinde;

Kaptıkaçtıda, dolmuşta, limuzinde kutlu olsun,

Armani''de, Bulgari''de, Türk-İslam sentezinde;

Demirin pasında, camin kırığında, kutlu olsun,

şükran ve minnet duygularıyla papatya sepetinde;

 (1), âmin,

 (2)

-- Can yelekleri tavandadır!

&

Kusursuz bir cinayet islemek için yıldızlar savasında

Görmek için kapalı tribünde Iran-Irak savaşını

Cennetin doğusuna göndermek için grevci isçileri

Bitpazarında satmak için kale ve burçları

Evde kalmış kızlar için yetmiş 

Düşman şaşırtmak için üç yüz altmış , yüz bir 

Zengin olmak için üçgen ve dörtgen muskalar

Bin Bir Gece için yeni şehzadeler, yeni beberuhiler

Devlet için yeni bir Sahriyar, yeni bir Sahzaman

Mülk için yeni bir Nizamulmulk ve kırk haramileri

Yeni bir halk için tasavvuf ve tarikat adâbı

Gönül birliği için Sehrazad ve denizci Sinbad

Asi kadınlar ve genç kızlar için anlamlı bir açıklama:

 (3)

-- Can yelekleri tavandadır!

&

Bir tılsımlı gömlek gerek artık sana

halk kılığına girip halka karıştığın zaman

Sultan Cemin gömleğinin bir esi gömlek

Topkapı Sarayı’ndaki,

kılıç kesmesin diye etini

ok yürümesin damarlarında

kursun islemesin kemiğine

kement boynunu sıkmasın

eline çivi batmasın

ayakkabı vurmasın ayağını

ve görünmez olasın istediğin zaman

Battal Gazı’nın kılığına giresin

basın sıkısınca

avlucunda Hasreti Ali''nin kılıcını

tutasın

(Kalçayı saran elbiseler, romantik

kloş_ ve kemerli etekler,

bolerolar. Çok geniş paçalı ya da

sigara darlığında pantolonlar...)', '[ . . ] Karada, denizde ve havada, kutlu olsun, yeşil gözlerde, hokka ağızda, tas memelerde; Her zaman ve her yerde, kutlu olsun, ömrümüzün ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/can-yelekleri-tavandadir-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar Arasında', 'dort-duvar-arasinda-ozdemir-i-nce-pbxqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şeyler kapanıyordu bir yerlerde,

belki bir kapı, belki bir mezar -

ama çatı değildi - sanki bir yangın,

tavşanların, kuşların hızından anlıyordun,

ama çatı değildi kapanan,

üzerinde bir bayrak dalgalanan.

Ama çatı değildi kapanan; 

biraz daha ışık, diye haykırdın,

dağlarıma ve uçurumlarıma,

hepsini gövdeme

duvarlarıma kazıyacağım.

Bir şeyler kapanıyordu bir yerlerde:

Kiminin bahtı, kiminin yüreği,

kiminin kapısı ve penceresi.

Düşündün: Her şey bütün bir sonsuzluk

ve bir dakikaydı önünde ve sonunda.

Bir dakika, o senin olan bir dakika,

yani yaşaman için sana bırakmadıkları.', 'Bir şeyler kapanıyordu bir yerlerde, belki bir kapı, belki bir mezar - ama çatı değildi - sanki bir yangın, tavşanların, kuşların hızından a...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dort-duvar-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandıklı Pazarındaki Çingene Kadın', 'sandikli-pazarindaki-cingene-kadin-ozdemir-i-nce-2uzfw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birden anımsadın bunca yıl sonra

o gördüğün badem gözlü

çingene kadını

tam yirmi beş yıl önce

Sandıklı pazarında.

Şimdiye kadar hiçbir kadın

öyle bakmadı

meydan okumadı sana;

gözlerini gördün

bir anda sevişip ayrıldınız.

Gökyüzüyle birlikte bakmıştı sana,

çaktırmadan arasta esnafında.', 'Birden anımsadın bunca yıl sonra o gördüğün badem gözlü çingene kadını tam yirmi beş yıl önce Sandıklı pazarında. Şimdiye kadar hiçbir kadın...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sandikli-pazarindaki-cingene-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şubat Ayında Ankara''da Yazılan Bir Şiir', 'subat-ayinda-ankara-da-yazilan-bir-siir-ozdemir-i-nce-7r4ep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yıl erken bastırdı kış

yağmur yağıyor, yağmur yağdıkça seviyorum seni

kar yağıyor, kar yağdıkça seviyorum seni.

karaya vurdukça, sular dondukça

üşüdükçe, bir şeyler yitirdikçe, umudum kırıldıkça

çıkmaza girdikçe yaşam, yüreğim sıkıştıkça,

sen değiştikçe daha çok seviyorum seni.

Donmuş suda çelik tadı var

ağzımda eski tütün ve buruk çay tadı

her sabah yaya geçiyorum bütün Ankara’yı

kömür ve kükürt kokuları arasında

her akşam yaya geçiyorum bütün Ankara’yı

okuyarak bildirilerini direnen öğrencilerin

bakarak yırtık afişlere, şarkıcı resimlerine,

nereye gitsem içimde bir geç kalmışlık duygusu

bu yüzden bir saat erken gidiyorum gideceğim yere

ne zaman, nerede ve nasıl bilmiyorum, ama birden

yaşamın korkunç bir hızla değiştiğini düşünüyorum

ve ikimizin aynı kişiler olmayacağımızı yarın.

Bu yıl erken bastıran kışı yaşıyoruz

sanki ölümlü kahramanlarıyız kő tü bir romanın

yeni bir dilin sözdizimine çalışıyoruz

gökyüzünü verip yüzünü alıyorum

görüntünü verip acıları siliyorum

yüzünü koyuyorum umutsuzluğun yerine

Usumda sesinin ve gövdenin

usumda sesinin ve gövdenin görkemli atlası.', 'Bu yıl erken bastırdı kış yağmur yağıyor, yağmur yağdıkça seviyorum seni kar yağıyor, kar yağdıkça seviyorum seni. karaya vurdukça, sular do...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/subat-ayinda-ankara-da-yazilan-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nakkas Ariyorum', 'bir-nakkas-ariyorum-murat-kayali-ayf3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'asik bir yüregin

kara kapli lügatindan

kim okur ve anlar?

bagrimda acik duruyor sayfalari

ben sirrina varamadim

bu safkan yazilari okuyup anlayamadim

Mecnun-Yusuf-Sehrazat-Leyla ve Züleyha ya soramadim

yasar bir ask-asik bulamadim

canini yazilara adamis bir katip ariyorum

varsa beri gelsin...

icimde kivrilan arabeskleri dillendirsin

asik bir yüregin

yüzünü karsisina almadan

kim cizebilir ve resmedebilir?

aslindan uzaklastirmadan

istiyorum ki cizsin; bir altin varaga

hakkini versin akin-aka, karanin-karaya

nar rengi ile kani karistirmasin

un beyazlar kar beyaz olmasin

acigim-acikta ve gölgem-gölgede kalsin

gözlerine-ellerine suret kök salmis

bir nakkas ariyorum

varsa beri gelsin...

icimde dolasan mechulleri resimlendirsin

asik bir yüregin

bahcesine girmeden

güllerimi kim desteleyebilir?

parmagina dikenimi batirmam

dalima vuran bicagina karsi koymam

istiyorum ki; gel beni kucak kucak topla

git dök beni yarimin ayagina

götür koy beni onun basucuna

kokumu soluklansin, sürsün beni yanagina

caliya-cirpiya cicek actirmis

bir bahcevan ariyorum

varsa beri gelsin...

icimde solanlara su versin', 'asik bir yüregin kara kapli lügatindan kim okur ve anlar? bagrimda acik duruyor sayfalari ben sirrina varamadim bu safkan yazilari okuyup an...', ARRAY['Türk Edebiyatı','Şiir','Murat Kayalı']::text[], 8.5, '{"poet":"Murat Kayalı","poet_slug":"murat-kayali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-nakkas-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katran oldu yar beklemekten gözlerim', 'katran-oldu-yar-beklemekten-gozlerim-zeynep-simsek-34gqo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'buğulu bir rüzgardı geçecek

beklemenin anlamı kalmadı

çare de yok beklemekten

ayrılık hevesleri öldürdü

kim kimdi bilinmez 

katiller hiç biraraya galmez

durun hele durun henüz

kavganın ortasındayız

pes etmek yakışmaz adam olana

sırrına sadık olan beri gelsin

bu dünyada sen ilkde değil sonda değilsin

katran oldu yar beklemekten gözlerim

gün döndü yine geceye vurdu sitemler', 'buğulu bir rüzgardı geçecek beklemenin anlamı kalmadı çare de yok beklemekten ayrılık hevesleri öldürdü kim kimdi bilinmez  katiller hiç bir...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şimşek']::text[], 8.5, '{"poet":"Zeynep Şimşek","poet_slug":"zeynep-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/katran-oldu-yar-beklemekten-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dile Kolay', 'dile-kolay-zeynep-simsek-h4m2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağrı sadece bir yareden olmaz

aşk sancısı ise anlamsızdır mantıkta

geceler sırların sırrıdır insana yalnızsa

gel sevdiceğim otur yanıma 

anlatayım bir halimi

bilmem anlarmısın halden

sebebsiz dünyada yaprak kımıldamaz

korkuların kılavuzluğundaysa hayatımız

nereden gelirki acılar bir bilse yığılmış taşlar

dile kolaydır acısını tartmak canların

nereden boşanıverir bilinmezki yaşlar

değermi dökülen bunca kanların

korkmayın ey insanlar benden

birtek benden değil kimseden

hatta kendinizden

bilinmeyen diyarlara gitmekten', 'ağrı sadece bir yareden olmaz aşk sancısı ise anlamsızdır mantıkta geceler sırların sırrıdır insana yalnızsa gel sevdiceğim otur yanıma  anl...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şimşek']::text[], 8.5, '{"poet":"Zeynep Şimşek","poet_slug":"zeynep-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dile-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gülümse..', 'hadi-gulumse-selin-kandemir-e87q4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne Aşk Mektupları Gelir Bana,

Ne de Ben Gönderirim,

O Kadar Boş ki Günlerim,

Sigara Tiryakisi Bile Değilim,

Beni Hiç Kimse Tanımaz, ama Hiç Kimse,

Beni Tanıyacak Bir Tek Ölümse,

Oda Gelmedi Hala Bir Gün Gelirse,

Emredeceğim Gözlerime

Hadi Gülümse..', 'Ne Aşk Mektupları Gelir Bana, Ne de Ben Gönderirim, O Kadar Boş ki Günlerim, Sigara Tiryakisi Bile Değilim, Beni Hiç Kimse Tanımaz, ama Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Selin Kandemir']::text[], 8.5, '{"poet":"Selin Kandemir","poet_slug":"selin-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hadi-gulumse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2=1', '2-1-ozdemir-asaf-jwepb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim o, deme boşuna...

Benim, ben.

Öyle bir ben ki gelen kapına; 

Başdan başa sen.', 'Kim o, deme boşuna... Benim, ben. Öyle bir ben ki gelen kapına;  Başdan başa sen....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/2-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet', 'adalet-ozdemir-asaf-a6uic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsansız adalet olmaz

Adaletsiz insan olur mu? 

Olur, olmaz olur mu! 

Ama, olmaz olsun', 'İnsansız adalet olmaz Adaletsiz insan olur mu?  Olur, olmaz olur mu!  Ama, olmaz olsun...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anahtar', 'anahtar-ozdemir-asaf-66rum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Konuşmak susmanın kokusudur.

Ya sus-git, ya konuş-gel, ortalarda kalma.

Yalan korkaklığın tortusudur.

Dürüst kaba ol, eğreti saygılı olma.', 'Konuşmak susmanın kokusudur. Ya sus-git, ya konuş-gel, ortalarda kalma. Yalan korkaklığın tortusudur. Dürüst kaba ol, eğreti saygılı olma....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anahtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-ozdemir-asaf-tyrg7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sensiz olanlara seni aratıyorum, 

Ben sensiz kalanlara seni yaratıyorum, 

Seni saklayacağım, seni yazıp-andıkça

Kendimi çoğaltıyor, seni kuşatıyorum.

Unutturmayacağım, seni yaşatacağım, 

Kendimi çoğalttıkça, seni kuşatacağım, 

Her zamanda, her yerde sen bende yaşadıkça...

Sen evreninde sana seni aratacağım.', 'Ben sensiz olanlara seni aratıyorum,  Ben sensiz kalanlara seni yaratıyorum,  Seni saklayacağım, seni yazıp-andıkça Kendimi çoğaltıyor, seni...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ansizin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardakalan', 'ardakalan-ozdemir-asaf-binyg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana bir dinletim verin,

Biraz da zaman.

Ben bir deyim çıkarayım,

Bir duyuru sesi ondan.

Siz bir solukta onu dinleyin.

Sizin olsun artakalan zaman.', 'Bana bir dinletim verin, Biraz da zaman. Ben bir deyim çıkarayım, Bir duyuru sesi ondan. Siz bir solukta onu dinleyin. Sizin olsun artakalan...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ardakalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Argo', 'argo-ozdemir-asaf-v89w1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağacı sevecektiniz,

Yoldunuz, dal bırakmadınız...

Yılına al bırakmadınız,

Yemişini yiyecektiniz.

Kadını sevecektiniz,

Aldınız, ver bırakmadınız..

Sevi''ye yer bırakmadınız,

Ona ben değil, sen diyecektiniz.

Büyünürken zamanla,

Küçüldünüz zamanla,

Arıları kovdunuz dumanla,

Kovanda bal bırakmadınız.

Sobayı söndürdünüz,

Isıyı öldürdünüz,

Hava basıp üfürdünüz,

Mangalda kül bırakmadınız.

Parayla yamalı bohça''da,

Kapanık, dar bir açıda,

O caanım ikili bahçede

Bir renk, bir gül bırakmadınız.

Bir eliniz vardı, bir cebiniz,

Başınıza vurdu keliniz,

Alıp sattınız hepiniz,

Depoda mal bırakmadınız.', 'Ağacı sevecektiniz, Yoldunuz, dal bırakmadınız... Yılına al bırakmadınız, Yemişini yiyecektiniz. Kadını sevecektiniz, Aldınız, ver bırakmadı...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/argo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynanın Oyunu', 'aynanin-oyunu-ozdemir-asaf-l0bpd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çocuk doğdu, bendim.

Sıraya girdim insanlar içinde.

Alay-bayrak büyüdüm

Odalar, sofalar içinde.

Bir ayna doğdu, gördüm.

Sıraya girdi aynalar içinde.

İşime geldi, aldım,

Çarşılar, pazarlar içinde.

Bunca yıl yüzüne baktım.

Kendisini aşmadı

Olanlar içinde.

Bir sabah uyandım,

Duruyordu karşımda

Düşmancasına,

Bir cam,

Aldanmış,

Kendini ayna sanmış..', 'Bir çocuk doğdu, bendim. Sıraya girdim insanlar içinde. Alay-bayrak büyüdüm Odalar, sofalar içinde. Bir ayna doğdu, gördüm. Sıraya girdi ayn...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynanin-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağlı', 'bagli-ozdemir-asaf-go5gi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni öyle bir yalana inandır ki,

Ömrümce sürsün doğruluğu.', 'Beni öyle bir yalana inandır ki, Ömrümce sürsün doğruluğu....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bagli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakı', 'baki-ozdemir-asaf-yvpm4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi bahçesinde dal olamayanın biri

Girmiş bahçeme ağaçlık taslayor.', 'Kendi bahçesinde dal olamayanın biri Girmiş bahçeme ağaçlık taslayor....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/baki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epigram Ya Da Benden Sonra Mutluluk', 'epigram-ya-da-benden-sonra-mutluluk-ozdemir-asaf-di4c5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca yıl yaşadım

Elime ne geçtiyse yitirdim

Biraz daha yaşayacağım

Yalnız bir şey biriktirdim

Bir bakış, bir görüş, bir duyu, bir düşünce

Belki aç kalacağım

Suçlanacağım ölünce

Biraz yazdım, artık hep yazacağım

Hüzünden baş alamadım

Görünce', 'Bunca yıl yaşadım Elime ne geçtiyse yitirdim Biraz daha yaşayacağım Yalnız bir şey biriktirdim Bir bakış, bir görüş, bir duyu, bir düşünce B...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/epigram-ya-da-benden-sonra-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift', 'cift-enis-batur-7ufoz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pus, sis, alaca

bir tesbih saatler,

çeviriyorum.

Bir düğme açıyorum yakamda,

bir başka düğme kapanıyor,

çıkıp yürüyorum', 'Pus, sis, alaca bir tesbih saatler, çeviriyorum. Bir düğme açıyorum yakamda, bir başka düğme kapanıyor, çıkıp yürüyorum...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cift-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deja Vu', 'deja-vu-enis-batur-z6tra', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Takvimin, ağır, kadınsı dönüşünde hayat musluğuna biriken

