INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fugue IV', 'fugue-iv-enis-batur-iuqmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben daha yokum ''Sizi kendi şehirlerime götürmeliydim'' demişti adam. ''Kendi sokaklarıma, çıkmazlarıma, durmadan taşındığım, hiçbirini unutmadığım evler
..........
..........', 'Ben daha yokum ''Sizi kendi şehirlerime götürmeliydim'' demişti adam. ''Kendi sokaklarıma, çıkmazlarıma, durmadan taşındığım, hiçbirini unutmad...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/fugue-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fugue XIII', 'fugue-xiii-enis-batur-bwods', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman da değil

Gidilebilse, ne çok iz kalıyor geride.

''Belki zaman'', diye düşünüyor adam:

''Zaman eksiltebilir birikeni''. Oysa ne

zaman, ne de ona benzer şeyler - ona

benzer şeyler? - silebiliyor mekana

sinenleri.  Eşyalar de
..........
..........', 'Zaman da değil Gidilebilse, ne çok iz kalıyor geride. ''Belki zaman'', diye düşünüyor adam: ''Zaman eksiltebilir birikeni''. Oysa ne zaman, ne d...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/fugue-xiii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlençli Ninni', 'i-lencli-ninni-enis-batur-3zux8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Borges''in hülyalı masalını

anımsadım, Ege''de bir sabah:

Ben de Paracelsus gibi gülü küle

dönüştüren ateşe yakarıp külü 
..........
..........', 'Borges''in hülyalı masalını anımsadım, Ege''de bir sabah: Ben de Paracelsus gibi gülü küle dönüştüren ateşe yakarıp külü  .......... ............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ilencli-ninni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Le Rouge Et Le Noır', 'le-rouge-et-le-noir-enis-batur-dayb4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskiden bir bahar vardı, lavta ve arp,

düşmezdi elimizden Le Rouge et Le Noir;

üşürdü kadınlar, ellerimiz eldiven, 

atkıydı kollarımız engerek soğukta,

karakışın ardından çözülürdü yumak:

Tuz ve tütsü, kül ve duman, kelimeler,

sesler ve tınılar ve gece: Gecenin

sonunda ışık vardı.

Le Rouge biraz daha kanadı sonra,

Le Noir koyuldu biraz daha: Aynı

çıplak at gelip sırtına aldıydı zamanı.

Bir soru s
..........
..........', 'Eskiden bir bahar vardı, lavta ve arp, düşmezdi elimizden Le Rouge et Le Noir; üşürdü kadınlar, ellerimiz eldiven,  atkıydı kollarımız enger...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/le-rouge-et-le-noir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet Hamdi İçin Tırtıl Ninnisi', 'mehmet-hamdi-i-cin-tirtil-ninnisi-enis-batur-chkgy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Süte ve geceye tutsak

aç uykusuz koyunu karanlığın:

Gemiler dalmıs gidiyor açığa,

Tarancı ki karamsar bir dede

ilk atışta vuruyor imgeyi: Bir

sebep değil, belki neticedir gece.
..........
..........', 'Süte ve geceye tutsak aç uykusuz koyunu karanlığın: Gemiler dalmıs gidiyor açığa, Tarancı ki karamsar bir dede ilk atışta vuruyor imgeyi: Bi...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mehmet-hamdi-icin-tirtil-ninnisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortak Bir Işık', 'ortak-bir-isik-enis-batur-or6ge', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekledik, gelmediler. Açtık

pencereleri, kulak kesildik seslere

gündüz ve gece, taradık tek tek

istasyona inen yorgun yüzleri,

ufuktaki lekelere ayarladık dürbünü:

Bekledik, kırık, gelmeyeceklerini

anladıktan sonra bile.

Görkemli geçmedi günler burada:

Sıradan, sade, dingin anlar kovaladı

sıradan, sade, kekre anları: Yoktu

büyük fırtınalar öyle, büyük büyüler

kurulup çözülmedi bu yaz: Her zamanki

nedensiz hüzünler, çocukların şaşkın

falı, biraz tatilde kasaba sosyalojisi,

biraz başi boş konuşmayla döndü takvimler.

Gözümüz
..........
..........', 'Bekledik, gelmediler. Açtık pencereleri, kulak kesildik seslere gündüz ve gece, taradık tek tek istasyona inen yorgun yüzleri, ufuktaki leke...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ortak-bir-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahici Sanrı', 'sahici-sanri-enis-batur-y01n1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahın eşiğinden devriye gözüm

karşı tepeye hafif, uçarı bir hızla', 'Sabahın eşiğinden devriye gözüm karşı tepeye hafif, uçarı bir hızla...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sahici-sanri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-ozdemir-asaf-sfqo5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korku dağlarının yürekçisi,

Ölüm denizlerinin kürekçisi; 

Öyle suskun oturuyor şişesinin basında,

İçtiğinin hem hırsızı, hem bekçisi,

Onu kırmış olmalı yaşamında birisi.

Dinledikçe susması, düşündükçe susması...

Tek başına iki kişi olmuş kendisiyle gölgesi,

Heykelini yontuyor yalnızlığın ustası.', 'Korku dağlarının yürekçisi, Ölüm denizlerinin kürekçisi;  Öyle suskun oturuyor şişesinin basında, İçtiğinin hem hırsızı, hem bekçisi, Onu kı...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrışımlar', 'cagrisimlar-ozdemir-asaf-pyvof', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok küçük bir yalanı

Çok büyük bir orantıda

Dinlediniz mi..

Çok büyük bir yalanı

Çok yalın bir doğrultuda

Söylediniz mi.. 

Gecikmiş bir gizlemİ,

Birikmiş bir özlemi

Sakladınız mı.. 

Gelmeyecek bir gideni,

Olmayacak bir nedeni

Beklediniz mi..

Bir gerçeği erken,

Bir açlığı tokken

Anladınız mI..

Hep mi hep ölecekmiş gibi,

Hiç mi hiç ölmeyecekmiş gibi

YaŞadınız mı.. 

Yalanı sürmeye sürmeye,

Yanlışı görmeye görmeye

Saklandınız mı..

Doğruluğun yönünde,

Doğruların önünde

Aklandınız mı..

Ortamsız bir yaşamda,

Yaşamsız bir ortamda

Harcandınız mı..', 'Çok küçük bir yalanı Çok büyük bir orantıda Dinlediniz mi.. Çok büyük bir yalanı Çok yalın bir doğrultuda Söylediniz mi..  Gecikmiş bir gizl...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cagrisimlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Do', 'do-ozdemir-asaf-085ae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün sabaha karsı kendimle konuştum

Ben hep kendime çıkan bir yokuştum

Yokusun basında bir düşman vardı

Onu vurmaya gittim kendimle vuruştum', 'Dün sabaha karsı kendimle konuştum Ben hep kendime çıkan bir yokuştum Yokusun basında bir düşman vardı Onu vurmaya gittim kendimle vuruştum...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/do-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epigram', 'epigram-ozdemir-asaf-qcfn5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk, varlığında, yokluğunda belli olur

Egemenlik, varlığında, yokluğunda belli olur

Bir özgürlük var, sularca, havalarca olağan

Varlığında değil, yokluğunda belli olur.', 'Aşk, varlığında, yokluğunda belli olur Egemenlik, varlığında, yokluğunda belli olur Bir özgürlük var, sularca, havalarca olağan Varlığında d...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/epigram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Öykü', 'eski-oyku-ozdemir-asaf-5inqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umud bir öykü adIı, başında önde gider,

Bir ayrım olur sonra, yarısı dünde gider.

Bölüşür yaşanmışlar yaşanmakta olanı,

Anılarla umutlar barışık yönde gider.

Bir gün, bir ân, bir yerde bir dönemeç belirir,

Dengesini yitirir gecelerle gündüzler.

Yalanlara dönüşür korkular için-için,

Sıcaklığını keser duygular, düşünceler.

Tükenen sevilerin alışkanlıklarında,

Gittikçe donuklaşan ışıklar yanıp söner.

Karanlığı emzirir yığın-yığın gölgeler,

Can ateşi soluk göz-bebeklerine tüner.

Bir süre kanat çarpar artık yorulmuş bir kuş,

İnişinin kararan havalarından düşer.', 'Umud bir öykü adIı, başında önde gider, Bir ayrım olur sonra, yarısı dünde gider. Bölüşür yaşanmışlar yaşanmakta olanı, Anılarla umutlar bar...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eski-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harcamalar', 'harcamalar-ozdemir-asaf-q134l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mektuplar aldım sevindim,

Birinde denmiş geliyorum

Öbüründe yazılmış geleceğim.

Bekledim bekleyorum.

Bir yaşam verdim.

Açtım bir başkasını,

Uzun-uzun yazmış gel.

Okumadan arkasını

Gittim gidiyorum

Bir başka yaşama bedel.

Biri demiş sen, biri demiş ben.

Seni ben anladım, beni sen.

Bir yaşam daha verdim

Beklerken, giderken, dönerken.

Kaldı elimde üç-beş mektup,

Üç-beş yaşam.

Bir onları da açsam okusam

Önceki yaşamları unutup

Ya beklesem, ya da gidip arasam.

Ne bir iz geliyorum deyenden,

Ne de gel yazandan.

Bunları düşünüp dururken

Bir yaşam daha gitti elimden

Başkalarınca saklamak varken.

Ama ben umudluyum bundan; 

- Yüzümden, gözümden belli -

Umudu umudumla harcadığımdan..

Bundan sonra belki

Bir yaşam daha çıkar mektubumdan.', 'Mektuplar aldım sevindim, Birinde denmiş geliyorum Öbüründe yazılmış geleceğim. Bekledim bekleyorum. Bir yaşam verdim. Açtım bir başkasını, ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/harcamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyorum', 'i-steyorum-ozdemir-asaf-j6s5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgâr mı dedim..

İsterim ki saçların dağılsın.

Gece mi dedim..

Hemen düşüncelere dalmalısın.

Aşk der demez 

Kalbin hızlı çarpmalı.

Sabah, dememe kalmadan

Uyanmalısın.', 'Rüzgâr mı dedim.. İsterim ki saçların dağılsın. Gece mi dedim.. Hemen düşüncelere dalmalısın. Aşk der demez  Kalbin hızlı çarpmalı. Sabah, d...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/isteyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jüri', 'juri-ozdemir-asaf-ezfgy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün renkler aynı hızla kirleniyordu,

Birinciliği beyaza verdiler.', 'Bütün renkler aynı hızla kirleniyordu, Birinciliği beyaza verdiler....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/juri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-ozdemir-asaf-kid3r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son isteğin nedir? 

Sorusu,

Çok, çok kolaydır,

ilk isteğin nedir? 

Sorusundan.

Çünkü,

O soruyu

Kimse kimseye soramadı,

Korkusundan.', 'Son isteğin nedir?  Sorusu, Çok, çok kolaydır, ilk isteğin nedir?  Sorusundan. Çünkü, O soruyu Kimse kimseye soramadı, Korkusundan....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kelebek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kımıltı', 'kimilti-ozdemir-asaf-1de6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ışık vardı/

Ben ona bakıyordum.

O ışık sallanıyor sanıyordum.

Oysa hemen anladım,

Ki ben kımıldanıyordum.', 'Bir ışık vardı/ Ben ona bakıyordum. O ışık sallanıyor sanıyordum. Oysa hemen anladım, Ki ben kımıldanıyordum....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kimilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masa', 'masa-ozdemir-asaf-2s4au', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çağırdım geldiler.

Oturmasalar ölürdüm.

Oturdular öldüm.

Anlamadılar.', 'Çağırdım geldiler. Oturmasalar ölürdüm. Oturdular öldüm. Anlamadılar....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-ozdemir-asaf-42qm3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünüyordum

Olaylara insan,

İnsanlara olay çıktı

Masalımdan.

Biri varmış, biri yokmuş derken

Yollardan trenlerden,

Sözü aldım getirdim

Dağlardan tepelerden.

Ben de biriktirdim

Hiç''leri hep''e

Bir dağ bozdum

Yaptım binlerce tepe.

Kurdum orada burada

Ev-ev, köyler kentler,

Dağıttım oda oda

Dağıttım birer birer.

Dağıldı tepelere

Dağların onu ardı,

Sevenlere sevilenlere

Artık bir tepe vardı.

Birinde sen, birinde ben

Öbürlerinde onlar vardı.

Aşklar başlayacakken

Sonlar tepelerden başladı.

Başladı ayrılıklar,

Ayrı ayrıydı adları.

Birer birer ayırdılar

Evleri odaları.

Bir zaman oralarda

Seven özleyen kimdi.

Evlerde odalarda

Yaşanmayan bir şimdi.

Bir daha düşünürsem masal

Bozmayacağım dağları.

Düşünmek iyi, düşünmek güzel.

Ama önce iyi çizmeli yolları.

Yakın yakın derine

El-ele olsun yürümeleri.

Ayrılığın yerine

Mutluluğun şiiri.', 'Düşünüyordum Olaylara insan, İnsanlara olay çıktı Masalımdan. Biri varmış, biri yokmuş derken Yollardan trenlerden, Sözü aldım getirdim Dağl...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/masal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-ozdemir-asaf-h4j5w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana yalanlar söylese yetinecektim.

Ama yalan söyledi.', 'Bana yalanlar söylese yetinecektim. Ama yalan söyledi....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nokta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yolda', 'o-yolda-ozdemir-asaf-y6m1c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geliyor sandığım gidiyor çıktı.

Başlıyor umduğum bitiyor çıktı,

Üstüne-üstüne gittim, ne gidiş

Altına-altına iniyor çıktı.

Uyu büyu,ü dendi, düşüme gittim,

Haydi işe dendi, işime gittim,

Yaşa dendi, yaşıma gittim,

Yendiğim sandığım yeniyor çıktı.

Bozguna benzeyor, saklasam olmaz,

Eskiye yeniden başlasam olmaz,

Yakıştırsam olmaz, yazmasam olmaz,

Maviye boyadım, baktım mor çıktı.

Sapsarı saçlarım vardı, aklaştı,

Anılar üstüste bindi yükleşti,

Bir büyük oyunun sonu yaklaştı,

Tüm yanan ışıklar sönüyor çıktı.

Gözümde bir ışık, çağırıyordu,

Beşikte bir çocuk, bağırıyordu,

Öyle bir düğündü, çan çalıyordu,

Gel çanı sandım git çalıyor çıktı.

Kimler kimler yoktu bizim kervanda,

Birer birer indi hepsi bir handa,

Savurduk sap saman biz bu harmanda,

Bir gidiş yoluydu, dönüyor çıktı.', 'Geliyor sandığım gidiyor çıktı. Başlıyor umduğum bitiyor çıktı, Üstüne-üstüne gittim, ne gidiş Altına-altına iniyor çıktı. Uyu büyu,ü dendi,...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-yolda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-ozdemir-asaf-pse3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okulda, anladıkça başaracaksın.

Yasamda, başardıkça anlayacaksın.

Gelecek mutlu-mutsuz, inanmasan da; 

Gözlerin yaşardıkça anlayacaksın.', 'Okulda, anladıkça başaracaksın. Yasamda, başardıkça anlayacaksın. Gelecek mutlu-mutsuz, inanmasan da;  Gözlerin yaşardıkça anlayacaksın....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacaksa', 'olmayacaksa-ozdemir-asaf-38l12', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O gider buralardan, sen döndüğün bir günde..

Aranırken onu sen başkaları yüzünde.

Işık olur tararsın karanlıkları bir-bir..

O güneş gibi parlar, sen söndüğün bir günde.

Yaşamın aramakla olgunlaşıp yitmiştir; 

Kocaman bir ağacın tek bir yemişi gibi..

Karamsar bir öyküdür, bir sence değerlidir; 

Yalnız masal ulu''su bir dağ ermişi gibi.', 'O gider buralardan, sen döndüğün bir günde.. Aranırken onu sen başkaları yüzünde. Işık olur tararsın karanlıkları bir-bir.. O güneş gibi par...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olmayacaksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Yükselişi Ve Çöküşü', 'olumun-yukselisi-ve-cokusu-ozdemir-asaf-4q2a5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir yakını ölse birinin,

Onu ilk-olum sanır kalır o.

Ne zaman bir sevdiği ölse birinin,

Onu en-ölüm alır kalır o.

Ne zaman bir saydığı ölse birinin,

Onu hep-ölüm bulur kalır o.

Ne zaman bir-bildiği ölse birinin,

Onu son ölüm sayar kalır o.

Ne zaman bir umduğu ölse birinin,

Onu yok-ölüm duyar kalır o.

Ne zaman bir her şeyi ölse birinin,

Kendini ölümlere yaşar kalır o.

Ne zaman bir kendisi ölse birinin,

Ölümlerde kendini yaşar kalır o.', 'Ne zaman bir yakını ölse birinin, Onu ilk-olum sanır kalır o. Ne zaman bir sevdiği ölse birinin, Onu en-ölüm alır kalır o. Ne zaman bir sayd...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olumun-yukselisi-ve-cokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onarmak Zordur', 'onarmak-zordur-ozdemir-asaf-noyq7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her karşılaşmamızda kendine özgü

                                                                gülümsemesiyle elini kulağının arka-

                                                                sına koyup eğilir, kulağıma ''onu bir

                                                                daha oku'' derdi Sabahattin Eyuboğlu..

ONARMAK ZORDUR

Şarkılar değil de

Hep kulaklar bitiyor,

Onarmak zordur.

Bir yürek üşümüş

Kapamış kapılarını,

Onarmak zordur.

Bir şey yitirilmiş

Hiç eskimeyecektir,

Onarmak zordur.

İnsanIn içine düşen korku

Özgürlüğünden olmuştur,

Onarmak zordur.

Ölümü düşünmek yenilmek,

Sevmek ölümü yenmektir,

Onarmak zordur.', 'Her karşılaşmamızda kendine özgü                                                                 gülümsemesiyle elini kulağının arka-       ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onarmak-zordur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pay', 'pay-ozdemir-asaf-1ys35', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben pırıl pırıl bir gemiydim eskiden.

İnanırdım saadetli yolculuklara.

Adalar var zannederdim güneşli, mavi, dertsiz.

Bütün hızımla koşardım dalgalara.

O zaman beni görseydiniz.

Ben pırıl pırıl bir gemiydim eskiden.

Beni o zaman görseydiniz

Siz de gelirdiniz peşimden.

Ama simdi su aksam saatinde

Son liman kendim, bu döndüğüm,

Bilmiş, bulmuş, anlamış.

Hatırımda, bir vakitler güldüğüm.

Yoluna can serdiğim o kaçış.

Simdi, şu aksam saatinde

Dönüyorum görmüş, geçirmiş, atlatmış,

Gözlerin doymayan sahilinde.', 'Ben pırıl pırıl bir gemiydim eskiden. İnanırdım saadetli yolculuklara. Adalar var zannederdim güneşli, mavi, dertsiz. Bütün hızımla koşardım...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perspectıf', 'perspectif-ozdemir-asaf-k5snj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin içine girdiğim zaman

Dışımda kalıyorsun.

Senin dışından sana bakınca 

İçime sığmayorsun.', 'Senin içine girdiğim zaman Dışımda kalıyorsun. Senin dışından sana bakınca  İçime sığmayorsun....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/perspectif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salgı', 'salgi-enis-batur-dmk18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yıl, ağustosta. Bu büyü işte,

kısaca allegro diyorum ona ben:

Hem zarif, hemde kaba oluyor ağı.

Hem zarif, hem de kaba nasıl olur 

derseniz, bakın: ince dokuduğu için

zarif, uzun uzadıya çalışmadığı için

kaba.  Köşeleri sever çoğunlukla

aşağıda dokur ve ağın dışına çekilir.

Nereden mi biliyorum bunları? 

Eskiden örümcektim ben.

Her yıl ağustosta. Yalnız kalınca

rahatlarlar: Kadın eli dolaşmaz

dolaplarda, duvarlarda. İpin ucunu

kaçırıverirler tabii: Ekmek
..........
..........', 'Her yıl, ağustosta. Bu büyü işte, kısaca allegro diyorum ona ben: Hem zarif, hemde kaba oluyor ağı. Hem zarif, hem de kaba nasıl olur  derse...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/salgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peyzaj', 'peyzaj-ozdemir-asaf-xiok8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Et son front, êtait nu,

                                                                                    comme une place vide

                                                                                    entre deux armées”

                                                                                           Jules Supervielle*

Buram-buram ışık saçan,

Alın denizlerinden geçen

Sönük bir gemidir yalnızlık; 

Gözlerde dumanı kalır.

Umutları içtikçe içen,

Yoğunlaştıkça çöken

Ardındaki karanlık,

Bir de limanı kalır.

Sözlerdir anılarda çakan,

Boyuna kıyılara çeken,

Fener, onda da, bir an’lık

İzlerin kalanı kalır.

Gözlerden saldıran, kaçan

Yengiler, yenilgilerdir uçan.

Kimsesiz, çorak, yanık,

Uzanan alanı kalır.', '“Et son front, êtait nu,                                                                                     comme une place vide           ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/peyzaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sümela', 'sumela-enis-batur-21nzs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(bir kaç önsezi)

Trabzon: Yıllardır içime gömdügüm

kaçak sevdaya hem büyütüp hem

korkarak yataklık eden nefti

düş: Sindiğin taşa bakıyorum da

inanılmaz, ürpertici
..........
..........', '(bir kaç önsezi) Trabzon: Yıllardır içime gömdügüm kaçak sevdaya hem büyütüp hem korkarak yataklık eden nefti düş: Sindiğin taşa bakıyorum d...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sumela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulak', 'ulak-enis-batur-czbif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıldan yıla geçerken

hikayeler topladım evlerde,

çıkından çıkına doldum taşırdım

hiç bir yere sığmayan 

ölüm dirim haberlerini,

çıkamadığım yokuşları

bağışlıyorum giremediğim


..........
..........', 'Yıldan yıla geçerken hikayeler topladım evlerde, çıkından çıkına doldum taşırdım hiç bir yere sığmayan  ölüm dirim haberlerini, çıkamadığım ...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ulak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrım', 'cagrim-ozdemir-asaf-yffj1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biri olsa, biri gelse,

Ilım-ılım, diri gelse,

Sözün-sözün eri gelse,

Dimdik, yalın, dursa/ya.

Gözüm-gözüm akılardan,

Duyum-duyum takılardan,

Uzak, yakın yakılardan

Duru-duru baksa/ya.

Soğuk olsa, dese ışıt,

Karanlıksa, dese ışıt,

Buram-buram dese işit,

İçin-için varsa/ya.

Birim-birim yanaş olsa,

Dirim-dirim söyleş olsa,

Adım-adım yaklaş olsa,

Can-can, kan-kan baksa/ya.

Sular gibi paklayarak

Kuşlar gibi sakıyarak,

Adım dese, çoklayarak,

Güneş-güneş yaksa/ya.

Özüm-özüm gözü göze,

Süzüm-süzüm sözü aza,

Düğüm-düğüm bizi bize,

Birden tüme katsa/ya.', 'Biri olsa, biri gelse, Ilım-ılım, diri gelse, Sözün-sözün eri gelse, Dimdik, yalın, dursa/ya. Gözüm-gözüm akılardan, Duyum-duyum takılardan,...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cagrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şakacı', 'sakaci-ozdemir-asaf-grdjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güler, gülümser bir şakacı,

Güldürür,düşündürür,

Arada-bir durur, gözleri dalar,

Neler söyler, neler susar..

Yoksa, çok acı bir şakayı 

Şakadan da olsa,

Çok yalın bir karanlığa mı saklar.. 

Oynadığı oyunsa, 

Yaşamda oynadığı,

Oyununu mu yaşar.. 

Oyunda yaşadığı, 

Yaşamını mı oynar..

Yaşarcasına, oynarcasına.

Öyküler anlatır olmuşcasına,

Sonunu mutlu bağlar,

Gider evinde ağar.', 'Güler, gülümser bir şakacı, Güldürür,düşündürür, Arada-bir durur, gözleri dalar, Neler söyler, neler susar.. Yoksa, çok acı bir şakayı  Şaka...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Yargılanışı', 'sesin-yargilanisi-ozdemir-asaf-pzg8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Savunmadan kendini,

Başı dik

Dinlemiştir duruşmayı,

Susmacasına.

Kim tutuklasa,

Ne kadar tutuklansa

Hep kaçmayı başarmıştır,

Kurtulmamacasına.

Hep egemen, özgür kalmış,

Tutsak almıştır güzelliği..

Aşkı sürgüne göndermiştir yataklara,

Kamcılarcasına.

Yaşlandıkça anlamlaşan,

Anıları unutulmaktan koruyan

Bir ulu bekçi, göze karsı,

Uyumamacasına.

Bir çiçek, hiç solmayan,

Hiç koparılamayan,

Hiç yalanı olmayan,

Sonsuzcasına.', 'Savunmadan kendini, Başı dik Dinlemiştir duruşmayı, Susmacasına. Kim tutuklasa, Ne kadar tutuklansa Hep kaçmayı başarmıştır, Kurtulmamacasın...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sesin-yargilanisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdinin', 'simdinin-ozdemir-asaf-0zio2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi ben neden mi güler? 

Şimdi ben bir başka bana,

Bir başka şimdi''den baktığımdandır.

Şimdi bu müzik neye çalmakta,

Ne var ona böylesine dalmakta? 

Uçurumlarla dağlar birbirinden çıkmadır.

Selam verdim, görmedin, ne zaman, şimdi.

O şimdi benimdi, bu senin şimdi.

Şimdilerin kimi güldürür, kimi ağlatır.

Renklerin, seslerin, sözlerin anlamı, ağırlığı,

Kendileriyle ve öbürleriyle duyarlığı, uyarlığı

Bir de uymazlığı, duymazlığı, sağırlığı vardır.

''Bir şulesi var ki şem-i cân’ın

Fânusuna sığmaz âsumânın''

Çok şimdiler Şeyh Galib''in malıdır.

Şimdi buradaydı, nerede, oradaydı, görmedin mi? 

Ben ora, sen bura, sen ora, ben bura dendikçe,

Şimdi bir şey olsadır, hem bir şey olmasadır.

''Ne meyle ne nay-ü neyle şimdi,

Gönül eğlenmeyor bir şeyle şimdi''

Şimdisinden Fuzuli uzanmış olmalıdır.

Bir şimdiden bir şimdiye köprü kurarlar

Da balıklar üstünde Yunus deyu geçerler.

Benim çocukluğumdaki yunuslar yuvarlaktır.

''Deryada deryalıklar, suda oynar balıklar,

Ne bu sevdâ olaydı, ne de bu ayrılıklar''

Çocukluklar çocuklardan azdır.

Ne olacak şimdi, ne olmuşdu, komşuda yangın çıkmışdı,

Sönmüştü, külleri uçuşmuşdu, basıma yağmışdı.

Bu çizgiler, bu aklar, o anı yangınından kalmadır,

Ne olduysa için-için ve neler de olmadıysa,

Hiçbir zaman demedimdi bir hiç için.

O konak asıl şimdi yanmaktadır.', 'Şimdi ben neden mi güler?  Şimdi ben bir başka bana, Bir başka şimdi''den baktığımdandır. Şimdi bu müzik neye çalmakta, Ne var ona böylesine ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/simdinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-ozdemir-asaf-mtzly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir susmayı bakışlarda seslendiren,

Hüzünlü yangınsal aşka döndüren nedir.

Beklemeyi özlemlere süsleyen,

Yalnızlığın kara-ışığını söndüren nedir.

Duyanı ısıtan, kulağını kestiren, güneşe baktıran,

Korkusuzluk denizlerinde yüzdüren nedir.

Saraylarda çılgın eden, kentlerde tek bırakan,

Direklere astırıp üzdüren nedir.

Ne varsa yeryüzünde, ne yoksa

Onunla paylaştıran, böldüren nedir.

Her şeyi, ama her şeyi olağan dışında,

Örneğin bir gülü yeşil gördüren nedir.

Gözlere ışıltılı anlamlar bağlayan,

Yaşamı ölüme güldüren nedir.

Kalabalıklar, kalabalıklar içinden

Kişiyi yüceye sürdüren nedir.

Parça-parça büyümüş bir çocukluğu

Olgunluk aşamalarında yaşatırca öldüren nedir...', 'Bir susmayı bakışlarda seslendiren, Hüzünlü yangınsal aşka döndüren nedir. Beklemeyi özlemlere süsleyen, Yalnızlığın kara-ışığını söndüren n...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sorular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözcül', 'sozcul-ozdemir-asaf-90cha', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birisi gelse,

Bana candan bir şey verse,

Ben de alsam; 

Ne iyidir

Onun ve benim için.

Birisi gelse,

Bana bir söz dese,

Ben de anlamasam; 

Ne kötüdür

İkimiz için.

Birisi gelse,

Benden bir şey çalsa,

Ya da saklasa; 

Bu yıkımdır

İkimizden birisi için.', 'Birisi gelse, Bana candan bir şey verse, Ben de alsam;  Ne iyidir Onun ve benim için. Birisi gelse, Bana bir söz dese, Ben de anlamasam;  Ne...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sozcul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-ozdemir-asaf-demy8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kirli eller daha temiz.

Temiz elli

Kirli gönüllerden.

Ne dersiniz?', 'Kirli eller daha temiz. Temiz elli Kirli gönüllerden. Ne dersiniz?...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/su-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak', 'susmak-ozdemir-asaf-xppri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SUSMAK

Bir insan olsun

Olsun da burada

Bir insan olsun

Orada

Nerede olursa olsun

Bir insan

Gitse olsun, kalsa olsun

Giderse olan, gitmezse duran

Aranır bir insan bir insanı

Arar bir insanı bir insan

Söylenemeyor çok şey

Susmadan', 'SUSMAK Bir insan olsun Olsun da burada Bir insan olsun Orada Nerede olursa olsun Bir insan Gitse olsun, kalsa olsun Giderse olan, gitmezse d...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/susmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlama', 'taslama-ozdemir-asaf-12vmk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl biriktirdin

Dedi o

Ve çalışarak mı diye ekledim

Ben

O da

Evet dedi

Nasıl kazandın

Ve aklınla mı diye ekledim

Evet dedi

Sende evet çok dedim

Evet dedi

Benim her şeyim var dedi

Bir şeyin yok dedim

Ne o diye sordu utanmadan

Dedim, bende olan', 'Nasıl biriktirdin Dedi o Ve çalışarak mı diye ekledim Ben O da Evet dedi Nasıl kazandın Ve aklınla mı diye ekledim Evet dedi Sende evet çok ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/taslama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanmalı', 'uyanmali-ozdemir-asaf-u9spu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek

Ölmemiş hiç kimse yaşamayacak

Yaşanmamış hiç kimse

Ölmeyecek', 'Bir gün gelecek Ölmemiş hiç kimse yaşamayacak Yaşanmamış hiç kimse Ölmeyecek...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyanmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyumak', 'uyumak-ozdemir-asaf-ahqg2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyku adı altında beni yoklamaz ölüm,

Neleri yaşadımsa uyanıklıkta gördüm.

Uyurken geçenlerin sormadım adlarını,

Kaçı kaça böldümse yaşanırlıkta böldüm..

Uyku adı altında beni yoklarsa ölüm.

Ki ben tüm uykuları hep uyanıkken gördüm..

Neden mi ben kendimin sorardım adlarını? 

Anlasınlar diyedir, ben nasıl, nerde öldüm.', 'Uyku adı altında beni yoklamaz ölüm, Neleri yaşadımsa uyanıklıkta gördüm. Uyurken geçenlerin sormadım adlarını, Kaçı kaça böldümse yaşanırlı...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uyumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var', 'var-ozdemir-asaf-hl967', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz nerede pırıl pırıl,

Nerede yolculuklar, yollar..

Orada adımlarım var.

Trenler midir gelen, insanlarıyla..

Gemiler midir giden, dumanlarıyla,

Orada gözlerim var.

Sayısız yeşil rengi yapraklar mi verir..

Tadları, meyvaları, gıdaları

Ağaçlar mi verir, topraklar mı verir..

Orada ağızlarım var.

Renk renk, biçim biçim açan çiçekler mi..

İlkyaz dolu bahçeler mi..

Ses kaynayan geceler mi..

Orada duyularım var

Nerede kuşlar, orada kulaklarım.

Nerede taşlar, topraklar, ellerim orada.

Nerede sevilecek vücud ve kadınlar,

Orada kollarım, dudaklarım var', 'Deniz nerede pırıl pırıl, Nerede yolculuklar, yollar.. Orada adımlarım var. Trenler midir gelen, insanlarıyla.. Gemiler midir giden, dumanla...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın', 'yakin-ozdemir-asaf-isg3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ışık düşerse üstüne basma.

Daha yakınlaşır, korkarsın.

Bir leke, silmeye-gör

Leke kalır, sen çıkarsın.

Bir gölge, nereye gider.

Gözlerince gider, bakarsın.

Bakarsın girer gözlerinden.

Leke onun peşinden, bakarsın.

Bir ışık düşerse üstüne basma,

Gözlerine basarsın.', 'Bir ışık düşerse üstüne basma. Daha yakınlaşır, korkarsın. Bir leke, silmeye-gör Leke kalır, sen çıkarsın. Bir gölge, nereye gider. Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yakin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalın', 'yalin-ozdemir-asaf-mrai1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her seven, 

Sevilenin boy aynasıdır.

Sevmek, 

Sevilenin o aynaya bakmasıdır.', 'Her seven,  Sevilenin boy aynasıdır. Sevmek,  Sevilenin o aynaya bakmasıdır....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğun Yer Gençliğindir', 'dogdugun-yer-gencligindir-sair-firuzan-gn8ys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevdaya yakilan agit

Bir oluye tutulana estir

Ecelle yiten anildiginda

Her sey susar.

Yeniden sevgiyi istemek

Sevgiliyle bagimli degil

Ozlenen sevgidir sevgili degil.

Bitmis sevdanin agir huznu

Aklin soguk limanina siner

Uslulugun yosunla etlenmis geceneklerinde

Yetmislerde bagrilmis bir adin

Done done yankilanisi

Dokunuslarin yeniden ogrenildigi

Opuslerin acildigi

Ayip sayilan

Ya da asagilanan

Cinselligin hani su

Can yakmanin iz birakmayan morluklari

Sevda sozcugu her zaman baska

Nasil soyunulur arzulardan sorarim

Salt ko''snu'' mu''du''r aliskanligin sultasinda kalmayan

Bir cocuk gibi yoluna konamamis

Bir cocuk gibi saganakli

Vurgun yemis

Sikilgan ustelik yurekli

O cocuk geziyor kentimizi bellegiyle.

Eminonunde guvercinleri el yordamiyla goren

Karadagdan gocmen, ortodoks olamayan bir musluman

Peygamber cicegi yeldirmeli yengem

Bes yasin siska bacaklariyla dinelen

Guzelce Kasimpasa halk dispanserinden

Zafiyetine beslenme receteleri sunulmus

Gozleri cigerleri kemikleri direncsiz

Bes vakit namazinda kadina sokuluyor;

- Ben buyuyunce yengecigim

Sana neler alacagim bilsen

/dur o''ksu''zu''m dur hele, sevaptir bu hu cekenleri yemlemek, sen buyu.

canin sag, kafan selamet, kismetin has olsun da yengen kalir mi

o gunlere, ha$a estagfurullah allahim verdigin nimete kufran olmaz,

gozlerimin perdesi artiyor o''ksu''zu''m, yeni cami kubbedir, denizin

Uskudara asili mavi ortusu bebeklerime inen olmali. Haydi vakittir,

ikindidir./

- Yengecigim Eyup Sultana gittigimizde

Tahta oyuncaklar aldigimizda.-

/Yuru garibim yuru Istanbullum yuru./

Eyubun halk cocuklarina oyuncakcilik eden 93 savasi gazisi

Tahtanin gevrek bu''ku''mu''nde, talasin sicak kokusunda

Boyalarin en dogulu olanini gunese gerip bakiyor.

Semtiyle do''l bagli oyuncaklar bunlar

Musluman kadin zafiyeti cocuk, u''c mor u''c eflatun  u''c ebruli guvercini

								doyurup

Koprunun korkuluklarindan denize ceviriyorlar bakislarini.

Cibalide fabrikalar vardiya degistiriyor,

Icelden dort kadin daha Galatada ise basliyor,

Bir bahriyeli Cebelitariki dusluyor.

Ben oturuyorum bes yildir duzenlenmeyen kitaplarimin arasinda

Kagitlar sarariyor mektuplar postada yitiyor

Cekmeyecegim telgraflarin en kisasini ariyorum;

Artik bitti/ bitti artik/ bitmisti/ artik/

Artik guclendirir mi onune geldigi sozcugu.

Hainlik soze inince zayifliyor mu ne.

Istanbulun yaman yuruyusculeri postacilar

Beklenmiyorlar benim acimdan epeydir,

Yazismalarin is icerikli olanlari

Inceliklerin yasamayan ozeniyle gidip geliyor.

Ak bir dosya kagidinda degisen tarihler

Ikibin yilina ondort yil kala

Hirosimaya bomba atan ucagin yildonumu gonullu bir intiharla

					      yeniden kutlaniyor.

Cagdas iletisimin sonucu duyarsizlik mi, olur mu, oldu mu bile...

Aci ve dehset gundelik yuzlerdir

Aldirmazligi yoldas edinmek ehlilestirmek midir uygarligimizi

Yoksa cagimizin yeni adi bu mu olacak?

Teknolojik dehseti sarmak uyutmak bastaci etmek belki

Seni seviyorumun gundelik tesekkur ederime es kilindigi

Ilkelerin sevincin uvey kardesi oldugu

Cunku sevinc coskunun nikahsiz yetimidir, kentsoylular ciddiyete  biter

Aciysa sabrin.

Iste oturuyorum yarisi baskent olan bir Orta Avrupa caddesinde

Yaz veremli bir zengin kizi gibi geziyor onumde;

Brandenburg kapisinda Bach''in sesleriyle dalgalaniyor atlar

Cikip gelinmis bir kentin yabanciligi

Bir balkonun denize acilisi gibi hem umut verir hem huzun.

Derbederligin Beatles''la dost oldugu

Parasizligin senin sakaci genc yuzunde bezendigi o Istanbul''da

Askinligin kitaplari yakiliyordu.

Sundurmalari olmayan yapilarin yoz dikilisi...

Guneydogulu bir isci cebinde tarhunuyla

Ortaanadoluyu geciyor,

Marmaraya varip dikis tutturamiyor,

Hamburg''a ulastiginda 

Butn dis orospularin

nasil da Almanca ogrendiklerine sasiyor...

Turkuleri elektronik sazla calan

bol paca gariban hemserisiyle

Duvarla bolunen kente variyor.

Konuk isci cocuklarinin boz parkinda

Iki kuzey afrikali aynen bagdas kurmus

Bir alman ogrenci yasi kirki gecmis eski Katmandu''dan

edindigi bilgelikleri toplumuna dayatarak koruyor.

Ulasim araclarinin uluslararasi her biriminde Afrikalilar bellidir

ikisi yukarivoltadan.

Dogayla kucaklasan cok eski bir gecmisin

Yumusakligini ozleyerek esrarli sigaralarini sariyorlar

hep elektrik renklerini kusanmalari

Yitmis guneslerini unutamadiklarindandir.

Ben onumde Berliner Weis bardagi

Islevselligini doruguna tasiyan bu kent

Taptaze bir kiz yuregini avuclayarak aliskanlikla

sunuyor dolara, marka.

Goguslerinin arasinda beyoglu tasindan haclari

Ofkeli degiller, sevinmiyorlar da

Disleri apak porselen

Gulmek gerekir, is giyimidir.

Buradan baktigimda kentim guzel kentim bana daha yakin

Itri''nin muziginden duyuyorum

Dogdugum yer gencligimdir biliyorum.

Kapali uretim degismeyi getirmez diyor altmissekizlerden Wolfgang

-gozlukleri John Lennon''un esi-

Degisiklikten ne anliyoruz sorusu

-felsefeyi Marks''in okudugu yerde ogreneyim- diye yola cikmis 

					    Fransiz Jean Paul''den

Doganin tanri sayildigi tum kulturleri yerle bir etmekten yaniti

Iranli ogrenci Ar$edir Horabiden.

Kac yil gecti dusunun diyor Istanbullu Mehmet Ali

Hala Lozanda''yiz hala Berlin''deyiz hala Paristeyiz

Muhurdardan asagi koyaklarda bir kum motoru, yonu Topkapi sarayi

Sultan nevruz, Hizir Ilyas yaseminleri

Ben hep inandim hep ama hep

-Ogrendikce umut daha mi geriliyor ne- aciklamasi bolivyali

                                           ressam Juan Azcoitiadan

Hayat kavgadir beyler diye kafa tutansa Jean Paul

Gozleri bir bro''ton kiri gibi uzak dingin.

Bu gece Wilmerdorferstrasse''de Perulular caliyor diyip kalkiyor

							 Mehmet Ali

gidelim haydi...

Soylenmemis tutkunlugunun vurdugu kumral bakisin

Nur-u aynim, devletli sultanim

beyninin ceperlerini kaziyan anilasmalarin

silinmez ustaligini hep bana yorma,

omuzlarina bir ikindide hayretle biraktigim basimi

sagaltan ellerini unutur muyum hic.

Var misin gidelim henuz kurulmamis o kasabaya

tek dusumuz olan o yeni yepyeni hayata,

mahrumiyet bolgesinden cikarilmak uzre tasarlanan

birlikte calisacagimiz dostlarla omuzdaslarla.

Yuksek gerilim unitelerinin

Kanaletlerin

konutlasma alt yapilarinin

fabrika yapan fabrikalarin

Shakespeare gibi Nazim gibi ustalarin kaleminden cikmisca

guzelligin taciyla donanmis bir gercegin

yaratilmasi icin bizleri secmis

O kasabaya.

Bir santiyeydi bizim sarayimiz olacakti

Yuksek firinlarin harinda yuregimiz taylar gibi

hasat sarkilarimiz senfoni orkestralarinda seslerini cogaltacakti,

Olmadi...

daraliyoruz

agir bunaliyoruz

Sikilmak hayatimizin padisahi.

Istanbul, dusleriyle bir yerlere cekiliyor

Ic yorgunlugun ozletiyor yurdunu

Gectigin yerleri dikenler burumus

Sel yataklarindan camurlar akiyor

Biz senle hicbir semti ayri yasamadik

Gitmesek de taniriz cok konustuk.

Yillarin yigintilari, senin yoksunlugun

vucudumu dagitiyor disina disina cekip canindan,

kalani ise herhangi birilerine comertlikle sunuyoruz

dogdugumuz yer gencligimizdir biliyoruz.

Her seyi bana yorma

dayanikliligimizi aptalliklarla katliyoruz.

Agzimizda Cin muzunun balli tadini emerken

Televizyonda vurusanlari, aclari guzellik ecelerini

avanak dizileri

Cok bilmislik ayaklarina yatarak izliyoruz.

Aci kavlayip porsuyunce

yasamak duyarsizligin gobeginden salgilaniyor

Cagimizin dusmanligi emzirmemesi icin

Sevgiyi bulmaliyiz

Hicbir kadin, hicbir erkek birbirine degemiyor.

Gormek icin bakmiyoruz

zaten ko''ru''z.

Agrilar icindeyiz

Bir genclik mi gercegin mirascisi

Yalanin bas taci edildigi tarihlerdeyiz

Oylesine alistik ki duymamaya

Kimin ne dedigi umurumuzda degil

Bindokuzyuzseksenbeslerden gecerken...', 'Bir sevdaya yakilan agit Bir oluye tutulana estir Ecelle yiten anildiginda Her sey susar. Yeniden sevgiyi istemek Sevgiliyle bagimli degil O...', ARRAY['Türk Edebiyatı','Şiir','Şair Firuzan']::text[], 8.5, '{"poet":"Şair Firuzan","poet_slug":"sair-firuzan","theme":"Türk Şiiri","is_hero":false,"total_lines":190,"source_url":"https://www.antoloji.com/dogdugun-yer-gencligindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızın Durumları', 'yalnizin-durumlari-ozdemir-asaf-65oif', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I. 

Her şeyi süpürebilirsin; 

Sonbaharı süpüremezsin. 

Sen her şeyi süpürebilirsin; 

Sonbaharı süpüremezsin. 

Yalnızsa 

Sürekli bir sonbaharı 

Süpürür hep. 

Düşünemezsin. 

II. 

Yanar 

Sobasında 

Yalnızın 

Üşüyen 

Bakışları. 

Lambasında 

Karanlığa donuk 

Bir ışık 

Titrer 

Sönük-sönük. 

Penceresi 

Dışına kapanmıştır, 

Kapısı 

İçine örtük. 

III. 

Yalnız 

Bin yıl yasar 

Kendini 

Bir anada. 

IV. 

Yalnızn 

Nesi var, nesi yoksa 

Tümü birdenbiredir. 

V. 

Yalnız 

Bir ordudur 

Kendi çölünde 

Sonsuz savaşlarında 

Hep yenen 

Kendi ordusunu. 

VI. 

Yalnızın 

Sakladığı bir şey vardır; 

Boyuna yerini değiştirir, 

Boyuna onu arara. 

Biri bulsa diye. 

VII. 

Yalnız 

Hem bilgesi, 

Hem delisidir 

Kendi dünyasının. 

Ayrıca; 

Hem efendisi 

Hem kölesidir 

Kendisinin 

Tadını çıkaramaz 

Görecesiz dünyasında 

Hiçbirinin 

VIII. 

Yalnız 

Sürekli dinleyendir 

Söylenmemiş bir sözü. 

IX. 

Sözünde durması 

Yalnızın yalancılığıdır 

Kendisine. 

Hep yüzüne vurur utancı. 

O yüzden 

Gözlerini kaçırır 

Gözlerinden. 

X. 

Yalnızın odasında 

İkinci bir yalnızlıktır 

Ayna. 

XI. 

Yalnız 

Hep uyanır 

İkinci uykusuna. 

XII. 

Yalnız 

Kendi bencinin 

sen’idir. 

XIII. 

Bir sözde saklanmış bir yalanı 

Bir gözde okuduğundan 

Bakmaz kendi gözlerine bile. 

XIV. 

Hep susadığında 

O 

Kendi çölündedir. 

XV. 

Kendi öyküsünü 

Ne anlatabilen 

Ne de dinleyebilen. 

Kendi türküsünü 

Ne yazabilen, 

Ne söyleyebilen. 

XVI. 

Bir zamanlar güldüğünü 

Anımsar 

da...Yoğurur hüzünün çamurunu 

Avuçlarında. 

XVII. 

Yalnız 

Aranan tek görgü tanığıdır 

Yargılanmasında 

Kendi davasının... 

Her duruşması ertelenir 

Kavgasının. 

XVIII. 

Yalnız 

Hem kaptanı 

Hem de tek yolcusudur 

Batmakta olan gemisinin. 

Onun için 

Ne sonuncu ayrılabilir 

Gemisinden, 

Ne de ilkin. 

XIX. 

Yalnızın adı okunduğunda 

Okulda ya da yasamda 

Kimse 

''Burda'' 

diyemez.. 

Ama 

Yok da.. 

XX. 

Uykunun duvarında başladı... 

Önceleri bir toz gölgesi sanki; 

Sonra bir yumak yun gibi. 

Ama simdi iyice görüyor 

Örümceğin ağını 

Gün gibi 

XXI. 

Yalnız 

Duymuş olduğunun sağırı, 

Görmüş olduğunun koru 

Dur 

Ölür ölür ölür 

Öldürür öldürür öldürür 

Duyduklarını unutur, 

Duyacaklarını düşünür. 

XXII. 

Yalnızın adına 

Hiç kimse konuşamaz.. 

O 

Kendi kendisinin 

Sanığıdır. 

XXIII. 

Yalnız 

Önceden sezer 

Sonra olacakları 

Paylaşacak biri vardır; 

Anlatır anlatır ona 

Olanları, olmayacakları. 

XXIV. 

Her leke 

Kendisiyle çıkar.', 'I.  Her şeyi süpürebilirsin;  Sonbaharı süpüremezsin.  Sen her şeyi süpürebilirsin;  Sonbaharı süpüremezsin.  Yalnızsa  Sürekli bir sonbahar...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":158,"source_url":"https://www.antoloji.com/yalnizin-durumlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Övgü', 'yalnizliga-ovgu-ozdemir-asaf-g8x78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluğun gözü kördür,

Yalnızlık sağır.

Ondandır biri tökezleyerek yürür,

Öbürü uykusunda bile bağırır.

Mutluluk yalnız kendisini görür; 

Unutur bu yüzden ilkin kendisini.

Yalnızlık kendi tutukluğunda özgür,

Boyuna bekler dönsün diye sesini.

Mutluluk alışır kendisine, ölümden beter; 

Borçsuzluğuyla övünür, ama kedisi doğurmaz.

Yalnızlığın gidecek bir yeri yoktur; 

Boyuna kapısına döner, açan olmaz.

Mutluluğun mezarları, yalnızlığın heykeli var..

Her ikisinin de saksılarında çiçek.

Biri hep başka bir renkle solar,

Öbürüyse ha açtı, ha açmayacak.', 'Mutluluğun gözü kördür, Yalnızlık sağır. Ondandır biri tökezleyerek yürür, Öbürü uykusunda bile bağırır. Mutluluk yalnız kendisini görür;  U...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizliga-ovgu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ozdemir-asaf-z3nt9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız kaldınız sanırsınız,

Biliyorum.

Yalnız bırakılmışsınız,

Biliyorum.

Ötesi yok.

Ötesi var:

Yalnızlık

Müziğin bile seni dinlemesidir.

Yalnızlık

İnsanin kendine mektup yazması

Ve dönüp-dönüp onu okuması

Yalnızlığın da ötesidir.', 'Yalnız kaldınız sanırsınız, Biliyorum. Yalnız bırakılmışsınız, Biliyorum. Ötesi yok. Ötesi var: Yalnızlık Müziğin bile seni dinlemesidir. Ya...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanık', 'yanik-ozdemir-asaf-2fhke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağladığımı gör deye ağlamayorum; 

Ağladığım için ağladığımı görüyorsun.', 'Ağladığımı gör deye ağlamayorum;  Ağladığım için ağladığımı görüyorsun....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yanik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılıç', 'kilic-ece-ayhan-72t78', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey serseriligin denizleri! Ey ahtapolari atilmislar kiyiya mutsuzlugun! Bir kraliçedir oglum kanatlarini açmis. Örtünür canfes. Unutur gitg
..........
..........', 'Ey serseriligin denizleri! Ey ahtapolari atilmislar kiyiya mutsuzlugun! Bir kraliçedir oglum kanatlarini açmis. Örtünür canfes. Unutur gitg ...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kilic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülasa', 'hulasa-rustu-onur-xtjq3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ölsem be anacığım

Nem var ki sana kalacak

Ceketimi kasap alacak,

Pardösömü bakkal

Borcuma mahsuben...

Ya aşklarım

Ya şiirlerim ne olacak

Ya sen ele güne karşı

Nasıl bakacaksın insan yüzüne

Hülasa anacığım

Ne ambarda darım

Ne evde karım var.

Çıplak doğurdun beni

Çıplak gideceğim', 'Ben ölsem be anacığım Nem var ki sana kalacak Ceketimi kasap alacak, Pardösömü bakkal Borcuma mahsuben... Ya aşklarım Ya şiirlerim ne olacak...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Onur']::text[], 8.5, '{"poet":"Rüştü Onur","poet_slug":"rustu-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hulasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Leyla Sokağı', 'sair-leyla-sokagi-rustu-onur-0dylc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Payıma düşen toprak parçası

Senin de payına düşer

Ayrılık gayrılık yok

Ölüm nefesinde nasıl olsa

Amma henüz vakit erken

Daha gün

Karşı apartmanın balkonunda

Dur bakalım hele

Ben salata satayım

Şair Leyla Sokağı''nda

Sen gene koş

Bez fabrikasındaki

Tezgahının başına

Ölüm içimde

Ölüm dışımda

Ölüm talihsiz aşımda

Ölüm kuru başımda

Teselli benim gözyaşımda', 'Payıma düşen toprak parçası Senin de payına düşer Ayrılık gayrılık yok Ölüm nefesinde nasıl olsa Amma henüz vakit erken Daha gün Karşı apart...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Onur']::text[], 8.5, '{"poet":"Rüştü Onur","poet_slug":"rustu-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sair-leyla-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykumu Geri Ver', 'uykumu-geri-ver-omer-sevincgul-852cx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anahtarım oldun! 

Seninle açtım içimin kapılarını, kendime girdim. Sonra ne yaptın? Bırakıp gittin beni. 

Çıkmak istiyorum, çıkamıyorum, kapılarım kapalı, kendimde mahpus kaldım. 

Kendi dehlizlerimde geziniyorum. Bir aydınlık, bir karanlık... Önüme ne çıkacak, bilmiyorum. 

Her gölgeli alan korkutuyor beni, ucubeler çıkacak sanıyorum, birden fırlayacaklar önüme.

Zora soktun beni, kendimi tanımaya zorladın. Bu yetmezmiş gibi, beni uykumdan da ettin. Uyuyordum her şeyden habersiz, uyandırdın. 

Şimdi tedirginim artık, adı bilinmedik kaygılarım, kitaplara yazılmamış korkularım var. 

Cevabı bilinmeyen sorulara döndüm. Çekip gittin birden. Ne ses veriyorsun bana, ne de teselli. 

Sıradan biri gibi yaşayamam artık, hiçbir şey olmamış gibi davranamam! 

Hem kendimi, hem de hayatı yeniden tanımlamalıyım, bunu biliyorum. 

Biliyorum ama... 

Nasıl?', 'Anahtarım oldun!  Seninle açtım içimin kapılarını, kendime girdim. Sonra ne yaptın? Bırakıp gittin beni.  Çıkmak istiyorum, çıkamıyorum, kap...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevinçgül']::text[], 8.5, '{"poet":"Ömer Sevinçgül","poet_slug":"omer-sevincgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uykumu-geri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sendeyim Sen Nerdesin', 'ben-sendeyim-sen-nerdesin-emre-ozdamar-jna2z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharı çağıran sesinle bir çağırsan 

Gel desen portakal çiçeklleri ardından 

Gelirim, ardımdan dağlar gelir 

Ah o gözlerini gözlerimden kaçırmasan 

Ki gözlerin sonbahar akşamlarından bir parçadır

Dökülen yaprakların rengi gözlerinde saklanır

Ve sen bilemezsin

Sana tutsak bedenim gözlerinin 

Darağacında sallanır

Bu yüzden yürürüm 

Yollar görünür bana

Yürürüm yağmur yağar

Yürürüm gökkuşağı açar yollarıma

Bak yıldızları da getirdim sana

Geceye göz kırpan titreyişleri dudaklarımda

Çıkmaz bir sokaktan, dipsiz bir kuıyudan 

Merhaba', 'Baharı çağıran sesinle bir çağırsan  Gel desen portakal çiçeklleri ardından  Gelirim, ardımdan dağlar gelir  Ah o gözlerini gözlerimden kaçı...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-sendeyim-sen-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Parıldar', 'kan-parildar-davut-kucukkilinc-79mi4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlar olur, yüreğime iner 

Bir haber bile yok senden

Çılgın gözler, kan parıldar

Geceler sessiz senden', 'Dağlar olur, yüreğime iner  Bir haber bile yok senden Çılgın gözler, kan parıldar Geceler sessiz senden...', ARRAY['Türk Edebiyatı','Şiir','Davut Küçükkılınç']::text[], 8.5, '{"poet":"Davut Küçükkılınç","poet_slug":"davut-kucukkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kan-parildar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sert Sözlü', 'sert-sozlu-cemil-fevzi-goksu-lcbkp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağzın bozuk, sözün sert ise düzelt dilini

Yoksa dar gününde kimse uzatmaz elini', 'Ağzın bozuk, sözün sert ise düzelt dilini Yoksa dar gününde kimse uzatmaz elini...', ARRAY['Türk Edebiyatı','Şiir','Cemil Fevzi Göksu']::text[], 8.5, '{"poet":"Cemil Fevzi Göksu","poet_slug":"cemil-fevzi-goksu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sert-sozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenmek Uğruna', 'yenmek-ugruna-orhan-polat-b3oyt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''sevi için''

yenilmeden başlamak için hayata,

artık çok geç...

yenik başladığımız hayatlarda,

yenilmişlerle aynı yollardayız...

düşünmeden yaşadığımız,

kayıp hayatların, yenik insanları,

yenik masalların, kayıp aşıkları

yenik kahramanları sürükler,

savaş meydanlarına,

sırf yenilmeden devam etmek için hayata...

(ankara 25 ağustos 2000)', '''sevi için'' yenilmeden başlamak için hayata, artık çok geç... yenik başladığımız hayatlarda, yenilmişlerle aynı yollardayız... düşünmeden ya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yenmek-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Sende Gizli', 'her-sey-sende-gizli-can-yucel-skivu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yerin seni çektiği kadar ağırsın, 

Kanatların çırpındığı kadar hafif.. 

Kalbinin attığı kadar canlısın, 

Gözlerinin uzağı gördüğü kadar genç...

Sevdiklerin kadar iyisin, 

Nefret ettiklerin kadar kötü.. 

Ne renk olursa olsun kaşın gözün, 

Karşındakinin gördüğüdür rengin.. 

Yaşadıklarını kâr sayma: 

Yaşadığın kadar yakınsın sonuna; ne kadar yaşarsan yaşa, 

Sevdiğin kadardır ömrün.. 

Gülebildiğin kadar mutlusun. 

Üzülme bil ki ağladığın kadar güleceksin 

Sakın bitti sanma her şeyi, 

Sevdiğin kadar sevileceksin. 

Güneşin doğuşundadır doğanın sana verdiği değer 

Ve karşındakine değer verdiğin kadar insansın. 

Bir gün yalan söyleyeceksen eğer; 

Bırak karşındaki sana güvendiği kadar inansın. 

Ay ışığındadır sevgiliye duyulan hasret, 

Ve sevgiline hasret kaldığın kadar ona yakınsın. 

Unutma yagmurun yağdığı kadar ıslaksın, 

Güneşin seni ısıttığı kadar sıcak. 

Kendini yalnız hissetiğin kadar yalnızsın 

Ve güçlü hissettiğin kadar güçlü. 

Kendini güzel hissettiğin kadar güzelsin.. 

İşte budur hayat! 

İşte budur yaşamak, 

Bunu hatırladığın kadar yaşarsın 

Bunu unuttuğunda aldığın her nefes kadar üşürsün 

Ve karşındakini unuttuğun kadar çabuk unutulursun 

Çiçek sulandığı kadar güzeldir, 

Kuşlar ötebildiği kadar sevimli, 

Bebek ağladığı kadar bebektir. 

Ve herşeyi öğrendiğin kadar bilirsin, 

bunu da öğren, 

Sevdiğin kadar sevilirsin...', 'Yerin seni çektiği kadar ağırsın,  Kanatların çırpındığı kadar hafif..  Kalbinin attığı kadar canlısın,  Gözlerinin uzağı gördüğü kadar genç...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/her-sey-sende-gizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Denizinde Sığınacak Bir Liman Vardır Her Zaman', 'hayal-denizinde-siginacak-bir-liman-vardir-her-zaman-osman-demir-f6x21', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayal Denizinde Sığınacak Bir Liman

Vardır Her Zaman				

Yaşamın acı çekmekle

Eşdeğer olduğu anlarda, 

Alın başınızı gidin. 

Uçsuz bucaksız

Hayâlin limanlarına.

Zorluğu yoktur bunun öyle 

Gözlerinizi kapatmanız

Yeterlidir...

Harekete geçmek için

Hayalin yelkenlisine binmek kalır size

Sadece..... 

Gördüklerinizin esaretinden kurtulur

Bambaşka bir ufuk açarsınız önünüzde

Rüzgarını da ayarladınız mı birde 

Deymeyin keyfinize

Gönlünüzce keyif sürersiniz 

İstediğiniz yerde 

İstediklerinizle...........  

Büyür dünyanız görmediğiniz an

Ayın ardına saklansın,

Güneşte bunalan...

Aydınlatmaktan çok, 

Gizlemesindedir 

Onun güzelliği. 

Güneş nöbeti devrettiği an

Başlar ay.... 

Hayal denizlerinizde 

Fırtınalar estirmeye..

5.12.1999', 'Hayal Denizinde Sığınacak Bir Liman Vardır Her Zaman				 Yaşamın acı çekmekle Eşdeğer olduğu anlarda,  Alın başınızı gidin.  Uçsuz bucaksız ...', ARRAY['Türk Edebiyatı','Şiir','Osman Demir']::text[], 8.5, '{"poet":"Osman Demir","poet_slug":"osman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hayal-denizinde-siginacak-bir-liman-vardir-her-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece, Ben ve Sen', 'gece-ben-ve-sen-osman-demir-tnbgt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece Ve Ben 

Güneş kaybolup çökünce gece

Ruhumu sarar bin bir düşünce

Bir de dertler akla gelince 

Sabaha kadar yatamam ben......

Beklemekle geçmez, durmuştur zaman

Saat gibi gelir, ufacık bir an

Güneş görünüp de ağarırken tan 

Derdimi yine de atamam ben....

Keder deryasında boğuldu neşe

Hasret kaldı mahzun gönül güneşe 

Gün dönüp de saat gelirken beşe

Izdıraplı dünyamı satamam ben....

Can sıkıntısından ezilir beden 

Dertlerin tükenmez kaynağısın sen

Ruhum acıdan haykırıyorken 

Neşe denizine batamam ben', 'Gece Ve Ben  Güneş kaybolup çökünce gece Ruhumu sarar bin bir düşünce Bir de dertler akla gelince  Sabaha kadar yatamam ben...... Beklemekle...', ARRAY['Türk Edebiyatı','Şiir','Osman Demir']::text[], 8.5, '{"poet":"Osman Demir","poet_slug":"osman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gece-ben-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmetselcuk', 'ahmetselcuk-nurtac-burhan-0v4q9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çatlayan topraklari ariyor bulutlar,

rüzgara kapılmış uçuyor turnalar,

damarımda kan yerine akıyor volkanlar,

sevdami sonsuz kere vurdu yalanlar...', 'çatlayan topraklari ariyor bulutlar, rüzgara kapılmış uçuyor turnalar, damarımda kan yerine akıyor volkanlar, sevdami sonsuz kere vurdu yala...', ARRAY['Türk Edebiyatı','Şiir','Nurtaç Burhan']::text[], 8.5, '{"poet":"Nurtaç Burhan","poet_slug":"nurtac-burhan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ahmetselcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuklu', 'tutuklu-sunay-akin-a27lr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutsak olacağını bilerek 

yine bu sabah 

demirparmaklıktan içeri 

usulca sızdı 

güneş 

Yasaklanınca görüş gününde 

çiçek getirilmesi 

arka duvarın dibinde 

sarmaşık tohumu 

dikmiş annem 

Oysa el bile 

sallayamamıştım ona 

kuyrukta saatlerce bekleyip 

doldurduğu içme suyunu 

dökerken ardıma', 'Tutsak olacağını bilerek  yine bu sabah  demirparmaklıktan içeri  usulca sızdı  güneş  Yasaklanınca görüş gününde  çiçek getirilmesi  arka d...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tutuklu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Beni Şaşırt', 'bir-gun-beni-sasirt-mustafa-korganci-ns8tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şaziye''nin Anısına

Bir gün beni şaşırt

Elinde bir demet çiçekle çık gel

Ve sarıl boynuma.

Yine '' seni zerre kadar sevmedim '' de

Ama '' aşığınım , aşığınım '' de

Şaşırt beni birtanem

Bie şişe şarap aç , bir mum yak geceye

Whitney Houston söylesin BODYGUARD

Dans edelim dudak dudağa

Kucakla beni , kucakla

Sarhoşum , ayyaşım sana

Diyorum ya birtanem 

Bir gün beni şaşırt', 'Şaziye''nin Anısına Bir gün beni şaşırt Elinde bir demet çiçekle çık gel Ve sarıl boynuma. Yine '' seni zerre kadar sevmedim '' de Ama '' aşığın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Korgancı']::text[], 8.5, '{"poet":"Mustafa Korgancı","poet_slug":"mustafa-korganci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-gun-beni-sasirt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Kapıyı Dön Bak Ben Geldim', 'ac-kapiyi-don-bak-ben-geldim-arif-tayfun-kesebir-sf323', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aç kapıyı dön bak ben geldim

          Merak etmiyormusun sana neler getirdim

          Solgun bir yüz ardından gözyaşı

          İşte bu bir aşığın hayatı

          Sense umursamaz bir tavırla 

          Karşıma geçip güldün kahkahayla 

          Gözlerinin içi gülüyordu

          Söyle deim sana bu aşk bitiyor mu?', 'Aç kapıyı dön bak ben geldim           Merak etmiyormusun sana neler getirdim           Solgun bir yüz ardından gözyaşı           İşte bu bi...', ARRAY['Türk Edebiyatı','Şiir','Arif Tayfun Kesebir']::text[], 8.5, '{"poet":"Arif Tayfun Kesebir","poet_slug":"arif-tayfun-kesebir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ac-kapiyi-don-bak-ben-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-rifat-ilgaz-41a8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kilim gibi dokumada mutsuzluğu

Gidip gelen kara kuşlar havada

Saflar tutulmuş top sesleri gerilerden

Tabanında depremi kara güllelerin

Duymuyor musun

Kaldır başını kan uykulardan

Böyle yürek böyle atardamar

Atmaz olsun

Ses ol ışık ol yumruk ol

Karayeller başına indirmeden çatını

Sel suları bastığın toprağı dönüm dönüm

Alıp götürmeden büyük denizlere

Çabuk ol

Tam cağı ise başlamanın doğan günle

Bul içine tükürdüğün kitapları yeniden

Her satırında buram alin teri

Her sayfası günlük güneşlik

Utanma sucun tümü senin değil

Yırt otuzunda aldığın diplomayı

Alfabelik çocuk ol

Yollar kesilmiş alanlar sarılmış

Tel örgüler çevirmiş yöreni

Fırıl fırıl alici kuşlar tepende

Benden geçti mi demek istiyorsun

Aç iki kolunu iki yanına

Korkuluk ol', 'Kilim gibi dokumada mutsuzluğu Gidip gelen kara kuşlar havada Saflar tutulmuş top sesleri gerilerden Tabanında depremi kara güllelerin Duymu...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarım', 'cocuklarim-rifat-ilgaz-hoznf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoklama defterinden tanımadım sizi,

Benim haylaz çocuklarım

Sınıfın en devamsızını

Bir sinema dönüşü tanıdım

Koltuğunda satılmamış gazeteler

Dumanlı bir salonda

Kendime göre karsılarken aksamı

Nane sekeri uzattı en tembeliniz

Götürmek istedi küfesinde

Elimdeki ıspanak demetini

En dalgını sınıfın

Çoğunuz semtine uğramaz oldu okulun

Palto ayakkabı yüzünden

Kiminiz limon satar balık pazarında

Kiminiz Tahtakale''de çaycılık eder

Biz inceleye duralım aç tavuk hesabi

Tereyağındaki vitamini

Kalorisini taze yumurtanın

Karşılıklı neler öğrenmedik sınıfta

Çevresini ölçtük dünyanın

Hesapladık yıldızların uzaklığını

Orta Asya''dan konuştuk

Laf kıtlığında

Birlikte neler düşünmedik

Burnumuzun dibindekini görmeden

Bulutlara mi karışmadık

Güz rüzgarlarında dökülmüş

Hasta yapraklara mi üzülmedik

Serçelere mi acımadık kış günlerinde

Kendimizi unutarak', 'Yoklama defterinden tanımadım sizi, Benim haylaz çocuklarım Sınıfın en devamsızını Bir sinema dönüşü tanıdım Koltuğunda satılmamış gazeteler...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cocuklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizden Biri', 'i-cimizden-biri-rifat-ilgaz-54b7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eli değnek tutar tutmaz

Çoban oldu;

Sardılar sırtına bazlamayı

Onaştı yıl güne verdi karnını,

Onaştı yıl koyun güttü, kavalsız

İnsanlardan ağayı tanır,

Adını bilmez sorarsan,

Hayvanlardan Karabaşçı

Günü yetti, bıyığı bitti,

Okundu künyesi,

Gitti, davulsuz zurnasız', 'Eli değnek tutar tutmaz Çoban oldu; Sardılar sırtına bazlamayı Onaştı yıl güne verdi karnını, Onaştı yıl koyun güttü, kavalsız İnsanlardan a...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/icimizden-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahveler Gazeteler', 'kahveler-gazeteler-rifat-ilgaz-miww4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimini vurguncu yaptı 39 harbi

Kimini karaborsacı

Laf olur diye dost çayı içmeyenler

Mahkemelik oldu rüşvet yüzünden

Gaz fişi, ekmek karnesi derken

Kimler karışmadı ki piyasaya

''Kimini sefil etti 39 harbi,

kimini şair etti.''

Beni de gazete tiryakisi.

Dadandık kahvelere ajans yüzünden,

Bir bardak ıhlamur bedeline

Yeni nizamdan dem vuran yazılar okuduk

Düştük eli kalem tutup da

Eli silah tutmayanların peşine,

Cenk meydanlarını dolaştık,

Denizler geçtik dağlar aştık,

Gün oldu kırıldı kanadımız

Kaldık çöllerde.

Gün oldu Urallar''dan vurup

Ulaşmak istedik Kızılelma''ya

Yürüdük şehir şehir,

bir de ne görelim

Arpa boyu yol gitmişiz!

Düşenin dostu mu olur,

Zafer nerde, biz orda:

''Meserret'' de kurtardık Sivastopol''u

''İkbal'' de girdik Berlin''e

Atıkalı kahvesinde patladı

Atom bombası

Pes dediler, bir yaz akşamı

Şehzadebaşı''nda Japonlar,

Çektik zafer bayrağını kapıya!', 'Kimini vurguncu yaptı 39 harbi Kimini karaborsacı Laf olur diye dost çayı içmeyenler Mahkemelik oldu rüşvet yüzünden Gaz fişi, ekmek karnesi...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kahveler-gazeteler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulağımız Kirişte', 'kulagimiz-kiriste-rifat-ilgaz-zck7f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaslılar adına konuşmanın tam zamanı

Kütükte yası yetmişlerin arasındayım.

Bir tekerlemenin çağrışımında

İnanıvermeyin isimin bittiğine.

Ne var ki dertlerimiz tasalarımız artıyor,

Yas ilerledikçe.

Biz yaslılar turlu nedenlerden

Kuşlarla birlikte uyanmak zorundayız

Saksıdaki karanfil bakim ister.

Tüm çiçekler, ağaçlar, parklar,

Yollar köprüler bakim ister.

Balıkçı barınağı, barınaktaki gemiler,

Gün dogmadan deniz fenerimiz,

Kıyılarımız, gökyüzü, bulutlar,

Bir uçtan bir uca esen rüzgar,

Butun gün gözümüz üzerlerinde olmalı.

Bu arada torun torba çocuklarımız

Martılarla birlikte çoğalan...

Onlar da bakim ister kuskusuz.

Erken de kalksak alaca karanlıkta

Hangi birine yetişebiliriz ki...

Biz yaslılar için en önemlisi

Kuzeyden esen nemli rüzgarlar,

Karayel de önemli, gündoğrusu da.

Raporlar yazılmalı, hava raporları,

Soğuk sıcak tüm dalgalar, akımlar,

Alçak basınç radyolarda, yüksek basınç,

Güneyden esen yellerle birlikte

Sisli puslu havalarda durulmalı.

Yaslandıkça azıyor romatizmalarımız,

Bur günümüz bir günümüze uymuyor,

Artıyor ağrılarımız, sızılarımız,

Kapıyı kim vuracak belli olmaz,

Kulağımız kirişte olmalı!', 'Yaslılar adına konuşmanın tam zamanı Kütükte yası yetmişlerin arasındayım. Bir tekerlemenin çağrışımında İnanıvermeyin isimin bittiğine. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kulagimiz-kiriste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mıstabey', 'mistabey-rifat-ilgaz-vaj9z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaşın gözün mü oynuyor,

A Mıstabey,

Bana mı öyle geliyor ?

Nevrin döndü, süzülüverdin.

Gözümüz yok işlerin yolunda doğrusu,

Çıkmadı senin gibisi Safranbolu''dan

Bugüne bugün

İki fırın sahibisin,

Senin düşünmek neyine ?

Haramiler mi çevirdi kervanını,

Gemilerin mi battı Karadeniz''de ?

Hele bak,

Fiy yemiş güvercin gibisin.

Senin ne derdin olur, a Mıstabey,

Ceza kestilerse Çemberlitaş''taki fırına,

Hacı ne güne duruyor tezgahta,

Bilirsin postu vermez ele...

Hele düşündüğün şeye bak,

İpe çekmezler ya adamı

Ekmeğe kul karıştırdı diye;

Şükür bulduğumuza bu kadar...

Yoksa küreğin sapı yüzünden

Başı belaya mı girdi

Saraçhane''deki Rıza''nın ?

Kolay değil fırın işletmesi

Cadde üstünde...

Kesersin bir karış küreğin ucundan

Olur biter...

Rıza mı çekecek eziyeti,

Çeksin kerata,

Şeytan azapta gerek...

Bunlar gelir geçer, Mıstabey,

Üzülmeye değmez.

Çok düşkündün havadise eskiden,

Kaçırmazdın ajansları...

ne meydan muharebeleri vermedin,

Şu kahvenin ortasında,

Moskova''yı kaç kere feşettin.

Sana ne oldu bugünlerde

Radyoya kulak vermez oldun.

Seninkiler ne hale gelmişler

Taşı toprağı toplamışlar Bulgarya''dan

Bırakmışlar Varşova''yı geride,

topyekün kaçıyorlarmış!

Boş oturmamışlar Mıstabey

Ne fırınlar yapmış herifçioğulları

Senin fırınlar halt etmiş yanında,

Kapısından girilir

Bacasından çıkılırmış...

Yaşamadı Mıstabey,

Sana dokunmayana yılan

Bin yıl yaşamadı!

Ne o dalıp gittin, Mıstabey,

Nargilen kül bağlamış!

Neden yorgunsun böyle,

Neden kulakların böyle düşük ?

Boş durduğun yok anlaşılan!

Ne parçalar geldi geçti elinden

Bu karne çıkalı;

Sonunda düştün mü bu çirkefe ?

Sen ne dersen de, Mıstabey,

yaşın kemalini bulmuş,

Bu senin dişine göre değil!

Ama huy çıkar mı can çıkmayınca!

Sakar öküz titretirken kuyruğu

Varıp başucuna sormuşlar,

Nedir son sözün diye;

Deri mi yüzün de demiş, atıverin

Sarı ineğin üstüne...

Biliriz eski kulağı kesiklerdensin,

Ne söylesek fayda yok,

Arpadan olacak anlaşılan

Atın ölümü!

Hem düşün, Mıstabey,

Sen evli barklı adamsın,

Dile düştün mü Safranbolu''da

İki paralık olur itibarın!

Hani ahbapların ağzında

Bakla da ıslanmaz oldu.

İt değil ki kapatasın ekmekle

Şunun bunun çenesini.

Söz de ele vermişsin sakalı,

Doyurmuşsun gözünü

kürkten bilezikten yana

Şimdi de tutturmuş haspamız

Başımı sokacak ev isterim diye...

Tutkunsun, vereceksin ister istemez;

Gülü seven katlanır dikenine...

Ne yapalım,

Taş attın da kolun mu yoruldu ,

Bağışla gitsin Fatih''tekini!

Amaaaan, Mıstabey,

Bunlar kara kara düşünmeye değmez,

Tazelensin hele nargilen,

Bak keyfine!', 'Kaşın gözün mü oynuyor, A Mıstabey, Bana mı öyle geliyor ? Nevrin döndü, süzülüverdin. Gözümüz yok işlerin yolunda doğrusu, Çıkmadı senin gi...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/mistabey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum I', 'oglum-i-rifat-ilgaz-xicyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben de düşkündüm oyuna,

Ben de kumları avuçlar

Kazardım tırnaklarımla toprağı,

O zaman da çocuklar oynardı,

Ama benzemiyor bütün oyunlarımız,

Gezdirdim ceplerimde şıkır şıkır

Deniz kokulu tasları,

En güzellerini topladım

Midye kabuklarının.

Saldım bahar rüzgârına

Uçurtmaların en süslüsünü.

Ne kurulunca koşan tramvaylarım vardı,

Ne çekince giden develerim.

Balıklarımızı tanırdım,

Adlarını bilirdim kuşların; 

Seçerdim düdüğünden

Limanımıza uğrayan vapurları.

Bilirdim yanık yüzlü kaptanlarımı

Denizkızı’nın Selametçin; 

Ben de ayırırdım onlar kadar

Poyrazı karayelden.

Gemiler tanıdım, çift direkli,

Tutmazsa rüzgârı

Açıklarımızda volta vuran gemiler,

Kızardım, limanımızı hiçe sayan

Paketlere Nemselere; 

Dalar da silinen dumanlarına

Düşünürdüm uzak limanları,

Uzak limanların çocuklarını.

Senin de var ufak tefek

Kendine göre bildiklerin; 

Çeşitli oyuncakların yoksa da

Bir saniye de tren yapacak kadar

Kibrit kutularını,

Tecrüben var benden fazla.

Benden üstünsün kuskusuz,

Sigaradan top,

Kutusundan tank,

Kâğıtlarından uçak yapmada!', 'Ben de düşkündüm oyuna, Ben de kumları avuçlar Kazardım tırnaklarımla toprağı, O zaman da çocuklar oynardı, Ama benzemiyor bütün oyunlarımız...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/oglum-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydın Mısın', 'aydin-misin-rifat-ilgaz-eetzu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kilim gibi dokumada mutsuzluğu 

Gidip gelen kara kuşlar havada 

Saflar tutulmuş top sesleri gerilerden 

Tabanında depremi kara güllelerin 

Duymuyor musun 

Kaldır başını kan uykulardan 

Böyle yürek böyle atardamar 

Atmaz olsun 

Ses ol ışık ol yumruk ol 

Karayeller başına indirmeden çatını 

Sel suları bastığın toprağı dönüm dönüm 

Alıp götürmeden büyük denizlere 

Çabuk ol 

Tam çağı ise başlamanın doğan günle 

Bul içine tükürdüğün kitapları yeniden 

Her satırında buram alın teri 

Her sayfası günlük güneşlik 

Utanma suçun tümü senin değil 

Yırt otuzunda aldığın diplomayı 

Alfabelik çocuk ol

Yollar kesilmiş alanlar sarılmış 

Tel örgüler çevirmiş yöreni 

Fırıl fırıl alıcı kuşlar tepende 

Benden geçti mi demek istiyorsun 

Aç iki kolunu iki yanına 

Korkuluk ol', 'Kilim gibi dokumada mutsuzluğu  Gidip gelen kara kuşlar havada  Saflar tutulmuş top sesleri gerilerden  Tabanında depremi kara güllelerin  D...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aydin-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum III', 'oglum-iii-rifat-ilgaz-mabtl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç de meraklı değilsin çiçeğe,

Komşunun saksısını sen kuruttun,

Kopardın penceresindeki gülünü.

Bir sonuç mu çıkarayım bundan

Yeşilliğe düşman diye bizim çocuk? 

Gelgelselim öyle düşkünsün ki 

Göbekli marullarına Yedikule''nin; 

Mevsiminde elinden düşmüyor

Elma gibi domatesler; 

Tavsan kadar seviyorsun havucu.

Ben de tutkunum senin gibi

Bursa şeftalisine, Ereğli çileğine.

Sanma soyca hoşlanmıyoruz çiçekten

Güle değil,

Gül düşkünlerine bizim hincimiz.

Biz de gördük haşhaş tarlasını,

Gelincik sanmadık.

Ilgaz''larda topladık çiğdemi,

Edirne''nin gülünü Edirne''de.

Engel olmaz bu bilgimiz

Sümbülden çok sevmemize yeşil soğanı.

Yasamak için iştahını arttıracak

Şiirler vereceğim sana,

Ne istersen bulacaksın içinde

Bu toprakla ilgili:

Portakallarını göreceksin Dörtyol''un

Mersin silolarında bitlenen

Altın sarisi buğdayları,

Turfandadır diye el süremediğimiz

Çavuşları, kınalı yapıncakları,

Bağı sorulmadan yenilen

Memleket üzümlerini salkım salkım', 'Hiç de meraklı değilsin çiçeğe, Komşunun saksısını sen kuruttun, Kopardın penceresindeki gülünü. Bir sonuç mu çıkarayım bundan Yeşilliğe düş...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/oglum-iii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum IV', 'oglum-iv-rifat-ilgaz-uqing', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni saksıda gül yetiştirir gibi

Yetiştirmedik, tek başına

Bir limonlukta büyütmedik seni.

Kırağı çalmaz diye acı patlıcani

Salıverdik sokağa; 

Düşecektin eninde sonunda

İlk günlerde çok hırlaştınız,

Sonra sokuldunuz birbirinize,

Kaynaştınız karıncalar gibi.

Büyümedin bir dadının dizleri dibinde,

Kucaklarında sütninelerin.

Ne kaç dağındaki peri kızlarına tutuldun,

Ne kurtarmayı düşündün

Şehzadeyi, devler elinden.

Tanımadan Keloglanı

Düştün macuncunun arkasına,

Dolaştın mahalleyi.

Yağmurlu bir günde tanıdın

Göl tutarken bekçinin oğlunu,

Recep''le taşladınız

Atkestanesini, cami avlusunda,

Attınız Emi’nle kedi yavrusunu,

Kireç kuyusuna.

Bunlar mahallemizin çocukları; 

Henüz bilmiyorsun,

El tarlasında koza düşürürken anası

Sıtma nöbetleri geçirenleri,

Kuzuları doğup

Çoban köpekleri ile büyüyenleri,

İki gözünde heybenin

Çeltiğe giden Yeşil ırmak döllerini.

Tanımıyorsun,

Benzi tütün yaprağından soluk

Çocuklarını Sakarya’nın.

Demirindesiniz ayni bıçağın,

İlerde kucaklaşacaksınız, nasıl olsa; 

Hazır olsun kalbin onları sevmeye

Daha şimdiden!', 'Seni saksıda gül yetiştirir gibi Yetiştirmedik, tek başına Bir limonlukta büyütmedik seni. Kırağı çalmaz diye acı patlıcani Salıverdik sokağ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/oglum-iv-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklığın Ötesinden I', 'parmakligin-otesinden-i-rifat-ilgaz-ey693', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanları alabildiğine sevmeyi,

Bırakmazlar yanına.

Böyle çekersin cezasını

Üç duvar, bir kapı arasında

Onlardan ayrı

Böyle onlardan uzak.

Yasak sana, boylu boyunca sokaklar,

Bahçeler, yalı kahveleri.

Dostlara simdi mektup değil,

Bir selam yasak! 

Kapılar demir sürgülü, çifte kilitli,

Kapalı, hürriyete giden yollar; 

İçerdeki içerde mahzun,

Dinardaki dinarda.

Burada her şey sade:

Ekmek ve su, düşünceler...

Emirler çeşitli:

Kapıda kilit, emir,

Uzakta düdük, emir,

Emir, dışarıda dikilen nöbetçi.

Hürriyeti çoktan unuttum,

O yemyeşil masalların kızıdır

Eskiden sevilmiş.

Bir ince hastalıktır olsa.

O simdi ciğerlerimde.

Su pencereye verdim kendimi,

Bütün üzüntülere karşılık,

Bogazın suları üzerinden

Karsı, sırtlara açılmış pencerelere.

Üsküdar’ı bilmezdim eskiden,

Burada ısınıverdi kanım.

Vurgunum su Kızkulesi''ne; 

Ne de şirin görünüyor

Uzaktan Karacaahmet; 

Hiç de söyledikleri gibi değil,

Bana düşündürmüyor ölümü', 'İnsanları alabildiğine sevmeyi, Bırakmazlar yanına. Böyle çekersin cezasını Üç duvar, bir kapı arasında Onlardan ayrı Böyle onlardan uzak. Y...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/parmakligin-otesinden-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Remzi', 'remzi-rifat-ilgaz-bni8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sorayım sana

Kulak dolgunluğu belediklerini mi söylersin

Uyku sersemliği göz gezdirdiğin kitaptan

Aklında kalanları mi

Çalışmadın istediğim gibi

Ya komşunun suyunu taşıdın

Bekar çamaşırı yıkarken annen

Ya da beşiğini salladın kardeşinin

Gaz yoktu belki bu gecelik

Şişesi çatlamıştı lambanın

Karşılıksız kalacak sorularım demek

Ama vakti gelince senden öğreneceğim

Makarna verildiğini karneyle

Bulgaryadan gelen kömür motorlarının

Yanaştığını Kumkapi''ya

Kulağına kar suyu can toriklerin

Karaya vurduğunu Bogaz''da

Yaramasa da isimize, kahvenin

Kaça sürüldüğünü el altından

Yaz ortasında bulursun

Hasta için olduktan sonra

Limonun en sulusunu

Mahalle kırılırken uyuzdan

Sen taşırsın kukuçtu

Mısır Carsısı’ndan

Kursağına girmese de bulursun

Yumurtanın en tazesini

Her derdine koşarsın mahallenin

İnsaflısını verem doktorunun

Dişçinin en ucuzunu

Sen salık verirsin komşulara

Bildiklerin de vardı fazladan

Kalayla çivi üzerine

Biraz daha kurcalarsam

Dökersin içyüzünü nalburların

Benim bilgili becerikli çocuğum

Derse kalktığın zaman

Yüzünun kızarması neden

Üstte basta yok diye mi

Utanmak bize düşer çocuğum

Çalışmadığın içinse

Bildiklerin sana yeter

Notun önceden verilmiş

Bilmediğin şahıs zamirleri olsun', 'Ne sorayım sana Kulak dolgunluğu belediklerini mi söylersin Uyku sersemliği göz gezdirdiğin kitaptan Aklında kalanları mi Çalışmadın istediğ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/remzi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaret Günü Notları', 'ziyaret-gunu-notlari-rifat-ilgaz-x1zj7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Bugün başlıyor asil çilesi,

Namus yüzünden on beş yıl giyen

Beşiktaşlı Ragıpın,

Bugün tuttu Adana’nın yolunu

İki çocuklu karisi;

Seyhan Bara kontratlı gidiyor.

Kaslar alindi, saçlar boyandı.

Roplar dikildi modaya uygun,

İki çocuk bırakıldı komşuya.

Nedir ki masrafı ikisinin,

Kazan ver postaya,

Altına döndü Çukurova''da başaklar

Parmaklığa dayamış alnını Ragıp''ım

Bekliyor karisini orta koğuşta

Olandan bitenden habersiz.

II

Öğretmeni tanımadan

Öğrendi polisi, jandarmayı,

Koltuğunda babasının çamaşır paketi

Köylü sigarası, üç paket,

Bu da kendi armağanı.

Ayıplasalar da mahallede yeridir

Böyle taşınmasını cezaevine,

Parmak kadar çocuğun.

Komşuya düşer dedikodusu elbet

Kitap yüzünden yatanın:

Böylesi hiç geçer mi gazeteye

Yıl 1944

Babasına bakarsan oralı değil,

Varsın diyor, su yolunda kirilsin

Bizim su testisi!

III

Gün görmüş oğlan şu Fikri,

Bilir nasıl karşılanır

3 numaradan Adalet.

Ne çıkar üstte yok, basta yoksa,

Konyalının ceketi yenicedir,

Temelin pabuçları biçimli.

Uğursuz derler Fatihlinin boyunbağına,

-Bir ayda üç hüküm yedi-

Böyle günde takılır elbet,

Açar çiçek gibi adamı.

Güler yüz, tatlı dil Fikrimden,

At elin, eyer emanet.

IV

Üç kuruş, beş kuruş

Harçlık gelir dışardan,

Esten, dosttan, akrabadan.

Yalnız Necati içerden çıkarır

Genç karisinin ekmek parasını.

Kalmadı elde avuçta,

Buraya düştü düşeli,

Bir gençliği kaldı para eder.

Söyle her ziyaret sonu

Beş liracık sıkıştırır eline;

Her seferinde mahcup,

Her seferinde kendinden iğrenir.

V

Ters yüzüne çevirdiler kapıdan

Tütündeki Seviyeyi.

Sarılacak kocasının boynuna

Neler anlatacaktı, neler!

Simdi düşünüyor kara, kara:

''İhtilattan men''de ne demek?

Gitti havaya gündelik,

Bir de gelip görememek!', 'I Bugün başlıyor asil çilesi, Namus yüzünden on beş yıl giyen Beşiktaşlı Ragıpın, Bugün tuttu Adana’nın yolunu İki çocuklu karisi; Seyhan Ba...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/ziyaret-gunu-notlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dileğim Var', 'bir-dilegim-var-murat-serdar-guney-b8g9s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaz sıcağı dışarıda

Kar yağıyor yatağıma

Sevgime aşkıma

Bembeyaz dallarda yalnızlık

Bir ayrılık

Üşüyorum,çaresiz

Ve ben yalnızım odamda

Aklım yok

Terkedilmiş bir deli

Kar yağıyor odama

Sensiz geçen ilk akşamıma 

Çaresizlik,gözyaşlarım

Ve ben suskunum odamda

Hayat boş yaşayamam

Aklım yok düşünemem

Aşkım yok sevinemem

Bir senim var 

Birde dileğim

Oda çok uzaklarda', 'Yaz sıcağı dışarıda Kar yağıyor yatağıma Sevgime aşkıma Bembeyaz dallarda yalnızlık Bir ayrılık Üşüyorum,çaresiz Ve ben yalnızım odamda Aklı...', ARRAY['Türk Edebiyatı','Şiir','Murat Serdar Güney']::text[], 8.5, '{"poet":"Murat Serdar Güney","poet_slug":"murat-serdar-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-dilegim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkadır', 'baskadir-sabit-i-nce-2ye0u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbül gıdı zar ederim

figanım başkadır benim

her güzeli yar ederim

sultanım başkadır benim

yolcuyum handan giderim

göçüm bir başkadır benim

gurbet elde ah ederim

sucum bık başkadır benim...Askın sazını çalarım

telim bir başkadır benim

gece gündüz hep çağlarım

selim bir başkadır benim

Ikıl ayakla yürürüm

yolum bir başkadır benim

ıkıl gözümle görürüm

korum bir başkadır benim

İnceyim ince soylarım,

dilim bir başkadır benim

ateş ile dans eylerim

kulum bir başkadır benim', 'Bülbül gıdı zar ederim figanım başkadır benim her güzeli yar ederim sultanım başkadır benim yolcuyum handan giderim göçüm bir başkadır benim...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baskadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Türkü Yak', 'bir-turku-yak-sabit-i-nce-vc7ku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir türkü yak...

Yanık bir türkü yak

Hüznünden kainat ağlasın

Beni anlatsın

Sen ol nağmelerde

Yankılansın dağ doruklarında

Saclarının teli ile

Ellerimi bağlasın

Bir türkü yak

Yalnızlığıma yoldaş edeyim

Herkes ağlasın yanıklığına

Bir türkü yak

Geçmişim görüntülensin içinde

Geleceğime ayna tutayım

Sevgilileri unuttursun

Mısralarda tek seni yutayım

Bir türkü yak

Sonsuzluğa uzanan bir ses

Gönlümü serinleten nefes

Desinler ki ''harika, çok enfes''

Bir türkü yak

Dudaklarım titresin

O türkü dillerde gönüllerde

Unutulmasın söylensin

Bir türkü yak', 'Bir türkü yak... Yanık bir türkü yak Hüznünden kainat ağlasın Beni anlatsın Sen ol nağmelerde Yankılansın dağ doruklarında Saclarının teli i...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-turku-yak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birliğe Yolculuk', 'birlige-yolculuk-sabit-i-nce-2wvbv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne çöllerde mataramdaki

Son damlayı sebil ettim

Ne dertli sazımın mızrabından

Tellere eziyet ettim

Ne kırk yıllık ömrümü

Geçmişime geleceğe ve sonsuza

Emanet ettim

Bülbülün nağmesinde

Dervişin nefesinde

Zenginin şişkin kesesinde

İltifat, itibar, kifayet, hidayet

Esaret cesaret... ettim

Sadece tertemiz gönlümü

kirlettim

Kapında tapunda yapında

Hatta incecik suratında

Oynadım, kıvırıp da dans ettim

Askınla, meşkinle

Ve sevdanın ateşinde

Pistim yanıp kul ettim

Su kocamaz gönlümü

an be an biten ömrümü

Ateşine pervane yaptım

Beni bencilliği ve ikinciliği

Bir edip birliğe gittim', 'Ne çöllerde mataramdaki Son damlayı sebil ettim Ne dertli sazımın mızrabından Tellere eziyet ettim Ne kırk yıllık ömrümü Geçmişime geleceğe ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birlige-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahil', 'cahil-sabit-i-nce-ukghl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selamünaleyküm dedi oturdu

Muskacı hocaya güvendi cahil

Yanında da bir oğlunu getirdi

Muskanın gücüne inandı cahil

Hocam su oğluma bir haller oldu

Tazecik fidanım sarardı soldu

De Allah aşkına bu nasıl oldu

Hocaya muskaya pek kandı cahil

Evli mi bekar mi bu oğlan dedi

Kasını kaldırıp seyran eyledi

Babası konuştu hoca dinledi

Sırrını anlattı saftandı cahil

Oğlanın adini sordu ilk önce

Acıdı oğlanla göz göze gelince

Oto ne büyükler deyince

İrkildi hayretle sallandı cahil

Ebcede hesabıyla yıldızın açtı

Yazacağı muska iyi ilaçtı

Okuyup üfleyip bir sayfa açtı

Hocanın eline kapandı cahil

Yazdı muskaları tarifin yaptı

Hocamız böylece milyonlar kaptı

Allah’ı unutup hocaya taptı

İNCE bir saygıyla toplandı cahil', 'Selamünaleyküm dedi oturdu Muskacı hocaya güvendi cahil Yanında da bir oğlunu getirdi Muskanın gücüne inandı cahil Hocam su oğluma bir halle...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cahil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-sabit-i-nce-9h14t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer sizde biraz merhamet varsa

Dertlerim artıyor yol verin dağlar

Nazlı yar çıkışta yoluma dursa

Solmasın gonca gül yol verin dağlar

çökmüş dayanmıyor gönlümün damı

Deli, mecnun deyi kınaman beni

Sağımda ardıcı solumda çamı

Size tutunayım el verin dağlar

Ben de sizin gibi yoktan olmuşum

Beli demişim de, karar vermişim

Mahsur misli ben de dara girmişim

İpinin öldürmen dal verin dağlar

Mevla bindir çiçek sizi süslemiş

Türlü renkler verip gergef işlemiş

Gelen gider olup göçe başlamış

Arıya çiçeği bol verin dağlar

Acımadan yakıp kesip iz ettim

İniş yokuş dinlemedim düz ettim

İnce gönlü göyündürüp köz ettim

Yanan bağrınızdan kül verin dağlar', 'Eğer sizde biraz merhamet varsa Dertlerim artıyor yol verin dağlar Nazlı yar çıkışta yoluma dursa Solmasın gonca gül yol verin dağlar çökmüş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/daglar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım', 'dostlarim-sabit-i-nce-v54wu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayaklar altında yol ettin beni

Gelen giden ezer durur dostlarım

Koydu aşkı narı kul etti beni

Gece gündüz tozar durur dostlarım

Tükenmez cevherdim pul etti beni

Özgürlüğüm alıp kul etti beni

Bülbül gibi gülde dil etti beni

Har içinde gezer durur dostlarım

İlkbahar, yaz derken güz etti beni

Gürgen ağacından saz etti beni

Dillere düşürüp söz etti beni

Çala kalem yazar durur dostlarım

Yağmur kar gibiydim dol etti beni

Has ipek dokudum çul etti beni

İnceyim itlere yal etti beni

Kırk elekten süzer durur dostlarım', 'Ayaklar altında yol ettin beni Gelen giden ezer durur dostlarım Koydu aşkı narı kul etti beni Gece gündüz tozar durur dostlarım Tükenmez cev...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymadım', 'doymadim-sabit-i-nce-x1t32', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O nasıl güzellik yaktı kavurdu

Güzelliğin seyretmeye doymadım

Zaman değirmenin hızlı çevirdi

Biran gibi gelip geçti saymadım

Ayni yere giden iki yolcuyuz

Sevgiye susamış iki elciyiz

Gönül duvarına tutmuş alcıyız

Gönül yollarında sesin duymadım

Ürkek ceylan gibi baktın yüzüme

Kavurdun koz attın özün özüme

Zehirli okları attın gözüme

Verdiğin acıyı acı saymadım

Deli rüzgar gibi estin de geçtin

O kibar ellerle kefenim biçtin

Gönül sarayımı izinsiz açtın

Sensiz gecen ömrü omur saymadım

Kıyamadım mam yüzüne bakmadım

Senin kokun yetti güller takmadım

Mest oldum da has bahçeden çıkmadım

İnce seni sevdim doymadım', 'O nasıl güzellik yaktı kavurdu Güzelliğin seyretmeye doymadım Zaman değirmenin hızlı çevirdi Biran gibi gelip geçti saymadım Ayni yere giden...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/doymadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-sabit-i-nce-dv42u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk oduna yanmasını

Bilemedin behey gönül

O deryaya dalmasını

Bilemedin behey gönül

Kalem alıp yazmasını

Diyar gezmesini

Aşk sazını çalmasını

Bilemedin behey gönül

''Ben'' deryasını dolaştın

Hep masivaya bulaştın

Sevgi varken hep dolaştın

Sevemedin behey gönül

Azgın seller gibi coştun

Hırsla yorulmadın koştun

Gönül erlerinden kaçtın

Göremedin behey gönül

Güzelle gönül eyledin

Boşa türküler söyledin

Hiç nasihat dinlemedin

Eremedin behey gönül

Ne utanmaz arlanmazsın

Bu gidişle karlanmazsın

İnce gibi zorlanmazsın

Ölemedin behey gönül', 'Aşk oduna yanmasını Bilemedin behey gönül O deryaya dalmasını Bilemedin behey gönül Kalem alıp yazmasını Diyar gezmesini Aşk sazını çalmasın...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakimim', 'hakimim-sabit-i-nce-2u2dq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konulsak diyorsun sayın hakımım,

hancı derdi nasıl soylayım bilmem.

bene ne sandın sen ben bir adımım

ne yapımda nasıl edeyim bilmem...Bu aşka düşeli yanar ağlarım,

everestden yüce gönül dağlarım

nehirlerden şaşkın göz pınarlarım

bu sele ben nasıl keseyim bilmem...Gam yükünü kervanlara yükledim,

geceleri gündüzüme ekledim.

gelir diye yar yolların bekledim,

o güzeli nasıl söyleyim bilmem...askın tandırına attım kendimi,

kavurdu kul etti su bedenimi,

İnce bir ok deldi geçti sinemi,

yara dosttan geldi nasıl söyleyim', 'Konulsak diyorsun sayın hakımım, hancı derdi nasıl soylayım bilmem. bene ne sandın sen ben bir adımım ne yapımda nasıl edeyim bilmem...Bu aş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hakimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olamaz', 'i-nsan-olamaz-sabit-i-nce-e233q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her bedende can vardır ya

sevmeyen insan olamaz

suret beden insandır ya,

sevmeyen insan olamaz

okumuştur ilmi vardır

kar dediği hep zarardır

o aslında canavardır

sevmeyen insan olamaz.

sureti hakdan görünür

türlü libaslar giyinir

din, iymanıyla övünür

sevmeyen insan olamaz

Hak kelamından dem vurur

her yanı kibirle gurur

sırca sarayda oturur

sevmeyen insan olamaz

İnce doğruları söyler

hanı nerde gaddar beyler? ? 

hal bilmeyen aşkı neyler

sevmeyen insan olamaz.', 'Her bedende can vardır ya sevmeyen insan olamaz suret beden insandır ya, sevmeyen insan olamaz okumuştur ilmi vardır kar dediği hep zarardır...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insan-olamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kah', 'kah-sabit-i-nce-p9529', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kah yanarım kah sönerim

Kah pervane kah dönerim

Kah ağlarım kah gülerim

Kah dağlarda dumanım ben

Kah deliyim kah divane

Kah Yunusum kah Mevlana

Kah Etmemim kah da dana

Kah Mahsura ol darım ben

Kah sultanim kah gedeyim

Kah sevgili kah sevdayım

Kah yarayım kah devayım

Kah Eyyuba magrayim ben

Kah bülbülüm kah bir gülüm

Kah laleyim kah sümbülüm

Kah olumsuz kah oluyum

Kah ebem kah ezelim ben

Kah kalınım kah inceyim

Kah aydınlık kah geceyim

Kah vezinim kah heceyim

Kah dillerde şiirim ben', 'Kah yanarım kah sönerim Kah pervane kah dönerim Kah ağlarım kah gülerim Kah dağlarda dumanım ben Kah deliyim kah divane Kah Yunusum kah Mevl...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kimi', 'kimi-sabit-i-nce-iluzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su insan bin turlu hülyaya dalar

Zerreyi kareyi sele çevirir

Kimi de boş boşa fikrini yorar

Harcanıp tükenmiş pile çevirir

Bazıları koşar bir uğraş verir

Her sözü fikriyle camlar devirir

Kimisi uslanmaz dümen çevirir

Bazısı sırımı tule çevirir

Çiçekler dökülür gelinir sona

Dallarda meyveler can verir cana

Bir gülücük bile yeter insana

Arifler manayı dile çevirir

Vakit gelir yaprak solmaya baslar

Uğraşıp rızkını almaya baslar

Ol deyince yoklar olmaya başlar

Rahmet kesilince kule çevirir

Güz gelir tabiat çulunu soyar

Gökteki yıldızlar duramaz kayar

İnce her taşı da yerine koyar

Koca kainatı sala çevirir', 'Su insan bin turlu hülyaya dalar Zerreyi kareyi sele çevirir Kimi de boş boşa fikrini yorar Harcanıp tükenmiş pile çevirir Bazıları koşar bi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtulmuşum', 'kurtulmusum-sabit-i-nce-21bzu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hak nurunu gerçeklerde

Gördün demek kurtulmuşum

Güzelliği çiçeklerde

Gördün demek kurtulmuşum

Sevda alevinde sinsin

Oyna ki bire gidesin

Hak gerçeklerde bilesin

Sordun demek kurtulmuşum

Sevda ateşi yandıkça

Gönül o yare kandıkça

Gerçek sana inandıkça

Vardın demek kurtulmuşum

Gözler konuşur sevişir

Seven bu sırra erişir

Aşka yananlar bilişir

Verdin demek kurtulmuşum

Gabi sessiz gabi azgın

Böyle sanma yarin yazgın

Sevenlerde olmaz bozgun

Erdin demek kurtulmuşum

Sevda türküsü söylensin

Yanık gönlümüz eğlensin

İnce de hakka bağlansın

yerdin demek kurtulmuşum', 'Hak nurunu gerçeklerde Gördün demek kurtulmuşum Güzelliği çiçeklerde Gördün demek kurtulmuşum Sevda alevinde sinsin Oyna ki bire gidesin Hak...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kurtulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Çiçeği', 'dag-cicegi-erol-ozkan-b4l9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çöller büyüyor izlerimde sessizce

Altın üzüntüler geziniyor gönlümde

İnce bir yel uykuma varsa delice

Bir ben kalırım toprağa en yatkın belkide

Seninle unuttum her avunulmaz düşlerimi

Gerçeğe dönüştü mutluluk gülüşleri

Seninle dolaştım en uzak en soğuk dünyalarda

Yudum yudum ısındım seninle enderin sevdalarda

Soluğunda sımsıcak bir mutluluk türküsü

Gözlerimde sevişen gözlerinin gökgürültüsü

En derin sevgilerde titrerdi bedenim

Seni bulmakmış yanlızlıkta böylesine kaderim

Gerçek beklemeyi ben öğrendim senden

Ne vazgeçer ne giderim tutarım ellerinden

Bir dağ çiçeğinin en güzel renklerinden

Çeker alırım seni  seni beklemeden', 'Çöller büyüyor izlerimde sessizce Altın üzüntüler geziniyor gönlümde İnce bir yel uykuma varsa delice Bir ben kalırım toprağa en yatkın belk...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dag-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bilsin', 'ne-bilsin-sabit-i-nce-ksid2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönülde sevgiden seller akmayan,

askı muhabbete nereden bıksın?

askın nisanını boyna takmayan,

gurbete hasrete nereden bıksın?

sevdanın çölünde mecnun olmayan,

Leyla’yı Mevla’yı nereden bıksın.

gururla kısırı yele salmayan,

kaçıl insan nasıl nereden bilsin...Yüzgeç olup deryalarda yüzmeyen,

denizi dalgayı nereden baksın?

on sekiz bin alemlere gezmeyen,

Burak''ı, mısracı nereden bıksın?

yeter ince sözü fazla uzatma,

arım olmayanlar sözü ne bilsin,

kendini kandırıp boşa aldatma,

kışı görmeyenler yazı ne bilsin??', 'Gönülde sevgiden seller akmayan, askı muhabbete nereden bıksın? askın nisanını boyna takmayan, gurbete hasrete nereden bıksın? sevdanın çölü...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-bilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Güzel', 'o-guzel-sabit-i-nce-67mi2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yayından fırlamış ok

birden içeri gırdı

gözleri ateş saçar,

kibarca selam verdi.

sırtındaki ceketi

saikı zer afet simgesi

etek topuğa değmiş

bir gündüzün gecesi

merhaba hocam dedi

nazkı referans eyledi

gözleri güneş mi ne

nasıl dayansın sine

dudakları gülünce

gece ay doğdu bence

sordum bu güzel kimdir

ferahtın sırınıdır ..işte böyle bir sevda

yaşanıyor herlerde

bülbül güle yanıyor

yine yaram kanıyor

sevda ve aşk deyence

okyanus kabarıyor

bu dünyada sevmeyen

boşa oyalanıyorrrr....', 'Yayından fırlamış ok birden içeri gırdı gözleri ateş saçar, kibarca selam verdi. sırtındaki ceketi saikı zer afet simgesi etek topuğa değmiş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-sabit-i-nce-qa4wl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okyanusta dalgalar

gönlüm kadar coşmadı

kalbimde fırtınalar,

bir sana ulaşmadı...bin bir geçit astımda,

bir sana ulaşmadı

uçarak yaklaştımda,

bir göz atıp bakmadı.

dağlar denizler geçtim,

aşk sinemden çıkmadı,

bir tek ben onu seçtim,

donup bile bakmadı

yaralandım yar deyi,

yaram açıp bakmadı

Alınca bir gül deyi,

verdim amma kokmadı.', 'Okyanusta dalgalar gönlüm kadar coşmadı kalbimde fırtınalar, bir sana ulaşmadı...bin bir geçit astımda, bir sana ulaşmadı uçarak yaklaştımda...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şunlar', 'sunlar-sabit-i-nce-xy5sy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayseri’den Ankara’ya giderken,

otobüs koltuğun kursu sandı o

kulaklarım sessizliğe hasretken,

Bremende mızıkacı oldu o.

Birazcık okumuş ahkam kesiyor,

acı poyraz gıdı çok sert esiyor.

bir tek kendi müslümanca yaşıyor,

on üstünden tam bir sıfır aldı o..bilenle bilmeyen bir olmaz dedi,

karsısındakine cahilsin dedi.

azıcık susarak tepki bekledi,

tv deki bir reytingci oldu o..

İslamın sözcüsü sandı kendini,

farkettim de tez anladım fendini,

allamei cihan etti kendini,

beşinci mezhebe imam oldu o.

Kalem diyor yaz şunların halini,

gönül diyor bağla şunun dilini

İnce iyi bilir hakkın yolunu,

Şeriat bulunca sonu sandı o..', 'Kayseri’den Ankara’ya giderken, otobüs koltuğun kursu sandı o kulaklarım sessizliğe hasretken, Bremende mızıkacı oldu o. Birazcık okumuş ahk...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talancılar', 'talancilar-sabit-i-nce-ygn1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gelen talan eyliyor,

talanlara doyduk yeter.

hepsi yalan söylüyorlar,

doğruluğa doyduk yeter,

aha bu iş burda biter..

sülük gibi kanım emdin,

seslenmedik hep sen bindin,

gökten zembille mi indin,

enayiysek bildik yeter,

aha bu iş burda biter..

demokrasi dedik amma,

demedik ki bizi tınma.

kerhen bir oy verdik amma

bu oy''una kandık yeter,

aha bu iş burda biter..

İnce derki sunduk yeter,

aha bu iş burda biter..', 'Her gelen talan eyliyor, talanlara doyduk yeter. hepsi yalan söylüyorlar, doğruluğa doyduk yeter, aha bu iş burda biter.. sülük gibi kanım e...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/talancilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'usandim', 'usandim-sabit-i-nce-fxns0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırk dört yıldır çile çeker ağlarım

bu çileyi çeke çeke usandım

kurudu yaprağım viran bağlarım

yapraklarım döke döke usandım

Gayri felek ne alıp satamam

avcı olup bir av bile tutamam

çile gömleğimi yırtıp atamam

söküklerim dike dike usandım

Herdaim felekten yedim silleyi

aglarım durmadan bilmem gülmeyi

hepşu insanlardan yedim çelmeyi

düşe kalka seke seke usandım

Gönül verdim bir vefasız güzele

kurudu yaprağım dondu gazele

sevgi saklanınca çıkmaz mesele

ince güller döke döke usandım', 'Kırk dört yıldır çile çeker ağlarım bu çileyi çeke çeke usandım kurudu yaprağım viran bağlarım yapraklarım döke döke usandım Gayri felek ne ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/usandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Türküsü', 'sevda-turkusu-erol-ozkan-c07r5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'An gelir tatlı bir sevda türküsü

Usulca yanaşır düşlerinin kucağına

En doyulmaz gülümseyişiyle

Sarılır kalbinin kollarına

En derin düşlerini kurar çocukca

Bazen en yüce dağlara çıkar seninle

Ve bütün acıklı oyunlar oynanır o sahnede

Seni çağırsa da o sevda türküsü

Koş sen yinede sensizliğine

Umutlu düşler kur içinde

Çiçek çiçek aç gözlerini her fırtınaya

Dayan en acı sessizliklere

Unutma o seni çağırır uykularına

Onun adı tatlı bir sevda türküsü', 'An gelir tatlı bir sevda türküsü Usulca yanaşır düşlerinin kucağına En doyulmaz gülümseyişiyle Sarılır kalbinin kollarına En derin düşlerini...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevda-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senın Oldum', 'senin-oldum-sinan-sadikoglu-2sta0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçların la Gök yüzünü ördüm 

Bulut oldum tel tel okşadım

Kuş oldum her yerine uçtum

Bulut oldum Kuş oldum Ruzgar oldum

Bir savruluşun da SENİN oldum

Nefesin de uzaklara uçtum 

Yüreğin de derinlere daldım

Gözlerin de yağmur oldum

Kokunda bahar oldum

Nefes oldum Kanın oldum Damla oldum

Bir gülüşünde SENİN oldum

Sessizlik te sesini duydum

Karanlıkta gözlerini gördüm

Bahar sabahı seni kokladım

Kokun oldum Sesin oldum Gözün oldum

Bir bakışın da SENİN oldum

Sevginle şehir kurdum

Avare oldum sokaklarını dolaştım

Köşebaşların da sarhoş yattım

Dilendim semt semt seni diledim

Semt oldum Sokak oldum Köşen oldum 

Bir dokunuşun la SENİN oldum', 'Saçların la Gök yüzünü ördüm  Bulut oldum tel tel okşadım Kuş oldum her yerine uçtum Bulut oldum Kuş oldum Ruzgar oldum Bir savruluşun da SE...', ARRAY['Türk Edebiyatı','Şiir','Sinan Sadıkoğlu']::text[], 8.5, '{"poet":"Sinan Sadıkoğlu","poet_slug":"sinan-sadikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senin-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Böceği İle Karınca', 'agustos-bocegi-i-le-karinca-tevfik-fikret-jbxr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karıncayı tanırsınız

Minimini bir hayvandır

Fakat gaayet çalışkandır

Gaayet tutumludur, yalnız

Pek hodgamdır, bu bir kusur:

Hodkam olan zalim olur.

Bir gün ağustos böceği

Tembel tembel ötüp durmak

Neticesi aç kalarak

Karıncadan göreceği

Bürudete bakmaz, gider

Bir lokma şey rica eder

Der ki: - Acıyınız bize

Coluk çocuk evde açız

Ianenize muhtacız.

Karınca bir yüreksize

Layık huşunetle sorar:

- Aç mısınız? Ya o kadar

Uzun, güzel günler oldu.

O günlerde ne yaptınız?

Böcek inler: - Açız, açız

Bakın benzim nasıl soldu

O günlerde gülen, öten

Sazla, sözle eğlenen ben

Bugün bakın ne haldeyim!

Vallah açız, billah açız,

Halimize acıyınız!

Karınca eğlenir: - Beyim,

şimdi de raksedin, ne var?

''Yazın çalan kışın oynar.''', 'Karıncayı tanırsınız Minimini bir hayvandır Fakat gaayet çalışkandır Gaayet tutumludur, yalnız Pek hodgamdır, bu bir kusur: Hodkam olan zali...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/agustos-bocegi-ile-karinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçılar', 'balikcilar-tevfik-fikret-5ow4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Bugün açız yine evlatlarım, diyordu peder, 

Bugün açız yine; lâkin yarın, ümid ederim, 

Sular biraz daha sakinleşir... Ne çare, kader! 

- Hayır, sular ne kadar coşkun olsa ben giderim 

Diyordu oğlu, yarın sen biraz ninemle otur; 

Zavallıcık yine kaç gündür işte hasta... 

- Olur; 

Biraz da sen çalış oğlum, biraz da sen çabala; 

Ninen baban, iki miskin, biz artık ölmeliyiz... 

Cocuk düşündü şikayetli bir nazarla: - Ya biz, 

Ya ben nasıl yaşarım siz ölürseniz? 

Hâlâ 

Dışarda gürleyerek kükremiş bir ordu gibi 

Döverdi sahili binlerce dalgalar asabi. 

- Yarın sen ağları gün doğmadan hazırlarsın; 

Sakın yedek biraz ip, mantar almadan gitme... 

Açınca yelkeni hiç bakma, oynasın varsın; 

Kayık çocuk gibidir: Oynuyor mu kaydetme, 

Dokunma keyfine; yalnız tetik bulun, zirâ 

Deniz kadın gibidir: Hiç inanmak olmaz ha! 

Deniz dışarda uzun sayhalarla bir hırçın 

Kadın gürültüsü neşreyliyordu ortalığa. 

- Yarın küçük gidecek yalnız, öyle mi, balığa? 

- O gitmek istedi; ''Sen evde kal! '' diyor... 

- Ya sakın 

O gelmeden ben ölürsem? 

Kadın bu son sözle 

Düşündü kaldı; balıkçıyla oğlu yan gözle 

Soluk dudaklarının ihtizâz-ı hâsirine 

Bakıp sükût ediyorlardı, başlarında uçan 

Kazayı anlatıyorlardı böyle birbirine. 

Dışarda fırtına gittikçe pür-gazab, cûşan 

Bir ihtilâc ile etrafa ra''şeler vererek 

Uğulduyordu... 

- Yarın yavrucak nasıl gidecek? 

şafak sökerken o, yalnız, bir eski tekneciğin 

Düğümlü, ekli, çürük ipleriyle uğraşarak 

ilerliyordu; deniz aynı şiddetiyle şırak - 

şırak dövüp eziyor köhne teknenin şişkin 

Siyah kaburgasını... Ah açlık, ah ümid! 

Kenarda, bir taşın üstünde bir hayâl-i sefid 

Eliyle engini güya işaret eyleyerek 

Diyordu: ''Haydi nasibin o dalgalarda, yürü! '' 

Yürür zavallı kırık teknecik, yürür; ''Yürümek, 

Nasibin işte bu! Hâlâ gözün kenarda... Yürü! '' 

Yürür, fakat suların böyle kahr-ı hiddetine 

Nasıl tahammül eder eski, hasta bir tekne? 

Deniz ufukta, kadın evde muhtazır... ölüyor: 

Kenarda üç gecelik bâr-ı intizâriyle, 

Bütün felaketinin darbe-i hasariyle, 

Tehi, kazazede bir tekne karşısında peder 

Uzakta bir yeri yumrukla gösterip gülüyor; 

Yüzünde giryeli, muzlim, boğuk şikayetler...', '-Bugün açız yine evlatlarım, diyordu peder,  Bugün açız yine; lâkin yarın, ümid ederim,  Sular biraz daha sakinleşir... Ne çare, kader!  - H...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/balikcilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kimsin Diye Sorma Meleğim', 'bana-kimsin-diye-sorma-melegim-tevfik-fikret-7sg3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana kimsin diye sorma meleğim

Pek güzel dinle de izah edeyim

Nam-ı naçizime `Fikret'' derler

Şi''re de nisbetimi söylerler

Kaldığım varsa da gah ekmeksiz

Kalmadım şimdiye dek mesleksiz

Nur bekler gibi nısf-ı şebde

Bekledim on iki yıl mektebde

Sonra çıktım ne için bilmeyerek

Bu da bir cilve-i baht olsa gerek

Bab-ı Ali''ye müdavimlendim

Ehl-i namus diye mimlendim

Şimdi bir hayli eser sahibiyim

`Ahmed Ihsan''da musahhih gibiyim

Saye-i lutf-i cihan-banide

Hocayım Mekteb-i Sultani''de...', 'Bana kimsin diye sorma meleğim Pek güzel dinle de izah edeyim Nam-ı naçizime `Fikret'' derler Şi''re de nisbetimi söylerler Kaldığım varsa da ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-kimsin-diye-sorma-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İçim Su', 'bir-i-cim-su-tevfik-fikret-3cu5u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel çoban, bir içim, bir yudum su testinden

Bugün sıcak yine pek, sanki ortalık yanıyor

Güzel çocuk senin olsun hayatım istersen

Niçin gözüm sana baktıkça böyle yaşlanıyor?

Güzel çoban, ne kadar tatlı söylüyorsun sen

Yalan da olsa içim doğru söyledin sanıyor

Güzel çocuk, bana bak, aldatır mıyım seni ben?

İçin bu yaşları boş anlıyorsa aldanıyor!

Güzel çoban, bir içim, bir yudum su testinden

Bugün sıcak yine pek, sanki her yanım yanıyor!', 'Güzel çoban, bir içim, bir yudum su testinden Bugün sıcak yine pek, sanki ortalık yanıyor Güzel çocuk senin olsun hayatım istersen Niçin göz...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-icim-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haluk''un İnancı', 'haluk-un-i-nanci-tevfik-fikret-7siv2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yaratıcı güç var, ulu ve akpak, 

kutsal ve yüce, ona vicdanla inandım. 

Yeryüzü vatanım, insansoyu milletimdir benim, 

ancak böyle düşünenin insan olacağına inandım. 

Şeytan da biziz cin de, ne şeytan ne melek var; 

dünya dönecek cennete insanla, inandım. 

Yaradılışta evrim hep var, hep olmuş, hep olacak, 

ben buna Tevrat''la, İncil''le, Kuran''la inandım. 

Tekmil insanlar kardeşi birbirinin... Bir hayal bu! 

Olsun, ben o hayale de bin canla inandım. 

İnsan eti yenmez; oh, dedim içimden, ne iyi, 

bir an için dedelerimi unuttum da, inandım. 

Kan şiddeti besler, şiddet kanı; bu düşmanlık 

kan ateşidir, sönmeyecek kanla, inandım. 

Elbet şu mezar hayatı zifiri karanlığın ardından 

aydınlık bir kıyamet günü gelecek, buna imanla inandım. 

Aklın, o büyük sihirbazın hüneri önünde 

yok olacak, gerçek dışı ne varsa, inandım. 

Karanlıklar sönecek, yanacak hakkın ışığı, 

patlayan bir volkan gibi bir anda, inandım. 

Kollar ve boyunlar çözülüp, bağlanacak bir bir 

yumruklar şangırdayan zincirlerle, inandım. 

Bir gün yapacak fen şu kara toprağı altın, 

bilim gücüyle olacak ne olacaksa... İnandım.', 'Bir yaratıcı güç var, ulu ve akpak,  kutsal ve yüce, ona vicdanla inandım.  Yeryüzü vatanım, insansoyu milletimdir benim,  ancak böyle düşün...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/haluk-un-inanci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Han-ı Yağma', 'han-i-yagma-tevfik-fikret-fujif', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sofracık, efendiler - ki iltikaama muntazır

Huzurunuzda titriyor - bu milletin hayatıdır; 

Bu milletin ki mustarip, bu milletin ki muhtazır! 

Fakat sakın çekinmeyin, yiyin, yutun hapır hapır...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin! 

Efendiler pek açsınız, bu çehrenizde bellidir

Yiyin, yemezseniz bugün, yarın kalır mı kim bilir? 

Bu nadi-i niam, bakın kudumunuzla müftehir! 

Bu hakkıdır gazanızın, evet, o hak da elde bir...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin! 

Bütün bu nazlı beylerin ne varsa ortalıkta say

Haseb, neseb, şeref, oyun, düğün, konak, saray,

Bütün sizin, efendiler, konak, saray, gelin, alay; 

Bütün sizin, bütün sizin, hazır hazır, kolay kolay...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin! 

Büyüklüğün biraz ağır da olsa hazmı yok zarar

Gurur-ı ihtişamı var, sürur-ı intikaamı var.

Bu sofra iltifatınızdan işte ab u tab umar.

Sizin bu baş, beyin, ciğer, bütün şu kanlı lokmalar...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin! 

Verir zavallı memleket, verir ne varsa, malını

Vücudunu, hayatını, ümidini, hayalini

Bütün ferağ-ı halini, olanca şevk-i balini. 

Hemen yutun düşünmeyin haramını, helalini...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin! 

Bu harmanın gelir sonu, kapıştırın giderayak! 

Yarın bakarsınız söner bugün çıtırdayan ocak! 

Bugünkü mideler kavi, bugünkü çorbalar sıcak,

Atıştırın, tıkıştırın, kapış kapış, çanak çanak...

Yiyin efendiler yiyin, bu han-ı iştiha sizin,

Doyunca, tıksırınca, çatlayıncaya kadar yiyin!', 'Bu sofracık, efendiler - ki iltikaama muntazır Huzurunuzda titriyor - bu milletin hayatıdır;  Bu milletin ki mustarip, bu milletin ki muhtaz...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/han-i-yagma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-erol-ozkan-5ncfx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret dolu bir fırtınaydı gözlerinden süzülen

Gül damlacıklarıydı dudaklarından yansıyan

Ay ışığı kırılmasıydı yüreğimdeki sancı

Buzdan bir erguvan çiçeği duygularım

Ne fırtına ne gül damlası

Bulur mu sandın beni

Adı konmamış şiirler mi anlatır beni

Bu kadar kolay mı dost yüreğin solgun sesini duyabilmek

Bembeyaz gül tarlasına düşmüş düşlerim

Haykırır mı sandın sevda çığlıklarıyla

Kupkuru pınarların baş ucundan

Ağlayan yapraklar mı gülebilirdi yanlızlığıma

Ve ben güzelim 

En derin dağ doruklarında

Sisler arasında söylerim türkülerimi.', 'Hasret dolu bir fırtınaydı gözlerinden süzülen Gül damlacıklarıydı dudaklarından yansıyan Ay ışığı kırılmasıydı yüreğimdeki sancı Buzdan bir...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seslenis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Köprü', 'i-ki-kopru-erol-ozkan-zqioo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her güneş doğuşunda

Her ay yansımasında

Her çiçeğin gülüşünde

Her yürek haykırışında

Her çiğ damlasında

Her deniz dalgasında

Her kuş ötüşünde

Her aşk nağmesinde

Her sevda tarlasında

Her yaprak gülüşünde

Her olan her ne kadar her varsa

Hepsi bana köprü

Ama bir adım attığımda

Hepsi birer hayal

Her ıssız gece

Her sessiz çığlık

Her yaşlı göz

Her yaralı yürek

Her fırtına

Her türlü çile

Bunun gibi her ne varsa

Hepsi bana köprü

Ama bir adım attığımda

Hepsi benim yanımda', 'Her güneş doğuşunda Her ay yansımasında Her çiçeğin gülüşünde Her yürek haykırışında Her çiğ damlasında Her deniz dalgasında Her kuş ötüşünd...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iki-kopru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Sevdam', 'don-sevdam-ayse-eski-zjgx2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yılan hikayesi gecesi;

Gözlerin geldi aklıma...

Aslında dayanacak gücüm var desem yalan olur,

yenik düştüm sevdana.

Sen benden daha delisin;

Çektin gittin işte geri gelmedin.

Ne zaman son bulacak bu işkencen,zamanım bitiyor

Çatlayası deli yürek sen,sen diye atıyor

Ya sen gel,ya beni öldür.

Yüreğim sensizliği kabul etmiyor...', 'Bir yılan hikayesi gecesi; Gözlerin geldi aklıma... Aslında dayanacak gücüm var desem yalan olur, yenik düştüm sevdana. Sen benden daha deli...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Eski']::text[], 8.5, '{"poet":"Ayşe Eski","poet_slug":"ayse-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/don-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-ayse-eski-3iptg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte sakin sessiz

Gözümde bir damla gözyaşıyla

Kalbimde sönmüş bir aşkın külleri

Beynimdeyse birkaç hatıra

Gidiyorum işte

ELVEDA!', 'Gidiyorum işte sakin sessiz Gözümde bir damla gözyaşıyla Kalbimde sönmüş bir aşkın külleri Beynimdeyse birkaç hatıra Gidiyorum işte ELVEDA!...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Eski']::text[], 8.5, '{"poet":"Ayşe Eski","poet_slug":"ayse-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/elveda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Veda', 'bu-son-veda-omer-faruk-cakir-y6l7s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biraz sonra gökyüzüne bak

Uzaklarda bir yıldız kayacak

Fırtınalar kopacak, yağmur yağacak

Bu son veda, zaman doldu dolacak

Biliyorum gün yine doğacak

Gece gölgemde saklanacak

Kapıyı açma sakın

Duvara da bakma

Bir ipin ucunda

Gece sallanıyor olacak', 'Biraz sonra gökyüzüne bak Uzaklarda bir yıldız kayacak Fırtınalar kopacak, yağmur yağacak Bu son veda, zaman doldu dolacak Biliyorum gün yin...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-son-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Pencere', 'kucuk-pencere-omer-faruk-cakir-tdd60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir garip şeydi yaşamak,

Umudu yaşatmaksa güç.

İllaki sarılmalı mı hayata?

Umut ölür mü yoksa?

Küçük bir pencereden,

Gökyüzüne bakmaktı hayat.

Bazen gökyüzü kadar büyük,

Bazen pencere kadar küçük!

Biliyor musun?

Mutsuzluğu hiç aramadım ben.

İki kişilik bir saklambacın kahramanlarıydık.

O hep beni buldu!

O gece bir tuhaftı içim 

Yine hiç uyumamıştım

O lanet gecenin sabahı

Ben neden o kaldırımdaydım?', 'Bir garip şeydi yaşamak, Umudu yaşatmaksa güç. İllaki sarılmalı mı hayata? Umut ölür mü yoksa? Küçük bir pencereden, Gökyüzüne bakmaktı haya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuk-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki Ben', 'ki-ben-omer-faruk-cakir-bfk3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman ki senden benden aldıkları ile yaşar

Ki ben istesem aldıklarını geri 

Verecek nesi var!

Ki ben istesem aldıklarını geri ey zaman

Yok değil ama yoktan

Yâr değil ama yârdan

Kâr değil ama kardan

Sen değil ama senden

Ki ben istesem aldıklarını geri ey zaman

Hiç değil ama hiçten kırılan,

Kağıdı, buruşturulup atılan,

Nice yardan geçen gönülde; bu kez yeni bir ferman!

Var git be deli adam o yâre uzan', 'Zaman ki senden benden aldıkları ile yaşar Ki ben istesem aldıklarını geri  Verecek nesi var! Ki ben istesem aldıklarını geri ey zaman Yok d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun', 'kursun-omer-faruk-cakir-h0506', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurşun sandın ki yüreği delendin, sen

Sadece deliği deşen

İdamım gerçekleşti az önce

Sen son isteğim sen

Bu günümde de yoktun yanımda

Sen en sevilen!', 'Kurşun sandın ki yüreği delendin, sen Sadece deliği deşen İdamım gerçekleşti az önce Sen son isteğim sen Bu günümde de yoktun yanımda Sen en...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-omer-faruk-cakir-uhyri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sorgularken kendimi rastladım bu cevaba 

Acıydı belki ama acı da vardı hayatta 

Hani şu yıldız vardı ya, uzakta, sordum ona 

Ne yapılır ki hayat yoksa hayatta', 'Sorgularken kendimi rastladım bu cevaba  Acıydı belki ama acı da vardı hayatta  Hani şu yıldız vardı ya, uzakta, sordum ona  Ne yapılır ki h...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sorgu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncecik Bİr Veda Havası', 'i-ncecik-bi-r-veda-havasi-omer-faruk-cakir-32rjg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elveda demem sana, el değilsin

Hiçbirgün olmadı ki, gün olsun gelsin

Kim sorarsa hüznü anlatayım, gelsin

Elveda demem sana, El değilsin

Elveda demem sana, el değilsin

Gece de ne suskun ha! ki sen tek sessin

Olmasan da yanımda bil ki içimdesin

Elveda demem sana, el değilsin

Elveda demem sana, el değilsin

Güller yok ki hayatta yüzde gülücük bitsin

Biten bitsin sen benim bitmeyenimsin

Elveda demem sana, el değilsin', 'Elveda demem sana, el değilsin Hiçbirgün olmadı ki, gün olsun gelsin Kim sorarsa hüznü anlatayım, gelsin Elveda demem sana, El değilsin Elve...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/incecik-bir-veda-havasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazende', 'nazende-omer-faruk-cakir-j8od5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani demiştin ya bana ey gece 

Hiçbir yıldıza yarinin adını verme 

Olaki kayıpta gider diye 

Söyler misin şimdi bana değişen ne? 

Bir ömür sensiz nasıl yaşanır, bilmiyorum 

Öğretecek misin? 

Umudu yaşatmak güçtü zaten, umut nazende bir çiçek 

Öldürecek misin? 

Gitme desem de, küçüğüm gidecek 

Gidipte dönmeyecek misin? 

Nazendem, beni viran bir şehir kılıp 

Terk mi edeceksin? 

Hiçbir yıldıza adını vermemiştim bilmem kaç gece 

Olaki kayıpta gidersin diye 

Nazende, bu hal ne öyleyse 

Giden kim, kim bu aynadaki harabe?', 'Hani demiştin ya bana ey gece  Hiçbir yıldıza yarinin adını verme  Olaki kayıpta gider diye  Söyler misin şimdi bana değişen ne?  Bir ömür s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nazende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-pinar-altanoglu-tng1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bende gördüğün

ben ile

Bendeki ben

çoook  ayrı

birbirinden.

(10.07.86 Viyana)', 'Bende gördüğün ben ile Bendeki ben çoook  ayrı birbirinden. (10.07.86 Viyana)...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-omer-karayilan-b0h35', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıfır beş suları,beş parasızsın,

Çorbalar vitrinde buğulanıyor.

Yeni bir sabaha karşı yalnızsın,

Sokak lambaları hala yanıyor.

Ah bu otel odaları,külüstür,

Ah bu aynalarda dağılan sesin.

Bütün karartılar seni ürkütür,

Yanlış bir treni beklemektesin.

Ne yana uzansan yalnızlık orda,

Neye el uzatsan, kırılan bir cam.

Varmak istediğin istasyonlarda,

Seninle birlikte inecek akşam.

Sakalın birikmiş,göğsünde sızı,

Parmak uçlarında yüksek gerilim.

Sen tüm şehirlerin baştan yalnızı,

Bense aradığın adam değilim..', 'Sıfır beş suları,beş parasızsın, Çorbalar vitrinde buğulanıyor. Yeni bir sabaha karşı yalnızsın, Sokak lambaları hala yanıyor. Ah bu otel od...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karayılan']::text[], 8.5, '{"poet":"Ömer Karayılan","poet_slug":"omer-karayilan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yabanci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engel', 'engel-pinar-altanoglu-z0xat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olacak kesin şeyler

engellenemez;

sevmek  ve ayrılmak

gülmek ve ağlamak

doğmak ve ölmek gibi....

olacak kesin şeyler

engellenemez,

engeller !

(01.11.1986 Istanbul)', 'Olacak kesin şeyler engellenemez; sevmek  ve ayrılmak gülmek ve ağlamak doğmak ve ölmek gibi.... olacak kesin şeyler engellenemez, engeller ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/engel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Benzer Biri', 'sana-benzer-biri-omer-karayilan-94z1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana benzer birini tanıdım bir vakit,

Gülünce gün ışırdı.

Güzeldi,ne giyse yaraşırdı,

Aklım karışırdı.

Bakmaya doyamazdım,

Baksam içime sahipsizlik bulaşırdı.

Dokunmaya kıyamazdım,

Uzak diyarlardan gelmiş gibiydi,

Kaçtıkça yaklaşırdı.

Sana benzer birini gördüm bir vakit,

Korkunç güzel gözleri vardı,

Müşiş derin bakardı.

Yüzünde İstanbullu bir hüzün,

Koynunda resmim vardı.

Bir kavgayı tutmuştuk bir ucundan,

Elleri tütün,saçları deniz kokardı,

Tutsam kıvılcımlar çıkardı avcundan,

Ateşti,yakardı.

Sana benzer birini yaşadım bir vakit,

Bensiz bir dakka durmaz,

Benle olamazdı.

Ezan sesleriyle başlardı gün onunla,

Yıldızlarla sönerdi.

Gülümsese ağrılarım dinerdi,

Öpsem başım dönerdi.

Öfkesi delikanlıydı,

Delifişekti,heyecanlıydı.

Umudunu sevdamıza banardı,

Omuzuna güvercinler konardı.

İmkansızdı onu taşımak göğsümde,

Görmesem içim yanardı.

Sana benzer birini sevdim bir vakit,

Çocukça korkardı ölümden.

Bilmezdi,ertelenemezdi ölüm oysa.

Seni mi o sandım bilmem,

Onu mu sen.

Ona hiç benzemiyorsun..', 'Sana benzer birini tanıdım bir vakit, Gülünce gün ışırdı. Güzeldi,ne giyse yaraşırdı, Aklım karışırdı. Bakmaya doyamazdım, Baksam içime sahi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karayılan']::text[], 8.5, '{"poet":"Ömer Karayılan","poet_slug":"omer-karayilan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sana-benzer-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal ve Gerçek', 'masal-ve-gercek-pinar-altanoglu-vy03g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir masal oldu şimdi

yaşanan güzel anılar,

yıllar sandığında 

sararmaya mahkum

o güzel duygular.

Gün gelip

yeni gençler açtığında o sandığı

sararmış anıları yaşatacaklar.

Masallar,

güzel duygular,

kilit altında kalacak sonsuza kadar.

Oysa...

gerçekler ve kabuslar

her an aramızdalar.

Asırlardır insanlar

Buna yaşamak diyorlar.....

(19.01.1987 Istanbul)', 'Bir masal oldu şimdi yaşanan güzel anılar, yıllar sandığında  sararmaya mahkum o güzel duygular. Gün gelip yeni gençler açtığında o sandığı ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/masal-ve-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Kişi', 'mutlu-kisi-omer-hayyam-yvn09', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk kitabını evirdim,çevirdim,

Bir adam konuştu kitabın içinden;

Yüreği yana yana bir adam:

''Kimdir mutlu kişi, bilir misin?

Bir karısı olacak, ay gibi güzel,

Bir gecesi sürecek yıl kadar uzun...''', 'Aşk kitabını evirdim,çevirdim, Bir adam konuştu kitabın içinden; Yüreği yana yana bir adam: ''Kimdir mutlu kişi, bilir misin? Bir karısı olac...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mutlu-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-pinar-altanoglu-j2fja', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin ne parlak

çoçuk,

saçların ne sıcak.

Kocaman kocaman gülüşünü

çok seviyorum

çocuk,

sana çabuk alıştım

sınırları aşacağız

çocuk..

İlk kez yaşıyorum

bazı duyguları,

ilk kez gerçek saygıyla

bitimsiz sevgiyi

birlikte öğreniyorum....

Dikkat et çocuk,

dikkat et...

Sakın bozma

bu oyunu.

( En güzel Ağustos''ta Istanbul)', 'Gözlerin ne parlak çoçuk, saçların ne sıcak. Kocaman kocaman gülüşünü çok seviyorum çocuk, sana çabuk alıştım sınırları aşacağız çocuk.. İlk...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sakin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Bir Yana, Sen Bir Yana', 'dunya-bir-yana-sen-bir-yana-omer-hayyam-jg6au', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeryüzü padişahların, kralların olsun.

Cehhennem kötü insanın olsun, Cennet iyi insanın..

Tanrıya toz kondurmamak meleğin işi olsun,

Temizlik, Cennet kapıcısının işi..

Kim, ne olursa olsun,

Sevgili bizim olsun tek,

Canı, Canımız olsun....', 'Yeryüzü padişahların, kralların olsun. Cehhennem kötü insanın olsun, Cennet iyi insanın.. Tanrıya toz kondurmamak meleğin işi olsun, Temizli...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dunya-bir-yana-sen-bir-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustosta Kar', 'agustosta-kar-mumtaz-begen-1dqqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlasan hisseder burdan duyardım, 

Zor günde yanında yine ben vardım, 

Demek senin için sâde kumardım, 

	Başkası için at bundan sonra zar, 

	Yağdırdın gönlüme Ağustosta kar! 

Hani sen sevince başka severdin, 

Sev de Leyla kimmiş, ben de gör derdin, 

Ne yüzüm güldü ne bir gün gösterdin, 

	Bir bir anlatmaktan ar ederim ar, 

	Yağdırdın gönlüme Ağustosta kar! 

Dedin mi bir gün “al şunu yesene”

Bildiğin tek şey var “çıkıp gelsene”

Haydi artık sen de bir şey desene, 

	Çektiğim yetmez mi dahası mı var? 

	Yağdırdın gönlüme Ağustosta kar! 

Boşa gider sıkma artık kurşunu, 

Kıymetlisin, kursun anan turşunu, 

Biraz geçte olsa anladım şunu, 

	Senden ne sevgili olur ne de yâr, 

	Yağdırdın gönlüme Ağustosta kar!', 'Ağlasan hisseder burdan duyardım,  Zor günde yanında yine ben vardım,  Demek senin için sâde kumardım,  	Başkası için at bundan sonra zar,  ...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agustosta-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''na', 'o-na-mehmet-can-kaya-pr2i5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey can..!

Seni görmekse de muradım;

Görsem de arş''a çıkar feryadım.', 'Ey can..! Seni görmekse de muradım; Görsem de arş''a çıkar feryadım....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can Kaya']::text[], 8.5, '{"poet":"Mehmet Can Kaya","poet_slug":"mehmet-can-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/o-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Garip Şey Anne', 'ne-garip-sey-anne-ferdi-coskun-7186g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam Olunca Bir Garip Hüzün Çöker İçime 

Bilemiyorum Belkide Senden Ayrılacağım Diye

O Güzel Günün Ardında Tatlı Bir Acıyla

Sensiz Geçen  Akşamın Karanlığında

Hep Seni Düşünür 

Sensizliğin Acısını İçimde Hissederim

Bir Garip Şekilde

Ne Zor Şeymiş Sevmeden Yaşamak

NE GARİP ŞEY ANNE', 'Akşam Olunca Bir Garip Hüzün Çöker İçime  Bilemiyorum Belkide Senden Ayrılacağım Diye O Güzel Günün Ardında Tatlı Bir Acıyla Sensiz Geçen  A...', ARRAY['Türk Edebiyatı','Şiir','Ferdi Coşkun']::text[], 8.5, '{"poet":"Ferdi Coşkun","poet_slug":"ferdi-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-garip-sey-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan Bir Öykü', 'siradan-bir-oyku-deniz-soylu-v5cyl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unuttun mu kimin çocuklarıyız biz

Bir kırık kalemle

Bir yırtık sayfadan doğduk

                       yıldızlar kaçışırken evine

Hep sevgi koktu dizeler

Fişekçi''nin kaleminde.

... O mürekkep besledi bizi.

Hatırlarsın garip rastlantılardan

                         değildi yüzünü görüşüm

O an bir gökkuşağı

Teslim etti kendini insafsız hayata.

... Ve Asaf''ın şiirleri büyüttü bizi.

Mevsim kış aylardan Şubat

Ortasında dünyanın 

Sonsuzluk alevi

İsteyerek bilerek başladı herşey.

... Ümit Yaşar yürüttü bizi.

Korktuk gün doğuşundan

Yağmurlarda Orhan Veli okuduk

Bir yılan arasında sayfaların

Ezdik

      ezdik

           ezdik

Elimiz kaldı içinde.

... Hasan Hüseyin diriltti bizi.

Bir matbaadır hayat

İnsanlar üç-beş sayfa gazete

Gece baskısında

Acısıyla tatlısıyla

Uyuya kalmaktır aşk

Can Yücel''in matbaasında.

... Tüm ozanlar yüceltti bizi.', 'Unuttun mu kimin çocuklarıyız biz Bir kırık kalemle Bir yırtık sayfadan doğduk                        yıldızlar kaçışırken evine Hep sevgi k...', ARRAY['Türk Edebiyatı','Şiir','Deniz Soylu']::text[], 8.5, '{"poet":"Deniz Soylu","poet_slug":"deniz-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siradan-bir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyalar Kurdum', 'dunyalar-kurdum-deniz-soylu-y9u7y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çamurdan değil

Hücre hücre aşktan

Tanrılar

        insanlar 

                 dünyalar yarattım

Oynayasın diye.

İnsanlar yerleştirdim

İçine dünyaların

Damarlarında aşk

Güzelleştiler büyüdükçe

İnsanlığımız kalmadı

Bunu görüp küçüldükçe.

Sonra

Seni tanımayana

                    kitaplar yazdım

Masalları

Destanları yaktım attım

Nasılsa boş hepsi diye.

Şarkılar söyledim

Yola geldi asiler dinledikçe

Her insan sen oluverdi

Sözler Cemre''leşip

Yeryüzüne düşünce.

Tanrılar

        insanlar

                 dünyalar yarattım sana

Aşkı öğrenesin diye.', 'Çamurdan değil Hücre hücre aşktan Tanrılar         insanlar                   dünyalar yarattım Oynayasın diye. İnsanlar yerleştirdim İçine ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Soylu']::text[], 8.5, '{"poet":"Deniz Soylu","poet_slug":"deniz-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dunyalar-kurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yağmur Yağan', 'o-yagmur-yagan-deniz-soylu-lkzma', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni istiyorum bu akşam

Uzun oldu görüşmeyeli...

Kokun solmuş battaniyemde saçların

Yediğimiz yemeklerin tadı

Çıkmış hatırımdan

İçtiğimiz rakı yok

Uçmuş  damlalar bardaktan

Bir Eylül yağmurunda

           sıcak

Öpüşmemiz yarım kalmıştı

Gezer dudağımda ıslaklığı.

Uzun olmuş görüşmeyeli

Seni istiyorum bu akşam

Yine o yağmur yağan.', 'Seni istiyorum bu akşam Uzun oldu görüşmeyeli... Kokun solmuş battaniyemde saçların Yediğimiz yemeklerin tadı Çıkmış hatırımdan İçtiğimiz ra...', ARRAY['Türk Edebiyatı','Şiir','Deniz Soylu']::text[], 8.5, '{"poet":"Deniz Soylu","poet_slug":"deniz-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-yagmur-yagan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıt', 'anit-deniz-soylu-ksx2w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önceleri

Anıtlaşmak isterdim

Bazı şeyler kaybolana dek

Şimdi istediğim

Sevgimize

Bir anıt dikmek.', 'Önceleri Anıtlaşmak isterdim Bazı şeyler kaybolana dek Şimdi istediğim Sevgimize Bir anıt dikmek....', ARRAY['Türk Edebiyatı','Şiir','Deniz Soylu']::text[], 8.5, '{"poet":"Deniz Soylu","poet_slug":"deniz-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götürmek İster Beni', 'goturmek-i-ster-beni-eyup-yildiz-5bx6z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azrail canımı almaya gelmiş gülüm

Senden koparıp götürmek ister beni

Sensiz son dakikalar son saniyelerim

Bembeyaz kefene sarıp götürmek ister beni

Yavaş yavaş yaklaşıyorum ölüme

Alışamadım bitanem sensizliğe

Daha doyamadan gençliğime

Kırık bir tabuta koyup götürmek ister beni

Sevgin eksilmedi hiç gönlümden

Utanıyorum beni sevenlerden bu kötü kaderimden

Seni son birkez daha göremeden

Bir avuç toprağa gömüp götürmek ister beni', 'Azrail canımı almaya gelmiş gülüm Senden koparıp götürmek ister beni Sensiz son dakikalar son saniyelerim Bembeyaz kefene sarıp götürmek ist...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Yıldız']::text[], 8.5, '{"poet":"Eyüp Yıldız","poet_slug":"eyup-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goturmek-ister-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Gördüm', 'sende-gordum-eyup-yildiz-lzosv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim titriyor bitanem seni görünce

Sevdan uyutmuyor beni gecelerce

Kalbim alışamadı bitanem sensizliğe

Çileyi sende gördüm gülüm çileyi sende

Ne yapsamda unutamıyorum seni

Uğruna adadım gençliğimi

Senin için terkettim tüm sevdiklerimi

Hasreti sende gördüm gülüm hasreti sende

Senin insafsız yüreğine mahkum oldum

Birkaç damla gözyaşı arasında kayboldum

Sensizken günden güne kahroldum

Yaşarken ölmeyi sende gördüm gülüm yaşarken ölmeyi...', 'Yüreğim titriyor bitanem seni görünce Sevdan uyutmuyor beni gecelerce Kalbim alışamadı bitanem sensizliğe Çileyi sende gördüm gülüm çileyi s...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Yıldız']::text[], 8.5, '{"poet":"Eyüp Yıldız","poet_slug":"eyup-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sende-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Calls Of The Sides', 'calls-of-the-sides-ugur-ozbala-pmkmy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anoşer battle begins between light&darkness.

Once again i hear şe calls of şe sides,

Trying lo lure me to şeir goals.

Once again i am lost in şis struggle...

Dark whispers echo in şe night;

Torturing&alluring me to my dark side,

I can''t resist.

The sun blinds me to şe truş,

Illumination warms me deep inside.

I can''t fight against it.

Forever i am lost !', 'Anoşer battle begins between light&darkness. Once again i hear şe calls of şe sides, Trying lo lure me to şeir goals. Once again i am lost i...', ARRAY['Türk Edebiyatı','Şiir','Uğur Özbala']::text[], 8.5, '{"poet":"Uğur Özbala","poet_slug":"ugur-ozbala","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/calls-of-the-sides-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hatice-korkmaz-4mhid', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ask bir güldür,

Güller her dem açmaz.

Sulanmayınca büker boynunu,

Solmaya dermanı bile kalmaz...', 'Ask bir güldür, Güller her dem açmaz. Sulanmayınca büker boynunu, Solmaya dermanı bile kalmaz......', ARRAY['Türk Edebiyatı','Şiir','Hatice Korkmaz']::text[], 8.5, '{"poet":"Hatice Korkmaz","poet_slug":"hatice-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere', 'gidenlere-hatice-korkmaz-p00gl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidenler var ömrümde

Öyle şimşek gibi değil,

Tıpkı bir yıldız gibi sessiz ve yavaş yavaş...

Gidenler var ömrümde,gidenler

Sen ve senin gibiler!', 'Gidenler var ömrümde Öyle şimşek gibi değil, Tıpkı bir yıldız gibi sessiz ve yavaş yavaş... Gidenler var ömrümde,gidenler Sen ve senin gibil...', ARRAY['Türk Edebiyatı','Şiir','Hatice Korkmaz']::text[], 8.5, '{"poet":"Hatice Korkmaz","poet_slug":"hatice-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gidenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkularım Hayallerimdir', 'tutkularim-hayallerimdir-nergiz-kartal-ahrvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir uzun hayaldir  erişemediklerim

Bazen geçmişe dönen söz

bazen içimde  bir ürperti

bazen deli dolu coşar gönlüm

bazen tutsağı olurum nağmelerin

bilinmeyen şarkılarda

     

Bir uzun hayaldir özlemlerim

duvarda asılı resimim

bazen renkten renge  konan fırça

bazen fırçanın yarattığı  tebessümüm

benzeri bulunmayan

paletim ressamın sihirli parmağında

bir uzun hayaldir umutlarım

dize dize dökülürüm yapraklara

bazen fısıltı olurum sevgilinin dudağında

bazen hitabeyim

meydanlarda okunurum coşkunca

doğmamış  bebeğim

bir ozanın rüyasında

uzun bir hayaldir özgürlüğüm

bir tavşanın ürkek kaçışında

bazen su kenarında maralı ceylan

kanadı kırık kekliğim

hedefim yüreğimden vurulmaya hazır

tetiği çekilmiş tüfeğin namlusunda...

BİR UZUN HAYALDİR  ÖZLEMLERİM,ÖZGÜRLÜĞÜM

UMUTLARIM

UZUUUN BİR HAYAL ERİŞEMEDİĞİM TUTKULARIM.

                                          05.02.1991

                                         KURUCAŞİLE/BARTIN', 'Bir uzun hayaldir  erişemediklerim Bazen geçmişe dönen söz bazen içimde  bir ürperti bazen deli dolu coşar gönlüm bazen tutsağı olurum nağme...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tutkularim-hayallerimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Ülkesinde', 'yalnizliklar-ulkesinde-nergiz-kartal-a84w9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen hiç kendini aradınmı çaresiz

yüreğinde

nefesinde

yaşadınmı buruk bir yalnızlığı

kuşların çocukların sesinde

izledinmi günbatımını ufuklar boyu

Avcuna alıp bir gül yaprağını sevdinmi ?

sen hiç kuşlar gibi özgür oldun mu ?

ve özgür avcıların kurşunlarıyla

vuruldun mu?

yaşadınmı yaşamın güzelliğini

Başını bir taşa dayayıp

taşlaşmış yüreklerde yattınmı?

sevdin mi sevildin mi delicesine

aşk nemem şey

tattın mı?

sen hiç  kendini aradın mı çaresiz

Yalnızlıklar ülkesinde

      

                                              1988

                                            Kurucaşile', 'Sen hiç kendini aradınmı çaresiz yüreğinde nefesinde yaşadınmı buruk bir yalnızlığı kuşların çocukların sesinde izledinmi günbatımını ufukla...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizliklar-ulkesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dudak Bükümü', 'bir-dudak-bukumu-erol-ozkan-vd73j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçüktüm;

Sevmeyi,kuşların dallarda öpüşmelerinde gördüm.

Irmakların toprakla sevdasına,

Arının peteğiyle olan tutkusuna,

Hep uzaktan baktım,

Bir dudak bükümü ağlamaklı.

Büyürken;

Mecnunlar gördüm,

Aşk sağanağı altında yıkanmış.

Yalnızlıklar tanıdım.

Bir çift yürek olmuş sevdalara imrendim.

Dupduru bir denizin,sahile özlemini izledim,

Bir dudak bükümü ağlamaklı.

Büyüdüm;

Özümsenmiş mutluluk çığlıklarını işittim,

Yeryüzünün tüm nadide yanlarından.

Sarp bir kayada tek bir çiçek,

Sarmaş dolaş biribiriyle,

İmrendim.

Yağmurun hasretle toprağa dokunuşunu gördüm,

Bir dudak bükümü ağlamaklı.

İçime inen karanlık bir sevdanın,

Kanatlarını çırpıp,geçip gittiğini,

Yürek burkucu haykırışlarının çağrısını,

Sessizce dinledim,yapayalnız bir yerlerde.

Gözlerinin sesini isterdim,diye düşündüm,

İçime açlık veren dilenişlerimle.

Düşündüm;sevgi yoksunluğunun ne olduğunu,

Bir dudak bükümü ağlamaklı.

Birgün olur da,ben de sevmeyi yaşarsam,

Geleceğin pınarlarından yudumlarsam yaşamı,

Gülmeyi onuruma yedirir de,

Becerebilirsem ağlamayı,

Tüm mutlulukları ağırlayacağım yüreğimde,

Bir dudak bükümü ağlamaklı.

İç çekip solumaksa her yoksunluğu tatmak,

Ben varım buna,sen olmasanda.

Boyun eğip döneceğime tutkularıma,

Varıp anlatmayacaksamdüşlerimin yılgınlığını,

Seninle olamamaksa en kötü sonsuzluğum,

Cesurca haykıracağım yüreğimin sevdasını.

Yine de;uzaktan da olsa,seveceğim seni,

Bir dudak bükümü ağlamaklı.', 'Küçüktüm; Sevmeyi,kuşların dallarda öpüşmelerinde gördüm. Irmakların toprakla sevdasına, Arının peteğiyle olan tutkusuna, Hep uzaktan baktım...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-dudak-bukumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzin''in Gençlik Yılları', 'guzin-in-genclik-yillari-salah-birsel-bacy5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Güzin'' i düşünürken

Güzin'' in de düşündükleri vardı

İnce inceydi parmakları

Minnacık bir yüzü vardı

Güzin'' in aklında

Atlar arabalar

Daha başka erkekler

Başka hayatlar vardı

Güzin'' in kedileri vardı

Benim gibi okşanmak isteyen

Ama sevdanın adı geçsin

Güzin kaşlarını çatardı

Güzin masalların da Güzin'' i

Şehzadeler Güzin'' in şehzadeleri

Büyük bir defter tutar

Güzin'' in hayalleri

Ben odada otururken

Güzin'' in de oturduğu odalar vardı

Kendisine ait bir yatağı

Kendi uykuları vardı', 'Ben Güzin'' i düşünürken Güzin'' in de düşündükleri vardı İnce inceydi parmakları Minnacık bir yüzü vardı Güzin'' in aklında Atlar arabalar Dah...', ARRAY['Türk Edebiyatı','Şiir','Salah Birsel']::text[], 8.5, '{"poet":"Salah Birsel","poet_slug":"salah-birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guzin-in-genclik-yillari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacivat İle Kamber Hanım', 'hacivat-i-le-kamber-hanim-salah-birsel-kh3kn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin ortasında KAMER HANIM

Uykulardan uyku beğeniyor

Donmuş arkasını butun düşüncelere

Yatıyor

Hacivat ise bir minderceğizde

Yastıklar yastıklarla boğuşuyor

Ye sari Zadenin şarkısındaki gibi

Ömrüm seni sevmekle nihayet bulacaktır diyor

Ömrüm seni sevmekle nihayet bulacaktır diyor

Hacivat ateşler içinde

Ama pidelerine karsı memleketin

KAMER HANIM horluyor', 'Gecenin ortasında KAMER HANIM Uykulardan uyku beğeniyor Donmuş arkasını butun düşüncelere Yatıyor Hacivat ise bir minderceğizde Yastıklar ya...', ARRAY['Türk Edebiyatı','Şiir','Salah Birsel']::text[], 8.5, '{"poet":"Salah Birsel","poet_slug":"salah-birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hacivat-ile-kamber-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacivat''ın Karısı', 'hacivat-in-karisi-salah-birsel-wwxfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hacivat’ın karisi

incecikten yeldirmeli

Göz kaş oynatmalı

Gerdan kırmalı

Belden sarmalı

Gülmeli güldürmeli

Rakı süzmeli

Aşık üzmeli

Şiir süzmeli

Hacivat’ın karisi

Beyoğlu’nda gezmeli', 'Hacivat’ın karisi incecikten yeldirmeli Göz kaş oynatmalı Gerdan kırmalı Belden sarmalı Gülmeli güldürmeli Rakı süzmeli Aşık üzmeli Şiir süz...', ARRAY['Türk Edebiyatı','Şiir','Salah Birsel']::text[], 8.5, '{"poet":"Salah Birsel","poet_slug":"salah-birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hacivat-in-karisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçi Kapalı Balo', 'i-ci-kapali-balo-salah-birsel-9zqpo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ileri üç geri

Üç geri bir ileri

Otursan da kalksan da

Aklında bunu tutacaksın

Yasam bazlama süratlidir

Düşünce değiştirir bıkmadan

Siki durmazsan bastığına yapışmazsan

Seni olmayacak islerde çürütür

Niye kızdınsa dün

Buğun de ona kızacaksın

Şallak sulak giyinecek

Şallak sulak hoplayacaksın

Bir ileri üç geri

Üç geri bir ileri

Değişenlere değil

Değişmeyenlere koşacaksın', 'Bir ileri üç geri Üç geri bir ileri Otursan da kalksan da Aklında bunu tutacaksın Yasam bazlama süratlidir Düşünce değiştirir bıkmadan Siki ...', ARRAY['Türk Edebiyatı','Şiir','Salah Birsel']::text[], 8.5, '{"poet":"Salah Birsel","poet_slug":"salah-birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ici-kapali-balo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kamer Hanımın Bir Üzüntüsü', 'kamer-hanimin-bir-uzuntusu-salah-birsel-4fnca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ola ki bir gün size

Kamer Hanım derki ihtiyarladım ben

Çocuklarım oldu

Bir başka erkekten

Kaynar ayni gün patates

Mutfaktaki tencerede fıkır fıkır

Yumurcaklar basar yaygarayı

İç odadan

O gün üzmeyin Kamer Hanım''ı siz

Yok canim daha neler deyin

İnanmazsa bakarsa yüzünüze

Hacivat da ihtiyarlamıştır ya diye ekleyin', 'Ola ki bir gün size Kamer Hanım derki ihtiyarladım ben Çocuklarım oldu Bir başka erkekten Kaynar ayni gün patates Mutfaktaki tencerede fıkır...', ARRAY['Türk Edebiyatı','Şiir','Salah Birsel']::text[], 8.5, '{"poet":"Salah Birsel","poet_slug":"salah-birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kamer-hanimin-bir-uzuntusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Benzer', 'aska-benzer-sabahattin-kudret-aksal-mzlfx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşka benzer bir duygu uyanmaya görsün içimde

Dağılır gider kaygılarımın bulutu

Gözümde aranır tazelenir mavi

Kulaklarımda eski yolculuklardan bir uğultu

Donuverir söyle bir dünya, kayar yerinden ağaç

Sudaki çağrı ne havada bu ne koku böyle

Görünce alışkanlıkların tükendiği dostlukların da

Çıkıverdiğini çevremin ortaya bir başka kılıkla

Bir karıncalanmadır duyarım ayaklarımda

Elden geçirilmiş direkleri, yelkeni yeni

Yosunu alinmiş tekneler de böyle olur olursa

Çaresiz, artık kimse tutamaz beni

Evimmiş,isimmiş kentimmiş anlamam

Eşyasını dağıtıp yola düsen kişi örneği

Basar giderim bir bilinmedik yere doğru

Budur derim ne de olsa bu isin gereği

Bundan sonra bana artık yol görünsün

İster bir yeşil ağaçlık arasında

Bir toprak, ister susuzluktan çatlamış kıraç

Yüreği ışımışsa bir kez ne der görüntü adama

Yoldayım ya gene de gelmez aklıma

Bu deli tutku düşüme tez ulaşmak için mi

Belki de ereğim başka, bir güzel kaçmak

Neyin nesi bu olan biten bilmem ki

Gözümde arınır tazelenir mavi

Kulaklarımda eski yolculuklardan bir uğultu

Aşka benzer bir duygu uyanmaya görsün içimde

Dağılır gider tüm törelerin bulutu', 'Aşka benzer bir duygu uyanmaya görsün içimde Dağılır gider kaygılarımın bulutu Gözümde aranır tazelenir mavi Kulaklarımda eski yolculuklarda...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin-kudret-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aska-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Karşı', 'denize-karsi-sabahattin-kudret-aksal-goi34', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adam oturmuş denize karşı

Elinde oltası yıldız tutar

Çeker çıkarır bir bir geceden

Çeker çıkarır tadına bakar

Ardında ışık içinde çarşı

Bir kız geçer arkadaki yoldan

Bir eda bir çalım akça pakça

Ağzı yüzü bir delice türkü

Vurur kokusu uzaklaştıkça

Öyle bir dişi ki beter gerçekten

Dalmış gitmiş işine beriki

Vız gelir çarşı türkü vız gelir

Çocuksu bir bakış gözlerinde

Bir başına rıhtımda oturur

Ne geçer içinden bilinmez ki.', 'Adam oturmuş denize karşı Elinde oltası yıldız tutar Çeker çıkarır bir bir geceden Çeker çıkarır tadına bakar Ardında ışık içinde çarşı Bir ...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin-kudret-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/denize-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-talat-sait-halman-mbq83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi ayazmadan su içsem

Başında kaç batın

Susuzluktan ölmüştür

Irıpları çekmeyegör

Boğazda her balığa

Bir orospu gömülmüştür

Dinmişse

Saraylarda düğünler

Harem ağası gülmüştür

Yangın yerlerinde tekbir

Yoksulların

Canevinden dökülmüştür

İstanbul

Çağların görmekten korktuğu

Düştür', 'Hangi ayazmadan su içsem Başında kaç batın Susuzluktan ölmüştür Irıpları çekmeyegör Boğazda her balığa Bir orospu gömülmüştür Dinmişse Saray...', ARRAY['Türk Edebiyatı','Şiir','Talat Sait Halman']::text[], 8.5, '{"poet":"Talat Sait Halman","poet_slug":"talat-sait-halman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih-i Kadim', 'tarih-i-kadim-tevfik-fikret-firyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte, der, insanoğlunun geçmiş hayatı bu.

Ve başlar bize maval okumaya.

Ninniler uydurup uyutur bizi

dedelerimizin derin boşluklar içinde, uzun,

zifiri karanlık hayatından.

Gösterir bize evvel zamanı,

tek doğru, en güzel örnek, der.

Bakarsın gelecek günlerin farkı yok geçen geceden.

Senin tarih dediğin işte budur,

alnında altı bin yıllık buruşuklar

ve bir o kadar da kuşku.

Başı geçmişe bir düşe değer,

sürünür ayağı bomboş bir geleceğe,

bir deri bir kemik,

ayakta zorla durur.

Ben hiç tiksinmem ondan,

karşıma alırım onu arada bir,

anlat bakalım, derim, şu eskilerden.

Bir parça feylesofa benzer o,

bir parça sırtlana benzer,

berbat suratıyla da bir hortlağa.

Yoklar mezarını unutulmuş gecelerin,

başlar paslı, boğuk bir sesle

bir bir bana anlatmaya,

sırasıyle, ne olmuş ne bitmişse:

Hep yıkım üstüne yıkım,

acı üstüne acı! 

Ne vakit geçse anlı şanlı bir ordu,

çöküverir ağır gölgesi bir bulutun,

kanlar yağar dört bir yana.

En başta bir kanlı bayrak.

Kanlı bir taç gelir arkasından.

Sonra araçlar sökün eder kan içinde:

Balta, topuz, yay, kılıç, mızrak,

mancınık, top, tüfek, sapan.

Arada, kanlı komutanlar ve savaş birlikleri.

En son alay alay esirler geçer.

Yenen bir kişiye yenilen on kişi,

çiğneyen haklı, yiğnenen hapı yuttu.

Yıkımlara, acılara alkış tut,

yüksekten bakanlar önünde eğil,

insafla birdir aşşağılık ve namussuzluk,

doğruluk lafta, yürekte değil,

iyilik ayaklarda, kötülük kucaklarda.

Bir gerçek var, tek bir gerçek:

Eli kolu bağlayan zincir.

Bir tek şey var sözü geçen: yumruk.

Hak güçlünün, kötünün yanı.

Uzun lafın kısası:

Ezmeyen ezilir! 

Nerde bir şeref var, iğreti.

Nerde bir mutluluk var, yama.

Bir şeyin ne başına inan ne sonuna.

Din şehit ister, gökyüzü kurban.

Her yanda durmadan kan akacak,

durmadan her yanda kan! 

İşte böyle inler, sayıklar o,

anlatır insanoğlunun bu belalı ömrü

ne yolda, nasıl sürdüğünü.

Bakarım iskeletin kanlar köpürür dişlek ağzında.

Duyarım sesinin titreyen kuyusunda

yankısını korkunç bir iniltinin,

ben de başlarım birdenbire titremeye,

toprak da tiksintiyle titremiş gibi gelir bana.

Savaşın gürültüsü, patırtısı, indir artık

indir bu acıklı sahnenin perdesini! 

Dinsin sonu gelmeyen bu karışıklık! 

Sen de, gelenekçi iskelet,

yazdığın kara yazılara bir son ver,

aydınlığa susadık biz, aydınlığa susadık.

Uzun karanlıklar içinde uyumak isteyen mi var? 

Bizden iyi geceler onlara,

bizden onlara iyi uykular! 

Kimsin, ey gölge, kendinden geçmiş,

koşuyorsun karanlıklara doğru? 

Kanla oynamış gibisin,

kırmış geçirmişsin insanoğlunu.

Sen buna kahramanlık mı dedin? 

Onun kökü kan ve hayvanlık be? 

Şehirler çiğne, ordular dağıt,

kes, kopar, kır, sürükle,

ez, vur, yak ve yık.

Yalvarmalara yakarmalara boş ver,

gözyaşlarına iniltilere aldırma.

Ölümle, acıyla doldur geçtiğin yeri,

ne ekin ko, ne ot ko, ne yosun.

Sönsün evler, sürünsün insanlar orda burda,

kalmasın alt üst olmayan hiçbir yer,

mezar taşına dönsün her ocak,

damlar çöksün yetimlerin başına.

Bu ne alçaklık böyle bu ne namussuzluk! 

Hey bana bak, başbuğ musun ne? 

Yerin dibine bat, cakanla gösterişinle! 

Her başarı bir yıkım bir mezarlık,

işte bir yavrucak yatıyor şurda,

ey cihangir, onu gör de utan! 

Devril, bağımsızlığın eskimiş tahtı, devril,

nice acılar verdin bütün insanlara,

inim inim inlettin bütün insanları.

Parçalan, kararmış tac, tuz buz ol,

hep senin yüzünden yoksulluğu insanların.

Göz yaşından incilerin nerde hani? 

Nasıl da yosun tutmuşlar, bi görsen! 

Eski çağlar nasıl kanmış size? 

Ey kan içen kargalar,

bütün karanlıklar sizinle dolu! 

Artık yeter fikri susturduğunuz,

yerini hiç bir şey tutamaz bu dünyada

zincirsiz, kelepçesiz yaşamanın.

Hadi gidin tarih korusun sizi,

-haydutlara en iyi sığınaktır gece-,

gidin, yok olun siz de o mezarlıkta.

İşte müjdelerin en güzeli,

işte en gerçek özgürlük

düşümüzdeki gelecek çağlarda:

Ne savaş, ne savaşan, ne salgın,

ne saltanat, ne yoksulluk, ne ezen, ne ezilen,

ne yakınma, ne de zulmün kahrı,

ne tapılan, ne tapan,

ben benim, sen de sen! 

Ey soyulan iskelet, kimse bilmeyecek o zaman,

kimse bilmeyecek senin sayıp döktüklerini,

savaş ne, karışıklık ne, zafer ne, anlaşma ne? 

Belki duyulmadık bir öykü,

belki korkunç bir masal.

Çok sürmez köhne kitap,

fikri gömen sayfaların

bugün olmazsa yarın yırtılacak.

Ama kim yapacak dersin bu işi? 

Bu öyle büyük, öyle kocaman bir devrim ki,

hangi güç kalkar, ben yaparım der? 

Yerlerin ve göklerin sahibi mi? 

Tamam, işte oldu şimdi! 

Yeri göğü elinde tutan o kibirli,

o somurtkan ve dokunulmaz.

Bütün bu kavgalar onun yüzünden değil mi? 

Gökyüzü, sen söyle,

yüzyıllarca sel gibi akan su,

- şimdi esrik bir ağzın türküsü,

kuru sesi zindandaki bir adamın,

iç açan bir söz ya da yakan bir söz şimdi,

bir geniş "oh! ", bir derin "eyvah! ",

bir yakarış, bir övgü,

Şimdi tüy gibi bir rüzgar,

Şimdi ağzın bir kasırga.

Dokunaklı bir yakınma şimdi,

sabredemeyen bir başa kakma,

bir titreme, bir çan sesi,

bir savaş davulunun gümbürtüsü,

için için ağlamasi çaresizliğin,

kahrın iyilikbilir kişnemesi,

bir söylev, apaçık, gürül gürül,

Şimdi utangaç ve hasta bir yalvarış,

bir rahatlık bir iç sıkıntısı,

Şimdi korkunç bir haykırma -

bütün bu karman çorman gürültü patırtıyla

inleyen boş kubbe, sen söyle! 

Sen ki her sesi yankılayansın,

söyle, bu bir sürü boş çabalama içinde,

daha yukarlardaki şu tanrı katına

hangi sesin yankısı varabilmiş ki? 

Hangi dua kabul olmuş bugüne dek? 

Binlerim seni, göklerin tanrısı,

din ulularından dinlerim seni:

"Ne benzer var, ne noksanı,

canlı ve ölümsüz ve her şeye gücü yeten ve yüce.

Odur veren yiyeceği içeceği,

düşleri gerçek yapan o,

bilen, haberi olan, kahreden ve öç alan,

açık, kapalı her şeyi duyan ve anlayan,

el uzatan yoksullara ve çaresizlere,

her zaman her yerde bulunan ve her yeri gören..."

Seni böyle övüp duruyorlar işte.

Oysa senin en üstün özelliğin ne,

"Ortaksız" oluşun değil mi? 

Kaç ortağın var şu bataklıkta, bir bak.

Topu ölümsüz ve her şeye gücü yeten ve kahreden.

Ve topu ortaksız ve tek.

Ve topunun buyruğu yasağı ve saltanatı var,

ve topunun yukarlarda bir gökyüzü.

Bütün ordan gelir yüreğe doğan.

Topunun güneşi, ayı, yıldızları var,

ve topunun görünmez bir tanrısı.

Topunun adanan bir cenneti var,

ve topunun bir varlığı, bir yokluğu,

ve topunun saygıdeğer bir peygamberi.

Ve topunun cennetinde körpecik güzel kızlar yaşar.

Ve topunun cehenneminde birer lokmadır insancıklar.

Tanrılar ne derse onu yapacak halk,

sabırla ve kahırla olacak iki büklüm.

Ama tanrılar ne derse onu yapacak.

İnanasım gelmiyor bunların hiçbirine.

"Ne bileyim? " diyor kime sorsam.

Hepsi bir kuruntu mu bunların yoksa? 

Belki aldanmak yaşamanın bir gereği.

Belki de hepsi de doğrudur, kim bilir,

belki ben hiç bir şeyin farkında değilim,

karıştırmaktayım "yok" la "var" ı.

Kusurum ne? Kuşkuda olmak mı? 

Kuşku koşmaktır aydınlıklara doğru.

İnsan aklıdır eninde sonunda gerçeği bulacak olan.

Belki de yok olacağız bir gün topumuz birden.

Kimbilir, öbür dünya belki de var.

Madem bu beden o ölümsüzün işi,

ne diye kıvranır durur bin türlü dert içinde? 

Hadi diyelim aslımız toprak bizim,

sen gel onu kederden bir çamur yap.

- her yeri kanla, göz yaşıyla dolu -

insaf be, bu kadarı da olur mu? 

Sen gel hem yoktan var et,

sonra da ettiğini boz, kötüle.

Hiç bir yaradandan ummam bunu:

Yaradan yok eder, ama perişan etmez! 

En zorlu düşmanın işte, tanrı,

boğmak ister seni ulu katında,

çok iyi tanırsın sen o yılanı,

onun kızgın zehrinden bir vakitler bize

bir tadımlık vermiştin hani.

Kuşku! En zalim en güçlü düşman.

Bunu ya bildin ya koydun kafamıza,

ya da bilemedin işin nereye varacağını.

"şeytanlık, düzen, sapıklık" denen şey var ya,

bugün yerinden yurdundan edecek seni o.

Tapınağında ışıklarını söndürüyor,

elleriyle parçalıyor heykelini.

Sense, iler tutar yerin kalmamış,

göçüp gidiyorsun olanca gücünle.

Burçlarında yıkılmalar falan hani? 

Nerde hani gümbürtüsü yıldırımlarının? 

O kızgın soluğun hani nerde? 

Ne cehennemlerinde bir kaynama var? 

Ne büyük acını gören bir göz.

Ne de kulaklarda dokunaklı bir çınlama.

Oysa bir ufak parçası kopsa insanın,

bir sızlanma olur, duyulur bir ağlaşma.

Sen Yeryüzü ve Gökyüzü''nle göç gir de,

bir inilti bile duyulmasın ortalıkta.

Tam tersi, kahkahadan geçilmiyor.

Zaten yalana ağlasa ağlasa,

bir ikiyüzlüler ağlar,

bir de ahmaklar.', 'İşte, der, insanoğlunun geçmiş hayatı bu. Ve başlar bize maval okumaya. Ninniler uydurup uyutur bizi dedelerimizin derin boşluklar içinde, u...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":241,"source_url":"https://www.antoloji.com/tarih-i-kadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih-i Kadime Ek', 'tarih-i-kadime-ek-tevfik-fikret-lwd7g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Molla Sırat''a

Paraya hiç dayanmayan bir şairmişim

Zangoçluk edermişim Protestanlara gider

Size edebi saygılarımı sunarım efendim

Yani yıldızlı bir kursunun üstadına

Bilgin sairine yani İslam dininin

Molla Sırat hazretlerine yani

Lütfen bize ne güzel

Zangoçluğu yakıştırıvermişler

Ama aldanmış olmayasın sakin üstadım

Müslüman oğluyum ne de olsa

Sen o güzel dini anlatma bana

O dinden senin kadar ben de anlarım

Ben de okudum o Tanrı kitabini

Yüreğe doğan o sözleri ben de dinledim

Ben de dolaştım sizin gibi cami cami

Tanrı önünde ben de oldum iki kat

Açılırdı hayalimde cennet yolu

Dolardı yüreğime cehennem korkusu

Ulu Tuba''ya ben de tırmandım

Ben de çıktım melekler katına

Ezani duydum mu bayılırdım

Nasıl koşardım o ''Tanrı'' sesine!

Ben de tesbih çektim, dua ettim

Ben de namaz kildim oruç tuttum,

Hepsini yaptım halt ettim!

Çünkü ne dendiyse inanmıştım

Kanmıştım senin kandıklarına

Bağlanmıştım körü körüne

Canimi adamıştım dinime canimi.

Tanrıyı da sevmiştim peygamberi de.

Ama onlar bu gün çok uzaklarda

Anladım ben asil gerçek nerde

Anladım Hanya’yı konyayı

Bizi hakka götüren yol başka

Senin su saydıkların var ya hani

Su şaşılacak şeyler hani doğaüstü

Onlar hep masal hep kafadan atma

Buğun hiç durmadan arıyor insan

Gitgide görüyor isin içyüzünü de

Senin hokkabazlar unutmuşlar geleceği

Isa ile Musa, aldatılan ve aldatan

O büyülü değnek, bir koca kuyruklu yalan

İşte insanoğlu bir yerde böyle sapık

Beserin böyle delaletleri var

putunu kendi yapar kendi tapar

Git ara kiliseyi, dolaş Kabeci

Can sesini duy, tekbiri dinle

Umduğun, beklediğin şeyler nerde hani

Ortada bir tek şey göreme

Şeytani da düzme, Allah’ı gibi

Buda’sı düzme, Ehrimen''i düzme, Yezdan’ı düzmece

Bir korkak kuşku yaratmış bunların topunu

Gölgeler baktım, gölgeler, gölgeler...

Sonra baktım bir karanlık uçurum

Haydi don geri, don geri, don, oğlum!

Ve beynimden vurulmuş gibi devrildim.

Simdi benim ne cennet, ne cehennem umurumda

Bakarım evrene, şaşar şaşar kalırım.

Ne tapılan tanırım, ne taptıran tanırım

Yaradılışın kuluyum ben artık

Ben yaradılışın kulu

Pıtrak gibi işte gökyüzünde mescitler

İşte onlara orda vicdanim secde eder

İşte benim bundan böyle tapınmam bu

İşte bundan böyle benim vaktim böyle geçer

Artık öyle rahat, öyle rahat ki içim

Ayırt edemem kendimi bir kayadan

Tapınmakta biraz minnacık bir kuşla

Bir ishal kuşu da, la il ilahe illallah der

Ben de la ilahe illallah derim

Ve doğruluk ve alçak gönüllülük ve sıkı dostluk

Ve el uzatma ve koruma ve insaf ve acıma

Ve sonra bir şaire zangoç dememek

İşte buyuran bunlar benim vicdanıma

Benim ayinim düşünüp yapmaktır

Benim dinim insan gibi yaşamaktır

İnanmışım: Taparım ben varlığa

Her kanat bana bir melek sesi getirir

Ne isim var peygamberle benim

Beni Hakka bir örümcek oturur

Kitabim iste yeryüzü kitabi

Bendedir iyilik, kötülük tohumu

Varırım hep böyle ta mezara dek

Yeniden dirilmek bizim nemize gerek

Taşır insanların hem aşkını, hem acısını

Bağrımdaki su deli, su ince yürek

İnsan gibi yaşamaktır buğun gerçek din

İnsan gibi yaşamak', 'Molla Sırat''a Paraya hiç dayanmayan bir şairmişim Zangoçluk edermişim Protestanlara gider Size edebi saygılarımı sunarım efendim Yani yıldız...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/tarih-i-kadime-ek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıra göller', 'sira-goller-ulku-tamer-okga3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyaz ve mor haşhaşları havaya savurarak 

Yeni bir afyon bulacaksın kendine. 

İşte o zaman beni unutma, 

Şairini, onun şiir yazan ellerini, 

İçine dizilen sıra gölleri, 

Kendi kendine konuştuğun seni, 

Her şeyi, hiçbir şeyi unutma. 

Zakkumların arasından bir şehre gireceksin, 

Aşk şiirleri, tabiat şiirleri, tarih şiirleri düşünerek 

Bir dinamit yapacaksın kendine. 

Korkma, ateşle onu. 

Öldürecek nice balıklar vardır sularında, 

Patlamayla dirilecek nice balıklar vardır. 

İşte o zaman an beni, yaşa beni, 

İşte o zaman unutma beni. 

Hatırlanacak çok hüzünler bulacaksın, 

Onların tohumunu havaya savurarak 

Uzun bir yolculuk yaratacaksın kendine, 

Her şeyin, hiçbir şeyin yolculuğu. 

İşte o zaman an beni, yaşa beni, 

Kıyılarda bile boğulan seni, 

Bir saz kuşu olarak gezinen hayaletini, 

Çeliğinden kemik oyan gövdeni. 

İçinde bir kaçakçı yaşar senin, 

Kayıkla dolaşır göllerinde, 

Beynine tabanca ve şiir satar, 

O kaçakçının bakışını sakın unutma.', 'Beyaz ve mor haşhaşları havaya savurarak  Yeni bir afyon bulacaksın kendine.  İşte o zaman beni unutma,  Şairini, onun şiir yazan ellerini, ...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sira-goller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarla Kuşu', 'tarla-kusu-ulku-tamer-m1f08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüler geçiyor tarla kuşundan,

gagasından, kanatlarından,

tarlasından.

Düşünüyor tarla kuşu:

ölümü acaba bir tohum muydu?

Dalgalara tükürsen

bire bin verir deniz,

bu kan neleri çoğaltacak?', 'Ölüler geçiyor tarla kuşundan, gagasından, kanatlarından, tarlasından. Düşünüyor tarla kuşu: ölümü acaba bir tohum muydu? Dalgalara tükürsen...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tarla-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecede', 'gecede-ulku-tamer-5jmfe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kararmaya durdu mu ortalıklar

Büyük mor bir ışık yalın kat yüreğinde

Oysa birçokları yalnız gecede

Yasar en ışıksız yerini bölünerek

Unuttuğu bir şey vardır başkalarının

Oysa bir yerlerde hepsini duyar

Üşür gecelerden bir ince yürek

Ama dağ başında bir yalnız diken

Ama tepelerde iri bir rüzgar

Yasamazlar birçokları gecede

Karanlık gölgeler düşer yollara

Sonra geçip butun korkulardan, karanlıklardan

Yiğitçe karşı koyar da bir ince yürek

Yansıyan duru ışıklar gibi iyimserliği

Geçer uzak güneşlerden, sulardan', 'Kararmaya durdu mu ortalıklar Büyük mor bir ışık yalın kat yüreğinde Oysa birçokları yalnız gecede Yasar en ışıksız yerini bölünerek Unuttuğ...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney Çocuğu', 'guney-cocugu-ulku-uluirmak-uux4x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen güney çocuğusun

Senin o nar çiçeği sevgilerini bilirim

Sen umudum, özlemim, yosun kokulu sabahımsın

Sen o defne parlaklığı, zakkum acısı

O meltem nemi ellerinle

Bana bir Mersin aksamı yaşatırsın

Sen güney çocuğusun

Senin o limon sarisi özlemlerini bilirim.

Yeşil Göksu aydınlığı kadar severim seni

Tasucu''nda uzak, gölge gözlerini görürüm

Ak köpükler düşünde yanımdasın sevinirim.

Sen güney çocuğusun sevdiğim

Seni palmiyeler altında düşünürüm

Seni efkarlı aksamlar içinde düşünürüm

Sen güney çocuğusun sevdiğim

Ver bana gözlerinden güneyi artık

Ver bana o ellerindeki meltemleri

Yeter, birlikte yaşayalım efkarlı aksamları, gel

Limon çiçekleri sabrımı tüketiyor

Palmiyeler, ilik yollar, gözlerin

Gözlerinde Mersin aksamları sevdiğim.

Sen güney çocuğusun

Senin o nar çiçeği sevgilerini bilirim

Sen umudum, özlemim, yosun kokulu sabahımsın

Sen o defne parlaklığı, zakkum acısı

O meltem nemi ellerinle

Bana Mersin aksamlarını yaşatırsın.', 'Sen güney çocuğusun Senin o nar çiçeği sevgilerini bilirim Sen umudum, özlemim, yosun kokulu sabahımsın Sen o defne parlaklığı, zakkum acısı...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Uluırmak']::text[], 8.5, '{"poet":"Ülkü Uluırmak","poet_slug":"ulku-uluirmak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/guney-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cılız Haykırı', 'ciliz-haykiri-turkan-i-ldeniz-7hvgf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzatma ellerini sabahlara bir -gelemem

Gelemem ölesiye bakma gözlerime

Belli ki sensiz, seninle bitecek bu özlem

Belli ki sancılara uyanacak içimdeki bahar.

Durup seslenme düşünceme

Kapılara beş kilit birden vurdular

Işıkları söndürdüler karanlıktayım

Güçsüzüm -ağlamaklı- üstelik yalnızım

Örümcek ağlarıyla bağlandı ellerim

Dört duvarla çevrildi yörem

-Bana kalsa simdi gelirim-

Yollara pusu kurdular -bekleme

Bekleme sakin gelemem.

Su zilcileri bir kırabilsem

Parça parça edebilsem pencereleri

Belki kurtulurum.

Karsız yollarda belirmese izim

Kin saçan gözler kovalamasa peşimi

Yanında olurum

Sen’le olurum.

Uygar tutsaklığın bu en cılız haykırısında

Göz yaslarımın sıcağından donacak cehennem

Gerçek seviden...

Sana ulasan yollara

Bir avuç toz niyetine serpeceğim kendimi.

-Hayvanlardan utanacaklar-

Onların utançları da içleri gibi kara

Oysa ki sana ait hersek beyaz

Yine de uzatma ellerini sabahlara bir -gelemem

Gelemem öldüresiye tutma ellerimi.', 'Uzatma ellerini sabahlara bir -gelemem Gelemem ölesiye bakma gözlerime Belli ki sensiz, seninle bitecek bu özlem Belli ki sancılara uyanacak...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ciliz-haykiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-turkan-i-ldeniz-jcy2f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şayisini unuttuğum günlerce bekleyişten

ben yorgunum ruhtum taşları yorgun

arlarda gecen gemiler durmuyor bu limanda

duranlardan sen çıkmıyorsun.

Bil ki katıksız sancılara razıyım yokluğun olmasa

bil ki bir avuç biber gözlerime serpilen

Ellerimde soğumadı ellerinin izleri

durup şiirler yazıyorum yoluna.

İçimde sıkıntının en dayanılmaz sekli

kaçıncı kere saatleri susturuyorum

bensiz çözülüp, sensiz bağlanması yok mu balatlarin

Tükeniyorum.', 'Şayisini unuttuğum günlerce bekleyişten ben yorgunum ruhtum taşları yorgun arlarda gecen gemiler durmuyor bu limanda duranlardan sen çıkmıyo...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekleyis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecedir', 'gecedir-turkan-i-ldeniz-po3ke', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gecedir

durdum ortasında hüznün

yağmur mermi gibi iniyor sabrıma

bu dar havadan bıktım artık

yoluma mayın ekerek giden Aralık

yatmış pusuya

Ocak sapa kaldı

yamacından geçtim şubatın da

gecedir

yumruğum kendi avcuma

öylesine sürüldü ki yüreğim buzullara

öğrendim ateş yakmasını suda

o hırçın nehir

köprüleri yıkmış

bahar karsı kıyıda

gün olur bir şiir açar

gökyüzü büyür

tat gelir acıya.', 'gecedir durdum ortasında hüznün yağmur mermi gibi iniyor sabrıma bu dar havadan bıktım artık yoluma mayın ekerek giden Aralık yatmış pusuya ...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gecedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme Sakın Perişan Olacağım', 'gelme-sakin-perisan-olacagim-turkan-i-ldeniz-mk7aj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öfkemin gülleridir, yağmura döner yüzünü

küsüpp senin güneşine

İçilecek bir kadeh schnaps nü

yarim bıraktım

Gelme.

Gölgeni yıkma yoluma

bocalıyorum

Kasırgalar yaratma öyle çılgınca

Korkulu soluklarda geniş olmak kim

Yaşadıkça yaklaşırım sandım - oysa

suyun ateşle uyumsuzluğu gibisin

Kopabilir desem en ince yerinde

Geçmişe uyanan gözlerinin

Ateş gemilerini bir bu ürkütür

Simdi uzaktan gülüp geçtiğim

Simdi

uzaktan

gülüp geçtiğim

Ne mi çıkar güneş tutulmasından

Nasıl mi çocukluğum

Ben o zamanlar da böyle üşürdüm

Evlerde kati yönetimli kuklalar

çatışmalara hazırlar saygımı

Beklediğim günlere daha ne kadar

Anlatılmaz umutlara merhaba

Hatırlatma butun onları ve onları

Benzer benim çektiklerim

Peygamber Yusuf

Bir anda çağrışımlar yok edince zamanı

Uzaklaştıkça ölçülere vurması kolaylasan

Nasıl mi çocukluğum

Geçti mi çocukluğum

Çocukluğum mu - hiç yasamadığım

Bırakır her yerde kendini hüzne

Unutmak pazarında en pahalı

Buyruklar - buyruklar - buyruklar

buyruklar - itirazsız - hep bas uz re

Düşünmekti ezen gözlerimi yük

yanlıştı yanlış su benim korkularım

ürkerek birer mum gibi

yöresi sönük.

Ve bir gün

yürüdüğünü her şeyin

Ve bir gün

eh iste nasılsa

korkularımı bilinçle kovdum

Dur dediler dinlemedim

Koştum

İsyanım onlara oh ola.

Belki özüm orda diye

İlle de İstanbul dersen

Hırcın bir deniz bulacaksın kıyıda

Sonra çok bunalıma itecek seni

karanlığa kursunla yazılan teoriler

ve gölgelerin saygısız büyüklüğü

aslına oranla

Gerekirse açıp butun köprüleri

Yılma, yüklen şiirlere

Gücün Karmaca.

Kesin ayrılıklara yeni çiçek serpmek

en duygulu serüveni yasarken

güneşi güldürse de arada bir

buzulları çözmeye yetmez

Abusunu yüreğime akıtan askından

yeni kavuştum kendime

yine ayırma

Geçitlerde yol vermez yabanlar

Derim ki kimse aramadı böylesine

kendini bulmak için

benim kadar.

Benim kadar hiç kimse

öyle ülke ülke dolaşıp...

Uzun da olsa yollar ne çıkar

sabrımı almışım yedeğime

Ne çıkar uzatsa anılar

ahtapot kollarını

Varsayıp her şeyi hiçbir şeye

Giderim doğacak günlere.

Sen yine eskiden olduğu gibi

Zenci mızrakları havayı yırtarken

Tam tamına katıksız

Malraux''yu mu okuyorsun aksam üzerleri

Bağ bozumu türküler yakılan

o sancılı günlerinde dört mevsim

-Hayli yakın eskidikçe onlar bana-

Ateşleri yak da öyle oku

Çünkü fenerini elinden alıyorlar

Diyojenin.

Geciken bir şey var güz sularında

Bilmesem bahar belki diyeceğim

Artık hiç olmadık yerlerdeyim senden uzak

Söyleyemeden o çok ezberlediğimi

Düşüncenin yorulduğu yerden

Acıyla bıraktığım o köşeye

yeniden dönmek mi

İstemem bırak

- Çoğalan acılara yeni direnç nerede -

Öz şiirlerin Tanrısal havasında

Gelmesin eski aşklar

Yeni saltanatıyla.

Gelme sakin perişan olacağım.', 'Öfkemin gülleridir, yağmura döner yüzünü küsüpp senin güneşine İçilecek bir kadeh schnaps nü yarim bıraktım Gelme. Gölgeni yıkma yoluma boca...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/gelme-sakin-perisan-olacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumarbaz', 'kumarbaz-turkan-i-ldeniz-qfueo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bunlar benim sultan yıllarım

burcum böyle buyuruyor

yanıltmaya burcumu

çapraşık yollara dalıyorum kaybolmaya

bir anda

bulvara çıkıyorum

silah çekiyorum gözü kapalı

ilk atışta

on ikiden vuruyorum

yanıltmaya burcumu

ne denli yanlışa koşsam

doğrulara kavuşuyor

bunlar benim sultan yıllarım

burcum böyle buyuruyor

madem

bunlar benim sultan yıllarım

fırsat bu fırsattır deye

ben de tutar kumar oynarım

ben de tutar kumar oynarım

hem büyük kumar oynarım

gecenin birinden gülerek ötekine

çünkü

her keresinde elim güzeldir

hem çok gibisinden

iste bu yeşil çuhalı masa

şunlar da hızlı kumarbazlar sözüm ona

karsımda coşkudan donan

bense öyle rahat

gözlerimden kahkahalar fırlatıp

geleneksel çizgide ufluyorum sigaramdan

çünkü

sonucu başlamadan belli

bu oyun da benim yine

çünkü

kozlarım Nuri ve Kenan

ben ki Düzce’de eskittiğim on beş yılda

hiç kumara girmedim

kumar nedir bilmedim

kumar ve içki ve aşk

günahtır dediler öyle belledim

her ramazan hatim indirirdim

sahi ben hatim indirirdim her ramazan

yeşil örtüler içinde

sekiz oktavlık sesim vardı

uç uca sigaralarda kaplasam da bu gün

yine sekiz oktavlar sesim

ama

simdi görsem elifi tanımam

demek öğrenmeden ezberlemişim

sonra İstanbul

reklam afişleri denizi vitrinleriyle İstanbul

ah İstanbul sen eskiden fazla mi güzeldin ne

yas on beş saçlarım belimde

dar ilce yaşantısından

büyük kent özgürlüğüne

topkapı sarayı beylerbeyi yıldız

önce saraylardan başladım gezmeye

neden önce saraylardan derseniz

azim soyda çok saraylı vardı da

ondan derim

hele bir büyük halam Esmehan vardı ki

doksanında bile güzel Esmehan diye anılırdı

Çerkez Esmehan saraylı Esmehan güzel Esmehan

aslına hüzünlü bir kadındı

derdini salt bana anlatırdı

çocukluğuna benziyormuşum diye

kaderin benzemesin derdi

sandığını açar bana ipekliler verirdi

hemen lekelediğim yırttığım ipekliler

evet aslında hüzünlü bir kadındı

sandığını ver derdini salt bana acardı

saraydaki aşkını ve hüsranını

ona acır ve çok severdim

iste ondandır benim saraylara merakim

ve kinim

bu kinle girdim ilk kumara

ama ne zaman

nerde nasıl kiminle

oysa butun ilkler aklımda

örneğin şaraba Turgay’la

aşka Kaptanla girdiğim

ama ilk kumar

iste bunu hatırlamıyorum efendim

zaten hatırlamam pek de gerekli değildir sanırım

siz suresine ve sonuna bakin

her kumarda bu kinle orantılı buyur elim

ve rivayet ederler kim

on temmuzda Yenikoy''de

üttüğüm burjuva Bekir

kahrından ellerini biçtirmiştir

ben görmedim

evet beni hiç yenemezler

hangi oyuna girsem yenemezler

hile de katsalar yenemezler

hiç mi hiç yenemezler

eğleneyim diye söyle bazen

sıfıra indirgerim de kendimi

çoğalırım yenibaştan

ve hiç yenilmem

hep yenelim de hiç yenilmem

çünkü

kozlarım Nuri ve Kenan

siz Nuri’yi başka adla tanırsınız

yasak bir ozandır kendi şiirlerine

karanlığımı işitmek ilk özelliği

onuru alnında zambak

onarır ölümlü bile

güle benzetir bir gülleyi

yüreğini koyar da ortaya

mermi gibi barut atar

kenan

yüzünde sergiler hüznünü neşesini

Kenya''da konakladı on yıl

on yıl sürgün yaşadı gözlerimden

eski zaman aşımından uzak

kenan

şifreleri çözen anahtar

uğruma yıkınca butun geçmişini

simdi siki esrar sarar

ve beni hiç yenemezler

hangi oyuna girsem yenemezler

oyun hileli de olsa yenemezler

burcum böyle buyuruyor

bunlar benim sultan yıllarım

çünkü

yıldızım çok köşeli

ve aydın

salt

öz yenilgiden sakınırım.', 'bunlar benim sultan yıllarım burcum böyle buyuruyor yanıltmaya burcumu çapraşık yollara dalıyorum kaybolmaya bir anda bulvara çıkıyorum sila...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":129,"source_url":"https://www.antoloji.com/kumarbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdik İnsanı Halk', 'sevdik-i-nsani-halk-turkan-i-ldeniz-8unit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin en eski sabah belki

belki o uzak deniz...

ilk tarihe dikip taç beyti

yürüdük kaç ışık yılı seninle biz.

Bazen mühür bastık yıldızlara -dikey koşarak-

bazen çekti ilgimizi dip sulardaki giz

ATLANTIS.

Dağlar taşlar tanıktır, gökyüzü tanık

bir ünledik mi sekiz oktavı kırardı marsımız

uzanırdı sonsuza

ama

bazen ağıt olduk kendimize

sessiz.

Sevdik insani halk halk -beyaz, kara, kızıl, sari-

sevdik insan için olanı.

Toprağa saban, mermere can

çizgiye harf, çizgiye şayi kimliği kazandıran

insani sevdik.

Sevdik:

-Sizindir kara, hava, deniz

sizedir bu taşıtlar

özgürce geziniz.

-Ben geceyi gün eylerim

buydun elektriğiniz.

-''Olmaya, devlet cihanda...''

röntgen, lazer, x

asılar, ilaçlar elinizin altında.

-Ve siz konusun diyedir telefon

dünyanın obur yakasıyla

bakin ne rahat sığdı, tüm dünya

odanıza, televizyonla. -

diyen insani ve nice dahalar

nice dehaları sevdik.

Sevdik aşkla -kutsadık tapmadan da öte.

Ama

sevmedik asla savaşları silahları.

Simdi sen boynun büküp, soru oluyorsun ya

tartışmaya kapalı konularda

yoktur soruların önemi;

suyu sahraya, güneşi zindanlara sorma.

Sorma kula kul olmak hangi kitapta.

Evrensel erdemi biçimlerken kalem

ilmi zulme, zulmü ilme sorma.

Sen Diyojen değilsin, bırak elindeki feneri

sorma

yozluğa, yolsuzluğa, yobazlığa bu vize nemden

umudu sor bana

yeniden.

Gözlerin en eski sabah belki

belki o uzak deniz...Biz yorulmak bilmeyiz

bilmeyiz yorulmak biz

yine insana

yeni insana

Gideriz', 'Gözlerin en eski sabah belki belki o uzak deniz... ilk tarihe dikip taç beyti yürüdük kaç ışık yılı seninle biz. Bazen mühür bastık yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sevdik-insani-halk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihin Satırbaşı', 'tarihin-satirbasi-turkan-i-ldeniz-nipeh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çarmıhını sırtlanıp nereye böyle uzak

dağın ardı kum denizi

her kum dibi - bin tuzak.

Acın yere göğe sığmaz

nasıl taşıdın nasıl, kaç binler yıl, kaç halk

daha kaç binlere kaç devama.

yorgunsun, gitme, dinlen biraz

bak kurtlar kan uluyor, kan soluyor

ve ağını geriyor her yana aksam

çoktan kanat kapari, sabra durdu güvercin

otur söyle, acelen ne dinlen biraz

sofrada değil pusuda beklenensin

Ben senden çok gitmeyi...

*

-Kılavuz kuşlar bos dondu gene-

Buraların yağmuru kumdur, kum yağar geceyle

bense güneş saati kurarım, direnç döverim örste

bu direnci sana hazırladım milat öncesi

üstünde durur hala çekiç sesleri

-Kılavuz kuşlar boş döndü gene-

*

Özlediğin sularda ben çok gezindim

inci, ipek ve zencefil taşırdı, bindiğim kalyonlar benim

fırtına yoktu, korsanlar yoktu, yoktu korku

o zamanlar o sulardan Poseidon sorumluydu.

hangi limana varsak orda ilkbahar

zaten o sularda her mevsim sanki ilkbahar

her liman bir bayramdı, bir büyük şölen

o bayramları aşkları su papirüse çizdim.

-baktığın yöne göre değişir

bir yani ikindi, obur yani şafaktır o resmin.-

simdi nemde o kalyonlar, nereye kayboldular

duru sulara ne oldu, öyle gün günden

neden sarardılar, neden karardılar.

*

Ben senden çok gitmeyim.

Hem sonra evlere dolan ezgiler vardı

sabah rengiyle, hani o esintiyle

la minör, fa diyez, si bemol un an hası

coşkuyla uçardı ya, kaplardı ya odaları

hani yolları, bulvarları, baştanbaşa havayı

onlar nemde simdi, o ezgiler nemde

nemde yağmur ormanları

onları da çektiler giyotine.

Ben senden çok gitmeyim.

*

Dirimin serüveni kişiye özel derlerse de inanmam

arada kol vurup tarihin satırbaşına

mağara, çivi, hiyeroglif, tas kabartma, matbaa

birer sayfa acarım da, her cağdan her boylamdan

hersinde ortak payda

ateş, barut, kan.

Ben senden çok gitmeyim.

*

Ey kaostan bu yana odağında yandığımız cehennem

akkor olduğumuz malum

malum

haddeden geçtiğimiz, gen

nice kurudu sular - varmadan okyanusa

insanin insana kıyımı, insanin doğaya

köle pazarları, sömürge halklar, açlık Afrika

altın, petrol, uranyum, dolar

cıvalı zar, hileli kumar

daha kaç acı nemde büyüyor

ağı sevmiyorum çocuklar uçurtma koşsunlar.

Çocuklar uçurtma koşsunlar - gökyüzüne vursun iş düzümleri

sen çarmıhından çık, giy şu direnci

yine gitmek ilk dersen, peki nereye?

En yetkin ülke yüreği değil mi.', 'Çarmıhını sırtlanıp nereye böyle uzak dağın ardı kum denizi her kum dibi - bin tuzak. Acın yere göğe sığmaz nasıl taşıdın nasıl, kaç binler ...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/tarihin-satirbasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlık Çoğunluktadır', 'aclik-cogunluktadir-turgut-uyar-0d7d8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gulu çiğdemi filan bırak

Sardunyayı karidesi filan bırak

Acıyı ve ölümleri bırak

Oy pusulalarını ve seçimleri bırak

Evet

Seçimleri özellikle bırak

Çünkü açlık çoğunluktadır

Her kişinin ukala ömrü

Yeter sanılır çiçeklenmeye

Ve dünyanın karanlığından

Bir aşk bahanesiyle kurtulmaya

Kaçıp giden baharların anisi

Elden ele devredilen bir gençlik duygusu

Laleler sümbüller butun obur boklar püsürler

Hakkim var midir bunları söylemeye

- vardır

Güneş doğarken ve batarken

Yazdan kısa girerken ve kıştan çıkarken

Ve dağda ve kırda

Hakkim vardır -

Çünkü en azından dünyadan

Döl
..........
..........', 'Gulu çiğdemi filan bırak Sardunyayı karidesi filan bırak Acıyı ve ölümleri bırak Oy pusulalarını ve seçimleri bırak Evet Seçimleri özellikle...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aclik-cogunluktadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı Bekleyene', 'bahari-bekleyene-turgut-uyar-4whra', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben kışın güzelliğini söylerim ne gelirse dilime

çünkü kış bir hazırlıktır soluğuma kıpkırmızı gülüme

nice kırmızı ayaklar gelip geçti o gün katar katar

kış günleri sözgelişi ben bir çöp bile almadım elime

altı kız bir ay ışığı def çalıp şarkılar söylediler

beri yanda ormanlar yanardı, ciğerparele
..........
..........', 'ben kışın güzelliğini söylerim ne gelirse dilime çünkü kış bir hazırlıktır soluğuma kıpkırmızı gülüme nice kırmızı ayaklar gelip geçti o gün...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahari-bekleyene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızla Gelişecek Kalbimiz', 'hizla-gelisecek-kalbimiz-turgut-uyar-qfj7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hızla gelişecek kalbimiz

kalbimiz hızla.

sürgünlerin umutsuzluğunda

kırık kalpler, yaralılar, onulmazlar

farksız çarpanların umutsuzluğunda

ve köprü başlarının umutsuzluğunda

ve köprü başlarının umudunda.

sular bitse bile, çiçekler atılırken oralara

temiz bir ilişkinin bulutsuzluğunda

ve eski dağlarda, eski dağlarda kış

kovalarken ülkesini

hızla gelişecek kalbimiz.

kendi öz hüznümüzün öz tarlasında

bozkır dayanıklılığımızın tarlasında

kalbimiz

ellerimiz ayaklarımız arasında

ve kimsenin bölemediği şarkıyı

güllerin, buğdayların ve acı
..........
..........', 'hızla gelişecek kalbimiz kalbimiz hızla. sürgünlerin umutsuzluğunda kırık kalpler, yaralılar, onulmazlar farksız çarpanların umutsuzluğunda ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hizla-gelisecek-kalbimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Çeltiklere', 'islak-celtiklere-turgut-uyar-m9bbi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benim bir sevincim var yüzün artık akşam

bir çocuğun gülüşünü görüyorsun nereye baksam

kıyımız uzak ve kuytuda ellerimiz sanki yok

ellerimiz yok ama senin elleri
..........
..........', 'benim bir sevincim var yüzün artık akşam bir çocuğun gülüşünü görüyorsun nereye baksam kıyımız uzak ve kuytuda ellerimiz sanki yok ellerimiz...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/islak-celtiklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye’m', 'turkiye-m-turgut-uyar-nx5rw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni boydan boya sevmişim,

Ta Kars''a kadar Edirne''den.

Toprağını, taşını, dağlarını

Fırsat buldukça övmüşüm.

Sen vatanımsın, ekmeğimsin

Duyduğum, bildiğim zafersin yıllarca.

Zonguldak''ta 63 numara

Nazlı sahiller Akdeniz''de.

Sevdasın ciğerlerimde parça parça

Yarı kalmış
..........
..........', 'Seni boydan boya sevmişim, Ta Kars''a kadar Edirne''den. Toprağını, taşını, dağlarını Fırsat buldukça övmüşüm. Sen vatanımsın, ekmeğimsin Duyd...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkiye-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert', 'dert-sair-ergenekon-yztl9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dert değil, bakma arkana, hadi git artık!

gözüm görmesin seni, yeter rahat bırak beni!

vallaha anmayacağım adını, sormayacağım seni

dert değil, haydi git artık

hatırlamam bile seni bir saat sonra, sen de kimsin be!

bulunmaz elmas mı sandın kendini?

ciddiyim sorun değil, yeter git artık...

.............

dur gitme, yalandı hepsi...

yanımdayken özlüyordum seni,

lütfen kal yanımda, gitme son bir kez bak bana

dert değil, gözlerin baksın yeter bana!

06:21 08-08-2000

alaybey-izmir', 'dert değil, bakma arkana, hadi git artık! gözüm görmesin seni, yeter rahat bırak beni! vallaha anmayacağım adını, sormayacağım seni dert değ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ergenekon']::text[], 8.5, '{"poet":"Şair Ergenekon","poet_slug":"sair-ergenekon","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-sair-ergenekon-cv16m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birgün aşık olur da bir başkasına,

aklına gelirsem onun elini tutarken

sakın, sakın beni düşünme ve hiç sorma niye diye

kalbin sakın çarpmasın hızlı hızlı

yanındakine sakın belli etme beni düşündüğünü

ve sakın eve gidince resmime bakma

arkadaşlarıma sakın sorma o nerede diye

eğer duyarsam beni aradığını, daha da uzaklara giderim buralardan

beni bulamayacağın yere kadar giderim inan buna

inan bana ve inan bu söylediklerime ki seni hiç sevmedim zaten

hep seninle oynadım her gün birlikte iken

kuruyan yapraklar gibi sarardım senden sonra

sakın zannetme sen yaptın bunları bana

hasta oldum

ablam sigaradan dedi

ama ben sigara dahi içmedim hayatım boyunca

tek zehir aldım

o da sendin hayatımı mahveden, hayatıma giren........

02:26 08-08-2000

alaybey-izmir', 'birgün aşık olur da bir başkasına, aklına gelirsem onun elini tutarken sakın, sakın beni düşünme ve hiç sorma niye diye kalbin sakın çarpmas...', ARRAY['Türk Edebiyatı','Şiir','Şair Ergenekon']::text[], 8.5, '{"poet":"Şair Ergenekon","poet_slug":"sair-ergenekon","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sakin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Topraklar', 'yorgun-topraklar-nergiz-kartal-uaz5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Garibim toprak ana

sayısız ırgata,sayısız kazma

çapalar karnını

deşer mi deşer

kan akıtırcasına

binlerce tohum serper üzerine 

nasırlı eller

bağır ne olursun

her tohuma yüzlerce tohum ister 

yorulursun

garibim toprak ana

sayısız ırgata,sayısız kürek

oyar karnını düşünmeden

atar seni bir yandan bir yana 

öbek öbek...

can alırcasına,acımasızca

bağır çağır

olurya duyulursun

susma ne olur

yoksa bir beton yığını altında

kaybolursun', 'Garibim toprak ana sayısız ırgata,sayısız kazma çapalar karnını deşer mi deşer kan akıtırcasına binlerce tohum serper üzerine  nasırlı eller...', ARRAY['Türk Edebiyatı','Şiir','Nergiz Kartal']::text[], 8.5, '{"poet":"Nergiz Kartal","poet_slug":"nergiz-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yorgun-topraklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnhisar', 'i-nhisar-murat-kilic-m5bd9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kutsal görevimi yapmış olduğum güze İlçeye

Bu güzel yere İnhisar derler

Yazın bol bol meyvesin yerler

İlçe girişinde var Jandarması

İşte bizim mekan da orası

Bu ellerde dağlar birazcık boldur

Kenarından geçen bozuk bir yoldur

Bir de nehri var adı Sakarya

Tepeler arasından nazlı nazlı akarya

Kışı hafiftir çamuru balçık

Gel de bu işin içinden sen çık

Yollar kıvrım kıvrım çıkar dağlara

Dağlar üzerinde nefis yaylalara

Koyunlu Söğüt yolunda

Deliler pek meşhurdur onda

İnsanları pek cana yakın

İnhisara gelirler akın akın

Meşhurdur Samrı köyün yaylası

Hele birde yayladaki havası

Kara kara dutları var bal gibi

Kaysıları iri iri nar gibi

Hisarcık yolu çamurlu ve taşlıdır

İnsanları genellikle yaşlıdır

Kışın kapanınca kardan yolları

Kara bir düşünce alır insanları

Tarpak''tır bu ilçenin beldesi

İlçedeki ahalinin gözdesi

Narı boldur birazcıkta inciri

Gel de terket sen bu güzel yeri

Sakarya kenarında var gazinosu

Sarhoş eder insanı o pis kokusu

Her akşam kavga çıkar gazinoda

Jandarmalar yetişir hemen imdada

Çayköy dediğin Sakarya kenarında

Bir kız gördüm şu çayköy''ün yolunda

Nazlı nazlı akar iken sakarya

Gözlüyordu sevdiğini elindeki çapayla

Biraz ilerideki köy Tozmandır

En meşhur şeyi ise kirazdır

Ortasından geçer koca bir kanal

Lakin insanları bakar hep aval aval

Muratça köyü en güzel yerde

Yalnız insanları çok azdır köyde

Havası tertemiz kokar mis gibi

Zenginleri köye biraz küs gibi

Harmanköy yolun sonunda

Ne güzellikler var bir bilsen onda

Yaz gelince biraz maden ararlar

Kış gelince kahvelere dolarlar 

                                                          29.02.2000

                                                          İnhisar', 'Kutsal görevimi yapmış olduğum güze İlçeye Bu güzel yere İnhisar derler Yazın bol bol meyvesin yerler İlçe girişinde var Jandarması İşte biz...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç']::text[], 8.5, '{"poet":"Murat Kılıç","poet_slug":"murat-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/inhisar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüme', 'kara-gozlume-murat-kilic-kxo28', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bir günüm 

Geçmiyor bu günüm dünüm

Sensiz geçen akşamlarda

Sanki ben bir ölüyüm

Sen benim kara bahtım

Kara gecelerde yeminim ahtım

Sen olmazsan ben neyleyim

Dünyada malım,mülküm,tahtım

Sensiz gecelerim dolu işkence

Hele birde aklıma sen gelince

Çıldırayımmı bilmem senin için

Kabuslarla dolu bu gecede

Kara gözlüm sabreylersen bu da biter

Selvi boylum elbet birgün bu da geçer

Sırma saçlım,sürme gözlüm,al yazmalım

Elbet birgün bu hasret bizim için biter

                                                      25.02.2000

                                                      İnhisar', 'Yine sensiz bir günüm  Geçmiyor bu günüm dünüm Sensiz geçen akşamlarda Sanki ben bir ölüyüm Sen benim kara bahtım Kara gecelerde yeminim aht...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç']::text[], 8.5, '{"poet":"Murat Kılıç","poet_slug":"murat-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-gozlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RÜYALAR', 'ruyalar-i-hsan-murat-epe0p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'RÜYALAR

Rüyalar uyandı yollar üzerinde

Bulutları aşıp

Yeşil bahçelerden bir demet çiçekle

Arzu sofralarına uğrayıp

Boğazda düğümledi

En güzel meyveleri

Sarışın kızları uyandırıp

Gerdanlarına

Bir tutam kekik kokusuyla

Erkenden gelip

Şehvetten önce inkisarla

Ve sabah geldi çiğselerle

Her tadın üzerine

Hasret ateşiyle

Ay yüzlü sevdaya

Rüyalar geldi yine

Yeniden hayata

Tatlı ölümden sonra

Saçlarımın hizasına

Hayallerimi süsleyen

Beyaz gelinlikli

Çingene kızıyla

Esmer güzelinden

kuytu gölgelere

Geceyi bırakıp

Gündüze yağdı

Dün gece gördüğüm

Ölüm rüyası                      10/07/2000', 'RÜYALAR Rüyalar uyandı yollar üzerinde Bulutları aşıp Yeşil bahçelerden bir demet çiçekle Arzu sofralarına uğrayıp Boğazda düğümledi En güze...', ARRAY['Türk Edebiyatı','Şiir','İhsan Murat']::text[], 8.5, '{"poet":"İhsan Murat","poet_slug":"i-hsan-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruyalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Rüzgar', 'aglayan-ruzgar-tamer-uzun-0bb1x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '13.07.2000    

   Pınar Ablam''a işafen...

 Havada ağlayan bir rüzgar...

Belli, mevsimlerden sonbahar !

Son yemişlerleriyle beli bükülmüş dallar

Sökün etmede buradan da kuşlar.

Göğün yüzünde buruk tebessüm, bir ar...

Gül ne olur ! üzül''cek, ne var ?

Sonbahar; döner döner, olur ilkbahar

Kavuşur bir bir yuvalarına kuşlar !', '13.07.2000        Pınar Ablam''a işafen...  Havada ağlayan bir rüzgar... Belli, mevsimlerden sonbahar ! Son yemişlerleriyle beli bükülmüş dal...', ARRAY['Türk Edebiyatı','Şiir','Tamer Uzun']::text[], 8.5, '{"poet":"Tamer Uzun","poet_slug":"tamer-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglayan-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Dursun', 'birak-dursun-ali-condal-tygvk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümde yaktığın o kor ateşi

Söndürme ne olur yansın tutuşsun

Bizim sevgimiz bir mevsimlik mi

Bıkrakta kalbimde bir ömür dursun

Sana verdiğim o güller aşkına

Peşinden geldiğim yollar aşkına

Sevipte demeyen diller aşkına

Bırakta sevgimiz kalbimde dursun

Gitsende gönlümde kalacak sevgin

Sen duymasan bile dilimde ismin

Hani gönderdiğin o küçük resmin

Bırak cüzdanımda benimle dursun', 'Gönlümde yaktığın o kor ateşi Söndürme ne olur yansın tutuşsun Bizim sevgimiz bir mevsimlik mi Bıkrakta kalbimde bir ömür dursun Sana verdiğ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birak-dursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Telim', 'gonul-telim-ali-condal-zf1q0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nağme arama sakın gönül telimde

Kırıldı artık, o çalmıyor sana

Bir gülüşe hasret bıraktın onu

Tebessüm arama,gülmüyor sana

Hüzün çalıyor artık notalarında

Kuruldu sevdası ilkbaharında

Ayrılık gizliyor gözyaşlarında

Kırdın gönül telimi çalmıyor sana

Mutluluk eserdi nağmalerinde

Kalemde tükendi yazmıyor sana

Sevgiye susamış bomboş elleri

Ne kadar uzansa ermiyor sana', 'Nağme arama sakın gönül telimde Kırıldı artık, o çalmıyor sana Bir gülüşe hasret bıraktın onu Tebessüm arama,gülmüyor sana Hüzün çalıyor art...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-telim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim Sana', 'siirlerim-sana-ali-condal-gms4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazsam sana

Seninle başlasa

Seninle bitse tüm heceleri

Kızar mısın bana

...

Yada bir şarkı söylesem

Aşk dolu, sevgi dolu bir şarkı

Seninle başlasa

Seninle bitse tüm nağmeleri

Kızar mısın?

...

Seni sevdiğimi söylesem

Aşık olduğumu 

Tutkunluğumu haykırsam

İnanır mısın bana

Yoksa

Gülüp geçer misin

Kızar mısın yoksa bana

...

Dizlerine kapansam

Ağlasam

Göz pınarlarım kuruyana kadar ağlasam

Hiddetle bağırır mısın?

Kızar mısın bana?

Yoksa koşup sarılır mısın boynuma

Artık anla be gülüm

Aşığım sana', 'Bir şiir yazsam sana Seninle başlasa Seninle bitse tüm heceleri Kızar mısın bana ... Yada bir şarkı söylesem Aşk dolu, sevgi dolu bir şarkı ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/siirlerim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi Boylum', 'selvi-boylum-ali-condal-d11tz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saç bağın çözülmüş

zülüfleri yüzünde

ağlamışsın yaş kurumuş gözünde

Özledim ben uyumayı dizinde

selvi boylum şimdi kime yar olmuş

siyah saçlarına aklar mı dolmuş

Bir fidandım 

dallarımı kırdılar

Gonca idim bağımı kuruttular

Yüreğimi un edip öğüttüler

Selvi boylum şimdi kime yar olmuş

Siyah saçlarına aklar mı dolmuş

saklama gül yüzünü

Bir kerecik göreyim

iste benden yollarına öleyim

Yüce tanrım odur senden dileğim

Selvi boylum şimdi kime yar olmuş

Siyah saçlarına aklar mı dolmuş

Beden yorgun

Taşıyamaz bu derdi

Mevlam bana dert üstüne dert verdi

Ben sevdimde yine elleri gördü

Selvi boylum şimdi kime yar olmuş

Siyah saçlarına aklar mı dolmuş.', 'Saç bağın çözülmüş zülüfleri yüzünde ağlamışsın yaş kurumuş gözünde Özledim ben uyumayı dizinde selvi boylum şimdi kime yar olmuş siyah saçl...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/selvi-boylum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Be Gülüm', 'kal-be-gulum-ali-condal-kyfj4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kal be gülüm 

Şuracıkta otururum ben

Dizinin dibinde hemen

Yeter ki rahatsız olma 

Yeter ki gitme yanımdan sen

Başkası seni anlayamaz ki benim gibi

Söz veriyorum kazan dibi ısmarlarım sana

Vallahi hesaplar benden

Elini tutarım kızılayda dolaşırken

Yine şiirler yazarım sana

Kırmızı güller alırım

Ne olur 

Kal be gülüm

Ben dayanamam ayrılık sahnesine

Yeter artık 

Tam burada kapansın perde

Burayı seyrettirme bana

Ağlarım...

Bırak bu erkekler ağlamaz edebiyatını

Bizimki de yürek be kızım

Yangın düşmeye görsün haneye

Bak ağlarmıyım 

Ağlamazmıyım

Nisan bir şakası de

Seni sınadım de yada

Yine boynuma sarıl

Öp beni uzun uzadıya

Yada al şu silahı 

Daya anlıma

Çek tetiği

Bir damla kanım akmaz

Ölüm senden olursa

Yürü cesedimin üstünde

Kızarsam nağmerdim 

Yeter ki gitme

Kal benimle

Kal be gülüm

Gidersen yaşayamam

Ölürüm....', 'Kal be gülüm  Şuracıkta otururum ben Dizinin dibinde hemen Yeter ki rahatsız olma  Yeter ki gitme yanımdan sen Başkası seni anlayamaz ki ben...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kal-be-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Oldu Yarim', 'el-oldu-yarim-ali-condal-pe8fn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar mı yağmış Kırıkhan ın düzüne

Rastlamadım nazlı yarin izine

Doyasıya bakamadan gözüne

Gitti gelmez, el oldu nazlı yarim

Gözyaşımı siler diye beklerim

Dertlerime yeni dertler eklerim

Sensiz yanar, sönmez ki şu yüreğim

Gitti gelmez el oldu nazlı yarim

Nazlı yarim, gonca gülüm nerdesin

Günler geçmez, uyku haram bilesin

Beklerim ki, bir gün çıkıp gelesin

Gitti gelmez, el oldu nazlı yarim.', 'Kar mı yağmış Kırıkhan ın düzüne Rastlamadım nazlı yarin izine Doyasıya bakamadan gözüne Gitti gelmez, el oldu nazlı yarim Gözyaşımı siler d...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/el-oldu-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerin Dolmuyor,', 'yerin-dolmuyor-ali-condal-xgj8n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretin içime sindi desemde

İnanma birtanem sensiz olmuyor

Nice sevdalara taht olsa gönlüm

Senin sevgin başka, yerin dolmuyor

Gönlümü kapattım tüm sevdalara

Çiçekler açmıyor hasret bahara

Sevdam kara kışta gönlüm ayazda

Senin sevgin başka yerin dolmuyor

Gözlerim yaşlara pınar olsada

Saçlarıma her gün karlar yağsada

Yüreğim hasretten kan ağlasada

Senin sevgin başka yerin dolmuyor.', 'Hasretin içime sindi desemde İnanma birtanem sensiz olmuyor Nice sevdalara taht olsa gönlüm Senin sevgin başka, yerin dolmuyor Gönlümü kapat...', ARRAY['Türk Edebiyatı','Şiir','Ali Çondal']::text[], 8.5, '{"poet":"Ali Çondal","poet_slug":"ali-condal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yerin-dolmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yalnızlık', 'yalnizlik-son-sevda-h6ld8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerdesin

Nasılsın Kimbilir

Yine Güzelmisin;Bıraktığım Gibi

Bu Yalnızlığı Sende Duyuyormusun

Ta İçinde Zehir Gibi

Zıkkım Gibi', 'Nerdesin Nasılsın Kimbilir Yine Güzelmisin;Bıraktığım Gibi Bu Yalnızlığı Sende Duyuyormusun Ta İçinde Zehir Gibi Zıkkım Gibi...', ARRAY['Türk Edebiyatı','Şiir','Son Sevda']::text[], 8.5, '{"poet":"Son Sevda","poet_slug":"son-sevda","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgide Kısa Devreli', 'sevgide-kisa-devreli-baris-toptas-g4m32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki -ya da üç- düşten ibaretti,ıssızlığa bulanık, 

Koyu bir ruha uyumlu artık,adresleri saklı... 

Donuk bir bakışa heves etmiş,güneylerden habersiz, 

Muğlak seyirleri üzerine şehrin,bana gösterdiğin! 

Hala farkında olmadığın,dalgalanmalardı duyumlarda, 

Farketmezdi senin için,farketmeksizin düşlediğinden... 

Sana dair demiştim,İstanbul üzerine alınmış(!), 

Şimdilerde yağmayan karların üstünde unuttuklarımdı,aslında terkettiğim! 

Benim düşlerim,ellerinin uzanamadığı köşelerindeydi, 

Sevgide kısa devre yapmış İstanbul''un... 

Denizin içindeki sevdamızdan değil de; 

Sevdamızın içindeki denizin sözleriydi,sana söylediğim!', 'İki -ya da üç- düşten ibaretti,ıssızlığa bulanık,  Koyu bir ruha uyumlu artık,adresleri saklı...  Donuk bir bakışa heves etmiş,güneylerden h...', ARRAY['Türk Edebiyatı','Şiir','Barış Toptaş']::text[], 8.5, '{"poet":"Barış Toptaş","poet_slug":"baris-toptas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgide-kisa-devreli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharlara', 'baharlara-baris-toptas-o12pf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinde aradığım,adları belirsiz baharlardı, 

   Ama beni vuran, içimdeki kış oldu... 

   Senin görmeni bekleyemezdim,içimdeki  kırılışları; 

   Ne ümitler çıkmak isterdi;ne korkular durdururdu onları... 

   Benim,martılarla mavilere sürüklenişime benzerdi, 

   Senin yalın uzanışının adı:Düşlerindeki İlkbahar!.. 

   Oysa geride kalan,bir yaşanmamışlık; 

   Sonbahar...Boğaza kıyı çay bahçelerindeki,sarı hüzünler... 

  

   Arada dönemlere karşı alerjili kent, 

   Ve yaptıkları betonarme kurallar,martıları bırakmayan... 

   Hem bilirim ki,çabuk üşürsün rüzgara karşı, 

   Hem de bilirsin ki incitemem seni,karlı akşam vakitleri...', 'Gözlerinde aradığım,adları belirsiz baharlardı,     Ama beni vuran, içimdeki kış oldu...     Senin görmeni bekleyemezdim,içimdeki  kırılışla...', ARRAY['Türk Edebiyatı','Şiir','Barış Toptaş']::text[], 8.5, '{"poet":"Barış Toptaş","poet_slug":"baris-toptas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baharlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-sair-bera-7nspq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son defaydı  bu baktığım resmine 

İçimde intihar ettim  seni,hiç acımadım kıyarken 

Bu  akşam sen öldün  sen yüreğimde 

Sen ölmese idin ben sağ çıkamazdım bu savaştan

İlk  önce sıktım anıların boğazını 

Sesini  işittiğim telefonu da sattım bir eskiciye

Sana yazdığım klavyeyi değiştirdim 

Senden mail aldığım adresi de kullanmıyorum 

Gözümü yumup değiştirdim şifresini 

Bir daha istesem de bulamayayım 

Anılar savunmasız bir anımda sırtımdan vurmasınlar diye

Yani anlayacağın hepten suya vermiş gözlerim bile sevindiler bu işe

Onca  itiş- kakış  onca çırpınış onca sen yoksun artık 

Silerken ne yazdıklarının  geldi aklıma

Ne  şimdiler de , artık hiç bir anlam ifade etmeyen sözlerin

Nede  benim anlamsız bekleyişime bir türlü veremediğim isim 

Ne sen bir daha geleceksin bu şiirden sonra 

Nede ben, şiir e benzeyen sözleri adayacağım senin adına 

Yarım kalmış sevdalarımın arasına atacağım seni 

Son bulmuş beklentilerden bir demet gül ,hediye  bana 

Son hatam olmayacaksın biliyorum 

Ama ilk hatamda değildin ki,bir kere hata yapacak kadar aptal mıyım böyle bir dünyada? 

Güzel sözlerden  süslenmiş acı bir ayrılık beklemekten yoruldum her aşkta 

Suprizleri hiç sevmedim

Bilerek ve isteyerek anlayacağın taammüden  işledi yüreğim tüm cinayetleri

Belki de  notaları hiç yazılmamış bir besteydi beklentilerim

Son bulmayacak duygular yekunu

Artık hiç bir matematiksel hesap yapmadan tutulduğum aşkların adını bile koyamaz oldum 

Gitmeden  kimseye elveda diyecek takati kalmamış biri gibiyim 

Son bir karar verdikten sonra caydırılmaktan korkan 

Ama dedim ya artık bu sondu 

Yaralı kuş tiritlerine de girmekte yok bu şiirden sonra 

Sıçtırtma  mantıksal aşklara,üzülmeyi seven bir yüreğim olduktan sonra 

Kim korkar acıdan,bazı acılar antibiyotiktir insana 

Ben böyle özgürüm güzel gözlüm ,ben böyle sever böyle giderim

Ne derin bir sancıdır içinde kalan nede ne de sövmeler dünlere 

Sensizliğin türküsünü yazacaktım ya korktum dilime dolanır diye

Çiçekçi dükkanlarının da  önünden geçmiyorum artık bir gül görüp 

Seni hatırlatır diye

Hiç kimsede ödünç almak istemedim istemiyorum mutluluk gibi bir hediye 

Hoşça kal güzel gözlüm. Hoşça kal söz ver  bana bundan sonra güleceğim diye 

Benim şiirlerimin adı yoktur birtanem 

Hüznü doldurup kalemimin jarjorüne 

Gözlerim yumuk saydırırım kelimeleri  keleş misali 

Ne sözlerim bir mermi misali dokunsun isterim aslında 

Ne de son bakışımı hatırlamanı 

Benim hayallerimin sınırı yoktur bebeğim 

Menzili olmayan bir yol gibi 

Ufku kim bilir hangi yüreğe kilitli', 'Son defaydı  bu baktığım resmine  İçimde intihar ettim  seni,hiç acımadım kıyarken  Bu  akşam sen öldün  sen yüreğimde  Sen ölmese idin ben ...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/son-defa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tertemiz Bir Lekedir Yalnızlık', 'tertemiz-bir-lekedir-yalnizlik-mete-gurkan-2jm30', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kendine mektuplar yazmaksa yalnızlık 

yalnızlığın kendi kendiliğidir kağıda dökülen

mürekkep tadında

tertemiz bir lekenin kirleticiliğiyle

okumaksa eğer tekrar tekrar onları

insanın tek başınalığıdır her sayfada çevrilen

küçük bir kitaplığa sığdırmaktır milyonlarca kitabı 

hepsi yalnızlıktan tozlanmış ve yaralı

                                                    ağustos , olympos', 'kendine mektuplar yazmaksa yalnızlık  yalnızlığın kendi kendiliğidir kağıda dökülen mürekkep tadında tertemiz bir lekenin kirleticiliğiyle o...', ARRAY['Türk Edebiyatı','Şiir','Mete Gürkan']::text[], 8.5, '{"poet":"Mete Gürkan","poet_slug":"mete-gurkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tertemiz-bir-lekedir-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararken', 'ararken-refet-altan-qpftv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman;

Dolu-dizgin geri dönse

ve Sen olmasan.

Yaşadım,

Sayamam kendimi,yoksan.

Yoksun;

Şimdi neden mi varım?

Hala;

Seni bulmak için

Yaşarım.

(29.04.1963)', 'Zaman; Dolu-dizgin geri dönse ve Sen olmasan. Yaşadım, Sayamam kendimi,yoksan. Yoksun; Şimdi neden mi varım? Hala; Seni bulmak için Yaşarım....', ARRAY['Türk Edebiyatı','Şiir','Refet Altan']::text[], 8.5, '{"poet":"Refet Altan","poet_slug":"refet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ararken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-refet-altan-qp1wt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne Sen bil, ne başkası,

Benim bildiğim yeter.

Ne Sen sev, ne başkası

Benim sevdiğim yeter.

Çalınmaz kapıların

Ardında yalnızlığım.

Ne Sen gel, ne başkası,

Bırakıp giden yeter.

(27.04.1963)', 'Ne Sen bil, ne başkası, Benim bildiğim yeter. Ne Sen sev, ne başkası Benim sevdiğim yeter. Çalınmaz kapıların Ardında yalnızlığım. Ne Sen ge...', ARRAY['Türk Edebiyatı','Şiir','Refet Altan']::text[], 8.5, '{"poet":"Refet Altan","poet_slug":"refet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeter-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Karşılığı Yüzünün', 'yok-karsiligi-yuzunun-cezmi-ersoz-ds390', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin sana rağmen bir yüzün var

Herkesin ilk aşkına benzeyen

Beklemek kadar acı , anlamak kadar zor

Nedensiz ölümlerin suskunluğu gibi

Yok karşılığı yüzünün

Senin sana rağmen bir yüzün var 

Herkesin ilk aşkına benzeyen

Yaklaştıkça imkansız uçurumlar

Nedensiz hayatların o büyük acısı gibi

Yok karşılığı yüzünün', 'Senin sana rağmen bir yüzün var Herkesin ilk aşkına benzeyen Beklemek kadar acı , anlamak kadar zor Nedensiz ölümlerin suskunluğu gibi Yok k...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yok-karsiligi-yuzunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakınlık', 'yakinlik-necip-fazil-kisakurek-6dvuf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neye yaklaşsam, sonu uzaklık ve kırgınlık; 

Anla ki, yok Allah''tan başkasıyla yakınlık...', 'Neye yaklaşsam, sonu uzaklık ve kırgınlık;  Anla ki, yok Allah''tan başkasıyla yakınlık......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yakinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namaz', 'namaz-necip-fazil-kisakurek-tl4fn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Namaz, sancıma ilaç, yanık yerime merhem ;

