INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Ayrılık Şiiri 6', 'on-ayrilik-siiri-6-ataol-behramoglu-mqhw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmiş zaman

Anımsanıyorsa,şimdidir;

Koparılıp atılır ya da

Bir yaprak gibi bir defterden

Koparılıp atılan

Çırpınan bir yürek olabilir,

Ya da bir yaz gecesi,

Yıldızları can çekişen', 'Geçmiş zaman Anımsanıyorsa,şimdidir; Koparılıp atılır ya da Bir yaprak gibi bir defterden Koparılıp atılan Çırpınan bir yürek olabilir, Ya d...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/on-ayrilik-siiri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-suat-secgin-aalfp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çürüyen bir ömür savruluyor,

Ellerinden bak,

Bir masal var sende,

Bilmezsin...

Düşünden ırak, hayalden ırak.

Sen bihaber salınırken yaz çimenlerinde,

Bir dert can çekişir şuramda bir yerimde,

Kendime hep bu duvarı aşamazsın, derim de...

Gönül ne dur bilir ne durak,

İsterim ardından kölen gibi bağırmak,

Kölen gibi haykırmak...

Sen bana çıkmış en yüklü faturasın,

Ve gönlüme haciz,

Senin benden yok haberin,

Ben eteklerinde küçük ve aciz...

Sen bana en yasaksın,

En ağır hükme müstehak,

Bir yol geçiyor senden, bilmezsin,

Gitmek de hak,

Gitmemek de hak...', 'Çürüyen bir ömür savruluyor, Ellerinden bak, Bir masal var sende, Bilmezsin... Düşünden ırak, hayalden ırak. Sen bihaber salınırken yaz çime...', ARRAY['Türk Edebiyatı','Şiir','Suat Seçgin']::text[], 8.5, '{"poet":"Suat Seçgin","poet_slug":"suat-secgin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZaLim', 'zalim-adil-gazoz-axnnq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana hayat ümit verdin sonra bırakıpta gittin ,

seni böyle sevmeseydim bunca çile çekermiydim

                                                                       ZaLim..

hergün hergün meyhaneden geceleri köşelerde,

içip içip ağlıyorum kaderime küsüyorum 

                                                                       ZaLim..

aşkından düştüm dillere rezil ettin el aleme

bakmaz oldular yüzüme kimsesizim bu alemde 

                                                                      ZaLim..

Allahın varmı vicdanın varmı merhamet insafın söyle varmı.', 'bana hayat ümit verdin sonra bırakıpta gittin , seni böyle sevmeseydim bunca çile çekermiydim                                               ...', ARRAY['Türk Edebiyatı','Şiir','Adil Gazoz']::text[], 8.5, '{"poet":"Adil Gazoz","poet_slug":"adil-gazoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Dostumsun', 'unutma-dostumsun-ahmet-telli-23u4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen dostumdun benim gülünce güneşler açan

Bulutlara rüzgara asarım suretini her akşam

Her akşam bir mektup yazarım dağlar kadar

Meşeler göğermiş diyorsun, varsın göğersin

Anlamını yitiren bir şeyler mi var şimdilerde

Yazdığım şiirlere yabancıyım, sokaklara yabancıyım

Taşı delemiyor bir çığlık ve apansız 

Su oluyorum ipince, kendime sızıyorum

Dünya yetmiyor bazan, bırakıp gidebilir miyim?

Kuşları ürkütülmüş bir dal gibiydin, öylesine mahzun!

Efkar da yakışırdı sana, ilk kadeh kekik kokardı

Unutalım mı şimdi kente indiğimiz o ilk günü

Sabahlara kadar okuduğumuz o kitapları

Sabahlara kadar düşüncelerimizde yaşattığımız hayallerimizi

Kar aydınlığında yürüdüğümüz o yolları

Sen dostumdun benim gülünce güneşler açan

Bulutlara rüzgara asarım suretini her akşam

Her akşam mektup yazarım dağlar kadar

Kayıp bir adresten geliyor sesin şimdi, üşüyorsun

Unutma dostumsun sen, neredeysen orda ölmek isterim!', 'Sen dostumdun benim gülünce güneşler açan Bulutlara rüzgara asarım suretini her akşam Her akşam bir mektup yazarım dağlar kadar Meşeler göğe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutma-dostumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilimsin', 'sevgilimsin-ataol-behramoglu-8rv7t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilimsin , kim olduğunu düşünmeye vaktin yok,yapacak

       işleri düşünmekten

Kalabalığın içinde kalabalıktan biri

Gecenin içinde bir yıldız, yitip gitmiş çocukluk gibi

Sevgilimsin,ak dişlerini öpüyorum, aralarında bir mısra gizli

Dün geceki tamamlanmamış sevişmeden 

Sevgilimsin, boğuk aşkım, kanayan gençliğim

Uçuruyorum seni çocukluğuna doğru 

Kanatların yoruluyor, ter içinde kalıyorsun 

Gece yanıbaşımda bağırarak uyanıyorsun

Her sabah el sallıyorum metalle karışmana 

Sevgilimsin, arasına bir kağıt koyup erteliyoruz aşkı 

Otobüslerde ve trenlerde kaçamak yaşanan

Ve bedenlerimiz kana kana kanayamadan yan yana', 'Sevgilimsin , kim olduğunu düşünmeye vaktin yok,yapacak        işleri düşünmekten Kalabalığın içinde kalabalıktan biri Gecenin içinde bir yı...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgilimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sürtük...', 'adi-surtuk-mehmed-yilmaz-wolv9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adımı o koydu, sürtük...

Ben sürtük. Onda, ben bir sürtük!

Canımda bir sürtük,

Bu yürek nasıl taşır bir sürtüğün yükünü,

Yel kayadan ne koparır Meleğim?

Aklımda hiç silinmeyen bir portre,

Odamın duvarlarında üç harf...

Çantamda iki küçük mavi boncuk...

En sevdiğince verilmiş bir kimlik,

Adı sürtük...

Yel kayadan ne koparır Meleğim?

Çantamda iki küçük mavi boncuk!', 'Adımı o koydu, sürtük... Ben sürtük. Onda, ben bir sürtük! Canımda bir sürtük, Bu yürek nasıl taşır bir sürtüğün yükünü, Yel kayadan ne kopa...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Yılmaz']::text[], 8.5, '{"poet":"Mehmed Yılmaz","poet_slug":"mehmed-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-surtuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinden', 'hasretinden-yahya-ozkok-ns7lg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir elimde hançer bir elimde tüfenk,

Başlıyor akşamları hasretinle cenk,

Yeri   göğü   inletiyor    çığlıklarım

Öyle büyük ki acım dünyalara denk.

Gözlerinde kışladığım günden beri,

Kül olmaya başladığım günden beri,

Bir tek seni düşlediğimgünden beri,

Ne gözümde yaş kaldı ne yüzümde renk.

Gelip de    bu acıyı dindirir  misin?

İçimdeki yangını söndürür müsün?

Ölürsem nezarıma gönderir misin?

Gül yanaklarından oluşan bir çelenk.', 'Bir elimde hançer bir elimde tüfenk, Başlıyor akşamları hasretinle cenk, Yeri   göğü   inletiyor    çığlıklarım Öyle büyük ki acım dünyalara...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özkök']::text[], 8.5, '{"poet":"Yahya Özkök","poet_slug":"yahya-ozkok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'olasın', 'olasin-yahya-ozkok-v2tfj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dilerim bir kara sevda peşinden,

Koştura koştura KEREM olasın.

Kanına bend kurup inci dişinden,

Yollara baktıkça verem olasın.

Yüreğin dağlansın ah u zar ile,

Her günün çürüsün bu mezar ile,

NERGİS''ten bin beter intizar ile,

Ömrünce vuslata  haram olasın.

Güneşi aldın ya her sabahımdan,

Zelzele misali  titre   ahımdan,

İşte son dileğim bu İLAH''ımdan,

Kirden gönüllere   meram olasın', 'Dilerim bir kara sevda peşinden, Koştura koştura KEREM olasın. Kanına bend kurup inci dişinden, Yollara baktıkça verem olasın. Yüreğin dağla...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özkök']::text[], 8.5, '{"poet":"Yahya Özkök","poet_slug":"yahya-ozkok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BULAMADIM', 'bulamadim-orhan-avcu-kzlbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BULAMADIM,,,

BULAMADIM,,,

YOLLARDA İZİNİ,

BULAMADIM 

RÜZGARDA KOKUNU,,

BULAMADIM 

SESSİZ ODAMDA SESİNİ,,

BULAMADIM,,

KİREÇ ODAMDA RESMİNİ,,

BULAMADIM.......

YASTIKLARIMDA GÖZ YAŞI BULDUM,,

ELLERİMDE UYŞUKLUK BULDUM,,,

DİZLERİMDE DERMANSIZLIK BULDUM,,,,

YÜREĞİMDE ÇARESİZLİK BULDUM,,,

SENİN YOK OLDUĞUN YAŞAMDA,,

ANLAMSIZLIK BULDUM...', 'BULAMADIM,,, BULAMADIM,,, YOLLARDA İZİNİ, BULAMADIM  RÜZGARDA KOKUNU,, BULAMADIM  SESSİZ ODAMDA SESİNİ,, BULAMADIM,, KİREÇ ODAMDA RESMİNİ,, ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Avcu']::text[], 8.5, '{"poet":"Orhan Avcu","poet_slug":"orhan-avcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Şimdiden Seni Özlemek', 'daha-simdiden-seni-ozlemek-cem-turhan-so2a3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunu hissetmeden seni özlemek var ya !		

Seni özlemek seni		

Sadece seni,

Yalnızca seni..........ne güzel		

Daha dokunamadığım ellerinden tutmak

Daha sevmediğim yüzünü okşamak

Daha tatmadığım dudaklarından ; ''seni seviyorum'' demeni Duymak ne güzel

Ne güzel seni yaşamak		

Sadece seni		

Seni seninle yaşamak

Daha bakmaya kıyamadığım gözlerine bakmak

Söylemeye cesaret edemediklerimi kulağına fısıldamak

Rüzgardan dalga dalga yayılan,

Fırtınalar koparan saçlarına dokunmak ne güzel

Ne güzel seni hissetmek

Derinden

Taa yürekten

Kalp atışlarını duymak

Seni sarmak

Seninle nefes almak	

Seninle yaşamak

Daha sana veremediğim coşkuyu yaşamak ne güzel	

Ne güzel seni sevmek

Sadece seni

Yalnızca seni		

Çocukça		

Dolu dolu

Yürekten............ve gerçekten!', 'Yokluğunu hissetmeden seni özlemek var ya !		 Seni özlemek seni		 Sadece seni, Yalnızca seni..........ne güzel		 Daha dokunamadığım ellerind...', ARRAY['Türk Edebiyatı','Şiir','Cem Turhan']::text[], 8.5, '{"poet":"Cem Turhan","poet_slug":"cem-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/daha-simdiden-seni-ozlemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-cem-turhan-p5d4g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman yatağıma girip geceyi örtsem üzerime

Yalnızlık usulca gelir sokulur yanıma

Ve sevgi şiirleri okur sabahlara dek bana		

O şiirlerde ararım seni

Ve beklerim		

Tüm yalnız gecelerden sonraki sarı boyalı gündüzler boyunca

Gökkuşağı renkli çiçekler içinden çıkıp gelmeni

Bir an bile olsa yaşayabilmek için tüm o ezberlediğim şiirleri', 'Ne zaman yatağıma girip geceyi örtsem üzerime Yalnızlık usulca gelir sokulur yanıma Ve sevgi şiirleri okur sabahlara dek bana		 O şiirlerde ...', ARRAY['Türk Edebiyatı','Şiir','Cem Turhan']::text[], 8.5, '{"poet":"Cem Turhan","poet_slug":"cem-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kör!', 'ey-kor-omer-hayyam-c0hdl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey kör! bu yer, bu gök, bu yıldızlar, boştur boş! 

Bırak onu bunu da gönlünü hoş tut hoş! 

Şu durmadan kurulup dağılan evrende

Bir nefestir alacağın, o da boştur boş!', 'Ey kör! bu yer, bu gök, bu yıldızlar, boştur boş!  Bırak onu bunu da gönlünü hoş tut hoş!  Şu durmadan kurulup dağılan evrende Bir nefestir ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldığımız Yerden', 'kaldigimiz-yerden-sair-shilz-sme7e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha çok vakit var

Sözler kendini buluncaya dek,

Ağrımız dininceye

Biz burda olucaz...

Senden midir

Yoksa yaşadığın yerlerden mi?

Çizgiler var ki

Mutlak ortasında hayallerin,

Geçmişimiz sandığımız zamanımızın...

Gözlerinin kenarındakiler mi

Ilık yumuşak kollarındakiler?

Sen beni buluncaya dek,

Gerçek sesini duyuncaya

Üç ayımızın kayıtları

Seni aradığım raporları kafamda...

Küçük yüzün, küçük dudakların

Onlar hatırlayıncaya dek,

Ben hatırlamaya devam ederim zorla

Üç ay dayanamayıncaya...

(İzmir_bir harizan günü)', 'Daha çok vakit var Sözler kendini buluncaya dek, Ağrımız dininceye Biz burda olucaz... Senden midir Yoksa yaşadığın yerlerden mi? Çizgiler v...', ARRAY['Türk Edebiyatı','Şiir','Şair Shilz']::text[], 8.5, '{"poet":"Şair Shilz","poet_slug":"sair-shilz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaldigimiz-yerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgün Değilim', 'uzgun-degilim-umit-yasar-oguzcan-mrt9z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzgün değilim kanmayı öğrendimse

Senden seni kıskanmayı öğrendimse

Gelsin beni çepeçevre kuşatsın o ateş

Yüz yıl yanarım yanmayı öğrendimse.', 'Üzgün değilim kanmayı öğrendimse Senden seni kıskanmayı öğrendimse Gelsin beni çepeçevre kuşatsın o ateş Yüz yıl yanarım yanmayı öğrendimse....', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzgun-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burhan', 'burhan-burhan-kamali-eind6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler karanlık ıssız deryalar gibi

Güneş doğmaz umut saçılmaz sanırsın

Bir dağ rüzgarı alıp götürürse seni 

onca dostun yanında yapa yanlız kalırsın

                                                   burhan....', 'Geceler karanlık ıssız deryalar gibi Güneş doğmaz umut saçılmaz sanırsın Bir dağ rüzgarı alıp götürürse seni  onca dostun yanında yapa yanlı...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/burhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku', 'oku-adnan-azar-h3422', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni anımsayıp yazdığım şiirleri

eline aldığında bilerek oku

sana yazdığım her maktubu

sıkılma sevdiğim gülerek oku

acı sözler söylersem satırlarımda 

sana kızdığımın anlamıdır bilerek oku

dertlerimi yazdıysam eğer

kendi dertlerimdir diyerek oku

seni görmeden ölürsem

yırtma mektuplarımı yaşlı gözlerle oku

kapanıp görmezse gözlerim eğer

sonbaharda göç eden kuşları oku....', 'seni anımsayıp yazdığım şiirleri eline aldığında bilerek oku sana yazdığım her maktubu sıkılma sevdiğim gülerek oku acı sözler söylersem sat...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan-azar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Nedir Bilmezsin', 'sevmek-nedir-bilmezsin-ozgur-kurt-enece', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Duygu vardır ya hissedersin ama anlatamazsın

Bir Özlem vardır ya özlersin ama ağlayamazsın

Yanlzlık koğuşunda hapis olmak nedir bilirmisin be güzelim

Yıllardır hasret çeken bilir bunu sen değil 

Duygularımı sana anlatamam

Özlemimi bilirim ağlayamam

Sen ırak ellerdeydeyken ;

Benim koğuşlarda volta attığımı bilirmisin

Sen yorulma anlamazsın 

Acı çeken sevenler anlar anlattıklarımı

Ama sabah uyandığımda bir karar verdim ;

Artık seni sevmeyecektim 

Seven kalpler unutmaz derler 

Unutacaktım...

Tıpkı senin beni unuttuğun gibi

Kahpe bir hancı!!!

BENİ SEVDİĞİNİ SÖYLEMİŞTİN YALANCI', 'Bir Duygu vardır ya hissedersin ama anlatamazsın Bir Özlem vardır ya özlersin ama ağlayamazsın Yanlzlık koğuşunda hapis olmak nedir bilirmis...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kurt']::text[], 8.5, '{"poet":"Özgür Kurt","poet_slug":"ozgur-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmek-nedir-bilmezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsanız Eğer;', 'seviyorsaniz-eger-ozdemir-i-nce-wux5w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seviyorsanız eğer;

Geç kalmayın sakın aşkınızı

söylemeye

telgraf çekin, telefon edin,

mektup yazın...

Uçaklara, trenlere

tüm taşıtlara binin...

Koşun, arayın, bulun,

haber gönderin, birine anlatın...

Duvarlara yazın, ağaçlara kazıyın...

Yani deneyin bütün olanakları,

hiç olmazsa; iki yaprak

samanlı kağıda yazın...

Ama sakın geç kalmayın!

AŞKINIZI SÖYLEMEYE...', 'Seviyorsanız eğer; Geç kalmayın sakın aşkınızı söylemeye telgraf çekin, telefon edin, mektup yazın... Uçaklara, trenlere tüm taşıtlara binin...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seviyorsaniz-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiir', 'i-simsiz-siir-abdullah-caheroglu-lgdj8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen alnıma çarpan akşam serini

Sen Yusuf yüzüyle aktın kanıma 

Bir yıldız bıraktı sana yerini

Ulaştır eczanı esrik yanıma

Matem siyahıdır gözlerim benim

Hüzün yaslandığım asayı Musa

Sen ölen bir güne ağladın mı hiç?

Sen  kara yazgılar kucakladın mı?

Saçlarını ördüm düşlerin gece

Ben içimde donan güneşler gördüm

Gülüyor dünyanın mağrur gözleri

Züleyhada yoktu ondaki kibir

Vakit daralmadan düşmeli yola

Mutluluk perisi söyle yerini

Mecali kalmadı dudaklarımın 

Ağır kaldıramaz yüreğim benim

Kalem yakışıyor senin eline 

Konuş haflerine hayran kalayım.

                                              1999', 'Sen alnıma çarpan akşam serini Sen Yusuf yüzüyle aktın kanıma  Bir yıldız bıraktı sana yerini Ulaştır eczanı esrik yanıma Matem siyahıdır gö...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Caheroğlu']::text[], 8.5, '{"poet":"Abdullah Caheroğlu","poet_slug":"abdullah-caheroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isimsiz-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apansız', 'apansiz-musa-dilber-ls4qd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerime bakta konuş

Sevda neymiş göreceksin...

Derinlere dalma sakın 

Belki sende seveceksin...

Sevmesende

Beni göreceksin!...', 'Gözlerime bakta konuş Sevda neymiş göreceksin... Derinlere dalma sakın  Belki sende seveceksin... Sevmesende Beni göreceksin!......', ARRAY['Türk Edebiyatı','Şiir','Musa Dilber']::text[], 8.5, '{"poet":"Musa Dilber","poet_slug":"musa-dilber","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/apansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyle', 'sevgiyle-omer-hayyam-kj9nb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgiyle yoğrulmamışsa yüreğin

Tekkede, manastırda eremezsin

Bir kez gerçekten sevdin mi dünyada

Cennetin cehennemin üstündesin.

Bir sır daha var, çözdüklerimizden başka

Bir ışık daha var, bu ışıklardan başka

Hiç bir yaptığınla yetinme, geç öteye!

Bir şey daha var, bütün yaptıklarından başka.', 'Sevgiyle yoğrulmamışsa yüreğin Tekkede, manastırda eremezsin Bir kez gerçekten sevdin mi dünyada Cennetin cehennemin üstündesin. Bir sır dah...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiyle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-tolgay-kirkil-egze0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutların kırılmasın

Hayellerin yıkılmasın

Gözlerin yaşla yıkanmasın

Bekle beni dönaceğim

Belki bir yaz akşamında

Belki bir kış sabahında

Belki mutluluğun kapısında

Bekle beni döneceğim

Uçan kuşun kanadında

Akşamları senin rüyalarında

Şu gurbet kapısında

BEKLE BENİ AŞKIM DÖNECEĞİM', 'Umutların kırılmasın Hayellerin yıkılmasın Gözlerin yaşla yıkanmasın Bekle beni dönaceğim Belki bir yaz akşamında Belki bir kış sabahında Be...', ARRAY['Türk Edebiyatı','Şiir','Tolgay Kırkıl']::text[], 8.5, '{"poet":"Tolgay Kırkıl","poet_slug":"tolgay-kirkil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekle-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geyikli Gece', 'geyikli-gece-turgut-uyar-xjfzz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Halbuki korkulacak hiçbir şey yoktu ortalıkta

Herşey naylondandı o kadar

Ve ölünce beş on bin birden ölüyorduk güneşe karşı

Ama geyikli geceyi bulmadan önce

Hepimiz çocuklar gibi korkuyorduk.

Geyikli geceyi hep bilmelisiniz

Yeşil ve yabani uzak ormanlarda

Güneşin asfalt sonlarında batmasıyla ağırdan

Hepimizi vakitten kurtaracak

Bir yandan toprağı sürdük

Bir yandan kaybolduk

Gladyatörlerden ve dişlilerden

Ve büyük şehirlerden

Gizleyerek yahut dövüşerek

Geyikli geceyi kurtardık

Evet kimsesizdik ama umudumuz vardı

Üç ev görsek bir şehir sanıyorduk

Üç güvercin görsek Meksika geliyordu aklımıza

Caddelerde gezmekten hoşlanıyorduk akşamları

Kadınların kocalarını aramasını seviyorduk

Sonra şarap içiyorduk kırmızı yahut beyaz

Bilir bilmez geyikli gece yüzünden

      ''Geyikli gecenin arkası ağaç

        Ayağının suya değdiği yerde bir gökyüzü

        Çatal boynuzla
..........
..........', 'Halbuki korkulacak hiçbir şey yoktu ortalıkta Herşey naylondandı o kadar Ve ölünce beş on bin birden ölüyorduk güneşe karşı Ama geyikli gece...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/geyikli-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aniden', 'aniden-onur-ertemiz-2pqcs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duygularım rüzgara dönüşüp , 

Fısıldasa sana , seni sevdiğimi.

Ya da nota olup okşasam benliğini.

Gözyaşın olup aksam bedenine.

Sen olsam.', 'Duygularım rüzgara dönüşüp ,  Fısıldasa sana , seni sevdiğimi. Ya da nota olup okşasam benliğini. Gözyaşın olup aksam bedenine. Sen olsam....', ARRAY['Türk Edebiyatı','Şiir','Onur Ertemiz']::text[], 8.5, '{"poet":"Onur Ertemiz","poet_slug":"onur-ertemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Melankoli', 'siyah-melankoli-onur-ertemiz-pgere', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun bir buz parçası gibi eritiyor bedenimi

İçimde bir sızı var dağıtıyor yüreğimi.

Şimdi yoksun , uzaklardasın herşeyim.

Rüzgarlar seni götürüyor.

Denizler bizi ayırıyor.

Bulutlar ağlıyor , sensiz yaşanmıyor.

Şimdi yoksun , uzaklardasın herşeyim

Siyah götürüyor yalnızlıklara

Ölüm çağırıyor kucağına

Sarıl bana , hiç bırakma

Ağlıyorum ''yalnız geceye''

Ağlıyorum sensizliğe

Sarıl bana , hiç bırakma

Yağmur yağıyor dışarda,yalnızlık çökümüş üstüme gitmek bilmiyor.

Karanlığın kasvetiyle dolmuş yüreğim.

Kahırla ,kederle üzüntüyle.

Yüreğim senin yalnızlığınla ağlıyor.

Kalbim isle dolmuş bir baca gibi.

Boşaltmak istesem...

Olmuyor.

Kaçmak istesem...

Kaçamıyorum.

Anlatmak istesem...', 'Yokluğun bir buz parçası gibi eritiyor bedenimi İçimde bir sızı var dağıtıyor yüreğimi. Şimdi yoksun , uzaklardasın herşeyim. Rüzgarlar seni...', ARRAY['Türk Edebiyatı','Şiir','Onur Ertemiz']::text[], 8.5, '{"poet":"Onur Ertemiz","poet_slug":"onur-ertemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/siyah-melankoli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut', 'bir-umut-cahit-sitki-taranci-ox6h1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgunsun,uzaklardan gelmişsin;

Yitirmişsin neyin varsa birer birer.

Bir sağlık,bir sevinç,bir umut...

Onlar da neredeyse gitti gider.

Dost bildiğin insanların yüzleri

Aynalar gibi kapkara.

Suyu mu çekilmiş bulutların?

Dönmüşsün kuruyan ırmaklara.

Taşlara düşen saat gibi,

Ne artı, ne eksi.

Bir sağlık,bir sevinç,bir umut

Hikaye hepsi.', 'Yorgunsun,uzaklardan gelmişsin; Yitirmişsin neyin varsa birer birer. Bir sağlık,bir sevinç,bir umut... Onlar da neredeyse gitti gider. Dost ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mordu Heryer', 'mordu-heryer-cagin-senturk-3li84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MORDU HERYER 

Sadece bir kez 

hep öyle oldu 

artık yok uzaydaki mavi 

özlüyorum 

bir yanlış hem de çok büyük 

engelleyemiyorum 

ya da yöm veremiyorum 

özlüyorum 

sanki yüzüyordu kurbağa 

ve sanki bulamıyo 

''nedenleri'' aramam dedi 

ama geçmişi ve geleceği 

''neden'' aramaktan ibaretti 

işte buydu anlam 

''neden'' aramak 

özlüyorum 

gözyaşı dökmedim kaç gündür 

unuttum adını 

olgunluk, kaybetmektir 

olmayan heyecanını 

yaşamak 

o zaten her zaman gereksizdi 

aynı amaçsız olduğu kadar 

özlüyorum............................ 

                                                                        02.06.1999', 'MORDU HERYER  Sadece bir kez  hep öyle oldu  artık yok uzaydaki mavi  özlüyorum  bir yanlış hem de çok büyük  engelleyemiyorum  ya da yöm ve...', ARRAY['Türk Edebiyatı','Şiir','Çağın Şentürk']::text[], 8.5, '{"poet":"Çağın Şentürk","poet_slug":"cagin-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mordu-heryer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Korkum', 'tek-korkum-ruya-ersoy-wqlf8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölürsem arkamdan ağlar mısın ...

Karalar bağlayıp yas bağlar mısın...

Yoksa!ölen öldü deyip

Yeni umutlara,neşelere koşar mısın...

Bu yüzden korkuyorum ölümden.

Sonunda unutulmaktan,yok olmaktan

Bana sorsalar sen mi,o mu diye

Yinede ölüme ben koşarım. 

Ölümden değil de unutulmaktan

Sonunda silinip,yok olmaktan

 İşte; tek korkum 

Sonsuzlukta elele değil de

Tek basıma kalmaktan...', 'Ölürsem arkamdan ağlar mısın ... Karalar bağlayıp yas bağlar mısın... Yoksa!ölen öldü deyip Yeni umutlara,neşelere koşar mısın... Bu yüzden ...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-korkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedigin kadar', 'i-stedigin-kadar-hasan-kutuk-3kdw8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istediğin kadar uzak ol benden,istediğin kadar.

isterse aramızda aşılması zor okyanuslar,isterse yüce yol vermez dağlar olsun.yinede mutlu sayarım kendimi,çünki

senin yaşadığın bu dünyada bende yaşıyorum', 'istediğin kadar uzak ol benden,istediğin kadar. isterse aramızda aşılması zor okyanuslar,isterse yüce yol vermez dağlar olsun.yinede mutlu s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kütük']::text[], 8.5, '{"poet":"Hasan Kütük","poet_slug":"hasan-kutuk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/istedigin-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Oldunmu Sevgilim', 'mutlu-oldunmu-sevgilim-ruya-ersoy-3n2nr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluğu umarsızca arıyorum

Mutsuzum hem de çok mutsuzum

Yakamozların .denizdeki görüntüsünde aradım onu

Güneşin doğuşunda,gecelerin karanlığında

Dağların en uç noktasına tırmandım ama,

Gökyüzündeki yıldızların arasında da bulamadım. 

Mutluluğu umarsızca aradım

Sevdiğim insanı hiç yanımda bulamadım

Çırpındıkça daha çok battığımı hissettim,korktum

Göz yaşlarımın hiç dinmediğini fark ettim,kahroldum, 

Sevdiğimin göz yaşlarımın ardından yok oluşu

Kötü kaderimin ağlarını sürekli örmesi

Benim hayata küsmeme sebep oldu

İnanır mısın!

Her sabah yeni bir umutla uyandım

Her geçen saatte de tekrar tekrar yıkıldım

Mutluluğu böyle bulamayacağımı anladım

Sonunda hayatla barışmaya karar verdim

Hayatı bana küstürüp zehir eden o insana

Ağlamak yerine sadece acımam gerektiğini anladım

İşte o gün o içimdeki fırtınanın dineceğini,

Bir gökkuşağı olabileceğini hissettim yüreğimde.

Mutluluğu umarsızca ararken uzaklarda,

Bir gün hiç kaybetmediğimi fark ettim.

Nasıl mı?zavallı sevgi yoksulu sevgilim;

Mutluluğun kendinle barıştığın günde itibaren,

Seni hiç bir zaman bırakmayacağını anladım.

Ben buldum peki ya sen sevdiğim;

Uzaklarda aradığın mutluluğu buldun mu?', 'Mutluluğu umarsızca arıyorum Mutsuzum hem de çok mutsuzum Yakamozların .denizdeki görüntüsünde aradım onu Güneşin doğuşunda,gecelerin karanl...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mutlu-oldunmu-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmuyorum', 'korkmuyorum-ruya-ersoy-qcz53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden kış ve soğuk bir gece

Gökyüzünü karabulutlar kapladı sessizce

Sonra bütün hiddetiyle çaktı şimşekler sinirlenircesine

Ben yine ürkek bir çocuk gibi ürperdim

Bilirsin gök gürültüsünden ,şimşekten ne kadar korktuğumu

Yorganın içine saklandım sesleri duymamak için

 Seni aradı bedenim titreyerek,bedenin sarsın diye

Ama sen benden uzaklarda ve başka......boş ver

,Gökyüzüne haykırdım çığlık atan bir sesle;

Ey karanlık, ey heybetli kızgın gökyüzü

Sevdiğim varken senden korkmuyordum,

Şimdi yok ama yinede senden korkmuyorum

Gücümü yaradan mutluluğu yarınlardan bekliyorum

Sevdiğimden ne bekliyorum diye sordu ,sanki gökyüzü

Ondan nemi bekliyorum boş ver ama

Allah''a benim için neydi onun neydi,neden mutsuz

Acaba benimde katkım var mıydı diye sormasını istiyorum.

Gökyüzü birden gülümsercesine sakinleşti

Yağmurunu sanki gözyaşları mı saklarcasına

Gökyüzünden bedenime doğru süzülmesine izin verdi.', 'Mevsimlerden kış ve soğuk bir gece Gökyüzünü karabulutlar kapladı sessizce Sonra bütün hiddetiyle çaktı şimşekler sinirlenircesine Ben yine ...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korkmuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-sair-bera-1xew7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana şiirler biriktiriyordum 

Pc nin en nadide köşesinde 

Sonu olmayan bir başlangıcın çoktan ipini çekmiştim

Bir tutamlık canı kalmıştı artık sensizliğin 

İnan ki gülüm ;şu an ki gülümsemelerim senden bana  hediye', 'Sana şiirler biriktiriyordum  Pc nin en nadide köşesinde  Sonu olmayan bir başlangıcın çoktan ipini çekmiştim Bir tutamlık canı kalmıştı art...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sema-akin-gqz7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün özlersen gel demiştin giderken

Belki istersen burdayım demiştin

Umutlarım sende yarınlarımda sen

Sen yeterki gel demiştin giderken

Günlerden birgün gece saatin kaçı

Sen hala ordamısın

Beni yine bekliyormusun

Yüzünü bile hatırlamadığım sevgili', 'Birgün özlersen gel demiştin giderken Belki istersen burdayım demiştin Umutlarım sende yarınlarımda sen Sen yeterki gel demiştin giderken Gü...', ARRAY['Türk Edebiyatı','Şiir','Sema Akın']::text[], 8.5, '{"poet":"Sema Akın","poet_slug":"sema-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabaha Kadar', 'sabaha-kadar-ozdemir-asaf-2jl25', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya o kadar büyük ki; 

Bir noktayım ortasında, ne yapsam.

Bazan da o kadar küçülüyor ki dünya,

Devrilecek sanıyorum, kımıldarsam.

Hayat o kadar uzun ki,

Öyle bitmez geliyor ki bir an..

Bir de bakıyorum, o kadar kısalıyor ki; 

Ne çıkar, diyorum, bir hayattan

Saadet o kadar lâzım ki yaşayana; 

Billâhi can verir uğrunda insan.

Hem o kadar boş ki mesud olmak,

Gün yüzü görmeden ölenlerin arkasından.

Ben o kadar önemli kişiyim ki,

O kadar iyiyim ki aklım ve düşüncelerimle.

O kadar fenayım ki ben

Delice niyetlerimle.

Gece; ne kadar karanlık ve sessizsin..

Öyle kaplayorsun ki evleri, yolları, denizleri.

Hem o kadar aydınlık ve seslisin ki; 

Çılgınca coşturuyorsun bizleri.

Sabah; bir yeni dünya gibi geliyorsun; 

Öylesine süslü, öylesine saadesin ki..

Sen o kadar güzelsin ki sabah,

O kadar güzelsin ki.', 'Dünya o kadar büyük ki;  Bir noktayım ortasında, ne yapsam. Bazan da o kadar küçülüyor ki dünya, Devrilecek sanıyorum, kımıldarsam. Hayat o ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sabaha-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Uyanmak İstemedim', 'hic-uyanmak-i-stemedim-ruya-ersoy-fglzt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece hiç uyanmak istemedim

Rüyamda seni ve beni gördüm

Sanki ayrıla acı çeken biz değildik

El ele sarmaş dolaş dolaştık sahilde

Hani her zaman oturduğumuz bir cafe vardı

Yine tatlı buselerle oradaydık

Düne gece hiç uyanmak istemedim

Rüyamda seni ve beni gördüm

Mehtabı seyrediyorduk kuytu bir köşede

Sen kulağıma aşk şarkıları fısıldarken

Ellerinle belimi kavrayıp sıkıca sarılıyordun

Seni seviyorum diye haykırıyordun

Dün gece hiç uyanmak istemedim

Rüyamda seni ve beni gördüm 

Mutluluk yolunda beraber koşuyorduk 

İstemesem de uyandım,gerçekleri anladım

Bu sadece bir rüyaydı belki;

Her şeye rağmen çok ama çok güzeldi.', 'Dün gece hiç uyanmak istemedim Rüyamda seni ve beni gördüm Sanki ayrıla acı çeken biz değildik El ele sarmaş dolaş dolaştık sahilde Hani her...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hic-uyanmak-istemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Konuğu', 'agustos-konugu-ataol-behramoglu-wyc20', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Odama bir an giren uçucu bir böcek

-Arıdan irice, kanatları renkli-

Dolaştı bir süre, vızıldamadan.

Sonra bulup yolunu pencerenin

Çıkıp gitti

Bir öykü çeviriyordum Çehov''dan

Masamda bira bardağı

-Odam, kitaplarım,olağan dünyam-

Tül perdede ağustos ışınları

Tanık oldu yaşamıma

Bu uçucu böcek, sadece bir an

Çıkıp gitti sonra

Tıpkı yaşamıma bir an katılan

Sonra yitip giden bir sevgili gibi', 'Odama bir an giren uçucu bir böcek -Arıdan irice, kanatları renkli- Dolaştı bir süre, vızıldamadan. Sonra bulup yolunu pencerenin Çıkıp gitt...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/agustos-konugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arada', 'arada-ataol-behramoglu-7gix9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güz güneşi benzeşiyor bahar güneşiyle

Biri kışa girerken biri kıştan çıkarken

Biri yeni bir aşk öncesinse bir kederden sonra

Biri biten bir aşktan sonra kedere girerken', 'Güz güneşi benzeşiyor bahar güneşiyle Biri kışa girerken biri kıştan çıkarken Biri yeni bir aşk öncesinse bir kederden sonra Biri biten bir ...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/arada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-mustafa-celebi-cetinkaya-5lzon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir ; 

sükutumun öfkeli resmi

kalbimin dili..

Sokaklarda bir ışıltı ;

bildim !

bayram kandili....

27.05.2000', 'Şiir ;  sükutumun öfkeli resmi kalbimin dili.. Sokaklarda bir ışıltı ; bildim ! bayram kandili.... 27.05.2000...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Ayrılık Saati Gelse', 'ne-zaman-ayrilik-saati-gelse-umit-yasar-oguzcan-4dxuo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman ayrılık saati gelse

En vazgeçilmez yerinde yaşamın

Duysak ayak seslerini akşamın

Ve sokaklardan el ayak çekilse

Bir ürpertiyle duyarım o zaman

Seni çağıran sesi uzaklardan

Ne zaman ayrılık saati gelse

Bir gariplik çöker içime birden

Kalan tek anı gibi bir devirden

Durmadan çalınır o gamlı beste

Sanki bilirde hazin öykümüzü

Bulutlar ağlar, kararır gökyüzü

Ne zaman ayrılık saati gelse

Bir çaresizliği anlatır gibi

Birden değişir gözlerinin rengi

Mavi solar, koyulaşır yeşilse

Sarınca ruhunu eski bir hüzün

Uçar gider pembeliği yüzünün

Ne zaman ayrılık saati gelse

Uzatsan özlemle dudaklarını

Tüm ağaçlar döker yapraklarını

Ne çiçek kalır ortada, ne bahçe

Sadece uğultusu o rüzgarın

Ve bir umut kırıntısı: Belki yarın

Ne zaman ayrılık saati gelse

Bir fırtına çıkmışçasına, büyük

İçimdeki güllerin boynu bükük

Bir zaman kalakalırım öylece

Neden sonra gittiğini anlarım

İçimde güller ağlar...', 'Ne zaman ayrılık saati gelse En vazgeçilmez yerinde yaşamın Duysak ayak seslerini akşamın Ve sokaklardan el ayak çekilse Bir ürpertiyle duya...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ne-zaman-ayrilik-saati-gelse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Surda Bir Gedik Açtık', 'surda-bir-gedik-actik-necip-fazil-kisakurek-idqyf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Surda bir gedik açtık mukaddes mi mukaddes

