INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kervan', 'kervan-necip-fazil-kisakurek-et6hz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedi renkli Peygamber kuşağının altında,

Kervanım yola çıktı, öncüsü kır atında...', 'Yedi renkli Peygamber kuşağının altında, Kervanım yola çıktı, öncüsü kır atında......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kervan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaözünde', 'karaozunde-sabit-i-nce-1mjqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karaözü denmiş ak olan yere,

Akça özler dolu Karaözünde.

Kevser ırmağıdır akan her dere,

Gel testiyi doldur Karaözünde.

İlim, irfan, medeniyet oradan,

İnsanları seçkin değil sıradan.

İstedikçe vermiş ulu yaradan,

Ne ararsan boldur Karaözünde.

Çevresi tertemiz sanki cennettir,

Amaç tektir insanlığa hizmettir.

İnsana saygı var, çok da cömerttir,

Özgürlüğe yoldur Karaözünde.

Çalışkandır, üretirler, yaparlar,

Hak diyerek insanlara taparlar,

Faydalı işlere hep bir koparlar,

Hünkara bir koldur Karaözünde.

Dilim dönmez, kelam yetmez,

Anlat anlat inan bitmez.

İnsanları hiç kin gütmez,

Aşk badesi doldur Karaözünde.

Anlatılmaz yaşanırsa bilinir,

Sevginin uğruna orda ölünür,

İNCE muhabbetten üçe bölünür,

Hak yanında kuldur Karaözünde.

28-7-2000 KARAÖZÜ', 'Karaözü denmiş ak olan yere, Akça özler dolu Karaözünde. Kevser ırmağıdır akan her dere, Gel testiyi doldur Karaözünde. İlim, irfan, medeniy...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karaozunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara Geldim', 'yara-geldim-sabit-i-nce-oc4yf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yara geldim, yara geldim,

Denizleri yara geldim.

Dağlar aşıp, çöller geçip

Bilmediğim yar’a geldim.

Zâra geldim, zâra geldim,

Dü beş atıp zar’a geldim.

Dertlerimi yazsın diye,

Güçlü bir yazara geldim.

Sur’a geldim, sur’a geldim,

Aşılmaz bir sur’a geldim.

Halimi  arz edem diye,

Hakime kusur’a geldim.

İnce koşup yâra geldim,

Ciğerimi yara geldim.

Bir leyla’nın aşkı ile,

Şu çölleri yar’a geldim.

27-7-2000 Kayseri', 'Yara geldim, yara geldim, Denizleri yara geldim. Dağlar aşıp, çöller geçip Bilmediğim yar’a geldim. Zâra geldim, zâra geldim, Dü beş atıp za...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yara-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçum mu?', 'sucum-mu-sabit-i-nce-ogsd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Münkir-Nekir gibi sorgu sorarsın,

Ne devletten çaldım, ne de aşırdım.

Sen kim oluyorsun hesap sorarsın,

Yurt dışına sanki mal mı kaçırdım.

Hesap-kitap deme iyi bilirim,

Doğruluğun ben yoluna ölürüm.

Maksat başka ise, iste gelirim,

Kız dururken yoksa, dul mu kaçırdım.

Yetim malı yemediysem suçum mu,

Benden almak istediğin öç müdür?

Ne istersin, haraç mıdır, baç mıdır,

Yoksa yaladığın yal mı kaçırdım.

Yıllar yılı sömürdünüz yetmez mi?

Araban mı durdu yola gitmez mi?

Hiç kimsenin sana gücü yetmez mi

Yoksa kovanından mal mı kaçırdım.

Bu düzenin böyle gider mi sandın,

Sandın ise bil ki baştan aldandın.

Yoksa ince ince nara mı yandın?

Tökezledin demek, nal mı kaçırdım.

27-7-2000 Kayseri', 'Münkir-Nekir gibi sorgu sorarsın, Ne devletten çaldım, ne de aşırdım. Sen kim oluyorsun hesap sorarsın, Yurt dışına sanki mal mı kaçırdım. H...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sucum-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni', 'sev-beni-sabit-i-nce-k4pw1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilerim güzelim can-ı gönülden

Doyasıya, doyanaca sev beni.

Olmuyorsa sevmek beni gönülden,

“beni sevdi” diye nolur sev beni.

Gökten ay indirip getirmez miyim,

Görmesinler diye yitirmez miyim,

Gönlümdeki gülü yetirmez miyim,

Gül solmasın diye nolur sev beni.

Utanç duvarını yıkan da benim,

Kalbinde ateşi yakan da benim.

Rüyanda karşına çıkan da benim,

“rüyalarım “ diye nolur sev beni.

İste sen, kapında kölene olayım,

İste ki, uğrunda ölen olayım.

Gözündeki yaşı silen olayım,

“hizmetkârım” diye nolur sev beni.

İnce’yim, incel de kırıl diyorsan,

Kuşak ol belime sarıl diyorsan,

Beni sevenlere darıl diyorsan,

“beni tek seven o” diye sev beni.

27-7-2000 Kayseri', 'Dilerim güzelim can-ı gönülden Doyasıya, doyanaca sev beni. Olmuyorsa sevmek beni gönülden, “beni sevdi” diye nolur sev beni. Gökten ay indi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sev-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevdim Bir Zamanlar, Seviyorum Yine de', 'cok-sevdim-bir-zamanlar-seviyorum-yine-de-ataol-behramoglu-dpwtf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok sevdim bir zamanlar, seviyorum yine de

Alıp başımı gitmeyi yollar boyunca

Seyretmek bir bozkır akşamını camından bir otobüsün

Masal şehirlerini geçerken hızla

Çok sevdim bir zamanlar, seviyorum yine de

Ürpertili, sımsıcak tenini kadınların

Salmak serin sulara gövdemi

Düşüp gitmek ardına şiirin ve aşkın

Çok sevdim bir zamanlar, seviyorum yine de

Varolduğumu düşünmeyi, ürpererek...

Karanlık bir odada küçük bir çocuk gibi

Yağmurdan ve yalnızlıktan ürkek

Çok sevdim birzamanlar, seviyorum yine de

Düşüncemi geniş ve sonsuz olanla birleştirmeyi

Hırçın ve ele geçmezce atılgan

Uysal ve usulcacık benim olan şeyi...

Çok sevdim bir zamanlar, seviyorum yine de

Ve hep seveceğim beynim ve tenim varoldukca bu dünyada

Pırıl pırıl olanı, her zaman bir güz diriliğinde

Değişmez ve değişken olanı sonsuzca...', 'Çok sevdim bir zamanlar, seviyorum yine de Alıp başımı gitmeyi yollar boyunca Seyretmek bir bozkır akşamını camından bir otobüsün Masal şehi...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cok-sevdim-bir-zamanlar-seviyorum-yine-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerinden Sevişmek', 'uzerinden-sevismek-cemal-sureya-zg9sd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başkaları da var masa da

İleri geri konuşuluyor

Ötedesin o adamın duldasında

Göz kapaklarına bürünmüş adam

Eli her an omuzunda

Eğiliyor sigaranı yakıyor 

Teşekkürler sigara dumanı 

Sağolasın o adam 
..........
..........', 'Başkaları da var masa da İleri geri konuşuluyor Ötedesin o adamın duldasında Göz kapaklarına bürünmüş adam Eli her an omuzunda Eğiliyor siga...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzerinden-sevismek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran', 'hicran-zeki-tazegul-u8a7m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi artık cok uzaklardayım

Doğup büyüdüğüm diyarlardan.

Kah burada , kah sıladayım.

Nasibim yok bast-ı zamandan.

Gecler karanlık , renkler donuk,

Nereye baksam alışılmadık.

Ne yapsam  faydasız

Bir türlü dikiş tutturamadık.

Hatıralarımda hala yaşıyor

Yol kenarındaki eski evimiz.

Anılarıma perçinli çıkmıyor

Kuğulu park , habire gittiğimiz.', 'Şimdi artık cok uzaklardayım Doğup büyüdüğüm diyarlardan. Kah burada , kah sıladayım. Nasibim yok bast-ı zamandan. Gecler karanlık , renkler...', ARRAY['Türk Edebiyatı','Şiir','Zeki Tazegül']::text[], 8.5, '{"poet":"Zeki Tazegül","poet_slug":"zeki-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hicran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamı Yeşertmek Seninle', 'yasami-yesertmek-seninle-mustafa-bozkurt-n6j3k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Butun bir hayat ;

Yarısı senin yarisi benim

Benim olan yasanmaz

Senin olan Yasanmaz

Ya niye!,neden,

Ne bu cileki

Bu eziklilk neki

Olumun kanatlari altinda,

Yasamaya direnmek.

Sevmek olumu

Bir kere

Nefreti savurmak,

Yasamin sonsuzluguna

Yesertmek yasami;

Yeniden seninle...', 'Butun bir hayat ; Yarısı senin yarisi benim Benim olan yasanmaz Senin olan Yasanmaz Ya niye!,neden, Ne bu cileki Bu eziklilk neki Olumun kan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bozkurt']::text[], 8.5, '{"poet":"Mustafa Bozkurt","poet_slug":"mustafa-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasami-yesertmek-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlü', 'kara-gozlu-mustafa-bozkurt-3vpfp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gozlu kara bakisli

Hayata tutsak bir cift goz

Anlatamaz

Anlatamaz yoksulugu

Kapanmis gozlerin

Yirtik pirtik ustun

Kap kara gozun 

Anlatamaz yoksulugu

Bakislarin hep bosa

Anlamsiz bir hayati anlatir gibi

Yasamin yok olmuslugunu

Bikkinligini,bitkinligini

Anlatamaz gozlerin

Anlatamaz yoksulugu

Acimasizligin saltanatini deviremez

O mu yaratmiski yoksulugun celatini

Bir olumu anlatir

Bir ezikligini

Ve o saf yuregin

Boyun egmeyen yasama direnisini

Bir onu anlatir

O kara gozlerin

Ama anlatamaz yoksulugu

Anlatamaz

Bir kendin gibilere anlatir durur her seher

Sonra sorgular tarihi

Bilmez o agalar,pasalar

Beyler efendiler

Sayinlar mayinlar

Ne anlarlar

Kara gozlu

Yoksulugu ne bilirler

Nede anlarlar

Bakislarindan seni...

                     8.4.2000

                          9:30', 'Kara gozlu kara bakisli Hayata tutsak bir cift goz Anlatamaz Anlatamaz yoksulugu Kapanmis gozlerin Yirtik pirtik ustun Kap kara gozun  Anlat...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bozkurt']::text[], 8.5, '{"poet":"Mustafa Bozkurt","poet_slug":"mustafa-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kara-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-cem-ocal-c8i0h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz her geceden sabaha,

Yıllarım gençliğine, aklım kalbine gider.

Hep bir tek gül olursun rüyalarımda,

Yüzün yine bütün güler.

Gece hasret kadar uzun geçer,

Gerçek kadar.

Çok istersem olmaz sanırım ama boşuna,

Rüyalar çabuk biter.

(Şubat 2000-İzmit)', 'Sensiz her geceden sabaha, Yıllarım gençliğine, aklım kalbine gider. Hep bir tek gül olursun rüyalarımda, Yüzün yine bütün güler. Gece hasre...', ARRAY['Türk Edebiyatı','Şiir','Cem Öcal']::text[], 8.5, '{"poet":"Cem Öcal","poet_slug":"cem-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mustafa-serdar-i-spir-o8ew7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bilinmez meçhul değildir zaman

Sonu gelmez karanlıkların derinliklerinde

Dert yüklü heybeleri yüklenmiş yolcuların

Anlaşılmaz sevda yoluna düştükleri an

Bir garip aşıklar ordusu ki yürürler hayallere

Ne sevenler belli ne sevenleri ne de yönleri 

Yağmur tanelerinin denizlere düştüğü gibi

Teslim olur gönüller gönüldeki yellere

Hayatın kaçıncı mevsimidir yaşanılan

Acaba hangi tarafı yalan aynaların

Çırpınan yürklerin kavuşmasına yakın

Kim bilir kaç fırtınanın ardından

Tarihsiz tarifsiz çileler bittiği zaman

Yolun sonuna geldiklerinde sevdalılar

Akıllara gelmez son nefeslerde

Başlıyor mu bitiyor mu zaman', 'Bir bilinmez meçhul değildir zaman Sonu gelmez karanlıkların derinliklerinde Dert yüklü heybeleri yüklenmiş yolcuların Anlaşılmaz sevda yolu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Serdar İspir']::text[], 8.5, '{"poet":"Mustafa Serdar İspir","poet_slug":"mustafa-serdar-i-spir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-fazil-husnu-daglarca-j7822', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ilık bir su gibidir içimde yalnızlığım,

Yalnızlığım, ruhumda uzak bir ses gibidir.

Her sabah ufuklardan mavi şarkılar gelir,

Ve her sabah ürperir içimde yalnızlığım

Güneşim aydan sarı, yarınım dünden zorsa,

Sarsın artık ömrümü tunç kandillerin isi

Üşüyen ellerimden tutmalıydı birisi,

Eğer benim gözlerim onları görmüyorsa.

Bir camın arkasında açılıyor güllerim,

Havuzum pırıl pırıl... yıkar bakışlarımı.

İşler temiz ziyalar suya nakışlarımı; 

Ruhumun dünyasından eser tahayyüllerim

Rüya rüzgarlarında bir yaprak yalnızlığım

Düşüncem bir neydir ki ürperir perde perde

Belki bu mısralarım esecek gönüllerde

Fakat herkese uzak kalacak, yalnızlığım.', 'Ilık bir su gibidir içimde yalnızlığım, Yalnızlığım, ruhumda uzak bir ses gibidir. Her sabah ufuklardan mavi şarkılar gelir, Ve her sabah ür...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizligim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-serdal-dogan-xwhbz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun gecelerin ardından,

İçilen

Bir bardak şaraptın.

Çaldılar seni 

Bir gece vakti,

Tanrılara sundular,

Sen çaresiz,sen esir,sen kurbandın.

Umut çok uzaklarda,

Sensizliğin ilk sabahında

Astım kendimi.', 'Yorgun gecelerin ardından, İçilen Bir bardak şaraptın. Çaldılar seni  Bir gece vakti, Tanrılara sundular, Sen çaresiz,sen esir,sen kurbandın...', ARRAY['Türk Edebiyatı','Şiir','Serdal Doğan']::text[], 8.5, '{"poet":"Serdal Doğan","poet_slug":"serdal-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğday', 'bugday-volkan-guzel-91tp4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde bir çiçek

Evirip çeviriyorum, 

Neye yaradıgınımı keşfediyorum çiçeğin

Oysa baş öne eğik

Nelermi geçiyor aklımdan? 

Hangi bugdayımı öğütüyor bu değirmen bilemiyorum, 

Ruhumun, cesedinin yerini bilmediğim gibi, 

Elimde hala deminki çiçek, 

Gözlerim söylüyor bunu bana

Belliki hissedemiyorum sapını çiçeğin

Hissedemediğim yalnızca sapımıydı çiçeğin? 

Nice duygularım körelmişti, 

Şu kısacık zaman içinde.', 'Elimde bir çiçek Evirip çeviriyorum,  Neye yaradıgınımı keşfediyorum çiçeğin Oysa baş öne eğik Nelermi geçiyor aklımdan?  Hangi bugdayımı öğ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Güzel']::text[], 8.5, '{"poet":"Volkan Güzel","poet_slug":"volkan-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bugday-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemheri', 'zemheri-serkan-cekirge-kzttu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen cırılcıplak bir gül!Narin.

Bne zamansız zemherinin pesinde uykusuz.

Rüzgardan,yaban ellerden,kendimden sakınırken seni giyindin kanattın yüreyimi.

Bunu hak etmemiştim.', 'Sen cırılcıplak bir gül!Narin. Bne zamansız zemherinin pesinde uykusuz. Rüzgardan,yaban ellerden,kendimden sakınırken seni giyindin kanattın...', ARRAY['Türk Edebiyatı','Şiir','Serkan Çekirge']::text[], 8.5, '{"poet":"Serkan Çekirge","poet_slug":"serkan-cekirge","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zemheri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım''a', 'canim-a-gulumser-agirer-m7pu0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen biraz ''lütfen'' benimsin

Bense aslında 

sokaktaki adamın olduğum kadar

senin

Nice aylara!', 'sen biraz ''lütfen'' benimsin Bense aslında  sokaktaki adamın olduğum kadar senin Nice aylara!...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Buyuz Dostum', 'biz-buyuz-dostum-gulumser-agirer-zkjps', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Banuş''a

az orospu değiliz be dostum

yarışırız birbirimizle

öldürürüz adamı tek elimizle

çalarız kalbini ne kadar dirense de..

bir de çarpmasak düz duvara arada

kendi isteğimizle...

Her neyse...kaşar mı demişti bize

toplumun  akıllı evladı?

Kaşarız ya, en lezzetlisinden

Var mıymış bi itirazı?', 'Banuş''a az orospu değiliz be dostum yarışırız birbirimizle öldürürüz adamı tek elimizle çalarız kalbini ne kadar dirense de.. bir de çarpmas...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biz-buyuz-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırım', 'sanirim-gulumser-agirer-zo3lq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanırım fazla inandım.

Asla olmayacak planlarımızla

Olmayan bir geleceği yazdim.

Hayat böyle birşey ama, 

Hele daha varken otuzuna..

Neyse..

Hayallerimizi sen satmasaydın

Zaten ben sıkılacaktım:)

22.02.2000', 'Sanırım fazla inandım. Asla olmayacak planlarımızla Olmayan bir geleceği yazdim. Hayat böyle birşey ama,  Hele daha varken otuzuna.. Neyse.....', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-gulumser-agirer-l5bod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana bir şiirle veda etmeliyim sanırım:)

adı ''ben seni hiç sevmedim ki'' olmalı

sevmedim de gerçekten...bunu iyice anlatmalı

etkilenmedim bile bırak sevgiyi...

zaten aşk dediğin o kadar kolay mı ki?:)

evet şimdi yazmaya başlayacağım

ve umurumda olmadığını anlatacağım...

...ama sanırım önce şu yaşları durduracağım...

05.07.1999', 'Sana bir şiirle veda etmeliyim sanırım:) adı ''ben seni hiç sevmedim ki'' olmalı sevmedim de gerçekten...bunu iyice anlatmalı etkilenmedim bil...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/veda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezartaşım', 'mezartasim-gulumser-agirer-e7ec4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mezartaşıma

Neon taksanız

ama kim çeker eşektriği oraya

Hem ne yazacaksınız...

Ayıp olur fakir fukaraya', 'Mezartaşıma Neon taksanız ama kim çeker eşektriği oraya Hem ne yazacaksınız... Ayıp olur fakir fukaraya...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mezartasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar...', 'kadinlar-serkan-cekirge-pap01', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz nasıl varlıklarsınız?Ey kadınlar,

Kusluk vakti söylemistin  gözlerinin içi gülerek.

Kahretsin ki bu yalanı ilk söyleyen sen deyilsin.

Sonda olmayacaksın.

Ne zamana kadar benı kandıracaksın ey hayat,

Sende yalansın elma şekerim kadar,

kırmızı,cekici kainat kadar ulu.', 'Siz nasıl varlıklarsınız?Ey kadınlar, Kusluk vakti söylemistin  gözlerinin içi gülerek. Kahretsin ki bu yalanı ilk söyleyen sen deyilsin. So...', ARRAY['Türk Edebiyatı','Şiir','Serkan Çekirge']::text[], 8.5, '{"poet":"Serkan Çekirge","poet_slug":"serkan-cekirge","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel Acıbadem Hastanesi', 'ozel-acibadem-hastanesi-gulumser-agirer-5gj0g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer yarısı boş

dolu dolu yirmidört seneyse

görüp göreceğim

ve güzel olacaksa cesedim..

..ki ümit ettiğim

söyleyebileceğim

hepinizi ölesiye sevdiğim.

Ve hüzünlüyse son bakışı gözlerimin

tek üzüntüm

herşeyim

bebeğim..

birtanecik Eşim.', 'Eğer yarısı boş dolu dolu yirmidört seneyse görüp göreceğim ve güzel olacaksa cesedim.. ..ki ümit ettiğim söyleyebileceğim hepinizi ölesiye ...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozel-acibadem-hastanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-gulumser-agirer-azhu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğumgününe bir kala

kocaman bir elveda

söylenmemiş

susulmamış

sorgulanıp bulunmuş yalnızca..

Yapıp bir hediya paketi

-hep yaptırırsın ya-

as işte boynuna

ve taşı ölene kadar

ve asla unutma

Hatırla!

01.03.2000', 'Doğumgününe bir kala kocaman bir elveda söylenmemiş susulmamış sorgulanıp bulunmuş yalnızca.. Yapıp bir hediya paketi -hep yaptırırsın ya- a...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geveze', 'geveze-gulumser-agirer-taj9s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmiş hatalar peşini bırakmaz insanın

Çenesini tutamadığı sürece

Geçmiş insanı tutar

Fazla birşey yok yapacak

Kendi içine kusar.

19.12.1999', 'Geçmiş hatalar peşini bırakmaz insanın Çenesini tutamadığı sürece Geçmiş insanı tutar Fazla birşey yok yapacak Kendi içine kusar. 19.12.1999...', ARRAY['Türk Edebiyatı','Şiir','Gülümser Ağırer']::text[], 8.5, '{"poet":"Gülümser Ağırer","poet_slug":"gulumser-agirer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/geveze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naftalin', 'naftalin-sunay-akin-jsfls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eksik olan

bir yanı vardı aşkımızın

bir filminde 

üç beş figüran dövüp

ata binmemesi

gibi cüneyt arkın''ın

Haberin olsun 

vermedim eskiciye 

yırtık ayakkabılarımı 

nasıl ayrılırım ki onlardan

kapınızın önünde 

az mı çıkarıp

giymiştim

Naftalinledim bende kalan yün kazağını

söylemiş miydim size

naftalin 

ki güvelere karşı kullandığı 

kimyasal silahıdır 

anıların', 'Eksik olan bir yanı vardı aşkımızın bir filminde  üç beş figüran dövüp ata binmemesi gibi cüneyt arkın''ın Haberin olsun  vermedim eskiciye  ...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/naftalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-murat-urusakli-au1ly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat boş yine bugün,

İlk günlerdeki gibi yalnızım, çaresizim,

Her geçen gün karanlığa batıyorum,

Sonu olmayan yollara bakıp,

Senin için ağlıyorum,', 'Hayat boş yine bugün, İlk günlerdeki gibi yalnızım, çaresizim, Her geçen gün karanlığa batıyorum, Sonu olmayan yollara bakıp, Senin için ağl...', ARRAY['Türk Edebiyatı','Şiir','Murat Uruşaklı']::text[], 8.5, '{"poet":"Murat Uruşaklı","poet_slug":"murat-urusakli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayat-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylülde Melal', 'eylulde-melal-mucip-kina-llp69', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eylülde asiydi ilk gülmelerim

Gökkuşağı şafakla çökerdi üzerime

Hüzzamdı içimde sevgim hazandı

Bir azgın tufandı iliklerimde

Aymazdı yüreğim yollar belalı

Dudağımda ıslık gün işkenceydi

Islak düşlerimde çocuktu dünya

Hayat yedeğimde bir bilmeceydi

Eylüller bakirdi yalnızlığımda

Eylüller sabrıma sessiz ölüştü

Mevsimlerden öte limandı bana

Şiirler yaktığı karanlığında

Soğuk gecelere bir gömülüştü

İkindi vakitleri doğumdu maverama

Gölgemde gün batıı sevgiler dirilişti

Ne ettim hallerime, köz ektim küllerime 

Bir eylül hazanında sabrıma sevda düştü

Ve şimdi yine benim melulluk saatinde

Sonsuzluk ummanına güvercinler uçuran

Eylüller harcı değil bu son macerasında

Ömrümün küllerini maveraya savuran', 'Eylülde asiydi ilk gülmelerim Gökkuşağı şafakla çökerdi üzerime Hüzzamdı içimde sevgim hazandı Bir azgın tufandı iliklerimde Aymazdı yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Mucip Kına']::text[], 8.5, '{"poet":"Mucip Kına","poet_slug":"mucip-kina","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eylulde-melal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğümlendi!!!', 'dugumlendi-gokhan-bozdogan-0sn38', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düğümlendi işte yine boğazım 

ağlayamadım yanında

sırf sen üzülme diye ağlamadım yanında

doldu gözlerim

yutkundum

ama ağlamadım 

ağlayamadım

sırf sen üzülme diye ağlamadım yanında

her gece ıslak gözlerim 

gözyaşlarım her gece gözlerimde ve

yüzüm damla damla yaşlarla kardeş

yastığım ıslak

yine

ama beni görmüyorsun

beni böyle bilmiyorsun

ağlıyorum yine

seni seviyorum diye haykırıyorum

duymuyorsun

gözlerini arıyor gözlerim

baktıkça daldığım

kaybolduğum o gözlerini arıyorum ben

gidiyorsun yüreğim seninle gidiyor

seni evet seni

yalnızca seni seviyorum

seviyorum.......

seveceğimde......', 'düğümlendi işte yine boğazım  ağlayamadım yanında sırf sen üzülme diye ağlamadım yanında doldu gözlerim yutkundum ama ağlamadım  ağlayamadım...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dugumlendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Asker', 'olu-asker-sunay-akin-tsy7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zeynep ve Derviş''e

Nasıl da çok istemiştim

savaşa gitmeden 

sevgilimle evlenmeyi

ama nereden bilebilirdim

ki silahın

demirine çarpıp

saklandığım yeri belli edeceğini

parmağımdaki yüzüğün...', 'Zeynep ve Derviş''e Nasıl da çok istemiştim savaşa gitmeden  sevgilimle evlenmeyi ama nereden bilebilirdim ki silahın demirine çarpıp sakland...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olu-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-mucip-kina-ek4d9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni yazmayacağım bu hazan akşamında

Sen ki bestelenmeden gönlümde çalınansın

Çocuklar sana ölmeden önce

Seni yazsın

Seni anlasın diye boş bırakıyorum

Ve hüznüm bende kalsın

Sana sokak serserisi bir bilge

Sana gönlü yarım bir berduş bırakıyorum', 'Seni yazmayacağım bu hazan akşamında Sen ki bestelenmeden gönlümde çalınansın Çocuklar sana ölmeden önce Seni yazsın Seni anlasın diye boş b...', ARRAY['Türk Edebiyatı','Şiir','Mucip Kına']::text[], 8.5, '{"poet":"Mucip Kına","poet_slug":"mucip-kina","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/miras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Borç Değildir', 'askim-borc-degildir-banu-yilmaz-jox7a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmiyorsan derdetme kendine birtanem,

Aşkım sana borç değildir.

Sen bilmesen de anahtarım gözlerinde,

Benden sana küçük bir hediyedir.

Karşılığını beklemem senden birtanem,

Hayatta herşey karşılıklı değildir.

Boyumdan büyük bir sevgi besledim içimde,

Bilemedim senin kalbin kiminledir.

Rüyalarımda yaşadım, hayallerimde avundum,

Gözümden akan yaşla okyanusları doldurdum.

Birtanem yalnızlığıma ortağım oldun,

İmkansızım sensin son umudum.

Hiçbir zaman doğmasan da ufkumda,

Kalbim seni sevdi, pişman değildir.

Seni sensiz sevmeyi öğrendim birtanem,

Aşkım sana borç değildir.

(ağustos/2000)', 'Sevmiyorsan derdetme kendine birtanem, Aşkım sana borç değildir. Sen bilmesen de anahtarım gözlerinde, Benden sana küçük bir hediyedir. Karş...', ARRAY['Türk Edebiyatı','Şiir','Banu Yılmaz']::text[], 8.5, '{"poet":"Banu Yılmaz","poet_slug":"banu-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askim-borc-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yabancı', 'bir-yabanci-banu-yilmaz-i4gef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün bir yabancıyım kendime...

Başkasını görüyorum sanki aynada,

Bir başkasında nefes alıyorum,

Bu eller bu gözler benim deği,l

Dudakların arasından çıkan ses benim değil,

Bugün bir yabancıyım kendime...

Bugün bir yabancıyım herşeye...

Başka biri yatıyor yatağımda,

Bir başkasının yerini allıyorum,

Bu oda bu resimler benim değil,

Seslerin söylediği isim benim değil,

Bugün bir yabancıyım herşeye...

Bugün bir yabancıyım herkese...

Başkasını görüyorum sevgilimin fotoğrafında,

Yıllardır beni uyandıran ses, hayır tanımıyorum,

Bu arkadaşlar; onlarla konuşan beden benim değil,

Bu satırları yazan eller benim değil,

Bugün bir yabancıyım herkese...

Bir yabancı...

(temmuz/200)

Bir yabancı..........', 'Bugün bir yabancıyım kendime... Başkasını görüyorum sanki aynada, Bir başkasında nefes alıyorum, Bu eller bu gözler benim deği,l Dudakların ...', ARRAY['Türk Edebiyatı','Şiir','Banu Yılmaz']::text[], 8.5, '{"poet":"Banu Yılmaz","poet_slug":"banu-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-yabanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadıklarımdan Öğrendiğim Bir Şey Var', 'yasadiklarimdan-ogrendigim-bir-sey-var-ataol-behramoglu-mafsq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşadıklarımdan öğrendiğim bir şey var: 

Yaşadın mı, yoğunluğuna yaşayacaksın bir şeyi

Sevgilin bitkin kalmalı öpülmekten

Sen bitkin düşmelisin koklamaktan bir çiçeği

İnsan saatlerce bakabilir gökyüzüne

Denize saatlerce bakabilir, bir kuşa, bir çocuğa

Yaşamak yeryüzünde, onunla karışmaktır

Kopmaz kökler salmaktır oraya

Kucakladın mı sımsıkı kucaklayacaksın arkadaşını

Kavgaya tüm kaslarınla, gövdenle, tutkunla gireceksin

Ve uzandın mı bir kez sımsıcak kumlara

Bir kum tanesi gibi, bir yaprak gibi, bir taş gibi dinleneceksin

İnsan bütün güzel müzikleri dinlemeli alabildiğine

Hem de tüm benliği seslerle, ezgilerle dolarcasına

İnsan balıklama dalmalı içine hayatın

Bir kayadan zümrüt bir denize dalarcasına

Uzak ülkeler çekmeli seni, tanımadığın insanlar

Bütün kitapları okumak, bütün hayatları tanımak arzusuyla yanmalısın

Değişmemelisin hiçbir seyle bir bardak su içmenin mutluluğunu

Fakat ne kadar sevinç varsa yaşamak özlemiyle dolmalısın

Ve kederi de yaşamalısın, namusluca, bütün benliğinle

Çünkü acılar da, sevinçler gibi olgunlaştırır insanı

Kanın karışmalı hayatın büyük dolaşımına

Dolaşmalı damarlarında hayatın sonsuz taze kanı

Yaşadıklarımdan öğrendiğim bir şey var: 

Yaşadın mı büyük yaşayacaksın, ırmaklara, göğe, bütün evrene karışırcasına

Çünkü ömür dediğimiz şey, hayata sunulmuş bir armağandır

Ve hayat, sunulmuş bir armağandır insana.', 'Yaşadıklarımdan öğrendiğim bir şey var:  Yaşadın mı, yoğunluğuna yaşayacaksın bir şeyi Sevgilin bitkin kalmalı öpülmekten Sen bitkin düşmeli...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasadiklarimdan-ogrendigim-bir-sey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahramanlar Erken Ölür', 'kahramanlar-erken-olur-hakan-kiziltan-sixs2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşanacak günlerimiz vardı seninle daha

Yapılacak işlerimiz

Duyulacak sözlerimiz

Görülecek yerlerimiz 

Sorulacak hesaplarımız vardı seninle dayıcım

Bir gün uyandığımda yalnızdım

Yapılacak işlerimi unuttum

Gidilecek yerler kayboldu

Ama bir şey öğrendim

Yaşam vardı 

Ben vardım

Ve sen dayıcım ne kadar uzakta olsanda bu diyardan

Sen varsın yanımda

Ve hep olacaksın', 'Yaşanacak günlerimiz vardı seninle daha Yapılacak işlerimiz Duyulacak sözlerimiz Görülecek yerlerimiz  Sorulacak hesaplarımız vardı seninle ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kızıltan']::text[], 8.5, '{"poet":"Hakan Kızıltan","poet_slug":"hakan-kiziltan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kahramanlar-erken-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-banu-yilmaz-0x5tx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen,

Küçük bir çocuk gibiyim senin yanında.

Üşüdüğüm an eriyip gitmem kollarının arasında,

Üzüldüğüm zaman göğsüne yaslanıp hıçkırarak ağlamam,

Mutlu olduğumda öpücüklerlr boynuna sarılmam...

Senin yanında olmak tek çocukluğum,

En büyük mutluluğum...

(eylül/1999)', 'Bazen, Küçük bir çocuk gibiyim senin yanında. Üşüdüğüm an eriyip gitmem kollarının arasında, Üzüldüğüm zaman göğsüne yaslanıp hıçkırarak ağl...', ARRAY['Türk Edebiyatı','Şiir','Banu Yılmaz']::text[], 8.5, '{"poet":"Banu Yılmaz","poet_slug":"banu-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuklugum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-ustun-cakir-8b3je', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yar

Bir anda seni unutmak istedim

Kalbimden çıkarıp fırlatmak istedim

Acıların en büyüğünü yaşatmak istedim

Sana olan aşkım izin vermedi yar

Resmini tutuşturp yakmak istedim

Hatıraları silip unutmak istedim

Hayallerimden sıyırıp atmak istedim

Sana olan aşkım izin vermedi yar

Gözlerine bakıp haykırmak istedim

En acı sözleri söylemek istedim

Güller gibi solduğunu görmek istedim

Sana olan aşkım izin vermedi yar

Seni terkedip gitmek istedim

Bir başka güzeli sevmek istedim

Kendimi atıp ölmek istedim

Sana olan aşkım izin vermedi yar', 'Yar Bir anda seni unutmak istedim Kalbimden çıkarıp fırlatmak istedim Acıların en büyüğünü yaşatmak istedim Sana olan aşkım izin vermedi yar...', ARRAY['Türk Edebiyatı','Şiir','Üstün Çakır']::text[], 8.5, '{"poet":"Üstün Çakır","poet_slug":"ustun-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm Diyorum', 'omrum-diyorum-ahmet-telli-l5ps5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzgün bir çocuğun yalnızlığı

Kadar saydam kalabilseydim

Ömrüm derdim ömrüm nasıl da

Dolu geçmiştir ölebilirim artık

Ölüm hiç de ürkünç gelmiyor

Yaşanmışsa tüm yaşanacaklar

Acı yitiriyor anlamını ve renkler

Kül oluyor körleşirken gökboşluğu

Bu dünya dünya mıdır hani

Bildiğimiz o yamyam küresi

Ki apiz öküzlerinin çekip durduğu 

Bir cansıkıntısıydı önceleri

Hantal ve gürültücü bir tehdit

Gibi düşüyorken üstümüze

Alaycı bir gülüş takılıyor yalnız

Dudaklarımın hüzün kıvamına

Ömrüm diyorum şimdi ömrüm 

Üzgün bir çocuksun sen ve yalnız

Öyle kal çünkü bu dünyada

Sana en çok mutsuzluk yakışıyor', 'Üzgün bir çocuğun yalnızlığı Kadar saydam kalabilseydim Ömrüm derdim ömrüm nasıl da Dolu geçmiştir ölebilirim artık Ölüm hiç de ürkünç gelmi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/omrum-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmelisin''! ! ''', 'bilmelisin-turgut-yuca-72crx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahhh ahh içimdeki bu acı 

Kim dindirebilir, yada kim uğraşır benimle? 

Kim değiştirebilir bu çarkın dönüşünü? 

Ben yine o adam işte

İçimdeki beni bilemesende

Sanki bilmek istesen; bilemesen

Seni bilsen o yeterde

Ne olursa olsun sen beni bilsen

Görmesen de gözlerimde

Sana olan duyguları

Hissetmesen bile bütün korkuları

Sana olan kinimi bilmesen 

Bir fırtınada kalmış bir gül.

Yaprakları tek tek düşse bile,

Üzerinde sadece dikeni kalsa bile,

Sen bilsen onun bir gülün dikeni olduğunu

Sen o dikenleri yüreğime bilesen,

Hiç bilmesem ben seni

Görmesem;  sadece sesini

Sen bilmezsen ama sadece yüreğimi

Bütün gece yanımda olsan 

Ama bilmesen geldiğini

Bütün gece içimi acıtsan 

Ama silmesen gözlerimi.

Bütün aşklarımı yırtıp atsan

Bütün aşıklarımı; 

Ve senin bütününü bilmesem

Ve senin herşeyini bilebilsem

Sadece toprak mı olsam yoksa? 

Sadece su mu? 

Yada sadece bir çocuk hem toprak hem su

Ağlasam sadece sen bilmesen.

Aşk..Nedir bilmesem 

Bilmesem gözlerin ne renk

Bilmesem ben sen ne demek

Sen..Hırçın sonbaharın Deli yaprağı olsan

Bilmesen düştüğünü

Göremeden bir daha yazı

Yorgun akşamlar gibi

Solgun yüzlerimizde okunan

Bütün derbederlikler gibi

Seni bir unutsam...

Seni bir unutmasam...', 'Ahhh ahh içimdeki bu acı  Kim dindirebilir, yada kim uğraşır benimle?  Kim değiştirebilir bu çarkın dönüşünü?  Ben yine o adam işte İçimdeki...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bilmelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-i-lhan-palali-arliq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretin akşamı kolluyor gündüz,

Bu işin çaresi yok gibi canım...

Bakışın o denli kayıtsız, dümdüz,

Sözlerin bağrıma ok gibi canım...

Daha ne; susmuşsa hayırsız dilim? 

Özür dileniyor hasret mendilim...

Kelebekler kadar titrektir kalbim,

Bir gülüşün bile çok gibi canım...

Dünya dönüp durur böylece, niçin? 

Düşmüşüm ardına meğer bir hiçin.

Hakkını helâl et, üzdüğüm için,

Bu sevdan başımda tâk gibi canım...

Gelmenle güzellik ufka serilir,

Virane gemime liman verilir,

Buz tutmuş dilekler çözülür, erir,

Seninle siyahlar, ak gibi canım...', 'Hasretin akşamı kolluyor gündüz, Bu işin çaresi yok gibi canım... Bakışın o denli kayıtsız, dümdüz, Sözlerin bağrıma ok gibi canım... Daha n...', ARRAY['Türk Edebiyatı','Şiir','İlhan Palalı']::text[], 8.5, '{"poet":"İlhan Palalı","poet_slug":"i-lhan-palali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmbat', 'i-mbat-i-lhan-palali-kn1dw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğe cân geldi imbât sesinden,

Bir lâhza demeden tanışık oldum.

Geceme hürriyet verdim günlerden,

Sıyrıldım öfkeden, düştüm, savruldum; 

Temâsı gerekti bana güllerden,

Ne sordum yollara, ne de soruldum...

Benzime kan geldi, serde heyecân,

Hasreti kökünden biçtin, bitirdin! 

Ufacık mutluluk zevke heyelân; 

El ettin ömrüme; güle çevirdin,

Lidersin sürüye bense bir yalan,

Mutlu duyguları sele çevirdin...

Duyguma han geldi, bittim demeden; 

Bilmem ki umut mu zorda ellerin? 

Bunalan gönlümü açtı penceren:

Ateşler bu gece serin mi serin,

Hoşgeldin; gülünce bana ses veren; 

Seninle doluyum, gönlümde yerin...', 'Yüreğe cân geldi imbât sesinden, Bir lâhza demeden tanışık oldum. Geceme hürriyet verdim günlerden, Sıyrıldım öfkeden, düştüm, savruldum;  T...', ARRAY['Türk Edebiyatı','Şiir','İlhan Palalı']::text[], 8.5, '{"poet":"İlhan Palalı","poet_slug":"i-lhan-palali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/imbat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
