INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Yazdım', 'adini-yazdim-senay-erdogan-vuno1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimin içine adını yazdım

Benden başka kimse sevmesin diye

Uçan kuştan bile seni kıskandım,

Benden başka kimse görmesin diye.

Gizlerim seni ben ömrüm boyunca,

Hiç kimse seni bilmesin diye.

Adını yazdım ben boylu boyunca 

İçinden kimse silmesin diye

Bir gün gidersen inan ölürüm,

Dualar ettim gitmesin diye

Her gece rüyamda seni görürüm,

Uyanmam ben rüyam bitmesin diye', 'Kalbimin içine adını yazdım Benden başka kimse sevmesin diye Uçan kuştan bile seni kıskandım, Benden başka kimse görmesin diye. Gizlerim sen...', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adini-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-guner-karabulut-5su9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sen kaldın beni terketmedik,

Seninle geçti çocukluğum, gençliğim

Seninle geçiyor yaşlılığım.

Nice dostlar,sevgililer terkedip gitti de,

Sen hiç gölge düşürmedin sadakatine.

İğne atsan yere düşmez kalabalıklarda bile,

Sessizce gelip oturdun yüreğime.

Çatladı dudaklarım da kimse farketmedi susuzluğum,

Yine seninle geçti geceler boyu uykusuzluğum.

Zaman zaman olduysa da şikayetim, vefasızlığım;

Bir sen, bir sen kaldın beni teketmedik yalnızlığım.', 'Bir sen kaldın beni terketmedik, Seninle geçti çocukluğum, gençliğim Seninle geçiyor yaşlılığım. Nice dostlar,sevgililer terkedip gitti de, ...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalnizligim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künyem', 'kunyem-guner-karabulut-vzba5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adım: Mehmet,

Memleketim: Türkeli

At sırtında doğmuşum ben.

Onun için yazmaz nüfusumda doğum yeri

Takvim yokmuş benim doğduğum çağlarda.

Anam bilmezdi seneleri, günleri.

Ne zaman sorsam;geçmişe dalar da,

Tarihle yaşıt olduğumu söylerdi.

Nice tahtlar,nice taçlar eğildiler önümde.

Nice rütbeler,mertebeler geçti elime.

Hepsini ulusuma armağan ettim de,

Bir şehadet mertebesini ayırdım kendime.

Nasibim çok boldu lakap’tan addan yana.

Her adımla bir döneme hükmettim.

Altaylar’da Atilla,

Malazgirt’de Alpaslan,

Niğbolu’da ‘Doğan’ dediler bana.

Ama ben hep aynı Mehmettim.

Genç Osmandı adım Bağdat seferine çıkarken.

Bizans  önlerinde  Ulubatlı Hasan’dım.

İstanbul surlarına bayrağı dikerken,

Bir çağı açtım,bir çağı kapattım.

Yahya çavuştum Gelibolu yaylasında.

Ateş yedim yedi düvel, dört cepheden.

Etten duvar örüp de boğazın iki yakasına.

Geçirmedim düşmanı Çanakkele’den.

Gün geldi; güneş tutuldu.

Bir kabus gibi üzerimize çöktü karabulutlar

Dört bir yandan düşmana kaptırdık yurdu

Karardı Türklük dünyası, söndü umutlar

İşte  o zaman,

Bir kök gibi saldım da kollarımı Anadolu topraklarına

Beslenip,eski gücümü yeniden buldum

Beslendikçe büyüdüm,sığmaz oldum kabıma

Büyüdüm,büyüdüm,büyüdüm; M.Kemal oldum

Bu künyeyle yayıldı tarihe benim  adım

Her devirde ülkem üzerinde bir nöbetçiyim

Kısa künyemi sorarsan komutanım,

Ben; MEHMETÇİĞİM', 'Adım: Mehmet, Memleketim: Türkeli At sırtında doğmuşum ben. Onun için yazmaz nüfusumda doğum yeri Takvim yokmuş benim doğduğum çağlarda. Ana...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/kunyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-guner-karabulut-5g0wi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldırma  güzel  çocuk, aldırma sen annene

Koş, bağır,yorul,terle hayat senin kime ne

Yorululunca uzanıp sırtüstü  çimenlere,

Bin uçanhalına da sür istediğin yere .

Bu sihirli bir çağdır, uçanhalın yat olur 

Bindiğin ince çubuk, bir küheylan at olur

Toplum örmeden daha ayıp,günah ağını

Fırsatı değerlendir yaşa altın çağını

Özgürlüğünü yaşa, elinden alınmadan

Masallarını yaşa, sihirler bozulmadan

Yaşa her yaptığının hesabı sorulmadan 

Elindeki dizginler ağzına vurulmadan', 'Aldırma  güzel  çocuk, aldırma sen annene Koş, bağır,yorul,terle hayat senin kime ne Yorululunca uzanıp sırtüstü  çimenlere, Bin uçanhalına ...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet', 'cennet-guner-karabulut-259jw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aslında ne havva vardı,ne de adem

Cennet tümüyle çocuklara emanetti

Ne yaramazlık yaptılar bilmem

Tanrı onları büyümeye mahkum etti', 'Aslında ne havva vardı,ne de adem Cennet tümüyle çocuklara emanetti Ne yaramazlık yaptılar bilmem Tanrı onları büyümeye mahkum etti...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosnalı Çocuk', 'bosnali-cocuk-guner-karabulut-dt8b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsenin oyuncağını kırmamıştı.

Almamıştı kimsenin bebeğini elinden

Öyleyse neden?

Yağmur yağmur kurşunlar geçiyordu üzerinden

Ellerinde tüfekler,tabancalar,

Kocaman,kocaman amcalar,

O dövmemiştiki onların çocuklarını.

Hatta  tanımıyordu bile onları.

Bak işte göğsüne gelmişti kurşunun biri.

Ne de çok kanıyordu.

Yarası sızlıyor, yarası yanıyordu.

Parmağı kanamıştı daha önce.

Ama bu kadar acımamıştı.

Kardeşi kesmişti bilmeden.

Ne de çok ağlamıştı.

Şimdi ağlıyamıyordu.

Kızar mıydı acep annesi kanlanan elbisesine?

Daha yeni alınmıştı da.

Dayısı almıştı yaşgününe.

O gece hiç çıkamamıştı.

Üstelik annesiyle yatmıştı bütün gece.

Ne de çok sevinmişti .

Sahi;annesi nerelerdeydi?

Neden onu almıyordu kucağına?

Neden bastırmıyordu başını,

Sıcacık göğsüne?

Bak üşüyordu

Neden onu bir türlü göremedi?

Bosnalı çocuk bunu hiç öğrenemedi', 'Kimsenin oyuncağını kırmamıştı. Almamıştı kimsenin bebeğini elinden Öyleyse neden? Yağmur yağmur kurşunlar geçiyordu üzerinden Ellerinde tüf...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bosnali-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyhat', 'heyhat-hasan-ahmed-gokce-2e7da', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Heyhat geçiyor hayat

Gönül göz arasında

Bu ne nâçâr nakarat

Acziyet tarlasında...', 'Heyhat geçiyor hayat Gönül göz arasında Bu ne nâçâr nakarat Acziyet tarlasında......', ARRAY['Türk Edebiyatı','Şiir','Hasan Ahmed Gökçe']::text[], 8.5, '{"poet":"Hasan Ahmed Gökçe","poet_slug":"hasan-ahmed-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/heyhat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sen ve Ben', 'i-stanbul-sen-ve-ben-aliye-ozlu-bja0g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul sen ve ben

Sabahın ilk saatleri olacaktı

Ne kadar ağlayacaktık

Ölmeden önceki halimize

Nekadar dağıtacaktık

Çocukluğumuzu caddelere

Ne kadar ağlayacaktık

Çocukluğumuza

Bir balerin dansedecekti

Bu şehir bize dar gelecekti

Ayrılmalıyız artık diyecektik

Ah ölüler 

Ne kadar pişmanlık duyarsak

O kadar görkemli olur

Cenaze törenleri

Ne kadar pişmanlık duyarsak

O kadar sevişemeyiz

Bedenlerimiz titrer

Bir balerin dans edemez

Felç olur

Anılar zinciri bir bir sökünür

Çocukluğumuz caddelere dökülür

Gökyüzü kırmızılara bürünür

Herşey ama herşey 

Alır başını gider

Bir biz kalırız

İstanbul, sen ve ben.

İstanbul

....1997', 'İstanbul sen ve ben Sabahın ilk saatleri olacaktı Ne kadar ağlayacaktık Ölmeden önceki halimize Nekadar dağıtacaktık Çocukluğumuzu caddelere...', ARRAY['Türk Edebiyatı','Şiir','Aliye Özlü']::text[], 8.5, '{"poet":"Aliye Özlü","poet_slug":"aliye-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-sen-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-necip-fazil-kisakurek-k4nkt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıçak soksan gölgeme,

Sıcacık kanım damlar.

Gir de bak bir ülkeme:

Başsız başsız adamlar...

Ağlayın, su yükselsin! 

Belki kurtulur gemi.

Anne, seccaden gelsin; 

Bize dua et, emi!', 'Bıçak soksan gölgeme, Sıcacık kanım damlar. Gir de bak bir ülkeme: Başsız başsız adamlar... Ağlayın, su yükselsin!  Belki kurtulur gemi. Ann...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dua-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Kar Prensesi', 'kirmizi-kar-prensesi-atilgan-alemdar-dci5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kırmızı kar prensesi

saç ve dudak şarap gibi

fakat içmeden sarhoş eder

bakışları samyeli

değdiği yeri mühürler

göz değil kezzap gibi

kırmızı kar prensesi

sanki buz tutmuş elleri

tutmak için güneşi bekler

tutkunun canlı heykeli

unutup geceden düşer

tıpatıp maytap gibi

kırmızı kar prensesi

ona bakmak azap gibi

bakmasam da rüyama girer

gökten inmiş kitap gibi

beni cennete zincirler 

boşaltıp cehennemi

kırmızı kar prensesi', 'kırmızı kar prensesi saç ve dudak şarap gibi fakat içmeden sarhoş eder bakışları samyeli değdiği yeri mühürler göz değil kezzap gibi kırmızı...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirmizi-kar-prensesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zegissia', 'zegissia-atilgan-alemdar-ctvn6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yunanistan’ın adriyatik’e bakan kısmında

adını anlamazsınız bir şehir vardır, ışıklı

geceleri,düşen yıldızların uğrak yeri gibidir

yunanistan’ın adriyatik’e bakan kısmında

adını bilmediğim bir kız vardır sarışın

liman barında şarkı söyler dans eder

zegissia dedim,olur dedi gözlerini sakladı

türkleri hiç sevmezmiş lâz’ım dedim kurtuldum

oturduk bir kenara gemi dolu şarap içtik (gemi gibi harab olduk)

adını inkâr ettiğim bir duygu vardır,sancılı

yunanistan’ın adriyatik’e bakan kısmında

geldi bağrımın ortasına saplandı

sanki denizin dibine açılmış gizli bir delik

bütün sularımı(duygularımı)   yavaş yavaş içine çeker

ayda en az bir sefer taş çatlar olur iki

adını anlamazsınız bir şehir vardır,ışıklı

yoluma düşer iş icabı bir kaç gün konaklarım

yunanistan’ın adriyatik’e bakan kısmında

gözleri mat mavi sarışın bir kadın çeker beni

adını zegissia koydum bir sebebi vardır mutlaka

sesi çocuk yüzü çocuk...maalesef kalbi yarım

liman barında şarkı söyler dans eder', 'yunanistan’ın adriyatik’e bakan kısmında adını anlamazsınız bir şehir vardır, ışıklı geceleri,düşen yıldızların uğrak yeri gibidir yunanista...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zegissia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldu ve Bitti', 'oldu-ve-bitti-ali-mesut-haydaroglu-rom0i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O gün işte o gün cesaretlenmiştim ki 

İşte o gün vazgeçmiştim sevgimden

O gün yıkmıştın beni

Yıllarca unutamamıştım senin 

Katma değer sevgini

Kazıyamadım kalbimden

Sevginin derin izini ve büyük baş harfini

Mezardayken yalnız değildim

Kalbimdeki Aşkınla, o hiç sönmeyen

Aksine günden güne alevlenen

Vücudumu sarıp içimi yakan

O yüce aşkımla birlikteydim...', 'O gün işte o gün cesaretlenmiştim ki  İşte o gün vazgeçmiştim sevgimden O gün yıkmıştın beni Yıllarca unutamamıştım senin  Katma değer sevgi...', ARRAY['Türk Edebiyatı','Şiir','Ali Mesut Haydaroğlu']::text[], 8.5, '{"poet":"Ali Mesut Haydaroğlu","poet_slug":"ali-mesut-haydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oldu-ve-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar', 'yarinlar-riza-aslan-952hd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yarınlar yarınsız kaldı

sebebini hiç bir zaman anlayamadan

hiç kimseye anlatamadan

suçlamak boşuna 

nafile ortaya atılan onca gerçekler

nafile sömürülen onca yürek

nafile sensizlik

bitmez hiç bir zaman bunlar

belirsizliği benliğini kahretsede

bitmez

hep yarım kalır yaşananlar

her bir yarım ayrı diyarlara gider

ve hiç bir zaman birleşmezler', 'yarınlar yarınsız kaldı sebebini hiç bir zaman anlayamadan hiç kimseye anlatamadan suçlamak boşuna  nafile ortaya atılan onca gerçekler nafi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmreniyorum Masumluğuna', 'i-mreniyorum-masumluguna-hasan-sutay-9nf16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevincini gördüm

Işıl ışıl gülen gözlerinde

Gizlemediğin belliydi

Yaşama sevincini.

Anlıyorum habersizsin

Gelecek günlerden.

Bulaşmamışsın gündelik dertlere.

Bize gelince...

Nelere üzülüyoruz

Ağlıyoruz nelere.

Sen yine yaşayadur

Güzel günler hayalinle.

İnan çok daha güzelsin hayatın

Bu masum halinle.

Gülen gözlerin ve masumluğunla

Bize ümit veriyor

Hayat bağışlıyorsun anla.

Bir çirkef hayata

Bin nefretle bakarak iğreniyorum.

Sen yine her şeyden habersizsin ama

Ben sana imreniyorum.

İmreniyorum masumluğuna.', 'Sevincini gördüm Işıl ışıl gülen gözlerinde Gizlemediğin belliydi Yaşama sevincini. Anlıyorum habersizsin Gelecek günlerden. Bulaşmamışsın g...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sutay']::text[], 8.5, '{"poet":"Hasan Sutay","poet_slug":"hasan-sutay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/imreniyorum-masumluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heber Yahut Galata', 'heber-yahut-galata-atilhan-buyuksel-3bll1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Asilmaz bir kale koruyor seni 

Haybersin galata kesfim zor seni 

Ne top ne gülleler hayreder sana 

Kat kat duvarlar ne yol gider sana 

Alti milyari nedir sirri gütmenin 

Bir düdük ayni yöne gitmenin 

En bizdeni niçin bekçidir sana 

En akillisindan en sarlatana 

Korur seni geçilmez ordular 

Ve etten kemikten duvar oldular 

Ya nasil yikayim hayber kaleni 

Ya haybersin desem kim duyar beni 

Yahudi rum mason çingenelerin 

Içimizde kalen bilinmez yerin 

Hayber görünmez bela atar cirit 

Uyur gezer vatan kurtaran yigit 

Kasdeder kim sana bulursun hayber 

Gider gümbürtüye duyulmaz haber 

Bin it bulursun sahit bulamam 

Oyunu bozmaya yigit bulamam 

Olmadik suçla iftira atarsin 

Bir yalana binbir yalan katarsin 

Galata bilsem seni anlatamam 

Kisalir ömrü kim anlatirki tam 

Çamur atar izi kalir suç kalir 

Hayber diyen ekmege muhtaç kalir 

Sana dil uzatani bulamazsan 

Geçer kilinir beynelmilel yasan 

Basa iner geçilmez gümrüklerin 

Dar gelir dünya kirmizi bülltenin 

Bir dokunan bin bela alir basa 

Söndürür hayati sizlamak bosa 

Ya faili meçhule kurban gider 

Gaza süsüyle felç olur yan gider 

Susar akrep içgüdülü güçlerin 

Delilsiz gizli kalir ipuçlarin 

Ya asilir alkisa duyan gider 

Üstüne siyah çelenk koyan gider 

Uçkuru çözülmedik bir iftira 

Verirsin balans ayari muhtira 

Sincandan tas atsam surun sarsilir 

En uyuz it ürür öne atilir 

Dokunsam ciyak ciyak seslenir 

Telawiw newyork romadan ses gelir 

Bizim itleri geçsem sizin ipler 

Geçit vermez vatan kurtaran tipler 

Bütün alem muzdarip nerde varsan 

Filistin afrika asya hindistan 

Sahil sehir limanlarda burçlarin 

Her devlet içinde gizli uçlarin 

Tiyatro oynamak tek maharetin 

Oynatirsin bizi pek az külfetin 

Benzer düsmanin süt dökmüs kediye 

Hizmetine bahsedilmis hediye 

Yeriyorken hosgörü dehasi var 

Ayakta uyur musamahasi var 

Kundaga kasdeder benim düsmanim 

Sefalet içharb kan dolu vatanim 

Yak fitne atesi horoz bogustur 

Sen geri çekil sevin el ogustur 

Adini desem yasak düsmanimin 

Bahti bu milletimin vatanimin 

Boyadin gözü igrenci sik ettin 

Akillarimizi karmasik ettin 

Gözün en ücra kösede heryerde 

Borç takarsin dogmayan bebegede 

Ne zormus meger milyonu beslemek 

Milyar ari gibi çalissin demek 

Alemin kazanci kesbi kasasi 

Cebinde fonu bilmem ne borsasi 

Sabahtan müreffeh abad edersin 

Aksama felceder berbad edersin 

Hem kan akidir insaf hem soyarsin 

Hayber fesadinla heryerde varsin 

Akrepte zehiri bana yaziklar 

Maharet zanneden bayraktarim var 

Alemin tevessül etmedigini 

Isleyen kavimsin isledigini 

Varmi isleyen kavim ey galata 

Kusat alemi yayil her tarafta 

Bir ucun londra paris atina 

Otur milletlerin karabahtina 

Yutarsin her devleti bütçesiyle 

Hanedani hani sehzadesiyle 

Yetmez iç harble kasdedersin cana 

Don biçersin hayber ta dogmayana 

Bilinmedik asilmadik kalesin 

Her yerde galata sulu kulesin 

Ta karaköyden tohumu atarsin 

Gelecege yön verir fal bakarin 

Uzanir soyun ta eski misira 

Eski yunan karaim yanisira 

Küfret yetmis iki millete çit yok 

Adin demek suç fislemeyen it yok 

Buçuk millet her milletin hayberi 

Bizim hayber köhne bizanstan beri 

Limanlardan gelir fuhus fitnesiyle 

Her millte milletin kisvesiyle 

Adin baska olur nufusun baska 

Kiliga girer renk bulursun baska 

Bin yil geçer akrep baskalasmazsin 

Hayber nere gitsen fitneye bassin 

Nerde bir gülistan görsen bozarsin 

Bozar tahrib eder sahib çikarsin 

Her rezalet degismez fitratina 

Uyar hayber tükürsem suratina 

Akrep gibi yavassin sabirlisin 

Kan içersin dünya ile hirlisin 

Becerin yok yarimsin karlisin 

Yilan gibi yer altinda sirlisin 

Edep sanat yok zeka kusurlusun 

Fesandinla nasil böyle zorlusun 

Oldugun yer kan kokar olur bizar 

Usanirdirir insan canindan bezer 

Bozulacak bütün oyun alemde 

Bekle maya tuttu pek yakin hemde', 'Asilmaz bir kale koruyor seni  Haybersin galata kesfim zor seni  Ne top ne gülleler hayreder sana  Kat kat duvarlar ne yol gider sana  Alti ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/heber-yahut-galata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Devlet Yahut Bizans', 'derin-devlet-yahut-bizans-atilhan-buyuksel-fz7lt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizi ite itide ite bogduran bizans 

Üstüne varani vatan vatan kogduran bizans 

Malazgirtte onu içimizde eridi sandik 

Köhne Bizansin kirli davadan usandik 

Yilan gibi tohumu atar kus yuvasina 

Yavrusu zehir verir yavrunun en hasina 

Yavru yilani biz sanip biz diye sarilan 

Bizim yavruya desemki bu yavru yilan 

Bizden it bulur üstüme bütün gücüyle 

Gelir eski kini tükenmeyen öcüyle 

Bir yalaga bizi ite sesziz kirdirir 

Tutar ite itide bedelsiz kirdirir 

Kimi ülküdas kimi vatansever vatandas 

Bizimsin ne diyem hain diyemem gardas 

Beddua edemem koyun gibi güdülüsün 

Koçlari seçilmis darma daganik sürüsün 

Rum oyununa kafan kuma gömülüsün 

Kasabin ardisira yigin yigin yürüsün 

Koyunum bize hain dedin hamasetinle 

Ruma rum diyemedin basindaki itinle 

Bin yol bulsa galatali bin yola gidersin 

Bir yol göstereni tazi gibi ezersin 

Bozdular dilim tutuk derdimi anlatamam 

Bende edemem tam taptirir bizans bir tamam 

Kime gomonos dedi kimine mürrteci 

O degil bu degil kardesim sor su rum neci 

Çevirdi dilimi galatanin agopçaya 

Benzetir dinimi sapik dini ortadokçaya 

Bizans baska yol bulur yolun sonu gelmeden 

Sen saga ben sola baska yoldan gitti deden 

Bir o sokaga döner bu sokaga çevirir 

Yolu unutturur sasirtir daga çevirir 

Yolu yoktu babanin saskin saskin gezerdi 

Yolunu kaybettirirdi bizans hem ezerdi 

Uyursan beni sola seni saga götürür 

Yazik degilmi torunununu daga götürür 

Hazir kardesim torunun torununa yol 

Bitmez sapik yolu bizansin her sorana yol 

Bize bölücü diyen bine böldü yolumu 

Düsman etti kardesi tutmaz etti kolumu 

Uyanda kardesim avciya bir haykirsana 

Soyup yurdunu her sokaga tuzak kurana', 'Bizi ite itide ite bogduran bizans  Üstüne varani vatan vatan kogduran bizans  Malazgirtte onu içimizde eridi sandik  Köhne Bizansin kirli d...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/derin-devlet-yahut-bizans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kökü Derin Devlet', 'koku-derin-devlet-atilhan-buyuksel-j8vkl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca asikar bunca gizlinin 

Ilmini bilip sezmis degilim 

Ne seyyah olmusum su alemin 

Sirrina erip gezmis degilim 

Bunca zehirin bunca yilanin 

Tefeci defiyle bizi soyanin 

Yilan gözlünün zehir ciyanin 

Üstüne varip ezmis degilim 

Geni degisik ceni degisik 

Kani degisik teni degisik 

Kimya fizigi feni degisik 

Ayridir deyip sezmis degilim 

Kandirip bizden isim devsiren 

Saklar culunu culuma giren 

Yilana bak horoz dögüstüren 

Tiksinip yine tezmis degilim 

Ah su yd.....böyle igreti 

Bozar barisi iyi niyeti 

Yalan yanlisi sahte ögreti 

Misliyle deyi azmis degilim 

Sermaya katlar kita kundaklar 

Sucsuzu asip sucluyu aklar 

Hürriyet deyip kitap yasaklar 

Yine barisi bozmus degilim 

Agzi salyali kusmugu yerde 

Bilimi fenni teknigi nerde 

Füzeyi yapip aya giderde 

Tutup yolunu kazmis degilim 

Giden senmisin aya uzaya 

Kalan benmiyim yürüyen yaya 

Fareden ilac domuzdan maya 

Söyleyip cizip yazmis degilim 

Yd. yasa türk gibi görün 

Türkün adina culuna bürün 

Sanmaki bu is derdi bugünün 

Degil asirlar sormus degilim 

Kundakla gelip saraya sizmis 

Akilliyi bogup araya sizmis 

Hösgörü deyip azdikça azmis 

Tahammülüm hos görmüs degilim', 'Bunca asikar bunca gizlinin  Ilmini bilip sezmis degilim  Ne seyyah olmusum su alemin  Sirrina erip gezmis degilim  Bunca zehirin bunca yila...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/koku-derin-devlet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laikçe Bir Soru', 'laikce-bir-soru-atilhan-buyuksel-8mlky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Laik soru sorsam laik cevap gelirmi 

Zehir yoksa ya iftira ya sus denirmi 

Su gerici osmanlinin her on veziri 

Üçü cifitti dördü dönme rumdu biri 

Bazan yörükten bize türk olurdu pasa 

Ya zehirlenir ya bela alirdi basa 

Rum vezir efendim hünkar ciger köseniz 

Derdi hain imis satti sizi pasaniz 

Vatan selameti için asmak gerektir 

Acimayin hünkar demek aslan yürektir 

Iftira yer yörük pasa ipe giderdi 

Suçlu bilirdi kendini bilmezdi derdi 

Uzat basi kurtulacak türkün devleti 

Görünmezdi kan kusturan dönme illeti 

Böyle idi saray devlet devlet içinde 

Basi biz ip yahudinin dönme piçinde 

Ag gibi örülmüs kollari yahudi rum 

Bize kan kusturan ahtapot gizli kurum 

Ya su laik devletin hiç yokmu içinde 

Yoksa gayretmi yok cifit dönme piçinde 

Cifit yokmu sizsin devlete türk kan kusa 

Kisirmi soyu yokmu dönme cifit yoksa 

Sizsin ta oba oba sizsin bucak bucak 

Her köseye tohum atsin sönsün her ocak 

Padisahi halleden varya dönme guruh 

O gün gazinin ardina sigindilar yuh 

Onuda kullanip zehir verdiler yine 

Sanma ne ona dostturlar ne obirkine 

Dönme guruh ismetle kusatti gaziyi 

Atiyi kusatip yokettiler maziyi 

Akrep basamaklari agir agir çikar 

Bes asir hedefte ne usanir ne bikar 

Bir asirda onu ziddi gösterir bunun 

Ikinci asir düsmani savundugunun 

Üçüncü asir yol yakindir hedefine 

Hafizai beser biz o usanmaz yine 

Dördüncü asirda çepeçevre kusatir 

Besinci asirda sefaleti yasatir 

Ve o gün kaleleri yikar birer birer 

Katliam olur ne kadin kalir ne bir er 

Hayberde iz kaybedersin gelir siirtten 

Payitahtta ispanya selanik giritten 

Akreb bir kavimsin kini bin yil sürüktür 

Iz kaybeden bir milletin derdi büyüktür 

Nasil bilmece bu tiyatroyu kim çöze 

Alim yok nesep kim bilir iner kim öze 

Oba oba kusatilmisiz liman liman 

Nerde Eyub Timurhan kalksin bu sis duman 

Hastahanede nesli felceder sizinca 

Basinla kan döker yalan haber yazinca 

Hariciye bize iranli düsman bulur 

Dünya disinda karanlik alem kurulur 

Adliye düsmani astigi alimlerin 

Brokrasi odagi karanlik islerin 

Cifitla yasamin bu kardesim bedeli 

Geri biraktilar nesli ifsat edeli 

Heleki olmaz pontus hocayla bu isler 

Haldunla açilsin gizli yollar kesifler 

Yol göstirir timura yikar tüm burçlari 

Fravunun içimizde hain uçlari 

Gizler çehre dönme en asil türk edasi 

Millet susturan medya cifit gür sedasi 

Ele geçirmis gizli devlet kurumlari 

Bizans azinligi dönme cifit rumlari 

Açilmaz bir kapi dur diyecek gidise 

Der cifit kirve ihtisas gerek bu ise 

Burokrasi emanettir cifit dönmeye 

Milletim asirlar rahat yüzü görmeye 

Dilimizi ar eyler verin galataya 

Bu arabcadir o farsca dil kurtulur guya 

Camion kirko kasa gelsin masa 

Gitsin mesreb mahkum olsun tasa 

Bunlar hangi çagdas milletin dili 

Geldi galatadan öz türkçemiz gideli 

Portekizden geldi bizden türk su dönmeler 

Araba farsa yuh yahudiye övmeler 

Atalim arabcayi farsacayi ya Türkce 

Demek ari oldu galatadan gelince 

Öz Türkce diyen galata ehli oldu dilimin 

Meger ne gündür merkezi imis bilimin 

Yol gösterdin fersah fersah ileri 

Gitmisizde bak su dünya pek geri 

Gönlümüz hos türkümüz musiki olali 

Bildik onuda sulukleye sorali 

Sulukule yasa galata sen olmasan 

Böyle güllük gülistan olurmu vatan 

Issizi yok aç sefil ne gezer bu ülkede 

Bir tamamsin bizans galatada sulukulede 

Yahudi ermeni rumunla bir tamamsin 

Bizans birin milyonu güder pek yamansin 

Bos hastahaneler oldu herkes müstefi 

Tarafinizca yapildi uzayin kesfi 

Dogum uzmani doktor erkek ebelerin 

Göstergesi degilmi çagdas hedeflerin 

Pek çagdassiniz galata pek gericiyiz 

Siz uzayi kesfetmisken ya biz neciyiz 

Bu marifet senin bizans sanirdik mevta 

Türkü uyur çerkezi bostur kürdü softa 

Sen olmasaydin geri kalirdik yarista 

Geçtik alemi huzur refahta barista 

Ne faili meçhul ne anarsi bulunur 

Irz emniyette mal korunur can korunur 

Diplomatin brokratin hipokratin var 

Seçtin bizden vitrine senin yeraltin var 

Pofpoflayip bizans ahmagi getir basa 

Ates sen olmussun bizden bulursun masa 

Bizans bin yil olsa sirrini açmaz yine 

Gizli devlet varilmaz gizli kütügüne 

Çekik göz japon almanin keltin öncüsü 

Bizans hatta tüm alemde kesfin öncüsü 

Ilminle isik saçtinda gidildi aya 

Yeni kita sensiz nasil gider uzaya 

Egenin o bir yani kardesimiz yunan 

Istila etmisti vatani arabistan 

Yardim etti yunan kurtulduk istiladan 

Arabtan irandan binbir türlü beladan 

Saha kalktin galata gizlisi kalmadi 

Köhne bizans köhne davadan usanmadi 

Kuruldumu köhne bizans isler tersine 

Ari gibi çalis millet aç sefil yine 

Böyledir bu memleketin mahkum yerlisi 

Hakim galatalisi sulukulelisi 

Oyun bozacak bir sarasker gerek bize 

Bin yil yürüdük biz her arkaya her ize 

Bos yola ne ömürler heder oldu eyvah 

Bu yola gidenede götürenede vah 

Bu yolda bir sarasker bekiyorum fakat 

Haine sert bize yüreginde sefkat 

Ayirir at izini fitne it izinden 

Kurtarir milleti gerçek yalan bizinden 

Vahyin kitabindan bir nur isaret bulur 

Bu karanlik alemde bir alem kurulur 

Ne milleti ardi bos savasta kirdirir 

Ne olur itler üstüne sürer yildirir 

Yikar iç kaleleri sürer ta haybere 

Hayberi kusatilir fitneye son vere', 'Laik soru sorsam laik cevap gelirmi  Zehir yoksa ya iftira ya sus denirmi  Su gerici osmanlinin her on veziri  Üçü cifitti dördü dönme rumdu...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":136,"source_url":"https://www.antoloji.com/laikce-bir-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soykırım Ve Arzı Mevud', 'soykirim-ve-arzi-mevud-atilhan-buyuksel-362ph', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açil susam açilsin dedik 

Erdik sirrina indi perdeler 

Sordum sirrin söyle ey Sfinsk 

Derki sirdir; perdeleriz 

Zehir verdigimizin adini 

Topragini alir culun giyeriz 

Fitne atesini yakinca biz 

Sönsün deyip körükleriz 

Erkegin kes kizlarin cariye 

Aldik ishakin kaldi geriye 

Calmisis topragin bizim diye 

Sahip cikar verde deriz. 

Kökümüz girit ne bilsin goyim 

Sanir ceddimiz abraham soyum 

Bizim tuzaklar böyledir bayim 

Dagilmis binbir yerdeleriz 

Isa der seytanin ogullari siz 

Seytana acik rahme gebeyiz 

Degil filistin Kitab ehli biz 

Kitap bizim yerde deriz 

Soyum abrama kurunca tuzak 

Isak tükendi Ismail ancak 

Göcüp gitti cöle bizden uzak 

Sanir amca zadeleriz. 

Dagil aleme cogalsin kavim 

Kanindan alem kan alsin kavim 

Kundak sokup bataklarda goyim 

Bilmez kanin tazeleriz 

SUSAM 2 

Grek romen amcaoglu 

Kipti bizans sodom soyu 

Bilinmez sir dipsiz kuyu 

Kökü Fravunzadeleriz 

Elde tevrat rol yapariz 

Nerde batak orda variz 

Ciplak heykel put tapariz 

Goyim sanat sansin deriz 

Dans bale kokteyl opera 

Bizde tapmaktir seytana 

Toplaninca havralarda 

Serefe kan olsun deriz 

Kerhane meyhane bizim 

Icinde sermaye bizim 

Sulukule gaye bizim 

Cikmazlara dalsin deriz 

Fikir sanat bulus nedir 

Bizde degil goyimdedir 

Calis bize bal yap yedir 

Bizi doyar sansin deriz 

Nesep bozup karistirmis 

Raksa dansa alistirmis 

Ari gibi calistirmis 

Tefe ile soysun deriz 

Yilan domuz maymun seytan 

Dendi kovulduk hicazdan 

Bataklarda tohum sacan 

Ocagina girsin deriz 

Azdir nufus yetmez bizde 

Gütmek gerektir bu izde 

Sicim bizden it var sizde 

Uyanani alsin deriz 

Akilliyi zehir vere 

Bagimsizlik demek nere 

Serdik gizli devrim yere 

Demokrasi sanssin deriz 

Ceddimiz kabilden beri 

Parcaladik goyimleri 

Dönüp bizler birde geri 

Dünya kani bulsun deriz 

Bu pislik Türk icinde yok 

Sodomda varda cinde yok 

Yunanda var macinde yok 

Sac tohumu olsun deriz 

Karismazsak goyimlere 

Veba taunla bizlere 

Gazap gelir vurup yere 

Iclerine dalsin deriz 

Hahambasi derki sözüm 

Binbir tuzak binbir cözüm 

Kitap yasaklatmak özüm 

Düsünceye darsin deriz 

Sirrimiz var engerekde 

Seytan zinaoglu birde 

Bunun bilindigi yerde 

Cellat sicim olsun deriz', 'Açil susam açilsin dedik  Erdik sirrina indi perdeler  Sordum sirrin söyle ey Sfinsk  Derki sirdir; perdeleriz  Zehir verdigimizin adini  To...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/soykirim-ve-arzi-mevud-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı Kardeşim', 'olmadi-kardesim-atilhan-buyuksel-ygt9i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olmadi kardesim çiçekler attin 

Bülbül sandin su yilana olmadi 

Asyadan milleti ardina taktin 

Maraton kostun yunana olmadi 

Top oynardin elden üstün olmadi 

Bos konustun suçlu oldun bahane 

Küsülmez yunana küstün olmadi 

Düstün zindana hayalim virane 

Millet seçti seni ya sen yunana 

Lagimina çukur açtin olmadi 

Ovalardan adalara limana 

Baraja su oldun tastin olmadi 

Rehberim degildi ilk is hamallik 

Kusatip fitneyi önce kovaydin 

Ortalik sis duman iken karanlik 

Bin düsünüp gözünü bir ovaydin 

Yazik milletime batik vatanim 

Kaptan zindana sürüldün olmadi 

Kendini kurtaramayan kaptanim 

Defterin çabuk dürüldün olmadi 

Tedbirdi zürriyyetini savcinin 

Bileydinde ne bildin ne sormadin 

Oltayi üstüne atan avcinin 

Cifit olduguna hiç uyanmadin 

Suçsuzum dedin ya kis kis güldüler 

Bana tuzak kurdu dönme deseydin 

Hamle bekeyip korktu büküldüler 

Aslan olup yel gibi bir eseydin 

Yunanin kerhanesine barina 

Acidin sermayesine olmadi 

Cifit basina sapik barbarina 

Set olmadin gayesine olmadi 

Çözemedin içimizde yunani 

Fazil bir alime çirak olaydin 

Cifit fitneyi hain siritani 

Timur gibi ayiklayip kiraydin 

Kime yanam kardesim yikilmisiz 

Sana yansam ya kim yanar halime 

Korkutulmus sindirilmis yilmisiz 

Bittik darbe vuruldu hayalime', 'Olmadi kardesim çiçekler attin  Bülbül sandin su yilana olmadi  Asyadan milleti ardina taktin  Maraton kostun yunana olmadi  Top oynardin el...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olmadi-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sulukule Yahut Diplomasi', 'sulukule-yahut-diplomasi-atilhan-buyuksel-v7cb2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ruma gelin vermis kerimesini 

Yunandan getirmis tazecik saf kani 

Laik çagdas devletimin sesini 

Duyuran hariciye sabik bakani 

Ne olur rumdan bize damad olunca 

Rumdan dogar bir torun türkten ad olur 

Hakkiyla temsil eder bizi kanimca 

Yükselir alemde adimiz yad olur 

Aferin sana laik vatansever kiz 

Geldi damizlik el atti sorunuma 

Dedesi vezirimdi torun kircamiz 

Veliahti bakan olsun torunuma 

Gelir taze bir kan mutluyum kizilmaz 

Bize rumdan diplamat lazim degilmi 

Sahin olur düsmana kuyum kazilmaz 

Alistirdi yobazi hazim degilmi 

Olsun üç bes gerici bassin fakayi 

Çagdas laik yolumuz geri dönülmez 

Hakkimiz yok egede iki yakayi 

Bölmeye bu vatani zaten bölünmez 

Bizim halkçi çagdas laik seçkinimiz 

Yakindi ta eskiden anavatana 

Danisikli dövüstürdü geçkinimiz 

Kani katti gencimiz yunanistana 

Bakanim kanini katmissa yunana 

Çagdas laik fakat otadoks rummudur 

Milletin sirrini satmissa yunana 

Hariciyeme yeni rum sorunmudur 

Bakmayin yüz vezirin doksan dokuzu 

Çagdas azinliktan geçer basimiza 

Perde gerisi olur hokus pokusu 

Iyisinden bela seçer basimiza 

Önde baska oynatir baska arkasi 

Bakanin rum olunca tuzak kurulur 

Gelmez biraraya iki yakasi 

Her plan bu milletten uzak kurulur 

Ortadoks rum demissin günah kardesim 

Iftira ettin vah kardesim bakana 

Demissin bizim koçta rum ah kardesim 

Dil uzattin vatansever manukyana', 'Bir ruma gelin vermis kerimesini  Yunandan getirmis tazecik saf kani  Laik çagdas devletimin sesini  Duyuran hariciye sabik bakani  Ne olur ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sulukule-yahut-diplomasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhül Değilmi', 'mechul-degilmi-atilhan-buyuksel-pwnke', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vardir suçu asin diyen itoglu 

Devir suçlununda itin degilmi 

Mahkemeye varsin diyen itoglu 

Hakimim cellada teslim degilmi 

Alinip Fravnun mumyadan hücre 

Babalik tesbiti yapilmadikça 

Olsada nufusu bucada kaydi 

Celledin piç soyu meçhul degilmi', 'Vardir suçu asin diyen itoglu  Devir suçlununda itin degilmi  Mahkemeye varsin diyen itoglu  Hakimim cellada teslim degilmi  Alinip Fravnun ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mechul-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Morris Süleyman Ve Kabinesi', 'morris-suleyman-ve-kabinesi-atilhan-buyuksel-xalgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurdu morris süleyman kabineyi 

Icraat yok yalan çok yorumda var 

Unutmamis bir tamamdir herseyi 

Mason kabinede cifit rumda var 

Kütügünde yarim dini tam oldu 

Oldu kizil mason geldi gam oldu 

Ad degisti gavurköy islam oldu 

Unuttuk neslini geldi yama oldu 

Ari ol çalis kar yok zararsa var 

Kuyruk var millet bela ararsa var 

Tüzük yasa var kanun kararsa var 

Banka tefe repo faiz borsa var 

Ugur kalkdi deprem yangin selde var 

Ilim teknik bizde yok o elde var 

Komedya var zevk sefa her telde var 

Fikre sansür agir bir bedelde var 

Seker yok elektirik yok zamsa var 

Is yok as bulunmaz hüzün gamsa var 

Kan sokakta var içen yamyamsa var 

Gulu gulu tansimiz tam tamsa var 

Ayi gibi oynatan çingene var 

Dönme hükümette kat kat gene var 

Milletin sirtinda bizans kene var 

Kurtulmak cifittan bin bin sene var 

Keçi kani içen sapik loca var 

Laik fetva veren pontus hoca var 

Çagdas yollu kadin meçhul koca var 

Söndürülmüs ocak tütmez baca var 

Fravun soyundan inme tayfa var 

Mason loca gizli sinme tayfa var 

Treversti lezbi dönme tayfa var 

Cifit basin çiplak kadin sayfa var 

Su hayberin yeralti kasasi var 

Gizli cemati var yarasasi var 

Yasamizdan ayrlir yasasi var 

Olsa bir sevincimiz tasasi var 

Seytana tapinan çagdasimiz var 

Dolaksiz soyundan bir basimiz var 

Felaket içinde gözyasimiz var 

Isgence var zehirden asimiz var', 'Kurdu morris süleyman kabineyi  Icraat yok yalan çok yorumda var  Unutmamis bir tamamdir herseyi  Mason kabinede cifit rumda var  Kütügünde ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/morris-suleyman-ve-kabinesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam Veremediğim', 'anlam-veremedigim-riza-aslan-8ybz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bazen dalıyorum öylece

anlam veremadiğim o kuru kalabalığa

bir yarış var

kimin,kiminle yarıştığı belli olmayan

bir hareket var

bir ışık hiç sönmeyen

bir ışık ki nereyi aydınlattığı belli olmayan', 'bazen dalıyorum öylece anlam veremadiğim o kuru kalabalığa bir yarış var kimin,kiminle yarıştığı belli olmayan bir hareket var bir ışık hiç ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlam-veremedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-sari-pisi-0f6vr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sır yüreğimde

Ömür boyu saklanan

Bir nefes benliğimde

Ömür boyu solunan

Bir ateş yüreğimde

Ölene dek yakan

Bir sevda hayatımda

Sonsuza dek yaşayan

                                           (Belde Lisesi 99)', 'Bir sır yüreğimde Ömür boyu saklanan Bir nefes benliğimde Ömür boyu solunan Bir ateş yüreğimde Ölene dek yakan Bir sevda hayatımda Sonsuza d...', ARRAY['Türk Edebiyatı','Şiir','Sarı Pisi']::text[], 8.5, '{"poet":"Sarı Pisi","poet_slug":"sari-pisi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/efsane-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalar Var', 'firtinalar-var-riza-aslan-j0a6z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'başımda fırtınalar var

içimde sensizlik

yine de ulaşmalıyım sana

anlatmalıyım beni sana

çünkü sen 

beni anlayamadın', 'başımda fırtınalar var içimde sensizlik yine de ulaşmalıyım sana anlatmalıyım beni sana çünkü sen  beni anlayamadın...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/firtinalar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Gideceğim', 'cekip-gidecegim-riza-aslan-flr0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni neden bu kadar çok sevdiğimi 

anladığım an

hiç tereddüt etmeden 

çekir gideceğim buralardan', 'seni neden bu kadar çok sevdiğimi  anladığım an hiç tereddüt etmeden  çekir gideceğim buralardan...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cekip-gidecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler Kopar', 'bir-seyler-kopar-riza-aslan-xf10p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'içimden bir şeyler kopar

gönülde fırtınalar diner

her şey gider 

ayrılır dönmez

bir sen kalırsın

çünkü sen düştesin', 'içimden bir şeyler kopar gönülde fırtınalar diner her şey gider  ayrılır dönmez bir sen kalırsın çünkü sen düştesin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-seyler-kopar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-riza-aslan-fxzr0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sensizlik,uçsuz bucaksız bir çöl gibi

sensizlik , çok istediğim ama

ulaşamadığım hayallerim gibi

sensizlik bir odada tek başına yaşamak gibi

sensizlik ufak bir hücrede katıksız yaşamak gibi

sensizlik, sensizlik ölüm gibi', 'sensizlik,uçsuz bucaksız bir çöl gibi sensizlik , çok istediğim ama ulaşamadığım hayallerim gibi sensizlik bir odada tek başına yaşamak gibi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensizlik-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-riza-aslan-hk2va', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağlamak bardaktan boşalırcasına

ağlamak sensizliğe adım adım koşarcasına

ağlamak yağmur gibi yağarcasına

bu gece ağlamak ,ağlamak istiyorum', 'ağlamak bardaktan boşalırcasına ağlamak sensizliğe adım adım koşarcasına ağlamak yağmur gibi yağarcasına bu gece ağlamak ,ağlamak istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aglamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine yalnızım', 'yine-yalnizim-riza-aslan-9pj1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine yalnızım

çevrem dolu insan

kahkahalar,neşeler,sevinçler

yalnızım

bunu ben iste(me)  dim

(ama)   yalnızım

tek başımayım

yalnızım

mutlu(mu)  yum', 'yine yalnızım çevrem dolu insan kahkahalar,neşeler,sevinçler yalnızım bunu ben iste(me)  dim (ama)   yalnızım tek başımayım yalnızım mutlu(m...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yine-yalnizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Geç Olacak', 'sabah-gec-olacak-riza-aslan-kv390', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün sabah geç olacak

kafam bir milyon yine

dönüyor oda 

dönütor masa 

dönüyor', 'bu gün sabah geç olacak kafam bir milyon yine dönüyor oda  dönütor masa  dönüyor...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sabah-gec-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutam Sevgi', 'bir-tutam-sevgi-riza-aslan-ba2du', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir tutam sevgi için tüm bunlar

içten gelerek yapılan 

her şey bu

adilik yok üç kağıtçılıkta

herşey içten 

her şey isteyerek', 'bir tutam sevgi için tüm bunlar içten gelerek yapılan  her şey bu adilik yok üç kağıtçılıkta herşey içten  her şey isteyerek...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-tutam-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatıyorum Beni', 'anlatiyorum-beni-riza-aslan-4ivj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gecenin içinden çıkıp

güneşin ışığını süzüp

olmayacak şeyleri yapıp

bir ton hakaret dinleyip 

açıyorum bu düşüncemi

anlatıyorum beni', 'gecenin içinden çıkıp güneşin ışığını süzüp olmayacak şeyleri yapıp bir ton hakaret dinleyip  açıyorum bu düşüncemi anlatıyorum beni...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlatiyorum-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engel', 'engel-riza-aslan-i5wqt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu günümü yaşayamıyorum

geçmişim ve geleceğim 

engelliyor beni', 'bu günümü yaşayamıyorum geçmişim ve geleceğim  engelliyor beni...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/engel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani Dünya', 'fani-dunya-mucahit-baskal-svtb0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şansıma darıldım bahtıma küstüm

   bu fani dünyadan göçmekti kastım

   dar ağacında bastığım dalı kestim

   aklımı yitirdim kendimi astım.

   kendimi bir anda toprakta buldum

  bilinsin bende bir günahkar kuldum

  bu fani dünyadan göçtüm kayboldum

  topraktan gelmişidim yine toprak oldum

 bu şiirim hatıra olsun sizlere benden

ruhum ayrıldı gayri bedenden

   kabrime gelin su dökün tepemden

başka bir isteğim yok dostlarım sizden....', 'Şansıma darıldım bahtıma küstüm    bu fani dünyadan göçmekti kastım    dar ağacında bastığım dalı kestim    aklımı yitirdim kendimi astım.  ...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fani-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birden', 'birden-riza-aslan-sltpt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'birdeb geldiniz aklıma

neyim var

neyim yok

döktüm ortaya

yargılayın beni dedim

ceza verin bana 

hücreye atın

gün ışığı göstermeyin

çünkü ben taşıyamıyorum kendimi

ben anlayamıyorum

kendimi', 'birdeb geldiniz aklıma neyim var neyim yok döktüm ortaya yargılayın beni dedim ceza verin bana  hücreye atın gün ışığı göstermeyin çünkü ben...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/birden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mana', 'mana-mustafa-muzaffer-macaroglu-j38ku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bülbülde ses, gülde gonca

Bende hayal

Bu alemde daha nice güzellikler var

Bir ilahi sır yaklaştıkça akıl şaşar

İnsan hayal ettiği müddetçe yaşar

Katibim türküsü,bahriye çifte tellisi

Bir zamanlar dillere destandı İstanbul efendisi

Ne eski nağmelerde zevk 

Ne efendiden eser kaldı

Her güzelin yerini 

Bir çirkin mana aldı.', 'Bülbülde ses, gülde gonca Bende hayal Bu alemde daha nice güzellikler var Bir ilahi sır yaklaştıkça akıl şaşar İnsan hayal ettiği müddetçe y...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Muzaffer Macaroglu']::text[], 8.5, '{"poet":"Mustafa Muzaffer Macaroglu","poet_slug":"mustafa-muzaffer-macaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorolan', 'zorolan-bulend-b-ki-w39d0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zor olan sevmek değil,

Kötü bir günün ardından, bir kötü gün daha geçirmek

Zor olan ölmek değil,

Acısını çekmek bir ömür sensizliğin...

Zor olan ayrılık değil aslında,

Sensizliğe hüküm sürememek zor.

Zor olan özlemek değil a gülüm...

Her günkü gibi, bugün de,

Yolunu gözlemek zor...', 'Zor olan sevmek değil, Kötü bir günün ardından, bir kötü gün daha geçirmek Zor olan ölmek değil, Acısını çekmek bir ömür sensizliğin... Zor ...', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zorolan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Sana', 'bende-sana-gonul-duzgun-qu2hp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimdeki fırtına yine dinmek bilmiyor

Anılar sararmış fotoğraflar gibi masun kederli

Valizimde telaşlı çaresiz yarınlar 

Gün geceye güneş aya yaprak dala dargın

Bende sana', 'İçimdeki fırtına yine dinmek bilmiyor Anılar sararmış fotoğraflar gibi masun kederli Valizimde telaşlı çaresiz yarınlar  Gün geceye güneş ay...', ARRAY['Türk Edebiyatı','Şiir','Gönül Düzgün']::text[], 8.5, '{"poet":"Gönül Düzgün","poet_slug":"gonul-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bende-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Kıskan', 'sen-beni-kiskan-gonul-duzgun-kg6og', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni kıskandığımıda nerden çıkardın çocuk

Hiçmi hiç kıskanmıyorum inan

Çünkü senin ne dallarına salıncak kuracak bir ağacın

Ne de yağmur yağınca koklayacağın bir karış toprağın var

Kuşlar söyledi deme bana inanmam çocuk

Çünkü senin kuşların da yok

Oysa benim bahçe dolusu ağaçlarım

Saçaklara sığmayan kuşlarım vardı

Sevinçlerim erik dalına asılı

Kederlerim buğday tanesi kadardı

Umutlarım ufacık yüreğime sığmadı

Sen beni kıskan çocuk sen beni kıskan

Çünkü benim bayramlık sevinçleriyle dolu

Yaşanası bir çocukluğum vardı', 'Seni kıskandığımıda nerden çıkardın çocuk Hiçmi hiç kıskanmıyorum inan Çünkü senin ne dallarına salıncak kuracak bir ağacın Ne de yağmur yağ...', ARRAY['Türk Edebiyatı','Şiir','Gönül Düzgün']::text[], 8.5, '{"poet":"Gönül Düzgün","poet_slug":"gonul-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-beni-kiskan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 YAŞINDA', '19-yasinda-serkan-guler-ofcth', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim hayale  daldıgı zaman .

İçimde bir ateş yanıdıgı zaman .

Arzularım yarım kaldıgı zaman .

Boynumu kadere bükerim ben .

Vefasız  sevgilim beni inkar ederse 

O mutlu günleri unuttum derse

Benden başkasına gönül verirse 

Ahirette hesabını sorarlar ona

Çiçeği burnunda 19 yaşında

Hayatın çilesini aldı sırtına 

Bu dünyada yüzüm gülmedi daha

Ecelim zamansız gelmiş olsada 

Ona bu mesajı ileti verin !!!', 'Gözlerim hayale  daldıgı zaman . İçimde bir ateş yanıdıgı zaman . Arzularım yarım kaldıgı zaman . Boynumu kadere bükerim ben . Vefasız  sevg...', ARRAY['Türk Edebiyatı','Şiir','Serkan Güler']::text[], 8.5, '{"poet":"Serkan Güler","poet_slug":"serkan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/19-yasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığı', 'ayisigi-ali-esen-pgsot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayışığı, yalnızlara yol gösterir,

Yitip giden ağlamaklı sevgilerde.

Arayıp bulduğunu sandığın,

yarısı yırtık eski resimlerde.

Annenin çeyiz sandığındaki

taptaze

güvelerin bile yiyemediği anılarda

Eski zamanların unutulmaz şakılarında

hiç bilmediğin, hiç yaşanmamış,

bitmeyen yalnızlıklarda

hayatı tanımak ister misin küçüğüm.

Kendini anlamaya çalıştığın

Bu neden böyle diye sorduğun

Islak yalnızlıklarda...

Babanın sana hep güven veren

Sarıp sarmalayan sesini,

Hep şikayet eder gibi saat başı

gong çalan duvar saatini

bebeğini, teyzeni ve çok sevdiğin kedini

ve benim artık unuttuğum sevinçlerimi.

Ayışığı yalnızlara yol gösterir...

18.9.00', 'Ayışığı, yalnızlara yol gösterir, Yitip giden ağlamaklı sevgilerde. Arayıp bulduğunu sandığın, yarısı yırtık eski resimlerde. Annenin çeyiz ...', ARRAY['Türk Edebiyatı','Şiir','Ali Esen']::text[], 8.5, '{"poet":"Ali Esen","poet_slug":"ali-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayisigi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-guner-karabulut-qcpio', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir belkiye bağladım tüm umutları, 

Bir belki hep sıcak tuttu korları.

Saniyelerin bile hesabını yaparken, 

Bir belki aldı götürdü yılları.

Yalvarırım çöz artık şu kördüğümü.

Bu yürek hep böyle bağlı kalmasın.

Ben ''hayır''a bile razı ettim gönlümü, 

Yeter ki cevabın ''belki'' olmasın.', 'Bir belkiye bağladım tüm umutları,  Bir belki hep sıcak tuttu korları. Saniyelerin bile hesabını yaparken,  Bir belki aldı götürdü yılları. ...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vesikalık', 'vesikalik-burak-ersemiz-2t1zj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Renkler rol aldı

bu oyunda.

Siyah şeytan oldu

Beyaz ise melek.

Sevdiceğim bir resmin var bende

siyah ve beyaz...', 'Renkler rol aldı bu oyunda. Siyah şeytan oldu Beyaz ise melek. Sevdiceğim bir resmin var bende siyah ve beyaz......', ARRAY['Türk Edebiyatı','Şiir','Burak Ersemiz']::text[], 8.5, '{"poet":"Burak Ersemiz","poet_slug":"burak-ersemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vesikalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadılar', 'anlamadilar-burak-ersemiz-g4ewk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamadılar.

Anlayamadılar.

Anlamak istemediler.

Gerçekten anlamak isteselerdi seni.

sanmazlardı,

karıncalarla filleri çiftleştirdiğini.', 'Anlamadılar. Anlayamadılar. Anlamak istemediler. Gerçekten anlamak isteselerdi seni. sanmazlardı, karıncalarla filleri çiftleştirdiğini....', ARRAY['Türk Edebiyatı','Şiir','Burak Ersemiz']::text[], 8.5, '{"poet":"Burak Ersemiz","poet_slug":"burak-ersemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlamadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOPAK', 'topak-hasan-ejderha-e3xoo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Yüreği mahzun, alnı ak, dikmiş gözlerini beton bahçeye

Büyür, büyür içinde bir topak

korkak adımlarla arşınladığı sokaklar

korkar şimdi izlerinden

buğulanır burnunda toprak

ak pak bir kuş geçer düşüncelerinden.

Seni ben topak

ak-pak bir nakış ipliğiyken

yüreğinde ak bir topağın heyecanı ile hayal kurup,

nakış işleyen yetim bir kızın elinde görmüştüm.

seni ben topak,

Anamın  kırma yannığından, şıralı elleriyle

bağ budamaya giden babamın azığına koyarken görmüştüm şipşirin.

Yağmur bekleyen bir çiftçinin içine topaklandığın

yağmur ağlayan buluttan sonra yüzünden yıkanıp

eridiğinde görmüştüm, akarken siğim siğim

ne çok görmüşüm de seni, 

korkak mısın ki bana görünmezsin.

Niçin habire büyürsün içimde 

ne büyükmüş içim dedirterek, şaşırtmak isteyişini sezer gibiyim

lakin bilirim ben içimin büyüklüğünü

nelerin sığdığını ve nelerin sığacağını.

Korkak bir yüreğin sıkışması değil bu topak

yaprak yaprak bir hasretin büyümesi belki ama

sevinemeyeceksin sen ne kadar büyüsen içimde

o kadar küçüleceksin hey korkak.

Kimin kime kastı var,  çıkamaz mısın içimden ey topak

ak bir karın topak topak üşümesi değil bu halim

iri bir taşın ağırlığı, bir topak tuzun içime erimesinin yakıcılığı 

dost kalır yanında senin

demedim ki sana bir benim  içimdesin

ama bazı günler topaklanır, topaklanır, topaklanırsın

şu kara taşlar şu duvarlar muhakkik

bilirim bana neler yapacağını, şikayet etmesem seni günde beş vakit

bana yalvardığını duyarım da o an yalvartmam

yalvartmam, çünkü sana göre değil o makam

peki sen bana yüklenirken içime topaklanıp, neredeyim bir bilsen

dikilsem karsına yuvarlasam, yuvarlasam 

gideceğin bir iç bulamayana kadar yuvarlasam.

Cismimi sana bırakıp çıktım dün buradan topak

ne güzel senin olmadığın bir içi taşımak

dost sokaklarını arşınlamak, yarışmak duyguların en yücesiyle yücelerde

çık içimden beni niye buldun topak

şair yüreğimi zorlama benim

ölmeyenin ölü numarası yaptığı bir kurşun sızlaması değil bu

kutbu izleyen sofilerin hasreti ise sen değilsin

çık içimden çık topak, aşk alsın yerini yaprak yaprak.

II 

Topak, topak seni yok sayan bir aşkın yiğitliği ile yere atıp

parçalama eyleminden ne kadar uzağım görüyorsun

sen ise ha bire bastırıyor, bastırıyorsun 

yalnız sen beni bilirsin, ben ise seni burada tanıdım topak

horlayarak uyuyan, yirmi beş yıla mahkum bir mahpusun

bile içinden uyku ile çıkmıyor musun

ne kadar da zayıfsın aslında görüyorsun

bilirim içimdeki halini sultanlık arıyorsun

al, bu günler kadar bir altın iktidarın olsun.

Topak... an be an seni yaşattın

söyle, yok mudur sana has hayatın

yetişin çiçekler, doldurun içimi şu topak gitsin

sarsında gönlüm sizi hasretle büyütsün

ey! topak ben sana devletim burada, sen ise bana yüksün

içimde ne kadar büyüsen, anlarsın ki o kadar küçüksün

beni hayallere uyutur,  uyandırırsın sonra cız cız

büyü şimdi içimde büyüyebildiğince, yalnızız

bilesin ki istesem belki seni kovarım, 

sana kalır dermanı az yaralarım.

Deldin içimi, deldin topak

acı sular akar şimdi vücudumdan yakarak

betonlar mekandır sana, bana devlettir toprak

duvarlar dua geçirmez mi sandın zalim topak

haykırdığını görmedik mi dün bir mahkumun ağlayarak

uyuyarak bile kovan ben seni

ellerimi açınca göklere, pul pul döküp yere

saçmadım mı betondan bahçenin ortasına, üfürüp pencerelere

kafasına böcek konan bir mahkumun çığlıklarına diretemeyen sen

Mantıklı Mantıksız ağabeyin iki cümlesiyle

ezileceğini bilerek bile katlanabilirdim sana

yine de seni içimden kovmak düşüyor bana.

Topak... topak gökten bir taş gibi düştün başıma ve içime

bu bir kefaret ya da müjdenin çilesidir belki de

ama bil ki ilk değil sana toslamam

ben bildim, sen beni bildin mi topak

sensin içimde olan, aç da yüreğime bak.

III

Baksana kalem bile sızlanır topak

bilirsin ki şimdi canan uzak,  dost uzak 

vakit vakit seni şikayetimde; sızlayarak silinmen içimden

aratır oldu seni ey topak

korkak halin yok mu, dayanamayarak pes etmen

uykuda bile gitmen, yukarıdan murad dilerken ben

ciyak  ciyak halinden tiksinmek istemeyerek kınadım seni dün.

Topak... boynunu kaşındırdığı için şalvarını yakan

Mecnun Ahmet bile mantıklı senden, çok an

''Allah''ı an çayımı vereyim  sana'' dedi dün

her gün içimde gördüğün

büyük kasırgalar sanma ki sendendir

Ahmet''in bu hali bir, 

birde Mantıklı Mantıksız ağabeyin, mantığı yok mu,

seni silmekte yer yer.

yüklen içime, yüklen topak, yoksa varlığın bitecek.

Seni sevmek, ya da nefret etmek,

bir bu soru cevapsız dünyada topak

karanlıktan korkarak 

sızlanan çocukluğuma uğrak

                                              yeri oldu bu duvarlar

bildin mi ne dedim topak, bilmezsin çardağa ayak yalın dinelip

buz kesen ayaklarını tınmadan, iftar haberi ezanı beklemeyi

oralarda sen yoktun topak, sen beni yak, aşkım seni yakacak

kollayarak tayınını aldırdığım Mecnun Ahmet''in

yirmi beşlik mahkumlara bakışını hatırla topak

kalk diye haykırışını düşün Seyyit İsmail''e

''seyyit ayağını uzatmaz'' demiş ti namazgahta ya

anladın mı içimden sıyrıldığın anları

saniyelerimi kendim olarak yaşayışımı doya doya.

Acemi mahpusluğumda saldırışın kadar yalvarmaktasın şimdi

her ikindi kovduğum sen, her sabah içimdesin tilki gibi

ikimizi birden resmetse biri,

ansızın tutuklanmış ben gibi çırpınacaksın bilirim

senin ağırlığından kıvranırken, seninle cedelleşmek olmasa delirirdim.

on dört mart bin dokuz yüz seksen yedi, şunu şuraya yaz dediler her gün

on dört mart bin dokuz yüz doksan altı denileni yazmak oldu suç sebebim

anla, anla ki topak bir müjdeye gebeyim

sevebilirim belki seni, Ömer''in sakalındaki ilk beyaz kıl gibi.

Kuyunun dibi

kirlendi belki de topak

atlılar nereden su içecek artık

dua dua temizlenirdi belki kir, sahiden atıldıysa göz görerek

yok topak yok! şüphe senden yakıcıdır. ağızdan girince yüreğe acıdır

mahalle kadınları sarkarak pencereden pencereye

anlatırlar sulardaki kirleri, ölü eti yiye yiye

işte o zaman topak dost bile oluruz belki seninle

bir dostumuz olmaz belki ama, ölü eti yiyen

onlar olur şahlık elbisesini giyen

beni tut topak uçacağım, bağlamazsan gönül ipiyle bir yere kaçacağım

korkaklar kaçar deme bana, ikimiz de biliyoruz o kelimeyi ama

görüyorsun ki korkaklar kaplamış dünyayı

artık bir merhem yok, kabuk tuttura bu yarayı

kaçmak dedimse bildiğin kaçmak değil

ne kötü sen anlar oldun beni bir.

IV 

Dışarıdan gelen motosiklet sesine, ''işte hürriyet hey''

diye bağırmıştı hani, Mantıklı Mantıksız Ağabey

Mecnun Ahmet güldü ona, sonra beton bahçeye düşen

küçük taşı göstererek; ''bu daha hür

gitmesine bakma motorun güldür güldür

kulun iradesi olmasa şaşar hürriyeti''

beni gösterdi sonra ''istersen hocama sor''

ona estağfurullah bile dedirtmeyen sendin topak

yatak örtüsünü sigarayla yakıp seyreden Cennetliğin

gülümser halini çekemezsin bilirim

Cennetliğin tebessümünden korkan sen neden içimdesin bilmem ki

içeri düşmekti durağın biri, şimdi kalmadı içeri seni bileli

içeri, daha içeri yolculuklar akışır içimde, 

senden kurtulurum her dosta gidişimde. 

Düşümde gördüm, kovdu  seni dün efendi, topak

buğum buğum buğularla yundum ak-pak 

Ödlek Bıyıklı bile senden cesur

mağrur hali yok mu, yirmi beş yılla süslenen Argo''nın

onlara taktım seni unutup, tutup bir yerinden fırlatamıyorum fakat

ah... ah topak, düveninde tebessüm satar, söz satar efendi şimdi bir bakışa

bense yana yana tırmanırım senin sürdüğün yokuşa. 

Bir taş daha düştü bugün betondan bahçeye

bölüştü onu iki mahkum, demir kaşıkla vurarak kırdılar yan yan

tutukluluğum birkaç yılla süslenmiş mahkuma döndü o an

taştan bir parça da ben istedim onu iki mahkum parçalarken

gördün mü ne olmuşuz, nasıl tükenmişiz zalim topak

patlayarak uçurduğum hayallerim, azap olur döner şimdi yağmurdan ıslanarak

kıvrak bir zekayla deliliğini haykıran  Ahmet''e neden imrenirim bilmem ki 

Cüneyt''in ve Fatin''in, dükkanda ortaya attığı tekel gibi

birinci  sigarasını arkası olmadığı halde dağıtan Yusuf''a imrenmem gerekirken.

Yirmi kişinin akşam namazı için sıraya girdiği, 

havlu kadar seccade kuyruğunda sen yoktun topak

sevinerek eşyalarını toplayan Ali Osman''ın tahliyesine çırpınıyordun belki de

simit aşı pişirip ''hocam bıyır'' diye çağıran, 

Antepli Fayık''ın sohbetinde çırpınışın gibi 

nane içerek kovduğu gribini 

ıslak betona yatarak geri kazanan 

deli Ali''nin bile giremezken içine, 

bana nasıl da hükmedersin be topak.

Babasını sırtlayıp, tedavi için hastaneye kaldıran Yusuf''un

baba katili damgasından da mı büyüksün ki sen topak

barak türküleri söyleyen Nizipli''nin, eşkıya yüzünde senin acıtman var bilirim    

dilim dilim helvasını dağıtan ve açlığını gönlüne atan otuz altılığın

elli beş yıllık yüreğine girme ne olur 

Erkut''un Çeçenistan haberlerine gösterdiği hassasiyeti istemem gerçi senden

halin malum  herkesce, budur işte beni en derinden kahreden

tavuğun buğday yığınında, buğday deşinmesi gibi zengindir burada yemin.

Duvardaki eli baltalı cellat resmi var ya topak, 

ömründe  ağlamamış bir kere bile 

en sonunda  ağlatmış onu keseceği biri

kulağına söylediği meçhul bir söz ile

hiç düşündün mü topak, cellada ne demiş o mahkum

niçin sorarım ki sana, celladın icraatı değil mi senin mutluluğun

''seni seviyorum'' demiştir belki de ne dersin

''kimse sevmez celladı o niye sevsin'' 

                                                    deme sakın

malum kesmemiş onu cellat, sonra ağlamış, ağlamış, ağlamış

topak... topak, artık o celladın baltası sana müstahak.

Şu bizim  komutan var ya topak,

tarhanalık yoğurt, askerlik laflarını bırak da,

kardak krizi hakkında konferansı bile sana tercih eder di

emin değilim ama, belki tatlı bile yerdi 

                                                         senden kurtulmaya

ineğe ya da danaya ortak olup, kurban keseceğini bile söylerdi insanlara.

Mecnun Ahmet''in, otuz altı yılına rağmen

her hafta kundurasını boyaması ne akıllı bir eylem değil mi topak

ya da yirmi dört yılla süslenmiş Mıstık''ın düğün daveti herkese

komutan izin verse de vermese de kaçacağım Mıstık''ın düğününe mutlak

umut bu topak, umut... her şeyden güçlü ve burada çok.

kork artık topak kork, seccadede kuyruk uzadı

uzadıkça seccadede kuyruk, bilirim senin saltanatın bitecek 

çiçekler düşünceleri, düşünceler dağları süsleyecek.

V

Doksanlık babannesini çeyrek altın için doğrayan,

anlatırken de, ''foşur foşur kan aktı moruktan'' diyen caninin

ikram ettiği çayı, sana rağmen reddetme bahtiyarlığımın

sana ne kadar acı verdiğini bilirim ama aldırmıyorum topak

çayı reddetmek değil bu, ne fikirli çay dostu Ahmet DOĞAN 

ne de avukatım Haki kızar buna, omuzuma vurarak benden ateş isteyen

iki bin ellilik bile ondan çay almıyor biliyorum

Göktürk İsmail bile çaysızlığa dayanır da almazdı yine de

                                                                       lüks bir otelde, 

ben içmeyerek hocama verdiğim çayın hazzı var içimde

''en çaysın anında içmediğin çayın hazzı mı olur.'' sen bilmezsi olur topak 

anlayamadın ya hazzımın manasını, işte burada fark

ağlayarak yatağa kapanan Cennetliğin, anladım ki sigarası yok

Efendi Hocam''ın her maaş günü aldığı sigaraları anladım, bana almamış topak

nettim mi o sigaraları, teslim ettim cennetliğe muhakkak

hak bu topak hak, hem de emanet edilen hak

deme ki ''hoca Cennetliği tanımaz'' tanır o topak tanır

Cennetlik ağlamadan almalıydım sigaraları, o hakkın teslimine inanır.

Kaypak zahidin adıyla lakabı ne zıt birbirine değil mi topak

pencereden görünen toprak bile onaylıyor bunu bak 

''dolabında çay, sigara ve şeker olduğunu bilerek uyumak,

var ya hocam'' diyerek hapishaneyi şerh eden Mantıklı Mantıksız ağabeyin

duyduğu haz ile aldım bugün bir top beyaz kağıdı

Erkut''un çeçen inadı mı geçti ne bana, oysa kovmalıydım seni topak

Kaypak zahide dönelim istersen şimdi

anahtarı dolapta kalmış kilidi

toplu iğneyle açan hırsız takımının üstadı

Zahid ismini kopardım, yeter ona lakabı

bakıyorum yine yüklendin içime, zira içim yandı

bir gün seni haklayacak, hocama kavuşma hazzının tokadı

nedir benden istediğin nedir topak

belki de senden daha soylu, şu bizim Kaypak.

İlk, şu koğuşta çay bardağı çalmanın serbest olmasını sevdim, 

o vakur edasıyla oturan Cennetliği bir de

zikirdeyken bakışı yok mu onun, bir ben görüyorum belki de

ya da bir bana gösteriyor topak

kursak dolması yapmak için katlandığı zahmeti düşün Mıstık Ağa''nın dün

her gün tıkınması bir yana, mide için bu yapılır mı topak

Kaypak bile kınamıştır onu muhakkak.

Adliyedeki şu buzağılık... ne komik bir isim orada topak

çocukluğumda buzağı koyduğumuz, önüne gem dayanmış ocak

gibi düşünmüştüm orayı yazık

koluma asma kilitle kilitlenen zincir bile oranın adı kadar ağır gelmemişti bana

başka isim yok muydu oraya koyacak topak

buzağı ne kadar şirin gelirdi çocukken kardeşimle bana

buzağılıkta biz şirin gelmedik biliyorum jandarmaya

üzerimizi araya araya zincirlediler hepimizi

zincirleri çözerken yine aradılar bizi

ama ne kadar güldük değil mi topak, acı belki ama seninle dost olmak 

burada bir sen kaldın şair yüreğime dost olacak.

Dışardan yeşillik geldi bu gün topak

yaprak yaprak dışarıyı yaşamak bir dal yeşil soğanda

bir top çiçek gibi tutmak maydanozu iştahla, ne manalıymış burada anladım

feryadım dudağımda kıpırtılarla yükselirken göğe, 

sıyrılıp çıkışını içimden; mal beyanından, beş gün hapis yatan Bertizlinin, 

kendine asır gelen tahliyesine benzetiyorum

önceleri sen benimle oynardın, şimdi ben seninle oynuyorum 

sokak sokak gezip bir ekmeği bulamayan dilencinin 

ekmeğe duyduğu açlığı ben Dükkan Efendisine duyuyorum. 

Oh! be topak... bir aydır tatlı yemeden durup da,

Ramazan''ın getirdiği kadayıfı, Ahmet Bey''i yadederek 

                                                             yemiyorum demek 

ne büyük şerefti değil mi

beni anladığından ne kadar emindim oysa, 

çok sevdiğin bir şeyi sızlatmak, fikre istinatla

anlamalısın beni artık topak. Ben senden deliyim

ne korkak duyguların oyuncağı, ne de nefsimin yemiyim

siyim siyim yağan şu yağmur var ya topak

ekilmişim olmadığı halde bereketine sevinirken, afetinden de korkarım

yüreksizlere düşmanım bilirsin, yüreği yanında olanlara ise yarım

yarım aklımla da olsa topak,  sadece aşk yolunda varım

karım, ne seni ne de şu beton damı tanımak, sabrı buldum, sabrı topak.

Maket gemiler yapan Kerim, bir donanma sayısınca gemiler yapmış burada

ömründe donanma  lafını duymadan topak

sülüs yazılarla tablo yapan Talip''in yazdıklarını okuyamaması gibi

şu kahır... kahır ne ki burada topak, bütün duyguların cenneti şu beton dam

''hocam çamaşır leğenim olmadı dört yıldır'' diye dertlenen 

Ali''ye çamaşır leğeni aldım dün kırmızısından. 

katilinden hırsızına kadar insan burada her can

herkes içsin diye çay kaynatan zengin Babo''nun çayını kimse içmezken

benim küçük demliğin başına üşüşen insanların içinde; 

dışarıda bir kemiğin peşine düşenleri de var ama topak, 

dost olmak var ya dost olmak

en adi birinin bile yüreğindeki yiğitlik kırıntısını bulmak, 

o yiğitliği duymak, ona yiğitliğini duyurmak, burada nedir en iyi sen bilirsin topak mutlak haklı olarak dayak yiyen Cemil''in bana sokularak,

''senden niye korkuyorlar hocam'' demesine nasıl içerledim ah bir bilsen topak 

korkak ya da cesur olmak kaç para ki burada

birer yumurtayla yirmi adamın olmaktan daha karlı değil mi herkesi sevmek

bunu anlayabilse Cemil, yanmalıyım, yanmalıyım topak gel yüreğime gir.

Hayatın çığlıkları içinde, duyguların katır tepmesi gibi toslaması yok mu topak

haykırarak söylenen her şeyin sustuğu mekanı yaşamak sonra,

günde bir paket içen yüz ikiliğe aldığım, on paket birinciyi, üç günde bitirmesi,

iki bin iki yüz parçaya doğrayıp bir tabloyu karıştırıp sonra dizmek yeniden

en mantıklı eylemi buranın, aksiyonlarını zincirleyen bir toplumun

uyuklaması aksiyonudur şimdi mağaralarda, 

televizyon seyredenci olarak suçlandığım anları

televizyonun üç metre gerisinde mahpus yatarak kırk gün

televizyonu öldürdüğümün tek imzalı belgesi şimdi şu halim

doya doya hürriyeti yaşamak gibi, öldürmek hürriyetini biçen nesneyi

kalbii olan her şeyi gömüp, kabuklardan heykeller yapan bir sanatçının(!)

kabuk hali yaşanır her gün demirlerin içinde

çöplüklerde kurtuluşu arayan çöp bekçilerinin 

çöplükte hayata izin vermediğini bile bile 

yine de haykırarak ranzadan sıçrayan

iki bin altmışlığın bulduğu çareyi dinlerim her gün

''yirmi iki leşim var hocam'' diye anlatırken

ha bire bir tek kırmızı gülü, üç yaprağı ile yaparak biriktiren

Dursu''nu dinlediğim gibi. 

Camiden halı çalarken yakalanan Şef''in, 

''şu Selçuklu, şu Arap, şu Osmanlı mimarisi hocam'' diyerek gösterdiği

cami maketlerine bakarken bilemedim ne düşüneceğimi 

işlediği suçu ne kadar çirkinse,  zıddınca da güzeldi maketleri

''iddiaya gireceklerin dikkatine'' diye başucuna ilan asan

ranza komşumun maçları takip etmesi kadar kitap okuma hevesindeyim

domates salçasından alkol damıtan dahilerin tek hayranı benim

bir meyve dalı yüzünden adam vuranla, ihtiyar babasını dövenleri vurana

sorduğunda ''suçun nedir?'' cevabı aynıdır  ''cinayet işledim''

hiçbir şeyin içi yok burada topak

krom bir tabaktan bıçak yapmak

silahların en iyisiyle caka satmak fırsatını verir insanlara

sigara paketinden biriktirdiği aliminyum ile radyo anteni yapanı atmamalı yabana

dünyada ne kadar hüzün varsa toplanmış buraya da

Cennetliğe yüklenmiş bu gün

anasını ziyaretçi kabininde, incelmiş çöp gibi gören Sungur''un

üzgün üzgün gelişi de hüzünle doludur topak

ürkek ürkek bıyığını düzelten süslünün, püskülü mü, yiğitliğimi bıyığı bilinmez

söyle topak söyle hasret burada niye bitmez.', 'I Yüreği mahzun, alnı ak, dikmiş gözlerini beton bahçeye Büyür, büyür içinde bir topak korkak adımlarla arşınladığı sokaklar korkar şimdi iz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":342,"source_url":"https://www.antoloji.com/topak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayinsin ve Zalimsin', 'hayinsin-ve-zalimsin-mustafa-aytac-arman-lxese', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben mi istedim ayrılmayı 

Söyle kim yarı yolda bıraktı

Kim kim yeminleri hiçe saydı

Seni sevmiyorum deyişim zalim kalbinimi sızlattı

Senin canın yanmaz 

Seven insan yarı yolda bırakmaz

Ayrılmamız lazım deyip kaçmaz

Alacağın olsun zalim

Sensin zalim 

Sensin hain 

Artık ağlamaya kalmadı mecalim

Sevmiyorum seni zalim

Gülen gözlerimi ağlattın 

Aşk yolunda yalnız bıraktın

Söyle ben sana ne yaptım

Sevmiyorum seni zalim

Gülmek haram oldu buralarda

İçim yanıyor akşamdan sabaha

Seni istediğimi sanma 

Sevmiyorum seni hain

Damla damla aktı göz yaşlarım

Bilemezsin  neler yaşadım

Seni sevdim sen ayrıldın 

Sevmiyorum seni zalim

Çığlık çığlığa sana hasretim

Her fırsatta seni seviyorum dedim

Benim o saf sevgimden ne istedin

Sevmiyorum seni hain

Bir akşam vakti olmayanları yaptın

Bir başıma bırakıp kaçtın

Bu aşkı bir sayfa gibi kapattın

Sevmiyorum seni zalim', 'Ben mi istedim ayrılmayı  Söyle kim yarı yolda bıraktı Kim kim yeminleri hiçe saydı Seni sevmiyorum deyişim zalim kalbinimi sızlattı Senin c...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aytaç Arman']::text[], 8.5, '{"poet":"Mustafa Aytaç Arman","poet_slug":"mustafa-aytac-arman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayinsin-ve-zalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıprandık', 'yiprandik-riza-aslan-0977n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çabuk yıprandık

hızlı geçen bir ömür boyunca

belki yıllarca 

belki onyıllarca

yapılacak her şeyi

bir kaç aya sığdırdık

yarınlar varken önümüzde

uzun,hiç tükenmeyecek

biz çok hoyratça davrandık

ve yıprandık', 'çabuk yıprandık hızlı geçen bir ömür boyunca belki yıllarca  belki onyıllarca yapılacak her şeyi bir kaç aya sığdırdık yarınlar varken önümü...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yiprandik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmişiz', 'bitmisiz-riza-aslan-z0wgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bitmişiz biz

tükenmişiz

ömrümüzün ilk baharında', 'bitmişiz biz tükenmişiz ömrümüzün ilk baharında...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bitmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-riza-aslan-axabt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yapılan her şey bir oyun

bir oyun bu 

kuralları daha önceden belirlenmiş

bir oyun bu

gerçekleri saklayan

bir oyun bu

geçmişi saklayan

hayat bir oyun', 'yapılan her şey bir oyun bir oyun bu  kuralları daha önceden belirlenmiş bir oyun bu gerçekleri saklayan bir oyun bu geçmişi saklayan hayat ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oyun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçsiz Anılar', 'sevincsiz-anilar-cezmi-ersoz-uwz45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümüm kandil olacak,

akşamlar akşamlar akşamlar olacak

Ben bu acılı baloda

Maskesini yitirmiş seferi şair

Ben inançsız yolcu

Bütün istasyonlarda

kanlı rütbeler takılacak omuzuma

Bir kuşluk vakti dalgın atların hıncını

düşünürken

sen''Yalnızlığın bahçesini sulamış olacaksın''

Ve gidiyorum...

Dudaklarımda bir nergis tadı

Bak,kar izleriörtü bile,

Kendini iyi koru, bu kış çok uzun sürebilir.

Anılarım tutkularıma bağlıydı bilirsin

Artık pişmanlık olsa da ılur olmasa da.

Ne olursun sen hep böyle kal

Varsın ellerim ellerinsiz kalsın.

''Ölümüm kandil olacak,

akşamlar akşamlar akşamlar olacak...''', 'Ölümüm kandil olacak, akşamlar akşamlar akşamlar olacak Ben bu acılı baloda Maskesini yitirmiş seferi şair Ben inançsız yolcu Bütün istasyon...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevincsiz-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bir son', 'bir-son-riza-aslan-6xlhd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir son olmalı

hayal edildiğinde hoş

-ama- hiç bir zaman ol(a)mayan', 'bir son olmalı hayal edildiğinde hoş -ama- hiç bir zaman ol(a)mayan...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilmeli', 'yenilmeli-riza-aslan-hze0m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yenilmeli 

ayakta duramayan

yenilmeli dün,bugüne

bugün ise yarına

hep umut edilen bir yarın olmalı

hiç gerçekleşmeyecek

hep umut edilen bir yarın olmalı

umut edildiği gibi kalacak

gözler anlamsız bakmamalı

içindeki o ışık , o hayat pınarı

hiç bir zaman sönmemeli

korkmamalı istenilenlerden

hayaller , umutlar yanı dibindeyken

onlardan böyle karamsarca kaçmamalı

22-08-2000   pazartesi   saat: 0.39', 'yenilmeli  ayakta duramayan yenilmeli dün,bugüne bugün ise yarına hep umut edilen bir yarın olmalı hiç gerçekleşmeyecek hep umut edilen bir ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yenilmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışmadı', 'yakismadi-riza-aslan-jae7k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aslına yine yakışmadı

yaşananlar

yine çaresizlik sardı

her bir yanı

yine yalnızlıklar kol gezmeye başladı

beynin ücra köşelerinde

sahipsizlik-tek başınalık-

yine vurmaya başladı

en can alıcı yerlerden

sözler tükendi yine', 'aslına yine yakışmadı yaşananlar yine çaresizlik sardı her bir yanı yine yalnızlıklar kol gezmeye başladı beynin ücra köşelerinde sahipsizli...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yakismadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Yok', 'yanimda-yok-riza-aslan-p3u3m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ellerimde olanlar

tek tek uçup gidiyor

dün benim dediğim

kokusunu sahiplendiğim

bu gün yanımda değil', 'ellerimde olanlar tek tek uçup gidiyor dün benim dediğim kokusunu sahiplendiğim bu gün yanımda değil...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanimda-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce De', 'senden-once-de-riza-aslan-hrr7l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sanmaki senden önce de farklıydım ben

söyleyemediklerim vardı-her zaman ki gibi-

sevip de söyleyemediklerim çok oldu-yıllarca-

hayal edilen hep bir dost-sevgili-verdı

hiç bir zaman gelmeyecek', 'sanmaki senden önce de farklıydım ben söyleyemediklerim vardı-her zaman ki gibi- sevip de söyleyemediklerim çok oldu-yıllarca- hayal edilen ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senden-once-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Anlamlar', 'yeni-anlamlar-riza-aslan-aabgl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yeni anlamlar

yükledim yaşamıma

daha önce hiç tatmadığım

-korktuğum-', 'yeni anlamlar yükledim yaşamıma daha önce hiç tatmadığım -korktuğum-...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeni-anlamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiyor İçimden', 'gelmiyor-i-cimden-riza-aslan-xq6dr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gelmiyor içimden

gülümsemek

her gülümseyiş

bir mermi sanki

insanlara savurduğum', 'gelmiyor içimden gülümsemek her gülümseyiş bir mermi sanki insanlara savurduğum...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gelmiyor-icimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefes Alamıyorum', 'nefes-alamiyorum-riza-aslan-cj33y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'boğazım tıkanmış

nefes alamıyorum

derin nefesler çekiyorum hayattan

sömürüyorum

etrafımı çepe çevre saran havayı

bir dem çekiyorum

yıllanmış acılardan

kafam bulanıyor yine

yine nefes alamıyorum', 'boğazım tıkanmış nefes alamıyorum derin nefesler çekiyorum hayattan sömürüyorum etrafımı çepe çevre saran havayı bir dem çekiyorum yıllanmış...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nefes-alamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-oktay-yildiz-wjj5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sallanan eller

Yalnızlığı niteler

Surattaki gülümsemeler

Hüznü ifade eder.

Yüreğin volkan olur

Hayatın cehennem

Işık düşmanın olur

Karanlıksa tek dostun.

Lanet edersin bu hayata

Konuşursun yıldızlarla

Kimseye bakamazsın

Çünkü, bakacak biri bulamazsın

Yaşamaktan bıkarsın

İçinde yalnızlığı taşırsın.

(İstanbul-1996)', 'Sallanan eller Yalnızlığı niteler Surattaki gülümsemeler Hüznü ifade eder. Yüreğin volkan olur Hayatın cehennem Işık düşmanın olur Karanlıks...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yıldız']::text[], 8.5, '{"poet":"Oktay Yıldız","poet_slug":"oktay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeli Adam', 'golgeli-adam-ugur-arslan-e0res', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şehrin yakamozları 

Fakir bir yansımayla

Denizin dalgaları arasında

Saklambaç oynamaya başladı

Kıyıda gölgeli bir adam 

Dalgaları tutmaya,

Yakamozları bulmaya çalışıyor

Ve ağlıyor

Balıkçı motorları geçiyor açıktan

O,gözyaşlarını saklıyor

Ve belli etmiyor 

Yenilmişliğini son lodosa

Ve hırpalanmışlığını gece yağmurlarında

Kıyıda gölgeli bir adam

Öylece duruyor...

Bir sigara yakıyor gölgesinden gizli

Ve nemden tutuşmayan kibriti

Yüzünü aydınlatıyor

Kimsenin göremediği

Dönüp de bakılmayan

Ve balıkçı ağlarına takılmayan

Kıyıda gölgeli bir adam

Öylece duruyor 

Ve gözleri seni soruyor', 'Şehrin yakamozları  Fakir bir yansımayla Denizin dalgaları arasında Saklambaç oynamaya başladı Kıyıda gölgeli bir adam  Dalgaları tutmaya, Y...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/golgeli-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematikçinin Aşk-ı İlanı', 'matematikcinin-ask-i-i-lani-burcu-ucar-97d0w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni gördügüm anda çarpnlara ayrıldım

Elips yüzüne,matris gözlerine bayıldım

İşte dedim benim aradığım

İlk fırsatta aşkımı tümevarımla ispatladım

Logaritma sevgilim derdim sana

Hep hayal kurardık gelince bir araya

Koni şeklinde,üçgen şeklinde yuvamızda

Dizi dizi,seri seri çocuklarımızla

Tam sunacakken sana evlilik önerimi,

''analitiğimiz uymuyor''diyerek terk ettin beni

Oysa türevini alacak kadar sevmiştim seni,

Sana olan aşkım reeldi,lineerdi

Tanjantımı hesaplamadan giden vefasız sevgilim.

Rüyalarımda hep seni görörüm

Benim biricik hiperbolüm,minik parabolüm

Nerde eski detarminan,diskiriminant formülüm

Dön bana integralimi al signum yüzlüm

Eğer dönmezsen kahrımdan ölürüm

Bak şu kalbimin fonksiyonuna periyoduna

Asimptotumu bul da grafik çiz bana

Söz veriyorum'' konikçiğim'' demem sana

Seni çok seviyorum;ANLASANA...', 'Seni gördügüm anda çarpnlara ayrıldım Elips yüzüne,matris gözlerine bayıldım İşte dedim benim aradığım İlk fırsatta aşkımı tümevarımla ispat...', ARRAY['Türk Edebiyatı','Şiir','Burcu Uçar']::text[], 8.5, '{"poet":"Burcu Uçar","poet_slug":"burcu-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/matematikcinin-ask-i-ilani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar ağlıyor...', 'bulutlar-agliyor-hamdi-yulug-9sguh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çılgın gecenin koynunda,

Karanlığa aşkımı,

Gözyaşlarımla yazıyorum...

Umut yokluğunda,

Yine seni anıyorum,

Aşkını çığlık çığlığa,

Yüce dağların, doruğundan,

Yıldızlara,

Deryalara, 

Çöllere....

Haykırmak geliyor içimden,

Belki duyarsın feryadımı,

Yüreğinde yankılanır aşkım.

Bak yine, bulutlar ağlıyor,

Yüreğim sırılsıklam ıslandı.

Ama sen hala anlamadın,

Sana olan büyük aşkımı....

Umut yokluğunda, yine de;

Sevdanın yollarında yürüyorum.

Belki hayaline kavuşurum,

Seni bulurum umuduyla,

Gözlerimi karanlığa kapatmıyorum.....', 'Çılgın gecenin koynunda, Karanlığa aşkımı, Gözyaşlarımla yazıyorum... Umut yokluğunda, Yine seni anıyorum, Aşkını çığlık çığlığa, Yüce dağla...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bulutlar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolculuk Üstüne', 'bir-yolculuk-ustune-nazim-hikmet-ran-0750f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açıyoruz kapıları, 

kapıyoruz kapıları,

geçiyoruz kapılardan

ve biricik yolculu
..........
..........', 'Açıyoruz kapıları,  kapıyoruz kapıları, geçiyoruz kapılardan ve biricik yolculu .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-yolculuk-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelda', 'yelda-alper-altinisik-v997x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ağlama denizkızı,

İçim kan ağlasın.

Sen sadece gül !

Gül ki deniz kıskansın...', 'Sen ağlama denizkızı, İçim kan ağlasın. Sen sadece gül ! Gül ki deniz kıskansın......', ARRAY['Türk Edebiyatı','Şiir','Alper Altınışık']::text[], 8.5, '{"poet":"Alper Altınışık","poet_slug":"alper-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yelda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet beni', 'affet-beni-alper-dalkiliclar-9zcll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı yavaş yavaş kaybolurken

Ruhumdaki sıkıntıda yavaş yavaş artmaya başladı

Demin öyle bir gittinki yanımdan , 

Yanında tüm neşemi , mutluluğumuda götürdün.

Kalbime bir ok saplandı , gözlerim ıslak

Senın için sensizliğe ilk defa ağlıyorum.

Senin üzülmene dayanamıyorum.

Yüzünün asılmasına kahroluyorum...

Gün geçtikçe sana bağlanıyorum.

Kendimi kaybediyorum.

Bir resmin var bende bana gülen.

Birde sevgin beni ağlatan.......

Gene güneş doğuyor her zamanki gibi ,

Yine ben ayakta aklımda yine sen....

Ona aşkımı anlatıyorum defalarca ,

Sen ordayken  kulağına fısıldasın sevgimi diye.

Sensizliğimi haykırıyorum ona ,

Yanına geldiğinde sende hatırlar özlersin diye.....

''Seni kırdıysam affet ben kendimi affedemiyorum!''', 'Gecenin karanlığı yavaş yavaş kaybolurken Ruhumdaki sıkıntıda yavaş yavaş artmaya başladı Demin öyle bir gittinki yanımdan ,  Yanında tüm ne...', ARRAY['Türk Edebiyatı','Şiir','Alper Dalkılıçlar']::text[], 8.5, '{"poet":"Alper Dalkılıçlar","poet_slug":"alper-dalkiliclar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/affet-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-bora-i-seri-kjmej', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'böyle oldu bir kere ayrılmak gerek

başka bir yolu yok yok bir seçenek

bulursun seni kalpten sevecek

sonumuz böyleymiş ne yapmak gerek

üzme sevgilim üzme kendini

güzelsin bulursun başka birini

tereddütle haklıymış doğru söyledin

seni belkide hiç sevmemeliydim

bunları yazarken üzüldüm bende 

ihtirası acıyı döktüm kalemle

buymuş sonumuz söz yok kadere

ayrılmak artık şart oldu bize

nedeni sorma ne olursun bana

bütün suç bende günahı bana

şiirin devamını oku bırakma

oku ki seni sevmedim sanma

şakaydı sevgilim bırakırmıyım

birkere sevmişim ayrılırmıyım

gül üstüne hiç gül koklarmıyım

senden başkasını hiç ararmıyım', 'böyle oldu bir kere ayrılmak gerek başka bir yolu yok yok bir seçenek bulursun seni kalpten sevecek sonumuz böyleymiş ne yapmak gerek üzme s...', ARRAY['Türk Edebiyatı','Şiir','Bora İşeri']::text[], 8.5, '{"poet":"Bora İşeri","poet_slug":"bora-i-seri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil', 'karanfil-ali-riza-erdem-l18d4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karanfil huyluyuzdur

karanfil boylu 

düşersek eğer bir gül toprağa 

bir karanfil gibi 

sessiz

ve sakın düeriz 

sesi çok sonradan duyulur 

duyulur yüreklerle', 'karanfil huyluyuzdur karanfil boylu  düşersek eğer bir gül toprağa  bir karanfil gibi  sessiz ve sakın düeriz  sesi çok sonradan duyulur  du...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karanfil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazar''da Düğün Var...', 'hazar-da-dugun-var-hamdi-yulug-y784b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hazar''da düğün var balam!.....

Köpük köpük sevda dalgası....

Ak gelinlik giymiş Hazar,

Türk''ün türküsünü söyler bize;

Ah bir uzansam!

Bir uzansam Karadeniz''e,

Der gibi, yanık huzur...

Tarihin debdebesiyle

Kurulmuşken düğün;

Boy boy budanmış dalların

Gövdeye kavuştuğun gün,

Azeri, Kırgız, Özbek; Kazak, Türkmen,

Patlatıp arzı, çıktılar tümen tümen

Altın işlemeli, kurt başlı otağlar,

Kuruldu kıyısına Hazar''ın...

Selam durdu dağlar,

Hanlar hanı Oğuz Han''dan Alpaslan''a,

Fatih''ten, Yavuz''a dek,

Dizildi Hazar boylarına gaziler,

Bölük bölük, öbek öbek...

Döndü, Yesevice gönül pervanesi,

Yunus Yunus işlendi çevresi Hazar''ın...

Kavuşmak hevesiyle yandıkça nefes,

Türk! Türk adına susamışken herkes,

Yarıldı gökler, indi Korkut Ata;

Ak saçlı; akça koca,

Haykırdı Türk illerine;

Ey milletim!

Dini bir, lisanı bir

Birliğe koşan canlar,

Atatürkleşmiş Bilge Kağanlar,

Kavuşsun Hazar, Karadeniz''e...

Bunu gördüğün an,

Son söz, so vasiyetimdir inan;

Türk''ün vatanı bir

Adı soylu, büyük Turan.....', 'Hazar''da düğün var balam!..... Köpük köpük sevda dalgası.... Ak gelinlik giymiş Hazar, Türk''ün türküsünü söyler bize; Ah bir uzansam! Bir uz...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hazar-da-dugun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlar', 'anlar-nuri-bilir-ljhmj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve gün vururken penceremden eskimiş duygularıma,

Gün benim, hayat benim, sen benim oluyorsun ey sevgili.

Bütün unutulmuşluklar parlıyor gün ışığında,

Bir kez daha anlıyorum seni ne kadar, ne kadarını sevdiğimi.

Her şeyiyle benim için dönüyor dünya, dur desem duracak

Ama hiç durdurulur mu bir film en güzel anında,

Tam kahramanın yerinde kendinizi gördüğünüz zaman.

Ve rüzgar eserken penceremden yüreğimin yangınına,

Hasret benim, umut benim, gözyaşı benim oluyor ey sevgili.

Bütün vuslatların ışığı parlıyor yüreğime, aydınlanıyor yüreğim.

Bir kez daha anlıyorum seni ne kadar, ne kadarını özlediğimi.

Her şeyimle beni çağırıyor dünya, gel desem gelecek

Ama hiç durdurulur mu bir şarkı en duygusal anında,

Tam söyleyenin yerine kendinize ağladığınız zaman.

Ve ağaçların hışırtısı yankılanırken penceremden sensiz aşkıma

Sen benim, gözyaşı benim, şiir benim oluyor ey sevgili.

Bütün şairlerin duyguları yeşeriyor içimde,

Bir kez daha anlıyorum seni ne kadar, ne kadarını anladığımı

Her şeyiyle atıyor beni dünya, yalvarsam almayacak,

Hiç devam edilir mi bir ayrılığa, gözyaşının bile akamadığı anında 

Tam ağlanacak halinize güldüğünüz zaman.', 'Ve gün vururken penceremden eskimiş duygularıma, Gün benim, hayat benim, sen benim oluyorsun ey sevgili. Bütün unutulmuşluklar parlıyor gün ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Bilir']::text[], 8.5, '{"poet":"Nuri Bilir","poet_slug":"nuri-bilir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu vatan bizim....', 'bu-vatan-bizim-hamdi-yulug-yv2wp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi bölek dedi, kimi yıkalım, 

Buralara başka ülke kuralım, 

Daha biz ölmedik nasıl duralım, 

Ölürüm yıktırmam ülke bizimdir..... 

Senelerdir çile ile yoğrulan, 

Her gün bir köşede şehit olunan, 

Kundakta bebeğe kurşun sıkılan, 

Bölmek istenilen vatan bizimdir..... 

Türk''ün kaderi bu asırlar boyu, 

Çıkmadıkça canı değişmez huyu, 

Bizi bölmek isteyen kahpenin soyu, 

Bölünmez bu cennet vatan bizimdir..... 

Nice canlar gitti çakıl vermedik, 

Vatan namus deyip bedel ödedik, 

Yıkılmadık bu yoldan geri dönmedik, 

Övünülen bu cennet vatan bizimdir.... 

Kardeşiz dedikçe azıp durdular, 

Öğretmeni, çocukları vurdular, 

Anama, babama kurşun sıktılar, 

Yakılan yıkılan evler bizimdir...... 

Sakarya, Çanakkale, Gelibolu''da, 

Nerede ezan, bayrak, Türkler orada, 

Kefensiz yatan o şehitler buarada, 

Şehitler diyarı ülke bizimdir...... 

Bozkurt Hamdi canım feda vatana, 

Bu toprakta yatan şehit atama, 

Yeminim var vallahi yüce Mevlama, 

Ölmek istediğim vatan bizimdir.....', 'Kimi bölek dedi, kimi yıkalım,  Buralara başka ülke kuralım,  Daha biz ölmedik nasıl duralım,  Ölürüm yıktırmam ülke bizimdir.....  Senelerd...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-vatan-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-zeki-oz-xl9qx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Paşa bahçesinde yalnız oturmak nedir bilirmisin,

Bilirmisin bir bardak çayın yalnız başına limanında bir çay ne kadar acı olduğunu,

Boş sandalyeye bakan gözlerin boşluğu sevmemesini bilirmisin,

Yürek atar içindesindir el boştur tutacak yoktur bilirmisin,

Bilirmisin sen beni benim seni senin bendeki sensizliğini Bakamayan iki gözün gözüne hasret olduğunu Bilirmisin ,

Bilirmisin yaşlıdır gözler sabah yağmurları benim Bilirmisin,

Geceleri feryat gündüzleri hasret kimdir Bilirmisin, Kavaklar bile kısa kalır sevdanın yanında Bilirmisin,

Bilmem deme beni üzersin Bilirmisin1999.', 'Paşa bahçesinde yalnız oturmak nedir bilirmisin, Bilirmisin bir bardak çayın yalnız başına limanında bir çay ne kadar acı olduğunu, Boş sand...', ARRAY['Türk Edebiyatı','Şiir','Zeki Öz']::text[], 8.5, '{"poet":"Zeki Öz","poet_slug":"zeki-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilirmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısacası', 'kisacasi-beyazit-cenan-k9wt2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana seni söyle deselerdi

Kendimi söylerdim

Bana kendini söyle deselerdi

Seni söylerdim

Kısacası 

Sen bensin 

Bende senim', 'Bana seni söyle deselerdi Kendimi söylerdim Bana kendini söyle deselerdi Seni söylerdim Kısacası  Sen bensin  Bende senim...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kisacasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-levent-cokyuruyen-onpz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yapayalnız kalmıştı sokakta. Ağlıyordu, içliydi, dertliydi.

İki dudak olmuştu katili. Tek suçu masum sevgisiydi.

''''Çok güzel başlamıştık.'''' dedi gülümserken.

''''Bir kedi yavrusu gibi tatlı, elleri bulutlardan bile yumuşaktı.

Ama o gözleri... Gözleri benden yıldızlar kadar uzaktı.'''' dedi.

Bir şarkı mırıldandı sevgiyle acı karışmış sesiyle.

Sonra doğruldu ellerini yıldızlara doğru uzattı. Tuttu bir tanesini bana verdi. ''''Sen hiç bu kadar sevebildin mi?'''' diye sordu. Ağlamaklı oldum. ''''Hayır!'''' dedim.

''''Bu yıldızı yerine koyabilirsin belki.'''' dedi. ''''Nasıl?'''' diye sordum.

''''Onun gözleriyle ölürken!'''' dedi ve rüzgarı ardına alıp yaşlarla tozların birbirine karıştığı gözlerini silerek bulutlara kadar yükseldi ve gözden kayboldu.

Kahırdan kırlaşmış saçlarıyla cansız bedeni önümde yatıyordu.

Bileklerinden akan kan hala sıcaktı.

Ve hala seviyordu.', 'Yapayalnız kalmıştı sokakta. Ağlıyordu, içliydi, dertliydi. İki dudak olmuştu katili. Tek suçu masum sevgisiydi. ''''Çok güzel başlamıştık.'''' ...', ARRAY['Türk Edebiyatı','Şiir','Levent Çokyürüyen']::text[], 8.5, '{"poet":"Levent Çokyürüyen","poet_slug":"levent-cokyuruyen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-sunay-akin-tnkqa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıralanmış saksılar vardı 

limana bakan

penceremizin önünde

ve çiçekler arasında

ekmek kırıntıları serpen

martı yüzlü

bir anne

Terasta toplanan kadınlar 

limandaki beyaz geminin 

ışıkları yanınca

dedikodusunu yapmayı unuturlardı

tam o saatlerde sokaktan geçen

yazlık sinemadaki

biletçi kızın

Annesinin dizlerinin dibinden 

hiç ayrılmayan 

uslu bir çocuk gibidir

limandaki deniz

ama sokağa çıkıp

dalga olmak geçer

yüreğinden', 'Sıralanmış saksılar vardı  limana bakan penceremizin önünde ve çiçekler arasında ekmek kırıntıları serpen martı yüzlü bir anne Terasta topla...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/liman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekleyeceğim', 'seni-bekleyecegim-i-brahim-torun-eyrl5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bekleyeceğim 

Dalganın kıyıyı 

Toprağın suyu 

Çiçeklerin arıyı 

Beklediği gibi. 

Seni bekleyeceğim 

Aydınlığın karanlığı 

Gecelerin gündüzü 

Bugünlerin yarını 

Beklediği gibi. 

Sonbaharda yüzümde esen 

Rüzgar olacaksın. 

İlkbaharda üstüme yağan yağmur. 

Yazın beni kavuran güneş olacaksın. 

Seni bekleyeceğim 

Soğuk bir kış gecesinde 

Karanlığın içinden 

Çık da gel. 

Sıcak yatağım 

Seni bekliyor olacağım...', 'Seni bekleyeceğim  Dalganın kıyıyı  Toprağın suyu  Çiçeklerin arıyı  Beklediği gibi.  Seni bekleyeceğim  Aydınlığın karanlığı  Gecelerin gün...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-bekleyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece İki Hece', 'sadece-i-ki-hece-turgay-kadiroglu-la0f4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki heceli bir şiirin keşfine çıkalım 

Hadi kapat gözlerini ve dinle ki ikileri duyalım

Atom iki hece ve eşya da

Dünya, güneş, yıldız ve evren de

Hücre iki hece ve cenin de

Bebek, çocuk ve insan da

Duygu iki hece ve sevgi de

Alev, ateş, yangın ve keder de

Leyla ve Mecnun, sahra ve vaha

Aslı ve Kerem, Ferhat ve şirin de

Yağmur iki hece ve tohum da

Ağaç, yaprak, toprak ve mezar da

Canlı iki hece ve hayat da

Yaşam, ömür ve ölüm de

Deprem, zilzal, gece ve vakit de

Çığlık, yıkık, kayıp ve yardım da

Hızır ve deniz, İlyas ve şehir

İmdat ve yetiş, umut ve şükür de iki hece

Kader ve zaman, yazı ve yarın

Çaba amaç, sonuç ve ödül de

Bayrak ve Hilal, geçmiş ve çınar

Zincir, bilek, kılıç, haliç ve zafer de

Kalem, kitap, Kur ''an, igra ve ilim de

Mekke ve Kabe, Kudüs ve Aksa da iki hece

Adem ve baba, Havva ve ana 

Kabil ve kadın, Habil ve mazlum, arzu ve katil de

Zalim ve zulüm, Urfa, ocak, balık ve ırmak da

Melek ve şeytan, nefis ve gönül de iki hece

Musa ve asa, nefes ve İsa, Meryem ve doğum

Çarmıh ve çivi, acı ve sema da

Para, kazanç, zengin ve kibir de, 

Kimya, Karun, saray, inat ve yokluk da

İnkar, alay, sağnak, kaynakve tufan da

Kenan ve hüsran, Cudi, gemi ve nesil de iki hece

Melek, sorgu, kabir, doğru, yanlış ve ölçü de

Mahşer ve şahid, rahmet ve cennet de iki hece

Bedir ve kuyu, Uhud ve Halid

Hendekve Selman, İslam, fetih ve Halid de

Davud ve demir, Yusuf ve edeb

Yakup ve gömlek, Resul ve sünnet de sadece iki hece''', 'İki heceli bir şiirin keşfine çıkalım  Hadi kapat gözlerini ve dinle ki ikileri duyalım Atom iki hece ve eşya da Dünya, güneş, yıldız ve evr...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sadece-iki-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u Özledim', 'i-stanbul-u-ozledim-i-brahim-torun-xkdyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'özledim

Sabahları martı sesleriyle uyanmayı,

Sabahın alaca karanlığında balkondan İstanbul''u seyretmeyi,

Hani o köy ekmeği dedikleri, sıcacık, taze ekmeğini,

İnsanların koşuşturmacasını özledim,

Ordan oraya, şurdan buraya...

Nereye gittiklerini, nereden geldiklerini çözemesemde,

Özledim,

Ortaköyle sahile karşı oturup sigara ile çay içmeyi,

Balık ekmek, balık ekmek diye bağıran tergahtarlarını...

Haliçte balık tutan İstanbul halkını özledim,

Vapurun çıkardığı sesin kulaklarımda çınlamasını özledim,

Offf, Offf

Hani vardı ya,  o sahilde benim doğum günümü kutlamıştın,

Güneş batıyordu,

Gözlerim uzaklarda, derin düşüncelerde...

Özledim,

Seni özledim,

İstanbul''u özledim...', 'özledim Sabahları martı sesleriyle uyanmayı, Sabahın alaca karanlığında balkondan İstanbul''u seyretmeyi, Hani o köy ekmeği dedikleri, sıcacı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istanbul-u-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler', 'sevgiler-sabit-caynak-6i5a4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaçmak yok derinliklerinden gözbebeklerinin

Yüzünde dingin koyların sessizliği

Koşarsın uçarcasına doruklarına doyumsuzluğun

Sevgi kokulu barış güvercinleri kanatlanır yüreğinden

Tüm sevgilere, tüm insanlara ve yaşanacak aşklara', 'Kaçmak yok derinliklerinden gözbebeklerinin Yüzünde dingin koyların sessizliği Koşarsın uçarcasına doruklarına doyumsuzluğun Sevgi kokulu ba...', ARRAY['Türk Edebiyatı','Şiir','Sabit Caynak']::text[], 8.5, '{"poet":"Sabit Caynak","poet_slug":"sabit-caynak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-bekir-sitki-ozer-b05xz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak bir nokta;küçük

Yaşamak bir sevgi;yüce

Yaşamak bir ölü;suskun

Yaşamak bir nehir;coşkun

Yaşamak bir oyun;ellerinde

Ve yaşamak bir hak, anlamını bilene!', 'Yaşamak bir nokta;küçük Yaşamak bir sevgi;yüce Yaşamak bir ölü;suskun Yaşamak bir nehir;coşkun Yaşamak bir oyun;ellerinde Ve yaşamak bir hak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albatros Yalnızlığı', 'albatros-yalnizligi-recep-garip-qr6th', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık bir yarasa uçuşu

Gecede zehrini akıtır içime

Bir ebabil bir saka kuşu

Arar bulur beni

Belki de bir albatros

Mavi türkülerini söyler

İçime inen boğazıma düğümlenen

Belki de alır götürür beni

Uçsuz bucaksız gökyüzüne

Yalnızlık bir yarasa

Çarpar suratıma

Dağlar yamaçlarına vurur beni

İçime öksüz çocuklar oturur

Bir şiir düşer gönlüme

Gönlüm bir çöl esrarıdır

Kumlar gökyüzünün martıları

Rüzgar alır kanatlarına

Savurur uçurur düşürür yüreğime

İşte kum tepecikleri 

İşte kumdan yapılmış evler

İşte testiler su içilen

Yalnızlığı bakraçlarında

Sararmış ekin tarlalarıdır yediveren

Bir çınaraltı uykusudur öğle üzeri

Bir tarhana tarlası damüstleri

Annemin elinden dökülen nakış

Yazmalarıdır genç kızların

Genç kızlar bir saman alevi gibidir

Yalayıp geçer suratlarını 

Delişmen gençlerin

Ve yalnızlık

Bir ilkbahar dökümü

Çiçeklerin kokuların kaybolup gittiği

Bir hilale yasla göğsünü 

Yıldızlar kıskansın seni

Zülüflerin anka kuşuna

Bakışların oğlak burcuna çevrilsin

Ayinler zülfü yari okşasın

Kalksın yalnızlık duldaları

Budalalar kahrolsun

Ve hercai yansımlar düşürülsün

Türküler söylensin nazlı dağlara

Ve ıtırlar adına 

Bilcümle çiçekler adına

Yemekler kaynatılsın halaylar çekilsin

Bir aşkı memnu hikayesi yazılsın

Ve şöyle başlasın

Güzel mi güzel yiğit mi yiğit

İki dağın al yazmalı telli duvaklı bir gelini

Kartal bakışlı bahadır yürekli

Gören vurulur suda durulur cinsinden

Bir rüzgarın oğlu varmış

Çok şiddetli mi şiddetli bir rüzgâr çıkmış

Ardından fırtınalar karanlık bulutlar

Gök gürlemiş yer çatlamış

Dağlar ayrılmış birbirinden

Olan biteni gören olmamış bir daha

Bu nedenledir yandığım

Yeter yüreğime düşen ateş

İbrahim‘de  güle çevrilen ateş

Neredesin gel kuşandır beni

Yüreğimden kaldır ateşlerini

Yalnızlık bir ateştir

Kavurur tüketir

Külünü havaya savurur insanın 

Gel yarasaları uçur yüreğimden

Yasla yüreğini göğsüme

Hilali başına taç

Saçlarını rüzgâr yap

Savur yalnızlığımı

Albatroslar götürsün gökyüzüne

7 Şubat 2000', 'Yalnızlık bir yarasa uçuşu Gecede zehrini akıtır içime Bir ebabil bir saka kuşu Arar bulur beni Belki de bir albatros Mavi türkülerini söyle...', ARRAY['Türk Edebiyatı','Şiir','Recep Garip']::text[], 8.5, '{"poet":"Recep Garip","poet_slug":"recep-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/albatros-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Başlasak', 'nereden-baslasak-bekir-sitki-ozer-soug6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nereden başlasak

Gülmeden aglasak mı?

Erisek mi usul usul,

Bir hiçte mi boğulsak?

Ucuz kahramanlara özenip,

Yıksak mı kartondan devleri?

Yoksa düşlerde öcüler mi yaratsak?

Nereden başlasak?

Zincirleri mi parçalasak,

İnançları mı terk etsek?

Öfkeyi, nefreti sabırlamı yoğursak?

Ve beklesek bir şeyleri,

Beklerken gururla mı ölsek,

Yoksa yaşamak için,herşeye boyun mu eğsek?

Nerden başlayıp,nerede bitirsek?', 'Nereden başlasak Gülmeden aglasak mı? Erisek mi usul usul, Bir hiçte mi boğulsak? Ucuz kahramanlara özenip, Yıksak mı kartondan devleri? Yok...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nereden-baslasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılardan Sızıntılar', 'anilardan-sizintilar-bekir-sitki-ozer-g65fj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anılardan sızıntılardır bugüne taşan

Dirhem dirhem tüketilen umutlar

Fersiz renkler,

Hasret akşamlarında yitik

Terli bir öpüşmedir, soluk soluğa

Küflenmiş sevdalardan geriye kalan.

Yılların aymazlığında,

Törpülenir isyanlar

Yitirdiklerimizin anlatımı da vardır elbet

O da;

Dudaklarda acı bir gülümsemedir...', 'Anılardan sızıntılardır bugüne taşan Dirhem dirhem tüketilen umutlar Fersiz renkler, Hasret akşamlarında yitik Terli bir öpüşmedir, soluk so...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anilardan-sizintilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamadın', 'olamadin-bekir-sitki-ozer-bhr6l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bahar yağmurudur

Güneşin ışıklarıyla yağan.

Hasrettir kurumaya,

Yüz tutmuş yeşillikler

Bahar yağmuruna.

Yine onlardır, bahar yağmuruyla

Hasret gideren

Ya ben!

Ya ben! insafsız

Yıllar var ki hasretim sana

Bir bahar yağmuru kadar bile olamadın!', 'Bir bahar yağmurudur Güneşin ışıklarıyla yağan. Hasrettir kurumaya, Yüz tutmuş yeşillikler Bahar yağmuruna. Yine onlardır, bahar yağmuruyla ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma I', 'ogluma-i-guner-karabulut-py6xu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazılmamış bir kitaptır  önünde duran yaşam

Yazılmamış bir kitap sen yaşadıkça yazılacak  olan

Boşuna bekleme bu kitabın yazarını

Sen kendin yazacaksın hayatının romanını

Zamana bel bağlama zaman seni oyalar 

Ellerinin altından kayıp gider sayfalar

Her batan gün bir sayfayı alır senden götürür

Sen zamanı yaşamadan zaman seni bitirir

Finale yaklaştıkça başlar göç hazırlıkların

Gözlerinin önünden geçer tüm yazdıkların

Beğenmezsen kitabın ne kaderine küs ne feleğe küfret

Sen yazdın bu kitabı bunu kabul et', 'Yazılmamış bir kitaptır  önünde duran yaşam Yazılmamış bir kitap sen yaşadıkça yazılacak  olan Boşuna bekleme bu kitabın yazarını Sen kendin...', ARRAY['Türk Edebiyatı','Şiir','Güner Karabulut']::text[], 8.5, '{"poet":"Güner Karabulut","poet_slug":"guner-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogluma-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgündeki Sevdalar', 'surgundeki-sevdalar-bekir-sitki-ozer-fsihj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemlerin doruğa ulaştığı an,

Terk edilmiş sevdanın

Tutsağısın artık...

Portakal çiçeklerinin kokusundan bile,

Nefret edersin...

İliklerine dolar,

Yanlızlığın acımasızlığı.

Kendini,

Bir virane,

Bir döküntü gibi hissedersin.

Bana baksana sen!

Sürgüne yollanmış sevdalardan

Ne beklersin?', 'Özlemlerin doruğa ulaştığı an, Terk edilmiş sevdanın Tutsağısın artık... Portakal çiçeklerinin kokusundan bile, Nefret edersin... İliklerine...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/surgundeki-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalar Dindiğinde', 'firtinalar-dindiginde-bekir-sitki-ozer-466aa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oysa gemiler kalkmaya hazırdı limanda

Çaresiz suskun tayfalar

Kuşkulu gözleri çok uzaklarda

Şimdi beklemede herşey

Sürüncemede...

Gride kaybolmuş bütün renkler

Martılar pusmuş kuytulara,

Dalgalarda belli bir isteksizlik

Öfkeleri kayalarda patlamakta.

Bomboş sokaklarda sessizlik

İnsanlar korkudan kaçmakta

Sevgililerin gözleri yaşlı

Dönmeyen gemileri gözlemekte

Oysa gemiler umutla yüklü

Fırtınanın dinmesini beklemekte

Ama şimdi herşey

Sürüncemede...', 'Oysa gemiler kalkmaya hazırdı limanda Çaresiz suskun tayfalar Kuşkulu gözleri çok uzaklarda Şimdi beklemede herşey Sürüncemede... Gride kayb...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/firtinalar-dindiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-bekir-sitki-ozer-qm5cb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen giderken

Beraberinde umutlarımı götürdün

Karanlıkları bıraktın bana ,

Düşlerime kara bir gölge gibi düştün.

Gözlerine bakınca aralanırdı, karanlıklar

Işık selinde boğulurdum

Gülünce nisan yağmurlarında 

Islanmış gibi olurdum.

İliklerime kadar ürperirdim

Dokununca ellerime,

En şiddetli depremleri yaşardım

Başım dönerdi, sarsılırdım.

Tuzlu ıslak öpüşmelerinde,

Nefesim düğümlenirdi

Soluk soluğa kalırdım.

Sen giderken 

Beraberinde güzellikleri götürdün

Yıkıntıları bıraktın bana.

Sevda küskünü yüreğime,

Ateş gibi düştün...', 'Sen giderken Beraberinde umutlarımı götürdün Karanlıkları bıraktın bana , Düşlerime kara bir gölge gibi düştün. Gözlerine bakınca aralanırdı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-giderken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Seni', 'yasamak-seni-bekir-sitki-ozer-clv07', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak seni,

Bir öykü güzelliğinde

Yaşamak seni,

Solmuş bir çiçek çaresizliğinde

Yaşamak seni,

En mahşeri kalabalıklarda

Yaşamak seni,

En sessiz yerinde gecenin

Yaşamak seni,

Ölüm suskunluğunda

Yaşamak seni,

Bir çocuk çoşkunluğunda

Kısacası yaşamak:

Seni sensiz,

Seni sende yaşamak', 'Yaşamak seni, Bir öykü güzelliğinde Yaşamak seni, Solmuş bir çiçek çaresizliğinde Yaşamak seni, En mahşeri kalabalıklarda Yaşamak seni, En s...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkık Ve Kırık', 'yikik-ve-kirik-bekir-sitki-ozer-tono4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkık ve kırıksa tüm umutların

Bir noktadan farkı yoktur yaşamın

Ve karanlıklar içinde ki,

Bir ışık özleminde ise bu çırpınışlar

Gözyaşlarında yitirilmiştir umutların

Kan ağladığın gecelerde ki hırçınlığın

Yanlızlığın içinde ki zavallılığın

Lanet yağdırdığın sevgiye,

Tekrar dönüşünde ki anlam

Bir ışık arayışıdır yoklukta

Yıkık ve kırıksa tüm umutların...

Uçurumların diplerinde

Açan çiçeklerdir aradıkların

Yokluk ile varlık arasında ki

Bir bağ gibi tıpkı...

Ulaşamazsın!...

Ellerin boşlukta kalır,

Gözlerin çiçeklerde

Ve gözyaşların düğümlenir yaşamın,

Yıkık ve kırıksa tüm umutların...', 'Yıkık ve kırıksa tüm umutların Bir noktadan farkı yoktur yaşamın Ve karanlıklar içinde ki, Bir ışık özleminde ise bu çırpınışlar Gözyaşların...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yikik-ve-kirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-bekir-sitki-ozer-f0r8t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neredesin?

Çöllerde susuz kalmışcasına

Nefesini hissetmek istediğimde...

Neredesin?

Herşeyi kadere yükleyip

Gözyaşlarımla sevgini yaşattığımda...

Neredesin?

Gece yarılarında uyanıp

İsmini ilahi bir dua gibi haykırdığımda...

Neredesin?

Kendi kendime gözdağı verip

Terk edilmişliğimi gizlemeye çalıştığımda...

Neredesin?

Geç vakit yollara düşüp 

Sahte kabadayılar gibi, koca kente kafa tuttuğumda...

Neredesin?

İliklerime kadar yanlızlığıma gömülüp

Yaşama sevincimi yitirdiğimde...

Neredesin?

Çaresizliğin ezikliği altında

Kendi kendimden tiksindiğimde...

Neredesin?

Bir heykel donukluğunda kaskatı kesilip,

Ölmeyi düşündüğümde...

Neredesin?', 'Neredesin? Çöllerde susuz kalmışcasına Nefesini hissetmek istediğimde... Neredesin? Herşeyi kadere yükleyip Gözyaşlarımla sevgini yaşattığım...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Özer']::text[], 8.5, '{"poet":"Bekir Sıtkı Özer","poet_slug":"bekir-sitki-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/neredesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bile Bile Karanlık Yola Sapıyoruz...', 'bile-bile-karanlik-yola-sapiyoruz-nur-kayapinar-mf9im', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok garip bir duygu olsa gerek sevgi

Hem hissetmesi zordur,hemde hissedince kopması

Sevmedim canı gönülden hiç bir erkeği

Onun kadar.

Çok yakındık birbirimize ama 

aramızda belirlenmiş bir sınır vardı.

Bile bile karanlık yola sapıyorduk.

Birlikte bir çok engeli aşmış,herşeyin

üstesinden gelmiştik ama bu 

herhalde en zor olanıydı.

Biz de zoru başarmaya çalışıyorduk zaten.

Ama hayır olmazdı...

Bu başarılamayacak bir zorluktu.

Ne kadar önemli olsa da zoru başarmak,

bunu başarmak hiç bir yiğidin harcı değildi.

Çünkü bunun adı ''ayrılıktı.''

Biz bunu ancak bu sene yaşadık.

Çok yakındık birbirimize ama 

aramızda belirlenmiş bir sınır vardı.

Bile bile karanlık yola sapıyorduk.

Ve ayrılmıştık abi.

Sen okumaya gitmiştin.

Bense sevinmem yerine sen okurken 

gözlerim yaş dolu yolunu gözlüyordum...

Sesim kısılmış,öksürüyorum

Bir de soğuktan üşütmüşüm herhalde.

Bu gün senin battaniyeni aldım üstüme

iyi geldi,çok iyi ısıttı beni.

Bugün-yarın birşeyim kalmaz telaşlanma.

Sen nasılsın abi?

Sen de aramızda bu kadar mesafe 

Olmasına rağmen biraz olsun

yaklaşabildin mi bana?

Bunu için çaba harcadın mı?

Kendine oralarda benim yerime koymak için 

birilerini buldun mu?

Yoksa halen aramakta mısın?

Demek aramadın bile,ve bunu sorduğum için bana darıldın!

Tamam tamam şaka yapmıştım zaten.

Ne ben ne de sen yerimizi kimse tutamaz bizim,

kendi gözümüzde.

Çok yakındık birbirimize 

Ama aramızda belirlenmiş bir sınır vardı.

Bile bile karanlık yola sapıyorduk.

Bu yolu aşabilmek için de 

yine beraber çaba harcayacağız.

Senelerce...

Elele...

   (15.10.2000-PAZAR)', 'Çok garip bir duygu olsa gerek sevgi Hem hissetmesi zordur,hemde hissedince kopması Sevmedim canı gönülden hiç bir erkeği Onun kadar. Çok ya...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bile-bile-karanlik-yola-sapiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Bir Gün', 'ama-bir-gun-ruya-ersoy-w6d0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekler çok güzeldir ama bir gün solar

Parada hoştur ama bir gün biter

Çocuklarımıza çok bağlıyızdır

 Ama bir gün uçup giderler

Sevmek sevilmek çok güzeldir ama bir gün

Kalbinden hissedersen senden hiç ayrılmaz

Sonsuza kadar senle birlikte olur', 'Çiçekler çok güzeldir ama bir gün solar Parada hoştur ama bir gün biter Çocuklarımıza çok bağlıyızdır  Ama bir gün uçup giderler Sevmek sevi...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ama-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sukutu Hayal', 'sukutu-hayal-abdulkadir-sezgin-f3yk4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani çocukluğumdaki o tatlı haz annem

O saf çocukluğum ömre bedeldi

Gelmedi çiçeklerle bezenmiş beklenen yaz annem

Hani yarınlar dünden güzeldi

Dizinde birazcık ağlasam annem

Dünyaya geldim dene buldum annem

Sonbirkez boynuna sarılsam annem

Ve gitsem...Bu hayattan yoruldum annem', 'Hani çocukluğumdaki o tatlı haz annem O saf çocukluğum ömre bedeldi Gelmedi çiçeklerle bezenmiş beklenen yaz annem Hani yarınlar dünden güze...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Sezgin']::text[], 8.5, '{"poet":"Abdülkadir Sezgin","poet_slug":"abdulkadir-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sukutu-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istanbul', 'istanbul-resul-efe-bg7si', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eli kirli bir kadındı İstanbul

gözyaşlarının ardına saklanmış

salak geceleri sorgulayan

yıkıma uğramış duygular içinde 

sessiz sakin kahpelikler yaşatan

eli kirli bir kadındı İstanbul

sözüm meclisten dışarı

istanbul- İstanbul''du

                        14 Ekim kozyatağı', 'eli kirli bir kadındı İstanbul gözyaşlarının ardına saklanmış salak geceleri sorgulayan yıkıma uğramış duygular içinde  sessiz sakin kahpeli...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/istanbul-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Yaranamadım', 'ben-sana-yaranamadim-resul-efe-ryet3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yorgun akşamlardı sensizliğin acısını hissettiren

ve bir damala gözyaşı

mutluluğum kırık bir dal parçası üstünde düşerken

akıp giden film şeridiydi hayat

ben sana yaranamadım 

tutamadım elinden

ben zaten hayırsızdım 

sen benden hayırsız çıktın

ben sana yaranamadım

vapur çığlıklarıydı iç çekişlerim 

sigara dumanı hayalim

yanında

okyanusa açılmış bir sandal gibi benliğim

ben sana yaranamadım

okyanuslarla dalga geçtim

yağmurlara sen sebep dedim

üzgün kadehleri sen bildim

ben sana yaranamadım

çünkü ben sana acı veremedim

                             13 ekim kozyatağı', 'yorgun akşamlardı sensizliğin acısını hissettiren ve bir damala gözyaşı mutluluğum kırık bir dal parçası üstünde düşerken akıp giden film şe...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-sana-yaranamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzet Ki', 'farzet-ki-umit-yasar-oguzcan-rthz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farzet ki;geri gelmiş o gamsız devir

Delicesine sevdiğin senin olmuş

Bir bahar sabahı sahilde seninledir

Yanan alnını alnına dayamışsın

O incecik elleri ellerindedir

Farzet ki;mazidir devamı yarının

Sevdiğin başını dizlerine koymuş

Bahar bahar kokan siyah saçlarının

Her telini ayrı ayrı öpmektesin

Ve tadı dudağında avuçlarının

Farzet ki;buldun kış içinde baharı

Rüzgar yine ılık ılık esmektedir

Aynı şehirde,aynı deniz kenarı

Köpükler,dalgalar ve sonsuz mavilik

Tekrar yaşıyorsun hatıraları

Farzet ki;denizde beraberce yüzmüş

Sonra sıcak kumlara uzanmışsınız

Yine evvela seni yalvartmış,üzmüş

Ve dolanmış boynuna o sedef kollar

Kumlar altın sarısı, dalgalar gümüş

Farzet ki;doğup büyüdüğün yerdesin

Caddeler aşina insanlar tanıdık

Aksi kulağında sevdiğin sesin

O dudakların tadı dudaklarında

Velhasıl yine o eski günlerdesin

Farzetme yeter yaşadığın bugündür

Ne sevdiğin yanında ne o yerdesin

Çekil garip odana ışığı söndür

Söyle;''Nerdesin ey sevgili nerdesin?''

Söyle; o türkü senin eski türkündür.', 'Farzet ki;geri gelmiş o gamsız devir Delicesine sevdiğin senin olmuş Bir bahar sabahı sahilde seninledir Yanan alnını alnına dayamışsın O in...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/farzet-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'korkular', 'korkular-ahmet-sahin-soner-qeasf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlıklarda kaldı korkularım,

Yağmurlar yağdırdım üzerine

Ve rüzgarlarla süpürdüm izlerini ...

Korkularımı siliyorum gecenin ferinde,

Ve ıslanan sokaklarda bıraktığım düşlerimi,

Beyaz bir buluttu üzerime çektiğim,

Ve ıslak sigarımı dumanıydı sırdaşım.

Yıldızlar ısıtırdı yüreğimi,

Yağmur buğusunda kapanan yıldızlar,

Beyaz bir buluttu yüreğimi ısıtan

Beyaz bir buluttu üzerime çektiğim yorgan

Karanlıklarda bıraktım korkularımı,

Gecenin kızıl benzinde,

Denizler üzerinde süzülen martılar vardı

Ve yalnızlığına sığındığım yağmur taneleri ,

Umarsızca hafiften esen bir rüzgarda ,

Kaybolsun diye savurduğum korkularım,

Korkularımı yargılıyordum karanlıklarda 

Bir haykırış vardı yüreğimde 

Bir çıkış yolu arefesinde ,

Yeşerttiğim umutlarım vardı

Ve kararttığım korkular.

Korkmak istemiyordum korkmaktan 

Ve gece perdesini araladı ansızın,

Yıldızlar ısıttığı yüreğimi,

Ayın gülümsemesiydi yüzümde yansıyan

Yine dostlarım ışıldıyordu uzaklarda,

Sıcaklığına savunduğum 

Beyaz bir yağmur bulutuydu sevgilim,

Korkularımla hesaplaşmıştım gecenin karanlığında,

Gece perdesini indiriyordu, 

Ve perdesine iğnelediği birkaç yıldızdı karşımda duran

Alaforoz olmuştu denizlerin üzeri,

Uzaklarda güneşin sıcaklığıydı yüzeme vuran,

Korkularımı karanlıklarda bıraktım .......', 'Karanlıklarda kaldı korkularım, Yağmurlar yağdırdım üzerine Ve rüzgarlarla süpürdüm izlerini ... Korkularımı siliyorum gecenin ferinde, Ve ı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/korkular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gittin', 'gittin-ahmet-sahin-soner-znou3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittin !

Işıklar söndü bir bir 

Denizler yakamozsuz kaldı 

Martılar denizsiz 

Ufuksa kızılsız 

Gittin !

Doğmadı bir daha güneş 

Ay ışımadı yüzümüze 

Renkler vermedi , yıldızlar gökyüzüne

Deniz fenerleri tarif etmedi , yolları

Rotasız kaldı karaya vurdu gemiler

Çiçek açmadı bir daha

Denizin çocukları gülmez oldu

Gittin !

Yürekler alabora oldu 

Orman örtüsüz 

Kuşlar tüysüz 

Bir deli yürek

Sevgi dolu bir yürek kaldı 

Gittin !

Bomboş şimdi aynalar

Yansıyan yüzüm yok aynada 

Ben yokum , Şiirlerim yok 

Gittim ! 

 Senle birlikte ...........

25 Haziran 2000', 'Gittin ! Işıklar söndü bir bir  Denizler yakamozsuz kaldı  Martılar denizsiz  Ufuksa kızılsız  Gittin ! Doğmadı bir daha güneş  Ay ışımadı y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gittin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR SEVDA MASALI', 'bi-r-sevda-masali-ahmet-sahin-soner-ma1ax', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana Bu  Sözlerimi Gözlerine Bakarak Söylemek İsterdim

Ama Yoksun Şimdi , Bir Yıldızsın Uzaklarda , Ötelerde  ..........



Mavi denizlere dalmışım , akşam kızıllığında

Kızıl kısa saçlarını okşuyorum rüzgarın

Akşam rüzgarı serinliğinde , savrulan titrek bedenim

Ve balıkların , yakamozla olan oyununu seyrediyorum ;

Dramatik bir komedya işte , karanlıklarda umutlarım

Sessizlik içinde yanıp sönen yıldızlar gibi ,

Ve sonsuzluğu arayan bir balıkçının hayallerinde  ,

Susturduğum martıların sesleriyle korkularımı arıyorum ,

Gün doğumlarının mutluluğu ile dolan yüreğim

Ve günbatımlarında sessizliğine büründüğüm kızıllıkta

Yeni denizler keşfetmek uğruna

Kırdığım okul günlerini hatırlıyorum tebessümle

Sırf gökyüzünde süzülmek uğruna verdiğim ödünleri

Bir martının kanadında



Uzak sahillere yol almak sevdası vardı ya

Hani vardı ya ikimiz için çizdiğimiz resimler

Hiç bestelemediğimiz mısralarımız vardı hani bizden

Hadi kaldır kafanı topraklardan ,

Gözlerime bak utancını yargılayalım bir bir

Rıhtımın bir köşesinden dalalım uzaklara

Alabildiğine uzatalım ellerimizi batan güneşe

Yelkenliler getirdim senin için

Hadi binip gidelim o saçlarının rengi ufkun kızıllığına

Martılara eziyet olmasın , yormayalım beyaz kanatlarını

Bize yol göstersin yunus balıkları

Uzak denizlere doğru uçsun beyaz güvercinler

Yeniden ay ışığında yıldızları sayalım seninle



Yakamadığımız gecenin ışıklarını yakalım

Hiç kimse kısıtlamasın yıldızları sayabilme özgürlüğümüzü

Hiç kimse gece ortasındaki yalnızlığımızı

Hadi tut ellerimi , denizler üzerinde koşalım desem .........

Ama yoksun  ...............

Gözlerin , gözlerinde yok

Gözlerimden senin için akan yaşları hisset

Ve sonsuzluğun düşlerini kurmak sensiz

Kor ateşler üzerinde yürümenin acısı var yüreğimde

Ama sen yoksun !

Gidiyorum karanlıklara doğru denizler üzerinde

Söndürüyorum gecenin tüm ışıklarını

Mavi denizlere dalıyorum serin sulara

Seni sular gibi , denizler gibi sevdim

Bir avuç umutsuzluğa umut bağladım senin için

Senin için resmettim akşamın kızıllığında martıları

Ve sessizliğine büründüğüm karanlığın içinden söküp aldığım umutları

Senin için denizler aldım , ışıklar yaktım üzerine

Gel dedim uzattım ellerimi  .................. Gelmedin

Ben gittim karanlıklardayım

Yalnızım , hiç sevmediğim ıssızlıkta

Dalarak gözlerimle o mahur sonsuzluğa yavaş yavaş

Sizsice kalbime saplanan bir yasal mermisi sızısıyla

Sana getirdiğim yelkenlilerin avam kamarasında .................

BEYAZ BİR MARTININ DÜŞLERİNDE RESMETTİĞİ  ,  MAVİ SULARDA SESSİZCE İLERLEYEN YELKENLİLERDEYİM

BİR AVUÇ UMUDA DEMİR ALMIŞ GİDİYORUM  , O SAÇLARININ RENGİ GECENİN KIZILLIĞINA DOĞRU .......................

AHMET ŞAHİN SONER    19.07.1999

( GECE KIZILLIĞINDA KÜLLENMİŞ AŞKLAR )', 'Sana Bu  Sözlerimi Gözlerine Bakarak Söylemek İsterdim Ama Yoksun Şimdi , Bir Yıldızsın Uzaklarda , Ötelerde  .......... Mavi denizlere dalm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bir-sevda-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiremitli Yakamozlar', 'kiremitli-yakamozlar-ahmet-sahin-soner-21mx4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece sabaha açmış kanatlarını 

Ciğ düşmüş karanlıklara , kiremitlere

Saat 06:26 aylardan ekim 

Bir pazar sabahı alacakaranlığındayım.

Ay süzülüyor penceremden içeri 

Karanlıkta yazıyorum şiirlerimi 

Ay'' ın rengarenk yakamozunda gece 

Kiremitler parıldıyor gözlerimde,

Gözlerin gibi yüreğime.

Hiç bilmediğim bir karamsarlıkta 

Yaşanası aşkımızın yoğunluğunda.

Ay vuruyor geceye sevgilim

Ay vuruyor çiğde ıslanmış kiremitlere 

Gözlerin gibi parıldıyor yıldızlar son kez.

Karanlıkta yazıyorum şiirlerimi 

Neden mi diye sorma 

Senden kalma bir şarkı yankılanıyor.

Konuşamıyorum , konuşamıyorum , konuşamıyorum

Nedenini çözemediğim bir sürünceme işte 

Ağlamıyorum 

Ağlamıyorum desem’ de gözlerim doluyor işte,

Ama seninde doldu gözlerin hissetim işte

Gecenin ay''la olan oyunu 

Kiremitlerde yakamozlar

Ve senli geçen bir gece işte , ama sensiz

İlk defa karanlıkta yazıyorum şiirlerimi

Derinliklerde sessiz bir yerde kalmış yüreğim

Dayanamıyorum , 

Telefonunu çaldırıyorum 

Biliyorum uyumuyorsun 

Uyu diyorsun ama uyumuyorsun

Alacakaranlıktan aydınlığa dönüyor saatler

Ve yakamozlar kiremitlerde

Ay batıyor aydınlığa 

Sen doğuyorsun günüme

Kiremitlerde yakamozlar var gözlerinden

Ay gibi , mavi bir yastık gibi

Ve senin nefesin esiyor bedenime 

Esiyor sabahın esintisi

Sen kokuyor sabah

Kulağıma fısıldıyorsun

Sesini hissediyor yüreğim 

Hissetmeden edemiyor ki 

Sen olmuş kalbimin yarısı 

Kiremitlerde yakamozlar

Ayın ısıltısında gözlerin 

Gecemde , gündüzümde hep sensin', 'Gece sabaha açmış kanatlarını  Ciğ düşmüş karanlıklara , kiremitlere Saat 06:26 aylardan ekim  Bir pazar sabahı alacakaranlığındayım. Ay süz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kiremitli-yakamozlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutamıyorum', 'seni-unutamiyorum-ahmet-sahin-soner-k01pc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu satırlara başlarken yine senidüşünüyorum

Seni içimden silip atamıyorum ; - Allah kahretsin

Gözlerim kapanıyor , ellerim titriyor

Sözler evet hakaret dolu sözler 

Boğazımda düğümleniyor

Kalbimi bir başka burukluk kaplıyor bu gece  Ahhh !!

                                                          Seni Unutamıyorum .....

Lanet tohumları ekiyorum kalbime . – neden mi !

Seni düşüncelerimden , duygularımdan , aklımdan silmek için

Belki bu düşüncelerim hatırlatıyor seni bana

İşte o an deli gibi oluyorum

Geriye dönüp seni ve sevdamızı hapseden yılların içinden

Seni söküp almak , yeniden sevmek istiyorum

Şimdi her ne kadar seni sevmiyorum desem de ; - Ben 

                                                              Seni unutamıyorum ......

Lanet yağdırıyorum seninle geçen günlere 

Bir yandan da hasretini çekiyorum o güzelim günlerin

Bir karamsarlık fırtınası içerisinde 

Yelkenleri alabora olmuş , yelkenliler gibi

Sığınacak bir liman , bir dost arıyorum 

Sana ulaşmak istiyorum , Seni arıyorum 

                                                           Seni unutamıyorum ..........

Sonbaharda yapraklarını dökmüş ağaçlar gibi 

Başı boş ağaçların ortasında , seni arıyorum

Hatırlarsın işte , yine o eski koruluktayım 

Ilık ılık esen hani bizim rüzgarımıza kaptırmışım kendimi

Uçan kuşları , cisil cisil yağan yağmuru seyrediyorum

Sırf seni unutmak için biliyormusun

Yokluğunun üzerinden yıllar geçti ama ..... – Ben 

                                                    Seni Unutamıyorum ..........

28 Ocak  1993', 'Bu satırlara başlarken yine senidüşünüyorum Seni içimden silip atamıyorum ; - Allah kahretsin Gözlerim kapanıyor , ellerim titriyor Sözler e...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-unutamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz feneri', 'deniz-feneri-ahmet-sahin-soner-kyn7w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlıkta yanıp söner deniz fenerleri 

O hep oradadır aslında 

Gel gör ‘ ki sen ancak parıldadığında ,

İşte o anda fark edersin var olduğunu

Bilmelisin ki her sönüş ,

Bir sonraki parıltının başlangıcı

Ve bilmelisin ki ,

Kimdir yolcu , kim sabit beton gibi

Ne yolcudur , ne de beton ,

Işığı gördüğün an anla ‘ki ,

Sende bir deniz fenerisin aslında

O ışık seninde ışığın

Her sönüşünden sonra tekrar parlamalısın 

Ta ‘ ki deniz kabarıp seni yutacağı ana kadar 

Yaşamalısın ,

Saatlerce karanlık yağmalı üstüne ,

Ve rüzgarda savrulmalı bedenin

Bilmelisin ki her savruluş ,

Bir serdengeçtidir aslında

Ayakta olan sensindir , 

Ne denizdir , yol gösteren ne de rüzgar

Sen varsındır ,

Sabitlemişindir kendini 

Işık kendi ışığındır , rüzgarda senden 

Sen bir deniz fenerisin aslında

Her parıldayış ,

Senin var oluşundur ,

Her karanlık ise 

Var oluşunun habercisi 

Yaşamalısın 

Sen bir deniz fenerisin aslında !!!

   27 Temmuz 1997', 'Karanlıkta yanıp söner deniz fenerleri  O hep oradadır aslında  Gel gör ‘ ki sen ancak parıldadığında , İşte o anda fark edersin var olduğun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/deniz-feneri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çiçeği', 'sevda-cicegi-ahmet-sahin-soner-sqpzn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dağın yamacındaydı

Yüreğinde düğümlenmiş bir şaki sevdası

Zemheri ayazı soğuk gecelerde

Yüreğimin üzerine çöreklenen karayılan 

O kış ortasında bir çocuktu 

Yalınayaktı , yırtıktı mintanı

Körpeydi  .....

Belliydi gözyaşlarından ,

Küçücük yüreğinde kocaman şaki sevdası

Koparılmamış bir çiçekti 

Belki de bir gün ölecekti

Sevdiğine son kez gülecekti

Ardından ağlayacaktık , sessizce

Solgundu benzi dün akşam

İçinde bir haykırış vardı

İnce bir sızıyla irkildi

Ve gözleri açık gitti

Rüzgar vurdu yüzüne ..... – Gülümsedi

Süzüldü gökyüzüne

El etti sevenlerine son bir kez

Döndü ve gitti

Beyazlar giymişti

Şafak sökerken herkes onu seyretti

Gelmişti , görmüştü , sevmişti

Toprak almıştı onu

Yüreğindeki sevdaydı onu gülümseten

Sevdiğine gitmişti

Kim bilir bir gün yine gelecekti

Bir ilkbahar sabahı bize gülümseyecekti

Belki de hiç gelmeyecekti

O bir çiçekti 

Toprağa sevdalı bir yürekti

Bir çiğdemdi sarı benizli

Gökten düşen beyaz kelebeklere yenik düştü

Eğdi boynunu

Sevdiğine ........ – Toprağa gitti 

12 Mart 1996', 'Bir dağın yamacındaydı Yüreğinde düğümlenmiş bir şaki sevdası Zemheri ayazı soğuk gecelerde Yüreğimin üzerine çöreklenen karayılan  O kış or...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevda-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-ahmet-sahin-soner-33f0q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anılar vardır , yıllar öncesinden

Kimi zaman yazılası ,

Kimi zaman yaşanası ,

Onulmadık bir anda unutulası 

Anılar vardır sıcak 

Anılar vardır yağmur sonrası 

Kimi zaman umut ışıltısı

Kimi zaman uzaklarda bir gün batımı 

Anılar vardır , yaşanan , yaşatılan

Anılar ufka sevgi diye kazınan

Seni anıyorum şu an vakit gün ortası

Seni yaşamak yine başka bir yarına kaldı 

Perdesini sessizce kapattı zaman 

Gidiyorum yağmurlu bir  bursa akşamında

Ayaklarımın yöneldiği anılara doğru 

   28 Nisan 1998', 'Anılar vardır , yıllar öncesinden Kimi zaman yazılası , Kimi zaman yaşanası , Onulmadık bir anda unutulası  Anılar vardır sıcak  Anılar vard...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğümüz', 'ozgurlugumuz-ahmet-sahin-soner-m08up', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilinmez bir yoldan geliyorum ,

Bilinmezliğe attığım bu son adımlar

Sonsuzluğa varamıyor düşüncelerim 

İçimdeki isyana çare bulmuyor

Kırık dökük köhne umutlar

Bir yalnızlık buğrasında kayboluyorum 

Derin ıssızlığın içerisine sinermişçesine saklanıyorum 

Hani bir daha hiç uçamayacakmış bir şahin gibi

Sabitlemişim bir şekilde kendimi

Umurumda değil biliyor musun artık

Üstü başı yırtık , bir karış sakal 

Ter kokularının boğuntusunda yarı aç , yarı tok

Dumanı henüz tütmemiş sigaranın yanık kokusunda yaşamak

Umurumda değil biliyor musun

Uzayıp giden yollara , yoldaki yolcuya 

Havada uçan kuşlara bile aldırmıyorum artık

Çalınmış düşlerimi istiyorum 

Elimden aldığınız özgürlüğümü 

Yetmiyor artık

Tel örgüler arasında verdiğiniz özgürlük yetmiyor,

Sadece ay’ ın ve doğan güneşin ışıklarıyla gelen

Bir gülümsemeden ibaret özgürlüklerden değil 

Yıldızları sayabilme özgürlüğümden 

Enginlere kuşlarla yükselme özgürlüğümden verin .

Her gün uyandığımda ;

Hep aynı elbiseyi üzerime geçirmek 

Aynı koridordan yürümek 

Aynı bahçede , aynı insanları görmek 

Aynı tel örgünün arkasından mı bakmak hayata 

Özgür müsün ha !!

Boş ver , boş ver hadi .....................

7 Ocak 1998', 'Bilinmez bir yoldan geliyorum , Bilinmezliğe attığım bu son adımlar Sonsuzluğa varamıyor düşüncelerim  İçimdeki isyana çare bulmuyor Kırık d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ozgurlugumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkenli', 'yelkenli-ahmet-sahin-soner-l57ui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Engin denizlerin ortasındayım ,

Rüzgarın sesiyle kanatlana bir yelkenlide

İlerliyorum , uçarcasına

Bu yolculuk nereye ha.....

Karanlıklara mı dersin

Yoksa yeni sevgilere mi !

Fırtınalar ortasındayım ve çakan şimşekler

Boyumdan büyük dalgalar arsında

Yaralı martılar güvertede 

Ve bir sabah

Yeşillerle bezenmiş bir deniz ülkesinde

Suların berraklığı ve güneşin ışıkları altında

Sahilin her bir köşesinde yarı baygın 

Yarı çıplak , gözleri çökmüş insanlar

Yelkenli yoktu ortalıkta

Son yolculuğunu yapmış 

Bırakmıştı tüm yolcularını sahilin dört bir köşesine

Herkes bir başka suskundu 

Bir parça tahta parçasıydı karaya vuran

Ve karşı kıyıda seyrediyordun beni 

Gözlerinde süzülüyordum gökyüzüne doğru

İşte ben o yelkenlinin son yolcusuydum

                                                     ELVEDA ! 

1 Mayıs 1996', 'Engin denizlerin ortasındayım , Rüzgarın sesiyle kanatlana bir yelkenlide İlerliyorum , uçarcasına Bu yolculuk nereye ha..... Karanlıklara m...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yelkenli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı', 'balikci-ahmet-sahin-soner-836c9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir balıkçı vardı ....

Hani sandalında şarap çeken ,

Elleri misina yarası

Hani heleny idi sandalının adı

Bir balıkçı vardı 

Mavi denizlere ezelden aşık

O sabah gördüm darmadağınıktı saçları

Ve aklar sarmıştı kirli sakalını

Yüreğinin üzerinde merhem ister hançer yarası

Bir balıkçı vardı 

Hani sevgiyi bize öğreten

Uzaklara el sallarken gülümseyen

Aşka aşık olmayı yüreğimize sindiren

Bir balıkçı vardı hani

Seni ölümden döndüren

Sonrada sana yüreğini veren

Seninde bir zamanlar sevdiğin

Sonrada bir anda silip gittiğin

İşte o balıkçı vardı ya

Dün akşam sandalına seni resmederken

Son defa seni sevdiğini söylerken

Senden çok sevdiği mavi sulara gitti 

Artık yaşamıyor biliyormusun !!! 

 10 Haziran 1996', 'Bir balıkçı vardı .... Hani sandalında şarap çeken , Elleri misina yarası Hani heleny idi sandalının adı Bir balıkçı vardı  Mavi denizlere e...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/balikci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Çok Farklısın', 'sen-cok-farklisin-ahmet-sahin-soner-0lmyk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine karşımdasın bir akşamüzeri , 

Ellerinle şekiller çiziyorsun görünmez bir tabloya

Hep burada seni bekleyişim akşamları 

Nedendir , bilir misin   yalın ayak koşmam kaldırımlarda

Yüksekten uçan bir kuşa merhaba deyip el sallamam

Bir oyunu tek perde , tek  figüran tek suarede bitirmek

Ne acıdır bilir misin paylaşımsız  ölüp gitmek

Ardına son kez bakmadan kapatmak defterleri 

Uzun uzadıya var olamamak 

Son sözün boğazında düğümlenen acısıyla ,

Bir kerede silip atamamak umarsızca karanlıklara

Kararmış bir umuda ışık tutamamak hasret fenerleriyle

Tarifi imkansız bir duyguya bürünmüşüm

Karmakarışık somutlaşmış yaklaşımlar

Seni unutmak istediğimde , yine sen karşımdasın

Ellerinle şekiller çiziyorsun görünmez o meşhur tabloya

 6 Eylül 1996', 'Yine karşımdasın bir akşamüzeri ,  Ellerinle şekiller çiziyorsun görünmez bir tabloya Hep burada seni bekleyişim akşamları  Nedendir , bilir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-cok-farklisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum', 'seni-bekliyorum-ahmet-sahin-soner-jntms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte buradayım .......

Seni bekliyorum yaz yağmurlarıyla ,

Bir duman bulutuna sarınmış karşı yamaçlarda ,

Ve beyaz beyaz umuda uçan kuşlarla,

Yalnızım , oturmuş hayalinle hasreti konuşuyorum

                                                 Seni Bekliyorum .......

İşte buradayım .........

Elimde hiç yanmamış ıslak bir sigara 

Yüzümde buruk bir tebessüm , gözlerim yollarda

Sen yoksun ya gidemiyorum uzaklara

Bir umut işte arkasına gizlenmişim

                                                 Seni Bekliyorum .........

İşte buradayım ..........

                                                 Seni Bekliyorum .........

Yağmurun sesiyle , ıslak sokaklarda

Göz yaşı döken ağaçların altında , 

Dönüşü olmayan bir zamanda gel

Hadi gel tutsak duygularıma 

Vazgeçmek mümkün olmasın 

Ayrılıklar olmasın', 'İşte buradayım ....... Seni bekliyorum yaz yağmurlarıyla , Bir duman bulutuna sarınmış karşı yamaçlarda , Ve beyaz beyaz umuda uçan kuşlarla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-bekliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Eylülde Kaldı', 'sevgim-eylulde-kaldi-ahmet-sahin-soner-2jdeh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayallerle gemiler yürümez artık

Gökyüzünde yıldızlar ışıldasada

Sevgim kalbinde büyümez artık

Sevgim eylülde kaldı

Işıklar saçan aydan bir haber yok

Denizlerde yakamoz silinmiş artık

İstanbul suskun gece karanlık 

Sevgim Eylülde kaldı

Bu bahar sensiz geçiyor artık

Sevginin küçük elleri avuçlarımda

Bu hayat sensiz yaşanmaz artık

Sevgim Eylülde kaldı

  10.09.1999 ( Bestem )', 'Hayallerle gemiler yürümez artık Gökyüzünde yıldızlar ışıldasada Sevgim kalbinde büyümez artık Sevgim eylülde kaldı Işıklar saçan aydan bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgim-eylulde-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara Gitmek', 'uzaklara-gitmek-ahmet-sahin-soner-bnc8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklara gitmek istiyorum

Mavi denizlere ulaşmak 

Yeni sevgiler resmetmek istiyorum

Yansımak gökyüzüne yeniden ... Seninle 

Yağmur vursun istiyorum yüzüme

Sonra gökyüzünü yedi renge boyamak ..... Seninle

Martılarla yarışmak enginlere doğru

Mısra olup yazılmak denizlere

Yağmur olup yağmak nicelere

Küçük değil ki benim sevdalarım

Yalnızken dost kalanlara vurgunum

Büyük sevgileri resimlemek ..... Seninle

Denizlere aşığım ben  - Sulara

Peşinden ardın sıra uçtuğumuz kuşlara

Uzaklara gitmek isteyişim bundan

Kader kardeşlerime ulaşmak

Sitem ve hüznün unutulduğu bir dünya bulmak

Hadi  gel kaçalım buralardan ..... Seninle

Yeni umutlara kürek çekermişçesine

Uzaklara gitmek istiyorum .... Seninle

Ama yoksun , yoksun işte

Denize sevdalı yüreğin yok artık

Toprağa sevdalandın işte delicesine

Sensiz bıraktın kaderin yollarını

Yüzünde derin çizgiler var

Toprak oldu kim bilir bedenin

Sensizim , yalnızım , mutsuzum işte

Gidiyorum korkarak ve sinsice 

Deniz olmak istiyorum , her yere ulaşmak

Topraktan çıkıp gelmeyeceğin için

Topraktan ötesi olmadığı için 

Belki de seni yaşamak yaşatmak için

Sahildeki bıraktığımız izleri takip ediyorum

Gidiyorum ama , - sana geliyorum

Seni beklemiyorum  !

Uzaklara gidiyorum çok uzaklara

Issızlığa , sonsuzluğa , yalnızlığa

Karanlık bir kuyuya değil

Toprağa , denize , uzaklara gidiyorum

 17 Haziran 1996', 'Uzaklara gitmek istiyorum Mavi denizlere ulaşmak  Yeni sevgiler resmetmek istiyorum Yansımak gökyüzüne yeniden ... Seninle  Yağmur vursun is...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/uzaklara-gitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bu Kadar Ucuzmu', 'sevgi-bu-kadar-ucuzmu-ahmet-sahin-soner-gxqop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay mı ayrılık 

Aşk pazarında 

Ucuz mu bir yürek dolusu sevgi

Acımıyormusun o deniz mavisi gözlere

Kor ateşler üzerinde yürümek 

Acıtmıyor mu hiç tenini

Yağan yağmura nispet mi 

Şu gözünden akan yaşlar

Ya o güneşin rengi saçlarını

Kolay mı kesip atmak

Sevgi , sevgi bu kadar ucuz mu

Kolay mı birdenbire hoşcakal demek

Neden ! böyle bilinmeyene süzülmek

Ardından göz yaşı dökenlere aldırmadan

Hiç düşünmeden çekip gitmek

Bu kadar kolay mı ayrılık

Bu kadar kolay mı gökyüzüne uçmak 

Bir çukurun içerisinde 

Beyazlar içinde seni görmek

Üzerine bir avuç toprak atmak

Bu kadar kolay mı seninleyken seni unutmak

Yalnızlığa hüküm giymek 

Bu kadar kolay mı Ayrılık

20 Mart 1996', 'Bu kadar kolay mı ayrılık  Aşk pazarında  Ucuz mu bir yürek dolusu sevgi Acımıyormusun o deniz mavisi gözlere Kor ateşler üzerinde yürümek  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgi-bu-kadar-ucuzmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve İşte Ben', 've-i-ste-ben-ahmet-sahin-soner-p1npa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Islak sokaklara bakmak , buğulu gözlerle

Sönen umutlara ağlamak beyaz saçlarla

Hüsranla , göz yaşı dökmek , uzakta kalanlara

Dost tutmak , arkadaş olmak 

                                      Denizler üzerinde süzülen martılarla

Ve aşık olmak , 

Uçsuz bucaksız yaylalara , ovalara , dağlara

Umut bağlamak , bir avuç umutsuzluğa 

Düş kurmak , sevgi üzerine insnlarla

Ve ağlamak 

Susarak bir köşede sessiz sessiz tek başına

Yanlızlığın tadına varmak , kekik kokulu dağlarda

Derin vadilere uçan bir kuşa el sallamak

Ve gülümsemek

Belkide geride kalan son birkaç günümüze 

Kim bilir belki de içimizde küllenen aşk ateşine 

Yinede gülümsemek hüsranla geçmiş yıllara

İyimserlik oyunu oynamak dağlarla , taşlarla 

                                          Umuda uçan beyaz kuşlarla ......

Ve sitem etmek

Bir ahhh .... çekerek

Geride bıraktığımız o küçük umutlara

Ölen sevgilerim anımsamak , ve ağlamak

Buğulu gözlerle bağlanmak hayata ve yinede  gülümsemek

Yeniden sevmek göz yaşı olmadak yaşamak 

Hayal kurmak dağlarda 

Umuda yolculuk etmek , yeni umutlar bulmak 

Toplayıp tüm umutları dağıtmak insanlara

Ve bir daha ağlamak , ağlatmak

 İnan  o kadar zor ki !!!!

 Sevgisiz , paylaşımsız ölmek

7 Mayıs 1995', 'Islak sokaklara bakmak , buğulu gözlerle Sönen umutlara ağlamak beyaz saçlarla Hüsranla , göz yaşı dökmek , uzakta kalanlara Dost tutmak , a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ve-iste-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Türkiyem', 'benim-turkiyem-ahmet-sahin-soner-rg7mp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hiç yağan yağmurun altında

Karabulutlar arasında ışıyan güneşle

Yan yana iki gökkuşağı gördün mü söyle !!!

İlk defa yağmurun tadına vardın mı 

Ölümü yaşamadan bu dünyada

Rüzgarları derin vadilerde dinledin mi 

Uçtun mu kuşlar gibi enginlere , özgürce

İzledin mi güneşin batışını toroslarda

Güneşle iki gökkuşağı arasında doğdun mu hiç

Güney doğuda yağmur ektin mi barut kokulu dağlara

Sarıkamış ta sabahın ayazında

Topladın mı boynu bükük kar çiçeklerini

Yıldızlı bir istanbul akşamında

Boğaza yansıdın mı hiç martılarla

Bulutsuz gördün mü hiç ağrı dağını ağustos ortasında

Selam durdun mu ulu dağdan anadolu ya doğru 

Ege de , ak deniz de dalgalandırdın mı şanlı bayrağı

Tezek kokan yaylalarıma vardın mı hiç 

Kınalı kuzuyu okşayan elleri öptün mü 

Örse çekiç sallayan ellerin acısını

Hissettin mi yüreğinde hiç

Tandır ekmeğini pekmeze banzırıp,

Zafere soğan kırarca 

Erzurum da bir yer sofrasında 

Yalınayak dolaşan yurdum çocukları arasında 

Gevaş ta otlu peynir kokulu köy odalarında

Mistik tunceli akşamlarında

Kim bilir bir gün ankara da

Gece ayrılarında , kurt ulumalarında 

Ayın ışıltısını gördün mü hiç

Karadeniz de bir çay bahçesinden

Yakamoz tarlalarına saldın mı ayakları geceleri

Yunuslarla yarıştın mı hiç marmara da 

Alnından vurulup şehit düşen mehmetlerin 

Ardından ağlayan anaların , babaların gardaşların , bacıların 

Acısını tuttun mu yüreğinde sabahın ayazına kadar 

Türkiyem , memleketim insanının vatanı 

Benim vatanım türklük aşkıyla yananların vatanı

17 Ekim 1993', 'Sen hiç yağan yağmurun altında Karabulutlar arasında ışıyan güneşle Yan yana iki gökkuşağı gördün mü söyle !!! İlk defa yağmurun tadına vard...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/benim-turkiyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın Bana', 'uzaksin-bana-abdullah-yildiz-aoksl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahipsiz gönlümü almak istemezmisin.

Hissetmek istemez misin sevgimi

Yazmışım seni her parçama

Sigaramın her nefesinde

Aldığım her nefeste

Kokladığım her çiçekte

Bütün hayalimde sen varsın

Sanki her zaman benimlesin

Ne olur hep yanımda olsan

Sevginden birazcık tatsam

Rüzgar getiriyordu kokunu bana

Kuşlardan alıyordum haberini

Uzak kalma benden 

Diz çökmüş bekliyorum seni

Zamanın içinde kaybolmuş gibisin sanki

Yıldızlara sordum, ağaçlara sordum 

Taşlara sordum ve kuşlara sordum

Dediler  ki o gelmez  sana

Sormaz olaydım.

Bütün umutlarım yıkıldı bir anda

Gecelerin karanlığında kayboldum.

Artık aydınlatmıyordu yıldızlar yolumu

Bulamıyordum kaybettiğim umutlarımı



Sevginle büyüttüğüm çiçekler

Soldular birer birer.

Susamışlardı onlar da sana 

En az benim susadığım kadar.', 'Sahipsiz gönlümü almak istemezmisin. Hissetmek istemez misin sevgimi Yazmışım seni her parçama Sigaramın her nefesinde Aldığım her nefeste K...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldız']::text[], 8.5, '{"poet":"Abdullah Yıldız","poet_slug":"abdullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uzaksin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-derya-colasan-60dw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık ve çok sesli yerlerde 

duydum sesini

ilk önce

ilk konuşmalar, yeni tanışmalar...

biraz dumanlı, biraz çakırkeyif, 

bolca komik...

ve aylarca sürecek olan...

kendime bile söylememiştim oysa

seni özlediğimi

bakışını, dokunuşunu sevdiğimi,

bilerek olmasa da -hani yanlışlıkla- 

bana dokunmanı istediğimi... 

oysa bir kere bile görmemiştim 

güneşli günlerde yüzünü

gözlerinin yeşilliğini.

yemyeşil gözlerine güneş vurup

gülümseyerek bana 

yürüdüğünü...

ama mevsim bahara dönmüştü 

bir kere

ve görünce gözlerinin ışığını 

güneşli bir vapur iskelesinde... 

daha ötesi yoktu 

bunun adı aşktı, biliyordum 

taa o zamanlar...

önce kendime sonra sana söz verdim

hiçbir şeye değişmem bu aşkı diye.. 

inanmadı en yakın dostlarım 

hayal bu dediler

aldırmadım. 

deli bir kan dolaşıyordu damarlarımda 

yorgun, kırılmış, nefret dolu, 

kadınca duygularından korkan

aşka güveni kalmayan,

hep düşüp düşüp tekrar ayağa kalkan....

bu kadar büyük olduğunu

ben bile bilmiyordum 

kalbimin... 

ve inanmıyordum hiç,

boyu boyuna suyu suyuna 

uyan bir kalp bulacağını kendine...

ve inanmıyordum hiç,

başka bedendeki bir kalbe 

böylesine yerleşeceğime...

o bedeni kendi bedenimden 

ayrı görmeyeceğime...

mevsim önce yaza sonra kışa döndü

sonra hesabını bile tutamadık 

döndü durdu...

aylarca yaz kış demedi 

hep çiçekler açtı yüzümde..

geçen her gün daha çok aşkla uyandım sabahları

başka güzel geldi bahar dalları...

aşkıma sarılıp uyudum, gözlerimdeki ışık hiç sönmedi 

bana güneşi getirdin

papatyalarla birlikte...

sabahlarıma aydınlık

yüzüme neşe, içime canlılık

umudu, sevgiyi getirdin bana...

yağmurlu günlerde ıslak bedenlerle gülmeyi...

aylardır bir tek şey  söylüyorum

hiç vazgeçmeden söyleyeceğim

Seni Seviyorum', 'Karanlık ve çok sesli yerlerde  duydum sesini ilk önce ilk konuşmalar, yeni tanışmalar... biraz dumanlı, biraz çakırkeyif,  bolca komik... v...', ARRAY['Türk Edebiyatı','Şiir','Derya Çölaşan']::text[], 8.5, '{"poet":"Derya Çölaşan","poet_slug":"derya-colasan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/kelebek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Akşamları', 'bahar-aksamlari-ayhan-erdem-rhz7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son bulsun kara günlerim nihayet, 

 Hayırla an beni ey bahar akşamları, 

 Neşeyle anılsın geceler, ruhumu şadet, 

 Hayırla an beni ey bahar akşamları. 

Bağlandı gönlüm ufkuna sevdayla izinde, 

 Buldum solan bahçemde, bir eş onsekizinde, 

Bitkin düşer isteklerim şen denizinde, 

Hayırla an beni ey bahar akşamları. 

 Geçmişe dalıp kahkahalar salmakta boşuna, 

Hevesle bürünmüş siyahlar, puslu geceye, 

Gel boş verelim anılara, dalsınlar acıya, 

Hayırla an beni ey bahar akşamları. 

Sevdayı yanan bir ufuk sandı elemler, 

 Hüzünle bunalmış tenime dokunmayın alemler, 

Mademki derbeder gönlümü kıskandı hayinler, 

Hayırla an beni ey bahar akşamları.', 'Son bulsun kara günlerim nihayet,   Hayırla an beni ey bahar akşamları,   Neşeyle anılsın geceler, ruhumu şadet,   Hayırla an beni ey bahar ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Erdem']::text[], 8.5, '{"poet":"Ayhan Erdem","poet_slug":"ayhan-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahar-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydin', 'neydin-burak-ersemiz-jex4b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neydin sen

ne,ne,ne

Söyle

Neydin sen.

Evet bir pildin sen,

Bitince köylü çocuklarının

bulup raylara dizdiği.

bir pildin sen.', 'Neydin sen ne,ne,ne Söyle Neydin sen. Evet bir pildin sen, Bitince köylü çocuklarının bulup raylara dizdiği. bir pildin sen....', ARRAY['Türk Edebiyatı','Şiir','Burak Ersemiz']::text[], 8.5, '{"poet":"Burak Ersemiz","poet_slug":"burak-ersemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-burak-ersemiz-42j2g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur Yağıyor

Şemsiyesiz zamanımda,

Ne yapsaydım yani

Her zaman sen olamazdın ya.

Yalnız kalıncamı

yağmuru sevmiyorum acaba.', 'Yağmur Yağıyor Şemsiyesiz zamanımda, Ne yapsaydım yani Her zaman sen olamazdın ya. Yalnız kalıncamı yağmuru sevmiyorum acaba....', ARRAY['Türk Edebiyatı','Şiir','Burak Ersemiz']::text[], 8.5, '{"poet":"Burak Ersemiz","poet_slug":"burak-ersemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batı', 'bati-burak-ersemiz-dni81', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bataklıkta güneş batınca

üzülen yoktur.

sadece bataklıkta,

üzülen yoktur.', 'Bataklıkta güneş batınca üzülen yoktur. sadece bataklıkta, üzülen yoktur....', ARRAY['Türk Edebiyatı','Şiir','Burak Ersemiz']::text[], 8.5, '{"poet":"Burak Ersemiz","poet_slug":"burak-ersemiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Vakitlerinde', 'dus-vakitlerinde-osman-murat-koktas-420o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saat; usulca, sessizce ilerler 

gözler kapanır yavas yavas

hatıralar canlanır karanlık odada 

birden, ''Düs Vakitleri'' gelir çatar 

''sessiz bir park köşesi

serin bir sonbahar günü 

sarı yapraklar, yere düşmekte

utanan, titrek, çıplak ağaçlar

ıslak bir nefes, 

saçlarımda süzülen 

yalnız sen ve yalnız ben 

sarmaş-dolaş ''sevdalı'' 

siyah-beyaz bir fotoğraf karesinde

masum gözlerle birbirini izleyen 

ölesiye suskun, ölesiye sevdalı, ölesiye mesut...''

bir rüzgar uğultusu,

penceremden süzülen

çırpınan perdeler, titreyen ayaklarım

saat gecenin ertesini vurmakta

ah! ne kötü zaman 

'' Düs Vakitleri'' sona erdi yine 

koltuğum tat vermez oldu artık

^şimdi yatma zamanı.^ 

''uyku saatim geçiyor.''

17-10-2000

11:40', 'saat; usulca, sessizce ilerler  gözler kapanır yavas yavas hatıralar canlanır karanlık odada  birden, ''Düs Vakitleri'' gelir çatar  ''sessiz b...', ARRAY['Türk Edebiyatı','Şiir','Osman Murat Köktaş']::text[], 8.5, '{"poet":"Osman Murat Köktaş","poet_slug":"osman-murat-koktas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dus-vakitlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Mezarlıktan Doğar Bizim köyde', 'gunes-mezarliktan-dogar-bizim-koyde-veysel-aksu-pqx7o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbetin cemresi içime düştü

Gözlerim memlekete açıldı birden

Hüznümü bu akşam demli çayım bölüştü

Anam geçti bir anda şalvarıyla zihnimden

Köydesin, yalnızsın

Koca evde tek başınasın anacığım

Karşı tepede tam eve bakan yamaçta

babam yatıyor

Ve

Onun arka yanında

Bostanlara bakan yamaçta oğlun

Seher vakti güneş her gün

Babamın üstünden doğuyor köye

Ve biliyorum bu vakitte sen

Namazını kılmışsın elinde tesbihinle

Rabbinlesin bir başına

Hayat arkadaşının mezarı

Karşıda, ışımaya başlayan

Güneşle görünüyor

Ve senin al bereli yaşmağına

Göz yaşın dökülüyor

			Biliyorum

Ruhunda hüzün bulutları

Esrik yağmurlar dökerken evin önüne

Yüreğin acıyla burkuluyor

			Hissediyorum

Alaca karanlıkta

Veya gün ortasında

Ondan bir şeyler görüyor yanıyorsun

Yüreğine bir ok saplanıyor, ağlıyorsun

			anlıyorum

Yalnızsın anacığım

	Yanmışsın anacığım

Babamın diktiği asma, üzüm veriyor

	Sen ağlıyorsun

Ve onun olut ağacı meyvelerini

Torunlarına değil kuşlara sunuyor

			Kanıyorsun

Koca bir evde tek başına anacığım

Söyle, ne olur söyle

	Ne yapıyorsun

Ve bu kahırla gününü akşama 

	Nasıl ulaştırıyorsun

Güneş epey yükseldi

Hayat başladı köyde

Ahırda hayvanlara

Veriyorsun yem küspe

Ve takıp alüminyum kovalarını koluna

Bostana iniyorsun

Meteris tepesinden inip

Köprüyü geçince görünüyor

Vedat''ının mezarı

Kovalar gülle oluyor elinde

Yorulup bitiyorsun

Yol kenarında bir taşın üstüne

Oturup sessiz sessiz

Göz yaşı döküyorsun

		Biliyorum

Sonra doğrularak yavaşça yerinden

Varıyorsun oğlunun mezarı başına

Islak kirpiklerinden hüzün damlaları

Dökülüyor oğlunun mezar taşına

Eğiliyorsun anacığım

Oğlunun üzerine

Uzanıyorsun toprağa

Dualar gönderiyorsun

Can yongana ilk evladına

Boşalıyorsun mezar başında

Ağlıyor, ağlıyorsun

		Ve her gün sen

			Bir yıl yaşlanıyorsun

Ve ben burda

İçime gurbetin cemreleri düşerken

Aklıma senin göz yaşların

Babamın diktiği üzüm asması

Ve rahmetli abimin armut fidesi geliyor

Uyuyamıyorum anacığım

		Unutamıyorum

Ne olur sen de anacığım

		Bu oğlunu dualarda unutma

Hiçbir derdi aklında tutma unut

		Ama

		Dua etmeyi

		Ve dualarda beni ve ...!

		Ne olur UNUTMA', 'Gurbetin cemresi içime düştü Gözlerim memlekete açıldı birden Hüznümü bu akşam demli çayım bölüştü Anam geçti bir anda şalvarıyla zihnimden ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Aksu']::text[], 8.5, '{"poet":"Veysel Aksu","poet_slug":"veysel-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/gunes-mezarliktan-dogar-bizim-koyde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Güneşi', 'sabah-gunesi-abdullah-yildiz-puny7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık inanmıyorum sevgiye

Oysa her şeyin bir sonu olduğunu

Geçte olsa anladım sayende

Yoksa bir daha yanılacaktım

Sonsuza kadar bekleyecektim seni

Umutlara kapılıpta açık denizlerde kaybolacaktım yine

Şimdi şimdi ise 

Mezarda değilde, tek başına bir yatakta

Hapiste değilde, tek başına bir odada

Üstelik bu odanın pencereside yok

Güneşin ışıklarını, uçuşan kuşları ve kelebekleri

Rengarenk çiçeklerin kokusunu 

Rüzgar getirmiyordu bana

Söylermisin bana dışarıda hayat devam ediyor mu?

Eğer devam ediyorsa ben ölmüşüm

Hayat devam etmiyorsa,

Herşey yok olmuşsa seven insanların dışında

Sevenler ölmez diyebilirmiyim sevgilim

Neden yoksun dünyamda anladın mı sevgilim

Biliyordun sende benim gibi

Sevgisiz bir dünyanın olmayacağını

Sana fazla bağlanmadan ayrıldı yollarımız

Böyle olması daha iyi oldu

Yoksa her hüzünlü melodinin arkasından 

Gelecek tek şey gözyaşlarım olurdu

Şimdi ise kalemimin mürekkebi gözyaşlarım

Yazdıkça ağlıyorum

Yazdıkça ıslanıyor sayfalar

ve tekrar tekrar yazıyorum

Islanmış sayfalara

Sanki ağlamak için gelmişim dünyaya

Biraz da gülmek istedim, izin vermedin vermediler

Çok şey istemedim senden

Sadece sevginden bir tutam

Hayatıma tat versin diye

Uzun zamandır bekliyordum

Tekrar güleceğim zamanı

Şu boş geçmişim gibi

Geleceğimde de

Sonu gelmez yolların

Yorulmak bilmeyen yolcusu olacağım

Uzun bir süre daha

Sabah güneşinin doğuşu

Yeni bir günü, hayatın devam ettiğini

Fısıldıyordu kulağıma

Hala bir çok sabahın olacağı belliydi güneşin doğuşundan

Nihayet gece oldu

Bulutlar çekildi bir kenara

Tek bir yıldız eşlik etti yolculuğumda

Her yer karanlıktı ama görüyordum herşeyi

Gündüz göremediklerimi bile

Yıllardır körebe oynuyormuşum

O yüzden göremiyormuşum beni sevenleri

O yüzden göremiyormuşum hayatın gerçeklerini

Hiç bir şey için geç olmadığını

Fısıldıyordu sabah güneşi.', 'Artık inanmıyorum sevgiye Oysa her şeyin bir sonu olduğunu Geçte olsa anladım sayende Yoksa bir daha yanılacaktım Sonsuza kadar bekleyecekti...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldız']::text[], 8.5, '{"poet":"Abdullah Yıldız","poet_slug":"abdullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sabah-gunesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Kal', 'oyle-kal-veysel-aksu-yt852', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllanmış bir tiryakiye

Koyu sıcak bir çayın hayali neyse

Bir ağustos sıcağında

Tarladaki köylüye

Buz gibi bir derenin hayali neyse

Bir şaire

Kardelenler nasıl ilham verirse

Her seher vaktinde bülbül

Gülün açılmasını nasıl beklerse

Dalındaki yuvasında anasını

Nasıl beklerse serçe kuşları

Ve analar oğullarını, oğullar analarını

	Nasıl hasretle 

		gözlerse 

Gözleri nemli gurbet diyarlarında

Sıcak bir yaz günü

	Bir tas tuzlu ayran neyse

				Yanan birine

Sen de benim için öylesin

		Öyle ol ve öyle kal

			Güzelim

		Ve öylesin güzelim', 'Yıllanmış bir tiryakiye Koyu sıcak bir çayın hayali neyse Bir ağustos sıcağında Tarladaki köylüye Buz gibi bir derenin hayali neyse Bir şair...', ARRAY['Türk Edebiyatı','Şiir','Veysel Aksu']::text[], 8.5, '{"poet":"Veysel Aksu","poet_slug":"veysel-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyle-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Destan', 'destan-abdullah-yildiz-6or60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski kaldırım taşı sandın gururumu

Ama hep sen yıprattın

Hep sen çiğnedin

Sana olan sevgim

Alevler arasında yanan bir odun gibi

Kül oldu

Benim seni sevdiğimi sen değilde

Rüzgar savurdu 

Dünyanın dört bir yanına

Belki bir gün çıkar

Sana olan sevgimin sonsuzluğuna

Ne farkeder ki inanan çıksa

Sen inanmadıktan sonra

Öldükten sonrasında da

Sana olan bu sevgim

Destan olup dilden dile dolaştığı sürece

Seviyor olacağım seni', 'Eski kaldırım taşı sandın gururumu Ama hep sen yıprattın Hep sen çiğnedin Sana olan sevgim Alevler arasında yanan bir odun gibi Kül oldu Ben...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldız']::text[], 8.5, '{"poet":"Abdullah Yıldız","poet_slug":"abdullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/destan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustu & Bunalım', 'sustu-bunalim-levent-cokyuruyen-wnsh4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Terkedilişimin ilk saatleri.

Bunalım belirtileri gene sinyaller veriyor.

Tutunabilecek güç yitik, kafa karışık.

Karşımda hayatım bana bakıyor. Birde hayatımın anlamı.

İkisi birbirine öyle çok yakışıyor ki, bu güzelliğin bozulmaması için ölmeye razıyım.

Sevgiye dair son umut olarak baktığım ve hayatın anlamı olarak nitelendirdiğim küskün, kırgın.

Hayatım beni izliyor. Bu düştüğüm boşlukta ona tutunmam için yalvarır bir halde.

Anlamsızsın diyorum hayatıma. Onu geri getir o zaman diyor.

Anlamıma yalvarıyorum. Tepkisiz!

Yitiriliyorsun diyorum hayatıma. Yalnız yapamazmısın? diyor.

Yaparım ama anlamsızlık neyi ifade eder? diyorum ona. Sustu...

Umuda açılan yelkenler umutsuz rüzgarlarda dahi yırtılabilir.

Eğer ki umuda açılan son yelkenlere rüzgar çarpmıyorsa batma vakti gelmiştir!', 'Terkedilişimin ilk saatleri. Bunalım belirtileri gene sinyaller veriyor. Tutunabilecek güç yitik, kafa karışık. Karşımda hayatım bana bakıyo...', ARRAY['Türk Edebiyatı','Şiir','Levent Çokyürüyen']::text[], 8.5, '{"poet":"Levent Çokyürüyen","poet_slug":"levent-cokyuruyen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sustu-bunalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgine ihtiyacım var', 'sevgine-ihtiyacim-var-alper-dalkiliclar-ijrnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik okadar acı verici ki.....

Sensiz geçen zamanın hiç bir anlamı yok....

Kalbimde öyle bir yerin varki seni ordan alabilecek kimsede yok..

Öyleki sol yanımı boş koydum.

Kalbim de ellerim gibi sahibinin yanında olmasını diliyor.

Şu an akşam oluyor.

Güneş denizin üstünde batmak üzere.

Okadar güzel bir manzara varki , 

Bu doğa harikasını anca yine bir doğa harikası tamamlayabilir.

Yani evrenin en tatlı varlığı , sen tamamlayabilirsin......

Aynı bir yarımımın boş olup , o yarımımı seninle tamamladığım gibi....

Toprağın suya , çiçeğin güneşe ihtiyacı olduğu gibi ,

Benimde sana , senin sevgine ihtiyacım var.....

Beni sevginden mahrum bırakma...........', 'Sensizlik okadar acı verici ki..... Sensiz geçen zamanın hiç bir anlamı yok.... Kalbimde öyle bir yerin varki seni ordan alabilecek kimsede ...', ARRAY['Türk Edebiyatı','Şiir','Alper Dalkılıçlar']::text[], 8.5, '{"poet":"Alper Dalkılıçlar","poet_slug":"alper-dalkiliclar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgine-ihtiyacim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek sevgi', 'gercek-sevgi-alper-dalkiliclar-v98mq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden sevgiyi yakalamak bu kadar zor?

Yakalayıpta elde tutamamak.....

Yada bulduğunu sanıpta yanılmak...

Sevgisiz yaşanmıyacağını iyi biliyorum.

Mutlu olabilmem için sevgi terimi hayatımda olmalı

Sende olmalısın .....

Bir insan sevgiyi nasıl yaşatır içinde?

İnsanın sevebilmesi için illa yüzünü görmesimi lazım

illa sesini duyması mı lazım?

İlla ellerine dokunması mı lazım?

Hayır sevgi insanı kör edebiliyorsa ,

bunların olması gerekmez!

Seni görmüyorum ama benim için senden güzeli yok

Beni duymuyorsun ama beni senden daha iyi anlayan yok

İşte görüyorsun herşeyin reel olması gerekmez

Bence işte gerçek sevgi budur....

Gel gör ki bunu benden başka bulanda yok.....', 'Neden sevgiyi yakalamak bu kadar zor? Yakalayıpta elde tutamamak..... Yada bulduğunu sanıpta yanılmak... Sevgisiz yaşanmıyacağını iyi biliyo...', ARRAY['Türk Edebiyatı','Şiir','Alper Dalkılıçlar']::text[], 8.5, '{"poet":"Alper Dalkılıçlar","poet_slug":"alper-dalkiliclar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma ki', 'unutma-ki-umit-yasar-oguzcan-js7mf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen uykusuzluk nedir bilir misin

Tırnaklarınla yastığını parçaladın mı

Gözlerini tavana dikip

Düşündüğün oldu mu bütün gece

Ve bütün bir gün

Belki gelir ümidiyle bekledin mi hiç?

Gelmeyince

Seni aramayınca

Ölesiye ağladın mı?

Sonra çekilip en koyusuna yalnızlıkların

Ona ait ne varsa

Bir bir hatırladın mı

Sen günden güne erimeyi bilir misin

Dev bir ağacın vakarı içinde ölmeyi

Bir teselli aramayı

Issız parklarda, tenha sokaklarda

Ve bütün şehir uyurken uzaklarda

Deli divane yollara düşüp

Yaşlanmış bir köpek gibi

Eskimiş bir gömlek gibi

Atılmışlığını hissettiğin oldu mu

Sevmekten

Günler geceler boyunca yürümekten

Elin, ayağın, kalbin yoruldu mu

Sen yalnızlığın acısını bilir misin

Unutulmak bir hançer gibi saplandı mı sırtına

İçinde kıskançlığın zehirli çiçekleri açtı mı

Bütün gururunu çiğneyip

Sevdiğinin geçtiği yollarda

Bastığı toprakları eğilip öptün mü

Sen çaresizlik nedir bilir misin

Sen yokluk nedir gördün mü

Yanan başını

Duvarlara vurup parçalamak geldi mi içinden

Sen her gün bin defa öldün mü

Böyleyim diye ayıplama beni

Bir gün kendimi

Sonsuzluğun koynuna bırakırsam

Yaralı ve yenik bir asker gibi

Darılma

Unutma ki

Her seven adsız bir kahramandır

Unutma ki

İnsan; sevebildiği kadar insandır.', 'Sen uykusuzluk nedir bilir misin Tırnaklarınla yastığını parçaladın mı Gözlerini tavana dikip Düşündüğün oldu mu bütün gece Ve bütün bir gün...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/unutma-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Dili', 'askin-dili-sair-doktor-ta9wy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni o kadar çok seviyorum ki

bunu sana her söylediğimde

birşeyler eksikmiş  gibi geliyor bana.

Sözcükler ya da sesler taşıyamıyor

içimdeki sana dair anlamları...

''Seni seviyorum'' diyorum

ve bu ses kayboluveriyor hemen

havanın acımasız boşluğunda!

''Seni seviyorum'' yazıyorum

basit şekiller oluveriyor harfler

ve hatta birer leke gibi düşüyor

tertemiz bir kağıt aklığına...

Oysa basit değil aşk bu kadar!

Nasıl göstermeli aşkı?...

Seni o kadar çok seviyorum ki

eksiksiz anlatmalıyım seni

yani kendimi,seni ben yapan şeyi...

Aşkın bir dili olsa diyorum

evrensel ve de anlatabilmesi kolay

Aşkın bir dili olsa diyorum

ve çözebilseler keşke

kalbimi;dilime ve kalemime bağlayan şifreyi!

Kalbimin karanlık bir his odası yok ki

aşkımı gözlerimde tab ettireyim...

Görüyorsun değil mi sevgilim?,

Seni o kadar çok seviyorum ki

kırık dökük bu şiir bile

anlatmaya yetmedi...', 'Seni o kadar çok seviyorum ki bunu sana her söylediğimde birşeyler eksikmiş  gibi geliyor bana. Sözcükler ya da sesler taşıyamıyor içimdeki ...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askin-dili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkolsun Be Arkadaş', 'askolsun-be-arkadas-sevgi-yagmuru-d846j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anladım ben sana yar olamadım 

Hiç olmazsa dostça ara be arkadaş

Biliyorum ellerimi tutmayacaksın

Hiç olmazsa dostum kal be arkadaş

Duydum ki bir sevdiğin varmış

Ağladım kahroldum be arkadaş

Benden vazgeçmiş onu sevmişsin 

Darıldım sana dargınım arkadaş

Uzaklar da sevdiğim yok demişsin 

Gözü yaşlı bir dost var de arkadaş

Adımı sormuşlar bilememişsin

Aşkolsun sana aşkolsun be arkadaş...', 'Anladım ben sana yar olamadım  Hiç olmazsa dostça ara be arkadaş Biliyorum ellerimi tutmayacaksın Hiç olmazsa dostum kal be arkadaş Duydum k...', ARRAY['Türk Edebiyatı','Şiir','Sevgi Yağmuru']::text[], 8.5, '{"poet":"Sevgi Yağmuru","poet_slug":"sevgi-yagmuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askolsun-be-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim Bahçe', 'yetim-bahce-bedri-rahmi-eyuboglu-nvta8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin güllerin her yerde açar

Dağda, bayırda, kırda, bozkırda

Bozkır biraz şüpheli ama

Günlerden bir gün açar mı açar

Bozkır dediğin sakar

Senin güllerin her yerde açar

Ya benim güllerim

Sevinen çocuk gözlerinde bir

Bedava iyilik yapanların gözlerinde iki

Bağışlamasını bilen yüreklerin en kuytu yerinde

 açar üç

Benim güllerimle senin güllerin el ele

En güzel bahçe

Benim güllerim olmadıkça

Senin bahçelerin yetim, yitik', 'Senin güllerin her yerde açar Dağda, bayırda, kırda, bozkırda Bozkır biraz şüpheli ama Günlerden bir gün açar mı açar Bozkır dediğin sakar S...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yetim-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti Gidecek', 'gitti-gidecek-bedri-rahmi-eyuboglu-mp2qe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek

Güzel meslek

Ama zor

Can dayanıyor

Dayanmasına

Ama yürek

Gitti gidecek', 'Sevmek Güzel meslek Ama zor Can dayanıyor Dayanmasına Ama yürek Gitti gidecek...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gitti-gidecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-bedri-rahmi-eyuboglu-kvvtd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Simsiyah

Bembeyaz

Bomboşum

İster siyah tebeşirle çiz

İster beyaz tebeşirle

Nafile', 'Simsiyah Bembeyaz Bomboşum İster siyah tebeşirle çiz İster beyaz tebeşirle Nafile...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nafile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şahit Aranıyor', 'bir-sahit-araniyor-bedri-rahmi-eyuboglu-65mk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşadım!

Erik ağaçları şahidimdir

Yıldızlar şahidimdir.

 Yaşadım!

Avuçlarımın gücü yettiği kadar

Dağları, kadınları, meyveleri

Yaşadım!

İncirin dallarına yürüyen süt

Yonca tarlasından gelen nefes

Horozun ibiğinden damlayan kan

Yollar ve sevgili türküler şahidimdir.', 'Yaşadım! Erik ağaçları şahidimdir Yıldızlar şahidimdir.  Yaşadım! Avuçlarımın gücü yettiği kadar Dağları, kadınları, meyveleri Yaşadım! İnci...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sahit-araniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Üstüne', 'sevda-ustune-bedri-rahmi-eyuboglu-4hvij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün kitapları yakmalı

Sevda üstüne ne söylemişlerse yalandır

Kitaplara göre insan

Karanlıkta yüzüne bin mumluk lamba tutulmuş

Gözleri, yüreği kamaşmış insandır

Aptaldır, hastadır, kahramandır

Bütün kitapları yakmalı

Sevda üstüne ne söylemişlerse yalandır.

İçinde bir tek suret yaşayan yüreğe yürek mi derler

Bir tek yaprak veren dalın boynun burarlar

Bir tek meyve veren dalı keserler

İnsan dediğin bir buğday tarlası gibi olmalı

Esti mi rüzgar bir değil milyonlar için esmeli

Bir tek meyve veren dalı kesmeli

İnsan dediğin derya misali

Üstünde milyonlarca dalga

İçinde kıyametler kopmalı

İnsan dediğin derya misali

Uçsuz bucaksız olmalı.

Gel çıkalım sevgilim gel

Gel kurtulalım birler hanesinden

Çekelim gidelim bir uçtan bir uca

Açalım yüreğimizin kapılarını sonuna kadar

Sevelim sevelim sevelim

Sevebileceğimiz kadar.', 'Bütün kitapları yakmalı Sevda üstüne ne söylemişlerse yalandır Kitaplara göre insan Karanlıkta yüzüne bin mumluk lamba tutulmuş Gözleri, yür...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğumuz', 'dostlugumuz-bedri-rahmi-eyuboglu-f15zp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostluğumuz güzel bir kuştu

Alkanat morkanat belalı bir kuş

Alkanat morkanat pahalı bir kuş

Otuz yıl nuh demiş kafeste durmuş

Kadrini bilmemişiz uçmuş

Uçar ayak olmayacak yerler sıçmış

Oluyor böyle şeyler oluyor

Canıma değdikçe canım acıyor

Elime değdikçe elim yanıyor

Çok uzaklarda bir yer kanıyor

Yo olduğun gibi görün diyor

Ya göründüğün gibi ol

Dol karabakır 

Dol karabakır

Dol karabakır

Olur mu böyle olur mu?

	Olur

yersiz bir çalım bir azamet

Siktirici bir çalım

Şaşı bir kibir

Bir afra bir tafra

Ciğeri beş para etmez yersiz bir gurur

		olur böyle şeyler olur

Gururun bu kadarı ebegümecinde de bulunur

Dostluk dediğin güzel bir kitap

Hava gibi

Su gibi

Ekmek gibi

Vazgeçilmez bir tad

Sonuna kadar dayanmak şart

Dostluk dediğin eşsiz bir kitap Sevmediğn sayfaları varsa 

		Atla

Sayfayı kökünden yırtmak şart mı

Dostluk dediğin kiralık at mı

Dostluk dedğin taksi mi

Dilediğin zaman açan mı

Dostluk dediğin çok nazlı bir kuş

	Kapıp da kaçan mı

Gözünün bebeği gibi korumak marifet

Dostluk dediğin nadir bir kuş

Huyuna suyuna dikkat

Bir kez kuyruğu titretti mi

Diriltene mükafat

Oluyor böyle şeyler oluyor

Her ahbaba dost denmiyor

Gitti mi bir kez gelmiyor

Dostluk dediğin nazlı bir kuş

Her kuşun eti yenmiyor

Dol kara

Dol bakır

Dol

Dostluk dediğin filfilli fistan

Her Allahın günü giyince insan

İster istemez aşınıyor-eskiyor-inceliyor

Eskidikçe tadına doyulmuyor

Nazdan nazik oluyor

Çiniden bilezik-

Bizer kadrini bilmedik

Hıyarca davrandın mı tuz buz-

Paramparça dostluğumuz', 'Dostluğumuz güzel bir kuştu Alkanat morkanat belalı bir kuş Alkanat morkanat pahalı bir kuş Otuz yıl nuh demiş kafeste durmuş Kadrini bilmem...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/dostlugumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alevsiz yangınlar', 'alevsiz-yanginlar-atabay-guveloglu-m4uh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklımdan çıkartıp atamadığım,

Hiç silemediğim kaygılarım var.

Yıllardır parlayıp,tütemediğim

İçimde alevsiz yangınlarım var...

Görürüm resmini,bakışlarını

Nereye çevirsem bakışlarımı.

Ne kadar tutsam da göz yaşlarımı

Nihayet insanım,duygularım var...

Hayal kurup,iç geçirip derinden

''Başlamak mümkün mü?''derim yeniden.

''Pişmanım''diyerek bir gün aniden

Geleceksin diye algılarım var...

İlgilendirmiyor mutlu insanlar,

Dostum oldu sigaram ve bardaklar.

Çıldırıp giderdim şimdiye kadar

İyi ki her gece rüyalarım var,

Seninle dop dolu rüyalarım var!...', 'Aklımdan çıkartıp atamadığım, Hiç silemediğim kaygılarım var. Yıllardır parlayıp,tütemediğim İçimde alevsiz yangınlarım var... Görürüm resmi...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alevsiz-yanginlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-hamit-karadag-o0luh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece,

Sessizlik ve hüzün müdür hep?

Yoksa;

Sevinç ve mutluluk mu?

Kimbilir?

Biryerlerde bu gece,

Bir hayat sönüyor şimdi.

Yada doğuyor çığlıklarla 

İsyan edercesine.

Bu gece ,bu geceler,

Nelere gebeler?

Nelere ana nelere baba olmadılar ki?

Kucağında büyütmediler mi?

Sevgiyi.

Coşturmadılar mı şairi

Yada cesaret vermediler mi aşığa

Nelere  gebe şu  geceler,

Mehtabı doğururken bilmezler

Kaç yüreğe düşer ateş

Aşklar kanlanır canlanırda koşar

Yetişemez ardından insan,

Tık nefes.

Geceler,

Sessizliğin sesi değil midir,

Gecenin sesi?

Gece değil midir,saran herkesi.', 'Gece, Sessizlik ve hüzün müdür hep? Yoksa; Sevinç ve mutluluk mu? Kimbilir? Biryerlerde bu gece, Bir hayat sönüyor şimdi. Yada doğuyor çığlı...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gece-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Beni İstiyor', 'simdi-beni-i-stiyor-atabay-guveloglu-adghl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu alem sanki bir seyirlik gibi,

Kimi gider,kimi yeni geliyor.

tüm canlılar birer kurbanlık gibi,

Ecel denen sırasını bekliyor.

Yıllar acımasız,saatler zalim,

Yıprandı bedenim,kalmadı halim.

Dünyanın kahrından yorulmuş kalbim,

Bazen ağrı verip,bazen tekliyor.

Mümkün değil mevsimleri durdurmak,

Gün gelir,sararıp dökülür yaprak.

Alıyor,doymuyor şu kara toprak

Kimler gitti,şimdi beni istiyor...', 'Bu alem sanki bir seyirlik gibi, Kimi gider,kimi yeni geliyor. tüm canlılar birer kurbanlık gibi, Ecel denen sırasını bekliyor. Yıllar acıma...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-beni-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk olmasa', 'ask-olmasa-atabay-guveloglu-pn521', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm değerler,güzellikler

Neye yarar aşk olmasa?

Bin yıl yaşatsa hekimler

Neye yarar aşk olmasa?

Baktığını görmez gözler,

Boşadır söylenen sözler.

Zenginlikler,tüm nimetler

Neye yarar aşk olmasa?

Bu hayatın tadıdır o,

Şevki,maksadıdır o.

Yaşamanın adıdır o

Neye yarar aşk olmasa?

Boştur dünya,boştur hayat,

Hiç bir şeyden alınmaz tat.

Ne kadar da olsan rahat

Neye yarar aşk olmasa?

Havva''yla başlatmış Adem,

Severiz,insanız madem!

Koca evren,bunca alem

Neye yarar aşk olmasa?', 'Tüm değerler,güzellikler Neye yarar aşk olmasa? Bin yıl yaşatsa hekimler Neye yarar aşk olmasa? Baktığını görmez gözler, Boşadır söylenen sö...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Avcı Oldu', 'hayat-avci-oldu-atabay-guveloglu-ehhv0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kovaladı durdu yıllardan beri,

Hayat avcı oldu,ben bir av oldum.

Yaraladı kırılası elleri,

Hayat avcı oldu,ben bir av oldum.

Özlemlerle ciğerlerim söküldü,

İhanetle kanatlarım döküldü.

Aşk bıçağı ile derim yüzüldü

Hayat avcı oldu,ben bir av oldum.

Ahu bakışlarla okları geldi,

Zalim gülüşlerle kalbimi deldi.

Seraplar gösterdi,aklımı çeldi

Hayat avcı oldu,ben bir av oldum.

Kurtulmak ne mümkün onun elinden,

Yaraladı can alıcı yerimden.

Sanki zevk alıyor çektiklerimden

Hayat avcı oldu,ben bir av oldum.', 'Kovaladı durdu yıllardan beri, Hayat avcı oldu,ben bir av oldum. Yaraladı kırılası elleri, Hayat avcı oldu,ben bir av oldum. Özlemlerle ciğe...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-avci-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar Dostum', 'ne-cikar-dostum-atabay-guveloglu-8k2ia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkına ihanet etmişse zalim,

Deli gibi sevsen ne çıkar dostum?

Seni mutlu etmez,köşklerin,malın,

Karun gibi olsan ne çıkar dostum?

Ayrılık vurmuşsa taa yüreğinden,

Demek ki çığ kopmuş bir kez yerinden.

Yuvarlanıp gidip onun peşinden

Yıkıp,kırıp geçsen ne çıkar dostum?

Boşadır zevkleri kesip attığın,

Yazıktır canına bunca yaptığın.

Vefasız çıkmışsa sevip taptığın,

Uğrunda ölsen de ne çıkar dostum?

Niçin sonu yok bu feryatlarının,

Faydası olur mu göz yaşlarının?

Her şeye boş verip,güzel dünyanın

Kıymetini bilsen ne çıkar dostum?', 'Aşkına ihanet etmişse zalim, Deli gibi sevsen ne çıkar dostum? Seni mutlu etmez,köşklerin,malın, Karun gibi olsan ne çıkar dostum? Ayrılık v...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-cikar-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gece', 'o-gece-atabay-guveloglu-6u93u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmak imkansız,birden seninle

Bir karar vermiştik sanki o gece.

Görülmez,duyulmaz gizli emirle

Vuslata ermiştik sanki o gece.

Sevgi fısıldarken kulaklarıma,

Ateşler düşmüştü gül dudaklara.

Gerek kalmamıştı hiç bardaklara

İçmeden sarhoştuk sanki o gece.

Çılgın bedenleri her kare kare

Nasıl da öpmüştük bin bir hasretle.

Ruhumuzu sarsan sonsuz şevhetle

Göklere uçmuştuk sanki o gece.

Bin yıl geçse bile unutulur mu?

Özlem göz yaşları kurutulur mu?

Yaşarken ölenler diriltilir mi?

Biz zaten ölmüştük sanki o gece?', 'Unutmak imkansız,birden seninle Bir karar vermiştik sanki o gece. Görülmez,duyulmaz gizli emirle Vuslata ermiştik sanki o gece. Sevgi fısıld...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-atabay-guveloglu-6vyga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dost kalmadı gidişinle

Diyorlar ''ayrılık niye?''

Yine sorulursun diye

Konuşmaktan korkuyorum.

Söyleyemem,anlatamam,

Onları da ağlatamam!

Ayrılık zor her şeyiyle,

İnanmaz oldum sevgiye!

Yine kaybolursun diye

Kavuşmaktan korkuyorum.

Bir kez daha kaldıramam,

O acıyla yaşayamam.

Can verdim sana hediye,

Feda ettim seve seve!

Yine darılırsın diye

Barışmaktan korkuyorum.

Seni asla unutamam,

Bu kalbimi dolduramam...', 'Dost kalmadı gidişinle Diyorlar ''ayrılık niye?'' Yine sorulursun diye Konuşmaktan korkuyorum. Söyleyemem,anlatamam, Onları da ağlatamam! Ayrı...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/korkuyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-atabay-guveloglu-817fz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dönecek mevsimler,baharlar kışlar

Seni senlikten,beni benlikten alıp.

pişmanlıkla kaderin ayağına kapanıp

Sevgi dileneceksin,gözünde damlacıklar

Ağlayacak,ağlayacaksın...

Bir çığlık duyacaksın yıllar ardından gelen,

Diz çöküp yalvarışım mutsuz edecek seni.

Yalnız gecelerinde arzulayınca beni

Bir feryat edeceksin o kalbinden beklenen

Ağlayacak,ağlayacaksın...

Bom boş ellerinle kabrime geleceksin

''Çiçek vermedi dallar,affet sevgilim''diye.

Her nefeste öldürecek ihanetin sevgiye.

Seni bir ömür seven ruhumu göreceksin

Ağlayacak,hep ağlayacaksın...', 'Dönecek mevsimler,baharlar kışlar Seni senlikten,beni benlikten alıp. pişmanlıkla kaderin ayağına kapanıp Sevgi dileneceksin,gözünde damlacı...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglayacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güvercinim', 'beyaz-guvercinim-atabay-guveloglu-y3f7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güverciniUçmak istiyorum seninle,

Yoksun beyaz güvercinim.

Haydi yine kon elime

Yoksun beyaz güvercinim.

İpek tenlim,can gülüşlüm,

tatlı dillim,bebek yüzlüm.

Bahtım gibi kara gözlüm

Yoksun beyaz güvercinim.

Kartallar mı kaptı seni?

Poyrazlar mı attı seni?

Ayrılığın yaktı beni

yoksun beyaz güvercinim.

Barışın sembolü bileyim,

Gel artık kurban olayım.

Bak ben yine yuvadayım

Yoksun beyaz güvercinim.

yoksun beyaz güvercinim,

yoksun beyaz m.', 'güverciniUçmak istiyorum seninle, Yoksun beyaz güvercinim. Haydi yine kon elime Yoksun beyaz güvercinim. İpek tenlim,can gülüşlüm, tatlı dil...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beyaz-guvercinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir mi gülüm', 'gelir-mi-gulum-atabay-guveloglu-nhqmx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılıksız ve özlemsiz bir dünya,

İnsanlar yaşarken bulur mu gülüm?

Bu resim gerçek mi,yoksa bir rüya,

Rüyaların resmi olur mu gülüm?

Gülün ömrü az olurmuş bilmedim,

Bahar geldi,ben gülümü görmedim...

Ürkek bir tebessüm dudaklarında,

Sevgi parıltısı yanaklarında.

Çerçeveden taşan şu kollarında

Vücudum uyuyup ölür mü gülüm?

Gülün ömrü az olurmuş bilmedim,

Bu bahar da ben gülümü görmedim...

Ne bir tek can olduk,ne de özledik,

Sanki hiç sevmedik,sevgi bulmadık.

İkikiz de kıymetini bilmedik,

Mutluluk geriye gelir mi gülüm?

Gülün ömrü az olurmuş bilmedim,

Kaç bahardır ben gülümü görmedim...', 'Ayrılıksız ve özlemsiz bir dünya, İnsanlar yaşarken bulur mu gülüm? Bu resim gerçek mi,yoksa bir rüya, Rüyaların resmi olur mu gülüm? Gülün ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelir-mi-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-atabay-guveloglu-qu72w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitsin bu ayrılık,bitsin Allah''ım,

Sana şu uzanan eller aşkına!

Bizi kavuşturan bir yol bulayım,

Kabe''ye uzanan yollar aşkına!

Sen büyüksün Rabbim,yüce lutfunla,

Ya bizi kavuştur,ya al yanına...

Bir kör kuyudayım,görünmez dibi,

Her nefes alışım bir feryat gibi.

Bir Kerem,bir Mecnun,bir Ferhat gibi

Gözü açık giden kullar aşkına!

Sen büyüksün Rabbim,yüce lutfunla,

Ya bizi kavuştur,ya al yanına...

''Seviniz''diyorsun yüce kitapta,

Verdiğin emirle düştüm bu aşka...

Bitir bu azabı,beni bağışla

Gözümden boşanan seller aşkına!

Sen büyüksün Rabbim,yüce lutfunla,

Ya bizi kavuştur,ya al yanına...', 'Bitsin bu ayrılık,bitsin Allah''ım, Sana şu uzanan eller aşkına! Bizi kavuşturan bir yol bulayım, Kabe''ye uzanan yollar aşkına! Sen büyüksün ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yakaris-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme ağlarsın', 'gitme-aglarsin-atabay-guveloglu-egq49', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu aşkı öldürüp,çekip gidersen,

Ağlarsın sevgilim,sen çok ağlarsın.

Gözlerini kapat,hisset istersen

Yanarsın sevgilim,sen çok yanarsın.

Kolay mı sanırsın ayrılıkları?

Kurur sanma gözlerinin pınarı...

Kır şu gururunu,geçmişi düşün,

Hani bir tek bendim o can yoldaşın?

Kalkması zor olur sonra düşüşün,

Kanarsın sevgilim,sen çok kanarsın.

Kolay mı sanırsın yalnızlıkları?

Kurur sanma gözlerinin pınarı...

Kusursuz dost olmaz demiştin bana,

Bilmeden olmuştur,bir kez bağışla.

Yeniden öp beni,gönlüme çağla,

Pınarsın sevgilim,sen bir pınarsın.

Biter ama göllerin de suları,

Kurur sanma gözlerinin pınarı...

Ne yapsan ruhunu saracak hüzün,

Bitecek umudun,solacak yüzün.

İnan ki yollarda kalacak gözün,

Bakarsın sevgilim,sen çok bakarsın.

Silmen mümkün değil o anıları,

Kurur sanma gözlerinin pınarı...

Özleyip dört yana baktıktan sonra,

Geç olur yaşamdan bıktıktan sonra.

Çok değil,kapıdan çıktıktan sonra

Ararsın sevgilim,sen çok ararsın.

Gördükçe dallarda şu kumruları,

kurur sanma gözlerinin pınarı...', 'Bu aşkı öldürüp,çekip gidersen, Ağlarsın sevgilim,sen çok ağlarsın. Gözlerini kapat,hisset istersen Yanarsın sevgilim,sen çok yanarsın. Kola...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gitme-aglarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve bendim', 'sen-ve-bendim-atabay-guveloglu-26bz9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk aşıklar Adem ile Havva''nın,

Ateşi sen,sanki bendim çağrısı.

Şehvet ile yedikleri elmanın

Çekirdeği sendin,bendim yarısı.

Kelebeğin,kuşun,suyun havanın,

Bizdeydi tüm güzelliği doğanın.

Emek dolu,çiçek dolu kovanın

Peteği sen,sanki bendim arısı.

Bizdik her örneği bunca nimetin,

Buğdayın,mısırın,bin bereketin.

Sevgilerle ördüğümüz demetin

Başağı sen,sanki bendim sarısı.

Adı kaldı sevgilerin,umudun,

Çiçeğin,bebeğin,kuşun,bulutun.

Özlemlerle sızlayan bir vücudun

Şifası sen,sanki bendim ağrısı,

Sanki,bendim ağrısı,bendim...', 'İlk aşıklar Adem ile Havva''nın, Ateşi sen,sanki bendim çağrısı. Şehvet ile yedikleri elmanın Çekirdeği sendin,bendim yarısı. Kelebeğin,kuşun...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ve-bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-hamit-karadag-squx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sım sıkı kapa gözlerini

Düşün bir an.

Yüreğini hisset, dinle bak,

Duyacaksın sevginin sesini.

Durma kulak ver bu sese

Ve yürü.

Yürü ki secgi engel tanımasın.

Kırmasınlar cesaretini.

Her  gönül arayıpta  bulmalı

kendinde sevgiyi.

Gün ışığı gibi sarsın hayatı,

sevgi doldursun

Dağı , taşı, ovayı, insanı.

Titresin yürekler hazzından ,

Arar olsun lezzetini sevginin.

Bir kuşun kanadına verelim

Alsın götürsün  bilmediğimiz diyarlara

Versin bir çiçek gibi,paylaşalım.

Hepimize yeter de artar bile.

Sevgiye sevdalanalım,Sevdalarda yaşayalım.

Paylaştıkça büyüsün

Büyüdükçe güzelleşsin

Ve  bir umut ışığı olup

Doğsun gönlümüze

Sevgi..............

BURSA-18.10.2000', 'Sım sıkı kapa gözlerini Düşün bir an. Yüreğini hisset, dinle bak, Duyacaksın sevginin sesini. Durma kulak ver bu sese Ve yürü. Yürü ki secgi...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-riza-aslan-i6p3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'anlamsız gibi gözükse de

yapılan her davranışın

şu an bir anlamı var

yarın anlamsızlaşsa da

düşünüldüğünde 

hata da sayılsa

yapılan her davranışın

şu an bir anlamı var', 'anlamsız gibi gözükse de yapılan her davranışın şu an bir anlamı var yarın anlamsızlaşsa da düşünüldüğünde  hata da sayılsa yapılan her davr...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-riza-aslan-vhsmt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'vazgeçmiştim

bu son veda artık bitirmişti

hiç olmayanı

ağlamamam gerekliydi

-ama- ağladım

yine dolandım sokaklarda başıboş

tanıdık yollardan 

o bildik caddelerden

hiç bilmiyormuş gibi geçtim

yabancıydı her şey 

ben yabancıydım', 'vazgeçmiştim bu son veda artık bitirmişti hiç olmayanı ağlamamam gerekliydi -ama- ağladım yine dolandım sokaklarda başıboş tanıdık yollardan...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vazgectim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bir Çocuk Olmak İstiyorum!', 'boyle-bir-cocuk-olmak-i-stiyorum-nur-kayapinar-5eop9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir söz söylemek istiyorum

Sonsuzluğa giden bir yolda

Birşey söylemek istiyorum

Doğruluk olan ülkelerde

Birşeyler yapmak istiyorum

Tarihe geçecek

Birşeyler yapmak istiyorum

Doğru yol gösterecek

Böyle bir kişi olmak istiyorum.

Bir ışık tutmak istiyorum

Savaş çıkan yerlere

Bir kuş olmak istiyorum

Özgürce yaşayan

Bir insan olmak istiyorum

Barış içinde yaşayan

Böyle bir kişi olmak istiyorum

Dünyada barış isteyen

Böyle bir çocuk olmak istiyorum

İnsan gibi yaşayan

                                                 1994(9 YAŞIM)', 'Bir söz söylemek istiyorum Sonsuzluğa giden bir yolda Birşey söylemek istiyorum Doğruluk olan ülkelerde Birşeyler yapmak istiyorum Tarihe ge...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/boyle-bir-cocuk-olmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liselim', 'liselim-nur-kayapinar-1vysq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden Pazartesi

Her akşam olduğu gibi 

Aklımdan hiç çıkmadın ki!

Artık birinci kural oldun bana

Yeni bir ödev oldun

Hergün seni düşünmek

Nereye gidersem gideyim

Ne zaman olursa olsun

Hep aklımda sen varsın

Seni düşünmeden edemiyorum

Hele yağmurlu gecelerde 

Yağmur damlaları gözyaşım oluyor

Tutamadan kendimi ağlıyorum

Ve hala seni düşünüyorum

Seslen bana kulak ver

Biraz olsun dinle beni

Ve biraz olsun doğru söyle

Sevdin mi beni?

Yoksa benle oyun mu oynadın?

Kullanıp beni attın bir kenara 

Ama inan,bana inan Liselim

Ben seni çok sevdim

Sana ben ölesiye aşıktım

Sen değerimi anlayamadın

Ben sevdim Liselim;seni sevdim

Sen benim değerimi bilmedin

Beni sevmeyi beceremedin.

                                                     01.02.1999-23:55

                                                         (ANKARA)', 'Bugün günlerden Pazartesi Her akşam olduğu gibi  Aklımdan hiç çıkmadın ki! Artık birinci kural oldun bana Yeni bir ödev oldun Hergün seni dü...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/liselim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum', 'seni-cok-seviyorum-nur-kayapinar-7y2ek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrıldığımız o günden beri

Üzülerek mutluluklar diledim sana

Saklasam da sevgimi

Senin yerin bir başka

Geçtiğimiz aylarda 

Seni ardım denizin köpüklü dalgalarında

Aşkım çok büyük inan bana

Bırak artık

Aşkı başkalarında arama

Sana neden aşık oluyorum?

Bilemiyorum.

Sana son kez söylüyorum

Bu sözümü iyi düşün

Seni Seviyorum.

Seni Çok Seviyorum.', 'Ayrıldığımız o günden beri Üzülerek mutluluklar diledim sana Saklasam da sevgimi Senin yerin bir başka Geçtiğimiz aylarda  Seni ardım denizi...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vakitsiz Giden Yaz', 'bu-vakitsiz-giden-yaz-ziya-osman-saba-imlkr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu vakitsiz giden yaz, erken inen akşamla,

Kapanmış pancurlara dayıyarak başını,

Dinle solgun bahçenin kalbe anlattığını,

Ağacın yaprak yaprak, havuzun damla damla.

Kuşlar sanki yaralı, benzin sararmış gamla,

Duymak güneşin, rengin bizi bıraktığını,

Günler günü vefasız leyleklerin akını.

-Ah uzak palmiyeler... Kaçmak, seninle, yazla.

Çardak altları bitti, bitti üzümün tadı,

Artık ihtiyar çamlar, selviler saltanatı,

İşte bir kere daha haraboldu bahçeler.

Ürperen vücudunu yavaşça koluma ver.

Gözlerinde okunan bütün hüznü eylülün,

Karanlıktan, geceden, ölümden korkan gönlün.', 'Bu vakitsiz giden yaz, erken inen akşamla, Kapanmış pancurlara dayıyarak başını, Dinle solgun bahçenin kalbe anlattığını, Ağacın yaprak yapr...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-vakitsiz-giden-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sayfa Soluk Vede Tozlu', 'bir-sayfa-soluk-vede-tozlu-tamer-avci-99r8g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehrin ışıklarını gözlerimle öpüyorum her gece

 içimdeki nehre bu yüzden hiç bakamıyorum

 Solgun bir yüzle doğuyorum ve ölüyorum her sabah

 Yağmur o sabah ve o gece yağmıyor,inadını

 anlıyorum

 Karanlık durgun coşkun uğultuluyum bir zaman

 Bir zaman ölümün kelepçelerini çıkarıyorum

 papatyadan tırnaklarımı geri alıyorum bir zaman

 Mümkünmü? rüzgarımla saçlarını örüyorum

 Bir heyalanla dağdan iniyor heyacanlarım

 Patika patika yükseliyorum engebeli yüreğine

 Orada umut metrekare metrekare çiğneniyor

 Topraksız kalsamda susuz kalamıyorum

 Bir sayfa en sona kalıyor solgun ancak tozlu

 Bir sayfa siyah bir geleceğe açılıyor

 Kapanıyor yıpranıyor vede ölüyor durmadan

 Tozlu bir sayfada kalıyor umut, sen vede zaman', 'Şehrin ışıklarını gözlerimle öpüyorum her gece  içimdeki nehre bu yüzden hiç bakamıyorum  Solgun bir yüzle doğuyorum ve ölüyorum her sabah  ...', ARRAY['Türk Edebiyatı','Şiir','Tamer Avcı']::text[], 8.5, '{"poet":"Tamer Avcı","poet_slug":"tamer-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sayfa-soluk-vede-tozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Anlamı Sen', 'yasamin-anlami-sen-zulkuf-cengiz-xuptv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '>Gidişinle Agrı güneşe küsmüştü 

>Hayat yaşanmışlar içinde kötü 

>Yaşanmamışlar arasında ise 

>Anlamsızdı 

>Gidişinle geceler 

>Nefret saçıyordu gülüm ve ben bu nefretler 

>İçinde sana 

>Seni seviyorum diyebiliyorsam 

> 

>Utanmadan sevgimi haykırabiliyorsam 

>Söylermisin bu bu nedemektir 

> 

>Dünyadan daha küçük olan kalbime 

>Dünyanın taşıyamayacagı kadar sevgi besliyorsam 

>Sana karşı anlaki ben seni çok seviyorum 

>', '>Gidişinle Agrı güneşe küsmüştü  >Hayat yaşanmışlar içinde kötü  >Yaşanmamışlar arasında ise  >Anlamsızdı  >Gidişinle geceler  >Nefret saçıy...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasamin-anlami-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidim Var..', 'umidim-var-simge-atakan-gj3b0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel desem gelir misin esen rüzgarla

Sorar mısın beni sonbahardaki yağmurlara

Güneşim olup doğar mısın her sabah odama

Ve beni sevdiğini söyleyip yaşar mısın hayatı zamanında

Söyle bir tanem şarkıları benimle sever misin

Çiçeğim ol desem,bir damla su versem açar mısın

Barındırır mısın beni ufacık sevgi dolu yüreğinde

Ve şimdi seni sevdiğimi söylesem ne dersin?

Gel,bak,gör beni ne haldeyim sensiz

Tek başıma olmuyor her şey densiz

Anla bir tanem karanlık dünyam ve ben kimsesiz

Ama her şeye rağmen seni bulmaya ümidim var!', 'Gel desem gelir misin esen rüzgarla Sorar mısın beni sonbahardaki yağmurlara Güneşim olup doğar mısın her sabah odama Ve beni sevdiğini söyl...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umidim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Şey Aynı Değil...', 'hicbir-sey-ayni-degil-simge-atakan-htbk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey aynı değil artık 

Ne ben, ne sen, ne insanlar

Nede doğan güneş aynı

Yağmur farklı yağıyor üstüme

Dedim ya  hiçbir şey aynı değil artık

Eskiden böyle değildim oysa

Sen yanımdayken her şey farklıydı

Ama şimdi zifiri karanlık çöktü gökyüzüne

Ağaçlar yapraklarını döktü

Soldu sarısıyla,kırmızısıyla,beyazıyla açan güller

Geride kaldı özlemle beklenen günler

Sıkıldım artık ben Ankara’dan

Neden mi nedeni sen bilirsin

Hiç yalvarmayan ben,

Sırf senin için yalvarıyorum

İtiraflar geçtikçe zorlaşır

Ben senle geçen günlerimi özlüyorum

Anlıyor musun belki gelirsin diye 

Bir umutla bekliyorum....', 'Hiçbir şey aynı değil artık  Ne ben, ne sen, ne insanlar Nede doğan güneş aynı Yağmur farklı yağıyor üstüme Dedim ya  hiçbir şey aynı değil ...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hicbir-sey-ayni-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusunda', 'uykusunda-yilmaz-erdogan-x3vrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aydın tolan''a

melekler gibi öldü

melekler ölür mü hiç?

bilmem...

ama ölürse

mutlaka böyle ölür...', 'aydın tolan''a melekler gibi öldü melekler ölür mü hiç? bilmem... ama ölürse mutlaka böyle ölür......', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uykusunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-ferah-guneri-bircan-t66yr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahibi olmayan,

O dudaklar! 

Benim ile beraber,

Beslediğinde bizleri; 

Tat alma duyumla! 

Tapacağıma sana; 

Engeli bulunmayan,

O kulaklar! 

Dinlediğinde sevgimi,

Duyduğunda sesimi; 

İşitme duyumla! 

Tapacağıma sana; 

Doğadan uzak kalan,

O burunlar! 

Benimle soluduğunda; 

Koklama duyumla! 

Tapacağıma sana; 

Bakmak değil de,

Artık görmek isteyen,

O gözler! 

Aradığında,

Her yerde beni; 

Görme duyumla! 

Tapacağıma sana; 

Sonucunda benim olmayan,

O bedenin! 

Ruh ve bedeni ile,

Tapusunu verdiğinde bana; 



Sadık kaldıkça,

Can bedene:

İbadet eder gibi,

Tüm sadakatimle! 

Tapacağım,

Beş duyumla,

Bir ömür,

Söz! 

Bende sana.', 'Sahibi olmayan, O dudaklar!  Benim ile beraber, Beslediğinde bizleri;  Tat alma duyumla!  Tapacağıma sana;  Engeli bulunmayan, O kulaklar!  ...', ARRAY['Türk Edebiyatı','Şiir','Ferah Güneri Bircan']::text[], 8.5, '{"poet":"Ferah Güneri Bircan","poet_slug":"ferah-guneri-bircan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/soz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus Diyorsun', 'sus-diyorsun-sota-papaladze-yem6v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sus diyorun bana konuşma

Konuşmaya başlamadımki daha.

Dinliyorum dinliyorum,

Sonuna dek gizleniyrum.

İsteyip konuşamıyorum ben,

Sus konuşma diyorsun sen.

Hele bir duyabilseydin konuştuğumu

Acaba diyebilecekmiydin bir daha konuşma

Gözlerinden yaş dökülecekti belki

Sus konuşma diyemiyecektin inanki...

                                        Taşkent    13.10.2000', 'Sus diyorun bana konuşma Konuşmaya başlamadımki daha. Dinliyorum dinliyorum, Sonuna dek gizleniyrum. İsteyip konuşamıyorum ben, Sus konuşma ...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sus-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Çay İçeriz', 'biz-cay-i-ceriz-mehmet-yavuz-40gte', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz her akşam çay içeriz

Kafayı çeker gibi

Dalarız en derim hayallere

Yanı başımızdaki mum gibi

Bir türlü gerçekleşmez

Kahpe hayaller

Soğur çayımız

Gözyaşlarımızla beraber

Biz karıştırırız çayı

Dünyayı dönderir gibi

Bir yudum çekeriz midemize

Tüm dertleri sinemize çektiğimiz gibi

       8 Ekim 2000-Pazar', 'Biz her akşam çay içeriz Kafayı çeker gibi Dalarız en derim hayallere Yanı başımızdaki mum gibi Bir türlü gerçekleşmez Kahpe hayaller Soğur ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yavuz']::text[], 8.5, '{"poet":"Mehmet Yavuz","poet_slug":"mehmet-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/biz-cay-iceriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen Ya Ben', 'ya-sen-ya-ben-suleyman-avci-fh776', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni öylesine düşünüyorum ki 

bazen

yaşamakla yaşamamak arasında kalıyorum

ve seni öylesine seviyorum ki

bazen

yaşatmakla yaşatmamak arasında kalıyorum', 'seni öylesine düşünüyorum ki  bazen yaşamakla yaşamamak arasında kalıyorum ve seni öylesine seviyorum ki bazen yaşatmakla yaşatmamak arasınd...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ya-sen-ya-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Esince', 'sen-esince-suleyman-avci-1tms8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen 

her sevginin ardından gelen 

bir rüzgar olmalısın

büyük bir sevgi yağmurundan önce esmelisin yüreğime

yüreğim dersen

kapamalı ardından 

tüm giriş ve çıkışlarını', 'sen  her sevginin ardından gelen  bir rüzgar olmalısın büyük bir sevgi yağmurundan önce esmelisin yüreğime yüreğim dersen kapamalı ardından ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-esince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyle-i Bi Bedr', 'leyle-i-bi-bedr-sair-sabuni-lgckr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Leyle-i bi bedr misalisin 

Leyla-i bi vefa hallisin 

Güzel yüzlü tatlı kallisin

Sen zi müjgan-ı hilallisin

Sine-i zaliminde var nur-ı hafi

Bir busecik versen o bana kafi 

Ref-i aşkın fıtrata münafi

Sen bi vefasın ben ise vafi

Bu sefil can ile eylesen kelam

Sarar nale-i dilimi berd ile selam

Yar bi vefasın olmuşsun belam

Aşk-ı memnun ile olacak ihyam', 'Leyle-i bi bedr misalisin  Leyla-i bi vefa hallisin  Güzel yüzlü tatlı kallisin Sen zi müjgan-ı hilallisin Sine-i zaliminde var nur-ı hafi B...', ARRAY['Türk Edebiyatı','Şiir','Şair Sabuni']::text[], 8.5, '{"poet":"Şair Sabuni","poet_slug":"sair-sabuni","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/leyle-i-bi-bedr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yere Kadar', 'bir-yere-kadar-nilgun-sezer-ruzgar-melegi-4v7eu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yere kadarmış,sevgin gülüşün 

Bir tatlı sözünle beni öpüşün

Bir yere kadarmış aşkı sezişin

Kollarını açıpta bana gelişin

Bir yere kadarmış aşkım sevgilim

Nerde,ne zaman gelecekti bu aşkın sonu?

Aklımda takılıydı,hep bu soru

Aldanış mı olmalıydı sevdanın yolu?

Boynuna doladığım,şu sevgi dolu

Kollarım mutluyken,gözlerim dolu

Sıradışı bir aşka sınır koydu

Dilinden dökülen bir hançer oldu

Bir yere kadardır sevgi dediğin...

 Nilgün Sezer (Rüzgar Meleği)', 'Bir yere kadarmış,sevgin gülüşün  Bir tatlı sözünle beni öpüşün Bir yere kadarmış aşkı sezişin Kollarını açıpta bana gelişin Bir yere kadarm...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Sezer (Rüzgar Meleği)']::text[], 8.5, '{"poet":"Nilgün Sezer (Rüzgar Meleği)","poet_slug":"nilgun-sezer-ruzgar-melegi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yere-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Ebruli', 'askim-ebruli-nilgun-sezer-ruzgar-melegi-sidrk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana öyle bir gün ver ki

Sonsuzluk kadar uzun olsun

Yarınlarım bugün olsun

Ruhumda aşkın renkleri

Pembe,mavi,yeşil olsun

Sarılar sarsın onları

Dalgalar ebruli dursun

Bana öyle bir gün ver ki

Sonsuzluk kadar uzun olsun

Su üstünde oynaşan dalgalar gibi

Benim aşkımda ebruli

Ruhumun desenleri,

Yüreğinde nakış olsun

Bu sevginin hikayesi

Ölümsüz bir motif olsun

Bana öyle bir gün ver ki

Yarınlarım bu gün olsun

 Nilgün Sezer (Rüzgar Meleği)', 'Bana öyle bir gün ver ki Sonsuzluk kadar uzun olsun Yarınlarım bugün olsun Ruhumda aşkın renkleri Pembe,mavi,yeşil olsun Sarılar sarsın onla...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Sezer (Rüzgar Meleği)']::text[], 8.5, '{"poet":"Nilgün Sezer (Rüzgar Meleği)","poet_slug":"nilgun-sezer-ruzgar-melegi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askim-ebruli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Vur', 'sende-vur-nilgun-sezer-ruzgar-melegi-6k220', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hadi sende vur 

Adettendir,seven vurulur

Sevilenindir gurur 

Sevgi dolu dizgin

Sevgi içten

Sevgi savunmasız 

Hadi sende vur

Senindir bu onur

Vur düşünme,

Acı onda güzel durur 

Vur aldırma 

O senindir,kırılsa  ne olur?

Sonra git

Arkana bakmadan git ki

Darmadağın,solmuş halimi

Görmeden git

Belki içinde pişmanlık olur

 Nilgün Sezer (Rüzgar Meleği)', 'Hadi sende vur  Adettendir,seven vurulur Sevilenindir gurur  Sevgi dolu dizgin Sevgi içten Sevgi savunmasız  Hadi sende vur Senindir bu onur...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Sezer (Rüzgar Meleği)']::text[], 8.5, '{"poet":"Nilgün Sezer (Rüzgar Meleği)","poet_slug":"nilgun-sezer-ruzgar-melegi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sende-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-yusuf-kotan-g3csk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dikenden çalıdan bir yola düştüm,

Yırtılmakta yürüdükçe her yanım,

Geri dönmek sonu kadar uzakta,

Ben hayattan yaşamaktan usandım.

Olur mu Allahın günü düşünmek.

Revamı bu yaz günü böyle üşümek.

Geceleri savuşturmak uykusuz.

Hep bana mı düştü böyle üzülmek', 'Dikenden çalıdan bir yola düştüm, Yırtılmakta yürüdükçe her yanım, Geri dönmek sonu kadar uzakta, Ben hayattan yaşamaktan usandım. Olur mu A...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kotan']::text[], 8.5, '{"poet":"Yusuf Kotan","poet_slug":"yusuf-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yol-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum...', 'gidiyorum-sair-doktor-8ywlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsmini yazasım gelmiyor artık,kağıtlara

sesini de özlemiyorum

ve resimlerini yan yana koyarken ben

birşeyler hissetmeyi umut ediyorum.

Kalbimde üşümekte olan bir şarkının akorları,

dilim ise ayrılığın sözlerini söylüyor

akordsuz bir gitardan çıkan titreşimlere...

Şimdi yağmurlar yağıyorken bu kente

ben hep şemsiyesiz sonbaharları özlüyorum,

ıslanmanın aşkı akla getirişine şaşırıyorum.

Çiselerken damlalar ipek saçlarına

ben gidiyorum...

Ve giderken yanımda

aşkı ve ayrılığı götürüyorum!

İsmini yazasım gelmiyor artık,kağıtlara

ama her kalem tutuşumda

ve isminin baş harfini yazarken bile

seni hatırlayacağım...', 'İsmini yazasım gelmiyor artık,kağıtlara sesini de özlemiyorum ve resimlerini yan yana koyarken ben birşeyler hissetmeyi umut ediyorum. Kalbi...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidiyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sevmedim Kİ', 'hic-sevmedim-ki-mehmet-tas-ozsk9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok uzun yollar aştım

Çakıl taşları kesti ayaklarımı

Yedi başlı devler

Yedi köprüde kesti de yolumu

Ulaşmak için pınarlarına sevdanın

En güzel rüyalarımı paç verdim..

Hasret rüzgarları doldurdu yelkenlerimi

Anaforlarında bin türlü belanın 

Bir tek limanım vardı

İçimdeki sevdanın ateşinde ısındım.

Bil ki 

Yaşanacak hiçbir bela kalmadı geride

Hiçbir sevda geçmedi gönlümdeki sevdayı

Hiçbir fani ulaşamadı 

Gönlümde kurduğum 

Tepesi alaca şafaklarla dolu

Meleklerin at koşturduğu

Yıldızların nakış nakış işlendiği

Sevda dağının zirvesine.

Sen ki;

Etinle,kanınla canınla

Bir ölümlü değil misin ki

Sen ki,

Sevda dağının zirvesinde 

Meleklerin çağrısını duymadın ki

Ve sen 

Gönlümün zirvesine yerleşemedin ki..

Ben seni hiç sevmedim ki......

       mehmet TAŞ', 'Çok uzun yollar aştım Çakıl taşları kesti ayaklarımı Yedi başlı devler Yedi köprüde kesti de yolumu Ulaşmak için pınarlarına sevdanın En güz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hic-sevmedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tehlike', 'tehlike-koray-askin-dva4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tehlikenin çemberi daralır,

seni keser beni keser ellerimden.

hain!

kahpedir böyle ve ansız...

tehlikenin çemberi geçer beni,

illede sevdiğimi alır

kahpe!

haindir böyle ve zamansız...

tehlikenin çemberi susar

kapatmaz çenesini,kana susar

sana susar,bana susar,

korkarım!

hayat gibidir o,ölüm gibi değil;

seni almaz çünkü sevdiğine göz diker...', 'tehlikenin çemberi daralır, seni keser beni keser ellerimden. hain! kahpedir böyle ve ansız... tehlikenin çemberi geçer beni, illede sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Koray Aşkın']::text[], 8.5, '{"poet":"Koray Aşkın","poet_slug":"koray-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tehlike-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Büyük', 'adi-buyuk-koray-askin-gx76m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dön davut dağlara

yaşın küçük ismin büyük bilirim

dön davut dağlara ne işin var buralarda

annen nerdedir kimbilir şimdilerde

uzaksa ya bize, neden yalnızsın? 

dön davut yüzünü oraya; 

o dağlara dön yüzünü bana sırtını ver

ve madem yok annen yanında

tutma daha fazla çişini

şu köşeye yapıver...', 'dön davut dağlara yaşın küçük ismin büyük bilirim dön davut dağlara ne işin var buralarda annen nerdedir kimbilir şimdilerde uzaksa ya bize,...', ARRAY['Türk Edebiyatı','Şiir','Koray Aşkın']::text[], 8.5, '{"poet":"Koray Aşkın","poet_slug":"koray-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adi-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilet', 'bilet-koray-askin-xzfpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gel güzelim gözlerinde,

benler var.

güzelim gel dudaklarında,

tadım kalmış.

sensiz beklenmiyor otobüsler;

duraklar sessiz olmuş.

biletim sende,

biletim siyah montunun,

iç cebinde kalmış!

hadi gel güzelim,

inat etme.

sensiz burdan bile;

ayrılamıyorum işte...', 'gel güzelim gözlerinde, benler var. güzelim gel dudaklarında, tadım kalmış. sensiz beklenmiyor otobüsler; duraklar sessiz olmuş. biletim sen...', ARRAY['Türk Edebiyatı','Şiir','Koray Aşkın']::text[], 8.5, '{"poet":"Koray Aşkın","poet_slug":"koray-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamı arıyorum', 'sevdami-ariyorum-hamit-karadag-4nbba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dudaklarının kırmızısında mı saklı herşey?

Öpsem anlayabilir miyim?

Gözlerinin elasında mı yoksa,

Baksam okuyabilirmiyim?

Kumralında mı saçlarının,

Okşasam onları, hissedebilir miyim?

Nerede saklı benim sevdam?

Kalbinde mi?

Açar mısın?

Gireceğim..................

BURSA-18.10.2000', 'Dudaklarının kırmızısında mı saklı herşey? Öpsem anlayabilir miyim? Gözlerinin elasında mı yoksa, Baksam okuyabilirmiyim? Kumralında mı saçl...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdami-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-hamit-karadag-3xqhj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevinmek yasak bana,

coşmakta.

Hani yaşamak istesem 

Doyasıya bir sevdayı  var ya;

Dünyayı yıkacaklar başıma.

Yada haykırsam avazım çıktığınca

Seni seviyorum diye,

Deli gömleği giydirecekler.

Hele gülsem bir de içten

kahkahalarla,

Hepten deli diyecekler.....

Bursa- 18.10.2000', 'Sevinmek yasak bana, coşmakta. Hani yaşamak istesem  Doyasıya bir sevdayı  var ya; Dünyayı yıkacaklar başıma. Yada haykırsam avazım çıktığın...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüm mü', 'dondum-mu-riza-aslan-pycoo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'döndüm mü benliğime 

bilmiyorum

aylar 

belki de yıllar sonra 

seni arıyor ve ağlıyorum', 'döndüm mü benliğime  bilmiyorum aylar  belki de yıllar sonra  seni arıyor ve ağlıyorum...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dondum-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmiyor', 'degismiyor-riza-aslan-giltx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazı şeyler değişmiyor

değiş desen de

değiştiremediklerine

aptalıktan desen de

salaklıktan desen de

herşey yerli yerinde

bazı şeyler değişmiyor

sen ne kadar istesen de', 'bazı şeyler değişmiyor değiş desen de değiştiremediklerine aptalıktan desen de salaklıktan desen de herşey yerli yerinde bazı şeyler değişmi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/degismiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadıklarının Ezginliği', 'anlatamadiklarinin-ezginligi-riza-aslan-l6w1t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anlatamadıklarının ezginliği 

bir yerde yakalıyor ve eziyor seni

yakalanmamak için ne kadar da uğraşsan

her köşe başında ardınıda kollasan

anlatamadıklarının ezginliği 

bir yerde yajalıyor ve eziyor seni

ve anlamı kalmıyor

anlatamadıklarının

o çok değer verdiğin giz kayboluveriyor

-kayboluyor-

25-07-2000', 'anlatamadıklarının ezginliği  bir yerde yakalıyor ve eziyor seni yakalanmamak için ne kadar da uğraşsan her köşe başında ardınıda kollasan a...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anlatamadiklarinin-ezginligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
