INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Kimse Söküp Alamadılar', 'hic-kimse-sokup-alamadilar-ruya-ersoy-n4ws5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerime zincire vurdular

Ayaklarıma prangalar taktılar

Kalbime hançer sapladılar

Beni karanlık bir kodese attılar

Ama içimdeki sana olan sevgimi 

hiç kimse söküp alamadılar

Gözlerimi kör edip dağladılar

Gözyaşlarımdan bir pınar yaptılar

Tırnaklarımı parmaklarımdan söktüler

Kalbime hançer sapladılar

Ama içimdeki sana olan sevgimi

Hiç kimse söküp alamadılar', 'Ellerime zincire vurdular Ayaklarıma prangalar taktılar Kalbime hançer sapladılar Beni karanlık bir kodese attılar Ama içimdeki sana olan se...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-kimse-sokup-alamadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yokluğunda Ben Çok Yalnız Kaldım', 'senin-yoklugunda-ben-cok-yalniz-kaldim-abidin-aral-7dona', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni gördüğümde bakışlarım bir insan bakışından farklıydı

Tam bir hayvan gibi bakıyodum sana 

Sende bunun farkındaydın,

Ve bunu anlamandan sende vahşice bakış attın.

Sanki karşımda bir siyam yavru kedisi vardı.

Sanki bende serengeti''nin geniş düzlüklerindeydim.

Ve bende alabildiğine süren bir avın içindeydim

Çok koştum,çok yoruldum 

Ama sonunda sen benim olmuştun

Ve seni kollarımın arasına alıp sarmalamıştım.

Seni doyasıya koklayıp hayatımın kadını yapmak istiyodum.

Sende bunu anlayışla karşılayıp evet demiştin

Seninle çok güzel günlerimiz olacaktı,

Ama olmadı sen benim olamadın sevgilim

Hain 29 Ekim 

Sensizliği yaşadığım 33 üncü gün

Seni benden alıp gitti,azrail

Seni çok özledim,nolur gel', 'Seni gördüğümde bakışlarım bir insan bakışından farklıydı Tam bir hayvan gibi bakıyodum sana  Sende bunun farkındaydın, Ve bunu anlamandan s...', ARRAY['Türk Edebiyatı','Şiir','Abidin Aral']::text[], 8.5, '{"poet":"Abidin Aral","poet_slug":"abidin-aral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senin-yoklugunda-ben-cok-yalniz-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğumuz', 'mutlulugumuz-ruya-ersoy-h5gzk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmişin üzüntüsünü giderek mutluluğumuz

Hüzünlü,buruk günler yerine ,sevgi olacak umudumuz

Hasret yakında bitecek huzur dolacak  yuvamız

Yeniden yaşama sevinci  ile dolacak gönlümüz

Kırgınlıkların yaşanmayacağı bir dünya yaratacağız

Sevgi kelimelerini kalbimizden haykıracağız

Hiçbir zaman dünyamızda yalana yer vermeyeceğiz

Sevgi ışıklarımıza gıpta ile bakacaklar

Çünkü herkezi ,mutluluğumuzla ısıtıcağız', 'Geçmişin üzüntüsünü giderek mutluluğumuz Hüzünlü,buruk günler yerine ,sevgi olacak umudumuz Hasret yakında bitecek huzur dolacak  yuvamız Ye...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutlulugumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyek', 'diyek-ozdemir-asaf-ajw2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkiye''de İstanbul ne ise, 

İstanbul''da gece ne ise,

Gecede yürümek ne ise,

Yürürken düşünmek ne ise, 

Seni unutamamacasına düşünmek ne ise, 

Unutamamanın anlamı ne ise, 

Seni sevmek ne ise, 

Saklayayım, yok söyleyeyim derken 

Birden aşka düşmek ne ise. 

Her neyse.', 'Türkiye''de İstanbul ne ise,  İstanbul''da gece ne ise, Gecede yürümek ne ise, Yürürken düşünmek ne ise,  Seni unutamamacasına düşünmek ne ise...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/diyek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Kutsal Duygu', 'en-kutsal-duygu-ruya-ersoy-bkpcd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek insanlara lütfedilen en kutsal duygu

Bunun kıymetini bilelim ve sevgiye sıkıca sarılıp

Onu kaybetmenin acısını tatmamak için

Elimizden ve kalbimizden hiç çıkartmayalım

Bunun acısı çok büyük olur sonra

İnsanoğlu sakın bunu unutama

Unutursan eyer

Senin için yaşamanın anlamı kalmaz bu dünyada', 'Sevmek insanlara lütfedilen en kutsal duygu Bunun kıymetini bilelim ve sevgiye sıkıca sarılıp Onu kaybetmenin acısını tatmamak için Elimizde...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/en-kutsal-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizik', 'cizik-ozdemir-asaf-vkn82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geleceğim, bekle dedi, gitti.. 

Ben beklemedim, o da gelmedi. 

Ölüm gibi bir şey oldu..

Ama kimse ölmedi.', 'Geleceğim, bekle dedi, gitti..  Ben beklemedim, o da gelmedi.  Ölüm gibi bir şey oldu.. Ama kimse ölmedi....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cizik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-evrim-ertugrullu-lu7d1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşi koyamadim ben bu sevdaya

Zor olmadı yüreğimin sana teslimi

Şimdi,şimdi bu sevdanin karanlik zindanlarinda 

Yapayalnız zavallı bir esirim

Ne bir ses var uzaklarda,ne de bir ışık var mutluluk adına

Zaman zaman yakınlarda 

Çok yakınlarda yalnız bir yıldız var

Karanlık bulutlar arasında...

Yağmur misali ruhuma yağıp beni sellerinde boğan

Irmak olup engin denizlere kavuşan

Rüzgar olup bedenimi sımsıkı saran,

Tertemiz bir aşk var yüreğimde senin adını taşıyan.

Güller ektim yüreğime demet demet,

Umut koydum adını her bir çiçeğin

Bildiğim gördüğümden farklı,

Düşledigim gerçeklerden uzakta bir yalandi çogu kez

Ama yine de inandırmıştım kendimi öylece

Bir gün,

Bir gün senin de beni sevebileceğine

Umudu taşimak yeterdi belki,

Bir nokta koymadan yaşadigimiz hiçbir şeye.

Sonunu getirerek başlanmişi yok etmek kolay degildi

Ve kolay değildi yine, senden uzakta seni düşünmeden yaşamak

Yüreğimin bitmeyen yalnızlığının beni ölesiye sardığı 

Biçare bir sevdalıyım ben

Yokluğunda yaşamak için çırpınan,

Geceleyin kendince hayaller kuran

Hep içimde, 

Hep içimde yaşatarak umudu 

Uzağında varlığından bir ışık arayan bir sevdalıyım ben

Ve belki hiçbir zaman beni sevmeyeceğini bile bile

Yine de seni bekleyen yalnız bir sevdalıyım ben

Sonsuzluğun ötesinde bir sevgiyle...

Bir temmuz sabahıydı sana ilk rastladığım an

Bilmezdim,

Bilmezdim o zaman yüreğimin sana böyle bağlanacağını

Demir atmıştı bir gemi hiç anlamadan,

Ayrılmak istemediği bir limana ansızın.

Sonsuza dek kalabilir miydi bu limanda?

Bilseydi eğer bu limanda hiç istenmediğini...

Ya da bir umut daha var mıydı

Sevdiğinden uzakta bir sevdalı yaşar mıydı?

Ve ben seni sevmeseydim eğer 

Böyle ansızın içimi açar mıydım?

Ve tek bir soru kalmıştı artık kendime sorduğum

Eğer bilseydin bu sevgimi, benden daha çok kaçar mıydın?.

Ey sevgili!

Bil ki seni sevdiğimden beri ,

Senden başka düşüncem olmadi böyle derinden

Sensiz bir hayalden uyanmadım hiç sabahları

Ve her yeni güne gözlerimi açıp ‘merhaba!’ deyince

Hiçbir şey gelmedi hatirima senin varligindan önce

Her sensiz geçen günün mutsuz akşaminda

Gün batarken gökyüzünün kor kızıllığında

Bil ki,

Bir yanık sevdalı hep seni hatırlar,

Yokluğunun o amansız karanlığında...

Öyle sessiz uzaktan bir sevdaydı işte!

Ansızın benliğimi sarıp kalbimin içine yerleşen

Ve her geçen günün ardında,

Uzağında umudumla beslenen

Sen olmuştun artik!

Hayatıma verdiğim en güzel anlam 

Oysa ,

Oysa bir ağacın bağrında gizli kalmıştı sevdam

Dallarına kuşların yuva yaptığı,

Ve üzerinde bülbüllerin coşkuyla adini sayikladigi.

Sokaklarda duvarların en kuytu köşesinde, 

Parklarda oturakların üzerine kazılmış harflerinde.

Güzelliğinin büyülü ışığından uzakta kalan,

Yüreğimde gizli kalmıştı senin için çarpan

Hasretinle yanan deli yüreğimde...

Öyle sessiz uzaktan bir sevdaydı işte!

Sensiz geçen her günün hayalinle dolu gecesinde

Çoğu zaman gözyaşlarımda gizli kalmıştı

Yokluğunun acımasızca yaraladığı 

Özleminle dolu yüreğimde...

Bir sıcak tebessümünde hayalinin bende bıraktığı

Ve bir de dile gelen satırlarında gizli kalmıştı sevdamın

Sararan bir yapraktı, rüzgarlara kapılıp göklerde savrulan

Ve habersiz yaşadim bunca zaman

Hep arayıpta bulamadığım bu sevdadan,

Hayatıma renk katan varlığından...

Oysa önemli olan tek bir gerçek vardı artık.

Kalbimin sonu gelmeyen burukluğunda ,

Tertemiz bir hayal olmuştun inandigim.

Çıkmaz sokaklarında kaybolduğum her yolun sonunda,

Bir ışık olmuştun umutlu güzel günler adına...

Ve her şey çaresizce anlamını kaybederken ansızın,

Birşeyler öylece büyüyordu içimde sana karşi.

Yitirmişligin de ötesinde bir duyguydu bu ,

İçimde yaşattigim...

Ne var ki geçişi çok çabuk olmuştu zamanin,

Oysa hiç böyle kendimi umuda bağlamamıştım...

Her kabusun titreten ürpertisinde,

Ufka çöken karanlığın ardında her gece.

Hep seni kaybetmenin korkusunu yaşadim,

Sevgini kazanmışçasına bir hayal içinde...



Adını adımla yan yana kazıdım umut diye

Sevda diye! aşk diye! KADER diye yüregime!

Kalbimi sana teslim etmişsem artik,beni sakın yaralama sevdiğim!

Ansızın benliğime girip beni sarmışsan artık

Dalga dalga yayılan sevdamı çiğneyip,beni sensiz bırakma sevdiğim!

En büyük sevgilere inat yaşayalim istersen sonsuzluk diyarinda

Rüyamı benden geri alıp  beni acıya dost,mutlululğa hasret bırakma !

Ve yine unutma ki,

Dilersen bir sözünle en büyük mutluluklara salarsın beni

Ve yine dilersen bir sözünle en büyük ateşlere atarsin beni...

Bir bütünün iki yarısı

Ya da ruhumun aradığım diğer parçasıydın sen

Çünkü seni tanıdığım anda hissetmiştim bunu yüreğimde

Bir kıvılcım doğmuştu gözlerinden gönül bahçemin solmuş çiçeklerine

Kader oyununu oynamıştı yine bana

 En savunmasız olduğum bir anda sessizce!

Amaç neydi oysa, benliğini yitirmiş bu dünyada 

Yüreklerde derin bir sevgiyi yaşamaktan başka?

Gözlerinde bulduysam kendimi

Sözlerinde terkettiysem benliğimi

Bil ki!

Bu benim savunmasızlığımdan değil

Yüreğimdeki yansımasındandır 

İçimde kaybolmuş birşeylerin...

Dedim ya

Dedim ya karşi koyamadim ben bu sevdaya 

Zor olmadı yüreğimin sana teslimi

Şimdi ,şimdi bu sevdanin karanlik zindanlarinda 

Yapayalnız zavallı bir esirim...

Aşk oradaydi,işik oradaydi,umut oradaydi yine oysa

Mümkün olabilseydi keşke !

Beni sevdiğini duysaydım bir gün senden yalan da olsa!

Bir gece de beni sevdiğini düşünerek uyusaydım.

Artık,

Artık uzak olmasaydı bu hayal bana

Ve bu karanlıklar sensizlikle dolmasaydı!

Mümkün olabilseydi keşke

Yüreğimdeki bu umut hiçbir zaman solmasaydı.

Bir gece beni sevdiğini düşünerek uyusaydım,

Ve bir daha

Bir daha uyanmasaydım...', 'Karşi koyamadim ben bu sevdaya Zor olmadı yüreğimin sana teslimi Şimdi,şimdi bu sevdanin karanlik zindanlarinda  Yapayalnız zavallı bir esir...', ARRAY['Türk Edebiyatı','Şiir','Evrim Ertuğrullu']::text[], 8.5, '{"poet":"Evrim Ertuğrullu","poet_slug":"evrim-ertugrullu","theme":"Türk Şiiri","is_hero":false,"total_lines":139,"source_url":"https://www.antoloji.com/umut-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim?', 'ben-kimim-i-zzettin-kahraman-ny59l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben nicelerini rahatlattım,

''Oh''..diyen seslerini duydum.

Nicelerini dört duvar arasına kapattım,

Kahrolsunlara vuruldum.

Ben nice aşıkları elele tutuşturdum,

Nice gizliyi gerçeğe kavuşturdum.

Ben neler gördüm neler

Neler gördü benim gibiler

Benim kolum kirli kanadım boyalı,

Arkadaşım size ışık verdi, yerine koyuldu koyulalı

Ben ne inim ne de bir cinim

Hergün beraber yaşadığınız BEN KİMİM?', 'Ben nicelerini rahatlattım, ''Oh''..diyen seslerini duydum. Nicelerini dört duvar arasına kapattım, Kahrolsunlara vuruldum. Ben nice aşıkları ...', ARRAY['Türk Edebiyatı','Şiir','İzzettin Kahraman']::text[], 8.5, '{"poet":"İzzettin Kahraman","poet_slug":"i-zzettin-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-kimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizcan', 'denizcan-baris-karabulut-xj2y7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep seni sevdim, seni düşündüm

Söyleyemedim bir kere

Kızarsın diye;

Rüyamda her gece ben seni gördüm

Uyanmak istemezdim

Gidersin diye;

Deniz yeşili gözlerin vardı sevdaya salan,

Bakamazdım bir türlü,

Sezersin diye;

Kapında dolaştım yine dün gece

Sessizce ağladım

Duyarsın diye...', 'Hep seni sevdim, seni düşündüm Söyleyemedim bir kere Kızarsın diye; Rüyamda her gece ben seni gördüm Uyanmak istemezdim Gidersin diye; Deniz...', ARRAY['Türk Edebiyatı','Şiir','Barış Karabulut']::text[], 8.5, '{"poet":"Barış Karabulut","poet_slug":"baris-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/denizcan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla Beni', 'hatirla-beni-suleyman-bekcan-nyvd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün dudakları birbirine değmeyenler için

Yazılmış bir şiir okursan eğer

Bilki bu şiir benimdir.

Dudaklarını şiirimin üstünde gezdir; 

Hatırla beni...

Yağmurları gözyaşımla sevdim, bilirsin! 

Düştüğünde bir sonbahar akşamı yola

Kaldırımlarda ayak izlerimi göreceksin

Ta.., uzaklardan baktığın zaman

Hatırla beni...

Bütün insanlar yok olmuş, ortalık ıssız

Bir çöle düşmüş vaha arıyosan eğer,

Bir serap ta olsa; 

Dudaklarına götürdüğün damlacıklarda

Hatırla beni...

İnsanlar nasıl da bilmiyor, beyazın güzel olmadığını

Yıllar yılı kovalıyacaksın, saçında beyazı göreceksin,

Görmeyecek kadar yaşlı olsan bile

Saçının her telinde

Hatırla beni...

Bu resimde nereden çıktı böyle? 

Şu ortadaki kadın yoksa sen misin? 

Ya, bu yanındaki çocukta ne? 

Anladım..! Evlenmişsin...

Sokaktaki bir çocokta olsa

Öylesine ezik ve yeğis,

Okşadığın zaman çocukları

Hatırla beni...

Ben sende bir Süleyman olarak kalabildim.

Sen, sen.., sen dedim ve bittim.

Bilirsin mekanı İmaret derler

Yolun düşerse eğer

Hatırla beni..

                                       1973', 'Birgün dudakları birbirine değmeyenler için Yazılmış bir şiir okursan eğer Bilki bu şiir benimdir. Dudaklarını şiirimin üstünde gezdir;  Hat...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Bekcan']::text[], 8.5, '{"poet":"Süleyman Bekcan","poet_slug":"suleyman-bekcan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hatirla-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-kul-nesimi-9i6hd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cananı benim sevdiğimi can bilir ancak

gönlüm dileğin dünyada canan bilir ancak

bildim hem akl ile hem ilm ile hakkı

şöyle bildim onu ki kuran bilir ancak

ibdal oluben beyliğin eden arifi gör ki

bu saltanatın kadrini sultan bilir ancak

kim aşk denizine dalıp gark olagörsün 

bu aşk denizinin bahrini umman bilir ancak

ey saki getir devr-i ayağın tozu ile sun ki

bu devr- ayağın devrini devran bilir ancak

işret meclisine gelip giden meyler içilir

pinhane çeker şöyle ki şeytan bilir ancak

hiç kimse Nesimi sözünü fehm edebilmez

bu kuş dilidir bunu süleyman bilir ancak', 'cananı benim sevdiğimi can bilir ancak gönlüm dileğin dünyada canan bilir ancak bildim hem akl ile hem ilm ile hakkı şöyle bildim onu ki kur...', ARRAY['Türk Edebiyatı','Şiir','Kul Nesimi']::text[], 8.5, '{"poet":"Kul Nesimi","poet_slug":"kul-nesimi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gazel-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Arzu', 'beklenen-arzu-suleyman-bekcan-vqysi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pembe bir akşam bitiverecek

Hayallerin en pembesi

Yalnızlığın başlayacak upuzun

Karanlıklar, kızıllıklar ötesi.

Derdin en büyüğü çıkıverecek ortaya

Kalbin isyan edecek mutluluğa, arzuya

Bir dikişte içeceksin hüznü, kederi

Benim senin yalnızlığını içtiğim gibi.

Yalnız birşey düşüneceksin;

Hayaller, düşler aynı olacak

Pare pare olacak hep yaşantın

Kızıla dönecek o pembe hatıraların.

Acı duyacaksın, üzüleceksin yaptıklarına

Aşkımı yalnız bırakmak nasılmış anlayacaksın

Saçının her bir telinde beni hatırlayacak

Arzulu akşamlarında beni arayacaksın...', 'Pembe bir akşam bitiverecek Hayallerin en pembesi Yalnızlığın başlayacak upuzun Karanlıklar, kızıllıklar ötesi. Derdin en büyüğü çıkıverecek...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Bekcan']::text[], 8.5, '{"poet":"Süleyman Bekcan","poet_slug":"suleyman-bekcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklenen-arzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-i-hsan-yarenoglu-y3k60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazan yapraklarını döktü aşkımıza.

Hazan,

Karıştırdı yazı bahara.

Harmanladı sevdayı kentlerle,

Aşkın en güzel zamanında,

Aşkı öksüz bıraktı hazan.

Yolları birbirine kattı hazan.

Kentleri de,

Yürekleri de.

En çok sevda kattı,

Karıştırdı harmanladı.

Yanlış yaptı hazan;

Yapraklarla aşkı karıştırdı,

Yaprak diye aşkımızı döktü.

Hazan...', 'Hazan yapraklarını döktü aşkımıza. Hazan, Karıştırdı yazı bahara. Harmanladı sevdayı kentlerle, Aşkın en güzel zamanında, Aşkı öksüz bıraktı...', ARRAY['Türk Edebiyatı','Şiir','İhsan Yarenoğlu']::text[], 8.5, '{"poet":"İhsan Yarenoğlu","poet_slug":"i-hsan-yarenoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-i-hsan-yarenoglu-rc1nk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudağım da yarım kalmış bir sevda türküsü.

Kalbime ve beynime kabul ettiremiyorum.

Kalbim neyse,

En çok beynim inkar ediyor,

Gidişini.

Sevda taşımacılığı yapan otobüs şirketleri,

İsyankar,

Şöförleri de.

Ya! yol;

Uzanıp incelen o uzun yol,

Beş saat süren,

Beşinci saatin sonunda,

Sevdayı müsait bir yerde indiren yol

Mahzun...

İstanbul;

Bitti diye sesleniyor sessizce.

Belki duyulur duyulmaz bir ses:

''Sevda burada oturmuyor artık!''

Taşınmış sevda uzaklara...

Ne derlerİstanbul için;

''Değil güleni, ağlayanı bile bahtiyar.''

Ağlayan,

Ya! ağlayan,

Ankara''ysa!..', 'Dudağım da yarım kalmış bir sevda türküsü. Kalbime ve beynime kabul ettiremiyorum. Kalbim neyse, En çok beynim inkar ediyor, Gidişini. Sevda...', ARRAY['Türk Edebiyatı','Şiir','İhsan Yarenoğlu']::text[], 8.5, '{"poet":"İhsan Yarenoğlu","poet_slug":"i-hsan-yarenoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orhan Velim', 'orhan-velim-ahmet-sahin-soner-yhpp0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizim okulda bir kız vardı 

lisedeydim toydum ozaman

fingirdek leylaydı adı

ben o zaman acemi bir oglan

leyla kancayı takmıstı bana 

ben takmazdım onu ama 

leyla yaptı oyununu

bir gün hocam cagırdı yanına 

bu kıza niye sarkıntılık edersin diye 

ben şaşkın hoca kızgın

yarın velin gelsin dedi bana

gittim evime o aksam 

söyleyemezdşm anama ve bama

sabah oldu aldım velimi yanıma 

doğru gittim, okula 

hoca cagırdı yine yanına 

nerde velin dedi 

Cıkarttım velimi cantamdan koydum masaya 

bune dedi 

Velim dedim Hocam  -  Orhan VELİ''M

Cetvel marifeti buya 

Üç gün okuldan uzaklaştırıldım.

Aldım velimi yanıma 

Bindim yeni gelme bir macar  körüklüsü

ortadan ayrık bir otobüse 

dogru gittim ortaköy''e 

leyla ortaydı 

Ben veli''mi bırakmadım 

Leylada beni

ama ben leylayı hiç sevmedim ki 

yılllar geçti 

Ben veli''m mutluyduk 

Ortaköyde bir barda gitara vuruduk

Bıyığımız terlemiş delikanlı olmuştuk

Canım cekti bir akşam

Emirgana sürüm yolumu

Yanımdaydı veli''m orhan velim 

köprüye ulaştım az sonra 

kadınlara baktım bir gecelik

kadınlar vardı sarıdam esmerden

yanaştım limana yanasır gibi kıyıya 

Kim ola dersiniz 

Evet leyla , fingirdek leyla

Ne leyla bırakmıştı fingirdemeyi 

Nede ben bırakabilmiştim veli'' mi', 'bizim okulda bir kız vardı  lisedeydim toydum ozaman fingirdek leylaydı adı ben o zaman acemi bir oglan leyla kancayı takmıstı bana  ben tak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/orhan-velim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkımız Bizim', 'sarkimiz-bizim-necip-fazil-kisakurek-lrsvf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırılırda bir gün bütün dişliler

Döner şanlı şanlı çarkımız bizim

Gökten bir el yaşlı gözleri siler

Şenlenir evimiz barkımız bizim

Yokuşlar kaybolur çıkarız düze

Kavuşuruz sonu gelmez gündüze

Sapan taşlarının yanında füze

Başka alemlerle farkımız bizim

Kurtulur dil, tarih, ahlak ve iman

Görürler nasılmış, neymiş kahraman

Yer ve gök su vermem dediği zaman

Her tarlayı sular arkımız bizim 

Gideriz nur yolu izde gideriz

Taş bağırda, sular dizde gideriz

Bir gün akşam olur bizde gideriz

Kalır dudaklarda şarkımız bizim', 'Kırılırda bir gün bütün dişliler Döner şanlı şanlı çarkımız bizim Gökten bir el yaşlı gözleri siler Şenlenir evimiz barkımız bizim Yokuşlar ...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarkimiz-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Gözlü', 'isik-gozlu-eflatun-xwugv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyurken yüzünü seyredip yanımda,

Tanrının büyüklüğünü görmüşüm.

Gri gümüş telli saçların avuçlarımda,

Kendimi dünyanın en zengini saymışım.

Sen ey ışık gözlü sevgili,

Senden sonrasına,

Ölümü yazmışım...', 'Uyurken yüzünü seyredip yanımda, Tanrının büyüklüğünü görmüşüm. Gri gümüş telli saçların avuçlarımda, Kendimi dünyanın en zengini saymışım. ...', ARRAY['Türk Edebiyatı','Şiir','Eflatun']::text[], 8.5, '{"poet":"Eflatun","poet_slug":"eflatun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/isik-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Sokak', 'sokak-sokak-gokhan-ozsoy-ybo7q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sokak sokak koşarken

ardından bir geçmişin

geçmişi gelecekle toplayıp

geleceği geçmiş yapmak için', 'sokak sokak koşarken ardından bir geçmişin geçmişi gelecekle toplayıp geleceği geçmiş yapmak için...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özsoy']::text[], 8.5, '{"poet":"Gökhan Özsoy","poet_slug":"gokhan-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sokak-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Çiçeği', 'su-cicegi-gokhan-ozsoy-6z5nd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'su çiçeğim,

şu küçük

bir türlü yanmayan mumların

ne işe yaradığını anlayamıyorum

derdin sen

eskiden

şimdi ben

o küçük

bir türlü yanmayan mumlara

her baktığımda

seni hatırlıyorum

ince bir sızıyla

ve biliyorum

artık şu küçük

bir türlü yanmayan mumların

ne işe yaradığını...', 'su çiçeğim, şu küçük bir türlü yanmayan mumların ne işe yaradığını anlayamıyorum derdin sen eskiden şimdi ben o küçük bir türlü yanmayan mum...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özsoy']::text[], 8.5, '{"poet":"Gökhan Özsoy","poet_slug":"gokhan-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ağzında', 'yol-agzinda-eflatun-b4jps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki ürkek, kırılgan insandı onlar.

Bir yolun ağzında buluştular.

Çıplak bedenlerinde geçmişin yara izleri,

Çuvaldan bir örtüye sarındılar.

Ve baktılar birbirlerine,

Baktılar ürkerek kırılmaktan.

Biri çıkarsa örtülerini ,

Diğeri de çıkaracak.

Biri bıraksa kalkanlarını,

Diğeri de bırakacak.

Öylece beklediler birbirlerini,

Beklediler ürkerek kımıldamadan.

İlk kadın cesaretlendi.

Sıyırdı azıcık örtüsünü,

Sol omuz başı göründü.

Adam uzattı elini,

Adamın eli çeliktendi.

44 yıllık uğraşının sonucu,

El yapımı çelikten.

Ve soğuktu.

Adam sıcağı unutmuştu.

Tir tir titredi yüreği kadının.

Geçmişin hayaletleriyle savaştı bir süre

Ve örtündü ürkerek yeniden.

Bulabildiği ne varsa, çer, çöp, taş, diken,

Kat kat örtündü eskisinden beter.

İki ürkek, kırılgan insandı onlar.

Bir yolun ağzında ayrıldılar.

Kadın çirkindi artık,

Adamsa hala çelikten.', 'İki ürkek, kırılgan insandı onlar. Bir yolun ağzında buluştular. Çıplak bedenlerinde geçmişin yara izleri, Çuvaldan bir örtüye sarındılar. V...', ARRAY['Türk Edebiyatı','Şiir','Eflatun']::text[], 8.5, '{"poet":"Eflatun","poet_slug":"eflatun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yol-agzinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-ezel-gulselim-59ycq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ömür hasretle bekle

Herkes kesse de umudunu sen kesme

İhanetle, korkuyla, karasevdayla bekle

Gelmeyeceğim doğsa da içine

İnatla, tutkuyla, ısrarla bekle...

Yüreğindeki sesi dinle ve asla vazgeçme...

Bekleme ateşi yeşersin içinde,

Her gün yeniden..

Sen dirensen de...

Sen vazgeçsen de...

Vazgeçemesin,

Umut kesmesin,

Senden içeri..

Kahretsen de,

Terketsen de..

Ruhun unutmasın beni..

Başka bedenle dönsen de

Hasret ışısın gözünde..

Bekle..bekle..bekle..

Herkes umudu kesse de 

Sen kesme...', 'Bir ömür hasretle bekle Herkes kesse de umudunu sen kesme İhanetle, korkuyla, karasevdayla bekle Gelmeyeceğim doğsa da içine İnatla, tutkuyl...', ARRAY['Türk Edebiyatı','Şiir','Ezel Gülselim']::text[], 8.5, '{"poet":"Ezel Gülselim","poet_slug":"ezel-gulselim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Bana Ait Birşeyler Var', 'sende-bana-ait-birseyler-var-elif-erdem-ilkgb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende bana ait bir şeyler var...

Sana ait özlemlerim var...

Sana ait özlemleri,

Bir günün aydınlığında 

Önce ruhuma çöken bir sis misali,

Sana biraz daha yaklaşıp hayallerinden medet umarak,

Karanlık güneşlerim diye,ama yine de

Yanlızca sana adandıkları için tapınırcasına sevdim.

Gidişinin yanlızlığında bir ince sızı gibi yağmur yağıyordu

Sanki,gökyüzü dile gelmiş bana kendimi anlatıyordu

Yereğim de ayaklandı sanki; gitti seninle uzaklara

Şimdi içim bomboş..

O kocaman boşluğu özlemlerinle doldurdum

Hasretinle süsledim; anılarımızı biriktirdim orada

Sende bana ait birşeyler var...

Aşkım sende kaldı; ümitlerim sende

Sevgilerim de vardı seninle giden kalbimde

Canımı aldın bir de; koparıp gittin taa o en uzaklara...

Ruhu olmayan bir beden,

Özlem, hasret vekederlerini

Anılarımıza eşlik etsin diye bıraktın

Sende bana ait birşeyler var...

Asla sökemeyeceğim üzerinden,

Teninle bütünleşen ve yüreğine mühürlenen,

Gözlerinde hapsedilen

O hep bildik ve yanlız sana ait

Bir kalbim var sende...

Sıcak nefeslerimde,ılık gözyaşlarımın ıslattığı her hecede

Hissiyatımın en yoğun söyleyişlerinde

Yine bu gece farkettim ki

Onsuz yaşayamadığım,nefes alamadığım

Bir canım var sende...', 'Sende bana ait bir şeyler var... Sana ait özlemlerim var... Sana ait özlemleri, Bir günün aydınlığında  Önce ruhuma çöken bir sis misali, Sa...', ARRAY['Türk Edebiyatı','Şiir','Elif Erdem']::text[], 8.5, '{"poet":"Elif Erdem","poet_slug":"elif-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sende-bana-ait-birseyler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Böyle Kalsın', 'hep-boyle-kalsin-i-brahim-torun-z7xzv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cümlelerle dans ettim

Dilimden dökülen aşk

           sözcükleri oldular

           senin için.

İçime doğan sevgi oldular

           benim için.

Kulaklarımda çınlayan

           şarkı oldular,

           ikimizi anlatan.

Üstümüze yağan sevgi oldular

           bizi ıslatan.

Ormanda ağaç, kırlarda

           çiçek oldular....

Hiç solmayan....', 'Cümlelerle dans ettim Dilimden dökülen aşk            sözcükleri oldular            senin için. İçime doğan sevgi oldular            benim i...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hep-boyle-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Üşümedin Bende', 'bir-sen-usumedin-bende-erol-karadas-7fjdx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

Kışlar daha soğuk geçerdi, üstelik

bundan fazla yağardı kar.

Boyum ufak yaşım küçüktü

bir adamdan; yüreğimse

bir adamdan daha büyük

Sıvasız bir duvar dibinde

Çekingen ılıksı bir güneş

Ve sevdalardan

Gözleri kamaşan bir yürek.

Uzun sürerdi kışlar, üstelik

daha üşütürdü rüzgâr.

Beyaz.. mavi.. Soğuktan

ve ayazdan dokunuşlar.

Ağaçlar, kuşlar üşürdü

yıldızlar bile titrerdi de

bir sen üşümezdin bende.

          II

Şimdiyse ''yalnız şehir''de

geçiyor kışlar, üstelik

boyum da bir adamınki kadar,

ama yağmıyor eskisi gibi kar.

Ne beyaz.. ne mavi..

ne de soğuk dokunuşlar.

Ve... ''yalnız şehir''den

küskün ayrılıyor rüzgâr.

Eski kışlardan birinde hâlâ

senli yüreğim..

Sıvasız duvar dibinde..

Bir sen üşümedin bende.', 'I Kışlar daha soğuk geçerdi, üstelik bundan fazla yağardı kar. Boyum ufak yaşım küçüktü bir adamdan; yüreğimse bir adamdan daha büyük Sıvası...', ARRAY['Türk Edebiyatı','Şiir','Erol Karadaş']::text[], 8.5, '{"poet":"Erol Karadaş","poet_slug":"erol-karadas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-sen-usumedin-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-absolute-evil-gv6ua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gece bir yıldız tut gökyüzünden,

Ben, seni o yıldızda seveceğim.

Gamzelerinden yaşlar süzülürken,

Gözlerinin pırıltısını o yıldızda göreceğim.

Her gece bir yıldız tut gökyüzünden,

Enaz senin kadar asi, senin kadar hırçın,

Şarkılar fısıldayan rüzgar ben olacağım,

Omuzlarının üstünde dalgalanırken saçın', 'Her gece bir yıldız tut gökyüzünden, Ben, seni o yıldızda seveceğim. Gamzelerinden yaşlar süzülürken, Gözlerinin pırıltısını o yıldızda göre...', ARRAY['Türk Edebiyatı','Şiir','Absolute Evil']::text[], 8.5, '{"poet":"Absolute Evil","poet_slug":"absolute-evil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yildiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Törpüsü', 'omur-torpusu-bilal-eyidogan-y3dw1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıktın han evimi viran eyledin.

Viran evlerimin garip bekçisi.

Ben mi çilekeşim, yoksa sen misin?

Bitmez acıların tek emekçisi.

Eskiden şen şakrak söylerdi dilin

Şimdi dilindeki acı türküsü

Çekmediğin türü kalmadı derdin

Hem öyle bir dert ki binbir türlüsü..

Söyle ne getirdin bana birtanem?

Yoksul soframızdan bir bardak su mu?

Annem ağlıyor mu yine birtanem?

Yoksa yüzündeki abdest suyu mu?

Tükettin ömrümü, tükettin beni

Çilekeş ömrümün ömür törpüsü

Ölünce kefene sarmayın beni

Örtsün gecelerin siyah örtüsü...', 'Yıktın han evimi viran eyledin. Viran evlerimin garip bekçisi. Ben mi çilekeşim, yoksa sen misin? Bitmez acıların tek emekçisi. Eskiden şen ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Eyidoğan']::text[], 8.5, '{"poet":"Bilal Eyidoğan","poet_slug":"bilal-eyidogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omur-torpusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Değil', 'kayip-degil-riza-aslan-xutj2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kayıp değil yaşanan yıllar

yaşanan her şeyin bir anlamı var

kor alevler içinde yanan yürekler

küllenecek

nice acılar daha eklenecek üzerine

nice anlık hazlar

yine sözler verilecek

unutulacağı bilinerek

planlar yapılacak geleceğe dair

isimler konulacak çocuklara

oturulacak evin yağlı boya resmi...

anlamsız gibi gelecek herşey

bir sabah uyandığında yine

bir boşlukta hissedeceksin kendini

seni çepe çevre sarmalayan

yalnızlığın merhaba diyecek sana

yine o çekecek en çekilmez acılarını

ağlayacaksın...

yumruklar savuracaksın yıpranmış benliğine

yine bir sabah uyandığında 

o sıcaklığı hissedemeyeceksin

o derin nefes alışları duyamıyacaksın

elini attığında dokunmak için

yalnızlığın dolanacak eline

çaresizliğin 

yine vuracak beklemediğin bir anda

ve anlayacaksın

neler yaşarsan yaşa

sen yalnızsın

19-10-2000', 'kayıp değil yaşanan yıllar yaşanan her şeyin bir anlamı var kor alevler içinde yanan yürekler küllenecek nice acılar daha eklenecek üzerine ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kayip-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Buralardan', 'gidersen-buralardan-mujde-altekin-nqbpx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşünme Ayrılığı

Sil Çıkar Aklından

Talan Olur Yüreğim

Gidersen Buralardan

Yol Alır Giderim

Ferman Dinlemem Durmam

Toprak Olur Meskenim

Gidersen Buralardan

Matem Tutar Yüreğim

Bağlar Kara Yazmalar

Yosun Tutar Bedenim

Alır Beni Karalar

Oflar Düşmez Dilimden 

Yüreğime Kor Damlar

Meftun Olurum Derde

Gidersen Buralardan.', 'Düşünme Ayrılığı Sil Çıkar Aklından Talan Olur Yüreğim Gidersen Buralardan Yol Alır Giderim Ferman Dinlemem Durmam Toprak Olur Meskenim Gide...', ARRAY['Türk Edebiyatı','Şiir','Müjde Altekin']::text[], 8.5, '{"poet":"Müjde Altekin","poet_slug":"mujde-altekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidersen-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayburt', 'bayburt-celal-altinay-ygghc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gizli kalmış güzelliklerin diyarı

Cennet bahçesine benzer ilkbaharı yazı 

Dedem korkut zihni ağlar baba  şair zihninin vatanı

Sevginin  sadesi  sendedir Bayburt 

            

                Senin sevginle aşk besledim

                Ruhumda sevgini gizledim 

                Kır çiçeğinin  kokusunu özledim

                Sevginin sadesi  sendedir Bayburt

Can içinde can beslenir 

Bülbüller güzel kalenden seslenir

Bayburt’ta gül karda beslenir 

Sevginin sadesi sendedir Bayburt

                 Sevgi  ibadettir  seni sevmeli 

                 Ömründe insan bir kere seni görmeli 

                 Kırk  paharlarından su içmeli 

                 Sevginin  sadesi sendedir Bayburt 

  

İsmin bir nefes gibi  düşmez dilimden

Sığdıramam seni  gök kubbeye neden

Ecdadım sende yatıyor sana nasıl  eğilmesem

Sevginin  sadesi sendedir Bayburt         

	1977-2000', 'Gizli kalmış güzelliklerin diyarı Cennet bahçesine benzer ilkbaharı yazı  Dedem korkut zihni ağlar baba  şair zihninin vatanı Sevginin  sade...', ARRAY['Türk Edebiyatı','Şiir','Celal Altınay']::text[], 8.5, '{"poet":"Celal Altınay","poet_slug":"celal-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bayburt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak İsterdim', 'aglamak-i-sterdim-levent-cokyuruyen-21ryp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamak isterdim sana,

Sensiz geçen şu yalnız aşkıma,

Acısız günümün olmadığı şu dünyaya,

Hıçkırarak ağlamak isterdim.

Ağlamak isterdim ömrümce,

Sevgiyle bakarken resmine sessizce,

İçimle pençeleşen dudaklarımı unutarak,

Hıçkırarak ağlamak isterdim.

Sensizliğime yanarken,

Şu kalbim hala seni anarken,

Güzel gözlerine son bir defa bakarken,

Hıçkırarak ağlamak isterdim.', 'Ağlamak isterdim sana, Sensiz geçen şu yalnız aşkıma, Acısız günümün olmadığı şu dünyaya, Hıçkırarak ağlamak isterdim. Ağlamak isterdim ömrü...', ARRAY['Türk Edebiyatı','Şiir','Levent Çokyürüyen']::text[], 8.5, '{"poet":"Levent Çokyürüyen","poet_slug":"levent-cokyuruyen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglamak-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Konulamayan', 'adi-konulamayan-riza-aslan-t35bo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adı konul(a)mayan

bir öyküydü bizimkisi

adı yoktu olamazdı

20-10-2000', 'adı konul(a)mayan bir öyküydü bizimkisi adı yoktu olamazdı 20-10-2000...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adi-konulamayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galata Köprüsü', 'galata-koprusu-ahmet-sahin-soner-rgyb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'El alemin acemi aşıkları onun kollarında dal budak saldı 

İlk öpücüklerin heyecanını üçüncü kişi olarak yaşadı , 

Bakire kadın olmaya karar verdi , acemi oğlan erkek

Sırlar pas tuttu kadının yüreğinde 

Anılarını yazmaya zaman bulamadı oğlan 

Beyaz bir martı can verdi dubalarda 

Bir balık takıldı oltaya mavnalar da 

Dilenciler , şarapçılar , balıkçılar mesken edindi ihtiyar ayaklarını

Bir kolunu halice saldı ,

Diğer kolu kaldı boğazın serin sularında ,

Aşık oldum ona , - Sarhoştum adam akıllı 

Yağmur yağıyordu , sisli bir İstanbul  akşamıydı 

Sandalım serin sularda , 

Bir yanımda kız kulesi , bir yanımda galata 

                                     

 10 Ekim 1993', 'El alemin acemi aşıkları onun kollarında dal budak saldı  İlk öpücüklerin heyecanını üçüncü kişi olarak yaşadı ,  Bakire kadın olmaya karar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/galata-koprusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Uğraş mı Duyguları Komik Bahanelere Vurmak?', 'bir-ugras-mi-duygulari-komik-bahanelere-vurmak-ceren-gulec-3rm7n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir uğraş mı duyguları komik bahanelere vurmak?

Oysa yalan yok o çığlıklarda...

Yaşanası değil hissedilenler,

Belli...

Ama yok işte karşı çıkış...

Saçmalıyorum...

Aramızdaki görülmeyen mesafeleri hiçe sayarak

Buğulu camları suçluyorum yüzünü göstermiyorlar diye...

Bir hayal, diğerleri gibi...

Bir eğlence sanki siyah zamanları aydınlatmak için...

Bir oyun, bir merak...

Ama sevda değil...', 'Bir uğraş mı duyguları komik bahanelere vurmak? Oysa yalan yok o çığlıklarda... Yaşanası değil hissedilenler, Belli... Ama yok işte karşı çı...', ARRAY['Türk Edebiyatı','Şiir','Ceren Güleç']::text[], 8.5, '{"poet":"Ceren Güleç","poet_slug":"ceren-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-ugras-mi-duygulari-komik-bahanelere-vurmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilim', 'canim-sevgilim-osman-baykal-orvo6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğanın yeşili gözlerine bezenmiş,

Elmanın,kirazın,kanın kırmızısı dudaklarına

Pamuğun yumuşaklığı ise o sımsıcak bedeninde saklı yarim,

Sen hayatımın en değerli hediyesi ,yüreğimin fani bekçisi

Gönül pınarım,aşk romanım,duygu demedimsin,

Sevgin öyle yüce,öyle büyük ki

Gökyüzündeki yıldızlar yazmaya,denizin mavisi boyamaya yetmez

Çünkü senin samimi duyguların,cana yakınlığın,şefkatin

Ve benim olan sevginle ömrüme ömür,dermanıma dermansın

Sen deli yüreğimin tek sahibi ve ayrılmaz parçasısın

Gönül pınarından akan sevgi dolu,aşk dolu ellerini öperken sıcaklığınla

Sensiz geçen saatlerin ızdırabını duyarım

Gözlerimde beni,dudaklarında beni ararım  o sevgi dolu bedeninde 

Umutlarım sen ,arzularım hep sen,hayatımın anlamı yine sen

Çünkü deli dolu beni seven ,bana bağlanan yine kalbimdeki sen

Ben seni ilk sevdim,ben seni son sevdim,çünkü ben sana senin olan gönlümü verdim.', 'Doğanın yeşili gözlerine bezenmiş, Elmanın,kirazın,kanın kırmızısı dudaklarına Pamuğun yumuşaklığı ise o sımsıcak bedeninde saklı yarim, Sen...', ARRAY['Türk Edebiyatı','Şiir','Osman Baykal']::text[], 8.5, '{"poet":"Osman Baykal","poet_slug":"osman-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa...', 'oysa-ceren-gulec-l81qv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanları silmişim bazı anlarda.

Yürek, istemsiz çırpınışlara maruz kalmış.

Daha önce fark edilmemiş dakikalar içinde yaşıyorum.

Bazı anlar var ki, yitip gitmiş biz fark etmeden.

Dakikalar kısa, saniyeler uzun...

Zamanlar anlamsız, zamanlar boş...

Oysa bizim de zamanlarımız olabilirdi...

Kelimeler, harfler arasına gizlenmiş bazı duygular.

Notalar arasında yitip gitmiş bir şeyler.

Hıçkırıklar tıkanıyor derinlerde bir yerde.

Şarkılar kazınıyor düşüncenin esiri beyinlere.

Şarkılar söyleniyor yiten umutları geri getirmek için.

Şarkılar dinleniyor gidenlerin ardından.

Oysa bizim de şarkılarımız olabilirdi...

Sokaklarda umut dolu çocuk çığlıkları...

Gözler parıltılı...

Yürekleri kaplamış coşular...

Dillerinde sözlüğe alınmamış kelimeler...

Çocuklar yalınayak, çocuklar umut dolu...

Çocuklar ki, aracısı nice sevgilerin...

Oysa bizim de çocuklarımız olabilirdi..

Bulutlar kümelenmiş birbiri ardına.

Yağmur yağıyor sevgileri ıslatmak için.

Kağıt gemiler yüzüyor kaldırım kenarlarında.

Hiç yolcusu yok...

Kağıt gemiler süzülüyor derin maviliklere doğru...

Kağıt gemiler ki, aydınlığın sessiz adımları...

Oysa bizim de kağıt gemilerimiz olabilirdi...

Hazan, beraberinde hüzünleri de dağıtmış sokaklara.

Ayrılan ellerde parçalanmış yürekler...

Kimi yüreklerde sevgi tohumları...

Birbirine verilen sözler...

Ben... Bilinmez sevgilerin camlar arkasındaki temsilcisi...

Sen... Yabancı umutların sahte sahibi...

Oysa biz, birbirimizin olabilirdik...

Ama sen istemedin...

                                       [email protected]', 'Zamanları silmişim bazı anlarda. Yürek, istemsiz çırpınışlara maruz kalmış. Daha önce fark edilmemiş dakikalar içinde yaşıyorum. Bazı anlar ...', ARRAY['Türk Edebiyatı','Şiir','Ceren Güleç']::text[], 8.5, '{"poet":"Ceren Güleç","poet_slug":"ceren-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/oysa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymak İstersin Dİye', 'duymak-i-stersin-di-ye-ahmet-sahin-soner-pz4rm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani bazen sesini duymak istersin

Bazen yasamak istersin ya karanlığı

Umarsızca duymak istersin ya sessizliğin sesini

Tatmak istersin hani acı olanı 

Veya tadı henüz belirmemiş olanı

Duymak istersin bir cocuğun cığlığını 

Hani bir bilinmez sonrasında

Belirginleştirirsin ya

Sadeleştirisin ya hayatı.

Yaşamak istersin ya hani umarsızca 

İşte öyle bişeydi seni aramam

Nedenini bilmeksizin belkide sırf sesin için 

Senin için belki , yaşamak istediğim için

Hani sıcak bir süt içersin sabahları

İçini ısıtır ya glikozun tadı.

Bir kaşık baldan almışındır,

Bir tutam güneşten

Bir bardak sudan almışındır,

yüzündeki tebessümü 

Süt kadar güneş kadar sıcak su kadar serin

Seni aramamı gerektiren tebessümü

Seni aramamı sen istedin 

Sinyallerini gönderdin yüreğinden

Ben sadece sana '' Alo '' dedim

Hani bazen duymak istersin ya 

Sesini duymak sebebimdi ya 

Seni yaşamak ihitiyacımdı ya

Hani  sen öğretmiştin canım derken

Hani sen seslenmiştin gece,

ay sabaha karışırken

Sebebim sendin

hani  sende duymak istersin diye', 'Hani bazen sesini duymak istersin Bazen yasamak istersin ya karanlığı Umarsızca duymak istersin ya sessizliğin sesini Tatmak istersin hani a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/duymak-istersin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-serkan-cekirge-m9wah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kusursuz sevgiler hayal etmiştim,

sensiz gecelerde sana dair.

Sana dair mutluluklar;

Senli sevimeler.

Anlayamadıgım bu hayata 

İnadına saygısızca!

Senli hayallerim vardı

Sabaha karşı kızıl guneşten önce...

Sensiz aşlar sana dair 3 kelimelik kadınlar?

Seni aradım ruhu kahbe şarap gibi kadınlarda.

Anlayamadıgım bu hayata 

İnadına saygısızca!

Ne ben o zamansız zemheriye ruhumu verdim!

Ne senli hayallere kavuşabildim,

Şairin dedigi gibi.

Bi zaman bı yerde buluşuruz yolu yok bunun...

Anlayamadıgım hayata 

İnadına saygısızca.', 'Kusursuz sevgiler hayal etmiştim, sensiz gecelerde sana dair. Sana dair mutluluklar; Senli sevimeler. Anlayamadıgım bu hayata  İnadına saygı...', ARRAY['Türk Edebiyatı','Şiir','Serkan Çekirge']::text[], 8.5, '{"poet":"Serkan Çekirge","poet_slug":"serkan-cekirge","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sana-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-elif-gultekin-uo88h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmek parayla olamaz

Sevmek gönülle olur

Sevmek bir gülle olamaz

Sevmek gönülle olur

İki insan sevdi mi

Bir gönül olur', 'Sevmek parayla olamaz Sevmek gönülle olur Sevmek bir gülle olamaz Sevmek gönülle olur İki insan sevdi mi Bir gönül olur...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevmek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Barışı', 'gunesin-barisi-elif-gultekin-xwkdv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin batışı beni hep sevindirir

Çünkü yarın doğacağına eminim

Ve bilirim ki yarın daha güzel umutlar

Yepyeni bir hayat getirecek bize güneş

Çok  uzak diyarlardan

Güneş her batışında 

Bir yerlerde başka umutlarla doğuyor nasıl olsa

Ve güneş her doğuşunda bir yerlerde batıyor

İşte böyle bir dünyadayız

Birileri ölürken bir yerlerde

Birileri doğuyor

Boşver be kardeş

Hayat devam ediyor', 'Güneşin batışı beni hep sevindirir Çünkü yarın doğacağına eminim Ve bilirim ki yarın daha güzel umutlar Yepyeni bir hayat getirecek bize gün...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunesin-barisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-elif-gultekin-8yson', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir denize benzer hayatımız ,

Bazen tek düze, bazen kızgın

Ama hep umut dolu değil midir deniz?

Balıkçıların ve balıkların umudu,

 Özgürlüğün simgesi

Deniz sırlarla doludur

Gizemli ve çekici

Ve bir o kadar da ölümcül

Neden hep denizin ardını çekici buluruz

Ve neden hep orada güzel bir hayat olduğunu düşünüp avunuruz,

Deniz ölümcülde olsa 

Kimi zaman atlayıvermek isteriz içine.

Ölmek istemesek bile...

Deniz sonsuz

Deniz umut

Deniz neşe

Deniz güç

Deniz barış

Ve kimi zaman ölümdür bizim için deniz

Ölmek istemesek bile...', 'Bir denize benzer hayatımız , Bazen tek düze, bazen kızgın Ama hep umut dolu değil midir deniz? Balıkçıların ve balıkların umudu,  Özgürlüğü...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatacak Sana', 'anlatacak-sana-ruya-ersoy-37wc6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu mektup anlatacak sana

Her gece sevgini ektiğimi

Sadece sensizliği biçtiğimi

Bu mektup anlatacak sana 

Sensiz gitmediğim o sahile gittiğimi

Hatıralarla avunamadığımı

Anlatacak bu mektup sana

Hatırladığın değilmi o günleri

Sen başkasının  kollarındasın şimdi

O güzel gözlerin artık ona bakıyor 

O güzel dudakların artık onu öpüyor

Her gece sevgini ektiğim bu kalbe

Artık mezar taşıma dikiyorum', 'Bu mektup anlatacak sana Her gece sevgini ektiğimi Sadece sensizliği biçtiğimi Bu mektup anlatacak sana  Sensiz gitmediğim o sahile gittiğim...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlatacak-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlemeye Mecbursun', 'dinlemeye-mecbursun-ruya-ersoy-ojc1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Madem derdimi sordun sevgilim

Beni dinlemeye mecbursun

Neden mi? meyhane köşelerindeyim

Neden mi?içkiler dostum benim

Nasıl toprak yağmur isterse

Bende seni istiyorum sevgilim

İçkilerde ,meyhane köşelerinde aradığım sensin

Aradım durmadan,seni aradım,durdum

Yine bulamadım sevgilim seni

Gözyaşlarım aka aka bitmez oldu

Ben bittim, tükendim,yıkıldım sevgilim

Aramaktan sonra bulamamaktan yoruldum

Gel son bir defa görmek gereksede seni

Beni görmek istemesende gel

Derdimin istediğimin sen olduğunu

Avere dolaştığım bu yollarda sevdiğimi,söyleyeyim', 'Madem derdimi sordun sevgilim Beni dinlemeye mecbursun Neden mi? meyhane köşelerindeyim Neden mi?içkiler dostum benim Nasıl toprak yağmur is...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dinlemeye-mecbursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Öpüştü o', 'bir-opustu-o-ruya-ersoy-xeyuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dudaklarda beliren bir öpüştü o

Ürkek bakışlar,tatlı kıpırdılardı

O duygu ile sevgilerini birleştiren

O duyguydu aşkı en güzel anlatan

Sevmenin güzel olduğunu söyleyen

Ürkek korkak kızın bakışlarıydı o

Bir pırıltı vardı o kara gözlerinde

En sonunda oda gerçekten sevmişti

Anlatamadığı sevgisini ifade etmişti

Sevdiğini belirtmek ne güzel demişti

Dudaklarındaki tebessüm anlatmıştı

Sevginin güzel bir duygu olduğunu

Anlatmıştı bir öpüşte o', 'Dudaklarda beliren bir öpüştü o Ürkek bakışlar,tatlı kıpırdılardı O duygu ile sevgilerini birleştiren O duyguydu aşkı en güzel anlatan Sevme...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-opustu-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lütfen Söyle', 'lutfen-soyle-ruya-ersoy-ibopm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana mutlu haberi vermeme izin bile vermedin

Sana artık evlenebiliriz demek için gelmiştim

İzin vermedin anlamak istemedin beni

Gözyaşlarımla beni tek başıma bıraktın

O anda dünya başıma yıkıldı  ölmek istedim

Bir sigara yaktım bir parça unutturur diye

Birden kadehlerle arkadaşlık kurdum

Onlara anlattım derdimi,üzüntümü

Ölemedim, ölmek istemedim çünkü

Ayrılığımızın sebebini öğrenemedim

Mezar taşıma ne yazılacağını bilemedim', 'Sana mutlu haberi vermeme izin bile vermedin Sana artık evlenebiliriz demek için gelmiştim İzin vermedin anlamak istemedin beni Gözyaşlarıml...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/lutfen-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Cahili', 'ask-cahili-ruya-ersoy-nb1gt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tatlı şirin küçük bir kızdı o

Mutluluk,sevgi saçıyordu

Yıllar geçti o şirin kız büyüdü

Çok güzel bir kız olmuştu

Onda tek eksik olan,mutluluktu

Küçük kız neden mutsuzdu

Yoksa dünyanın ağırlığını kaldıramadımı

Artık gülmüyor mutluluk saçmıyordu

Anladım, aşk onu hüzünlendirmişti

Ona mutluluk yerine mutsuzluk getirmişti

Tek sorunu yanlış kişiyi sevmekti

O da aşk selinin pençelerinde can verdi

O küçük kız aşk cahilinden başka birisi değildi', 'Tatlı şirin küçük bir kızdı o Mutluluk,sevgi saçıyordu Yıllar geçti o şirin kız büyüdü Çok güzel bir kız olmuştu Onda tek eksik olan,mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-cahili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bir Kadın', 'o-bir-kadin-ruya-ersoy-1jj37', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kız tanıdım mutlu

Pembe bulutlar üstünde umutlu

Evlilik seline kapıldı,tek istediği

Mutlu,güzel ömür boyu bir evlilikti

Gitti almanyaya hayallerle dolu

Bir sene sonra gözleri yaşlı geldi

Kalbi kırık döndü bir kadın olarak

Tek suçu saf ve yürekli olmak

Bu kız artık hayatın olgunlaştırdığı

Bütün kötü yanlarını gösterdiği

Suçu sevmek,inanmak olan bir kadın

Geçmişte hayellerle umutlarla yaşayan kız

Bugün hüzünlü,kederli,kalbi kırık bir kadın', 'Bir kız tanıdım mutlu Pembe bulutlar üstünde umutlu Evlilik seline kapıldı,tek istediği Mutlu,güzel ömür boyu bir evlilikti Gitti almanyaya ...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/o-bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttun mu Sevgilim', 'unuttun-mu-sevgilim-ruya-ersoy-wxua1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutacaksın dedin geçecek zamanla

Sen unuttun mu sevgilim o güzel günleri

Elveda derken yanaklardan dökülen yaşlar

Çiçekleri yaşatırken beni öldürdü

Ben unutamadım kalbime bir hançer gibi saplandı

Yarası geçti ama izi hala kalbimde kaldı

Tekrar soruyorum sen unuttun mu  sevgilim

Yıllar geçti yine aynı duygularım

Yıllar geçti yine aynı hatıralarım

Sevgileri,aşkları,tatlı günleri unutamadım

Sevmeyi tatmak,hayata başlamaktır

Bunu öğrenmek hayatta tek mutluluktur

Tekrar soruyorum sen unuttun mu sevgilim', 'Unutacaksın dedin geçecek zamanla Sen unuttun mu sevgilim o güzel günleri Elveda derken yanaklardan dökülen yaşlar Çiçekleri yaşatırken beni...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unuttun-mu-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ruya-ersoy-xfjsv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece yine ürperdim,uyandım

Sigarımı aldım ve içmeye başladım

Beni ürperten senin sevgindi

Sevgilim sonumuz ne olacak bilmiyorum

Dumanlar odamı kaplarken bir hüzün çöktü

Gözlerimden akan yaşlar sel gibi aktı gitti

En güzel günlerimi alıp bırakma beni

Açmışım ellerimi Allah''a dua ediyorum

Sevgilimi benden ayırma,ayrılık istemiyorum

Sonra düşündüm bu kuruntu neden

Her sevgide acı,keder,mutsuzluk aramak neden

Öyleyse artık ürpermeden rahat,mutlu uyuyabilirim

Sevgi dolu bir kalple yaşayabilirim', 'Bir gece yine ürperdim,uyandım Sigarımı aldım ve içmeye başladım Beni ürperten senin sevgindi Sevgilim sonumuz ne olacak bilmiyorum Dumanlar...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korku-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayanın Seveni', 'anlayanin-seveni-ruya-ersoy-vvhta', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla yaş gözlerinden süzüldü

O güzel   yüzünde bir hüzün büründü

Neydi onun suçu neden böyle oldu

Mutluluk ona çok mu göründü

Bir kerecikte bu duyguyu o tatsa

Buna izin verinde bu hüzün son bulsa

Sevenleri ayırmak  isteyenler

Kendi sevenlerinden bulsunlar

Anlasınlar sevmenin,sevilmenin ne kadar güzel olduğunu

Anlasınlar ayrılığın,hasretin,ne kadar hüzünlü olduğunu', 'Bir damla yaş gözlerinden süzüldü O güzel   yüzünde bir hüzün büründü Neydi onun suçu neden böyle oldu Mutluluk ona çok mu göründü Bir kerec...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlayanin-seveni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yazar', 'ne-yazar-atabay-guveloglu-67qjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Özledim''demişsin dostun birine,

Yıllar sonra ateş düşmüş gönlüne.

Ak dikenler bitti gülün yerine

Özlesen ne yazaar,gelsen ne yazar?

Zaman akıp gitmiş,durmak bilmiyor,

Dünü bugün yapmak elden gelmiyor.

Mızrabım kırılmış,sazım çalmıyor

Özlesen ne yazaar,gelsen ne yazar?

Ruhumu sarsan o fırtına dinmiş,

Deli dolu gönlüm uslanıp sinmiş.

İçimdeki volkan küllenip sönmüş

Özlesen ne yazaar,gelsen ne yazar?

Belki zor olacak beni tanıman,

Sıcaklık duymazsın öptüğün zaman.

O çılgın arzular çıktı aklımdan

Özlesen ne yazaar,gelsen ne yazar?

Kalmadı o neş''em,candan gülüşler,

yok artık bildiğin içten bakışlar.

Gözümde gözlükler,kalpte dikişler

Özlesen ne yazaar,gelsen ne yazar.

Her güzellik vaktindeymiş sevdiğim,

İki dünya yeter bana verdiğin.

Serap imiş,rüya imiş gördüğüm

Özlesen ne yazaar,gelsen ne yazar?', '''Özledim''demişsin dostun birine, Yıllar sonra ateş düşmüş gönlüne. Ak dikenler bitti gülün yerine Özlesen ne yazaar,gelsen ne yazar? Zaman a...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maziye Gözyaşları', 'maziye-gozyaslari-atabay-guveloglu-fyyik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemini çekiyorum çocukluk yıllarımın,

Mevsim daima bahar,berraktı sular her zaman.

Çember,topaç çevirmekten yorulan kollarımın

Dermanını verirdi bir öpüşüyle anam.

Gözlükleri yoktu babamın o zaman,

Beyaz değildi şakakları da.

Ne güzeldi hayat,elimden tuttuğu an,

Gezerdik tasasız,kırları da,sokakları da.

Ninem vardı ninniler söyleyip

Masalla uyutan dizinde.

Dedem vardı saçlarımı okşayıp

Hediyeler alan her bayram gününde.

Musallat olmuyordu aşlar başıma,

Sevdalılara gülüyordum sinemada.

Gurbet mi,düşmanlar başına

En uzak yolumdu gidişim parka.

Ne karlar yağmıştı başıma,ne de amansız lodos,

Ekmek parası da,yürek yarası da kaygım değildi.

O masum kalbimde herkescikler dost,

Toprak çatlak,yaprak solgun değildi.

Uçup gitti çocukluğum,varamadan farkına

Gençlik devri başladı aşk mektuplarıyla.

Bakamazdım artık sınavlara,yarına

Her şeyimdi o güzel,açılan kollarıyla.

Çocukken baba oldum,en tatlı sorumluluk,

Bu amaç uğruna kurulur evlilikler.

Kıskançlık girdabında sürüklendi mutluluk

Ne eşler kaldı bugün,ne dost,ne sevgililer.

Zaman akıp gitmiş,buldum elliyi,

İçim ham, diyorlar olgunluk yaşı.

Ağlıyorum düşündükçe,geçen tatlı maziyi

Süzülüyor yanağımdan özlem dolu göz yaşı...', 'Özlemini çekiyorum çocukluk yıllarımın, Mevsim daima bahar,berraktı sular her zaman. Çember,topaç çevirmekten yorulan kollarımın Dermanını v...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/maziye-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırt o resimleri', 'yirt-o-resimleri-atabay-guveloglu-ikrqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giden gider,sana göz yaşı kalır,

Yırt o resimleri,yırt be kardeşim!

Çerçevelerini taşa vurup kır,

Yırt o resimleri,yırt be kardeşim!

Kaymış bir yıldızdan vaz geçmez misin?

Doğan günden bir şey beklemez misin?

Yazıktır canına,mazoşist misin

Yırt o resimleri,yırt be kardeşim!

Sarı saçlar,saçlarını ağartmış,

Kara gözler yaşamını karatmış.

Göz yaşların ıslatarak saratmış

Yırt o resimleri,yırt be kardeşim!

Üzerine gelen duygu seliymiş,

Aşkın değil,ihanetin ismiymiş.

Gerçek değil,rüyaların resmiymiş

Yırt o resimleri,yırt be kardeşim!

Ruhunu kaybeden geri bulur mu?

Böyle gidenlerin izi kalır mı?

İnsan,katiline bakar durur mu?

Yırt o resimleri,yırt be kardeşim!

Neler göreceksin yeter ki yaşa,

Yaşamda her cefa geliyor başa.

Unut o zalimi,hayatı yaşa

Yırt o resimleri,yırt be kardeşim!

Sanma ki gün gelir bulursun bir gün,

Yazık,gözlerinden olursun bir gün.

Fotoğraf elinde ölürsün bir gün

Yırt o resimleri,yırt be kardeşim!

Yırt o resimleri,yırt be kardeşim,

Yak o resimleri,yak be kardeşim!..', 'Giden gider,sana göz yaşı kalır, Yırt o resimleri,yırt be kardeşim! Çerçevelerini taşa vurup kır, Yırt o resimleri,yırt be kardeşim! Kaymış ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yirt-o-resimleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Olma Şansı', 'mutlu-olma-sansi-yilmaz-guney-1h9gg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat bize mutlu olma şansı vermedi sevgili, 

biz kendimizden başka herkesin üzüntüsünü üzüntümüz acısını acımız yaptık çünkü. 

Dünyanın öbür ucunda hiç tanımadığımız bir insanın göz yaşı bile içimizi parçaladı. 

Kedilere ağladık, kuşların yasını tuttuk... 

Yüreğimizin zayıflığı kimi zaman hayat karşısında bizi zayıf yaptı. Aslında ne güzel şeydir insanın insana yanması sevgili... 

Ne güzeldir bilmediğin birinin derdine üzülebilmek ve çare aramak. Ben bütün hayatımda hep üzüldüm, hep yandım. 

Yaşamak ne güzeldir be sevgili... 

Sevinerek, severek, sevilerek, düşünerek... 

Ve o vaz geçilmez sancılarını duyarak hayatın...', 'Hayat bize mutlu olma şansı vermedi sevgili,  biz kendimizden başka herkesin üzüntüsünü üzüntümüz acısını acımız yaptık çünkü.  Dünyanın öbü...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Güney']::text[], 8.5, '{"poet":"Yılmaz Güney","poet_slug":"yilmaz-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutlu-olma-sansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznümün Bahçelerinde', 'huznumun-bahcelerinde-osman-erdal-erturan-u9wz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hüznümün bahçelerinde

yıllarca yalnızlık büyüttüm

kendi yagmurlarımla

soguktu ve yaprakları döküldü

her mevsim

20/10/2000     01:27', 'hüznümün bahçelerinde yıllarca yalnızlık büyüttüm kendi yagmurlarımla soguktu ve yaprakları döküldü her mevsim 20/10/2000     01:27...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/huznumun-bahcelerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatsam Sevdamı', 'anlatsam-sevdami-turgay-kadiroglu-zckjd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fani bedenim ve ona anlam katan sevdam 

Gönlümde yanan, varlığımı hatırlatan sevdam

Sevdamı, sevdamı dağlara anlatsam

Taşırlardı senelerce, güçlerinin yettiğince

Anlatırlardı yeni nesillere kendi dillerince

Nur kadar kırışmış yüz hatlarında

Sevdamı, sevdamı suya anlatsam

Taşırdı engin okyanuslara 

Anlatırdı deryadan bihaber alıklara, balıklara, 

Yakutlara, yakut kılıklılara, inci ve mercanlara

Sevdamı, sevdamı Tarık''a anlatsam

Çakardı semavatta şimşek misali

Nakşederdi Buruc üstüne o ilahi ismi

Zirederdi Levh-i Mahfuzda''ki en hüsna zikri

Sevdamı, sevdamı zerreye anlatsam

Dönerdi zevk ile mecnun misali

Dönerdi, dönerdi ve sevdanın cazibesiyle 

Yansırdı Allah''ın ayetlerine, buutlarına 

Doğdum doğalı zikrindeyim o sevdanın 

Kalbimdeki mühürden, şah damarıma

Avuç içimdeki sayıdan, sağ elimdeki esmaya

Kundağımdaki şehadetten, soluğumdaki Hu''ya.', 'Fani bedenim ve ona anlam katan sevdam  Gönlümde yanan, varlığımı hatırlatan sevdam Sevdamı, sevdamı dağlara anlatsam Taşırlardı senelerce, ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlatsam-sevdami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamadım', 'yasayamadim-turgay-kadiroglu-nnyb0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur oldum ıslanamadım 

Ateş oldum yanamadım

Aşk oldum sevdalanamadım

Gözyaşı oldum ağlayamadım

Uçurum oldum atlayamadım

Sema oldum kanatlamadım

Ses oldum duyamadım

Işık oldum göremedim

Ölüm oldum ölemedim

Kefen oldum giyinemedim

Tabut oldum omzuma yüklenemedim

Mahrem bir mezar oldum sırlanamadım

Dünya oldum duramadım

Gece oldum uyuyamadım

Uyku oldum rüyalamadım

Rüya oldum bir daha uyanamadım.', 'Yağmur oldum ıslanamadım  Ateş oldum yanamadım Aşk oldum sevdalanamadım Gözyaşı oldum ağlayamadım Uçurum oldum atlayamadım Sema oldum kanatl...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasayamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-turgay-kadiroglu-6i869', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimde neler yazılı aç da bir oku 

Belki sen çıkarırsın bu zehirli oku

Kalp muskamın içinde gizlidir

Gittikçe sarpa saran, sardıkça dikilen

Dikildikçe yükseğe eren, gönül yokuşu

Bu gece karanlık denizden doğdu sanki

Bir karanlık ki, doğacak güneşe savaş açan

İklimlerde hayat yok, yaşadığım yer insan kafesi

Çekin üstümden duvarları, gözlerime toprak serin

Ruhumun nefesi yetmese de bedenime, 

Yüreğimi serinletir sela sesi

Bir hayalmiş yaşadığım ömür boyu

Soluğum ben bilmeden zikretmiş evreni tek bilen Hu''yu

Ve yüreğim, hayat sıratında sırtlanmış, 

Şimdilerde Yusuf güzelinin şereflendirdiği

Yakup hasretinin kör göz yaşlarıyla dolu

Dibi gökleri destek bilen kuyuyu.', 'Yüreğimde neler yazılı aç da bir oku  Belki sen çıkarırsın bu zehirli oku Kalp muskamın içinde gizlidir Gittikçe sarpa saran, sardıkça dikil...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/serzenis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Yazılır', 'askimiz-yazilir-turgay-kadiroglu-bgxu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklarda bilinmezlerin yanında kaf dağı

Üzerine yıllardır ağlayan bulutlarla o bir yas dağı

İçine gömdüğü sevdasıyla o bir yanar dağı

Yüreğimin yanındaysa sadece bir toprak yığını

Pınarlarım kupkuru içinde örümcek ağları

Bir damlayla randevulaşan son nefesindeki deniz kızı

İhtişam olsun diye takındığı diri ve yüksek kayaları

Ve içinde bir damla su olmayan içimin pınarları

Ruhum sığ sevgiye ve sağ bedene bol geliyor

Gecelerime sabah ışığı, yalancı aydınlıklar vuruyor

Kalemim geceleri dirilip sabaha dek demleniyor

Güneşimin üzerine diktiğim güller kuru karlar içinde kuruyor

Kırmızı-beyaz, sarı ve siyahi

İşte benim denizimin renkleri

İnanmazsan alev yüklü gemilere sor

Yüreğimin sahip olduğu ateş denizinde yüzen gemilere

Sema yarılır, kaynaklar fışkırır, yıldızlar çıldırır

Toprak sarsılır, söz kakemden sıyrılır

Ve ateşin, suyun, umudun, çöldeki vahanın

Üsküdar''daki martının kanadına aşkımız yazılır', 'Uzaklarda bilinmezlerin yanında kaf dağı Üzerine yıllardır ağlayan bulutlarla o bir yas dağı İçine gömdüğü sevdasıyla o bir yanar dağı Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimiz-yazilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muzmin Bir Şair''e', 'muzmin-bir-sair-e-can-yucel-k0xy2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir beyaz Rustan kapmış

Bir Tepebaşı otelinde Şiiri

Gayrı ne permanganat ne antibiyotik

Bir akıntıdır gidiyor sittin senedir

Gözünden yaş geliyor su dökerken bile.

Belini doğrultmak için Türk Şiirinin

Çekiyormuş bu çekilmez çileyi,

Yoksa çaldığı gibi başından büyük bir taşa

Kırarmış çoktan

Pelikan marka dolma kalemini.

Bakarak bu Çağdaş ve Çardaş Şaire

Hiç de zührevi değilmiş meğer Zühre!', 'Bir beyaz Rustan kapmış Bir Tepebaşı otelinde Şiiri Gayrı ne permanganat ne antibiyotik Bir akıntıdır gidiyor sittin senedir Gözünden yaş ge...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muzmin-bir-sair-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-sair-neslihan-vs9bu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen de benim gibi yap 

Karanlık boşluklara bırak gözyaşlarını.

Bırak ki; dudakların titremesin

Mutluyum derken

Böylesi daha kolay

Kimbilir.... bakarsın

Ustaca yaparsak 

Kendimizi de kandırırız mutluyuz diye

Belki sahiden de mutlu oluruz

Kimbilir?', 'Sen de benim gibi yap  Karanlık boşluklara bırak gözyaşlarını. Bırak ki; dudakların titremesin Mutluyum derken Böylesi daha kolay Kimbilir.....', ARRAY['Türk Edebiyatı','Şiir','Şair Neslihan']::text[], 8.5, '{"poet":"Şair Neslihan","poet_slug":"sair-neslihan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kimbilir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçeleme', 'serceleme-banicicek-kirzioglu-wo635', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serçeler ağar akşama yakın

Serçelenir ağaçlar

Kımıltı haaa, kımıltı

Bitimsiz

Bu serçeler gündüzü yemlik bilir

Gece yüzlerce aç bıçak saplanır gibidir

Özsuyunu gagalamak geçer içlerinden

Yuva bildiklerinin

Gece uzun -çok uzun-

Bin boğum

Yüz bin boğum

-Bir yuvalık bulsalar

Çoğalan sevgi gibi

Yuva yapmaya dursalar-

Serçeler çiçeklenir ağaçlara

Ağaçlar serçeye duman olur

Su yeşili

Yaban pembe

Yumurtalara özlem duyulur.

Serçe çiçekleri söyleşir

Bilesiniz. Kanat gaga...

Bir ezgiyi söyleşir

Kent akşamlarının soluk tükenik ezgisini

Başkent türküsünü.

-Gelin bir çıkmaza ''serçe'' adı verelim-

Serçeden yemişler oluşur

Serçeleşen dallarda

Kara tüylü yemişler

Uçmasını unutmuşlar ya Bulvar''a

Gagalarında ''cik cik'' kalakalmışlar.

Serçeler sarkar akşama;

Serçelenir ağaçlar

Çoğalırlar ki azalmadan

-Gece ağaç onların-

Bakışlar asılır kalır serçe dallarına

Kararır gün serçe çığlıklarında

Serçe kokusudur artık yayılan bulvarlara.

Yuvasız serçelerin üzerine iner gecemiz

Dallarda geceler, ürkek, garip serçelerimiz

Vayyy...', 'Serçeler ağar akşama yakın Serçelenir ağaçlar Kımıltı haaa, kımıltı Bitimsiz Bu serçeler gündüzü yemlik bilir Gece yüzlerce aç bıçak saplanı...', ARRAY['Türk Edebiyatı','Şiir','Banıçiçek Kırzıoğlu']::text[], 8.5, '{"poet":"Banıçiçek Kırzıoğlu","poet_slug":"banicicek-kirzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/serceleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümdar Kalbim', 'hukumdar-kalbim-kemal-sakan-elyyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üfler sıcak kamıştan soluğunu

Atlasın yırtıldığı yerden başlar çağlamaya

Bir dağa çarparak inler sesin

Bir bulut yorgun gezinir ağzımızdan

Gözyaşı dolu siyahi bir anıt gibi

Başın biçimsiz bir iradeyle kalkarak

Buluşur sonsuz yolculukta

Bu şehir hızlı bir ordu gibi geçilmeli

Savaşan soylu perçemiyle kavganın

Sınırları yokeden hükümdar kalbimi

Çağırıyor uzak yerlerdeki gülümsemen senin

Ağarınca güne ödünç verilmiş

Haberini yayacak krallığın habercisi

Sen sevgilisin, sevilmişsin son kez ey sevgili

Uzayacak yolum hasrete abanır gibi

Aramaktan bıkmayacak

Yorulmayacak

Çağa karşı başım dik 

Kısık bir göz hüznünü akıtarak içine

Yaralı bacağımı taşıyacağım

Sürüyerek te olsa

Taşıyacağım ulu bir tepeye yeşil

Umut, sarı yorgun, mavi hep sensin

Hint gözlerin ele vererek gireceğim

Büyük surlarından içeri

Ellerim ne çok büyütmüş seni

Şaşıracak halkımız

Ormanların gece gözleri donacak

Bu nasıl bir acıdır

Büyüdükçe öfkelenmiş bir kısrak tazeliğinde

Sonra belime sarındığım

Orta çağ kuşağından çıkaracağım

Çocuklarımın delişmen suratlarını

Gürbüz başaklar gibi okşuyorum saçlarını

Ve  en uzaktaki gülümsemen senin

Çekiyor halkın akşam dönüşü yorgunluğunu ekinlerden

Sınırda ağlayan yabancılar beliriyor

Su dağıtıyor tanrısal bir yumuşaklıkla

Kadınsı yaralar taşıyan erkekler

Sırtlarını  buruşturaraktan

Ağrılı bir çağa karşı ve 

Elimde gövdemden ağır bir kılıçla

Bölüyorum kendimi

Anlayacaksın o vakit

Sofradan neden zamansız kalktığımı', 'Üfler sıcak kamıştan soluğunu Atlasın yırtıldığı yerden başlar çağlamaya Bir dağa çarparak inler sesin Bir bulut yorgun gezinir ağzımızdan G...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sakan']::text[], 8.5, '{"poet":"Kemal Sakan","poet_slug":"kemal-sakan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/hukumdar-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül', 'bulbul-ahmet-hasim-ec5fu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gamlı hazânın seherinde,

Isrâra ne hâcet yine bülbül? 

Bil, kalbimizin bahçelerinde,

Cân verdi senin söylediğin gül.

Savrulmada gül şimdi havada,

Gün doğmada bir başka ziyâda.', 'Bir gamlı hazânın seherinde, Isrâra ne hâcet yine bülbül?  Bil, kalbimizin bahçelerinde, Cân verdi senin söylediğin gül. Savrulmada gül şimd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşim']::text[], 8.5, '{"poet":"Ahmet Haşim","poet_slug":"ahmet-hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bulbul-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darılırmısın Sevgilim?', 'darilirmisin-sevgilim-sair-sermina-myefa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kış gecesi yanına gelsem,

Kapıyı usulca açıp koynuna girsem

Seni uyandırıp,rüyanı bölsem

Darılırmısın sevgilim?

Kapın kilitliyse pencereden girsem

Sıcak bir öpücükle seni uyandırsam

Kulağına seni sevdiğimi fısıldasam

Darılırmısın sevgilim?', 'Soğuk bir kış gecesi yanına gelsem, Kapıyı usulca açıp koynuna girsem Seni uyandırıp,rüyanı bölsem Darılırmısın sevgilim? Kapın kilitliyse p...', ARRAY['Türk Edebiyatı','Şiir','Şair Sermina']::text[], 8.5, '{"poet":"Şair Sermina","poet_slug":"sair-sermina","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/darilirmisin-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-aykut-yakup-gultekin-nnn95', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerede gözlerinde parlayan güneş?

Sevgi yağmurların nerede anne?

Kalbimde tutuşan sıcak bir ateş,

Yine beni sana bağlıyor anne!

Sıcaklığın yavaş, yavaş sarıyor beni,

Sanki gölgen kucaklıyor birden gölgemi,

Bir rüyada buluyorum kendimi,

Neden uyanıyorum rüyadan anne?

Uyumak istiyorum bir ömür boyu,

Eğer olunsaydı bir kulun kulu,

Senin kulun olmak isterdim hidayet yolu,

Senin ayağının dibinde anne?

Beni yetiştirdin güzellik için,

Aklımda saklı duracak hep öğütlerin,

Asla dolmayacak gönlümde yerin,

Benim için sen “hayat” sın anne...

Aykut Yakup Gültekin', 'Nerede gözlerinde parlayan güneş? Sevgi yağmurların nerede anne? Kalbimde tutuşan sıcak bir ateş, Yine beni sana bağlıyor anne! Sıcaklığın y...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anne-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksin', 'gideceksin-aykut-yakup-gultekin-xa9xq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gideceksin! Gözlerimde bulutlar nemlenecek,

Gideceksin! Aklım yüreğime seni gömecek,

Gideceksin! Yanağımdan göz yaşım dökülecek,

Gideceksin! Pişmanlığımda senle gidecek.

Gideceksin! Dağlar bile ağlayacak ardından,

Gideceksin! Tek umut kalmayacak bana yarından,

Gideceksin! Sanki kanım çekilecek damarlarımdan,

Gideceksin! Tamamen yok olacak gözümde zaman.

Gideceksin! Seni arayacağım yollarda her gün,

Gideceksin! Ağır ağır yaklaşacak gönlüme ölüm,

Gideceksin! Kalbimde yeşermeyecek başka bir sürgün,

Gideceksin! Seninle gelecek peşinden zulmüm.

Gideceksin! Bulutlar ağlayacak ardından yine,

Gideceksin! Yalnızlık çökecek birden sevgine,

Gideceksin! Karanlıklar dökülecek ak yüreğine,

Gideceksin! Seninle gidecek bu dünya bile.', 'Gideceksin! Gözlerimde bulutlar nemlenecek, Gideceksin! Aklım yüreğime seni gömecek, Gideceksin! Yanağımdan göz yaşım dökülecek, Gideceksin!...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gideceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek İstek', 'tek-i-stek-aykut-yakup-gultekin-v006m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerine, buğular dökülsün gökyüzünden,

Saçlarının, örgüler örülsün her telinden,

Kalbimi alsan belki koparıp ta yerinden;

Unutmak kolay olur, gönlünü yüreğimden.

Seni andım bak yine yağmurlu bir akşamda,

Gözlerinin hayali canlanıyor karşımda,

Sana bazı şeyleri bu gün anlatmasam da;

Anlarsın belki bir gün mezarımın başında.

Sakın ağlama gülüm yüreğini burupta;

Ağlama, değmez geçer her şey tek bir solukta,

Sımsıkı sarıl yarın, kalan hatıralara,

Onlar bağlayacaktır seni elbet hayata.

Gözlerinin içine başka hayal girmesin,

Mutlu olursan eğer ölüm bile gelmesin,

Senden tek dileğim var elbet yapabilirsin!?

Mezarımın başından fatiha eksilmesin....', 'Gözlerine, buğular dökülsün gökyüzünden, Saçlarının, örgüler örülsün her telinden, Kalbimi alsan belki koparıp ta yerinden; Unutmak kolay ol...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-istek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Ölü', 'yasayan-olu-tuba-akalin-294t0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ölü gelecek evine yarın

Gözlerinde yarım kalmış arzular

Dalıp hayaline hatıraların

Duracak kapında sabaha kadar

Duyunca kapının çaldığını

Korkulu gözlerle dışarı bakma

Tüm odaların yak lambasını

Birtek seninkini yakma

Siyahlar içinde çık pencereye

Aç kapıyı yabancı değil korkma

Bir ölü ki gözleri açık

Ölüm seni sevmekten acı değil

Aradı bu ölü hayatı sende

O ölü artık 

Sevsende...Sevmesende...', 'Bir ölü gelecek evine yarın Gözlerinde yarım kalmış arzular Dalıp hayaline hatıraların Duracak kapında sabaha kadar Duyunca kapının çaldığın...', ARRAY['Türk Edebiyatı','Şiir','Tuba Akalın']::text[], 8.5, '{"poet":"Tuba Akalın","poet_slug":"tuba-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasayan-olu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Ölüm Kuşları', 'beyaz-olum-kuslari-arkadas-zekai-ozger-xuaau', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonra bir gün anneler de ölür

Böcekler ve kertenkeleler ölür

Boşalır suyu havuzun kum seddi yıkılınca

Sivrisinekler ve kağıttan kayıklar ölür

Sonra o gün çocuklar da ölür

Biz hepimiz önce küçük bir çocuktuk

Sonra büyüdük hepimiz çocuk olduk

Balçıktan bir külçe olan dölleri

En iri elleriyle kepçeliyen

Ve biçimliyen

Ve hep önce kendidiyle biçimliyen

O dehşetli yontucuyu

Doğumu ve gebelik sanatının bütün hünerlerini

Sütten bir mermere eşsiz bir incelikle işliyen

Anneyi o usta nakkaşı

Unutmadık

Önce anne doğurdu çocuğu acıya

Sonra çocuk acıya anneyi ve ölümü kattı

Sonra herşey ve herkes çocuktan var oldu

Geçti sarp kayalardan aştı nice dağlar

İçti ağulu sütünü hayat denen annenin

Sıkıntının kutsal kabında yıkadı ellerini

Hüznü kuşlara dağıttı unutmasınlar diye onu

Acıyı gömdü toprağa gayrı açar mezarlık çiçekleri

Böyle vardı bir ırmak kıyısına

Anne bir tedirginliktir nerede olsa

Bağırgan bir karmaşadır onun sesi

takılır gibi eski bir gıramafona titrek bir iğne

- bu ayıp bu günah

bu çok ayıp günay

-el ne der sonra

ayak ne der

bırakmaz çoçuğu çocukça yaşamıya

ama bir gün anneyle de hesaplaşılır

çocuk yalnız annesine yaşar çocukken

anne yalnız çocuğuna yaşamaz anneyken

bölüşür anneliği babanın kasığında

çocuğun bakışında çelişkidir büyüyen

ağlamak bir soru olur sevginin yarım payında

-ah baba 

	niye baba

ve bir gün babalar ölür

tanrı bir ürpertidir çocuğun yüreğinde

her tanrı biraz baba gibidir

yiğit ve erkektir çocukları koruyan 

umacılar ve peri masallarının korkulu padişahı

çünki tanrıyı yaratan ve öldüren şeyler aynıdır

vurunca acının ilk gölgesi yaratır kuşkuyu

acının padişahı elbette zalim olur

ve bilincin duvarına çarpınca şaşkınlığı

bir soru önce acıya sonra acıya uzanır

-hey tanrı

	hani tanrı

böylece o gün tanrı da ölür

şimdi annenin yüreğinde ışıyandır

sevginin ıslak soluğuyla örgülü tapınak

bir gün bir kalem bir hokka içindeki kana bulaşır

akıtır mürekkebini sevda denilen papirüse

hani ki bir kuş gelir bir tapınağın duvarına yuva

                                                                        yapar

çökertir tapınağı daha bir güzelleşir yuva

işte artık ne anne ne tapınak

yıkılır gözyaşlarının sığınağı da

sonra bir gün anneler de ölür

gerilir gıcırtısı bir tüfek tetiğinin

öfke yalnız tekliği besler büyür çocuk

	çocuk büyür

sesi nemli yine elleri yine soğuk

hayat sığmıyorsa gövdene yüreğini sığdır çocuk

nemli bir sesi sığdır o gittikçe nemlenen

çocuk çocuk sana bir dost gerek

işte yeniden giyiniyor kendini çocuk

bir çiçek gibi kopardı başkalarına uymıyan

	yanlarını

kendini üstlemişsin var olmak için susmalar köprü

çocuk çocuk sana bir aşk gerek

sen iyilikler ve güzellikler uzmanı

suskunun gizemli sabrı

bir teraziyi en iyi kullanan

iğnenin ve ipliğin mercek gözlü büyücüsü

karnaval gecesinin eğlentisiz parmak çocuğu

ey hayat canbazı

ey ip şaşkını

ezberle o incecik tel üzerinde

hayatı dengeliyen asayı:

aşkın ve dostluğun ayrımı yoktur çocuk

ikisini de doğuran şey aynıdır

bir kuşa bakarken hüzünlendiren, bir güle baktıkça yürek kanatan,

bir yüreği açmadan solduran, bir kadınla yatarken çocuk gibi ağlatan,

uyuz bir kedi gördükçe kanı kudurtan, suyu yüz derece sıcaklıkta donduran, 

anneyi üreten babayı çoşturan çocuğu güldüren, seni izmirlere çılgın gibi koşturan,

bir vagon penceresinden şaşkın baktıran, bir mektubu ısrarla bekleten,

umudu dalında çürüten, acıyı dayanılır kılan bir çıbanı irinle onduran aşka merhem sürdüren

güneşsiz bir gök gördükçe öldüren öldüren öldüren.

Sevgi: tragedyanın kaynağı yaşamın kökeni insanı

Var kılan umut

Ah nasıl ayrılır aşk ve dostluk birbirinden

Can canı sever ötesi yok bunun çocuk

Ölümü ve ölümün ölümsüzlüğünü

Sevgiyi ve sevginin ölümsüzlüğünü

Ah elbette aşktır dostluğu mayalayan

Ama kim anlatabilir bu parmak çocuğa

Bir dostla bir sevgili arasındaki ayrımı

Hayır’lara evet’lerle direten

Çirkini öptüren kötüyü  sevdiren

Aşkı sevgiliyle değil kendinle yorumla

Kim ki kendini açığa komaktan korkmaz

O saygın bir insandır

Herkes kendi yorumunun cellatıdır biraz da

Böylece lady chatterley de sevilir giovanni de

Böylece lady chatterley ve giovanninin sevgilisi de

Elbette her aşk yalnızca kendine sorumludur

Ama elbette her aşk kendine sorumlu

 olunca

bir gün aşk da ölür

ve başlar sıkıntısı kuralsız bir çelişkinin

yapışkan bir sevişmenin sancısı doldurur

				boşlukları

ve tutku aç bir güve gibi kemirirken sevdayı

dölün pasıyla bulanırken sevginin beyazlığı

ah şimdi kim inandırabilir bu eski çocuğa

aşkın ve dostluğun varlığını

bir gün ansızın yiter dostalar ve sevgililer

etin ve kemiğin sıcaklığıyla solar sevdalar

işte o gün her şey ölür

şimdi bu yüreği nerelerde beslemeli

bütün saksıları kırılıyorken güneşin büyüsüyle

ve ölümler ilençliyorken en masum sevinçleri

ve her sevgi kendisiyle çelişiyorken

şimdi bu nasıl doğmaklar olur yeniden beyazlara

ama şimdi kim kandırabilir sizi

bir ölünün hayat kokan ağzını öpmek için.', 'Sonra bir gün anneler de ölür Böcekler ve kertenkeleler ölür Boşalır suyu havuzun kum seddi yıkılınca Sivrisinekler ve kağıttan kayıklar ölü...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":132,"source_url":"https://www.antoloji.com/beyaz-olum-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'leke...', 'leke-omer-asim-f2t7c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Apansız dertler vardır

 kınayanların dahi

 kendine pay biçebileceği

 Bir merhamet''in 

 kendi mazisinden pay biçip te

 bir vuslat''ı daim kılmak için

 sarmalandığı bohçanın, aslında sütbeyazı olan 

 lekesinde gizli

 Leke;

 vurulmuştur bir kere

 sütbeyazı tanımaz.

 Sonra, sahibi merhamet

 leke yi sökmek ister

 leke ziftkara görünmektedir

 gece yarılarında çaresiz saç baş yolma merasimlerinden

 artakalan saç tüylerinden yapılmış

 döşeklerde yatanlar ca

 hani bazen 

 düşmez kalkmaz bir Allah deyip

 selam edenler de yok değildir

 lakin onlar

 gök kuşağının tek rengiyle boyamazlar düşlerini

 yedi rengi bahşedilmiştir gönüllerine

 her noktaya rengiyle bakarlar

 onlarda azınlık..

 Taktı ya kafayı..!

 bu leke gitmeli..

 çalışmalı yedi ay bin gündüz

 sabunla temizlenmez ki..

 o zaman sizde adalar vapurunun ardındaki

 köpükleri deneyin!!!

 onlar da ''sütbeyazı'' ya..!

 şunun şurasında bahar''a ne kaldı ?

                -ömer asım-', 'Apansız dertler vardır  kınayanların dahi  kendine pay biçebileceği  Bir merhamet''in   kendi mazisinden pay biçip te  bir vuslat''ı daim kılm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Asım']::text[], 8.5, '{"poet":"Ömer Asım","poet_slug":"omer-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/leke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu''nun Kavruk Yiğitleri', 'anadolu-nun-kavruk-yigitleri-metin-aksu-odb7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'anadolunun kavruk yiğitleri

aşka sevdalı,türküsü dudaklarında 

hayattan yemiş tokadı acımasızca

çileye tutsak,nasırlar avuçlarında

mahkum iki öküz.bir tarlaya 

tırpanla dost,arzuları derinlerde

kurban edilip bir töreye

silahla kardeş,dostları mezarda

kan davası uğruna sebeb olup cana 

öfkeyle kavgalı,ömürleri hapiste

köy küçük. yangın bir kıza

töreye kurban ,sevdaları bağırlarında', 'anadolunun kavruk yiğitleri aşka sevdalı,türküsü dudaklarında  hayattan yemiş tokadı acımasızca çileye tutsak,nasırlar avuçlarında mahkum ik...', ARRAY['Türk Edebiyatı','Şiir','Metin Aksu']::text[], 8.5, '{"poet":"Metin Aksu","poet_slug":"metin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anadolu-nun-kavruk-yigitleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-mucahit-baskal-kd2fe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'annem babam sayesinde geldim dünyaya

doğar doğmaz daldım bir derin rüyaya

acı çile dolu bu dünya denen diyara

istem dışı geldim yoruldum gayri

binbir zorlukla büyüdüm geldim

ben bu ömrün çeyrek yaşına

biliyorumki bende baki değilim

bende yatacağım birgün musalla taşına

gülmeyi denedim hiç gülemedim

sevdim ama nedense hiç sevilmedim

şu kısa ömrü boşa geçirdim

artık bende yoruldum gayrı

dünyadan intihar edip göçmek istedim

buna gücüm yetmedi benim

inanın dostlarım yoruldum gayrı

biliyorum yaşamak ayrı mutluluk ayrı

....', 'annem babam sayesinde geldim dünyaya doğar doğmaz daldım bir derin rüyaya acı çile dolu bu dünya denen diyara istem dışı geldim yoruldum gay...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoruldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde', 'nerde-metin-aksu-7mtl4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerde mezar taşları

Nerde kanayan gözyaşları

Şimdi nerdeler

Sevdiğimin ahu bakışları

Nerde dokunuşları

Selvi boylum  nerde', 'Nerde mezar taşları Nerde kanayan gözyaşları Şimdi nerdeler Sevdiğimin ahu bakışları Nerde dokunuşları Selvi boylum  nerde...', ARRAY['Türk Edebiyatı','Şiir','Metin Aksu']::text[], 8.5, '{"poet":"Metin Aksu","poet_slug":"metin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'geldim', 'geldim-boran-butuner-54sif', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağ ayazı yaylaya inende eski bir dost gibi geldim yanına 

Kavgalardan kan revan içinde çıkarken üstüm başımda paramparça geldim yanına

Yetim bir çocuk gibi 

Ana kucağına hasret

Cebimde bilyalarımla geldim

Üç mevsim çürüttüm yokluğunda

Ağacın yaprağını döktüm yere

Dağları beyaza gelin eyledim

Güle tomurcuk verdim

Yemin billah yazı görmedim

Yürek yangınında sulara giremedim doya doya

Yüreğimi avuçlarıma aldım

Avucumda ateşlerle geldim

Dudağımın arasında en acemi şiirlerimi 

Gözlerimin ferinde çocuk korkusunu getirdim

Çırılçıplak dağlara uzanıp

Dağ rüzgarlarını getirdimde öyle geldim yanına

Dostluk diyordun söze gerek yok

İnsan kendine sevdalıdar 

Dostuna sevdalıdır zaten

Seni kendimde bulup sevdalandım

Adına şiirler  yazdımda öyle geldim yanına

Hayallerime senin adını verdim

Sensiz düş görmedim geceyarılarında

karanlığın üç kırkbeşlerinde

En arka vagonlardaki hüzünlerimi getirdim sana

Şimdi karşımdasın 

Tüm suretin göz hizamda

Ama sen nerdesin 

Beni alıp götüren o sevda

O şaşkın bakışlı 

Duygularından korkan

Liseli kız nerede

Nerede hayallerim

Benliğimi verdiğim umut yükü 

Gece gibi seyrettiğim gözlerin nerede

Oysa 

Dağ ayazı yaylaya inende eski bir dost gibi gelmiştim yanına

Kavgalardan kan revan içinde çıkarken 

Üstüm başımda paramparça

Şimdi yüreğimin dört bir yanını paramparça ederde 

Öyle giderim yanından', 'Dağ ayazı yaylaya inende eski bir dost gibi geldim yanına  Kavgalardan kan revan içinde çıkarken üstüm başımda paramparça geldim yanına Yeti...', ARRAY['Türk Edebiyatı','Şiir','Boran Bütüner']::text[], 8.5, '{"poet":"Boran Bütüner","poet_slug":"boran-butuner","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülteci', 'multeci-ali-celik-6xox7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sınırlar geçiyorum, 

