INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah ve Sen', 'sabah-ve-sen-hamit-karadag-fsjnc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabahın serinliği vuruyor yüzüme

Ayılıyorum.

Çiğ  düşmüş  yapraklara,

Güneş bulutları  zorluyor

Ulaştırmak için ışığını  dünyaya.

Ben dalmışken  sabahın  sisine

Seni  düşünüyorum.

Bir  sis   yoğunluğunda sarılışını,

Seni hissediyorum.

Bilmem  kaçıncı  uykudasın  tatlı  sevgilim

Güneşe vermişim busemi

İlk ben  öpeceğim  biliyorsun dudaklardan

Kalkınca  güneşi ,

Güneşte beni  göreceksin.

Ben  güneşe verdim  busemi

Güneş  bende ben güneşte

Güneş  sende  ben  sendeyim

Bir  sis  yoğunluğunda  seveceğim seni.

Her  bir zerremi ruhunda  hissedeceksin

Uyanacaksın benimle

Ve  her şey  yeniden başlayacak.

Umut  ve  coşkuyla,

Sen  güleceksin.

Hamit Karadağ  -  Bursa -  26.10.2000', 'Sabahın serinliği vuruyor yüzüme Ayılıyorum. Çiğ  düşmüş  yapraklara, Güneş bulutları  zorluyor Ulaştırmak için ışığını  dünyaya. Ben dalmış...', ARRAY['Türk Edebiyatı','Şiir','Hamit Karadağ']::text[], 8.5, '{"poet":"Hamit Karadağ","poet_slug":"hamit-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sabah-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-onder-baysal-cmqze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakma öyle sessiz durduğuma

Yüreğimde fırtınalar kopuyor

Sebebi ne senin varlığın nede yokluğun

Sebebi benim sana duyduğum

Adını bile unuttuğum......

AŞK......', 'Bakma öyle sessiz durduğuma Yüreğimde fırtınalar kopuyor Sebebi ne senin varlığın nede yokluğun Sebebi benim sana duyduğum Adını bile unuttu...', ARRAY['Türk Edebiyatı','Şiir','Önder Baysal']::text[], 8.5, '{"poet":"Önder Baysal","poet_slug":"onder-baysal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar-Çocuklar', 'martilar-cocuklar-nur-kayapinar-tpdai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine hüzünlü bir akşam

Ne kuş sesleri kaldı gökte

Ne yerde çocuk sesleri

Yine de silemiyorum aklımdan

O güzelim martı ve 

Onlar kadar pak olan çocukları

Ne zaman istesem

Oynarım onlarla

Ne yaşımı sorar birisi ne de neden ağladığımı

Söylesem neye yarar ki terk edildiğimi

O çocuk kalbiyle ne anlar ki yalnızlıktan!

Bu güne değin belki ayrılmadı annesinden hiç;

Belki de biri annesiz-babasız yaşadı

Yine de söylenmez bir çocuğa bunlar

Ne zaman ki büyür,severse birini benim gibi

Hem de karşılıksız,tek taraflı

O zaman anlar yalnızlığı,sevgisizliği

Sonuçta herkes kendini bir kez olsun yalnız hissetmiştir herhalde

Kimi giderken son durağa otobüste tek başına

Kimi yazılıya sonradan giren bir talebe

Karşılıksız bir sevgiyi tadan herhangi bir varlık,

Ayrıldığında sevgilisinden ağlayan yar;

Belki hepsi bunların yalnızlığı;onun ne demek olduğunu bilir

Ama onlar martıların seslerini derine kadar duyamaz ben gibi

Oynayamaz bir çocukla ben kadar zevkle

Bu yüzden benim tattığım yalnızlık farklı bir türde

Etrafımda ailem olmasına karşın...

Martılara,çocuklara rağmen...

                                                                    Saat:22:05', 'Yine hüzünlü bir akşam Ne kuş sesleri kaldı gökte Ne yerde çocuk sesleri Yine de silemiyorum aklımdan O güzelim martı ve  Onlar kadar pak ol...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/martilar-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazımın Telleri', 'sazimin-telleri-nur-kayapinar-g6lw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatıralarım,tellerinde sazımın

Aşklarım,sevgi mesajlarım bir kutuda saklı

Yalnız kaldığımda yazdığım şiirler ise

Sadece benim bilmem gereken yerde

Sevgilimin adına yazdığım şiirlerim

Bizim şiirlerimiz orada

O kadar uzakta ki!

Metrelerce,kilometrelerce yürüsen de erişemezsin onlara

Belki onun kalbinde yerim yok

Onu etkilemeyi başaramadımsa da

Deli gibi onu sevemedimse de

Sevgimi onun yüzüne vuramadımsa da

Yine de sevdim,hiç değilse onu sevdiğime inandım

Öyle yaşadım...

Etrafımda ne kadar ''sana yaramaz,acı çekersin'' deseler de

Ne aldırıp vazgeçebildim senden,ne de yırtabildim sana yazdıklarımı veya yakabildim

Ama inan kimsenin sevemeyeceği kadar sevdim seni

Sazımın tellerindeki aşk şarkılarında olan sevgi kadar

hasret kadar sevdim seni

seni sevdim inan...

                                                         Saat:22:20', 'Hatıralarım,tellerinde sazımın Aşklarım,sevgi mesajlarım bir kutuda saklı Yalnız kaldığımda yazdığım şiirler ise Sadece benim bilmem gereken...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sazimin-telleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rica', 'rica-abdurrahim-karakoc-gjo3o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çileyi koklayıp gül niyetine 

Zindana girersen, beni de çağır.

Sabrı, kanaatı bal niyetine

Ekmeğe dürersen, beni de çağır.

Bazen iki dünya sığar içime 

Bazen iki güneş doğar içime

Bazen gam yağmuru yağar içime

Sen beni ararsan, beni de çağır.

Dostların var ise divanelerden

Göz yaşın aktıysa minarelerden

Binlerce senelik viranelerden

Birşeyler sorarsan, beni de çağır

Ezelin ezelden öncesi vardı, 

Yine sonsuzluktur sonsuzun ardı.

Zaman yumağına bizi kim sardı? 

Aklını yorarsan beni de çağır.

Dışarda göz yanar, içerde yürek, 

Taahhüt ehline tahammül gerek.

Mazlum yarasına merhem diyerek

Göz yaşı sürersen beni de çağır.

(Beşinci Mevsim)', 'Çileyi koklayıp gül niyetine  Zindana girersen, beni de çağır. Sabrı, kanaatı bal niyetine Ekmeğe dürersen, beni de çağır. Bazen iki dünya s...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/rica-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Sevgisi', 'anadolu-sevgisi-abdurrahim-karakoc-s4091', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bizim dağları bilmezsin gülüm, 

Hele boz dumanlar çekilsin de gör.

Her haftası bayram, her günü düğün, 

Hele yaylalara çıkılsın da gör.

Bilmezsin ovalar nasıldır bizde; 

Kağnılar yollarda, yoncalar dizde...

Saydıklarım damla değil denizde, 

Hele bir ekinler ekilsin de gör.

Görmedin sen bizim mavi suları, 

Karlar eriyince kırar yuları...

Köpük olur beyaz, sel olur sarı; 

Hele taştan taşa dökülsün de gör.

Sen bizim köyleri görmedin ki hiç, 

Yolları toz, çamur, evleri kerpiç.

O kirli kabukta, o en temiz iç; 

Hele bir yakından bakılsın da gör.

Anlamaz, bilmezsin sen bizim halkı, 

Sevgiyi bulasın, yakına gel ki...

Kalıplar gerçeği göstermez belki

Gönül perdeleri sökülsün de gör.

(Dosta Doğru)', 'Sen bizim dağları bilmezsin gülüm,  Hele boz dumanlar çekilsin de gör. Her haftası bayram, her günü düğün,  Hele yaylalara çıkılsın da gör. ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anadolu-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıp', 'ayip-abdurrahim-karakoc-aisna', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara gözlüm bu ayrılık yetişir, 

İki gözüm pınar oldu gel gayrı.

Elim değse akan sular tutuşur

İçim dışım yanar oldu gel gayrı.

Ayların sırtında yıllar taşındı, 

Sanma ki garibi eller düşündü.

Bebekler evlendi, yollar aşındı

Kozalaklar çınar oldu gel gayrı.

Hesap et, gideli sen gurbet ile

Otuz ay tutuldu kolay mı dile? 

Hapisler, sürgünler, esirler bile

Sılasına döner oldu gel gayrı.

Gönlüm sende, gözüm yollarda durdu, 

Saat isyan etti, takvim kudurdu.

Hasret hançerini bağrıma vurdu

Yüreciğim kanar oldu gel gayrı.

Emeği boşadır yuvasız kuşun...

Nerdeyse toprağa değecek başın.

Beni düşünmezsen kendini düşün

Herkes seni kınar oldu gel gayrı.

Vur Emri', 'Kara gözlüm bu ayrılık yetişir,  İki gözüm pınar oldu gel gayrı. Elim değse akan sular tutuşur İçim dışım yanar oldu gel gayrı. Ayların sırt...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ayip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Aşkım', 'sana-olan-askim-turgay-kadiroglu-ue0t8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana olan aşkım, 

Bir tohum tanesi kadar 

Kökleri yeri, 

Kanadı gökleri, 

Saracak bir çınar saklayan, 

Tohum taneciği kadar.

Bir su damlası kadar, 

Deryalara akacak

Dünyalara hayat olacak

Okyanuslar kuşatacak

Yer ile gök arasında mektuplar taşıyacak

Bir su damlacığı kadar.

Toprak bozması bir kum taneciği kadar

Büyüdüğünde canlıya yatak olacak

Titrediğinde tüm canları yakacak

Rahmet yağdıkça üzerine 

Merhamet saçacak sevdiklerine

Öldüğünde ela gözlerine, kefen olacak mahremine.

Bir kum taneciği kadar

Atom kadar, zerrenin zerresi kadar

Yarıldığında coştukça coşacak

Yayıldığında seni ve beni

Ve gözlerimizdeki parıltıyı

Bizden habersiz tüm mekanlara taşıyacak

Bir atom taneciği kadar

Yarıldıkça büyüyen 

Kanadıkça olgunluğa eren

Bir çayır kaşu kalbi kadar

Avuç içi kadar cismine

Dünyalara sığmayan sevdalar sığdıran

Acıdığında göklere yas tutturan 

Ağladığında ormanı küstüren

Bir çayır kuşu yüreciği kadar

Minicik bir bebeğin yumuk yumuk elleri

Güldüğünde görünen o saf yüreği

Annesinin ona hediye ettiği sevgisi kadar.', 'Sana olan aşkım,  Bir tohum tanesi kadar  Kökleri yeri,  Kanadı gökleri,  Saracak bir çınar saklayan,  Tohum taneciği kadar. Bir su damlası ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sana-olan-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-atabay-guveloglu-776is', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adamin biri, 

 Bir zalimi sevmis; 

Sevis o sevis! ..

 Adamin biri, 

Unutmak için içmis; 

Içis o içis! ..

 Adamin biri, 

""Eyvallah""demis; 

Kalkis o kalkis! ..

 Adamin biri, 

Denize gitmis; 

Gidis o gidis! ..', 'Adamin biri,   Bir zalimi sevmis;  Sevis o sevis! ..  Adamin biri,  Unutmak için içmis;  Içis o içis! ..  Adamin biri,  ""Eyvallah""demis;  ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/intihar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kangren Yazılar 1', 'kangren-yazilar-1-ahmet-ocal-invw7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mekan saray kokuyor : Çırağan Çırağan...

Vakit kelimelerin canını alma vaktidir.

Genç bir adama en derin kuyulara bile bağırılamayacak bir sır veriliyor: ''Aşk''

Çok noktalı bir cümle kuruluyor hayata dair : ''Yaşamak...''

Şimdi bizim acımızı bir mavzer kurşunu sarar.

Bu türkünün güzdür notası...

Uzun hava kıvamında düşer yapraklar.

En yamanı avzların

İklimsiz çıkmaz ağızdan...

Duvarlara çalınır şiir,yankısı gelmez; tutmaz kafiye...

Darmadağın aşk yaraları

Kan akar set kurulmaz önüne.

Fırat''a Dicle''ye öykünür kırmızı

Damara çalar,ele yaltaklanır ki

Güle kaptırır en koyusunu.

Kadife kadife dikilir kafiye şiire

Bir şair örer Zonguldak''taki işçilerin tulumlarını...

Sefer tası ziyafetler verilir,

Mektepli aşıkların isim kazıdığı maslarda...

Yağmurdan bahsedilmez mi hiç?

Damla damla erimez mi sabır?

Sırılsıklam köşebaşı rastgelişler,

Sızıp kalmalar soğuğun kucağında,

Karanlığa kafa tutmalar,

Fabrika önlerinde grevlerden kalma tenhaya karşı

''Az sonra sevdam geçecek'' gibi edilmiş

Büyükçe, sahipli bir söz...

Şimdi aşk; bir karın ağrısıdır.Böler bizi ikiye...

Dikiş tutmaz ayrılığımız...', 'Mekan saray kokuyor : Çırağan Çırağan... Vakit kelimelerin canını alma vaktidir. Genç bir adama en derin kuyulara bile bağırılamayacak bir s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öcal']::text[], 8.5, '{"poet":"Ahmet Öcal","poet_slug":"ahmet-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kangren-yazilar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırılsıklam', 'sirilsiklam-turgay-kadiroglu-bd1ua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Suyu ağırdır bu gece buluta 

Gözlerimin yaşı yeter mi acıma? 

Her yan sırılsıklam bir kuru soğuk kaldırmda

Buzullar içindeki sevda doygunu yüreğim yanmada

Beni anlayan tek dostum yine beraberiz

Üzerinde dizeler yazılı kaldırımlarım

Her bir taşına adımı yazayım 

Ölümümde başıma tac olasın

Ölümümde yine yağmur bu kez ince 

Yıllardır beni bekleyen toprağım boğuldu sevince

Ve ölüm bile güzel hayatın ardındaki gerçeği sevince

Dopdolu bir ömrün ardından gelen ölüm ise 

Daha da güzel günahlardan temizlenince.', 'Suyu ağırdır bu gece buluta  Gözlerimin yaşı yeter mi acıma?  Her yan sırılsıklam bir kuru soğuk kaldırmda Buzullar içindeki sevda doygunu y...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sirilsiklam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur', 'ne-olur-atabay-guveloglu-hrv51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sa.ah çıkıp da gelsen kapıma,

''Neredeydin''diye sormazdım sana.

Çılgın arzularım sönmüştür ama,

Bir bardak çayımı içsen ne olur?

''Tapıyorum''derdin,hatırı yok mu,

Bir saat ziyaret,o bana çok mu?

Göz yaşıyla geçen on yılı atıp,

Ayrılığı,kırgınlığı bırakıp,

Hüzün veren her konuyu kapatıp

Tatlı anılardan açsan ne olur?

''Tapıyorum''derdin,hatırı yok mu,

Bir saat ziyaret,o bana çok mu?

Ölmeden son defa görsem yüzünü,

Güzel gülüşünü,ceylan gözünü.

Ayırıp da senede bir gününü

Verdiğin o sözü tutsan ne olur?

''tapıyorum''derdin,hatırı yok mu,

Bir saat ziyaret,o bana çok mu?

Son bir defa olsun,et beni sarhoş,

İstersen çıkınca başkasına koş...

Toprak çağırıyor,kalan her şey boş

Bir gün melek olup uçsan ne olur?

''Tapıyorum''derdin,hatırı yok mu,

Bir saat ziyaret,o bana çok mu?', 'Bir sa.ah çıkıp da gelsen kapıma, ''Neredeydin''diye sormazdım sana. Çılgın arzularım sönmüştür ama, Bir bardak çayımı içsen ne olur? ''Tapıyor...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-olur-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölen sevgiliye', 'olen-sevgiliye-atabay-guveloglu-47d33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kara bulutlarla kaplandı dünyam,

Elleri elimden koptuğu o gün.

Gerçeğe dönüştü korkulu rüyam,

Son defa gözümden öptüğü o gün...

Çiçeklerle dolu kaldı balkonu,

Tanrım,daha mı çok sevdin sen onu?

''Ömrümüz ne kadar,bilemem''diye,

''Gülmem,nefes bile alamam''diye,

''ben senden sonraya kalamam''diye,

Son defa sözünü tuttuğu o gün...

Böyle mi bitermiş mutluluk yolu,

Tanrım,daha mı çok sevdin sen onu?

her gece göklerden göğsüme eğil,

pınar olsun sevgin,ateşe serpil.

Beyaz güller soldu,sanki sen değil

Siyah lalelerin bittiği o gün...

Hasretiyle içim her an dop dolu,

Tanrım,daha mı çok sevdin sen onu?', 'kara bulutlarla kaplandı dünyam, Elleri elimden koptuğu o gün. Gerçeğe dönüştü korkulu rüyam, Son defa gözümden öptüğü o gün... Çiçeklerle d...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olen-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-turgay-kadiroglu-9ag9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün 

Gecenin dolunaya

Mevsimin bahara

Toprağın rahmete

Çiçeğin tohuma

Çölün ıssızlığa

Şelalenin köpüğe

Suyun deryaya

Güneşin dünyaya

Yıldızın yangına

Doyduğu gündür bugün

Yüreğimin sana 

Senin sevgime

Gözlerimin parıltına

Kalemimin şiire

Silgimin yalnızlığa

Defterimin adına 

Duyguların hasretine

Aklımın intihara

Gönlümün gönlüne 

Doyduğu gündür bugün

Sevdanın ihanete

Sızının acıya

Gözlerimin pınara

Yüreğimin kana

Kalemimin hançere

Aklımın çöplüğe

Duyguların sensizliğe

Med-cezirin semaya

Semanın gözlere

Döndüğü gündür bugün', 'Bugün  Gecenin dolunaya Mevsimin bahara Toprağın rahmete Çiçeğin tohuma Çölün ıssızlığa Şelalenin köpüğe Suyun deryaya Güneşin dünyaya Yıldı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bugun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibine', 'sahibine-turgay-kadiroglu-g6vjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine akşam, yine karanlık

Sensizlik yine, hasretim aydınlık

Yine acı, yine gözyaşı

Sevgisiz yine, yürekte sızı 

Gözlerin yine, parıltı içlerinde

Soluğum yine, derininde

Yetimim yine, çırpınan denizim

Yine meydan okumada alev yüreğime

Yakup''um yine, Yusuf kokuna

Ama gözlerim yine, bakışında şifa aramada

Ölümüm yine, gözlerindeki ihanetine

Kerem''im yine, her yan küllerim kokmada

Ve ilk kez genzini yaksada, kokla içten küllerimi

Seviyorum yine, küllerimde dahi seni', 'Yine akşam, yine karanlık Sensizlik yine, hasretim aydınlık Yine acı, yine gözyaşı Sevgisiz yine, yürekte sızı  Gözlerin yine, parıltı içler...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sahibine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-atabay-guveloglu-5k3qb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen sevgili eşim,can yoldaşımdın,

Birden melek olup gittin koynumdan.

Bu deprem bitmiyor artık kalbimde,

O sesin gitmiyor kulaklarımdan.

Nereden bilirdim gideceğini,

Felek etti bize edeceğini!

Bu depremin saygısı yok sevgiye,

Gelip buldu bizi bilmem ne diye.

Hayatımı yıktı kırk beş saniye,

Akar göz yaşlarım senin ardından.

Nereden bilirdim gideceğini,

Felek etti bize edeceğini!

tek başıma kaldım artık burada,

Herkes dertli,kimse bakmaz feryada!

Bu acıya teselli yok ne fayda

Zevk alamam bu dünyanın tadından.

Nereden bilirdim gideceğini,

Felek etti bize edeceğini!

Bir ateş kavurur sanki özümü,

Hiç uyumaz seyrederdim yüzünü.

Öperdim tenini,ceylan gözünü

Alırdım bir veda güzel alnından.

Nereden bilirdim gideceğini,

Felek etti bize edeceğini!

layik miyim bu özleme,bu derde,

Bakıp göreceğim seni her yerde.

Bir gün buluşuruz belki mahşerde,

Sana taç yaparım göz yaşlarımdan...

Nereden bilirdim gideceğini,

Felek etti bize edeceğini!..

                     17 Ağustos 1999 Yalova depreminde sevgili eşi ölen arkadaşım Yusuf Kenanoğlu''na işaf ediyorum.A.G.', 'Sen sevgili eşim,can yoldaşımdın, Birden melek olup gittin koynumdan. Bu deprem bitmiyor artık kalbimde, O sesin gitmiyor kulaklarımdan. Ner...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/deprem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-atabay-guveloglu-31huw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyah,beyaz,sarı kumral

İnsanları seviyorum.

Bir başka dünyadır onlar

Çocukları seviyorum.

Seviyorum,seviyorum

Çocukları seviyorum.

Dostluk olsun dalgalanan,

Ülkeden ülkeye yayılan.

Barışa doğru açılan

Kucakları seviyorum.

Seviyorum,seviyorum

Kucakları seviyorum.

Alın teri ile koklaşmış,

Orak ile kucaklaşmış.

Çekiç ile nasırlaşmış

Avuçları seviyorum.

Seviyorum,seviyorum

Avuçları seviyorum.

Korkusuz dünya arayan,

Atmacaları olmayan.

Kardeşlik şarkısı okuyan

Şu kuşları seviyorum.

Seviyorum,seviyorum,

Şu kuşları seviyorum.

Ezmeyen ve ezilmeyen,

Azı alıp,çoğu veren.

Adaleti kutsal gören

Bakışları seviyorum.

Seviyorum,seviyorum,

Bakışları seviyorum.

Benim adım ''Doğa'' diyen,

Çiçek açıp gülümseyen.

Gıda veren,şifa veren

Yaprakları seviyorum.

Seviyorum,seviyorum,

Yaprakları seviyorum.

Güneşle dünyayı ısıtan,

yağmurla bereket dağıtan.

Her şeyle kendini anlatan

yaratanı seviyorum.

Seviyorum,seviyorum,

Yaratanı seviyorum...', 'Siyah,beyaz,sarı kumral İnsanları seviyorum. Bir başka dünyadır onlar Çocukları seviyorum. Seviyorum,seviyorum Çocukları seviyorum. Dostluk ...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/seviyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'vatanim', 'vatanim-mucahit-baskal-1m3yl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'vatanıma kem gözle bakanların 

yıkıp yok etmek için çalışanların

ay yıldızımı yere atıp yakanların

ölümü senden olsun yarabbim.

mehmetimi dağa çıkaranların

anaları evlatsız bırakanların

karalar bağlatıp ağlatanların

ölümü senden olsun allahım.

alevi sünni diye ayıranların

kürt türk diye kayıranların

seni unutup puta tapanların 

ölümü senden olsun rabbim

dilini dinini unutanların,

şerefini üç kuruşa satanların

yolunu kaybedib sapıtanların 

ölümü senden olsun yüce allahım', 'vatanıma kem gözle bakanların  yıkıp yok etmek için çalışanların ay yıldızımı yere atıp yakanların ölümü senden olsun yarabbim. mehmetimi da...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vatanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte benim hayatım...', 'i-ste-benim-hayatim-hamdi-yulug-k8gpb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzün yıldızları parlıyor bugün gökyüzünde, 

Bu gece yine için için yanıyorum, 

Oturmuş seni düşünüp ağlıyorum, 

Seni, gidişini, sevişini, herşeyini... 

Unutamıyor işte seni şu yaralı kalbim, 

Yaptıklarını hatırlayıp, pişman oluyor... 

Seni düşünüyorum bu gece, karanlık gökyüzünde... 

Simsiyah gökyüzünde parlayan yıldızları seyrediyorum, 

Onları sana benzetiyorum, 

Kararmış kalbimin bir kenarında yanan meşale misali... 

Dedim ya, seni düşünüyorum bu gece, 

Beni sevdiğini, bana nasıl baktığını, bana nasıl güldüğünü,

Ellerimi nasıl tuttuğunu, ellerini nasıl tuttuğumu, 

Büyüyen bir ateş gibi sevgimizin nasıl çoğaldığını 

Ve birgün ansızın bırakıp gidişini... 

Son vedanı hatırlıyorum, gözlerime ağlarcasına baktığını, 

Gözlerini kalbime gömdüğünü hatırlıyorum, 

Bir daha çıkamasın diye... 

Çıkamadılar zaten kalbimden gözlerin, 

Ölüler dirilirler mi ki gömülenler çıksın, gitsin? 

Gittin son bir veda ile gözü yaşlı, 

Elimde kolyen, ardından dakikalarca baktım, ağlamaklı, 

Sıkıldım, üzüldüm, perişan oldum ama ağlamadım... 

Ağlayamadım, engel oldu gururum, engel oldu aşkım, 

Uzaklara gittin, belki birdaha asla geri dönmemecesine, 

Özledim seni deliler gibi, özlüyorum hala... 

Sen bir yerde ben bir yerde, yinede sönmedi sevgimiz, 

Aksine çoğaldı dağlar gibi oldu hasretimiz... 

Hep seni hayal eder, hep seni düşünürdüm, 

Sesini duyunca yaşar, duyamayınca ölürdüm, 

Aradın beni aylarca bir sevgi uğruna, 

Ne yazık ki, ihmal edildin bir hata uğruna, 

Kırıldın, ağladın, affettin ama hep sevdin, 

Beni sevdin gülüm beni, kalbi kırık bir vefasızı, 

Yine ihmal edildin yine unutuldun bir hiç uğruna, 

Yine kırıldın, yine ağladın, yine affettin... 

Bir daha unutuldun, sevdanla başbaşa bırakıldın, 

Yine kırıldın, yine ağladın ama bu sefer affetmedin... 

Sevdiğini en mutlu gününde öldürdün, 

Ve ardına bakmadan gittin...

Beni benle başbaşa bıraktın, yıkıldım, üzüldüm, kırıldım... 

Senden ayrılınca kaldım çaresiz, sevgisiz ve birde sensiz, 

Hep sensizdim zaten ama şimdiki kadar asla değil...

Parçalanmış bir kalbe sahip oldun mu sen hiç? 

Parça parça edilmiş, yıkık ve virane, 

Bir o kadarda vefasız... 

Önceleri üzüldüm, yıkıldım ama asla ağlamadım... 

Geldi geçti deyip senide gözlerin gibi kalbime gömdüm... 

Unuttum dedim, unutacağım dedim, 

Unutamıyorum dedim, UNUTMAM dedim... 

Önce gözlerin sonra sen çıktın kalbimden, 

Bir vicdan azabıdır başladı ölü yüreğimde, 

Hiçbir şey kalmadı, senden başka kalbimde, 

Hatıraların, gözlerin ve sözlerin...

Şiirlerini getirdiler bana, 

Beni öldüren şiirlerini... 

Vefasız dediğini duydum, yıkıldım, 

Düşündüm seni gecelerce daima tek başıma, 

Şiirlerin öldürdü, hasretin yaktı yüreğimi, 

Kırıldım, üzüldüm, yıkıldım ve en sonunda ağladım... 

3 kişi ağladık sana; ben, kalbim ve gözlerim... 

Sana yandım, seni sevdim, seni hatırladım heryerde... 

Belki birgün sesini duyarım umuduyla 

Telefon bekledim günlerce, 

Telefon gelmeyip sesine hasret kalınca 

Ağladım ağladım, 

Sana yaptıklarımı ancak o zaman anladım...

Duydum ki kalbini vermemişsin kimseye, 

Olurda içinde görürler beni diye... 

Benim kalbimide istediler, ama vermedim kimseye, 

Olurda içinde seni görürler diye... 

Gökyüzü yıldızlar ile doluydu, ben hep seni düşünürken,

Hüzün yıldızları koydum adlarını, seni hatırlatıyorlar diye,

Aynı onlar gibi sende benden çok uzaklardaydın, 

Hep göz kırpardın uzaktan, sessizce, 

Bense hep seni bekledim kırık kalbim, yaşlı gözlerimle...

Bazen hayallere dalıyorum, seni düşünüp ağlıyorum, 

Seni ve sevgini arıyorum hep kalbimde... 

Düşmüyor adın hiç dilimden, 

Öleceğim gülüm bir gün ben, 

Senin sevginden, senin derdinden... 

Bir gün göreceğim yine belki seni, 

Seni, beni unutmuş, benim olmayan seni... 

İşte o an aşkımın gözyaşlarını hatırlayacağım, 

Ve yine bir köşeye oturup ağlayacağım... 

Yemin ettim senin üstüne sevmeyim başkasını diye, 

Ve heryerde, her zaman tekrarlıyorum yeminimi; 

Seni unutmam için öldürseler bile, 

Karşılık olarak dünyayı verseler bile, 

Darağacı kurup idam etseler bile, 

Senden başkasını asla sevmeyeceğim...', 'Hüzün yıldızları parlıyor bugün gökyüzünde,  Bu gece yine için için yanıyorum,  Oturmuş seni düşünüp ağlıyorum,  Seni, gidişini, sevişini, h...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/iste-benim-hayatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben uzaktan da severim seni....', 'ben-uzaktan-da-severim-seni-hamdi-yulug-gmdc1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Resmine bakarak iç çekerim

Kalbim yansa da sabrederim

Sen anlayamasan da beni

Ben uzaktan da severim seni....

Hayalimde tutarım ellerini

Öperim gül misali leblerini

Sen istemesen de beni

Ben uzaktan da severim seni....

Hatıranla avunurum,

Hayalimde sevişirim,

Sen sevmesen de beni,

Ben uzaktan da severim seni.....

Nasıl sevmem, nasıl aşık olmam bensana 

Hayat veriyor can veriyorsun bana

Sen anlamak istemesen de beni 

Ben uzaktan da severim seni.....', 'Resmine bakarak iç çekerim Kalbim yansa da sabrederim Sen anlayamasan da beni Ben uzaktan da severim seni.... Hayalimde tutarım ellerini Öpe...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-uzaktan-da-severim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamam..', 'dayanamam-hamdi-yulug-peggj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Razıyım hiç durmadan, bin azap çektirsinler,

Bir an için kaşını çatmana dayanamam. 

Hayat yoldaşım olsun gözyaşlarım ıstırap, 

Yeterki sen üzülme bir ona dayanamam....

Razıyım binbir şüphe yüreğimi kemirsin,

Kıskançlık yalanları tam can evime girsin. 

Ümitsizlik ruhumu divaneye çevirsin,

Yeterki sen üzülme bir ona dayanamam.....

Kızgın çöllerde günlerce beni yere sersinler,

İçecek su yerine bana zehir versinler.

Her gün bana bin azap çektirsinler,

Yeterki sen üzülme bir ona dayanamam.....

Taşlar kadar duygusuz olmana dayanırım,

Dostlarım yüz çevirsinler eşsiz dostsuz kalayım.

Seni birgün görmeyeyim ona da katlanırım,

Yeterki sen üzülme bir ona dayanamam.....', 'Razıyım hiç durmadan, bin azap çektirsinler, Bir an için kaşını çatmana dayanamam.  Hayat yoldaşım olsun gözyaşlarım ıstırap,  Yeterki sen ü...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dayanamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmemek Mümkün Mü Ölümü', 'bilmemek-mumkun-mu-olumu-yildiz-bilgin-axru3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçinde ta yüreğinin içinde bir şeylerin kıpırdadığını bilmek

Ve bunu diyememek

Gözlerinin içine bakıp ta seviyorum diyememek

Ve nedensiz uzaklaşmak ölümden beter değil mi

Ellerin ellerini tutarken, gözlerinin içinde umutsuzluğu yaşamak

Günler haftalar ve hatta seneler boyu hasret çekmek

Her yağmur damlasında biraz daha eriyip yok olmak

Ölümden beter değil mi

Akşamın o güzelim kızıllığında seni aramak

Ve seni bulamayınca kahrolmak

Özlem içinde kıvranmak

Ölümden beter değil mi', 'İçinde ta yüreğinin içinde bir şeylerin kıpırdadığını bilmek Ve bunu diyememek Gözlerinin içine bakıp ta seviyorum diyememek Ve nedensiz uza...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmemek-mumkun-mu-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Mektubu', 'veda-mektubu-bora-i-seri-f0pzi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'veda ediyorum artık hayata

doyamadım güneşe,doğaya,yaşamaya

veda ediyorum size gözlerimde yaşlarla

hoşçakalın kardeşlerim

arkadaşlarım,sevdikleim,sevgilim

anneciğimi,babacığım

ve küçük heykelim

kitaplarım,şiir defterim

hoşçakal evim ve bütün sev,diklerim

ağlayarak bütün sırlarımı döktüğüm yastığım

doyamadan yok olacağım hiç birinize

ruhum kuruyacak hep o deli özlemle

hoşçakal benim canım annem

bilirdin evladın seni çok severdi

doyamadan inan sana

oysa..

hep bu küçük yavrun kalmak isterdi

sarmanı isterdim kollarınla

hep duymak isterdim o yavrum deyişini

tutmak isterdim o gül yanaklarını

elveda benim canım arkadaşım

bilirsin senide çok severdim öleyise

hatırladın mı sarılıp ağlayışımızı?

acı tatlı anıları

seninle tattım mutluluğu yalan mı?

sana da hoşçakal sevgilim bebeğim benim

ilk aşkımın çiçeği sanada elveda 

sevmeye görmeye doyamadın sevgilim

seninle yaşadım,seni düşlediğim gibi seveceğim

seninle tattım aşk denilen duyguyu

senle yaşadım o doyumsuz mutluluğu

ben yok olurken o kara toprağın altında

sakın unutma beni tamam mı?

ölsemde seveceğim seni elveda!', 'veda ediyorum artık hayata doyamadım güneşe,doğaya,yaşamaya veda ediyorum size gözlerimde yaşlarla hoşçakalın kardeşlerim arkadaşlarım,sevdi...', ARRAY['Türk Edebiyatı','Şiir','Bora İşeri']::text[], 8.5, '{"poet":"Bora İşeri","poet_slug":"bora-i-seri","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/veda-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtaç Kalacaksın', 'muhtac-kalacaksin-bora-i-seri-uvmqi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'muhtaç kalacaksın günün birinde bana.

beni arayacaksın ama,

bulamayacaksın.

ellerini dizlerine,başını taşlara vuracaksın.

gözyaşların kor olacak,

düştüğü yeri yakacaksın.

seven çiftleri görüp kahrolacaksın,

yaşayan bir ölü olarak dünyada kalacaksın.

yanlız hayalimle kendini avutacaksın,

son ğişmanlık fayda etmez bunu anlayacaksın,

unutulmak nedir sende tadacaksın,

sevgi yağmurlarına özlem duyacaksın,

eski dostları yanında bulamayacaksın,

iş işten geçmiş olacak ama çok geç anlayacaksın.', 'muhtaç kalacaksın günün birinde bana. beni arayacaksın ama, bulamayacaksın. ellerini dizlerine,başını taşlara vuracaksın. gözyaşların kor ol...', ARRAY['Türk Edebiyatı','Şiir','Bora İşeri']::text[], 8.5, '{"poet":"Bora İşeri","poet_slug":"bora-i-seri","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/muhtac-kalacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ohh Nerdesin', 'ohh-nerdesin-mehmet-yavuz-wwlrn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ohh nerdesin

Sen nerdesin

Seni aradım

Bulamadın hiçbir yerde

Yıllar sonra

Seni buldum

Bir kenar sokakta

Yanı başımda

Halbuki ben seni

Nerelerde aramıştım

Ne uçra köşeleri taramıştım

Ama seni bulamamıştım

         27 Mart 2000  Cuma', 'Ohh nerdesin Sen nerdesin Seni aradım Bulamadın hiçbir yerde Yıllar sonra Seni buldum Bir kenar sokakta Yanı başımda Halbuki ben seni Nerele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yavuz']::text[], 8.5, '{"poet":"Mehmet Yavuz","poet_slug":"mehmet-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ohh-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımı Kaçırmasam...', 'aklimi-kacirmasam-mehmet-yavuz-6fdf8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aklımı kaçırmasam ne iyi

bu gidişle nereye ulan...

diyorlar bana kızıyorlar

oysa ben neler düşünüyorum

bu halim bu duruşum

bende olan bu sevda

düşlediğim dünya

sevdiğim kalbimde hissettiğim...

ama beni anlamıyorlar

bana açılmıyorlar

bana sormuyorlar nedenleri

beni keşfetmiyorlar sonunda

ben bir deli olayım 

ben bir akıllı olayım

ben bir fakir olayım

ve ben bir zengin olayım

ne farkeder bu dünya için

yine insanlar ağlayacak gülecek

yine yağmurlar yağacak dinecek

ve yine güneş doğacak batacak

ama düşündüklerimiz sevdamız...

o aşkımız o umutlarınız

hiç değişmeyecek

ve o azmimiz hiç bitmeyecek', 'aklımı kaçırmasam ne iyi bu gidişle nereye ulan... diyorlar bana kızıyorlar oysa ben neler düşünüyorum bu halim bu duruşum bende olan bu sev...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yavuz']::text[], 8.5, '{"poet":"Mehmet Yavuz","poet_slug":"mehmet-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aklimi-kacirmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir öğrencinin defterinden erzurum', 'bir-ogrencinin-defterinden-erzurum-yusuf-kilicel-f6ldi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burası Erzurum gülüm 

    Günü gününden kara.

    Bir sana hasretim,

    Bir de gelmeyen bahara.', 'Burası Erzurum gülüm      Günü gününden kara.     Bir sana hasretim,     Bir de gelmeyen bahara....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılıçel']::text[], 8.5, '{"poet":"Yusuf Kılıçel","poet_slug":"yusuf-kilicel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-ogrencinin-defterinden-erzurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dedikleri', 'ask-dedikleri-levent-sahin-q4lqb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne demek olduğunu öğrenemeden

Atıldım içine aşk deryasının...

Ne yandım ne dondum ne güldüm amma

Yok oldum içinde aşk deryasının...

Anlatma.. anlatmakla olmuyor 

Tarifi bulunmaz aşk deryasının.

Korkağın işi değil, tek öğrendiğim

Cesur son nefesinde aşk deryasının', 'Ne demek olduğunu öğrenemeden Atıldım içine aşk deryasının... Ne yandım ne dondum ne güldüm amma Yok oldum içinde aşk deryasının... Anlatma....', ARRAY['Türk Edebiyatı','Şiir','Levent Şahin']::text[], 8.5, '{"poet":"Levent Şahin","poet_slug":"levent-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-dedikleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Ve Bugün', 'bugun-ve-bugun-ozdemir-asaf-5veh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle çabuk geçiyor ki günler 

Hele sen de bir bak hayatına.

Daha dün doğmuşuz sanki 

Yeni okula başlamışız

Yeni sevmişiz

Öyle çabuk geçiyor ki günler 

Hele sen de bir bak hayatına 

Yarın bitecek sanki her şey

Yarın ölecek gibiyiz.

Daha doymamışız yaşamasına

Günlerimiz dün bir, bugün iki

Sakın bir şey bırakma yarına

Yarın yok ki.', 'Öyle çabuk geçiyor ki günler  Hele sen de bir bak hayatına. Daha dün doğmuşuz sanki  Yeni okula başlamışız Yeni sevmişiz Öyle çabuk geçiyor ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bugun-ve-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-ebru-duman-qltm4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece, yine karanlık ve sessiz

İçimdeki sensizlik yansıdı geceye yine

Seninle dolu ama kimsesiz

Yorgun, ümitsiz ve çaresiz

Birkaç araba sesi ve yansıyan ışıklar

Bilirim ki herkes benden habersiz

Sonsuzluk kadar derin,

Kavgam kadar çetin

Sana karşı hissettiklerim...', 'Gece, yine karanlık ve sessiz İçimdeki sensizlik yansıdı geceye yine Seninle dolu ama kimsesiz Yorgun, ümitsiz ve çaresiz Birkaç araba sesi ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Duman']::text[], 8.5, '{"poet":"Ebru Duman","poet_slug":"ebru-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensizlik-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bu', 'ask-bu-ebru-duman-ht1m0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonu olmayan bir yolda 

Nereye bilinmez belki aşkı aramaya

Derken bir bakmışsın aşk kapında

Aşk bu bakarmı yaşa başa?

Yaş 30, yolun yarısı olmasada

Aşkı arayan, aradığını bulur yolun sonunda...

Ankara 23.06.2000', 'Sonu olmayan bir yolda  Nereye bilinmez belki aşkı aramaya Derken bir bakmışsın aşk kapında Aşk bu bakarmı yaşa başa? Yaş 30, yolun yarısı o...', ARRAY['Türk Edebiyatı','Şiir','Ebru Duman']::text[], 8.5, '{"poet":"Ebru Duman","poet_slug":"ebru-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bana Yaren Olmaz', 'kimse-bana-yaren-olmaz-sefil-selimi-cd7zp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimse bana yaren olmaz yar olmaz

Mertlik hırkasını giydim giyeli

Dünya bomboş olsa bana yer kalmaz

İnsana muhabbet duydum duyalı

İmanım hükümdar benliğim esir

Ehl-i Beyt''i sevdim dediler kusur

Kimi korkak dedi kimi de cesur

Kurt ile kuzuyu yaydım yayalı

Ardımdan vuranlar yüzüme güler

Kestiği az gibi parçalar böler

Herkes kılıcını boynumda biler

Başımı meydana koydum koyalı

''Bu kızılbaş olmuş, yunmaz'' diyorlar

''Kestiği haramdır, yenmez'' diyorlar

''Camiye mescide konmaz'' diyorlar,

İmam Şah Hüseyn''e uydum uyalı

Kimi benden kağıt hüccet arıyor

Hal bilmeyen dip dedemi soruyor

Dostlar ölümüme karar veriyor

Sefil Selimi''yim dedim diyeli', 'Kimse bana yaren olmaz yar olmaz Mertlik hırkasını giydim giyeli Dünya bomboş olsa bana yer kalmaz İnsana muhabbet duydum duyalı İmanım hükü...', ARRAY['Türk Edebiyatı','Şiir','Sefil Selimi']::text[], 8.5, '{"poet":"Sefil Selimi","poet_slug":"sefil-selimi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimse-bana-yaren-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kevser Irmağı', 'kevser-irmagi-sefil-selimi-m6gf2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kevser ırmağında saki olan yâr

Bir bardak dem ikram etmez mi ola

Sıratın yolunu iyi bilen yâr

Benim de elimden tutmaz mı ola

Aman medet, duy sesimi dardayım

Sorma hallerimi, gayet zordayım

Cehennemden daha beter kordayım

Yanarım, yandığım yetmez mi ola

Her yanımı harlı ateş çevirdi

Vücut sarayımı yaktı kavurdu

Yaptım mamur ettim, geri çevirdi

Viranemde, güller bitmez mi ola

Zindanda kalsam da gam yemem gene

Sefil Selimî''yle dursan yan yana

Olmak istiyorum, dostla can cana

Muradımca bülbül ötmez mi ola', 'Kevser ırmağında saki olan yâr Bir bardak dem ikram etmez mi ola Sıratın yolunu iyi bilen yâr Benim de elimden tutmaz mı ola Aman medet, duy...', ARRAY['Türk Edebiyatı','Şiir','Sefil Selimi']::text[], 8.5, '{"poet":"Sefil Selimi","poet_slug":"sefil-selimi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kevser-irmagi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Handan', 'handan-abdullah-meral-w4ohd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine aynı bir gündü işte...

Uyanmıştı uykusundan Handan

Başlamıştı Handan 

Saçını taramaya

Ve düşündü biteviye

İşte yine

Tarağı takılıvermişti

Upuzun saçlarına

Üzgündü Handan

Niçin niçin insanlar

Sevmiyorlardı birbirlerini

Gözleri görür gibi olmuştu

Yarını

Evet yarın başka bir gün

Olacaktı işte

Hep aynı gün değil

Hep sevgileri çıkar üzerine

Kurulu olanların değil

Sevenlerin olacaktı 

Gözlerinde sevinç pırıltısı

Belirdi birden

.....ve birden 

Tekrar taramaya başladı

Saçını Handan', 'Yine aynı bir gündü işte... Uyanmıştı uykusundan Handan Başlamıştı Handan  Saçını taramaya Ve düşündü biteviye İşte yine Tarağı takılıvermiş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Meral']::text[], 8.5, '{"poet":"Abdullah Meral","poet_slug":"abdullah-meral","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/handan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Behçet Aysan Anısına', 'behcet-aysan-anisina-sozen-bilgili-1icrx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz otuz yedi meşale

Her biriniz bir bozkırda yanan

Biz milyonlarca yürek

Yalçın kayalarda ışıgınızla aydınlanan', 'Siz otuz yedi meşale Her biriniz bir bozkırda yanan Biz milyonlarca yürek Yalçın kayalarda ışıgınızla aydınlanan...', ARRAY['Türk Edebiyatı','Şiir','Sözen Bilgili']::text[], 8.5, '{"poet":"Sözen Bilgili","poet_slug":"sozen-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/behcet-aysan-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardımdan', 'ardimdan-sozen-bilgili-mrvba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir beni bilmezsiniz bir de sevda davamı

Yüreğim ve ellerim bu kavgadan nasırlı

Yoktan sayarım canımı, onurum ve aşkım uğruna

Çetrefilli yolları bilmem özüm sözümdür benim

Elbette başı dik yüreği bulutlarda bir şairim

Tarih beni böyle yazacaktır ardımdan ağlama sevgilim

Dilemedim aman yobazın celladından

Bedenimdir yanan fikirlerim gitmedi ardından

Sivas''ta kırıldı kolumuz kanadımız otuzyedi yerden

Tanrı dağı kadar allahsız bu can düşmanlarından

Nasıl olsa bir gün sorulacaktır hesap,ağlama sevgilim ardımdan', 'Bir beni bilmezsiniz bir de sevda davamı Yüreğim ve ellerim bu kavgadan nasırlı Yoktan sayarım canımı, onurum ve aşkım uğruna Çetrefilli yol...', ARRAY['Türk Edebiyatı','Şiir','Sözen Bilgili']::text[], 8.5, '{"poet":"Sözen Bilgili","poet_slug":"sozen-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ardimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İstiyorum', 'sevmek-i-stiyorum-nur-kayapinar-49ctb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın vermiş olduğu hüzün 

ve acı ile geldim sana

Bana yardım etmeni beklerken

Sen de vurdun en kötü anımda

Söyleyecekken sorunumu sana

Haykırdın yaptıklarımı yüzüme karşı

Bu bana seni kaybetmekten 

daha da koydu inan

Ama anladım ne olduğunu 

seviyeni

Düşündüm de

Artık ona göre davranacağım

Bana davrandığın gibi

ilgisiz ve saygısız

Bakalım hoşuna gidecek mi?

Hüzün ve heder dolu bir yaşam

İşte anla ki o zaman,ben nasıl

ve neden koştum peşinden

Eğer dönmek istersen bana yine 

Beni aynı adreste bulabilirsin

Seni beni çıkarman için

ilk gün beklediğim kuyunun

içinde bekleyeceğim

Gelmeni bekliyorum

Ben de özgür olmak;sevmek istiyorum', 'Yalnızlığın vermiş olduğu hüzün  ve acı ile geldim sana Bana yardım etmeni beklerken Sen de vurdun en kötü anımda Söyleyecekken sorunumu san...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevmek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarımsaklı Yoğurt Misali', 'sarimsakli-yogurt-misali-nur-kayapinar-l74mp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutmaya karar verdiğimde aklımdasın aksilik

Gözümün önünden hiç bir zaman gitmeyen o biçimsiz vücudu düzelten bacakların

ve jöleli saçların bana Neil Armstrong''u hatırlatıyor

Onun gibi uzaya tırmanmayı,senin yanında olmayı düşlüyor

Ama sadece bu  düşümü bir yatakta,bir de kumsalda yıldızları seyrederken tutmuş olduğum kutup yıldızının içinde buluyorum.

Sen de bir düş kurarsan

İnanıyorum ki;

Bacakları çarpık,saçları örgülü bir kolej kızıno görürsün

Tabi düşlediğin şey bir kutup yıldızının içinde değil,sadece buzdalabına konmuş 

ve acayip koku saçan sarımsaklı yoğurt gibidir.

                                                                      24:00', 'Unutmaya karar verdiğimde aklımdasın aksilik Gözümün önünden hiç bir zaman gitmeyen o biçimsiz vücudu düzelten bacakların ve jöleli saçların...', ARRAY['Türk Edebiyatı','Şiir','Nur Kayapınar']::text[], 8.5, '{"poet":"Nur Kayapınar","poet_slug":"nur-kayapinar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sarimsakli-yogurt-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznümün Gelinciği', 'huznumun-gelincigi-pinar-altanoglu-jov56', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Menekşeler gözleri, karanfiller özlemi

Anlatır dizelerde…

Renklerle kokular birleştirmesede kalpleri

Ne çok sevgililer arar durur

Aşk merdivenini…

Gül tarlalarında dolaşıp, 

Renkler ve kokulara boğuyorsun kendini,

Neden bu kadar önemli bulmak en güzelini…

Oysa sana, senden yakın 

Bir çiçek yaşar karşı tepede

Arkadaşlık eder kar tanelerine senin yerine…

Hiç bitmeyen bir ağrısı vardır 

Belli etmesede sevdası uzaya kadardır…

Arama bulamazsın karşı tepedeki o çiçeği

Bekle dur güller getirsin sana renkli sevgilerini…

Ne menekşe, ne karanfil, ne gül,

Ne aşk merdiveni,

En uzun ömürlü çiçektir 

hüznümün gelinciği… 

(En ıslak en soğuk ekiminde istanbul)', 'Menekşeler gözleri, karanfiller özlemi Anlatır dizelerde… Renklerle kokular birleştirmesede kalpleri Ne çok sevgililer arar durur Aşk merdiv...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huznumun-gelincigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-ozdemir-asaf-qhgvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir türkü söylediler, duydunuz mu..

Bir kuşu vurdular, gördünüz mü..

Böyle neden susuyorsunuz böyle

Güzelliğiniz çoğalıyor, öldünüz mü.', 'Bir türkü söylediler, duydunuz mu.. Bir kuşu vurdular, gördünüz mü.. Böyle neden susuyorsunuz böyle Güzelliğiniz çoğalıyor, öldünüz mü....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler... Kelimeler...', 'kelimeler-kelimeler-ozdemir-asaf-kfzyr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarıda kalmış aşklarının hesapları içinde

Denizlere açıldı içimizden biri

Niçin gittiğini söylemeden.

Doyulmamış arzularla doluydu yelkenleri.

Yıpranmış kelimelerin verdiği güvenden.

Bulacak sanıyordu yenilikleri.

Her an bir yeni su vardı,

Her yeni suda bir yeni an.

Deniz, dalgalarıyla gösteriyordu dışından

Yaşananla düşünülenler arasındaki farkı.

Bitmeyordu köpüklerle renkler

Bir başka damlada, bir başka ışıkta başlamadan.

Gözlerinin önünde bir oyun,ardında bir oyun.

Dışında ne varsa yeni, ne varsa gerçek.

Yeni manzaralarla gelen yeni duygular

Hani, eski keLimelerle olmasa

İnsanın ömrünce devam edecek.

Gözlerin önünde bir oyun, ardında bir oyun.

Anladı, ölmekle yaşamanın birleştiği noktada

Yeni rüzgârlarla esen yeni korkulara

Yeniliklerini bağışlamayan kelimelerin

Nasıl düşman sığınaklar halinde direndiğini.

Anladı, bütün olmuşlarla olanların

Ve bütün olacakların

O kelimelerin içinde

Kendisine varmadan eskidiğini', 'Yarıda kalmış aşklarının hesapları içinde Denizlere açıldı içimizden biri Niçin gittiğini söylemeden. Doyulmamış arzularla doluydu yelkenler...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kelimeler-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüküm', 'hukum-kenan-celik-lh85d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdaya hükümlüsün

Bir çeçek bile vermiyor toprak

Yüreğin dar bir dere

Sığmıyor iki kişi

Mecbursun orada yalnız yüzmeye

Gurbete hükümlüsün

Abonesin ayrılığa

Derin nefeslerin çırpınır durur

Uzak denizlerin yakamozlu sularında

Müziğe hükümlüsün

İki ayrı yöne yürüyor melodi ve sözcükler

Ezgiler durulmayan bir volkan

Bu volkanda erimeden yürüyeceksin

Yorumsuza hükümlüsün

Karanlıkta açan kara bir gülsün

Kimse farketmez seni

Ne de sen farkedersin kimseyi

Maden ocağına hükümlüsün

Kömür ne ki ısınmaktan başka

Kömürü ancak sen anlatabilirsin

Bazen grizu patlar arada

Sedyeyle çıkarılar seni

Zonguldak sana bakar

Sen Zonguldak''a bakamazsın

Yaşamaya hükümlüsün

kaçışın varış limanı yok

Ya darağacında

Ya da bir kutu hapla

Sınır dışısın yeryüzünden', 'Sevdaya hükümlüsün Bir çeçek bile vermiyor toprak Yüreğin dar bir dere Sığmıyor iki kişi Mecbursun orada yalnız yüzmeye Gurbete hükümlüsün A...', ARRAY['Türk Edebiyatı','Şiir','Kenan Çelik']::text[], 8.5, '{"poet":"Kenan Çelik","poet_slug":"kenan-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hukum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Aşk', 'yasak-ask-hasan-karadeniz-280e5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşandı

Tükenirken akşamlar

Hüzün vardı masalarımızda

Benim tek senin çoğul yaşadığın

Adı yasaktı soyadı toplum

Yakınında uzağı yaşadığım

Bir gece daha tükendi

Gözyaşlarının leke bıraktığı

Aşkımızda.....

(30.12.2000 / Biga )', 'Yaşandı Tükenirken akşamlar Hüzün vardı masalarımızda Benim tek senin çoğul yaşadığın Adı yasaktı soyadı toplum Yakınında uzağı yaşadığım Bi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Karadeniz']::text[], 8.5, '{"poet":"Hasan Karadeniz","poet_slug":"hasan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasak-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derttir', 'derttir-omer-asim-l5v2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derttir bir gece yarısı

oğlan gururuna yenilir

vurdular mı sırtına

talebe yoksulluğunu

Baba; töresini alır kenara çekilir

Derttir gece yarısı

kınar mı duygusuz bir ağız

kendine pay biçebileceği

saç baş yolma ayinlerinden artakalanı

selam sabah kesilmiş(mi)dir

balkon''a serpiştirilen yemlere pervane olan alıcı kuşlar dan

derttir

yıl biter dert bitmez

umut;azınlık ta kalmış

belki sirkeci vapurunun ardındaki köpük

teselli; Hattat Osman''ın okkasında

''Bu da geçer ya hu...!''', 'Derttir bir gece yarısı oğlan gururuna yenilir vurdular mı sırtına talebe yoksulluğunu Baba; töresini alır kenara çekilir Derttir gece yarıs...', ARRAY['Türk Edebiyatı','Şiir','Ömer Asım']::text[], 8.5, '{"poet":"Ömer Asım","poet_slug":"omer-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/derttir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Kişilik Oyun', 'tek-kisilik-oyun-sair-doktor-x19bn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek kişilik bir oyundu benimkisi

ama ikimizdik sahnede

seni ben oynuyordum,

beni de...

Seni oynarken ağlıyordu seyirci

ben ise hep komiktim

fazlaca aptal,fazlaca serseri...

Tarihi bir komedya mıydı,

yoksa dramatize edilmiş duygular mı?

Ağlamalı mıydı bu oyuna,

yoksa gülmeli miydi katıla katıla...?

Tek kişilik bir oyundu

ikimizdik sahnede

fazlaca dramatikti

yine de gülmek geliyordu içimden,

ağlamak gözüküyordu...

Tek kişilik bir oyundu

ikimizdik sahnede

seni ben oynuyordum,

beni de...

Gülmek kadar basit geliyordu herşey

ama ağlamak gerekiyordu!!!

                                              30.10.2000', 'Tek kişilik bir oyundu benimkisi ama ikimizdik sahnede seni ben oynuyordum, beni de... Seni oynarken ağlıyordu seyirci ben ise hep komiktim ...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tek-kisilik-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuk Tesbih', 'kopuk-tesbih-sair-doktor-tkwa4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen;

şiirin beynimdeki anlamdaşı,

hüzünbaz iklimimin sağanak yağmuru,

tesbihimin birinci taşı,

sonuncusu ben...

Sen ve ben;

şimdi 33''lük bir tesbihin

hem uzak,hem çok yakın

birinci ve sonuncu taşlarıyken

ve geçmek bilmiyorken

aramızda ipe dizilmiş zaman

ya usulce çekileceğiz,

ya da ipimizi koparıp

tane tane döküleceğiz...

Sen;

şarkımızın beynimdeki yankısı,

düşsel avuntularımın edilgen öznesi,

kopuk tesbihimin

nadide kayıp taşı...!

                                              30.10.2000', 'Sen; şiirin beynimdeki anlamdaşı, hüzünbaz iklimimin sağanak yağmuru, tesbihimin birinci taşı, sonuncusu ben... Sen ve ben; şimdi 33''lük bir...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kopuk-tesbih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümle Gelen Yanlızlık', 'olumle-gelen-yanlizlik-celalettin-yasar-hckkt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbahar gülleri gibi sararan bedenim

Elbet toprak olup yalnız kalacak bir gün

Yalnızlık sadece güllere mi mahsus

Bedenim de yalnız kalacak bir gün

Dostum oldu, düşmanım oldu, arkadaşım oldu sırdaşım oldu

Gözlerim bir gün mutluluk bir gün hüzünle doldu

Sonuçta yalnız kalmadım hergün

Yine de yüreğim yalnız kalacak bir gün

Sevenin olur sevinirsin, derdin olur üzülürsün

Her zaman yaptıklarınla, ve dostlarınla övünürsün

Gün gelir de yanlış yaptığınla dövünürsün

Senin de bedenin yalnız kalacak bir gün...', 'Sonbahar gülleri gibi sararan bedenim Elbet toprak olup yalnız kalacak bir gün Yalnızlık sadece güllere mi mahsus Bedenim de yalnız kalacak ...', ARRAY['Türk Edebiyatı','Şiir','Celalettin Yaşar']::text[], 8.5, '{"poet":"Celalettin Yaşar","poet_slug":"celalettin-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumle-gelen-yanlizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Şiiri', 'yalnizlik-siiri-gul-unal-8egxn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir yanda olaylar

en acı vereni bile

artık şaşırmadığım

bir yanda yalnızlığım

paylaşamadığım...', 'bir yanda olaylar en acı vereni bile artık şaşırmadığım bir yanda yalnızlığım paylaşamadığım......', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalnizlik-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kişilik Boşluk', 'i-ki-kisilik-bosluk-erol-ozkan-26bzr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bomboş sokaklardan topladım boşluğu,

Bir ,geceyarısı düşünde gördüm.

Kocaman düşünceler içinde,

Bomboş gökyüzünde,

Dolu dolu boşluklar içimde doğdu.

Onları bir dağa yükledim,

Gücü yetmedi taşımaya,

Bulutlara verdim boşluklarımı,

Tufana tuttular yeryüzünü.

Sığdıramadım tüm güzellikleri

Boşluklarıma,bomboş düşüncelerle.

Kıyısındaydım yalnızlığın,

Kin mi, nefret mi,istek mi sevgi mi?

Beklediğim ve düşlediğim.

Ne bilinmez bir dert,

Ne bilinmez bir utanç bu.

Yaşamaktan utanır mı boşluklar?

Tüm yitik duygular tek başına,

Ve tek başıma yüklendim;

Acıları,güzellikleri,

Anlatılası sevgi sözcükleri,

Söylenesi ve kahredesi yılgınlıklar.

Buz tutmuş bir nehrin tam ortasında sanki,

Bir ben varım sanki,ilmiği boynuna geçmiş,

Son sözünü söylemeye utanan.

Dopdolu boşluklar var yüreğimde.

İstemiştim;

İstemiştim hep yalnızlığı,en derin sorgularla.

Sevmiştim korkuyu,sevmiştim deliliği,

Deliliğin tüm vurdumduymaz aymazlığıyla..

Bir menekşede yaşardım boşluğumu,

Bazen birçift kahverengi gözde.

Kızgın yaz güneşi altında tane tane

Dökülürdü içimden,kahrolası

Ve sevilesi boşkluklar.

Upuzun bir özlemi çekerdi canım,

Ve kısacık bir ömüre vururdum yalnızlığımı.

Var olan herşey zıtlıklarıyla buluşurdu yüreğimde,

Bir yargıç edasıyla ayırırdım içlerinden,

En sağlam en doğru boşlukları.

Dizerdim onları gecelere,gündüzlere,

Ve ruhumun en boş yerlerine.

Aradığımı yinede bulamazdım,hep eksikti.

Bir eksiklik vardı içlerinde.

Tam son kapıyıda örtecekken,dönmemesine..

İnce bir ses duydum yardım ister gibi,

Ya da yardım etmek ister gibi.

Çekinir bir sesle konuştu benimle.

Kabul edersen eğer,

Yalnız başıma taşıyamadığım boşluklarımı,

Var mısın benimle paylaşmaya?

En dolu ,iki kişilik boşluklara...', 'Bomboş sokaklardan topladım boşluğu, Bir ,geceyarısı düşünde gördüm. Kocaman düşünceler içinde, Bomboş gökyüzünde, Dolu dolu boşluklar içimd...', ARRAY['Türk Edebiyatı','Şiir','Erol Özkan']::text[], 8.5, '{"poet":"Erol Özkan","poet_slug":"erol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/iki-kisilik-bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Bana Yer Varmı...', 'yureginde-bana-yer-varmi-hamdi-yulug-btyd3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Parmaklarının ucunda şu an hissediyor musun beni? 

Hisset! 

Hisset, Parmaklarına değen kağıdın içinde 

Dolaşan damarlarımı... 

Hisset damarlarımın, kanımın 

Seni aramak için 

Deliler gibi dolaşmasını... 

Parmaklarının ucunda şu an hissediyor musun beni? 

Dinle; duyuyor musun yüreğimin ritmini? 

Gönlümde esen rüzgârları dinle... 

Nefesimi tutmasam 

Gözlerindeki derin ovalarda titreyen 

Bütün yeşillikler kül olur, 

Sazlar büyür simsiyah, 

Kuruyan gözpınarlarında... 

Parmaklarının ucunda şu an hissediyor musun beni? 

Yazık! Mekanlar durduruyorsa seni. 

Ve yazık, kendini bağladıysan maddelere... 

İpsiz bir uçurtmayım ben... Ve kuyruksuz 

Saçlarının çizgilerinde süzülen... 

Rüzgârım sensin. 

Susma ve sakın gözlerini kapatma, düşerim! 

Yüreğinde yer var mı? 

Parmaklarının ucunda şu an hissediyor musun beni? 

Ve bir kaynak suyundan oluşan derenin 

Üzerine düşen yaprak gibi; 

Düşürüyor musun gülüşlerini 

Ve öpüşlerini sesimin üstüne? 

Akıyor musun benimle beraber, 

Akıyor musun yıldızlara doğru? 

Yıldızlar... Yıldızlar neden böylesine vefasız? 

Neden her üşüyüşümde 

Lapa lapa yağıyorlar avuçlarıma, 

Neden eriyip kayboluyorlar? 

Parmaklarının ucunda şu an hissediyor musun beni? 

Bilmiyorum. Bilmek istemiyorum... 

Ama parmaklarının ucunda şu an ne olur hisset beni... 

Hisset! 

Hisset, damarlarımdaki kanımın, 

Seni aramak için deliler gibi dolaşmasını... 

Söylemiştim değil mi? 

İpsiz bir uçurtmayım ben...Ve kuyruksuz... 

Saçlarının çizgilerinde süzülen... 

Rüzgarım sensin. 

Susma ve sakın gözlerini kapatma, düşerim. 

Yüreğinde yer var mı?......', 'Parmaklarının ucunda şu an hissediyor musun beni?  Hisset!  Hisset, Parmaklarına değen kağıdın içinde  Dolaşan damarlarımı...  Hisset damarl...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Yuluğ']::text[], 8.5, '{"poet":"Hamdi Yuluğ","poet_slug":"hamdi-yulug","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yureginde-bana-yer-varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç', 'gec-cem-ocal-d121n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen şevkat dizeleri koyuyorum sen olan fikirlerime,

Seni yazdığım şiirlerde bir kediyi okşuyorum.

Aklım, kalbim hep parmak uçlarımda…

Sen, en düşülebilir kenarlarında dolaşıyorsun beynimin,

En keskin virajlarından dönüyorsun son hızla.

Yumuşak ve umursamazsın endişelerime inat.

Hayattasın yine. En sevdiğin gibi bi başınasın.

Yanlız sözler, yanlız yalvarışlar kalıyor geçip gittiğin.

Ben kalıyorum, bilmeden yüreğimi, beynimi sildiğin…

19.09.2000', 'Bazen şevkat dizeleri koyuyorum sen olan fikirlerime, Seni yazdığım şiirlerde bir kediyi okşuyorum. Aklım, kalbim hep parmak uçlarımda… Sen,...', ARRAY['Türk Edebiyatı','Şiir','Cem Öcal']::text[], 8.5, '{"poet":"Cem Öcal","poet_slug":"cem-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-ertugrul-erbas-u47al', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gecenin koyu rengi

dolarken gözlerine

usulca sokuldu rüzgar

saçlarını okşadı

uyudu... 

düşünde

billur bir kayıktaydı

çoban yıldızı çekiyordu kürekleri

ansızın

mavi bir melek kondu omzuna

öptü

uyandı

uyuyunca gerçeği

uyanınca hayali

kıskandıran

kimdi bu kanatsız peri?

beyhude sormayın bana

uyanmak için 

henüz uyumadım ki!...', 'gecenin koyu rengi dolarken gözlerine usulca sokuldu rüzgar saçlarını okşadı uyudu...  düşünde billur bir kayıktaydı çoban yıldızı çekiyordu...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Erbaş']::text[], 8.5, '{"poet":"Ertuğrul Erbaş","poet_slug":"ertugrul-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ararken', 'seni-ararken-zeynep-dere-3ni1c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'barışsan bir daha küstürürmüyüm kendimi dagıttım

seni dererken

konuşsan bir daha sustururmuyum

dilim tutulaydı seni kırarken

eller deli diyor sen divane de kadehe sığındım her bahanede

bilmemki kaç gece kaç meyhanede

kendimi kaybettim seni ararken', 'barışsan bir daha küstürürmüyüm kendimi dagıttım seni dererken konuşsan bir daha sustururmuyum dilim tutulaydı seni kırarken eller deli diyo...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Dere']::text[], 8.5, '{"poet":"Zeynep Dere","poet_slug":"zeynep-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-ararken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin gideli -1-', 'gittin-gideli-1-huseyin-yalcin-48fek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baharlarda gitti senle birlikte

Dönüşün ruhumda dinmeyen yara

Hasretin içime bağdaş kuralı

Küsmüşüm gittiğin zalim diyara.

            ***

Fırtınalar renk renk hep çeşit çeşit

Alabora oldum yokluğunda bak.

Sensizlik kalbimde ölüme eşit

Korkarım faydasız gayri ağlamak.

            ***

Sensizliği astım duvarlarıma

Hayalin yoldaşım,kokun sıcak dost.

Seni,seni kattım dualarıma

Hep sana gönderdim kucak kucak dost.

            ***

Yittim yokluğunda kim kim bulacak?

Ne bir resmim var ne de eşgalim.

Gitmene ay değil bir yıl dolacak

Bilmem ne olacak benim bu halim?

            ***

Vehmin yakınımda hep nokta nokta

Rüyalara küstüm geceye dargın

Hep seni aradım var ile yokta

Yıllara razıydım bulsaydım bir gün.

            ***

Yokluğun sızlatır tel tel ruhumu

Ağladım olmadı sustum olmadı.

Hakk için and olsun bilesin şunu

Senden senden başka dostum olmadı.

            ***

Bir türkü duyarım taa uzaklardan

''Ne sen beni unut ne de ben seni''

Düşmez oldun artık bu dudaklardan

Nasıl unuturum nasıl ben seni.

            ***

Hiç çare olmadı gülmek,ağlamak

Şiirler karamsar heceler buruk

Ruhuma tak etti senden ayrılmak

Gözlerim isteksiz bakışlar donuk.

            ***

Ne öksüz,ne yetim,ne divaneyim

Şimdi bildim beni tam bir zır deli

Böyle olacağın nerden bileyim

Aklım başımda yok GİTTİN GİDELİ.

                                        

                                            18/12/1991

                                               Elbistan', 'Baharlarda gitti senle birlikte Dönüşün ruhumda dinmeyen yara Hasretin içime bağdaş kuralı Küsmüşüm gittiğin zalim diyara.             *** F...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yalçın']::text[], 8.5, '{"poet":"Hüseyin Yalçın","poet_slug":"huseyin-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gittin-gideli-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin gideli -2-', 'gittin-gideli-2-huseyin-yalcin-11cg6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bağrım hasretine,yokluğa gebe

Korkarım yakında deli doğurur.

Üşüyen duvarlar vurur yüzüme

Ağlarsa gözlerim seli doğurur.

             ***

Buz gibi yatağım sarar koluna

Okşar sever beni senin yerine

Bakmaktan usandım artık yoluna

Umut bağladım sevda türkülerine.

             ***

Rüyalar yalancı,hayaller garip

Geceler acımaz yorgun halime.

Hasreti yokluğu koluma alıp

Bilir misin?yatmak nasıl kelime.

             ***

Sensizlik her gece kapımda bekler,

Gezinir durur,hep dolaşır tak tak.

Ürperir yapraklar,korkar çiçekler,

Bir benim korkmayan,bir ben muhakkak.

             ***

Kafam allak-bullak bir boşluktayım 

Gönlümde hasretin buz gibi eli

Yoruldum,tükendim,bittim hastayım

Bir boynu büküğüm GİTTİN GİDELİ.

                                      

                                                   19/12/1991

                                                     Elbistan', 'Bağrım hasretine,yokluğa gebe Korkarım yakında deli doğurur. Üşüyen duvarlar vurur yüzüme Ağlarsa gözlerim seli doğurur.              *** Bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yalçın']::text[], 8.5, '{"poet":"Hüseyin Yalçın","poet_slug":"huseyin-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gittin-gideli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin gideli -3-', 'gittin-gideli-3-huseyin-yalcin-lqdib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlık sineme çöktü çökeli

Baharı olmayan mevsim gibiyim.

Hasret düğüm düğüm güğsümde yumak

İçmeden sarhoşum sersem gibiyim.

             ***

Saatler yas tuttu takvim elemli

Çürümeyen sakız ağzımda zaman

Çiçekler ah çeker gözleri nemli

Gidişin belli,ya dönüş ne zaman?

             ***

Hasret lokma lokma yutsa da beni

Korkum yok Allah''ın dediği olur

Alsa da sensizlik aciz bedeni

Yinede bu sevdam ayakta kalır.

             ***

Hayaller hep silik,rüyalar yarım

Gündüzler canavar,geceler akrep

Her gün aynı şey titrer korkarım

Seans seans oynar bir matine hep.

             ***

Odam altı adım durmadan git gel

Görenler olsa der:Bu adam zır deli

Yokluğun ki çok zor ölüme bedel

Günler geçmiyor sen burdan gideli.

             ***

Kötüye gidiyor hasretle aram

Ne yurt var,ne yuva,nede yerimiz

Hep seni düşündük ben ve sigaram

Hep senin uğruna yandık ikimiz.

             ***

Gölgemde terk etti çok çok yalnızım

Dönüşün içimde koskoca yara

Ya çıka gelirsin bir gün ansızın

Yada çiçek gönder ordan mezara.

             ***

Tükendim,yoruldum bitti nefesim

Hep yalnızlığımı güttüm güdeli

Taa arşa dayandı çığlığım sesim

Ellerim koynumda GİTTİN GİDELİ.

                 

                                          24/12/1991

                                             Elbistan', 'Yalnızlık sineme çöktü çökeli Baharı olmayan mevsim gibiyim. Hasret düğüm düğüm güğsümde yumak İçmeden sarhoşum sersem gibiyim.             ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yalçın']::text[], 8.5, '{"poet":"Hüseyin Yalçın","poet_slug":"huseyin-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gittin-gideli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Benden Başka Seven Var Mıdır', 'seni-benden-baska-seven-var-midir-tayfur-eken-a24vi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni benden başka seven var mıdır

Onlara da dünya böyle dar mıdır

Onlar da mı her günü senin için yaşar

Bilmem törpüler misin ömürlerini

Benimki gibi azar azar..', 'Seni benden başka seven var mıdır Onlara da dünya böyle dar mıdır Onlar da mı her günü senin için yaşar Bilmem törpüler misin ömürlerini Ben...', ARRAY['Türk Edebiyatı','Şiir','Tayfur Eken']::text[], 8.5, '{"poet":"Tayfur Eken","poet_slug":"tayfur-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-benden-baska-seven-var-midir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Niye Seviyorum', 'seni-niye-seviyorum-tayfur-eken-9c2hk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık öğrenmenin vakti geldi

Gel yanıma, iyi dinle beni.,

Bir zamanlar bir genç vardı

Ve bu genç, bir kızı sevdi.

Sadece onun için yaşardı,

aklını kaçırmamak için

yüzüne bakmaktan korkardı.

bir an yakınında olmak

ona yeter de artardı.

yeşili severdi

gözleri dünyanın en güzel yeşili

saçları kıskandırırdı güneşi

o uzaktan görününce

yerinde durmak istemezdi kalbi

sesini bir kere daha duymak için

herşeyini düşünmeden verirdi

her an onu hatırlamak için

eline kalem geçtiği an

adını karalardı

ama bunların hiç bir önemi yok

ne saçları, ne de gözleri

güzelliği

hiç birisi için sevmedi onu,

bir gülüşüne aşıktı aslında...', 'Artık öğrenmenin vakti geldi Gel yanıma, iyi dinle beni., Bir zamanlar bir genç vardı Ve bu genç, bir kızı sevdi. Sadece onun için yaşardı, ...', ARRAY['Türk Edebiyatı','Şiir','Tayfur Eken']::text[], 8.5, '{"poet":"Tayfur Eken","poet_slug":"tayfur-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-niye-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-tayfur-eken-jzhtt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm ne bir sondur sadece

Ne de sonsuz acılardan kurtuluştur

Aslında ölüm, uykudan uyanıp

Yüzüne bir avuç soğuk su vuruştur.', 'Ölüm ne bir sondur sadece Ne de sonsuz acılardan kurtuluştur Aslında ölüm, uykudan uyanıp Yüzüne bir avuç soğuk su vuruştur....', ARRAY['Türk Edebiyatı','Şiir','Tayfur Eken']::text[], 8.5, '{"poet":"Tayfur Eken","poet_slug":"tayfur-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar', 'sarkilar-necati-cumali-pry63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağladığını istemem ben ölürsem 

Beni en sevdiğin halimle hatırla

Uzak bir yerde çalıştığımı düşün 

Hayatta olduğuma inan

Bir gün gelir kendiliğinden

Geçer bütün üzüntüm. 

Her yeni gelen günü 

Yeni bir ümitle beklemeli

Her yeni gün 

Yeni havalarla gelir.

Gece, yağan yağmurla uyursun

Sabah, bir de bakarsın odan güneşli

Her gelen vapuru, treni

Yeni bir ümitle beklemeli

Her gelen vapur, tren 

Yeni insanlarla gelir

Ben esmerdim güzelim

Bu sefer bir sarışını seversin

Aşk yaşayanlar içindir.', 'Ağladığını istemem ben ölürsem  Beni en sevdiğin halimle hatırla Uzak bir yerde çalıştığımı düşün  Hayatta olduğuma inan Bir gün gelir kendi...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumalı']::text[], 8.5, '{"poet":"Necati Cumalı","poet_slug":"necati-cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ademin Kızlarından Biri', 'ademin-kizlarindan-biri-hayriye-unal-vqom9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbiriniz beni cehenneme gönderemez

Bir kadın eli bekliyordunuz işte el

Sizi

Ve arafınızı

Ve sevdiklerinizi

Ve bağrınıza iştiyakla bastıklarınızı

Silecek olan el

Kesilmelidir öyle ya

Kısas

            -haydi bize vadettiğini göster

            haydi göster

            bir sayha ya da bir ses ya da kara bir duman -sarsar?-

            gibi gelecek helak

Kısas

O kadim gelenek

Kadit ellerinizi fışkırmış saçlarınız arasında görmeliyim

herşey hazır

dudu kuşu

yarasa

bir boncuk

Hey sözleriyle zihnimi çelen müsvedde

geniş omuzlu erk/ek

erkini kutsuyorum

unufak ediliyor şairliğin

Artık ne ak kollu koşacak yardımına

ne gül parmaklı şafak

çünkü onlar yok hiç olmadılar

             -haydi bize vadettiğini göster

             haydi göster

             bir sayha ya da bir ses ya da kara bir duman -sarsar?-

             gibi gelecek helak

bando takımına girememiş bir oğlan

koyunları gütmüş bir oğlandır nerden baksak

rüyada güneş görülmezmiş ancak

tattaratam tattaratam

bir mehter takımını aratacak

denli gürültü sığarmış

sığırtmaç bir oğlanın rüyasına.', 'Hiçbiriniz beni cehenneme gönderemez Bir kadın eli bekliyordunuz işte el Sizi Ve arafınızı Ve sevdiklerinizi Ve bağrınıza iştiyakla bastıkla...', ARRAY['Türk Edebiyatı','Şiir','Hayriye Ünal']::text[], 8.5, '{"poet":"Hayriye Ünal","poet_slug":"hayriye-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ademin-kizlarindan-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hep', 'sen-hep-yunus-yasar-x3g5b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hep uykularda mı kendini anlatacaksın

Çitlere takılırken uçurtmanın mavi yüzü

Hep sayıklayacak mısın

Geçitlerde düşürdüğün 

bir çocuğun öpülesi gülüşünü

Sen hep fısıldayacak mısın

Söylemeden suya ulaşan şarkıları

Sürgülenip sürgünlüğüne

Eskimiş fotografların silüetlerini mi giyineceksin

Sen hep yalnız adreslerde mi yaşayacaksın.

Sen hep duruşlarınla mı kendini anlatacaksın

Dudaklarının kıvrımında uzayıp giden destanı

Bir yanı uzunçalar yüreğinin geri sarar bir yanı

Bir yanın gün sağarken gecenin memesinden

Sen hep böyle koca sevdaları mı taşıyacaksın.

Sen hep pekmez tadında bıraktığın

Ondokuz akşamlarını

Sedef kakmaly saksılarda mı saklayacaksın

Belki bir gün bir alay turaç sesine

Takılır da gelirsin ellerim bekleyedursun...', 'Sen hep uykularda mı kendini anlatacaksın Çitlere takılırken uçurtmanın mavi yüzü Hep sayıklayacak mısın Geçitlerde düşürdüğün  bir çocuğun ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yaşar']::text[], 8.5, '{"poet":"Yunus Yaşar","poet_slug":"yunus-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-gokhan-ozsoy-4to5w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ruhunu ruhuma yaklaştır ki

karlar yağsın üzerimize

yağan kar

ruhlarımızdan yeryüzüne kalan izleri

birer birer

ikişer ikişer kapatsın

birer birer

ikişer ikişer çekilelim 

insanlığın gündeminden

hem deminden

hem zeminden...', 'ruhunu ruhuma yaklaştır ki karlar yağsın üzerimize yağan kar ruhlarımızdan yeryüzüne kalan izleri birer birer ikişer ikişer kapatsın birer b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Özsoy']::text[], 8.5, '{"poet":"Gökhan Özsoy","poet_slug":"gokhan-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-senay-erdogan-eou2x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne seni unutacak kadar zaman geçecek,

Ne geçen zaman seni unutmaya yetecek.

Bırakıp gitsemde,seni unuturum sanma.

Zaman alışmayı öğretir,unutmayı asla.', 'Ne seni unutacak kadar zaman geçecek, Ne geçen zaman seni unutmaya yetecek. Bırakıp gitsemde,seni unuturum sanma. Zaman alışmayı öğretir,unu...', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutamam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-senay-erdogan-ujajd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dertlerin çoğaldığı

Sızıların arttığı,

İnsanı karanlığa iten geceler.

Gürültüden uzak sessiz geceler.

Rüyaların görüldüğü,

Hayallerin yaşandığı,

Karanlığın uzadığı,

Acımasız geceler.

Ah hüsran dolu geceler.', 'Dertlerin çoğaldığı Sızıların arttığı, İnsanı karanlığa iten geceler. Gürültüden uzak sessiz geceler. Rüyaların görüldüğü, Hayallerin yaşand...', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geceler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğim', 'cicegim-senay-erdogan-k0g1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni çiçeğim diye 

Koydum vazoya hayallerimde.

Hiç solmayacaksın çiçeğim,

Hayat suyun bende.', 'Seni çiçeğim diye  Koydum vazoya hayallerimde. Hiç solmayacaksın çiçeğim, Hayat suyun bende....', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-cemal-kirzioglu-w2g6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairin şiiri burada doğar,

Akşamın güneşi ufukta solar,

Bütün kalplere sevgiler dolar

Herkes sevdiğini alır sandala.

El ele kol kola denize giden

Sürerler orada yaşanan bir dem.

Fakat ben burdayım söyleyin nidem?

Herkes aşığını alır sandala.

Oynaşır kaynaşır sandallar birden, 

Secdeye kapanır o dallar birden

Kızlar mendilini sallarlar birden

Açılır engine dalar mehtâba.

Herkes sevdiğini alır sandala.', 'Şairin şiiri burada doğar, Akşamın güneşi ufukta solar, Bütün kalplere sevgiler dolar Herkes sevdiğini alır sandala. El ele kol kola denize ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Kırzıoğlu']::text[], 8.5, '{"poet":"Cemal Kırzıoğlu","poet_slug":"cemal-kirzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayta', 'hayta-atilla-abrek-r38wa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kadınlar gördüm yeşil,

Galiba hiçbiri buralı değildi

Kimi kartal bakışlı,kimi ceylan sekişli

Fakat hepsi hayır hayır tümü,

Giyinip bir sara titreyişi

O şarap mavisi dağa koştular

Bende bakıp ardlarından güneşe,

Kendimi doyurdum kendimi diyorum ama,

onları

Bırakıp gittim

        Atilla Abrek

       30.09.2000', 'Kadınlar gördüm yeşil, Galiba hiçbiri buralı değildi Kimi kartal bakışlı,kimi ceylan sekişli Fakat hepsi hayır hayır tümü, Giyinip bir sara ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaduyum', 'uzaduyum-atilla-abrek-rdo1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesin telefonda tenha,

belkide buğulu.

Bense dolaylı tümleç kusuyorum

Kulaklarımda sarı bir ıslık

Seni hatırlıyorum,

Her sigara yakışımda,

Gözlerin ufuktan atınca,

Kendimi bir fırtanaya çakıyorum.

Sana bir şarkı tutunca, radyodan

Herşey ıslanıyor.

Dilimde şarap ekşisi.', 'Sesin telefonda tenha, belkide buğulu. Bense dolaylı tümleç kusuyorum Kulaklarımda sarı bir ıslık Seni hatırlıyorum, Her sigara yakışımda, G...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzaduyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış', 'yanlis-atilla-abrek-kozwp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boş sandalyeler diyarında

Aslında boşmu o da bellisiz,

bütün tahmincileri yanıltan

Kulakları küpeli,oynakta biraz

Soğuk kalorüfer peteğinden

Daha açık bir beyaz

Halının üzerindeki kürdan

Ve asmalı mescit''te güz

Gibi kara bir şamdan 

Yanar,odada

İki yeşil göz

           Atilla Abrek

           2000', 'Boş sandalyeler diyarında Aslında boşmu o da bellisiz, bütün tahmincileri yanıltan Kulakları küpeli,oynakta biraz Soğuk kalorüfer peteğinden...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-atilla-abrek-dsc1c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir türlü ütü tutmayan gömleklerin

Gözleri kör eden hışırtısı 

Bütün yıldızlarından parlak,göklerin

Ben onlardan gayrı....

Memelerin benden  ayrı

Ayaklarımda yüzyıllık bir nasır

     2000', 'Bir türlü ütü tutmayan gömleklerin Gözleri kör eden hışırtısı  Bütün yıldızlarından parlak,göklerin Ben onlardan gayrı.... Memelerin benden ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasret-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni', 'ninni-atilla-abrek-lswjz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin doğduğun günlerde,

İnsanın yüreğini bile kırardı rüzgar

Sırf bu yüzden seni içerde

tutup

Saçlarımı güneşe verdim

Yüreğimin kanı sökün ederde

Akarsa gözlerimden

Saçlarım onlar buna dayanamaz

Alıştım sonunda 

            sensiz olduğu gibi

                        sesinsizde oluyormuş

                          2000', 'Senin doğduğun günlerde, İnsanın yüreğini bile kırardı rüzgar Sırf bu yüzden seni içerde tutup Saçlarımı güneşe verdim Yüreğimin kanı sökün ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ninni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belalı Sevda', 'belali-sevda-ayhan-eralp-kyf6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin    kül   ettiği   kalbimin     sancısına 

Yağmur    indiren     melekler     şahit   olmasa 

Hangi   melek,   günah    yazabilirdi   gözlerine

Benim  kaktüslerden  yağmur emen  ümitlerim 

Beyaz bir tomurcuğun sarhoşluğuna sığınmasa

Kalbim  nasıl  yüklenirdi   gözlerinin   vebâlini

Nasıl  bir  sevdadır   bu 

Çözülmez   beladır   bu

Sihirli  bir   şiirdir   dilin

Düğümler atıyor kalbime

Neyini    düşünsem,    sadece 

Düşündüğümden      ibaretsin 

Önce  gözlerin kaplıyor  bedenini

Sonra, tüm  evren oluyor gözlerin

Saçlarının karası yetişiyor imdadıma

Ve

Her şey  karanlıklardan  ibaret

Dudaklarını görüyorum, aydınlanıyor 

                               karattığın umutlar

Sonra cehennemlere atıyorsun beni

Dudakların kadar

Yanıyor,  yanıyorum

O gözler ki kalbinin  gizlendiği 

                               Truva atıdır

Ve sevmek   senin   için  savaştır,

Katliamdır, emsâlsiz bir vâhşettir

Her  türlü  hile  sana  mubahtır

Senin   kalbin, kalbime isyanın

Farz   olduğu     dar’ül   harptır

Saçların  cehennem  gibi  simsiyah

Her bir teli Ebrehe’nin  askeridir

Bu gurur ve kibir sana  Ebrehe’nin

                                       takdimidir 

Kuşatmışsın   kalbimi,

Fikrimi

Kâbe’mi 

Benden beklediğin esaretten de öte

                                        bir şeydir

Alevden  daha   kırmızı  ve  yakıcı

Kisrâ’nın,   sönmez  sanılan   ateşi 

                                      dudakların

Hiçbir hayal daha kırmızı yapamaz

  			  dudaklarını

Başka  bir  kıyasa   kâbil  olmayan

Nasıl  bir   kırmızıdır    dudakların

Aldanma şimdi, şiiristana

İltica  edişime

Gözlerine her yenildiğimde 

Erciyes’e çekilip, 

Yıldızlara  yakın olduğuma

Kalbimin Ergenekon’udur Erciyes.

Dudak büküşlerin yırtıp atsa da 

Her türlü anlaşmayı

Beyaz  gül tomurcuğuyla, uzlaşmasa da 

Teninin  beyazı.

İhanet etmemeli Truva’lı gözlerin,

Ubeydiye’ye, beyaz gül tomurcuğuna. 

Benim Truva atından, daha onurlu

Nice zaferlerim var. 

Hiç  bir   kavgadan   kaçmadım

Yiğitliğimin olmadı  yüzdesi asla

Kâbe’nin sahibi var

Kalbimin sahibi var

Nedir ki Ebrehe’ler 

Gönlümde   bu  günlere  beslediğim

Ebabile özenmiş göçmen kuşlar var. 

Hiçbir kutsal girmemiş gönlünden

Haberin  yok   mutlak   müjdeden

Kisrâ’nın   anahtarı    benimdir.

       (1999 KAYSERİ)', 'Gözlerinin    kül   ettiği   kalbimin     sancısına  Yağmur    indiren     melekler     şahit   olmasa  Hangi   melek,   günah    yazabilird...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Eralp']::text[], 8.5, '{"poet":"Ayhan Eralp","poet_slug":"ayhan-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/belali-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Önce Seni Sevenlerin Hali', 'benden-once-seni-sevenlerin-hali-mustafa-ozdemir-palu-sg1e0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin doğduğun köyde ihtiyaç yoktur yağmura

Bilirim,

Kızıl ıslaklık vardır toprağın renginde

Ve yüzüstü toprağa çökmüştür ergenler

Kutsamaktadırlar gözyaşlarıyla toprağı

Ve toprak sinesine çekmektedir

Sensizliğin kanlı ve kutsal ve kahpe gözyaşlarını.', 'Senin doğduğun köyde ihtiyaç yoktur yağmura Bilirim, Kızıl ıslaklık vardır toprağın renginde Ve yüzüstü toprağa çökmüştür ergenler Kutsamakt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özdemir Palu']::text[], 8.5, '{"poet":"Mustafa Özdemir Palu","poet_slug":"mustafa-ozdemir-palu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/benden-once-seni-sevenlerin-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar-Kralın Gururu', 'i-ntihar-kralin-gururu-mustafa-ozdemir-palu-vgxmq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir kraldım,

Sen bir fakir.

Tebdil-i kıyafet ettim sana geldim,

Kollarına otağ kurdum;

Sandım ki seni feşettim.

Pranga oldu kolların farkettim

Ve bir kral tuzağa düştü.

Gururludur krallar 

Onların esareti uzun sürmez.

Bu anlar içindir parmaklarındaki yüzük.

Ve birazdan ben de yüzüğümün kapağını açacağım,

Sonsuzluğa şarkılarımı söyleyeceğim.

Bugün yeni bir tarih yazılıyor,

Benden sonraki sevgililer 

Banklarda kralın gururu''nu okuyor

Dolu gözlerle bakire ergene kapanıyor

Bugün yeni bir tarih yazılıyor.', 'Ben bir kraldım, Sen bir fakir. Tebdil-i kıyafet ettim sana geldim, Kollarına otağ kurdum; Sandım ki seni feşettim. Pranga oldu kolların far...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özdemir Palu']::text[], 8.5, '{"poet":"Mustafa Özdemir Palu","poet_slug":"mustafa-ozdemir-palu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/intihar-kralin-gururu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-mustafa-ozdemir-palu-76o5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün gökten,

Bir yıldızın kayışına

Şahit olursan eğer

Bil ki,

Bu,

Yalnızlığımın son ihtişamıdır.', 'Bugün gökten, Bir yıldızın kayışına Şahit olursan eğer Bil ki, Bu, Yalnızlığımın son ihtişamıdır....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özdemir Palu']::text[], 8.5, '{"poet":"Mustafa Özdemir Palu","poet_slug":"mustafa-ozdemir-palu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-mustafa-ozdemir-palu-lkuon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırtına kalbimin kırık kapılarında çığlıklar savururken

Hayat beni mağlup edenler arasına yerleştirdi,

Acılar bir sel gibi üstüme hücum ederken

Bulutlar da yıldızları silip süpürmüşlerdi.

Uyan aşk uyan,

İçimdeki kıvılcımla şömineyi ateşle.

Ve sen ey sevgilim,

Başını göğsüme yasla da

Şu isimsiz şarkıyı dinle.', 'Fırtına kalbimin kırık kapılarında çığlıklar savururken Hayat beni mağlup edenler arasına yerleştirdi, Acılar bir sel gibi üstüme hücum eder...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özdemir Palu']::text[], 8.5, '{"poet":"Mustafa Özdemir Palu","poet_slug":"mustafa-ozdemir-palu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Gölgen', 'dus-golgen-dus-golgesi-m7dhp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler göründüğü gibi değil

Aşkın savruk tortusundayım..

Penceremin şarkısı yağmursu

Hüzün almış beni

Sensizliğe

Sevdan uzakta kalır

Beni  yanına al..

Uyumak istiyorum

Düş gölgende', 'Geceler göründüğü gibi değil Aşkın savruk tortusundayım.. Penceremin şarkısı yağmursu Hüzün almış beni Sensizliğe Sevdan uzakta kalır Beni  ...', ARRAY['Türk Edebiyatı','Şiir','Düş Gölgesi']::text[], 8.5, '{"poet":"Düş Gölgesi","poet_slug":"dus-golgesi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dus-golgen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskele', 'i-skele-abdullah-yildirim-2-1azeo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'son bir şarkı dinleyeyim şimdi.

düşlerimin üstüne, bir bardak su içer gibi.

geceyi mi beklesem?

yoksa şimdi mi içsem bu şarabı?

şarap içip sarhoş olsam,

baharın geleceğini düşleyip;

ağaç gölgelerinden uykular çalsam,

mehtaba tyatırıp gözlerimi;

yıldızlarımı kaydırsam...

hüzün hiç yakışmasa yüzüme o akşam!

bir iskalede yine 

şarabımdan içip

düşlerimin üstüne bir bardak su içer gibi

son şarkımı dinlesem.

gece, bütün sokakları dolaşıp 

şehrin gece bekçilerini dövsem..

sonra, belki elime kağıt kalem geçer

yine böyle yalnız kalır,

yine böyle

saçmalarım', 'son bir şarkı dinleyeyim şimdi. düşlerimin üstüne, bir bardak su içer gibi. geceyi mi beklesem? yoksa şimdi mi içsem bu şarabı? şarap içip s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldırım 2']::text[], 8.5, '{"poet":"Abdullah Yıldırım 2","poet_slug":"abdullah-yildirim-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iskele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-sair-bera-46ftl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana bakmak güzeldi

ve seninle olan bir yarını özlemek 

ne etsiz çiğköfte tadı unutulur 

nede gözlerine bakarken soğuttuğum tadı çayımın

senle olmak güzeldi 

herşeyden güzelide 

tarihin o demine bir anı istiflemek

___________(', 'sana bakmak güzeldi ve seninle olan bir yarını özlemek  ne etsiz çiğköfte tadı unutulur  nede gözlerine bakarken soğuttuğum tadı çayımın sen...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/o-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarını Merak', 'yarini-merak-sair-bera-1iopy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tercihler dünyası karıştıkça

tecrubeler dünyamda bir filiz bitiverdi

yarını görmenin mümkün olması için 

düne at gözlüğüyle bakmamak yeterdi', 'tercihler dünyası karıştıkça tecrubeler dünyamda bir filiz bitiverdi yarını görmenin mümkün olması için  düne at gözlüğüyle bakmamak yeterdi...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yarini-merak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Sen', 'once-sen-sair-bera-4hejq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'önce sen dedikçe sonra ben bittim 

kazanmaya uzattığım ellerimi 

bir kalemde,umarız ve tutarsızca

silkeleyip atıverdin,

kimbilir belkide haklıydın

ama yinede;

sevgiler narkozda oldukça 

senin canın sağolsun

gözlerini açmaya izin vermediğin sözlerim

sesini duyuramadıkça da 

benim sabrım sağolsun', 'önce sen dedikçe sonra ben bittim  kazanmaya uzattığım ellerimi  bir kalemde,umarız ve tutarsızca silkeleyip atıverdin, kimbilir belkide hak...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/once-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamalısın', 'anlamalisin-sair-bera-tn0bm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her dünden büyük izler taşımalısın 

günü bugün gibi değil yarın diye yaşamalısın

ve her düne baktığında hem kaçırdıklarına 

hemde yakalayıpta elinde parçaladıklarına 

ağlamalısın

çünkü ağlayabilirsen anlayabilirsin', 'her dünden büyük izler taşımalısın  günü bugün gibi değil yarın diye yaşamalısın ve her düne baktığında hem kaçırdıklarına  hemde yakalayıpt...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlamalisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Benim', 'i-ste-benim-i-brahim-torun-wjd18', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Laleler sümbüller açtığı zaman

Bir solmuş gül görsen işte o benim

Bülbüller şakıyıp öttüğü zaman

Bir susmuş dil görsen işte o benim

Suların çağlayıp aktığı yerde

Martıların kanat çırptığı yerde

Boynu bükük biri varsa sahilde

Terkedilen garip işte o benim

Kader tuzak kurmuş gittiği yere

Doğduğuna pişman etmiş bin kere

Dert yüklemiş herkes göz göre göre

Bir yolcu görürsen işte o benim

Zehir olmuş kadre kadre günleri

Ayrılığı atmış kör düğümleri

Felek çepe çevre sarmış her yeri

Bir mahkum görürsen işte o benim...', 'Laleler sümbüller açtığı zaman Bir solmuş gül görsen işte o benim Bülbüller şakıyıp öttüğü zaman Bir susmuş dil görsen işte o benim Suların ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı gül', 'kirmizi-gul-ali-kartal-na53u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana kırmızı gülü verdiğimde

aşkımızın

sembolü olarak saklamıştın

ya eğer

ben de aşkının semboli isem

o zaman

demektir ki

aynı kader paylaşılmış

kırmızı gülle

kader arkadaşımı geri yolla', 'Sana kırmızı gülü verdiğimde aşkımızın sembolü olarak saklamıştın ya eğer ben de aşkının semboli isem o zaman demektir ki aynı kader paylaşı...', ARRAY['Türk Edebiyatı','Şiir','Ali Kartal']::text[], 8.5, '{"poet":"Ali Kartal","poet_slug":"ali-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirmizi-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki', 'bil-ki-ali-kartal-jfyjb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'soğuk

bir kış gününde

tir tir titrerken

güneş tüm sıcaklığıyla

görünüp seni ısıtırsa

bi ki

o güneş benim

sıcak

bir yaz gününde

güneş tüm hararetiyle

seni bunaltırken

o an güneş

bir bulutla örtünüp

gölge oluşursa

bil ki

o bulut benim.

evinde yalnızken

yalnızlığın tüm kasveti

üzerine çökmüşken

o an telefonun çalıp

en sevdiğin 

dostun ararsa

bil ki

arattıran benim', 'soğuk bir kış gününde tir tir titrerken güneş tüm sıcaklığıyla görünüp seni ısıtırsa bi ki o güneş benim sıcak bir yaz gününde güneş tüm har...', ARRAY['Türk Edebiyatı','Şiir','Ali Kartal']::text[], 8.5, '{"poet":"Ali Kartal","poet_slug":"ali-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bil-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batkema', 'batkema-atilla-gokhan-uz-ffrkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sonunda biz de ayrıldık 

gardaşlık...

verilmiş sözümüz vardı

"Görüşürüz"dü vedamız

olmadı... 

kara lekeli ak yüzlü 

bir kağıttı beklediğim 

gelmedi...

ölüyü vurdular gardaş

biz öyle ayrıldık...

yele tutulmuş Semerkant

kolu kanadı kırılmış

yoksa, yoksa bizi

o yel mi savurdu dersin

kalbin benimle bilirim

gözlerim neylesin

oralar nasıl gardaşlık

bulunduğun şehir...

haber sızmaz duvarlara

anılarımızı bıraktık

biz öyle ayrıldık...', 'sonunda biz de ayrıldık  gardaşlık... verilmiş sözümüz vardı "Görüşürüz"dü vedamız olmadı...  kara lekeli ak yüzlü  bir kağıttı beklediğim  ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gökhan Uz']::text[], 8.5, '{"poet":"Atilla Gökhan Uz","poet_slug":"atilla-gokhan-uz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/batkema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-atilla-abrek-iqmbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hani yerini göstereyim desem

yumruk kadardır

belki kızarsın

                      diye 

açamam göğsümün sol yarısın

   2000', 'hani yerini göstereyim desem yumruk kadardır belki kızarsın                       diye  açamam göğsümün sol yarısın    2000...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/korku-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-atilla-abrek-al5j9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün herkes daha gri

havada keskin festival aymazlığı

Ve yarım bir yunan şarkısı kulaklarımda

caddeler, meydanlar,balonlar yok

Bir ben,bir yalnızlıgım,birde kendim

oturup ortasında ruletin

dönen topu seyrediyoruz nedense.

Kendim bana kızıyor, diyemem şundan

ama bende bir suçlu küfürbazlığı,

Yalnızlık iyi olmadığını ileri sürüyor 

keskin gözlerinde hardal kokusu

                2000', 'Bugün herkes daha gri havada keskin festival aymazlığı Ve yarım bir yunan şarkısı kulaklarımda caddeler, meydanlar,balonlar yok Bir ben,bir ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-atilla-abrek-yvjhp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni haykırdım kaleme

cevap bardaktan geldi

korktum

seni boguldum denizde

adını söyledim korkuya

besmele niyetine.

Ben en çok senden nefret ettim

bana bir sigara içmedin,

külünü bana tutmadın,

fal diye.

seni solumadım ya 

tembel gülüşüm ondan.

         2000', 'seni haykırdım kaleme cevap bardaktan geldi korktum seni boguldum denizde adını söyledim korkuya besmele niyetine. Ben en çok senden nefret ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Abrek']::text[], 8.5, '{"poet":"Atilla Abrek","poet_slug":"atilla-abrek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sitem-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Ninni', 'olume-ninni-lokman-tekin-kx31u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz bitti...

Mavi suratı göçtü

Kosmosun bahar sancılarına çağın

Gülden ağladı...

Yıldızlara yalnızlık şarkılarını

Söyleten müzikler söyletildi

Aşk öldü...

Ve ben minnacık sevdasıyla ülkemin

Sancısıyla ülkemin

Karanlığın gölgesiyle süslendim

Şimdi ölüm zamanı...

                        29 Temmuz 2000 Şemdinli', 'Yaz bitti... Mavi suratı göçtü Kosmosun bahar sancılarına çağın Gülden ağladı... Yıldızlara yalnızlık şarkılarını Söyleten müzikler söyletil...', ARRAY['Türk Edebiyatı','Şiir','Lokman Tekin']::text[], 8.5, '{"poet":"Lokman Tekin","poet_slug":"lokman-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olume-ninni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşlere', 'guluslere-lokman-tekin-0bmhh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar yağmalıydı 

Üstümüze...İnceden

Kuru bir dal gibi solumalıydık düşleri

Gülüşleri...

Ve aynı akışta yüzmeliydi

Karanlığın çatlak sesi.

                      9 Eylül 2000 Şemdinli', 'Kar yağmalıydı  Üstümüze...İnceden Kuru bir dal gibi solumalıydık düşleri Gülüşleri... Ve aynı akışta yüzmeliydi Karanlığın çatlak sesi.    ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Tekin']::text[], 8.5, '{"poet":"Lokman Tekin","poet_slug":"lokman-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/guluslere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın', 'bir-kadin-haydar-demir-wltd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diyarbakır''da bir kadın öyle güzel öyle kederliki

elinde yarabandı.

dolaşıyor surların etrafında 

belliki bilmiyor yarabandının açık yaraya

birde yaralı hüzüne iyi gelmediğini.

zaten ona sorsan......

 yaralı bir aşkın yaralarını sarmak için taşıyordur', 'Diyarbakır''da bir kadın öyle güzel öyle kederliki elinde yarabandı. dolaşıyor surların etrafında  belliki bilmiyor yarabandının açık yaraya ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Demir']::text[], 8.5, '{"poet":"Haydar Demir","poet_slug":"haydar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Defa', 'bin-defa-senem-yaklav-oq1q9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözünü gözümden çektiğin an

Elini elimden çektiğin an

Bir daha gideceğin zaman...

Beni sevdiğini bir defa daha söyle...

Bakışan gözler yeter artık dursun,

Sevgiyle inleyen nağmeler sussun,

Gözyaşlarıma dur! de ne olursun,

Benim olacağını bir defa daha söyle...

Issız geceler sensiz geçer mi söyle

Nasıl terkettin vefasızca sen beni böyle

O yaşadığımız günlerle birlikte

Benim ismimle avunacağını bir defa daha söyle...

Sarılan iki çift  görürsen eğer

Bakışan iki göz görürsen eğer

Birbirini mıknatıs gibi çeken eller görürsen eğer

Beni beklediğini,

Beni özlediğini

O güzel sesinle kulağıma bin defa daha söyle...

     BİN DEFA DAHA SÖYLE...', 'Gözünü gözümden çektiğin an Elini elimden çektiğin an Bir daha gideceğin zaman... Beni sevdiğini bir defa daha söyle... Bakışan gözler yeter...', ARRAY['Türk Edebiyatı','Şiir','Senem Yaklav']::text[], 8.5, '{"poet":"Senem Yaklav","poet_slug":"senem-yaklav","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bin-defa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahperi', 'mahperi-salih-dogan-jc2h7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş çekti kızıllığını göğümüzden

Vakit akşamdır karanlık çöker

Uçar sahil kuşları bembeyaz kanatlarına  sinen akşamın esmerliğinde

Gözlerim de tuzu var hala denizin öğlenki

Saat yedi kırksekiz

Ay dede gümüş suretini sermiş serin şiltesi üstüne mavi denizin

Saat yirmibir elli

Birazdan bir mahperi çıkagelecek

Yakamozlar sarkıtarak saçlarından

Saat oniki

Deniz titreyen bir gümüş çarşaf edasında

Sakin sessiz

Saat sıfırüç

Ay sarkıyor penceremden

rüzgarın ılık nefesi

Öpüşlerden bir gül düşürüyor

Dudaklarıma bahardan

Evhamlarım gelip geçiyor

kıyısından aklımın

serseri

saat sıfır dört

eylül gözlerin

sanki ırmak yorgunu

sabah !

sabah

bir gül gibi açılıyor kırlgan ve dokunaklı

ağarıyor ortalık

saat sıfır beş

birazdan gün kirpiklerimde oynaşır

sarı duvardan sarkan eflatun

begonyalar arasından

ta 

alanya kalesinden

içimize dolacak

dün gibi

saat altı.....', 'Güneş çekti kızıllığını göğümüzden Vakit akşamdır karanlık çöker Uçar sahil kuşları bembeyaz kanatlarına  sinen akşamın esmerliğinde Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Salih Doğan']::text[], 8.5, '{"poet":"Salih Doğan","poet_slug":"salih-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mahperi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şunu Unutma', 'sunu-unutma-i-brahim-torun-mbi51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiğini nasıl anlarsın?

Duygularını nasıl dile getirebilirsin?

Sevdiğini söyleyebilirmisin suskun dudaklara,

Dinlediğiniz şarkıyı unutmazmısın?

Hayalini kurduğunuz evinizin önünden geçermisiniz?

Birgün geri dönecek diye beklermisiniz?

Unuttum sanarak eğlenebilirmisin, gülebilirmisin,

mavi gökyüzüne karşı,

Hiç canından çok, özledinmi onu görmeyi?

Ellerinden tutup seni seviyorum diyebilmeyi?

Özledinmi....

Biliyorum yine benim varlığımdan habersiz,

mutlusun sen...

Ama bilemezsin ki bu şiiri yazarken,

Aklıma her geldiğinde...

Göz yaşlarım amansız bir hıçkırıklara boğulur...

Çünkü seni görmeyi özlemişlerdir,

Ne kadarda bana uzak olacağını bilsemde,

Sen şunu unutma...

SENİ SEVİYORUM!', 'Sevdiğini nasıl anlarsın? Duygularını nasıl dile getirebilirsin? Sevdiğini söyleyebilirmisin suskun dudaklara, Dinlediğiniz şarkıyı unutmazm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sunu-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ne Yaparım', 'sensiz-ne-yaparim-ramazan-okyay-r6bpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'S  ensiz ne yaparım sevdiğim?

 E  llerini tutmayı,gözlerine bakmayı

 N  ur yüzünü sevmeyi,saçlarını okşamayı

 S  en olmadan hayal etmek, ağlatmazmı beni?

 İ  çime derin sancılar saplanmazmı?

 Z  amanım geçermi,gece sabah ile kucaklaşırmı?

 N  asıl gülebilirimki aşkısı,

 E  n büyük mutluluğum olan ''SEN'' olmadan ?

 Y  anlızlığımı,sevgimi peylaştığım canım,

 A  ğladığımda,gözyaşımı silmek isteyen bebeğim,

 P  arlayan güneşim,içimi ısıtanım,

 A  nlatamadığım sevgimin sahibi,

 R  üyalarımı süsleyen meleğim,

 I  lık ılık yüreğime esen sevgi rüzgarım,

 M  uhtaç olduğum;nasıl gülerim ''SEN'' olmadan?

 S  onbahar olmazmı her mevsimim?

 E  n kötü günlerimi yaşamammı?

 V  erebilirmi birbaşkası senin sevgini?

 D  uyabilirmiyim engüzel sevgi sözcüklerini?

 İ  çime sinermi,girermi başka sevgi;

 G  önlüm kabul edermi?

 İ  çimi yüreğimi,beni heyecanlandırırmı?

 M  utlu olurmuyum ''BUSE''M'' sen olmadan?', 'S  ensiz ne yaparım sevdiğim?  E  llerini tutmayı,gözlerine bakmayı  N  ur yüzünü sevmeyi,saçlarını okşamayı  S  en olmadan hayal etmek, ağl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Okyay']::text[], 8.5, '{"poet":"Ramazan Okyay","poet_slug":"ramazan-okyay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sensiz-ne-yaparim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-semra-ulker-myrs4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başını cama dayama öyle.

Dalma ağlama aşk bu 

Mahveder insanı mesutken 

Bak ben ağlıyormuyum 

Seni ve her şeyi kaybetmişken', 'Başını cama dayama öyle. Dalma ağlama aşk bu  Mahveder insanı mesutken  Bak ben ağlıyormuyum  Seni ve her şeyi kaybetmişken...', ARRAY['Türk Edebiyatı','Şiir','Semra Ülker']::text[], 8.5, '{"poet":"Semra Ülker","poet_slug":"semra-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oylesine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayserili Olmak', 'kayserili-olmak-recep-calkaner-6siwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zorlukları aşmak için,

Kayserili olmak yeter.

Başarıya koşmak için 

Kayserili olmak yeter.

Kıvrak zekâ, fikir için

Soylu sevda, zikir için 

Yaratana şükür için 

Kayserili olmak yeter.

En güzel bir üretici 

Hesaplı bir tüketici

Olmak için yönetici

Kayserili olmak yeter.

Çalışkanlık ana hatta 

Ustadır her zanaatta 

Kazanç bulur kanaatte 

Kayserili olmak yeter.

Vardır sohbetinde hoşluk

İş ehlidir yapmaz boşluk

Olmasa da okumuşluk

Kayserili olmak yeter.', 'Zorlukları aşmak için, Kayserili olmak yeter. Başarıya koşmak için  Kayserili olmak yeter. Kıvrak zekâ, fikir için Soylu sevda, zikir için  ...', ARRAY['Türk Edebiyatı','Şiir','Recep Çalkaner']::text[], 8.5, '{"poet":"Recep Çalkaner","poet_slug":"recep-calkaner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kayserili-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş', 'tas-burak-terzi-id2u4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Okadar  uzakmıyız birbirimize.

Seslensen  ey verirmisiniz.

Birdaha dolarmı kadehlerimiz,

mezesi muhabbet rakı sofralarında.

Niye illaki son randevu musallataşında.', 'Okadar  uzakmıyız birbirimize. Seslensen  ey verirmisiniz. Birdaha dolarmı kadehlerimiz, mezesi muhabbet rakı sofralarında. Niye illaki son ...', ARRAY['Türk Edebiyatı','Şiir','Burak Terzi']::text[], 8.5, '{"poet":"Burak Terzi","poet_slug":"burak-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Buyum', 'ben-buyum-recep-calkaner-9418h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapılarak boş hayale,

Benzemek istemem sele,

Beni seveni severim,

O,insan olmasa bile.

Bir tebessüm bana sevinç,

Kaş çatılsa olurum linç,

Beni hiçe sayan varsa,

Benim için o dünden hiç.

Hakkı severim, Hak yemem

Haksızlığa boyun eğmem,

Gözümün bebeği olsa,

Beni sevmiyorsa,sevmem...

                         			 1970', 'Kapılarak boş hayale, Benzemek istemem sele, Beni seveni severim, O,insan olmasa bile. Bir tebessüm bana sevinç, Kaş çatılsa olurum linç, Be...', ARRAY['Türk Edebiyatı','Şiir','Recep Çalkaner']::text[], 8.5, '{"poet":"Recep Çalkaner","poet_slug":"recep-calkaner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-buyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'erciyes', 'erciyes-recep-calkaner-q8rd9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toroslar’dan gelir suyun,

Şifa vericidir suyun,

Aman dinlemez soğuğun,

Ayaz kaynağı Erciyes.

Ağustosta olur karın,

Nedendir bitmez efkãrın,

Bulutlar mı senin yãrin,

Sarar başını Erciyes.

Akıllar ermez yaşına,

Kuşlar konamaz başına,

Senin mağrur duruşuna,

Bakan ürperir Erciyes.

Önün kartınlıktır senin ,

Derde derman olur seyrin,

Suyu senden gelir şehrin,

Kar’ın yatağı Erciyes.

Ne güzel yaratmış tanrı,

Bilmiyorum eşin var mı ?

Senin konuğun hep kar mı?

Baharın gelmez Erciyes.', 'Toroslar’dan gelir suyun, Şifa vericidir suyun, Aman dinlemez soğuğun, Ayaz kaynağı Erciyes. Ağustosta olur karın, Nedendir bitmez efkãrın, ...', ARRAY['Türk Edebiyatı','Şiir','Recep Çalkaner']::text[], 8.5, '{"poet":"Recep Çalkaner","poet_slug":"recep-calkaner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erciyes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayseri', 'kayseri-recep-calkaner-09rto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başına takılı taçtır Erciyes

Güzeller güzeli ilim KAYSERİ,

Cana candır Tekir’in de tek nefes,

Tarifine dönmez dilim KAYSERİ.

Camilerin kucak açar göklere,

Sanayi’in hizmet sunar kentlere,

Ticaretin şöhret salmış yurtlara,

Sende öğrenilir ilim KAYSERİ.

Payı büyük eserlerde SİNAN’ın,

Şifa da eli var İBN-İ SİNA’nın,

Nakış, nakış işlenmiştir her yanın,

Ustaca dokunmuş kilim KAYSERİ.

Sen çekersin ancak garipler kahrı,

Erciyes’tir suyun menbağı, nehri,

Ulema yatağı, yatırlar şehri,

Gönlümün sevdası gülüm KAYSERİ.          

					1996', 'Başına takılı taçtır Erciyes Güzeller güzeli ilim KAYSERİ, Cana candır Tekir’in de tek nefes, Tarifine dönmez dilim KAYSERİ. Camilerin kucak...', ARRAY['Türk Edebiyatı','Şiir','Recep Çalkaner']::text[], 8.5, '{"poet":"Recep Çalkaner","poet_slug":"recep-calkaner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kayseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harami', 'harami-i-hsan-isik-tp6ox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Atasoy Müftüoğlu için-

Nasıl oldu bilmedim çıktım kendi yoluma

Bırakıp gidiyorken övdüğüm bahçeleri

Geceydi vakit, kuytuydu dünya

Bir haramiydim kılıcı kanlı

Yol boyu akıttım kendi kanımı

Değmedi dedim bir el elime

Bu savaşta dostlar çok fena yaralandım

Bir zehirli okla kendimi vurdum kendim

Öyle bir suç işledim ki

Birkaç yüzyıldır işkencedeyim

Nereye gidersem gideyim

“Üzülme’’ demiş ya Şirazlı Hâfız 

‘’Batarsa deve dikenleri her yanına

eğer gidiyorsan Kâbe yolunda”

Bence üzül, ağla, yırt gömleğinin yakasını da

Dikenler batmış, kanıyorken ayağın,

Yolun benzemiyorsa Kâbe yoluna', '-Atasoy Müftüoğlu için- Nasıl oldu bilmedim çıktım kendi yoluma Bırakıp gidiyorken övdüğüm bahçeleri Geceydi vakit, kuytuydu dünya Bir haram...', ARRAY['Türk Edebiyatı','Şiir','İhsan Işık']::text[], 8.5, '{"poet":"İhsan Işık","poet_slug":"i-hsan-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/harami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar', 'yagmurlar-mehmet-arif-kurdoglu-93ovw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En mutlu olduğum günler

Yaz yağmurlarının yağdığı günlerdi

Beni ben yapan ,

Seni benden alan

Yokluğunda avare avare dolaştığım

Varlığında kanatlanıp havalandığım

Yağmurların yağdığı günlerdi...

Yağmurla gelen

Yağmurla giden sendin ,

Seni bekleyen bendim,  hep bendim

Yağmurlara sevinen,

Yağmurlara kızan, öfke saçan bendim

Seni aldılar benden

Artık yağmur yağmıyor...', 'En mutlu olduğum günler Yaz yağmurlarının yağdığı günlerdi Beni ben yapan , Seni benden alan Yokluğunda avare avare dolaştığım Varlığında ka...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Arif Kurdoğlu']::text[], 8.5, '{"poet":"Mehmet Arif Kurdoğlu","poet_slug":"mehmet-arif-kurdoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmurlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekim Yağmurları', 'ekim-yagmurlari-burcu-tezel-k43v2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böyle mi sever insanı insan?

Böyle mi coşar içi?

Bu kadar güzel mi yağardı 

Her ekim bu yağmurlar?

Yoksa gözlerinden bir ihtimal sezdiğim için mi?', 'Böyle mi sever insanı insan? Böyle mi coşar içi? Bu kadar güzel mi yağardı  Her ekim bu yağmurlar? Yoksa gözlerinden bir ihtimal sezdiğim iç...', ARRAY['Türk Edebiyatı','Şiir','Burcu Tezel']::text[], 8.5, '{"poet":"Burcu Tezel","poet_slug":"burcu-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ekim-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen', 'gocmen-burcu-tezel-h4p5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vurursa tan vurur son darbeyi geceme

Tütün ciğerimi daha fazla delemez

Ölmez sağ çıkarsam 

Bu gecenin de altından

Ah!Bilirim aslında

Şu göçmen kuşlara değmez.', 'Vurursa tan vurur son darbeyi geceme Tütün ciğerimi daha fazla delemez Ölmez sağ çıkarsam  Bu gecenin de altından Ah!Bilirim aslında Şu göçm...', ARRAY['Türk Edebiyatı','Şiir','Burcu Tezel']::text[], 8.5, '{"poet":"Burcu Tezel","poet_slug":"burcu-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gocmen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-burcu-tezel-nm3dm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz geçiyorum,

Büyü bozuluyor.

Gözlerimi kamaştırıyor güneş,

Gülüyorum.

Sevmediğim şehre

Sevdiğimi içimde götürüyorum.

Şehir deniz oluyor artık

Deniz bir başka mavi

Ve gülüşün bambaşka bir deniz...

Sevmek ne güzel seni...

Seninle,

Denizi,güneşi ve yıprattığımız şu şehri

Herşey sihirli bir dokunuşla sanki

Yeniden yaratılıyor gözümde,

Senin ışıldayan sesinle...

Deniz geçiyorum,

Büyü çözülüyor.

Yeniden sevmeye başlıyorum dünyayı

Ve en çok seni

O''nun içinde...', 'Deniz geçiyorum, Büyü bozuluyor. Gözlerimi kamaştırıyor güneş, Gülüyorum. Sevmediğim şehre Sevdiğimi içimde götürüyorum. Şehir deniz oluyor ...', ARRAY['Türk Edebiyatı','Şiir','Burcu Tezel']::text[], 8.5, '{"poet":"Burcu Tezel","poet_slug":"burcu-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/buyu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Pencerenin Arkasından Bakıyorum Sana', 'bir-pencerenin-arkasindan-bakiyorum-sana-i-rfan-mutluer-y71lv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir pencerenin arkasından bakıyorum sana

Perdeyi hafif aralıyarak

Buğulu camlar arasında.

Önce silüetini çiziyorum camlara

Gözlerini, burnunu,

Dudaklarını, yanaklarını

Ve saçlarını işliyorum 

Buğulara...

Bir pencerenin arkasından bakıyorum sana.

Bir pencerenin arkasından bakıyorum sana

Gözlerimi gizleyerek,

Yüreğimde kabaran sevdalarla.

Dilimde bir buruk türkü,

Duyurmak için sevdamı sana

Bir pencerenin arkasından bakıyorum

Geçmediğin sokaklara.', 'Bir pencerenin arkasından bakıyorum sana Perdeyi hafif aralıyarak Buğulu camlar arasında. Önce silüetini çiziyorum camlara Gözlerini, burnun...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-pencerenin-arkasindan-bakiyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamız', 'sevdamiz-i-rfan-mutluer-s4ajm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdamız su gibi berrak

Sevdamız bıçak gibi keskin

Sevdamız ana sütü gibi temiz

Sevdamız ekmek kadar helal.

Sevdamız yüreğimizde büyüyecek dağ dağ,

Sevdamız kabaracak gönüllerde.

Sevdamız bir türkü olup dillerde,

Gencecik fidanlar yetişecek

Seva türküleri söyleye söyleye.', 'Sevdamız su gibi berrak Sevdamız bıçak gibi keskin Sevdamız ana sütü gibi temiz Sevdamız ekmek kadar helal. Sevdamız yüreğimizde büyüyecek d...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salkımsöğüt', 'salkimsogut-nazim-hikmet-ran-azg14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akıyordu su

gösterip aynasında söğüt ağaçlarını.

Salkımsöğütler yıkıyordu suda saçlarını! 

Yanan yalın kılıçları çarparak söğütlere

koşuyordu kızıl atlılar güneşin battığı yere! 

Birden

bire kuş gibi

                 vurulmuş gibi

                                kanadından

yaralı bir atlı yuvarlandı atından! 

Bağırmadı,

gidenleri geri çağırmadı,

baktı yalnız dolu gözlerle

      
..........
..........', 'Akıyordu su gösterip aynasında söğüt ağaçlarını. Salkımsöğütler yıkıyordu suda saçlarını!  Yanan yalın kılıçları çarparak söğütlere koşuyord...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/salkimsogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradakinin Ölümü', 'siradakinin-olumu-nazim-hikmet-ran-koqqf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O, ne önde 

               ne arkada

               sırada 

               sıramızdaydı..
..........
..........', 'O, ne önde                 ne arkada                sırada                 sıramızdaydı.. .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siradakinin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleşiriz Sevmeye Dair', 'soylesiriz-sevmeye-dair-yakup-yilmaz-7ybjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dört günlük ömründen

Bir gününü bana ayır

Sevmeye dair söyleşir

Bakışırız eskiyi yad ile

Göçeriz altıncı kat semaya

Selam veririz Meryem oğlu İsa''ya

Nefha isteriz bengi için

Vermezse ''eyvallah'' deriz

Dört günlük ömründen

Bir gününü bana ayır

Seni sevdiğimi anlatmam için

25.01.1998,Kırım,Krasnagvardiyeski', 'Dört günlük ömründen Bir gününü bana ayır Sevmeye dair söyleşir Bakışırız eskiyi yad ile Göçeriz altıncı kat semaya Selam veririz Meryem oğl...', ARRAY['Türk Edebiyatı','Şiir','Yakup Yılmaz']::text[], 8.5, '{"poet":"Yakup Yılmaz","poet_slug":"yakup-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soylesiriz-sevmeye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-yakup-yilmaz-j4ulc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbet akşamları pek acıymış

Yeni yeni anlıyorum meğer

O yorgunluk, o zahmet, o keder

Vatanımdayken baş tacıymış

 Afyon-Evcilerli öğrencilerime

23.12.1997,Salı,Krasnagvardiyeski', 'Gurbet akşamları pek acıymış Yeni yeni anlıyorum meğer O yorgunluk, o zahmet, o keder Vatanımdayken baş tacıymış  Afyon-Evcilerli öğrenciler...', ARRAY['Türk Edebiyatı','Şiir','Yakup Yılmaz']::text[], 8.5, '{"poet":"Yakup Yılmaz","poet_slug":"yakup-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gurbet-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Gardiyanım Oldu', 'sigara-gardiyanim-oldu-yakup-yilmaz-lvo5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim garba çekilmiiş 

Bir gurbet akşamı

Mektep dönüşü...

Ağzımda sigara

''Of'' çekiyorum,

Dumanlar yükseliyor,

Kızıllığında semanın ağzımdan,

Külleri düşmüş

Pabucumun ökçesine;

Savurup atıyorum

Soğuk havada

Karlar üstüne...

Ömrümün sadaka yıllarında

Kurman zindanım,

Sigara gardiyanım oldu...

''Ciğerimin karartısı oldun hasret''

10.02.1998,Salı

Ukrayna,Kırım,Kurman Kasabası', 'Gözlerim garba çekilmiiş  Bir gurbet akşamı Mektep dönüşü... Ağzımda sigara ''Of'' çekiyorum, Dumanlar yükseliyor, Kızıllığında semanın ağzımd...', ARRAY['Türk Edebiyatı','Şiir','Yakup Yılmaz']::text[], 8.5, '{"poet":"Yakup Yılmaz","poet_slug":"yakup-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sigara-gardiyanim-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmez', 'bilmez-ferhat-aldeniz-dj5ts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrin ortasında bir ev,

evde bir oda,

odada karanlık,

karanlıkta bir küçük ışık,

ışıkta umut,

umutta yürek,

yürekte sevda,

sevdada hüzün,

hüzünde gözyaşı,

gözyaşında yanak,

yanakta öpücük,

öpücükte dudak,

dudakta bir çift söz:

-bilseydin keşke-

03/11/2000', 'Şehrin ortasında bir ev, evde bir oda, odada karanlık, karanlıkta bir küçük ışık, ışıkta umut, umutta yürek, yürekte sevda, sevdada hüzün, h...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Aldeniz']::text[], 8.5, '{"poet":"Ferhat Aldeniz","poet_slug":"ferhat-aldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşım', 'paylasim-ferhat-aldeniz-y5ccz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var olanı paylaşalım:

Umut senin olsun,

umutsuzluk benim.

Bugün senin,

dün benim.

Sevinç sende kalsın,

hüzün bende.

Işığı sen al,

karanlığı ben.

İyilikler sana gelsin,

kötülükler bana.

Geriye bir tek şey kaldı,

Sevda.

Ne sen al

         ne ben,

paylaşalım,

         ikimizin 

               olsun...

03/11/2000', 'Var olanı paylaşalım: Umut senin olsun, umutsuzluk benim. Bugün senin, dün benim. Sevinç sende kalsın, hüzün bende. Işığı sen al, karanlığı ...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Aldeniz']::text[], 8.5, '{"poet":"Ferhat Aldeniz","poet_slug":"ferhat-aldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/paylasim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aspozi', 'aspozi-levent-oguz-nwck1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aspozi''yi yaktılar

Aspozi''yi yıktılar

Güneş yalarken uykularımda

Çınar yapraklarını

Güneş ki 

Hep dolunaydı öncesi

Aydınlığın ortasındaki zifiri 

Karanlığın gölgesi

Gölgesi hasta

Çok hasta bir kadının 

Şimdilerdeki yazılmamış güncesi

Güneş ki hep dolunaydı öncesi

Aspozi''yi yaktılar

Aspozi''yi yıktılar 

Güneş yalarken uykularımda

Çınar yapraklarını', 'Aspozi''yi yaktılar Aspozi''yi yıktılar Güneş yalarken uykularımda Çınar yapraklarını Güneş ki  Hep dolunaydı öncesi Aydınlığın ortasındaki zi...', ARRAY['Türk Edebiyatı','Şiir','Levent Oğuz']::text[], 8.5, '{"poet":"Levent Oğuz","poet_slug":"levent-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aspozi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Hüzün', 'olumsuz-huzun-hakan-sengorun-r7xki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölü ışıklar içinde yüzüyor solgun karanlıklar

Uykusu var gecenin bulutlara yaslamış başını

Sana doğru akıyor zaman bir girip bir çıkıyor ruhuna

sersem bir düş görmüş gibiyiz

Anlamsız bir bakış ve bir sessizlik tüm sahip olduğumuz bu

Ne kadarını elime alabilirsem baskışlarının hepsi benimle gelecek

Seni asla saklamıyorum kendimden

Koşarken hep saçlarına takılıp düşüp ölmeyi isterdim

Şimdi saçların boynuma dolanmış bir ip

Gözlerinde bulduğum tüm renkleri kaybettim yağmurun gölesinde

Yağmuru seviyorum bana sensizliği hatırlatıyor

Yağdıkça gece daha bir derinleşiyor sanki

Tüm sokaklar birbirine düğümlenmiş

Her şey yerinde hep aynı duruyor

Renkler değiştikçe zaman geçiyor

Bir kez daha izin ver kendine kaybolup gitsin

Bir kez daha aldat kendini hüznün anlam bulsun göz yaşlarında

Sana ait tüm renkleri savur gökyüzüne düş olup dolsun geceye

Kanat rüzgarı estikçe öldürsün beni', 'Ölü ışıklar içinde yüzüyor solgun karanlıklar Uykusu var gecenin bulutlara yaslamış başını Sana doğru akıyor zaman bir girip bir çıkıyor ruh...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olumsuz-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharın Düşü', 'sonbaharin-dusu-hakan-sengorun-45q7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Döndürüyor başımı sonbahar

Unutulmuş hüznü zamanın ayaklanmış

Çok uzakta olmasa gerek yağmur

Kokusu geliyor damlaların

Yaprakları dökülmüş ağaçların kuşlar üşüyor

Nasıl bir düş bu uyandıkça başlıyor

Sensizlikten değil rüzgarda biliyor

Bazen gökyüzünün ağladığını düşünürüm yağmurda

Bazen senide düşünüyorum

Gözlerin bulutları andırıyor ve her damla gözlerinden bir parça

Gözlerine dokunabilmek için koşuyorum her yağmurda

Dokundukça bakışların saplanıyor ruhuma

Zaten bir geceyi birde gözlerini hatırlıyorum

Tüm zamanlarda yaşanmış

Kendinde değil düşlerim gecede bir yerlerde

Biliyorum çok bahsettim sana geceden

Gecede biliyor seni senin kadar

Nedir yaşatan sonbaharı umutlarmı

Ben en saf yağmurda kaybolup gidecek geceyi bekliyorum

Son bahara ve sana kadar kalmış bana

sığınarak...', 'Döndürüyor başımı sonbahar Unutulmuş hüznü zamanın ayaklanmış Çok uzakta olmasa gerek yağmur Kokusu geliyor damlaların Yaprakları dökülmüş a...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sonbaharin-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Sen', 'i-cimde-sen-deniz-tekin-97a2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde sen 



Nihal '' e 

Yine gece , yine hüzün 

Ve yine içimde sen 

Ve yine biliyormusun ? 

İçimde sen olunca hüzünde güzel ..... 

Deniz TEKİN', 'İçimde sen  Nihal '' e  Yine gece , yine hüzün  Ve yine içimde sen  Ve yine biliyormusun ?  İçimde sen olunca hüzünde güzel .....  Deniz TEKİ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Tekin']::text[], 8.5, '{"poet":"Deniz Tekin","poet_slug":"deniz-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icimde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim Olur musun?', 'esim-olur-musun-hakan-akyurt-x998e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkım;

Seni sevmek sevdaların,

Seni beklemek özlemlerin en güzeli...

Sevda bir masalsa,

Sen birtanem; 

Pamuk Prensesim olur musun benim?

Sevda bir gerçekse; 

Sen sevdiğim;

Eşim olur musun benim?', 'Aşkım; Seni sevmek sevdaların, Seni beklemek özlemlerin en güzeli... Sevda bir masalsa, Sen birtanem;  Pamuk Prensesim olur musun benim? Sev...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esim-olur-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin', 'bilesin-hakan-akyurt-rwd26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin için çarpıyor bu deli yürek,

Aniden bırakıp gitmek yok,bilesin...

Fırtınalar esiyor gönlümde artık.

Beni böyle yalnız koymak yok,bilesin....

Ömrümce mutluluk sözü verdim sana.

Tam başlamışken kaçmak yok,bilesin...

Gözlerimle aşkı yaşatacağım sana.

O ceylan gözlerini kaçırmak yok,bilesin....', 'Senin için çarpıyor bu deli yürek, Aniden bırakıp gitmek yok,bilesin... Fırtınalar esiyor gönlümde artık. Beni böyle yalnız koymak yok,biles...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen,sen,sen...', 'sen-sen-sen-hakan-uzun-8tmz4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susamak nedir bilir misin ? 

Bir güdüdür o.

Özlemek nedir bilir misin ?

Bir istektir o.

Ayrılmak nedir bilir misin ?

Sonsuza dek ayrı kalmak.

bir yandan aşk,

bir yandan kin ve nefret

hepsine sebep sen,sen,sen...', 'Susamak nedir bilir misin ?  Bir güdüdür o. Özlemek nedir bilir misin ? Bir istektir o. Ayrılmak nedir bilir misin ? Sonsuza dek ayrı kalmak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Uzun']::text[], 8.5, '{"poet":"Hakan Uzun","poet_slug":"hakan-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-sen-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Unutacaktım Seni', 'simdi-unutacaktim-seni-hakan-uzun-kb0tf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söz vermiştim anmayacaktım adini

Söz vermiştim düşünmeyecektim seni

Söz vermiştim bakmayacaktım resmine

Şimdi unutacaktım seni

	

Artık sevmeyecektim bir daha

Artık koşmayacaktım peşinden

Artık olmayacaktın dünyamda	

Simdi unutacaktım seni

Bir daha ağlamayacaktım

Bir daha uykusuz kalmayacaktım

Bir daha başımı taşlara vurmayacaktım

Simdi unutacaktım seni

	

Yine sana gelemem 

Yine arayıp soramam

Yine yokluğunla yıkılamam

Simdi unutacaktım seni

Unutup ta mutlu olacaktım

Unutup ta yeniden başlayacaktım

Unutup ta kahrolmayacaktım

Simdi unutacaktım seni

Fakat yapamadım iste

Silip atamadım bir anda

Bak yine aklımdasın hala

Şimdi unutacaktım seni', 'Söz vermiştim anmayacaktım adini Söz vermiştim düşünmeyecektim seni Söz vermiştim bakmayacaktım resmine Şimdi unutacaktım seni 	 Artık sevme...', ARRAY['Türk Edebiyatı','Şiir','Hakan Uzun']::text[], 8.5, '{"poet":"Hakan Uzun","poet_slug":"hakan-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/simdi-unutacaktim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum günüm bu gün', 'dogum-gunum-bu-gun-hakan-uzun-jtrej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğum Günüm Bugün

doğum günüm bugün

bundan 19 sene önce gelmişim dünyaya

Masummuşum o zamanlar

çocukmuşum

sevimliymişim

hatırlamıyorum ya,

çok yaramazmışım.

19 sene geçti aradan

ne diyorlar benim için bilemem

ama ben kendimi tanıyorum

başkaları bilmese de ben biliyorum

bu günde doğmuşum ben

hatırlayan çıkmadı bu günü 

benden başka

değer veren olmadı bu güne

elimden tutan yoktu bu gün

avuçlarımdan kum gibi aktı zaman

şimdi bomboş bir hayat

her tarafa yalnızlık kök salmış

bu gün zehir oldu bana

hani dün beraber güldüğümüz dostlar

hani dün beraber yediğimiz arkadaşlar

ah nerede şimdi o vefasızlar ?

yalnızım, yalnız.

sen de aramadın ey sevgili,

sen de mi unuttun

unutulmak çok kötü be arkadaş

içmek de kötü ama,

var mı başka çare

hayat acımasız

yalnızım şimdi

sen yoksun sevgili

bedenin de yok, hayalinde.

elimde sigara

resmine bakıp ağlasam mı sana

yoksa maziyi hatırlayıp 

yakınsam mı unutulduğuma

çaresizlik içinde çaresizlik

benim durumum meçhul,

belki varım belki yokum

bu günde doğmuşum ben

yarın ne olur bilinmez

sen yoktun bugün

ben benleydim

yalnızdım

yalnızım..............', 'Doğum Günüm Bugün doğum günüm bugün bundan 19 sene önce gelmişim dünyaya Masummuşum o zamanlar çocukmuşum sevimliymişim hatırlamıyorum ya, ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Uzun']::text[], 8.5, '{"poet":"Hakan Uzun","poet_slug":"hakan-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/dogum-gunum-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Olur', 'dert-olur-cevdet-dogan-kurdoglu-ag3vm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başka idi babam, bizim halimiz

Töre hale, haller bana dert olur

Yadı söyler oldu bizim dilimiz

Ezgim tele, teller bana dert olur

Geldik yaban ele, bakın ne olduk

Ne aradık, neyi umduk, ne bulduk

Bal yerine kovanlarda, zehrolduk

Kovan bala, ballar bana dert olur

Ehl-i iman, müslümandık kardaşım

Türklük vardı, dimdik dururdu başım

Şimdi coşkun sele döndü gözyaşım

Derya sele, seller bana dert olur

İman ile, irfan ile açarken

Türk-İslamın nefesini saçarken

Şimdi bülbüllerim, bağdan kaçarken

Bağban güle, güller bana dert olur

Türklük şuurunda, İslam mihengi

Biri birine uyar iken ahengi

Alı hariç, sarı, siyah her rengi

Renkler ala, allar bana dert olur

KÜRDOĞLU ki feryat figan naralı

Parsel  parsel olmuş, gönlü yaralı

Namussuz çok, namuslusu paralı

PARA KULA, KULLAR BANA DERT OLUR

24.03.1992.. Campbelltown/ AVUSTURALYA', 'Başka idi babam, bizim halimiz Töre hale, haller bana dert olur Yadı söyler oldu bizim dilimiz Ezgim tele, teller bana dert olur Geldik yaba...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Doğan Kürdoğlu']::text[], 8.5, '{"poet":"Cevdet Doğan Kürdoğlu","poet_slug":"cevdet-dogan-kurdoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dert-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşseli', 'dusseli-hakan-sengorun-hms78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulduğum karanlıkları biriktirdim rengarenk bir ölüme

Gecenin bitmesine izin vermedim hapsettim düşlerime ellerini

Hiç gitmedin biliyorsun hep konuştum seninle sen uzakta olduğunu zannederken

Ben kaybolan düşlerimi aradım gözlerinde kaybolduğumun farkına varmadan

Çiçekler ve hüzün bulanık bir renge boyanmış zaman

Düşlerin renkleri solmuş kapatma gözlerini geceye adanmış ışık

Kendine ait değilsin farklı düşlerde aynı renklere boyadık geceyi hepsi bu

Şimdi ulaşman gereken bir sen var unuttuğun tüm hikayelerde hepsini tekrar tekrar dinlediğinde farklı zannediyorsun

Nasıl bir sen bu herşeyin içinde hiçbirşey

Hiç aldatmadı düşler geceyi neydiki sen dediğim şey unuttum

Oysa düşlerimi unutmam ben

Senin için diyorum sen diyorum sana kendinde bulamadığın sana dokunuyorumn

Bir şey ummadım nasılsa biliyorum

Senden daha fazlasını görüyorum çünkü gökyüzündeyim

DÜŞLEDİM GELDİN DÜŞÜNDÜM GİTTİN...', 'Bulduğum karanlıkları biriktirdim rengarenk bir ölüme Gecenin bitmesine izin vermedim hapsettim düşlerime ellerini Hiç gitmedin biliyorsun h...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dusseli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-hakan-sengorun-yppc2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam için söylenecek birşeyleri olmalı zamanın

Böyle anlamsız ve belirsiz bakmamalı gökyüzüne

Nedir rüzgarın anlatmak istediği

Üşüyen ve suskun benliklerimize

Yapabilirsin biliyorum ruhunu temizle

Bana değil kendine gülümse

Eğer istersen bir parça düş ayırır gece sana

Susmak konuşulacak her şey bittiğindenmi

Söylenecek söz bulamadığındanmı

Yaşayarak öğreniriz hüznü ve sahip çıkarız bizim olan her şeye

Birbirimize sahip çıkmadık hiç hiç birbirimizin olmadımı zaman

Yoksa hiç kendimiz olmadıkmı

Sesinle yankılanan biraz sen biraz sonsuzluktu

Benim hiç sahip olmadığım ama hep ihtiyacım olan son

Bize ayrılmış zamanın her anında sorgulanmaktan korkan yanılgılardı gerçeği çağıran

Zor değildi hiçbir zaman bu yaşattı bencilliğimizi 

Zor değildi ölüm bu korkuttu bizi

Sen hiç rüzgara bağırdınmı içindekileri en uç noktasına kadar

Peki bulutların sana gülümseyişlerine karşılık verdinmi hiç

ÖRNEĞİN:Bakışlarıylada sevebilir bir insan uçan sevimli bir kuşu anlıkta olsa bulabilir içindeki sevgiyi sevgi var olmaz hep vardır kim yok etti ki onu yüzyıllardır...', 'Yaşam için söylenecek birşeyleri olmalı zamanın Böyle anlamsız ve belirsiz bakmamalı gökyüzüne Nedir rüzgarın anlatmak istediği Üşüyen ve su...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kayip-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-hakan-sengorun-gbvcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Süzülürken  karanlık gökyüzünün üstüne

Ben gözlerinden izliyorum herşeyi

Geceye dair tüm düşleri görüyorum

SENSİZKEN BEN AY IŞIĞINDAN İZLİYORUM SENİ...

Kapladığında karanlık tüm bulutları

Gözlerin ateş yakıyor her şeyi

 Sonsuz kılıyorsun geceyi 

SENSİZKEN BEN AY IŞIĞINDAN İZLİYORUM SENİ...', 'Süzülürken  karanlık gökyüzünün üstüne Ben gözlerinden izliyorum herşeyi Geceye dair tüm düşleri görüyorum SENSİZKEN BEN AY IŞIĞINDAN İZLİYO...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-ali-mesut-haydaroglu-ns4u9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bahar mevsimi

Çiçeğin dala dolandığı gün

Sevdim seni

Nice hazanlar

Nice zemheriler geçti

Unutmadım seni', 'Bir bahar mevsimi Çiçeğin dala dolandığı gün Sevdim seni Nice hazanlar Nice zemheriler geçti Unutmadım seni...', ARRAY['Türk Edebiyatı','Şiir','Ali Mesut Haydaroğlu']::text[], 8.5, '{"poet":"Ali Mesut Haydaroğlu","poet_slug":"ali-mesut-haydaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bahar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemeç', 'donemec-omer-asim-6qy13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Şiir''de bir güneştir, ruhları aydınlatan''

Ütopik bir efsaneydi taşıdığımız

oysa gözlerimizde at gözlükleri

ağzımıza vurduğumuz gemle

oyalandık durduk

seneler kovaladı seneleri

Artık boşalıp dizgin''lerinden güvercinler

boyunlarına vurulan

Gülistana kanatlanır bir kazip ertesi

öncenin bahar''sız zemheri iklim''inden

kurtulup şair ıslatan bulut''lar

yedi coğrafya''dan buhar alıp 

bir derya''yı besler ki

Yunus''la Parina koyun koyuna

Güneş''e kanat çırpan martı''lar

 biliyorum üsküdar''ı geçtiniz

bir ümit''tir ardınızdan

Kezban''ın gözleriyle çağla''ların düet''i

dağarcığımda geliyorum

çok çok merkür''de tıkanırım

bulut''ları geçeyim hele bir

bir can simidi atarsınız zahir...', '''Şiir''de bir güneştir, ruhları aydınlatan'' Ütopik bir efsaneydi taşıdığımız oysa gözlerimizde at gözlükleri ağzımıza vurduğumuz gemle oyalan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Asım']::text[], 8.5, '{"poet":"Ömer Asım","poet_slug":"omer-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/donemec-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık ve Korku', 'karanlik-ve-korku-baris-tekin-nz4ow', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni ürkütecek geçtiğin yollar.

Arkandan gelecek ayak seslerim.

Sarınca vücudunu belirsiz kollar.

Enseni yakacak ateş nefesim.

Kimsesiz odanda kış geceleri.

İçin ürperdiyi anlar.

Beni an de,ki odur sarsan pencereleri.

De,ki odur rüzgar deyil odur haykıran.

Göğsümden havaya katığımzehir.

Solduracak bir gül gibi ömrünü.

Kaçıp dolaşsanda.

Sen şehir şehir.

Bana kalacaksın ömrünün SON GÜNÜ

Ölürsün... kapanır yolar geriye.

Ben mezarla sırdaş olurum beklerim.

Toprağında ateş olur beklerim.', 'Seni ürkütecek geçtiğin yollar. Arkandan gelecek ayak seslerim. Sarınca vücudunu belirsiz kollar. Enseni yakacak ateş nefesim. Kimsesiz odan...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-ve-korku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-baris-tekin-wktmm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senden son bir dileğim 

olsaydı eğer 

göz yaşlarınla ıslanan yanaklarına 

sıcak bir buse koymak 

isterdim 

bir akşam bir rakı tadında 

yiğitçe 

aniden 

korkmadan 

beni sevmeni isterdim 

senden son bir dileğim 

olsaydı eğer 

bu 

son dileğimin olmamasını 

isterdim!!', 'senden son bir dileğim  olsaydı eğer  göz yaşlarınla ıslanan yanaklarına  sıcak bir buse koymak  isterdim  bir akşam bir rakı tadında  yiğit...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-baris-tekin-1whkr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Öyle bir sevgi istiyorum ki'' 

Onsuzluğum da zaman 

Ölüm yarısı olsun 

''Öyle bir sevgili istiyorum ki'' 

Kalbi varlığımda 

Sevgi ve mutluluk dolsun 

Umut ışığı gözlerinde her an 

Gözlerimin enginliğinde kaybolsun.', '''Öyle bir sevgi istiyorum ki''  Onsuzluğum da zaman  Ölüm yarısı olsun  ''Öyle bir sevgili istiyorum ki''  Kalbi varlığımda  Sevgi ve mutluluk ...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim Artık', 'gidelim-artik-baris-tekin-7msv2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalk gidelim ! 

durulmaz artık. 

Bırak vursunlar, 

Gocunmayalım, vursunlar. 

Bırak yenildik sansınlar. 

Kalk uçalım ! 

Kanatsız, bir defalığına. 

Bırak gülsünler ardımızdan. 

Bırak öldük sansınlar. 

Yo otur konuşalım ! 

Yarenlerin dostluğu hatırına. 

Bırak sustuk, sindik sansınlar... 

08.04.00 

ANKARA 

 



.', 'Kalk gidelim !  durulmaz artık.  Bırak vursunlar,  Gocunmayalım, vursunlar.  Bırak yenildik sansınlar.  Kalk uçalım !  Kanatsız, bir defalığ...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gidelim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deva Gelmez,Bela Gitmez', 'deva-gelmez-bela-gitmez-mehmet-turan-yarar-bjy83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deva gelmez,bela gitmez teselli âha kalmıştır

Kulun hükmünden el çektim,karar Allah''a kalmıştır

Hayalinden de hoşnutum o yarin,kendisinden de 

Bu yüzden bence farketmez,ha gitmiştir,ha kalmıştır', 'Deva gelmez,bela gitmez teselli âha kalmıştır Kulun hükmünden el çektim,karar Allah''a kalmıştır Hayalinden de hoşnutum o yarin,kendisinden d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Turan Yarar']::text[], 8.5, '{"poet":"Mehmet Turan Yarar","poet_slug":"mehmet-turan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/deva-gelmez-bela-gitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsiz Coğrafya Aşklarına...', 'belirsiz-cografya-asklarina-basak-tunay-c3x08', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum arasıra

herincinişinde kalbimin

ve, her mutluluktan uçuşumda

neredesin?

öyle ya!

aynı şehrin sokaklarında geziniyoruz belki,

belki de bambaşka ülkelerin havasını soluyoruz

belki penceremin altından geçiyorsun

belki öyle uzaksın ki,

gün doğmamış daha bulunduğun coğrafyalara

yine de 

yağmurlar  gönderiyorum sana

bulutları geçtikleri yerlerin

aşklarıyla dolu

kuşlar gönderiyorum

sadece senin olduğun  yerlere göçen

şiirler gönderiyorum

sana dair

ve sana bir şey gönderiyorum

eline hiç geçmeyecek olan

sen yağmurda ıslanmadıkça

el sallamadıkça göçmen kuşlara

şiirlerle uçurmadıkça ruhunu

ağlamadıkça

köprüaltında donup kalmış bir

çocuğun ruhuna

         

( kasım2000/ ankara)', 'seni düşünüyorum arasıra herincinişinde kalbimin ve, her mutluluktan uçuşumda neredesin? öyle ya! aynı şehrin sokaklarında geziniyoruz belki...', ARRAY['Türk Edebiyatı','Şiir','Basak Tunay']::text[], 8.5, '{"poet":"Basak Tunay","poet_slug":"basak-tunay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/belirsiz-cografya-asklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Ettim', 'hayal-ettim-suleyman-avci-u8w1f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerini görmedim henüz

İnsan gözlerini görmeden nasıl sevdalanır böyle ?

Düşledim seni sadece,

Hayal ettim…

Hayal ettim;

Bir kumsalımız olmuş,

Gece elele yürümüşüz ıslak kumlarda,

Sen bana, ben sana

Kumsal bize dokunmuş,

Denize bakmışız birlikte,

Yıldız seçmişiz gökyüzünden kendimize.

Tenini koklamadim henüz

Insan tenini koklamadan nasıl sevdalanır böyle ?

Düşledim seni sadece,

Hayal ettim…

Hayal ettim;

Bir bahçemiz olmuş

Sen balığın yanına roka toplarken,

Ben çiçekler toplamışım,

Beyaz örtülü yemek masamıza

Karnımız aç, doymamışız bir balıkla

Doymamışız birbirimize

Sana dokunamadım henüz

İnsan dokunmadan nasıl sevdalanır böyle ?

Düşledim seni sadece,

Hayal ettim…

Hayal ettim;

Seni sadece

Ve sevdalandim.', 'Gözlerini görmedim henüz İnsan gözlerini görmeden nasıl sevdalanır böyle ? Düşledim seni sadece, Hayal ettim… Hayal ettim; Bir kumsalımız ol...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayal-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-osman-erdal-erturan-1njw5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kırmızıdutların ve çağlaların

beni çaldığında

dört yapraklı yoncanın 

bana seni getirdiğinde

seviyorum ama olmazların

şarap şişelerinde

ve köprüde

yağmurun seni benden aldığında

kendimle tanıştım

ben

30/10/2000', 'kırmızıdutların ve çağlaların beni çaldığında dört yapraklı yoncanın  bana seni getirdiğinde seviyorum ama olmazların şarap şişelerinde ve k...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/merhaba-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam Sende Saklıdır', 'sevdam-sende-saklidir-hakan-celikors-a3rd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevdam acılarda saklıdır,

giden yarin arkasından bakakalan

ve boğazında düğümlenen yumrukla

bir hoşçakal diyemeyen

sevdalının hüznünde..

ve yavrusunu şahana kaptıran

anne kuşun çaresizce çırpınan kanatlarında.

ve yorganı yıldızlar olan

o yalnız çocuğun titremesinde...

sevdam emekte saklıdır,

kızgın güneş altında tohum atan

ırgatların alın terinde

orak sallayan nasırlı ellerde.

ve göçükler altında kalan

madencinin kararmış yüzünde...

sevdam umutlarda saklıdır,

akgüvercinin kanadına binen,

sevdalının özleminde..

çeyiz sandıklarını dolduran,

köylü kızların dantellerinde.

ve en zor anında yaşamın,

maviliğe bakabilen bakışlarda...

sevdam yasaklarda saklıdır,

sözün ses olduğu alanlarda,

alın terinin hakkını arayan grevlerde.

volta atılan mapushane avlularında

ve gökyüzünü göstermeyen demir parmaklıklarda...

sevdam hüzünlerde saklıdır,

güz rüzgarlarıyla savrulan,

sararmış yapraklarda.

ilk yazın ıslaklığıyla kabaran toprağın,

o güzelim kokusunda..

ve büyük bir gürültüyle açan

ateş güllerinin tomurcuklarında....

 ve sevdam sende saklıdır gece saçlım,

senle gelen şafakların kızıllığında,

senle gelen emekte,umutlarda,

senle gelen yarınlarda

ve sende saklıdır sevdam....', 'sevdam acılarda saklıdır, giden yarin arkasından bakakalan ve boğazında düğümlenen yumrukla bir hoşçakal diyemeyen sevdalının hüznünde.. ve ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Çelikörs']::text[], 8.5, '{"poet":"Hakan Çelikörs","poet_slug":"hakan-celikors","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevdam-sende-saklidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarmısın', 'aglarmisin-ay-berk-35nde', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşlarla selam göndersem

Rüzgarla öpücük 

Ve sevdiğimi söylesem.....

Kızarmısın

Haberin olmadan çıka gelsem

Çalsam kapını

Ve ben olduğumu söylesem

Açarmısın ?

Daha olmassa bir dilenci olsam

Avuç açsam kapında

Azıcık aşk ile sevgi istesem seden

   Kovarmısın

Kahrımdan ölsem

Duysan senin için öldüğümü

Mezarımın başına gelip

Ağlarmısın... 

Ser0hat

           Ay_BerK_', 'Kuşlarla selam göndersem Rüzgarla öpücük  Ve sevdiğimi söylesem..... Kızarmısın Haberin olmadan çıka gelsem Çalsam kapını Ve ben olduğumu sö...', ARRAY['Türk Edebiyatı','Şiir','Ay Berk']::text[], 8.5, '{"poet":"Ay Berk","poet_slug":"ay-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-abdullah-turkes-6zyxz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çiçek düşünsem,sen geliyorsun aklıma.

Cıvıl cıvıl kuşları,

Yemyeşil agaçları düşünsem

Sen geliyorsun aklıma.

Gece mehtabı,ayın parlak yüzünü düşünsem

Sen geliyorsun aklıma.

Aşkı, sevdayı,yaşamayı düşünsem

Sen geliyorsun aklıma', 'Bir çiçek düşünsem,sen geliyorsun aklıma. Cıvıl cıvıl kuşları, Yemyeşil agaçları düşünsem Sen geliyorsun aklıma. Gece mehtabı,ayın parlak yü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Türkeş']::text[], 8.5, '{"poet":"Abdullah Türkeş","poet_slug":"abdullah-turkes","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-dusunmek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-abdullah-turkes-2j5co', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen her an ömrümden

Yıllar alıp götürüyor sanki,

Buna dayanmak imkansız;

Fakat öylesine bir sihirle sarıyorsunki beni...

Mecnun gibi çöllere düşsem,

Ferhat gibi dagları delsem,

Kerem gibi ateşlerde yansam,

Yinede senin için az olur biliyorum;

Çünkü seni daha, daha,daha çok seviyorum.', 'Sensiz geçen her an ömrümden Yıllar alıp götürüyor sanki, Buna dayanmak imkansız; Fakat öylesine bir sihirle sarıyorsunki beni... Mecnun gib...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Türkeş']::text[], 8.5, '{"poet":"Abdullah Türkeş","poet_slug":"abdullah-turkes","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bulsaydım Eğer', 'seni-bulsaydim-eger-caner-topuz-4l54s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bulsaydim eger!

İcimdeki çarpıntılar olurdu dev asa birer dalga

Kendim ve benligim zincirden kopan birer halka

Seni anarken ve sorarken duygularım kalkardı şaha

En boş an senle dolardi,senlen razı olurdum en aza

Seni bulsaydım eger

Bir degil,bin ömür  yetmezdi sana doymaya

Mecnun kiskanirdi rastlasaydi,sana askimla bana,

Beni ben carmiha gererdim vallahi  yangindan sana

Aşkını katık eder,saklardım her güze,yaza ve her bahara

Seni bulsaydım eger

Bagım olurdu sana,hislerimin en safı,en beyazı ve en seffafı

Seni her anış,sana her bakış en kısa sensizlik dondururdu kanımı

Aşkın kanardı bağrımda,tillahi esirgemezdim senden canımı

Taşardı benligim,coşardı yüregim,unuttururdu tüm andımı

Seni bulsaydim eger

Sonsuz bir derya,hatta bir umman olurdu sevgiden selim uğruna

Tatlı bir ateş olur,girerdim damarına,ugrardım hep yanaklarına 

Görünmez ama delinmez siper olur,billahi kafa tutardım kainata

Sana zarar vermektense,hapsederdim kendimi,zifire,karanlıga ve zindana

Seni bulsaydım eger !', 'Seni bulsaydim eger! İcimdeki çarpıntılar olurdu dev asa birer dalga Kendim ve benligim zincirden kopan birer halka Seni anarken ve sorarken...', ARRAY['Türk Edebiyatı','Şiir','Caner Topuz']::text[], 8.5, '{"poet":"Caner Topuz","poet_slug":"caner-topuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-bulsaydim-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervane', 'pervane-mehmed-kemal-0si1i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bir görüp bir yitirmek seni,

Seni bir görüp bir yitirmek,

Gür bir ormanda ayrı türden bir ağaç gibi,

Hedefine varmayan bir serseri kurşun,

Ya da bir büyük kavganın dışında kalmak,

Yatağını şaşırmış bir nehir olmak,

Bilmediği denizlere akmak ya da,

Ihlamurlar kokan bir parkın içinde

Ünlü heykeller ortasında,

Ünsüz dolaşmak ya da; 

Hiçbiri bu duygusal kederin benzeri değil,

Benzeri değil hiçbiri; 

Bir roketten uzaya atılmak,

Kocaman şaşkın adımlarla yürümek,

Adını bilmediğin gezegenlerin üstünde,

Dağların,ovaların,akarsuların üstünde,

Aklı karalı bulutların üstünde,

Egemeni olmak evrenin; 

Bir de seni bir görüp bir yitirmenin yalnızlığı.

Seni bir görüp bir yitirmek seni,

Seni bir görüp bir yitirmek,

Benzemiyor bunların hiçbirine; 

Bir bulup,

Bir yitirmeye,

Benziyor,

Sadece.', 'Seni bir görüp bir yitirmek seni, Seni bir görüp bir yitirmek, Gür bir ormanda ayrı türden bir ağaç gibi, Hedefine varmayan bir serseri kurş...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Kemal']::text[], 8.5, '{"poet":"Mehmed Kemal","poet_slug":"mehmed-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pervane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatlanmış Düşler,Tutuklu Söylemler', 'kanatlanmis-dusler-tutuklu-soylemler-caner-topuz-gskb6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanatlanmis düsler,tutuklu söylemler

sözcüklerim ifadesiz kalir,

kanatlanmis gider düslerim 

rüzgar olup çarpmak buluta,

yer olup tutmak yagmuru,

bend olup tutmak seli,

inan bir tanem 

bir hiçmis sensizligin yaninda.

Tutukluyken söylemlerim dudaklarimda

Lavlar filizleniyordu agrimda

ates bile  için için 

kesmekes,hüzünlü ve zoraki yaniyordu

sensizlik yanardaginda

bir soluk,bir nefes lazimken ,

bir daha,bin daha kavruldum yangininda,

savrulurken ciliz bir rüzgarda

sensiz kaybedilecek hiçbir sey kalmamisti

ne önümde ne ardimda

ne olurki simdi 

versem ruhumu meçhul sonsuzluga

zaten anca sigiyorum yalnizliga

gönül idama mahkum

bedende ciksa daragacina

Nedirki teslimiyet karanliga

Eger sen yoksan yanimda

Beyaz bulutlar bile artik yagmura gebe

Ateşin dumani sasirmis,tütüyor içine

Poyraz meltem zannediyor kendini

Denizin ortasinda ise içten bir selale

Sen  içimde sönemeyen bir yanardag

Solamayan tomurcuktan bir lale

Her sey anlamsiz sensiz,ben ise biçare', 'Kanatlanmis düsler,tutuklu söylemler sözcüklerim ifadesiz kalir, kanatlanmis gider düslerim  rüzgar olup çarpmak buluta, yer olup tutmak yag...', ARRAY['Türk Edebiyatı','Şiir','Caner Topuz']::text[], 8.5, '{"poet":"Caner Topuz","poet_slug":"caner-topuz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kanatlanmis-dusler-tutuklu-soylemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-emre-orkun-rj76s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden Sonra

Kaçacak yeri kalmamış

Vurmuş, öldürmüşüm İçimdeki,

Senin yaraladığın çocuğu.

Boyamışım ellerimle 

Bahtımın rengine,

Yetmemiş 

Aşkımın yanına gömmüşüm

Son resmini.

Bir can pazarında satmışım

Senden kalan virane kalbimi,

Ve anıların her köşesine dikmişim

Acılardan bir asker .

Acılar ki en sert ,

En kuytu yanımı ; 

Senimi, seni sevmemi bile

Alev alev kavurup,

Bir nefrete çeviren.', 'Senden Sonra Kaçacak yeri kalmamış Vurmuş, öldürmüşüm İçimdeki, Senin yaraladığın çocuğu. Boyamışım ellerimle  Bahtımın rengine, Yetmemiş  A...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/senden-sonra-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gibi', 'senin-gibi-emre-orkun-s8pk9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her günün son demi;

Koparırım içimdeki aşkını,

Her sabah büyür ansızın.

Ben görmemezlikden gelirim

O düşünmez, 

Vurur Senin gibi.

Vazgeçişimden sonra sevmeleri,

Yani ansızın el olduğundan beri,

Deliyim, duramam

Dönmek isterim 

Dönemem,

Bırakmaz gururumun annesi..

O bilmemezikten gelir

Ben susarım,

Konuşmam senin gibi.

Geçmişin aynası çıkınca karşıma 

Yani anımsayınca gözlerini

Korkarım, bakamam

Kırmak isterim, kıramam,

Ben sevmemezlikten gelirim

Düşünmem senin gibi.', 'Her günün son demi; Koparırım içimdeki aşkını, Her sabah büyür ansızın. Ben görmemezlikden gelirim O düşünmez,  Vurur Senin gibi. Vazgeçişim...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Gibi', 'masal-gibi-emre-orkun-f4xzm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masal gibi yaşamışız aşkı

Bir masal gibi Bertansa Sokağında.

Kah ağlayıp, kah gülmüşüz

Az tanıyıp çok sevmişiz.

Dalaşarak kötü devlere , 

Sevişerek nehirlerde

Kahramanlıklar yaratmış da

Uslanmışız ansızın.

Canımız sıkılmış yinede,

Ağaçlara yazmışız adımızı.

Ayrılık demiş, hasret demiş

Hüzünlenmişiz.', 'Masal gibi yaşamışız aşkı Bir masal gibi Bertansa Sokağında. Kah ağlayıp, kah gülmüşüz Az tanıyıp çok sevmişiz. Dalaşarak kötü devlere ,  Se...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/masal-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşim Acele', 'i-sim-acele-necip-fazil-kisakurek-70cse', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökte zamansızlık hangi noktada?

Elindeyse yıldız yıldız hecele!

Hüküm yazılıyken kara tahtada

İnsan yine çare arar ecele!

Gençlik... Gelip geçti... bir günlük süstü;

Nefsim doymamaktan dünyaya küstü.

Eser darmadağın, emek yüzüstü;

Toplayın eşyamı, işim acele!

(1972)', 'Gökte zamansızlık hangi noktada? Elindeyse yıldız yıldız hecele! Hüküm yazılıyken kara tahtada İnsan yine çare arar ecele! Gençlik... Gelip ...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/isim-acele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dövün', 'dovun-necip-fazil-kisakurek-zfy1e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben ölünce etsin dostlarım bayram;

Üstüste tam kırk gün, kırk gece düğün!

Açı doyurmaksa kabirde meram,

Yemeğim fatiha, günde beş öğün.

Hey gidi, gölgeler ülkesi dünya!

Bir görünmez şeyin gölgesi dünya!

Boşlukta ayrılık bölgesi dünya!

Bu dünyada yeme, içme ve dövün!

(1972)', 'Ben ölünce etsin dostlarım bayram; Üstüste tam kırk gün, kırk gece düğün! Açı doyurmaksa kabirde meram, Yemeğim fatiha, günde beş öğün. Hey ...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dovun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo', 'tablo-necip-fazil-kisakurek-wxlk1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölümü sığdıramaz,

Akıl daracık koğuk.

Ölemez, çıldıramaz,

Ağlar boğuk boğuk.

İlaç yarım, şişede,

Koltuk mahzun, köşede,

Ev halkı telaşede,

Ölü yerde, sopsoğuk...

(1982)', 'Ölümü sığdıramaz, Akıl daracık koğuk. Ölemez, çıldıramaz, Ağlar boğuk boğuk. İlaç yarım, şişede, Koltuk mahzun, köşede, Ev halkı telaşede, Ö...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tablo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayan Kalbim', 'dayan-kalbim-necip-fazil-kisakurek-x7dci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni dağladılar, değil mi kalbim,

Her yanın, içi su dolu kabarcık.

Bulunmaz bu halden anlar bir ilim;

Akıl yırtık çuval, sökük dağarcık.

Sensin gökten gelen oklara hedef;

Oyası ateşle işlenen gergef.

Çekme üç beş günlük dünyaya esef!

Dayan kalbim üç beş nefes kadarcık!

(1972)', 'Seni dağladılar, değil mi kalbim, Her yanın, içi su dolu kabarcık. Bulunmaz bu halden anlar bir ilim; Akıl yırtık çuval, sökük dağarcık. Sen...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dayan-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denge', 'denge-turgut-uyar-35oad', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sizin alınız al inandım

Sizin morunuz mor inandım

Tanrınız büyük amenna

Şiiriniz adamakıllı şiir

Dumanı da caba

Bütün ağaçlarla uyuşmuşum

Kalabalık ha olmuş ha olmamış

Sokaklarda yit
..........
..........', 'Sizin alınız al inandım Sizin morunuz mor inandım Tanrınız büyük amenna Şiiriniz adamakıllı şiir Dumanı da caba Bütün ağaçlarla uyuşmuşum Ka...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/denge-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralamaz', 'yaralamaz-riza-aslan-0412h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaralamaz

yıkmaz yaşananlar

gün yüzü alışıktır

daha önceden kalanlara

nice yaralar sarılmıştır

nice derin yaralar

iyileşmeyeceği düşünülen

kangren olur denilen

nice sonlar tükenmiştir

gün yüzü alışıktır

alaca karanlıkta yenmiştir

yenilemiştir acılarını

gün yüzü alışıktır

yeni acılara

yeni gün alışıktır

yeni sonlara

31-10-2000', 'yaralamaz yıkmaz yaşananlar gün yüzü alışıktır daha önceden kalanlara nice yaralar sarılmıştır nice derin yaralar iyileşmeyeceği düşünülen k...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaralamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırarak', 'haykirarak-riza-aslan-md9e6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haykırarak

naralar atarak

bir sonu anlamsız kılmaya

çalışıyorum

kendimi kandırıyorum

31-10-2000', 'haykırarak naralar atarak bir sonu anlamsız kılmaya çalışıyorum kendimi kandırıyorum 31-10-2000...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/haykirarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile Yalanlar', 'nafile-yalanlar-riza-aslan-ha1cf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nafile yalanlar

uyduruyorum kendime

nafile yarınlar kuruyorum 

yine hayallerde

hep başkalarına yüklüyorum

yaşayamadığım şeyleri

hiç bir zaman çözüm bulamadan

türküler söylüyorum

söylemeyi beceremediğim

yeni anlamlar arıyorum

anlamını bilmediğim

yeni bir sen arıyorum

sonu olmayan

31-10-2000

ankara karacan', 'nafile yalanlar uyduruyorum kendime nafile yarınlar kuruyorum  yine hayallerde hep başkalarına yüklüyorum yaşayamadığım şeyleri hiç bir zama...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nafile-yalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gece', 'o-gece-harun-kesik-q4ahb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O gece sanki ağlıyordu 

Bulutlar sessizce

Ben seni düşünürken

Sanki benimle beraber 

Haykırıyordu...

Ama ben aklımda sen

Yüreğime vatan aşkı

Düşmana süngümü takmış

Yatıyordum mezarımda..', 'O gece sanki ağlıyordu  Bulutlar sessizce Ben seni düşünürken Sanki benimle beraber  Haykırıyordu... Ama ben aklımda sen Yüreğime vatan aşkı...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-gece-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Dağlardan Bile Kıskandım', 'adini-daglardan-bile-kiskandim-baris-tekin-xhar1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sadece sana 

Yine uykusuzum bu gece gözlerim yorgun ve agrili, 

Ama yine uyku girmiyor gözlerime. 

Oturdum,dolaştım,uzandım olmuyor, 

Gitmiyor varligin aklımdan, 

Her dakika seni anıyorum, 

İsmin düşmez dolu dudaklarımdan. 

Zaman oldu ağlamak istedim. 

Ama yokluğumdan ağlayamadım. 

Göz yaşlarıma gizli olan hayalin, 

Gözlerimden düşerek sandım. 

Adını haykırmak istedim: 

Karşımdaki ıssız dağlara. 

Birden durdum uzun uzun düşündüm. 

Adını dağlardan bile kıskandım.', 'sadece sana  Yine uykusuzum bu gece gözlerim yorgun ve agrili,  Ama yine uyku girmiyor gözlerime.  Oturdum,dolaştım,uzandım olmuyor,  Gitmiy...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adini-daglardan-bile-kiskandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk bu Deyilmi', 'ask-bu-deyilmi-baris-tekin-oiv8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çınarları düşlüyorum; 

Dalları gövdem kadar. 

Ve senin ellerin ellerimde... 

Yollar, denizler, 

Kent bizim. 

Gözlerinin içinde aşkım. 

Düşler görüyorum sana dair; 

Hep iyiye yorduğum. 

Korktuğum; 

Bir gün çekip gitmen. 

Söylesene; 

Aşk bu değil mi?', 'Çınarları düşlüyorum;  Dalları gövdem kadar.  Ve senin ellerin ellerimde...  Yollar, denizler,  Kent bizim.  Gözlerinin içinde aşkım.  Düşle...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-bu-deyilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalıyor Kapımı', 'caliyor-kapimi-taner-tirnovali-w226u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşündüğüm zamanlar,

Bir elimde sigara,diğerinde kadeh

Dudaklarımda mırıldadığım şarkı;

Ve duvarda asılı resmine bakarken,

Kurduğum düşlerle,

Gözlerinin mavisinde kaybolup

Derinlerden ismini haykırdığımda,

Çalacaksın kapımı,biliyorum...

Bu yüzdendirki ben,

Öylesine mayhoş ve sarhoşum ki,

Dudaklarım eski,bozuk plak gibi,

Hep aynı şarkıyı söyleyip dururken,

Gözlerim tanımazken başkalarını,

Ve,mavi derinliklerden haykırırken ismini,

Bak ! İşte,çalıyor kapımı biri..', 'Seni düşündüğüm zamanlar, Bir elimde sigara,diğerinde kadeh Dudaklarımda mırıldadığım şarkı; Ve duvarda asılı resmine bakarken, Kurduğum düş...', ARRAY['Türk Edebiyatı','Şiir','Taner Tırnovalı']::text[], 8.5, '{"poet":"Taner Tırnovalı","poet_slug":"taner-tirnovali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/caliyor-kapimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-necip-fazil-kisakurek-8vb38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ak saçlı başını alıp eline,

Kara hülyalara dal anneciğim! 

O titrek kalbini bahtın yeline,

Bir ince tüy gibi sal anneciğim! 

Sanma bir gün geçer bu karanlıklar,

Gecenin ardında yine gece var; 

Çocuklar hıçkırır, anneler ağlar,

Yaşlı gözlerinle kal anneciğim! 

Gözlerinde aksi bir derin hiçin,

Kanadın yayılmış, çırpınmak için; 

Bu kış yolculuk var, diyorsa için,

Beni de beraber al anneciğim! ...

(1926)', 'Ak saçlı başını alıp eline, Kara hülyalara dal anneciğim!  O titrek kalbini bahtın yeline, Bir ince tüy gibi sal anneciğim!  Sanma bir gün g...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/annecigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Ver', 'i-zin-ver-yildiz-bilgin-4ogam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbine girmek istiyorum izin ver

Sana sevmeyi öğreteyim

Kalbimdeki sırları seninle paylaşayım

Ve hiç duyulmamış bir aşkı yaşayalım

İzin ver gözlerine bakayım

Gözlerindeki acıyı sileyim

O güzel gözlerdeki yaşı

Yudum , yudum içeyim

İzin ver ellerini tutayım

Ellerimin sıcaklığıyla sevgimi sana sunayım

İzin ver dudaklarım dudaklarını örtsün

Dudaklarının titremesini durdursun

İzin ver seni göklere çıkarayım 

Yaşamını değiştireyim

İzin ver vücudunu sarayım

Ve sana aşkı öğreteyim', 'Kalbine girmek istiyorum izin ver Sana sevmeyi öğreteyim Kalbimdeki sırları seninle paylaşayım Ve hiç duyulmamış bir aşkı yaşayalım İzin ver...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/izin-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-i-rfan-mutluer-fue9g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güvercinler

Uçabilseydi eğer

Daha bir

Yaşanılır olurdu dünya.', 'Güvercinler Uçabilseydi eğer Daha bir Yaşanılır olurdu dünya....', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guvercin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün Senin', 'yuzun-senin-i-rfan-mutluer-laevn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzün senin

O en asil

O en kral yüzler içinde

Unutulmayacak tek yüz.

Yüzün senin

Her çizgisinde yaşamaktan bir parça bulduğum,

Mutluluk izleri ararken,

Kendimi unuttuğum.

Yüzün senin,

Sabahlara kadar seyretmek istediğim

Ve her sabah,

Tekrar geceleri özlediğim.

Yüzün senin,

Pırıl pırıl ışıldayan,

Kahverengide gülen,

Bazen kırmızılıkta unutan ağlamayı,

Yüzün senin.', 'Yüzün senin O en asil O en kral yüzler içinde Unutulmayacak tek yüz. Yüzün senin Her çizgisinde yaşamaktan bir parça bulduğum, Mutluluk izle...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuzun-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şehir', 'o-sehir-senem-yaklav-9eiej', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tan vakti olmuş,vapurlar sirenlerini çalıyor

Kuşlar süzülüyor o sonsuz gibi görünen denizde

Ben ise...ellerim cebimde beş kuruşsuz,

Biraz üşümüş,biraz açım...

Başım önde son sigaram ağzımda

Sen olupta,beni göremeyeceğin yere gidiyorum.

Sımsıcak simitlerin kokusu çöküyor içime,

Bir zamanlar senin kokunun burcu burcu çöktüğü gibi içime.

Bir kayıkçı var uzakta, balık mı avlıyor?

Yoksa kaybettiği birşeyi mi arıyor!

Hey! BALIKÇI boşa balık arama bu denizde,

Baksana umudunu o da kaybetmiş

Ümit yok içinde,dibinde

Tıpkı sen,tıpkı ben,tıpkı biz gibi...

İşte yanaşıyoruz limana...

Sevgililer kolkola bülbüller gibi

Oysa ben ellerim cebimde biraz üşümüş

Kalkıyorum ayağa...

Gözlerim sensizliğe bakıyor,

O virane şehirde binalar bir kavak ağacı gibi duruyor karşımda,

Biliyorum!orda bir yerdesin bildiğim bir yer var ama?

Geri geri adım attığım bir yer

Baktığım,görmediğim ve senin olduğunu bildiğim

Duruyorum...Bekliyorum...

Kalıyorum o taşların üzerinde

O taşlar ki... o kadar soğuklar şu ayaz gibi havada,

SEN,BEN ve yaşanmış,yaşayacak olan yürekler gibi...', 'Tan vakti olmuş,vapurlar sirenlerini çalıyor Kuşlar süzülüyor o sonsuz gibi görünen denizde Ben ise...ellerim cebimde beş kuruşsuz, Biraz üş...', ARRAY['Türk Edebiyatı','Şiir','Senem Yaklav']::text[], 8.5, '{"poet":"Senem Yaklav","poet_slug":"senem-yaklav","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-sehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-senem-yaklav-v0f1i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen beni hiç sevmedin ki,

Sen ellere inandın bana değil,

Hiç bir zaman bende bulmadın kendini,

Gözlerimde aramadın sana olan sevgimi,

Bir yalan dünyada bulduk birbirimizi,

Orda yaşadık en deli sevgiyi

Seviştik sabahlara kadar

Güldük,üzüldük hiç birbirimize dokunmadan,

Ayrılamıyorduk sabahlar olmadan

Sesinle uyanırdım her uykudan

Hep birtanem derdin hiç bıkmadan

Birde sana gülmüşsem candan

Yerim seni yerim derdin bana o an.

Çılgın aşklar çabuk bitermiş birtanem

Yaşananlar kalırmış herşeye rağmen,

UNUTMAK MÜMKÜN OLSAYDI EĞER,

Seni sensiz yaşamaya da değer...

          (28-09-2000    01:42)', 'Sen beni hiç sevmedin ki, Sen ellere inandın bana değil, Hiç bir zaman bende bulmadın kendini, Gözlerimde aramadın sana olan sevgimi, Bir ya...', ARRAY['Türk Edebiyatı','Şiir','Senem Yaklav']::text[], 8.5, '{"poet":"Senem Yaklav","poet_slug":"senem-yaklav","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunes-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA', 'merhaba-sinem-tunali-j0exg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba gülen yüzlere

Merhaba ağlayan gözlere

Merhaba sevenlere

Merhaba

Merhaba benim gibi sevilmemişlere', 'Merhaba gülen yüzlere Merhaba ağlayan gözlere Merhaba sevenlere Merhaba Merhaba benim gibi sevilmemişlere...', ARRAY['Türk Edebiyatı','Şiir','Sinem Tunalı']::text[], 8.5, '{"poet":"Sinem Tunalı","poet_slug":"sinem-tunali","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/merhaba-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün', 'birgun-adem-buyuksari-gswfm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birgün bana soracaksın 

Bana mı taparsın Allaha mı

Allaha diyeceğim

Darılıp gideceksin

Ama nerden bileceksin 

Benim Allahım sensin', 'Birgün bana soracaksın  Bana mı taparsın Allaha mı Allaha diyeceğim Darılıp gideceksin Ama nerden bileceksin  Benim Allahım sensin...', ARRAY['Türk Edebiyatı','Şiir','Adem Büyüksarı']::text[], 8.5, '{"poet":"Adem Büyüksarı","poet_slug":"adem-buyuksari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birgun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap Ve Ben', 'sarap-ve-ben-baris-tekin-o9sys', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'son bir şarkı dinleyeyim şimdi. 

düşlerimin üstüne, bir bardak su içer gibi. 

geceyi mi beklesem? 

yoksa şimdi mi içsem bu şarabı? 

şarap içip sarhoş olsam, 

baharın geleceğini düşleyip; 

ağaç gölgelerinden uykular çalsam, 

mehtaba tyatırıp gözlerimi; 

yıldızlarımı kaydırsam... 

hüzün hiç yakışmasa yüzüme o akşam! 

bir iskalede yine 

şarabımdan içip 

düşlerimin üstüne bir bardak su içer gibi 

son şarkımı dinlesem. 

gece, bütün sokakları dolaşıp 

şehrin gece bekçilerini dövsem.. 

sonra, belki elime kağıt kalem geçer 

yine böyle yalnız kalır, 

yine böyle 

saçmalarım

.', 'son bir şarkı dinleyeyim şimdi.  düşlerimin üstüne, bir bardak su içer gibi.  geceyi mi beklesem?  yoksa şimdi mi içsem bu şarabı?  şarap iç...', ARRAY['Türk Edebiyatı','Şiir','Barış Tekin']::text[], 8.5, '{"poet":"Barış Tekin","poet_slug":"baris-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sarap-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karımın İstanbul''dan Yazdığı Mektup', 'karimin-i-stanbul-dan-yazdigi-mektup-nazim-hikmet-ran-q12ek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canım, 

Uzandığım yerde yazıyorum.

Yorgunum pek.

Aynada yüzümü gördüm, adeta yeşil.

Havalar soğuk, yaz gelmeyecek.

Haftada otuz liralık odun lazım, 

başa çıkılır gibi değil.

Sofada demin iş görürken, 

battaniyemi aldım sırtıma.

Camlar çerçeveler kırık, kapılar

kapanmıyor, 

burda barınmamız imkansız artık, 

taşınmalı! 

Ev yıkılacak üstümüze.

Kiralarsa pahalımı pahalı.

Sana bunları ne diye anlatırım? 

Üzüleceksin.

Derdimi kime dökeyim? 

Kusura bakma.

Isınsa, iyice ısınsa ortalık ama, 

Hele geceler.

Bıktım usandım üşümekten.

Rüyalarımda Afrika''ya gidiyorum.

Cezayir''deydim bir sefer.

Sıcaktı.

Alnımı bir kurşun deldi, 

bütün kanım aktı, 

ama ölmedim.

Bana bir hal geldi.

Çok ihtiyarladığımı hissediyorum.

Halbuki biliyorsun, 

henüz kırkıma basmadım.

Çok ihtiyarladığımı hissediyorum, 

söylüyorumda, 

söyleyince kızıyorlar, 

konferans dinliyorum herkesden.

Her neyse bu bahsi kapat.

Paraguay halk türkülerini çaldı radyo.

Bunlar dikenli bir yaprağın üzerine

aşkla, güneşle, insan teriyle yazılmış.

Acıda, umutluda...

Bayıldım Paraguay türkülerine.

Adviye''den mektup aldım.

Beni çok göresi gelmiş, 

Hiç unutamıyormuş....

Şaştımda kaldım.

Yıllardır, 

Sen memleketten gittin gideli,', 'Canım,  Uzandığım yerde yazıyorum. Yorgunum pek. Aynada yüzümü gördüm, adeta yeşil. Havalar soğuk, yaz gelmeyecek. Haftada otuz liralık odun...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/karimin-istanbul-dan-yazdigi-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Adanmış Son Şiir', 'sana-adanmis-son-siir-elif-erdem-e8350', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu uykusuz gecede sana en son seslenişim...

Gözyaşlarımda bir elveda...

Dönüşünün olmadığı yolda

Seni sensizce severek artık hiç ümitsizce

Ellerimden kayıp giden

Mutluluk pişmanlığında 

Son bir veda...

Tüm ümitlerime,''belki''lerime ve hayallerime

Elveda...

Hasretin beni yakıyor olsa da

Yokluğundan kahrolsam da

Dönüp arkana baktığında

Göreceğin ilk ve son gerçek elveda...

Bu son seslenişim sana aşkım...

Bir daha yaşanmayacak

Yanlızca sana ve daima 

Süren,sürecek ve bitmeyecek

Hasretim ve ebedi sevgim

Yok olan tüm ümitlerimle

Buruk son bir veda ile 

Seni sonsuza dek kalbime mühürlüyorum...

Elveda...', 'Bu uykusuz gecede sana en son seslenişim... Gözyaşlarımda bir elveda... Dönüşünün olmadığı yolda Seni sensizce severek artık hiç ümitsizce E...', ARRAY['Türk Edebiyatı','Şiir','Elif Erdem']::text[], 8.5, '{"poet":"Elif Erdem","poet_slug":"elif-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-adanmis-son-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-mucahit-baskal-eiw72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'feryadı figan eyler dururum

insanlar belki beni duyarlar diye

her defasında bin pişman olurum

beni belki yanlış anlarlar diye

insanlara dostluğu nasihhat ettim

bir ihtimal beni dinlerler diye

doğruya koştum yalanı terkettim

belki beni takip eylerler diye

tebliğe vardım suç imiş meğer

sevemem kimseyi doğrusu bu ise eğer

fakat yinede insanlar sevilmeye değer

sevilmeyi hak eden var ise eğer..

                                 m.b..', 'feryadı figan eyler dururum insanlar belki beni duyarlar diye her defasında bin pişman olurum beni belki yanlış anlarlar diye insanlara dost...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cagri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Kadını', 'ellerin-kadini-mucahit-baskal-ly6eq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yeşil gözlerine hayran olduğum 

beni terk edişin nedendir bilmem

sevgin idi senden tek istediğim

çokmu zor geldi beni sevmen

sana gülden güzelsin derken

bu sözlerimi iltifatmı sandın

yoluna canını adayan varken

yalan sözlere neden inandın

aşkımı ilan eyledim sana 

beni kedere acıya boğdun

sevgi dolu kalbimi vermişken sana

neden gidipte ellerin kadını oldun..

                                    m.b..', 'yeşil gözlerine hayran olduğum  beni terk edişin nedendir bilmem sevgin idi senden tek istediğim çokmu zor geldi beni sevmen sana gülden güz...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ellerin-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçelim', 'i-celim-mucahit-baskal-0grca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sıcak çayım var ve bir kaç dal sigaram

daha başka bir şeyi inan aramam

dostum al bir sigarada sen yak 

çünki bu benim  yakacağım en son sigara

gel bu geceyi böylece sabah edelim

çoşalım gülelim eğlenelim

iyi birer dost olup birbirimizi sevelim

gel bu gecede böyle sabah edelim

muhabbetin hasını edelim

haydi durma dost;um daha içelim

içelim içelim kendimizden geçelim

şu demli çayımızı yudum yudum içelim...

                                              m.b..', 'sıcak çayım var ve bir kaç dal sigaram daha başka bir şeyi inan aramam dostum al bir sigarada sen yak  çünki bu benim  yakacağım en son siga...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gül', 'beyaz-gul-sahin-aksu-0d727', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farklıydı duygularımız belki

Farklıydı aşka olan inancımız

Arkadaş, dost, akrabalarımız

Farklıymış meğer dünyalarımız

Sen beyaz bir gül toprağında

Ben kurumuş bir yaprak kaldırımlarda

Zamansız açılmış çiçeksin bu diyarda

Zamansız soldurdun beni de ilkbaharımda

Bilmez miyim hayatın güzelliğini

Görmez mi sanırsın bu gönül aşkı sevgiyi

Durdururlar mı zamanı, yaşatırlar mı o anı

Gülüşünle büyülediğin birkaç güzel saniyeyi', 'Farklıydı duygularımız belki Farklıydı aşka olan inancımız Arkadaş, dost, akrabalarımız Farklıymış meğer dünyalarımız Sen beyaz bir gül topr...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyaz-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madalyon', 'madalyon-sahin-aksu-u0daz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her iyiliğe layık biri sanırdım seni

Yanılmışım meğer böyle bilirdim önceleri

Hakkında hissettiğim duygu ve düşünceleri

Anladım ki artık görmüyorsun sevgilim

Altın kalbin vardı sanki düne kadar

Sana bakış açım bu, senden değil bunlar

Madalyonun öbür yüzü daha çok can yakar

Bana bakan yüzünü artık çözdüm sevgilim

Güzellik geçicidir derler sen de inan buna

Gözlerindeki ışıltıyı kaptırma günahlarına

Pişman olursun elbet gün gelir yaptıklarına

O gün ben yanında olmayacağım sevgilim', 'Her iyiliğe layık biri sanırdım seni Yanılmışım meğer böyle bilirdim önceleri Hakkında hissettiğim duygu ve düşünceleri Anladım ki artık gör...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/madalyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zirve', 'zirve-sahin-aksu-1ukww', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkım hep zirvede olsun istedim

Ve tabi dostlarımla

Yalnız kalmayı bazen istedim

Hayattan bıktığımda

Yalnızlığın tadı hala damağımda

Acısı da

Ve sen geldin aklıma

Herhangi bir yerde

Herhangi bir dağın zirvesinde

Seni buldum yalnızlığımda

Zirvesi olan tüm dağlarda', 'Aşkım hep zirvede olsun istedim Ve tabi dostlarımla Yalnız kalmayı bazen istedim Hayattan bıktığımda Yalnızlığın tadı hala damağımda Acısı d...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zirve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim', 'bilemedim-sahin-aksu-u84aq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni tanıdıktan sonra

Dönüp baktım yalancı maziye

Yaşamamış, yaşanmamış yılları saydım

Ve yandım...

Senin gözlerin kadar

Mazinin boşluğu da yakıyordu içimi

Üç-dört ay geçmişti 19’umu bitireli

Hevestir geçer diyordu

Çevremizin tecrübelileri

Ama geçmiyordu...

Bilmiyordum sonbaharın güzelliğini

Sanki ilk defa yaşıyordum mevsimleri

Yağmur olup yağıyordum yerlere

Işık olup açıyordum gecenin rengini

Ve sen doğuyordun içime güneş gibi

Ayrılık dağının ardından gülüyor

Mutluluk çiçeğini koparıyor

Üstelik pişman olmuyordun

Her ayrılık vakti güldüğün için

Önceleri seni affetmek istemedim

Benim ki aşk mı, yoksa tutku mu

Bunu bir türlü çözemedim

Senin ki dalga mı, avuntu mu

Bir de bunu, bunu bilemedim...', 'Seni tanıdıktan sonra Dönüp baktım yalancı maziye Yaşamamış, yaşanmamış yılları saydım Ve yandım... Senin gözlerin kadar Mazinin boşluğu da ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Aşkım', 'benim-askim-sahin-aksu-4adtm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutların ötesinde

Yüksek dağların zirvesinde

Meltem rüzgarlarının sesinde

Saklıdır benim aşkım

Çiçeğin açışında

Ceylanın bakışında

Güneşin batışında

Saklıdır benim aşkım

Bülbülün ötüşünde

Çocuğun gülüşünde

Yağmurun düşüşünde

Saklıdır benim aşkım

Gecenin esrarında

Gençliğimin baharında

Sigaramın dumanında

Saklıdır benim aşkım

Aşıkların sazında

Seni seviyorum sözünde

Bir tek O’nun gözünde

Saklıdır benim aşkım', 'Bulutların ötesinde Yüksek dağların zirvesinde Meltem rüzgarlarının sesinde Saklıdır benim aşkım Çiçeğin açışında Ceylanın bakışında Güneşin...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülecek günler', 'gulecek-gunler-sahin-aksu-2vqzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen en acı sözler gelirya diline

İstesen de söyleyemezsin oturur içine

İma et diye yalvarsan da gözlerine

Diyemez-bakamazsın boyun eğersin kaderine

Duygusuzsa karşındaki sevgini anlatamazsın

Gözü havada, gönlü kutudaysa açamazsın

Gülsen de çevrene mutluluk saçamazsın

Kaderin buysa uğraşma, kaçamazsın

Kaybedeceksin elbet gönlündeki derinliği

Kıştan alacaksın ruhuna en eksi serinliği

Bırak zamana yitirme senin olan benliği

Sevdiğin kız giydiği gün beyaz gelinliği

Göreceksin baharda açacak rengarenk güller

Kahredeceksin, boşuna mı harcandı diye dünler

Yeniden eşelenecek sen kahrettikçe kinler

Üzülme ama bir gün sana da gülecek günler', 'Bazen en acı sözler gelirya diline İstesen de söyleyemezsin oturur içine İma et diye yalvarsan da gözlerine Diyemez-bakamazsın boyun eğersin...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulecek-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönmeyen Umut', 'sonmeyen-umut-sahin-aksu-v45ib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gönlüm nerelerdesin

Sevmiyorsun kimseyi ne zamandır

Bilirim O’ndan beri hep dertlisin

Kinin de sevgin gibi pek yamandır

Unutulmuyor değil mi istesen de

Boşayamıyorsun aşkını tek celsede

Gelecek günlerin sana gülse de

Çıkamadın kuş misali kaldın kafeste

Nerede bir gül görsen bakarsın

Veremedim diye yas tutarsın

Gözlerine dalıp hayal kurarsın

O’nsuz geçen günlerine yanarsın

İçinde bir umut kaldı sönmeyen

En kötü gününde bile ölmeyen

Bahar yağmurları gibi dinmeyen

O’ndan başkasını yar bilmeyen', 'Ey gönlüm nerelerdesin Sevmiyorsun kimseyi ne zamandır Bilirim O’ndan beri hep dertlisin Kinin de sevgin gibi pek yamandır Unutulmuyor değil...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonmeyen-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Güleyim', 'nasil-guleyim-mucahit-baskal-og83b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mahsun gözlerime birikmiş yaşlar

kalbime saplanmış dinmez acılar

genç yaşımda saçıma dökülmüş aklar

kederli halime nasıl güleyim

daha sana doymadan geldi ayrılık

güneşim doğmuyor dünyam karanlık

sana olan aşkıma tüm evren tanık 

şu kara bahtıma nasıl güleyim

gönül bahçemde güllerim soldu

dostlarım ne arar ne sorar oldu

yaralı yüreğim kahırla doldu

içim kan ağlarken nası güleyim

                                         m.b.', 'mahsun gözlerime birikmiş yaşlar kalbime saplanmış dinmez acılar genç yaşımda saçıma dökülmüş aklar kederli halime nasıl güleyim daha sana d...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nasil-guleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Güneşi', 'sonbahar-gunesi-sahin-aksu-4ubgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gençliğimin en güzel çağında

Tanıdım sonbahar güneşini

Ağır bir taş idim duygu dağında

O’nda bulup-kaybettim aşk ateşini

Mani oldu bulutlar, onu görmemem için

Anlayamadım yağmurlar, niye yağdınız niçin

Sizin gibi ben de ağlarım, hem de için-için

Göremediğim zaman o nazlı, sonbahar güneşini

Korkar oldum artık battığın her akşam

Bekler oldum ay’dan müjdeli bir haberini

Hayal eder oldum ne zaman bir ışığa baksam

Biliyorum bir sabah doğmayacaksın sonbahar güneşi', 'Gençliğimin en güzel çağında Tanıdım sonbahar güneşini Ağır bir taş idim duygu dağında O’nda bulup-kaybettim aşk ateşini Mani oldu bulutlar,...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sonbahar-gunesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'neyleyim', 'neyleyim-sahin-aksu-zxhmt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hava güzel gün hoşmuş neyleyim

Kolaysa siz onu kalbime söyleyin

Gelmiyor ki içimden bir şey yapmak

Sevdiğinden uzak, kurak bir çöldeyim

Kuşlar uçar, çiçekler açarmış neyleyim

Duyarsanız eğer gönül sesimi dinleyin

Görmeyeli onu ediyor hep feryat figan

Karaya oturmuş gemide, ıssız denizdeyim

Yıldızlar parlak, ay loşmuş neyleyim

Yüreğim yaralı, siz onu iyileştirin

Tanıyalı bu aşkı kanıyor her zaman

Kayboldum karanlıkta, uykusuz gecedeyim', 'Hava güzel gün hoşmuş neyleyim Kolaysa siz onu kalbime söyleyin Gelmiyor ki içimden bir şey yapmak Sevdiğinden uzak, kurak bir çöldeyim Kuşl...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaram Kanar', 'yaram-kanar-sahin-aksu-d4tat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çektim havadaki bulutları gözlerime

Gökyüzü masmavi gözlerin gibi bugün

Güneş bir başka doğuyor yaralı kalbime

Senin yapamadığını o yapıyor her gün

Yedi renkli gökkuşağına bakıyorum

Aranıza beni de, beni de alın diyorum

Siyah olmaya razıyım yeter ki beni de alın

Her yağmurdan sonra görür beni belki yârim

Yıldızlar neredesiniz küs müsünüz bana

Ellerim havada, gözlerim yukarda sizi arar

Çekin alın beni de kalamam bu dünyada

Benim gibi yariniz mi var, içiniz mi yanar

Hatırlatmayın bana onu denizler, deryalar

Anlatmayın siz de susun şiirler, şarkılar

Canlanmayın yeniden hayaller, hatıralar

Bilmiyor musunuz hatırladıkça yaram kanar', 'Çektim havadaki bulutları gözlerime Gökyüzü masmavi gözlerin gibi bugün Güneş bir başka doğuyor yaralı kalbime Senin yapamadığını o yapıyor ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaram-kanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissetti mi Kalbin', 'hissetti-mi-kalbin-sahin-aksu-coyoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yetmiyor hayalin

Yanıyor yüreğim

Görmüyor gözlerim

Sevgilim neredesin

Üşüyor ellerim

Titriyor bedenim

Çınlıyor sözlerin

Sevgilim neredesin

Yazmıyor kalemim

Dinmiyor hasretin

Tükendi ümitlerim

Sevgilim neredesin

Günlerce bekledim

Şarkımızı dinledim

Hissetti mi kalbin

Sevgilim neredesin', 'Yetmiyor hayalin Yanıyor yüreğim Görmüyor gözlerim Sevgilim neredesin Üşüyor ellerim Titriyor bedenim Çınlıyor sözlerin Sevgilim neredesin Y...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hissetti-mi-kalbin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın', 'uzaksin-sahin-aksu-fmyt6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaksın bana

Görmek istesem de yoksun

Umutla bekleyeceğim bir daha

Gözlerinden ve sözlerinden yoksun

Seni anlatır bütün şarkılar

Hepsinde bir parçam saklı

Bir arasan, bir sorsan ne var

Gözlerim güneşle birlikte battı

Haber saldım ayrılık rüzgarlarına

Yarimi getirin koparmayın benden

Geldim bu yolun da sonlarına

Haftalardır haber alamıyorum senden', 'Şimdi uzaksın bana Görmek istesem de yoksun Umutla bekleyeceğim bir daha Gözlerinden ve sözlerinden yoksun Seni anlatır bütün şarkılar Hepsi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırma Gönül', 'kandirma-gonul-sahin-aksu-d8gvr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hissettiklerim doğrumu söyle

Ne olur bir de sen kandırma gönül

Görüp de vurulduğun her güzele

Kendini verip kaptırma gönül

Ders al hep yaşadıklarından

Düşme bir daha o tuzağa gönül

Sevip senden ayrılanlardan

Uzak dur her defa ağlama gönül

Bak bu da, bu da onlardan biri

Ona da inanıp bağlanma gönül

Seni çok seviyorum dese dahi

Bir tokat daha yeme, yeme gönül

Gelip geçiyor anla bir ömür

Kıymetini bilemedim ey gönül

Olmasan da sen bu kervan yürür

Benim olmadın hiç, emanettin gönül', 'Hissettiklerim doğrumu söyle Ne olur bir de sen kandırma gönül Görüp de vurulduğun her güzele Kendini verip kaptırma gönül Ders al hep yaşad...', ARRAY['Türk Edebiyatı','Şiir','Şahin Aksu']::text[], 8.5, '{"poet":"Şahin Aksu","poet_slug":"sahin-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kandirma-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-mucahit-baskal-17wit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'koca birömrü tükettim

bir gün olsun gülmedi yüzüm

hep ağlamaklı hep üzgün 

benim garip iki gözüm

zok zordur yaşamak 

bu fani yalan dünyada

bakma gönül sen ona buna

dünya han biz yolcuyuz bu hana

bir sınava tabiyiz 

biz bu fani dünyada

bir gün uyanır elbet

kalpler şimdi rüyada..

                    m.b...', 'koca birömrü tükettim bir gün olsun gülmedi yüzüm hep ağlamaklı hep üzgün  benim garip iki gözüm zok zordur yaşamak  bu fani yalan dünyada b...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruya-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabaneller', 'yabaneller-mucahit-baskal-0hwrg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anam yalnız kaldım bak yaban ellerde

sürüklenim gidiyorum hırçın sellerde

belki yarın belkide sonraki günlerde

ölümüm yakın benim yaban ellerde

yüreğimdeki yarayı bilmez kimseler

ne bilsin benim derdimi çilemi eller

halime bakıp belki bana deli derler

anam ne bilsin benim derdimi bu yaban eller

benim derdim herkesten çok 

bu derdimin bir çaresi bir çözümü yok

muratın karnı bazen aç bazen tok 

açın halinden anlamaz anam bu yaban eller

hekime gittim bir çare bulamadı

yalan dünyada fazla ömrüm kalmadı

hayallerim tükendi takatım kalmadı

ömrüm son bulacak bu yaban ellerde

derdim yansam bacıma onun nesinse

kötüler dolmuş gardaşımın çevresine

babam ermiş hakkın rahmetine

derdime çare olmaz bu yaban eller

anam yaram azıp durmadan kanıyor

kanlı gözlerim hep seni arıyor

bu halim düşmana neşe veriyor

muratın canını alıyor bu yaban eller

anam helal et hakkını garip yavruna

bir dirhem hakkım varsa helal olsun sana

yine azdı yüreğimdeki bu zalim yara

ölüyor yavrun anam bu zalim yaban ellerde..

                                                           m.b..', 'anam yalnız kaldım bak yaban ellerde sürüklenim gidiyorum hırçın sellerde belki yarın belkide sonraki günlerde ölümüm yakın benim yaban elle...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yabaneller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim', 'derdim-mucahit-baskal-v6sps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dostlarım zor geldi bu sevda bana

derdimi kimseye açamaz oldum

yangında bacayı sardıktan sonra

bir yolunu bulup kaçamaz oldum

güvercinim karlı dağlar ardında

işiyle gücüyle kendi derdinde

ey felek önüme ağlar gerdinde

kurtulup yanına uçamaz oldum

uzaktan uzağa yaşarım aşkı

sevdiğim yanımda olsaydı keşke

şiirlerle ona yaptığım köşkü

ellerimle kurup açamaz oldum

                                  m.b...', 'dostlarım zor geldi bu sevda bana derdimi kimseye açamaz oldum yangında bacayı sardıktan sonra bir yolunu bulup kaçamaz oldum güvercinim kar...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/derdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Oğlu Türküz', 'turk-oglu-turkuz-mucahit-baskal-afcj6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kurtlar girmiş çakallarla savaşa

düşürmüşler yine gardaşı gardaşa

vatanı için girmiş kurdum bu savaşa

can vermiş can koymuş bu davaya

alevi sünni diyerek düşürmüşler bizi bize

korkmadan savaşalım düşmanı getirelim dize

osmanlıdan miras kalmış bu vatan bize

bu yüce toprak yeter hepimize

oğuz hanın yirmidört boyundan türemişiz

bismillah deyip kılıncımızı bilemişiz

aydınlıktır geleceğimiz geçmişimiz

türküz türkoğluyuz kendimizi ezdirmeyiz..

                                                     m.b...', 'kurtlar girmiş çakallarla savaşa düşürmüşler yine gardaşı gardaşa vatanı için girmiş kurdum bu savaşa can vermiş can koymuş bu davaya alevi ...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/turk-oglu-turkuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Tükettim', 'omur-tukettim-mucahit-baskal-zh5ox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün gelecek şu köhne kapıdan 

cansız bedenimi çıkaracaklar

kirli elbisemi çıkarıp

bembeyaz bir kefene saracaklar

bedbenizli bedenimi yıkayıp

musalla taşına beni bırakacaklar

bir kaç dostum namazımı kılıp

ebedi yolculuk için yola çıkaracaklar

fukara bir cenazeyim ben

varsın olmasın dostum akrabam

beni götürsün tam dört inanmış adam

gömsünler beni kara toprağa.....', 'gün gelecek şu köhne kapıdan  cansız bedenimi çıkaracaklar kirli elbisemi çıkarıp bembeyaz bir kefene saracaklar bedbenizli bedenimi yıkayıp...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omur-tukettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım', 'muradim-mucahit-baskal-x1mi6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen tozlu yolların garip yolcusu

yaşantın hayaline uymaz muradım

yaşamak uğrunda ekmek kavgası

dizlerinde derman koymaz muradım

gurbette yokluktan kederden yana

yaradan hepsini bol vermiş sana 

kolların durmadan çalışır ama

ellerin bol para saymaz muradım

mahsun gözlerine birikir yaşlar

sılayı anınca akmaya başlar

yatağın toprak yastığın taşlar

gözlerin uykuya doymaz muradım

ardıçlı dağlardan sökerken şafak

nasılki dalından düşer bir yaprak

seninde son göçün öyle olacak

ölürsen kimseler duymaz muradım', 'sen tozlu yolların garip yolcusu yaşantın hayaline uymaz muradım yaşamak uğrunda ekmek kavgası dizlerinde derman koymaz muradım gurbette yok...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançer', 'hancer-mucahit-baskal-rc7e7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kahrı maf olmuş benim hayatım

doğmak imiş benim tek zanaatım

benide böyle yaratmış yüce allahım

bir kırıksazdır benim velihattım

dağlar yeşerip çiçek açsada

benim gönlüm hep hazan olur

ne kadar sevsemde ben insanları 

arkamdan kuyumu kazanlar olur..', 'kahrı maf olmuş benim hayatım doğmak imiş benim tek zanaatım benide böyle yaratmış yüce allahım bir kırıksazdır benim velihattım dağlar yeşe...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hancer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahuekber', 'allahuekber-mucahit-baskal-jsy29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'allah için savaşta 

yenilgi yoktur asla 

kanlarımızla atarız 

imzamızı her asra

allah için savaşırız

allah için biz varız

biz rahmanın kullarıyız

kullarına kul olmayız

gençler çocuklar büyükler,

herkes o günü bekler

kundaktaki bebekler

dillerde hep allahuekber', 'allah için savaşta  yenilgi yoktur asla  kanlarımızla atarız  imzamızı her asra allah için savaşırız allah için biz varız biz rahmanın kulla...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/allahuekber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'azap', 'azap-mucahit-baskal-9qccp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayat yine acımasızlığını etti bugün

isyanım kar etmedi derde ızdıraba

zindanda geçen her günüm hüzün

biten ümitlerimi yazdım kitaba

umutlarımı ektim gelmez bahara

lanet ettim geçmeyen zamana

azrail gelmiş canım almaya

hayatı mahvolmuş bir canım ben', 'hayat yine acımasızlığını etti bugün isyanım kar etmedi derde ızdıraba zindanda geçen her günüm hüzün biten ümitlerimi yazdım kitaba umutlar...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/azap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kaos', 'kaos-mucahit-baskal-zgy4e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istediğin şeyler olmuyor diye

bir nimet olan hayatını 

cehenneme döndürüyorsan

hala nefsini kaderini ve allahı

bilmekten uzaksın demektir..', 'istediğin şeyler olmuyor diye bir nimet olan hayatını  cehenneme döndürüyorsan hala nefsini kaderini ve allahı bilmekten uzaksın demektir.....', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kaos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Kabarıyor', 'i-cim-kabariyor-bulent-batmaz-601j3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dışarısı buz gibi soğuktu

Ben evde seni bekledim

Geliş saatin yaklaştıkça

İçim kabarıyordu heyecanlanıyordum.

Önceleri senin gidişini izlediğim

Mutfak penceresine

Bir kelebek gibi yapışmış

Seni bekliyordum

Görebildiğim kadar uzaklarda 

Seni arıyordum

İçim kabarıyordu kızıyordum.

Geleceğin vakit çoktan geçmişti

Ve sen gelmemiştin

Ben hala seni bekliyordum

Mutfakta ışık sönük

İçim labarıyordu hüzünleniyordum.

Dışarıya çıktım bir ufak rakı aldım

Herşeyi ile seni anlatan

Odama döndüm

Vakit gece yarısı olmuştu

Bugün hiç gülmemiştim

Sen de gelmemiştin

İçim Kabarıyordu içiyordum.', 'Dışarısı buz gibi soğuktu Ben evde seni bekledim Geliş saatin yaklaştıkça İçim kabarıyordu heyecanlanıyordum. Önceleri senin gidişini izledi...', ARRAY['Türk Edebiyatı','Şiir','Bülent Batmaz']::text[], 8.5, '{"poet":"Bülent Batmaz","poet_slug":"bulent-batmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/icim-kabariyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüm', 'olumum-erkan-candogan-2ds1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece -nedendir bilmem- seni gördüm rüyamda.

Kapkara bir tabutun içinde ben,

Ve sen karşımda ağlarken,

Elinde çiçeklerle ne güzeldin.

Keşke ölmeseydim dedim içimden.

(İzmir, 1998)', 'Dün gece -nedendir bilmem- seni gördüm rüyamda. Kapkara bir tabutun içinde ben, Ve sen karşımda ağlarken, Elinde çiçeklerle ne güzeldin. Keş...', ARRAY['Türk Edebiyatı','Şiir','Erkan Candoğan']::text[], 8.5, '{"poet":"Erkan Candoğan","poet_slug":"erkan-candogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olumum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Kesti Yolu', 'kar-kesti-yolu-nazim-hikmet-ran-g9ee5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar kesti yolu

sen yoktun

oturdum karşına dizüstü

seyrettim yüzünü

gözlerim 
..........
..........', 'Kar kesti yolu sen yoktun oturdum karşına dizüstü seyrettim yüzünü gözlerim  .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kar-kesti-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğe Dair', 'gelecege-dair-ertugrul-gazi-alkurt-78mx1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelecek de bir gün gelecek

Gelecek  gelmeden ömrümde bitecek  

Bu  kız bana  bakmazsa

Ertuğrul bu diyardan göçecek', 'Gelecek de bir gün gelecek Gelecek  gelmeden ömrümde bitecek   Bu  kız bana  bakmazsa Ertuğrul bu diyardan göçecek...', ARRAY['Türk Edebiyatı','Şiir','Ertugrul Gazi Alkurt']::text[], 8.5, '{"poet":"Ertugrul Gazi Alkurt","poet_slug":"ertugrul-gazi-alkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gelecege-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oldum', 'asik-oldum-ertugrul-gazi-alkurt-3mp84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinin rengini bilmediğim birisine  aşık oldum

Saçlarının teline dokunamadığım birisine aşık oldum

Sesini hiç ama hiç duymadığım birisine  aşık oldum

Ben aşkların en büyüğüne tanık oldum', 'Gözlerinin rengini bilmediğim birisine  aşık oldum Saçlarının teline dokunamadığım birisine aşık oldum Sesini hiç ama hiç duymadığım birisin...', ARRAY['Türk Edebiyatı','Şiir','Ertugrul Gazi Alkurt']::text[], 8.5, '{"poet":"Ertugrul Gazi Alkurt","poet_slug":"ertugrul-gazi-alkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asik-oldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bügün', 'bugun-sair-scream5-z8mxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün seni kendimle paylaştım…

ben söyledim o dinledi….

o söyledi ben dinledim…

seni anlattım ona..

beni benden aldıgın beni…

ve hayatıma anlam veren seni…

Senden konuştuk epeyce…

gözlerinden bahsettim…

çok etkilendi…

çunku bende o gözlere ve gözlerindeki sana vurulmustum..

baktıgımda dalıp gittiğim…

sonsuz ucurumlarda kayboldugum gozlerını anlattım ona…

sonra bakıslarını anlattım…

yürek delen…

sevgi fışkıran…

konusan bakıslarını anlattım…

sonra dudaklarını anlattım ona…

en çok dudaklarını büküp başını iki yana sallamanı beğenmış…

sonra o narın ellerını anlattım…

hani işine gelmeyince ‘’pat ‘’ diye vuran ellerini…

sonra gülüşünü anlattım…

güldüğün zaman guller acan yüzünü çizdim ona…

çok begendı…

sonra sesınden bahsettım…

insanın içini ısıtan….

o insancıl sesını anlattım…

sonra dokunusunu anlatım ona…

hıssettıgımde cıldırdıgım…

ates basan vucudumu…

tıtreyen vucudumu anlattım…

sonra yuregını anlattım..

içi sevgıyle dopdolu…

aşk dolu …

bir kus gıbı atan yuregını anlattım…..

sonra ruhunu yazdım ona…

insan olan senden bahsettım….

sadece dinledi…dinledi…dinledi….

sonra beni kıskandıgını söyledi bana…

böyle bırını sevdıgım…

boyle bırıne delıce vuruldugum ıcın…

ne dusundugunu sordum ona….

şöyleydı cevabı…

mademkı seviyorsun…

mademkı aşıksın…

yazmıssın adını daglara taşlara…

YAŞA SEVDİĞİNİ DEDİ BANA…DOYABİLDİĞİNCE YAŞA…', 'Bugün seni kendimle paylaştım… ben söyledim o dinledi…. o söyledi ben dinledim… seni anlattım ona.. beni benden aldıgın beni… ve hayatıma an...', ARRAY['Türk Edebiyatı','Şiir','Şair Scream5']::text[], 8.5, '{"poet":"Şair Scream5","poet_slug":"sair-scream5","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bugun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-sair-scream5-ftowg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hüzün yildizlari parliyor bugün gökyüzünde, 

Bu gece yine için için yaniyorum, 

Oturmus seni düsünüp agliyorum, 

Seni, gidisini, sevisini, herseyini... 

Unutamiyor iste seni su yarali kalbim, 

Yaptiklarini hatirlayip, pisman oluyor... 

Seni düsünüyorum bu gece, karanlik gökyüzünde... 

Simsiyah gökyüzünde parlayan yildizlari seyrediyorum, 

Onlari sana benzetiyorum, 

Kararmis kalbimin bir kenarinda yanan mesale misali... 

Dedim ya, seni düsünüyorum bu gece, 

Beni sevdigini, bana nasil baktigini, bana nasil güldügünü,

Ellerimi nasil tuttugunu, ellerini nasil tuttugumu, 

Büyüyen bir ates gibi sevgimizin nasil çogaldigini 

Ve birgün ansizin birakip gidisini... 

Son vedani hatirliyorum, gözlerime aglarcasina baktigini, 

Gözlerini kalbime gömdügünü hatirliyorum, 

Bir daha çikamasin diye... 

Çikamadilar zaten kalbimden gözlerin, 

Ölüler dirilirler mi ki gömülenler çiksin, gitsin? 

Gittin son bir veda ile gözü yasli, 

Elimde kolyen, ardindan dakikalarca baktim, aglamakli, 

Sikildim, üzüldüm, perisan oldum ama aglamadim... 

Aglayamadim, engel oldu gururum, engel oldu askim, 

Uzaklara gittin, belki birdaha asla geri dönmemecesine, 

Özledim seni deliler gibi, özlüyorum hala... 

Sen bir yerde ben bir yerde, yinede sönmedi sevgimiz, 

Aksine çogaldi daglar gibi oldu hasretimiz... 

Hep seni hayal eder, hep seni düsünürdüm, 

Sesini duyunca yasar, duyamayinca ölürdüm, 

Aradin beni aylarca bir sevgi ugruna, 

Ne yazik ki, ihmal edildin bir hata ugruna, 

Kirildin, agladin, affettin ama hep sevdin, 

Beni sevdin gülüm beni, kalbi kirik bir vefasizi, 

Yine ihmal edildin yine unutuldun bir hiç ugruna, 

Yine kirildin, yine agladin, yine affettin... 

Bir daha unutuldun, sevdanla basbasa birakildin, 

Yine kirildin, yine agladin ama bu sefer affetmedin... 

Sevdigini en mutlu gününde öldürdün, 

Ve ardina bakmadan gittin...

Beni benle basbasa biraktin, yikildim, üzüldüm, kirildim... 

Senden ayrilinca kaldim çaresiz, sevgisiz ve birde sensiz, 

Hep sensizdim zaten ama simdiki kadar asla degil...

Parçalanmis bir kalbe sahip oldun mu sen hiç? 

Parça parça edilmis, yikik ve virane, 

Bir o kadarda vefasiz... 

Önceleri üzüldüm, yikildim ama asla aglamadim... 

Geldi geçti deyip senide gözlerin gibi kalbime gömdüm... 

Unuttum dedim, unutacagim dedim, 

Unutamiyorum dedim, UNUTMAM dedim... 

Önce gözlerin sonra sen çiktin kalbimden, 

Bir vicdan azabidir basladi ölü yüregimde, 

Hiçbir sey kalmadi, senden baska kalbimde, 

Hatiralarin, gözlerin ve sözlerin...

Siirlerini getirdiler bana, 

Beni öldüren siirlerini... 

Vefasiz dedigini duydum, yikildim, 

Düsündüm seni gecelerce daima tek basima, 

Siirlerin öldürdü, hasretin yakti yüregimi, 

Kirildim, üzüldüm, yikildim ve en sonunda agladim... 

3 kisi agladik sana; ben, kalbim ve gözlerim... 

Sana yandim, seni sevdim, seni hatirladim heryerde... 

Belki birgün sesini duyarim umuduyla 

Telefon bekledim günlerce, 

Telefon gelmeyip sesine hasret kalinca 

Agladim agladim, 

Sana yaptiklarimi ancak o zaman anladim...

Duydum ki kalbini vermemissin kimseye, 

Olurda içinde görürler beni diye... 

Benim kalbimide istediler, ama vermedim kimseye, 

Olurda içinde seni görürler diye... 

Gökyüzü yildizlar ile doluydu, ben hep seni düsünürken,

Hüzün yildizlari koydum adlarini, seni hatirlatiyorlar diye,

Ayni onlar gibi sende benden çok uzaklardaydin, 

Hep göz kirpardin uzaktan, sessizce, 

Bense hep seni bekledim kirik kalbim, yasli gözlerimle...

Bazen hayallere daliyorum, seni düsünüp agliyorum, 

Seni ve sevgini ariyorum hep kalbimde... 

Düsmüyor adin hiç dilimden, 

Ölecegim gülüm bir gün ben, 

Senin sevginden, senin derdinden... 

Bir gün görecegim yine belki seni, 

Seni, beni unutmus, benim olmayan seni... 

Iste o an askimin gözyaslarini hatirlayacagim, 

Ve yine bir köseye oturup aglayacagim... 

Yemin ettim senin üstüne sevmeyim baskasini diye, 

Ve heryerde, her zaman tekrarliyorum yeminimi; 

Seni unutmam için öldürseler bile, 

Karsilik olarak dünyayi verseler bile, 

Daragaci kurup idam etseler bile, 

Senden baskasini asla sevmeyecegim...', 'Hüzün yildizlari parliyor bugün gökyüzünde,  Bu gece yine için için yaniyorum,  Oturmus seni düsünüp agliyorum,  Seni, gidisini, sevisini, h...', ARRAY['Türk Edebiyatı','Şiir','Şair Scream5']::text[], 8.5, '{"poet":"Şair Scream5","poet_slug":"sair-scream5","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/agladim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehit Çocuğuyum', 'bir-sehit-cocuguyum-mutlu-celik-b3zem', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya işe gidiyordu,

Ya da yeni gelmiş olurdu

Ben uyandığımda.

Her geldiğinde,

Çok şükür derdi annem.

Gidişinde de bana el sallatırdı

mutlaka.

Sol göğsündeki yıldızı

hala duruyor.

Çok severdim babamı.

Bir dahaki sefere beraberiz derdi,

Ama bunu 

her bayramda söylerdi.

Şapkası çok yakışırdı

hala saklarım.

Bir defa gördüm ağladığını.

Yıllar sonra annem söyledi

Arkadaşı vurulmuş.

O bir damla yaşı hatırlarım da 

çok dokunur bana.

Tabancasını hiç göstermezdi.

Ama bana güven verirdi.

Saçımı her okşayışında

dalıp giderdi...

Ben,aynasız olucam deyince

kahkahayla gülerdi.

Şimdi her sabah karşısında 

şapkamı giydiğim aynayı

bir doğum günümde o verdi.

Soğuk gecelerde çok özlerdim

Kar yağarken dua eder 

Üşümesin Allah''ım derdim.

Babamı çok özler,çok severdim.

Hele,herkes yattıktan sonra nasıl gururlanırdım

Babama güvenip de uyuyorlar,diye..

O sabah yorgun gelirken

Uykucular,daha yeni giderdi

Bazıları selam bile vermezken

O yine de gülümserdi.

O''na derdini anlatanlar

Cebinde kaç kuruş olduğunu duysalar

İnanmazlardı

Bir evim olsa derdi bazen

Bahçesine güller ekerim

Emekli olunca...

Şimdi,

Her gül götürüşümde hatırlarım,

Emekli olamasa da 

Gül bahçesinde yatıyor

Şehidim...

Pek yüzünü göremedim

Ama

O''nu çok özledim

Şimdi,

Sancağını şerefle taşıyan

Bir komiserim...

Hepiniz rahat uyuyun! 

Hep taşınacak sancağınız,

Bütün ŞEHİT POLİSLERİM...', 'Ya işe gidiyordu, Ya da yeni gelmiş olurdu Ben uyandığımda. Her geldiğinde, Çok şükür derdi annem. Gidişinde de bana el sallatırdı mutlaka. ...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bir-sehit-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilhassa', 'bilhassa-turgut-baygin-15sd4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O uzun gecelerde 

Ve bilhassa yağmurlu

bir de Ramo''nun meyhane

ya da Cunda Dalyan

bilirsin gençliğimizi yedik oralarda

Bazen ciğeri beş para etmez şu dünyada

ciğerlerini meyhane köşelerinde bırakmış

bir adam olarak

pişmanlık duymuyor değilim

neden daha dolu dizgin yaşayamadık

diye gecelerimizi

İçimde sızlamıyor değil hani

ve bilhassa yağmurlu gecelerde

adamakıllı...

19 10 00', 'O uzun gecelerde  Ve bilhassa yağmurlu bir de Ramo''nun meyhane ya da Cunda Dalyan bilirsin gençliğimizi yedik oralarda Bazen ciğeri beş para...', ARRAY['Türk Edebiyatı','Şiir','Turgut Bayğın']::text[], 8.5, '{"poet":"Turgut Bayğın","poet_slug":"turgut-baygin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilhassa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-gul-unal-59c3f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baktım

Sen yürüyordun

Hayatımın ta içine.

Gördüm,

Yürüyordun...

Yüzünde

belli belirsiz

bir gülümsemeyle....', 'Baktım Sen yürüyordun Hayatımın ta içine. Gördüm, Yürüyordun... Yüzünde belli belirsiz bir gülümsemeyle.......', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ben-seni-boyle-sevdim', 'ben-seni-boyle-sevdim-gul-unal-yd0l5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sevmedim böyle

Hiç kimseyi

Korkmadım hiç bu kadar

kaybetmekten

Ağlamadım, yalvarmadım

Gitme diye

Kal diye

Ben ömrümde ölmekten

Hiç bu kadar korkmadım

09 Haziran 1995', 'Ben sevmedim böyle Hiç kimseyi Korkmadım hiç bu kadar kaybetmekten Ağlamadım, yalvarmadım Gitme diye Kal diye Ben ömrümde ölmekten Hiç bu ka...', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-seni-boyle-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyudaki Kadin', 'kuyudaki-kadin-sair-ummugul-4u4y4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçeye indim, çicekleri kokladim

Kuyuya gittim, içine baktim

Bu ne güzellik, aman Allahim

Bana elini salladi, içindeki bir kadin

Tipki benim gibi...

O beni sevdi, ben onu sevdim.

Ben gülümsedim, o gülümsedi...

Içim isindi ellimi uzattim.

Elim degdigi an kayboldu!...

Gözlerim birden doldu,

Cünkü kaybettim onu...

O kadini!

Elimi çektim ve tekrar

O agliyordu, kuyudaki kadin,

Tipki benim gibi...

Ne garip bir duygu,

Onu görmek, uzaktan sevmek...

O kadini...

Kendiniz olan,

Dokundugunuzda yok olan,

O kadini...KENDINIZI', 'Bahçeye indim, çicekleri kokladim Kuyuya gittim, içine baktim Bu ne güzellik, aman Allahim Bana elini salladi, içindeki bir kadin Tipki beni...', ARRAY['Türk Edebiyatı','Şiir','Şair Ümmügül']::text[], 8.5, '{"poet":"Şair Ümmügül","poet_slug":"sair-ummugul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kuyudaki-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben mi İstedim', 'ben-mi-i-stedim-adnan-adiguzel-rl2ee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anne hadi vur beni

düşeyim bulutların kollarına

sil gözyaşlarını

sarıl son defa cansız vucuduma

anne hadi vur beni

sık kurşunu sık oğlum der gibi

anne anlamadım ben yaşamayı

ben yaşar gibi yaşar gibi ölüyorum

uykulara düşman gözlerim 

vücudum serseri yorgun dizlerim

bir sevmek vardı taa şuramda

bir ben vardım delikanlı hayatın uçurumlarında

vermek bilirdim sevmeyi

istemeden istenmeden vermek

gitmek bilirdim sevmeyi

ardına bakmadan 

ağırlaşan bedeni sarsmadan

uyandırmadan güneşi

anne hadi vur beni

bıktım hergün ölmekten 

bıktım artık sevmekten

ben ne insanlara sundum kalbimi

dönüpte bakmadılar 

ne sevgilim oldu ne dostum

bir ben oldum kaldırımların müdavimi

bir ben oldum ölülerin hayattaki beklentisi

bir ben oldum

bir ben öldüm

bir ben artık ben değilim anne

hadi vur anne

hadi çek tetiği

ağlarsam namerdim

ölürsem namerdim

hadi vur beni 

sarıl anne sarıl bedenime

okşa saçlarımı

ağla anne ağla

yağmurlar gibi yağ toprağıma

anne beni sen vur bırakma namertlere', 'anne hadi vur beni düşeyim bulutların kollarına sil gözyaşlarını sarıl son defa cansız vucuduma anne hadi vur beni sık kurşunu sık oğlum der...', ARRAY['Türk Edebiyatı','Şiir','Adnan Adıgüzel']::text[], 8.5, '{"poet":"Adnan Adıgüzel","poet_slug":"adnan-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ben-mi-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinimi Sömürme', 'dinimi-somurme-celal-altinay-clwdm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu evrenini sahibi var

Ne yapsak Ona aşikar 

Herkes topraktan yaratıldı

Başkasından ne farkımız var

Düşünce çağdan geri kalmaz

Müslüman dini kalıba konmaz

Vatan korunmazsa din olmaz

İnançlar inhisar altına alınmaz

Günah işleriz biz tüm canlılar

Affedecek tek bir tanrı var

İnanç ticareti yapılmaz hey şarlatanlar

Bırak dinimi sömürme

Ben Onu tanırım o tanrısını tanır

Hesabı ancak tanrıya verir.', 'Bu evrenini sahibi var Ne yapsak Ona aşikar  Herkes topraktan yaratıldı Başkasından ne farkımız var Düşünce çağdan geri kalmaz Müslüman dini...', ARRAY['Türk Edebiyatı','Şiir','Celal Altınay']::text[], 8.5, '{"poet":"Celal Altınay","poet_slug":"celal-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dinimi-somurme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hersey Senın Icın Ayselim', 'hersey-senin-icin-ayselim-recep-tugrul-91cxy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey esmer yuzünü hicrandan besleyen sevgilim.

Kendini bana beni yollara sürükletmeden bilki...

Mavi düşlerine sardıgın o acar delikanlı 

Seni ve aşkını zehir bir yürekle kuşattı.

Ama gün olurda umutlarda yenilirse kalleş bir kurşuna,

Birlik olupta büyüttüğümüz ışıklar yok olur sanma...

Ve unutma AYSEL hanım. O uslanmaz inadın yarısı sen 

Digeri ben olduktan sonra serüvencin seni nasıl olsa nerde Olsa bulur.....', 'Ey esmer yuzünü hicrandan besleyen sevgilim. Kendini bana beni yollara sürükletmeden bilki... Mavi düşlerine sardıgın o acar delikanlı  Seni...', ARRAY['Türk Edebiyatı','Şiir','Recep Tuğrul']::text[], 8.5, '{"poet":"Recep Tuğrul","poet_slug":"recep-tugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hersey-senin-icin-ayselim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yerine Nefret Üretiyorum', 'sevgi-yerine-nefret-uretiyorum-celal-altinay-gtel0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Etrafı görmek istemiyorum 

Sevgi yerine nefret üretiyorum 

Yaşam umudumu kaybediyorum 

Bu çağın gerçeğini anlatamıyorum

		Bu dünya bir kovana benzer

		Kimi gelir kimi gider

		Gün gelir yaşam baldan tatlı geçer

		İğnesi olmayan canlı ne gezer

Her yaşın mutlu bir yanı var

Çelişki doludur bu yaşam 

Sevgi ise en büyük kavram

Görevini yapandır onu yaşatan

Cinsiyet eşitliği bu gün artık yasal

Tabiat kanununu değiştiren kim var

Özgürlüğe saygı duyanlar

Toplumun en büyük varlığı onlar.

	1976', 'Etrafı görmek istemiyorum  Sevgi yerine nefret üretiyorum  Yaşam umudumu kaybediyorum  Bu çağın gerçeğini anlatamıyorum 		Bu dünya bir kovan...', ARRAY['Türk Edebiyatı','Şiir','Celal Altınay']::text[], 8.5, '{"poet":"Celal Altınay","poet_slug":"celal-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-yerine-nefret-uretiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bir Şiir', 'oylesine-bir-siir-aydin-korpe-fqy2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sana öyle bir şiir yazacağımki

kime yazıldığını ne sen anlayacaksın ne başkası

seni öyle anlatacağımki

ne güneş doğacak ne yıldız kayacak

seni öyle yazacağımki

ne dalga çıkıcak ne fırtına kopacak

seni öyle seveceğimki

ne leyla bilecek ne mecnun anlayacak

sana öyle bir şiir yazacağımki

her kelimesi aleme ibret olacak.', 'sana öyle bir şiir yazacağımki kime yazıldığını ne sen anlayacaksın ne başkası seni öyle anlatacağımki ne güneş doğacak ne yıldız kayacak se...', ARRAY['Türk Edebiyatı','Şiir','Aydın Körpe']::text[], 8.5, '{"poet":"Aydın Körpe","poet_slug":"aydin-korpe","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oylesine-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Aynı', 'hepsi-ayni-aziz-nesin-rfo22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç sevgiliyi sonuncu saydıysam

Hepsi de aynı kadındı

Bilmiyorlardı kendilerini

Ama ben biliyordum

Çünkü hep aynı bendim.

Kaç kadını seviyorum dedimse

Hepsi de aynı kadındı

Bilmiyorlardı birbirlerini

Ama ben biliyordum

Çünkü hepsini seviyordum.

Kaç kadın ihanet ettiyse

Hepsi de aynı kadındı

Bilmiyorlardı kaç yaram olduğunu

Ama ben biliyordum

Çünkü vurulan hep bendim.', 'Kaç sevgiliyi sonuncu saydıysam Hepsi de aynı kadındı Bilmiyorlardı kendilerini Ama ben biliyordum Çünkü hep aynı bendim. Kaç kadını seviyor...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hepsi-ayni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktır', 'asktir-nilgun-kudat-in0sa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşi tutsak yanarız,

Mutluluğun resminde olsak solarız,

Yıldızlarda buluşsak kayarız,

Geceleri oynaşsak kayboluruz,

Gündüzleri görüşsek yakalanırız,

Anneme sorsak azarlanırız,

Biz delikanlıyız!Kanımız deli.

Desek sıyırırız.', 'Güneşi tutsak yanarız, Mutluluğun resminde olsak solarız, Yıldızlarda buluşsak kayarız, Geceleri oynaşsak kayboluruz, Gündüzleri görüşsek ya...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Kudat']::text[], 8.5, '{"poet":"Nilgün Kudat","poet_slug":"nilgun-kudat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam unutmuşken Seni...', 'tam-unutmusken-seni-huseyin-cayikli-741yd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tam unutmuşken seni...

yeniden başlatmak için bu yangın 

başından beri bir köz gibi yandım

tam küllendi dedim

yine sen aradın 

ne olur git artık bir daha dönme ne olur.

giderken ateşleri al senin olsun

ben yıllarca yandım al senin onlar

artık bana ihtiyacında yok 

ve o hayatta mutlusunda 

söyle beni neden aradın.

Arkadaşlıkta bitmişti aradan balık ağları çekildi

körfeze kar geçti söyle neden aradın.

Bilirmisin geceler soğuk oluyor buralarda.

Ben hep şairin yazmak istediği şiir oldum.

Sen eşyalarını topladıktan beri ne şiir yazdım nede 

sandığın şair oldum.

sana söylemek istediklerim belki bu satırlarda

telefonun bile artık çok kısa veya ben kısa tuttum.

üç aydan beri seni düşünmedim.

Sen yoktun gitmiştin bir daha gelmeyecektin 

veya artık bu şehirde bile rastlaşmayacaktık.

söyle söyle beni niye aradın?', 'Tam unutmuşken seni... yeniden başlatmak için bu yangın  başından beri bir köz gibi yandım tam küllendi dedim yine sen aradın  ne olur git a...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tam-unutmusken-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki biraz zor', 'belki-biraz-zor-emre-erkut-ud8hh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki biraz zor dedigin gelmis bu gece aklina 

Belki sen hayati basit sanan yasam kolayligisin 

Anlatmak isteyipte anlatamadigin duygularin olmali 

Soylemek isteyipte soyleyemedigin icinde sakli bir sarki 

Sevgiyi varliga satmis yoklugu yasama katmis gibisin 

Korkun bile korkmus sanki bu kacistan 

Askada saygı duymuyorsun belki artik 

Duslerindeki gercek gercege yalan soylemis

Dogru bir soz varsa gozlerdeki saf bakis 

Yasak hasretler tuterse ansizin

Kokunla ararim bir mevsimi bukez 

Ciglik atarken bile urkek baslamis doganlar 

Gozlerde yas kalpte sızı isteyerekmi burdayim diyorsun 

Yasamda uzayan sevgi yoklugunda yanlizligimi paylas haydi 

Bak sana bir sey anlaticam asksa bu  dusunce 

Hani biraktim dedigin kelimeler vardir bazen 

Hani bazi kelimelerde hic unutulmaz degil mi 

Guzel gozlerindeki o bakisi anlatamamki 

Kiskanirlar; geceler haindir nede olsa 

Yildizlari izlerken aya tutulur bir anda 

Yuruyelim hadi burdan burasi yine soguk 

Burasi yine yanlizlik kokuyor nerde gordugum gece isigi 

Ay isigi icimde dolasirken resmin kopup gelicek sanki 

Yine gozlerinde gulumseyecegim belki bu gun 

Dudaklarima hapsettigim bir mimik bile

Gulumse diye agit yakiyor sana 

Oysa sen donuk donuk bakiyorsun  bana 

Sanki hic bir sey olmamis gibi bakiyorsun 

Hadi gidelim burdan burasi yine soguk yine usuyorum sevgilim 

Ver ellerimi bana geri ellerimin icinde yine sicakligin olsun 

Uzat gecenin karanligindaki buyuk gunesi 

Belki biraz zor yanlizlik senli ama sensiz geceler', 'Belki biraz zor dedigin gelmis bu gece aklina  Belki sen hayati basit sanan yasam kolayligisin  Anlatmak isteyipte anlatamadigin duygularin ...', ARRAY['Türk Edebiyatı','Şiir','Emre Erkut']::text[], 8.5, '{"poet":"Emre Erkut","poet_slug":"emre-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/belki-biraz-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Bir Mevsim Gibi Yoklugun', 'sessiz-bir-mevsim-gibi-yoklugun-emre-erkut-qdo58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessiz bir mevsim gibi  yoklugun

Sensiz kac yagmur gordu gozlerim 

Saatlerce dusundum vurulmus yuregim 

Dusmanca yasamak istemedim sensiziligi bile 

Simdi git gozlerine yaslar dolmasin 

Sonra gel yuzunde gulumseme eksik olmasin 

Bulusalim yine gocebe sevincimiz tukenmesin

Sessiz bir gece gibi yanlizligim 

Oyle gunler bekliyorki haykiris dolu sevgiyi 

Hala tutuklu hala dort duvar arasinda o ilgiyi

Ve simdi bile hasretinden vurgunlar yemis sevgim

Simdi git gozlerinde matem olmasin 

Sonra kosa kosa gel dudaklarina sevinc burunsun

Kavusalim yine gizemli sevgimize yorulmasin

Sessiz bir bulusma gibi bakislarin 

Bir kapanip bir acilan goz kapaklarin 

Hala sevdali hala tutkun yaralim 

Yuregimden tasan en guzel duygular 

Kopmasin bekleyelim acilari ama gulusle 

Yıkamasin bizi gunler eskitmesin bir kagit gibi

Simdi git istersen uzun bir sure hic gelme 

Sonra gel kimse ayiramasin birdahada terk etme 

Yanimda kal yine özlemli yine bir dakika icin 

Sana bir omurluk hasret icerim yine bu sevgide seni secerim', 'Sessiz bir mevsim gibi  yoklugun Sensiz kac yagmur gordu gozlerim  Saatlerce dusundum vurulmus yuregim  Dusmanca yasamak istemedim sensizili...', ARRAY['Türk Edebiyatı','Şiir','Emre Erkut']::text[], 8.5, '{"poet":"Emre Erkut","poet_slug":"emre-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sessiz-bir-mevsim-gibi-yoklugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özum Gibi', 'ozum-gibi-emre-erkut-46i2v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdim seni gozum gibi

Elbet sevgili asik gibi

Nefretim oldu hasretler

istedim hayat,omur gibi

Sevdim seni ozum gibi

Ezanlar kadar rab gibi

Vuslat kadar can gibi

Dusuncem oldu ozlem 

imgeledim bazen aski

Milattan once sevdim seni', 'Sevdim seni gozum gibi Elbet sevgili asik gibi Nefretim oldu hasretler istedim hayat,omur gibi Sevdim seni ozum gibi Ezanlar kadar rab gibi ...', ARRAY['Türk Edebiyatı','Şiir','Emre Erkut']::text[], 8.5, '{"poet":"Emre Erkut","poet_slug":"emre-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozum-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-ozgur-durman-vr1ag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni yazdım sahildeki kumlara,

İsmini fısıldadım içimdeki duygulara,

Sordum dalgalara gelsin dedim yeter dedim.

Ve sen yanlızca bitanem dinlediğim şarkılarda,

Duyduğum dalgalarda, sigaramın dumanında,

Bir hayel olup bir özlem olup kaldın,

Seni sordum sevdalara, göklerdeki yıldızlara,

İçimdeki korkulara, gönlümdeki arzulara,

Günler geçti sen gelmedin sevgilim.', 'Seni yazdım sahildeki kumlara, İsmini fısıldadım içimdeki duygulara, Sordum dalgalara gelsin dedim yeter dedim. Ve sen yanlızca bitanem dinl...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-ariyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmak', 'kavusmak-necip-fazil-kisakurek-0ci1v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne görsem, ötesinde hasret çektiğim diyar; 

Kavuşmak nasıl olmaz, mademki ayrılık var?', 'Ne görsem, ötesinde hasret çektiğim diyar;  Kavuşmak nasıl olmaz, mademki ayrılık var?...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kavusmak-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yeni Bir Acaba', 'yine-yeni-bir-acaba-ayhan-eralp-9aikp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acemidir gönlüm, acemi.

Cüretkar bir acemi!

Ve de yürekli!

Takılıp yanılmış anlarımda

Bu son demişliğimin

Hemen ertesinde

Pençesine düşüyorum,

Dirilttiğim ümitlerle

Bir kez daha, son kez daha!

Yeniden bir daha!

Düşüyorum sevdaların peşine.

Gönlümde her bir ümidin,

Yetim beyaz tomurcukları

Teslime koşuyor...

Yaralıdır gönül, yine yaralı

Öfkeli yarım kalan her şeye

Yine bir yarım!

Hep kendi yarım!

Kaldı hepsi ayrı bir yerde.

Hepsi ayrı bir yarım, ayrı seferde

Asla bir bütün etmiyor,

Bu kadar yarım.

Acemidir gönlüm, acemi.

Cüretkar bir acemi!

Ve de yürekli!

Ne kalbim uslanır,

Ne de Aykut usanır.

Bir yarım daha büyütüyorum

Terütaze ümitlerle

Yine yeni bir acabanın peşinde

Ruhum da bir telaş

Acemi bir telaş,

İçim pür telaş.

Ustalaş, ustalaş!

Ey kalbim ustalaş!

Artık ustalaş...

   12.09.2000', 'Acemidir gönlüm, acemi. Cüretkar bir acemi! Ve de yürekli! Takılıp yanılmış anlarımda Bu son demişliğimin Hemen ertesinde Pençesine düşüyoru...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Eralp']::text[], 8.5, '{"poet":"Ayhan Eralp","poet_slug":"ayhan-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yine-yeni-bir-acaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Hicret', 'gunese-hicret-ayhan-eralp-50zu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne   çıkar    mehtabın    güneşe   kaprisinden

Itri''ye   beste    çaldıran   bülbül   öfkesinden

Ömür, dostlar ve sözler  birer  birer   terk  eder

Geç kalan  göçmen  kuşlar güneşe hicret eder.

Kuyulara   atılmış   Yusuf''ken  sensiz  gönlüm

İsimsiz  hüzün   çağımda   yoldaşımdır   ölüm

Kaderim sensizlikse bundan  sonra hep  keder

Geç kalan göçmen kuşlar güneşe hicret  eder.

Mutlak    bir   sessizliktir      içimde   sensizlik

Cennetten   kovulmuş   Adem''dir    isimsizlik

Ayeser  ne  teslim   olur   nede   isyan   eder

Geç kalan göçmen kuşlar güneşe hicret eder.

 -22.08.2000', 'Ne   çıkar    mehtabın    güneşe   kaprisinden Itri''ye   beste    çaldıran   bülbül   öfkesinden Ömür, dostlar ve sözler  birer  birer   ter...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Eralp']::text[], 8.5, '{"poet":"Ayhan Eralp","poet_slug":"ayhan-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunese-hicret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-aziz-nesin-azpxo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözler önünde işte

Gittikçe arınıyorum kendimden

Her giden güzelleşir

Gidiyorum güzelleşmek için

Unutulsun diye çirkinliklerim

Gelecek birisi güzeldir

Gelince güzel değil

Hele gelmişse çirkin

Yaşam, ölüm gelecek diye güzel

Ey güzeller güzeli beklediğim

Kaç saatim, kaç dakikam ya da saniyem

Artık ne gelmek ne de gitmek

Yaşamın en zor yani beklemek

Hiçbirimiz beklemedik doğmayı,

Doğduğumuzdan beri beklediğimiz

ÖLMEK', 'Gözler önünde işte Gittikçe arınıyorum kendimden Her giden güzelleşir Gidiyorum güzelleşmek için Unutulsun diye çirkinliklerim Gelecek biris...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklemek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku Ki Bil', 'oku-ki-bil-sefil-selimi-5fd6t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Sabit İnce’ye-

Hak yolunu sordun benden,

Canlı Kuran oku ki bil.

Şirklerin alınır senden,

Denli piran oku ki bil.

Özü bilen temiz olur,

Ten bağı gülünü bulur.

Masiva imanı alır,

Şanlı yaran oku ki bil.

Menzil ehli dile açık,

Yaradan her kula açık.

Göl olmamız sele açık,

Önlü eren oku ki bil.

Bir kapıda bebek gibi,

Rehberlere olup tabi.

Her kimse seçemez Rab’ı,

Künlü gören  oku ki bil.

Bedendeki sefil durum,

Beyninizden ister yorum.

Kibirsizler kalmaz yarım,

Ünlü duran oku ki bil.

Sefil Selimi’niz ince,

Benim şahım benden önce.

Böyle olmalısın sence,

Yönlü soran oku ki bil. 

AŞIK SEFİL SELİMİ', '-Sabit İnce’ye- Hak yolunu sordun benden, Canlı Kuran oku ki bil. Şirklerin alınır senden, Denli piran oku ki bil. Özü bilen temiz olur, Ten...', ARRAY['Türk Edebiyatı','Şiir','Sefil Selimi']::text[], 8.5, '{"poet":"Sefil Selimi","poet_slug":"sefil-selimi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oku-ki-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Rüzgar', 'serseri-ruzgar-fatih-erili-abc4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Serseri bir rüzgardım önce 

Duruldum ellerine degince

Tenin en güzel duragıydı hikayemin 

Dokunup geciverdim saçlarına demin

Bir sıcak düş getirdim yaz bahçelerinden sana

N''olur o narin bedenine birkerecik sarsana

Hapset beni dolmalıyım hücrelerine

Sıkı tut nefesini kalmalıyım yüreğinde

Dinle bak hangi şarkıyı söylüyor sesim:

''''Şimdi gözlerime ağlamayı öğrettim''''

Güzelliğin cam buğusuna çizilmiş resim

Sen hayallerimin,aşkımın kesiştiği yerdesin.

Baharı bile getiririm  istesen 

Bulutlardır dostum,tek aşkım da sen

Yazık ki gitmeliyim bu şehirden

Biliyorsun bir asi rüzgarim çünkü ben

Ne zaman bir yerlerde bir deli rüzgar esse

Ver kulağını dinle

Haykırım sana sevgimi tabiatın diliyle

Belki de hiç anlamayacak olsan bile', 'Serseri bir rüzgardım önce  Duruldum ellerine degince Tenin en güzel duragıydı hikayemin  Dokunup geciverdim saçlarına demin Bir sıcak düş g...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erili']::text[], 8.5, '{"poet":"Fatih Erili","poet_slug":"fatih-erili","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/serseri-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ben O Hickimse', 'sen-ben-o-hickimse-i-stanbulda-atinali-dp62h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne sen vardın hayatta

Nede ben...

O da yoktu zaten

Hic olmamıstı...

Bir kac mevsim gecmis

Tecrubeler artmıstı...

Anlamıstım ama  cok gecti.

Sevgi kocaman bir yalandı.

Gercek olan alıskanlktı.

Konu insandı..

Gülmüstüm

İnsan her seye alısırdı...

Sevgi pahalı bir elbise olmustu

Bazen bir mücevher', 'Ne sen vardın hayatta Nede ben... O da yoktu zaten Hic olmamıstı... Bir kac mevsim gecmis Tecrubeler artmıstı... Anlamıstım ama  cok gecti. ...', ARRAY['Türk Edebiyatı','Şiir','İstanbulda atinali']::text[], 8.5, '{"poet":"İstanbulda atinali","poet_slug":"i-stanbulda-atinali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ben-o-hickimse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane Çiçekleri', 'bahane-cicekleri-ayhan-eralp-4gmgf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yakıp    hasret   dağlarını

Yıkıp   bir   bir   engelleri

Gelirken   sana   hesapsız

Bahane            çiçeklerini

Büyütüp   beslemek  niye

Terk  edip  tüm zırhlarımı

Sundum   sana   sırlarımı

Sermişken  sana  kalbimi

Bahane           çiçeklerini

Büyütüp  beslemek  niye

Hiç olmazsa  bir bakışın

Solar bak içimde   aşkın

Kalırsın   avare    şaşkın

Bahane          çiçeklerini

Büyütüp  beslemek  niye

Kırma   bendeki  ümidi

Söndürme  aşk   ateşini

İçimde   ruhunun     eşi

Bahane        çiçeklerini

Büyütüp beslemek niye

Sönse de   güneş    ışığı

Bitmez  dünyanın telaşı

Koma   kalbine   hesabı

Bahane         çiçeklerini

Büyütüp beslemek niye

Varın yokun hep karışmış

Hayat  ölüm  bir  karışmış

Aykut''um aklın   karışmış

Bahane            çiçeklerini

Büyütüp   beslemek   niye

       AYHAN ERALP

            22.09.2000', 'Yakıp    hasret   dağlarını Yıkıp   bir   bir   engelleri Gelirken   sana   hesapsız Bahane            çiçeklerini Büyütüp   beslemek  niye ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Eralp']::text[], 8.5, '{"poet":"Ayhan Eralp","poet_slug":"ayhan-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bahane-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-ozgur-durman-amy37', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün biterse akşam üstü,

Hayalim takılacak gözlerine,

Bir rüzgar uçarak saçlarına,

Ben geleceğim aklına,

Gururun düşerse ayaklar altına,

Boşver hatırlamaya çalışma,

Birgün gelirsen mezar taşıma,

Ben geleceğim aklına ağlayacaksın.', 'Gün biterse akşam üstü, Hayalim takılacak gözlerine, Bir rüzgar uçarak saçlarına, Ben geleceğim aklına, Gururun düşerse ayaklar altına, Boşv...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglayacaksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-ozgur-durman-u58mt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlarla dolu gökyüzüne bakarken.

Sen geldin aklıma seni düşündüm

Yokluğunu hissettim gönlümde,

O an bir burukluk çöktü içime,

Bir yıldız kaydı gökyüzünden.

Sanki inat edercesine,

Kaydı gözyaşlarım yanaklarımdan.

Kaydı o yıldızın ardından.', 'Yıldızlarla dolu gökyüzüne bakarken. Sen geldin aklıma seni düşündüm Yokluğunu hissettim gönlümde, O an bir burukluk çöktü içime, Bir yıldız...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Birgün', 'eger-birgun-ozgur-durman-tls0e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün tersine akarsa nehirler.

İnsanlar denizde,

Balıklar karada yaşarsa,

Bülbül susupta,

Gül ötmeye başlarsa,

Bulutlar yere inerse,

Yağmur göğe doğru yağarsa,

''Gel buraya benim ol'' derse hak,

İşte seni ozaman unutabilirim.', 'Birgün tersine akarsa nehirler. İnsanlar denizde, Balıklar karada yaşarsa, Bülbül susupta, Gül ötmeye başlarsa, Bulutlar yere inerse, Yağmur...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eger-birgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-ozgur-durman-7o3i6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zor şeymiş meğer seni beklemek,

Bir bulup bir kaybetmek ellerini,

Yollarda caddelerde seni beklemek,

Açılan her pencerede seni görmek,

Sonra durup durup saatlere küfür etmek,

Oysa seni sevince beklemek ne güzel.

Seni sevince geceler daha az karanlık.

Gündüz daha çok mavi,

Seni sevince hergün daha güzel.

Şimdi ölesiye sevildiğinden habersiz.

Kimbilir nerelerdesin?', 'Ne zor şeymiş meğer seni beklemek, Bir bulup bir kaybetmek ellerini, Yollarda caddelerde seni beklemek, Açılan her pencerede seni görmek, So...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozleyis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ağlarım', 'ben-aglarim-ozgur-durman-ph2e5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün ortada hiçbir sebep yokken.

Bir acı saplanı verirse güreğime,

Hiçbir sebep yokken gözlerim dolu verirse,

Dışarıda sıcak bir gün varken.

Gözlerimin önüne bir sis perdesi çekilirse,

Anlarınki o an başka elleri tutmuşsundur.

Ben anlamasam bile yüreğim anlarki,

Aşık olmuşsundur.

Kendine sevecek bir kalp bulmuşsundur.', 'Birgün ortada hiçbir sebep yokken. Bir acı saplanı verirse güreğime, Hiçbir sebep yokken gözlerim dolu verirse, Dışarıda sıcak bir gün varke...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ozgur-durman-csfz0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine gözlerimde tütüyorsun.

Sigaramın dumanında seni arıyorum.

Bulamayınca telaşlanıyorum.

Neyapacağımı bilemiyorum.

Hemen telefona sarılıp.

Bir kelimede olsa,

Sesini duymak duymak,

Sana tekşey söylemek istiyorum.

SENİ SEVİYORUM', 'Yine gözlerimde tütüyorsun. Sigaramın dumanında seni arıyorum. Bulamayınca telaşlanıyorum. Neyapacağımı bilemiyorum. Hemen telefona sarılıp....', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkunum', 'tutkunum-ozgur-durman-0xknu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle her karşılaştığımda güzelim.

Gözlerim baka birşey görmüyor.

Alabildiğine çarpıyor kalbim.

Birbirine dolaşıyor ayaklarım.

Heyecandan titriyor bütün benliğim.

Demekki sana tutkunum.

Sana hasretim...

Varlığın heran süşlerimde yaşıyorsa,

Geçmiyorsa sensiz zaman,

Kanım dolaşıyorssa damarlarımda,

Sarıyorsa vücudumu adımadım,

Demekki sana tutkunum.', 'Seninle her karşılaştığımda güzelim. Gözlerim baka birşey görmüyor. Alabildiğine çarpıyor kalbim. Birbirine dolaşıyor ayaklarım. Heyecandan ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutkunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım', 'muhtacim-ozgur-durman-9c4jc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlu birgün de,

Sana koşar gelirsem,

Islak şaçlarımı düzelt.

Başımı omuzuna yasla,

Nemli dudaklarıma,

Dudaklarını ansızın dedir.

Masum ve üzgün bir

Çocuk gibi konuşursan

Anla sana muhtacım.

Ver elini ellerime,

Yalanda olsa birkere,

SENİ SEVİYORUM de.', 'Yağmurlu birgün de, Sana koşar gelirsem, Islak şaçlarımı düzelt. Başımı omuzuna yasla, Nemli dudaklarıma, Dudaklarını ansızın dedir. Masum v...', ARRAY['Türk Edebiyatı','Şiir','Özgür Durman']::text[], 8.5, '{"poet":"Özgür Durman","poet_slug":"ozgur-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muhtacim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Kader', 'zalim-kader-kemal-soylu-mvbq2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkıma ilanen. 

İki dakka ayar etmesen 

benim gönlümü calıp gitmesen 

zalimsin be kahbe kader 

vurdun gittin giderken hiç sordun mu bana zalim kader

 eger beni unutmak istersen kumlara yaz 

o zalim esen ruzgar alır götürür benim ismimi hatırandan

eger beni hiç unutmak istemezsen kalbine yaz o zaman 

sen ölünceye kadar orda kalır 

ama zalimsin be kader sen bundan anlar mısın?', 'Aşkıma ilanen.  İki dakka ayar etmesen  benim gönlümü calıp gitmesen  zalimsin be kahbe kader  vurdun gittin giderken hiç sordun mu bana zal...', ARRAY['Türk Edebiyatı','Şiir','Kemal Soylu']::text[], 8.5, '{"poet":"Kemal Soylu","poet_slug":"kemal-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zalim-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Zaman Rakıcıları....', 'eski-zaman-rakicilari-dergahci-kalem-kacamaklari-zbgh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizler,

eski zaman rakıcılarıydık

fasl-ı muhabbetin

âşina kiracılarıydık

karafaki sürahide sevda yüzdürür,

pilakiye çatal atar,

zülf-i yar''e şiirler yazardık...

''Ağır'' başlardı gece

hünerli ellerin okşadığı 

bir tambur eşliğinde 

''haddimizi aşan'' sohbetlere dalardık

''ittihat-terakki'' yokuşundan sapar,

''derin devlet'' sokağından çıkardık....

Zaman yiterdi tambur sesinde

ne dün dün olurdu, ne bugün bugün

''geçti sevdalarla ömrüm,

ihtiyar oldum bugün'' diye 

inlemekteyken tambur,

yan masadan bir sedâ ;

''eline sağlık üstad,

dilşâd olasın her gün''..

üstad''ın gözleri mahmur.....

''Dem'' tutma vaktine gelindiğinde

ekşimsi kokusunda meyhanenin

bir zülf-i yar belirirdi

kuytu köşelerinde yüreklerin

''Yar, 

zülf-i yar 

sen bi-vefa, bi-haber,

ben mahzun, ben ketum,

ben ağyar....

Zülf-i yar ; eski yangınlardan bir kor,

Zülf-i yar ; her gönülde rengarenk olur..

Zülf-i yar ; yıldızlı gece

Zülf-i yar ; beli ince

Zülf-i yar ; zemheride bir serçe.......''

Dedim ya,

bizler eski zaman rakıcılarıydık

kimbilir kaç Zülf-i yar''in 

rüzgarlara savurup

harcadıklarıydık....

  (Kalem Kaçamakları)', 'Bizler, eski zaman rakıcılarıydık fasl-ı muhabbetin âşina kiracılarıydık karafaki sürahide sevda yüzdürür, pilakiye çatal atar, zülf-i yar''e...', ARRAY['Türk Edebiyatı','Şiir','Dergahcı Kalem Kaçamakları']::text[], 8.5, '{"poet":"Dergahcı Kalem Kaçamakları","poet_slug":"dergahci-kalem-kacamaklari","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/eski-zaman-rakicilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınır Ötesi Sevdalar...', 'sinir-otesi-sevdalar-dergahci-kalem-kacamaklari-vh9n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '..''Baharda tanıdım

   güzde tutuldum,

   dağlarda şahin''dim

   düzde tutuldum''...diye 

yakılmalıydı benim türküm..

Eskiydi özlemlerim

seninle bir kez daha 

eşelenmişti közler..

Esirdi sözcüklerim,

boğazımda zincirli..

Kederliydi bakışlarım,

gözlerinde mülteci....

Nedendi bilemem,

aman diler, af dilerdi

ve dalıp giderdi

kahverengi.....

Kayıp zamanların 

aşklarını arardım....

eskimiş yüreğimden,

yırtık bir yelken açmıştım

macro cosmos''a.....

ceplerime düş tohumu doldurup,

puslu gecelerde göğe salardım..

Ve ''neden bir var, bir yoksunuz?'' diye

yıldızlara sataşırdım.....

Haykırdım....

olmadı.....

sesim, beynimin kanyonlarında

kendini tekrarlayan bir tutsaktı..

Gerçek zamanların katılığında

varlığımı sakatladım.....

Sınır ötesi bir sevdada vuruldum,

Künyem saçlarında kaldı...........', '..''Baharda tanıdım    güzde tutuldum,    dağlarda şahin''dim    düzde tutuldum''...diye  yakılmalıydı benim türküm.. Eskiydi özlemlerim seninl...', ARRAY['Türk Edebiyatı','Şiir','Dergahcı Kalem Kaçamakları']::text[], 8.5, '{"poet":"Dergahcı Kalem Kaçamakları","poet_slug":"dergahci-kalem-kacamaklari","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sinir-otesi-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır Diyememek', 'hayir-diyememek-riza-aslan-qrejc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayır diyemeyişimden değil bu yaşananlar

söyleyemeyip de içime attıklarım

bana ait değil

gizlediğim

,kendimin bile bilmediği

içimdeki - ben - 

bana ait değil

yıpranmış,karalanmış

yamalı bir poğaça gibi sarmalanmış

utandığım,sıkıldığım

içimdeki - ben -

bana ait değil

gözlerim açıkken görmediğim

at gözlükleriyle

gördüğümü zannettiğim

sahiplendiğim,savunduğum

uğruna ağladığım

sevdiğim,aşık olduğum

içimdeki - ben -

bana ait değil

yalnızlıktan şikayet edip

yalnızlığımı seçtiğim

yarınlar isteyip

hep geçmişte geçmişi yaşadığım

tam bitti derken 

yeniden başladığım- başlayamadığım-

içimdeki - ben -

bana ait değil

05-11-2000

ankara karacan', 'hayır diyemeyişimden değil bu yaşananlar söyleyemeyip de içime attıklarım bana ait değil gizlediğim ,kendimin bile bilmediği içimdeki - ben ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayir-diyememek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Daralıyor-2', 'i-cim-daraliyor-2-riza-aslan-f4be9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'içim daralıyor bu aralar

sık sık

çözümsüz zamanlar içinde

çözüm arıyorum

göğüs kafesime sığmayan

çarpıntılarla savrulup duruyorum

kurumuş bir dal gibi

gözlerim dalıyor

ağlayamıyorum

bir şeyler var çözülmesi gereken

çözemiyorum

04-11-2000

karacan ankara', 'içim daralıyor bu aralar sık sık çözümsüz zamanlar içinde çözüm arıyorum göğüs kafesime sığmayan çarpıntılarla savrulup duruyorum kurumuş bi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icim-daraliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Daralıyor-1', 'i-cim-daraliyor-1-riza-aslan-pkmiz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'içim daralıyor bu aralar

sık sık

dalıp gidiyorum

anlamsız derinliklere

gözlerim dalıyor uzaklara

bir şeyler arıyorum

içimdeki boşluğu dolduracak

sözler arıyorum 

acımı hafifletecek

04-11-2000', 'içim daralıyor bu aralar sık sık dalıp gidiyorum anlamsız derinliklere gözlerim dalıyor uzaklara bir şeyler arıyorum içimdeki boşluğu doldur...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/icim-daraliyor-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağarcık', 'dagarcik-tayyar-cavus-tx65x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Konuştuğun dilin hakkını ver.

Birkaç kelimeyle sınırlama kendini.

Sana dar gelir gever,

Yık bendini.', 'Konuştuğun dilin hakkını ver. Birkaç kelimeyle sınırlama kendini. Sana dar gelir gever, Yık bendini....', ARRAY['Türk Edebiyatı','Şiir','Tayyar Çavuş']::text[], 8.5, '{"poet":"Tayyar Çavuş","poet_slug":"tayyar-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dagarcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Çok Karışık', 'aklim-cok-karisik-hakki-yalcin-cx8tb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O kızın gözlerinde

Gördüğüm bir ışıktı

Göz kırptı sevdalara

Dünyayla barışıktı

Yüreğime dolanan

Sanki bir sarmaşıktı

Kalbinde dolu sevda

Belki bana aşıktı

Aşk onun için erken

Yıkılırdı severken

Ona veda ederken

Aklım çok karışıktı', 'O kızın gözlerinde Gördüğüm bir ışıktı Göz kırptı sevdalara Dünyayla barışıktı Yüreğime dolanan Sanki bir sarmaşıktı Kalbinde dolu sevda Bel...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklim-cok-karisik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenler Gece Ağlar', 'sevenler-gece-aglar-hakki-yalcin-38wq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can dayanmaz can

Anılar hala

Sana yanık

Gözlerim suçlu

Yüreğim yanık

Aşkıma geceler tanık

Sevenler gece ağlar

Dinlesin bütün dağlar

Üç günde bitmiyor

Böyle sevdalar

Hasretin beni üzsün

Gitsende ölümsüzsün

Mahşere dek benim

İki gözümsün', 'Can dayanmaz can Anılar hala Sana yanık Gözlerim suçlu Yüreğim yanık Aşkıma geceler tanık Sevenler gece ağlar Dinlesin bütün dağlar Üç günde...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevenler-gece-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzak Düşmüşüm', 'senden-uzak-dusmusum-hakki-yalcin-u8dh1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yastığımın bir ucuna

Koyup gittin anıları

Hasretinle ateşledin

İçimde ki yangınları

Senden uzak düşmüşüm

kokun burnumda tüter

Kırılıp dökülmüşüm

Kalanlar bana yeter

Bu suskun odalarda

Seni bekler ağlarım

Aklımda gözlerin var

Dilimde dualarım...', 'Yastığımın bir ucuna Koyup gittin anıları Hasretinle ateşledin İçimde ki yangınları Senden uzak düşmüşüm kokun burnumda tüter Kırılıp dökülm...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-uzak-dusmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-i-rfan-mutluer-komk3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim senden başkasını görmüyorsa,

Seni sevdiğim içindir.

Kalbim delicesine çarpıyor

Ve ellerim titriyorsa

Ve konuşmayı unutmuşsa dilim

Ve zamanı unutmuşsam seninleyken

Ve yarınlarımı sana ayırmışsam

Ve yaşamın tadını seninle almışsam,

Seninle mutluysam,

Seninle gururluysam,

Ayaktaysam seninle, 

Dirençliysem seninle

Ve yarınlarıma umutla bakıyorsam,

Seninle ağlıyor, seninle gülüyorsam,

Geceleri uyku girmiyorsa gözlerime,

Her anımı seninle yaşamak istiyorsam,

Seni sevdiğim içindir bir tanem,

Seni sevdiğim için.

                            1989 - ANKARA', 'Gözlerim senden başkasını görmüyorsa, Seni sevdiğim içindir. Kalbim delicesine çarpıyor Ve ellerim titriyorsa Ve konuşmayı unutmuşsa dilim V...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğumdur Yaşanan Çağ', 'yoklugumdur-yasanan-cag-kemal-gunduzalp-k9bs1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık mor bir ırmaktı yaşamımda, akıp durdu

yitik zamanda rüzgarla paylaşılmış mutluluklarım yoktu

köprüsüzlük, ey iletişimin tutsak edilmiş yasak dili,

ey ölümcül aşk özlemi, kavuşamadım gitti işte...

Yitirecek hiçbir şeyim kalmadı, çekincesiz söylüyorum

ağlamak isterdim şimdi, sahipsiz bir çocuk gibi

insansal olan en güzel duygu değil midir ağlayabilmek

yalnız, yürekli, aldatılmış ve aldanmış; düş ile gerçek

çatışmayan ne kaldı zaten, hangi el değmemiş çelişki? 

Yıldızları izlemiyorum artık her gece gökyüzünde

kendi yıldızı kaymış biriyim, karanlıkta ve umutsuz

bu bireysel bir ayaklanmadır, kimse umursamaz

kimi sözcükleri unutmalıyım, kimi özel adları da

sevgilisiz insanlarla tüm ilişkilerimi kesmeliyim:

Ne berbat ve yoksul bir yaşamları vardır, kimbilir? 

Düşgücü gelişmemiş bir yaratığın yüzüne tükürmeliyim

çocukluğum, esmerliğim, gören sol gözüm, ey geçmiş 

ve gelecek

çağlar! 

Mavi bir ırmak olsun akıp giden susuz yaşamım

ölümün kül rengine soğuk bir şaka diye yazılsın:

Artık yitirecek bir şeyim yok, kendimden başka...

Yorulmuşum, akşamın koynunda tamgün uykulu 

gözlerimde yitirilmiş bir yaşamın kara çizelgesi 

uzaklara düşen sınıf geçmiş sevgili arkadaşlarım

en çok onlar devrimciydi, en yiğit, en militandı onlar

Eylül rüzgarlarıyla yaprak gibi yükseldiler sapsarı-

doruklara doğru, kendi bencil ve bireyci tepelerine

bense hiç yengi tadamamış yoksul ve hâlâ onurlu

gülme sakın! Yaşamımda savsöz olmasın isterim

bir aşkın eteklerine tutunmuşken içten ve yalnız.

''Sen de hiç çiçek sevmiyorsun kardeşim, bırak bunu! ''

Bıraktım mı kendimden korkarım, pişmanlığımdan

yabancı kalsın derim bana böyle bir duygu/suzluk

özeti karalanmış kötü bir ömrün sahibi desinler:

Burnunun dikine gitti hep ve her zaman kanadı-

yüreği, kimselerin tadamadığı sevda oklarıyla...

Ey yol değiştiren ırmak, ey yolcu, ey kötürüm aşk

ey serseri gibi dolaşan sokaklarda: Ben yokum artık!', 'Ayrılık mor bir ırmaktı yaşamımda, akıp durdu yitik zamanda rüzgarla paylaşılmış mutluluklarım yoktu köprüsüzlük, ey iletişimin tutsak edilm...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yoklugumdur-yasanan-cag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Ateşe Saldım', 'yuregimi-atese-saldim-kemal-gunduzalp-idcft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuk Eşkıya filmini anlatıyor bir çocuğa

dilinin ucunda en acıklı yanından Fırat türküsü: 

-Eşkıya’nın adı Baran diyor, yağmur gibi gözyaşı

Fırat biraz da eskimiş zamanlarda kardeşliğin sınırı

ötesi yok: Kejé’nin suskun sevdası yüreklerde.

Yüreğimi ateşe saldım, arkası yok, şiir öldü: 

Kejé, Seyithan filminde Yılmaz Güney’in sevgilisi

Ağıt ve destan. Aşk ve ayrılık. Ölüm ve sevgi.

Bir film en çok neyi anlatabilir başka türlü

en evrensel yanı nedir insanın kendinden başka? 

Fellini’nin gözlüklerini nasıl taşıdılar Roma’da

en İtalyan olan Amorcord’un taşra görüntüleri: 

Aşk gelip çatacak, ama ben uyudum ve kaçtı

beklenmeyen konuktu sanki ve sürpriz yoktu

çocuk Eşkıya filmini, ben yüreğimi saldım ateşe!', 'Bir çocuk Eşkıya filmini anlatıyor bir çocuğa dilinin ucunda en acıklı yanından Fırat türküsü:  -Eşkıya’nın adı Baran diyor, yağmur gibi göz...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregimi-atese-saldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görülmüştür', 'gorulmustur-sunay-akin-sxv0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yak

Mektubun ucunu,

Ne sevgini

Sayfalar dolusu

Dile getir....

Zarfı kapatırken yalnız,

Kuytu dudaklarını 

Çokça değdir.....', 'Ne yak Mektubun ucunu, Ne sevgini Sayfalar dolusu Dile getir.... Zarfı kapatırken yalnız, Kuytu dudaklarını  Çokça değdir........', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gorulmustur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Evcilik', 'yalan-evcilik-gulseren-onay-6zg89', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep birlikte oynardık çocukken,

Hep birlikte büyüyelim isterdik.

Hiç bir şey vermezdi

Oynadığımız evciliğin tadını.

Elin elime değdiğinde

İlk gençlik dönemlerimde

İçim titrerdi.

Ve bir gün;

Ellerin ellerimdeyken

Aynı lokmayı paylaşıp,

Aynı yastıkda uyumaya,

Aynı evde oturup,

Aynı durakda beklemeye,

Aynı çocukları büyütüp,

Birlikte yaşlanmaya,

Hatta birlikte ölmeye

Yemin ettik.

Ama bu gün,

Artık ellerin ellerimde değil,

Gönlün gönlümde.

İkimiz ayrı ayrı sokaklardan

Aynı rehinciye

Gençliğimizi geri istemeye gidiyoruz.

(20.01.2000 Antalya)', 'Hep birlikte oynardık çocukken, Hep birlikte büyüyelim isterdik. Hiç bir şey vermezdi Oynadığımız evciliğin tadını. Elin elime değdiğinde İl...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalan-evcilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-gulseren-onay-e7o0f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bu yalnızlık,

Bu yalnızlık öldürecek.

Bu dopdolu koca şehirde

Ne başımı koyacak bir omuz,

Ne tutunacak bir el var,

Nede bir kimse

Teselli edecek yüreğimi.

Bir gün 

Beni bu yalnızlık,

Beni bu sessizlik,

Beni bu kimsesizlik

Öldürecek.

Ağlamayacak 

Ardımdan kimse.

(08.02.2000 Antalya)', 'Beni bu yalnızlık, Bu yalnızlık öldürecek. Bu dopdolu koca şehirde Ne başımı koyacak bir omuz, Ne tutunacak bir el var, Nede bir kimse Tesel...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Gülü', 'sevgi-gulu-gulseren-onay-wy0yl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir gonca güldüm

Seni tanıdığımda.

Açılıp serpildim,

Katmerlendim

Her kokladığında.', 'Ben bir gonca güldüm Seni tanıdığımda. Açılıp serpildim, Katmerlendim Her kokladığında....', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgi-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluğa Not Düşmek', 'sonsuzluga-not-dusmek-kemal-gunduzalp-xptvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Özel Bir Başkaldırı Denemesi İçin) 

Tarih düşürmenin de bir anlamı olmalı zaten

kötü günlerin dipnotları diyedir bütün bunlar.

Yürüyen sen (kim o?)    Durma sakın, hep yürü

Durgun bir suyun sesindeyim/Göl ve akarsu.

Alçaklığın da bir adı olmalı zaten, değil mi, 

alçakların adını kim söyleyecek şimdi? Tarih’e! 

Ölü askerlerin düşlerini düşündüm, aşklarını

barışı görmemiş savaşçıların yatışını kırlarda

dar gündür gelir geçer dedim, geçer mi bilmem

yine umutlandım, yine gülerim belki  bir gün diye

kara bir gün için beynimin gizli köşelerinde

tarih düşerken defterime renkli gelecekler için.

Yoruldum ağlamaktan, sen de bilirsin, tanık ol

gözyaşlarımı yaladım gizli/tuzluca-gizli/ce...

Ey kimsesizlik, ey özgürlük sen nerdesin şimdi? 

hangi bireyin ağlatısı bu destansızlıkta duran?

Bu sorulardan da bıktım zaten. Ah, yaşamak! 

Bir savaş yorgunuyum, barış diyorsam size

yaşamım bir ufuk çizgisinde bitmesin diyedir.

Sonsuzluğa not düşmek, su üstüne yazı yazmak

kapıları kim çalacak, ne zaman; çocuklar uyuyor mu? 

Ben hazırım dünyaya suçsuzluğumu itiraf etmeye.', '(Özel Bir Başkaldırı Denemesi İçin)  Tarih düşürmenin de bir anlamı olmalı zaten kötü günlerin dipnotları diyedir bütün bunlar. Yürüyen sen ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonsuzluga-not-dusmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçma Sapan Aşk', 'sacma-sapan-ask-zafer-gun-yzhbt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakalamışken sert yaşamak gerekiyor aşkı.

Aşk insanı çıldırtmalı,

ihtiraslar barındırmalı içinde,

kavgalar ve kanatan öpüşmeler...

Aşk bu saçma sapan olmalı,

bencilce yaşanmalı;

ağlamalı birileri, çaba harcamalı.

Bittiği gün umarsızca unutmalı;

aşkı kahkahalara boğmalı.

Bitirmişken sert bitirmek gerekiyor aşkı,

aşk bu saçma sapan son bulmalı.', 'Yakalamışken sert yaşamak gerekiyor aşkı. Aşk insanı çıldırtmalı, ihtiraslar barındırmalı içinde, kavgalar ve kanatan öpüşmeler... Aşk bu sa...', ARRAY['Türk Edebiyatı','Şiir','Zafer Gün']::text[], 8.5, '{"poet":"Zafer Gün","poet_slug":"zafer-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sacma-sapan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Gitme Sevdası', 'cekip-gitme-sevdasi-zafer-gun-tafm1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir çekip giderim

ansızın

anlayamazsın

ki anlatamam anlamsızdır gidişlerim.

İçime sevda düşmüş bir kere

(çekip gitme sevdası)

aklımda hep o yalnızlık belası

Bunaldığın anlarda gelirim aklına

boğulduğun, kaçıp kurtulmak istediğin anlarda

ki anlarsın o zaman

ulaşılmaz bir tutkuya olduğunu gitmelerin,

sonu olmadığını...

Yaşadığın her kent bir parçan olur

ve her kente bir şiir bırakırsın sonunda,

yolculuklar hep umudadır da

pişmanlıklar başlar bir zaman sonra

ama dedim ya

''içimize sevda düşmüş bir kere

(çekip gitme sevdası)

aklımdaysa hep o özgürlük belası.''', 'Gün gelir çekip giderim ansızın anlayamazsın ki anlatamam anlamsızdır gidişlerim. İçime sevda düşmüş bir kere (çekip gitme sevdası) aklımda ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Gün']::text[], 8.5, '{"poet":"Zafer Gün","poet_slug":"zafer-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cekip-gitme-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuntu', 'avuntu-zafer-gun-3sdze', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...deli bir mermi,

bir dal sigara,

bir kadeh şarap,

ağır bir şarkı,

güz yağmurları,

çığlık çığlığa bir gökyüzü

ve sabahın ilk ışıkları aşkına!

etin etime değiyor bazen

sadece o kadar...', '...deli bir mermi, bir dal sigara, bir kadeh şarap, ağır bir şarkı, güz yağmurları, çığlık çığlığa bir gökyüzü ve sabahın ilk ışıkları aşkın...', ARRAY['Türk Edebiyatı','Şiir','Zafer Gün']::text[], 8.5, '{"poet":"Zafer Gün","poet_slug":"zafer-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/avuntu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Çocukları', 'denizin-cocuklari-ahmet-sahin-soner-7i4o2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte onlar , denizin çocukları

Okyanusları aşıp geldiler

Yosun kokusu sarmıştı tenlerini

Belliydi , denizin sahipleriydiler

Kardeşleriydi beyaz martılar

Sırlarıyla geldiler ufka bu aksam 

Ay''ın renkler verdiği denizde

Yakamoz ışıltısında

Bir deniz feneri yoldaşlığında 

Parlayan gözleriyle umuttular

Denizin sevdalısı 

Aşkın aşığı 

Denizin çocuklarıydılar', 'İşte onlar , denizin çocukları Okyanusları aşıp geldiler Yosun kokusu sarmıştı tenlerini Belliydi , denizin sahipleriydiler Kardeşleriydi be...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/denizin-cocuklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Der Misin', 'der-misin-sair-oedipius-uszrm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başımı omuzuna dayayıp ağlasam

Yüzüme bakıp siler misin göz yaşlarımı?

Boynuna sarılıp, sana ihtiyacım var desem

Aynı sıcaklıkla sende sarar mısın beni?

Yanağını okşasam, saçlarınla oynasam

O masum çocuksu gözlerle bakar mısın?

Rüyamda seni görüp adını nüksetsem

Sesimi duyup bana koşar mısın?

Özledim seni, ne olur beni bırakma desem

Ellerimi tutup hep seninleyim der misin?

Tekrar benim ol, bana geri dön desem

Zaten hep senindim der misin?

Peki gözlerinin içine bakıp

Seni çok seviyorum desem

Işıldayan gözlerinle

Bende seni seviyorum bi'' tanem der misin?

02.11.2000

21:40', 'Başımı omuzuna dayayıp ağlasam Yüzüme bakıp siler misin göz yaşlarımı? Boynuna sarılıp, sana ihtiyacım var desem Aynı sıcaklıkla sende sarar...', ARRAY['Türk Edebiyatı','Şiir','Şair Oedipius']::text[], 8.5, '{"poet":"Şair Oedipius","poet_slug":"sair-oedipius","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/der-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedensiz Çizgiler', 'nedensiz-cizgiler-ahmet-sahin-soner-r1cwt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden hırçınsın bu kadar akşamları

Neden başını taşlara vurman

Niye sitem edersin''ki boşuna uçan kuşlara

Niye söndürüyorsun içindeki yangını

Nedensizce cekip gitmek yakısmıyor sana

Soguklugundasın hala kış akşamlarının

Aklınsıra yargılıyorsun zamanı ve icindeki beni

Unutmak istermişcesine bende''ki seni

Derinlere , sessizliklere sesleniyorsun 

Haykırırcasına ..........

Bir zamanlar sevgiler dağıtırdı bu yürek

Suskunsun , mehtapla bile konusmuyorsun

Neden kapatıyorsun yakamozları 

Neden siliyorsun gecenin ışıltısını

Tabloları neden siyaha boyuyorsun

Bu çırpınışın , geceye ihanetin neden

İlk defa böyle ağlıyorsun , 

Sessizce bir köşede , muhtaçsın yüregindeki ben''e

Şekiller cizerdin geceleri ellerinle

Şekiller çizerdin denizin üzerinde

Neden kapıldın fırtınalara

Suskunsun ne zamandır akşamları

Aşıksın belki yükseklerdeki bir yıldıza

Kimbilir söndürmüslerdir içindeki umutları 

Tekdüze bir duygumu yoksa ardına saklandığın

Yıllar sonra bir başkasına aşık olursun değil mi

Karanlık bir bulut gibi dolusun

Dokunsam yağacaksın

Sevgi seli olup akacaksın 

Gözlerindeki buğuya saklamışsın korkularını 

Uzun uzun konusmadın bile benimle

Yıllar önce bir akşamda tanıdım seni

Yine böyleydin doluydun,aşıktın

Aşıksın tanırım ben seni 

Saklamaya çalışma 

Gözlerindeki ışıltı anlatıyor yüreğini

Yükseklerde bir yerlerde sevdaların

Nedensiz çizgiler var bu tablonda 

Delice bir sevdanın esintisinde renklenmiş

Gecenin perdesinde ışıyan 

Bir aşk var yüreğinde 

Konuşmuyorsun

Susuyorsun

Konuşamıyorsun , konuşamıyorsun', 'Neden hırçınsın bu kadar akşamları Neden başını taşlara vurman Niye sitem edersin''ki boşuna uçan kuşlara Niye söndürüyorsun içindeki yangını...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/nedensiz-cizgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ahmet-sahin-soner-50vn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskunum , gözlerim nemli , üşüyorum

Ellerim titriyor , boğazımda kesik sevgi sözleri

Nedense tıkanıp kalmışım , susmuşum

İçimde yar''e dökemediğim sevgi seli

Suskunum utancımı aşamıyorum

En derinlerden kopagelen duygulardayım

Varsayımlarım var sevgi üzerine

İçimdesin her an , gözlerinin ışıltısına kapılmışım

Yalnızlığıda şekillendirmiştim,içimdeki seni

Olmuyor yalnız olamıyorum sensiz

Rüyamda sen , gecemde , günümde sen

Uzun uzadıya yaşamak seninle 

Mutluyum , ellerimde ellerin dilimde ..............

İlk Harfler', 'Suskunum , gözlerim nemli , üşüyorum Ellerim titriyor , boğazımda kesik sevgi sözleri Nedense tıkanıp kalmışım , susmuşum İçimde yar''e dökem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-seviyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey yar', 'ey-yar-sair-osman-espcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neşe''ye 

Ne  olur kulak ver sözlerime

El kızı gibi bakma gözlerime

Şaşırdım elinden , düştüm dizlerine

Elini ver bana , gönlünü ver ey yar!', 'Neşe''ye  Ne  olur kulak ver sözlerime El kızı gibi bakma gözlerime Şaşırdım elinden , düştüm dizlerine Elini ver bana , gönlünü ver ey yar!...', ARRAY['Türk Edebiyatı','Şiir','Şair Osman']::text[], 8.5, '{"poet":"Şair Osman","poet_slug":"sair-osman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ey-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırası Var', 'hatirasi-var-i-rfan-kardes-3y3f6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinle başladı bu sevda

Yalınayak, ıslandığım zamanların

Yüzüne bakacak yüzümün olmadığı

Günlerin, hatırası vardır.

Gözlerinle başladı bu sevda

Belki de hiç bitmeyecek

Sevgilere, sevgililere inat

Vakitlerin, hatırsı vardır.

Gözlerinle başladı bu sevda

Sevgine düştüm düşeli, derdimi

Taşlara bile kazıdığım

Anların, hatırası vardır.

Gözlerinle başladı bu sevda

Her şeyi suya anlattığım, ama

Söylemeye hakkımın olmadığı

Zamanların, hatırası vardır.

Gözlerinle başladı bu sevda

Gözlerinde bitecek.

Ne kadar isterdim ellerinin sıcaklığını

Bir kucak sarımında hissetmeyi

Gözlerinle başladı bu sevda 

Gözlerinde bitecek

1990/SAKARYA', 'Gözlerinle başladı bu sevda Yalınayak, ıslandığım zamanların Yüzüne bakacak yüzümün olmadığı Günlerin, hatırası vardır. Gözlerinle başladı b...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kardeş']::text[], 8.5, '{"poet":"İrfan Kardeş","poet_slug":"i-rfan-kardes","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hatirasi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karda Işıltılar', 'karda-isiltilar-turgay-fisekci-m81qf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yağmaya başlayan kardan mı nedir? 

Saklamak zorunda olduğum kocaman bir sevinç varmış gibi

Çok güzel şeyler söyleyecekmişim de

Söyleyemiyormuşum gibi dolu dolu yüreğim.

İnsanca bir gülümsemeye rastladım

Hıdrellez günlerinde salıncaklarda sallanan insanların

Gönülleri kadar hafif.

Baloncunun peşinden koşan çocuk yüreği gibi sevdalı

Al, yeşil, sarı balonlarımız olsun n''olur diyen

Bağlara gidelim

Asma çardaklarda yatalım gecelerde

İsteyen sabahlasın, istediği kitapla

İncir, üzüm, nar, şeftali

Hepsi hepimizin diyen

Sevginin dostluğun, arkadaşlığın dışında

Hiçbir anlama gelmeyen

İnsanca bir gülümsemeye rastladım

Merdivende verdiğin sarı kasımpatıyı unutmadım

Sevdiğim bir şiir kitabına taktım onu

Karıştı çiçeğin şiirlere.

Kolunu boynuma doluyorsun otobüste

Çocuğunu seven bir anne gibi

Yakınlığımız insanlığımızdan geliyor

Ne kadar insanlaşırsak

O kadar arkadaşız.

Kar dinmek bilmiyor dışarıda...', 'Gece yağmaya başlayan kardan mı nedir?  Saklamak zorunda olduğum kocaman bir sevinç varmış gibi Çok güzel şeyler söyleyecekmişim de Söyleyem...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fişekçi']::text[], 8.5, '{"poet":"Turgay Fişekçi","poet_slug":"turgay-fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karda-isiltilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erimek', 'erimek-bedri-rahmi-eyuboglu-ifdjh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erimek belirsizce herşeyde,

Karışmak sulara yıldızlara,

Sinmek kokusuna mor menekşenin,

Yanmak damar damar, nefes nefes,

Yaşamak tükene tükene.', 'Erimek belirsizce herşeyde, Karışmak sulara yıldızlara, Sinmek kokusuna mor menekşenin, Yanmak damar damar, nefes nefes, Yaşamak tükene tüke...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/erimek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ticari', 'ticari-sair-doktor-te0xp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El yapımı bir sevdaydı bizimkisi,

kalbimizi işliyorduk

aşk yapımı bir sevda makinasında...

Sıfırdan bir yerlere gelmek gibi başladık

iki kalp koyarak ortaya.

Ve aşkımızın para etmesini bekliyorduk

böyle sermayesiz bir başlangıçla...

Aşkımın parekendecileriydi

umut iklimimden çalınan ümitlerim!

Ve biz toptan bir satışla başlıyorduk öğrenmeye

zarar kelimesinin sözlükte yer almayan ayrıntılarını...

El yapımı bir sevdaydık ikimiz,

zarar etti aşk,mecbur ayrılacaktık!

Bana kalırsa biz

aşk işine hiç girmeyecektik...!', 'El yapımı bir sevdaydı bizimkisi, kalbimizi işliyorduk aşk yapımı bir sevda makinasında... Sıfırdan bir yerlere gelmek gibi başladık iki kal...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ticari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızsan Eğer', 'yalnizsan-eger-ahmet-telli-lwpo1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın devraldığı

sessiz bir özsudur acı

birikir yüreğinin kıvrımlarında

ve ağar gözlerine ağır ağır

Bulutlar yere inmiştir artık

ya da gurbettesindir

Unutma

Bir hayalet gibi kapındadır

yalnızlık denilen şey

ufkun kararabilir birden

için çölleşebilir

Kaçışın bile bir adımdır

ya da dönüşündür kendine

Unutma

Her sayfası kederle kararan

bir hüzün defterine döner günler

ve her sabah ''merhaba hüzün''

''merhaba yalnızlık''

diyerek başlarsın hayata

Ama hayat bağışlamayacaktır seni

Unutma

Üstelik günlüğü yoktur hüznün

hiçbir zaman da tutulmayacaktır

Serüvenlerin yorgun yeniği

elleri titreyen yaşlı bir kadındır hüzün

ya da hasta bir tanıdıktır ancak

hepsi o kadar

Unutma', 'Hayatın devraldığı sessiz bir özsudur acı birikir yüreğinin kıvrımlarında ve ağar gözlerine ağır ağır Bulutlar yere inmiştir artık ya da gur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizsan-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedestan Yokuşu', 'bedestan-yokusu-seyfullah-fatih-1logd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilârâ,

Mağribilerin ülkesinde 

Ömrümü kaybettim,

Ellerimi yitirdim ipeklere uzanan....

Sonra yangınlar düştü içime

Ve bir mecûsi kıblesinde 

Kül bezirgânları,

Hayâlleri ufalayan...

Kâlp kanı içen vampirler vardı,

Hazır ve nâzırdı

Sihir törenleri,

Ortaçağ giyotinleri...

Geçilecek yerlerinde öykülerimin,

Gözyaşı çocukları birer dikili taştı

Ya da kilometre sayaçları...

Dilârâ,

Bedestân yokuşunda sunuldum ve satıldım alıcı kuşlara

Alnımda metelik yaftaları,

Alnımda silik hikâyeler...

Eski ve antik eşya niyetine

Konuldum,  değersiz teraziler kefesine...

Dilârâ, nerdesin ?

Nerdesin beynimden kurşun çıkaran bıçak..!

Sensizliğin mevsimi ne kadar kurak

Ve ne çok zindan böyle yaşamak...

Dilârâ,

Kafese koydular Anka kuşunu

Yusuf, kuyuya atılmakta hâlâ.

Bu yüzden 

Sükûtum, 

Tenhayım,

Suskunum,

Bir ses sana vakit tamam gel desin...

Dilârâ,

Asırlara sinişen bir korku içindeyim,

Bedestân yokuşunda bedbîn haldeyim,

Yerdeyim, gökteyim, bir zaman göçündeyim,

Olur olmaz kazılmış mezarlar içindeyim...

Dilârâ,

Sensiz anlam vermek güç 

Bu salgın yangınlara.

Ve sensiz düşmek zor,

Kapanmış masal yollarına...

Dilârâ,

Ey yolda kalanların emsâlsiz dostu,

Ey beynimden kurşun çıkaran bıçak..!

Gel kurtar beni Bedestân yokuşundan,

Kurtar beni, bu cüretkâr aynalardan...', 'Dilârâ, Mağribilerin ülkesinde  Ömrümü kaybettim, Ellerimi yitirdim ipeklere uzanan.... Sonra yangınlar düştü içime Ve bir mecûsi kıblesinde...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bedestan-yokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönülmeyen Lahzalar', 'donulmeyen-lahzalar-seyfullah-fatih-ghl6u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç insanın dil-i ruhsârı yazıldı suya,

Kaç dimağ kenarına şiirler kazındı...?

Kırıldı güneşlerin

Tutunulan ışığı

Ve anlamsız şekiller çizildi Ay''a

Kaç insanın dil-i ruhsârı yazıldı suya...?

Yorulmadı dişleri sıkarken devrânın

Gönül göçlerine düştük uçurum gibi...

Arasat düşlerinden bitevî uyandık

Bir yanımız gülistândı

Bir yanımız yangın,

Yorulmadı dişleri sıkarken devrânın...

Gel zaman geldi,

Git zaman gitti

Geçti ömrün nevbaharı...

Yaralar yeşerdi kardelen vaktinde

Sînemizde ne çok kışlar eridi

Ve gel zaman geldi, git zaman gitti...

Dönemedik huzur dolu o lâhzalara 

Yitti gönül yüzlü dostun cândan içre adresi...

Mahkum kuşlar gibi çığlık çığlığa,

Alnımıza çalındı bir mutlak kara,

Dönemedik

Huzur dolu o lâhzalara...', 'Kaç insanın dil-i ruhsârı yazıldı suya, Kaç dimağ kenarına şiirler kazındı...? Kırıldı güneşlerin Tutunulan ışığı Ve anlamsız şekiller çizil...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donulmeyen-lahzalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Nasılsa Yalnızsın', 'her-nasilsa-yalnizsin-ahmet-telli-h37i2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her nasılsa yalnızsın

Bir giz gibi deliyor yüreğini

cansıkıntılarının burgusu

ve hep bir şeyler eksik gibi

bir şeyler bekler gibisin

Yeni bozgunlar

yeni yenilgiler peşindesin

Bir bozkır kuraklığına dönmüş için

Oysa yalnız bir öpüştür

gurbeti türkülere dönüştüren

Çoktandır su vermedin

çiçeklere ve yüreğinin çeliğine

Zaman terkisine almış da öpücükleri

koşuyor sessizliğin ve yalnızlığın 

iyotlu kıyılarına

Bir yol ayrımı ki yanlışla doğru

hüzünlerle sevinçler kolkola

Sen ki ey kalbim

yanlışları ve hüzünleri taşıdın

bunca zaman

Taşıyamaz yüreğinin batık sandalı

bu yalnızlığı,bu can sıkıntılarını

Yaşam gelincikler gibi beklerken seni

gecenin kapısını çalma

ey kalbim', 'Her nasılsa yalnızsın Bir giz gibi deliyor yüreğini cansıkıntılarının burgusu ve hep bir şeyler eksik gibi bir şeyler bekler gibisin Yeni bo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-nasilsa-yalnizsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı Kuşu', 'balikci-kusu-seyfullah-fatih-h51t1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben balıkçıl kuşu su kenarında

İçimde akılalmaz vehimler...

Korkuyorum 

Kuruyacak ırmaklar

Büyüyecek birikintilerin med-cezirinde

Şahlanacak telaşlar...

Ben balıkçıl kuşu su kenarında

Taşlar atıyorum akan bir düşe...

Çoğalıyor

Halka halka bulantım

Halka halka düşüyorum kıyıya...

Ben balıkçıl kuşu su kenarında 

Yakamoz ayinlerinde yalvarıyorum

Aynalar mutlu değil hiçbir denizde

Dökülüyor sırçalarım

Ağlar gibi çıkıyorum sulardaki aksimde...', 'Ben balıkçıl kuşu su kenarında İçimde akılalmaz vehimler... Korkuyorum  Kuruyacak ırmaklar Büyüyecek birikintilerin med-cezirinde Şahlanacak...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/balikci-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nakışsız Hüzün', 'nakissiz-huzun-seyfullah-fatih-3r11l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdâ  kayıp bir köydür tenhalaşan dağlarda

Geçip giden bir efsunlu vakittir.

Harcadık dem’imizi  o beyhude yollarda

Yapma çiçeklerde aşk aradık nicedir...

Ruhumuzu unuttuk her çağdaş labirentte

Sildik tüm çizgileri, daralttık ufukları.

Gömdük kayıp düşleri daracık bir lâhite 

Tufanlarda bıraktık bestesiz baharları...

Nakışsız acılarla kör ettik sabırları,

Nasırsız omzumuzdan yere düştü hülyalar

Şahinler avlar iken  cân muhacir kuşları

Şimdi bizi ne paklar, hangi derin kaygılar...

Küllendi destanların yaktığı meşaleler

Örselendi dilimiz retoriksiz sözlerde.

Cümleler esir şimdi, râm oldu kelimeler

Şiirsiz merâmsızız tüm aşina seslerde...', 'Sevdâ  kayıp bir köydür tenhalaşan dağlarda Geçip giden bir efsunlu vakittir. Harcadık dem’imizi  o beyhude yollarda Yapma çiçeklerde aşk ar...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nakissiz-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muştu', 'mustu-seyfullah-fatih-wsqz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözünüz aydın 

Sabah oldu erkenden

Ve şiir yontularına gidiyoruz

Ellerimizde 

Gündelik alet çantalarımız

Gündelik kelepçelerimiz...

Sert taşlara sürteceğiz kırılgan yüreğimizi

Bir ihtimal taşlar şekillenecek

Şekiller seçeceğiz kataloglardan...

Gözünüz aydın

Şiir ayinlerine gidiyoruz erkenden...

İçimizde yoksul turnalar

Ve masal kuşları...

Su sesleri toplayacağız ufuklardan

Bir ihtimal ufuklar şekillenecek,

Yönümüzü soracağız pusulalardan...

Gözünüz aydın

Sabah oldu erkenden..!', 'Gözünüz aydın  Sabah oldu erkenden Ve şiir yontularına gidiyoruz Ellerimizde  Gündelik alet çantalarımız Gündelik kelepçelerimiz... Sert taş...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Gemiler', 'tas-gemiler-seyfullah-fatih-vwqyk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taş gemiler içinde geçiyor ömrümüz

Suç gibi özlemlerimiz

Suç gibi eylemlerimiz...

Gecikmiş doğumlarla geldik dünyaya

Bir yanımız eksikti

Özürlüydü yüreğimiz.

Gecikmiş aşklar yaşadık sonra,

Gecikmiş ecellerle yükseldik semâya..

Taş gemiler,

Rutubet kokusu...

Pusulalar yalnızlığa ayarlı.

Hali yok niyetlerin nefes almaya

Taş gemiler,

Zeminsiz bir hayatın kurgusu...

Mahkumuz,

Yosununa ağçların

Uykuların şirazesiz kâbusuna...

Şafak varsayımlarına tutunuyoruz

Suyun eteğinden,

Dökülüyor rotalar,.

Suyun eteğinde

Ölüyor martılar..', 'Taş gemiler içinde geçiyor ömrümüz Suç gibi özlemlerimiz Suç gibi eylemlerimiz... Gecikmiş doğumlarla geldik dünyaya Bir yanımız eksikti Özü...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tas-gemiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Bitimi', 'dus-bitimi-seyfullah-fatih-mcbs8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne eski masallar avutur içimi

Ne de uçuk hayaller...

Kimbilir

Kaç alâim-i semâ gördü gözlerim

Kaç sabâ makamında yere çakıldı...

Aynı rüyada hep aynı çocuk 

Ezberler mecburluğun muannit kitabını...

Sabahlar 

Ölü teni kadar soğuk

Antik kederler gibi donuk

Sabahlar 

Yabanıl oyuncaklar

Ki değişmiyor ne yapsan

Şekiller soluk...

Sen rüzigârım

Sen devrânım olmayacaksan

Gezinme gece artığı çölümde …

Uykular kovmalısın anlamak için

Düş bitimi ne demek

Nasıldır zorunlu sabahlar...

Elinden umut gibi

Elinden kor gibi

Bulanık sulara düştüğünde  aynalar...', 'Ne eski masallar avutur içimi Ne de uçuk hayaller... Kimbilir Kaç alâim-i semâ gördü gözlerim Kaç sabâ makamında yere çakıldı... Aynı rüyada...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dus-bitimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masallar Avutmaz İçimi', 'masallar-avutmaz-i-cimi-seyfullah-fatih-apo06', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne eski masallar avutur içimi

Ne de uçuk hayaller...

Kimbilir

Kaç alâim-i semâ gördü gözlerim

Kaç sabâ makamında yere çakıldı...

Aynı rüyada hep aynı çocuk 

Ezberler mecburluğun muannit kitabını...

Sabahlar 

Ölü teni kadar soğuk

Antik kederler gibi donuk

Sabahlar 

Yabanıl oyuncaklar

Ki değişmiyor ne yapsan

Şekiller soluk...

Sen rüzigârım

Sen devrânım olmayacaksan

Gezinme gece artığı çölümde …

Uykular kovmalısın anlamak için

Düş bitimi ne demek

Nasıldır zorunlu sabahlar...

Elinden umut gibi

Elinden kor gibi

Bulanık sulara düştüğünde  aynalar...', 'Ne eski masallar avutur içimi Ne de uçuk hayaller... Kimbilir Kaç alâim-i semâ gördü gözlerim Kaç sabâ makamında yere çakıldı... Aynı rüyada...', ARRAY['Türk Edebiyatı','Şiir','Seyfullah Fatih']::text[], 8.5, '{"poet":"Seyfullah Fatih","poet_slug":"seyfullah-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/masallar-avutmaz-icimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgara Yazdım Adını', 'ruzgara-yazdim-adini-refik-durbas-m7ah0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını, vadilerin cemresinde

yolunu yitirmiş sulara yazdım

Saçlarına kırağı düşmüş ovalara

Göçmen kuşların konağı ovalara

Rüzgara yazdım bir de...

Seni o rüzgar getirdi bana

Gördüm seni bir daha

gençliğimin ilkçağının 

gözleriyle gördüğüm gibi...

O yıllarda da böyle miydi

dudaklarının ve ağzının iklimi

kirpiklerinin karası

alnının serin serinliği

saçlarının ilkbaharı?

Yüreğimde aşkın ve yarası...

Yüreğim çarpardı

Ben çarpardım yüreğimi

çıkmaz ve ara sokaklara

Denizlerin tuzuna

gurbetlerin hüznüne

hüzünlerin sılasına...

Gözlerin,gözlerindi melhem

yüreğimin yarasına...

Alıp gitmek vardı seni o an

''Bana bir şiir oku'' dediğinde

Alıp gitmeliydim seni...

Bedeni haritalardan silinmiş

bir park kanepesinde oturur

başımı omuzuna koyardım

sana şiirler okurdum

Senin şiirini okurdum

Gökyüzünün en karanlık gecesinden

en aydınlık yıldızını çalar

ve kalbinin üzerine koyardım

O yıldızın aydınlığı ile aydınlanırdı

senin geçmişin ve benim geleceğim

O yıldızın aydınlığıyla

sana sevdalar biçerdim

bana karasevdalar...

Sana sevinçler ve bana hüzünler...

Ah, geçmişimin hatırasından

hatırıma bir daha gelen sevgili

Kalbimin hangi kuytusunda

saklamalıyım şimdi seni?

Hangi vadilerin rüzgarına

yazmalıyım adını ve aşkını?

Hangi rüzgarın elvedasına...

Çık gel şimdi nasıl gelirsen gel

ben beklemedeyim

Bir telefonun sessiz teline

bir mektubun puluna değil

rüzgarlara yazdım adını...

Rüzgarla bekliyorum seni...', 'Adını, vadilerin cemresinde yolunu yitirmiş sulara yazdım Saçlarına kırağı düşmüş ovalara Göçmen kuşların konağı ovalara Rüzgara yazdım bir ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ruzgara-yazdim-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayan Mücahidim', 'dayan-mucahidim-mucahit-baskal-qecl8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dayan mücahidim dayan 

bu senin yüce davan

hür olmazsa bilki kuran

kalpte hapis kaılır iman

yıldıramaz bizi bir an

ne işkence nede zindan

dilde tekbir kalpe iman 

rehberimiz yüce kuran

yıldıramaz bizi inan

batının topu güllesi

kulak versin bize herkes

bu ses mücahidin sesi

dayan mücahidim dayan 

bu senin yüce davan

hür olmazsa bilki kuran

kalpte hapis kalır iman..', 'dayan mücahidim dayan  bu senin yüce davan hür olmazsa bilki kuran kalpte hapis kaılır iman yıldıramaz bizi bir an ne işkence nede zindan di...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Başkal']::text[], 8.5, '{"poet":"Mücahit Başkal","poet_slug":"mucahit-baskal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dayan-mucahidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş ve İnsan', 'kus-ve-i-nsan-suleyman-avci-kxl22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana öyle bakma kuş

Ben de bilirim uçmasını

Yükseklerden bakmasını

Özgürlük değil 

Yalnızlık korkusudur 

Beni senden uzaklaştıran

Sen uçarken kuşlarlasın

Ben yerdeyken insanlarla

Ben yalnızken bir kuşum', 'Bana öyle bakma kuş Ben de bilirim uçmasını Yükseklerden bakmasını Özgürlük değil  Yalnızlık korkusudur  Beni senden uzaklaştıran Sen uçarke...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kus-ve-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Hali', 'dunya-hali-cemal-unal-p58j4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya hali işte,

Düşünüyorum da dostum,

Ne garip bir dünya deriz.

Sahi,dünya mı garip

Yoksa biz insanlar mı?

Dünyaya bakıyorum

Mevsimler takip ediyor birbirini,

İlkbahar yaz sonbahar kış diye,

Güne,günlere bakıyorum

Güneş aya devrediyor geceyi,

Ay ise,gündüzleri güneşe

Karlar,yağmurlar yağıyor.

Susamışlar susuzluğunu gidersin diye.

Bulutlar kayboluyor,

Temmuzun,ağustosun yakıcı sıcağı,

Ekinler sararsın,biçilsin diye,

Karada,havada,denizde

Canlılar var,her biri birilerini beslesin diye

Dünya hali işte,

Düşünüyorumda dostum ne garip bir dünya deriz.

Sahi dünya mı garip,

Yoksa biz insanlar mı,

Belgeseller izleriz,televizyonlarda,

Var olan dünyayı tanımak için 

Sıkça hayvanlar alemi ekranlarda,

Bazen gıpta ile ile izleriz onları kendimizden nefret ederek,

Bazen insan olduğumuz gelir aklımıza,bugünlere şükrederek

Bakmışınız,

Bir doğa kanunu çıkar karşımıza,

Mutlaka birileri,birilerinin peşinde,üstünlüğünü kanıtlayacak,

Amaç yaşamaksa dostum,o zaman ayakta kalınacak.

Ayakta kalamazsan sen eğer,

Peşindeki birileri,

Seni acı gerçeklerle tanıştıracak.

Dünya hali işte,

Düşünüyorum da dostum, ne garip bir dünya deriz.

Sahi dünya mı garip yoksa biz,biz insanlar mı?', 'Dünya hali işte, Düşünüyorum da dostum, Ne garip bir dünya deriz. Sahi,dünya mı garip Yoksa biz insanlar mı? Dünyaya bakıyorum Mevsimler tak...', ARRAY['Türk Edebiyatı','Şiir','Cemal Ünal']::text[], 8.5, '{"poet":"Cemal Ünal","poet_slug":"cemal-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dunya-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarabım ve Yalnızlığım', 'sarabim-ve-yalnizligim-zeynep-savci-vorg8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hergün biraz daha alışıyorsun kendine

Hergün biraz daha sen oluyorsun senle.

Gökyüzüne bakıyorsun,

Kimbilir hangi gezegendesin.

Gideceğin yerde ben de var mıyım?

Bak yine gözlerin daldı,

Yine uzaklardasın,

Oysa öyle yakınsın ki,

Parmaklarımın ucunda.

...

Gözlerin daldı yine,

Donuklaştı bakışların.

Bana her sabah,gördüğü rüyaları bu gözleriyle anlatan,

Sen değilsin sanki.

Bazen herkesi ve herşeyi bırakıp,

Uzaklara kaçmak istiyorum.

Kendimle başbaşa kalmak,

Yalnızlığımla dost olmak istiyorum.

Belki o zaman anlarım seni

Hem seni,

Hem biraz beni.

Öyle bir trene bineceğim ki;

Bu trenin dönüşü olmayacak.

Ya da ben sadece gidiş bileti alacağım.

Tabi gideceğim yerde sen de olmayacaksın.

Şarabım ve yalnızlığımı alacağım yanıma.

Gideceğim yer,

Öyle bir yer olacak ki;

Milyarlarca kum tanesi...

Belki bir çöl,ama mehtaplı bir çöl.

O kum taneleriyle,

Kalbimin sesini boğacağım.

Yakamoz ağlayışlarımın sırdaşı olacak.

Bense sensiz gecelerde,

Dalga sesleriyle teselli bulacağım.', 'Hergün biraz daha alışıyorsun kendine Hergün biraz daha sen oluyorsun senle. Gökyüzüne bakıyorsun, Kimbilir hangi gezegendesin. Gideceğin ye...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Savcı']::text[], 8.5, '{"poet":"Zeynep Savcı","poet_slug":"zeynep-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sarabim-ve-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olmak', 'seninle-olmak-zeynep-savci-fgmi3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle olmak,

Mutlulukların en güzeli.

Sevgiyi yaşamak seninle

Paylaşımın en güzeli.

İleriye bakmak seninle,

Hedefe doğru ilerlemek

Büyümek birlikte,

Doğruyu öğretmek belki de.

Hadi gel şimdi,

En güzel insanlar olmak için,

Yardım edelim birbirimize', 'Seninle olmak, Mutlulukların en güzeli. Sevgiyi yaşamak seninle Paylaşımın en güzeli. İleriye bakmak seninle, Hedefe doğru ilerlemek Büyümek...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Savcı']::text[], 8.5, '{"poet":"Zeynep Savcı","poet_slug":"zeynep-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seninle-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur?', 'ne-olur-bulent-eraslan-7wlhy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur sanki bu zamanlarda,

Beni bu duygular sarmasa

Ilık , tatlı bahar yeli gibi

Hafif bir esinti 

Gezinmese başımda

Ne olur ?

Ne olur sanki bu zamanlarda,

Hayat suyu koca çınarlara

Yürür ya usulca

Öylesine yakıcı coşkuyla

Sevda yüklü damlacıklar

Gezinmese damarlarımda 

Ne olur ?

Ne olur sanki bu zamanlarda

Susuz topraklar gibi çorak,

Çatlak, çizik , kavruk

Her zaman mahsun ve buruk

Olan bu kalbim

Böyle delicesine uçuk

Çarpmasa ne olur ?

Ne olur sanki bu zamanlarda

Kışa beş kala durmuş,

Bir bozuk saatin akrebine 

Takılıp kalsa zaman

Hep sessiz ve soluk olan

Düşlerin özleminde 

Duruverse tamamen

Ne olur ?

Ne olur sanki bu zamanlarda 

Bana yasak olan bu iklimi 

Bir sis bulutu gibi görsem

Kaplasa tüm gerçeklerimi

Gizlese benden beni

Ve bir daha asla

Üzerimden kalkmasa 

Ne olur ?', 'Ne olur sanki bu zamanlarda, Beni bu duygular sarmasa Ilık , tatlı bahar yeli gibi Hafif bir esinti  Gezinmese başımda Ne olur ? Ne olur san...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-olur-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Sevgi', 'beklenen-sevgi-bulent-eraslan-uamch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıkta, zifiri 

karanlıkta, 

Işık arar gibi 

Düştüm peşine sevginin

Bazen bir ele dokundum 

Tatlı ve sıcak,

Ama çoğu kez

Boşlukta kaldı ellerim.

Çile dokudum 

Hayat tezgahında 

İplik iplik, lif lif

Sevgiler riyâ çıktı,

Sevgililer riyâkâr.

Yılmadım, yorulmadım

Umutla bekledim.

Bir ömür geçti 

Beklemek yolunda

Ne beklediklerim geldi,

Ne de gelenler

Beklemeye değdi sonunda.', 'Karanlıkta, zifiri  karanlıkta,  Işık arar gibi  Düştüm peşine sevginin Bazen bir ele dokundum  Tatlı ve sıcak, Ama çoğu kez Boşlukta kaldı ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beklenen-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-bulent-eraslan-tft6l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vurulmuş göğsünden kanlar içinde, 

Bayrağa sarılı eller üstünde,

Kalplere gömülmüş toprak yerine 

Sen görev şehidisin, öğretmenim.

Kalbi ağlar iken gözleri gülen,

Nice zorluklarla bize ders veren,

Aldığı maaşla zar zor geçinen,

Sen emek yiğidisin, öğretmenim.

Limon satar iken kendi sıkılır,

İşportacılıkta kızarıp, dili tutulur,

En çok sevilir, hep unutulur,

Unutanları da sen yetiştirdin, öğretmenim.

Önceden altındın döndün bir pula,

“ Kırk yıl köle olacaklar “ döndürdü kula,

Elinde bir valiz düşersin yola,

Yollar yürümekle biter, öğretmenim.

Öğretmenler gününde başlar tacısın.

Devlet kurtaran, vatan ilacısın,

Üç yüz altmış dört gün bilmem necisin,

Bir tek gün sana yeter mi, öğretmenim ?

Sanma ki, riyakâr nutuklar biter,

Sahte gülücükler dostluklar yiter,

Bu böyle gelmiş, böyle de gider,

Sakın kırılma, darılma, öğretmenim.

Ne şefkatin biter ne de sevgin,

Dün nasıl isen ölesin bugün,

Görevin kutsal, kalbin çok zengin,

Şu küçücük yürekler sana yeter, öğretmenim.



Vurulmuş göğsünden kanlar içinde, 

Bayrağa sarılı eller üstünde,

Kalplere gömülmüş toprak yerine 

Sen görev şehidisin, öğretmenim.

Kalbi ağlar iken gözleri gülen,

Nice zorluklarla bize ders veren,

Aldığı maaşla zar zor geçinen,

Sen emek yiğidisin, öğretmenim.

Limon satar iken kendi sıkılır,

İşportacılıkta kızarıp, dili tutulur,

En çok sevilir, hep unutulur,

Unutanları da sen yetiştirdin, öğretmenim.

Önceden altındın döndün bir pula,

“ Kırk yıl köle olacaklar “ döndürdü kula,

Elinde bir valiz düşersin yola,

Yollar yürümekle biter, öğretmenim.

Öğretmenler gününde başlar tacısın.

Devlet kurtaran, vatan ilacısın,

Üç yüz altmış dört gün bilmem necisin,

Bir tek gün sana yeter mi, öğretmenim ?

Sanma ki, riyakâr nutuklar biter,

Sahte gülücükler dostluklar yiter,

Bu böyle gelmiş, böyle de gider,

Sakın kırılma, darılma, öğretmenim.

Ne şefkatin biter ne de sevgin,

Dün nasıl isen ölesin bugün,

Görevin kutsal, kalbin çok zengin,

Şu küçücük yürekler sana yeter, öğretmenim.', 'Vurulmuş göğsünden kanlar içinde,  Bayrağa sarılı eller üstünde, Kalplere gömülmüş toprak yerine  Sen görev şehidisin, öğretmenim. Kalbi ağl...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ogretmenim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Gelmez', 'beklenen-gelmez-bulent-eraslan-6re1t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beklenen gelmez

Bekleyen boşa bekler,

Hava kararır , zaman geçer,

Kapanır yavaş yavaş kepenkler

Beklenen yine gelmez

Bekleyen yine bekler.

Yıldızlar gömülür karanlığa

Ay batar mavi sonsuzluğa

Gün doğar, güneş parlar,

Cıvıl cıvıl olur sokaklar

Beklenen yine gelmez

Bekleyen yine bekler.

Gün değişir ay değişir,

Mevsim değişir, yıl değişir,

Saçlardaki renk,

Gözlerdeki ahenk değişir,

Ve.... bir gün dünya değişir

Beklenen yine gelmez,

Bekleyin artık bekleyemez.', 'Beklenen gelmez Bekleyen boşa bekler, Hava kararır , zaman geçer, Kapanır yavaş yavaş kepenkler Beklenen yine gelmez Bekleyen yine bekler. Y...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beklenen-gelmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-bulent-eraslan-kiu02', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce acı bir tebessüm

Sonra derin bir hıçkırık

Böyle başlamamış mıydı güzelim,

Bu kahrolası ayrılık ?

Ne senden bir ses geldi 

Ne benden sana bir veda

Birden ellerimiz ayrılıverdi

Gözlerimiz dalmışken o boşluğa

Ben o günden beri hep,

O boşluğa dalar dalar giderim.

Ne zaman Nisan yağmuru yağsa 

Ürperir tenim, üşür durur ellerim.

Bir çiğ tanesinde hatırlarım

Gözlerindeki bir damla yaşı

Bazen sesini duyar gibi olur da,

Özlemle uyanırım gece yarısı

Ayrılan yollar kesişmez bilirsin,

Beklemez oldu seni artık gözlerim

Sana soluk sayfalarından mazinin

Yalnızca sonsuz mutluluklar dilerim.', 'Önce acı bir tebessüm Sonra derin bir hıçkırık Böyle başlamamış mıydı güzelim, Bu kahrolası ayrılık ? Ne senden bir ses geldi  Ne benden san...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dilek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşu Bahçenin Gülü', 'komsu-bahcenin-gulu-bulent-eraslan-os2zs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen mahsun,

Sessiz sakin

Mütavazı lakin

Kalbi çığlıklarla dolu

Gülüsün komşu bahçenin.

Her sabah,

Seni biraz mutsuz,

Ve birer damla daha susuz,

Gördükçe böylesine durgun

Kalbime akşam hüznü çöküyor,

İçime ağır bir vurgun.

Seni ısıtabilmek için,

Güneş ışınlarıyla yarışmak,

Su verebilmek için,

Bulutlara karışmak 

Geliyor içimden.

İstiyorum ama yapamıyorum,

O, kahrolası çitleri

Bir türlü aşamıyorum.', 'Sen mahsun, Sessiz sakin Mütavazı lakin Kalbi çığlıklarla dolu Gülüsün komşu bahçenin. Her sabah, Seni biraz mutsuz, Ve birer damla daha sus...', ARRAY['Türk Edebiyatı','Şiir','Bülent Eraslan']::text[], 8.5, '{"poet":"Bülent Eraslan","poet_slug":"bulent-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/komsu-bahcenin-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmiş Bir Kent', 'bitmis-bir-kent-zafer-gun-ytw0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç bir kente benzemez burası

hayallerim ile bezenmiş

ve bir o kadar hayal kurmaktan uzak.

Her köşe başında bir tuzak,

bekler bağlamak için düşlerimi.

Bir şeylere sevdalanırım her gün batımı

oysa bu kentte sevmekte, sevilmekte yasak.

Genç bir kumsal alkolizmi sarar her yanımı

her defasında sebebim olur içmeye yalnızlığım,

sarsılırım,

bir sevi masalı geçer aklımın bir köşesinden

hemen o köşeden aklımı kaçırırım.

Gideceğim günün avuntusunda

geleceğe erinen günler yaşarım.

Ne kadar sevmesemde bu kenti

çekip giderken, hiç çekinmeden

bir yanımı burada bırakırım.

Hiç bir kent gibi değildir burası;

yaşadıkça yok sayarım,

dostlarımla paylaşımlarım gelir aklıma

oysa ne dost kalmıştır yanımda

ne de paylaşılacak bir şey (paylaşımsızlıktan başka)

Kin doludur yüreğim

ve bomboştur sokaklar

umutlarım yitmiş

hedeflerim bir bir tükenmiştir artık;

dolar yüreği

dolar gözlerim

sayfalar dolar bir biri ardına

yüreğim kaçar bu kentten

canım yanar,

uzakta bir yerlerdedir de beklediklerim

bilmediğim bir şey beni bu kente bağlar.', 'Hiç bir kente benzemez burası hayallerim ile bezenmiş ve bir o kadar hayal kurmaktan uzak. Her köşe başında bir tuzak, bekler bağlamak için ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Gün']::text[], 8.5, '{"poet":"Zafer Gün","poet_slug":"zafer-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bitmis-bir-kent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıyer''de', 'sariyer-de-ulas-agir-lvlae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlığı kırmızıydı gecenin

Ay yeryüzüne inmiş 

Zaman zor akıyor

Sarıyer’deyim bir börekçinin önünde

Sarhoştum üstelik karnımda açtı

Ama mutluydum 

Gecede sarhoştu bende

Göz yaşlarıma birden yağmur karıştı 

Sırıl sıklam olmuştum

Sarhoştum,üstelik sende yoktun

Sarıyer’de bir börekçinin önünde

Saat dört olmuştu

Karnımın aç olmasına aldırmadan gülüyordum

Çünkü çok mutluydum

Yıldızlar sırtında taşıyordu beni

Yeni bir bilinmeze

Şimdi ayrılık limanına geldim

Saat beş oldu

Hala sarhoşum ve açım

Üstelik sigaramda bitti.

Ama yinede limandaki fener yanıyordu

Bana geceye aldırış etmeden

Sanki halimize ağlıyordu

Ama biz hala açtık

Sevgiye sevgiliye...

Zaman zor akıyor demiştim ya

Hala öyle

Saat beşi bir geçiyor

Ve ben hala özlemlerimle yıldızlarımla 

Yürüyorum o bilinmeze

Aldığım son nefes belkide

Ama ben yinede mutluyum

Çünkü hala sarhoşum

Hala yürüyorum ...

Sirkeci’de arkama baktım gece yoktu

Sırdaşımda yumuştu bu İstanbul

Tıpkı seni yuttuğu gibi

Artık sarhoş olsam da mutlu olamayacaktım

Çünkü bu büyük İstanbul 

Yutmuştu seni,beni ve geceyi....', 'Çığlığı kırmızıydı gecenin Ay yeryüzüne inmiş  Zaman zor akıyor Sarıyer’deyim bir börekçinin önünde Sarhoştum üstelik karnımda açtı Ama mutl...', ARRAY['Türk Edebiyatı','Şiir','Ulaş Ağır']::text[], 8.5, '{"poet":"Ulaş Ağır","poet_slug":"ulas-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sariyer-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Ağlayacağım', 'yarin-aglayacagim-fikret-kaplan-oultf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dikenli teller ardında

Bıraktığım zamanı

Eritip gurur değrimeninde

yürüyorum hasretin üstüne...

Bir yolculuk ki 

Bilinmeze sırtlandı

Kambur deve kervanları

Bense mağrur ayaklar üstünde

Sevda yükünü taşıyamaz biçare...

Yıkılmayacağım !

Ezilsemde , savrulsamda.

Dağılsada yağmur gibi

Damla damla, parça parça yüreğim

Yeminim var

seni unutmak için 

Bugün değil yarın ağlayacağım.

01/07/1998 14:45 İzmir', 'Dikenli teller ardında Bıraktığım zamanı Eritip gurur değrimeninde yürüyorum hasretin üstüne... Bir yolculuk ki  Bilinmeze sırtlandı Kambur ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kaplan']::text[], 8.5, '{"poet":"Fikret Kaplan","poet_slug":"fikret-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarin-aglayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cubuk', 'cubuk-kucuk-i-skender-o1hs0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adiyla cagiracak kadar samimiydik sonbaharla

Örtuler geldi ruzgarla orterek ruzgari

Sen bir tek bana yoksuldun o sira

Yapilirken icine irmak karismis bir ayna

Bunu durmadan kanitleyecek sana,

Aynaya bakarken,yalnizca bana baktigini unutma!

Ayrilip giderken,sakin!sakin aynayi geceye ters tutma!', 'Adiyla cagiracak kadar samimiydik sonbaharla Örtuler geldi ruzgarla orterek ruzgari Sen bir tek bana yoksuldun o sira Yapilirken icine irmak...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cubuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük İstavrit Hikayesi', 'kucuk-i-stavrit-hikayesi-gul-unal-059rq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sığındığı kim kalmıştı ki

Allah''tan başka?

Ağlayarak saatler boyu

yakarışlarını bir o biliyordu

ve içindeki çırpınan kendisini.

Küçük istavrit hikayesine

dönmüştü hayatı

Bir el bekliyordu 

Onu denize bırakacak.

Tüm günahları tek başına

işlemişti

Şimdi yine

Tek başına çekiyordu

günahlarının cezasını...', 'Sığındığı kim kalmıştı ki Allah''tan başka? Ağlayarak saatler boyu yakarışlarını bir o biliyordu ve içindeki çırpınan kendisini. Küçük istavr...', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucuk-istavrit-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstasyon', 'i-stasyon-gul-unal-6y5ed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamakla ölüm arasında 

giderken

türlü düşüncelerle

türlü şekillerde

Aklına tren rayları

takıldı.

Buca''daki istasyon

ve orda yürüdüğü zamanlar

Özgürlüğün bittiği yerde

Başladı tüm acılar...', 'Yaşamakla ölüm arasında  giderken türlü düşüncelerle türlü şekillerde Aklına tren rayları takıldı. Buca''daki istasyon ve orda yürüdüğü zaman...', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istasyon-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur da Öyle Git', 'vur-da-oyle-git-cemal-safi-ku7ba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İdam mahkumunun söz hakkı vardır

Bari son arzumu sor da öyle git

Arının çiçekte göz hakkı vardır

Bir buse için dur da öyle git

Madem gidiyorsun bura son durak

Ne adres, ne mektup, ne resim bırak

Kendinden bir parça bir cisim bırak

Saçından birkaç tel ver de öyle git

Ardımdan bir damla yaş dökeceksen 

Adımı andıkça ah ah çekeceksen

Kabrime bir gonca gül dikeceksen 

Ne olur yaşatma vur da öyle git

Hem yıllarca oyna gönül sahnemde

Hem perdeyi kapat en mutlu demde

Sitem oklarına hedef sinemde

Açtığın yarayı sar da öyle git

Pişmanlık duyarda dönersen geri

Gel de gör aşkından kalan eseri

Seyret ateşinin düştüğü yeri

Hasretin zulmünü gör de öyle git', 'İdam mahkumunun söz hakkı vardır Bari son arzumu sor da öyle git Arının çiçekte göz hakkı vardır Bir buse için dur da öyle git Madem gidiyor...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vur-da-oyle-git-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Fırtınası', 'col-firtinasi-sule-ahlef-o88vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızgın kumların alevi vurur siyah gözlerine genç kadının,

Çıplak ayakları savurur kumları havaya.

Ve o geçer dört nala atıyla,

Sıcak rüzgarın peşisıra... 

Ay ışığı yolunu aydınlatır;

Çölün zifiri karanlığında rehber.

Kalbinin sesi karışır nal seslerine,

Genç kadının gözleri dalar siyaha boyanmış kumlara;

O çekip gitti dört nala atıyla...

Uzaklarda o kadının sesi...

Kıvrak bir şarkıyı söylemektedir.

Hatırlar siyah gözlerini adam.

Ama kapanır yaralar zamanla;

Belki de bundan,ardına bakmaz,

Ölümün sesi eserken çöl rüzgarıyla,

O geçer dört nala atıyla....', 'Kızgın kumların alevi vurur siyah gözlerine genç kadının, Çıplak ayakları savurur kumları havaya. Ve o geçer dört nala atıyla, Sıcak rüzgarı...', ARRAY['Türk Edebiyatı','Şiir','Şule Ahlef']::text[], 8.5, '{"poet":"Şule Ahlef","poet_slug":"sule-ahlef","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/col-firtinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-suleyman-elif-ahvx2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni ıslanırcasına yururken izlerim

sanki gulumsuyordu bana bakerken

o hala bakıyordu yagmıur yagarken

ıslanmıştı ıslanmıştı ıslanmıştı

parıldayan bir güneş gibi

o haliyle yinede gülüyordu

*********************************

senin için nöbet tutardım

askerligi bitirmek için

bir adım uzanmak istedım

senın o güzel gözlerine

ama olmadı çünkü nöbet bitmedi', 'seni ıslanırcasına yururken izlerim sanki gulumsuyordu bana bakerken o hala bakıyordu yagmıur yagarken ıslanmıştı ıslanmıştı ıslanmıştı parı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Elif']::text[], 8.5, '{"poet":"Süleyman Elif","poet_slug":"suleyman-elif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerin Gönlündeki Elif', 'gecelerin-gonlundeki-elif-ekrem-kaftan-c8yo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani Elif yazardın gecelerin gönlüne

Deryalar sükût edip kalemini dinlerdi

Yıldızlar gözlerinden nur alırdı o demde

Ve Elif''le başlardın yine bir taze güne

Geceler tükenmenin azâbıyla inlerdi

Ateşler mürekkebin hasretiyle yanardı

İs olup da hokkana dolmak için sultânım

Elifler mazi olmuş saadeti anardı

Bir hicret sonsuzluğu gizleyen zülfesinde

Çağlardı çağlar boyu gönlümdeki ummânım

Elif''in her noktası dönerdi kainâta

Duydukça seher vakti bülbülün nağmesini

Semâzen vecdi ile kaybolurdu noktalar

Gözlerinden dökülen Elif''in etrafında

Beklerdi mısra mısra yazılan aşk sesini

Bir Elif görmek için yükselen minâreler

Teselli bulurlardı ezanda Eliflerle

Kapanırdı gizlice gönüldeki yâreler

Vuslatın âh ettiren o şevk ü tarâbıyla

Ateşlere düşerdi  sermest o pervâneler

Yine bir Elif çekip şu sînemi dağla gel

Görmeyen gözlerimde Elif Elif çağla gel

Gönlüme sevda adlı kaldırılmaz dağla gel

Esîr-i aşkın eyle, hem ruhûmu bağla gel

Benim için Allâh''a hem yalvar, hem ağla gel

30 Ekim 2000', 'Hani Elif yazardın gecelerin gönlüne Deryalar sükût edip kalemini dinlerdi Yıldızlar gözlerinden nur alırdı o demde Ve Elif''le başlardın yin...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gecelerin-gonlundeki-elif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mechul Sultana', 'mechul-sultana-ekrem-kaftan-eefvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrümün fehm edilmez noktasında beklerim

Gelmiyorsun Sultânım, bilmiyorum nerdesin

Gayrı ölüm yolunda yavaş yavaş teklerim

Kabrime giden yolda gözlerinle perdesin

Unutmadım üzdüğüm günlerde azâbını

Şimdi ben çekmekteyim göklerin sıkletini

Tarihlerin tahtına gizledim kitâbını

Ararım gözlerinin sevdâlı minnetini

Mâzîye avdet olsa yanında ölmek için

Semâzence dönerek düşerdim kucağına

Ellerinin nârında yanarak gülmek için

Atılırdım Sultânım sevdânın ocağına

Hangi kapı açılsa ardında zulmet vardır

Kapının eşiğinde tükenseydi şu ömrüm

Senden sonra hep gözler, gönlüm için pek dardır

Bana vuslat olurdu dizlerinde bir ölüm

Nisyân için yazmışım, yokluğunda her şi’ri

Hayâlini silmeye nice güzel bulmuşum

Ateşlere atmışım, binlerce defter şi’ri

Anladım ki, Sultânım pek muztarib kulmuşum

Gelmez senin yâdına İstanbul günlerimiz

Çamlıca’da bir akşam el ele olduğumuz

Kadıköy’den denize, dalan hüzünlerimiz

“Bizi kimse ayırmaz” diye aşk dolduğumuz

Yine vapurlar geçer, iki şehr arasından

Sevdâlılar el ele denizde vuslat arar

Habersizdir her biri bir gönül yarasından

Yârini aşk yerine, denî hislerle sarar

Bilir misin kaç gece vapurlar şâhid oldu

Elindeki âteşin gönlümü yaktığına

“Vuslat muhaldir” diye gözlerimiz hep doldu

Seyrettik yanaklardan denize aktığına

Rüzgâr yine esiyor, Boğaz’dan ey Sultânım

Eteğinin uçuşu hayâlimi süslüyor

Bu anlarda yanıyor, cehennem gibi cânım

“Hâlâ seviyor” demek, melâlimi süslüyor

Topkapı Sarayı’nda râyihanı arardım.

Ayağının tozunu öptüğüm kutlu ânın

Hürmetine sultânım, kirpiğini tarardım

Kalmazdı zerre hükmü, cismimde akan kânın

Sana doğru açılan gizli yol vâr gönlümde

Bir gün çıkıp gelirsin, diye bekler dururum

Bir taht bulmuş olsa da nice bin yâr gönlümde

Geldiğin kutlu günde ellerimle vururum

Bilmedin bu sevdânın sonsuza aktığını

Çevirdin gözlerini ufukların ardına

Belki şimdi anladın, derinden yaktığını

Vuslattan kaçtım diye, gayrı kendini kına

Bir taze sabah başlar, bu şiirle sevdâmda

Dolar yine gülistan solmayacak güllerle

Teselli aramaktan vazgeçerim her câmda

Zikre durur şu gönlüm, seherde bülbüllerle

Bir Hûri suretinde isterim Hakk’tan seni

Cemâl-i İlâhî’yi beraber seyr ederiz

Tanımazsın sevdiğim Cennette elbet beni

El ele tutuşarak ziyâfete gideriz

22 Kasım 1999', 'Ömrümün fehm edilmez noktasında beklerim Gelmiyorsun Sultânım, bilmiyorum nerdesin Gayrı ölüm yolunda yavaş yavaş teklerim Kabrime giden yol...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/mechul-sultana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacakaranlık', 'alacakaranlik-mehmet-serin-zmq7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alacakaranlığı sevmem ben 

Ya gündüz olmalı ya gece

Derin batmalı kurşun insana

Ya da namluda kalmalı

Yarım olmamalı sevgili

Ya sevmeli ya da unutmalı...', 'Alacakaranlığı sevmem ben  Ya gündüz olmalı ya gece Derin batmalı kurşun insana Ya da namluda kalmalı Yarım olmamalı sevgili Ya sevmeli ya d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Serin']::text[], 8.5, '{"poet":"Mehmet Serin","poet_slug":"mehmet-serin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alacakaranlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli', 'sen-gideli-elif-erdem-3ddax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yokluğuna alışmıştım...

Seni sensiz düşünmeye

Geceler boyu elimde kalem

Duygularımı ve acılarımı dillendirmeye

Özlemlerimi,ümitlerimi satırlara dökmeye

O kadar alışmıştım...

Taa ki yeniden karşıma çıkıp

Tüm bedenimi,yorgun yüreğimi

Yeni bir depremle sarsana,

Beni benden alana kadar...

İşte şimdi ben yine

Yitirilmiş bir hayattan çok çok uzaklarda

Kırık dökük hayallerimle

Ve yine değişmez ''keşke''lerle,''belki''lerle

Tasvirindeyim sana bu kadar yakın

Ve aynı anda bu kadar uzak olabilmenin...

Tüm duygularımı uyandırdın yine

Yaşamak bu mu diye

Karanlığına daldığımız o gecenin ilk saatinde

Gözlerine bakarak,

Kokunu soluyarak,

Tüm varlığını hissederek,

Seni yaşayarak düşündüm.

Ve gördüm ki

Yaşamak benden çok uzakmış

Ve ben öleli 5 yıl olmuş...', 'Yokluğuna alışmıştım... Seni sensiz düşünmeye Geceler boyu elimde kalem Duygularımı ve acılarımı dillendirmeye Özlemlerimi,ümitlerimi satırl...', ARRAY['Türk Edebiyatı','Şiir','Elif Erdem']::text[], 8.5, '{"poet":"Elif Erdem","poet_slug":"elif-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-gideli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip....', 'bir-garip-burcin-tamer-tvk2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir garip uyumaktı ölmek aslında 

Bir garip uyumak

Var olmakla olmamak arasında......', 'Bir garip uyumaktı ölmek aslında  Bir garip uyumak Var olmakla olmamak arasında.........', ARRAY['Türk Edebiyatı','Şiir','Burçin Tamer']::text[], 8.5, '{"poet":"Burçin Tamer","poet_slug":"burcin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah', 'bir-sabah-burcin-tamer-f8mev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyanırsın,

Minicik ellerin,ufacık bir başın vardır.

Bir sabah uyanırsın başka bir diyarda!

Bir sabah uyanırsın ki;

Yumuşacık bulutların üstünden ,

Düşüvermişsin aşağıya.

Bir garip hayata ,bir garibin eline.

Ve o sabah uyanınca

Zilin sesini duyarsın

Ve....

Yarışma başlar', 'Bir sabah uyanırsın, Minicik ellerin,ufacık bir başın vardır. Bir sabah uyanırsın başka bir diyarda! Bir sabah uyanırsın ki; Yumuşacık bulut...', ARRAY['Türk Edebiyatı','Şiir','Burçin Tamer']::text[], 8.5, '{"poet":"Burçin Tamer","poet_slug":"burcin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sabah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harbe Giden', 'harbe-giden-ruya-ersoy-jxpty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'harbe giden sarı saçlı çocuk!

 gene böyle güzel dön;

 dudaklarında deniz kokusu,

 kirpiklerinde tuz;

 harbe giden sarı saçlı çocuk!', 'harbe giden sarı saçlı çocuk!  gene böyle güzel dön;  dudaklarında deniz kokusu,  kirpiklerinde tuz;  harbe giden sarı saçlı çocuk!...', ARRAY['Türk Edebiyatı','Şiir','Rüya Ersoy']::text[], 8.5, '{"poet":"Rüya Ersoy","poet_slug":"ruya-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/harbe-giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Yağan Yeminler', 'yagmurla-yagan-yeminler-burcin-tamer-l8tgn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kilo mutluluk alabilirmiyim?

Gözyaşlarımı versem

Bir buluta uzanabilirmiyim?

Göklere yükselsem

Bir gözyaşı, bir mutluluk

Biri gülmek,biri ağlamak

Bir bulutta saklı

Kurcalanmamıpş yıllar,

Altı çizilmemiş sözler.

Bir söz,bir yemin ve yıllar....

Bir yağmurla yağdı,

Sonra sel oldu,

Akıp gitti umarsızca yıllar,

Akıp gitti yollara.

Alıp gitti yollar seni,

Alıp gitti uzaklara.....', 'Bir kilo mutluluk alabilirmiyim? Gözyaşlarımı versem Bir buluta uzanabilirmiyim? Göklere yükselsem Bir gözyaşı, bir mutluluk Biri gülmek,bir...', ARRAY['Türk Edebiyatı','Şiir','Burçin Tamer']::text[], 8.5, '{"poet":"Burçin Tamer","poet_slug":"burcin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurla-yagan-yeminler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesela,Bir Gün,Beraber..', 'mesela-bir-gun-beraber-burcin-tamer-wxlvm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mesela diyorum,

Bir gece şişenin dibini beraber görsek

Ya da diyorum ki,

Bir gece atsak kendimizi denize,

Yine beraber.

Diyeceğim şu ki

Güneş doğmadan mesela

Bir gün beraber olsak seninle

Ve o güneş hiç doğmasada

Biz hep beraber kalsak!!', 'Mesela diyorum, Bir gece şişenin dibini beraber görsek Ya da diyorum ki, Bir gece atsak kendimizi denize, Yine beraber. Diyeceğim şu ki Güne...', ARRAY['Türk Edebiyatı','Şiir','Burçin Tamer']::text[], 8.5, '{"poet":"Burçin Tamer","poet_slug":"burcin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mesela-bir-gun-beraber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'isimsiz 1', 'isimsiz-1-cihangir-gulegen-uj81w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sallanır salıncak

sevdayı bulut eyleyip çekip gitmek lazımdır

söyleyecek söz bulamam gönlümü dar edene

bilirim kapanmak lazımdır içimin dergâhına

zaman değildir durup bakmak zamanı

sallanıp salıncak gibi rüzgar olmak lazımdır

çok vakitler çaldım,,

çok ağıtlar söyledim

hepsi kendim dinledim

bir pervane yürek olup ateşlerde gezindim

demi deme vurup,,

demi demle ovup,,

sarhoş olmak lazımdır

hû çekerim beni benden alana', 'sallanır salıncak sevdayı bulut eyleyip çekip gitmek lazımdır söyleyecek söz bulamam gönlümü dar edene bilirim kapanmak lazımdır içimin derg...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isimsiz-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'isimsiz 2', 'isimsiz-2-cihangir-gulegen-tq5z2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gece vakti

geldim durdum kapında

okudum şarkımızı hicaz makamında

ne kapın açıldı

ne ışık yandı

anladım ki can düşler altında hû

yıldızlar bilir sevdalığımı

olsaydı denizler bulurdum sana

çığlık çığlık martılarıyla

şimdi hangi efkar karaya çıkar

soğuk ve sarhoş eylül akşamlarında

bir rüzgar eser

açılır kanatlarım karanlığa

bir damla düşer bulutlardan yanağıma

çok evvel zamanlar oldu hisarbuselik gecelerden

bir araba farında döndü güne nice vakitler

sana bir sevdam vardı hedie

söyleyemedim

hû

dağınık dumanlar soludum ne ki yokluğunda

kim bilir beni şimdi

ankra''da bir otel odasında

ne kapım çalar

ne telefon böler uykumu

kaybolurum gitarın bas-tiz tonlarında

içtiğim votkadır ya kırmızılığı vişneden

tütün kokulu sakarya barlarında

bazı gölgeler geçer

hatta gölgeler sarar vücudunu

soğuk geceden düşer bir damla yanağıma

hangi gülün kokusu armağan senden bana

yokluğuna armağan bu hicaz beste

şimdi gönül kuşu sarhoş

yalancı muhabbet akşamlarında

hû', 'bir gece vakti geldim durdum kapında okudum şarkımızı hicaz makamında ne kapın açıldı ne ışık yandı anladım ki can düşler altında hû yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/isimsiz-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Güneş Gece ve Küçük Kız', 'yagmur-gunes-gece-ve-kucuk-kiz-burcin-tamer-pl713', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buralarda bir yağmur var

Yağmur gibi değil.

Buralarda bir güneş açar 

Güneş gibi değil.

Buralarda bir gece doğar

Gece gibi değil.

Buralarda bir küçük kız çocuğu ağlar

Senin gibi değil

Ağlar!

Ağlamak gibi değil.

Buralarda bir çiçek açar,

Çiçek gibi değil.

Buralarda bir yağmur açar,

Yağmur gibi değil.

Bir gece ağlar,

Küçük bir kız çocuğu gibi değil.

Buralardaki çiçekler

Senin için değil,

Çiçek gibi değil!!', 'Buralarda bir yağmur var Yağmur gibi değil. Buralarda bir güneş açar  Güneş gibi değil. Buralarda bir gece doğar Gece gibi değil. Buralarda ...', ARRAY['Türk Edebiyatı','Şiir','Burçin Tamer']::text[], 8.5, '{"poet":"Burçin Tamer","poet_slug":"burcin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yagmur-gunes-gece-ve-kucuk-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'isimsiz 3', 'isimsiz-3-cihangir-gulegen-gekf2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu ayın şiirleri

şimdi sensiz yazılır...

ansızın bir sigara yakılır

uzun uzun tellenir duman

bir türkü vurur beni uzaktan

adın gelir dilime takılır

nice sakiler bilir seni

nice kadehler uğruna kırılır

düşün girer düşüme ya

gözlerin her şeyi yarım bırakır

şimdi yağmurlar beklenir camları döven

rüzgar savurur yaprakları

her aldığım gülle

    daha çok dolan kavanoz

        kendinden düşer kırılır

her yere savrulur kurumuş gül yaprakları

cam parçaları sanki yüreğimi kanatır

eylül girer penceremden içeri

artık şiirlerim sensiz yazılır', 'bu ayın şiirleri şimdi sensiz yazılır... ansızın bir sigara yakılır uzun uzun tellenir duman bir türkü vurur beni uzaktan adın gelir dilime ...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isimsiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Üzerine 1', 'olum-uzerine-1-cihangir-gulegen-jsfhu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ölümü alıp yanıma

dalmışım bir uzun uykuya

şimdi kan damlar ellerimden yatağımın kenarına

bir rûya ki hayattan uzun

bir düş ki varlıktan kısa

ölmüşüm;

öldüğüme inanmam inadına', 'ölümü alıp yanıma dalmışım bir uzun uykuya şimdi kan damlar ellerimden yatağımın kenarına bir rûya ki hayattan uzun bir düş ki varlıktan kıs...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olum-uzerine-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımasız Hayat', 'acimasiz-hayat-bahar-avsar-g3jvn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha henüz çocukken tanışdım kötülerle,

daha güzellikleri yaşamadan karıştım çirkinliklere,

beyazlar gözümü almadan sarıldım karalara,

sıcağı sıcağına hissetim acıların ateşini vücudumda.

Güzel sandığımız dünya çoktan yok olmuş,

hayatımızın bütün düzeni bozulmuş,

sevgi yerine yüreğimiz kün ve nefret ile dolmuş,

insanların simdiki yaşadıkları hayat ise anlamsız ve bomboş,

Rüyalarımızda gördüğümüz cennetler hep hayallerde,

pembe düşler meğer hep uzaklarda,

sıcaklığımız ve sevgimiz ise hapis kalbimizin zindanlarında,

açan çiçekler ve doğan güneş sadece masallarda.

Kimse kimseyi düşünmüyor artık,

yine hepimiz kendimiz ile başbaşa kaldık,

nasıl bu denli bencil olduk,

nasıl oldu da böyle bu kadar güzelliği bunca kötülüğe değiştik?

Gözlerimizde göz yaşlarımız yerine nefret parlıyor,

dudaklarımız sevgi sözcükleri yerine küfürler savuruyor,

insanlar birbirine sarılmak yerine birbirini vuruyor,

durun da kendinize bir an sorun; Bizlere ne oluyor?

Bana kulak verin bir dakika ne olur...

Hadi gelin el ele tutuşalım,

bu kötülüklere bir son verelim,

acıları bitirelim,

birbirimizi sonsuza dek sevelim...

Bütün çirkinliklerden ve kötülüklerden uzak bir dünya kuralım,

bu acımasız dünyanın kuralını gelin de artık biz beraberce bozalım,

bunca acıların ve kanayan yüreğimizin öcünü bir an önce alalım,

tıpkı bir zamanlar hayatın bize attığı tokatları bizler de ona bir defa atalım!

Bizlerde artık dilediğimiz ve hayal ettiğimiz gibi yaşayalımç

Zaman geldi artık sakın geç kalmayalım...

Ne dersiniz?

(Ne dersin be kaderaskım?)', 'Daha henüz çocukken tanışdım kötülerle, daha güzellikleri yaşamadan karıştım çirkinliklere, beyazlar gözümü almadan sarıldım karalara, sıcağ...', ARRAY['Türk Edebiyatı','Şiir','Bahar Avşar']::text[], 8.5, '{"poet":"Bahar Avşar","poet_slug":"bahar-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/acimasiz-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşsel Diyalektik', 'dussel-diyalektik-ozgur-deniz-akdeniz-bmvee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sokağımda ışık

 gözümde fer yok 

yoruldum bu patırtıdan

oysa ben istemezdim ki boş bira ve meşrubat şişeleri arkasındaki umarsız ve gayesiz arkadaşlığa bakmayı.

yaşamak her bahar bir ağacın dalında yeniden doğmak değildir oysa 

yaşamak vurunca sarsıntılar içindeki boş şişenin dibine vurmak değildir savunmasız suratımın ortalık yerine

ve katışıksız mutlak inanç özündeyse insanın yaşam yaşamaya değer.', 'sokağımda ışık  gözümde fer yok  yoruldum bu patırtıdan oysa ben istemezdim ki boş bira ve meşrubat şişeleri arkasındaki umarsız ve gayesiz ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Deniz Akdeniz']::text[], 8.5, '{"poet":"Özgür Deniz Akdeniz","poet_slug":"ozgur-deniz-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dussel-diyalektik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderaşkım', 'kaderaskim-bahar-avsar-kbemu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yazyağmuru yağdın üzerime,

aklımı başımdan aldın esen deli rüzgâr gibi delicesine,

ürpertin bir soğuk kış gecesi gibi tenimi,

yaktın içimi bir kor ateş gibi...

Bir şimşek hızında girdin düşlerime,

dokunuverdin o buz dağları ardında sakladığım kalbime,

gelmiş geçmiş en büyük fırtınaları kopardın hayatımda,

tekrar sönmüş volkanı yıllar sonra uyandırdın içimde...

Kurumuş dalları tekrar yeşerttin,

kışlık diyarlara sonsuza dek bahar''ı getirdin,

denizin dalgalarını kayalara çarptın,

bütün karanlık dünyamı sevginle aydınlattın...

Yüreğimdeki kırgınlıkları ve nefreti aşka dönüştürdün,

içimde sakladığım beni herşeye rağmen gördün,

kendime olan sonsuz güvensizliğimi yok ettin,

yeniden hayatı, sevilmeyi ve herşeyden önce seni sevmeyi öğrettin...

Bir zamanlar sönmüş gözlerimdeki pırıltıyı görüyormusun?

Bu ne demek tahmin edebiliyormusun?

Etrafa yansıtığım bu büyük mutluluğumu hissedebiliyormusun?

Kalbim kapısını sonuna kadar açtım girmek istiyormusun?

Tut elimi ve sakın bir daha bırakma,

sarıl bana sımsıkı da sıcaklığını içim titreyene kadar hissedeyim,

yaklaş bana sakın uzak kalma, kaçma

izin verde sana kalbimi sonsuza dek armağan edeyim!!!!!!!

(Seni bir ömür boyu hiç bıkmadan sevecek olan KADERAŞKIN)', 'Bir yazyağmuru yağdın üzerime, aklımı başımdan aldın esen deli rüzgâr gibi delicesine, ürpertin bir soğuk kış gecesi gibi tenimi, yaktın içi...', ARRAY['Türk Edebiyatı','Şiir','Bahar Avşar']::text[], 8.5, '{"poet":"Bahar Avşar","poet_slug":"bahar-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaderaskim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cüzzamlı Bakkal', 'cuzzamli-bakkal-ali-erkan-aktasgul-wy7gy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gök düşmüş yere boyuyor dünyamızı.

Bense hüzünle sevinç arasında sıkıştım kaldım.

Üstünde ölü kargaların kan kırmızı,

Şarkılar söylediği bir ıssız kumsaldım.

Aklım felç etmiş tüm sarhoş dünyaları.

Bense ruhumu deli bir çocuktan çaldım.

Kudurmuş müşteriye ifrit gibi, sapsarı,

Şehveti bal diye satan cüzzamlı bakkaldım.

Uğraştığım tüm dertler öylesine uhrevi.

Bense bin bir küffar şehre hep korku saldım.

Uykusuz martıların yıkadığı masmavi,

Denizlerde rakseden bir acemi sandaldım.', 'Gök düşmüş yere boyuyor dünyamızı. Bense hüzünle sevinç arasında sıkıştım kaldım. Üstünde ölü kargaların kan kırmızı, Şarkılar söylediği bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Erkan Aktaşgül']::text[], 8.5, '{"poet":"Ali Erkan Aktaşgül","poet_slug":"ali-erkan-aktasgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cuzzamli-bakkal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-fazil-husnu-daglarca-x10kb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaç taşı anlamaz

Gökyüzü MAVİ iken

Ağaç susuzluğu anlamaz

Gökyüzü MAVİ iken

Ben seni

Çok sevdiğimi anlarım

Gökyüzü MAVİ iken', 'Ağaç taşı anlamaz Gökyüzü MAVİ iken Ağaç susuzluğu anlamaz Gökyüzü MAVİ iken Ben seni Çok sevdiğimi anlarım Gökyüzü MAVİ iken...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mavi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-fazil-husnu-daglarca-blt8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni

Seni

Öyle uzun seviyorum ki seni

Ya yaradılışta doğmuşum

Ya ölümsüzün biriyim ben...', 'Seni Seni Öyle uzun seviyorum ki seni Ya yaradılışta doğmuşum Ya ölümsüzün biriyim ben......', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantizm', 'romantizm-zafer-ugur-ucaxx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yatıp uzan bir ağacın dibine

Otlar uzanır neredeyse dizine

Rüzgâr sesi romantiktir kimine

Bir başkadır baharda hep duygular.

Papatyalar daldıkça o âyine

Vurdukça hırçın dalgalar sahile

Bazen hüzünlü, bazen de neşeyle

Bir başkadır baharda hep duygular.

Gökyüzü çalar uçuk bir maviye

Sokulur genç yaşlıya, yaşlı gence

Bambaşka bir âlem gibi gelince

Bir başkadır baharda hep duygular.', 'Yatıp uzan bir ağacın dibine Otlar uzanır neredeyse dizine Rüzgâr sesi romantiktir kimine Bir başkadır baharda hep duygular. Papatyalar dald...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/romantizm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar', 'dalgalar-zafer-ugur-9k5lf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep çırpındı, kabardı, kudurdu,

Hınçla çarptı deniz kıyılara.

Azgın dalgalar coştu da coştu

Kabarmış kiniyle insanlara...

Ve bu dev âniden köpük oldu

Çarpınca şu küçük kayalara...', 'Hep çırpındı, kabardı, kudurdu, Hınçla çarptı deniz kıyılara. Azgın dalgalar coştu da coştu Kabarmış kiniyle insanlara... Ve bu dev âniden k...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uğur']::text[], 8.5, '{"poet":"Zafer Uğur","poet_slug":"zafer-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dalgalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarla', 'umutlarla-umit-orengul-lsx1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başbaşa kalsak

Evet başbaşa

Uzaklardan, ta uzaklardan

Bir sesle irkilsem;

O ses...

O ses, ölümün sesi olsa

Ve ben kollarında ölsem', 'Başbaşa kalsak Evet başbaşa Uzaklardan, ta uzaklardan Bir sesle irkilsem; O ses... O ses, ölümün sesi olsa Ve ben kollarında ölsem...', ARRAY['Türk Edebiyatı','Şiir','Ümit Örengül']::text[], 8.5, '{"poet":"Ümit Örengül","poet_slug":"umit-orengul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umutlarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkal', 'tutkal-umit-orengul-zf21e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dehlize düşmüştüm

Sendeleyip yıkılınca...

Bir halat atmadınız,

Tutunup çıkmam için.

Parmak ucunuzu verdiniz

Sözde kurtulmam için.

Ama ben kavradım elinizi

Kavradım, hiç bırakmamacasına...

Eh işte...

Siz de tutuyorsunuz beni

Bırakırım sanmayın elinizi

Çünkü...

Arasına tutkal sürdüm.', 'Bir dehlize düşmüştüm Sendeleyip yıkılınca... Bir halat atmadınız, Tutunup çıkmam için. Parmak ucunuzu verdiniz Sözde kurtulmam için. Ama be...', ARRAY['Türk Edebiyatı','Şiir','Ümit Örengül']::text[], 8.5, '{"poet":"Ümit Örengül","poet_slug":"umit-orengul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tutkal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir Gurbeti', 'kim-bilir-gurbeti-hasan-tulkay-nrcpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbetin kahrını çekenler bilir

Her gece gözyaşı dökenler bilir

Kıvrıla kıvrıla sılaya doğru

Hasret ırmağından akanlar bilir

Gönlümün cilâsı neşesi kayıp

Ağlasam adama derler ki ayıp

Ay hafta gün değil saatler sayıp

Takvime hüzünle bakanlar bilir

Yastık diken olur yüzüne batar

Gam yükü yürekte uzayan katar

Haline haldaş yok içine atar

Ard-arda sigara ykanlar bilir

Dermansız dert üzre düşmüşüm sayrı

Usandım bittim ben tükendim gayrı

Eşinden dostundan vatandan ayrı

Yalnızlık mahkûmu Hasan''lar bilir

Garipler garibi Hasan''lar bilir

          (26100 Romans-Fransa/1994)', 'Gurbetin kahrını çekenler bilir Her gece gözyaşı dökenler bilir Kıvrıla kıvrıla sılaya doğru Hasret ırmağından akanlar bilir Gönlümün cilâsı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tülkay']::text[], 8.5, '{"poet":"Hasan Tülkay","poet_slug":"hasan-tulkay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kim-bilir-gurbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tesadüf...', 'bir-tesaduf-bahar-avsar-wx75s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tesadüfdü seni benim karşıma çıkaran,

sana kalın bir halat ile bağlayan,

kabimin kapılarını sana sonuna kadar açtıran,

seni bana sevdiren ve deliler gibi aşık eden.

Bir tesadüfdü sana güvenmem,

yıllardır karanlığa mahkum ettiğim odamın kapısın açıp aydınlığı içeri bırakmam,

bahçemde solmuş çiçeklere su vermem ve tekrar yeşertmem,

hayata tekrar dört elle sarılmam.

Bir tesadüfdü şu taşdan kalbimin pamuğa dönüşmesi,

içimdeki dev buzdağının erimesi,

kışlık diyarlara da tekrar yaz gelmesi,

bütün kötülüklerin ve nefretin sevgiye dönüşmesi...

Sadece bir tesadüf mü sence?????', 'Bir tesadüfdü seni benim karşıma çıkaran, sana kalın bir halat ile bağlayan, kabimin kapılarını sana sonuna kadar açtıran, seni bana sevdire...', ARRAY['Türk Edebiyatı','Şiir','Bahar Avşar']::text[], 8.5, '{"poet":"Bahar Avşar","poet_slug":"bahar-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tesaduf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini Uzat', 'ellerini-uzat-i-brahim-karadere-2hxli', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ellerini uzat tut ellerimi,

ne kadar sicak degilmi??

gözlerime bak incele bebeklerini,

kendini görüyorsun degilmi??

sana söyleyeceklerim var..

fakat birsey tutuyor dilimi,

söylemek istedigimi??

ANLIYORSUN DEGILMI KADERASKIM', 'ellerini uzat tut ellerimi, ne kadar sicak degilmi?? gözlerime bak incele bebeklerini, kendini görüyorsun degilmi?? sana söyleyeceklerim var...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Karadere']::text[], 8.5, '{"poet":"İbrahim Karadere","poet_slug":"i-brahim-karadere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ellerini-uzat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayten''in sonu', 'ayten-in-sonu-umit-yasar-oguzcan-rhv0j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayten''i Markiz pastanesinde vurdular

Onu ben vurdum

Ayten kanlar içinde düştü yere

Bense ağlıyordum

Şimşek gibi loşluğunda Markizin

Bir usturaydı ellerimde parlayan

Vurdum,ve baktım dağılmış yüzüne

Dedim;o da güzeldi bir zaman

Onun da gözleri vardı,dudakları vardı

Mermerler dile gelirdi konuşunca

Ya elleri her zaman duygulu,serin

Başım dönerdi ellerini tutunca

Önce bir garson gördü ikimizi

Sonra yabancı adamlar gördü,kadınlar gördü

Ayten''i hiç ayıplamadım

O anda kim olsa ölürdü

Renkli bir balon gibi sönüverdi

Koluna gömleğimin kanı damladı

O lekeden başka şimdi

Ayten''den eser kalmadı

Aldılar götürdüler beni

Bu cinayetin hesbını sordular

Dedim:ayten''i ben vurmadım

Onu Markiz pastanesinde vurdular.', 'Ayten''i Markiz pastanesinde vurdular Onu ben vurdum Ayten kanlar içinde düştü yere Bense ağlıyordum Şimşek gibi loşluğunda Markizin Bir ustu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayten-in-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koynumda Taşıdım', 'koynumda-tasidim-osman-erdal-erturan-lw85m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'koynumda taşıdım

gecenin baştan çıkaran kokusunu

aklım odanın penceresinden uçuncaya kadar

karşıya geçemedim

gözlerinden

dokununca gece yalnızlığıma

10/11/2000', 'koynumda taşıdım gecenin baştan çıkaran kokusunu aklım odanın penceresinden uçuncaya kadar karşıya geçemedim gözlerinden dokununca gece yaln...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/koynumda-tasidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyaniş', 'uyanis-ali-erkin-kutlu-8a918', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün-tün eşitliği olunca,

Sen ve ben karşılaşırız 

Bir başına kalmış mavilikte.

Günler uzarsa, 

Çikarsa günes gökyüzüne,

Delicesine,

Sen ve ben kaçıveririz, sessizce...

Sevdiğime güneşler doğuran ülkemize.

Gece kaplayinca karanlıkları

Sen ve ben buluşuruz.

Maviler ülkesinde, mavi ay o sevdiğim renkte.

Geceler derinleşince sinsice,

Sen ben kayboluveririz.

Sarı bir gül içinde…

Gizlice...

Gün-tün dönünce eşitliğe,

Martılar uzaklaşıverecek 

Sevdiğimin hislerine.

Güneş doğacak gözlerine

Uyanıp bakacaksın gökyüzüme.

Sevdigim;

Düşüneceksin gördüklerim rüya mı diye.', 'Gün-tün eşitliği olunca, Sen ve ben karşılaşırız  Bir başına kalmış mavilikte. Günler uzarsa,  Çikarsa günes gökyüzüne, Delicesine, Sen ve b...', ARRAY['Türk Edebiyatı','Şiir','Ali Erkin Kutlu']::text[], 8.5, '{"poet":"Ali Erkin Kutlu","poet_slug":"ali-erkin-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uyanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
