INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-hakan-yigit-a3124', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben sana ne kadar uzak olsam

 o kadar senin yanındayım

seni ne kadar sevsem de 

 o kadar senin sevgine muhtacım...

(19 Kasım 2000 Pazar 19.05)', 'ben sana ne kadar uzak olsam  o kadar senin yanındayım seni ne kadar sevsem de   o kadar senin sevgine muhtacım... (19 Kasım 2000 Pazar 19.0...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce Savaşçısı', 'dusunce-savascisi-osman-ozden-rtc29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben eski devirlerin adamıyım

Düşünce savaşçısıyım

Beynim,

Buzul çağından beridir dünyada

Kelimeler keşfedilmeden,

Duygular bilinmeden,

Ben her şeyi biliyordum

Kırmızı daha renk değildi 

O zamanlar...

Cinsiyetler yoktu

Doğumlar belirgin, 

Ölüm sınırlı değildi

Ama sen

Evrenlerin Efendisi

Tüm ben’liğinle

Yine benimleydin', 'Ben eski devirlerin adamıyım Düşünce savaşçısıyım Beynim, Buzul çağından beridir dünyada Kelimeler keşfedilmeden, Duygular bilinmeden, Ben h...', ARRAY['Türk Edebiyatı','Şiir','Osman Özden']::text[], 8.5, '{"poet":"Osman Özden","poet_slug":"osman-ozden","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusunce-savascisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgama Yetmiyor Geceler', 'kavgama-yetmiyor-geceler-mehmet-tas-ao5r3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yarısı öfke,kalanı sevda

Gönlümü pay ettim  alana gayrı

Bütün sayfaları yırtıp takvimden

Kafa tutar oldum zamana gayrı

             Öfkem yüreğimde bir demir kazık

              Sevdam hak yolunda  kuru bir azık

Bulutlar zehrini sağarlar her gün

Sevdalı dalları hazan örseler

Her kuşta şakıyan ayrı bir hüzün

Geceler yetmiyor kavgama gayrı

             Hasretin kokusu geceye sindi

             Sulara  sessizce bir yıldız indi.

Yollar hep çıkmaza ulaşır bir bir

Düşler yorumunu birden yitirir

Her gülün dalında bir bülbül ağlar

Mevsimler bahara ermiyor gayrı

              İçime,içime bir hüzün çöktü

               Sensiz geçen günler belimi büktü.

Bir garip yaş döker geceye karşı

Sabahtan akşama taşır çileyi 

Susar grup vakti bütün sokaklar

Kaldırımlar sırra ortaktır gayrı

                Sevdamı gökte bir yıldıza yazdım

                ‘’Adını iğneyle kalbime kazdım’’', 'Bir yarısı öfke,kalanı sevda Gönlümü pay ettim  alana gayrı Bütün sayfaları yırtıp takvimden Kafa tutar oldum zamana gayrı              Öfke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kavgama-yetmiyor-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk Ve Ben', 'bosluk-ve-ben-yavuz-suleyman-kirez-c04vu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutsuz akşam

Güneş batalı çok olmamış

Yürü diyor şeytan

Griyle mavinin karışmışlığına

Yürü diyor adalar war karşında

Geç diyor onların ardına

Bırak tüm sewdiklerini

Unut istanbulunu

O nu da unut

Yürü öylece

Günden say geceyi

Yoldan say denizi

Sıyrıl bütün anılarından

Yürü !

Deniz getirecek sana geleceği

Ne kariyer telaşı

Ne de aşk çıkmazı

Boşluk öylece

Adaların ardı...', 'Bulutsuz akşam Güneş batalı çok olmamış Yürü diyor şeytan Griyle mavinin karışmışlığına Yürü diyor adalar war karşında Geç diyor onların ard...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Süleyman Kirez']::text[], 8.5, '{"poet":"Yavuz Süleyman Kirez","poet_slug":"yavuz-suleyman-kirez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bosluk-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nesin?', 'sen-nesin-yavuz-suleyman-kirez-rptgb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyük bi problemsin 

Öyle böyle değil

Havuzsan karar ver 

Boşal ya da dol

İşçiysen dengeli ol

Birgünün diğerine uysun

Çözmesi zor oluyor

En kral matematikçiler 

Çözemez seni

Hastalık mısın yoksa?

Ne ilacın var ne de doktorun

Öyle bir belasın ki sen.

En delikanlı doktorlar 

Tedavi edemez beni

Sen başlı başına hasarsın

Yedek parça bulamadım

Öyle bir kazada doğdun ki sen

En baba ustalar onaramaz beni

Ağır tahribat gücüne sahipsin

Her sözün çelikten asker misali

Öyle bir düşmansın ki sen

En güçlü ordular

En deha komutan 

Yenemez seni

Ve sen öyle bir yaratıksınki

En uçuk genetikçiler

En bilgili biyologlar

Bilmez seni

Sen öyle bir varlıksın

Ne filozoflların çözemeyeceği

Ulaşılmaz , bilinmezsin sen

En büyük aşıkların bile

Anlatamayacağı...', 'Büyük bi problemsin  Öyle böyle değil Havuzsan karar ver  Boşal ya da dol İşçiysen dengeli ol Birgünün diğerine uysun Çözmesi zor oluyor En ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Süleyman Kirez']::text[], 8.5, '{"poet":"Yavuz Süleyman Kirez","poet_slug":"yavuz-suleyman-kirez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-nesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozlak', 'bozlak-adnan-durmaz-srymy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam oldu sarı bozkır bozlak bozlak kanadı

Mezar ıssızlığı çöktü göçük yüzlere

Biçilmiş göğ ekin bakışlarıyla

Birer gölgeydi kadınlar

Sevinç devşirirlerdi 

Bebelerinin ilk umut mumu yanan gözlerinden

Deli bir hayaket gibi koştu yel bağırarak

Parçalanmış eteklerini savurarak

Bir tarih zuhur etti göğün yırtık yerinden

Alaca kuşlukta çekip gittiler

On beş kişiydiler

Onbeşindeydiler

Öküz gönü çarıklarıyla dağlar gibi basarlardı toprağa

Bir kaç nikel para kuşaklarında

Bir de yavukludan yadigâr

Kınalı saç dürülü işlemeli yağlıklar...

Bozkırı biçen dereyi geçemedi ihtiyarlar

Birer mezar taşı gibi kalakaldılar

Çile çiçeklenmiş sakallarına 

Farimiş gözlerinden acı yaşlar boşandı

Korkularını susuşlarına saklayamadılar

Öpülen ellerine bir türlü bakamadılar

Birisi Yemen'' den söz açtı- birisi Balkanlar'' dan

Yeniden sızı verdi kocamış yaraları

Esirlik günlerini anımsadılar

Ufaldı karaltılar kil yeşili dağlarda

Kimisinin anası- kimisinin yâreni

Gitti onlarla ufkun ucuna kadar

Gözleri yabanıl atlar gibiydi

Ve kavi yürekleri kan içinde

Ölümcül bir afat oldu ayrılışları

 Ve bir daha dönülmez kadar uzak

Kerpiçten evlerin el kadar camlarından

Çocuksu gözleriyle bakakaldı yavukluları

Acı yaşlarını saklayamadan siğim siğim ağlayarak..

On beş kişiydiler

Onbeşindeydiler

Bir daha dönmediler...', 'Akşam oldu sarı bozkır bozlak bozlak kanadı Mezar ıssızlığı çöktü göçük yüzlere Biçilmiş göğ ekin bakışlarıyla Birer gölgeydi kadınlar Sevin...', ARRAY['Türk Edebiyatı','Şiir','Adnan Durmaz']::text[], 8.5, '{"poet":"Adnan Durmaz","poet_slug":"adnan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bozlak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-turgut-erdogan-4nxxi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutmadım, unutmadın.

Bir kasım yağmuru oldun,

Şehrin parkelerinde yankılandın.

Ben seni unutmadım,

Sen şehri unutmadın,

Şehir seni unutamadı...', 'Unutmadım, unutmadın. Bir kasım yağmuru oldun, Şehrin parkelerinde yankılandın. Ben seni unutmadım, Sen şehri unutmadın, Şehir seni unutamad...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unutmadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev', 'sev-metin-vatansever-jj7nl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden bu ümitsizlikte boş çabalar?

Her şey boş bir ümit için mi?

Değmez

Unutma!  Ümit verir seversin sevmez,

Başına taç yaparsın kıymetini bilmez.

Neden bu çileyi yaşamdan saymak?

Her şet, tüm gayretin yaşamaksa, yaşama!...

Mutluluk hakkın elbet sev,

Sev, ancak bağlanma körü körüne...

Dıştan göründüğü gibi değil sevgiler,

Yalan...

Neden bu yarına varma telaşı, 

Dur!...

Herşey varmak içinse sabaha, unut,

Unut ki bu günün böyle geçsin,

Gönlün şen kalsın, geceyi yarsın ümidin.

Neden bu mutluluğa susayış,

Herşey aradığın sevgide bitmez,

Bilmeden girme bu sorumluluğa.

DÜŞÜN... Düşün ki; saadet kör etmesin gözlerini,

GÖR... Gör ki; boş bir hülya yıkmasın hayallerini,

DUY... Duy ki; hislerin aldatmasın seni,

SEV... Sev ki; sevdiğin bilsin sevgini...', 'Neden bu ümitsizlikte boş çabalar? Her şey boş bir ümit için mi? Değmez Unutma!  Ümit verir seversin sevmez, Başına taç yaparsın kıymetini b...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sev-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 4', 'sone-4-william-shakespeare-hm6a5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'savurgan güzel,nedir bu kendini harcaman

senin mirasın olan güzellikleri böyle?

doğa temelli vermez ,ödünç verir her zaman

eli açık olana borç verir içtenlikle

böyle yanlış kullanmak olurmu güzel pinti

miras bırakman için sana bırakılanı?

kar etmeyen tefeci bu koskoca serveti

niye tüketiyorsun yaşatmak varken canı

meraklısın kendinle içli dışlı olmaya

bu tatlı benliğin sırf aldatmağa yarar

vaktin geldi diyerek seni çağırsa doğa

vereceğin hesapta elle tutulur ne var?

 kullanmazsan gömülür güzellğin seninle

kullanırsan varisin olur da sürer gider böyle', 'savurgan güzel,nedir bu kendini harcaman senin mirasın olan güzellikleri böyle? doğa temelli vermez ,ödünç verir her zaman eli açık olana bo...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Erken Geldi', 'guz-erken-geldi-refik-durbas-y9ca7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güz erken geldi,sen gelmedin

gelecektin,ben sigarayı bırakacaktım

nikotin bantları yerine

yağmuru akıtacaktım damarlarıma

Bir de intiharını ihtiyarlığımın

Gençliğimin geçmiş baharlarını bir de...

Çocuklar körebe oynamak için yağmurla

gülüşleriyle donatacaklardı sokakları

kanatları gümüşten bir serçe

çocukların körebesi olacaktı

Ben uçurtması olacaktım serçelerin

Memelerinin billurdan gökkuşağı

gecelerimi kuşatacaktı

alnından öpecektim karanlığın

senin uzundan da uzun çığlığından

kirpiklerinin karasına sinmiş

kokundan ve korkundan bir de...

Ah! sana dokunmanın yangını

zemheride buza kesmiş sular misali

sana yorganı olmanın sevdanın

yak ucundan saçının en ince teline

öpmenin,öpüşmenin,koklaşmanın

dudaklarıyla öpecektim seni

Rüzgarın kollarıyla saracaktım

bedenime dar gelen bedenini...

Sen gelmedin,güz erken geldi

gölgem pencere önlerinden

ara sokaklarına düştü karasevdanın

Kalbim hüzün ve kedere...

Gelişini bekliyorum şimdi

gidişini özlediğim gibi...

Kara kuytusunda sevişmenin

şehvetiyle emziresin diye beni

kara urganıyla boğasın diye beni

kara karanlığında unutasın diye beni

Güz erken geldi,sen gelmedin.', 'Güz erken geldi,sen gelmedin gelecektin,ben sigarayı bırakacaktım nikotin bantları yerine yağmuru akıtacaktım damarlarıma Bir de intiharını ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/guz-erken-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Hafta', 'gecen-hafta-unal-gul-y18vh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanının ömrü bir haftaya sığar mı ?

Benim sığdı.

sıcacık ellerini tuttum

ateş dudaklarını öptüm 

ölünceye kadar seveceğimi söyledim 

güzel gözlerine bakarak

dahası yüreğini gördüm 

tüm çıplaklığıyla...

dediği gibi şairin 

ölsem de gam yimem gayri', 'İnsanının ömrü bir haftaya sığar mı ? Benim sığdı. sıcacık ellerini tuttum ateş dudaklarını öptüm  ölünceye kadar seveceğimi söyledim  güzel...', ARRAY['Türk Edebiyatı','Şiir','Ünal Gül']::text[], 8.5, '{"poet":"Ünal Gül","poet_slug":"unal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecen-hafta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Olsun', 'haberin-olsun-muge-doganlar-5i0kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yamaçtan geçeyim,

Yol senin olsun.

Ben zehir içeyim,

Su senin olsun.

Duydum ki yeni bir yar bulmuşsun,

Mübarek olsun..

Bir tane de ben buldum,

Haberin olsun.......', 'Ben yamaçtan geçeyim, Yol senin olsun. Ben zehir içeyim, Su senin olsun. Duydum ki yeni bir yar bulmuşsun, Mübarek olsun.. Bir tane de ben b...', ARRAY['Türk Edebiyatı','Şiir','Müge Doğanlar']::text[], 8.5, '{"poet":"Müge Doğanlar","poet_slug":"muge-doganlar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/haberin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarışınım', 'sarisinim-mehmet-guven-ekmen-2cnvi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani an gelir çaresiz kalırsın,

Ne yapacağını bilemezsin,

Sözlerini bogazımda düğümler,

Sitemlerini içimde bastırırsın,

Hani an gelir çaresizliğinden,

Kendi kendine konuşmaya başlarsıni,

Veya duruduk yere susmadan saatlerce ağlarsın,

Hani aşkını sevgini haykırırsın ama sensizce,

Gözlerinden dökülen yaşlar bile görüncez,

Kan ağlayan için artık yeterder,

Ama dinleyemezsin devam edersin,

Nereye kadar diye sorarsın,

Cevabını bulamıyacağını bildiğin halde kendine,

Bır gün dayanamıyacağınıda bilirsin,

Sebebin ve sonun olucağınıda, ama neylersin deli gönlüm,

Sewmeye ve yaşamaya devam edersin herşeyi göze alarak,

Bir gün oda sevecek diye ümitlenirsin,

Ve bu ümitle azıcıkta olsa acılarını dindirirsin,

Bir gün oda senin için yaşayacak dersin,

Ve ağlamaya devam edersin sessizce ve derinde,

Kimsenin göremediği bir şekilde,

Sen hep böylesin iyi bilirim seni,

Ama bu sefer başkasın,

Vazgeçemiyorsun unutamıyorsun,

Aklından bir an bile çıkaramıyorsun,

Neden deli gönlüm neden,

Ne var bu sefer seni böle yapan ne haydi söle

Ama dur ben sölüyeyim

 O BAŞKA,O BAMBAŞAKA ADIDA R......A', 'Hani an gelir çaresiz kalırsın, Ne yapacağını bilemezsin, Sözlerini bogazımda düğümler, Sitemlerini içimde bastırırsın, Hani an gelir çaresi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Güven Ekmen']::text[], 8.5, '{"poet":"Mehmet Güven Ekmen","poet_slug":"mehmet-guven-ekmen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sarisinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Sevebilir Seni Benim Kadar.', 'kim-sevebilir-seni-benim-kadar-hakki-yalcin-2fov7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim sevebilir seni benim kadar

Oysa ellerin hala yabancı gibi

Bıraksaydım kalbimi avuçlarına

O zaman anlardın, anlardın belki

Sevdim deliler gibi

Neden inanmıyorsun

Korkaklar kaçar aşktan

Sen neden kaçıyorsun

Senin için ben neyim

Söyle onu bileyim

Kapında mı öleyim

Onu mu istiyorsun', 'Kim sevebilir seni benim kadar Oysa ellerin hala yabancı gibi Bıraksaydım kalbimi avuçlarına O zaman anlardın, anlardın belki Sevdim deliler...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-sevebilir-seni-benim-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-ozdemir-asaf-w5tzm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En kısa ceza

Ömür-boyu olandır..

Kimse bilmediğinden.

Kim bilir; 

Belki bir yalan''dır..

Kendiliğinden.

Bir korku''dur belki,

Saklanandır..

Çirkinliğinden.

Bir soru olsa gerek; 

Sorulmadığındandır..

Birden.', 'En kısa ceza Ömür-boyu olandır.. Kimse bilmediğinden. Kim bilir;  Belki bir yalan''dır.. Kendiliğinden. Bir korku''dur belki, Saklanandır.. Çi...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/arayis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahım', 'ahim-yesim-ozyapar-90fu6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bir kenara attıktan sonra 

Sorgusuz sualsiz gittikten sonra 

Beni bir kalemde sildikten sonra 

Neye yarar pişmanlık neye yarar. 

Canımdan canımı kopartmadınmı 

Uğrunda saçımı ağartmadınmı 

Bir anda dünyamı karartmadınmı 

Neye yarar pişmanlık neye yarar. 

Affetmem sevgilim affetmem seni 

Bağlamıştım sana emellerimi 

Allaha havale ettim ben seni 

Neye yarar pişmanlık neye yarar. 

Yalandı sözlerin hepsi bir yalan 

Acı bir hatıra geriye kalan 

O bir çift sözündü içimi yakan 

Neye yarar pişmanlık neye yarar. 

Hani yeminlerin nerde sözlerin 

Ölsemde ayrılmam diyen dillerin 

Sevgiye inancın bumuydu senin 

Neye yarar pişmanlık neye yarar. 

Sevenler bir ömür bekler demiştin 

Ne yeminler edip sözler vermiştin 

Ne yazık sandımki sende sevmiştin 

Neye yarar pişmanlık neye yarar. 

Pişmanlık duyupta gelme istemem 

Kanayan yaramı sarma istemem 

Halimi hatrımı sorma istemem 

Yeniden geriye dönme istemem. 

Yüreğim tutuşup bir kor olsada 

Gözlerim yaşlardan kanla dolsada 

İsmin dudağımda dua olsada 

Ahım var sözümden dönmeyeceğim.	

		

(1983)', 'Beni bir kenara attıktan sonra  Sorgusuz sualsiz gittikten sonra  Beni bir kalemde sildikten sonra  Neye yarar pişmanlık neye yarar.  Canımd...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Özyapar']::text[], 8.5, '{"poet":"Yeşim Özyapar","poet_slug":"yesim-ozyapar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Hayat', 'ey-hayat-yilmaz-odabasi-bd6xx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey hayat, sen şavkı sularda bir dolunaysın.

Aslında yokum ben bu oyunda, 

ömrüm beni yok saysın...

Yaşam bir ıstaka; 

gelir vurur ömrünün coşkusuna.

Hani tutulur dilin,

konuşamazsın…

Tırmandıkça yücelir dağlar.

Sen mağlupsun sen ıssız

ve kalbinde kuşların gömütlüğü; 

tutunamazsın! 

Eloğlu sevdalardan dem tutar,

aşk büyütür yıldızlardan; 

senin ise düşlerin yasak, 

dokunamazsın...

Birini sevmişsindir geçen yıllarda.

Açık bir yara gibidir hâlâ.

Hâlâ ne çok özlersin onu,

ağlayamazsın…

Yolunda köprüler çürür.

Sesin, sessizlik sanki bir uğultuda.

Savurur hayat kül eyler seni,

doğrulamazsın! 

Yapayalnız bir ünlemsin

dünyayı ıslatan şu yağmurlarda.

Her şey çeker ve iter,

anlatamazsın...

Yaşam bir ıstaka,

gelir vurur işte ömrünün coşkusuna.

Sesinde çığlıklar boğulur ama,

bağıramazsın…

Sonra vakt erişir, toprak gülümser sana; 

upuzun bir ömrün ortasında

ne hayata ne ölüme

yakışamazsın…

Yazdırmalısın mezar taşına:

Ey hayat, sen şavkı sularda bir dolunaysın,

aslında hiç olmadım ben bu oyunda

ömrüm beni yok saysın…', 'Ey hayat, sen şavkı sularda bir dolunaysın. Aslında yokum ben bu oyunda,  ömrüm beni yok saysın... Yaşam bir ıstaka;  gelir vurur ömrünün co...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Odabaşı']::text[], 8.5, '{"poet":"Yılmaz Odabaşı","poet_slug":"yilmaz-odabasi","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ey-hayat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum..', 'yoruldum-adil-koruyan-edswk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoruldum, yollarını gözlemekten.

Yelkovanla akrebin yarışından,

Geceyle gündüzün karışmasından,

Beklemekten yoruldum.

Her gün ölüp ölüp dirilmekten,

Ummaktan, umutlanmaktan,

Sözcükleri anlamlaştırmaktan,

Sevmekten yoruldum.

Her gün güneşin doğuşunu izlemekten,

Bir gün gelecek diye beklemekten,

Rüyalarımdaki güzeli sevmekten,

Yaşamaktan yoruldum.

20.11.2000', 'Yoruldum, yollarını gözlemekten. Yelkovanla akrebin yarışından, Geceyle gündüzün karışmasından, Beklemekten yoruldum. Her gün ölüp ölüp diri...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoruldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumla Dans', 'cocuklugumla-dans-ahmet-sahin-soner-la60u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmurları yüklenmiş bulutlar var 

Güneş batmakta ve ufuk hala kızıl

Bir çocuk koşuyor çamurlu yolda 

Kısacık bir pantolon giymiş üzerine

Üzerindeki mintanı yırtık,

Çorapsız geçirmiş ayakkabısını ayağına

Bir damla yaş süzülmüş yanağından,

Neden diye soramadım

Neden ağlarsın be çocuk , 

Öylesine geçip gitti önümden ,

Tophanenin arka sokaklarına doğru

Karanlığa koştu ,

Aman sende dedim ;

Ama düşünmeden edemedim

Boş ver diyemedim ,

Hava soğuyor , yağmur düşüyordu ,

Damlalar ıslatıyordu kaldırımları,

Islanıyordu istanbul

Islanıyordu gönlümün fidanları

Yolum çocuğun yoluna düştü ,

Yolum tophanenin arka sokakları 

Karanlık dar bir sokaktı.

Küçük bir sokak lambası ile aydınlanan,

Birkaç ağaç serpiştirilmiş üstüne

Tahta kapılı bahçeli evler

Arnavut kaldırımlı taş parkeli bir sokak

Çocukluğumu hatırladım 

Ve çocuk oldum bir an 

Yüksel  teyze ile fatma ablanın kavgaları

Rıfat  bakkalın şekerlemeleri 

Sobasız evimizin tütmeyen bacası geldi aklıma,

Benim hiç kaloriferli bir evim olmadı ki,

Ve her zaman bacası tüten bir evim,

Komşu anne derdim tüm kadın komşulara

Tüm erkeklerde komşu babalarımdı benim

Babam askerdi o zaman,

Resimler yollardı , dindirmek için özlemleri 

Asker buya toplu halde hepsi bir , hepsi yeşil 

Hep karıştırırdım babamı , resimlerde ;

Çareyi hepsine baba demekte bulurdum . 

Kaç baban var diye sorduklarında

Bilmezdim ya rakamları,

On tane babam var derdim,

Ben çocukken hiç oyuncağım olmadı ki

Ben çocukken ,

Eski bozuk bir radyo ile oynardım akşamları ,

Çöp kamyonları geçerdi evimizin önünden,

Üzerlerinde kırık dökük oyuncaklar görürdüm,

Ben çocukken çöpçü olmak istersim hep,

Alıp o oyuncakları tamir etmek isterdim, 

Ve hediye etmek kardeşlerime

Tahta bir kapını önünde durdum

İçeriye baktım uzun uzun 

Ve anlattım ya işte , 

Önümden seyirterek geçen çocuktu çocukluğum.

Tahta kapılı bir evin avlusunda 

Eski bir radyoydu oyuncağı, 

Ve evin bacısında duman yoktu ,

Tophanenin arka sokaklarında 

Tahta kapılı bir evin avlusunda ,

Dans ediyordu gözümün önünde çocukluğum', 'Yağmurları yüklenmiş bulutlar var  Güneş batmakta ve ufuk hala kızıl Bir çocuk koşuyor çamurlu yolda  Kısacık bir pantolon giymiş üzerine Üz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/cocuklugumla-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Bizim İçin', 'her-sey-bizim-i-cin-metin-vatansever-zdkde', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz bu yerler bağrına bastı beni, Ama...

Yüreğimde sır tutmuş sevdan var,

Hayallerim var, sensiz bitmiyor düşlerim.

Gündüzlerin üzerine devrilen, devriliveren geceler var,

O saymakla bitmeyen korkunç geceler...

Saatlerin sabahları vuracağı ana,

Tüm umutlarını bağlamış ben varım...

Ve sen varsın bir tanem, sevdalım...

Senin için, bizim için bu bekleyiş

Yarınımız için herşey...

Varsın öyle sensiz, bensiz geçsin geceler,

Aynı ümitlerle bağlı değilmiyiz anılara, yarınlara?

O güzel günlerin,

Aydın yarınların özlemiyle yaşamıyormuyuz?

Beni bağrına basan bu yerlerden,

Bu gecelerden kopup döneceğim biliyorsun,

İçimizde bir anda dindireceğimiz özlemimiz var, Her gecemizde sır tutmuş sevdamız var,

Birbirimize sunacağımız...', 'Sensiz bu yerler bağrına bastı beni, Ama... Yüreğimde sır tutmuş sevdan var, Hayallerim var, sensiz bitmiyor düşlerim. Gündüzlerin üzerine d...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/her-sey-bizim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Ay Tutulacak', 'bu-aksam-ay-tutulacak-hakan-gursu-ew7z7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam ay tutulacak

Ay bakışlarımızda tutulacak

Sonra,

Sen tutulacaksın düşlerime daha bir,

Derken,

Çılgınca bir sevişmemiz başlayacak

Karanlığın bittiği yere gitme diyeceksin

Bu akşam ay tutulacak

Ay bakışlarımızda tutulacak

Bir büyülteçin içinde çoğalacak zaman

Önce saatler dakikalara

Sonra dakikalar saniyelere dağılacak

En güzel anı sen olacaksın yaşamın

Bu akşam ay tutulacak

Ay bakışlarımızda tutulacak

Aşk 

Bir başka doğacak içimize

Tut ki,

Birlikte olmanın ıslaklığını yaşayacağız

Say ki,

Birlikteliğin tadını çıkaracağız

Temkinli sancıları bir kenara atıp

Yanlızca var olduğumuzu düşüneceğiz

Bu akşam ay tutulacak

Ay bakışlarımızda tutulacak', 'Bu akşam ay tutulacak Ay bakışlarımızda tutulacak Sonra, Sen tutulacaksın düşlerime daha bir, Derken, Çılgınca bir sevişmemiz başlayacak Kar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-aksam-ay-tutulacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-hakan-gursu-n6r50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırlarda dolaştım

Seni aradım

Çiçekler kokladım

Hep seni andım

Sanmaki yanlızdım

Aşkınla vardım

Sensiz olamazdım

Seni yaşadım', 'Kırlarda dolaştım Seni aradım Çiçekler kokladım Hep seni andım Sanmaki yanlızdım Aşkınla vardım Sensiz olamazdım Seni yaşadım...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozleyis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-sunay-akin-sujq2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Odunsuz bir sobanın 

yanında titreyen 

çocuğu görse yağmur 

gözyaşlarını odaya 

tavanarasındaki delikten 

usulca bırakır', 'Odunsuz bir sobanın  yanında titreyen  çocuğu görse yağmur  gözyaşlarını odaya  tavanarasındaki delikten  usulca bırakır...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozyasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yeni Yaş İçindir', 'her-yeni-yas-i-cindir-ozdemir-asaf-bcrp5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni bundan böyle

Beklese-beklese

Hüzün bekler, 

Çağırsa-çağırsa

Hüzün.

Neden mi? 

Neden olacak..

O kadar gezilip görüldü ki..

Hep ben bir şeyden,

Bir yer’den

Bir kimse’den uzaktaydım

Ve kendimden.

Ölüm beklemez beni..

Çünkü, ben gene de

Bir şeye,

Bir yer’e

Ya da bir kimseye giderken de

Kendimden uzakta olacağım.

İşte

Bunun adı hüzündür.', 'Beni bundan böyle Beklese-beklese Hüzün bekler,  Çağırsa-çağırsa Hüzün. Neden mi?  Neden olacak.. O kadar gezilip görüldü ki.. Hep ben bir ş...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-yeni-yas-icindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Alışılmaz', 'aciya-alisilmaz-ahmet-telli-dyw73', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi çığlık bir çığ gibi yarıyorsa

gecenin gerilmiş karnını bu saatte

acı tükenip bitmiştir orada artık

çırılçıplaktır tarihin bu sayfası

Fiziğin armağan ettiği bu teller

keçeleştirirken cinsel organımı

haykırıyorum insan olduğumu

ve çatlatıyor alnımın en gergin teli

Bu Kent Öldürüldü Diyorlar

Bu kent öldürüldü diyorlar

kurşuna dizildi bir geceyarısı

Hayaletler geziniyormuş şimdi

sokak aralarında ve caddelerde

baykuş tüneği olmuş alanlar

ve yarasalar uçuşuyormuş

Silah ve esrar kaçakçıları

altın çağını yaşarlarken

artıyormuş bir yandan da

kumarhaneler, meyhaneler

Borsa oyunları, hileli iflaslar

birbirini kovalayıp dururken

nasıl çıkmışsa pek bilinmiyor

yaygınmış şimdilerde rus ruleti

İntiharların sayısı bilinmiyor

çoğalıp duruyormuş fahişeler

ve artık bunların hiçbiri

olay bile sayılmıyormuş şimdi

Bu kent öldürüldü diyorlar

bahar gelmez artık buraya', 'Hangi çığlık bir çığ gibi yarıyorsa gecenin gerilmiş karnını bu saatte acı tükenip bitmiştir orada artık çırılçıplaktır tarihin bu sayfası F...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aciya-alisilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akbabalar Kelebekler', 'akbabalar-kelebekler-ahmet-telli-af5uo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreği ağzında bir çocuk

Gibi alırken kalemi elime

Beceriksiz, acemi ve olasıya

Yapayalnızım her defasında

Bu sonuncu olsun diyorum

Ömrümün eksiksiz tek şiiri

Yazılsın artık kırk yaşımın

Ve bir aşkın bittiği bu gece

Akbabalar bin yıl kelebekler

Bir mevsim yaşarlarmış ki aşk

Da kısa ömürlüdür, başlar

Gibi biter yaşanmışsa eğer

Yaşanan ne varsa hoşgörünün

Bir parçasıdır artık ama ben

Yine de yakabilirim bu gece

Bütün anılarımı bir şiir için

Sonra irkiliyorum, anılarım yoksa

Dostlarım da terkedilmiştir yangın

Sürüp dururken yurdumda ki o zaman

Kıymeti harbiyesi nedir bu şiirin

Sabaha karşı dilim paslı

Beynim keçeleşmiştir ve yangın

Yalnızlığıma sıçrarken üşüyor

Bütün sözcükler. Umut yoktur

Yüreğim diyorum, kekeme

Alıngan, serseri yüreğim

Sen nerden bilebilirsin

Bir şiirin nasıl yazıldığını

Ahmet Telli', 'Yüreği ağzında bir çocuk Gibi alırken kalemi elime Beceriksiz, acemi ve olasıya Yapayalnızım her defasında Bu sonuncu olsun diyorum Ömrümün ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/akbabalar-kelebekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamı Geciktirebilirsin Belki', 'aksami-geciktirebilirsin-belki-ahmet-telli-oru1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün batarken sula fesleğenleri

balkonun kokusu sokağa taşsın

sokaklar kayıp çocuklar gibi

hırçındır, ürkek ve biraz şaşkın

Sular bulutlanır sen susarsın

ve kent çıngıraklı bir yılan kadar

zehirlidir artık sevgilin mahpusken

üstelik kirli bir lekeye döner umutlar

Acılar katlanır mendil yerine

sarışınlaşırsın bu kaçıncı güz

ellerin üşür, çiy düşer çiçeklere

beklediğin mektuplar da gelmez

Bomboş sayfalara dönerken aklın

tecrit''teki kitabı fareler kemiriyor

ve düşlerin sonsuz bir boşluktayken

bir sigara yakıyorsun, tutuşuyor sular

Akşamı geciktirebilirsin belki

suladığın fesleğenlerle, kimbilir

ama vaktin ayırdındadır şimdi

kuşlar, çocuklar ve mahpuslar

Usulca inse de koldemirleri

(Feride için)', 'Gün batarken sula fesleğenleri balkonun kokusu sokağa taşsın sokaklar kayıp çocuklar gibi hırçındır, ürkek ve biraz şaşkın Sular bulutlanır ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aksami-geciktirebilirsin-belki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklar mı I', 'asklar-mi-i-ahmet-telli-axipr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşklar mı diyordun, 

anladım

Senin incindiğin, 

benimse

Yollara düştüğümdür yeniden

(Çocuksun Sen)', 'Aşklar mı diyordun,  anladım Senin incindiğin,  benimse Yollara düştüğümdür yeniden (Çocuksun Sen)...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/asklar-mi-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-ahmet-telli-e75gv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Bekle beni küçüğüm

umudu karartmadan

sevinci yitirmeden bekle

döneceğim bir gün elbet

bekle beni

Bahar geldiğinde

kırlara çıkacaksın

dizboyu otlar üstünde

koş koşabildiğince

ve sakın yitirme neşeyi

Kırların sessizliğinde

yüreğinin sesini dinle

ve orada benim için

küçücük bir yer ayır

ve bekle beni küçüğüm

Doğa pervasızdır biraz

bakarsın en olmaz yerde

masmavi bir su fışkırır

ve suyun ışıldayan göğsünde

sevincin nilüferleri

Bahar şaşırtmasın seni

sırtüstü uzan bir gölgeye

suların, kuşların sesini dinle

ve bekle beni orada

döneceğim küçüğüm

II

Mapusane türküleri

hüzünlüdür biraz

belki her dinleyişinde

yüreğin burkulmakta

için sızlamaktadır

Ama acılara alışılmaz

birşeyler var değişecek

birşeyler var

değiştirmemiz gereken

önce acılardan başlanacak

Beş on yıl dediğin

pek kolay geçmeyebilir

üstelik bu savaş

bu kahredici kıyım

bitmeyebilir daha uzun süre

Ama sen sahip çıkarak

yaşama ve sevince

bekle beni küçüğüm

acılar bitecek bir gün

sevgiler çiçek açacak

Mapusane türküleri

hüzünlüyse de biraz

yüreğin burkulmasın

için sızlamasın sakın

ve bekle beni küçüğüm

III

Kış kıyamet bir gün

bakarsın çıkıp gelmişim

varsın azgınlaşsın tipi

ve uğuldayadursun

dışardaki rüzgâr

Sakın şaşırma küçüğüm

üşümüş bir serçe gibi

titremesin ellerin

apansız çıkıp geleceğim

kış kıyamet de olsa bir gün

Uğuldayan bu rüzgâr

bu delice yağan kar

ürkütmesin seni

direnmektir artık

bekleyişin öbür adı

Sen türküler söyle

ve gülümse küçüğüm

çünkü sesinin

ırmağıyla yeşerecek

hasretin bozkırları

Bekle beni küçüğüm

umudu karartmadan

sevinci yitirmeden bekle

döneceğim bir gün elbet

beke beni küçüğüm

(Saklı Kalan)', 'I Bekle beni küçüğüm umudu karartmadan sevinci yitirmeden bekle döneceğim bir gün elbet bekle beni Bahar geldiğinde kırlara çıkacaksın dizbo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/bekle-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Hüzünle', 'eski-bir-huzunle-ahmet-telli-15sgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerdir eski bir hüzünle çıkıyorum voltaya

(kötüye işaret bu, üstelik yalnızlığa sığınıyorum)

Unutup gitmişim ezberimdeki bütün şiirleri

bulutlara bakıyorum uzun uzun, yalnız bulutlara

O uzak kasaba akşamları düşerken aklıma

tecrit''teki yine bir türkü tutturuyor

Ey kalbim sana denk düşüyor bütün bu acılar

acılar tek ve mutlak olan bir şeyi anlatıyor

Yağmur kuşları geçiyor avludan sürü sürü

dalların hışırtısını duyuyorum, üşütüyor beni

Ötede, kentin üstünde bir şimşek çakıyor birden

suretin yansıyor göğe ve her yağmur damlasına

Uzak bir anı oluyor her şey, silikleşiyor

ve alnım ateşler içinde, bir tutabilsen

unutup gitmişim bütün türküleri artık

(kötüye işaret bu, üstelik yalnız sana sığınıyorum)

Kısa süren hastalıklar vardır ya, işte öyle

geçip gidiyor akşama doğru hüzün bulutu

resmini asıyorum ranzamın başucuna yine

ve bir türkü tutturuyorum günün son çayında

-Teslim olmayalım halilim kurşun atalım!', 'Günlerdir eski bir hüzünle çıkıyorum voltaya (kötüye işaret bu, üstelik yalnızlığa sığınıyorum) Unutup gitmişim ezberimdeki bütün şiirleri b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eski-bir-huzunle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç', 'goc-ahmet-telli-120eu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göç oldu bir acıdan öbür acıya

oysa sağrısı kurumamıştı atımızın

daha dün sürüp gelmiştik buralara

bugün göründü yine yolların ucu

Devrildi kıl çadırlar seher vakti

usulca uyandırıldı çocuklar

ve kadınlar bohçası çözülmemiş

bir keder gibi gibi düştüler yola

Turnalar gitti biz gittik

bitmedi peşimizdeki nal sesleri

nerde konaklasak tedirgindik

kuruyordu ırmaklar ve göller

Bir yangın gibi taşıyıp durduk

kederi ve acıyı göğsümüzde

yer gök duman içindeydi sanki

genzimizi yakıyordu ayrılıklar

Zulüm bırakmadı peşimizi hiç

biz gittik o buldu izimizi

konar göçer olduk yedi iklimde

tanığımızdır dağlar taşlar

Yalnız bir öfke ışıltısı kaldı

gözlerimizin yorgun sularında

yaşamak bir inat oldu artık

yaşamak bir direnme oldu zulme

Ve işte devrildi yine kıl çadırlar

göç başladı bir acıdan bin acıya

Geride akşamın küllenen ateşi

ve susturulmuş çocuk sevinçleri kaldı

(Su Çürüdü)', 'Göç oldu bir acıdan öbür acıya oysa sağrısı kurumamıştı atımızın daha dün sürüp gelmiştik buralara bugün göründü yine yolların ucu Devrildi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/goc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmlâsız', 'i-ml-siz-ahmet-telli-2soj6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayağı kayan bir çocuk

Kadar şaşkınım, bilemedim

Düz yolda yürümenin imlâsını

Kanayan dizlerime bakıp da

Ağlamayı öğrenemediğim gibi

Sevgilisi değildim kadınlarımın

Bir papağan tüneğiydim belki

Ama birkaç sözcük öğrendiysem

Kadınlardan öğrendim, yine de

Bilemedim sevgilim diyebilmeyi

Büyülendim ama büyüyemedim

Aklım ermedi aynalara ve suya

Yüzümü gösterip kalbimi neden

Sakladıklarını öğrenemedim

Şaşkınım, cahilim ben bu dünyada

(Çocuksun Sen)', 'Ayağı kayan bir çocuk Kadar şaşkınım, bilemedim Düz yolda yürümenin imlâsını Kanayan dizlerime bakıp da Ağlamayı öğrenemediğim gibi Sevgilis...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imlasiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmail''in Kitabını Okurken', 'i-smail-in-kitabini-okurken-ahmet-telli-u81ip', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsmail''in kitabını okuyorum üç gecedir

ateşler içindeki dünyada bir neferin

ölüme at koşturan rüzgârını duyuyorum

Managua yanıyor, her yanım ateşler içinde

yanıyor bir çocuk sevgiyle okşanmaktan

ve temkinli olmak yakışmazdı sana zaten augusto

ve sen ey idris

ismail''in ölümü küçümseyen dostu

''yediğin kurşundan

bir gümbürtü kaldı ki bana! ..''

Roma''da navona alanında bırakıp ismail''i

telzaatar''a dönüyorum gecikmiş bir martı gibi

Yurdum diyebileceğim

her yer kan-revan içinde, görüyorum

ve boğazlanmış bir ceylan gibi

serilivermiş denizler ortasına

Önce ismail orda, ne zaman gelmiştir

''gümbür gümbür ve sonuna kadar, taa-sonuna

sonuna kadar sevdaya, sonuna kadar kavgaya

çatlayacak kadar sabırsızlıkla''

İsmail''in kitabını okuyorum üç gecedir

ve alnımı seher rüzgârına dayayıp

sesleniyorum

''-Ey usta

nerde benim payım içtiğin baldırandan! .''

(Belki Yine Gelirim)', 'İsmail''in kitabını okuyorum üç gecedir ateşler içindeki dünyada bir neferin ölüme at koşturan rüzgârını duyuyorum Managua yanıyor, her yanım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ismail-in-kitabini-okurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Bir Kış', 'sicak-bir-kis-ahmet-telli-k9ysw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçlarını gittikçe kısalttığın günlerde

Sen söylemiştin bu sözleri unutmadım

-Her aşk bir ayrılık gizler, ayrılıklarsa

Bir merhabanın sıcaklığını taşır kendisinde

Kalıcı olan hiçbir şey yok diyordun

An''lar var yalnız ömrü karşılayan

Şimdi sımsıcak bir kar yağıyor yine

Yüreğimin üstüne yağıyor hiç durmadan

Ellerin nasıl da üşüyor, bozacının

Karlı sesi doluyorken odamıza

Hava gittikçe kirleniyor bu kentte

Ve aralıksız kar yağıyor kar yağıyor

Kar ayrılık hüznüdür ve ne çok

Ayrılıklar yaşandı şu son birkaç yılda

Yurdundan ayrılanları düşünüyorum ve birisi

Özledim diyor, ülkemin kar kokusunu da özledim

Hiçbir an''ını tanımlamaya kalkmadan

Kısacık ömürler biçiyoruz kendimize

Sonra yolculuklara çıkıyoruz, bir kentten

Ötekine giderken özlüyoruz bir başkasını

Özlediğimiz birileri olmalı diyordun

Yanındayken bile özlediğimiz birileri

Öyleyse kalkıp Ati''ye gitmelisin, İstanbul''a

Belki hâlâ saklıyordur bir gülü kimbilir

Yaşandı mı o sıcak kış, yaşlandık mı

Aynalara bakmaya vakit bulamadık

Dönüp dönüp birbirimize bakmalardan

Yaşandı mı o sımsıcak kış, ne dersin

(Çocuksun Sen)', 'Saçlarını gittikçe kısalttığın günlerde Sen söylemiştin bu sözleri unutmadım -Her aşk bir ayrılık gizler, ayrılıklarsa Bir merhabanın sıcakl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sicak-bir-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizi Sevmiyorum', 'sizi-sevmiyorum-ahmet-telli-nk8lo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizi Sevmiyorum

Sesimden arındım ve ufku

Bir harmani gibi giyindim

Kahraman bir korkaktım

Kavmimin kadim tarihinde

Ki onlar için umutsuzluk

Kendim için haramiydim

Böyle bilindiydi bu hikâye

Yarından bugüne kaldıydı

Tersine akan bir ırmaktım

Sözün şaşkın serinliğinde

Kendi deltasında boğulandım

Ve sizi sevmiyorum ey kavmim

Yakın beni rüzgârın ıslığa

Islığın hükme döndüğü yerde

Derim ki ey kavmim, zulmünüz

Payidar, yurdunuz çığlığımdı

Ki hükmümü kendim veriyorum

Yakın beni sesim sorulara dönmeden

Küllerimin altında kalacak

Mutluluk sandığınız ne varsa

Böyle yaşandıydı bir ömür ve söz

Giyotindi sözün belleğinde

(Çocuksun Sen)

Ahmet Telli', 'Sizi Sevmiyorum Sesimden arındım ve ufku Bir harmani gibi giyindim Kahraman bir korkaktım Kavmimin kadim tarihinde Ki onlar için umutsuzluk ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sizi-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenildik', 'yenildik-ahmet-telli-vw2mj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yenildik;

Şimdi kim bilebilir zakkumun

O kekre tadını bizim kadar

Tenimize sinmiş sülfür kokusunu

Soluğumuzdaki cıvayı kim duyar

İntikamcıydı bilim, sezgimizse

Gölgesi sulara vuran bir ceylan

Neyi yaşamışsak ömrümüz diye

Derimize yazdı o vak''anüvis

Kehribar saplı bir hançerle

Kehânet kuyularında sınandık

Terkettiğimiz her şehir yakıldı

Anıtlar dikildi kahhar ve kutsal

Zamansa bir karadeliğe dönüştü

Belleğimizin oksitlenen çöllerinde

Çöl ve moraran cesetler, rüya

Kâbusa dönüyor cinnet saatidir

Coğrafyanın bu yakasında bir halk

Kendi oğullarını boğazlıyor artık

Kûfi bir cesaret oluyor cinnet

Biz keder diyorduk, tarihmiş

Dilimizde işte o kil ve kül tadı

Şimdi kim bilebilir yenilginin

O kekre kokusunu bizim kadar

Soluğumuzdaki cıvayı kim duyabilir', 'Yenildik; Şimdi kim bilebilir zakkumun O kekre tadını bizim kadar Tenimize sinmiş sülfür kokusunu Soluğumuzdaki cıvayı kim duyar İntikamcıyd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yenildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Kekemeydi', 'zaman-kekemeydi-ahmet-telli-akgbb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün bitti, elindeki güller de soldu 

anımsanacak neler kaldı bugünden 

paylaşılmış olan nelerdi sımsıcak 

belki bir türkü söyleriz geceye karşı 

saçlarını tarazlayan bir şafak olur 

Zaman kekemeydi ve tarihe sızan 

soytarılar gördük gencömrümüzde 

ölüm peşimize düşende bir göçebeydik 

suretimiz ağardı kurulan darağaçlarına 

bütün sığınaklar uçurumlara açılırdı 

Rüzgâr suyu soğutsun su terli bedenlerimizi 

ve aşkı düşünelim biz, destan yalnızlıkları 

konuşursak akşam olur ve yine yağmur yağar 

gidersek gülüşler azalır buralarda 

kim bulur kayıp adresteki dostları 

Bir karanlığa bakıyorum bir de zamana 

ay büyüyüp bir gül oluyor ellerinde senin 

ve ancak yeni bir yorumu oluyor aşkın 

saçlarından sızan bu karanlık yağmur 

ayın çağıltısıyla tutuşuyor begonyalar 

Saçlarındı diye düşünüyorum ömrümüzü 

çözdükçe savrulan rüzgârdı saçların 

ve ikide bir aklıma düşüyor aynı soru 

-Aşkı bilmiyorsam nasıl değiştiririm 

kendimi, seni ve bütün dünyayı', 'Gün bitti, elindeki güller de soldu  anımsanacak neler kaldı bugünden  paylaşılmış olan nelerdi sımsıcak  belki bir türkü söyleriz geceye ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-kekemeydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herhangi Bir Aşka Dair', 'herhangi-bir-aska-dair-ahmet-telli-rxk2j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herhangi bir kızınkinden ayrı değildi öyküsü

hayatına ülkesini ekleyip yaşamaktan başka

Usulca eğerek başını

yürürken nedense hep

birbirine dolaşır

gibi olurdu ayakları

Bir fotoğraf ve yeni

koparılmış bir çiçekti

ilk mektubuna eklediği

kelimelerse büsbütün yangın

Durup durup iç çekişleri

sessizliği, dalgınlığı

acıyla bakışı yollara

aşkı öğrenişindendi

Çiçekli bir dal

gibi uzandı sevdiğine

ve yalnızca

ayrılıklar korkuttu onu

Böylece bağladı

hayat, dünya ve kavga

ve aşk

onun tarihinde milattı

Temiz çamaşırlar ve bir demet çiçek

taşıyor simdi o kız, görüş günlerine', 'Herhangi bir kızınkinden ayrı değildi öyküsü hayatına ülkesini ekleyip yaşamaktan başka Usulca eğerek başını yürürken nedense hep birbirine ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/herhangi-bir-aska-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos', 'kaos-ahmet-telli-u6tib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay inceldi ve orman

bir tortu gibi çöktü dibe

Buğusu yoktu toprağın

büsbütün balçıktı yeryüzü

Irmaklar sağırdı ve dağlar

birer aptaldı o hantal gövdeleriyle

Gittikçe büyüyordu rüzgarın beynimdeki ur

Öfkemizden şimşeği yarattık

İnsanı yarattık

(hayır, balçıktan değil)

O gün bugün arayıp dururuz onu

hangi cehenneme gitti, bilmeyiz

Ahmet Telli

Karda İzler

Karda izler bırakıyorum avcılar peşime düşsün

Bir uçurum kenarında vursunlar beni ki dünya

Uğuldayıp duran bir uçurum değil miydi zaten

Karda izler bırakıyorum avcılar peşime düşsün

Siliyor adımı bir dal kırarak çam ormanından

Gibi incelterek yetişiyor ardımdaki tipi bana

Adımı yazıyorum kar üstüne ve ıslığını çığlık

Geçmişim kar sessizliğiyle özetleniyor artık

Bir kahkahayla çekip giderim karlı ovalardan

Bir uçurum kenarında vursunlar beni,vursunlar

Karda izler bırakıyorum avcılar peşime düşsün

Yolculuklar ve ayrılıklarla anlatılabilir ancak

Derim ki kar ve hüzün bir aşkın seyir defteridir

Kar yağıyorken milyon kere hüzün yağıyordur

Karda izler bırakıyorum avcılar peşime düşsün

Ömrüm parmak uçlarımda eriyen bir kar tanesi

yakışmıyor onlara.', 'Ay inceldi ve orman bir tortu gibi çöktü dibe Buğusu yoktu toprağın büsbütün balçıktı yeryüzü Irmaklar sağırdı ve dağlar birer aptaldı o han...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kaos-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlama Beni', 'suclama-beni-ahmet-telli-y1tsl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suçlama beni

böyle bırakıp

gidiyorum diye

bağrımı yakan

bir yaradır

bu ayrılık şimdi

Bil ki kanımdadır

sevişmelerin yangını

öylece girerken

gecenin bağrına

taşıyorum sımsıcak gülümşeyişini

Yaşanan günler

hayatı oyarak

gedikler açıyor

durulur mu artık

durgun sularda

bekleyerek seheri

Talan ediliyor

bahar ve aşk

öyle bir soyun ki

duracak gibi değil

vurmazsak eğer

kendimizi yola

Yaşamak zorunlu

kurtarılırsa eğer

bahar ve aşk

ve şimdi hayat

acı yeşil

bir kader renginde

Hayatın ve sevincin

kaderinin altettiği yer

kavganın ortasıdır

ki umudun çiçeklenişi

aşkın

yengisidir bu

Söylenecek bütün sözler

sevincin ve sevdanın

savunulmasına dairdir

ve şimdi onlar

yaralarını saracak

birilerini beklemektedirler

Ey anısıyla

kalbimi yakan

kederlenme hemen

ve suçlama beni

böyle bırakıp

gidiyorum diye

Ahmet Telli

Kül Olan

Bu kentte sorular yasaklanmıştır

böyle diyorlar fısıldarcasına ve ürkek

ve diyorlar ki gidip anlatılsın bir kez

çare düşünsün tarih denilen bilici

Gidip anlatılsın beklenen yolculara

aşklar küllenmeden ve beynimizi

büsbütün kemirmeden veba

yetişsin durmadan yolu gözlenen

Bu kentin sorusunu yanıtla ey yanılmaz olan

kahret ya da ışıklandır ve de ki:

-Siz ki yangın yıllarından geliyorsunuz

umuda bağlanmak umutsuzluktur ancak

Ve sen ey bilici, de ki:

-Bu masal çok anlatıldı önceleri

çocuklar da susturuldu her defa

karartıldı evlerin bütün ışıkları

-Ve direnmeyi bilmiyorsanız

kül olun savrulun dağlara taşlara

belki hayat yeniden fışkıracaktır o zaman

bu kentin ışıksız varoşlarından

Bir sfenksten söz ediliyor durmadan

yakınmış kahredilmesi', 'Suçlama beni böyle bırakıp gidiyorum diye bağrımı yakan bir yaradır bu ayrılık şimdi Bil ki kanımdadır sevişmelerin yangını öylece girerken ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/suclama-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Coğrafyanın Tetik Boşluğunda', 'bir-cografyanin-tetik-boslugunda-ahmet-telli-cq6g1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/ HECELERKEN ÖMRÜMÜ

Ömrümün hangi hecesine baksam 

Uzadıkça uzayan bozkır yalnızlığı 

Ve duman rengi kasabalar ki sen 

Okunaksız mektuplar da diyebilirsin 

Sesini yitirmiş bu gergin coğrafyaya

Sözlerin eksilip eskidiği bu gri atlas 

Karanlık bir vadiye akıyor, bütün 

Işıkları söndürülürken belleğimin 

Ve sen kurtarabilirsin beni ancak 

Unutmanın bu vahşi saldırısından

Alnımı okşa dağıt alışkanlığımı 

Belki sümbül serinliği olur yeniden

Çocukluğumun elinden tutan 

masalcımdın benim, göğsüne 

yaslanıp gecelerce dinlediğim 

Dinlediğim ve kederini nehrin 

Kızıl kahve toprağına benzettiğim

Bana öyle geldi ki her çiçek 

Ve her kuş su içmek istiyor 

Sesinin gözesinden bu bahar 

Bense bir çiy damlasıyım 

Dudaklarının ışkın kokusunda

Ellerin diyorum, Berçelan Yaylası 

Yahut Munzur tedirginliği şimdi

Esirgedik kendimizi mutluluğun 

Sığ sularından ki aslında uzun 

Bir öyküye benziyor en kısa ömür 

Kayıp yıllarımızın uçurumundaysa 

Ay doğardı ve biz susardık seninle

Susardık, Munzur anlatırdı aşiret 

Töresinden dağ geleneği yarattığını 

Sonra arkadaşlarımız gelir konuk 

Olmazlardı ayrılıklara ki ay o vakit 

Bir göçebe çadırıydı Sümbül Dağı’nda

Zap Suyu ise telkari bir kemer olup 

Sarılırdı Kürt kızlarının beline

Kalbim dedim sonra, aşk da 

Bozkırdaki yangınlar misali 

Yeşerse de arsız otlar yeniden 

Ne dağların eflatun ufku ne de 

Kırlangıçların esmerliği görülür

Ki her ömrün ezberindedir 

Bu hecenin bütün harfleri 

Eprimiş anılar kalıyor geride 

Bir de ceylanların ürkek 

Sıçrayışları tetik boşluğunda

Ve unutuluyor işte bu kadar 

Çok sevilmişse sevilenin adı', '1/ HECELERKEN ÖMRÜMÜ Ömrümün hangi hecesine baksam  Uzadıkça uzayan bozkır yalnızlığı  Ve duman rengi kasabalar ki sen  Okunaksız mektuplar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bir-cografyanin-tetik-boslugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-sota-papaladze-qsiso', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarın önüne kapılmış

İki yapragız biz,

Rüzgar yön değiştirsede

Yön değiştirmeyiz biz.

               Taşkent  1994', 'Rüzgarın önüne kapılmış İki yapragız biz, Rüzgar yön değiştirsede Yön değiştirmeyiz biz.                Taşkent  1994...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Evimin Sahibi', 'yurek-evimin-sahibi-seyyid-efdal-murad-qnxhf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Selam olsun! 

Selam olsun zifiri karanlığımdan 

nur aydınlığıma,, 

bakire gecelerimin sessiz ve yağmalanmamış 

hırçın ama bir o kadar garip çocuğuna 

Selam olsun!!! 

......... 

Doğum kadar masum ama ölüm kadar 

kaçınılmaz olan vuslatıma Selam olsun, 

gönül sahibime AŞK efendime, 

varlığıyla en renkli bahçelerime güneş olan 

yokluğuyla bir hançer yarası açan 

yakan kavuran... 

''''derin yanlızlık denizimin'''' huzur girdabına 

sıcak yuvam tadım tuzuma 

Selam olsun!!.. Selam olsunnn........ 

......................

Neydin sen 

bir düşmü? içimi yakan 

bir gülüşmü? ruhumu candan, canı canandan ayıran 

Neydin sen? 

        bazen berrakmı berrak bir gözyaşı 

        bazen derinmi derin bir gayya 

        bir heyula,, 

        hiç uyanamayan gönlümden 

        aldın savurdun kuşlarımı yürek evimden 

        haydi söyle artıkkkk! 

        Neydin Sen? 

Bir şarkı dilimde yazanı yok söyleyeni yok 

bir ömür yolu dizilmiş notaları 

sıra sıra... 

her nağme hüzün ve ağıt 

her türlü kirden arınmış 

sırat köprüsü misali ince.. hayallerle sarılmış 

sinesi temizlenmiş  bir derviş 

ya da tapınanı kalmamış bir put 

bir şarkı dilimin ucunda 

ve arkanda bıraktığın gencecik bir TABUT!.... 

........ 

karanlık sokaklar,yüksek binalar ve 

acımasız insan yığınları 

ne yana baksam küstah bakışlar 

bende ise.. 

varlığının yıldızlar kadar uzağında 

yetim bıraktığıN düşlerimin med-cezirleri 

    ne yana baksam sensizliğimin sessizliği 

    ve hasretimin ayak sesleri.. 

oysa,,, 

oysa böyle olmayacaktık 

yenilmeyecektik kahpe yüzlere 

yüzümüzden güneşin rengi silinmeyecekti 

deyyusun ''''yüz'' ü ''''bin'' olsa 

biz ''birbirimiz'' olmaktan vazgeçmeyecektik... 

.... 

       Duy beni varlığında yittiğim yokluğum 

       Duy beni üşüyorum yokluğunda.. 

       VARlığıMın ''varlığı'' VARlığıNda gizli 

       Duy beni yürek evimin SAHİBİ!!......... 

                                                 Babam Dursun Cihan''a', 'Selam olsun!  Selam olsun zifiri karanlığımdan  nur aydınlığıma,,  bakire gecelerimin sessiz ve yağmalanmamış  hırçın ama bir o kadar garip ...', ARRAY['Türk Edebiyatı','Şiir','Seyyid Efdal Murad']::text[], 8.5, '{"poet":"Seyyid Efdal Murad","poet_slug":"seyyid-efdal-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yurek-evimin-sahibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Hafta 2', 'gecen-hafta-2-unal-gul-zh9he', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanın yaşamı bir haftaya sığar mı ?

benim sığdı.

sıcacık ellerini tuttum,

dudaklarım dudaklarına değdi, 

gözlerinin içine bakarak sonsuza kadar seveceğimi söyledim.

dahası yüreğini gördüm çırılçıplak.

şairin dediği gibi 

ölsem de gam yemem gayri', 'İnsanın yaşamı bir haftaya sığar mı ? benim sığdı. sıcacık ellerini tuttum, dudaklarım dudaklarına değdi,  gözlerinin içine bakarak sonsuza ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Gül']::text[], 8.5, '{"poet":"Ünal Gül","poet_slug":"unal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gecen-hafta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-sota-papaladze-yc7zk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son mektupla kırmıştın ümitlerimi

Oysa ne ümitlerle beklemiştim son mektubu

Azcık olsada umudum vardı.

Benim bu umutlarımı

Son mektup kırdı.

Demekki ben sana ne hayaller kurarken 

Sen mezarımı kazmışsın

Küçük bir yaprak beyaz sayfaya,

Ve beni gömmüşsün,

Güzel ellerinle.

Ve gömerken beni bu mezara,

Bir fatiha bile okumamışsın.

Şimdi ne umut var ne neşe

Bütün umutlarımın üstünden

Sanki büyük bir fırtına esti,

Benim bu umut ve hayallerimi

Son mektup kesti...

                   Taşkent    1994', 'Son mektupla kırmıştın ümitlerimi Oysa ne ümitlerle beklemiştim son mektubu Azcık olsada umudum vardı. Benim bu umutlarımı Son mektup kırdı....', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-mektup-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni', 'yeni-sota-papaladze-uscto', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün Rus gurubuna geçtik

Biraz sonra yeni sınıfa gireceğiz.

Zili bekliyoruz.

Sekreterin odasında oturmuşum,

Ayak ayak üstüne koymuşum.

Heycanlıyım azda olsa.

Yeni sınıf yeni öğrençiler

Ve yeni öğretmenler.

Yenilerle tanışacağız bugün.

Bu yenileride eskiteceğiz gibi.

                            Taşkent    1993', 'Bugün Rus gurubuna geçtik Biraz sonra yeni sınıfa gireceğiz. Zili bekliyoruz. Sekreterin odasında oturmuşum, Ayak ayak üstüne koymuşum. Heyc...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminliyim Ben..', 'yeminliyim-ben-hakki-yalcin-2yczp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olur bir akşam,

Çıkıp da gelsen

Yorgun, argın bana;

               Bak döndüm desen

Şu dilim tutulsun

Nerdeydin dersem,

Seni beklemeye

       yeminliyim ben...

Ümidim ilk bahar

Akşamlarında

Bir müjde gelecek

Dal uçlarından,

En güzel çiçekler

Avuçlarında

Seni beklemeye

       yeminliyim ben...', 'Ne olur bir akşam, Çıkıp da gelsen Yorgun, argın bana;                Bak döndüm desen Şu dilim tutulsun Nerdeydin dersem, Seni beklemeye   ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeminliyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysun Güven 1', 'aysun-guven-1-sukru-tatli-py3ah', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlıyorum biçare kaderime

Yoksun esmerim girme artık kalbime

Sevmek besbelli yalan bir kelime

Unutmak istiyorum kendi kendime

Nasip olsun mutluluk dert girmesin gönlüne

Gözlerimden akmaz oldu yaşlar

Ümit edip sevmekle geçti o çağlar

Vasiyetim olsun sana mutluluklar

Esiyor ayrılık dolu rüzgarlar 

Neye yarar artık sensiz bomboş yarınlar.', 'Ağlıyorum biçare kaderime Yoksun esmerim girme artık kalbime Sevmek besbelli yalan bir kelime Unutmak istiyorum kendi kendime Nasip olsun mu...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tatlı']::text[], 8.5, '{"poet":"Şükrü Tatlı","poet_slug":"sukru-tatli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aysun-guven-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretime', 'hasretime-ugur-demirkol-c01rb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yoksun ya yanımda

İşte O yüzden uçmak istiyorum denizlere

Bazen derinlere ama çok derinlere

Taa AYÇA AYÇA bakan yosunlara kadar

Bir tutam yosun alayım sarayım göğsüme

Balıklar bile şaşırır sevgime, hasretime...

Bir de bizim gibi hasret çeken yıldızlar var sevgilim gökyüzünde 

Kimi yakın birbirine ışıl ışıl

Kimileri uzaktır sevenlerine 

Ansızın bir gece biter bu bekleyiş bu özlem

Bir gece gökyüzünde bir yıldız kayar

Sessizce kavuşur hasretine sevgisine...', 'Sen yoksun ya yanımda İşte O yüzden uçmak istiyorum denizlere Bazen derinlere ama çok derinlere Taa AYÇA AYÇA bakan yosunlara kadar Bir tuta...', ARRAY['Türk Edebiyatı','Şiir','Uğur Demirkol']::text[], 8.5, '{"poet":"Uğur Demirkol","poet_slug":"ugur-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman', 'duman-enis-batur-euj01', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gümüş düşlerimin içinde dolaştı

geceden geceye

iri ğöğüslü Tatar kadınları

ve köpük köpük bir at,saçakları dövdü yağmur,saç damlarda

bir akordun merdiveninden

aşağı yukarı tırmandı

durdu piyano,', 'Gümüş düşlerimin içinde dolaştı geceden geceye iri ğöğüslü Tatar kadınları ve köpük köpük bir at,saçakları dövdü yağmur,saç damlarda bir ako...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuksuz Bir namlu', 'tutuksuz-bir-namlu-ahmet-ocal-oy4qc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün bir kitap aldım.

Kendime; hediye...

Adı : Anladım...

Bu gün benim doğum günüm;

Ağladım...

Soyadın; gecelerimin sönmez ışığı...

Gözlerim boyuna alışalı

Bütün biraltmışlardan nefret ediyorum..

Benim beş kontürüm var,

Seninse bir cümle hakkın dediğinde

Tek cümlem ''seni seviyorum''...

Ben şair değilim

Ama kendi şiirimi kendim yazıyorum.

''Ben yaman bir aşiretin tek namusuyum'' dedi

''Ben tutuksuz bir mavzer namlusuyum'' dedim.', 'Bu gün bir kitap aldım. Kendime; hediye... Adı : Anladım... Bu gün benim doğum günüm; Ağladım... Soyadın; gecelerimin sönmez ışığı... Gözler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öcal']::text[], 8.5, '{"poet":"Ahmet Öcal","poet_slug":"ahmet-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tutuksuz-bir-namlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenti', 'beklenti-halil-i-brahim-korkmaz-kbq28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerini yatırıp uzaklara,

Bekliyorsan birisini

Boşuna bekleme yüreğim.

Gelecek olan geldide

Seneler önce, gitti

Birdaha dönmiyesiye...', 'Gözlerini yatırıp uzaklara, Bekliyorsan birisini Boşuna bekleme yüreğim. Gelecek olan geldide Seneler önce, gitti Birdaha dönmiyesiye......', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beklenti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Nasılsın?', 'bugun-nasilsin-halil-i-brahim-korkmaz-510de', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün nasılsın 

Hayatımın gerçek öznesi 

Bugün nasılsın ha 

Bugün nasılsın 

Ben yine kederliyken 

Ömrümün anlamı 

Dünyamın tek varlığı 

Bugün nasılsın ha 

Bugün nasılsın 

Ben yine seni düşünürken 

Sigaram hiç bitmesin diyorum 

Dibi görünen şişelere bakıyorum 

Bugün nasılsın ha 

Bugün nasılsın 

Ben yine her yerde seni ararken 

Sen kimi düşünüyorsun 

Ne yapıyor ve kimi bekliyorsun 

Bugün nasılsın ha 

Bugün nasılsın 

Ben yine seni seviyorken', 'Bugün nasılsın  Hayatımın gerçek öznesi  Bugün nasılsın ha  Bugün nasılsın  Ben yine kederliyken  Ömrümün anlamı  Dünyamın tek varlığı  Bugü...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-nasilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hiç !!', 'ben-hic-halil-i-brahim-korkmaz-wwzcl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şarap içer miyim ben hiç, 

Dibinde görmesem seni? 

Hiç sigara içer miyim ben, 

Dumanında gözlerini sevmesem? 

Ben hiç, yok birşey...', 'Şarap içer miyim ben hiç,  Dibinde görmesem seni?  Hiç sigara içer miyim ben,  Dumanında gözlerini sevmesem?  Ben hiç, yok birşey......', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Gecenin Bilmem Kaçını Bir İki Geçerken', 'saat-gecenin-bilmem-kacini-bir-i-ki-gecerken-halil-i-brahim-korkmaz-w9165', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnşallah bugün daha iyisindir DEMET 

Bilgilerimin birinci şiirlerimin ikinci demeti 

İlkgözağrım - hoş sadece değil annemin söylemesi 

Sanki de değil tanıyanların tamamen ortak düşüncesi - 

Nereden çıkıp geldin sen DEMET 

Tam da ayrılmışken NAZ''ımdan 

Sevgilerimin kardeşi 

Aşklarımın hiç yaşamadan ölen öznesi 

Nereden çıkıp da geldin sen 

Saat gecenin bilmem kaçını bir iki geçerken 

Belki belki de daha erken 

Nereden çıkıp da geldin sen aklıma 

Sevdalarımın işlevsiz yüklemi 

Eski aşk! Yeni kardeş 

Nereden çıkıp geldin sen 

Tam da ayrılmışken sevdiğimden', 'İnşallah bugün daha iyisindir DEMET  Bilgilerimin birinci şiirlerimin ikinci demeti  İlkgözağrım - hoş sadece değil annemin söylemesi  Sanki...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saat-gecenin-bilmem-kacini-bir-iki-gecerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-halil-i-brahim-korkmaz-uwpu2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba, adını söyleyemediğim. 

Kendisini asla göremediğim, 

Gözlerini hiç sevemediğim, 

Kalbini hissedemediğim, merhaba. 

Sensiz hergün güneş doğuyor, 

Resmini gözüme çiziyor, 

İsmini kalbime yazıyor, 

Ama, ama seni hiç getirmiyor. 

Sen gelince aklıma; 

Alevlenir duygular, 

Bütün bedenim yanar, 

Yalnız seni arzular. 

Sen ki sıcak güneşten, 

Sen ki güzel geceden, 

Ben ki kalbini kazanan, 

Tek yar, olayım yar.', 'Merhaba, adını söyleyemediğim.  Kendisini asla göremediğim,  Gözlerini hiç sevemediğim,  Kalbini hissedemediğim, merhaba.  Sensiz hergün gün...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merhaba-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hanımefendi', 'hanimefendi-halil-i-brahim-korkmaz-qigx9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hanımefendi 

Teklifime kabul dediğin zaman 

Dünyalar benim olmuştu 

Babaannem sağolsun bu günümde zehir oldu 

Hanımefendi 

Sana söz verdim 

Sigara içmeyeceğim 

Bira ve alkol için 

Hiç bir şey söyleyemeyeceğim 

Hanımefendi 

Sen bu saçmalığa katılmayacaksın 

Deneme tahtası hiç olmayacaksın 

Benim yüzümden asla üzülmeyeceksin 

Hanımefendi 

Unut beni 

Unut dediklerimi 

Asla üzmek istemem seni', 'Hanımefendi  Teklifime kabul dediğin zaman  Dünyalar benim olmuştu  Babaannem sağolsun bu günümde zehir oldu  Hanımefendi  Sana söz verdim  ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hanimefendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimden Seni', 'sevdigimden-seni-halil-i-brahim-korkmaz-wu765', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık korkuyorum gecelerden

Sevdiğim yıldızlardan ve aydan

Gezdiğimiz deniz kenarlarından

Seviyorum seni diyen dudaklardan

Güneşin doğuşunu bunun için bekliyorum

Sensiz kalabalıkta bile yalnız hissediyorum

Seni bulamamın imkansızlığını bildiğim halde

Her şeyde, her yerde seni arıyorum

Her gece sabahlıtorsam meyhanede

Bakıp kalkıyorsam boş sandalyene

Ve kaldırıp kadehimi, içiyorsam şerefine

Bilki sevdiğimden seni hem de ölesiye', 'Artık korkuyorum gecelerden Sevdiğim yıldızlardan ve aydan Gezdiğimiz deniz kenarlarından Seviyorum seni diyen dudaklardan Güneşin doğuşunu ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigimden-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra Defteri', 'hatira-defteri-halil-i-brahim-korkmaz-7yi6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karıştırırken tozlu rafları

Bir defter gördüm

Yaprakları sapsarı

İçinde gül yaprakları

Onu yerinden aldım

Kaldırdım kapağını

O defter ile

Mazime daldım

Aklımdan geçiyordu bir bir

Çocukluk aşkları

Okul arkadaşları

Gençlik yılları

Ve birden kapı çaldı

Anılar silindi

Seni beklerken

Nihayet O çıkageldi

...', 'Karıştırırken tozlu rafları Bir defter gördüm Yaprakları sapsarı İçinde gül yaprakları Onu yerinden aldım Kaldırdım kapağını O defter ile Ma...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatira-defteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Zamanı', 'sevmek-zamani-halil-i-brahim-korkmaz-9ferf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykırmak zamanı susuyorum

Kahreden bülbül çığlıklarıyla

Öznesi nesnesi olmayan cümlelerle

Haykırmak zamanı susuyorum

Gülmek zamanı ağlıyorum

Adile NAŞİT kahkahalarıyla

Kuralsız uyaksız yakarışlarla

Gülmek zamanı ağlıyorum

Çalışmak zamanı uyuyorum

Tembel bir kedi edasıyla

Rüyasız konuşmasız yatataklarla

Çalışmak zamanı uyuyorum

Sevmek zamanı seviyorum

Ferhat''ın dağı, Mecnun''un gözleriyle

Kendi yüreğimin ateşiyle

Sevmek zamanı yanıyorum', 'Haykırmak zamanı susuyorum Kahreden bülbül çığlıklarıyla Öznesi nesnesi olmayan cümlelerle Haykırmak zamanı susuyorum Gülmek zamanı ağlıyoru...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmek-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Öğretmenim', 'sevgili-ogretmenim-talip-apaydin-9ni0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SELAHATTİN ÖĞRETMEN

Kırık köyünün büyük beyaz okuluna,

Pencerelerden bir baktım,

Selahattin öğretmenin sesi geliyordu.

Öğrenciler taş kesilmiş dinliyordu.

Neler diyordu, o duvarlar biliyordu.

Kımıldamadan öyle kaldım,

Okula güneş vuruyordu.

O, karşımda dinlendiren aydınlık

Gönlüme vuruyordu bir parçası

Düşüncemi tuttum, açıklara saldım.

Bir at koşar gibi çayırlarda

Selahattin öğretmen koşuyordu.

Köyün kara toprak evleri,

İlerde her şeyden habersiz

Kendi hayatını yaşıyordu.', 'SELAHATTİN ÖĞRETMEN Kırık köyünün büyük beyaz okuluna, Pencerelerden bir baktım, Selahattin öğretmenin sesi geliyordu. Öğrenciler taş kesilm...', ARRAY['Türk Edebiyatı','Şiir','Talip Apaydın']::text[], 8.5, '{"poet":"Talip Apaydın","poet_slug":"talip-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgili-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyor musun Sahiden', 'gidiyor-musun-sahiden-hakan-gursu-sr71c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyormusun sahiden..?

Ya ben ne yaparım akşamüstleri..

Seni tanımadan,

Ezilmişliğim vardı ya hani..

İsyanlarım...

Omuz kaldırışlarım...

Kendime güvenim vardı ya,

Onların arasında boğulasım tutar,

Çıldırasım gelir ha..

Gidiyormusun sahiden..?

Ya ben na yaparım akşamüstleri

Oysa,

İlk kez sevesim tutmuştu,

Mutluluğu gözle görünür yapmıştım,

Gözlerimle okşamıştım usul usul,

Okşamıştım acımalı,

Yüreğime saplanmış acıları koparabilirmisin..?

Alabilirmisin bakışlarını gözlerimden...

Gidiyormusun sahiden..?

Ya ben na yaparım akşamüstleri', 'Gidiyormusun sahiden..? Ya ben ne yaparım akşamüstleri.. Seni tanımadan, Ezilmişliğim vardı ya hani.. İsyanlarım... Omuz kaldırışlarım... Ke...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidiyor-musun-sahiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Vardı', 'bir-kiz-vardi-feridun-demir-r76qk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kız vardı

Kendi söylediği şarkılara ağlayan

Ağlaması kesilirdi

Demli bir çay içtiğinde benim evimde

O kesince ağlamasını 

bu kez ben başlardım ağlamaya

Dudaklarında kalan çay damlalarını içebilirim umuduyla

Fazla kalmadı ama

dudaklarının tadı dudaklarımda

Ben de yeni bir sevgili buldum

Dudaklarında şekerli çay damlaları bulunan', 'Bir kız vardı Kendi söylediği şarkılara ağlayan Ağlaması kesilirdi Demli bir çay içtiğinde benim evimde O kesince ağlamasını  bu kez ben baş...', ARRAY['Türk Edebiyatı','Şiir','Feridun Demir']::text[], 8.5, '{"poet":"Feridun Demir","poet_slug":"feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-kiz-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akvaryumumdaki Balıkları İzliyorum', 'akvaryumumdaki-baliklari-i-zliyorum-feridun-demir-blkw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akvaryumumdaki balıkları izliyorum sensiz bu günümde

Sen gittiğin gün aldım onları

Seni unuttursunlar diye bana

Ama kahretsin

Sana benziyor bu kahrolası lepistesler

Seni hatırlatıyorlar bana iyice

unutmak isterken seni ölesiye

Unutamıyorum seni bir türlü 

Ve işte yiyorum sonunda nefretimden seni

Tadın çok iğrenç ama

Keşke diyorum;

Keşke hamsiye benzeyen bir sevgiliye aşık olsaydım', 'Akvaryumumdaki balıkları izliyorum sensiz bu günümde Sen gittiğin gün aldım onları Seni unuttursunlar diye bana Ama kahretsin Sana benziyor ...', ARRAY['Türk Edebiyatı','Şiir','Feridun Demir']::text[], 8.5, '{"poet":"Feridun Demir","poet_slug":"feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/akvaryumumdaki-baliklari-izliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Bir Simit Var', 'elimde-bir-simit-var-feridun-demir-j1prc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimde bir simit var

Yarısı senin; yarısı benim

Ve bir de kalbim var; tamamen senin

Ve sen simidini yerken konuşuyorsun

''Ben aşkın en çok susamını severim''

Ve sonra susuyorsun ve gidiyorsun

Yeni sevgililer buluyorum sonra

Ama onların hiçbirine aşık olmuyorum

Çünkü onlar nefret ediyorlar simitlerin susamından', 'Elimde bir simit var Yarısı senin; yarısı benim Ve bir de kalbim var; tamamen senin Ve sen simidini yerken konuşuyorsun ''Ben aşkın en çok su...', ARRAY['Türk Edebiyatı','Şiir','Feridun Demir']::text[], 8.5, '{"poet":"Feridun Demir","poet_slug":"feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/elimde-bir-simit-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürmesi Gerekmişti Sevdiği Kadını', 'oldurmesi-gerekmisti-sevdigi-kadini-feridun-demir-ocwg3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öldürmesi gerekmişti sevdiği kadını

Ve özür diledi sevdiği kadını seven kalbinden

sevdiği kadını öldürdüğü için elleri

''Özür dilerim sevgili kalbim

Sevdiğin kadını öldürmem gereti

Çünkü yağmur yağıyordu

ve sevdiğin o büyük gövdeli kadının hayatı boyunca hiç şemsiyesi olmamıştı

Ve ıslanmamalıydım ben yağmurda

Bilirsin nefret ederim 

yağmurdan ve yağmurda ıslanmaktan', 'Öldürmesi gerekmişti sevdiği kadını Ve özür diledi sevdiği kadını seven kalbinden sevdiği kadını öldürdüğü için elleri ''Özür dilerim sevgili...', ARRAY['Türk Edebiyatı','Şiir','Feridun Demir']::text[], 8.5, '{"poet":"Feridun Demir","poet_slug":"feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oldurmesi-gerekmisti-sevdigi-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Yükü', 'kalbimin-yuku-zulkuf-cengiz-qjbrq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyormusun hiç bir şey degişmedi

Halen ilk günkü gibi 

Halen seni taparcasına sevip

Halen hasretinle yanıyorum 

Ve gözlerimin ucuna gelen gözlerine 

Halen bakamıyorum 

Yine sesini duymak ellerini tutmak 

Ve sıcak nefesini tenimde hissederek seni öpmek 

Halen adını her duydugumda 

Kalbimdeki sevinç

Gözlerimdeki ışıltı 

Ve degişmeyen herşey gibi 

Kalbimin yükü olan sonsuz sevgi

Dünyadan daha küçük olan kalbime dünya ya sıgmayacak kadar sevgi besliyorsam sana karşı sence bu ne demektir', 'Biliyormusun hiç bir şey degişmedi Halen ilk günkü gibi  Halen seni taparcasına sevip Halen hasretinle yanıyorum  Ve gözlerimin ucuna gelen ...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kalbimin-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Haketmiyorum', 'seni-haketmiyorum-hakan-gursu-xbu58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlahi aşk

Yanlızca seni seviyorum demek mi?

Her nefesim bu ama,

Seni haketmiyorum.

Kandan bir vazoda,

Yüreğimi sunmalıydım

Bir an saçlarından eksik etmeden güneşi

Yanarak,

Alev alev karşında durmalıydım

Seviyorum...demekle,

Seni haketmiyorum.

Bir örtü,

Yada

Bir kanat olmalıydım üstünde

Islanmayasın diye yağmurlarda yürürken,

Bende ki acılar neki,sende acı oldukça

Tüm acılarını toplamalıydım bende

Dudakların olmalıydım..

Tükürürken...

Anladım..

Seni haketmiyorum.', 'İlahi aşk Yanlızca seni seviyorum demek mi? Her nefesim bu ama, Seni haketmiyorum. Kandan bir vazoda, Yüreğimi sunmalıydım Bir an saçlarında...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-haketmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustur Beni', 'sustur-beni-bulut-yankutan-w0e38', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sustur beni

Dilimde keskin bir bıçak gibi gezin

Benki şiirlere, benki ölümsüzlüğe inanırım bilirsin

Sustur beni, kaldır beni, öp beni dudağımdan

Bir gün vuracaklar beni biliyorum

Tam sana sarılmışken tam sırtımdan

Gecenin en karanlın yerinde

Yedi el silah sesi

Döne döne girecek yedi kurşun

Dudaklarımdan

                        dudaklarına

Yedi Damla Kan Dökülecek...', 'Sustur beni Dilimde keskin bir bıçak gibi gezin Benki şiirlere, benki ölümsüzlüğe inanırım bilirsin Sustur beni, kaldır beni, öp beni dudağı...', ARRAY['Türk Edebiyatı','Şiir','Bulut Yankutan']::text[], 8.5, '{"poet":"Bulut Yankutan","poet_slug":"bulut-yankutan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sustur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim Seni', 'bekledim-seni-hakan-gursu-igwqt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her an,

Çıplak tepelere bakarak,

Serin

Soğuk

Bulanık

Sularda

Bekledim seni

Bekledim seni

Soluk

Bezgin

Yüzler arasında

Aradım seni

Bir güneş örneği', 'Her an, Çıplak tepelere bakarak, Serin Soğuk Bulanık Sularda Bekledim seni Bekledim seni Soluk Bezgin Yüzler arasında Aradım seni Bir güneş ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekledim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-hakan-gursu-asmyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sıkımlık limon ekşiliği

Avuçlar dolusu şekeri

Mayhoşladı yüreğimde

Bir yabansı karmaşadaki beynim

Duygularım,

Curcunada

Hayallerim

Hay huyda

Ölümler var düşlerimde

Bir zamanlar güneşe nanik yapan gözler

Şimdi,,

Güneş gözlüğü ile bakıyor ona..

Umutlarım kör

Umutlarım sağır

Pişmanlığın yoldurduğu

Bir tutam 

Saç kaldı ellerimde.....', 'Bir sıkımlık limon ekşiliği Avuçlar dolusu şekeri Mayhoşladı yüreğimde Bir yabansı karmaşadaki beynim Duygularım, Curcunada Hayallerim Hay h...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umutlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığım Şehir ve Anneme', 'yasadigim-sehir-ve-anneme-sota-papaladze-ix9e9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençliğimi verdiğim şehre

Bir iki şey söylemek isterim

Biraz acı, biraz tatlı.

Ömrümün baharını geçirdim sende

İlk doğdum senin rutubetli havandan soludum

Susadım senin serin sularından içtim.

Ve karadenizin küçük kasabası

Senin yağmurlarını anlatmaya gerek varmı

Artık herkes biliyor seni.

Azmı ıslanmıştım damlalarından kaçarken

Yakalardınya ansızın şemsiyesiz ceketsiz

Güneşli bir günde çıkardın aniden

Bulutsuz ve esintisiz.

Ve denizim Kara denizim

Beni iyi bir yüzüçü usta bir balıkçı yapan denizim

Senden azmı balık yedim azmi eylendim.

Bedenimi ilk kez senin sularında ıslattım,

Senin sahillerinde güneşlendim

İlk boğulma tehlikesini yine sende atlattım.

İyide kürek çekerim bilirsin

Azmı gezindim çalkantılı sularında

Ellerim azmı nasırlandı

Elbiselerim azmı ıslandı.

Dün albüme baktım,

İlk yakaladığım balığı görünce nasılda sevinmişim

İşte o günden sonra annem söylüyor

Ben hergün denize inmişim.

Ben yanlız denize balığa değil

Kuşlara da meraklıyım

Kışın yaban tavuğunun peşinden azmı koştum

Sokaklarda floryaların peşinden,

Ve onları kaç yıl besledim.

Hala unutamıyorum kırmızı kafalı şirin sakamı

Dert ortağım benim ne güzel öterdin

Seninle dertleşirdim bilirsin.

Ömrümü verdiğim şehirde birde atmacalar var

Ağustoz ayı geldimi cıkardık dağa.

Ah Fındıklı ah

Dört mevsimin ayrı bir zevkti

Meyve zamanı olurya

Kirazı armutu inciri

Çıkardık dalında yerdik,

Ama coğunlukla tenbeldik

Üşenip çıkmazdık ağaca

Çürürdü güzelim meyveler dalda.

Evimin önünden sahil yolu gecerdi

Alışmıştım ninni gibi gelirdi gecen arabaların sesleri.

Azmı tam yirmi yıl dinledim.

İlk arkadaşım bu şehirden benim

İlk dostum ilk düşmanımda.

İlk aşkım,

İlk göz ağrım,

İlk göz ağrımda buradan.

Neleri sevmiştim ben bu kasabada

Neleri neleri.

Daha sizlere yazamadığım bilseniz neleri.

Annem babam ve kardeşlerim...

Annem azmı çalıştı çay bahçelerşnde, kardeşim karnındayken.

Çok ama çok cesaretliydi

Bilseniz kuş kadardı  yüreği.

Bir bilseniz ah bir bılseniz

Yorgunluktan kıvranırdı geceleri.

Birde Babamı bilseniz

Yirmibeş yılını verdi mesleğine

Yirmibeş yıl pazarsız

Hergün sabah yediotuz akşam dörtotuz.

Bir of bile çekmedi bu yirmibeş yılda

İşten sonra dururmuydu sanki 

Kendine yapacak birşey bulurdu.

Kardeşlerimi anlatmaya gerek yok

Hepsi bir çiçek

Biri pamuk,biri tonton, biri yumurcak

İnanın gurbette bu satırları yazarken

Gözlerim yaşardı, ağlamaklı oldum

Gözlerimden süzülen damlacıklar

Annem kelimesinin üstüne düştü

Bakın o bile biliyor annelerin kıymetini.

Annem annem!

Yanındayken seni,

Daha çok öpüp koklayamadığım için,

şimdi kahroluyorum.

Ama beni affet

Bir bilsen seni ne çok seviyorum.

Şimdi bunlar, gözümün önünden bir filim gibi geçiyor.

Sanki dün gibi yaşadıklarım.

Daha iki gün önce top oynamış gibi

Denizinde yüzmüş gibi

Dağlarında gezmiş gibiyim.

Ama yaşadığım o güzel günlerin

Sayfalarının çoktan kapandığını biliyorum.

İnanın o yeri ve zamanları

Çokmu çok özlüyorum... 

                  Taşkent  30.09.1993', 'Gençliğimi verdiğim şehre Bir iki şey söylemek isterim Biraz acı, biraz tatlı. Ömrümün baharını geçirdim sende İlk doğdum senin rutubetli ha...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/yasadigim-sehir-ve-anneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severmisin', 'severmisin-hakan-oymak-6vb4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eğer bir gün gelir kavuşamazsak 

bana eskisi gibi merhaba dermisin 

şayet ayırırsa bizi kara toprak 

mezarıma gelir dua edermisin 

aşkından Mecnun olup yollara düssem

bir buketle teselli edermisin

seni sevdiğimi söylesem

yüzüme bakıp tebessüm edermisin

beni sevip sevmediğini sorsam?

gülerek yürekten (evet) dermisin?', 'eğer bir gün gelir kavuşamazsak  bana eskisi gibi merhaba dermisin  şayet ayırırsa bizi kara toprak  mezarıma gelir dua edermisin  aşkından ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Oymak']::text[], 8.5, '{"poet":"Hakan Oymak","poet_slug":"hakan-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/severmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-baris-kahvecioglu-xsbxe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen içimdeki sevda tomurcukları,

Yağmurdan sonra açan güneşsin,

Koparmaya kıyamadığım bir gül,

Bakamaya doyamadığım sevgilim,

Bir türlü seni seviyorum diyemediğim,

Ve bir tanemsin,

Uğrunda herşeyi feda edeceğimsin.', 'Sen içimdeki sevda tomurcukları, Yağmurdan sonra açan güneşsin, Koparmaya kıyamadığım bir gül, Bakamaya doyamadığım sevgilim, Bir türlü seni...', ARRAY['Türk Edebiyatı','Şiir','Barış Kahvecioğlu']::text[], 8.5, '{"poet":"Barış Kahvecioğlu","poet_slug":"baris-kahvecioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım Seni', 'unutmadim-seni-baris-kahvecioglu-3liph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün akşam yine esti derinden,

Aklıma geldi eski günlerden,

Seninle birlikte elele iken,

O gün geldi aklıma unutamadım,

Aklıma geldi ilk tanıştığımız,

Hani yağmurdan kaçarken ıslandığımız,

Seninle o anı yaşadığımız,

O gün aklımageldi unutamadım.', 'Dün akşam yine esti derinden, Aklıma geldi eski günlerden, Seninle birlikte elele iken, O gün geldi aklıma unutamadım, Aklıma geldi ilk tanı...', ARRAY['Türk Edebiyatı','Şiir','Barış Kahvecioğlu']::text[], 8.5, '{"poet":"Barış Kahvecioğlu","poet_slug":"baris-kahvecioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutmadim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hep Sevecektim', 'seni-hep-sevecektim-i-lhan-simsek-r2xap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dünya kurdum..

Ben, sen ve onlar

Öyle bir dünya ki

Bir sen tanıdık

Onlarsa; yabancılar.

Tüm nehirlerin kaynağı ben oldum,

Tüm denizlerin yerine seni koydum,

Dönüp sana ulaşayım diye.

Bulut oldum, seni yağdırdım,

Yağmurum;

Tekrar ben olasın diye.

Sonra güzelim;

Ben seni istedim,

Se beni özledin,

Ah güzelim ah!

Sen beni özlemeseydin de

Ben seni hep sevecektim.', 'Bir dünya kurdum.. Ben, sen ve onlar Öyle bir dünya ki Bir sen tanıdık Onlarsa; yabancılar. Tüm nehirlerin kaynağı ben oldum, Tüm denizlerin...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şimşek']::text[], 8.5, '{"poet":"İlhan Şimşek","poet_slug":"i-lhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-hep-sevecektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-cem-ocal-4c33i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana yazılacak o kadar çok şey var ki canım.

Sen ama, o kadar uzaksın ki benden ,

Mektup bile yazılamayacak kadar uzak.

Ve çok şeyi olmasa da insanın,

Bir sevgiliye yazılamayan mektuplar

En büyük eksiklik olacaktır her zaman.

Anlatamadığım güzellikler kalır dudaklarımda,

Dudaklarının anlatamadığım güzelliği kalır.

Hiçbirşeyim olmaz çok şeyim olsa da.

Yazsam uzaksın, anlatsam dinlemezsin.

Bıraksan beni gitsem veya ben seni bırakabilsem.

Sen beni sevsen keşke, ben seni sevmesem…

Ekim 99', 'Sana yazılacak o kadar çok şey var ki canım. Sen ama, o kadar uzaksın ki benden , Mektup bile yazılamayacak kadar uzak. Ve çok şeyi olmasa d...', ARRAY['Türk Edebiyatı','Şiir','Cem Öcal']::text[], 8.5, '{"poet":"Cem Öcal","poet_slug":"cem-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/serzenis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun?', 'biliyor-musun-halil-i-brahim-korkmaz-6vbuw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve sen sevgili sevgili

Beni düşünmediğini biliyorum

Rahat bir şekilde uyuduğunu

hatta rüyanda bile beni görmediğini

Adını kazıdığım ağaç gibi biliyorum

İsminin sadece ağaçta durduğunu

Sana sorular soracağım bu gece

Ey sevgili sevgili

Seninleyken yüzdoksanlara vuran nabzımın

şimdi kaç attığını

Sevgili yanındayken söylenen sözlerin

Ne gibi bir etki bıraktığını

Ve artık eski sevgili olduğunu

Biliyor musun?', 'Ve sen sevgili sevgili Beni düşünmediğini biliyorum Rahat bir şekilde uyuduğunu hatta rüyanda bile beni görmediğini Adını kazıdığım ağaç gib...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biliyor-musun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basılır Birgün', 'basilir-birgun-halil-i-brahim-korkmaz-l6y3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir yazıyorum

Orhan Veli gibi

Basılacağını ümit etmiyorum

Tıpkı Nazım Hoca gibi

Şiir yazıyorum

Gece yarıları

Sabah ertesileri

Ders çıkışları

Şiir yazıyorum

Basılmıyacağını bilerek

Kafiye, kural tanımıyorum

Nasılsa kimse önemsemeyecek

Şiir yazıyorum

Basılır birgün belki

Bir gece ansızın

Basılan yüreğim gibi', 'Şiir yazıyorum Orhan Veli gibi Basılacağını ümit etmiyorum Tıpkı Nazım Hoca gibi Şiir yazıyorum Gece yarıları Sabah ertesileri Ders çıkışlar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/basilir-birgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-halil-i-brahim-korkmaz-c1ewi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Para kalmadı usta

Son sigaramızı çekiyoruz

Daha dört günüm var usta

İkibuçuk milyon cebimdeki para

Son dalımızında usta

Sonu geldi söner

Artık yatmak gerek usta

Saat bire çeyrek var', 'Para kalmadı usta Son sigaramızı çekiyoruz Daha dört günüm var usta İkibuçuk milyon cebimdeki para Son dalımızında usta Sonu geldi söner Art...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Rüyalarımı Ver', 'bana-ruyalarimi-ver-halil-i-brahim-korkmaz-tgwpk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektuplarım, resimlerim sende kalsın

Bana seninle olan anılarımı ver

Senin için olan şiirlerim senin olsun

Sende kalan duygularımı ver

Yediğimiz, içtiğimiz sende kalsın

Bana senin için olan günahlarımı ver

Ellerinle dokunduğun, gözlerinle gördüğün

Benim olan, sende kalan

Herşeyim senin olsun

Başka şey istemem hepsi sende kalsın

Sadece bana rüyalarımı ver yeter.', 'Mektuplarım, resimlerim sende kalsın Bana seninle olan anılarımı ver Senin için olan şiirlerim senin olsun Sende kalan duygularımı ver Yediğ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Korkmaz']::text[], 8.5, '{"poet":"Halil İbrahim Korkmaz","poet_slug":"halil-i-brahim-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bana-ruyalarimi-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çok İsterdim', 'ne-cok-i-sterdim-ekim-can-vviz9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben senin ellerini hiç tutmadım,

Saçlarını okşamadım,

Gözlerine bakamdım,

Dizlerinde yatmadım,

Oysa ne çok isterdim;

Ellerini tutabilmeyi,

Saçlarını okşayabilmeyi,

Gözlerinin içinde kaybolmayı,

Dizlerinde yatmayı.

Bizim deli hoyrat sevişmelerimiz olmadı.

Tenini hissetmedim,

Kokunu almadım,

Zamanı paylaşmadım

Aşkını doyasıya yaşamadım,yaşatamadım.

Oysa ne çok isterdim;

Deli hoyrat sevişmeleri,

Tenimde tenini,

İçimde kokunu,

Zamanı paylaşmayı,

Aşkı yaşamayı,yaşatmayı,

Ne yazık ki olmadı.

(27/9/2000)

Bu şiir Biricik aşkım Nazlı için yazılmıştır.O şimdi çokkkk uzaklarda.', 'Ben senin ellerini hiç tutmadım, Saçlarını okşamadım, Gözlerine bakamdım, Dizlerinde yatmadım, Oysa ne çok isterdim; Ellerini tutabilmeyi, S...', ARRAY['Türk Edebiyatı','Şiir','Ekim Can']::text[], 8.5, '{"poet":"Ekim Can","poet_slug":"ekim-can","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-cok-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Ambarı', 'hayal-ambari-mustafa-cetin-2rln7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilim, gözyaşlarım düştü, düştü toprağa

Bir ikon oldu sanki, Bakiremin hüzniyle

Rüyalarımın resmi, ruhumun aynasında

Binbir gece hislerin titreşen öyküsiyle

İşte bunlar hayalim, bir cevap versen bana

Gülümsesen kalbime insan ışıltısiyle

Bir bakışına feda ederdim baharları

Yıldızları serperdim saçına her teliyle

Lacivert semaları biçerdim kametine

Belki üşürsün aman, bestemin nefesiyle

Hilali küpe diye çalardım gökyüzünden

Samanyolu toplardım, gülüyle çiçeğiyle

Ve şiirler döşerdim, ayağının altına

Yani hece taşları, Yunusumun diliyle

                           ( 17 Kasım 2000 )', 'Sevgilim, gözyaşlarım düştü, düştü toprağa Bir ikon oldu sanki, Bakiremin hüzniyle Rüyalarımın resmi, ruhumun aynasında Binbir gece hislerin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çetin']::text[], 8.5, '{"poet":"Mustafa Çetin","poet_slug":"mustafa-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayal-ambari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek (Baran''a)', 'melek-baran-a-turgut-erdogan-ybpb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MELEK  (Baran''a)

Yağmurla geldin,

Yağmurla gittin,

Günahsızdın	

Çünkü melektin.

SiiR_AdAM Alanya, Ekim 2000', 'MELEK  (Baran''a) Yağmurla geldin, Yağmurla gittin, Günahsızdın	 Çünkü melektin. SiiR_AdAM Alanya, Ekim 2000...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/melek-baran-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyordum', 'bilmiyordum-turgut-erdogan-gom0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİLMİYORDUM

Yaşadıkça,

Sensizlik yazıyordum.

Ömrüm sensizlikle bitecek!

Anlamıyordum...

Yalnızlıklarımda,

Yalnızlıklarımı sayıyordum avuç avuç,

Tutturamıyordum bir türlü,

Ağlıyordum...

Sensizliklerimde,

Acı dolu türküler yazıyordum,

-ki türküleri yakan namerttir-

Oysa,

Mum yakılır karanlıklarda,

Biliyordum...

Yüreğimi kanatıyordum.

Hasret akşamlarında bulutlara

Mektuplar yazıyordum.

Oysa,

Sana ulaşmadan,

Kirpiklerimden yağıyormuş,

Bilmiyordum...

SiiR_AdAM  Alanya Kasım 2000', 'BİLMİYORDUM Yaşadıkça, Sensizlik yazıyordum. Ömrüm sensizlikle bitecek! Anlamıyordum... Yalnızlıklarımda, Yalnızlıklarımı sayıyordum avuç av...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bilmiyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İster İdim Allah''ı', 'i-ster-i-dim-allah-i-yunus-emre-ilcit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İster idim Allah''ı buldum ise ne oldu

Ağlar idim dün ü gün güldüm ise ne oldu

Erenler meydanında yuvarlanır top idim

Padişah çevganında kaldım ise ne oldu

Erenler sohbetinde deste kızıl gül idim

Açıldım ele geldim soldum ise ne oldu

Alimler ulemalar medresede buldusa

Ben harabat içinde buldum ise ne oldu

İşit Yunus''u işit yine deli oldu hoş

Erenler manisine daldım ise ne oldu

(İstanbul,22.11.2000)', 'İster idim Allah''ı buldum ise ne oldu Ağlar idim dün ü gün güldüm ise ne oldu Erenler meydanında yuvarlanır top idim Padişah çevganında kald...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ister-idim-allah-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-erol-guler-elyiq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok güzelsin benim ey sevdiceğim

Bu dünyada eşin yoktur sanırım

O kara gözlerin, siyah saçların

Koklayıpta sarmaya kıyamadığım...

Seni gördüğüm an içim açıldı

Sanki bu dünyaya yeniden geldim

Gözlerim her yerde seni arıyor

Sana bakmalara doyamadığım...

O güzelliğin yakıyor beni

Yandım da uğruna kül oldum senin

Seni bir an görmesem yaşayamam ben

Sensiz hiç bir zaman olamadığım...

Güzelliğin sanki büyüledi beni

Gözlerim bir başka görüyor seni

Öl desen uğruna ölürüm hani

Aşkım,bir tanem, güzel meleğim.

(İstanbul, 22.11.2000)', 'Çok güzelsin benim ey sevdiceğim Bu dünyada eşin yoktur sanırım O kara gözlerin, siyah saçların Koklayıpta sarmaya kıyamadığım... Seni gördü...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgiliye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VEDASIZ AYRILIK', 'vedasiz-ayrilik-ayhan-aktas-sf0ks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sayfa kapandı bak yıllar sonra

Neden anlamadık, nasıl okuduk ?

Ağlıyorum şimdi geçen yıllara

Neydik bir zamanlar şimdi ne olduk

Bir vede etmeden , helalleşmeden

Dönüp bir kerecik bile bakmadan

Yaşanan güzel anılara saygı duymadan

Sildik birbirimizi hatıralardan

Benim için sen yoksun artık

Her gün kapımdan geçsende

Yaşarken ölmeyi iyi bilirim

Sende anlayacaksın geç farketsende', 'Bir sayfa kapandı bak yıllar sonra Neden anlamadık, nasıl okuduk ? Ağlıyorum şimdi geçen yıllara Neydik bir zamanlar şimdi ne olduk Bir vede...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Aktaş']::text[], 8.5, '{"poet":"Ayhan Aktaş","poet_slug":"ayhan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vedasiz-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamdaki Sevgili', 'ruyamdaki-sevgili-erol-guler-wxjs7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yumdum gözlerimi sen çıktın karşıma

Kimdin, neydin, bilmiyorum, bilemedim.

Bir peri mi, bir melek mi desem sana ben

Anlat, kaçma benden güzel sevgilim.

Gözlerime bakıp güldün dün gece

Konuşmak istedin benle gizlice

Çaldın kalbimi, aşık ettin beni kendine

Ararım sevgilim seni her yerde

Rüyamda göründün, birden yok oldun

Ben de gerçek diye sana tutuldum

Gözlerini gördüğüm gibi vuruldum.

Benliğimi alt üst ettin sen benim.

(İstanbul, 22.11.2000)', 'Yumdum gözlerimi sen çıktın karşıma Kimdin, neydin, bilmiyorum, bilemedim. Bir peri mi, bir melek mi desem sana ben Anlat, kaçma benden güze...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruyamdaki-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitlerim Vardı', 'umitlerim-vardi-erol-guler-k5vxd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ümitlerim vardı, taze taze

Gerçekleşmesini çok istediğim.

Bu ümitlerle yaşadım hep

Gezdim, güldüm ve eğlendim.

Ümitlerim vardı, ışık ışık

Ve, o ışığa bakınca kamaşan gözlerim

Doldu, doldu boşaldı.

Gerçekleşmeyecekmiş gibi görünen

Ümitlerim için.

Ümitlerim vardı, yıldız yıldız

Ulaşılamayacak gibi görünen

Bazen parlayan, bazen sönen

Ümitlerim vardı.

Ümitlerim vardı, parlak parlak

Geleceğimi aydınlatan.

Bu aydınlık ve ışık ile

Bana kendimi bulduran.

(İstanbul, 22.11.2000)', 'Ümitlerim vardı, taze taze Gerçekleşmesini çok istediğim. Bu ümitlerle yaşadım hep Gezdim, güldüm ve eğlendim. Ümitlerim vardı, ışık ışık Ve...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umitlerim-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum ki', 'bilmiyorum-ki-erol-guler-617pk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resmine bakıyorum doyasıya

Elimden ne gelir, bilmiyorum ki.

Hayalinle avunmak, tek çarem benim

Senden başkasını, sevmiyorum ki.

İstemem sensiz, dünyada mal, mülk

Yanımda bir tek sen olsan yeter.

Sen olmadan bir gün yaşayamam ben,

Aklımdan hiç bir zaman çıkmıyorsun ki.

Sensiz inan zaman çok zor geçiyor,

Her gün kahrolarak ölüyorum ben.

O günler benim için büyük ızdırap,

Onları yaşamaktan saymıyorum ki.

Derdimin dermanı herşeyimsin sen,

Olamam sensiz sevdiceğim ben.

Bana gelmen, benim olman büyük emelim.

Ne zaman gerçekleşir bunlar.bilmiyorum ki...

(İstanbul, 22.11.2000)', 'Resmine bakıyorum doyasıya Elimden ne gelir, bilmiyorum ki. Hayalinle avunmak, tek çarem benim Senden başkasını, sevmiyorum ki. İstemem sens...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilmiyorum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözlü Kız', 'ela-gozlu-kiz-erol-guler-uk60n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümü kaptırdım bir güzel kıza,

Kaşları karadır, gözleri ela.

Kendisi cilveli, nazlıdır ama,

İnsanı bir kere süzüşü yeter.

İnce kaşları yay, kirpikleri oktur,

Bu dünyada ondan güzeli yoktur.

Her şeyin güzeli onda pek çoktur.

Tenhada verdiği bir buse yeter.

Yan bakışı neler neler anlatır.

Biraz görünmezse hemen aratır.

Söz verir, gelmez hep de aldatır.

Arada sırada gelişi yeter.

Dağınık saçları gül kokuludur,

Güzeldir, incedir ve edalıdır.

Her zaman şendir, çok neşelidir,

Uzaktan bir kere gülüşü yeter.

Sevdiğim kızı gördüğüm zaman,

Yüreğim oynar yerinden bir an.

Tenhada yalnız kaldığımız an,

Seni seviyorum, değişi yeter.

(İstanbul, 22.11.2000)', 'Gönlümü kaptırdım bir güzel kıza, Kaşları karadır, gözleri ela. Kendisi cilveli, nazlıdır ama, İnsanı bir kere süzüşü yeter. İnce kaşları ya...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ela-gozlu-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Dünya', 'kimsesiz-dunya-faik-bilek-wa2f8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dogrudan yana oldum ömrüm boyunca,

Haklıyı haksızı anlattım durdum.

Ne açlar gördüm hain oldu doyunca,

Sonunda kimsesiz bir dünya kurdum..', 'Dogrudan yana oldum ömrüm boyunca, Haklıyı haksızı anlattım durdum. Ne açlar gördüm hain oldu doyunca, Sonunda kimsesiz bir dünya kurdum.....', ARRAY['Türk Edebiyatı','Şiir','Faik Bilek']::text[], 8.5, '{"poet":"Faik Bilek","poet_slug":"faik-bilek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kimsesiz-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL', 'yol-fatih-gundogan-ilqyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın acısını çekelim dedik beraber,

Yola çıktık azıksız, dünyadan bihaber...', 'Hayatın acısını çekelim dedik beraber, Yola çıktık azıksız, dünyadan bihaber......', ARRAY['Türk Edebiyatı','Şiir','Fatih Gündoğan']::text[], 8.5, '{"poet":"Fatih Gündoğan","poet_slug":"fatih-gundogan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yol-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin Çağlayanların Hıçkırmasıydı', 'gidisin-caglayanlarin-hickirmasiydi-muslim-celik-oxwp9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgicil gözlerine buğular çökmüş

yağmurun salkımı dizilmiş kirpiklerine 

gözlerinde gezinen gök

Düşürür gölgesini yüreğime

Giden gitti döner mi geri 

gelenler biraz da bendeki 

tutan bulunur mu yerini 

Ey, bu ayrılığın yanlış yolcusu 

Anımsanan ilk ''aşk'' denli solgun ve derinliğinden

Pembe gülüşlü sevenlere armağan

Şiirin duruyor ardında, yıldızlı , nar çiçekli', 'Sevgicil gözlerine buğular çökmüş yağmurun salkımı dizilmiş kirpiklerine  gözlerinde gezinen gök Düşürür gölgesini yüreğime Giden gitti döne...', ARRAY['Türk Edebiyatı','Şiir','Müslim Çelik']::text[], 8.5, '{"poet":"Müslim Çelik","poet_slug":"muslim-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gidisin-caglayanlarin-hickirmasiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-suleyman-avci-gagah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolcu yolunda gerek 

Gidiyorum 

Bütün imkansızlıklara 

Anama babama 

Ve hatta sana rağmen gidiyorum 

Arkamda bir yakamoz ışıltısı 

Ve bir vapur düdüğü bırakıyorum yalnızca 

Herşeyi ama herşeyi 

Anılarımı, yaşanmışlıklarımı da yanımda götürüyorum 

Hepinize inat 

Herşeyi bavuluma sığdırıyorum ve götürüyorum 

Sana ve tüm şehire inat 

Hepinizi bencilliğiniz ile başbaşa bırakıyorum 

Ve elinizde kalan tek güzel şeyi alıyorum sizden 

Tıpkı sizin çok eskiden yaptığınız gibi 

Kısasa kısas 

Çocukluğuma karşılık 

Anılarınızı alıyorum 

Geri de vermiyorum....', 'Yolcu yolunda gerek  Gidiyorum  Bütün imkansızlıklara  Anama babama  Ve hatta sana rağmen gidiyorum  Arkamda bir yakamoz ışıltısı  Ve bir va...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidiyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncak', 'salincak-tahsin-ozkurt-vwijx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sallanırken aşkın salıncağında

görmez olursun gerçekleri.. 

yada seçemessin uzaktaki gemiyi

yüreğini tanımaya fırsat bulmadan yüreğinden olursun..

 sallanırken aşkın salıncağında.. yanar döner olursun    .. 

eski şarkıları bir başka sewersin.. yada bilemessin yitirdiklerini.. 

yüreğini tanımaya fırsat bulmadan yüreğinden olursun..

sallanırken aşkın salıncağında... yaklaşan fırtınadan korkmaz olursun.. 

bir başka cesaretlenirsin... yada üşümez olursun gece    ayazında ..

 yüreğini tanımaya fırsat bulmadan yüreğinden olursun..

sallanırken aşkın salıncağında bir de bakmışsın    ki yitirmişsin herşeyi.. 

yada kör olmuşsun besbelli sessizliğinden 

yüreğin tanınmıyor    ,kimliğin belirsiz.. 

sallanırken aşkın salıncağında.....yitirilmiş ve çaresiz...', 'Sallanırken aşkın salıncağında görmez olursun gerçekleri..  yada seçemessin uzaktaki gemiyi yüreğini tanımaya fırsat bulmadan yüreğinden olu...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özkurt']::text[], 8.5, '{"poet":"Tahsin Özkurt","poet_slug":"tahsin-ozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/salincak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Sevda', 'ayni-sevda-hakan-gursu-sd64y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynı yerdeyiz....

Sen ve ben,

Aynı sevdada,

Sessiz gözlerimi,

Okşamakta gözlerin..

Uzanıyorum usulca,.

Dudaklarına...

Haince öpüyorum,

Tadını içime kazımak

İstercesine..

Dünyanın bütün nimetleri

Orada toplanmış

Sanki...

Yudum yudum erimekteyiz

Aynı sevdadayız..

Sonrası yok.....', 'Aynı yerdeyiz.... Sen ve ben, Aynı sevdada, Sessiz gözlerimi, Okşamakta gözlerin.. Uzanıyorum usulca,. Dudaklarına... Haince öpüyorum, Tadın...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayni-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu', 'bu-hakan-gursu-cu0c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu

Kararsız,

Bu 

Uzun,

Bu 

Anlamsız,

Gecelerde..

Düşünmeyen bir beynim

Yanmayan bir kalbim

Olsun

İsterdim..

Uyuyabilmek için......', 'Bu Kararsız, Bu  Uzun, Bu  Anlamsız, Gecelerde.. Düşünmeyen bir beynim Yanmayan bir kalbim Olsun İsterdim.. Uyuyabilmek için.........', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybedilen Herşeyin Ardından', 'kaybedilen-herseyin-ardindan-sair-elvan-7ptr1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günlerden salı kaybedilen bir hayat geride kalan gözü yaslı akılları bulanık ve ölüm kavramını kaybetmis isnsanlar...

gözlerden süzülen yaslar  ve hayatın baharında tazecik bir gençlik.

kaybedilen unutulan ve beraber paylasılan hersey adına küçük bir tebessüm yüzlerde.

her an aglamaklı  gözlerden süzülen onu kaybetmenin yalnızlıgı ile bombos bakan acı dolu bakıslar

sevgi dolu bir annenin son sözleri ogluna son nasihatları yasarken kaybedilen duyguların adına son bir özür belkide

kulagına fısıldanan son bir ninni güzel sesinden yanagına kondurulan son bir öpücük

o hep gülümseyen yüzün perde perde solmus birden pırıldayan gözlerin unutu vermis bizleri

o saf temiz kalbin yürek oksayan sözlerin olmadan sen olmadan bu sahilin anlamı varmı?

o hep gezdigimiz günesin batısını martıların uçusunu  izledigimiz yerde bekliyor olacagım seni sakın unutma kalbim hep senin için çarpıcak

gökyüzüne her baktıgımda yada her yagmur damlası düstügünde topraga senin gözlerinden bakacagım dünyaya tıpkı senin dedigin gibi gülümseyecegim hayata

artık hersey söylendi yarıda kalan kaybedilen ve özlüm duyulan tüm anılar gömüldü karanlıga ölümün soguklugu ile üsüyen beden usulca yerlestirildi mezarına 

sonsuz bir sevgiyle son veda edildi ugurlandı son yolculuguna..

                                                                                                         RÜSTÜ''YE...', 'günlerden salı kaybedilen bir hayat geride kalan gözü yaslı akılları bulanık ve ölüm kavramını kaybetmis isnsanlar... gözlerden süzülen yasl...', ARRAY['Türk Edebiyatı','Şiir','Şair Elvan']::text[], 8.5, '{"poet":"Şair Elvan","poet_slug":"sair-elvan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaybedilen-herseyin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni İste', 'beni-i-ste-hakan-gursu-j7eu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bak yüreğim kabarmış,

Beni İste..

İsteki....

Umudum tazelensin

Ellerime ellerin doğsun..

Bütün evlerin ufkundan 

Dökülsün şehrin göğsüne

Kuş sesleri..

Gözlerimde,

Emsalsiz gözlerin doğsun,

Rüyalarımın penceresinde,

Şehvete boya bedenimi

Suçlu yüreğimde,

Yüreğin doğsun

Beni İste..

Hayatımızın anlamı olsun..', 'Bak yüreğim kabarmış, Beni İste.. İsteki.... Umudum tazelensin Ellerime ellerin doğsun.. Bütün evlerin ufkundan  Dökülsün şehrin göğsüne Kuş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Anda', 'su-anda-baran-ozbey-3ab7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu anda seni düsünüyorum martıları...

Kayalıklarda nefes alan dalgaları 

Su anda yalnızca...

Uzaklıgın hüzünlerdirmiyorki birtanem beni

Özgürlüğümün tadını çıkarıyorum

Su anda yalnızca...

İstersem sınırsızca severim ben seni 

Sana dair siirler yazarım...

Hatta sarkılar bile söylerim senin için,

Hayatın renkleriyle sararım.

Su anda sana sarıldığım gibi...', 'Şu anda seni düsünüyorum martıları... Kayalıklarda nefes alan dalgaları  Su anda yalnızca... Uzaklıgın hüzünlerdirmiyorki birtanem beni Özgü...', ARRAY['Türk Edebiyatı','Şiir','Baran Özbey']::text[], 8.5, '{"poet":"Baran Özbey","poet_slug":"baran-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/su-anda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Handaki Ben', 'handaki-ben-i-lhan-simsek-69e70', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün yorgun insanların konakladığı handaydım,

Hani şu yüksek kapılı.

İnsanların yalnızlıktaki dostu duvarlar

Yer sofrasındaki ayrıcalık,

Ve ben sensiz ordaydım;

Şu geçen yoksunluğundaki akşamlar gibi

Soğuk ve sessiz.

Küçük demir parmaklıklı pencereler

Uyuyamadım.

Yalnız insan Kervanları ile konakladığım

O Yüksek kapılı handaydım.', 'Dün yorgun insanların konakladığı handaydım, Hani şu yüksek kapılı. İnsanların yalnızlıktaki dostu duvarlar Yer sofrasındaki ayrıcalık, Ve b...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şimşek']::text[], 8.5, '{"poet":"İlhan Şimşek","poet_slug":"i-lhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/handaki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdamlık', 'i-damlik-atilgan-alemdar-ilb53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'idamlık bir mahkûmun 

dudaklarındaki son sigara

sanki benim dudaklarımdaki

senin dudakların sanki

ama mahkûm benden şanslı

çünkü son sigarasını içip ölecek hemen

oysa ben bir daha dudaklarını öper miyim bilmem

çünkü ölmedikçe yaşamak riskim var

keşke dudaklarına son istek diyen 

idamlık bir mahkûm olsaydım

ama nerde....şans yok ki.', 'idamlık bir mahkûmun  dudaklarındaki son sigara sanki benim dudaklarımdaki senin dudakların sanki ama mahkûm benden şanslı çünkü son sigaras...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/idamlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşlerim', 'guneslerim-i-brahim-uzer-yxusi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben söyledikçe

Sen, yavaş yavaş anlıyorsun

Artık, bakıyorum da

Usulca,dinliyorsun

biliyormusun,benim güneşimide

görmedin

Çünkü ben onu

her  zaman,göstermem

benim güneşlerim,insanın

ta içine işler

Düştüm mü,tüm aydığımla

Senide,denizleride,rüzgarıda

Ama her şeyi

yakarım..istersem

Sonrasında...

Munis,bir çocuk gibi

arkamda,kızıllığımı

upuzun,bırakır giderim.

Sense,benim batışımı

görkemli bir şölen gibi

gözkapaklarında,yaşatırsın

Benim,güneşlerimin,yerini

hiçbir,karanlık alamaz

Gecelerin gizemli saltanatı

benim,külhanlığımla biter

Severken,saygı duyarım

ılık ılık akarım,yüreklere

Bak dinle,biraz

kendini ve beni

Nasırlı koca ellerinin

ezilmiş,ufacık bedeninin

çektiklerinin,ceremesini

güneşlerimin,esrarını

halâ öğrenemedin

Artık,öğrenemezsinde....

Çünkü,anlamıyorsun

Sabahları,nasıl çıktığımı

görmedin ki...!

Az emek,bol uykuyla

şişmiş,göz kapaklarına

doğmam ben.

Doğmak,sadece ısınan gönüllere olur

Ama,ben seni ısıtamıyorum

Çünkü senin üstüne

Halâ doğmadım...

İyi düşün,güzelim

bu küçük,dünyada

ya yanında,ya içindeyim

Ama,yüreği ısınanların

yönündeyim.....!

                                   08.05.2000

          ''Aynı Yerdeyim''', 'Ben söyledikçe Sen, yavaş yavaş anlıyorsun Artık, bakıyorum da Usulca,dinliyorsun biliyormusun,benim güneşimide görmedin Çünkü ben onu her  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uzer']::text[], 8.5, '{"poet":"İbrahim Uzer","poet_slug":"i-brahim-uzer","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/guneslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozan', 'ozan-i-brahim-uzer-4tmkg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ozan nedir

diye, düşünürüm

çocukluğumdan beri

Eskiden taktığım

Bu lâkap,olsa gerek

şiirlerin,öykülerin

Çobanıdır ozan

Elinde,uzun bir kalem

etrafında,bir sözcükler

örtüsü..

Onları,güder devamlı

Sırtında,kepenek varmıdır

bilmem ama

Uzun,bir uğraş

Gölgelerle,uzayan

Alacakaranlık

ve kutsal emek..!

Ayakta çarık varmıdır

Onu da bilemem ama

şiirlerin,etrafında

döner devamlı

Onu,bir yerde

otururken gördüm

konuşalım dedim

yarenlik ederiz,birbirimize

Sustu ve sessizce

bana baktı

düşünüyorum dedi

Biliyorum ki

Azdı,şiirleri alıpta

okuyan...!

Ozanlar ekmek mi

şiir mi kovalamalı

Peki niye uğraşır ki

Ozan

Başka,türküsü de

vardır onun

Büyüktür,hüneri

tek istediği sabır ve

insan...!

her zaman,satırlarıyla

Gizli bir dansı vardır

Damsız,kavalyesiz

ve de kimsesiz

O her yerde

Sevdiklerinin

Kadını veya adamıdır

Ama bir ozan

Şiirlerinin,çobanıdır.

                                      11.11.2000', 'Ozan nedir diye, düşünürüm çocukluğumdan beri Eskiden taktığım Bu lâkap,olsa gerek şiirlerin,öykülerin Çobanıdır ozan Elinde,uzun bir kalem ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uzer']::text[], 8.5, '{"poet":"İbrahim Uzer","poet_slug":"i-brahim-uzer","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ozan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhane', 'meyhane-engin-bayraktar-rii8g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün bir meyhane gördüm .

Mezarlığın tam karşısında .

Birgün beni ararsan .

Ya meyhane deyim.

Yada tam karşısında .', 'Dün bir meyhane gördüm . Mezarlığın tam karşısında . Birgün beni ararsan . Ya meyhane deyim. Yada tam karşısında ....', ARRAY['Türk Edebiyatı','Şiir','Engin Bayraktar']::text[], 8.5, '{"poet":"Engin Bayraktar","poet_slug":"engin-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/meyhane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanma', 'utanma-sair-bien-pxo91', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Astoria  Hatırası

Birden düşse tüm yapraklar

Sonbahar çökse birden

Birden gelsen aklıma

Birden haykırsam

Bir zamanlar birbirimizden

Bize gelen bir can vardı

İşte o canı  ne ben aldım

Ne senin le kaldı

Birden düşse tüm yapraklar

Sonbahar çökse birden

Birden solarsam eğer

Hiç utanma

Bir zaman birbirimizden 

Bize gelen bir can vardı

İşte o canı ne ben aldım 

Ne seninle kaldı', 'Astoria  Hatırası Birden düşse tüm yapraklar Sonbahar çökse birden Birden gelsen aklıma Birden haykırsam Bir zamanlar birbirimizden Bize gel...', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/utanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-sair-bien-y0ji9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Astoria hatırası

Nedir sürükleyen bilimeyen gerçeklere,

Nedir beni benden alan başka kişiliğe saran.

Yok olmayan ümitlerin dünyasında,

Sımsıkı sarılan umit bekleyen insancılar.

Bilinirmi ki? 

Ne olacak yarınlarda

Bilinirmi ki?

Gerçek mutluluk tadı, acı gerçek kavramı.

Gösterir mi ki?  Kopan fırtınalar

İçimden akan sıcak göz yaşları.', 'Astoria hatırası Nedir sürükleyen bilimeyen gerçeklere, Nedir beni benden alan başka kişiliğe saran. Yok olmayan ümitlerin dünyasında, Sımsı...', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Sevgi', 'deli-sevgi-ali-kemal-32ey2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni

  Kendi haline bıraktım

  Nereye gidersen git artık

  Sen deli sevgi 

  İster 

  Uzak yıldızlara uç

  İster 

  Kör kuyulara düş 

  Akibetin

  Benden sorulmaz', 'Ben seni   Kendi haline bıraktım   Nereye gidersen git artık   Sen deli sevgi    İster    Uzak yıldızlara uç   İster    Kör kuyulara düş    ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal']::text[], 8.5, '{"poet":"Ali Kemal","poet_slug":"ali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deli-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Son Elvedayla', 'gidersen-son-elvedayla-mehmet-maden-dpnbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pınar''a

Gidersen son elvedayla sen

suları çekilir o gün ırmağımın.

Kaç kuraklık yaşar kalbim, bilmiyorum

yağmurla dönmelisin, güller düşürerek içime!

Gidersen son elvedayla sen

yalnızlık fırtınayla gelir üstüme.

Kaç mevsim üşür kalbim, bilmiyorum

güneşle dönmelisin, temmuz örterek üstüme!

Gidersen son elvedayla sen

ölüm usulca dokunur ellerime.

Kaç asır gömülür kalbim, bilmiyorum

hayatla dönmelisin, ses vererek sesime!', 'Pınar''a Gidersen son elvedayla sen suları çekilir o gün ırmağımın. Kaç kuraklık yaşar kalbim, bilmiyorum yağmurla dönmelisin, güller düşürer...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Maden']::text[], 8.5, '{"poet":"Mehmet Maden","poet_slug":"mehmet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidersen-son-elvedayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Taşan Damlalar', 'i-cimden-tasan-damlalar-mehmet-maden-9dlmq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-bekleyiş-

Güller yaslanmış kapıma

Yar mı geldi yoksa? 

İçeride ekmek kokusu var

Geldi mi yoksa yar? 

-bir anlamı olmalı-

Bir anlamı olmalı yalnızlıkların

Geceyi ışıkla yazmak gibi.

Bir anlamı olmalı ayrılıkların

Sevgiye hüzünle varmak gibi.

-yol arkadaşlarıma-

Çoğul bir yaşamın peşindeyim

Alın soluğum sizin olsun.

Ölümü yendiğim ülkedir hayat

Alın yüreğim sizin olsun.', '-bekleyiş- Güller yaslanmış kapıma Yar mı geldi yoksa?  İçeride ekmek kokusu var Geldi mi yoksa yar?  -bir anlamı olmalı- Bir anlamı olmalı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Maden']::text[], 8.5, '{"poet":"Mehmet Maden","poet_slug":"mehmet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yol-arkadaslarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşgünü Sendromu *', 'yasgunu-sendromu-mehmet-maden-oofwr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşanmış bir yıl daha sığınırken geceye

Yeni bir takvim düşecek kuş tüyü yastığına.

- altışubatbindokuzyüzyetmişaltı -

Sen

Bir yıl daha gençleşmiş olacaksın

(ardında bahar!)

Ben

Bir yıl daha yaşlanmış olacağım

(önümde sonbahar!)', 'Yaşanmış bir yıl daha sığınırken geceye Yeni bir takvim düşecek kuş tüyü yastığına. - altışubatbindokuzyüzyetmişaltı - Sen Bir yıl daha genç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Maden']::text[], 8.5, '{"poet":"Mehmet Maden","poet_slug":"mehmet-maden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasgunu-sendromu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahriye Abla', 'fahriye-abla-ahmet-muhip-diranas-og9bc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hava keskin bir kömür kokusuyla dolar

Kapanırdı daha gün batmadan kapılar

Bu afyon ruhu gibi baygın mahalleden

Hayalimde tek çizgi bir sen kalmışsın sen!

Hülyasındaki geniş aydınlığa gülen

Gözlerin , dişlerin ve akpak gerdanınla

Ne güzel komşumuzdun sen fahriye abla

Eviniz kutu gibi küçücük bir evdi

Sarmaşıkla
..........
..........', 'Hava keskin bir kömür kokusuyla dolar Kapanırdı daha gün batmadan kapılar Bu afyon ruhu gibi baygın mahalleden Hayalimde tek çizgi bir sen k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fahriye-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan Ediyorum', 'i-syan-ediyorum-vasif-senturk-vyokk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsyan ediyorum

Bana asi diyorlar

Fakirin ekmeğin çalana

Söylenen bunca yalana

Dava da geri kalana

İsyan ediyorum

Bana asi diyorlar

Dolarla zengin olana

Devletten milyar vurana

Her gece hayal kurana

İsyan ediyorum

Bana asi diyorlar

İnsanları ayırana

Eşi dostu kayırana

Zevkten düşüp bayılana

İsyan ediyorum

Bana asi diyorlar

Haksızlığa hak verene

Azınlığa zevk verene

Yolsuzluğa göz yumana

İsyan ediyorum

Bana asi diyorlar

Zülme boyun eğenlere

Emmi,dayı,yeğenlere

Herşeye evet diyenlere

İsyan ediyorum

Bana asi diyorlar

Vasıf''ı ters büyümeye

Yanlış yolda yürümeye

Haksızlıktan yerinmeye

İsyan ediyorum

Bana asi diyorlar

(Adıyaman-17.08.1988)', 'İsyan ediyorum Bana asi diyorlar Fakirin ekmeğin çalana Söylenen bunca yalana Dava da geri kalana İsyan ediyorum Bana asi diyorlar Dolarla z...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/isyan-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-turgut-erdogan-2wpxc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi diyorum,

Ansızın bir yağmur başlasa.

Çisil çisil, usul usul yağsa,

Düşen bir yaprak gibi hazan ortasında.

Yağmur olup sevinçlerim yağsa,

Ağıt olup hüzünlerim yağsa,

Tane tane, kor kor yağsa,

Ömrümün tam ortasına.

Ansızın çekip gitsem,

Hınçla vurup dünyanın kapısını.

Artık acılar çekmesem,

Hissetmesem hasretin sancısını.

Bu kadar yeter desem,

Silsem ömrün kalan yarısını.

Kimseye bırakmasam devirsem,

Bir tekmeyle idam sehpasını.

Ne yüreğime acı siner,

Ne hasretler çoğalır.

Ansızın yağmur diner,

Şairin arzusu başka hazana kalır.

Alanya, 24.11.2000', 'Şimdi diyorum, Ansızın bir yağmur başlasa. Çisil çisil, usul usul yağsa, Düşen bir yaprak gibi hazan ortasında. Yağmur olup sevinçlerim yağs...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yagmur-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-metin-vatansever-u67sd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gideceksin biliyorum,

Ama gitmelimisin anlayamadığım bu,

İnanmazsın anlatsamda ben,

Sabahlara tutsak geceleriminısdırabını,

Beni uykusuz gecelerin koynuna atıyor gibisin,

Yalnızlığı biliyorum,

GİTME!.. Kal benimle...

Hayır,

Sessiz sedasız çıkamazsın  anılaromdan

Bir mahşer günü yaşamalı yüreğim sen giderken,

Yaşamalı ki kabullenebileyim gittiğini,

Giderken  saatleride durdurmalısın,

Her anı bir asır gibi yaşamak zor.

GİTME!.. Paylaş yalnızlığımı...

Gideceksen önce bir hançer çek,

Yürü deli duygularımın üzerine

Cezamıinfaz et sonra katı yasalarınla,

Önce sevgimi öldür yüreğimde Bileklerime vur ayrılık zincirlerini

Gideceksen git, ama

GİTME!.. Olacak son sözüm...', 'Bir gün gideceksin biliyorum, Ama gitmelimisin anlayamadığım bu, İnanmazsın anlatsamda ben, Sabahlara tutsak geceleriminısdırabını, Beni uyk...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gitme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahroluşum', 'kahrolusum-metin-vatansever-j0c0d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umutlarım idam sehpasında,

Ha öldü ha ölecek,

Özlem denilen duygulara da

Kader sırt çevirdi zaten

Uzanan ellerim katılaştı

Gözlerim beklemekten bitkin

Sevilerim çıkmaz sokaklarda

Sevgiden yoksun kalbim

Dertlerin durağı oldu

Bir söz var şimdi dilimde

Kahroluşumu ezberliyorum...', 'Umutlarım idam sehpasında, Ha öldü ha ölecek, Özlem denilen duygulara da Kader sırt çevirdi zaten Uzanan ellerim katılaştı Gözlerim beklemek...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kahrolusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemişsindir', 'ozlemissindir-hakan-gursu-ipxev', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buruk bir duygu yüklenirse kalbine

Gözlerin,

Duman,duman takılırsa uzaklara..

Hele kulakların zamansız deli,deli çınlarsa..

Bilki....

Buraları,birşeyleri,

Özlemişsindir.

Caddeler,

Islanmışsa gözyaşlarından..

Birde,

Sırılsıklam bir yağmur yağıyorsa o akşam,

Ellerin titriyorsa üşümeksizin

Eğer,

Özlem dolu br şarkı tutturmuşsa dudakların

Ve..

Ansızın bir hıçkırık yırtarsa kara geceyi

Sende benim gibi

Birşeyi özlemişsindir..', 'Buruk bir duygu yüklenirse kalbine Gözlerin, Duman,duman takılırsa uzaklara.. Hele kulakların zamansız deli,deli çınlarsa.. Bilki.... Burala...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlemissindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl''da', 'nasil-da-hakan-gursu-2mzi2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her geçen an

Daha çok istiyorum onu

Nasıl tanıştık?

Elini nasıl tuttum

Nasıl''da ıslaktı,sırılsıklam

İzmir''de

Deniz kıyısında,

Dalgaların sesi karışırıken 

Sessizliğimize,

Nasıl da ilk kez öptüm dudaklarından,

İzmir''de

Bir kıyı kahvesinde..

Güneş....

Işıklarıyla demliyordu çaylarımızı

Nasıl da 

Okşadım simsiyah saçlarını

İzmir''de

Yıldızlar yanarken, gözlerinin derinliklerinde

Nasıl da

Başımı göğsüne dayayıp

Çekmiştim kokusunu içime

Heyhat!!!!!

Şimdi düşünüyorum da...

Nasıl akıpta gidiyor

Cehennem habercisi zaman...

Geçmeyen boğazıma yetmeyen para,

Birde aşkım

Ona susamışlığım..

Her an biraz daha istiyorum onu..

Ama o nerede', 'Her geçen an Daha çok istiyorum onu Nasıl tanıştık? Elini nasıl tuttum Nasıl''da ıslaktı,sırılsıklam İzmir''de Deniz kıyısında, Dalgaların ses...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nasil-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-hakan-gursu-7omc2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ince nakışla geçip gidiyor akşam üstü

Oysa dün gelecekti..

Sabah dudağımdan öperek uyandıracaktı

Çay demleyecektim

Kızarmış Ekmek

Peynir..

Birer sigara yakacaktık,

Sonsuz umudumuzdan

Dünyadan ve insanlardan 

Konuşacaktık uzun,uzun

Susacaktık uzun,uzun

Sinemaya mı giderdik akşama doğru

Bir ince nakışla gidiyor

Akşam üstü oysa...

Acıların uzağından

Kederlerin uzağından

Yanlızlığın uzağından

Kanat açarken,

Işıktan oyulmuş umutlara..

Kandili mavi alevli sulara..

Neredesin Şimdi........', 'Bir ince nakışla geçip gidiyor akşam üstü Oysa dün gelecekti.. Sabah dudağımdan öperek uyandıracaktı Çay demleyecektim Kızarmış Ekmek Peynir...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neredesin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyleyim İşte', 'ben-boyleyim-i-ste-gul-unal-fsgre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben böyleyim işte

Gözüm mü kara desem

Yoksa aklım hala bir karış havada mı

Ben böyleyim işte

Duydum mu havada kokusunu

Sevginin

Kendimi tutamam

Ben böyleyim işte

Balıklama dalarım sevdalar

Geçmişe bakmadan

Geleceğe aldırmadan

Ben böyleyim işte

Böyle olmak suçsa eğer

Çekerim de cezamı...', 'Ben böyleyim işte Gözüm mü kara desem Yoksa aklım hala bir karış havada mı Ben böyleyim işte Duydum mu havada kokusunu Sevginin Kendimi tuta...', ARRAY['Türk Edebiyatı','Şiir','Gül Ünal']::text[], 8.5, '{"poet":"Gül Ünal","poet_slug":"gul-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-boyleyim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünüm', 'gorunum-hakan-gursu-kq068', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve.....

Saçlarımı yüzüme değdi

Tek bedendeydi ruhlarımız

Kaybolduk birbirimizde...

Ve......

Kaslarımız gerildi

Duyuyorduk..

Bir insan yaratmanın

Engin mutluluğunu......', 'Ve..... Saçlarımı yüzüme değdi Tek bedendeydi ruhlarımız Kaybolduk birbirimizde... Ve...... Kaslarımız gerildi Duyuyorduk.. Bir insan yaratm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gorunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-ahmet-sahin-soner-e9xfj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yasamayı öğretirdin insanlara, 

Sen gittin.....

Ve ben öğrettiklerinle yaşıyorum

Senin doğum günün bugün, 

Sana, çicekler vermek isterdim

Sarılıp canlı bedenine, öpmek isterdim.

Eski doğum günlerini hatırladım.

Dün gece anılara karışarak 

Gözlerim doldu, 

Hıçkırdım, ağladım, 

Yaşamayı aşılardın bizlere

Sevmeyi aşılardın, 

Neden gittin, 

Kolay mı zannettin ölmeyi....

Çekip gitmeyi, 

Yüzünü göremedim... 

Beyazlara sarmalanmıştın.

Çekip alamadım, 

Alışamadık sensizliğe, 

Alışamadık sensiz sohbetlere 

Bugün evine geldim;

Üzerine çiçek bıraktım

Sana değil ama, 

Sen kokan toprağına sarıldım, 

Ve ilk defa bu doğum gününde ağladım.

Ağlamamızı istemezdin 

Ama kolay değilmiş

Bugün senin doğum günün

Doğum günün kutlu olsun

25.11.1975 - 27.09.2000', 'Sen yasamayı öğretirdin insanlara,  Sen gittin..... Ve ben öğrettiklerinle yaşıyorum Senin doğum günün bugün,  Sana, çicekler vermek isterdi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damgın Arkadaş', 'damgin-arkadas-oktar-almac-y8h3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalgın gözlerle bakıyordu etrafına 

Karmaşık duyguları vardı,sanki tarifsiz

Sigara dumanı gibi,içine atıyordu dertlerini

Belliki yanıyordu yüreği.

Kurtulamıyordu içinde bulunduğu durumdan ,

Oltaya takılmış bir balık gibi,

Çırpınıp duruyordu durmadan.

Şaşkındı arkadaşım,belirsizlik vardı yüzünde,

Bitsin der gibiydi çaresizlikten.

Bitsin.........................................

Hayır,hayır yapamam,bilmiyorum,

Bitmesin.........................................

Kaçıp uzaklaşmak istiyordu buralardan

Ve için de bulunduğu karmaşık duygulardan.', 'Dalgın gözlerle bakıyordu etrafına  Karmaşık duyguları vardı,sanki tarifsiz Sigara dumanı gibi,içine atıyordu dertlerini Belliki yanıyordu y...', ARRAY['Türk Edebiyatı','Şiir','Oktar Almaç']::text[], 8.5, '{"poet":"Oktar Almaç","poet_slug":"oktar-almac","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/damgin-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstencim', 'i-stencim-hakan-gursu-e7eli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yosun kokar mavnaları İzmir''in

Kızları mercan,

Yüreğim gökkuşağı

Tütüne yağmur olmuş alınteri

Yunan tanrılarının gücü bedenimde,

Kardan saraylar yaptım

Erzincan düzüne..

İstediğim güzel

Kalbimden göçer de gider

Edirne''nin 

Bir sokağını şarapla yıkadım

Her akşam evimizin kokusu

Adım,adım

Kurmak için yarını, elde ne varsa kalan

Yağmurun başaklarda boy vermeye tutkulu

Geleceğe kurmuşken tüm düşlerimi

İzmir''de çarpıldım,

Yürek tuzla buz

Ege...

Özlemlerimin enginliğisin

Ekin bitmez,

Keklik ötmez düz değil

İstencim yetim tohum', 'Yosun kokar mavnaları İzmir''in Kızları mercan, Yüreğim gökkuşağı Tütüne yağmur olmuş alınteri Yunan tanrılarının gücü bedenimde, Kardan sara...', ARRAY['Türk Edebiyatı','Şiir','Hakan Gürsu']::text[], 8.5, '{"poet":"Hakan Gürsu","poet_slug":"hakan-gursu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istencim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Aşkıma', 'son-askima-enis-behic-koryurek-8b3xy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey benim gül demetim, ey bir çile ipeğim! 

Seni çok seviyorum, daha çok seveceğim.

Sen benim kuraklıktan solan gönül bahçemde,

Sen benim şu yıldızsız kalan hulya gecemde

Bir son bahar değilsin, sonuncu bir baharsın; 

Ufkumda fecri açan gül kanatlı rüzgarsın. 

Şi''rimdeki heyecan bugün sendedir ancak, 

Bu şi''rim bende artık son heyecan olacak, 

Şu gönlüm bilsen, nasıl çırpınarak yoruldu.

Bir güzelden kurtuldu, bir güzele vuruldu.

Her birinde bir parça daha yorgun düşerek,

Kimine lanet edip kimiyle öpüşerek,

Nihayet, işte bugün hepsinden ayrılmışım; 

O kadar bıkkınım ki, mazime darılmışım...

Sen ki bir çocuk kadar şakraksın, neşelisin; 

Sen ki aşka gençlikle koşan güzel delisin; 

Bana mahkum olduğun lahzalar var sanırım; 

Busemle ürperdiğin o anları tanırım.

Ey cici kırlangıcım, benim ipek böceğim! 

Yaklaş sana pek gizli bir şey söyleyeceğim:

Seni gittikçe fazla seviyorum yaramaz! 

Bugün dünden daha çok ve yarından daha az..

Kıymetli tutuyorsun, değil mi, bu sevgimi? 

Yalvarırım, beni hep titreyerek sev, e mi! 

Bakışımdan korkarak, göğsüme sokularak,

Aşkın bütün şiirini her an bende bularak..

Yalvarırım, böyle sev! Bana karşı aciz ol! 

Sevişmekte zalimlik, inan ki en fena yol..! 

Artık mücadelesiz, gözyaşından müstağni

Bir sevgiye muhtacım, sen de böyle sev beni.

O ipekten göğsünde bırak başım dinlensin! 

Bir çile ipeğim sen, gül demetim de sensin! 

Sakın sanma bıkarım tatlı buselerinden...

Sevilmek ihtiyacı bende öyle derinden

Gelen bir iptila ki severim sevildikçe.

Esirinim, seninim olduğunu bildikçe.

Şairliğim seninle en bahtiyar, en mağrur

Anındayken düşün ki gençliğimin sonudur.

Bırak gönlüm kendini bu aşka hakim sansın! 

Genç kadın, mahkum ol ki ona hakim olansın...', 'Ey benim gül demetim, ey bir çile ipeğim!  Seni çok seviyorum, daha çok seveceğim. Sen benim kuraklıktan solan gönül bahçemde, Sen benim şu ...', ARRAY['Türk Edebiyatı','Şiir','Enis Behiç Koryürek']::text[], 8.5, '{"poet":"Enis Behiç Koryürek","poet_slug":"enis-behic-koryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/son-askima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Nijad!', 'ah-nijad-recaizade-mahmud-ekrem-k63xq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret beni cayır cayır yakarken

Bedenimde buzdan bir el yürüyor.

Hayaline çılgın çılgın bakarken

Kapanası gözümü kan bürüyor.

Dağda kırda rasgetirsem bir dere

Gözyaşlarım akıtarak çağlarım.

Yollardaki ufak ufak izlere

Senin sanıp bakar bakar ağlarım.

Güneş güler, kuşlar uçar havada,

Uyanırlar nazlı nazlı çiçekler..

Yalnız mısın o karanlık yuvada?

Yok mu seni bir kayırır, bir bekler?

Can isterken hasret odiyle yansın,

Varlık beni alil alil sürüyor.

Bu kaygıya yürek nasıl dayansın?

Bedenciğin topraklarda çürüyor!

Bu ayrılık bana yaman geldi pek,

Ruhum hasta, kırık kolum kanadım.

Ya gel bana, ya oraya beni çek,

Gözüm nuru oğulcuğum, Nijad''ım!', 'Hasret beni cayır cayır yakarken Bedenimde buzdan bir el yürüyor. Hayaline çılgın çılgın bakarken Kapanası gözümü kan bürüyor. Dağda kırda r...', ARRAY['Türk Edebiyatı','Şiir','Recaizade Mahmud Ekrem']::text[], 8.5, '{"poet":"Recaizade Mahmud Ekrem","poet_slug":"recaizade-mahmud-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ah-nijad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Seyahat', 'gozlerinde-seyahat-orhan-seyfi-orhon-sf9u1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıktım bugün güzellerin gözlerinde seyahate:

Bu yolculuk bilmem nasıl erecekti nihayete?

Mavi gözler... Pek asabi, dalgalı bir deniz gibi;

Yeşil gözler en ziyade mütemayil hıyanete.

Sarışınlar... Yorgun bir yaz semasını andırıyor,

İlk busede başlayacak talihinden şikayete.

Ela gözler... Akşam gibi gölge dolu, hicran dolu,

Bu gözlerde hiç tesadüf etmedim ben saadete.

Gece oldu... En sonunda siyah gözler geldi, durdum;

Bu karanlık yolda artık imkan yoktu seyahate!', 'Çıktım bugün güzellerin gözlerinde seyahate: Bu yolculuk bilmem nasıl erecekti nihayete? Mavi gözler... Pek asabi, dalgalı bir deniz gibi; Y...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi Orhon","poet_slug":"orhan-seyfi-orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerinde-seyahat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı Olup Konacağım Başucuna', 'marti-olup-konacagim-basucuna-balim-akkaya-issmn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaklardan kokun geliyor sanki burnuma

Sıcaklığını hissediyorum sanki yanıbaşımda

Bu gece uğrayacağım yanına

Bir martı olup geleceğim

Gecenin karanlığında

İyot kokulu denizlere bata çıka

Tuzlu damlacıklar bulursan uyandığında

Sakın ağladım sanma

Martı olup kanatlarımla

Sonbahar rüzgarını taşıyacağım sana

Fısıltı halinde bir sesle

Kimsenin bilmediği şarkıları söyleyeceğim

Uyurken seyredeceğim seni

Getirdiğim rüzgarı dolaştırıp saçlarında

Kokunu çekeceğim içime

Seninle dolacağım alabildiğince

Sonra karanlıklara kanat açıp

Döneceğim

Sabah uyandığında

İki damla tuzlu su bulacağım yastığımda

Anlayamayacağım  ağladım mı

Yoksa

İyot kokulu denizlerin suyu mu bu iki damla

Hisset benim varlığımı sevgilim bu gece

Martı olup konacağım başucuna!

(17 Eylül 1991 - Başkent)', 'Uzaklardan kokun geliyor sanki burnuma Sıcaklığını hissediyorum sanki yanıbaşımda Bu gece uğrayacağım yanına Bir martı olup geleceğim Geceni...', ARRAY['Türk Edebiyatı','Şiir','Balım Akkaya']::text[], 8.5, '{"poet":"Balım Akkaya","poet_slug":"balim-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/marti-olup-konacagim-basucuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürmüyor', 'oldurmuyor-balim-akkaya-huik0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşanmaz sanıyordum sensiz

Biter diyordum herşey

Terk edersen beni

Ölünmüyormuş oysa ha deyince

Sandığım kadar kolay değilmiş

Birden bitivermiyormuş herşey

Korkardım seninle birlikteyken

Ayrılırsak yokoluvermekten

En basitiymiş meğer yokolmak

Şimdi anladım ki hayat devam ediyor

Öldürmüyor ayrılık

Öldürse daha iyi dedirtiyor insana

Yalvartıyor yok olmak için Tanrı''ya

Sensizlik öldürmüyor birtanem ama

Çürütüyor her geçen gün bir parça daha...

(16 Ocak 1992 - Başkent)', 'Yaşanmaz sanıyordum sensiz Biter diyordum herşey Terk edersen beni Ölünmüyormuş oysa ha deyince Sandığım kadar kolay değilmiş Birden bitiver...', ARRAY['Türk Edebiyatı','Şiir','Balım Akkaya']::text[], 8.5, '{"poet":"Balım Akkaya","poet_slug":"balim-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldurmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangimiz', 'hangimiz-balim-akkaya-6wh6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangimiz zannetmedik ki aşık olduğumuzu

Hangimiz hayal kurmadık

Hangimizin geçmedi ölüm aklından zaman zaman

Hangimiz yalnız kalmadık ki kimi zaman

Hangimiz ağlamadık giden sevgilinin ardından

Ve hangimiz demedik en sonunda,

''Bu aşk denen şey yalan!''

(16 Şubat 1992 - Başkent)', 'Hangimiz zannetmedik ki aşık olduğumuzu Hangimiz hayal kurmadık Hangimizin geçmedi ölüm aklından zaman zaman Hangimiz yalnız kalmadık ki kim...', ARRAY['Türk Edebiyatı','Şiir','Balım Akkaya']::text[], 8.5, '{"poet":"Balım Akkaya","poet_slug":"balim-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hangimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Noktalar', 'yesil-noktalar-balim-akkaya-28q2g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen geçmişte kaybolur düşüncelerim

Karışır gider o eski zamanlara

Eski sevdalar geçer gözümün önünden birer birer

Dünde miyim, bugün dün mü?

Yoksa dün bugün mü?

Karıştırırım

Hayat defterinin tozlu sayfaları çevrilir teker teker

Hep bir sayfada takılır kalır gözlerim

Ağlamak isterim ya nafile akmaz damlalar

Kaybolurum anıların acı verici boşluğunda

Gerçek anlamda bir çift yeşil göz hatırımda

Geri kalanlar karanlık ve silik

Gözyaşları var birde unutulmadık

Bir yıl öncesi mi bu sevda

On yıl mı yoksa bir ay mı bilmem

Yıllarca mı sürmüştü, yoksa üç-beş gün mü?

Mutluluklu mu vermişti bana hüzün mü?

Sevmiş miydi beni, ya ben sevmiş miydim onu?

Yirmidokuz harfin hangisiyle başlıyordu adı?

Ya da yirmisekiz harfin; Ğ olamazdı tabi

Yaşı neydi, işi neydi, öğrenci miydi?

Güzel miydi, çirkin miydi hiç bilmiyorum

Yeşil gözlerini biliyorum sadece

Pırıl pırıl bir çift, çok güzel yeşil göz

Sinsi mi bakardı, sevecen miydi yoksa?

Yeşil noktalar ve gözyaşlarım aklımda

Gerisi silinmiş ama anılara daldığımda

Takılıp kalıyorum o yeşil noktalarla o tuzlu damlalarda...

(5 Nisan 1992 - Başkent)', 'Bazen geçmişte kaybolur düşüncelerim Karışır gider o eski zamanlara Eski sevdalar geçer gözümün önünden birer birer Dünde miyim, bugün dün m...', ARRAY['Türk Edebiyatı','Şiir','Balım Akkaya']::text[], 8.5, '{"poet":"Balım Akkaya","poet_slug":"balim-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yesil-noktalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İbibik Kuşu', 'ey-i-bibik-kusu-ceyhun-atuf-kansu-w9xdl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdim nedir bilir misin?

Ey garip ibibik kuşu.

Söylesem bölüşür müsün,

Ey garip ibibik kuşu?

Yaz sıcağında duyduğum,

Vadilerin içli sesi.

Gölgesinde uyuduğum

Sükun dolu yaz öğlesi

Nerede gümüş şadırvan,

Bol gölgesinde çınarın?

Aşığıyım şırıldayan,

Gönlüme akan suların.

Bayıltıcı iğdelerde,

O sarı sarı çiçekler.

Eski baharlar nerede,

Bizi hangi dağda bekler?

Az mı uyudum sesinle,

Benim içli, garip kuşum?

Ben de senin gibi, dinle,

Bir garip derde düşmüşüm.

Ey iyi kalpli ibibik,

Benim kırlarımın kuşu!

Bir serin rüyada ibrik,

İçinde uyur gözyaşı.

Anneciğim benim kırım,

Koşsam bir uçtan bir uca.

Dertlerimi unuturum

Çiçekli yollar boyunca.

Uzakta bıraktığım ev,

Komşu kızının gülüşü,

En büyük acıları sev,

Sev diyor ibibik kuşu.', 'Derdim nedir bilir misin? Ey garip ibibik kuşu. Söylesem bölüşür müsün, Ey garip ibibik kuşu? Yaz sıcağında duyduğum, Vadilerin içli sesi. G...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun-atuf-kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ey-ibibik-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda mısın?', 'orda-misin-sair-doktor-pam4x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orda mısın?

Uykularım rehin almış zamanı,

geçmek bilmiyor geceler.

Ne yana baksam bir anı

ve bir avuç hüzne boğulmuş sen,

ben...

Ordamısın?

şimdi ağlamaklı şarkılara söz yazıyor şiirlerim

kemanlar ağlıyor,

ben ağlıyorum,

duyuyor musun?...

Yaşanan mutsuzluk değil,

yaşanan ben...

Ne yana baksam bir ilişkinin derin izleri,

ne yana baksam korku

bilmiyorum uzak mı ayırdı bizleri?,

yoksa yaşanan aşk değil miydi?

bilmiyorum...

Orda mısın?

Ne zaman telefonum çalsa

korkuyorum açmaya

müziğin sesini kısıyorum

kulağım telefon bekleyişinde

sözde ders çalışıyorum ama

fikrim senin kuytuluğunda

ve ıpıslak,kitabımın

daha tek sayfasını bile okumadığım sayfaları...

Orda mısın?

gözlerim keman ağlıyor,

dilimde hüznün şarkıları,

kulağımda son söylediklerin...

Bir telefon görüşmesine sığan

zamanı mühim değil,

bir aşkın cenazesi!

Saçma sapan bir ayrılık bahanesi...

Orda mısın?

sesin karanlıkta dolanıyor.

Hayatımı sen yapan şeyler;

anılar,hediyeler,resimler

ve bu kalpte bıraktığın buruk acı

hepsi kitap olmuş

usulce yerlerini alıyor satır aralarında.

Senden geriye kalanlar;

korkuların,uzaklığın ve

sevmeme engel bir sen...

Orda mısın?

git de biraz yanımda ol!

Bir sarılmanın sıcaklığını,

elimin elinde terleyişini,

korku dolu kaçamakları,

bir aşkı aşk yapan

yayılım bakışları,öpücükleri

hatırlıyor musun?...

Ve sen hala o fazlaca korktuğun

tercih edilebilirliğimin nedenini

kuru ve soğuk bir uzaklığa

ve bu ilişkinin ciddiyetine feda ediyorsun!

Git de biraz yanımda ol

bu faili sen cinayete

korku maskesi takıyorsun...

Orda mısın?

istesem yanıma gelir misin?

Geri sayım başladı

artık bir bomba gibi geliyor

odamdaki saat tiktakı

uykularım rehin almış zamanı

istemezlerse sabah olmuyor...

Sesin dolanıyor karanlıkta,

içimi üşütüyor ayrılığın,

kemanlar çalıyor kulaklarımda,

ne yana baksam bir anı ve

sevmeme engel bir sen...

Orda mısın?', 'Orda mısın? Uykularım rehin almış zamanı, geçmek bilmiyor geceler. Ne yana baksam bir anı ve bir avuç hüzne boğulmuş sen, ben... Ordamısın? ...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/orda-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simsiyah Yankılar', 'simsiyah-yankilar-cuneyt-demir-9wbsg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşke tanımasaydım seni

Omuzlarıma bu kadar yük binmezdi o zaman

Gözlerim ağlamayı bilmezdi bu kadar sık

Kalbim çarpmazdı böyle delicesine

Benimde ellerim sıcacık olurdu mutlaka

Geceleri asla uykusuzluk çekmezdim sabaha kadar

Rüyalarım hatta tatlı hülyalarım olurdu

Duygusuzca düşünmezdim yokluğunda yıllarımı

Hem üşümezdim de hiç böylesine ölü soğukluğunda

Hırsla savurmazdı kuzey rüzgarları yalnızlığımı

Kan çanağına dönmezdi gözbebeğimin taa içi

Kayan yıldızlarla  bende farklı dilekler tutardım

Duyardım anlardım yanımda konuşulanı

Adımların ise bu kadar küçülmezdi

Bende gülerdim zaman zaman

Deniz ve mehtap benim içinde önemli olurdu belki

Hele kara saplı bıçak dostum olmazdı sırtımda

Keşke tanımasaydım seni

Omuzlarıma bu kadar yük binmezdi o zaman

Gözlerim ağlamayı bilmezdi bu kadar sık

Kalbim çarpmazdı böyle delicesine

Benimde ellerim sıcacık olurdu mutlaka

Güneşsiz dünyamda kavrulmazdı ciğerlerim

Beynimse böylesine hırçın uğuldamazdı

Kor yüreğime damla damla vurmazdı gözyaşlarım

Ruhumu daraltmazdı benliğimi sıkıştırmazdı

Tüm zerrelerim acı çektirmezdi zavallı bedenime

En tiz sesiyle çığlıklar atmazdı yüreğim

Simsiyah yankılar oluşturmazdı ufkumda

Sonra birşeyler yer içerdim diğer insanlar gibi

Açlığı, susuzluğu, hani o hasreti bilmezdi bu can

Helallik vermezdi zalim geceye

Öksüz bir garip gibi hissetmezdi kendini

Buluşur gezerdi işte sevdiği dostlarıyla

Sürekli uzaklara dalıpta kalmazdı oralarda

Bütün gücüyle tütünü çekmezdi her an

Keşke tanımasaydım seni 

Omuzlarıma bu kadar yük binmezdi o zaman

Kalbim çarpmazdı böyle delicesine

Benimde ellerim sıcacık olurdu mutlaka

Yüreğim tatmasaydı senin sevdanı keşke

Keşke tanımasaydım seni', 'Keşke tanımasaydım seni Omuzlarıma bu kadar yük binmezdi o zaman Gözlerim ağlamayı bilmezdi bu kadar sık Kalbim çarpmazdı böyle delicesine B...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Demir']::text[], 8.5, '{"poet":"Cüneyt Demir","poet_slug":"cuneyt-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/simsiyah-yankilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-fatih-misket-svioj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taze bir gül dalında buldumda aşkı

Yaprak oldum çiçek oldum ben bugün

Terk eyledim hem sarayı hem köşkü

Köle diye geldim kapına bugün

Ne bahçeler ne bağları dolaştım

Binbir türlü çiçeklerden bal aldım

Gülü gördüm onun seyrine daldım

Doyamadım tadına gülümün bugün

Sonbaharlar girdi gülle arama 

Dert ekledi kapanmayan yarama

Doyasıya bakmadan bahtı karama

Bu viran ellerden göçtü bak bugün', 'Taze bir gül dalında buldumda aşkı Yaprak oldum çiçek oldum ben bugün Terk eyledim hem sarayı hem köşkü Köle diye geldim kapına bugün Ne bah...', ARRAY['Türk Edebiyatı','Şiir','Fatih Misket']::text[], 8.5, '{"poet":"Fatih Misket","poet_slug":"fatih-misket","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvimdeki Deniz', 'takvimdeki-deniz-necip-fazil-kisakurek-r9vpp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasreti denizlerin,

Denizler kadar derin.

Ve o kadar bucaksız.

Ta karşımda yapraksız

Kullanılmış bir takvim.

Üzerinde bir resim;

Azgın, sonsuz birdeniz.

Kaygısız, düşüncesiz,

Çalkanıyor boşlukta

Resimdeyse bir nokta;

Yana yatmış bir gemi,

Kaybettiği alemi

Arıyor deryalarda.

Bu resim rüyalarda 

Gibi aklımı çeldi,

Bana sahici geldi.

Geçtim kendi kendimden,

Yüzüme o resimden,

Köpükler vurdu sandım.

Duymuş gibi tıkandım,

Ciğerimde bir yosun.

Artık beni kim tutsun.

Denizler oldu tasam,

Yakar onu bulmazsam

Beni bu hasret dedim

Varırım elbet dedim.

Bir ömür geze geze

Takvimdeki denize.

Ne var bana ne oldu

Odama nasıl doldu

Birden bire bu meltem

Ve dalgalandı perdem

Havalandı kağıtlar.

Odamda kıyamet var.

Ah yolculuk yolculuk

Ne kadar baygın soluk

O gün bizde betbeniz

Ve ne titrek kalbimiz.

Ve eşyamız ne küskün.

Yola çıktığımız gün

Bir sıraya dizilmiş

Gözyaşlarını silmiş,

Bakarlar sinsi sinsi

Niçin o anda hepsi

Bir kuş gibi hafifler

Arkandan geleyim der

Niçin o güne kadar 

Dilsiz duran ne kadar

Eşya varsa dirilir

Yolumuza serpilir

Ufak böcükler gibi

Gezer onların kalbi

Üstünde döşemenin

Gizli bir didişmenin

Saati çalar o an

Birden bakar ki insan

Herşey karmakarışık.

Ayırmak olmaz artık

Bir kalbi bir taraktan

Ve kalb ağlayaraktan

Çekilir geri geri

Terkeder bu mahşeri.

Bu mahşerin içinden

O gün ben de geçtim ben,

Nem varsa evim, anam,

Çocukluğum, hatııram,

Ve ne sevdalar serde

Bıraktım gerilerde

Kaçar gibi yangından.

Rüzgarların ardından

Baktım da süzgün süzgün

Kurşun yükünü gönlün

Tüy gibi hafiflettim.

Denize hicret ettim.', 'Hasreti denizlerin, Denizler kadar derin. Ve o kadar bucaksız. Ta karşımda yapraksız Kullanılmış bir takvim. Üzerinde bir resim; Azgın, sons...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/takvimdeki-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Hikaye', 'baska-hikaye-stepne-sair-qgrof', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay bir buluttan çıkıp

Bir başkasına girer

Sen yoksan öksüzdür gece

Yaprak kımıldamaz yatak odasında

Kanepede yatarım sessiz, nefessiz

Salonun tüm köşeleri ezberimdedir ya

Hepsi tamam mı diye,

Ben gene de sayarım

Uyku tutmaz o gece

Gerçi yanımda olsan da tutmuyor ya,

O başka bir hikaye…', 'Ay bir buluttan çıkıp Bir başkasına girer Sen yoksan öksüzdür gece Yaprak kımıldamaz yatak odasında Kanepede yatarım sessiz, nefessiz Salonu...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/baska-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta Olursan', 'hasta-olursan-stepne-sair-j2kh6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün hasta olursan

Çorbanı ben yapacağım

İlaç getirecek kimileri

Ben suyuna sevgi atacağım', 'Bir gün hasta olursan Çorbanı ben yapacağım İlaç getirecek kimileri Ben suyuna sevgi atacağım...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasta-olursan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Oldun mu?', 'kor-oldun-mu-stepne-sair-7ad4b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen hiç tutsak kaldın mı düşlerine

Salıverdin mi umutlarını suyu çekilmiş tarlalara

Bilir misin nasıl boy atar düş kırıklıkları

Dönüp dururken uykusuz, yalnız yatağında

Bir sağına, bir soluna.

Nasıl yakar elini o yanındaki soğuk yastık,

Nasıl da mezar taşı gibi soğuktur o yorgan,

Faltaşı gibi açık gözlerin dikili karanlığa

Boş boş bakarsın anlamsız, amaçsız

Tan atarken ufukta teslim olursun yorgunluğa

Sen hiç kör oldun mu

Durup dururken, gün ortasında.

Sen hiç iyi ettin mi

Kanadı kırılmış bir kırlangıcı

Tek bir öpücüğünle

Sakladın mı bağrında güz yağmurlarından

Siper ettin mi bedenini düşman bakışlara

Yandı mı yüreğin

İyileşip de bir gün

Uçup gidiverdiğinde

Teselli aradın mı şeytan uçurtmalarında

O sessizce uçup giden kırlangıç

Dönüp geldi mi hiç ertesi bahar

Sordun mu asmışmı dizelerini dolaştığı göklerin mavilerine

Yoksa senin göğünde

Hiç yer olmamışmıydı maviliklere

Bir fotoğrafa asılı kalmış sessiz kahkahaların

Bir zamanlar gerçek olduğunu hatırladınmı hiç

Hiç ağladın mı kullanılmış bir havluya bakıp

Bir eski mektup hiç burktu mu yüreğini

Hiç düşündün mü

Bir zamanlar çocuk olduğunu

Sevdiğini bir zamanlar

Ya da nasıl soğuduğunu,

Ölmüş babanın ellerinin avuçlarında

Sen hiç nadasa bırakılmış düşlerinde

Kör oldun mu?', 'Sen hiç tutsak kaldın mı düşlerine Salıverdin mi umutlarını suyu çekilmiş tarlalara Bilir misin nasıl boy atar düş kırıklıkları Dönüp dururk...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kor-oldun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız Sırrı', 'kayan-yildiz-sirri-salih-mirzabeyoglu-s9pti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göklerde kanat açmış gûya gönlümce hür kuş 

Ben değil mi yine ben kedere hedef durmuş

Gizleniyor bildiğim saklambaç oyununda

Benim gölge âlemde kendisine kaybolmuş

Bu mahmurluk sırtımda kaplumbağa kabuğu

Rahatı rahatsızlık şu dünyanın seyrinde 

Ah geçmiş ne gelecek şimdiyse uçan buğu

Yollar ki bir birine kavuşmanın derdinde

Su üstünde ürperti hep gurbetlik duygusu

Nakışa düşen mânâ deniz üstünde desen

Zamanın nabzımı tutsun diye kurduğu

Dalgada gölge eşya benim gözümde de sen

Bir kayanın üstünde bilmem böyle kaç vakit 

Rüyâların izinde tâbirlerin peşinde

Yıldırım düşen levha kumaşım ki mücerret

Açıktan geçen gemi yüreğim o gemide

· · 

Tedirgin bekleyişler berzah sırrında hapis

Fikir ki saklı güzel gözümde açık derin

Pervane çeken mihrak nisbet kurduğum akis

Rüyâların ötesi müjde verdi güvercin

Ağı germiş çoktandır yıldız köşeler cinsi 

Gebe dumanlı dünya sancı sarınca doğum

Rüzgâr dinlenen dalga kıyı idrakı şimdi

Ruh nisbeti bir harman ışık içinde oyun

Kuş gagası ve dudak topluluktan işaret

Hayat sanat ve mânâ yoğunlukta bir mizân

Mağara dostluğunda doğrulanan öz hikmet 

Bütün fikir hisarı aynada duran nişân

· · · 

-''Kanıma girmiş adam işte önünde hayat!''

Uykuda uyanıklık gözü açık uykuda 

Bir ben vardım yine ben dağı delen o Ferhat

Akşam alnımda gezen hararet berrak suda

Kayan yıldız sırrı mı sırrı ile barışık

Gümüş renkte duruldu varolmak kuruntusu

Burcumun hissesinde alnındaki kırışık

Ölmek için mi doğduk asıl olmak doğrusu

Ömrün sonunda tarla marsık kokulu külhân 

Kuyu içinde çile çekmiş insan duygusu 

Deri üstünde deri yanık kokusu aman

Olan oldu dünyada kalan insan tortusu

· · · · 

Gökyüzünde bir bulut şeffaf kuyruklu balık 

Nazlı nazlı süzülür kıyısında seherin

Rüzgâr toplayan yelken hayret ve sonsuz açlık

Aşkımın şarkısında va''dolunmuş eserim

Harfi harfine uygun gözümde tek marifet 

Etle kemik bir bütün çile yükünü sırtlan

Kurtuluş gemisinin tayfasından vasiyet

Fikir elinde fikir kölen emrinde kaptan

MAYIS 1983', 'Göklerde kanat açmış gûya gönlümce hür kuş  Ben değil mi yine ben kedere hedef durmuş Gizleniyor bildiğim saklambaç oyununda Benim gölge âle...', ARRAY['Türk Edebiyatı','Şiir','Salih Mirzabeyoğlu']::text[], 8.5, '{"poet":"Salih Mirzabeyoğlu","poet_slug":"salih-mirzabeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kayan-yildiz-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşilırmak', 'yesilirmak-salih-mirzabeyoglu-dz7y3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözyaşı yüklü bulut toprak altında kaynak

Sakarya''nın derdine kıvrılır Yeşilırmak

Bizdendir onun âşkı emanet ve anahtar 

Benzerler benzeşirler zamanı işte akar

Nasıl ki Allah emri O ol deyince olur

Yeşilırmak nefsinde emre uyarken budur

Fikir aşk ve hürriyet ayrılmazlar güzelden

Sırrı malûm sırrında sözleşmişler ezelden

O ki güneşe ayna akis kapan bir görgü 

Yıldız yıldız kıvılcım yeni çağda bir örgü

İşte düğümün ucu işde insan ve toplum

Sakarya''nın kalbinde zaman ölçümü buldum

Ne varlık ne de oluş yok da yoktu bir zaman 

Ruhum eşyadan gafil ne zaman ne de zaman 

Hayat dediğin masal çırpınan suyun sesi

Tek marifet dünyada harcamamak nefesi

İmân sahici imân ateş hattında koşu

Bir günü bir gününe eş olmama buluşu

Yeşilırmak''da hamle sahibi ona kefil

Sakarya''nın ruhunu lif lif açan yeni dil

Fikir fiil ve sanat tek gaye gerçek emek

Bütün dava olmakta Allah''a görünerek

Budur insan rüyâsı gecenin yarısında 

Karayılan yelkovan ve akrep arasında

İnkılâba dayanmış saatler döne döne

Büyük Doğu bayrağı İBDA ile en öne

Mânâsını öğrenmiş kurtuluş alayları

Hakikat çevresinde şehitlik adayları

Toplum nedir bilmişler inananlar elele

Sümüklüler kovulmuş ayıklanmış hergele

-''Selam size akıncı!''-''Size selam!'' iâde

Doğruyu Allah bilir bizce tamadır vâde

1984', 'Gözyaşı yüklü bulut toprak altında kaynak Sakarya''nın derdine kıvrılır Yeşilırmak Bizdendir onun âşkı emanet ve anahtar  Benzerler benzeşirl...', ARRAY['Türk Edebiyatı','Şiir','Salih Mirzabeyoğlu']::text[], 8.5, '{"poet":"Salih Mirzabeyoğlu","poet_slug":"salih-mirzabeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yesilirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-beyhan-guler-4yaob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sende beni benim seni sevdiğim kadar

Çok seviyor musun birtanem ?

Bir gün değil, hafta değil,ay değil

Bir saat görmesen, özlüyor musun bir tanem ?

Sabahtan akşama hasretlik

Çekiyor musun bir tanem ?

Dedin ki : Evet.

İşte bir tanem mutluluğum olur o an.

Sevinçten deliye dönerim inan.

Dünyada sevmekten, sevilmekten

Kısaca, sevgiden güzel ne var ?

Yaşam sevgiyle anlamlı,

Sevgiyle bir bütün.

Ve biz birbirimizle

Bir bütünüz bir tanem..

(İstanbul, 24.11.2000)', 'Sende beni benim seni sevdiğim kadar Çok seviyor musun birtanem ? Bir gün değil, hafta değil,ay değil Bir saat görmesen, özlüyor musun bir t...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Güler']::text[], 8.5, '{"poet":"Beyhan Güler","poet_slug":"beyhan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım', 'kizim-asiye-bolkan-ecwgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerinle

Selam dedin dünyaya

Omasum bakışınla

Işık saçtın dünyama

İlk kucaklayışımda

Sana sarılışımda

Mis   gibi  kokladığımda

Selam dedin dünyama

Sana  yaşamaz dediler,

İmkansız belki bir ümit dediler,

Yalvardım yaradana,

Bağışladı seni bana.

Adını merve dedim,

Bana hediye dedim

Miniçik ellerinle okşardın yüzümü,

Küçücük yüreğinle hissederdin ananı,

Yakarırdım sana her bakışımda

Mevlama bana bağışla diye,

Sen mutluluğum canım kanım

Miniçik kızım benim,

Şimdi büyüdün yavrum,

Okulana başladın,

Benden ayrılmak istemediğinde,

Kolay değildi yavrum.

Sevgiyi hayatı öğreniyorsun,

Hataları zorlukları görüyorsun.

Okuyup yazıyorsun

Benim minik yavrucuğum...', 'Güzel gözlerinle Selam dedin dünyaya Omasum bakışınla Işık saçtın dünyama İlk kucaklayışımda Sana sarılışımda Mis   gibi  kokladığımda Selam...', ARRAY['Türk Edebiyatı','Şiir','Asiye Bolkan']::text[], 8.5, '{"poet":"Asiye Bolkan","poet_slug":"asiye-bolkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-beyhan-guler-j80oi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilerin en yücesini

Sana duydum.

Duyguların en gerçeğini,

Sende buldum.

Sendin benim havam, suyum

Nedir bilmem, tez gittin elimden.

Yapayalnız, tek başıma

Kalakaldım tek başıma

Ne bir ışık sevgiden yana

Ne bir tutacak dal umut adına.

Reva mıdır bu Tanrım bana.

(İstanbul, 24.11.2000)', 'Sevgilerin en yücesini Sana duydum. Duyguların en gerçeğini, Sende buldum. Sendin benim havam, suyum Nedir bilmem, tez gittin elimden. Yapay...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Güler']::text[], 8.5, '{"poet":"Beyhan Güler","poet_slug":"beyhan-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Yelinden', 'kasim-yelinden-stepne-sair-nf0ep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep aynı gemiler gelir ayrı yerlerden,

Huzurludur yolcuların memnun yüzleri.

Boşalırken birer, birer güvertelerinden,

Çığlık çığlığa bağrışan çocuk sesleri.

Farklı bir yerden gelen bir gemi benimdir,

Yelkeni kasım yelinden.

Hep aynı kadınlardır çapkın gülüşleri,

Kim bilir, kimlere ne umutlar dağıtır.

Sallanan bir mendil, ya da veda mimikleri,

Kimine yürek dolusu acı yaşatır.

Farklı bir dünyadan gelen bir kadın benimdir,

Saçları Kasım yelinden.

Ne lodoslar eser, kabına sığmaz Marmara.

Bir kar fırtınasında amansız köpükler,

Lodos çağırır beni azgın dalgalara,

Tutarım kendimi, tüketilmedikçe düşler.

Farklı bir zamandan esen bir lodos benimdir,

Köpükleri Kasım yelinden.

Şen kahkahalara karışır piyano sesleri.

Su gibi içer parmaklar abanoz tuşları,

Bin bir ses içinde de olsa tanırım o sesi,

Usta parmaklardan dökülen vuruşlarını.

Farklı bir piyanoda gezen o parmaklar benimdir,

Uçları Kasım yelinden.', 'Hep aynı gemiler gelir ayrı yerlerden, Huzurludur yolcuların memnun yüzleri. Boşalırken birer, birer güvertelerinden, Çığlık çığlığa bağrışa...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kasim-yelinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Burda Bulursun', 'beni-burda-bulursun-vasif-senturk-31u5l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle ilk karşılaştığımızda

Ne ay''ın yalancı parıltısı vardı yüzünde

Ne de güneşin yakıcı sıcaklığı

Yinede öylesine aydınlatıyor,ısıtıyordun ki 

Ortalığı

Seni görmemek,görüpte ısınmamak,mümkün müydü?

Gözlerinde yakamozları vardı durgun denizlerin

Kalbinde ise çoşkun fırtınaları kopuyordu

Okyanusların.

Sen se kaptansız bir gemi misali,

Başı boş dolaşıp duruyordun.

Sana kollarımı açtım

Senin için boşalttım yüreğimi

Kulaklarımı kuş cıvıltılarına tıkadım.

Sadece seni duyayım seni yaşayayım diye.

Hiç tereddüt etmedin

Limana girerken,

Sormadın başka gemileri

Tek tayfanla yanaştın rıhtıma

Safralarını boşalttın kara bahtıma

Fazla kalmam diyordun önceleri,

Kaptanım gelir gelmez giderim diyordun;

Senin hiç kaptanın olmadı

Hiç olmayacakta belli.

Liman senin güzel gemi, istediğince kal

Sana kaptan olamam belki

Ama istersen canımı al

O can ki senin için çıkar

Gözünü kırpmadan

Senin için yaşadı çünkü

Seni hiç tanımadan

Ama sen alışmışsın özgürce gezmeye

Bende takat kalmadı enginlerde yüzmeye

Duydum gidiyormuşsun bırakıp bu limanı

Sakın unutma gülüm senle yaşam bulanı

Hadi git güle güle özgürlük yolun olsun

Eğer geri dönersen

BENİ BURDA BULURSUN.

                           (Mersin-17.09.1995)', 'Seninle ilk karşılaştığımızda Ne ay''ın yalancı parıltısı vardı yüzünde Ne de güneşin yakıcı sıcaklığı Yinede öylesine aydınlatıyor,ısıtıyord...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/beni-burda-bulursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçemez miyim', 'i-cemez-miyim-vasif-senturk-54fqw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güzelle karşılıklı oturup

İki kadeh rakı içemez miyim?

O güzeli dizlerime yatırıp

İki kadeh rakı içemez miyim?

Varıp ta otursam dost meçlisine

Bana sorarlar mı gelişin niye

Badeyi kaldırıp şerefe diye 

İki kadeh rakı içemez miyim?

Bir elimde kadeh yanım da güzel

Bazen türkü söyler bazen de gazel

Bunları severim ben ebet ve ezel

İki kadeh rakı içemez miyim?

Vasıf''ı yüreğin yara derinden

Vazgeçmem bunlardan,geçer serimden

O güzelin dudağından,elinden

İki kadeh rakı içemez miyim?

                          (  Mersin-03.11.1994)', 'Bir güzelle karşılıklı oturup İki kadeh rakı içemez miyim? O güzeli dizlerime yatırıp İki kadeh rakı içemez miyim? Varıp ta otursam dost meç...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/icemez-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşmalar', 'kosmalar-sair-uzaklar-wqaxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koyup gönlümü dilime     

yollara seresim gelir  

Bana kıyan sevgilime   

Onuda veresim gelir      

Duygumun bu son dönümü      

Çevirmem artık yönümü     

Gözüm kapatsada önümü        

Sonuna varasım gelir     

Gün çanağını kırasım  

kara yeli durdurasım     

Deniz gibi kabarasım     

Dağları deviresim gelir      

Düşüncemde ağır yükler     

Ciğerimde kötülükler       

Ağzımda kızıl köpükler    

Yoluna seresim gelir  

Ne ola bu işte suçum     

Sığmıyor kabına içim    

Elimde bir tutam      

Toprağa giresim gelir', 'Koyup gönlümü dilime      yollara seresim gelir   Bana kıyan sevgilime    Onuda veresim gelir       Duygumun bu son dönümü       Çevirmem ar...', ARRAY['Türk Edebiyatı','Şiir','Şair Uzaklar']::text[], 8.5, '{"poet":"Şair Uzaklar","poet_slug":"sair-uzaklar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kosmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan ki Hasreti Kadar', 'i-nsan-ki-hasreti-kadar-nihat-behram-8zmqg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşksa:

Sağır da olsa dile döner seslenir...

Düşse:

Eni sonu suya düşer ıslanır...

Aşktan öte başka hangi tohum yeşerir

Hangi dal sügün verir ezildiği yerinden? 

      (...Dolunaydı...Dağların bulutlandığı,

      toprağın yoncalandığı aydı...Öpsem,

      yaralanır sandığım

      çiçekler kadar körpeydi bahar...

      Bir yanım sazınca külhan,

      yağız,civan,atmaca; 

      bir yanım nazınca uslu,

      suskun,ıssız,utangaç,

      savrulup savrulup sokaklara

      söylediğim şarkılar

      süsüydü ömrümüzün,

      yitince bulunmaz zenginliğimiz...

      Ne güzel günlerdi ah

      ne güzeldin gençliğim; 

      gönlümü tarih düşüp

      ömrümce yol gözledim,

      yazık ki sen beklemedin...) 

İki derde yenik düştüm ne çare:

biri aşk

biri düşten düşe sızım sızım yüreğim...

Taşa çaldım derdimi,

taş çatladı kıvrım kıvrım kök verdim; 

güle sardım kendimi,

gül kurudu derdim azdı yürüdü...

İnsan ki hasreti kadar:

belki bin sevda bin ayrılık

fakat

bir aşk bir intihar

bir ömre ancak sığar.', 'Aşksa: Sağır da olsa dile döner seslenir... Düşse: Eni sonu suya düşer ıslanır... Aşktan öte başka hangi tohum yeşerir Hangi dal sügün verir...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/insan-ki-hasreti-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin', 'derin-hakan-sengorun-uyxlj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim çağırıyor sesini paramparça sessizliğe

Düşlerim savaşıyor uykumla gecenin içinde yorgunluğu zamanın

Her bakışına bir kelime kondu 

Karanlıklar var oldu içimde

Sesine sığındım içimdeydi bilemediğim yollar

Gittikçe küçüldü gece gün ağladı gökyüzünde

Ellerin çağırıyor sesimi kayboluyorum sessizliğinde

Bir bulut kırılıyor ışık saçan damlalar düşüyor karanlığa

Gözlerim kamaşıyor ıslaklığında dokundum yağmura

Gülücüğün olsun son sözün

Sesin saklı kalsın düşlerimde

Yaşanmaktan eskimiş anların sarsıntıları yaşattı bu şehrin hüznünü

Yaşadıkça yeniledi acımı

Bakışlarından uçtu kelimeler uzaklara

Bir DERİN dumana boğuldu baktığında

Hüznün zehrini akıttı kanıma

Düşündün gökyüzünü sonunu bulamadın

Sesler yaptım şarkıma duydun hüznümü yaşamaya yetmedi ruhun sevdamı

Bırak kendini içine beni bulsun her ölümde

İnanmak zor gerçeğe bu yüzden yalan söyler mutlulukların

Asil bir karanlığı sahte bir aydınlık kaplar ama saklayamaz DERİNDEKİ yok oluşları......', 'Ellerim çağırıyor sesini paramparça sessizliğe Düşlerim savaşıyor uykumla gecenin içinde yorgunluğu zamanın Her bakışına bir kelime kondu  K...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/derin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüne Ulaştığımda', 'gokyuzune-ulastigimda-reyhan-sendil-euz9p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni çıkmaza sürükleyen

Kendince doğru olduğuna inandığın

Anlamı olmayan her tepkinde

Benim tüm yaptılarım adına

Manasız fikirler doğrultusunda

Hiç anlaşılamayan yaklaşımlarında

Seninle bütünleşen anlamsız inatlarınla

Yırtıp tükettiğin benim kitaplarım gibi

Benim ömrümden her sayfayı tüketişinde

Tüm yaşama sevinçlerimi

Acımasızca yok etmek istercesine

Sana olan sevgimi anlayamamışlığınla

Birlikte yaşama anlamını yok edişin gibi

Herzaman gülmeyi unutmuş halinle

Hep büyük hedefler peşinde koşarken

Bu hedefler arasında kaybolmuş bana

Hala senin doğrularını anlatmaktaysan

Bunları duymaktan sağır olmuş kulaklarım

Bu kadar yıpranmışlıktan sonra bile

İlk defa, en doğru olduğuna inandığı

Kendi gerçeklerimin içinden gelen

Gayet net bir duyumla

Bu ses anlatımında

Seninle bunca yaşanmışlığı

Yaşlı gözlerin derinliklerinde bırakıp

Gökyüzüne ulaştığımda ben,

Özgür ve mutlu olacağım', 'Beni çıkmaza sürükleyen Kendince doğru olduğuna inandığın Anlamı olmayan her tepkinde Benim tüm yaptılarım adına Manasız fikirler doğrultusu...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Şendil']::text[], 8.5, '{"poet":"Reyhan Şendil","poet_slug":"reyhan-sendil","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gokyuzune-ulastigimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Yıl Önce Gel', 'on-yil-once-gel-gonca-aydemir-mcmt6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi git kırçiçeğim,on yıl önce gel

Ben o duyguları çoktan tükettim

Ne var ne yoksa sevgiden yana

Har vurup harman savurdum 

Mirasyedi misali

Tükenmez sanmıştım heyhat!

Mevsimi geçti fasl-ı baharın

Şimdi git kırçiçeğim

Elinde bir demet gülle on yıl önce gel

Yokuşlar daha yokuş

Geceler daha uzun artık

Kızıl akşamları seyrediyorum tek başıma

Kanım kaynamıyor köçekçelerde

Kahkaha atmayalı asırlar oldu

Ağır ağır kar yağmakta şakaklarıma

Haydi git kırçiçeğim

Sevgi dolu bir gönülle

ON YIL ÖNCE GEL!', 'Şimdi git kırçiçeğim,on yıl önce gel Ben o duyguları çoktan tükettim Ne var ne yoksa sevgiden yana Har vurup harman savurdum  Mirasyedi misa...', ARRAY['Türk Edebiyatı','Şiir','Gonca Aydemir']::text[], 8.5, '{"poet":"Gonca Aydemir","poet_slug":"gonca-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/on-yil-once-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Biçiyorum', 'yalnizliklar-biciyorum-riza-aslan-lh16n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnızlıklar biçiyorum 

kendimce

boy boy

beden beden', 'yalnızlıklar biçiyorum  kendimce boy boy beden beden...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizliklar-biciyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişik Zamanlar', 'degisik-zamanlar-umit-yasar-oguzcan-n1l2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '18.45 

En geç yediye çeyrek kala evdeyim 

Ben gelene kadar bütün üzüntülerinden kurtulmalısın 

Borcumuz varmış, derdimiz varmış düşünme 

Ümitsizlik fakirlerin harcı değil 

Saksının yerini değiştir 

Göreceksin daha güzel olacak 

Aç pencereyi odamız havalansın 

Sonra mutlu geceleri düşün sabahları değil 

Gelir gelmez sarıl boynuma, öp beni 

Geçsin bütün yorgunluğum dudaklarında 

Doldursun yatakları aşkımız 

Biz de insanız elbet Tanrı Değil. 

22.30 

Seni bir güzel öpmeliyim önce 

Dudaklarımın nelere kaadir olduğunu anlamalısın 

Sonra sen istemelisin yatağı 

O baygın başdönmesini 

O tatlı yorgunluğu 

O ölüp ölüp yeniden var olmayı 

Yatağımız büyük olmalı büyük 

Bir odayı doldurmalı kucaklaşmamız 

Kırmızı ışığı sevmem 

yeşil bir ampul yanmalı abajurda 

Dışarısı alabildiğine karanlık olmalı 

Senin mutlu aydınlığına inat 

Ve ben sabahın ilk ışıkları altında 

Seni bir kere daha sevmeliyim. 

7.15 

Beni 7.15 de uyandır 

Akşamdan kur saati uyuyup kalmayalım 

Zamanlar içinde en güzel sabah çayı 

Sonra giyinip traş olmalıyım 

Artık ayrılmalıyız, üzülme 

Göreceksin akşam çabuk olacak 

Haydi gülümseyerek uğurla beni 

Son otobüse yetişmeliyim.', '18.45  En geç yediye çeyrek kala evdeyim  Ben gelene kadar bütün üzüntülerinden kurtulmalısın  Borcumuz varmış, derdimiz varmış düşünme  Ümi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/degisik-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin II', 'senin-i-cin-ii-ali-riza-erdem-1x821', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kaderinde kaçamayacağını anladığında

esen rüzgarlarlara kokunu bırak

ve düşünde gör beni

sevdanı yüreğimin ortasına kondur bir kuş gibi

elinin sıcaklığını değsin yüzüme

rakkas eden umut perileri ile birlikte', 'kaderinde kaçamayacağını anladığında esen rüzgarlarlara kokunu bırak ve düşünde gör beni sevdanı yüreğimin ortasına kondur bir kuş gibi elin...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/senin-icin-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orhan Veli', 'orhan-veli-erkan-candogan-efei6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine aklıma sen geldin Orhan Veli.

Seni de aşk değil miydi şair yapan,

Ya geçim derdi...

Çok şükür çekmiyorum ama

Ben de aşığım senin gibi...', 'Yine aklıma sen geldin Orhan Veli. Seni de aşk değil miydi şair yapan, Ya geçim derdi... Çok şükür çekmiyorum ama Ben de aşığım senin gibi.....', ARRAY['Türk Edebiyatı','Şiir','Erkan Candoğan']::text[], 8.5, '{"poet":"Erkan Candoğan","poet_slug":"erkan-candogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/orhan-veli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-erkan-candogan-lzigr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel uzan boylu boyunca

Koy başını dizlerime.

Ve ben o güzel saçlarını 

Saatlerce okşayım...

Hemencecik uyuma.

Mırıldansın dudakların,

Aşkımızı anlatsın bir bir.

Ben sadece ve sadece 

Seni dinleyim...

Bir vakit uyuduğunda,

Usulca kucaklayıp seni,

Yatırayım yatağına.

Bir minicik öpücük kondurup dudağına,

Üstünü örteyim...

İnan ki bu,

Hayattaki tek dileğim...', 'Gel uzan boylu boyunca Koy başını dizlerime. Ve ben o güzel saçlarını  Saatlerce okşayım... Hemencecik uyuma. Mırıldansın dudakların, Aşkımı...', ARRAY['Türk Edebiyatı','Şiir','Erkan Candoğan']::text[], 8.5, '{"poet":"Erkan Candoğan","poet_slug":"erkan-candogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgi', 'cizgi-ozdemir-asaf-6x21t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendimi sileceksem, bilirim sende varım.

Senin ben yarısıyla seni ben tamamlarım.

Seni sende bütünler, sana sende inanır,

Seni sende silerim, seni bende yazarım.', 'Kendimi sileceksem, bilirim sende varım. Senin ben yarısıyla seni ben tamamlarım. Seni sende bütünler, sana sende inanır, Seni sende silerim...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cizgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlarda Yağmur', 'daglarda-yagmur-unal-gul-kh0ef', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlarda yağmurun sesine eşlik eden rüzgarın sesi

İşte doğanın senfonisi

Seni özlüyorum.

Başımı kaldırıyorum gökyüzüne

Gözlerimi kapıyorum.

Güneş gibisin.

Güzel koca gözlerinle 

Gülümsüyorsun.

Kokunu duyuyorum.

Ormanda sonbahar kokularının arasından. 

Gülümsüyorum.', 'Dağlarda yağmurun sesine eşlik eden rüzgarın sesi İşte doğanın senfonisi Seni özlüyorum. Başımı kaldırıyorum gökyüzüne Gözlerimi kapıyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Gül']::text[], 8.5, '{"poet":"Ünal Gül","poet_slug":"unal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/daglarda-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yörük', 'yoruk-su-prensesi-2ijk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YÖRÜK

Şehre indiğinde

1.

Sevmekten nefret ediyorum

Çünkü;

Sevmeyi bilmiyorum

2.

Ben sevmeyi bilmiyorum

Sevgiye aç büyümüşüm 

Büyümüşüm inmişim şehre 

Şehir benden de aç sevgiye

Sevgi denmiş o sıcak duyguya 

Sonra sevgiyi şekillendirip 

	çıkarmışlar ortaya 

Adını aşk koymuşlar

Özelliklerini sıralamışlar

Anidir;

Birden çıkar ortaya,

Birden yaşanır,

Birden kaybolur.,

Aşk kendinin yakıp,

Kendinin söndürdüğü 

Bir ateşimsi duyguymuş,

Doğumu da ölümü de

Senin elindeymiş

Şehirde 

Şehir beni 

Aşkla doyurmaya çalıştı

Ama 

Yeni doğan bebek nasıl muhtaçsa 

	annesinin beyaz sütüne

Ben de öyle muhtaçtım

O sıcak sevgiye

Elinde kalmamıştı belki de

Belki de benden önce de yoktu

Elindekiyle doyurmak istedi

O ölümsüz duyguyla değil de

Aşkla

Ölümü de doğumu da 

	senin elinde olan aşkla

Bense sevgiye açtım

Açtım ellerimi şehre

Bana biraz sevgi versin diye

Bana “hiç” verdi...

25.11.2000', 'YÖRÜK Şehre indiğinde 1. Sevmekten nefret ediyorum Çünkü; Sevmeyi bilmiyorum 2. Ben sevmeyi bilmiyorum Sevgiye aç büyümüşüm  Büyümüşüm inmiş...', ARRAY['Türk Edebiyatı','Şiir','Su Prensesi']::text[], 8.5, '{"poet":"Su Prensesi","poet_slug":"su-prensesi","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yoruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Irmağa Benzer', 'i-nsan-irmaga-benzer-suleyman-avci-4j1df', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'herkes 

kendi payına düşen 

sularda köpürsün 

köpürsün 

görücüye çıkmıs baharın dallarında

tüneyen akşam güneşi 

sen 

çığlıklarını döve dur güzelim 

ben yine azar azar gelirim 

köpürmeyi 

en az senin kadar 

ben de bilirim', 'herkes  kendi payına düşen  sularda köpürsün  köpürsün  görücüye çıkmıs baharın dallarında tüneyen akşam güneşi  sen  çığlıklarını döve dur ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-irmaga-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilen Vardır Elbet', 'bir-bilen-vardir-elbet-suleyman-avci-gzfx0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gezegenlerin bile birleştiği çağda 

hızla insandan uzaklaşıyoruz 

dilimiz uyuşmus alkole batıp çıkmaktan 

uyuşmuşuz 

kısa cümleler kurmaktan 

söyle usta 

pişmek için ne kadar yanmak gerek 

yaşam fırınında 

dünya 

kavgadan uzak büyütülüyor 

sokaklarda', 'gezegenlerin bile birleştiği çağda  hızla insandan uzaklaşıyoruz  dilimiz uyuşmus alkole batıp çıkmaktan  uyuşmuşuz  kısa cümleler kurmaktan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-bilen-vardir-elbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıktan Kaçmak', 'yalnizliktan-kacmak-suleyman-avci-5rz9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman geceydi

Yalnızlık geçiyordu bulutlardan

Gurbet gelme üstüme

Gidecek yurdum yok

Yağmurlar da ıslanan

Sırılsıklam bir kent kokuyordu yanakların

Hep uzun menziller de sevdim

Hayatı ve seni

Her bulutun ardından

Bakakalır gözlerim

Sonbahar altında kalmadan düşlerim

Gel kaçır beni bu yalnızlığımdan', 'Zaman geceydi Yalnızlık geçiyordu bulutlardan Gurbet gelme üstüme Gidecek yurdum yok Yağmurlar da ıslanan Sırılsıklam bir kent kokuyordu yan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizliktan-kacmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-mehmet-soral-qch8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş, son nefesini vermek üzere,

kaydı penceremin önünden aşağı.

Nazlı gelin edalı, akşam karanlığı, 

Olmayacak sabahın habercisimi acep?

Ölüm, sanki karşı kapının arkasında,

Göz kırpıp kırpıp kaçıyor bana,

Hem arzulayan, hem naz yapan

Bir sevgili misali, içimi yakıyor.

Şıngır mıngır bir sedye sesi koridorda,

Belki bir yaşam geliyor, belki de gidiyor

Bir telaş ki ama ne telaş

Uçuşuyorlar sanki, başucumda sedyeler.

Haydi git öteye, ne olur ölüm!

Yarın oğlumun yaş günü de var.

Karım gelecekmiş ziyaretime,

İnce parmaklarıyla sarılmış

Sarma getirecekmiş bana.

Kokusuna hasret, nefesine muhtacım.

Bırak beni ölüm bir sabahlık kadar.

Ekim, 2000', 'Güneş, son nefesini vermek üzere, kaydı penceremin önünden aşağı. Nazlı gelin edalı, akşam karanlığı,  Olmayacak sabahın habercisimi acep? Ö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Soral']::text[], 8.5, '{"poet":"Mehmet Soral","poet_slug":"mehmet-soral","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ucundan', 'gecenin-ucundan-arzu-dincer-0ss66', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde yüzülesi bir aksam,

Ve adacıklar halinde yıldızlar

Kulaç atasın geliyor kuyruklu yıldıza dogru,

Bir uğrayıp küçük prens''e,

Gül''üne bakmak

Ve yanlızlığını paylasmak yanlızlığımla,

Maviye çalan siyahtan bir şal yapmak,

Ve uzaklara yittiğini unutan ışınlardan taç...

Venüs bir balo düzenliyormuş bu akşam,

Kolumda Mars ..

İnsanlar yıldız olmuş bu gece...

Uçuyor hayattan sıyrılmış gerçeklikleri ile...

Gecenin ucundan atlıyorum,

Yaşama yaşam kıyısında bir filika...

Yanlızlığımı alıyor önce,

Sonra beni....', 'Gökyüzünde yüzülesi bir aksam, Ve adacıklar halinde yıldızlar Kulaç atasın geliyor kuyruklu yıldıza dogru, Bir uğrayıp küçük prens''e, Gül''ün...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-ucundan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Kadın', 'aglayan-kadin-aslihan-erdal-x26jl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kadın tanıdım Ankara’nın sisli havasında,

Kızılay’ın ortasında bir elinde şarap,bir elinde sigarasıyla

Bir bank da oturup ağlıyordu;haykırırcasına...

Yüzünde acının izleri vardı çizgi çizgi,

Bir şarkı mırıldanıyordu titrek sesi;

“Elveda,Elveda Ey Sevgili...”

Cebinden bir resim çıkarttı ;

Biraz eski,biraz yırtıktı.

Öptü,kokladı,bağrına bastı,

Anladım ki yüreği yastaydı.

Resme baktıkdan sonra gözlerini yıldızlara dikti.

Usulca “Acaba bunlardan hangisisin?”dedi,

Elinde sarı renkli bir kağıt belirdi,

Ve onu bankın üzerine bırakıp gitti.

Koşup aldım bıraktığı kağıdı,

Büyük bir merakla okumaya başladım yazıları

“Ey benim hasret kokan çiçeğim”diye başlıyordu

Ve şöyle devam ediyordu:

Eğer birgün seni bu dikenli yollarda,

Yalnız başına bırakırsam kızma bana;

İstemezdim bu mektubu vermeyi sana,

Bir hastalık bulmuş beni yaşamın ortasında acımasızca,

Söyleyemedim kimselere,sanki korkarcasına.

Korkuyorum hasret kokan çiçeğim;

Ölümden değil,sensizlikden korkuyorum,

Seni bulmuşken,kaybetmekden korkuyorum.

Seni çok ama çok seviyorum,

Herzaman yanındayım bunu bilmeni istiyorum.

Not:Yukarıdan hep seni izleyeceğim,sakın beni unutma meleğim...

Diye biten bir mektupdu bu.

Kafamı kaldırıp gökyüzüne baktım;

Bir yıldız  kaydı.

Oturduğum bankdan kalktım,

Herşey olduğu gibi kalmalıydı.

Mektubu katladım,bankın üzerine bıraktım.

Tam o sırada siren seslerinin farkına vardım,

Ambulans biraz öteye yanaştı;

Anlaşılan bir kişi daha hayata gözlerini kapatmıştı.

Ama tek bir fark vardı,

O kişi;

Az önce mektubunu okuduğum,

Yüzünde acının izleri olan

Ve ölürken bile ağlayan kadındı...', 'Bir kadın tanıdım Ankara’nın sisli havasında, Kızılay’ın ortasında bir elinde şarap,bir elinde sigarasıyla Bir bank da oturup ağlıyordu;hayk...', ARRAY['Türk Edebiyatı','Şiir','Aslıhan Erdal']::text[], 8.5, '{"poet":"Aslıhan Erdal","poet_slug":"aslihan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/aglayan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Fırtına', 'i-cimdeki-firtina-aslihan-erdal-t5xrj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binbir umutla çıkmıştım mutluluk yolculuğuna,

Yanıma aldığım tekşey sendin;

Önümdeki o karanlık dalgaları,

O geçilmez dalgaları seninle aşacaktık oysa...

Canımı hiçe saydım uğrunda,

Geceler boyu beni korkutan rüyalarımda;

Sen yoktun yanımda!

Beni benimle yalnız bırakıp gitmiştin

O korkunç okyanuslarda...

Beni duyan kimse yoktu etraflarda,

Bağırıyordum,

Haykırıyordum,

Yanımda biri olsun istiyordum.

Ama nafile;mutluluk uğruna herşeyimi feda etmiştim,

Arkadaşlarıma,dostlarıma senin için veda etmiştim.

Anladım ki artık herşeyimi kaybetmiştim,

Ben yarınları kirlettiğim gibi hatıraları da katletmiştim,

Böyle olmasını inan hiç istememiştim,

Ama hiç kimseyi delicesine sevmemiştim. 

Bunları düşündükce o karanlık sular aydınlanır gibi oldu,

Sanki doğru yol o suların içinden geçiyordu,

Ayağa kalktım,gözlerimi kapattım ve kendimi suya bıraktım;

Biran kendimi bulutların üstündeyim sandım...

Gözlerimi açtım,hertaraf karbeyaz,

Ama bir tuhaflık var;bu mevsim yaz...

Ben daha dün o korkunç fırtınayı yaşıyordum,

Allah’ım ne oldu bana?bu bedeni nerede taşıyorum?

Korkuyorum,hemde çok...

Anladım ki ben artık bedende de yaşamıyorum.

Atlatmıştım o koca fırtınayı yine tavizler vererek

Öyle bir taviz ki bu;hayata veda ederek...

Sağlam çıkartamazdım bedenimi o dipsiz girdaplardan,

İyi dinle hiç duymadın;BU SON VEDALARDAN...

Hoşcakal Tatlı Çocuk,sakın üzülme benim için,

Gam yedim seni mutlu edemediğim için,

Yaptığım herşey senin içindi birtek senin için,

Sakın bir damla gözyaşı bile akıtma bu garip FANİ için...', 'Binbir umutla çıkmıştım mutluluk yolculuğuna, Yanıma aldığım tekşey sendin; Önümdeki o karanlık dalgaları, O geçilmez dalgaları seninle aşac...', ARRAY['Türk Edebiyatı','Şiir','Aslıhan Erdal']::text[], 8.5, '{"poet":"Aslıhan Erdal","poet_slug":"aslihan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/icimdeki-firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi', 'hadi-aslihan-erdal-qi753', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim ağlamakta,

Yüreğim kanamakta,

O gidiyor acımasızca,

Daha yaşanacak ne çok şey vardı oysa...

Gitme desem bu aşk uğruna,

Kalamaz mısın sevgilim?

Yaşananlar adına son bir şans,

Veremez misin sevgilim?

Seni delicesine seven bu kalbi,

Affedemez misin sevgilim?

Beni benimle yalnız bırakıp: GİT HADİ!!! 

Arkana sakın bakma; ÇEK GİT HADİ!!!

Hatıraları da almayı unutma:HEPSİNİ SİL,SİL HADİ!!!

Beni tamamen çıkart hayatından:YAPABİLİRSEN YAP HADİ!!!', 'Gözlerim ağlamakta, Yüreğim kanamakta, O gidiyor acımasızca, Daha yaşanacak ne çok şey vardı oysa... Gitme desem bu aşk uğruna, Kalamaz mısı...', ARRAY['Türk Edebiyatı','Şiir','Aslıhan Erdal']::text[], 8.5, '{"poet":"Aslıhan Erdal","poet_slug":"aslihan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-vasif-senturk-6217k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu karanlık sürmeyecek

Benim ülkeme de güneş doğacak

İnsanların içi ısınacak

Açacaklar gözlerini

Ve uyanacaklar

Bir gün

Bahçelerde çiçekler açacak

Şakıyan bülbüller

Kafese konmayacak

Polisler kelepçe kullanmayacak

Çoşkun suların önlerine 

Bendler yapılmayacak

Okulların etrafı

Dikenli tellerle çevrilmeyecek

Alabildiğine oynayacak

Uzun saçlı çocuklar

Geceleri siren sesleri bölmeyecek

Uykularını

Ve sabah olacak 

Bir gün

 (Adıyaman-02.10.1988)', 'Bu karanlık sürmeyecek Benim ülkeme de güneş doğacak İnsanların içi ısınacak Açacaklar gözlerini Ve uyanacaklar Bir gün Bahçelerde çiçekler ...', ARRAY['Türk Edebiyatı','Şiir','Vasıf Şentürk']::text[], 8.5, '{"poet":"Vasıf Şentürk","poet_slug":"vasif-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Meselesi', 'ask-meselesi-atilgan-alemdar-mtyaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o kız değil benim sevdiğim

uykularımı giyen,sonbahardır

gözleri mavi,elleri beyaz

hayâlden öte bir kuğu vardır

sarı demem saçlarına,gücenir

omzunun üstünde güneştir yükselir

her gece karanlığıma bilenir

ağzında güllü bir buğu vardır

ben azalırım,o,çoğalır içimde

ufuksuz denizdir dikilir önümde

yaşamayı imkânsız kılan kalbimde

öldürmek bilmez bir ağu vardır

o kız değil benim sevdiğim

yıldızların içinde bir muammâ

uzak diye az sevdim derdim,ama

aşkın azı yoktur,çoğu vardır.', 'o kız değil benim sevdiğim uykularımı giyen,sonbahardır gözleri mavi,elleri beyaz hayâlden öte bir kuğu vardır sarı demem saçlarına,gücenir ...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-meselesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mine', 'mine-atilgan-alemdar-uhfot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mine benim çiçeğimin adı

şimdi solmuş olsa bile....

toprağı susuz kaldı,susuzluk onu aldı

...şimdi yok...

sonbahar ne kadar yağmur yolsa bile

giden bir insan gibi,mecbur

uykusuzluğum gibi mahurdu...

bir mevsim bahçemde durdu

şimdi yok,hatıramda kalsa bile

ben biliyordum,solacaktı zaten

o kadar sağlam bakışları yoktu

kötü gün dostu değildi,bazen

habersiz düş kapımı çalsa bile

mine benim çiçeğimin adı....

çiçeğim mine midir bilmem...

hem çiçek soldu fakat mine''m

solmadı yıllardır bende kaldı

...bir çiçek vardı 

bana mine''mi hatırlatırdı

şimdi sadece bir mine kaldı

o solmuş çiçeği hatırlatan', 'mine benim çiçeğimin adı şimdi solmuş olsa bile.... toprağı susuz kaldı,susuzluk onu aldı ...şimdi yok... sonbahar ne kadar yağmur yolsa bil...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaram Dedim', 'yaram-dedim-sabit-i-nce-ro6xp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaram dedim, yaram dedim,

Aç kalbini yaram dedim.

Bir Şirin için Ferhat’a ,

Gel dağları yaram dedim...', 'Yaram dedim, yaram dedim, Aç kalbini yaram dedim. Bir Şirin için Ferhat’a , Gel dağları yaram dedim......', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaram-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara da', 'ankara-da-sabit-i-nce-u77pd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki güzel dostu buldum,

Ankara da, Ankarada.

Aradığım postu buldum,

Ankara da, Ankarada.

Dosta açık kapıları,

Mükemmeldir yapıları,

Olmasa da tapuları,

Ankara da, Ankarada.

İsmail Yusuf misali,

Hüseyini güzel timsali.

Olmaz menendi emsali,

Ankara da, Ankarada.

Muhabbettir sevdaları,

Engindir gönül bağları,

İnsanlıktır davaları,

Ankara da, Ankarada.

Kelimeler kısır kalır,

Sevgi satar gönül alır,

İnce’ler kıymetin bilir,

Ankara da, Ankarada.

20.9.2000 Ankara yolu', 'İki güzel dostu buldum, Ankara da, Ankarada. Aradığım postu buldum, Ankara da, Ankarada. Dosta açık kapıları, Mükemmeldir yapıları, Olmasa d...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ankara-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İSEN', 'i-sen-sabit-i-nce-gvj84', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İSEN

Kainatda ayna benim,

Gel gör, görebilir isen.

Gökte uçan turna benim,

Gel al, alabilir isen.

Ne ararsan hepsi bende,

Arama, bulunmaz tende.

Bir eksiklik var mı sende,

Gel bul, bulabilir isen.

Tevratı yazan da benim,

İncil’i dizen de benim.

Miraç da gezen de benim,

Gel bil, bilebilir isen.

Kuran’da konuşan benim,

Havvayla buluşan benim.

Topraktan oluşan benim,

Gel ol, olabilir isen..

İnce’yim buluşan benim,

Dost olup bilişen benim.

Kalmaya çalışan benim,

Gel kal, kalabilir isen.

20.9.2000 Ankara yolu.', 'İSEN Kainatda ayna benim, Gel gör, görebilir isen. Gökte uçan turna benim, Gel al, alabilir isen. Ne ararsan hepsi bende, Arama, bulunmaz te...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/isen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Gel', 'oyle-gel-sabit-i-nce-absk8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanırsan yaradana,

Cemalini gör öyle gel.

Mezarda cansız yatana,

Ahvalini sor öyle gel.

Aşkin kemendin boynuna,

Dolamışsan sar öyle gel.

Sevdalıysan yar koynuna,

Başin koyup gir öyle gel.

Eğer sakiyim diyorsan,

Aşk badesin ver öyle gel.

Dost dost diye soruyorsan,

Canı yola ser öyle gel.

Hakkın gerçek aşığıysan,

Yüzün pir''e sür öyle gel.

İNCE sevgi kaşığıysan,

Açlara bir sor öyle gel.

 23.4.1996', 'İnanırsan yaradana, Cemalini gör öyle gel. Mezarda cansız yatana, Ahvalini sor öyle gel. Aşkin kemendin boynuna, Dolamışsan sar öyle gel. Se...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyle-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim köyüm', 'benim-koyum-sabit-i-nce-cf4yv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Temiz havasını alamasam da, 

Memet emmimizi bulamasam da, 

Şimşir kaşığımı yalamasam da, 

Kayseri de uğrak yerimdir KÖYÜM.

Köyüm köyüm benim köyüm, 

Köyümü nasıl söylüyüm.

Sediri var otururum dostlarla, 

Dedesi kalmamış koyun postlarla, 

Karşılaşmam asla orda astlarla, 

Kayseri de uğrak yerimdir KÖYÜM.

Köyüm köyüm benim köyüm, 

Köyümü nasıl söylüyüm.

İNCE anlatamaz köyü, köylüyü, 

Orada bulursun selvi boyluyu, 

Bulmak isterisen güzel huyluyu, 

Kayseri de uğrak yerimdir KÖYÜM.

Köyüm köyüm benim köyüm, 

Köyümü nasıl söylüyüm.

			

SABİT İNCE', 'Temiz havasını alamasam da,  Memet emmimizi bulamasam da,  Şimşir kaşığımı yalamasam da,  Kayseri de uğrak yerimdir KÖYÜM. Köyüm köyüm benim...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benim-koyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakiler', 'bakiler-sabit-i-nce-mhyt9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hem Yavuzdur, hem Bülent’tir, Bâkiler,

Haz vermiyor, bâde sunan Sâkiler...

Kim ne kadar uğraşsa da çare yok,

Sancağı taşırlar, Bülent, Bâkiler...

20/9/2000 Ankara Yolu Sabit İnce', 'Hem Yavuzdur, hem Bülent’tir, Bâkiler, Haz vermiyor, bâde sunan Sâkiler... Kim ne kadar uğraşsa da çare yok, Sancağı taşırlar, Bülent, Bâkil...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bakiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Kolaymış', 'cok-kolaymis-sabit-i-nce-phmb7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aldım elime kalemi,

Çok kolaymış şiir yazmak.

Karıştırdım el-alemi,

Ne kolaymış şiir yazmak.

Süslü kelimeler dizdim,

Kolaycacık bade ezdim.

Okudukça candan bezdim,

Ne kolaymış şiir yazmak.

Hece tamam kafiye hoş,

Kelime çok, manası boş,

Yürü kaf dağınaca koş,

Ne kolaymış şiir yazmak.

Has bahçede güller bitir,

Şakıyan bir bülbül getir,

Kendin sırça köşkte otur,

Ne kolaymış şiir yazmak.

Yoksulluğu sakız eyle,

Aşk, aşk diye türkü söyle,

İşte bizim şiir böyle,

Ne kolaymış şiir yazmak.

Ne bulduysan kelime diz,

İçine koy süslü bir giz.

Belki senden kalır bir iz,

Ne kolaymış şiir yazmak.

İnce olsun, kalın olsun,

Şair densin adın kalsın.

Vitrinler kitapla dolsun,

Ne kolaymış şiir yazmak.

21.7.2000 Kayseri', 'Aldım elime kalemi, Çok kolaymış şiir yazmak. Karıştırdım el-alemi, Ne kolaymış şiir yazmak. Süslü kelimeler dizdim, Kolaycacık bade ezdim. ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cok-kolaymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fettan Kız', 'fettan-kiz-emin-duru-jqxbp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Asfalttan dönünüz sağdaki yola,

Birazcık yürüyün bakın sol kola.

Karşında gördüğün ev peri misali,

Büyüler insanı bütün her hali.

Evi biraz geçin bir ıslık sesi,

Zaten şaşırtan da budur herkesi.

Bana değil diye kanmayın sakın,

Hafifçe gülerek arkaya bakın.

Karşında gördüğün fettan güzel kız

Ne bir modeldir nede bir yıldız.

Gördüğü gençlerin sevgilisidir.

Duyduğun ses onun sesidir.', 'Asfalttan dönünüz sağdaki yola, Birazcık yürüyün bakın sol kola. Karşında gördüğün ev peri misali, Büyüler insanı bütün her hali. Evi biraz ...', ARRAY['Türk Edebiyatı','Şiir','Emin Duru']::text[], 8.5, '{"poet":"Emin Duru","poet_slug":"emin-duru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fettan-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-erol-guler-r8dlf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Havalar güzeldi, çok sevinmiştim.

Koşarak evden çıktım, gülerek.

Vararak kırlara, eğlenmek istemiştim.

Gönlümü kırlarda, azat ederek.

O anda gökyüzü birden karardı,

Benimde sevincim yarıda kaldı.

Bulutlar her tarafı birden kararttı.

Gönlüm orda kaldı istemeyerek.

Ansızın başlayan hafiften yağmur,

Islatmaya başladı duygularımı,

Yağmurla birlikte çıkan rüzgarlar,

Gönlümü titretti, serin eserek.

Etrafı derin bir hüzün bürüdü,

Ruhumu kapladı bu büyük vahşet,

Duramadım, gezemedim, eğlenemedim,

Gönlümü kurtardım, ordan kaçarak.

(İstanbul, 27.11.2000)', 'Havalar güzeldi, çok sevinmiştim. Koşarak evden çıktım, gülerek. Vararak kırlara, eğlenmek istemiştim. Gönlümü kırlarda, azat ederek. O anda...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-yilmaz-erdogan-tdutm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kilitlenmiş beton kanatları kuşların 

Oksit gibi yakışkan bir mayışmayla ağarmış gün

Pas tutan kelimeler için bir iksir belki de

Ya da aklına susamış sevgililerin safdilliği

Acıtmış ömrünü çekirgelerin

Medyatik soruşturmalardaki enflasyonist yargılar

Haber değeri taşımıyor haber spikerinin ölümü

Herkes kendi manşetinde satır arası 

Hiçbir bakışı aydınlatmıyor florasan buğusu

Burası son durak inecekler için son fırsat

Bir daha ne süper ne mega kupon verilecek

Kalanlar şoförün evini göremeyecekler hiçbir zaman 

Oları sonsuza götürecek,afaroz edilmiş bir merak

Burası son durak

Hafızada kalan tek numara için

Telefona uzanır elleri

Ölümüne randevulu insanların

Temize çekilemez not defterleri

                                               (Ocak 1995)', 'Kilitlenmiş beton kanatları kuşların  Oksit gibi yakışkan bir mayışmayla ağarmış gün Pas tutan kelimeler için bir iksir belki de Ya da aklın...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-durak-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-erhan-guleryuz-8w4xz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcak sımsıcaktı aşk

Yandı bu yaz ve yaktı bizi

Beyaz bembeyaz güller

Kuruyup düştü avuçlarımdan

Uzak çok uzak sanki

Ayrı dünyalardan bulduk birbirimizi

Tuzak bir tuzak belki

Güvendim bakışlarına çok sevdim seni

Ben de sevdim demek yetmiyor

Yanımda yoksun artık

Sensizliğe gücüm yetmiyor

Günler sensiz geçmiyor 

Efsane olmuştu iki günlük sevdamız

Mevsimler geçti bak

Bitti aşk masalımız

Birtanem herşeyim sevdiğimdin sen benim

Rüzgarlarda uçup gitti unutuldu şarkımız', 'Sıcak sımsıcaktı aşk Yandı bu yaz ve yaktı bizi Beyaz bembeyaz güller Kuruyup düştü avuçlarımdan Uzak çok uzak sanki Ayrı dünyalardan bulduk...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/efsane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğa''nın Kucağında', 'doga-nin-kucaginda-erol-guler-h2xb6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaz gelir,ağaçlar çiçek açar, her yer yeşillenir.

Göçebe kuşlar soğuk yerlerden sıcak yerlere gelir.

Karınca her zamanki gibi, telaşlı teleşlı başlar çalışmaya

Kışın yiyeceği şeyleri toplar, depo eder o sıcakta.

Çünkü kışın bu topladıkları lazımdır ona.

Ağustos böceği ise hiç bir şeye aldırmadan

Yazın tadını çıkarmaktadır saz çalarak

Karıncayla alay eder aynı zamanda,

Sanki bu durum hep böyle devam edecek.

Lale, çiğdem, menekşe, sümbül,

Gülün yanında da bülbül.

Hep beraber açarak kırlarda,

Mis kokular saçarak etrafa,

Baharı müjdelerler insana.

İnsan da doğa''nın kucağında,

Yaşamakta kendi hayatınca

O mis kokulu çiçekler arasında

Doğa''ya canlılık katar bir başka...

(İstanbul, 27 11 2000)', 'Yaz gelir,ağaçlar çiçek açar, her yer yeşillenir. Göçebe kuşlar soğuk yerlerden sıcak yerlere gelir. Karınca her zamanki gibi, telaşlı teleş...', ARRAY['Türk Edebiyatı','Şiir','Erol Güler']::text[], 8.5, '{"poet":"Erol Güler","poet_slug":"erol-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/doga-nin-kucaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Kentin Yakışıklısı', 'kayip-kentin-yakisiklisi-yilmaz-erdogan-9m0nz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dokuzunda kayboldu Mayıs''ın,

Cesedi bulundu

Onikisinde...

Kaçırıldığında da

Kaybolduğunda da

Ve cesetken de

Yakışıklıydı...

Amcamdı...

              (Ağustos 1995,İstanbul)', 'Dokuzunda kayboldu Mayıs''ın, Cesedi bulundu Onikisinde... Kaçırıldığında da Kaybolduğunda da Ve cesetken de Yakışıklıydı... Amcamdı...      ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kayip-kentin-yakisiklisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Çığlık', 'sessiz-ciglik-i-brahim-sevimli-2xkax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni böyle amansız bırakıpta gittin ya

Seni seven gönlüme yazıklar oksun

Sımsıcak gülümseyip seviyorum derdin ya

Sana kanan gönlüme yazıklar olsun

Solmuş rüzgarlar bile direnirken rüzgara

Bir çırpıda hiç biter miydi bu rüya

Tüm kalbimizle sımsıkı sarılmışken sevdaya

Terkedipte gidene yazıklar olsun

Artık ayrılık var,durma yüreğim kana

Kimbilir,belki bir gün kapanır mı bu yara

Kördüğüm gibi gönlüm bağlıydı sana

Bağlayıpta kaçana yazıklar olsun', 'Beni böyle amansız bırakıpta gittin ya Seni seven gönlüme yazıklar oksun Sımsıcak gülümseyip seviyorum derdin ya Sana kanan gönlüme yazıklar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sevimli']::text[], 8.5, '{"poet":"İbrahim Sevimli","poet_slug":"i-brahim-sevimli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-i-brahim-sevimli-jphl1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık ne zormuş anladım

Gittiğine inanmadım

Gidemezdin çünkü sen

Bana haber vermeden

Ayrılık ne zormuş anladım

Anladım da geç kaldım

(21 Ekim 2000 - Erenköy)', 'Ayrılık ne zormuş anladım Gittiğine inanmadım Gidemezdin çünkü sen Bana haber vermeden Ayrılık ne zormuş anladım Anladım da geç kaldım (21 E...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sevimli']::text[], 8.5, '{"poet":"İbrahim Sevimli","poet_slug":"i-brahim-sevimli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrilik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirme umudunu', 'yitirme-umudunu-adem-han-kaba-u01t7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir cuma sabahi geciyordum  pencerenizin onunden

Kor bir adamin attigi adimdan daha yavas ve oylece derinden 

Yavasca dogrulttum basimi hic egmedigim onumden 

Zifiri karanlik dunyama gunes gibi actigin pencerene 

Belki bir mum isigi kadar bir parlik dogar diye yeniden.

Oylece  baka kaldim bir kac zaman ve yine karanlik ine husran.

Artik arkadas oldugum o aci ile kalbim toka yapti yeniden 

Gozyaslarimi akitmak istedim kahretsin diye haykirmak icimden 

Soz vermistim oysaki gecen cuma ve ondan onceki 

Gecmeyecektim pencerenizin onunden 

Asla bakmayacaktim umut dahi etmeyecektim 

Ne sozumu tutabildim nede seni unutabildim 

Kimbilir bir dahaki cuma o ilk gunki gibi akarsin pencerene 

Yine dogarsin gunes gibi karanlik dunyama 

Gecen cumada olmasa ondan sonraki cuma kimbilir

Evet vazgecmeyecegim pencerenin onune gelmekten 

Vazgecmeyecegim asla seni eskisi gibi sevmekten....', 'Bir cuma sabahi geciyordum  pencerenizin onunden Kor bir adamin attigi adimdan daha yavas ve oylece derinden  Yavasca dogrulttum basimi hic ...', ARRAY['Türk Edebiyatı','Şiir','Adem Han Kaba']::text[], 8.5, '{"poet":"Adem Han Kaba","poet_slug":"adem-han-kaba","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yitirme-umudunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne diyem ki..', 'ne-diyem-ki-yildirim-beyazit-omurtag-0o80v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni bir yıl daha başladı 

Adına 1999 diyorlar.

Tabi bende bir yaş daha 

İhtiyarladım.

Zaman su gibi geçiyor

Bir daha anladım.

Çok eskilerde 

Bilmem hangi senelerde 

Murat ırmağı kenarında 

Kağnı arabasında 

Bibim gilin köye gidiyorduk 

Hasır fötr şapka başımda 

Oyuncak silahım belimde.

Babamın terkine binmiştim

At üstünde nede heybetliydi babam

Haft renk ırmağını geçiyorduk atlarla

Arebeyi  ga’yla ... Yani kağnıyla

İkindi vaktiydi, hava serti ve efkarlıydı babam.

O dengbejdi, yani sesi güzeldi...

Ve başladı yanık yanık söyledi...

Ben terkinde ona sarılmıştım

Yarım yamalak anlıyordum söylediklerini

Bir aşk hikayesiydi söylediği Memo-Zin’di

Şimdi bir çayırlıktaydık ağır gidiyordu kafile

Akrabaların hepsi silahlıydı

Tüfekli ve saralıklıydılar

Keleşler daha yoktu piyasada 

Kiminde kırıkkale, kiminde Berno

Hepsi atlıydı babamın etrafında...

Onlarda efkarlıydı 

Onlarda sevdalı...

Her biri mem’di

Her birinin bir Zine’si vardı.

Hepsi dertliydi

Hepsi kan davalı...

Asıldıkça babam türküsüne yanık sesiyle 

Katılıyorlardı onlarda “ Saet Hoeş “ sesleriyle...

Rüzgar bu kıskandı şapkamı

Uçurdu başımdan Murat nehrine...

Türküde bitti, hayallerde 

Herkes düştü şapkamın derdine...

Ben şehirliydim onlar için kıymetliydim...

Azizdim onlar için umuttum.

Bakmadılar havanın sertliğine 

Daldılar suya...

Atlar kişnedi, gemler kasıldı, ıslandılar

Ama şehirli yeğenlerinin şapkasını kurtardılar.

Zaten onlar hep yiğittiler, gözü pektiler

İnsan oğlu insan, fedakardılar.

Şehir bencilliğinden uzak

Hep birbirleri için yaşadılar.

Onlar aşirettiler,

Onlar Hasenalıydılar

Ve onlar savaşçıydılar.

Yeminliydiler

Kadınlara mahsus şeydi

Onlar ağlayamazdılar.

Zorda kaldılar mı ya, yalnız kalırdılar

Veya tütüne baş vururdular.

Devlet düşmanları oralardaydılar...

Oraları da küstürüp düşman ediyordular.

İş batıda, okul batıda, su batıdaydı.

Ulan kırolar size yok diyordular.

Adalet paradan yana 

Size sopa, size kurşun diyordular

Bazı devlet düşmanı devlet adamları 

Hak iki dudak arasındaydı 

Ve buna çok üzülüyorlardı. 

Her zaman “Allah var ya” diyorlardı. 

Kardeşimle bana halimizi görün 

Okuyun diyorlardı. 

Biz şehirdeydik ve biz okuyacaktık. 

Gelecekleriydik onların, umutlarıydık. 

Yolumuz yok görüyorsunuz 

Okulumuz yok, biliyorsunuz 

Adam olun kurtarın 

Umudumuz sizsiniz bizim diyordular 

Tezek kokulu, gaz lambalı 

Tandır odalarında 

Arada bir yanan lüküs lambalı 

Misafir odalarında. 

Çukura kaçmış gözleriyle

Derin derin bakarak yüzümüze 

Kurtarın bizi, Allah için kurtarın diyordular. 

Çocuktuk biz anlamıyorduk ki...

Yıllar sonra yavaş yavaş anlayacaktık

Geri kalmışlığa çare arayacaktık...

Kimimiz solda bulduk çareyi, kimimiz sağda.

Bu seferde onsekizin de tanışmaya başladık copla...

Size ne lan, size mi kaldı vatanı kurtarmak

Diyerek kafalarımıza inen copla sopayla,

Tanıştık siyasi şubelerin bodrumlarıyla.

Hayatımı karartan iftiralarla.

Ben yapmadıma inanmadılar işkenceciler

Mahzende bindiler sırtıma sopalarıyla.

Daha onsekizindeydim tanıştım zindanlarla.

Halkımı kurtaracak çareler buldum

Onlara da anlattım dağıttığım bildirilerle...

İyi niyetime inandıramadım birilerini 

Onsekizindeydim tanıştım kelepçelerle.

İstemiyorlar, bırakmıyorlar diyemedim

Umudu olduklarıma.

Düşüncelerim ezildi oniki eylüllerde...

Artık hep  beraberdim kelepçelerle.

Okutturmadılar söyleyemedim bir türlü

Umudu olduklarıma

Düşüncelerim hep aydınlık, hep ışıktı...

Söndürdüler hücrelerin 

Zifiri karanlıklarında

Haberi bile olmadı bir tekinin

Binlerce özür diledim umudu olduklarımdan 

Gözyaşlarımla

Ve tanıştım efkar arkadaşım 

İzmarit ve sigaralarla

Aşık olduğum da haberi olmadı benden 

Teselli aradım şarkılardan türkülerden.

Şimdi ise kendimde tanımıyorum beni

İyiden iyiye uzaklaştım benden.

			Yıldırım Beyazıt OMURTAG', 'Yeni bir yıl daha başladı  Adına 1999 diyorlar. Tabi bende bir yaş daha  İhtiyarladım. Zaman su gibi geçiyor Bir daha anladım. Çok eskilerde...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Beyazıt Omurtag']::text[], 8.5, '{"poet":"Yıldırım Beyazıt Omurtag","poet_slug":"yildirim-beyazit-omurtag","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/ne-diyem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmesin', 'gecmesin-selma-caliskan-0rja0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir selaleye dayandim bak,

Korkuyorum yesermekten,

Ama yesilide cok seviyorum,

Sirtim islak, saclarim, ellerim islak

Ayaklarim kuru kalmis yar,

Yüregim tenim sicak kalmis bak.

Gün batimi kurdugum hayalin hatrina,

Vur beni ayaklarinin dibine,

Vurda! Öfken Nefretin, hatirimi gecmesin.

Bir sonbahara dayandim sanki,

Sari yapraklar yollarima, kollarima, saclarima düstü bak

Birak,

Verdigin buselerin hatrina, birak.

Birak ki, zamanin askimi gecmesin.

Allahtan sonra sana sigindim bak

Her mevsimi, yesil sandim da, karistirdim yar.

Kiyamazdin ya bana, gözyasimin hatrina düsünme,

Düsünme ki,

Düsüncelerine yanlis karisip, dogrularimi gecmesin, gecmesin yar.', 'Bir selaleye dayandim bak, Korkuyorum yesermekten, Ama yesilide cok seviyorum, Sirtim islak, saclarim, ellerim islak Ayaklarim kuru kalmis y...', ARRAY['Türk Edebiyatı','Şiir','Selma Çalışkan']::text[], 8.5, '{"poet":"Selma Çalışkan","poet_slug":"selma-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gecmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Kovalıyorum', 'hayati-kovaliyorum-fidan-aykut-n1iv9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul kendi kendine konuşuyordu yine bu sabah. 

Anadolu şehirleri böyle değildir;

Ona can veren insanları dinler oysa.

Alımlı, kaprisli, kaçan sevgiliyi oynayan İstanbul ise,

Kovalanıyordu bu sabah yine

Kendisine müptela ettiği sevgilileri tarafından.

Bizler tarafından.

Bense yine her zamanki asiliğimle

Başkaldırdım İstanbul''a.

Korna sesleriyle çığlıklar atan,

Gri battaniyesiyle kasvet saçan

İstanbul'' a rağmen;

Göğü yaran martının ''ben özgürüm'' çığlıklarını,

Üzerine çiğ düşmüş çiçeklerin

Söyledikleri umut şarkılarını duyabildim.

İşte bu yüzden kaçma İstanbul.

Çünkü;

Ben seni değil,

Hayatı kovalamaya karar verdim çok uzun zaman önce.

Artık senin gerinde değil,

Önünde koşuyorum.

28.11.2000- 08:30/ İstanbul', 'İstanbul kendi kendine konuşuyordu yine bu sabah.  Anadolu şehirleri böyle değildir; Ona can veren insanları dinler oysa. Alımlı, kaprisli, ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayati-kovaliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratmak', 'yaratmak-metin-vatansever-7mjof', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaratmak elimde olsaydı,

Taştan yaratırdım kendimi,

Zincirler takardım bileklerime,

Arzularıma gem vurup,

Miller çekerdim gözlerime

Yok ederdim sevili duygularımı

Ve... Bu kahredercesine sevdayı,

Kalbimi çölden yaratırdım ki

Hiç bir sevda yeşermesin,

Senin için yalnız bu dudakları,

Evet onları bırakırdım

O kahredercesine busen için,

Yalnız hissizliğini duymak için...

Yaratmak elimde olsaydı,

Senide bir heykel olarak yaratırdım,

Kolları olmayan başı öne eğik bir heykel,

Yalan olmazdı o zaman hislerin

Ve de boşuna atan bir yüreğin,

Onu bir sevgi mabedine dikerdim

Sevdalıların elele dolaştığı...

Ama gözlerine o anlamı vermek için

Çatık yaratırdım kaşlarını,

Saçlarının her  kıvrımını çizerdim,

Yaratmak elimde olsaydı,

Kimbilir, belki de yaratmazdım seni...', 'Yaratmak elimde olsaydı, Taştan yaratırdım kendimi, Zincirler takardım bileklerime, Arzularıma gem vurup, Miller çekerdim gözlerime Yok eder...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaratmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazacağım', 'yazacagim-asik-i-hsani-7w1jq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazacağım bu can tende

Durana dek yazacağım

Eşitsizlik zincirini

Kırana dek yazacağım.', 'Yazacağım bu can tende Durana dek yazacağım Eşitsizlik zincirini Kırana dek yazacağım....', ARRAY['Türk Edebiyatı','Şiir','Aşık İhsani']::text[], 8.5, '{"poet":"Aşık İhsani","poet_slug":"asik-i-hsani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcaklığında', 'sicakliginda-emin-yavuzyigit-t0irk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıcaklığı seviyorum

Sıcakla yoğrulmayı

Sıcakta eğrilmeyi

Sıcaklığında kaybolmayı

Yüreğimin sıcaklığında

Yüreğimi arıyorum

Kalplerin derinliğinde 

Sıcak bir tebessümü arıyorum

Ben denizlerin sahillerine 

Yansıyan sıcaklığı aramıyorum

Ve yahut

Gecelerime tercüman olan

Ve bedenimi aydınlatan

Ayın ılıyan tebessümünü

Aramıyorum

Ben 

Sıcaklığında 

Sıcaklığımı arıyorum', 'Sıcaklığı seviyorum Sıcakla yoğrulmayı Sıcakta eğrilmeyi Sıcaklığında kaybolmayı Yüreğimin sıcaklığında Yüreğimi arıyorum Kalplerin derinliğ...', ARRAY['Türk Edebiyatı','Şiir','Emin Yavuzyiğit']::text[], 8.5, '{"poet":"Emin Yavuzyiğit","poet_slug":"emin-yavuzyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sicakliginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Destanı', 'i-stanbul-destani-bedri-rahmi-eyuboglu-wnzne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul deyince aklıma martı gelir

Yarısı gümüş, yarısı köpük

Yarısı balık yarısı kuş

İstanbul deyince aklıma bir masal gelir

Bir varmış, bir yokmuş

İstanbul deyince aklıma Gülcemal gelir

Anadolu''da toprak damlı bir evde

Gülcemal üstüne türküler söylenir

Süt akar cümle musluklarından

Direklerinde güller tomurcuklanır

Anadolu''da toprak damlı bir evde çocukluğum

Gülcemalle gider İstanbul''a

Gülcemalle gelir

İstanbul deyince aklıma

Bir sepet kınalı yapıncak gelir

Şehzadebaşı''nda akşam üstü

Sepetin üstünde üç tane mum

Bir kız yanaşır insafsızca dişi

Boyuna bosuna kurban olduğum

Kalın dudaklarında yapıncağın balı

Tepeden tırnağa arzu dolu

Sam yeli söğüt dalı harmandalı

Bir şarap mahzeninde doğmuş olmalı

Şehzadebaşı''nda akşam üstü

Yine zevrak-ı derunum

Kırılıp kenara düştü

İstanbul deyince aklıma Kapalıçarşı gelir

Dokuzuncu Senfoniyle kolkola

Cezayir marşı gelir

Dört başı mamur bir gelin odası

Haraç mezat satılmakta

Bir gelinle güvey eksik yatakta

Köşede sedef kakmalı tombul bir ut

Tamburi Cemil Bey çalıyor eski plakta

Sonra ellerinde şamdanlar nargileler

Paslı Acem kılıçları

Amerikan kovboyları

Eller yukarı

Ne kadar da beyaz elbiseleri

Amerikan deniz erleri

Kocaman bir papatyadan yolunmuşlar gibi

Sütten duru buluttan beyaz

Beyazın böylesine ölüm yakışır mı dersin

Yakışmaz

Ama harbederken onlara

Bambaşka elbiseler giydirirler

Kan rengi, barut rengi, duman rengi

Kin tutar kir tutmaz

İstanbul deyince aklıma

Kocaman bir dalyan gelir

Kimi paslı bir örümcek ağı gibi

Gerinir Beykoz''da

Kimi Fenerbahçe''de yan gelir

Dalyanda kırk tane Orkinos

Kırk değirmen taşı gibi dönmektedir

Orkinos dediğin balıkların şahı Orkinos mavzerle gözünden vurulur

Denizin içinde ağaçlar devrilir

Kan çanağına döner dalyanın yüzü

Camgöbeği yeşili bulanır

Bir çırpıda kırk Orkinos

Reisin sevinçten dili dolanır

Bir martı gelir konar direğe

Atılan Kolyosu havada yutar

Bir başkasını beklemez gider

Balıkçı gülümser tatlı tatlı

Adı Marikadır bu martının der

Her zaman böyle gelir böyle gider

İstanbul deyince aklıma Adalar gelir

Dünyanın en kötü Fransızcası orda harcanır

Çalımından geçilmez altmışlık madamların

Ağzı dili olsa da tenhadaki çamların

Görüp göreceği rahmeti anlatsa insanların

İstanbul deyince aklıma kuleler gelir

Ne zaman birinin resmini yapsam öteki kıskanır

Ama şu Kızkulesinin aklı olsa

Galata kulesine varır

Bir sürü çocukları olur

İstanbul deyince aklıma

Tophane''de küçücük bir sokak gelir

Her Allahın günü kahvelerine

Anadolu''dan bir sürü fakir fukara gelir

Kimi dilenecek dilenmesine utanır

Kiminin elinde bir süpürge peyda olur uzun

Dudaklarında kirli paslı bir tebessüm

Çöpçü olmuştur bugüne bugün

Kiminin sırtında perişan bir küfe

Kiminin sırtında nakışlı semer

Şehrin cümbüşüne katılır gider

Kalın yağlı bir kolana koşulur

Piyano taşırlar omuz omuza

Kendinden ağır yükün altında adamlar

Balmumu gibi erir dururlar

Sonra kanter içinde soluk alırlar

Nazik eşya nazik hamallar ister neylersin

Ama onlar kadar piyanoyu ciddiye alırlar mı dersin

Nazdan nazik çiniden bilezik eller

Derken

Karşı radyoda gayetle mülayim bir ses

Evlere şenlik Üstad Sinir Zulmettin

Hacıyağına bulanmış sesiyle esner:

Gamı şadiyi felek

Böyle gelir böyle gider

İstanbul deyince aklıma 

Stadyum gelir

Güne güneşe karşı yirmibeşbin kişi

Hepsinin dudağında İstiklal Marşı

Bulutlar atılır top top pare pare

Yirmibeşbin kişilik bir aydınlık içinde eririm

Canım ağzıma gelir sevinçten hilafsız

İsteseler bir gelincik gibi koparır veririm

İstanbul deyince aklıma

Stadyum gelir

Kanımın karıştığını duyarım ılık ılık

Memleketimin insanlarına

Daha fazla sokulmak isterim yanlarına

Ben de bağırırım birlikte

Avazım çıktığı kadar

Göğsümü gere gere

Ver Lefter''e yaz deftere

Stadyum gelir 

İstanbul deyince aklıma

Binlerce insanın aynı anda

Aynı şeyi duymasından doğan sevincin

Heybetini düşünürüm

Birbirine eklenir kafamda

Binler yüzbinler milyonlar

Sonra bir mısra havalanır ürkek

Bir uykuyu cananla beraber uyuyanlar

İstanbul deyince aklıma

Yahya Kemal gelirdi bir eyyam

Şimdi Orhan Veli gelir

Demindenberi dilimin ucundasın Orhan Veli

Demindenberi senin tadın senin tuzun

Senin şiirin senin yüzün

Yaralı bir güvercin misali

Başımın üstünde dolanır durur

Gelir sessizce konar bu şiirin bir yerine

Neresine mi arayan bulur

Erbabı bilir

Deli eder insanı bu şehir deli

Kadehlerin çınlasın Orhan Veli

İstanbul deyince aklıma Sait Faik gelir

Burgaz adasında kıyıda

Mavi gözlü bir çocuk büyür döne döne

Mavi gözlü bir ihtiyar balıkçı gencelir küçülür

İkisi bir boya geldi mi Sait kesilirler

Bütün İstanbul''u dolaşırlar elele başbaşa

Ana avrat küfrederler uçan kuşa eşe dosta

Sivriadada da martı yumurtası toplarlar çilli çilli

Ziba mahallesinde gece yarısı

Sabaha Galata''dan geçer yolları

Maytaba alacakları tutar kahvede

Zararsız bir deliyi

Ula Hasan derler gazeteyi ters tutaysun

Çaktırmadan gazetesini tutuştururlar fakirin

Sonra oturup sessizce ağlarlar

İstanbul deyince aklıma 

Sait Faik gelir

Taşında toprağında suyunda

Fakirin fukaranın yanıbaşında

Bir kalem bir bilek bilendikçe bilenir

Kıldan ince kılıçtan keskin

Hep iyiden güzelden yana

Hep kimsesizlerin

İstanbul deyince aklıma

Said''in son yılları gelir

Hey Allahım en güzel çağında Said''e

Dört beş yıl ömrün kaldı denir

Sait Sait olur da nasıl dayanır

Mavi gözlü çocuk boşverir ölüm haberine

İhtiyar balıkçı pis pis düşünür

Bir zehir yeşilidir açılır

Bir yeşil ki ciğerine işler adamın

Bir yeşil ki kasıp kavurur

Küçük mavi çocuk

İhtiyar balıkçı

Ve dilimize bulaşan zehir yeşili

İstanbul çalkalandıkça bu denizlerde dipdiri

Dilimiz yaşadıkça yaşasın Said''in şiiri

İstanbul deyince aklıma

Sabiyem gelir

Sabiyem boynundan büyük bir demetle

Sarıyer''den gelir Pendik''ten gelir

Bahar nereden gelirse velhasıl

Sabiyem oradan gelir

Ne delidir ne divane

Aslını ararsan çingenedir

Tepeden tırnağa güneştir

Topraktır

Anadır

Analar içinde bir tanedir

Biri sırtında biri memesinde biri karnında

Karnı her daim burnundadır

Canını mendil gibi takar dişine

Yürekten birşeyler katar işine

Bir ucundan girer şehrin ötekinden çıkar

Alçakgönüllüdür Sabiyem

Hem maşa satar, hem göbek atar

Ver bir çeyrek güzelim der

Neyse halin o çıksın falin

Canı çıkar Sabiyemin falı çıkmaz

Sonra anlatır dün gece başına gelenleri

Görürüm üryamda bir sarı yılan

Cenabet uğraşır durur benimlen

Uyanır bakarım benim bebeler

Yatağın ucuna kaymış

Ayağımın parmaklarını emer

İstanbul deyince aklıma

Bir basma fabrikası gelir

Duvarları uzun masaları uzun sobaları uzun

Dal gibi dalyan gibi kızlar çalışır bütün gün ayakta

Kanter içinde mahzun

Yüzleri uzun elleri uzun günleri uzun

Fabrikada pencereler tavana yakın

Al topuklu beyaz kızlar dalga geçmeyin

Dışarda ağaçlar dizi dizi

Duvarlar duvarlar uzun duvarlar

Niçin ağaçlardan ayırdınız bizi

Dışarda tarlalar turuncu asfalt mosmor

Dışarda dışarda dışarda

Mevsim gürül gürül akıp gidiyor

Ondokuz yaşında Eyüplü Gülsüm

Dalmış beyaz köpüklü akışına ipeklilerin

Kötü kötü düşünüyor

İpeğin akışına doyum olmaz

Ama gel gör ki ipekli emprimeden oğlana don olmaz

Bir top Amerikan bezi sakız gibi beyaz

Bir top Amerikandan neler çıkmaz

Perdeler yatak çarşafları çoluğa çocuğa çamaşır

Sakız gibi ağarmış bir top Amerikan bezi

Gülsüm''ün gözleri kamaşır

Üçüncü oğlanı doğururken Gülsüm

Bir top Amerikana hasret sizlere ömür

Gülsüm''lerin sürüsüne bereket

Yerine bir Gülsüm''cük bulunur elbet

Gider Gülsüm gelir Gülsüm

Azrail ettiğin bulsun

İstanbul deyince aklıma

Ağzına kadar soğan yüklü bir taka gelir

Sülyen kırmızısı üstüne zehir gibi yeşil

Samsun''dan Sürmene''den Sinop''tan

Yaz demez kış demez mutlaka gelir

Kirli yelkeninde yeni bir yama

Demirinin pası gelir dilime

Nabzımda duyarım motorunun hızını

Canımın içine sokasım gelir

İri kalçaları pullu denizkızını

İstanbul deyince aklıma

Takalar gelir

Alçakgönüllü kalender

Ya Peleng-i Deryadır adları ya Şimşir-i Zafer

İstanbul deyince aklıma

Koca Sinan gelir

On parmağı on ulu çınar gibi

Her yandan yükselir

Sonra gecekondular gelir ardısıra

İsli paslı yetim

Eyy benim dev memesinde cüceler emziren 

acayip memleketim', 'İstanbul deyince aklıma martı gelir Yarısı gümüş, yarısı köpük Yarısı balık yarısı kuş İstanbul deyince aklıma bir masal gelir Bir varmış, b...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":259,"source_url":"https://www.antoloji.com/istanbul-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Bahar Çiçeğiyim', 'ben-bir-bahar-cicegiyim-fatih-misket-g9mjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir bahar çiçeğiyim

Umutlara gebe

İçimde sevdalarla,

Ben bir bahar çiçeğiyim

Yelken açarım en ufak rüzgarlarda

Kırlara, ormanlara...

Bana sorarsan hayatın adı sevda.

Ben bir bahar çiçeğiyim

Kuşlara aşık

Gökleride severim, yıldızları da...

Hele güneşi ayı...

İnsanlarıda severim...ama..!

Ama insanlar kırar dalımı

Kolumu kanadımı

Fakat yine de sevgi doludur içim

Ve gidiyorum...

Şimdi hazan zamanı

Ama yine geleceğim...

Unutma...!

Ben bir bahar çiçeğiyim.', 'Ben bir bahar çiçeğiyim Umutlara gebe İçimde sevdalarla, Ben bir bahar çiçeğiyim Yelken açarım en ufak rüzgarlarda Kırlara, ormanlara... Ban...', ARRAY['Türk Edebiyatı','Şiir','Fatih Misket']::text[], 8.5, '{"poet":"Fatih Misket","poet_slug":"fatih-misket","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-bir-bahar-cicegiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-fatih-misket-q61ku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşüyor gecenin tam ortasına

Ve hasretlerin arkasına bir aşk

Üşüyor ellerim senden ayrıldığında

Fakat yüreğim hep sımsıcak

Bu son haster olsun vuslatın kapısında

Bu son yalnızlık olsun gecenin ortasında

Ve bu son şiir olsun! yokluğuna yazılacak.', 'Düşüyor gecenin tam ortasına Ve hasretlerin arkasına bir aşk Üşüyor ellerim senden ayrıldığında Fakat yüreğim hep sımsıcak Bu son haster ols...', ARRAY['Türk Edebiyatı','Şiir','Fatih Misket']::text[], 8.5, '{"poet":"Fatih Misket","poet_slug":"fatih-misket","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-fatih-misket-wcoja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk bir limandır

Hırçın denizinden kurtulup dünyanın

Bu limana sığınır sevdalılar

Aşkın büyüsünü uyandırır bu aşıklar

Aşk; gerçektir

Aşk; o en saf, o en temiz duygu

Yari yüreğinden vuran

Ona sevdayı sunan

Ve bir ömür boyu

Mutluluğa doyanlarındır aşk

Aşk; bir  ölümdür

Öldürür!..

Aşk sevgilinin yüreğine gömülür

Aşkın toprağıdır gönül.

Bir sahradır aşk...

Ne yana gitsen kurtulamazsın

Öldüremezsin!

Hiç sevmedinse bilemezsin

Aşksız dünyada gülemezsin

Bir kere düştünmü aşka

Onu gönlünden silemezsin

Aşk bir ölümdür

Kendi ölmez, seveni sevileni öldürür.', 'Aşk bir limandır Hırçın denizinden kurtulup dünyanın Bu limana sığınır sevdalılar Aşkın büyüsünü uyandırır bu aşıklar Aşk; gerçektir Aşk; o ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Misket']::text[], 8.5, '{"poet":"Fatih Misket","poet_slug":"fatih-misket","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aska-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Getirdim Sana', 'bahar-getirdim-sana-buket-aslan-zdtzj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Neyi arıyorsan sen, O’sundur” der  Mevlana..

 Zulmün peşindeysen zalimsin, aşkı arıyorsan aşık....

 Elinden  tuttuğumuz her sevgili, bizi sürükleyip,

kendi iç dünyamızın derinliklerinde  bir keşif gezisine

çıkarır. Her ilişki, benliğimizde bir kazıdır  aslında,

her sevda ruhumuzun bir başka yüzü... Her aşkta

kendimizi  ararız, o yüzden bulduklarımız benzerimizdir.

Resimlerini yan yana koyun  sevdiklerinizin ve

dikkatle bakın yüzlerine, onların suretlerinden

 kendi  yüzünüz bakacaktır size... Aşk denilen

 kaleydoskobun buzlu camına gözünüzü  dayadığınızda,

binbir cam rengarenk ışıklar saçarak döndüğünde,

her  seferinde bambaşka şekiller ördüğünü görürsünüz.

 Her camda, farklı bir  renginiz vardır; her şekilde

sizden bir parça... Aşklarınız  hülasanızdır.

Sevdiginiz her adam, beğendiğiniz her kadın

farklı ruh  hallerinizi ele verir; arada bir çevirdiniz mi

kaleydoskobu, cam paralar yer  değiştirip yeni şekiller

alır; hepsi siz... Sevgilinizin gözlerindeki  dolunay,

sizdeki ışığın yansımasıdır aslında;

dilindeki sizin ilhamınız,  tenindeki sizin yansımanızdır.

Yoksa halâ bir sevdiğiniz, o henüz kendinizi

bulamadığınızdandır... Aşk, narsizmdir.

Sevda, çevrildikçe içinizin  farklı ışıklarını yakan

eğlenceli bir kaleydoskop gibi başımızı döndürüyor.

Ve biz, hep baharı takip ederek dünyayı gezen bir

gezgin gibi içimizdeki  eski baharları arıyoruz.

Narcissusu’u bilirsiniz; Öyle heybetli ve güzelmiş  ki,

bakmaya dayanazmazmış kendine... Gün boyu

ayna karşısına geçip kara  gözlerini, incecik burnunu,

 dar kalçalarını, kıvırcık saçlarını  seyredermiş

hayran hayran... Bir gün ırmak kenarında gezinirken,

sudaki  yansımasına ilişmiş gözü. Uzanıp, iyice

bakmak istemiş. Tam gördüğünde  kendisini,

dengesini kaybedip düşüvermiş ırmağa,

kapılıp gitmiş suya...  Yeryüzünün en güzel insanının

öldüğünü duyan Tanrı, unutulmaması için O’nu

her bahar açan gözel kokulu bir çiçeğe dönüştürmüş,

Narcissus, nergis  olmuş. Kıssadan hisse, benden

size tavsiye, taze bir nergis verin bugün  sevgilinize...

Sonra da, nerede baharsa mevsim, rotasını oraya

çevirip  içinizdeki eski baharlara koşan bir gezgin gibi

 “Bahar getirdim sana” deyin.

Baharın elinizde olduğunu unutmadan..

Gözlerindeki ırmağa baktığınızda  kendinizi göreceksiniz;

dikkat edin de hayran olup düşmeyin...

Düşüp  bahar kokulu bir çiçeğe dönüşmeyin...', '“Neyi arıyorsan sen, O’sundur” der  Mevlana..  Zulmün peşindeysen zalimsin, aşkı arıyorsan aşık....  Elinden  tuttuğumuz her sevgili, bizi s...', ARRAY['Türk Edebiyatı','Şiir','Buket Aslan']::text[], 8.5, '{"poet":"Buket Aslan","poet_slug":"buket-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bahar-getirdim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeseydim', 'sevmeseydim-metin-vatansever-bqjzi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmeseydim;

Gözlerim ararmıydı ümidim olmadan seni,

Ellerim uzanırmıydı apansız karanlıklardan,

Kalbim duyarmıydı sensizlik acısını...

Sevmeseydim;

Bizim şarkımız çalarken dolarmıydı bu gözler,

Senden ayrılırken bükülürmüydü boynum,

Hüzünlenip yudumlarmıydım yalnızlığı...

Sevmeseydim;

Gelirmiydim sana bir an görmek için,

Gördüğümde titrermiydi yüreğim,

O sihirli kelimeyi söylerken tutulurmuydu dilim...

Sevmeseydim;

Sevmeni beklermiydim senden,

Verdiğinde tutarmıydım ellerini,

Kaçırırmıydım bakışlarımı,

Aşkını gözlerinde tatmak varken...', 'Sevmeseydim; Gözlerim ararmıydı ümidim olmadan seni, Ellerim uzanırmıydı apansız karanlıklardan, Kalbim duyarmıydı sensizlik acısını... Sevm...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmeseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'büyümek', 'buyumek-ovunc-ozkan-ltl05', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben 

