INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelicem', 'gelicem-yalcin-cinar-0njz6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugüne kadar defalarca öldüm!

Ana rahminde gözlerim açılmamışken,

Sinesinde bir hastalık yüzünden,

Birçok kez görünmez kazaydı neden

Yeniden geldim,bıkmadım ölümden

...

Bazen açlık oldu sonumu getiren

Çoğunda savaş vardı topluca yok eden

Aslına bendim hep beni öldüren,

Sonra tekrar öldürmek için üreten!

Anlamadım,yine geldim ve ölücem.

...

Kimi zaman aşkın elinden,

Kimi zaman kara bir lekeden

Kurtulmak için ecelimi beklemeden

Çare sanıp bendim intihar eden!

Yorulmadım ölmekten,daha çoook gelicem.

                   26-11-95', 'Bugüne kadar defalarca öldüm! Ana rahminde gözlerim açılmamışken, Sinesinde bir hastalık yüzünden, Birçok kez görünmez kazaydı neden Yeniden...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Çınar']::text[], 8.5, '{"poet":"Yalçın Çınar","poet_slug":"yalcin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelicem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç üzülmedim', 'hic-uzulmedim-riza-aslan-u5roh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gidişine

hiç üzülmedim

daha önce giden 

herkes gibi

zamanı gelince 

bir gün 

sen de gidecektin', 'gidişine hiç üzülmedim daha önce giden  herkes gibi zamanı gelince  bir gün  sen de gidecektin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hic-uzulmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yılda', 'yeni-yilda-yalcin-cinar-w42zi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar yağsın yeni yıla girerken

Kurumuş otları,çıplak ağaçları örtsün.

Geçen yıl olmayan ümitlerimizin,

Yaşadığımız kötü günlerin üzerine

Bembeyaz,yeni bir sayfa gibi açılsın.

Eriyecek olması baharı,

Baharda yeşerecek doğa,

Ümitlerimizi canlandırsın.

...

Kartopu yapmalıyım çıplak ellerimle!

Yuvarlamalıyım en yüksekten,

Hiç son bulmayacak tepeden.

Yuvarlandıkça büyümeli,sevgim gibi

Dünya görmeli,görmelisin

İşte bu erimemeli,erimiyecek

Her yıl yeniden yapıcağım

Ve üşüyen ellerimi ellerinle ısıtmanı bekleyeceğim.

...

Kar yağmalı yeni yıla girerken

Çocuklar sevinmeli,sokaklarda cıvıl cıvıl

Kardanadamı görmeliyim yeni yılda

Selamlamalıyım onu yılın ilk sabahında

Geçen yılki acılarımı süpürüp kaldırırken

Ve sonra teşekkür etmeliyim ona

Güle güle demeliyim,güle güle...

İşini bitirmiş eriyip giderken.

...

Kardanadamın giderken bıraktıkları

İki kara gözü,bir kırmızı burnu ve süpürgesi

Kara gözleri yarimin gözleri gibi,

Benim Ona sevdam gibi

Kırmızı burnu yanan yüreğim,

Ve süpürgesi... bunları neden süpürmedi!

Ümidimi yitirmiyim diye mi ?

...

Alıp saklamalıyım bıraktıklarını

Ümidim bu yıl da olmazsa !

Birdahaki yıl ona vermeliyim yine,

Beni,bizi görsün diye.

Eğer olursa!.. yine vermeliyim

Benim gibileri görsün diye

Onlar da umutsuz kalmasın diye

Kar yağmalı yeni yılda

Kar yağmalı her yılbaşında.

                   07-12-97', 'Kar yağsın yeni yıla girerken Kurumuş otları,çıplak ağaçları örtsün. Geçen yıl olmayan ümitlerimizin, Yaşadığımız kötü günlerin üzerine Bemb...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Çınar']::text[], 8.5, '{"poet":"Yalçın Çınar","poet_slug":"yalcin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yeni-yilda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden ben', 'neden-ben-riza-aslan-arjhk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'neden ben demiştin

benim neyimi sevdin demiştin

bilmiyorum,

bilseydim sevemezdim', 'neden ben demiştin benim neyimi sevdin demiştin bilmiyorum, bilseydim sevemezdim...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neden-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşü olmayan', 'donusu-olmayan-riza-aslan-7ypx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dönüşü olmayan bir sevgimiydi bu

yoksa başedilmez bir ezginlik mi ?', 'dönüşü olmayan bir sevgimiydi bu yoksa başedilmez bir ezginlik mi ?...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/donusu-olmayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtçuk', 'kurtcuk-yalcin-cinar-io2qd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'avuçlarım kurşun eker toprağa

silahım kan biçer,hasatta

gözlerim kısıktır,ufka bakar halde

arkamda kalan yer ise çölleşmiştir

dönüş yokki orda bana

benim kurtlarım dolunay da dağlarda ulumaz

benim kurtlarım kıtır kıtır kıvrılırken kafamın içinde ulur

sapsarıdırlar

taptaze

ve savunmasız kurtçuklar

bir kaşıntı bilirim

aklın kaşınır,

beynimin kıvrımları !

ve bir kayaya hınçla çarparsın başını

kayada kan izi beklerken

o da ne !

sarı ezik kurtçuklar

kıvranıp ölüyorlar

hayallerin son nefesini izledim

ve gerçeklerden gizleyemedim

kurtçuklarım çürüyen elma gibi kafatasımda

yavaş yavaş ölüyorlar

  . . . . . . . . . . 

tüylerim ürperir bazen,bir küçük tırtıl gezermiş gibi tenimde 

sonra bakarım nerde,oysa o kelebek olup ölmüştür bile', 'avuçlarım kurşun eker toprağa silahım kan biçer,hasatta gözlerim kısıktır,ufka bakar halde arkamda kalan yer ise çölleşmiştir dönüş yokki or...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Çınar']::text[], 8.5, '{"poet":"Yalçın Çınar","poet_slug":"yalcin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kurtcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahkalarla gülen', 'kahkalarla-gulen-riza-aslan-dyihp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kahkalarla gülen

bu insanın içinde 

hıçkırarak ağlayan 

biri var bugün', 'kahkalarla gülen bu insanın içinde  hıçkırarak ağlayan  biri var bugün...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kahkalarla-gulen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Volta', 'volta-yalcin-cinar-p8kqc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'VOLTA

Çarşaf gibi şimdi deniz

Ve biz de deniz gibiyiz.

Deniz küsmüş sahile

Dalgalar ömür boyu hapis...

Bir sal var ufuk çizgisinde,

Hayal-meyal güneşin battığı yerde.

Küçük direğinde paramparça yelkeni

Çatlamış yaralı yüzüyle kaptan

Bitmek üzere güvertede....

Rüzgar çoktan yitmiş bu düşte

Hoş,esse de boş olurdu ya...

Bu file yelkenli sal ve kaptanı

Onu hissedemezdi artık....

Ne fırtınalar aşmışlardı...

Deniz ve rüzgar birleşmiş,

Metrelerce yükseklikte dalgaları

Mezar olsun diye göndermişlerdi.

Bunu kim olsa anlardı

Çatlamış dudaklarından,

Sararmış,yaralı yüzünden,

Paramparça elbiselerinden,

Yelkeni file olmuş salından

Okunuyordu bütün hikaye.

Kaç kez Azrail ile karşılaşmıştır ?

Belki birbirlerini çok iyi tanımışlardır!

Düşünsene bir saldaki O viraneyi...

Acaba buraya kadar niye geldi ?

Yalnızlık sahilinde volta atarken,

Bir ses duydu,uzaklardan biryerlerden!

Kimdi bu,yüreğine seslenen !?

Ona arkadaş,dost,yar demek isteğiylen

Başladı ve çıktı bu mücadeleden.

Şimdi,yalnızlık sahilinden yapılma salı,

Zorlu yolculukta savaş verirken yırtılan

Sevgi ve ümit dolu cebi yüreğinden

Denize dökülüp yitirdiği hayalleriylen

Oydu bu savaşı kaybeden...

Uyandığında o salın yatağı olduğunu!

Bütün bunların bir rüya olduğunu görmüş,

Sevinememişti bile...

Çünkü uyandığında en başa dönmüştü

Yalnızlık sahilinde volta atıyordu yine....

Bir of çekip ''keşke'' dedi ''keşke...''

''Hiç uyanmasaydım,Denizin ortasında,salımın üzerinde

yakın dostum Azrail''e teslim olsaydım''...

              27-10-96', 'VOLTA Çarşaf gibi şimdi deniz Ve biz de deniz gibiyiz. Deniz küsmüş sahile Dalgalar ömür boyu hapis... Bir sal var ufuk çizgisinde, Hayal-me...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Çınar']::text[], 8.5, '{"poet":"Yalçın Çınar","poet_slug":"yalcin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/volta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
