INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çekiyorum', 'ben-cekiyorum-bayram-tunca-b6z09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizliğin acısını ben çekiyorum

Yokluğun sancısını ben çekiyorum

Sensizliğin hasretini ben çekiyorum

Bütün sıkıntıları hep ben çekiyorum

B. TUNCA/25.10.2000-16.37', 'Sensizliğin acısını ben çekiyorum Yokluğun sancısını ben çekiyorum Sensizliğin hasretini ben çekiyorum Bütün sıkıntıları hep ben çekiyorum B...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-cekiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Arkadaş+', 'hey-arkadas-bayram-tunca-tsz3c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benimle bazen tesadüfen karşılaşıyorsun

Karşılaştığımızda da hal/hatır soruyorsun

Gerçi ne çektiğimi sen daha iyi biliyorsun

Anlatsam dayanabileceğini mi sanıyorsun

25.10.2000-16:37

Aşk ateşten Gömlek', 'Benimle bazen tesadüfen karşılaşıyorsun Karşılaştığımızda da hal/hatır soruyorsun Gerçi ne çektiğimi sen daha iyi biliyorsun Anlatsam dayana...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hey-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıyorum-Kazıyorum+', 'yaziyorum-kaziyorum-bayram-tunca-bfyb4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç durmadan gece gündüz yazıyorum

Hiç durmadan gece gündüz kazıyorum

İlham geldikçe, hep aşk şiiri yazıyorum

O yârin hasretinden, dağları kazıyorum

25.10.2000-16:37

Aşk Ateşten Gömlek', 'Hiç durmadan gece gündüz yazıyorum Hiç durmadan gece gündüz kazıyorum İlham geldikçe, hep aşk şiiri yazıyorum O yârin hasretinden, dağları k...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaziyorum-kaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evler', 'evler-behcet-necatigil-jax4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar yüzyıllar yılı evler yaptılar.

İrili ufaklı, birbirinden farklı, 

Ahşap evler, kagir evler yaptılar.

Doğup ölenleri oldu, gelip gidenleri oldu,

Evlerin içi devir devir değişti

Evlerin dışı pencere, duvar.

Vurulmuş vurgunların yücelttiği evlerde 

Kalbi kara insanlar oturdu.

Gündelik korkuların çökerttiği evlerde 

O fukara insanlar oturdu.

Evlerin çoğu eskidi gitti, tamir edilemedi,

Evlerin çoğu gereği gibi tasvir edilemedi.

Kimi hayata doymuş göründü, 

Bazılara zamana uydular.

Evlerin içi oda oda üzüntü,

Evlerin dışı pencere, duvar. 
..........
..........', 'İnsanlar yüzyıllar yılı evler yaptılar. İrili ufaklı, birbirinden farklı,  Ahşap evler, kagir evler yaptılar. Doğup ölenleri oldu, gelip gid...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/evler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Duygusu-1-', 'sairin-duygusu-1-bayram-tunca-ejzrh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben deniz, şiir yazmadığım zaman

Suyu kesilen çeşmeye benziyorum

Ben sevdiğimi görmediğim zaman

Sanki sıkılmış limona benziyorum

Sayısız aşk şiiri yazıp, sayfama astım

Aslında yoktu, benim kötü bir kastım

Sevgimi, şiirle duyurmaktı maksadım

Aşkımı aleme duyurmaktı tek kastım

Şiir yazdığım zaman roman gibi yazarım

Sevdiğim zaman da, Ferhat gibi severim

Leyla için çöllerde Mecnun gibi gezerim

Sevip sevmediğini, gözlerinden sezerim

B. TUNCA/25.10.2000-16.37', 'Ben deniz, şiir yazmadığım zaman Suyu kesilen çeşmeye benziyorum Ben sevdiğimi görmediğim zaman Sanki sıkılmış limona benziyorum Sayısız aşk...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sairin-duygusu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Işığı', 'mum-isigi-cem-acar-no1wi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mum Işığı

Mum ışığında

          sevdamı aradım

           içim sızlayarak

O şimdi uzaklarda

Uzaklardan 

kastettiğim

Yol değil Dostum

yol değil...

           Kalp mesafesi

Ki

en acı verenide

bu 

değilmi

26 Ekim 1997

-ilkaşkıma-', 'Mum Işığı Mum ışığında           sevdamı aradım            içim sızlayarak O şimdi uzaklarda Uzaklardan  kastettiğim Yol değil Dostum yol de...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mum-isigi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ne Oldu', 'sana-ne-oldu-bayram-tunca-dwunu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bir zamanlar akıllı Bayram’dın

Şimdi mecnun gibi garip bir şairsin

Evvel böyle değildin, şimdi ne oldun

Galiba, O''nu çok sevdiğin için oldun

B. TUNCA/25.10.2000-16.37', 'Sen bir zamanlar akıllı Bayram’dın Şimdi mecnun gibi garip bir şairsin Evvel böyle değildin, şimdi ne oldun Galiba, O''nu çok sevdiğin için o...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Ne Demişler+', 'hani-ne-demisler-bayram-tunca-t2wa2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani ne demişler her işte vardır bir hayır

Bak bu âdemoğluna yapılanlar oldu hayır

Çoban Bayram, şairlikte oldu biraz mahir

O da oldu, gönüllerde taht kuran bir şair

25.10.2000-16:37

''Aşk Ateşten Gömlek''', 'Hani ne demişler her işte vardır bir hayır Bak bu âdemoğluna yapılanlar oldu hayır Çoban Bayram, şairlikte oldu biraz mahir O da oldu, gönül...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hani-ne-demisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat Et+', 'dikkat-et-bayram-tunca-emmvj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz kıyılarında martılar var

Ahiret mizanında da tartı var

Her kulun bir mizan kartı var

Allah’ın da, iki türlü startı var

25.10.2000-16:37

''Aşk Ateşten Gömlek''', 'Deniz kıyılarında martılar var Ahiret mizanında da tartı var Her kulun bir mizan kartı var Allah’ın da, iki türlü startı var 25.10.2000-16:3...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dikkat-et-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezan*', 'ezan-bayram-tunca-z1v4z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu ezan ki; sözleri Nebimizden

İlk bestesi de Habeşli Bilâl’den 

Mirastır o bize Peygamberimizden 

Kimse silemez, onu belleğimizden

Belletildi rüyada melek tarafından

Geçirildi dünyadaki en sık elekten

Korundu bugüne kadar tahribattan

Korunacak, ebede kadar tahripten

Günde, beş vakit nida eder bülbüller

Mest olur, onu duyan aşina gönüller

Ogün bugündür, dört bir yanda inler

Yer ve göktekiler, huşu içinde dinler

Dinleyip de icabet etmeyenler de var

İcabetteki kârı aklı yetmenler de var

Ne çok ziyandadırlar aah bir bilseler

Ne iyi olurdu onlar da icabet etseler

Sanki de ciğerime hançer saplanıyor

Çünkü, kimisi davete icabet etmiyor

İcabet etmeyenlere Nebi çok kızıyor

Hatta, evlerini yakasım geliyor diyor

25.10.2000-16.37', 'Şu ezan ki; sözleri Nebimizden İlk bestesi de Habeşli Bilâl’den  Mirastır o bize Peygamberimizden  Kimse silemez, onu belleğimizden Belletil...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ezan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum', 'dusunuyorum-bayram-tunca-iwyre', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkından sıtmaya tutulmuş gibi tir tir titriyorum

Sende üşürsün diye sana bir iyilik düşünüyorum

Önce, ailenden usulünce istemeyi düşünüyorum

Şayet vermezlerse, sonra kaçırmayı planlıyorum

B. TUNCA/25.10.2000-16.37', 'Aşkından sıtmaya tutulmuş gibi tir tir titriyorum Sende üşürsün diye sana bir iyilik düşünüyorum Önce, ailenden usulünce istemeyi düşünüyoru...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunuyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskişehir’de Bir Evde', 'eskisehir-de-bir-evde-bayram-tunca-8q06f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İkram edilen bir çay bir pasta.

Yaptı bana yabangülüne hasta.

O daha çok küçük çocuk yaşta.

Bilirsin akil yasta değil basta. 

25.10.2000-16,37', 'İkram edilen bir çay bir pasta. Yaptı bana yabangülüne hasta. O daha çok küçük çocuk yaşta. Bilirsin akil yasta değil basta.  25.10.2000-16,...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/eskisehir-de-bir-evde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Yanaktan Öpem', 'gel-yanaktan-opem-bayram-tunca-wkw84', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evleri beyaz badana boyalı.

Çok oldu, o kızı göz koyalı.

Evlerinin önü vişne kiraz.

Gel de, yanaktan öpem biraz.

25.10.2000-16,37', 'Evleri beyaz badana boyalı. Çok oldu, o kızı göz koyalı. Evlerinin önü vişne kiraz. Gel de, yanaktan öpem biraz. 25.10.2000-16,37...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gel-yanaktan-opem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BenimYarim', 'benimyarim-bayram-tunca-yzxyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Heybeleri var, iki gözlü.

Benim yarim, ela gözlü.

Benim yarim bana sözlü.

Benim yarim, açık sözlü

25.10.2000-16,37', 'Heybeleri var, iki gözlü. Benim yarim, ela gözlü. Benim yarim bana sözlü. Benim yarim, açık sözlü 25.10.2000-16,37...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benimyarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğanın Aşkla Dansı', 'doganin-askla-dansi-cem-acar-l9fac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam saatleri...

Etraf hafif gri

renginde,

Dalgalar gürültü

çıkararak

yalar kayaları.

Us

uzak ufukları

gözlemler.

Gri laciverte dönüştükçe,

düşünceler bulutlanır

yaşanılanlar hatırlanırken...

Renk kara ise

gökyüzünde,

 ve karamsarlık 

kaybolur ise

aniden

tuhaflık var bir yerde

diyerekten

düşünür düşünür 

dururum...

08 Ağustos 1997

-Mersin-', 'Akşam saatleri... Etraf hafif gri renginde, Dalgalar gürültü çıkararak yalar kayaları. Us uzak ufukları gözlemler. Gri laciverte dönüştükçe,...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/doganin-askla-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılsak da Helalleşelim', 'ayrilsak-da-helalleselim-bayram-tunca-09y20', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dargın durmayalım barışalım

Gel seninle hayatı paylaşalım

Uyumlu eşler olmaya çalışalım

İllâ da gideceksen helalleşelim

B. TUNCA/25.10.2000-16.37', 'Dargın durmayalım barışalım Gel seninle hayatı paylaşalım Uyumlu eşler olmaya çalışalım İllâ da gideceksen helalleşelim B. TUNCA/25.10.2000-...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayrilsak-da-helalleselim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derya ve Sevda', 'derya-ve-sevda-bayram-tunca-3t90c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Girdim girift bir deryaya

Girdim bir rey-i sevdaya

Derya ejderha gibi yutuyor beni

O yârin sevdası, kurutuyor beni

B. TUNCA/25.10.2000-16.37', 'Girdim girift bir deryaya Girdim bir rey-i sevdaya Derya ejderha gibi yutuyor beni O yârin sevdası, kurutuyor beni B. TUNCA/25.10.2000-16.37...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/derya-ve-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Gün Ömürdendir', 'gecen-gun-omurdendir-bayram-tunca-ebdy2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son baharda dökülen yapraklar gibi

Başımdaki saçlarım tel tel dökülüyor

Her geçen mevsim her geçen yıl gibi

Her geçen gün ömürden götürülüyor

B. TUNCA/25.10.2000-16.37', 'Son baharda dökülen yapraklar gibi Başımdaki saçlarım tel tel dökülüyor Her geçen mevsim her geçen yıl gibi Her geçen gün ömürden götürülüyo...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gecen-gun-omurdendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cebime Bakılsa*', 'cebime-bakilsa-bayram-tunca-kfbtm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ceplerime bakılsa, kâğıt parçası çıkar

Kâğıt parçasına bakılsa, şiirlerim çıkar

Şiirlerim okunsa, çektiğim çilem çıkar

Çilemi çekmeye kalkanların canı çıkar

25.10.2000-16.37', 'Ceplerime bakılsa, kâğıt parçası çıkar Kâğıt parçasına bakılsa, şiirlerim çıkar Şiirlerim okunsa, çektiğim çilem çıkar Çilemi çekmeye kalkan...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cebime-bakilsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isınmak İstiyorum', 'isinmak-i-stiyorum-bayram-tunca-nr336', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim üşüyor ısıtmak istiyorum

Ayağım üşüyor ısıtmak istiyorum

Bedenim üşüyor ısıtmak istiyorum

Aşkının ateşiyle ısınmak istiyorum

B. TUNCA/25.10.2000-16.37', 'Ellerim üşüyor ısıtmak istiyorum Ayağım üşüyor ısıtmak istiyorum Bedenim üşüyor ısıtmak istiyorum Aşkının ateşiyle ısınmak istiyorum B. TUNC...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/isinmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım-3-*', 'anlatamadim-3-bayram-tunca-4ze3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açlığımı toprakla yatıştırdım

Geceyi, gündüzü karıştırdım

Kendimi aç susuzluğa alıştırdım 

Ama onu yokluğa alıştıramadım

Senelerce hep yatak yaptım otları

Anlatamadım açlığımı karnı toklara

Alıştıramadım sevdiğimi yokluklara

Ben zaten alışmıştım yoksulluklara

Yastık yaptım, buz gibi taşları

Laf anlatamadım o vefasızlara

Görmedi kimse özümden akan yaşları

Acırdım açlığıma rağmen karnı açlara

Anlatamadım dertsizlere derdimi

Anlatamadım kaderimi sevdiğimi

Anlatamadım yemeyip, yedireceğimi

Anlatamadım uğrunda ölebileceğimi

Yorgan yaptım o karanlık geceleri

Hep yanımdan gelip geçti niceleri

Uzaktan bakanlar, sandılar sanki deli

Sağolsun sonunda sahip çıktı bir veli

Kınamayın dostlar bunların hepsini yaşadım

Bu çileleri nasıl yaşadığıma ben de şaşardım

O günler geldikçe usuma şükrederim Rabb’ime

Rabb’im kimseyi muhtaç etmesin namertlerine

25.10.2000-16.37', 'Açlığımı toprakla yatıştırdım Geceyi, gündüzü karıştırdım Kendimi aç susuzluğa alıştırdım  Ama onu yokluğa alıştıramadım Senelerce hep yatak...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlatamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim', 'yetim-bayram-tunca-huucg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetim/yetim ben sana ne ettim

Sen çağırdığında hep seğirttim 

Sen benim yanımda bir keyiftin 

Sen, önceleri çok iyi bir heriftin

25.10.2000-16,37', 'Yetim/yetim ben sana ne ettim Sen çağırdığında hep seğirttim  Sen benim yanımda bir keyiftin  Sen, önceleri çok iyi bir heriftin 25.10.2000-...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yetim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gidiyorum*+', 'i-ste-gidiyorum-bayram-tunca-h4lkx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte geldim, işte gidiyorum, şu fani dünyadan

Bir ömür boyu, hep koşturdum, hiç durmadan

Yine de eli boş gidiyorum aradığımı bulmadan

Hem de çoğu insan gibi muradıma doymadan

25.10.2000-16:37', 'İşte geldim, işte gidiyorum, şu fani dünyadan Bir ömür boyu, hep koşturdum, hiç durmadan Yine de eli boş gidiyorum aradığımı bulmadan Hem de...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iste-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Duygu', 'bir-duygu-cem-acar-bfmgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamın rutinliğini bozabilme

yetisini bulabilmek,

pervasızca ve korkusuzca...

Yaşamın sürekliliği

içinde kaybolmak,

süreksizliğin hazını duya duya...

Şiirler gibi akıp gidebilmek

en derin

yalnızlıklar...

24 Nisan 1996

-tren yolculuğu-', 'Yaşamın rutinliğini bozabilme yetisini bulabilmek, pervasızca ve korkusuzca... Yaşamın sürekliliği içinde kaybolmak, süreksizliğin hazını du...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Göz', 'bir-cift-goz-bayram-tunca-t989j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sendeki, o bir çift çakır göz

Yaptı yüreğime sönmez köz

Nerede kaldı o verdiğin söz

Gel de sen, şimdi bu işi çöz

B. TUNCA/25.10.2000-16.37', 'Sendeki, o bir çift çakır göz Yaptı yüreğime sönmez köz Nerede kaldı o verdiğin söz Gel de sen, şimdi bu işi çöz B. TUNCA/25.10.2000-16.37...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-cift-goz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkili Dörtlükler+', 'i-kili-dortlukler-bayram-tunca-bdf00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İkili dörtlükler, yumurta ikizi gibidir

İkili dörtlükler âşık-maşuk misalidir

İkisini birbirlerinden ayrı koyamam

Bir kez okumakla tadına doyamam

Çiğ yumurtayı dahi tek başıma soyamam

Sevdiğimden başkasını kalbime koyamam

Ben aşkın tadına tek başıma hiç doyamam

İkili dörtlüklerimi, şiirlerden ayrı koyamam

25.10.2000-16:37

Aşk Ateşten Gömlek', 'İkili dörtlükler, yumurta ikizi gibidir İkili dörtlükler âşık-maşuk misalidir İkisini birbirlerinden ayrı koyamam Bir kez okumakla tadına do...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ikili-dortlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktur Söylenecek Sözüm', 'coktur-soylenecek-sozum-bayram-tunca-y213m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoktur; vefasız dostlara söylenecek sözüm

Vefasızlara söylesem de anlaşılmaz sözüm

Aslında, dünyalıklarında yoktur hiç gözüm

Aslında Yörük efesidir benim gerçek özüm

Burada söylesem yine yanlış anlaşılır sözüm

Belki de ma-kes bulmaz havada kalır sözüm

Susma hakkımı kullanıyorum, saklıdır sözüm

Yeri geldiğinde, söylenecektir o acıklı sözüm

B. TUNCA/25.10.2000-16.37', 'Çoktur; vefasız dostlara söylenecek sözüm Vefasızlara söylesem de anlaşılmaz sözüm Aslında, dünyalıklarında yoktur hiç gözüm Aslında Yörük e...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/coktur-soylenecek-sozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alamadım Çakır Gözlüğü', 'alamadim-cakir-gozlugu-bayram-tunca-7yvxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Verin bana çifte gözlüğü

Vurayım o yalan sözlüyü

Bulamadım ben tokgözlüyü

Alamadım ben çakırgözlüğü

Çakır gözlüden bana yâr olmaz artık

O yalancığı vursam da ar olmaz artık

Gençliğim var, vursam da kâr olmaz

Zaten o da bu dünyada mutlu olmaz

B. TUNCA/25.10.2000-16.37', 'Verin bana çifte gözlüğü Vurayım o yalan sözlüyü Bulamadım ben tokgözlüyü Alamadım ben çakırgözlüğü Çakır gözlüden bana yâr olmaz artık O ya...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/alamadim-cakir-gozlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne Diyorsun+', 'sen-ne-diyorsun-bayram-tunca-f61ho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün bir şey örüp duruyorsun

Benim neler çektiğimi görüyorsun

Sana âşık olduğumu da biliyorsun

Malumu ilân oldu sen ne diyorsun

Mecnun misali gezinip duruyorum

Soğuktan yetim gibi büzülüyorum 

Aşkımı anlatamayışıma üzülüyorum

Senden gelecek sinyali gözlüyorum

10.10.2000-17:55

Aşk Ateşten Gömlek', 'Her gün bir şey örüp duruyorsun Benim neler çektiğimi görüyorsun Sana âşık olduğumu da biliyorsun Malumu ilân oldu sen ne diyorsun Mecnun mi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ne-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Kim Tanır', 'gercek-kim-tanir-bayram-tunca-knm2i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sel yıkar gider, kumu kalır

Yâr bırakır gider gamı kalır

Bilen bilir de bilmeyen, onu dostum sanır

Ben tanıyamadım, acep onu esasen tanır

Kulaklarım çınlıyor, acep beni kim anıyor

Söyleyin dostlar beni gerçek kim tanıyor

Bilen biliyor, bilmeyen beni sağlam sanıyor

Benim gibisi de nedense, böylesine kanıyor

Ah bir bilebilseniz, yüreğim nasıl da yanıyor

Bir vefasızın yüzünden içim hep kan ağlıyor

Ayakta gören dostlarım, beni sağlam sanıyor

Bilmiyorlar ki, kanım mama gibi hep kaynıyor

B. TUNCA/25.10.2000-16.37', 'Sel yıkar gider, kumu kalır Yâr bırakır gider gamı kalır Bilen bilir de bilmeyen, onu dostum sanır Ben tanıyamadım, acep onu esasen tanır Ku...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gercek-kim-tanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr Gelse Derman Olur+', 'y-r-gelse-derman-olur-bayram-tunca-gulas', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur taneleri birleşse sel olur

Gözyaşlarım birleşse derya olur

Tartılsa çilemiz onunki katre, benimkisi derya olur

Başkası değil de o yâr gelse, yarama merhem olur

Kar taneleri birleşse, çığ olur

Gözyaşlarım birleşse, çay olur

Yârim bugün de gelmezse kaç aylar olur

Yârim kendi gelse, derdime derman olur

Dolu taneleri birleşse, harman olur

Gözyaşlarım birleşse, deryalar olur

O yâr bugün de gelmezse, söyleyin kaç yıl olur

O yâr kendisi gelse, belki derdime derman olur

Dereler birleşse çay olur

Çaylar birleşse nehir olur

Nehirler birleşse derya olur

O yâr kendi gelse, inan derdime derman olur

10.10.2000-18:10

Aşk Ateşten Gömlek', 'Yağmur taneleri birleşse sel olur Gözyaşlarım birleşse derya olur Tartılsa çilemiz onunki katre, benimkisi derya olur Başkası değil de o yâr...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yar-gelse-derman-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin Bizi Yaradan', 'sensin-bizi-yaradan-bayram-tunca-1bsrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgâr esiyor karadan

Dağı taşı kaldır aradan

Seni seviyoruz Yaradan

Sensin her şeyi  yaratan

Meltem esiyor denizden

Hesap sorarsın hepimizden

Aman diler şu ademoğlu Senden

Affetmezsen, ne gelir elimizden

B. TUNCA/25.10.2000-16.37', 'Rüzgâr esiyor karadan Dağı taşı kaldır aradan Seni seviyoruz Yaradan Sensin her şeyi  yaratan Meltem esiyor denizden Hesap sorarsın hepimizd...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensin-bizi-yaradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemedim*', 'diyemedim-bayram-tunca-nw7l5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani derler ya, damlaya damlaya göl olur

Gözyaşlarım birleşse, göl değil, derya olur

Görenler sordu sen böyle değildin ne oldu

Diyemedim düşmandan çok dostlar yordu

Israrla sordular sen böyle değildin ne oldu

İçimde yanan ateş değil, sanki de akkordu

Ellerim istemeyerek de olsa, saçlarımı yoldu

Diyemedim, dostlardan ziyade o nazlı yordu

10.10.2000-17.55', 'Hani derler ya, damlaya damlaya göl olur Gözyaşlarım birleşse, göl değil, derya olur Görenler sordu sen böyle değildin ne oldu Diyemedim düş...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/diyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İstanbul Sabahı', 'bir-i-stanbul-sabahi-yalcin-aydin-ndp8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahını yaşadım İstanbul

Yeniden doğmuş gibiyim.

Güneşin doğdu Kızkulesi''nden

Martıların çığlıkları kulaklarımda...

Rüzgarın mı titretti beni,

Yoksa sen mi ?

Birkaç balıkçı umut salladı denize

Bekleyişe sarıldı misinalar.

Esrarlı kokun dolaşıyor sahilde

Sessizliğin,sanki birşey anlatır gibi...

Anıların mı titretti beni,

Yoksa sen mi ?', 'Sabahını yaşadım İstanbul Yeniden doğmuş gibiyim. Güneşin doğdu Kızkulesi''nden Martıların çığlıkları kulaklarımda... Rüzgarın mı titretti be...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Aydın']::text[], 8.5, '{"poet":"Yalçın Aydın","poet_slug":"yalcin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-istanbul-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünmek', 'gorunmek-bayram-tunca-rs5rp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ekser suret-i haktan görünürsün

Bin bir çeşit urbaya bürünürsün

Yaptığınla, her daim övünürsün

Bilesin, belki orada dövünürsün

Hizmette geri, ücrette önde görünürsün

Dinin ve imanınla, her daim övünürsün

Her zaman her yerde önde görünürsün

Unutma ki, belki de ahrette dövünürsün

B. TUNCA/25.10.2000-16.37', 'Ekser suret-i haktan görünürsün Bin bir çeşit urbaya bürünürsün Yaptığınla, her daim övünürsün Bilesin, belki orada dövünürsün Hizmette geri...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gorunmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberim Var Dağlar', 'haberim-var-daglar-bayram-tunca-lcxvr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım ırmaklarınız gibi çağlar

Size bir acı haberim var yüce dağlar

Boşuna sevinmeyin hey yüce dağlar

Bakın baraj oluyor o güzelim vadiler

Hiç kâr etmiyo artık ağlayıp/sızlamalar

Gem vuruyorlar artık sularınıza dağlar

Hiç de kâr etmiyor, bağırıp/çağırmalar

Sular altında kalıyor, o güzelim ovalar

Oy Dağlar, ne atlarınız ne de terkileri kaldı

Tek o güzel öyküleriniz ile türküleriniz kaldı

Ne o eski bağlarınız kaldı, ne de bostanınız

Sizi de kirlettiler, yoktur artık o eski tadınız

B. TUNCA/25.10.2000-16.37', 'Gözyaşlarım ırmaklarınız gibi çağlar Size bir acı haberim var yüce dağlar Boşuna sevinmeyin hey yüce dağlar Bakın baraj oluyor o güzelim vad...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haberim-var-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Olur', 'tatli-olur-bayram-tunca-1avel', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tatlı olur, Pekmez Tarlasının yemişi

Tatlı olur, o yaban gülünün gülüşü

Tatlı olur, o yârin dudaktan öpüşü

Tatlı olur, o yârin seviyorum değişi

Tatlı olur, Pekmez tarlasının inciri

Tatlı olur, o yaban gülünün incisi

Tatlı olur, Pekmez Tarlasının meyvesi sebzesi

Tatlı olurdu, yaban gülümün boynuma sarılışı

B. TUNCA/10.10.2000-17.55', 'Tatlı olur, Pekmez Tarlasının yemişi Tatlı olur, o yaban gülünün gülüşü Tatlı olur, o yârin dudaktan öpüşü Tatlı olur, o yârin seviyorum değ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tatli-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-cem-acar-z9087', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedendir bilinmez

Kalplerin savruluşu

bu denli haykırışlarla

dolu...

Yaşam rüzgarının yönsüzlüğü

Sevginin dayanılmaz

acıları

Ve de

nedendir biliyormusun

dostum

seni ne için sevdiğimi...

Yaşam kokundur 

rüzgarlarla dansındır

yüce sevgindir

beni çeken....

18 kasım 1996

   -Ebru''ya-', 'Nedendir bilinmez Kalplerin savruluşu bu denli haykırışlarla dolu... Yaşam rüzgarının yönsüzlüğü Sevginin dayanılmaz acıları Ve de nedendir ...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dost-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annededir*', 'annededir-bayram-tunca-zgrvw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baldan tatlıdır dilleri

Bereketlidir ak elleri

Hep sıcaktır sineleri 

Şefkatlidir yürekleri

Annedir, hep aşkın odağı

Odur hepimizin ilk burağı

Odur en iyi sevgi yumağı

Onlar kurar, sıcak yuvayı

Ondadır hilal kaş/ipek saç

Annelere yakışır en iyi taç

Anne, başa taç, derde ilaç

Evlat pir olsa, ona muhtaç

Onların mekanı cennet-i ala

Onlara layık olabilene ne ala

Acep bizler ne dururuz hala

Alsak, onların sözlerini gala

Anneler cazibenin ana merkizi

Çeker mıknatıs misali hepimizi

Anneler, ailemizin iffet abidesi

Onlarla çoğalıyor ademin nesli

O nezaket ve zerafet kaynağıdır

Damıtılmış anzer balı tadındadır

Kokunun ve dokunun hülasasıdır

Nebimizin sevdiği üçten birisidir

Anneye yakışır lâl ü güher sözler

Çünkü onlardadır tüm güzellikler

Onlardadır hilâl kaş/sırma saçlar

Annelere yakışır en ahsen taçlar

Melekleri kıskandırır ondaki vasıflar

Onları yerdeki ve göktekiler alkışlar

Cennetin anahtarı onun rızasındadır

Cennet annelerin ayağının altındadır

25.10.2000-16.37

NOT:

Bu şiirim en çok okunulan bir şiirimdir', 'Baldan tatlıdır dilleri Bereketlidir ak elleri Hep sıcaktır sineleri  Şefkatlidir yürekleri Annedir, hep aşkın odağı Odur hepimizin ilk bura...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/annededir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Anam*', 'ah-anam-bayram-tunca-wb8ob', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kollarını beşik yapıp salladın

Yediğim her lokmayı balladın

Her türlü kötülükten kolladın

Her zaman başımı sıvazladın

Gelin ve damat misali süsledin

Her şeye rağmen hiç küsmedin

Ayrıldığımda yollarımı gözledin

Hasretimle de ciğerini közledin

Başımın tacı, derdimin ilâcı anam

İnan senin hakkını hiç ödeyemem

Senin kadar hiç kimseyi sevemem

Hiçbir vakit, sana öf bile diyemem

Sırtımı dayadım, palamut ağacına

Ben nasıl dayanayım  senin acına

Anam derdim, çoğu kez o bacıma

Kim anlar ki hasretinle yandığıma

Sırtımı dayadım, kuru ardıç ağacına

Nasıl da dayanırım senin yokluğuna

Anam bilip, anam dedim, analığıma

Kim derman olur ki, benim sancıma

Ah anam, dolandım hep köşe bucak

Bulamadım senin ki gibi sıcak kucak

Sensiz, benim garip halim ne olacak

Desene, evladın daha çook donacak

Acım birken, sensiz oldu, elvan elvan

Çook kuru ekmek yedim, yavan yavan

Ne çok yayan yürüdüm, çıplaktı taban

Ne de yaman üşüdüm, yavandı kaban

Sırtımı dayadıklarım vefasız çıktılar anam

Yediklerimi bir bir boğazıma tıktılar anam

Feryad-ı figanlarım ta arşı âlâya çıktı anam

Çilelerime dayanamadım canım çıktı anam', 'Kollarını beşik yapıp salladın Yediğim her lokmayı balladın Her türlü kötülükten kolladın Her zaman başımı sıvazladın Gelin ve damat misali ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ah-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Nasıl Duruyor Acaba+', 'o-nasil-duruyor-acaba-bayram-tunca-fiurb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava bulutlu gözlerim buğulanıyor

Kış aylarında hava çabuk kararıyor

Onu görmediğimde ufkum daralıyor

Yüreğim yanıyor gözlerim kararıyor

Böyle sisli havalarda gözlerim buğulanıyor

Onsuz duramıyorum, acep o nasıl duruyor

Onu görmediğimde ela gözlerim sulanıyor

Ancak onu gördüğümde yüzüm nurlanıyor

25.10.2000-16:37

Aşk Ateşten Gömlek', 'Hava bulutlu gözlerim buğulanıyor Kış aylarında hava çabuk kararıyor Onu görmediğimde ufkum daralıyor Yüreğim yanıyor gözlerim kararıyor Böy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-nasil-duruyor-acaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağım Solum*', 'sagim-solum-bayram-tunca-cakhh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağımda melek/solumda melek

Nasıl çelme takarsın ah be felek

Söylesene, günahım nedir bilem

Günahlarım için çok tövbe edem

Sağımda bir oğlum/solumda bir oğlum

Sanki de her biri, en güçlü birer kolum

Artık mutluluktur, her an benim yolum

Onlar olmazsa, tutmaz ki benim kolum

Beni benden değil, komşumdan sorun

Beni benden değil, dostlarımdan sorun

Beni benden değil, şahitlerimden sorun

Beni benden değil, şiirlerimden öğrenin

Sağımda bir oğlum, solumda diğer oğlum

Sanki, her ikisi de güçlü, birer elim/kolum

Ezelden beri, hak yoludur, her daim yolum

Ne kadar yaşasam da yine ölümdür sonum

25.10.2000-16.37', 'Sağımda melek/solumda melek Nasıl çelme takarsın ah be felek Söylesene, günahım nedir bilem Günahlarım için çok tövbe edem Sağımda bir oğlum...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sagim-solum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derinlik ve Sevgili', 'derinlik-ve-sevgili-cem-acar-yi0en', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derinlik

gizem''in

belirsizliğin

umudunmu içinde

yoksa

senin ruhundamı saklı...

      Varoluş

      sonsuzluğun başdöndürücü

      yalnızlığına dek...

Sevmek

aşkın vazgeçilmez

sarhoşluğuna kadar...

      Ve Sen

Umudu buluncaya dek

bekleyeceksin

Ki ulaşabilmek

için

dayanılamaz duygulara

ölümün serin sessizliğine...

O da bir çaremi

yoksa kaçışmı

onu şunu bilmem...

bildiğim

    sen umutsun

    sen gizemler tanrıçasısın

15 nisan 1995

-ilkaşkıma-', 'Derinlik gizem''in belirsizliğin umudunmu içinde yoksa senin ruhundamı saklı...       Varoluş       sonsuzluğun başdöndürücü       yalnızlığı...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/derinlik-ve-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezgi', 'ezgi-cem-acar-f9ptp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz belirsizliğe takılmış

Etraf mavi karanlığında

Ve Ezgi ayrılıverdi

aramızdan...

Pembe renginde

pembe renginde...

ağustos 1995', 'Göz belirsizliğe takılmış Etraf mavi karanlığında Ve Ezgi ayrılıverdi aramızdan... Pembe renginde pembe renginde... ağustos 1995...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-cem-acar-v6jzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak bir limanda

demirleyen gemiye

binmek isterken yürekler

bir yandan hayal kurarlar

-sevginin eşsiz kışını-

Sahilin öbür yanı

beklerken sevgilileri...

Ne çok acı çeker

Deli-Kanlılar...

Gözler beklerken umudu

hayatın anlamını sorgular...

Dalgalarla gelen demir parçası

ne çok yüreği ateşlendirir

ansızın...

18 mayıs 1995 

-adana-', 'Uzak bir limanda demirleyen gemiye binmek isterken yürekler bir yandan hayal kurarlar -sevginin eşsiz kışını- Sahilin öbür yanı beklerken se...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/liman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam ve Anılar', 'yasam-ve-anilar-cem-acar-ybda8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam

Yaşam dediğimiz

birkaç anı 

birkaç dost

belkide bir sevgili...

Peki ya dostum

ya o unutulmaz sohbetler,

kahkahalar ve hüzünle 

içiçe şarap votka 

kokan geceler

yaşam değilmiydi...

Seneler sonra

hatırlanmazmı

beynin bir köşesinden

ansızın çıkıvermezmi

unutulmuşmu olacak

Ve seninle karşılaştığımızda

dostum,

gülümsemeyecekmiyiz

geçmişe

güzelliklere,

bir tutam sevgiyi

göndermiyecekmiyiz

zaman tünelinden geriye...

Mezar taşına uğurlandığımız

gün

anılardan başka

kalacak birşeyler olamayacağını

bilerekten....

          Nisan 1995

          -Ebru''ya-', 'Yaşam Yaşam dediğimiz birkaç anı  birkaç dost belkide bir sevgili... Peki ya dostum ya o unutulmaz sohbetler, kahkahalar ve hüzünle  içiçe ş...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasam-ve-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Duygu', 'uc-duygu-cem-acar-yei74', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek

       yıldızların çarptığı anlar gibi

       deniz suların kabarışı gibi

       ölesiye...

Beklemek

sonsuzluğa demir atmışçasına

baharda çiçek açmayı

bekleyen ağaçlar misali

       Birleşmek

       toprak ile tohum misali...

20 mayıs 1994

-mersin-', 'Sevmek        yıldızların çarptığı anlar gibi        deniz suların kabarışı gibi        ölesiye... Beklemek sonsuzluğa demir atmışçasına bah...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uc-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın Sessizliğinde', 'karanligin-sessizliginde-elif-gultekin-wl1uv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlığın sessizliğinde,

Bir kız geçer bu sokaktan.

İçindeki heyecandan bellidir,

Sıcak yuvasına yol alır,

Hiç durmadan

Karanlığın sessizliğinde,

Ve kışın sert soğuğunda

Bir çocuk yatar bu sokakta

Yüzündeki hüzünden bellidir üşüdüğü

Karanlığın sessizliğinde,

Ve yazın serin akşamında,

Nineler oturur bu sokakta

İçindeki kıpırtıdan bellidir,

Yarın oğlu gelecektir

Karanlığın sessizliğinde

Bir güneş batar bu sokakta

Yüzündeki beyazlıktan bellidir,

Kavuşmuştur Rab’bına

Karanlığın sesizliğinde

Bir ay doğar güneşin ardından

İçimdeki sevinçten bellidir

Artık gün birmiştir

Elif Gültekin', 'Karanlığın sessizliğinde, Bir kız geçer bu sokaktan. İçindeki heyecandan bellidir, Sıcak yuvasına yol alır, Hiç durmadan Karanlığın sessizli...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/karanligin-sessizliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hoş Olurdu', 'ne-hos-olurdu-elif-gultekin-kmtxb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne hoş olurdu bir gemiye binip,

Gitmek uzak diyarlara

Ya da bir atın üzerinde 

Koşmak doyasıya

Ne hoş olurdu düşünüp durmak

Seni sevdiğimi, 

Hayatı sevdiğimi,

Ne hoş olurdu sevmek

Bir ağacı,bir insanı

Doğayı sevmek kısacası

Ne hoş olurdu yağmur altında

Doyasıya koşmak

Ya da deniz kenarında

Atışırmak

Ne hoş olurdu eskiye gitmek

Komşuluğu arkadaşlığı görmek

Tarihi hissetmek

Ne hoş olurdu bilmek

Herşeyin doğru olduğunu

Yalansız bir dünyada yaşandığını

Ne hoş olurdu bilsen

Bir tren geçerken kalbimin üzerinden

Seni tekrar görebilmek....', 'Ne hoş olurdu bir gemiye binip, Gitmek uzak diyarlara Ya da bir atın üzerinde  Koşmak doyasıya Ne hoş olurdu düşünüp durmak Seni sevdiğimi, ...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-hos-olurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik Perisi', 'i-yilik-perisi-i-smail-hakki-kavurmaci-8f9qk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne olur ki gelse

masallardaki

o iyilik perisi

masamda çay

kafam karmakarışık

gönlüm dar

ne olurki gelse

salına salına

şu kapıdan içeri dalsa

iyi bir dost

ya da bir sevgili gibi

gülücükler saçarak

 ''merhaba canım

çok bekletmedim ya'' dese

ben şaşkın ama sevinçli

otursa karşıma

bir sigara yaksa

birde çay söylesem

bu gün bu masada

benide sevindirse

yalnızlığımı şenlendirse

ne olur ki.', 'ne olur ki gelse masallardaki o iyilik perisi masamda çay kafam karmakarışık gönlüm dar ne olurki gelse salına salına şu kapıdan içeri dalsa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iyilik-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dirsaiz Kuyu', 'dirsaiz-kuyu-unal-gul-w8bhb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hızla iniyorum ruhunun derinliklerinde

sanki dipsiz bir kuyuya düşüyorum.

Hani kanı çekilir ya insanın 

işte öyle.

Bir fark var yalnız,

dibe indikçe  daha aydınlık her yer.

Bu duyguyu seviyorum,

Seni seviyorum.', 'Hızla iniyorum ruhunun derinliklerinde sanki dipsiz bir kuyuya düşüyorum. Hani kanı çekilir ya insanın  işte öyle. Bir fark var yalnız, dibe...', ARRAY['Türk Edebiyatı','Şiir','Ünal Gül']::text[], 8.5, '{"poet":"Ünal Gül","poet_slug":"unal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dirsaiz-kuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayale Ağlarım', 'hayale-aglarim-yasli-dost-aezvg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimileri aşklarını,kimileri acılarını,

Bense hayallerimi anlatırım şiirlere.

Ne aşk ,ne üzüntü gerçektir benim için.

Hepsi birer hayaldir.

Ve ben sadece bir hayale aşık olur ,

Bir hayale ağlarım.

Gözyaşlarım da hayaldir benim için.

Gözlerimden ruhuma süzülürler gizlice,

Gizli bir hayali anlatırlar kalbime.

Asla gerçek olamayacak bir hayal için,

Ağlarım ben sadece.', 'Kimileri aşklarını,kimileri acılarını, Bense hayallerimi anlatırım şiirlere. Ne aşk ,ne üzüntü gerçektir benim için. Hepsi birer hayaldir. V...', ARRAY['Türk Edebiyatı','Şiir','Yaşlı Dost']::text[], 8.5, '{"poet":"Yaşlı Dost","poet_slug":"yasli-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayale-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Yoksul, Işıksız Sokaklardan', 'su-yoksul-isiksiz-sokaklardan-ataol-behramoglu-pk9ls', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu yoksul,ışıksız sokaklardan geçerken akşamüstleri

Elimde yiyecek filesi,evime doğru

Siliniyor sanki zihnimin yorgunluğu

Isıtıyor halkımın ozanı olmak duygusu içimi

Yıpranmış ellerinde bir sokak çiçekçisinin

Bir kırmızı gül gibi', 'Şu yoksul,ışıksız sokaklardan geçerken akşamüstleri Elimde yiyecek filesi,evime doğru Siliniyor sanki zihnimin yorgunluğu Isıtıyor halkımın ...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/su-yoksul-isiksiz-sokaklardan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapishanede Bir Sabah Türküsü', 'hapishanede-bir-sabah-turkusu-ataol-behramoglu-qz5l0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maltepe Askeri cezaevinin avlusunda

Sisler içindeki Büyükada''nın karşısında

Oturmuş yazarım bu şiiri

Eylül başlarında bir cumartesi sabahı

Lodos titretiyor ağaçları

Yağmur geceden yıkamış çiçekleri

Gökyüzü mavi,bulutlar beyaz

Ardından baharın geçti koca bir yaz

Hapisteyiz hala ve güzün ilk serinlikleri

Avlunun dört yanı dikenli teller

Tellerin gerisinde nöbetçiler bekler

Kapanır uykusuzluktan gözleri

On gündür çocuk sesi duymadım

Özledim ''baba'' deyişini kızımın

Özledim beni görünceki sevincini...

Hayatım benim, kırk yıllık hayatım

Seni başarabildiğimce dürüst yaşadım

İçim burada da pırıl pırıl şimdi

Geçer,güzelim,bu günler de geçer

Sökülüp atılır dikenli teller

Koparır halk bir gün zincirlerini', 'Maltepe Askeri cezaevinin avlusunda Sisler içindeki Büyükada''nın karşısında Oturmuş yazarım bu şiiri Eylül başlarında bir cumartesi sabahı L...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hapishanede-bir-sabah-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar', 'asiklar-ahmet-oner-wtnbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tertemiz aşkımı lekeledin sen

bir türlü kendime gelemedim ben

sensizlik çok zormuş inan

SEVDİĞİM

seni seviyorum diyemedim ben

derbeder sokaklarda çilekeş oldum ben

soğuk kaldırımlarda beklerken 

yinede seni seviyorum 

diyemedim ben', 'tertemiz aşkımı lekeledin sen bir türlü kendime gelemedim ben sensizlik çok zormuş inan SEVDİĞİM seni seviyorum diyemedim ben derbeder sokak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öner']::text[], 8.5, '{"poet":"Ahmet Öner","poet_slug":"ahmet-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asiklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar', 'tekrar-akin-kir-5qsgr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün gelipte tekrar karşılaşırsak;

Yanmış bir aşkın küllerini,

Ellerimde bulacaksın.

Bakacaksın gözlerime,

Ağlamaklı olacaksın.

Ben,

Savuracağım o külleri;

Ve külü bile kalmayan,

Eski aşkımızı unutup,

Yepyeni bir aşka bşlayacağız.

                Birlikte...

                           El ele...

                                    Sevgiyle...', 'Gün gelipte tekrar karşılaşırsak; Yanmış bir aşkın küllerini, Ellerimde bulacaksın. Bakacaksın gözlerime, Ağlamaklı olacaksın. Ben, Savuraca...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tekrar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Türetmek', 'sevgiyi-turetmek-ceyhun-atuf-kansu-vjirn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi sözcüğünü türettim

Ayışığını buldum sıcak bozkır sekisinde

Kara ipek saçlarını gecenin.

Çınar ağacını güz sözlüğünden

Gölgesi bile Türkmen

Sevgi sardı dört yanımı dal toprak.

Kırmızı alıç boncuğunu

Aldım dizdim sevginin ipliğine

Çocukluk çerçisinden.

Oyun sözcüğünden bir torba

Bir torba taze ceviz türettim

Sevgiyi söyler vurdukça birbirine.

Dere boyu Mamak gecekondu önü bahçe

Sarı ayvadan türettim istasyonda

Akşam eve dönen yorgun sevgiyi.

Dede Korkut'' tan o kesme taş Türkçeden

Bir kale yücelttim sevgi sözlerinden

Sarar bedenini yayla çiçek gözleri.

Sevgi türettim bin kez asma dalından

Yunus''un bağında erdi üzüm

Kızardı dirildi sonunda ölüm.

Sevgidir topraktan türettiğim can sözcüğü.', 'Sevgi sözcüğünü türettim Ayışığını buldum sıcak bozkır sekisinde Kara ipek saçlarını gecenin. Çınar ağacını güz sözlüğünden Gölgesi bile Tür...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun-atuf-kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgiyi-turetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınak', 'siginak-nihat-behram-bre97', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yedeğimde hep bir şiir olmalı 

Korusun diye beni, 

Sarsın 

Solusun diye... 

Yedeğimde hep bir şiir olmalı 

Dileğimce değiştirebildiğim 

Değiştikçe beni de değiştiren 

Yüreğimle sindiğim, 

Kimsenin bilmediği, 

Acısına başka acı 

Sevincine başka sevinç değmemiş, 

Canım gibi 

Yok etmek hakkını kendimde gizlediğim 

Ömrümce çılgın, gönlümce engin, 

Yeni doğmuş bebeklerin sesiyle 

Yankısı ufkuma dokunurcasına yakın

Soluğumda kıvılcım, dudağında gül 

Yaşamaya düğümlü, 

Goncalar kadar körpe 

Dalgalar kadar hırçın 

Kavuşmamız olanaksız birine sakladığım, 

Mahrem, bağışıksız, 

Mazlum bir şiir 

Yedeğimde hep bir şiir olmalı; 

Çırpındığım geceler 

Yetişip yatıştıran 

Esinlenip dindiğim, 

Duygusu sağılmamış, 

Üşüse soluverecek, 

Pürüzsüz, bir başına incecik, 

Gülüşü gülüşüme denk, andıkça parıldayan

Andıkça parıldadığım, 

Kanmayan, kandırmayan; 

Öfkesi kirlenmemiş, 

Zehri gibi kendi hayatımın 

Ayrılık yaralarını sarılır sanmış, 

Sürgün, ürkütülmüş, 

Üzgün bir şiir. 

Yedeğimde hep bir şiir olmalı

Yuvasında ilk kez uçan serçe gibi telaşlı, 

Şafakta kuzulamış karaca gibi baygın, 

Ulaşınca çılgınlığa kırılan dallarda ömrün 

Yanarak uğuldayan 

Yanarak uğuldadığım... 

Yine daldım da kendi düşüme

Hasretin kanayışı bitermiş sandım... 

Beni şiirler bağışlasın!', 'Yedeğimde hep bir şiir olmalı  Korusun diye beni,  Sarsın  Solusun diye...  Yedeğimde hep bir şiir olmalı  Dileğimce değiştirebildiğim  Deği...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/siginak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Gazel', 'olume-gazel-nihat-behram-w6t6x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsandır en yüce değerleri yaratan. 

                      Sevdayı sözgelimi, 

                      erdemi, özlemi, özveriyi, 

                      umudu, şefkati, düşü... 

                      Yaşamı tanıdıkça kendini tanımlayan... İnsandır... 

                      Ve fakat 

                      yakalar yakalamaz uygun bir an 

                      bulur bulmaz dengini 

                      durmaz 

                      tümünü 

                      haraç mezat pazarlar... 

                      Soylu mu soylu, huylu mu huylu; 

                      hırsız mı hırsız, arsız mı arsız! 

                      İnsandır... 

                      Tanrılar yaratacak denli esinli, tinsel, engin... 

                      Canı pahasına direnecek denli gözüpek, 

                      atılgan, seçkin... 

                      Ve fakat 

                      kendi büyüsüne sığınacak denli bitkin, 

                      güvensiz, sefil... 

                      Sefasını sefaletten sağacak denli rezil... 

                      Özlü mü özlü, sözlü mü sözlü; 

                      bezgin mi bezgin, azgın mı azgın! 

                      İnsandır... 

                      Diş diş dudaklarında 

                      özgürlüğün tutkusu kıvılcımlanır, 

                      çığlığı gecenin ışıltısı olur şarkılarında. 

                      Çağıran acılarsa eğer 

                      koşar 

                      üleşir her şeyini... 

                      Ve fakat 

                      ışıltının karşısında kuduran da odur... 

                      Bilgine değil, haine tapan; 

                      kendi türünü yok etmenin ustası; 

                      doydukça bölüşmeyi unutan... 

                      Masum mu masum, mazlum mu mazlum; 

                      Katil mi katil, zalim mi zalim! 

                      İnsandır... 

                      Bir o’dur ölümlü doğuşunun bilgisiyle yaşayan... 

                      Vurgunu olduğu göğe süssüz, 

                      sürgünü olduğu cana güçsüz, 

                      çılgını olduğu tene öksüz... 

                      Narince açan... Soldukça üzgün... 

                      Sevincini bile gözyaşıyla yoğuran... 

                      bir yanı hep anılara sarmaşık... 

                      Gönül boyu yaralı... Ömür boyu âşık... 

                      Bağrında özlem, sırtında hançer 

                      dağları delip, ağzında ışıkla gelebilir... 

                      Coşkun, düşlü, dövüşken... 

                      Ve fakat 

                      çıkan için ufkunu yakan 

                      dostunu satan da odur... 

                      Doymak bilmezcesine çakalcana açgözlü; 

                      uygarlığınca acımasız, evcilliğince vahşi... 

                      Korkak, kaypak, sürüngen... 

                      Ulaşsa 

                      denizler gibi yıldızlar da kirlenir ellerinde... 

                      Binlerce yılmış gibi ömrü, onlarca yıl susabilir; 

                      suskunluğu çatal çatal, yılanca zehirlidir... 

                      İçli mi içli, güçlü mü güçlü; 

                      suçlu mu suçlu, hınçlı mı hınçlı! 

                      İnsandır... 

                      Sonunda solacak, 

                      kurumuş bir yaprak gibi rüzgâra ilişerek 

                      geldiği toprağa dönecektir. 

                      Yücelerde soluduysa ömrünü 

                      baharda sazı kalır 

                      dallarda hızı kalır 

                      kuşlarda açar sesi 

                      dillerde sözü kalır... 

                      Irmağın kıvrım kıvrım suyunda 

                      köpürür, gümüşlenir... 

                      döndükçe gümüşlenir... 

                      Arının kekik tüten balıyla 

                      leylaklar kınalanmış bakışlar kutsar onu, 

                      köklere sürgünlere uğurlar... 

                      Ardı sıra 

                      ateşböcekleri uçuşur, 

                      su tutuşur... 

                      Dalgalar alkışlarıdır... 

                      Kimi ölür izi kalır, 

                      kimi ölür buzu kalır', 'İnsandır en yüce değerleri yaratan.                        Sevdayı sözgelimi,                        erdemi, özlemi, özveriyi,              ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/olume-gazel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'böyle giderse', 'boyle-giderse-life-is-life-3k99m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kin dolu yürekler sevgi yok oldu...

Namussuzlar düzenbazlar sel oldu...

Gerçeğe kapandı gözler kör oldu...

Sonumuz karanlık böyle giderse...

Kahramandır dedik cana kıyana...

Helal dedik memleketi soyana...

Bel bağladık söz veripte cayana.....

Sonumuz karanlık böyle giderse...

İşimiz bu;  dedikodu  vesvese...

Bir göz ile bakamadık herkese..

Önce insan diyemedik nedense.....

Sonumuz karanlık böyle giderse..', 'Kin dolu yürekler sevgi yok oldu... Namussuzlar düzenbazlar sel oldu... Gerçeğe kapandı gözler kör oldu... Sonumuz karanlık böyle giderse......', ARRAY['Türk Edebiyatı','Şiir','Life is Life']::text[], 8.5, '{"poet":"Life is Life","poet_slug":"life-is-life","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-giderse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminim Olsun', 'yeminim-olsun-life-is-life-7sgrb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülüşünle güneş doğar geceye

Yokluğunda hüzün çöker  her  heceye

Söylemiştim  sana  belki  binlerce

Unutmayacağım seni;  ölsemde

Geceler  bitsin  artık  sabah  olsun

Bu  karanlık  dünyama  güneş  doğsun

Başkasına bakarsa gözlerim  kör olsun

Canımdan çok sevdiğime yeminim  olsun', 'Gülüşünle güneş doğar geceye Yokluğunda hüzün çöker  her  heceye Söylemiştim  sana  belki  binlerce Unutmayacağım seni;  ölsemde Geceler  bi...', ARRAY['Türk Edebiyatı','Şiir','Life is Life']::text[], 8.5, '{"poet":"Life is Life","poet_slug":"life-is-life","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeminim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇEN YILLARA', 'gecen-yillara-life-is-life-bnejc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok sevmiştim yarmısın sen.....

Çözemediğim   sırmısın  sen....

Yazın  yağan   karmısın  sen....

Nede   çabuk   geçtin  ömrüm

Akıp  giden  yollar  gibi.....

Kök  salmamış  dallar gibi.... 

Hazan vurmuş güller gibi....

Nede   çabuk   geçtin  ömrüm

Hayalim gerçek olmadan....

Daha  muradım  almadan...

Bu dünyadan  usanmadan...

Nede   çabuk   geçtin  ömrüm', 'Çok sevmiştim yarmısın sen..... Çözemediğim   sırmısın  sen.... Yazın  yağan   karmısın  sen.... Nede   çabuk   geçtin  ömrüm Akıp  giden  y...', ARRAY['Türk Edebiyatı','Şiir','Life is Life']::text[], 8.5, '{"poet":"Life is Life","poet_slug":"life-is-life","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecen-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Sonu', 'basi-sonu-ozgur-ozturk-dlmca', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sisin ardında bildiğim orman

Ormanın hiç bilmediği ben

Bendeki sensizlik

Senin dokunamadığın kalp

Kalbin dinmeyen sızısı

Sızının verdiği haz

Hazzın yaktığı özlem

Özlediğim sen

Belki hiç olmayacak BİZ', 'Sisin ardında bildiğim orman Ormanın hiç bilmediği ben Bendeki sensizlik Senin dokunamadığın kalp Kalbin dinmeyen sızısı Sızının verdiği haz...', ARRAY['Türk Edebiyatı','Şiir','Özgür Öztürk']::text[], 8.5, '{"poet":"Özgür Öztürk","poet_slug":"ozgur-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/basi-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardaki Taşlar', 'duvardaki-taslar-ozgur-ozturk-fs2mm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen mi zalimsin beni görmezken

Yoksa ben mi, kendimi saklarken

Ama bunun adı zulum.

Acaba yine de yaşatırmıydın,

Eğer anlatsaydım, bile bile

Boşa giden zamanlar mı?

Bu suskunlukta akan

Yoksa yerine oturan taşlar mı?

Bu aşkın temeline atılan', 'Sen mi zalimsin beni görmezken Yoksa ben mi, kendimi saklarken Ama bunun adı zulum. Acaba yine de yaşatırmıydın, Eğer anlatsaydım, bile bile...', ARRAY['Türk Edebiyatı','Şiir','Özgür Öztürk']::text[], 8.5, '{"poet":"Özgür Öztürk","poet_slug":"ozgur-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duvardaki-taslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairden Bir Not', 'sairden-bir-not-mahir-ulas-akcan-f2bq1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'merhaba okuyucu

bir dostum şiirlerimden bir kaçını eklemiş ve ben de bu mesaj ile

herkese selam iletmek istedim

yakında yeni ve yayınlanmayan şiirleri ekleyeceğim

dostlukla...

ilk kitabım: Phantasmagoria-Düşsel Görüntü Oyunu

Yayınevi: Siyasal Kitabevi', 'merhaba okuyucu bir dostum şiirlerimden bir kaçını eklemiş ve ben de bu mesaj ile herkese selam iletmek istedim yakında yeni ve yayınlanmaya...', ARRAY['Türk Edebiyatı','Şiir','Mahir Ulaş Akcan']::text[], 8.5, '{"poet":"Mahir Ulaş Akcan","poet_slug":"mahir-ulas-akcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sairden-bir-not-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Geldiği Gibi', 'i-cimden-geldigi-gibi-kayahan-acar-cyacu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen;

Ben istemeden,

Hiçbir şey yapmıyorsun.

Bir mektup yazıp,

Atmıyorsun.

Ya da...

Gece yarısı,

Çalsa telefonlarım;

Seni daha çok severim,

Biliyor musun?

Sen ben istemeden,

Hiçbir şey yapmıyorsun.

Benim yazdığım gibi yazmalı;

Benim aradığım gibi aramalısın beni.

Bir yanın hep eksik olmalı.

O yanını benimle tamamlamalısın.

Benim sevmekten anladiğim bu.

Sen ben istemeden hiçbir şey yapmıyorsun.

Dün gece kaç kez çaldı telefonların;

Ya yoktun , ya uyuyordun.

Farketmez, anlıyor musun.

Sen ,

Ben istemeden,

Hiçbir şey,

Yapmıyorsun.', 'Sen; Ben istemeden, Hiçbir şey yapmıyorsun. Bir mektup yazıp, Atmıyorsun. Ya da... Gece yarısı, Çalsa telefonlarım; Seni daha çok severim, B...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icimden-geldigi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Olmalı Bu Gece', 'uzun-olmali-bu-gece-metin-vatansever-4ghs1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzun olmalı bu gece,

Sabahın ufkuna ger gözlerini,

Ger ki; Mutluluk gerdeğe girsin gözbebeklerimde,

Ger ki; Parçalasın esaret zincirlerini yüreğim,

Ger ki; Deli duygularım isyan etsin yalnızlığıma.

Uzun olmalı bu gece,

Sabahın ufkuna ger gözlerini,

Ger ki; Yeni bir çığır açılsın gözkapaklarından,

Kurşuna dizilsin köhne umutlarım,

Özgürlüğünü yudumlasın ümitlerim.

Uzun olmalı bu gece,

Sabahın ufkuna ger gözlerini,

Ger ki; Yüreğimde birazcık sevgi kalmışsa eğer,

O bir tadımlık sevgimi tadasın,

O''da yoksa; 

Boşuna, yum gözlerini artık

Olsun artık gündüz,

Nasıl olsa bu derde

Batacağımız kadar battık...', 'Uzun olmalı bu gece, Sabahın ufkuna ger gözlerini, Ger ki; Mutluluk gerdeğe girsin gözbebeklerimde, Ger ki; Parçalasın esaret zincirlerini y...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uzun-olmali-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmamış Hüzün', 'unutulmamis-huzun-sair-verde-c8yyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halbuki yüreğim kanıyordu geceleri

Sensizdim o zamanlar, havada iğde kokusu vardı,

Bu kokuyla SEN gelirdin aklıma ,yanık tenin gelirdi.

Kirpiklerime asılı kalan damlalarda gözlerin vardı,

Gözlerime çektiğim sürmede ise siyah saçların

Verdiğin umutlardaki avuçladığım siyahları

Göğsüme bastırırdım mavi rüzgarlarda,

Yudumladığım hasretinle büyüdü siyahlarım,umutlarım ve ardındaki BEN!

Haykırdığım rüyalarım vardı ya,hani ağlayarak uyandığım,

Hani doyasıya SENİ kokladığım,

Gittiğini görürdüm,BENİ terkettiğini.

Tıpkı bir solukta buğuladığım  camlardan yazdığım isminin silindiği gibi.

Çekip gidiyordun hayatımdan,ellerin ellerimden kayıyordu usulca,

Ve bana yine iğde kokulu hayallerim kalıyordu SENİ aradığımda.

Benliğime mayaladığım o ağır sevdalı yüreğindi tenime can veren,

Çatlamış dudaklarıma sızan yağmur damlasında yine SEN vardın

Rüzgarın bile titrediği mum alevinde SENİN sevdandı  bedenimi bürüyen,

Şevkat gamzelerinle süslenmişti yorgun siyahlarım

SEN  bir  OZANDIN , BEN ise SAZIN ,

Seyrederdim SENİ uzaktan,hani bir dokunsan gönül tellerime derdim,

ÇÜNKÜ İLK DEFA SENDE GÖRDÜM AŞKIN AKSİNİ,RUHUMUN DİK BAŞLI DAĞ YAMAÇLARINDA!

Bir nakkaş inceliği ile göğsüme yazılmıştı ismin,

Bir hayal gibi, gözlerimin denizinde kürek çekiyordu sevdan,

Ah o sevdan , o iğde kokulu ağır sevdan.

Ruhumun karanlık kıyılarına dokunuyordu esmer dudakların,

Parmakların hülyalarımı tarardı geceleri,

Seni düşündüğümde ufkum sonsuzla kucaklaşırdı,

Kutsallaşırdın rüyalarımda, ötelerden gelen ufak bir selam gibi..

Ve anladım ki;YAKUP''UN yüreğindeki SENDİN!

BEN ise ZÜLEYHA''nın ta kendisi...!

                                                 

                                                                 (12 TEMMUZ 2000)', 'Halbuki yüreğim kanıyordu geceleri Sensizdim o zamanlar, havada iğde kokusu vardı, Bu kokuyla SEN gelirdin aklıma ,yanık tenin gelirdi. Kirp...', ARRAY['Türk Edebiyatı','Şiir','Şair Verde']::text[], 8.5, '{"poet":"Şair Verde","poet_slug":"sair-verde","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/unutulmamis-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter', 'biter-tuncer-oral-y9xx1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biter ''bir tanem'' her şey biter,

Ne dalga kalır denizde

Ne deniz olacak su

Nede suyun dibinde kum...

Karabulutlar gelir geçer birer birer 

Bitmez sandığın rüyalar biter.

Umutlar tükenir

Hayal kırıklıkları biter

Bitmez dediğin acılar biter,

En derin yaralar iyileşir.

Ormanda kuş sesi,

Havada duman kokusu,

Tarlada buğday başağı biter.

Sen ne dersen de

Nerede olursan ol

Ne kadar mutlu olsan da

Oda biter.

Ne o körü körüne saygı kalır,

Ne pişmanlıkların arkası gelir.

Bitmez denilen yol biter.

Her şeyden ziyade ömür biter.

Bir tek;

Bendeki bu yürek,

Bu yürekteki bu sevda

BİTMEZ...

...........

BEN BİTSEMDE...

31*10*2000

12:00', 'Biter ''bir tanem'' her şey biter, Ne dalga kalır denizde Ne deniz olacak su Nede suyun dibinde kum... Karabulutlar gelir geçer birer birer  B...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/biter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeli', 'bitmeli-tuncer-oral-v6y5x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her şey;

Bir an önce bitmeli 

Gün erken kararmalı 

Güneş erken doğmalı 

Saatler kısalmalı 

Biraz da hızlanmalı 

Bahar hemen gelmeli 

Yaz uzun sürmemeli 

Zaman denilen kavram 

Sözlükten silinmeli 

Beklediğimiz ölüm 

Bir an önce gelmeli 

Acılar tükenmeli... 

6*10*2000 

13:35', 'Her şey; Bir an önce bitmeli  Gün erken kararmalı  Güneş erken doğmalı  Saatler kısalmalı  Biraz da hızlanmalı  Bahar hemen gelmeli  Yaz uzu...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bitmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver', 'bosver-tuncer-oral-d37so', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana şiir yaz diyorsun. 

Boş ver. 

En güzel şiirler ayrılıklar üzerine olur, 

Seninle bir ömür istiyorum. 

En güzel şiirler mutsuzluğa yazılır, 

Mutluluğu seninle kucaklamak istiyorum. 

Boş ver 

Ben şiir yazmayayım. 

En güzel şiirler acılara yazılır. 

Çektirdiğin yeter 

Artık durulmak istiyorum. 

9*11*2000 

19:00', 'Bana şiir yaz diyorsun.  Boş ver.  En güzel şiirler ayrılıklar üzerine olur,  Seninle bir ömür istiyorum.  En güzel şiirler mutsuzluğa yazıl...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bosver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Velhasıl', 'velhasil-faruk-yuksel-pj8m4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne bir şevk,ne de muzdaripliğin bedeli;

Mutsuzluk işlemiş ki,içime öyle derin, sitemli,

Hep bir şeylere ulaşmanın hevesi,sonucun gaf-ı;

Bu aldanışlar bir yana,içimi ezen,hicabının derin haykırışı...

Ey siz gülşende sabahı bulanlar!

Medeti acizden umanlar;kudreti onda görenler!

Öyle bir günün sonunda,bu derin kızıllıkta,bu haykıran bakışta;

Gördüm ben de ta derinlerden akan merhameti...

Rüyaların en güzelinde,aldanışlığın en büyüğü,

Ne umduk da ne bulduk misali,acizliğin en büyüğü;

Beklemezken ben de her zaman ki gibi; herkes gibi

Asıl kahreden, biçareymiş gibi durmaktır öyle ortada!

Galibiyim bu derin savaşın,belki de mağlubuyum

Hasretlik bir ömür düşmez içimden!

İnan ne bir aşk,ne bir sevdadır beni vuran;

Öyle bir gece karalarla iner gibi düştü içime...

İçimde ta derinlerde,ırmaklar gibi akan bir ses;

Der ki;ne aldanmak o masum görünüşe;

Ne de bırakmak kıymetlimi kem gözlere...

Varmaktır benimkisi;göstermektir o derin merhameti!

Sen de ne bir aşkın ,ne de bir sevdanın ürünü,

Kefenini çoktan biçtin bilinmez birinin gözünde 

Lakin bunlar da olur bir gün aldanış masalı;

Vel-hasıl ...Aldırma her teselliye sen de, var git!..', 'Ne bir şevk,ne de muzdaripliğin bedeli; Mutsuzluk işlemiş ki,içime öyle derin, sitemli, Hep bir şeylere ulaşmanın hevesi,sonucun gaf-ı; Bu a...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/velhasil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Daha', 'bugun-daha-faruk-yuksel-jyv2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani derim ki ;bugün daha...

Yine o gurub vaktinin kızıllığında;

Belki yeniden başlamak istenenle ;

Etrafın sessizliğini bozan bu kızıllıkla,

Hani son kez de olsa ...

Olur ya hani...

Serinliğiyle çırpılan kanatların,

Sıkılan yürekleriyle;

Hep bir şeylere koşmanın hevesiyle ,

İnsanların...

Elleri açık yürekleriyle,

O ağlamaklı sitemkar gariplerin,

Unutmuş olsam da ben;

Yine bir ben olan içimdeki beni;

Yarın,yine belki de: Son kez...

Diye demeler olacaksa da;

Bir gece,bir mehtabı görebilme hatırına;

Bugün daha...desem!..', 'Hani derim ki ;bugün daha... Yine o gurub vaktinin kızıllığında; Belki yeniden başlamak istenenle ; Etrafın sessizliğini bozan bu kızıllıkla...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bugun-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendedir', 'bendedir-faruk-yuksel-6bpp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkma!Nedenler de tek bendendir...

İnan bak sitem değil,

Bendedir gecenin dumanıyla çöken kasvet

Bendedir bu harabe kentin kem gözleri

Şafağın en koyusunda ezana koşan bir yana;

Hep bir tövbesi eksik günahkarlık bendedir...

Bendedir sitemkar gözlerin kaybeden hüznü;

Şevk dolu akşamlarda hep bir yanı eksik bakışlarda bendedir

Bendedir bu talih ki;hep yarım:

Her aydın günden gelen karanlıkla

Boğar ruhumu o gün gibi aydın gecede...

Lakin dedim ya bendendir!..', 'Korkma!Nedenler de tek bendendir... İnan bak sitem değil, Bendedir gecenin dumanıyla çöken kasvet Bendedir bu harabe kentin kem gözleri Şafa...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bendedir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata', 'hata-tuncer-oral-todck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgide hata olmaz,

Hata sevmeyi bilememekte.

Aşkta hata olmaz,

Hata doğru aşkı bulamamakta.

Kalpte hata olmaz,

Hata kalbe varamamakta.

Düşte hata olmaz,

Hata hayra yoramamakta.

Bu aşkın tek hatası,

Hata aramakta.

 17/10/2000', 'Sevgide hata olmaz, Hata sevmeyi bilememekte. Aşkta hata olmaz, Hata doğru aşkı bulamamakta. Kalpte hata olmaz, Hata kalbe varamamakta. Düşt...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mehtap', 'son-mehtap-faruk-yuksel-5aahb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vakitlerin en doyumsuzu...

Ne damarımda şevk,ne içimde aşk...

Mutluluk ;duymak istemediğim.

Bekler miyim bilinmez ;

Yoksa beklemeyi mi düşüneceğim!

Lakin;feryadım nafilelerden!..

Bir muzdariplik ve son merhametim akan yaşlarda...

Ve sarar bedenimi,insan olmanın gururu...

Bir yanda yenilmemiş olmak;

Yahut öyle düşlemek,

Hani derim ki; hep aradığım teselli o son mehtapta!

Oysa vakit bu kızıllık ki;

Hep yaralar içimi ,

Ölüm o kadar yakın, dermanım o kadar aşikar!

Ben ki ne hükmeder,ne hükmedilir

Öyle duran ortada bir yürekle

Dedim ya :Belki de teselli o son mehtapta!

Dostlarım da öyle her gece ,riyasız,yalınayak ve çırılçıplak ...

Tüm benlikleriyle sessiz ve samimi;

Ve düşünebildiğin kadar günahsız...

Bin günah şahidi; dilsiz, ki o kadar tepkisiz;

Ve öyle derinden yaralayışları...

İşte dolarım bu kızıllıkta hicabıyla gecenin, 

Dem be dem akla gelir hicranlı gönüller;

Hep dilimde dolaşan türkülerle ;

Derim ki:Ey gönül !Bendeki teselli o son mehtapta!', 'Vakitlerin en doyumsuzu... Ne damarımda şevk,ne içimde aşk... Mutluluk ;duymak istemediğim. Bekler miyim bilinmez ; Yoksa beklemeyi mi düşün...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/son-mehtap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Mutluluk', 've-mutluluk-faruk-yuksel-u9u8v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk aldanışların en büyüğü...

Mutluluk sitemlerin en korkuncu...

Mutluluk öyle coşkun,derin ve öyle ateşperest,

Kavurur zahiri içimi;

Vuslatı bir sabah satar ,

Zalim,kıymet bilmez talihsize...

Mehtabı,hicranımla;efganımla doldurur işte!

Vurur öyle gaddar,öyle zalimane;

Örer çirkefin tatlı rüyasını...

Derinden derinden eritir garip hülyalarımı...

Dedim ya:Korkmaya ne hacet...Mutluluk içimden ve hep benim olan;

İçimin istediği aldanışlık olan;

Gösterse de sorgusuz o hoyrat yüzünü;

Hissettirdi tüm benliğiyle hayalinin üzerimdeki aksini...', 'Mutluluk aldanışların en büyüğü... Mutluluk sitemlerin en korkuncu... Mutluluk öyle coşkun,derin ve öyle ateşperest, Kavurur zahiri içimi; V...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ve-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demeyeceğim', 'demeyecegim-tuncer-oral-ef1u0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana kal demeyeceğim,

Uzaklara dalışından belliydi gidişin.

Zaten hiç kalmadın ki...

Sana konuş demeyeceğim,

Suskunluğundu beni ateşe itişin

Gerektiğinde konuşmadın ki...

Sana mutlu ol demeyeceğim,

Mutsuzluğum mutluluğun olsa da.

Mutluluğu hiç hak etmedin ki...

Bana ilaç ol demeyeceğim,

Sırtımdaki hançer senin eserin.

Hiç çarem olmadın ki...

Sana birini sev demeyeceğim,

Yalnızca sevilmeyi seversin.

Sen sevmeyi bilmezsin ki...

Sana suçlusun demeyeceğim,

Suç seni sevende.

Sen beni hiç sevmemişsin ki ...

 16/10/2000', 'Sana kal demeyeceğim, Uzaklara dalışından belliydi gidişin. Zaten hiç kalmadın ki... Sana konuş demeyeceğim, Suskunluğundu beni ateşe itişin...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/demeyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalandır', 'yalandir-faruk-yuksel-s5rwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yangınlar kopup düşmüş yüreğinden,

Gözlerin dumanıyla bürünmüş yılların;

Bilirim lakin mevsim hazandır sende,bu yaz gününde!

Dert neyse ne de ;

Her teselliye de aldanma derim ama;

Uyanırken içinde biri;

Sende hiç olmamış gibi şaşırma öylece...

Bil ki laf-ı güzaftır hepsi;aldanma lakin.

Senin de bildiğin,gönüldür,aşktır,yürektir;

Bulutlarla giden yağmurlar gibidir!

Öyle sitemkar bakma!

Değil mi sanki ömrüm de öyle 

Kim demiş ki her şey öyle yerli-yerinde...

Kim demiş ki bitmez bu!

Bir zelzele,bir tufan her gün ayrı koyar beni...

Gece ve yıldızlar,değil mi sarıldığım dostlarım...

Bir şafak vaktinde onlar da biter...

Ya o utanmadan,kör gece mi aydınlatan ay!

Yalandır işte!..

Ağrına gider bir sitem bir ürperiş;

Anlamsız öfkeler içinde kopar da bir isyan,

Ve bakarsın bir vakit ;boynuna asılmış o nafileler!

Ne eyler,ne der bilmem ki artık gönül...

Ve bir gün varıp sonuna ufukların

Ulaşırken tan yerindeki o uyuyan hayale;

Hep son adımı atacakken;

Kayıverir birden!..

İşte benim de içimi dağlayan karalardan inen bu havadistir!..

Lakin sen de aldırma,dinle bu son teselliyi:

Geceler,yıldızlar ve ay

Yalandır işte!..', 'Yangınlar kopup düşmüş yüreğinden, Gözlerin dumanıyla bürünmüş yılların; Bilirim lakin mevsim hazandır sende,bu yaz gününde! Dert neyse ne d...', ARRAY['Türk Edebiyatı','Şiir','Faruk Yüksel']::text[], 8.5, '{"poet":"Faruk Yüksel","poet_slug":"faruk-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalkantılar Ortasındayım', 'calkantilar-ortasindayim-tuncer-oral-7iers', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çalkantılar ortasındayım

Ne güneş görünüyor ufukta 

Ne de kara.

Üşüyorum her yanım ıslak

Göz yaşlarım belli olmuyor

Yüreğimde derin bir yara.

Bıçağın keskin yüzündeyim

Tabanlarım kan avuçlarım ateş

Sen attın beni bu nara.

Gözümden kaçırırdın telini

Gönlüme düğümlendi saçların

Bir sağa bir sola tara.

Anladım geçte olsa

Aşk yok. Sen sevdiğin müddetçe

Seni seveni ara

Ayrılık şarkıları çalınır şimdi

Aşk, hüzün, ölüm.

Seni zamanda bulmuştum,

Yine zamanda gizli çare.

                                   16*10*2000

                                         19:45', 'Çalkantılar ortasındayım Ne güneş görünüyor ufukta  Ne de kara. Üşüyorum her yanım ıslak Göz yaşlarım belli olmuyor Yüreğimde derin bir yara...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/calkantilar-ortasindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-tuncer-oral-xnzxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan 

Gidişlerin yolcusu mu olayım ?

Yoksa; 

Balıklara yem mi 

Derin denizlerde ?

Yoksa 

Seni sevip 

Güzel gözlerinde mi kaybolayım ?

Ne de olsa 

Hepsi çıkmaz sokak ...

17/2/2000', 'Dönüşü olmayan  Gidişlerin yolcusu mu olayım ? Yoksa;  Balıklara yem mi  Derin denizlerde ? Yoksa  Seni sevip  Güzel gözlerinde mi kaybolayı...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cikmaz-sokak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yağmur Yağışında', 'her-yagmur-yagisinda-tuncer-oral-sgivl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yağmur yağışında; 

Adapazarı aklıma gelir. 

O yıkık kent, 

O garip 

O viran kent, 

Yaşamak için direnen kent. 

Her yağmur yağışında; 

Adapazarı aklıma gelir. 

Yıkık binalar gelir 

Çadırlar, barakalar gelir. 

Sefalet gelir aklıma. 

Parçalanan yürekler gelir. 

Her yağmur yağışında; 

Aklıma sen gelirsin. 

Mutlu olduğumuz günler gelir. 

Ellerimiz kenetli 

Beraber ıslandığımız 

O çamur sokaklar gelir. 

Her yağmur yağışında; 

Haydarpaşa-Adapazarı trenleri gelir. 

Bu sevdanın en canlı şahitleri. 

Sana gelirken bitmez tükenmez sandığım 

Seninleyken nasıl bittiğini anlayamadığım yollar gelir. 

Her yağmur yağışında; 

Adapazarı Gar''ı gelir aklıma. 

Siluetin gelir gözümün önüne. 

Gardaki kafe gelir. 

Avuçlarının sıcaklığını hissedişim gelir 

Yanaklarımda. 

Sonra birden ellerini çekişin. 

Masumane boynunu büküşün, 

Beni büyüleyişin gelir bakışınla. 

Her yağmur yağışında; 

Sevdam dile gelir. 

Bir sızı depreşir önce. 

Sonra biraz öfke, 

Biraz hüzün. 

Aslında seni çok, 

Ama çok özleyişim gelir. 

Birde; 

Sonbaharın önüne kattığı 

Kırık bir kalp gelir, 

.................................

YAĞMUR YAĞMASA BİLE.... 

10*11*2000   18:50', 'Her yağmur yağışında;  Adapazarı aklıma gelir.  O yıkık kent,  O garip  O viran kent,  Yaşamak için direnen kent.  Her yağmur yağışında;  Ad...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/her-yagmur-yagisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerim', 'gecelerim-hazan-tekir-dex87', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıradan bir gecenin alacasında

Sıradanlığıyla yaşıyorum hayatı,

Bu sıradan gecelerin altında

Sıradan ağlamalarla boğuyorum vuslatı .

Giydiğim elbiseler ısıtmıyor artık beni

Bir sevgi istiyorum senden

Yaksın ekvator sıcaklığında beni.

Gecenin elleri yüzümü okşuyor

Bu yüzden isyan edemem karanlığa.

Hasretin geceler boyu ağlatıyor

Bu yüzden sevinemem güneşteki yangına.

Bir kibrit bile yakamıyorm yarınlara,

Kar beyazı umutlarım üşüyor.

Bir gül konsun diye beklerken avuçlarıma,

Dikenleri ileyüreğim kanıyor.', 'Sıradan bir gecenin alacasında Sıradanlığıyla yaşıyorum hayatı, Bu sıradan gecelerin altında Sıradan ağlamalarla boğuyorum vuslatı . Giydiği...', ARRAY['Türk Edebiyatı','Şiir','Hazan Tekir']::text[], 8.5, '{"poet":"Hazan Tekir","poet_slug":"hazan-tekir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hani-olur-ya', 'hani-olur-ya-tuncer-oral-s4h2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapat perdeleri kapat 

Hani olur ya kıskanır belki 

Güneş usulca girerken içeri 

Elin elimde iken 

Gözlerim gözlerinde iken 

Kıskanır belki 

Isıtmaz eskisi gibi... 

Aç pencereleri aç 

Yağmur girsin çisil çisil içeri 

Hani olur ya o toprak kokusu 

Sevgimize sevgi katar belki 

Damlalar ninni olur 

Dizlerinde uyurum belki 

23 Mayıs 2000', 'Kapat perdeleri kapat  Hani olur ya kıskanır belki  Güneş usulca girerken içeri  Elin elimde iken  Gözlerim gözlerinde iken  Kıskanır belki ...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hani-olur-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan', 'perisan-tuncer-oral-eh4sj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Perişan haldeyim 

Umutlarım gasp edilmiş 

Karanlıktayım. 

Kurduğum tüm kaleler 

Kumdanmış meğer, 

Savunmasız, ortalıktayım. 

Zelzeleye tutulmuş ruhum 

Tüm güzellikler yıkık 

Enkaz altındayım. 

Sinirlerim körelmiş 

Tırnağım çekilmiş etten 

Hissetmemişim. 

Kalbimi sökmüşsün giderken 

Elim kolum bağlı kalmış 

Arkandan bakakalmışım. 

Geri dönmeliyim bu yoldan 

Yönümü karıştırdım 

Kaybolmuşum. 

Gözlerim kan çanağına dönmüş 

Ağlamaktan değil 

Uykuyu unutmuşum. 

Ateşin kavuruculuğundan sakınmamışım 

İçine itilmiş, atılmışım 

Ne gören ne duyan olmuş 

Ne kadar sürer bilmiyorum ama 

Hala yaşamaktayım ... 

10*11*2000 

18:45', 'Perişan haldeyim  Umutlarım gasp edilmiş  Karanlıktayım.  Kurduğum tüm kaleler  Kumdanmış meğer,  Savunmasız, ortalıktayım.  Zelzeleye tutul...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/perisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasırga', 'kasirga-tuncer-oral-krv6t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve

Kasırga koptu;

Güneşe inanıp.

Okyanusa açıldıktan sonra...

15*11*2000

19:02', 'Ve Kasırga koptu; Güneşe inanıp. Okyanusa açıldıktan sonra... 15*11*2000 19:02...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kasirga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odak', 'odak-tuncer-oral-rain0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Odaktayım;

Bütün oklar üzerime çevrili

Her geçen an çember daralmakta.

Ben ölüme koşarken

Ölüm;

Bana doğru şevkle yaklaşmakta...

 16/10/2000', 'Odaktayım; Bütün oklar üzerime çevrili Her geçen an çember daralmakta. Ben ölüme koşarken Ölüm; Bana doğru şevkle yaklaşmakta...  16/10/2000...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/odak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Güzeldir', 'cicek-guzeldir-sair-melegim-htm7p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül kadar degil.

Hayal güzeldir,

Gercek kadar degil.

Sen güzelsin,

kalbin kadar degil.

Seni herkes sevebilir,

Benim kadar degil.', 'Gül kadar degil. Hayal güzeldir, Gercek kadar degil. Sen güzelsin, kalbin kadar degil. Seni herkes sevebilir, Benim kadar degil....', ARRAY['Türk Edebiyatı','Şiir','Şair Meleğim']::text[], 8.5, '{"poet":"Şair Meleğim","poet_slug":"sair-melegim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cicek-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör', 'gor-tuncer-oral-so7dw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gördün mü? 

Alevin çırayı sarışını 

Ya da kıvılcımın 

Benzini kucaklayışını 

Yanmak mı o? 

Gel şimdi; 

Yüreğimdeki yangını GÖR!..', 'Gördün mü?  Alevin çırayı sarışını  Ya da kıvılcımın  Benzini kucaklayışını  Yanmak mı o?  Gel şimdi;  Yüreğimdeki yangını GÖR!.....', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşgale', 'mesgale-nazim-hikmet-ran-9z36v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öküzlerimin boynuzlarında aydınlanırken ortalık

toprağı sürüyorum sabırlı bir kibirle

çıplak ayaklarımda toprak nemli ve ılık.

Demir dövüyorum öğleye kadar 

kırmızıya boyanıyor karanlık.

Ya
..........
..........', 'Öküzlerimin boynuzlarında aydınlanırken ortalık toprağı sürüyorum sabırlı bir kibirle çıplak ayaklarımda toprak nemli ve ılık. Demir dövüyor...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mesgale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Böylemiydi', 'hep-boylemiydi-sair-ulas-zic9h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan mı severdi yoksa gönül mü,

Beyin durur muydu kalp çalışınca?

Yada niye uyuşmazlardı ömürlerince,

Olmadan olmaz var mıydı.

Hep bir kırmızı gül mü anlatırdı sevgiyi sevgiliye

Ve hep sevgili niye kaçardı

Yada hep  niye kovalardı bizim deli aşık

Aşkı fotoromanlarda yaşamak niye farklıydı

Niye gönül sevgiyi içine sığdıramazdı

Hep taşar dururdu

Delilik yapmak sevgiliye niye yakışırdı

Yada delilik yapmadan aşk olmaz mıydı

Delilik diyince hep aklıma duvardan atlamak gelir

Uçaktan atlamak da delilik olmaz mıydı

Aşk kitabı bunu kabul etmez miydi yoksa

Yari görünce niye eller tutmaz olurdu

Yoksa sevginin bir parçası mıydı bu

Severken geceyi gündüze katmak güzel olurdu

Yoksa gündüzün yarla arasımı bozuktu

Yıldızlar mıydı tek arkadaşı

Kıskançlık bu kadar ilerlemiş miydi

Cebindeki fotoğrafı görünce niye koşar adımla kaçar giderdi

Halasının kızı yada teyzesinin gelini olduğunu niye anlayamazdı

Gülmekte haram olmuştu, hiç gülmemekte

Saklamıyor muydu gamzelerini

O canım gözlerinin güzelliğini...

Hepsi hoştu ya, hepsi güzel ve anlatılmazdı ya 

İşte gülüm tüm bu  güzelliklerde

Gönlümden taşan sevgimle

Tut mayan elim görmeyen, gülmeyen, gülemeyen gözlerimle

O tutarsız kıskançlığımla, tutarsız deliliğimle

Gecemle ve gündüzümle sevdim seni,

Seninde beni sevdiğin gibi....', 'İnsan mı severdi yoksa gönül mü, Beyin durur muydu kalp çalışınca? Yada niye uyuşmazlardı ömürlerince, Olmadan olmaz var mıydı. Hep bir kırm...', ARRAY['Türk Edebiyatı','Şiir','Şair Ulaş']::text[], 8.5, '{"poet":"Şair Ulaş","poet_slug":"sair-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hep-boylemiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ellerimi', 'tut-ellerimi-enver-ari-bmb4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kanatlarım olsa da

Uçamam sensiz

Dal,budak salsam da

Tomurcuklansam da

Açamam sensiz

Nefes alıp verişim aldatmasın

Gülüp,oynasam da

Yaşayamam sensiz

Sensiz yaşayamam

Yokluğunda;

Bedenim yükl olmaya başladı.

Ne olur!...

Tut ellerimden

Yüküm hafiflesin

Tut ki, bir tanem

Sıkıntılarım dağılıp gitsin

Üzüntülerim bitsin

Ne olur!...

Tut ellerimden

Tut ellerimden

Ne ayazlar etkilesin seni

Ne yazlar

Ayazlar da yüreğine akan sıcaklık

Yazlar da

Gönlünü dolduran serinliğim ben

Tut ellerimi bir tanem

Ne olur,sakın bırakma

Gönlümün bütün güzellikleri

Sana yöneldi

Yüreğine akmak istiyor

sana güç vermek,

Sana yaşama sevinci

Katmak istiyor

Tut ellerimi,

Tut ki, sevdalım

Bu gözler hep seni görmek

Yalnız sana bakmak istiyor

Tut ellerimi

Ne olur!...

Bırakma ki, sevdiğim

Ellerin, hep ellerimde,

Gözlerim, hap gözlerimde olsun

Ellerimi tut,

Ey!...yüreğinde yüreğimi bulan

Bırakma ellerimi

Bırakma ki,

Sevgini taa..canımda hissedeyim

Atomlarına kadar,her hücremde

Seni bulayım

Tut ellerimi ki,canım

Seninle bir ömür

Huzuru,

Bir ömür mutluluğu bulayım

Ne olur bırakma ellerimi

                    18.12.2000', 'Kanatlarım olsa da Uçamam sensiz Dal,budak salsam da Tomurcuklansam da Açamam sensiz Nefes alıp verişim aldatmasın Gülüp,oynasam da Yaşayama...', ARRAY['Türk Edebiyatı','Şiir','Enver Arı']::text[], 8.5, '{"poet":"Enver Arı","poet_slug":"enver-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/tut-ellerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Saçlısı''na', 'kizil-saclisi-na-nazim-hikmet-ran-7za7g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pembe yanaklı al dudaklı bir karım olursa eğer..

Olursa 24 ayar ahlaklı..

Anama bakar gibi bakar..

İlaha tapar gibi taparım..! 

Ama...! 

Kalleş çıkarsa karım..

Anam avradı
..........
..........', 'Pembe yanaklı al dudaklı bir karım olursa eğer.. Olursa 24 ayar ahlaklı.. Anama bakar gibi bakar.. İlaha tapar gibi taparım..!  Ama...!  Kal...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kizil-saclisi-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Ortası', 'kis-ortasi-enver-ari-g56ky', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kış ortasında

Baharı yakaladım derken

Gönlüm yıkılıp, harap olan 

Viraneler döndü

Baykuşlar bile dönüp bakmaz oldu

Her şey öyle perişan ki;

Kuşlar uçmaz oldu

Çiçekler açmaz oldu

Güller o güzelim kokularını saçmaz oldu

Yanan bir yüreğim var

Her yer küllerle doldu

Ey!..kış ortasında

Özlemiyle yandığım

Hasretiyle sararıp solduğum

Ey!.. sevgisiyle mutlu olduğum

Bütün bu kül duman içinde

Viraneye dönmüş olan

Baykuşların bile dönüp bakmadığı yüreğimde

Yine seni görüyorum

Yine sen varsın

Seni bulunca da CANGÜLÜM

Her şeyi yenide buluyorum

Ve gücüme kuvvetime 

Yeniden kavuşuyorum

İşte sen bana böyle bir yarsın

Kış oratasında yansam da inan

Sen bana her zaman

Baharsın

                             10.12.2000', 'Kış ortasında Baharı yakaladım derken Gönlüm yıkılıp, harap olan  Viraneler döndü Baykuşlar bile dönüp bakmaz oldu Her şey öyle perişan ki; ...', ARRAY['Türk Edebiyatı','Şiir','Enver Arı']::text[], 8.5, '{"poet":"Enver Arı","poet_slug":"enver-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kis-ortasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurumsun', 'yagmurumsun-enver-ari-8wb7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman gözlerim bulutlansa

Yüreğimden kopup gelenin

Sen olduğunu bilirim

Bilirim

Göz pınarlarımda

Yoğunlaşanın sen olduuğnu

Ne zaman

Damlalarım akmaya başlasa

Yağmurumun sen olduğunu 

Bilirim

Billurlaşan akışında

Sıcaklığını hissederim

Sularının berraklığnda

Yüzüm gibi

Bütün benliğimi de yıkarım

Bilirim

Hasretinden çoraklaşan yüreğime

Yağan yağmurum sensin

Sen yağmurumsun

                             30.11.2000', 'Ne zaman gözlerim bulutlansa Yüreğimden kopup gelenin Sen olduğunu bilirim Bilirim Göz pınarlarımda Yoğunlaşanın sen olduuğnu Ne zaman Damla...', ARRAY['Türk Edebiyatı','Şiir','Enver Arı']::text[], 8.5, '{"poet":"Enver Arı","poet_slug":"enver-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmurumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cangülümsün', 'cangulumsun-enver-ari-063kk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim ilk gülüm,son gülümsün

Sen benim sevdiğim tek gülümsün

Canımdan çok severim seni

Sen benim sevdiğim cangülümsün

Sen sevgiye uzanan elimsin

Ben yağdığımda akan selimsin

Ben mecnunum, sen çölümsün

Sen benim sevdiğim cangülümsün

Sevgiyle dokuduğum kilimsin

Gönülden okuduğum ilimsin

Gören gözüm,söyleyen dilimsin

Sen benim sevdiğim can gülümsün

                                          Kasım 2000', 'Sen benim ilk gülüm,son gülümsün Sen benim sevdiğim tek gülümsün Canımdan çok severim seni Sen benim sevdiğim cangülümsün Sen sevgiye uzanan...', ARRAY['Türk Edebiyatı','Şiir','Enver Arı']::text[], 8.5, '{"poet":"Enver Arı","poet_slug":"enver-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cangulumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gemin Camdan Sevgili', 'senin-gemin-camdan-sevgili-cezmi-ersoz-0n02v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duydum ki yine umudunu kesmişsin insanlardan,

dostluklardan... Duydum ki yine acımaya başlamışsın

kendine...

Yolunu kimselerin bilmediği, bilmek de istemediği

sevginin o hayal ülkesinde birilerini beklerken çok

üşümüşsün...

İnsan ancak kendisine sevgili olabilir, diyormuşsun.

Şimdi artık yollarda ve binbir hayalin peşinde

sürüklediğin ve yıprattığın sevgine minnet borcunu

ödeyecekmişsin...

Acıyan sevgini şımartacak, onu örtülere saracakmışsın.

Onu kendini güçlü ve korunaklı olduğunu hissetmediğin

hiçbir yerde ortaya çıkarmayacakmışsın...

Sevgini yırtıcı bir kuş gibi yetiştiriyormuşsun.

En iyi savunmanın saldırı olduğunu ve yokolmamak için

yoketmek gerektiğini öğretiyormuşsun ona...

Ona onu, sabırlar, merhametler ve inceliklerle değil,

hazlar, hayranlıklar ve kıskanç ilgilerle

besleneceğini vadediyormuşsun.

Her gece uyumadan önce arkasında Che Guevera’nın resmi

olan aynanla konuşuyormuşsun: Bir sen varsın önemli

olan, bir sen varsın gerçek olan... Hem onca acıya

rağmen hala güzelim...

Ve artık kendime yasaklıyorum başkalarına acımayı ve

hayatın acısını...

Aynadaki nefesinin buğusunu görüyorum buradan.

Gözlerinle gözgöze gelemediğim için tutup aynadaki

buğuyu öpüyorsun.

Yaralı kendini öpüyorsun...

Çekmeceden cüzdanının çıkarıp içindeki kredi

kartlarını seyrediyorsun zoraki bir hayranlıkla.

İçinde sevgini sakladığğın kaleyi daha da

güçlendirmeyi geçiriyorsun aklından.

Kredi kartlarını yalıyorsun dilinle ve onların zehirli

tadını içine akıtıyorsun.

Bankamatikten her para çektiğinde kulağına gelen ölüm

çığlıklarına alıştırmak istiyorsun kendini böylece.

Hem senden güçsüzlerin ölümü, hem bu ölümleri gizleyen

ve bütün katliamları anında temize çeken teknolojinin

zehirli tadı sarıyor şimdi sevginin yaralarını.

Bankamatikten her para çektiğinde kulağına gelen

çocukların ve kimsesizlerin ölüm çığlıklarına

dayanamadığını hissettiğin anlar, senin için hayatta

sadece annenin babanın ve kardeşlerinin önemli

olduğunu söylüyorsun kendine ve akşam iş dönüşü onlara

hediyeler alarak evine dönüyorsun...

Ve eskiden, sevgini bir kalenin ardına saklamadan önce

sadece kendi çocuklarını sevenleri kınadığını unutmak

içinse bu defa başkaları değil kendin kanatıyorsun

sevgini.

Sonra küçük, tüylü bir köpek almak istiyorsun kendine.

Köpegi severken, kucaklarken sana acımasızlık eden

dostlarının, seni sevginin o hayal ülkesinde yıllarca

bekletip düşlerini ve ömrünü çalan sevgililerin

yüzleri geçsin istiyorsun karşından.

Onların yüzleri geçtikçe sahibin olduğun için senden

başka kimseyi sevmeyecek ve bağlanmayacak olan

köpeğine daha da sıkıca sarılmak istiyorsun, öpüp

koklamak.

Kendini öper gibi, yaralı ve belki de artık hiç

iyileşmeyecek olan kendini.

Hiç iyileşmeyeceğini artık kendinden bile

saklayamadığın böyle anlarda para kazanmak istiyorsun,

iş kurup daha çok para kazanmak.

Böyle anlarda bir kalenin ardında gizlediğin herşeye

yanlışlarla dolu olsa da senden izler taşıyan tarihine

bile düşman oluyorsun.

Seni bu hale getirenlerle bir olup bu belki de artık

hiç iyileşmeyecek yaralı kendini yoketmek

istiyorsun... Sonra yorgun düşüyorsun... Artık

dinlenmek istiyorsun. Yarına daha dinlenmiş ve

korkularından kurtulmuş olarak uyanmak istiyorsun...

Ve uykuya dalmadan önce vitrinlere bıraktığın

dalğınlığın geliyor aklına...Kendine bir kez daha

acıyorsun ve bu yüzden pahalı bulup da almadığın

giysileri almaya karar veriyorsun.

Bu pahalı giysiler sayesinde ilgilerin kölesi değil,

ilgilerin merkezi olmayı istiyorsun.

Bu giysiler sayesinde sızlayan sevgilerini örtmek,

örtmek, örtmek istiyorsun. Görünmez olmak istiyorsun.

Oysa senin gemin camdan sevgili...

İşte güçlü balığın güçsüz balığı yokettiği kanlı

denizin her tarafından seni görebiliyorum...

Sadece ben değil dost düşman herkes uykuya daldığını

görebiliyoruz buradan.

Çünkü senin gemin camdan sevgili.

Sıkıntından yediğin tırnaklarının kenarlarını...

Korkulu bir rüya gördüğünde birden silkinişini...

Yaralı sevgini korumak için aldığın onca kötücül

karara rağman nasılsa hep masum kalan sayıklamalarını

görüp duyuyorum buradan...

Kaleni ve kalenin ardında sakladığın yaralı sevgini.

Boşuna saklama sevgini. Senin gibiler hiç örtünemez

sevgili...

Seni bu kanlı deniz ve düşmanların da dostların da

hemen tanır.

Ya benzerini bulup gidersin buralardan.

Ya da seni yokederler sevgili...

Herkes gibi ve herşeyi bilerek yaşamaszın sen

Senin gibiler örtünemez...

Bu kanlı denizde senin gemin camdan sevgili.', 'Duydum ki yine umudunu kesmişsin insanlardan, dostluklardan... Duydum ki yine acımaya başlamışsın kendine... Yolunu kimselerin bilmediği, bi...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/senin-gemin-camdan-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinden Öptüm', 'sesinden-optum-nilsu-sari-98fue', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sesinden öptüm seni

bana verdiğin esinle

en sevdiğim yanım senin yanın

öyle derinden baktın ki bana

kendimi yitirdim sende

en uzun yol; iki kaşının arası

yüzün sayısız dille konuşur anlama ki arasın

sana su kadar yakınım

güneş kadar uzak

açsam telefonu sesin gelir

kapasam ruhum gider', 'sesinden öptüm seni bana verdiğin esinle en sevdiğim yanım senin yanın öyle derinden baktın ki bana kendimi yitirdim sende en uzun yol; iki ...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sesinden-optum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metropol Aşkları', 'metropol-asklari-nilsu-sari-uvnh2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Geceyi burada geçirdiler

  Rıhtımın karşısında

Martıların sabah şarkısında uyanan

Su ile yaralanacakmış gibi duran

Dudakları hala -öldüklerinde bile- çatlak

Tenleri hala biraz kırmızı utancın tatlı ateşiyle

Sormuyorlar Kadıköy''de neden pencereleri merakla açılır aşkın

Soğukluğu ve durgunluğu nasıl aşılır gecenin

Tenleri ucuz viski ile sarhoş

Akılları yalnız bir adanın yalnızlığında

Özenle seçilmiş hüzünlerde tüketirler

Eksiltirler düşleri hep, hep düşleri eksiktir

Sonra birden öpüşmeye başlarlar,

İki dudak, dudaklar, içlerinde sevgisizliğin açık tehdidi

Bazen susmazlar, konuşurlar, kadıköyde rıhtımın karşısında

deli bir piyangocunun parmaklarının dolandığı

ve bizim kader dediğimiz o amortinin

kendilerine vurmasını isteyen küçük çocuklar

parayı kazandıklarında

ilk işleri bir martı evi açmak olan

mutsuz gece bekçileri sevdanın

onlar olmasa ne güneş doğacak

ne çiçek açacak

ne şehir katran karası irininden sıyrılacak

ne de beyaz olacak

onlar

metropol''un aşkını kınından sıyırır, dirençle taşırlar

sevişmeleri eksikse bize ne

önümüze koyarlar yırtılmış dillerini ve damaklarını

öpüşlerini sererler gizliden gizliye

oysa biz onları hiç sevmezdik

kadıköy’de bir evde

öldüklerinde

öldüklerinde

rıhtım''ın karşısında geçirdiler

geceyi

sonra soğuk

birden

çöktü

metropol bindi üzerlerine

aniden aşk

birden ayrılık

ve baki kalan sevgilerinin en derin yerinde

susuş

en sevdiğiydi bu kadının, beyaz tenine taparcasına

susuş

sözcükler, bu sözcükler işte

anlamıyorlar ki bir tanem

dağınık imgelerde ortada gün gibi duran

ah yalnızlık

gece kağıda bıraktığımız

her sabah biraz daha silinen umutlarımız

kendimizi kanatarak canlı tuttuğumuz

sevda.

                               ( Eylül 96   ist)', '''Geceyi burada geçirdiler   Rıhtımın karşısında Martıların sabah şarkısında uyanan Su ile yaralanacakmış gibi duran Dudakları hala -öldükler...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/metropol-asklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Nedir ki', 'yasamak-nedir-ki-nilsu-sari-7yq3u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hiç yalnızlığın hüznünü

                                       onca

İşin ve insanların arasında yaşadın mı ?

         ve yüreğinde aşkların en güzeli ile

                                                   sevgisizliği

Anlam dolu bakışlarda

                                     hiçliği

Denizin sonsuz ufkunda

                              geleceği arayıp

Yıldız pırıltılarında

                    geçmişim deneyimlerini

Korkularını kaybetmenin

                                benliğini,

                     sahip olduğunu sandığın

 güzelliklerini

                    dolayıp gönlüne

Ve boğulduğunu sevdanın iplerinde

Sevgilinin öpülesi boynuna

                        dolarken sevdanı

ölmüşlüğün ağırlığını hiç 

yaşadın mı?', 'Sen hiç yalnızlığın hüznünü                                        onca İşin ve insanların arasında yaşadın mı ?          ve yüreğinde aşkla...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasamak-nedir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat ve Sevgi', 'hayat-ve-sevgi-nilsu-sari-jh7eu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatı sevmemi öğütlerdin

                                     Sevdim

İnsanları seversen yaşarsın 

                                             demiştin

Kucak açtım hepsine birden

                                   sevgi özlemiyle

Ama yine olmuyor ki...

Garip gönlüm bir kez seni sevmiş,

                                        bir kez hayata küsmüş...

Sen desende, demesen de

O yine bildiğini okur,

                   hayatta insanlarda gözü yoktur...

Her şey her yer sıfırdır gözümde

Bir sen varsın inan sevgilim

Deli dediğin gönlümde...', 'Hayatı sevmemi öğütlerdin                                      Sevdim İnsanları seversen yaşarsın                                           ...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayat-ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Kelebek,Eflatun İpek', 'surgun-kelebek-eflatun-i-pek-nilsu-sari-8hnd3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen:iç yurdundan

          Sürgün kelebeğin

                  kalabalık uçuşu     

Sen:eflatun

           ipeğin 

             yırtılma sesi

Sen:kırlangıç

               kanadının

                 buzda

                   bıraktığı iz

 Sen:gidilmemiş yolun

                        yorgun

                          yolcusu

  Sen:bıçağı          

           Ürperten

                         Ten                                     (mart 00)', 'Sen:iç yurdundan           Sürgün kelebeğin                   kalabalık uçuşu      Sen:eflatun            ipeğin               yırtılma sesi...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/surgun-kelebek-eflatun-ipek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birbirimizin Güneşiyiz', 'birbirimizin-gunesiyiz-nilsu-sari-xmjyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Döndüysek yüzümüzü 

Akşam güneşinin battığı ufka

Görmek istediğimizi görmek için

                      Bakabildiysek ve

Gördüysek o saydam ufukta

Tanyelindekini

Ve insanlığa bırakılan

Beyaz kağıda yazılmamış mirası

O zaman kabulümüzdür

Bilmem kaçıncı yaşam dünyası

Çırpınarak yükseldiyse gönlümüz

Yüreğimiz

Ve yüceldiysek sevgiyle

Aşkla

Ve dolduysa gözlerimiz yaşla

Doğanda batanda biz,

Birbirimizin güneşiyiz.', 'Döndüysek yüzümüzü  Akşam güneşinin battığı ufka Görmek istediğimizi görmek için                       Bakabildiysek ve Gördüysek o saydam u...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birbirimizin-gunesiyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Düğünü', 'sevmenin-dugunu-nilsu-sari-75miy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dingin denizin kıyısında

Işıklı

Kıpırtılar kirpiklerimde

Nem

Ve aklımda sensizlikle

Ölüm ikilemi.

Ayın

Güneşe karşı koyuşu ile

Yüreğimin hasrete

Karşısındaki seni

Sevmenin düğünü yaşadığım

Konukları seninkiyle

Aynı', 'Dingin denizin kıyısında Işıklı Kıpırtılar kirpiklerimde Nem Ve aklımda sensizlikle Ölüm ikilemi. Ayın Güneşe karşı koyuşu ile Yüreğimin has...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmenin-dugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Batışına İnat', 'gunesin-batisina-i-nat-nilsu-sari-ottio', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümü aydınlatan

                güneşin batışına inat

Hep yeniden doğduğunu hatırlayacağım.

Gözlerindeki yakamozları

                göremeyeceğime inat

Her doğuşunda mehtabın

                 denize gireceğim

Sana inat

               sen benim olmasan da

Seni seveceğim', 'Gönlümü aydınlatan                 güneşin batışına inat Hep yeniden doğduğunu hatırlayacağım. Gözlerindeki yakamozları                 göre...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunesin-batisina-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçmeler Üzerine', 'i-cmeler-uzerine-nilsu-sari-2yx7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamaya çalışıyorum 

Sadece

Uğultusunda bekliyorum rüzgarın

O ise dönüp gidiyor

Sonra

Yüzümde ellerinin izi

Aniden bir tokat

Yoruluncaya kadar vuruyor

Gözlerini görüyorum

Çaresizlik, iç kırıklığı taşıyan

Hiç görmemiştim bu kadarını

Ben

Ağlıyorum canım

Ellerinin acısından değil

Kırıklığına', 'Anlamaya çalışıyorum  Sadece Uğultusunda bekliyorum rüzgarın O ise dönüp gidiyor Sonra Yüzümde ellerinin izi Aniden bir tokat Yoruluncaya ka...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/icmeler-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuklama', 'soguklama-nilsu-sari-m1kzg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen soğuklarda hiç titredin mi?

Soğuk, ayazdan

yalnızlıktan

	Sevememekten

	Sevilmemekten

Sen soğukta titremenin anlamını hiç yaşadın mı taa içinde?

Titredin mi? kuru ayazda

	        Yalnızlıktan korkarken

	        Sevilmemenin şamarıyla

	        Sevememenin bunaltısıyla

Ta içinde yaşamanın tadını/acısını bilir misin?

Ayazda içinde titreyen organlarının verdiği,

Yalnız ruhunun ısınmak için çırpınışlarının

Ve sevemeyip,sevilmemenin yüreğini sıkıştırmasının

Ve sonunda iç kırgınlığının

Yüzüne vurduğu soğukluğun

Hastalıklı ifadesini

Yüzünün,

Sudaki görüntüsünü.

Sendeki titreşimlerini hiç hissettin mi?

Baktıkça , akan suya,duran suya.

Kendini ve diğerlerini

Hissedebilir misin soğuğu?

Sım sıcak olduğunu düşlediğin sarılmalarda.

Ya ölümün soğukluğunu,

Yüreğinde ve mezar taşlarında.

Sıcacık toprağın koynundayken karşındaki

Bu soğuklukların verdiği açlıklarda

Isınmanın  ne olduğunu bilir misin?

Bana da öğretir misin?

				(Ağust.''00)', 'Sen soğuklarda hiç titredin mi? Soğuk, ayazdan yalnızlıktan 	Sevememekten 	Sevilmemekten Sen soğukta titremenin anlamını hiç yaşadın mı taa ...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/soguklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekle Kavrulmuş ve Susuz', 'gercekle-kavrulmus-ve-susuz-nilsu-sari-pc166', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben boyle gömülmüşüm işte

                                   gerçeğe tutkunluğum yüzünden

                                        ışık özlemlerim yüzünden

Gündüzden bezmiş , güneşten ayrı düşmüş

                                      gömülürüm aşağılara doğru,

                                               akşama doğru ,gölgeye doğru 

                     Tek gerçekle kavrulmuş   ve susuz...........', 'Ben boyle gömülmüşüm işte                                    gerçeğe tutkunluğum yüzünden                                         ışık özlem...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gercekle-kavrulmus-ve-susuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-i-nayet-beyoglu-apg83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her geceden farklı bir geceydi  bu gece

Duyguların dize geldiği, gönüllerin bilemediği

Yüreklerin alev alev yandığı bir geceydi bu gece.

Sahilde kocaman bir ateş yaktım senin için 

Soğuk nefesimizi ılık ılık duygular beslerken

Buharın şeffaflığı ateşin rengine büründü bir anda

Ateşin karsısında kızarıp sararan göz bebeklerimiz birbirine bakarak

Göz yaslarımız yanaklarımızdan süzülürken 

Birbirimize dokunamayışımızın acı ızdırabı okunuyor suratımızdaki çizgilerden 

Yapacak bir şey bulamıyoruz 

Denizin uzağındaki parlayan ışıklara takılıyor gözlerimiz

Saçların dalgalanıyor hafif meltem  rüzgarında

Dayanamayıp boğazımda düğümlenenleri söylemek istiyorum 

Ama olmuyor çaresiz kalmış bütün her şey 

Dilim bile dönmüyor göz yaslarının düğümlediği boğazım yüzünden 

Beklendiği gibi gitmiyor hayallerde canlanan güzel şeyler

Hayali güzel olduğu için orada ateş basındayız sen ve ben

Uzaktan parıldayan yıldıza bakıyorum gözlerim, dalıyorum

Sen yavaşça yaklaşıyorsun yanıma

Basını omzuma koyuyorsun kederle 

Ve gökteki o yıldızın bizim söyleyemediklerimi bize söylemesini bekliyoruz

Kulak veriyoruz deniz dalgalarının sesine

Rüzgarın hafif uğultusu kulaklarımıza en güzel nameleri fısıldıyor

Ve ateşin kenarından kalkıyoruz sese doğru 

Kumlar can atıyor buluşmak için çıplak ayaklarımızla, 

El ele tutuyoruz hiç tutmadığımız ellerimizle

Sahilin dalgaları vuruyor parmak uçlarımıza

Ardından bileklerimizde hafif bir üşüme

Göz göze bakarken giydiğin bembeyaz kıyafetin yavaşça ıslanıyor

Önce dizlerimize 

Sonra belimize kadar ruhumuz üşüyor

Gözlerimiz ayrılmıyor birbirimizden

Deniz dalgaları söylemediğimiz seni seviyorum sözleriyle çalkalanıyor

Gökler ağlamaya başlıyor bütün hüneriyle

Bakışlarımız aynı anda parlıyor artık

Ve tutan ellerimizi görmüyoruz birbirimizin 

Bizi çağıranlar var çok uzak ışıklardan 

En son duyduğum şey senin sesini

En son baktığım şey senin gözlerini

Artık ruhum hissediyor seni ve sevgini

Benim için asla ölmeyeceksin 

Yüzmeyi bilmesek ikimizde

Yüzüyoruz artık sevgi denizinde.', 'Her geceden farklı bir geceydi  bu gece Duyguların dize geldiği, gönüllerin bilemediği Yüreklerin alev alev yandığı bir geceydi bu gece. Sah...', ARRAY['Türk Edebiyatı','Şiir','İnayet Beyoğlu']::text[], 8.5, '{"poet":"İnayet Beyoğlu","poet_slug":"i-nayet-beyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sen-ve-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşluk Müziği', 'kusluk-muzigi-nuri-pakdil-dog0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kutsal inadı olanlar gerekli

Bir kalbi daha olanlar gerekli', 'Kutsal inadı olanlar gerekli Bir kalbi daha olanlar gerekli...', ARRAY['Türk Edebiyatı','Şiir','Nuri Pakdil']::text[], 8.5, '{"poet":"Nuri Pakdil","poet_slug":"nuri-pakdil","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kusluk-muzigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar', 'sevdalar-muhammet-avsar-g73fs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yürekleri yangın yeri eylemiş,,

sönmeyecek kor olmuştur sevdalar,

her gönüle başka bir şey söylemiş,

her telden çağıran sazdır sevdalar...

Aslısına kul eylemiş Kerem''i,

her saniye tuza beler yaremi,

bilinmez derya mı yoksa dere mi?

herkesin yıkandığı sudur sevdalar...

dilden dile geçer destan olurlar,

en asi erkeğe fistan olurlar,

sonu gelmeyecek bir yoldur onlar,

her durağı aşık dolu sevdalar,

Şirinçin Ferhat''a deldirdi dağı,

tuttu mu bırakmaz sağlamdır ağı,

açtıkça dolaşır bu gönül bağı,

çözülmeyen kör düğümdür sevdalar

başa gelir git demeyle savuşmaz,

sen savaşsan o seninle savaşmaz,

herkes onda sevdiğine kavuşmaz,

bazen sonu hüsran olur sevdalar,

kimi yanan ocakları söndürür, 

kimilerin mutlu eder güldürür,

kimilerin verem eder öldürür,

dermansız dertlere sokar sevdalar,

düşmem deme içine yanıltır zaman,

yaş dökmemiş gözler olur bir Umman,

sen inne, o da  samanlıkta saman,

içinde kaybolduğun mekan sevdalar

gün olur bu yolda sen de koşarsın,

gün olur bu yolu sen de aşarsın,

nasıl geldi başa sen de şaşarsın,

kapını zamansız  çalar sevdalar...

AVŞAR''ı da sürükledin narına,

sanma ki bu günüm çıkar yarına,

sen astın beni de kendi darına,

boynum yağlı ipe taktın sevdalar,

sinemi korunda yaktın sevdalar.....', 'yürekleri yangın yeri eylemiş,, sönmeyecek kor olmuştur sevdalar, her gönüle başka bir şey söylemiş, her telden çağıran sazdır sevdalar... A...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Avşar']::text[], 8.5, '{"poet":"Muhammet Avşar","poet_slug":"muhammet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevdalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Pınarı', 'ask-pinari-orhan-gencebay-28tf5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eğer aşka bir ceza verebilseydim 

benim gibi onunda sevmesini isterdim

meçhulden gelmişim meçhule giderim ömür denen şu yoldan

susadım su içitim yürek kansın diye yoldaki bir pınardan

aşk pınarıymış bu içmesen anarsın

 içsen benim gibi aşk diye yanarsın ne ilk içen bendim

ne son geçen bu yoldan dertler başladı aşk pınarından

şimdi arıyorum aşksız günlerimi meğer zehirlemişim

kendi kendimi aşk pınarı değil dert pınarıymış bu kaybettim yarınımın ümitlerini  ümitlerini

sevmemek elde değil zamanı belli değil

 bir canım var yaşarım bende değil

gönlümde seffalet aşkla başladı 

isyan etti bana tüm duygularım

her yudum bir zehir her nefes bir alev

her ahımda kaldı arzularım ah edişte kaldı duygularım', 'eğer aşka bir ceza verebilseydim  benim gibi onunda sevmesini isterdim meçhulden gelmişim meçhule giderim ömür denen şu yoldan susadım su iç...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabahat Seni Sevende', 'kabahat-seni-sevende-orhan-gencebay-np2qx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayat rüya gibi aşk bir kumar gibi kaybettim seni sevgili

yağmur gibi yaşlar akar gözlerimden bulamadım ey sevgili

aşk dolu geceler kadar yanlızım sensizim sensiz

seni başıma taç gözlerime yaş ettim 

şu hasta kalbime aşkını ilac ettim

aşk bu mudur ey sevgilim

bir aşk vardır bir gönülde 

kabahat seni seven şu benim deli deli gönlümde', 'hayat rüya gibi aşk bir kumar gibi kaybettim seni sevgili yağmur gibi yaşlar akar gözlerimden bulamadım ey sevgili aşk dolu geceler kadar ya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kabahat-seni-sevende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahişe', 'fahise-sunay-akin-aiotq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'incitirim korkusuyla 

yıkarken

nasıl da usulca

gezdirirdi ellerini

teninde annen...', 'incitirim korkusuyla  yıkarken nasıl da usulca gezdirirdi ellerini teninde annen......', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/fahise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaten', 'zaten-roni-margulies-9tmbf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl kırık dökük,

yarım yamalak, eksik,

nasıl yamalı hayatlar

geçiyor gözlerimin önünden.

Bir zanaat mutsuzluk sanki:

Öğrenip bir önceki nesilden,

onyıllarca didiniyoruz

ve kuşkuya düşsek de bazen,

sanıyoruz ki

böyledir, iyidir,

ne olacak ki başka,

budur hayat zaten.

Ya beceremiyoruz biz bu işi,

ya da becerecek bir şey yok zaten.', 'Nasıl kırık dökük, yarım yamalak, eksik, nasıl yamalı hayatlar geçiyor gözlerimin önünden. Bir zanaat mutsuzluk sanki: Öğrenip bir önceki ne...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni-margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavşak', 'kavsak-roni-margulies-kthsa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnce uzun bir iskelenin ucunda,

denize dikmiş gözlerini, kımıldamadan,

öylece duruyor adamın biri akşam üzeri.

Önünde su, arkasında kayalar,

unsurların kavşağında kalakalmış sanki.

Giderek kararıyor çevresinde suların rengi.

Ya bir gemi var bu saatlerde beklediği,

ya da sulara bırakıverecek kendini.

Öylesine ince bir denge ki!', 'İnce uzun bir iskelenin ucunda, denize dikmiş gözlerini, kımıldamadan, öylece duruyor adamın biri akşam üzeri. Önünde su, arkasında kayalar,...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni-margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kavsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-roni-margulies-8igny', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte yine İstanbul.

Alçalıyor uçak Florya üzerine,

sağ taraf açık seçik Yeşilköy.

Kapasam gözlerimi:

Adil Abi''nin bisikletçi dükkanı,

Rone Park''ın ağaçlarında kalplerle oklar,

Reks sineması''nın kocaman ekranı,

Ekonomidis''lerin bahçesinde mangallar.

İnişten hemen önce,

uzansam dokunacam, tam uçağın altında,

iki çocuk duruyor caddenin ortasında,

atılıvermiş çimlere bisikletler.

Biliyorum birazdan Yardımçavus''ta

macera bu ya, ayran içmeye gidecekler.

Sarsılarak değiyor tekerler yere:

Yeniden yaşamaya değil bu sefer

gömmeye geldim çocukluğumu, babamla beraber.', 'İşte yine İstanbul. Alçalıyor uçak Florya üzerine, sağ taraf açık seçik Yeşilköy. Kapasam gözlerimi: Adil Abi''nin bisikletçi dükkanı, Rone P...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni-margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/agit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giriş Yerine Söyleşi', 'giris-yerine-soylesi-atilhan-buyuksel-j80tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'lyas- 

Hıdır ağabey bizim Menderesi asan çokmu cesur 

Değilse intikamdan çekinmez mi 

Çekiniyorsa tedbir almaz mı 

Tedbiri varsa tahmin edilemez mi 

Her sene her köyde bir babayiğit doğar 

İstese bile bunların hangi birine tedbiri olabilir 

Korkaksa her yerde gözü kulağı olması gerekmezmi 

Her yerden haber alıyorsa 

herkesin bir yakını ona çalışıyor olmazmı 

Hal böyle ise nasıl seçti bunları 

Seçerken işi teklif ederken hiç hata yapmazmı 

Yaparsa bir yakınımız anlatmazmı 

Şöyle casusluk teklif ettiler 

Vatan için dediler menfaat vaadettiler yutmadım 

Tehdit bilem ettiler ürkmedim demezmi 

Diyen çıkmadığına göre teklifte hata yapmıyorlar demektir 

Böyle firesiz seçimi yapmak için zaruri ilim hangisidir 

Bir bakışla mı anlıyorlar 

Yumurtanın cılkını elmanın çürüğünü 

Belki ölçmesi tartması lazım 

Dokunması ellemesi tutması çevirmesi lazım 

Öyle enayi varmıdır ki buna imkân verecek 

Herkes de enayi değil ya 

Ağabey susuyorsun 

Yoksa 

Eyvah 

Berber mi 

Susuyorsun dahası mı var 

Tellak mı terzimi 

Susuyorsun eyvah 

Dişçi mi eyvah hekim mi vay bana 

Ebe de mi 

Yandım 

Ah Istanbullu ebe yakmış bizi de haberimiz olmamış 

Peki ağabey bir ebe böyle bir çeteye niçin çalışsın 

Anladım kızıyorsun niçinin erkenine 

Önce mühim olan nasıllardır diyorsun 

Ama işi yapmıyorsa nasılı da olmaz değilmi 

Niçinden maksadım sahiden yapıyormu 

Yoksa yaptığına ikna olsak niçinini bulamayabiliriz 

Şimdi baştan alıyorum 

Para için mi 

Değil 

Böyle hiyaneti para için yapacak akreb yoktur bilirim 

Korkudan mı 

Kim bilir 

Ağabey susuyorsun daha beteri ne olabilir 

Laik maik olduğundan mı 

Alaka yok 

Ortodoksmudur 

Yani yanlış anlama 

bizim laiklerin 

hafta sonu tatili 

külahı çulu yılbaşısı 

marşlı cenazesi filan 

hep ortodoks adeti ya 

ister istemez aklıma geliyor 

Bu sokak tıkandı 

Başka noktadan başlayayım 

Firavunun ebeleri bu işi niye yaparlardı 

Anladım tamam kızma geri alıyorum düzeltiyorum 

Firavunun ebeleri bu işi yaparlardı nokta 

Firavunun ebeleri Mısırı terkedince nerelere göçtüler 

Karadan mı denizden mi 

Yelkenle mi kürekle mi 

Yine tıkandık 

Başka sokaktan giriyorum 

Bu gün Mısırda kalmış Firavn kavmi hangi mezhep 

Şii değil sünni hiç değil 

Katolik değil protestan değil 

Ortodoks mu eyvah 

Bunca dinu mezheb varken niçin onda karar kılmşlar 

Dur kızma düzeltiyorum 

Bilemeyiz niçinini 

Görmüyoruz heriflerin içini 

Ortodoksdurlar nokta 

Peki niçin laik görünsünler 

Yine düzeltiyorum 

Laik görünürler nokta 

Ben şimdi ırkçı filan mı oldum 

Hayır 

Lakin bana ırkçı diyecekler 

Gizli ortodoks olduklarını belli edecekler 

Görünüşte laik olanlar 

Yoksa ben bunları söyledim diye 

Çinlinin aklına gelmiyor bana düşmanca sataşmak 

Hindunun da aklına gelmiyor bana iftira atmak 

Demek ki it gibi sataşacaklar 

İtiraf etmiş olacaklar 

Firavnın torunları olduklarını 

Ya sataşan çıkmazsa 

O zaman yanılmışım derim 

Firavunlar kısır imişler soyları bitmiş derim 

O sokağa bir daha bakmam 

Konuyu o yönde daha fazla kurcalamam 

Adaletli dedim mi ağabey', 'lyas-  Hıdır ağabey bizim Menderesi asan çokmu cesur  Değilse intikamdan çekinmez mi  Çekiniyorsa tedbir almaz mı  Tedbiri varsa tahmin edil...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/giris-yerine-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takdim', 'takdim-atilhan-buyuksel-k2a9t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaylı hikayeleri konusunda alemin gerisinde kaldığımız sizin dikkatinizi çekmemişmydi. 

neyse hatırlattık. farkettiniz. Bize örnek gösterilen şu batı günde bir kaç tane uzaylı hikayesi ayda kaç tane uzaylı filimi yılda bir kaç yüz uzaylı masalı sürüyor piyasaya... 

Uzaylılar mesela arizonaya inmiş oluyorlar,sonra yirmi yıl haber çıkmıyor,derken bir bakıyoruzki herifler Los Angeles polis teşkilatına dolmuşlar,hatta bir tanesi devriye geziyor 

James Caan,la birlikte.. 

Uzaylılar esela amarikaaya sızmış oluyorlar her televizyonun anteninin yanına bir tane daha yerleştirip bununla göz bağlayıcı şua salıp esas eşkallerini gizleyerek fahşayı teşvik ediyorlarki,sonunda kaak amarikan alimlerinin keşfi bir gözlük ile bakan biri işi aşikare görüp antenleri uçurup milleti uyandırıyor. Uzaylılar mesela amerikaya tohuum atıyorlar her tohum kimin bbahçesine düştü ise onun şeklini alıp ertesi gün onun yerine işe gidiyor,vaziyete uyanan biri imdat diye koşsa onlardan.Hatta kasabanın doktoru..mesela mesela... 

Filimlerin sayısı on bin cıvarında.Uzaylılar yumurtalarını insan bedenie zerkedip gidiyorlar, 

bu yumurtatan çıkan tırtıl içerden azar azar yiyerk büyüyor olgunlaşınca içerden yarıp çıkıyor. 

Uzaylılar mesela köpeğin sinirinden girip beynine ulaşarak ona emirler veriyorlar,yaniyenidenn proğramlıyorlar,düne kadar marifetli çoban köpeği iken,hariçten bakan kişiye aynı şekli aynı görünürken,bu gün azgın kuduz it olup bulduğunu ısırarak uzaylıların tohumlarını yayıyor kendi helak olana kadar. 

Daha nele var neler. Bu çeşit uzaylı hikayeleri satışından keferenin topladığı mal bir afrika devletinin bütçesini katlıyor. 

Demek ki biz geride kalmışız..Bir taraftan başlamamızın vakti gelmiş geçiyor.Ne yapsak acep diye kara kara düşünürken tesadüfen sayın Esen Boğanın bazı sayfalarını görünce 

buda bir başlangıçtır dedim ve işte buyurun diye takdim ediyorum. 

Aldı Esen Boğa 

Bismillah 

Evvela sualin yararı sonra cevabın çeşidi 

1. Dünyada vukuu bulan şğpheli nahoş hadiseler varmıdır. 

Şüpheli ne demek 

Nahoş ne demek. 

2.Bu hadiselerden rahatsız olduklarını yazıp çizen kişiler varmıdır 

Bunlar mesela kimlerdir 

meslekleeri nelerdir 

meseleye ilgiler nedendir 

emeklerinin netice vermediği sabitmidir 

yapma arkadaş derken kime hitab ediyorlar 

buu kişilerin samimisi sahtekarı nasıl tanınır 

samimilerin çeşidi nedir 

gizlice tehdit edilenleri varmıdır 

can güvenliklerini ahmaklıklarınamı borçludurlar 

samiminin uyananı devrilmektemidir 

sen uzaylı olsan mesela dedik,nasıl çalışırdın 

3.Hadiselerin müsebbibi olarak gösterilen vvaziyeter nelerdir 

fakirlik diyenin delili nedir 

zennginlik diyenin delili nedir 

ırkçılıkdiyenin delili 

tahammülsüzlük diyenin delili 

din diyenin 

iktisat diyenin 

taraftarların biribirini tanımaması diyenin 

4.Hadiselerin müsebbibi olarak işaret edilen şahıslar kimlerdir 

eskimo diyen varmı 

hiristiyanlardır diyenin delili nedir 

yahudilerdir iyenin delili nedir 

uzaylılardır diyenin delili nedir 

ben yaptım diyen kimdir 

alenen iyi yaptım diyen varmı 

5.Her gün on bin sual basan matbuatta sorulmayan sualler varmı 

sorulması ayıp sayılan sualler varmı 

soranı işinden eden sualler varmı 

soranı kim vurdu yapan sualler varmı 

soranı hücrede intihar ettiren sualler varmı 

6.Varsa bu işe yeter gücü zehiri dikeni olan kimdir 

eskimolarmı 

uzaylılarmı 

7.Bu işlerin evveliyatı nedir 

geçen asırda oluyormuydu 

hangi asırda nerede olmuyordu 

hikayesi kaybolmamış en eski olay hangisidir 

8.Nahoş işlerin bir haritası varmı 

bir yayılma güzergahı tesbit edilebiliyormu 

en eski hadiseler hangi deniz cıvarında 

yoksa denize uzak yaylalardanmı yayılıyor 

kuzey kutbbundaki karadeniz üzerinde şaibe varmı 

koreye yekın tatar denizinden ne haber 

uzaylı hikayelerinde çok geçen atlantis nedir 

akdeniz nam dereden nehaber 

ya eyke denizinden eski haber varmı 

9.Dünyanın enn eski matbuatı ne diyor 

_3100 den beri fravun kayıtları varmı 

ehramları iç duvararında saklanan haberler nedir 

onca renkli resimden anlaşılan nedir 

haberleri onca taşın altında gizlenmesi nedendir 

10.Avrupanını eski kitaplarından haber varmı 

en eskisi hangisidir 

_800 den eski bir avrupa kitabı varmı 

yoksa niye yok 

mısır girite uzakmı 

11.Fravunlar mısırdan kaçınca nereye sığındılar 

Hindemi 

habeşemi 

morayamı 

romayamı 

atinayamı 

12.Fravunlar mısıra nerden gelmişlerdi 

girittenmi 

maltadanmı 

kıbrıstanmı 

sudandanı 

13.Bu günn mısırda olup fravun kavmine varislik iddia eden kopt azınlık bu gün kiminle aynı mezhepten görünüyor 

girit gibi ortadoksmu 

hind gibi hindumu 

sudan gibi müslümanmı 

habeş gibi hiristiyanmı 

falaşa gibi yahudimi 

sen uzaylı olsan nasıl bir hal üzere görünürdün 

14.Piramitleri görünce ağzı açık kalanlar cultur cultur diye naralananlar kimlerdir 

afrikalılarmı 

asyalılarmı 

paris,londra nnew yorklularmı 

yapan senin ceddin olsa idi sen nesıl davranırdın 

15.Çağdaş new yorkun hal ve gidişi kime benziyor 

kızılderilileremi 

irlandalılaramı 

sodom ve gomoreye mi 

bizans ve romayamı 

paris ve londrayamı 

16.Amsterdam bu hikayede nasıl görülüyor 

endonezyayı hangi hüneriyle istila edebilmiş 

elas işleme merkezi olması neyin nesi 

elmas işlemenin ilmi kaç senee mektep ister 

elmasa meraklılar uzaylımı 

17.Portekizin bu hikayedek yeri nedir 

Niye ingiliz imparatorluğundan uzun sürdü 

niye hala çin sahilinde sömürgesi var 

angola ile mozambiği nesiyle onca asır tutabildi 

portekiz bayrağı ile çalışanlar uzaylımı 

18.Misonerler meselesine ip ucu varmı 

güney amarikayı beş asırda nettiler 

çinde iki asır neydi işleri 

japonya ile maceraları nedir 

kızılderilileri nasıl hallettiler 

ruvanda ve brundide haritaları nasıldır 

sen uzaylı olsan bu işleri nasıl yapardın 

19.Dünya gezegeninin dini kitaplarında bu konular varmı 

misyonerlerin incilinde vaziyet nedir 

bizim kitabımızda işaretler nelerdir 

bırakın bunları diyen kimdir 

kızıl derilileri önce sekiz yıllık kesintisiz yatılı ilk okul şartı koyanlar kimlerdi 

bu mecburi tahsilde nnelerin ööğretilmesini yasak ettiler bir nesil byle oyaladıktan sonra ne yaptılar 

20.Bizansın bu hikayede yeri nedir 

Bizim laiklerin arasında her poh varda niye bizanslı yok 

sen bizanlı olsan nasıl teşkilatlanırdın 

hangi partiye girmezdin 

hepsine girmemen için sebep ne 

Beri tarafta yoksulluk felaket savaşlar katliamlar faili mechul cinayetler iflaslar 

Geri tarafta sermaye katlayan kıtalar kundaklayan bir acayip gizli güç 

ekene biçtirmeyen biçene yedirmeyen borç almazı borçlandıran borça alanı sakatlayan 

önce borçlandırıp sonra ödeyemesin diye tarla ddükkan yaktıran bir güç. 

Müsemması her yanda sırıtıyorken ismi nerede bu gücün yüz köşe yazarı bin isim kaç bin sıfat kullanır olmuşlarki ismin hala meçhul olduğuna başka delil gerekmez 

ismi konulmadıkca cismine zincir vurulamaz şerrine sed çekilemez bir azim bela 

ruvandadan bosnaya bağdattan haybere gavur masllarındaki oraklı iskelet gibi dolaşıyor', 'Uzaylı hikayeleri konusunda alemin gerisinde kaldığımız sizin dikkatinizi çekmemişmydi.  neyse hatırlattık. farkettiniz. Bize örnek gösteril...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":139,"source_url":"https://www.antoloji.com/takdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayber', 'hayber-atilhan-buyuksel-ff1t7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşılmaz bir kale koruyor seni 

Haybersin galata keşfim zor seni 

Ne top ne gülleler hayreder sana 

Kat kat duvarlar ne yol gider sana 

Altı milyarı nedir sırrı gütmenin 

Bir düdük aynı yöne gitmenin 

En bizdeni niçin bekçidir sana 

En akıllısından en şarlatana 

Korur seni geçilmez ordular 

Ve etten kemikten duvar oldular 

Ya nasıl yıkayım hayber kaleni 

Ya haybersin desem kim duyar beni 

Yahudi rum mason çingenelerin 

İçimizde kalen bilinmez yerin 

Hayber görünmez bela atar cirit 

Uyur gezer vatan kurtaran yiğit 

Kasdeder kim sana bulursun hayber 

Gider gümbürtüye duyulmaz haber 

Bin it bulursun şahit bulamam 

Oyunu bozmaya yiğit bulamam 

Olmadık suçla iftira atarsın 

Bir yalana binbir yalan katarsın 

Galata bilsem seni anlatamam 

Kısalır ömrü kim anlatırki tam 

Çamur atar izi kalır suç kalır 

Hayber diyen ekmeğe muhtaç kalır 

Sana dil uzatanı bulamazsan 

Geçer kılınır beynelmilel yasan 

Başa iner geçilmez gümrüklerin 

Dar gelir dünya kırmızı bülltenin 

Bir dokunan bin bela alır başa 

Söndürür hayatı sızlamak boşa 

Ya faili meçhule kurban gider 

Gaza süsüyle felç olur yan gider 

Susar akrep içgüdülü güçlerin 

Delilsiz gizli kalır ipuçların 

Ya asılır alkışa duyan gider 

Üstüne siyah çelenk koyan gider 

Uçkuru çözülmedik bir iftira 

Verirsin balans ayarı muhtıra 

Sincandan taş atsam surun sarsılır 

En uyuz it ürür öne atılır 

Dokunsam cıyak cıyak seslenir 

Telawiw newyork romadan ses gelir 

Bizim itleri geçsem sizin ipler 

Geçit vermez vatan kurtaran tipler 

Bütün alem muzdarip nerde varsan 

Filistin afrika asya hindistan 

Sahil şehir limanlarda burçların 

Her devlet içinde gizli uçların 

Tiyatro oynamak tek maharetin 

Oynatırsın bizi pek az külfetin 

Benzer düşmanın süt dökmüş kediye 

Hizmetine bahşedilmiş hediye 

Yeriyorken hoşgörü dehası var 

Ayakta uyur musamahası var 

Kundağa kasdeder benim düşmanım 

Sefalet içharb kan dolu vatanım 

Yak fitne ateşi horoz boğuştur 

Sen geri çekil sevin el oğuştur 

Adını desem yasak düşmanımın 

Bahtı bu milletimin vatanımın 

Boyadın gözü iğrenci şık ettin 

Akıllarımızı karmaşık ettin 

Gözün en ücra köşede heryerde 

Borç takarsın doğmayan bebeğede 

Ne zormuş meğer milyonu beslemek 

Mılyar arı gibi çalışsın demek 

Alemin kazancı kesbi kasası 

Cebinde fonu bilmem ne borsası 

Sabahtan müreffeh abad edersin 

Akşama felceder berbad edersin 

Hem kan akıdır insaf hem soyarsın 

Hayber fesadınla heryerde varsın 

Akrepte zehiri bana yazıklar 

Maharet zanneden bayraktarım var 

Alemin tevessül etmediğini 

İşleyen kavimsin işlediğini 

Varmı işleyen kavim ey galata 

Kuşat alemi yayıl her tarafta 

Bir ucun londra paris atina 

Otur milletlerin karabahtına 

Yutarsın her devleti bütçesiyle 

Hanedanı hanı şehzadesiyle 

Yetmez iç harble kasdedersin cana 

Don biçersin hayber ta doğmayana 

Bilinmedik aşılmadık kalesin 

Her yerde galata sulu kulesin 

Ta karaköyden tohumu atarsın 

Geleceğe yön verir fal bakarın 

Uzanır soyun ta eski mısıra 

Eski yunan karaim yanısıra 

Küfret yetmiş iki millete çıt yok 

Adın demek suç fişlemeyen it yok 

Buçuk millet her milletin hayberi 

Bizim hayber köhne bizanstan beri 

Limanlardan gelir fuhuş fitnesiyle 

Her millte milletin kisvesiyle 

Adın başka olur nufusun başka 

Kılığa girer renk bulursun başka 

Bin yıl geçer akrep başkalaşmazsın 

Hayber nere gitsen fitneye başsın 

Nerde bir gülistan görsen bozarsın 

Bozar tahrib eder sahib çıkarsın 

Her rezalet değişmez fıtratına 

Uyar hayber tükürsem suratına 

Akrep gibi yavaşsın sabırlısın 

Kan içersin dünya ile hırlısın 

Becerin yok yarımsın karlısın 

Yılan gibi yer altında sırlısın 

Edep sanat yok zeka kusurlusun 

Fesandınla nasıl böyle zorlusun 

Olduğun yer kan kokar olur bizar 

Usanırdırır insan canından bezer 

Bozulacak bütün oyun alemde 

Bekle maya tuttu pek yakın hemde', 'Aşılmaz bir kale koruyor seni  Haybersin galata keşfim zor seni  Ne top ne gülleler hayreder sana  Kat kat duvarlar ne yol gider sana  Altı ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/hayber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenim', 'bedenim-atilhan-buyuksel-0b6z4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşılmaz yolları aşar yürütür 

Ruhumun peşine koşma bedenim 

Beşikten mezara besler büyütür 

Sonra terkederse şaşma bedenim 

Bir yanda hakikat yalan bir yanda 

Yazin kışı yaşa kışınsa yazı 

Yolcu ol göğe yaşayıp zamanda 

Gece rüyalarda oldur olmazı 

Boş işler peşinde koşup yorulma 

Olma be ruhum böyle dengesiz 

Dalıp hülyalalara tahta kurulma 

Olur olmazları geçiştir sessiz 

Her gün degişir o renkten bu renge 

Gece alıp gider çıkmaz yollara 

Gün başlayınca cağırır cenge 

Kendine bu yolda başka dost ara', 'Aşılmaz yolları aşar yürütür  Ruhumun peşine koşma bedenim  Beşikten mezara besler büyütür  Sonra terkederse şaşma bedenim  Bir yanda hakika...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bedenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bela', 'bela-atilhan-buyuksel-sxwpi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başımda bela 

Çekilmez yeter 

Ölmeye gerek 

Varmı varlığım 

Ölümden beter 

Bir çığlık atar 

İçimdeki ses 

Cinler oynaşır 

Periler koşar 

Bende her nefes 

Dogar sanırdım 

Bir hüzme ışık 

Doğmadı gitti 

Hayat çekilmez 

Karma karisik 

İçimdeki şu 

Silinmez aci 

Asti ruhumu 

Çığlık atarak 

Kurup darağcı 

Yazılmış başa 

Hayat nafile 

Ne yapsak boşa 

Dert çekip ağla 

Yaşarsan yaşa', 'Başımda bela  Çekilmez yeter  Ölmeye gerek  Varmı varlığım  Ölümden beter  Bir çığlık atar  İçimdeki ses  Cinler oynaşır  Periler koşar  Ben...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-atilhan-buyuksel-xldkl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğmadık bebeği borçlandıran 

Ne yapmazki doğan bebeğe 

Çağdaş geçinir bizi kandıran 

Senfoni der davul dümbeleğe 

Takar Türkü kürde dönme guruh 

Türk adına Araba küfreder 

Övgü yağdırır ruma perse yuh 

Ona çağdaş bize gerici der', 'Doğmadık bebeği borçlandıran  Ne yapmazki doğan bebeğe  Çağdaş geçinir bizi kandıran  Senfoni der davul dümbeleğe  Takar Türkü kürde dönme g...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bebek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başörtü', 'basortu-atilhan-buyuksel-tuzuc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başörtmek suçmu diyen haşa suç olurmu 

Baş örten ananın savcısı piç olurmu 

Başörtmen bahane kardeşim varlığın suç 

Soyu piç olandan insaf beklenirmi hiç 

Başörtmek suç değildir bizde hep taç olur 

Savcısı piç olana başörtmek suç olur 

Soyunnmak moda örtünmek yunanda suçtu 

Zina aşikare doğan bebekler piçti 

Örtünmekten ya hangi millet huy kapardı 

Rum değilse savcı rum olsa ne yapardı 

Benzemez dini dinime türkmü şu savcı 

Türkün herşeyine hem it olur hem avcı', 'Başörtmek suçmu diyen haşa suç olurmu  Baş örten ananın savcısı piç olurmu  Başörtmen bahane kardeşim varlığın suç  Soyu piç olandan insaf b...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/basortu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-haydar-ergulen-nj1wo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-idil''e-

O Şehre davrandığın gibi davran bana da

O Şehre gittiğin gibi bana da git uçarak

bana da in, bana da kon ve el salla geride

bıraktığına: Elveda benim küçük adamım!

ufacıktan bir Şehri nasıl adam ettinse,

Sevdinse adam gibi, beni de o Şehir gibi

sev! Korkma sakın, adam etmez aşk beni,

geç benden, benim de köprülerim var,

aşkı seyret oradan, dalgın günüm geçiyor,

benim de gecelerim var, danset, eteklerin

fırdönsün, sen bana dön, bana eşlik et,

benim de sabahlarım var, uyanmaya ne saat,

ne telefon, ne kapı: bisikletin zilini

dizlerini kanatan bir deli kız çalsın yeter ki!

Benim de parklarım var, uzanıver salkımsaçak

üstüme, dalımdan tut, benim de yapraklarım var

güneşli gövdene müjde eli kulağında bahar,

benim de Şiirlerim var, aşk konulu, senin

o Şehri sevmene benziyor, seni sevmeye

benziyor adamakıllı serserin olana kadar

Bir Şehri kıskanıyorum, benim böyle neyim var?', '-idil''e- O Şehre davrandığın gibi davran bana da O Şehre gittiğin gibi bana da git uçarak bana da in, bana da kon ve el salla geride bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkan', 'balkan-atilhan-buyuksel-i2akc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Veda ettim Edirneden vatana 

Uzandı yolum şu garib balkana 

Ova üstüne serilmiş yadigar 

Yol uzadıkça uzar şanlı tuna 

Bu vatan bir zamanlar şen şakraktı 

Bayrak açtı kadırga tuna aktı 

Yıkılmış camiler sönmüş ocaklar 

Nerde o eski ihtişamlı vaktı 

Gece garabeti çökmüş balkana 

Boyanmış toprağı yatar alkana 

Yad et eski günleri sehavetten 

Silkinip kalk bir daha haykır tuna 

Duyar gibiyim geçerken tunadan 

Vaz geçmiş yiğiter yardan anadan 

Akıncının sesi çınlar kubbede 

Bu topraklarda böyleydi bir zaman 

Geçerken tunayı burkulur için 

Baykuşmu tünedi garibsin niçin 

Dirilmezmi tarih kalkıp uykudan 

Akıncım bu yolları bir daha geçin', 'Veda ettim Edirneden vatana  Uzandı yolum şu garib balkana  Ova üstüne serilmiş yadigar  Yol uzadıkça uzar şanlı tuna  Bu vatan bir zamanlar...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/balkan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-atilhan-buyuksel-8pute', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benmiyim aynadaki bu adam 

Elleri bağlı hayali kırık 

Bin yılı geçmiş gibi üstünden 

Şakakları beyaz teni kırışık 

Adem in doğup Nuhun öldüğüne 

Şahit olmuş gibi aklı karışık 

Hemen inanir duyup gördügüne 

Bu adam dünyada kaç yıllık 

İlimden nasibin almamiş adem 

Değersiz dediği,karma karışık 

Bakmayin yine söylenir madem 

Diyar diyar kovulmaya alışık', 'Benmiyim aynadaki bu adam  Elleri bağlı hayali kırık  Bin yılı geçmiş gibi üstünden  Şakakları beyaz teni kırışık  Adem in doğup Nuhun öldüğ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aynalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayı Oynatanlar', 'ayi-oynatanlar-atilhan-buyuksel-8jgyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değil biçare insana hayvana bile 

Zulmeder kopt azınlık sustun be kardeşim 

Ayaklarını zincirler burnunda lule 

Hakkını aramdın pustun be kardeşim 

Seni eğlendirirdi ayı oynatanlar 

Kendinden geçip güldün kustun be kardeşim 

Ayıların üzerinde bedduası var 

Ya seni oynatınca küstün be kardeşim 

Ateşe bastırlılırılınca ayı oynardı 

Belki yok idi ama kastın be kardeşim 

Ayının imdadı melul bakışı vardı 

Sıra senin ateşe bastın be kardeşim', 'Değil biçare insana hayvana bile  Zulmeder kopt azınlık sustun be kardeşim  Ayaklarını zincirler burnunda lule  Hakkını aramdın pustun be ka...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayi-oynatanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarım', 'ayaklarim-atilhan-buyuksel-p042n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayaklarım adım adım 

Bu yola yürüdü gitti 

Beni kendi adımlarım 

Ölüme sürüdü gitti 

Ey bu köyün sakinleri 

Bütün varımı yitirdim 

Bir ileri koştum geri 

Bitmez bir ömrü bitirdim', 'Ayaklarım adım adım  Bu yola yürüdü gitti  Beni kendi adımlarım  Ölüme sürüdü gitti  Ey bu köyün sakinleri  Bütün varımı yitirdim  Bir ileri...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaksız Atlılar', 'ayaksiz-atlilar-atilhan-buyuksel-887cb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayaksız atlılar yine bugün 

Ağır ağır buradan geçtiniz 

Başkasının doğup öldüğüne 

Gün tayin edip ömür biçtiniz 

Demek bu yolcu gider sürgüne 

Bir yolcu varmış haberi duyur 

Dediniz öldü filan oğlu zat 

Herkes ayakta yolcuysa uyur 

Göçüp hayattan oldumu azat 

Yeni hayata denilir buyur 

Beklemekte sabahta boşuna 

Güneeş doğmaz ağarsa tan yeri 

Ah çekip ağla vahta boşuna 

Bu yolda gelirmi giden geri 

Dövünsek yırtınsakta boşuna', 'Ayaksız atlılar yine bugün  Ağır ağır buradan geçtiniz  Başkasının doğup öldüğüne  Gün tayin edip ömür biçtiniz  Demek bu yolcu gider sürgün...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayaksiz-atlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasapname', 'kasapname-atilhan-buyuksel-lq8mm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akıllımız bizim neden 

Akıbeti ipe gider 

Hangi gizli güçtür güden 

Bizi nana muhtaç eder 

Devletin bekası demiş 

Yalan fetva yalan mühür 

Şehzade katleden devlet 

Demek parçalanmaz büyür 

Rumda bin çesit iftira 

Bilinmez ne iskence var 

Şehzadeye dilsiz rolü 

Yapip bogmuş binlerce var 

Sinagogda yazmiş rahip 

Fetva sahte tuğra sahte 

Yazan rahip fetva demiş 

Alime iftira sahte 

Genç osmani boğan şu güç 

Dönme imiş türk olurmu 

Başını türk kesermi hiç 

Fitneye körük olurmu 

Şu İsmetin meçhul soyu 

Asmiş beşbin hain deyip 

Takmiş rum it tarih boyu 

Alimlerin boynuna ip 

İpimi çeken çingene 

Keyiflenme asar beni 

Mavi gözlü su rum kene 

Aliko boğdurur seni 

Menderesi boğan şu it 

Hizmet demiş inanmişiz 

Boğmuş dönme onca yiğit 

Selam çakip sayanmişiz 

Kimine yobaz karasi 

Asar hain der uydurur 

Ona solcu damgasi 

Bunu sağci deyip vurur 

Hain diyen asılana 

Alkışlayandır köpekler 

Kültürüne manukyana 

Ya sahip çıkar ya bekler 

Haddini bil cıfıt mason 

İlerici gerici kim 

Manukyana bekci olan 

Vatan sever bölücü kim 

Madalya ver manukyana 

Alan tükmü veren türkmü 

Alim asip müslümana 

Yobaz deyip yeren Türkmü', 'Akıllımız bizim neden  Akıbeti ipe gider  Hangi gizli güçtür güden  Bizi nana muhtaç eder  Devletin bekası demiş  Yalan fetva yalan mühür  Ş...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kasapname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmdadım', 'i-mdadim-atilhan-buyuksel-mwoz2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne göklerde bir ilham 

Ne muradım var benim 

Ne aldım dünyada kam 

Ne bir adım var benim 

Kubbe üstüme düşmüş 

Bitti yadım var benim 

Soldum çökmüş büzüşmüş 

Ne imdadım var benim', 'Ne göklerde bir ilham  Ne muradım var benim  Ne aldım dünyada kam  Ne bir adım var benim  Kubbe üstüme düşmüş  Bitti yadım var benim  Soldum...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/imdadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bela ya Cevap', 'bela-ya-cevap-atilhan-buyuksel-8k2kx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne ithaldir cinden macinden 

Bize belalar galatanin dönme.. 

.......Picinden gelir 

Önce limanlara göceder 

Sonra basa bela pic nesil 

........Icinden gelir 

Bin yillik gecmisi bir günde 

Yikar dönmeler basimiza 

........gecinden gelir 

Hangi yola varsan cikilmaz 

Yollar acik fitneye susmak 

.........icinden gelir 

Meyhanelerde eker tohum 

Sonra pic nesil neden denir 

.........Nicinden gelir.', 'Ne ithaldir cinden macinden  Bize belalar galatanin dönme..  .......Picinden gelir  Önce limanlara göceder  Sonra basa bela pic nesil  ........', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bela-ya-cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormayin', 'sormayin-atilhan-buyuksel-ox6fv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sormayin burda 

Derde devadan 

Olmaz geciniz 

Sifa kayboldu 

Devadan ayri 

Deva seciniz 

Kasemde serbet 

Sanmayin ilac 

Zehir iciniz 

Kiymeti yok 

Ne verirseniz 

kiymet biciniz', 'Sormayin burda  Derde devadan  Olmaz geciniz  Sifa kayboldu  Devadan ayri  Deva seciniz  Kasemde serbet  Sanmayin ilac  Zehir iciniz  Kiymet...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sormayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartal', 'kartal-atilhan-buyuksel-h9n89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beş asır uyanmaz ölüm uykusundayız 

Düşürdün hayber kahbe pusundayız 

Üstümüze saçılmış ölü toprağısın 

Yarışa ne gün uyansak ayak bağısın 

Bu milleti olmadık şeyle oyaladın 

Dünya asra koşar gözümüzü boyadın 

Hayber olaydında merd düşmanım nolaydı 

Bizden üstün ya bir meziyyetin olaydı 

İleriydik dünyada geriyiz yarışta 

Bozuldu düzen iktisadımız barışta 

Geçirdik zamanı yalanın laklakınla 

Yücelerden leş kargası vakvakınla 

Gökte kartalı alıp ayağa düşürdün 

Kahbece bu milleti tuzağa düşürdün 

Sığındın tahammül boş verip geçimize 

Ta uzaktan gelip yamandın içimize 

Yerli oldun milletimi dağa düşürdün 

İninde yılan aslanı ağa düşürdün', 'Beş asır uyanmaz ölüm uykusundayız  Düşürdün hayber kahbe pusundayız  Üstümüze saçılmış ölü toprağısın  Yarışa ne gün uyansak ayak bağısın  ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kartal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zifiri Karanlık', 'zifiri-karanlik-atilhan-buyuksel-nc3av', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey zifiri karanlık 

Bunaldım bu hayattan 

Ustüme düş bir anlık 

Ana gibi gölge ol 

Hayat dediğin zikzak 

Bugün güldüğün şeye 

Demek yarın ağlamak 

Bilde bana bilge ol', 'Ey zifiri karanlık  Bunaldım bu hayattan  Ustüme düş bir anlık  Ana gibi gölge ol  Hayat dediğin zikzak  Bugün güldüğün şeye  Demek yarın ağ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zifiri-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-atilhan-buyuksel-f58yq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün olur yüzünde yollar akar 

Yılların çizgisi bir bir okunur 

Elinde asa olur başında kar 

Sarayda yaşa köşke gir dokunur 

Zirveden inmeye başlayınca 

Yaprak dökümün güz olur bir gün 

Geçen günleri bir bir sayınca 

Bakarsın günün az olur bir gün', 'Gün olur yüzünde yollar akar  Yılların çizgisi bir bir okunur  Elinde asa olur başında kar  Sarayda yaşa köşke gir dokunur  Zirveden inmeye ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanaryam', 'kanaryam-atilhan-buyuksel-28479', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uctu kanaryam 

Sonsuza dogru 

Basladi paryam 

Oldumu dersin 

Vardigi yerde 

Actimi güller 

Devayi derde 

Buldumu dersin 

Acmadi lale 

Bülbüle küstü 

Düstü bu hale 

Soldumu dersin 

Hasretin yeter 

Damda kanaryam 

Baykuslar öter 

Kondumu dersin 

Böylemi rüya 

Terkedip gitti 

Bir hayat guya 

Buldumu dersin 

Devasiz derde 

Düstüm vefasiz 

Halimi nerde 

Sordumu dersin 

Cesme kurudu 

Güle su veren 

Atesin yurdu 

Sardimi dersin 

Çabuk güz oldu 

Bitti tükendi 

Ömrüm tez oldu 

Ardımı dersin', 'Uctu kanaryam  Sonsuza dogru  Basladi paryam  Oldumu dersin  Vardigi yerde  Actimi güller  Devayi derde  Buldumu dersin  Acmadi lale  Bülbül...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kanaryam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-atilhan-buyuksel-fkl4m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yakında oldum gördüm uzağı 

Düştüm ağına bir avcının 

Kör düğümleri çıkmaz tuzağı 

Tatdım kahrını hayat ağacının 

Kös kös geldi belalar abandı 

Koştum imdada olmadı duyan 

Yer çöküp gök battığı zamandı 

Bunca cefaya dediler dayan', 'Yakında oldum gördüm uzağı  Düştüm ağına bir avcının  Kör düğümleri çıkmaz tuzağı  Tatdım kahrını hayat ağacının  Kös kös geldi belalar aban...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kordugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafta', 'kafta-atilhan-buyuksel-gmm3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedi basli dev 

Yatarmis kafta 

Varligi yutan 

Gıder ön safta 

Kücük büyügü 

Doyurmak gerek 

Büyük kücügü 

Yutup yiyerek 

Üc yüzü yer yüz 

Biter üc bitmez 

Sayilar baska 

Burda bilinmez 

Akrep suskunmuş 

Olurmus titrek 

Doymaz varligi 

Yutup yiyerek 

Akıbet meçhul 

Olur bu yolda 

Giden gelirmi 

Kalırmı orda', 'Yedi basli dev  Yatarmis kafta  Varligi yutan  Gıder ön safta  Kücük büyügü  Doyurmak gerek  Büyük kücügü  Yutup yiyerek  Üc yüzü yer yüz  B...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kafta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-atilhan-buyuksel-0yy2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hürriyet dedikleri 

Şu yalan sahte ilaç 

Elini bağlar kolun 

Kırar derki haydi kaç 

Kavuk salla bük boyun 

Sakin geri uç olma 

Ol sürüde bir koyun 

Hele ki koç hiç olma 

Soyul dişin sökülde 

Sus konuşma suç olma 

Çevir başin bükülde 

Ya sürüde hiç olma 

Ya terkedip yaban ol 

Yere düşmüş taç olma 

Ya sürüde çoban ol 

Kemik kap muhtaç olma 

Koyun gibi aydin ol 

Yola gelmez güç olma 

Kap bir köşe saygin ol 

Hele işsiz hiç olma 

Ya razi ol ya kaçta 

Kasab icin koç olma 

Ister aç ol muhtaçta 

Piçe it zangoç olma 

Adam ol derler sakin 

Diyar diyar kaç olma 

Seyyadi bi insafin 

Emrinde ki piç olma 

Koyun gibi sayilan 

Kasaba dost geç olma 

Böbürlenip yayilan 

Gözü dönmüş aç olma 

Olma be kardeşim hiç 

Ne koyun ol kasaba 

Ne Bizans elinde güç 

Ne sayıl gir hesaba', 'Hürriyet dedikleri  Şu yalan sahte ilaç  Elini bağlar kolun  Kırar derki haydi kaç  Kavuk salla bük boyun  Sakin geri uç olma  Ol sürüde bir...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ogut-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usanç', 'usanc-fethi-giray-wwthe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usandim,

Yesermemis umutsuz bahceyi beklemekten...

Usandim,

Tarla kusunun sesinden...

Usandim,

Bu yurekten, kendimden...

Usandim,

Durup durup seni ozlemekten!...', 'Usandim, Yesermemis umutsuz bahceyi beklemekten... Usandim, Tarla kusunun sesinden... Usandim, Bu yurekten, kendimden... Usandim, Durup duru...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usanc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrancı', 'i-ranci-atilhan-buyuksel-mpfmx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu memlekette herkesin cısı var 

Türkün irancısı turancısı var 

Bu kan bağıdır öteki din bağı 

Bizim dönmenin niçin sancısı var 

İrancimisin diyen cıfıtım sen 

Hele de fanatik siyoncumusun 

Herkesin din bağı olur kan bağı 

Ortadoksum helen iyoncumusun 

Mollalar irana diyen yanaşma 

Cıfıtmı nesebin Türkten türkmüdür 

Doğru söyle ortadoksum kırışma 

Vatan sevgisi bizden büyükmüdür 

Kan çeker yunana dizer medhiye 

Sapık yolunu çağdaş der yutturur 

Terörist devlete terörist diye 

Diyene medyan lanet okutturur 

Diyemezsin dost araba irana 

Damgalar cıfıtım Türklük adımıza 

Rusvay eder basını dosta düşmana 

Dost bulunaz gelmez imdadımıza 

Yasaktır övgü dizme müslümana 

Siyonist devleti yunanı medhet 

Şarkılar diz övgü yağdır yunana 

Tevrat incili akan kanı medhet', 'Bu memlekette herkesin cısı var  Türkün irancısı turancısı var  Bu kan bağıdır öteki din bağı  Bizim dönmenin niçin sancısı var  İrancimisin...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iranci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Alem', 'bu-alem-atilhan-buyuksel-6bg1c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu alemde derde derman olan deva yok 

belki hayatta hayat kadar berheva yok 

Düstünse kaldiran olmaz yüzüstü 

Iste gönül böyle bivefa dosta küstü 

Aradim bulmadim kisi kendinden özge 

Ne es ne dost ne ya bulunur tenden özge 

Dert icinde kivraniptir gönül ama 

Dost bidigin dünyada dost bulama 

Iste dert odurki devasi yok devasiz 

Zebun oldum yüzüstü düsüp vefasiz 

Duyanin yok kaldiran olmaz düsmeye gör 

Olmaya bu alemde sarhos olup icmeye gör 

Yazin yel olur tufan olur baharda zemheri 

Kisin donup kalirsin kapindan iceri 

Giren rüzgar olur yel olur sel olur 

Nerde vefasizlik derd ile gel olur 

Ilham olur dert olan deva diye ne varsa 

Bilmem bu dertler bende böyle ne ararsa', 'Bu alemde derde derman olan deva yok  belki hayatta hayat kadar berheva yok  Düstünse kaldiran olmaz yüzüstü  Iste gönül böyle bivefa dosta ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-alem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdime Çare', 'derdime-care-atilhan-buyuksel-30krm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdime care 

Sihirbaz kadin 

Acti tasini 

Aciyi tadin 

Ictigim ilac 

Zehirden aci 

Astilar beni 

Kurup daragci 

MANZARA 

Anladım ne demek çağdaşız biz 

Neki yüzyılı alıp yuttunuz 

Dünya nere gider siz lafında 

Milleti yüzyıl geri tuttunuz 

Çöpten ekmek toplayan sahneler 

Birde aç bıraktınız soyuttunuz 

Bunaldı millet sefalet dizboyu 

Demek buydu sizin mutlunuz 

Dur diyene tehdit savuran 

Devrim mukaddesiniz kutlunuz 

Hasta yaşlı cocuk milletin 

Kanını ta iliğini kuruttunuz 

Olmaz bu çağda en gerici siz 

Hayret bizi nasıl uyuttunuz', 'Derdime care  Sihirbaz kadin  Acti tasini  Aciyi tadin  Ictigim ilac  Zehirden aci  Astilar beni  Kurup daragci  MANZARA  Anladım ne demek ç...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/derdime-care-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyler', 'beyler-atilhan-buyuksel-kh5qu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazıkki bu millete bitti yüzyılı 

Hikaye dinler o efendi bu beyden 

Onlar içer sofrada oynamaz kılı 

Millet şu aç sefil yalın ayak giden 

Önce aldılar ne varsa elimizde 

Çağdaş yol bizi getirdi bu hale 

Bir o izde götürdüler bir bu izde 

Aç bıraktılar olsun doyduk hayale 

Devrim yaptık işte bu yolda çağdaşız 

Sarık çıkardık şimdi giyindik peruh 

Aya gitsin el devrim ile bağdaşız 

Tükürün beyler eskiye tükürün tuh 

Şerefe kaldırın kadehi hakkınız 

Öğretin çağdaş olmayı yamyama 

Yüzyılda bir arpa boyu yol aldınız 

Çabuk yoldan nasıl çağdaş olduk ama', 'Yazıkki bu millete bitti yüzyılı  Hikaye dinler o efendi bu beyden  Onlar içer sofrada oynamaz kılı  Millet şu aç sefil yalın ayak giden  Ön...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heykel', 'heykel-atilhan-buyuksel-yy6z1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Putu heykeli bizans kültürü 

Zoraki çağdaş yolunu yürü 

Deve yarışı tosbağa türü 

Sırtında yük hörgücü bulunmaz 

Niçin sokağa dikilmiş höyük 

Bindir anadolu üstün yük 

Bir ağırlık ki cüsseden büyük 

Sırtına almaya gücü bulunmaz 

Aşılmaz bir kale koruyor seni 

Haybersin galata keşfim zor seni 

Ne top ne gülleler hayreder sana 

Kat kat duvarlar ne yol gider sana 

Altı milyarı nedir sırrı gütmenin 

Bir düdük aynı yöne gitmenin 

En bizdeni niçin bekçidir sana 

En akıllısından en şarlatana 

Korur seni geçilmez ordular 

Ve etten kemikten duvar oldular 

Ya nasıl yıkayım hayber kaleni 

Ya haybersin desem kim duyar beni 

Yahudi rum mason çingenelerin 

İçimizde kalen bilinmez yerin 

Hayber görünmez bela atar cirit 

Uyur gezer vatan kurtaran yiğit 

Kasdeder kim sana bulursun hayber 

Gider gümbürtüye duyulmaz haber 

Bin it bulursun şahit bulamam 

Oyunu bozmaya yiğit bulamam 

Olmadık suçla iftira atarsın 

Bir yalana binbir yalan katarsın 

Galata bilsem seni anlatamam 

Kısalır ömrü kim anlatırki tam 

Çamur atar izi kalır suç kalır 

Hayber diyen ekmeğe muhtaç kalır 

Sana dil uzatanı bulamazsan 

Geçer kılınır beynelmilel yasan 

Başa iner geçilmez gümrüklerin 

Dar gelir dünya kırmızı bülltenin 

Bir dokunan bin bela alır başa 

Söndürür hayatı sızlamak boşa 

Ya faili meçhule kurban gider 

Gaza süsüyle felç olur yan gider 

Susar akrep içgüdülü güçlerin 

Delilsiz gizli kalır ipuçların 

Ya asılır alkışa duyan gider 

Üstüne siyah çelenk koyan gider 

Uçkuru çözülmedik bir iftira 

Verirsin balans ayarı muhtıra 

Sincandan taş atsam surun sarsılır 

En uyuz it ürür öne atılır 

Dokunsam cıyak cıyak seslenir 

Telawiw newyork romadan ses gelir 

Bizim itleri geçsem sizin ipler 

Geçit vermez vatan kurtaran tipler 

Bütün alem muzdarip nerde varsan 

Filistin afrika asya hindistan 

Sahil şehir limanlarda burçların 

Her devlet içinde gizli uçların 

Tiyatro oynamak tek maharetin 

Oynatırsın bizi pek az külfetin 

Benzer düşmanın süt dökmüş kediye 

Hizmetine bahşedilmiş hediye 

Yeriyorken hoşgörü dehası var 

Ayakta uyur musamahası var 

Kundağa kasdeder benim düşmanım 

Sefalet içharb kan dolu vatanım 

Yak fitne ateşi horoz boğuştur 

Sen geri çekil sevin el oğuştur 

Adını desem yasak düşmanımın 

Bahtı bu milletimin vatanımın 

Boyadın gözü iğrenci şık ettin 

Akıllarımızı karmaşık ettin 

Gözün en ücra köşede heryerde 

Borç takarsın doğmayan bebeğede 

Ne zormuş meğer milyonu beslemek 

Mılyar arı gibi çalışsın demek 

Alemin kazancı kesbi kasası 

Cebinde fonu bilmem ne borsası 

Sabahtan müreffeh abad edersin 

Akşama felceder berbad edersin 

Hem kan akıdır insaf hem soyarsın 

Hayber fesadınla heryerde varsın 

Akrepte zehiri bana yazıklar 

Maharet zanneden bayraktarım var 

Alemin tevessül etmediğini 

İşleyen kavimsin işlediğini 

Varmı işleyen kavim ey galata 

Kuşat alemi yayıl her tarafta 

Bir ucun londra paris atina 

Otur milletlerin karabahtına 

Yutarsın her devleti bütçesiyle 

Hanedanı hanı şehzadesiyle 

Yetmez iç harble kasdedersin cana 

Don biçersin hayber ta doğmayana 

Bilinmedik aşılmadık kalesin 

Her yerde galata sulu kulesin 

Ta karaköyden tohumu atarsın 

Geleceğe yön verir fal bakarın 

Uzanır soyun ta eski mısıra 

Eski yunan karaim yanısıra 

Küfret yetmiş iki millete çıt yok 

Adın demek suç fişlemeyen it yok 

Buçuk millet her milletin hayberi 

Bizim hayber köhne bizanstan beri 

Limanlardan gelir fuhuş fitnesiyle 

Her millte milletin kisvesiyle 

Adın başka olur nufusun başka 

Kılığa girer renk bulursun başka 

Bin yıl geçer akrep başkalaşmazsın 

Hayber nere gitsen fitneye başsın 

Nerde bir gülistan görsen bozarsın 

Bozar tahrib eder sahib çıkarsın 

Her rezalet değişmez fıtratına 

Uyar hayber tükürsem suratına 

Akrep gibi yavaşsın sabırlısın 

Kan içersin dünya ile hırlısın 

Becerin yok yarımsın karlısın 

Yılan gibi yer altında sırlısın 

Edep sanat yok zeka kusurlusun 

Fesandınla nasıl böyle zorlusun 

Olduğun yer kan kokar olur bizar 

Usanırdırır insan canından bezer 

Bozulacak bütün oyun alemde 

Bekle maya tuttu pek yakın hemde', 'Putu heykeli bizans kültürü  Zoraki çağdaş yolunu yürü  Deve yarışı tosbağa türü  Sırtında yük hörgücü bulunmaz  Niçin sokağa dikilmiş höyük...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":124,"source_url":"https://www.antoloji.com/heykel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cifitlar', 'cifitlar-atilhan-buyuksel-aktvp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak su dönme dolaplar 

Binbir tuzak kurar bize 

Kendi adin culun saklar 

Baska kimlik arar bize 

Acik dünyada gümrükler 

Yasak bizim gümrükte var 

Hilebazdır yalan söyler 

Gümrüklere örmüş duvar 

Japon Çinle ticareti 

Yasaklamis Türk tüccara 

Türke gümrük esareti 

Dönmeyi her yerde ara 

Kullanır dönme adımız 

Gider dünyada her yere 

Elindedir limanımız 

Esir etmis gitsek nere 

Istemez Türk kelte yakin 

Olsun ticaretin yapar 

Japon cine olsa akin 

Islenmedik suclu arar 

Kurusuna rüsvet alir 

Oyalayip yorar gec der 

Tazeye rüsvet yok kalir 

Kokar gümrükte yok eder 

Tuccarimi ticaretten 

Usandirir iflas eder 

Alimimi marifetten 

Suclu bulur ipe gider', 'Bak su dönme dolaplar  Binbir tuzak kurar bize  Kendi adin culun saklar  Baska kimlik arar bize  Acik dünyada gümrükler  Yasak bizim gümrükt...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cifitlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savcı', 'savci-atilhan-buyuksel-gdh9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu galatanın gizli hayali 

Sanma şamdanı haçı bulunmaz 

Suçlu aranır yağma vatana 

Sorun sırrını açı bulunmaz 

Bizans artığı yeremi battı 

Kanını bizim kanamı kattı 

Bitmedi Bizans pusuya yattı 

Sanma ayini Piçi bulunmaz 

Dönmeye olunca piç demek suç 

Anlamak zor olur söylemek güç 

İnzibatı eşek savcısı piç 

Bize bizden sorgucu bulunmaz 

Anadolumu baştan aşağa 

Soyup milleti yalın ayağa 

Mahkum eden sanki bayağa 

Şu galatanın suçu bulunmaz', 'Şu galatanın gizli hayali  Sanma şamdanı haçı bulunmaz  Suçlu aranır yağma vatana  Sorun sırrını açı bulunmaz  Bizans artığı yeremi battı  K...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/savci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firavun', 'firavun-atilhan-buyuksel-937ls', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah eder yoldaş neden böyleyiz 

Bizmi böyleyiz bizde bizmi var 

Laik çağdaşız hangi izdeyiz 

Yunandan izmi Türkten izmi var 

Çerkezin beyi mısırdan kovunca 

Fravun soyu kaçar yunana 

Bütün akdeniz sahil boyunca 

Piçlenir tohum saçar yunana 

Hamın Yafesin samın ilinde 

Farkı Yunandan muhtariyet var 

Gayri meşru doğum hiç birinde 

Olmaz saf nesepte ariyet var 

Aday fravun rahiplerinden 

Yazar çömleğe seçim olurdu 

Demokrasi mirastır o günden 

Fahuşdan sanat geçim olurdu 

Çıplak tanrılar fahişe idi 

Kısır değildi soyu olacak 

Bizans milleti böyle türedi 

Yayıldı sahile bucak bucak 

O gün atina kuruldu roma 

Nuh illerine baskın verdiler 

Akraba idi sapık sodoma 

Bütün bölgeyi kasıp gerdiler 

Bizim limanlar yunana yakın 

Elbet içimizde piçi olacak 

Bizde yunana biz deme sakın 

Fahuşa teşvik taçı olacak 

Türküz der gizli haçını takar 

Aslı Yunansa yunana benzer 

Türke benzemek zor gelir bakar 

Bizi yolumuzda gerici der ezer', 'Ah eder yoldaş neden böyleyiz  Bizmi böyleyiz bizde bizmi var  Laik çağdaşız hangi izdeyiz  Yunandan izmi Türkten izmi var  Çerkezin beyi mı...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/firavun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Economi', 'economi-atilhan-buyuksel-ivc3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu kasaplar bizi sayıp 

Sürüden koçu seçerse 

Ayak kalırışmış baş kayıp 

Öne ak koyun geçerse 

Başta olunca ak koyun 

Kasaba doğar bir güneş 

Öttür kavalı yap oyun 

Süt ucuz olur et beleş 

Bir geceliktir pul eder 

Mezata düşer paramız 

Akıllımız ak koyun der 

Sütü az verdi karamız 

Biri der sanat yok bizde 

Biri der tembel açımız 

Neden kasap içimizde 

Demez ne oldu koçumuz 

Şu kasaba kem bakanı 

Yaşatmayın içimizde 

Sürün mezbahaya kanı 

Helal olsun koçumuzda 

İftira at suçlu desin 

Beyazımız karamıza 

Hükmü cellatımız versin 

Bırakmayın aramıza', 'Şu kasaplar bizi sayıp  Sürüden koçu seçerse  Ayak kalırışmış baş kayıp  Öne ak koyun geçerse  Başta olunca ak koyun  Kasaba doğar bir güneş...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/economi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Argo', 'argo-atilhan-buyuksel-0glyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'argo demiş ya cıfıt diline 

eğip dilini büker yobazım 

bir yalağa geçirmiş eline 

konuşur teker teker yobazım 

ha harfini yutup eylemiş ka 

agopçayı öz türkçe sanır 

marifeti bu yobazın başka 

yok mahareti gururlanır 

t 

nolayın yobazım köylü kalaydın 

oğuz eline bekçi olaydın', 'argo demiş ya cıfıt diline  eğip dilini büker yobazım  bir yalağa geçirmiş eline  konuşur teker teker yobazım  ha harfini yutup eylemiş ka  ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/argo-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attim Okumu', 'attim-okumu-atilhan-buyuksel-cj6ao', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Attim okumu varsin hedefe 

Varmadi gitti uzaga dütü 

Cikmaz sokaktan kurtulmak icin 

Sürdüm atimi tuzaga düstü 

Vatan tutayim derken yuvada 

Vardi yolumuz iraga düstü 

Nevbahar idi ciktim yoluma 

Kara bahtima kiraga düstü 

Düstüm yüzüstü caresiz kalip 

Artik cikilmaz sokaga düstü 

Dönmeye mutlu türküm zamani 

Bize vatan dan firaga düstü 

Yasa cagdaslik ona bin öküz 

Cagdas türke bir buzaga düstü 

Elde muharref cagdas gecinip 

Bizim degismez bayaga düstü 

Liman boyunca sactilar tohum 

Soysuz bir nesil sokaga düstü 

Masum ananin yasli günüdür 

Nesep sormayan bir caga düstü 

Gitti ninnimiz geldi raksiniz 

Fravuna es bu caga düstü 

Eski seriat isterukcüler 

Devran dönünce ne yaga düstü 

Birdi yolumuz bine bölündük 

Kahin bir sola bir saga düstü 

Üclü pramit kible olunca 

Benim dörtgenim feraga düstü 

Akrepten zehir yutunca usta 

Vardi isi bir ciraga düstü', 'Attim okumu varsin hedefe  Varmadi gitti uzaga dütü  Cikmaz sokaktan kurtulmak icin  Sürdüm atimi tuzaga düstü  Vatan tutayim derken yuvada ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/attim-okumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dugun Su', 'dugun-su-atilhan-buyuksel-uxc4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Caglayip dere 

Durgun akan su 

Vardi bir yere 

Kurdular pusu 

Alip gideydim 

Akan gözyasim 

Neyidi neydim 

Agrimaz basim 

Yolda yorulmaz 

Gider bu izde 

Varir varilmaz 

Bu yolda bizde', 'Caglayip dere  Durgun akan su  Vardi bir yere  Kurdular pusu  Alip gideydim  Akan gözyasim  Neyidi neydim  Agrimaz basim  Yolda yorulmaz  Gi...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dugun-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönme', 'donme-atilhan-buyuksel-jcx6i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim dönme dolaplar 

Cagdaslik deyip durur 

Sanma kasti ilim fen 

Fuhus yap ye ic kudur 

Tohum almis anasi 

Disko kokteyl barda 

Dayim at demis katir 

Babasin sormuslarda 

Biliriz katir nesli 

Dayi belki at olur 

Fakat sorki babasin 

Soyu karma kat olur 

Sapiga hürriyet der 

Kasdi bilki kendine 

Soyu picin demisler 

Akil ermez fendine', 'Bizim dönme dolaplar  Cagdaslik deyip durur  Sanma kasti ilim fen  Fuhus yap ye ic kudur  Tohum almis anasi  Disko kokteyl barda  Dayim at d...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-atilhan-buyuksel-l2qx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayat kısa nefesmis 

gelip ardımı kesmiş 

tükendi günün diyen 

beni çağran bu sesmiş 

demek gençlik bir zaman 

anlık rüzgarmış esmiş 

başıma ak bulaştı 

yüzümden yollar aştı 

yürümez adımlarım 

diyar diyar dolaştı 

zaman terse dönmese 

Ayağa düşen baştı 

0 

doğdun işte yavrucuk 

ah bir doğsam diyordun 

sende bu acı aşı 

içmeyemi doğdun 

varmaz geçilmez yolları 

açmayamı doğdun 

anadan yardan hayattan 

geçmeyemi doğdun 

ve birgün hayattan 

kaçmayamı doğdun 

yözyaşını yollara 

saçmayamı doğdun 

yalan hayata değer 

biçmeyemi doğdun 

kervan gibi konup 

göçmeyemi doğdun 

yalan hayattan kesit 

seçmeyemi doğdun 

yoksa ektiğini hemen 

biçmeyemi doğdun 

yalan hayata 

hakkikat doğdun', 'hayat kısa nefesmis  gelip ardımı kesmiş  tükendi günün diyen  beni çağran bu sesmiş  demek gençlik bir zaman  anlık rüzgarmış esmiş  başıma...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/hayat-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümet', 'hukumet-atilhan-buyuksel-hpbu2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurdu morris süleyman kabineyi 

İcraat yok yalan çok yorumda var 

Unutmamış bir tamamdır herşeyi 

Mason kabinede cıfıt rumda var 

Kütüğünde yarım dini tam oldu 

Oldu kızıl mason geldi gam oldu 

Ad değişti gavurköy islam oldu 

Unuttuk neslini geldi yama oldu 

Arı ol çalış kar yok zararsa var 

Kuyruk var millet bela ararsa var 

Tüzük yasa var kanun kararsa var 

Banka tefe repo faiz borsa var 

Uğur kalkdı deprem yangın selde var 

İlim teknik bizde yok o elde var 

Komedya var zevk sefa her telde var 

Fikre sansür ağır bir bedelde var 

Şeker yok elektirik yok zamsa var 

İş yok aş bulunmaz hüzün gamsa var 

Kan sokakta var içen yamyamsa var 

Gulu gulu tansımız tam tamsa var 

Ayı gibi oynatan çingene var 

Dönme hükümette kat kat gene var 

Milletin sırtında bizans kene var 

Kurtulmak cıfıttan bin bin sene var 

Keçi kanı içen sapık loca var 

Laik fetva veren pontus hoca var 

Çağdaş yollu kadın meçhul koca var 

Söndürülmüş ocak tütmez baca var 

Fravun soyundan inme tayfa var 

Mason loca gizli sinme tayfa var 

Treversti lezbi dönme tayfa var 

Cıfıt basın çıplak kadın sayfa var 

Şu hayberin yeraltı kasası var 

Gizli cematı var yarasası var 

Yasamızdan ayrlır yasası var 

Olsa bir sevincimiz tasası var 

Şeytana tapınan çağdaşımız var 

Dolaksız soyundan bir başımız var 

Felaket içinde gözyaşımız var 

İşgence var zehirden aşımız var', 'Kurdu morris süleyman kabineyi  İcraat yok yalan çok yorumda var  Unutmamış bir tamamdır herşeyi  Mason kabinede cıfıt rumda var  Kütüğünde ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hukumet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Put', 'put-atilhan-buyuksel-0pb5k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekinir putuna açıktan tapmaya 

Bir ismi şifreler tapar kopt azınlık 

Olur meyilli içgüdüsü sapmaya 

Soyutur putunu yapar kop azınlık 

Adalardan fuhuşu sürer putunu 

Saf inancımı irdeler kopt azınlık 

Sapık yolunu iç güdüsü kutunu 

Satar millete şifreler kopt azınlık 

Nesebten nesebe kabilden bu yana 

Sapık meşaleyi yakar kopt azınlık 

Musadan eski sihir büğü yalana 

Ehrama yönelir bakar kopt azınlık', 'Çekinir putuna açıktan tapmaya  Bir ismi şifreler tapar kopt azınlık  Olur meyilli içgüdüsü sapmaya  Soyutur putunu yapar kop azınlık  Adala...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/put-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-atilhan-buyuksel-aosvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ey yolcu bu yola bizde böyle kimsesiz 

bu at üstünde kimsesiz gidecekmiyiz 

inanmadan bilmeden ve sesiz çaresiz 

ölüm ipini kendimizçekecekmiyiz 

ey yolcu yorulacakmı bu bedenimiz 

o gün gidiş merasimi kurulacakmı 

sorulacakmı millet nasıl bilirdiniz 

vardığımız yer ıssız kabirmi kucakmı 

ıssız bir kabirmi sıcak bir kucakmı', 'ey yolcu bu yola bizde böyle kimsesiz  bu at üstünde kimsesiz gidecekmiyiz  inanmadan bilmeden ve sesiz çaresiz  ölüm ipini kendimizçekecekm...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yolcu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dere', 'dere-atilhan-buyuksel-pmr20', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siril siril akar caglayip dere 

Dönülmez yollara düstü bir kere 

Sana durakmıdır o vardigin yer 

Benim yolumsa sonsuza gider 

Alip gider yolun bir deniz senin 

Varmiydi silada bir bekleyenin 

Yoksa benim gibi garipmi kaldin 

Bu yollara düsüp cikmaza daldin 

Icinden akan sel göz yasinmidir 

Öyleyse yirtinip aglayip cildir 

Ararsin demek sen derdine ortak 

Yollara düsüp cagir aglayarak 

Sanami yazildi karali yazi 

Bende unutmusum bahari yazi', 'Siril siril akar caglayip dere  Dönülmez yollara düstü bir kere  Sana durakmıdır o vardigin yer  Benim yolumsa sonsuza gider  Alip gider yol...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dere-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-atilhan-buyuksel-s8hlo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tarih ikibine bir kala 

Yer yarıldı çöktü marmara 

Bitmemişti toplanmış hala 

Limanda keşişler bir ara 

İhtilallle bizans hayali 

Kurdular kadehler şerefe 

Kalktıda inmedi bu hali 

Gören Rabbım vurdu hedefe 

Musanın fravuna intikamıdır 

Beddua ile yere batacak 

Zalimin zulmü bekamıdır 

Mazlumun ahını yerde tutacak', 'Tarih ikibine bir kala  Yer yarıldı çöktü marmara  Bitmemişti toplanmış hala  Limanda keşişler bir ara  İhtilallle bizans hayali  Kurdular k...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deprem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devir Değişti', 'devir-degisti-atilhan-buyuksel-jmxgb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Su kahin basa gecti geceli 

Devir degisti zaman degisti 

Kahbece vurur bizi arkadan 

Cizvit alcaklik yaman degisti 

Kimisi insafi terkedip düstü 

Sürü basina itler üsüstü 

El öpmeninde gecti zamani 

Öper ayagi zaman degisti 

Gizli ihtilal olmus megerse 

Gül bahcesinden bülbül giderse 

Karga gelirmis gak gak diyerek 

Hüküm degisti ferman degisti 

Bak su .yd...cagdas gecinir. 

Ayaga düserde bas gecinir 

Fuhusa tesvik verir liyakat 

Bu toprakta edep san degisti 

Aglarim hale batti günesim 

Belki son dogusum son gelisim 

Cigner vatani domuz sürüsü 

Günes dogmadiysa tan degisti 

Coban olunca kahin sürüye 

Secip koclari kaldi geriye 

Kendini koctur bilen koyunlar 

Damarda dolasan kan degisti', 'Su kahin basa gecti geceli  Devir degisti zaman degisti  Kahbece vurur bizi arkadan  Cizvit alcaklik yaman degisti  Kimisi insafi terkedip d...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/devir-degisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktım', 'biraktim-atilhan-buyuksel-hrcx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıraktım sarayı bulunca postu 

Yeren yersin halim taan,a bıraktım 

Yaranı eşi iyalimi dostu 

Yalnız bıraktığı an,a bıraktım 

Her türlü derde alıştım cefaya 

Zevki sefayı bir yana bıraktım 

Ağyanı bıraktım boşverip saya 

Bütün lezzetleri naan,a bıraktım 

Her gelen gider bir gidişki baktım 

Olacak şeyi zamana bıraktım 

Kalırmış burada baktımki tahtım 

Dünya tahtını virana bıraktım', 'Bıraktım sarayı bulunca postu  Yeren yersin halim taan,a bıraktım  Yaranı eşi iyalimi dostu  Yalnız bıraktığı an,a bıraktım  Her türlü derde...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-atilhan-buyuksel-0tekd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kac yil oldu gün 

Dogar gün batar 

Bilip derdimi 

Sustunuz daglar 

Bilirsiniz bir 

Ip ucu verin 

Sirtimdaki su 

Gami devirin 

Üstümdeki dert 

Tasinmaz agir 

Konustugum bu 

Adamlar sagir 

Konusmayarak 

Dillerim durdu 

Daglar akillandi 

Insan kudurdu', 'Kac yil oldu gün  Dogar gün batar  Bilip derdimi  Sustunuz daglar  Bilirsiniz bir  Ip ucu verin  Sirtimdaki su  Gami devirin  Üstümdeki dert...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daglar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlik Geceler', 'karanlik-geceler-atilhan-buyuksel-s3ped', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlik geceler 

Bir uctan bir uca 

Yoklugu heceler 

Dünyanın burası 

Ne köydür ne şehir 

Issiz cöl ortasi 

Yalnizim kimsesiz 

Issiz bir evdeyim 

Ve cöl gibi sessiz 

Ben burada bekci 

Ne in ne cin gelir 

Birde gölgem elci', 'Karanlik geceler  Bir uctan bir uca  Yoklugu heceler  Dünyanın burası  Ne köydür ne şehir  Issiz cöl ortasi  Yalnizim kimsesiz  Issiz bir ev...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanlik-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Gece', 'sessiz-gece-atilhan-buyuksel-aq9fi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenın sessizligi 

Yine çöktü içime 

Başımı alıp gitsem 

Hangii diyara kime 

Zebun oldum çaresiz 

Çığlık atsam duyulmaz 

Yer yarılıp kimsesiz 

Yere batsam duyulmaz', 'Gecenın sessizligi  Yine çöktü içime  Başımı alıp gitsem  Hangii diyara kime  Zebun oldum çaresiz  Çığlık atsam duyulmaz  Yer yarılıp kimses...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessiz-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeyiniz', 'yeyiniz-atilhan-buyuksel-l6kqw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizansa şehir deyip 

Bize taşra deyiniz 

Biz çalıştık siz yeyip 

Vatan bizim neyimiz 

Siz oğlu galatanın 

Biz göçer yayladanız 

Sizler dönme atanın 

Biz yörük babadanız 

Hakkı on yer biriniz 

Bir fazla onumuza 

Onu taşır birimiz 

Bir yük çok onunuza 

Üveyi öz babanın 

Doğmuşuz bu toprağa 

Yükü bize sabanın 

Başımıza siz ağa', 'Bizansa şehir deyip  Bize taşra deyiniz  Biz çalıştık siz yeyip  Vatan bizim neyimiz  Siz oğlu galatanın  Biz göçer yayladanız  Sizler dönme...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeyiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat', 'cellat-atilhan-buyuksel-xhs0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vardır suçu asın diyen itoğlu 

Devir suçlununda itin değilmi 

Mahkemeye varsın diyen itoğlu 

Hakimim cellada teslim değilmi 

Alınıp Fravnun mumyadan hücre 

Babalık tesbiti yapılmadıkça 

Olsada nufusu bucada kaydı 

Celledın piç soyu meçhul değilmi', 'Vardır suçu asın diyen itoğlu  Devir suçlununda itin değilmi  Mahkemeye varsın diyen itoğlu  Hakimim cellada teslim değilmi  Alınıp Fravnun ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cellat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Bakalım', 'bil-bakalim-atilhan-buyuksel-46ig1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dedi bil bakalim angisi onca 

Umurtami oksa taukmu onca 

Dedim yumurtadan hep kuşmu çıkar 

Kümesin içine yılan sokunca 

Dedi boluculuk iapiyon cene 

Istersen soralum celip geçene 

Dedim horoz döğüştürebilene 

Haydi birde yılan döğüstürsene', 'Dedi bil bakalim angisi onca  Umurtami oksa taukmu onca  Dedim yumurtadan hep kuşmu çıkar  Kümesin içine yılan sokunca  Dedi boluculuk iapiy...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bil-bakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekilin', 'cekilin-atilhan-buyuksel-m0fig', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sizsiniz kardeşim bütün suçlu sizsiniz 

Kiminiz suçlu hayatı berbat kimimiz 

Bir kemik attı köhne bizans yalamaya 

Bir kemiğe bin yıl ardısıra gittiniz 

Vatana hizmet adına hiç usanmadan 

O kamçıladı kağnısını siz ittiniz 

Üç kuruşa kiminiz asker polissiniz 

Sayenizde ayakta kaldı dirilttiniz 

Bir suç bulursa gizli devlet birimize 

Vatan sever siz alkışlayan birliksiniz 

Siz kardeşim kiminiz siyasetçisiniz 

Kiminiz yazar çizer hukukçu kiminiz 

Bize hoşgörüsüz seyyadı bi insafın 

Avına karşı giden tazı gibisiniz 

Vatan kurtaran siz her akıllı adamı 

İftira atıp vatana hain ettiniz 

Bizansın her astığına alkış tuttunuz 

Ya siz kırık dökük paramparça idiniz 

Yarar adam bertaraf olur ayakta siz 

Kiminiz futbolcu sağcı solcu kiminiz 

Bu kadar faili meçhule kurban gider 

Ne hikmetdir yetmişinci yılı bittiniz 

Anlayın artık şunu itiraf edinki 

Ölenden farkınız ahmaklık marifetiniz 

Değirmen gibi adam öğütür şu düzen 

Ya halbur altı siz yetmiş kez seçildiniz 

Kıyasmı gerek dünya nerde nerdeyiz biz 

Çekilin yetti çağdaş olma hikayeniz', 'Sizsiniz kardeşim bütün suçlu sizsiniz  Kiminiz suçlu hayatı berbat kimimiz  Bir kemik attı köhne bizans yalamaya  Bir kemiğe bin yıl ardısı...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cekilin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çark', 'cark-atilhan-buyuksel-c4uix', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Feleğin şu çarkı terse dönerse 

Yorulmaz bedenin yorulur bir gün 

El tutmaz ayak yürümez olur 

Gelip musallaya konulur bir gün 

Usanır geçersin fani hayattan 

Beyninde sorular sorulur bir gün 

Ölüm şerbetiden bir tas içersin 

Dönüş merasimi kurulur bir gün', 'Feleğin şu çarkı terse dönerse  Yorulmaz bedenin yorulur bir gün  El tutmaz ayak yürümez olur  Gelip musallaya konulur bir gün  Usanır geçer...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cark-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caddeler', 'caddeler-atilhan-buyuksel-uf3pr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ömür boyu adımlarım 

yine bitmez bu caddeler 

yorgun düştü adımlarım 

oldu gün tez bu caddeler 

şu ömrüm tükendi azmı 

erişti güz bu caddeler 

Gizemlerin bulunmazmı 

Niçin örmez bu caddeler 

Kiminin göğe erdi başı 

kimine az bu caddeler 

Kimi donar yoktur aşı 

kimine yaz bu caddeler', 'ömür boyu adımlarım  yine bitmez bu caddeler  yorgun düştü adımlarım  oldu gün tez bu caddeler  şu ömrüm tükendi azmı  erişti güz bu caddele...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caddeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizans', 'bizans-atilhan-buyuksel-4ugdc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi ite itide ite boğduran bizans 

Üstüne varanı vatan vatan koğduran bizans 

Malazgirtte onu içimizde eridi sandık 

Köhne Bizansın kirli davadan usandık 

Yılan gibi tohumu atar kuş yuvasına 

Yavrusu zehir verir yavrunun en hasına 

Yavru yılanı biz sanıp biz diye sarılan 

Bizim yavruya desemki bu yavru yılan 

Bizden it bulur üstüme bütün gücüyle 

Gelir eski kini tükenmeyen öcüyle 

Bir yalağa bizi ite sesziz kırdırır 

Tutar ite itide bedelsiz kırdırır 

Kimi ülküdaş kimi vatansever vatandaş 

Bizimsin ne diyem hain diyemem gardaş 

Beddua edemem koyun gibi güdülüsün 

Koçları seçilmiş darma dağanık sürüsün 

Rum oyununa kafan kuma gömülüsün 

Kasabın ardısıra yığın yığın yürüsün 

Koyunum bize hain dedin hamasetinle 

Ruma rum diyemedin başındaki itinle 

Bin yol bulsa galatalı bin yola gidersin 

Bir yol göstereni tazı gibi ezersin 

Bozdular dilim tutuk derdimi anlatamam 

Bende edemem tam taptırır bizans bir tamam 

Kime gomonos dedi kimine mürrteci 

O değil bu değil kardeşim sor şu rum neci 

Çevirdi dilimi galatanın agopçaya 

Benzetir dinimi sapık dini ortadokçaya 

Bizans başka yol bulur yolun sonu gelmeden 

Sen sağa ben sola başka yoldan gitti deden 

Bir o sokağa döner bu sokağa çevirir 

Yolu unutturur şaşırtır dağa çevirir 

Yolu yoktu babanın şaşkın şaşkın gezerdi 

Yolunu kaybettirirdi bizans hem ezerdi 

Uyursan beni sola seni sağa götürür 

Yazık değilmi torunununu dağa götürür 

Hazır kardeşim torunun torununa yol 

Bitmez sapık yolu bizansın her sorana yol 

Bize bölücü diyen bine böldü yolumu 

Düşman etti kardeşi tutmaz etti kolumu 

Uyanda kardeşim avcıya bir haykırsana 

Soyup yurdunu her sokağa tuzak kurana', 'Bizi ite itide ite boğduran bizans  Üstüne varanı vatan vatan koğduran bizans  Malazgirtte onu içimizde eridi sandık  Köhne Bizansın kirli d...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bizans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Topraklarda', 'bu-topraklarda-atilhan-buyuksel-zhug9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu topraklarda mukaddes kanin 

Sel gibi akip karistigi yer 

Bayrakta yildiz ile hilalin 

Kana boyanip bulustugu yer 

Isleyip naksin gök kubbelerde 

Kani ile yazdigi sanli tarih 

Asim nesli tekbir namelerde 

Yek vucut olup yaristigi yer 

Migferin okun kilicin yayin 

Tekbir sesleriyle kükreyen 

Göklerde yükselen hilalin ayin 

Yerde ses verip tanistigi yer', 'Bu topraklarda mukaddes kanin  Sel gibi akip karistigi yer  Bayrakta yildiz ile hilalin  Kana boyanip bulustugu yer  Isleyip naksin gök kubb...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-topraklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burkulur', 'burkulur-atilhan-buyuksel-9i5qg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatta bilip 

Gördüklerimi 

Söylemek icin 

Kelime gerek 

Dil durup kalem 

Kurur derdimi 

Yazip cizmeyip 

Söylemeyerek', 'Hayatta bilip  Gördüklerimi  Söylemek icin  Kelime gerek  Dil durup kalem  Kurur derdimi  Yazip cizmeyip  Söylemeyerek...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/burkulur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbülüm', 'bulbulum-atilhan-buyuksel-5vhgu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahu figan eden bülbülüm 

Sizde derdi cefadan ne var 

Icin dökersin beyhude 

Aglarsin ben gibi ahu zar 

Ne gül sana derman olur 

Ne derman bana derman 

Gün olur yazilir basa 

Gecilmez gidilmez ferman', 'Ahu figan eden bülbülüm  Sizde derdi cefadan ne var  Icin dökersin beyhude  Aglarsin ben gibi ahu zar  Ne gül sana derman olur  Ne derman ba...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulbulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna', 'bosuna-atilhan-buyuksel-uat7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dolu dolu sandım tükendi vaktım 

yürü yürü çabuk koşta boşuna 

kasam dolsun dedim buyudu ahtım 

doluda boşuna boşta boşuna 

akıl hesap kitap tıkandı baktım 

ağarmış ne saçlar başta boşuna 

şu hayat boşuna yanarmış yaktım 

kuruda boşuna yaşta boşuna 

yazılmış kaderde yıkılsa tahtım 

beklemek boşuna kaçta boşuna 

bütün lezzetleri geçtim bıraktım 

ölümlü şu başta taçta boşuna', 'dolu dolu sandım tükendi vaktım  yürü yürü çabuk koşta boşuna  kasam dolsun dedim buyudu ahtım  doluda boşuna boşta boşuna  akıl hesap kitap...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bosuna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Devlet', 'derin-devlet-atilhan-buyuksel-lb3nz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derin devlet dedikleri 

Yaşar gizli yerde Bizans 

Şanlı mazi şanlı tarih 

Unutturdun nerde Bizans 

Kurşun atıp vurdukların 

Hile tuzak kurduklarn 

Akıllıyı yordukların 

Yetmez kan dökerde Bizans 

Gizlenip pusuda yatar 

Fitne tohumunu atar 

Türke tüklük çaka satar 

Müslümanım derde Bizans 

Soyu meçhul baştakinin 

Gizli rahip gizli dinin 

Kütüğünde başkahinin 

Bizim nüfus perde Bizans 

Bizde inanmıştık nice 

Düzeni kurmuşlar ince 

Kendi kanın tükenince 

Kanımız içerde Bizans 

Acik cami acik imam 

Gizli havra gizli haham 

Neden gizlidir soramam 

Yasak der gülerde Bizans 

Bu gizlilik neden ola 

Soyun nesebin sorula 

Fravundan hücre ala 

Kökü gizli yerde Bizans 

Yasatmislar icimizde 

Meyhanede Picimizde 

Sorulmayip gecimizde 

Akla gelmez nerde Bizans 

Kohen kahin keheneti 

Gizli devlet melaneti 

Kohne Bizans ihaneti 

Her zaman siperde Bizans 

Dini baska derin gücün 

Soyu türkmü dönme picin 

Soyar bizi yetmez öcün 

Kirar bizi birde Bizans 

Reha halman kohen asen 

Hani cagdas idin ya sen 

Bu isimler hangi dilden 

Söylemez gizlerde Bizans 

Güder bizi gizli kuvvet 

Kökü eski derin devlet 

Fetih fatih vekil millet 

Sandik secim nerde Bizans 

Akillimiz gider yolcu 

Birde bölüp sagci solcu 

Kirdirinca kalan golcu 

Ahmagin güderde Bizans 

Vurup soysuz ceylanimi 

Mayasiz edip kanimi 

Yiyen kahin imamimi 

Gericidir derde Bizans 

Bir cuvala koymus bizi 

Faiz tefe soymus bizi 

Basin yayin sesimizi 

Medya der keserde Bizans 

Ciplak heykel ciplak kültür 

Kültür gizli dinin sürdür 

Kerhane fal sihir üfür 

Kültür der süslerde Bizans', 'Derin devlet dedikleri  Yaşar gizli yerde Bizans  Şanlı mazi şanlı tarih  Unutturdun nerde Bizans  Kurşun atıp vurdukların  Hile tuzak kurdu...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/derin-devlet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazan', 'kazan-atilhan-buyuksel-l0t60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıfırdan başla günü gününce 

Gününü saymak demek ölümmüş 

Ocakta siyah kazan görünce 

Dedimki eyvah bu son günümmüş 

Unut her şeyi göçün başladı 

Atın hazır oldu bu son yolun 

Nerde yaylayıp nerde kışladı 

Turtmaz ayağın yetişmez kolun 

Bir cisim kesildin konuş dilim 

Kaldır ayağım kırmaş be kolum 

Ruhun vardığı yere gidelim 

Sürün atımı değişsin yolum', 'Sıfırdan başla günü gününce  Gününü saymak demek ölümmüş  Ocakta siyah kazan görünce  Dedimki eyvah bu son günümmüş  Unut her şeyi göçün baş...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kederim', 'kederim-atilhan-buyuksel-3knov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne senden uzakta ben 

Ne sen benden uzakta 

Hangi yola gidersen 

Geleceğim kaderim 

Eksende saçıma ak 

Sen beni unutma bak 

Senden ayrı olacak 

Kuvvetimmi var benim 

Kıvrışık yollar açsan 

Elim yüzüm çizerek 

Ulaşılmaz araçsan 

Uçar burakım derim', 'Ne senden uzakta ben  Ne sen benden uzakta  Hangi yola gidersen  Geleceğim kaderim  Eksende saçıma ak  Sen beni unutma bak  Senden ayrı olac...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi Ve Köpek', 'kedi-ve-kopek-atilhan-buyuksel-tda44', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köpek derki: kedi 

Sen ne yobazsin 

Sakladin herseyi 

Bu cagda yok fakat 

Hangi cagda varsin 

Ah demek sen 

Mürteci belli 

Sokaklar niçin 

Gidip vazifeni 

Evde yaparsin 

Kedi derki hani 

Bu hürriyetmidir 

Sen sokakta yap 

Bende böyledir 

Birak böyle kalsin 

Köpek derki bak 

Hürriyet dedik ya 

Dogrudur fakat 

Biraz kaçamak 

Nicin böyle yaparsin 

Sokakta acmak 

Hürriyet bence 

Utanmak dedin 

Yüzün dönünce 

Hangi caga bakarsin', 'Köpek derki: kedi  Sen ne yobazsin  Sakladin herseyi  Bu cagda yok fakat  Hangi cagda varsin  Ah demek sen  Mürteci belli  Sokaklar niçin  G...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kedi-ve-kopek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Yobaz', 'kim-yobaz-atilhan-buyuksel-iig0f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bunca asikar bunca gizlinin 

Ilmini bilip sezmis degilim 

Ne seyyah olmuşum şu alemin 

Sırrına erip gezmis degilim 

Bunca zehirin bunca yilanin 

Tefeci defiyle bizi soyanin 

Yilan gözlünün zehir ciyanin 

Üstüne varip ezmis degilim 

Geni degisik ceni degisik 

Kani degisik teni degisik 

Kimya fizigi feni degisik 

Ayridir deyip sezmis degilim 

Kandirip bizden isim devsiren 

Saklar culunu culuma giren 

Yilana bak horoz dögüstüren 

Tiksinip yine tezmis degilim 

Ah su yd.....böyle igreti 

Bozar barisi iyi niyeti 

Yalan yanlisi sahte ögreti 

Misliyle deyi azmis degilim 

Sermaya katlar kita kundaklar 

Sucsuzu asip sucluyu aklar 

Hürriyet deyip kitap yasaklar 

Yine barisi bozmus degilim 

Agzi salyali kusmugu yerde 

Bilimi fenni teknigi nerde 

Füzeyi yapip aya giderde 

Tutup yolunu kazmis degilim 

Giden senmisin aya uzaya 

Kalan benmiyim yürüyen yaya 

Fareden ilac domuzdan maya 

Söyleyip cizip yazmis degilim 

Yd. yasa türk gibi görün 

Türkün adina culuna bürün 

Sanmaki bu is derdi bugünün 

Degil asirlar sormus degilim 

Kundakla gelip saraya sızmış 

Akıllıyı boğup araya sızmış 

Höşgörü deyip azdıkça azmış 

Tahammülüm hoş görmüş değilim', 'Bunca asikar bunca gizlinin  Ilmini bilip sezmis degilim  Ne seyyah olmuşum şu alemin  Sırrına erip gezmis degilim  Bunca zehirin bunca yila...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kim-yobaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırca', 'kirca-atilhan-buyuksel-esyzp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ruma gelin vermiş kerimesini 

Yunandan getirmiş tazecik saf kanı 

Laik çağdaş devletimin sesini 

Duyuran hariciye sabık bakanı 

Ne olur rumdan bize damad olunca 

Rumdan doğar bir torun türkten ad olur 

Hakkıyla temsil eder bizi kanımca 

Yükselir alemde adımız yad olur 

Aferin sana laik vatansever kız 

Geldi damızlık el attı sorunuma 

Dedesi vezirimdi torun kırcamız 

Veliahtı bakan olsun torunuma 

Gelir taze bir kan mutluyum kızılmaz 

Bize rumdan diplamat lazım değilmi 

Şahin olur düşmana kuyum kazılmaz 

Alıştırdı yobazı hazım değilmi 

Olsun üç beş gerici bassın fakayı 

Çağdaş laik yolumuz geri dönülmez 

Hakkımız yok egede iki yakayı 

Bölmeye bu vatanı zaten bölünmez 

Bizim halkçı çağdaş laik seçkinimiz 

Yakındı ta eskiden anavatana 

Danışıklı dövüştürdü geçkinimiz 

Kanı kattı gencimiz yunanistana 

Bakanım kanını katmışsa yunana 

Çağdaş laik fakat otadoks rummudur 

Milletin sırrını satmışsa yunana 

Hariciyeme yeni rum sorunmudur 

Bakmayın yüz vezirin doksan dokuzu 

Çağdaş azınlıktan geçer başımıza 

Perde gerisi olur hokus pokusu 

İyisinden bela seçer başımıza 

Önde başka oynatır başka arkası 

Bakanın rum olunca tuzak kurulur 

Gelmez biraraya iki yakası 

Her plan bu milletten uzak kurulur 

Ortadoks rum demişsin günah kardeşim 

İftira ettin vah kardeşim bakana 

Demişsin bizim koçta rum ah kardeşim 

Dil uzattın vatansever manukyana', 'Bir ruma gelin vermiş kerimesini  Yunandan getirmiş tazecik saf kanı  Laik çağdaş devletimin sesini  Duyuran hariciye sabık bakanı  Ne olur ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kirca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandim', 'usandim-atilhan-buyuksel-ns1i5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usandim felek gami kederden 

Gül diyecek bir gün bahtim yokmu 

Yokmu azad eden şu gönlümü 

Tutuştu çereğa yaktım yokmu 

Yokmu cira karanlik gönlüme 

Yaksinda bir gül desin güleyim 

Hür olayimda gitsem ölüme 

Güleyimde öl desin öleyim', 'Usandim felek gami kederden  Gül diyecek bir gün bahtim yokmu  Yokmu azad eden şu gönlümü  Tutuştu çereğa yaktım yokmu  Yokmu cira karanlik ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/usandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fetih', 'fetih-atilhan-buyuksel-vhblm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cemaat bulunmuş rum keşişler 

Kostantiniyyenin iftitahında 

Girdi duvara yitti demişler 

Görünmüş müslüman külahında 

boşalttılar kardeşim boşalttılar 

hazinenin içini boşalttılar 

yetmez deyip cebini boşalttılar 

hem beynin içini boşalttılar 

içini boşalttılar dışını boşalttılar 

düşünmesin sormasın deyip 

tuttu beyninin içini boşallttılar 

kuşattılar kardeşim kuşattılar 

evini işini aşını kuşattılar 

ekmeğe muhtaç edip 

ovanı dağını taşını kuşattılar 

taş attılar kardeşim taş attıar 

tutup mukaddesine taş attılar 

nesilleri olmaza sürükleyip 

tarih adresine taş attılar', 'Cemaat bulunmuş rum keşişler  Kostantiniyyenin iftitahında  Girdi duvara yitti demişler  Görünmüş müslüman külahında  boşalttılar kardeşim b...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/fetih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laht', 'laht-atilhan-buyuksel-h62mn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alırlar bedenim bir taş üstüne 

Konup uzatılır ister istemez 

Istersen dövün ister baş üstüne 

Malını mülkünü hep ver istemez 

Bu yolda arkdaş olan bulunmaz 

Bekleyim desende bir an bulanmaz 

Halini vaktini soran bulunmaz 

Bir metre toprak başka yer istemez', 'Alırlar bedenim bir taş üstüne  Konup uzatılır ister istemez  Istersen dövün ister baş üstüne  Malını mülkünü hep ver istemez  Bu yolda arkd...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/laht-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laik Soru', 'laik-soru-atilhan-buyuksel-e6nad', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Laik soru sorsam laık cevap gelirmi 

Zehir yoksa ya iftira ya sus denirmi 

Şu gerici osmanlının her on veziri 

Üçü cıfıttı dördü dönme rumdu biri 

Bazan yörükten bize türk olurdu paşa 

Ya zehirlenir ya bela alırdı başa 

Rum vezir efendim hünkar ciğer köşeniz 

Derdi hain imiş sattı sizi paşanız 

Vatan selameti için asmak gerektir 

Acımayın hünkar demek aslan yürektir 

İftira yer yörük paşa ipe giderdi 

Suçlu bilirdi kendini bilmezdi derdi 

Uzat başı kurtulacak türkün devleti 

Görünmezdi kan kusturan dönme illeti 

Böyle idi saray devlet devlet içinde 

Başı biz ip yahudinin dönme piçinde 

Ağ gibi örülmüş kolları yahudi rum 

Bize kan kusturan ahtapot gizli kurum 

Ya şu laik devletin hiç yokmu içinde 

Yoksa gayretmi yok cıfıt dönme piçinde 

Cıfıt yokmu sızsın devlete türk kan kusa 

Kısırmı soyu yokmu dönme cıfıt yoksa 

Sızsın ta oba oba sızsın bucak bucak 

Her köşeye tohum atsın sönsün her ocak 

Padişahı halleden varya dönme guruh 

O gün gazinin ardına sığındılar yuh 

Onuda kullanıp zehir verdiler yine 

Sanma ne ona dostturlar ne obirkine 

Dönme guruh ismetle kuşattı gaziyi 

Atiyi kuşatıp yokettiler maziyi 

Akrep basamakları ağır ağır çıkar 

Beş asır hedefte ne usanır ne bıkar 

Bir asırda onu zıddı gösterir bunun 

İkinci asır düşmanı savunduğunun 

Üçüncü asır yol yakındır hedefine 

Hafızai beşer biz o usanmaz yine 

Dördüncü asırda çepeçevre kuşatır 

Beşinci asırda sefaleti yaşatır 

Ve o gün kaleleri yıkar birer birer 

Katliam olur ne kadın kalır ne bir er 

Hayberde iz kaybedersin gelir siirtten 

Payitahtta ıspanya selanik giritten 

Akreb bir kavimsin kini bin yıl sürüktür 

İz kaybeden bir milletin derdi büyüktür 

Nasıl bilmece bu tiyatroyu kim çöze 

Alim yok nesep kim bilir iner kim öze 

Oba oba kuşatılmışız liman liman 

Nerde Eyub Timurhan kalksın bu sis duman 

Hastahanede nesli felceder sızınca 

Basınla kan döker yalan haber yazınca 

Hariciye bize iranlı düşman bulur 

Dünya dışında karanlık alem kurulur 

Adliye düşmanı astığı alimlerin 

Brokrasi odağı karanlık işlerin 

Cıfıtla yaşamın bu kardeşim bedeli 

Geri bıraktılar nesli ifsat edeli 

Heleki olmaz pontus hocayla bu işler 

Haldunla açılsın gizli yollar keşifler 

Yol göstirir timura yıkar tüm burçları 

Fravunun içimizde hain uçları 

Gizler çehre dönme en asil türk edası 

Millet susturan medya cıfıt gür sedası 

Ele geçirmiş gizli devlet kurumları 

Bizans azınlığı dönme cıfıt rumları 

Açılmaz bir kapı dur diyecek gidişe 

Der cıfıt kirve ihtisas gerek bu işe 

Burokrasi emanettir cıfıt dönmeye 

Milletim asırlar rahat yüzü görmeye 

Dilimizi ar eyler verin galataya 

Bu arabcadır o farsca dil kurtulur guya 

Camion kirko kasa gelsin masa 

Gitsin meşreb mahkum olsun tasa 

Bunlar hangi çağdaş milletin dili 

Geldi galatadan öz türkçemiz gideli 

Portekizden geldi bizden türk şu dönmeler 

Araba farsa yuh yahudiye övmeler 

Atalım arabcayı farsacayı ya Türkce 

Demek ari oldu galatadan gelince 

Öz Türkce diyen galata ehli oldu dilimin 

Meğer ne gündür merkezi imiş bilimin 

Yol gösterdin fersah fersah ileri 

Gitmişizde bak şu dünya pek geri 

Gönlümüz hoş türkümüz musiki olalı 

Bildik onuda sulukleye soralı 

Sulukule yaşa galata sen olmasan 

Böyle güllük gülistan olurmu vatan 

İssizi yok aç sefil ne gezer bu ülkede 

Bir tamamsın bizans galatada sulukulede 

Yahudi ermeni rumunla bir tamamsın 

Bizans birin milyonu güder pek yamansın 

Boş hastahaneler oldu herkes müştefi 

Tarafınızca yapıldı uzayın keşfi 

Doğum uzmanı doktor erkek ebelerin 

Göstergesi değilmi çağdaş hedeflerin 

Pek çağdaşsınız galata pek gericiyiz 

Siz uzayı keşfetmişken ya biz neciyiz 

Bu marifet senin bizans sanırdık mevta 

Türkü uyur çerkezi boştur kürdü softa 

Sen olmasaydın geri kalırdık yarışta 

Geçtik alemi huzur refahta barışta 

Ne faili meçhul ne anarşi bulunur 

Irz emniyette mal korunur can korunur 

Diplomatın brokratın hıpokratın var 

Seçtin bizden vitrine senin yeraltın var 

Pofpoflayıp bizans ahmağı getir başa 

Ateş sen olmuşsun bizden bulursun maşa 

Bizans bin yıl olsa sırrını açmaz yine 

Gizli devlet varılmaz gizli kütüğüne 

Çekik göz japon almanın keltin öncüsü 

Bizans hatta tüm alemde keşfin öncüsü 

İlminle ışık saçtında gidildi aya 

Yeni kıta sensiz nasıl gider uzaya 

Egenin o bir yanı kardeşimiz yunan 

İstila etmişti vatanı arabistan 

Yardım etti yunan kurtulduk istiladan 

Arabtan irandan binbir türlü beladan 

Şaha kalktın galata gizlisi kalmadı 

Köhne bizans köhne davadan usanmadı 

Kuruldumu köhne bizans işler tersine 

Arı gibi çalış millet aç sefil yine 

Böyledir bu memleketin mahkum yerlisi 

Hakim galatalısı sulukulelisi 

Oyun bozacak bir sarasker gerek bize 

Bin yıl yürüdük biz her arkaya her ize 

Boş yola ne ömürler heder oldu eyvah 

Bu yola gidenede götürenede vah 

Bu yolda bir sarasker bekiyorum fakat 

Haine sert bize yüreğinde şefkat 

Ayırır at izini fitne it izinden 

Kurtarır milleti gerçek yalan bizinden 

Vahyin kitabından bir nur işaret bulur 

Bu karanlık alemde bir alem kurulur 

Ne milleti ardı boş savaşta kırdırır 

Ne olur itler üstüne sürer yıldırır 

Yıkar iç kaleleri sürer ta haybere 

Hayberi kuşatılır fitneye son vere', 'Laik soru sorsam laık cevap gelirmi  Zehir yoksa ya iftira ya sus denirmi  Şu gerici osmanlının her on veziri  Üçü cıfıttı dördü dönme rumdu...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":136,"source_url":"https://www.antoloji.com/laik-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylek', 'leylek-atilhan-buyuksel-le490', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İbret deyip yazan şair 

Şu hayvanat aleminde 

Uçup kaçtığına dair 

Yazdın ya ibret neyinde 

Kuş olmuşki uçmak gerek 

Balık ise yüzer elbet 

Köpek sahibin bilecek 

Papağanda gör muhabbet 

Yılan ile şu leyleğin 

Düşmanlığı nedir ola 

Akreple ölene değin 

Yolu gider aynı yola 

Leylek bize yakın olur 

Ya şu yılan kime yakın 

Fravuna akın olur 

Şu guguk nam kuşa bakın 

Nedendir haber uçurur 

Bizden kıptı milletlere 

Fitne son demini bulur 

Onun her uçtuğu yere', 'İbret deyip yazan şair  Şu hayvanat aleminde  Uçup kaçtığına dair  Yazdın ya ibret neyinde  Kuş olmuşki uçmak gerek  Balık ise yüzer elbet  ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/leylek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılan ve Yalan', 'yilan-ve-yalan-atilhan-buyuksel-ycifu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah şu loca yılanı 

Soktu bizi derinden 

Demokrasi yalanı 

Puf oldu uçtu birden 

Toplanınca locada 

Karar der anaç domuz 

Tüttü duman bacada 

Boşa gitti oyumuz 

Hakkı yoktur güderiz 

Demokrasi isteme 

Dediler milleti biz 

Alıştırdık sisteme', 'Ah şu loca yılanı  Soktu bizi derinden  Demokrasi yalanı  Puf oldu uçtu birden  Toplanınca locada  Karar der anaç domuz  Tüttü duman bacada ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yilan-ve-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Handa', 'handa-atilhan-buyuksel-1ybmv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bu handa garip misafir 

Gelip geri gitmeye geldim 

Yürümeyen şu bedenimi 

Yürü deyip itmeye geldim 

Geldim giderim geldiğim yer 

Gün olur çağirir benide 

Ömrün tükendi gel geri der 

Bu hana gelen gidenide 

Ne maldan verilir ne mülkten 

Kazancın kesbin bu dünyada 

Denir iki tahta bir top kefen 

Başada yeter ayağada 

Gel deyi cağrıldığım yer 

Bırak diyor mülkü malıda 

Buraya her cağrılan gider 

Sultanı beyi hamalıda 

Ne ileri gider ne geri 

Ölüm diye saat kurulmuş 

Denir bu kapıdan gir içeri 

Ömür biter saat dururmuş 

0 

Kurdu kabineyi morris süleyman 

İcraat yok vaad çok yorumda var 

Unuttuk aradan yirmi yıl zamman 

Bu kez kabinede cıfıt rumda var 

Unuttuk yokları bürüdü geri 

0 

yürüdü geri 

Nefsim yürürken sakın gurulma 

Adımın birer birer basta git 

Şımarma varlığa boşa yorulma 

Düşün kendini her an yasta git 

Görürsen bir garib halini sor 

Kibiri bir kenara asta git 

0 

yaratmışsın Allahım uzun uzun kısa kısa 

Yaratmış iyi kötü siyah siyah beyaz beyaz 

beyazı yaradan siyahı niçin yaratmışsa 

yaratmış Allahım kiminin rızkı kısalmış az 

niçin böyledir demişsim demişsinki adalet 

ya kötünün bu işte rızası varmıdır', 'Ben bu handa garip misafir  Gelip geri gitmeye geldim  Yürümeyen şu bedenimi  Yürü deyip itmeye geldim  Geldim giderim geldiğim yer  Gün olu...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/handa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde Kayboldun', 'i-cinde-kayboldun-burak-olurogullari-e2hph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudumun tükendiği yolda, 

Bir çakıl tanesi kadar umut olsaydın

Böylesine dokunupta yarama, 

Bu şekilde giden sen olmasaydın

Gerçek misin yalan mı anlayamadım, 

Böyle yarım kalmasaydı keşke

Bu uzun bu çorak yola beni de çıkarsaydın.

Yarını olmayan bir yol bu

Umut olsan ne fayda, 

Yasadım ya burukluğu, 

Yaşayacağım zaman geldi ya yokluğunu

Bırak ellerimi öylece kalsın, 

Salıver hislerimi acını yasasın, 

Bırak kara kara içmeyeyim artık sevgimi! 

Hala mı öldürmedi sanıyorsun yüreğimin sefaletliğini

Sevgim başka bir baharda

Gönlüm senin topraklarında solduktan sonra

Seni sana bırakmışım ne fayda

Ha sen içimde kaybolmuşsun

Ha ben uzak dehlizlerde senden uzaklarda

Her ağladığımda üşüten sözlerin aklımda

Bir koca kalıp sensizlik ta ki iliklerimde

Ne şairliğim ellerimde, ne bitmeyen gönül sızım dilimde

Nefret ettim artık gönlümün sensizliğinde.

Ne zaman geldin ne zaman yok oldun

Ben bile anlayamadım

Doyarım sana demiştim

Daha bir damla bile yudumlamadım....

Şubat 2000

06FiLiNtA', 'Umudumun tükendiği yolda,  Bir çakıl tanesi kadar umut olsaydın Böylesine dokunupta yarama,  Bu şekilde giden sen olmasaydın Gerçek misin ya...', ARRAY['Türk Edebiyatı','Şiir','Burak Oluroğulları']::text[], 8.5, '{"poet":"Burak Oluroğulları","poet_slug":"burak-olurogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icinde-kayboldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-atilhan-buyuksel-k8hy8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende bilmezdim ölümün 

İnsana yakın olduğunu 

Ana rahminden alınıp 

Kabire konulduğunu 

Bunca yıllık şu ömür 

Değersiz akçe imişte 

Öğrenirmişte şu insan 

Onuda bu son gidişte 

İnsan yalnız doğarmışta 

Yalniz yaşarmış demek 

Ölüm yakın olurmuşta 

Hayat boş boşaymış emek 

Bir yaprak gibi dökülür 

İnişi başlar yavaştan 

Yaprak döker insan ölür 

Ne farımız var ağaçtan 

Alıp burdan götürdüğün 

İki tahta bir top kefen 

Eş bildiğin dost gördüğün 

Kimse gitmezmiş giderken 

Adin şöhretin varlığın 

Çabuk unutur kalanlar 

Eşim dostumdur sandığın 

Şu gülendir ağlayanlar 

Bu tabuta aldıkların 

Dar bir yere götürülür 

Yürümezse adımların 

Ağır ağır yürütülür 

Bizim gibi şu yatanlar 

Ağir akça yiğittiler 

Üstüne toprak atanlar 

Sırası geldi gittiler 

Bu yolculuğun sonunda 

Ne var geri dönmez giden 

Yoksa işlermi yolunda 

Köşkmü tahtmı var inciden', 'Bende bilmezdim ölümün  İnsana yakın olduğunu  Ana rahminden alınıp  Kabire konulduğunu  Bunca yıllık şu ömür  Değersiz akçe imişte  Öğrenir...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perdeler', 'perdeler-atilhan-buyuksel-xnpi6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Perdeler cekilmis 

Gün batip kararmis 

Benim durur 

Sen otur sabahi 

Bekleyedur 

Icimden bir ses 

Derki kudur 

Beyazi kara 

Bilmisim meger 

Dediler bu kara 

Beyazsa budur', 'Perdeler cekilmis  Gün batip kararmis  Benim durur  Sen otur sabahi  Bekleyedur  Icimden bir ses  Derki kudur  Beyazi kara  Bilmisim meger  ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/perdeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Post', 'post-atilhan-buyuksel-jp1x1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varım yokumu 

Koyup yollara 

Boşa okumu 

Attım yoruldum 

Düşmana dosta 

Ümit bağladım 

Sonra bir posta 

Yattım yoruldum', 'Varım yokumu  Koyup yollara  Boşa okumu  Attım yoruldum  Düşmana dosta  Ümit bağladım  Sonra bir posta  Yattım yoruldum...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/post-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-atilhan-buyuksel-pfpj3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seçmiş başa 

Ben sürgün yemişim 

Rum senin neyine 

Hayran be kardeşim 

Doğarkenmi miras 

Verildi bu sana 

Borclumusun yoksa 

Bunu bir hahama 

Ya rumsun ve yahut 

Bizden seçkin itsin 

Rum arabasinı 

Iteleyip gitsin', 'Seni seçmiş başa  Ben sürgün yemişim  Rum senin neyine  Hayran be kardeşim  Doğarkenmi miras  Verildi bu sana  Borclumusun yoksa  Bunu bir h...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/surgun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim', 'secim-atilhan-buyuksel-plzf0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baskan c.....r dedikleri 

Locadan tain gelir 

Toplar kahin konsülün 

Cikar baskahin gelir 

Sanir millet sectigin 

Isabet kurtulustur 

Hedef belli kahinin 

Böl milleti vurustur 

Sandik secim var imis 

Iki turlu secersin 

Locanin sectiginden 

Yek digerin secersin 

Uyanmissan bu ise 

Isin kolay görrülür 

Toplar kahin konsülün 

Dosyan fise verilir 

Gizli kuvvet elinden 

Agu zehir icersin 

Yahut kendi postuna 

Makul deger bicersin', 'Baskan c.....r dedikleri  Locadan tain gelir  Toplar kahin konsülün  Cikar baskahin gelir  Sanir millet sectigin  Isabet kurtulustur  Hedef ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/secim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülküdaşlar', 'ulkudaslar-atilhan-buyuksel-3p9xt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu Bizansın ordusunda 

Mevcud imiş ülküdaşlar 

Selçuk beyin karşısında 

Saf saf olup savaşmışlar 

Demişlerki behey Selçuk 

Şu bizansla harb edersen 

Savaşacak bizden birçok 

Anlamazsın meğer sen', 'Şu Bizansın ordusunda  Mevcud imiş ülküdaşlar  Selçuk beyin karşısında  Saf saf olup savaşmışlar  Demişlerki behey Selçuk  Şu bizansla harb ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ulkudaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek', 'felek-atilhan-buyuksel-4v1ul', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldi gitti felek bende ne varsa 

Verdigi bir ah ile bir eyvah oldu 

Nev bahar sanirdim bense alemi 

Döküldü yapragin eyvah vah oldu 

Eser badi seba yeksar olurmus 

Yikildi yuvam yurdum seyyah oldu 

Bilinmez hayatin vakti kiymeti 

Bos yere tükendi ömrüm ah oldu', 'Aldi gitti felek bende ne varsa  Verdigi bir ah ile bir eyvah oldu  Nev bahar sanirdim bense alemi  Döküldü yapragin eyvah vah oldu  Eser ba...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigaram', 'sigaram-atilhan-buyuksel-aivui', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Lif lif yükselip göge 

Yanar sigaram 

Diyar diyar dost 

Arar sigaram 

Benimle tutusup 

Yanar sigaram 

Gam keder gelir 

Dostca kucaklar 

Sarar sigaram 

Üzgün halimi 

Sorar sigaram 

Nere gitse bende 

Dönüp karar 

Kilar siaram', 'Lif lif yükselip göge  Yanar sigaram  Diyar diyar dost  Arar sigaram  Benimle tutusup  Yanar sigaram  Gam keder gelir  Dostca kucaklar  Sara...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sigaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-atilhan-buyuksel-2uj5d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni sorular 

Yordunuz derim 

Sizden uzakta 

Olmak isterim 

Varligin beni 

Cikmaza atti 

Gündüz gecemi 

Bulmak isterim 

Varsa derdiniz 

Neydi benimle 

Neyi verdiniz 

Almak isterim 

Sekil bicimden 

Bana nedirki 

Sizi icimden 

Atmak isterim 

Cahiliyim ben 

Bunca sorunun 

Var ise bilen 

Sormak isterim 

Ömrümü yedi 

Böyle sorular 

Nicindi neydi 

Bilmek isterim 

Dünü bugünü 

Unutup yarin 

Bende bir günü 

Bulmak isterim 

Varmi gizemi 

Sordugunuzun 

Varsa bizemi 

Sormak isterim', 'Beni sorular  Yordunuz derim  Sizden uzakta  Olmak isterim  Varligin beni  Cikmaza atti  Gündüz gecemi  Bulmak isterim  Varsa derdiniz  Neyd...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sorular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açil Susam', 'acil-susam-atilhan-buyuksel-t6vp0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açil susam açilsin dedik 

Erdik sırrına indi perdeler 

Sordum sırrın söyle ey Sfinsk 

Derki sırdır; perdeleriz 

Zehir verdigimizin adini 

Topragini alir culun giyeriz 

Fitne atesini yakinca biz 

Sönsün deyip körükleriz 

Erkegin kes kizlarin cariye 

Aldik ishakin kaldi geriye 

Calmisis topragin bizim diye 

Sahip cikar verde deriz. 

Kökümüz girit ne bilsin goyim 

Sanır ceddimiz abraham soyum 

Bizim tuzaklar böyledir bayım 

Dağılmış binbir yerdeleriz 

Isa der seytanin ogullari siz 

Seytana acik rahme gebeyiz 

Degil filistin Kitab ehli biz 

Kitap bizim yerde deriz 

Soyum abrama kurunca tuzak 

Isak tükendi Ismail ancak 

Göcüp gitti cöle bizden uzak 

Sanir amca zadeleriz. 

Dagil aleme cogalsin kavim 

Kanindan alem kan alsin kavim 

Kundak sokup bataklarda goyim 

Bilmez kanin tazeleriz', 'Açil susam açilsin dedik  Erdik sırrına indi perdeler  Sordum sırrın söyle ey Sfinsk  Derki sırdır; perdeleriz  Zehir verdigimizin adini  To...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/acil-susam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susam-2', 'susam-2-atilhan-buyuksel-2pudz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Grek romen amcaoglu 

Kipti bizans sodom soyu 

Bilinmez sir dipsiz kuyu 

Kökü Fravunzadeleriz 

Elde tevrat rol yapariz 

Nerde batak orda variz 

Ciplak heykel put tapariz 

Goyim sanat sansin deriz 

Dans bale kokteyl opera 

Bizde tapmaktir seytana 

Toplaninca havralarda 

Serefe kan olsun deriz 

Kerhane meyhane bizim 

Icinde sermaye bizim 

Sulukule gaye bizim 

Cikmazlara dalsin deriz 

Fikir sanat bulus nedir 

Bizde degil goyimdedir 

Calis bize bal yap yedir 

Bizi doyar sansin deriz 

Nesep bozup karistirmis 

Raksa dansa alistirmis 

Ari gibi calistirmis 

Tefe ile soysun deriz 

Yilan domuz maymun seytan 

Dendi kovulduk hicazdan 

Bataklarda tohum sacan 

Ocagina girsin deriz 

Azdir nufus yetmez bizde 

Gütmek gerektir bu izde 

Sicim bizden it var sizde 

Uyanani alsin deriz 

Akilliyi zehir vere 

Bagimsizlik demek nere 

Serdik gizli devrim yere 

Demokrasi sanssin deriz 

Ceddimiz kabilden beri 

Parcaladık goyimleri 

Dönüp bizler birde geri 

Dünya kanı bulsun deriz 

Bu pislik Türk icinde yok 

Sodomda varda cinde yok 

Yunanda var macinde yok 

Sac tohumu olsun deriz 

Karismazsak goyimlere 

Veba taunla bizlere 

Gazap gelir vurup yere 

Iclerine dalsin deriz 

Hahambasi derki sözüm 

Binbir tuzak binbir cözüm 

Kitap yasaklatmak özüm 

Düsünceye darsin deriz 

Sırrımız var engerekde 

Seytan zinaoglu birde 

Bunun bilindigi yerde 

Cellat sicim olsun deriz', 'Grek romen amcaoglu  Kipti bizans sodom soyu  Bilinmez sir dipsiz kuyu  Kökü Fravunzadeleriz  Elde tevrat rol yapariz  Nerde batak orda vari...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/susam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavşanla Yılan', 'tavsanla-yilan-atilhan-buyuksel-ko394', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kuşun yavasına 

Dilenci kılığında 

Tüyü alır başına 

Bir yılan sokulur 

Sürme çekmiş kaşına 

Sizin gibi bir kuştum 

Açtım yolundu tüyüm 

Güzel çalımlı hoştum 

Ceddinizden büyüğüm 

Onun için buruştum 

Deyi ağlar yavuncur 

Girer eve sıkılgan 

Bir köşeye kurulur 

Ev sahibi sanırki 

Kendi cinsidir yılan 

Nice zaman aradan 

Geçince dost olunur 

Yerli olmuş ki yılan 

Artık rolun zamanı 

Bir gün üzgün bulunur 

Kuş yılana derdini 

Sorar yaranı saram 

Üzme kardeş kendini 

Dost değilmi ikimiz 

Yuvan der olsun yuvam 

Kuşcağız günü gelir 

Kuluçkaya yatacak 

İhaneti ne bilir 

Yılan yumurtasını 

Yumurtaya katacak 

Ve ay geçer yavrular 

Yumurtadan çıkınca 

İçlerinde yavru var 

Kuşunkine benzemez 

Dikkat edip bakınca 

Sanır kendi yavrusu 

Takdir der kuş bu hale 

Şu yılanın borusu 

Bir gün ötecek kale 

Fetholundu doğrusu 

Hem yuvada nufusu 

Artınca şu yılanın 

Zehirlidir yavrusu 

Kuş sandığı yılana 

Ana der akıllanın 

Hoşgörür kuş yavuncur 

Farkı zehiri olan 

Sanır bir cins yavrudur 

Yuvasına girince 

Yılan idi bu yılan 

Sanır kavga yem için 

Cinsi karakteri bu 

Kavga edilir niçin 

Bilmez yılan yanaşma 

Yuvası bu yeri bu 

Başka sebeb gösterip 

Her gün bir kuş zehirler 

Günü gelip bir tertip 

Devrim yapar hünkara 

Toprağı yaladı der 

Bir pak dil kuş yuvada 

Aklı ermez bu işe 

Mekik dokur ortada 

Kardeş bilir yılanı 

Dur demeli gidişe 

İzah eder yılana 

Hoşgörü faydasını 

Lazım bizim vatana 

Çağdaşlığın gereği 

Öyledir el baksana 

Deyip misal getirir 

Yılan bulur yeni suç 

Der kafanı değiştir 

Çağdaş böylemidir hiç 

Bu ne biçim gidiştir 

Olmaz senin gibi kuş 

Üzerinde tüy niçin 

Bak kafanın içini 

Düşünceni okurum 

Bu kafadan vaz geçin 

Bizim pakdil inanır 

Kuş sandığı yılana 

Başka renge boyanır 

Yolar tüyü tüsünü 

Kapısına dayanır 

Nesill geççer aradan 

Yerli kim kuş unutur 

Yanaşmaydı bu yılan 

Kaşı gözü bahane 

Kuş neslini kurutur', 'Bir kuşun yavasına  Dilenci kılığında  Tüyü alır başına  Bir yılan sokulur  Sürme çekmiş kaşına  Sizin gibi bir kuştum  Açtım yolundu tüyüm ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/tavsanla-yilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkımız', 'farkimiz-atilhan-buyuksel-ao1eb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilenci kılığında 

Bir gün yuvasına kuşun 

Yılan girer içeri 

Anlamaz zavallı kuş 

Hikmetini bu işin 

Sizin gibi bir kuştum 

Açtım yolundu tüyüm 

Güzel çalımlı hoştum 

Kol kanadım kırıldı 

Zulmettiler buruştum 

Misafire der Buyur 

İçeriye sıkılgan 

Bir köşeye kurulur 

Ev sahibi sanırki 

Kendi cinsidir yılan 

Nice zaman aradan 

Geçince dost olunur 

Yerli olmuştur yılan 

rol yapmanın zamanı 

Bir gün üzgün bulunur 

Sorar hemen derdini 

Nedir yaranı saram 

Üzme kardeş kendini 

Dost olmuşuz ikimiz 

Yuvan der olsun yuvam 

kuşcağız günü gelir 

Kuluçkaya yatacak 

İhaneti ne ne bilir 

Yılan yumurtasını 

Yumartaya katacak 

Ve ay geçer yavrular 

Yumurtadan çıkınca 

İçlerinde yavru var 

Kuşunkine benzemez 

Dikkat edip bakınca 

Sanır kendi yavrusu 

Takdir der kuş bu hale 

Sevinçlidir doğrusu 

Yılan attı bir adım 

Fethedilmiştir kale 

Artar yuvada nufus 

YavrularıYılanın 

Ne akıl işler ne us 

Kuş sandığı yılana 

Kuş derki akıllanın 

Hoşgör der kuş yavuncur 

Farkı zehiri olan 

Aynı bir cins yavrudur 

Yuvasına girince 

Yılan idi bu yılan 

Sanır kavga yem için 

Cinsi karakteri bu 

Kavga edilir niçin 

Bilmez yılan yanaşma 

Yuvası bu yeri bu 

Başka sebeb gösterip 

Her gün bir kuş zehirler 

Günü gelir bir tertip 

Devrim yapar hünkara 

Yaladı Toprağı der 

Bir pak dil kuş yuvada 

Aklı ermez bu işe 

Dolaşarak ortada 

Kardeş bilir yılanı 

Dur demeli gidişe 

İzah eder yılana 

Hoşgörü faydasını 

Lazım bizim vatana 

Bak çağdaşlık gereği 

Öyledir el baksana 

Deyip misal getirir 

Fakat yılan bulur suç 

Der kafanı değiştir 

Kasdedersin yuvaya 

Çağdaşlık olurmu hiç 

Olmaz senin gibi kuş 

Üzerinde tüy niçin 

Bak kafanın içine 

Düşünceni okurum 

Gericilikten geçin 

Bizim pakdil inanır 

Kuş sandığı yılana 

Başka renge boyanır 

Yolar hemen tüyünü 

Kapısına dayanır 

Yılan derki iyide 

Kanatların ne ola 

Olmaz kuş dediğnde 

Ayakları gagası 

İhtiyaçmı var kola 

Nesil geçer aradan 

Kuş yerli kim unutur 

Yanaşmaydı bu yılan 

Plan hile desise 

Kuş soyunu kurutur', 'Dilenci kılığında  Bir gün yuvasına kuşun  Yılan girer içeri  Anlamaz zavallı kuş  Hikmetini bu işin  Sizin gibi bir kuştum  Açtım yolundu t...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/farkimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı', 'olmadi-atilhan-buyuksel-oqa4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmadı kardeşim çiçekler attın 

Bülbül sandın şu yılana olmadı 

Asyadan milleti ardına taktın 

Maraton koştun yunana olmadı 

Top oynardın elden üstün olmadı 

Boş konuştun suçlu oldun bahane 

Küsülmez yunana küstün olmadı 

Düştün zindana hayalim virane 

Millet seçti seni ya sen yunana 

Lağımına çukur açtın olmadı 

Ovalardan adalara limana 

Baraja su oldun taştın olmadı 

Rehberim değildi ilk iş hamallık 

Kuşatıp fitneyi önce kovaydın 

Ortalık sis duman iken karanlık 

Bin düşünüp gözünü bir ovaydın 

Yazık milletime batık vatanım 

Kaptan zindana sürüldün olmadı 

Kendini kurtaramayan kaptanım 

Defterin çabuk dürüldün olmadı 

Tedbirdi zürriyyetini savcının 

Bileydinde ne bildin ne sormadın 

Oltayı üstüne atan avcının 

Cıfıt olduğuna hiç uyanmadın 

Suçsuzum dedin ya kıs kıs güldüler 

Bana tuzak kurdu dönme deseydin 

Hamle bekeyip korktu büküldüler 

Aslan olup yel gibi bir eseydin 

Yunanın kerhanesine barına 

Acıdın sermayesine olmadı 

Cıfıt basına sapık barbarına 

Set olmadın gayesine olmadı 

Çözemedin içimizde yunanı 

Fazıl bir alime çırak olaydın 

Cıfıt fitneyi hain sırıtanı 

Timur gibi ayıklayıp kıraydın 

Kime yanam kardeşim yıkılmışız 

Sana yansam ya kim yanar halime 

Korkutulmuş sindirilmiş yılmışız 

Bittik darbe vuruldu hayalime', 'Olmadı kardeşim çiçekler attın  Bülbül sandın şu yılana olmadı  Asyadan milleti ardına taktın  Maraton koştun yunana olmadı  Top oynardın el...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olmadi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tez Oldu', 'tez-oldu-atilhan-buyuksel-itr1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eriştim demine şu ömrümün 

Tükendi bitti fakat az oldu 

Doğum baslangiciymis ölümün 

Döküldü yapragim tez güz oldu 

Her fani gibi gectim bu yoldan 

Ne serencam gördüm ne dertleri 

Kah bu yoldan gittim kah o yoldan 

bittim görki yollar bitmez oldu 

Su fani hayat imiş yolculuk 

Demek her gelen burdan gecermis 

Ilk nefes olurmus ve son soluk 

tükettim şu ömrümü tez oldu', 'Eriştim demine şu ömrümün  Tükendi bitti fakat az oldu  Doğum baslangiciymis ölümün  Döküldü yapragim tez güz oldu  Her fani gibi gectim bu ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tez-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tunaya Ağıt', 'tunaya-agit-atilhan-buyuksel-mrqr5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidip maziye gezindim birde 

Baktim süheda secdede uyur 

Kilic sesiyle baslayip yerde 

Tekbir getirip göklere duyur 

Gökten ceddime sancak olmaya 

Gördüm hilali önüne düsmüs 

Gidip tarihe mühür vurmaya 

Yürüyüs ki Allaha Yürüyüs 

Ne günlerdi Kizilirmak Tuna 

Uzaktan doğar bize akardi 

Bir yerde bulutugun unutma 

Nil diye Firat kardesin vardi 

Hicazdan baslayip Budine dek 

Ayni ses yükselirdi kubbeye 

Belki bin yil nesiller gerek 

Tarihi halka halka dizmeye 

Tunam garipmisin bu yollarda 

Kartal diyar diyar hür ucardi 

Dogan bebekler akincilarda 

Kilic sesi nal sesi duyardi 

Yürüki Tunam tarih yazilsin 

Degismez bu neslin kan ayni kan 

Nakis vur tasa mühür kazilsin 

Gecmise varip atiye uzan 

Sehit askerin yerine asker 

Dogursun analar Tuna önünde 

Akinci dogsun dogsun sarasker 

Gökte hilalim görüldügünde 

Yık garabeti silkinip bir an 

Çarpıp çınla bu dağdan o dağa 

Şahlan Tunam bir daha şahlan 

Tekbir sesini al git uzağa', 'Gidip maziye gezindim birde  Baktim süheda secdede uyur  Kilic sesiyle baslayip yerde  Tekbir getirip göklere duyur  Gökten ceddime sancak o...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tunaya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-atilhan-buyuksel-ay9ps', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu tahtada yatan hediye 

Ucuz bir ata bindirilmis 

Dönüp geri gelmesin diye 

Soyunmusta giyindirilmis 

Kalkip yürü desek yürürmü 

Davetmi var esaretmi var 

Bu son gidis bilse ölürmü 

Yoksa gider cesaretmi var 

Cagiranmi var gel diyenmi 

Gördüm gidiyor agir aksak 

Aldigin bu yük hediyenmi 

Ey yolcu tutanmi var tutsak 

Niçin gidersin be hey yolcu 

Nasıl bu yolculuk zoru ne 

Bu fani hayatın ipucu 

Yahut cevabı ne soru ne 

0 

Doymaz usanmaz şu nefsim 

koştu koştu bir durağa geldi 

usandı bir durağa geldi 

hayalindeki köşkü sarayı 

ne geldi ne bir bağa geldi 

güz yaprağı döküldü 

kış oldu kırağa geldi 

eğildi buküldü yarışı 

hep aynı sokağa geldi', 'Bu tahtada yatan hediye  Ucuz bir ata bindirilmis  Dönüp geri gelmesin diye  Soyunmusta giyindirilmis  Kalkip yürü desek yürürmü  Davetmi va...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tutsak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-atilhan-buyuksel-rl5kc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah uyandım hayatın bittiğini 

Anladım tüm yollar gider Allaha 

Ayağın gidip elin ettiğini 

Taşlar dile gelip söyler Allaha 

Kaçamak bulunmaz kayda geçilir 

İsterse uzatılır günler geceler 

Bir günlük yol uzar ayda geçilir 

Kul olur hamallar beyler Allaha 

Ol denirse hemen olur olmazlar 

Görürsün küçülmüş önünde her şey 

Ne çoklar tükenmiş çoğalmış azlar 

Diz çöker o gün devler Allaha 

Sürtünür dik başlar varır secdeye 

Eğmezsen eğerler başını hemen 

Denilir geç oldu dövünmek niye 

Hiç gelir varlık değerler Allaha', 'Sabah uyandım hayatın bittiğini  Anladım tüm yollar gider Allaha  Ayağın gidip elin ettiğini  Taşlar dile gelip söyler Allaha  Kaçamak bulun...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykular', 'uykular-atilhan-buyuksel-jc2q2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bu vakti bende 

Isterim sizden uykular 

Uyuklayim söyleyinde 

Ayakta gölgem uyuklar 

Hayat demek buyduda 

Kovulmusum hayattayim 

Ecinniler hep uykuda 

Uyuklamaz ayaktayim 

Uyuklayin ecinniler 

Gölgem ile uyuklayın 

Uykuya dalip ninniler 

Söyleyerek sayıklayın', 'Gecenin bu vakti bende  Isterim sizden uykular  Uyuklayim söyleyinde  Ayakta gölgem uyuklar  Hayat demek buyduda  Kovulmusum hayattayim  Eci...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uykular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısıltı', 'fisilti-atilhan-buyuksel-xfh6a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Icimde bir fisilti tin tin eder 

Alip hayalimi uzaga gider 

Elimi acip ah edip aglasam 

Sus aglamak sana nafile der 

Karisti hayalim caresiz bugün 

Bu gördügün kacik benim derbeder', 'Icimde bir fisilti tin tin eder  Alip hayalimi uzaga gider  Elimi acip ah edip aglasam  Sus aglamak sana nafile der  Karisti hayalim caresiz...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/fisilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adım', 'bir-adim-atilhan-buyuksel-wh3ot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyada varliga bir adim attim 

Yetisti ardimdan karali bahtim 

Dur gitme diyerek önümü kesti 

Kis gelip kar yagdi firtina esti 

Caresiz sokakta kaldim kimsesiz 

Bilinmez yollara düsmüsüm sessiz', 'Dünyada varliga bir adim attim  Yetisti ardimdan karali bahtim  Dur gitme diyerek önümü kesti  Kis gelip kar yagdi firtina esti  Caresiz sok...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-atilhan-buyuksel-6uodt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mezar tasima yazin bu adem 

Bir gölge gibi ugrayip gecti 

Varligi kiymet olmadi madem 

Neyi nicini sormayip gecti 

Gelin üstüme bir ihlas ile 

Dua okuyun degil yas ile 

Deyin bu adam ne miras ile 

Hayattan nasip almayip gecti 

Hayattan bir dem almadi gönlüm 

Hos bulup bir yar sarmadi gönlüm 

Sukuna erip varmadi gönlüm 

Bu hana hemen uğrayip gecti', 'Mezar tasima yazin bu adem  Bir gölge gibi ugrayip gecti  Varligi kiymet olmadi madem  Neyi nicini sormayip gecti  Gelin üstüme bir ihlas il...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vasiyet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-atilhan-buyuksel-yw28n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ta uzaklardan nefesini 

Ensemde hissederim vatan 

Duysam kah rüzgarın sesini 

Vatanım bu ses derim vatan 

Sabah olupta gün doğarsa 

Bakarım senden uzaktayım 

Saçımdan ya bir tel ağarsa 

Kaderindir çek derim vatan 

Feryadımı alıp şu rüzgar 

Gidermi acep ta uzağa 

Senden ümitle bir ses duyar 

Tez olurum eserım vatan 

Arkadaşlarım cocukluğum 

Tozlu yollar dağların beni 

Emek verdiğim koşuştuğum 

Unutmuşsa neylerim vatan 

Hatıramda sabah ezanı 

Minareden bir ses duyardım 

Aksakal dedeyle kızanı 

Namaza bende vardım vatan 

Hani o iftar vakti babam 

Derdi oğul dinle ezanı 

Alev alev tutuşan sobam 

Ve anamın kazanı vatan 

Çamurdan oyuncak yapardı 

O küçük ellerim bir zaman 

Babamınsa bir oğlu vardı 

Gel deyince hep koşan vatan 

Geçer şerit gibi kafamdan 

Canlanır bütün cocukluğum 

Çan sesi var bu gün ne yandan 

Gurbet elde uyansam vatan 

Sana bir kem dokunmasında 

Varsın hasretin sabrederim 

Belki bin yıl kalsam yasında 

Bu hale şükrederim vatan', 'Ta uzaklardan nefesini  Ensemde hissederim vatan  Duysam kah rüzgarın sesini  Vatanım bu ses derim vatan  Sabah olupta gün doğarsa  Bakarım ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/vatan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-atilhan-buyuksel-6ajgi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senki kainatın padişahısın 

İmdad eyle bize rabbil alemiyn 

Her çağıranın ümiddi ahısın 

Duy bizi yad eyle Rabbil alemiyn 

Koyma garib boynu bükük çaresiz 

Gönlümüz hoş şad eyle Rabbil alemiyn 

Günahkar kulu bırakma kimsesiz 

Bizi sertaç eyle rabbil alemiyn', 'Senki kainatın padişahısın  İmdad eyle bize rabbil alemiyn  Her çağıranın ümiddi ahısın  Duy bizi yad eyle Rabbil alemiyn  Koyma garib boynu...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalvaris-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale', 'canakkale-atilhan-buyuksel-wl4vu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Agamemnon rahibine esir 

Truvada unuttuğum şu sır 

Doğranan bebeğe kırk üç asır 

Geçti hatti hitaya yanarım 

Agamemnonun hatırasına 

Çanakkalede kadırgasına 

Adını koyup geldi baskına 

Kanayan şu yaraya yanarım 

Fravunun kabusu illeti 

Çanakkalede şehit milleti 

Zülkarneyin kilitbahir seti 

Unuttuğum araya yanarım 

Düzerken fravuna medhiye 

Uzak durduğum moğol çinliye 

Japon hindli kızılderiliye 

Kaybettiğim kıtaya yanarım 

Sümer hitayın kitabesine 

Hattuşilinin hitabesine 

Turanın kayıp alfabesine 

Oğuzun hatıraya yanarım 

Yıkık nagazaki hiroşima 

Bana ne dedim geldi başıma 

Esir afrikalı gardaşıma 

İşlediğim hataya yanarım 

Yaydılar merne putun neslini 

Bozdular bitki otun neslini 

Karıştırıp saf atın neslini 

Katıra kardeş taya yanarım', 'Agamemnon rahibine esir  Truvada unuttuğum şu sır  Doğranan bebeğe kırk üç asır  Geçti hatti hitaya yanarım  Agamemnonun hatırasına  Çanakka...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/canakkale-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi', 'demokrasi-atilhan-buyuksel-9s6ji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kirk yilda bir kirk yil 

Uyanınca uykudan 

Secip getirik basa 

Hop deyince bizimki 

Verdi loca karari 

Gitti oylar bosa 

Yasa demokrasi 

Sandik secim cok yasa 

Ise basla sifirdan 

Kirka kadar sayarsin 

İzin verirse loca 

Basa bizden koyarsin 

Koyun olursa nasil 

Uyuyani uyarsin 

Yasa demokrasi 

Sandik secim cok yasa 

Seçilmişse sürüden 

Koçlar gider kasaba 

Kalan koyun olmazmı 

Yılan delikten ıslık 

Çalsa koyun uymazmı 

Yaşa demokrasi 

Sandık seçim çok yaşa', 'Kirk yilda bir kirk yil  Uyanınca uykudan  Secip getirik basa  Hop deyince bizimki  Verdi loca karari  Gitti oylar bosa  Yasa demokrasi  San...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/demokrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum', 'yavrum-atilhan-buyuksel-cbnu3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sizden uzakta 

Bugün dertliyim 

Agla be yavrum 

Karali yasin 

Bagla be yavrum 

Yollar cok uzak 

Hayat denilen 

Su garip tuzak 

Cok kücük yasin 

Agla be yavrum', 'Sizden uzakta  Bugün dertliyim  Agla be yavrum  Karali yasin  Bagla be yavrum  Yollar cok uzak  Hayat denilen  Su garip tuzak  Cok kücük yas...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yavrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım', 'basim-atilhan-buyuksel-0nw25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ayağa düştü başım 

demine geldi yaşım 

ilkbahar yaz tükendi 

güz oldu geldi kışım 

yaprak dökümü güz 

çabuk sarardı yüz 

aldığım nefesten 

İki kat büyüğüz', 'ayağa düştü başım  demine geldi yaşım  ilkbahar yaz tükendi  güz oldu geldi kışım  yaprak dökümü güz  çabuk sarardı yüz  aldığım nefesten  İ...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/basim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmişbeş Yıl', 'yetmisbes-yil-atilhan-buyuksel-iig5x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün cuhuriyetin 

Yetmisbesinci yili 

Cumhuriyyet bizim 

Gururumuzdur 

Kendine Türk diyen 

Herkes türk olup 

Yahudisi rumu 

Ugurumuzdur 

Nesebli hanedan 

Gitti sürgüne 

Geldi dönme basa 

Cumhururumuzdur 

Her şey çok ulu 

Mutluyuz fakat 

Şu başa bela 

Dini terkedip 

Yeni putlu din 

Buyurumuzdur 

Sorma kardeşim 

İnkılap oldu 

Raksı dansı bizim 

Şuurumuzdur', 'Bugün cuhuriyetin  Yetmisbesinci yili  Cumhuriyyet bizim  Gururumuzdur  Kendine Türk diyen  Herkes türk olup  Yahudisi rumu  Ugurumuzdur  Ne...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yetmisbes-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeyin Helal', 'yeyin-helal-atilhan-buyuksel-1ba60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boşaltın içini bu günlük istihakınız 

Kaldi millet bir deri varsa iştiyakınız 

Atıştırın bu fırsat sonra açız dersiniz 

Soyun bu yağma sizin nesil boyu yersiniz 

Uyuttunuz millet uyanmaz bin yıl uyanmaz 

Bin yıl uyuklayan şu bizden bir kıl uyanmaz 

Portup kaçar gümrük açık beynelmilelsiniz 

En son evrakınız gelir önce siz gidersiniz 

Ne hoş şu aheng sizin basın para pul sizin 

Bu vurgun bu yağma sizin o çapul sizin 

Yeraltında bu milleti gizli güdersiniz 

Kiminiz cıfıt kiminiz mason pedersiniz 

Beyler helal pıskırmayın helal şu sütümüz 

Yeyin etimiz binin ağır olsa yükümüz 

Semiz semiz göbeklenir yeyip şişersiniz 

Soyun hakkınızı bin deve yükü yersiniz', 'Boşaltın içini bu günlük istihakınız  Kaldi millet bir deri varsa iştiyakınız  Atıştırın bu fırsat sonra açız dersiniz  Soyun bu yağma sizin...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeyin-helal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-atilhan-buyuksel-92hss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anladımki şu hayat 

Sırtımızda ne yükmüş 

Taşıdığım bu yükse 

Kaf dağından büyükmüş 

Malın mülkün varlığın 

Bela imiş insana 

Son durağa vardığın 

Gün ki yükü alsana', 'Anladımki şu hayat  Sırtımızda ne yükmüş  Taşıdığım bu yükse  Kaf dağından büyükmüş  Malın mülkün varlığın  Bela imiş insana  Son durağa var...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıktım Zirveye', 'ciktim-zirveye-atilhan-buyuksel-hpkas', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ciktim zirveye düstüm yüzüstü 

Karali bahtim gülmedi gitti 

Ömrüm boyunca ne yaptim ise 

Yaptigim kiymet olmadi gitt 

Usandim felegin kahr elinden 

Iyi gün bahtim gülmedi gitti 

Yazildi basa diyari gurbet 

Bir yerde karar kilmadi gitti 

Derdi cefadan eyledi zebun 

Usandim felek yilmadi gitti 

Kendime sirdas bulayim dedim 

Gönlüm kimseyi sarmadi gitti 

Heybemde yüküm mücevher olsa 

Kimse müsteri olmadi gitti 

Gittim yillarca sonsuza dogru 

Kimse derdimi sormadi gitti', 'Ciktim zirveye düstüm yüzüstü  Karali bahtim gülmedi gitti  Ömrüm boyunca ne yaptim ise  Yaptigim kiymet olmadi gitt  Usandim felegin kahr e...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ciktim-zirveye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman İçinde', 'zaman-i-cinde-atilhan-buyuksel-fpaws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sandal demir atip rihtima 

Ugultuyla yük aldi buradan 

Sanki balyoz inmişti bahtima 

Anladim zaman geçti aradan 

Demek habersiz gelip gittide 

Ölümsüz hayatın bakisi gibi 

Hem yükleyip alip gittiğide 

Geçmis zamanin atisi gibi

.', 'Bir sandal demir atip rihtima  Ugultuyla yük aldi buradan  Sanki balyoz inmişti bahtima  Anladim zaman geçti aradan  Demek habersiz gelip gi...', ARRAY['Türk Edebiyatı','Şiir','Atilhan Büyüksel']::text[], 8.5, '{"poet":"Atilhan Büyüksel","poet_slug":"atilhan-buyuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zaman-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amentu', 'amentu-i-smet-ozel-g2hlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan 

eşref-i mahlûkattır derdi babam 

bu sözün sözler içinde bir yeri vardı 

ama bir eylül günü bilek damarlarımı kestiğim zaman 

bu söz asıl anlamını kavradı 

geçti çıvgınların, çıbanların, reklamların arasından 

geçti tarih denilen tamahkâr tüccarı 

kararmış rakamların yarıklarından sızarak 

bu söz yüreğime kadar alçaldı 

damar kesildi, kandır akacak 

ama kan kesilince damardan sıcak 

sımsıcak kelimeler boşandı 

aşk için karnıma ve göğsüme 

ölüm için yüreğime sürdüğüm eczâ uçtu birden 

aşk ve ölüm bana yeniden 

su ve ateş ve toprak 

yeniden yorumlandı. 

Dilce susup 

bedence konuşulan bir çağda 

biliyorum kolay anlaşılmayacak 

kanatları kara fücur çiçekleri açmış olan dünyanın 

yanık yağda boğulan yapıların arasında 

delirmek hakkını elde bulundurmak 

rahma çağdaş terimlerle yanaşmak için 

bana deha değil 

belgeler gerekli 

kanıtlar, ifadeler, resmi mühür ve imza 

gençken 

peşpeşe kaç gece yıllarca 

acıyan, yumuşak yerlerime yaslanıp uçardım 

bilmezdim neden bazı saatler 

alaturka vakitlere ayarlı 

neden karpuz sergilerinde lüküs yanar 

yazgı desem 

kötü bir şey dokunmuş olurdu sanki dudaklarıma 

Tokat 

aklıma bile gelmezdi 

babam onbeşli olmasa. 

Meyan kökü kazarmış babam kırlarda 

ben o yaşta koltuğumda kitaplar 

işaret parmağımda zincir, cebimde sedef çakı 

cebimde kırlangıçlar çılgınlık sayfaları 

kafamda yasak düşünceler, Gide mesela. 

Kar yağarken kirlenen bir şeydi benim yüzüm 

her sevinç nöbetinde kusmak sunuldu bana 

gecenin anlamı tıkansın diye ıslık çalar 

resimli bir kitaptan çalardım hayatımı 

oysa hergün 

merkep kiralayıp da kazılan kökleri 

Forbes firmasına satan babamdı. 

Budur 

işte bir daha korkmamak için korkmaz görünen korku 

işte şehirleri bayındır gösteren yalan 

işte mevsimlerin değiştiği yerde buharlaşan 

kelepçeler, sürgünler, gençlik acılarıyla 

güç bela kurduğum cümle işte bu; 

ten kaygusu yüklü ağır bir haç taşımaktan 

tenimin olanca ağırlığı yok oldu. 

Solgun evler, ölü bir dağ, iyice solmuş dudak 

bile bir bir çınlayan 

ihtilal haberidir 

ve gecenin gümüş ipliklerden işlenmiş oluşu 

nisan ayları gelince vücudu hafifletir 

şahlanan grevler içinde kahkahalarım küstah 

bakışlarım beyaz bulutlara karşı obur 

marşlara ayarlanmak hevesindeki sesim 

gider şehre ve şaraba yaltaklanarak 

biraz ağlayabilmek için 

fotoğraflar çektirir 

babam 

seferberlikte mekkâredir. 

İnsanın 

gölgesiyle tanımlandığı bir çağda 

marşlara düşer belki birkaç şey açıklamak 

belki ruhların gölgesi 

düşer de marşlara 

mümkün olur babamı 

varlık sancısıyla çağırmak: 

Ezan sesi duyulmuyor 

Haç dikilmiş minbere 

Kâfir Yunan bayrak asmış 

Camilere, her yere 

Öyle ise gel kardeşim 

Hep verelim elele 

Patlatalım bombaları 

Çanlar sussun her yerde 

Çanlar sustu ve fakat 

binlerce yılın yabancısı bir ses 

değdi minarelere:Tanrı uludur Tanrı uludur 

polistir babam 

Cumhuriyetin bir kuludur 

bense 

anlamış değilim böyle maceralardan 

ne Godiva geçer yoldan, ne bir kimse kör olur 

yalnız 

coşkunluğu karşısında içlendiğim şadırvan 

nüfus cüzdanımda tuhaf 

ekmek damgası durur 

benim işim bulutlar arşınlamak gün boyu 

etin ıslak tadına doğru 

yavaş yavaş uyanmak 

çocuk kemiklerinden yelkenler yapıp 

hırsız cenazelerine bine bine 

temiz döşeklerin ürpertisinden çeşme 

korkak dualarından cibinlikler kurarak 

dokunduğum banknotlardan tiksinmeyi itiraz 

nakışsız yaşamakları 

silâhlanmak sanarak 

çıkardım 

boğaza tıkanan lokmanın hartasını 

çıkınımda güneşler halka dağıtmak için 

halkı suvarmak bin saçlarımda bin ırmak 

ıhtırdım caddeleri meğer ki mezarlarmış 

hazırmış zaten duvar sıkılmış bir yumruğa 

fly Pan-Am 

drink Coca-Cola 

Tutun ve yüzleştirin hayatları 

biri kör batakların çırpınışında kutsal 

biri serkeş ama oldukça da haklı. 

Ölümler 

ölümlere ulanmakta ustadır 

hayatsa bir başka hayata karşı. 

Orada 

aşk ve çocuk 

birbirine katışmaz 

nasıl katışmıyorsa başaklara ağustos sıcağı 

kendi tehlikesi peşinden gider insan 

putların dahi damarından 

aktığı güne kadar 

sürdürür yorucu kovalamacayı. 

Hanidir görklü dünya dünyalar içre doğan? 

Nerde, hangi yöremizde zihnin 

tunç surlardan berkitilmiş ülkesi 

ağzı bayat suyla çalkanmış çocuğa rahim olan 

parti broşürleri yoksa kafiyeler mi? 

Hangi cisimdir açıkça bilmek isterim 

takvim yapraklarının arasını dolduran 

nedir o katı şey 

ki gücü 

gönlün dağdağasını durultacak? 

Hayat 

dört şeyle kaimdir, derdi babam 

su ve ateş ve toprak. 

Ve rüzgâr. 

ona kendimi sonradan ben ekledim 

pişirilmiş çamurun zifiri korkusunu 

ham yüreğin pütürlerini geçtim 

gövdemi alemlere zerkederek 

varoldum kayrasıyla Varedenin 

eşref-i mahlûkat 

nedir bildim. 

(1974)', 'İnsan  eşref-i mahlûkattır derdi babam  bu sözün sözler içinde bir yeri vardı  ama bir eylül günü bilek damarlarımı kestiğim zaman  bu söz a...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":152,"source_url":"https://www.antoloji.com/amentu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ağrı Yakıldıkça Sevilmeli', 'bir-agri-yakildikca-sevilmeli-i-smet-ozel-lxbho', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin dürüstlüğünden herkes kuşkulanır

korkulur o kuş yüklü iniltilerden

ve mor ağzını gecenin kumuna batıran ben

çağdaş serüvenler adına

bütün fotoğraflarını yakan

yakan ve bekleyen.

Çarpar yüzü bir çocuğun mezarlara

yine de ağartamaz tanımını gecenin.

Ezgisiz ama esnaf bakışlarıyla soyunan bir kadın

ayartılmaya uygun o çok baygın yerlerim

ağartamaz

çünkü çocuklar yağız bir öpüşle korunur

ben yakarım çağımın ellerini. Ben bekliyenim.

Gecenin kıyısında benden konuşulur.

Kara bir irin akıyor

öpünce o yıkılmış gülüşünden çocukların.

Kara bir salgıdır çünkü büyük

serüvenler ve çocukların soluk alışları da.

Ürker herkes üşümüş bir anahtar olagelmekten

bir çocuğun şehri çarpar yüzümün varoşlarına.

(1964)', 'Gecenin dürüstlüğünden herkes kuşkulanır korkulur o kuş yüklü iniltilerden ve mor ağzını gecenin kumuna batıran ben çağdaş serüvenler adına ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-agri-yakildikca-sevilmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esenlik Bildirisi', 'esenlik-bildirisi-i-smet-ozel-wtxiv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şehrin urgan satılan çarşıları kenevir

kandil geceleri bir şehrin buhur kokmuyorsa

yağmurdan sonra sokaklar ortadan kalkmıyorsa

o şehirden öcalmanın vakti gelmiş demektir

Duygular paketlenmiş, tecime elverişli

gövdede gökyüzünü kışkırtan şiir sahtedir

gazeteler tutuklamış dünya kelimesini

o dünyadan, o şiirden öcalmalı demektir

Ölüm gelir, ölüm duygusuna karşı saygısız

ve zekâ babacan tavrıyla tiksinti verir

söz yavan, kardeşlik şarkıları gayetle tıkız

öcalınmazsa çocuklar bile birden büyüyebilir

Yargı kesin: Acı duymak ruhun fiyakasıdır

kin, susturur insanı; adına çıdam denir

susulunca tutulan çetele simsiyahtır

o siyah öcalmakcasına gür ve bereketlidir

Vandal yürek! Görün ki alkışlanasın

ez bütün çiçekleri kendine canavar dedir

haksızlık et, haksız olduğun anlaşılsın

yaşamak bir sanrı değilse öcalınmak gerektir.

1973', 'Bir şehrin urgan satılan çarşıları kenevir kandil geceleri bir şehrin buhur kokmuyorsa yağmurdan sonra sokaklar ortadan kalkmıyorsa o şehird...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/esenlik-bildirisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşatan', 'yasatan-i-smet-ozel-oy6cf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben halka bakinca gümüş tirnakli kisraklar

sirça kirpikli gelinler huylanir.

Ben halka bakinca terlenirim

yaslanirim tarlalarin gölgesine, tozuna

kirlenir gülkurusu mendilim.

Benim rengimle kim yarişabilir

sancimi kimler altedebilir ben halka bakinca?

Ben ki kazdim, küredim, ellerimle boşalttim geceyi

yildizlari, hüznü ordan firlatip attim,

sonra ordan firtinali bir tüzeyle halka bakinca

yeniden yaralandim dünya irmaklarindan.

Dünyanin irmaklari dedigim yer

aydinlik, gülümserlik ve sevda

Oysa halkin göz çukurlari çamurlanmiştir

kani ilgit ilgit akar, kani kara

yazlik sinemalarda, üniformalar altinda

banknotlarin, kiravatlarin saltanatiyla

çürütülmektedir halk.

Gözlerim 

ne güzeldir halka bakinca

gözlerimde bögürtlendir

avuçlarimda nar,

ayaklarini çiplatip sulardan geçen çocuklar

sevinçle kipirdatir yapraklarimi.

Halkim

piçaklanmiş bir kadin gibidir

kaygular içinde yapayalniz

zehirli çiçeklerin ugultusu

uzaklaşmaz kulaklardan.

Gözlerim

neden güzeldir halka bakinca

beni neden küflemez o çökertilmiş anlam

herdaim karnimda tikili duran şafak

dünyalar biriktirir halk adina?

Çünkü bana göbek bagimdan işliyor toprak

hançeri ellerinde neşter kilan

arkadaşlarim var daglarda.

Kara yerden kirmizi gelincikler biterken

leylekler kirlenirken bin bereket ugruna

şeffaf, bakire kizlar pencerelerden

kaçirilmak için elederken delikanlilara

o zaman benim gözlerim işte

kavi bir mavzer olur halka.

Kanima kizgin demirler sokulur

ben halka bakinca

Kömür kokusunda yüzlerim kabarir

kalbim uyanir gires lekelerinden

gök gürülder köleler kipirdanir

uykumun rengi yayilir dünyaya

uykum çünkü uçari, çünkü hovarda

şafaklarin öncesidir.

sazaklar içinde bir çocugu emzirir

çaputlara sarilmiş çürüksüz çocugu

ben halka bakinca.

Yaşamak güzeldir

gözlerim daha güzel

gözlerim daha güzel halka bakinca

ve sürülmüş topragi

yaratkan beyni

işleyen elleri huylandiran bakişlarim

yani insan türünün var kilan hiz

yani hatta tarlalarda

döl yataklarinda bile oyalanmayan

savaşin, sevdanin rengi

her güzellik bu rengin ardindadir

yaşamak bir başina bu rengi geçebilmez

''ölümden korkup da sonunu sayan

ölür gider yar koynuna giremez.''

(1969)', 'Ben halka bakinca gümüş tirnakli kisraklar sirça kirpikli gelinler huylanir. Ben halka bakinca terlenirim yaslanirim tarlalarin gölgesine, t...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/yasatan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-i-smet-ozel-9k6mi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüler beni serinliğe yakıştıramaz

çünkü hiç kimse çıkmak istemez bu mevsimden dışarı

çünkü bitkinliklerini günden saklar ekinler

ekinler çocukların en rahat uykuları

gece ayakları kokan bir adam gibi gelir

eşiklere oturmuş aya doğru çocuklar

o serin bereket gölgeleri çocuklar

yani çocuk o güzel tüccar

yorgunluklar alıp kargılar dağıtan

geceye karanlıktan önce gelen çocuklar

bu şaşkınlığı çünkü gece uyuyamaz

sanki ne kalmıştır çocuklara isa''dan

ölüler beni ölüme yakıştıramaz

gibi hala saçlarımda tozlu bir akşam.

(1962)', 'Ölüler beni serinliğe yakıştıramaz çünkü hiç kimse çıkmak istemez bu mevsimden dışarı çünkü bitkinliklerini günden saklar ekinler ekinler ço...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yorgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşun Ölümü', 'kusun-olumu-i-smet-ozel-f4jia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuş damdan düşünce

sarişin bir yürüyüşüdür artik ölümün

bir yagmurdur açilan kurakliga

bir yagmurdur kulübesi nisandan

ve onun ayaklarina dolanan o gökyüzü

kansiz yüzleridir diri kuşlarin

kuş düşünce camdan

kuş düşünce damdan

kizlar saçlariyla ölümü düşünürler

uzun bacakli tanrilar koşuşur sokaklarda

kuş öldü herkes mi ariyor

gençlik mi yürüyor herkese ve mi ariyor

onun gözlerini satilan çarşilarda

kuş öldü kanadinin altindaki o yara

yagmurun karanligini getiriyor geceye

yagmurun irmaklarini getiriyor geceye

kuş öldü

küçücük bir yorgunluktu ölmeden önce

öldü, kim isitir artik onun ellerini

sularin aynasinda üşüyen ellerini

sularin saygisiyla üşüyen ellerini.

(1962)', 'Kuş damdan düşünce sarişin bir yürüyüşüdür artik ölümün bir yagmurdur açilan kurakliga bir yagmurdur kulübesi nisandan ve onun ayaklarina do...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kusun-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Diyarı', 'mutluluk-diyari-filiz-turan-r6cmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün batıyor ,güneş kızıl olmuş

Denizle kucaklaşmış büyük bir hasretle

Bu güzelliği seyrediyorum usulca bir kıyıdan

Masmavi sularda kaybolup gidiyorum...

Çok uzak diyarlarda bir yer var biliyorum...

Mutluluk ırmağının aktığı, hiç tükenmediği bir yer...

Orada yağmurlar sevgi damlacıkları...

Yağdıkca gönüllere dolduruyor sevgileri...

Bu diyarda hiç tükenmiyor sevgi ve mutluluklar..

Ayrılmıyor asla ölesiye seven kalpler..

Orada herşey çok güzel....

Hayat başka bir hayat.....

 Gönüllerde huzur yüzlerde tebessüm var..

Gözyaşı ırmağı kurumuş bu diyarda akmıyor...

Acı nedir bilmiyor yürekler hep coşuyor..

Hüzün uğramamış buralara...

Heryer buram buram mutluluk kokuyor...

Gönüller hasret böyle bir diyarı arıyor....

keşke bulmak mümkün olsaydı.......', 'Gün batıyor ,güneş kızıl olmuş Denizle kucaklaşmış büyük bir hasretle Bu güzelliği seyrediyorum usulca bir kıyıdan Masmavi sularda kaybolup ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutluluk-diyari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayal', 'bir-hayal-filiz-turan-s5a50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzattım bak ellerimi, tut hadi! 

Al götür beni uzak diyarlara..

Açılsın sonsuzluğun kapıları ardına kadar..

Elele beraber girelim mutluluk ülkesine..

Kapat gözlerini..görüyormusun bak! ! 

Uçsuz bucaksız papatya tarlaları

Gökyüzü olmamıştı hiç bu kadar mavi..

Ilık bir meltem okşarken saçlarımızı..

Mis gibi çiçek kokularını duyuyormusun? 

Uzanalım, yatalım yemyeşil çayırlara..

Biz gökyüzünü seyredelim, kuşlarda bizi..

Bir şarkı mırıldan hafifçe kulağıma..

Ebediyen hiç aklımdan çıkmasın..

Elele koşalım yemyeşil kırlarda..

Soluğumuz tükenene  kadar..

Yüreklerimiz coşsun çocuklar gibi..

Sevgi yağmurları yağsın ıslatsın bizi...

Sen papatyalardan taç yap saçlarıma..

Onu her taktığımda seni hissedeyim yanımda...

Tuttuğun ellerimi sonsuza kadar sakın bırakma

Korkarak açtım gözlerimi sessizce...

Ne papatyalardan taç var başımda

Ne de sen varsın yanımda

Ne kırlar var uzanıp yattığımız

Ne de kuşlar var bizim  için kanat çırpan

Sevgi yağmurları tükenmiş...

Yürekler suskun ve sevgiye hasret....

Aralık 2000', 'Uzattım bak ellerimi, tut hadi!  Al götür beni uzak diyarlara.. Açılsın sonsuzluğun kapıları ardına kadar.. Elele beraber girelim mutluluk ü...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-bayram-karaali-u6gkd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesim bir yerlerde kayboldu nedense,

Topladınmı Canım onları darmadağınık,

Çatallaşmış kesik ve kısılmış seslerimi

Serdinmi bozkırlara,sokak ortalarına? 

Nergisleri yüreğimde yeşertmiştim,

Sana ta oralara göndermek üzere,

Ayağım takıldı,elim koynumda kaldı,

Yüreğimmi,sorma onu;o paramparça...

Ellerim boş,bakışlarım aptalca artık,

Neydi bu?nedendi anlatmadınki?

Ben yollarında gezerken yalnızlık,

O çıplak yalnızlık hakettiğim değildi...

(Aralık.2000)', 'Sesim bir yerlerde kayboldu nedense, Topladınmı Canım onları darmadağınık, Çatallaşmış kesik ve kısılmış seslerimi Serdinmi bozkırlara,sokak...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk Büyüyor', 'bir-cocuk-buyuyor-metin-vatansever-gphew', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çocuk görüyorum

Çıplak ayakları, yırtık gömleği ile oturmus

Oturmusta, elleri arasına almış yüzünü düşünüyor,

O küçücük kafasında binbir soru,

Elindeki dal parçasında filizlendiriyor düşüncesini,

Kimbilir belki bir gün büyüyecek bu dal diyor

Umut umut kök salacak toprağa

Kendini koyuyor o dalın yerine

''Ayaklarım toprakta bende fidanım'' diyor,

Neler geçiyor, neler geçecek aklından

Yüzünde anlamlı fakat acı tebessümünde

Günü yalanlıyor gibi, eğdiğinde başını,

Esaret zincirlerini düşünüyor,

Düşünüyor...

Sırtını dayamıs bir kayaya,

Küçücük bie tepe üstüne oturmuş,

Bu '' geçmişim'' diyor sırtını dayadığı kayaya,

Güneş arkasında,

Ha bu diyor ''bugünüm'' gölgelik oturduğu yere

Ve şu önündeki, şu iniş ''yarınım olacak'' diyor,

Çekinmiyor inmekten, gidecek yarınlarına,

Büyüme ile olacak, büyüyecek,

Büyüyecek...

Ve bir çığ gibi inecek yarınlarına,

Onun bu yarın, sahip çıkacak,

Ezmeden, ezdirmeden  kendini

Yaşamayı, insanca yaşamayı görüyor, biliyor,

Biliyor...

Ve kalkıyor kükrercesine,

Yüzüne güneş vuruyor şimdi,

Günün gölgesi yok üzerinde

Sıkıyor yumruklarını, küçücük,

Bileklerinden bir zinciri kırarcasına

Kalkıyor elleri havaya

İnecek bu yokuşu, yarını için

''Yarınım bu inişim'' diyor,

Bir adım atıyor,

İlk adımını

Umut dolu küçücük kalbi

Hırs dolu, susuyor,

Susuyor...

Daha güçlü çıkacak sesi, susuyor,

Daha güçlü çıkmalı,

Haksızlıklara karşı bağırmalı,

Biliyor, büyüyecek, haykıracak

Bu çocuk bir büyüse,

Ah bir büyüse...', 'Bir çocuk görüyorum Çıplak ayakları, yırtık gömleği ile oturmus Oturmusta, elleri arasına almış yüzünü düşünüyor, O küçücük kafasında binbir...', ARRAY['Türk Edebiyatı','Şiir','Metin Vatansever']::text[], 8.5, '{"poet":"Metin Vatansever","poet_slug":"metin-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-cocuk-buyuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyandaki Yüreğim', 'i-syandaki-yuregim-bayram-karaali-hgp1j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimseye kırgın değilim ben.

Hayata kızgın ve küskünüm,

Soframa kan doğrandı

İçkilerime zulüm ve zalim.

Gündüzüm yok gece karanlığında

Yalnızım seninle beraber,

O kadar kolaymı keder,

Buz gibi,sıcakmı sıcak solurken.

Gömdüm demiştim yüreğime,

Sinsice nereden geldi böyle

Yanıbaşımda sessiz ve durgun,

Bıçak sallıyorsun kollarımda..

Haketmedin sen bu ihaneti,

Namuslu genç ellerin yanımdaydı oysa,

Gecemin aydınlığı sendin oysa,

Gündüzümde korktuğum bulutlu havalardan

Sen çıkardın beni.Yüreğim doymadı.........

Adını sen koy sevdiğim.......

Bir yaman tutulmadayım vazgeçilmez,

En uçta seyrettik güneşin batışını,

Bana kıy,bıçağını salla yüreğime....

Hakettim ben,hakettim, sana göre,

Yüreğimi yirmibirlik gördüğün için,

Öyle değil bebeğim öyle değil,

Kavrulan,solan,isyanlardaki yüreğim......', 'Kimseye kırgın değilim ben. Hayata kızgın ve küskünüm, Soframa kan doğrandı İçkilerime zulüm ve zalim. Gündüzüm yok gece karanlığında Yalnız...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isyandaki-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Yaş Gençliği', 'orta-yas-gencligi-bayram-karaali-r8k0n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gelin nazlığıyla uçuşan,

Yürüdükçe kapı gıcırtıları inlemesinde.

Beyaz bembeyaz karlarımızla,

Göz kırpan sokak lambamız var.

Çıplak ellerimiz kenetlenmiş elele

Çocukluk yılları kadar şen,

Gençliğimiz kadar serkeş,

Ellerimizde kanyaklarımız var.

Yaşayamadık biz bu güzellikleri,

Yitik,soluk gençlik yıllarımızda.

Yeni tanıdım,yeni öğrendim,

Böyle Orta yaş isyanlarında.....', 'Bir gelin nazlığıyla uçuşan, Yürüdükçe kapı gıcırtıları inlemesinde. Beyaz bembeyaz karlarımızla, Göz kırpan sokak lambamız var. Çıplak elle...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/orta-yas-gencligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Götür Benide', 'al-gotur-benide-bayram-karaali-d73w9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al götür benide yaşadığın sıcak ülkelere

Üşüyorum  yüreğim titremekte

Masmavi  coşkun denizlere

Yeşil yapraklı ormanlarına.

Yitmek üzereyim nefessizliğimle

Bir öpücük istiyorum senden,

En lezzetlisi,en güzelinden,

Yaşam  veren  tüm içtenliğinle...', 'Al götür benide yaşadığın sıcak ülkelere Üşüyorum  yüreğim titremekte Masmavi  coşkun denizlere Yeşil yapraklı ormanlarına. Yitmek üzereyim ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/al-gotur-benide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Topla benim İçin', 'yagmur-topla-benim-i-cin-bayram-karaali-5t94m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur topladın  benim için bulutlardan,

Fırtınalar ektin sakin topraklarına yüreğimin,

Nadasa bıraktığım toprakları yüreğimin,

Ekim zamanı,sulanmaya aç doyumsuzluğu var.

Cimrice nadasa  bıraktığım bu toprakları,

Açtım; senindir artık,namuslu ellerinle,

Didikle,topladığın yağmurlarla sula artık,

Bire bin vermek cennetler yaratmak istiyor.

Saklama benden saklama,

Ne yağmurlarını,nede ellerini,

Sana hazır,seni bekledi,sabırla,namusla,

Ellerinle didiklenip,yağmurlarınla sulanmayı bekleyerek.!!!!

İnatlaşma benimle,yüreğinin yollarını kapama,

Yorgunum,orada dinlenip,dinlendirmek,

Ellerini ellerimde,başımı göğsünde istiyorum,

Dur deme bana,geleceğim kollarına.....', 'Yağmur topladın  benim için bulutlardan, Fırtınalar ektin sakin topraklarına yüreğimin, Nadasa bıraktığım toprakları yüreğimin, Ekim zamanı,...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-topla-benim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme', 'uzulme-mustafa-koca-wx51h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bir kez gülsen gülüm,

O gün ne kahreder ne üzülürüm,

Sen bir kez gülsen gülüm,

O gün hep güzellikleri görürüm.

Eğer sen üzülürsen,

Bu hayata küsersen,

Bir damla gözyaşı dökersen,

Ben ölürüm...', 'Sen bir kez gülsen gülüm, O gün ne kahreder ne üzülürüm, Sen bir kez gülsen gülüm, O gün hep güzellikleri görürüm. Eğer sen üzülürsen, Bu ha...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzulme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rest', 'rest-mustafa-koca-p8jux', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Restim insanlara, kalpleri ayıranlara,

Saf sevgide çıkar arayanlara,

Mutluluğa karşı kör olanlara,

Ayrılık ile sevginin biteceğini sananlara.

Sözüm size insanlar bir deliyiz,

Paylaşmayı en iyi biz biliriz,

Ayrılsa da önce gözler, sonra eller,

Hasret bile bitiremez, bu kalpler sevgiyi söyler.

(2000)', 'Restim insanlara, kalpleri ayıranlara, Saf sevgide çıkar arayanlara, Mutluluğa karşı kör olanlara, Ayrılık ile sevginin biteceğini sananlara...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rest-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-mustafa-koca-ng4va', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin bir kor gibi yakar içimi,

Gel söndür, neredesin gülüm,

Sensiz yok sayıyorum kendimi,

Gel de bul beni, neredesin gülüm.

Gecelerim kederle sabah olur sensiz,

Sensiz yıldızlar bile sessiz,

Beni buralarda bıraktın kimsesiz,

Bitir bu ızdırabı, neredesin gülüm.

(2000)', 'Hasretin bir kor gibi yakar içimi, Gel söndür, neredesin gülüm, Sensiz yok sayıyorum kendimi, Gel de bul beni, neredesin gülüm. Gecelerim ke...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seren Direğim Kırık', 'seren-diregim-kirik-bayram-karaali-8v01i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seren direğim kırık yelkenlerim tutmuyor artık,

Denizlerim kan denizi ateşler içindeyim,

Gözlerim tayfun patlamasında gece karanlık

Lumbozlarım darmadağın su almadayım....

Bir bilinmez yolculuğa çıktım rotamda şaşkınım,

Kabuslar nedirki yürek ağlamasında

Işıksızım,fenerlerde yok burunlarda,

Karaya vurdum fiyortlara çarptım....

Gözlerime göz olan,rotama kaptan,

Yelkenlerime rüzgar,titremelerime,

Sıcacık battaniye,fenersizliğime ışık,

Yok artık yok,yolculuk bir bilinmeze.....

CESARETİMDE YOK ARTIK,ROTALAR ŞAŞKIN,

YELKENLERİ TÜMDEN İNDİRDİM  YERLERE,

SAVRULUP YOK OLSUN,İSTEMİYORUM ARTIK,

DERİN DENİZLERDE BOĞULUP YOK OLMAK....', 'Seren direğim kırık yelkenlerim tutmuyor artık, Denizlerim kan denizi ateşler içindeyim, Gözlerim tayfun patlamasında gece karanlık Lumbozla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seren-diregim-kirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-mustafa-koca-c2ug6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdam yüreğimde bir çiçek,

Bir nazlı gül, bir kelebek,

Günü gelince oda yeşerecek,

Gel sevdamın suyu, toprağı ol.

Sevdam yüreğimde bir hasret,

Bir özlem, bir davet,

Günü gelince bitecek sükunet,

Gel sevdamın vuslatı ol.', 'Sevdam yüreğimde bir çiçek, Bir nazlı gül, bir kelebek, Günü gelince oda yeşerecek, Gel sevdamın suyu, toprağı ol. Sevdam yüreğimde bir hasr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-mustafa-koca-8gwur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklar yarim artık,

Çünkü sen uzaklarsın,

Bir bilinmeyen yerdesin,

Yağmur yüklü bir bulutum ben ise,

Arıyorum seni bir kuş kanadında,

Bir bahar yelinde,

Bir vedan bile yok gönlümde,

Ve kulağımda yok son bir sedan,

Elimde olan varlığın, bütün benliğimde.

Şimdi sen uzaklarsın,

Şimdi sen uzaktasın,

Ben ise sensiz yokum zaten.', 'Uzaklar yarim artık, Çünkü sen uzaklarsın, Bir bilinmeyen yerdesin, Yağmur yüklü bir bulutum ben ise, Arıyorum seni bir kuş kanadında, Bir b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul Beni', 'bul-beni-mustafa-koca-wkymn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde bir avuç yürek, birde kendim,

Bütün varlığım benim bu sevgim,

Çırp kanatlarını uç bana,

Yırt kılıfını ürkek olma.

Kavuş bana; ben gülüm, bülbül ol,

Koş bana; ben sahilim, dalga ol,

Uç bana; ben denizim, martı ol,

Bul beni; ben hasretim, vuslatım ol.

Kavuştur gecemi sabaha,

Buluştur gözlerini yıldızlarla,

Ver yüreğini bulutlara,

Yağsın sevgiye susamış gönlüme.

Bul beni seni arıyorken,

Bul beni sana hasretken,

Ya da yolla selamını yıldızlara,

Hasret yıldızı alır getirir bana.', 'Elimde bir avuç yürek, birde kendim, Bütün varlığım benim bu sevgim, Çırp kanatlarını uç bana, Yırt kılıfını ürkek olma. Kavuş bana; ben gül...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bul-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedin', 'bilemedin-mustafa-koca-ksxzt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bilemedin sevmeyi,

Belli edemedin belki de,

Veremedin değer duygularıma,

Tek şey düşündün, kendini,

Ve beni kendin için sevdin.

Sen bilemedin paylaşmayı,

Tek varlığın kendin,

Ben anlatırken derdimi,

Sen gülüp geçtin sadece,

Anlamadın anlayamadın,

Sen bilemedin sevgine de değer vermeyi,

Ama dedin ki ölürüm senin için,

Ben ise sonuna kadar yaşarım,

Sevdiğim için, seven için,

Ölüm peşin hasret, yaşamak ise kavuşma umududur.

Sen kazanmayı bilemedin,

Paylaşmayı öğrenemeden,

Sevmeyi değer vermeyi başaramadan,

Ben uçarken veya kaçarken ellerinden,

Sen üzülmeyi bile beceremeyeceksin.', 'Sen bilemedin sevmeyi, Belli edemedin belki de, Veremedin değer duygularıma, Tek şey düşündün, kendini, Ve beni kendin için sevdin. Sen bile...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilemedin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Zamanı', 'gitme-zamani-mustafa-koca-4p2dz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitme zamanı yine kaçma zamanı,

Ve hasret yine en iyi dostum,

Zor olan bırakmak geride duyguları,

Bir türlü anlaşılmayan ise o duygular.

Gitme zamanı yine kaçmak zamanı,

Ve gülerken bile gizli gülmek,

Anlarken bile anlamamış gibi olmak,

Zor olan ağlarken saklayabilmek yaşları.

Gitme zamanı yine kaçmak zamanı,

Mutluluğu da bırakmak öksüz,

Ve düşünmemek martıları,

Zor olan hasret yıldızını görmemek.

Gitme zamanı yine kaçmak zamanı,

Ait olmadığım dünyadan uçmak zamanı,

Gitmek ama unutmamak SÖZLERİ,

Ve bir de ...', 'Gitme zamanı yine kaçma zamanı, Ve hasret yine en iyi dostum, Zor olan bırakmak geride duyguları, Bir türlü anlaşılmayan ise o duygular. Git...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-mustafa-koca-qxcrj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen bırakırım akışına hayatı,

Bakarım bir seyirci gibi,

Bazen karşılarım ayakta,

Yaşarım sonuna kadar.

Bazen kaçarım insanlardan,

Bazen korkarım anlamayanlardan,

Bazen susarım sadece,

Bazen ise bir gülümseme.

Bazen yaşarım sevgiyi kalbimde,

Bazen ise taşırım hüznü gönlüme,

Bazen gider birileri,

Bazen ise gelir yeni umutlar,

Bazen bakar geçerim,

Bazen güler ağlarım,

Bazen duygulanırım veya kızarım,

Bilinmeli ki BU BENİM HAYATIM...', 'Bazen bırakırım akışına hayatı, Bakarım bir seyirci gibi, Bazen karşılarım ayakta, Yaşarım sonuna kadar. Bazen kaçarım insanlardan, Bazen ko...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bazen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine mi ?', 'yine-mi-mustafa-koca-x9k6s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine mi yollar göründü,

Yine mi gitme zamanı,

Yine kaçma zamanı belkide,

Ama giderken kalmak zor olan.

Kalmak bir yerlerde,

Gönlümü bırakmak,

Kendimi bırakmak,

Gitmek gidiyor gibi yapmak.

Al kalbimi,

Alda öldür,

İşte o zaman,

Gerçekten giderim...

Unuturum o zaman belki de,

Belki de hatırlamam,

O yüzden al öldür kalbimi,

Çünkü içinde sen varsın...', 'Yine mi yollar göründü, Yine mi gitme zamanı, Yine kaçma zamanı belkide, Ama giderken kalmak zor olan. Kalmak bir yerlerde, Gönlümü bırakmak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitir Hasreti', 'bitir-hasreti-mustafa-koca-2ea3d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamlarda sakladım hüznünü,

Her gün bekledim geliş gününü,

Sensiz yaşamadın ne dünü ne bugünü,

Çok mu zor gel artık bitir hasreti

Yıldızlara eş tuttum sevdamı,

Yaşattım kalbimde senli her anı,

Geride bıraktın biraz hüzün biraz anı,

Çok mu zor gel artık bitir hasretti.

Bir bakışını, bir gülüşünü özledim,

Mutlu ederdi beni sözlerin,

Gel desen dağları aşar gelirim,

Çok mu zor gel artık bitir hasreti.', 'Akşamlarda sakladım hüznünü, Her gün bekledim geliş gününü, Sensiz yaşamadın ne dünü ne bugünü, Çok mu zor gel artık bitir hasreti Yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Koca']::text[], 8.5, '{"poet":"Mustafa Koca","poet_slug":"mustafa-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitir-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Sevgisi-2-', 'anne-sevgisi-2-bayram-tunca-a4gv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk Dünyaya senin vesilenle geldim

İlk ab-ı hayat gıdamı senden aldım

İlk sıcak yatak tadını sinende tattım 

İlk korku/endişemi sayende atlattım 

İlk konuşmayı senin dilinden öğrendim

İlk yürümeyi senin ayağından öğrendim

İlk tebessümü senin cemalinde gördüm

İlklerimi iliklerimde senin sayenle tattım

İlk azalarımı kullanmayı senden öğrendim

İlk jimnastik hareketimi senden öğrendim

İlk mimik hareketlerimi senden öğrendim

İlklerimi senden görüp, senden öğrendim

Gözümü açar açmaz ilk güzel seni gördüm

Güzelliğinle belleğimin peteğine doldurdum

Ailemizde de en çok seni sevmeyi aşk ettim

Dövsen de öf dememeyi ahtı peyman ettim

Düştüğüm ve ağladığımda ilk seğirten sendin

Beni ilk defa edep adabı öğreten, yine sendin

İlklerimi iliklerimde tattırıp haz aldıran sendin

Sen benim başımın tacı gönlümün sultanıydın

Ana olmanla, başıma taç, derdime ilaç, oldun

Ana olmanla, övüneceğim, iffet abidem oldun

Anne olmakla, övülen şefkat kahramanı oldun

Sen benim iyilik meleğim, göz bebeğim oldun

Ah sen benim her şeyim olmana rağmen, anne

Bense, sana lâyık bir evlat olabildim mi acaba? 

Eğer lâyık bir evlat olabildimse, ne mutlu bana 

Yoksa ne etsem dahi hakkını ödeyemem  anne

Gördüm en iyi Allah kelamı Kur’an anlatıyor seni

Ben de anlatmak isterdim, en güzel  şekilde seni

Her beşerin sözü gibi sönük kalır anlatmam seni

Ama beşikten mezara kadar seveceğim ben seni

Hakkını helal et, hakkıyla yine anlatamadım seni

Çok istedimse de yine bu kadar anlatabildim seni

Ne edem kelamım da bu kadar ifade edebilir seni

Ezelden ebede kadar aynı şekilde seveceğim seni

B. TUNCA/18.12.2000-16.25', 'İlk Dünyaya senin vesilenle geldim İlk ab-ı hayat gıdamı senden aldım İlk sıcak yatak tadını sinende tattım  İlk korku/endişemi sayende atla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/anne-sevgisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Neredesin', 'sen-neredesin-bayram-tunca-2m31k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne gündüzlerimde, ne gecelerimde

Ne hülyalarımda, ne de rüyalarımda

Ne düşlerimde, ne de düşüncelerimde

Beni yalnız bırakmayan sen neredesin

Ne karlı dağlarda, ne de düz ovalarda

Ne toprak kokulu karada, ne semada 

Ne sı Denizlerde, ne de Ummanlarda

Beni yalnız bırakmayan sen, neredesin

Ne akşamlarımda ne de sabahlarımda

Ne yaz aylarımda, ne de kış aylarımda

Ne ilkbahar ne de sonbahar aylarımda

Beni yalnız bırakmayan sen, neredesin

Ne uyanıkken, ne de mışıl mışıl uyurken

Ne hazin hazin ağlarken, ne de gülerken

Ne iyi günüm, ne de kötü günümdeyken

Beni yalnız bırakmayan Leyla neredesin

Yoksa, sen çöllerde görülen serap mısın

Yoksa, her an takip eden, gölgem misin

Yoksa, rüyalarımı süsleyen o peri misin

Beni yalnız bırakmayan Leyla neredesin

Yoksa denizlerdeki kaybolan dalga mısın

Yoksa denizlerdeki mercan kayalık mısın

Yoksa kırlardaki açan yaban çiçeği misin

Yoksa hep hayal ettiğim, güzel sen misin

Yoksa, semada yalancı yağmur bulutu musun

Yoksa, geceleri yanıp sönen ateş böceği misin

Yoksa, bir mevsimlik açıp solan kır çiçeği misin

Beni hiç yalnız bırakmayan Leyla sen neredesin

Ah bir çözebilsem, sen kimsin, neyin nesisin

Dost musun yada dost gözüken düşman mısın

Sen, hayattaki çözemediğim yegâni bilmecesin

Beni hiç yalnız bırakmayan Leyla sen neredesin

Gel desem gelmezsin, git desem gitmesin

Sen yıllarca hülya ve rüyalarımı süslersin

Ben beklemekten usandım, sen hâlâ gelmezsin

Yıllarca, hasretinden ne çektiğimi bilmez misin

B. TUNCA/18.12.2000-11.55', 'Ne gündüzlerimde, ne gecelerimde Ne hülyalarımda, ne de rüyalarımda Ne düşlerimde, ne de düşüncelerimde Beni yalnız bırakmayan sen neredesin...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-neredesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelecek', 'gun-gelecek-nurhayat-kalpakoglu-7spis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün gelecek bizde toprağa 

Kavuşacağız

Üzerimize yağmur yağacak,

Güneş açacak,

Rüzgar esecek.

Belki bir papatya yaprağında

Belki bir ağaç dalında 

Tekrar yeşeraceğiz,

Taki hayat devam ettiği sürece

Bir daha nasıl ne zaman 

Olur bilmem ama,

Yine beraber mutlu olacağız

Ve  yine yeni ufuklara açılacağız,

yalnız doğal ve saf kalacak şey

O vazgeçilmez sevgimiz ve aşkımız olacak

O bizimle her zaman her yerde 

Hep var olacak ,

Taki biz var olduğumuz sürece....', 'Gün gelecek bizde toprağa  Kavuşacağız Üzerimize yağmur yağacak, Güneş açacak, Rüzgar esecek. Belki bir papatya yaprağında Belki bir ağaç da...', ARRAY['Türk Edebiyatı','Şiir','Nurhayat Kalpakoğlu']::text[], 8.5, '{"poet":"Nurhayat Kalpakoğlu","poet_slug":"nurhayat-kalpakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gun-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda', 'uzaklarda-adil-koruyan-6jfw5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklarda, çok uzaklarda,

Kuşların bile ulaşamayacağı,

Gecenin koyu karanlığında,

Seni düşledim yatağımda.

Yanımda olmanı isterdim.

Yastığımı paylaşmak.

Kaybolmak, dağılmış saçlarında,

Öldüresiye bir tutkuyla

Tenine her dokunuşunda,

Yanımda olmanı istedim,

Kollarımın arasında....', 'Uzaklarda, çok uzaklarda, Kuşların bile ulaşamayacağı, Gecenin koyu karanlığında, Seni düşledim yatağımda. Yanımda olmanı isterdim. Yastığım...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzaklarda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oracıkta', 'oracikta-yasemin-dogrubakar-0kupi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sığınak olsun geceler kabuslarına

Saatlerce beni düşün yanlız başına

Aklına geldikçe bana ettiklerin 

Kahrol hatta öl oracıkta

Gülmek hayal olsun sadece

Mutluluk masallardaki kaf dağı olsun sana

Bana ulaşmaya çalıştıkça batağa gir

İçin erisin bir gülüşüme, kor ol yan oracıkta

Beni sevdiğini kaybedince anla

Anlaki paramparça olsun yüreğin

Kahret benle iken bensiz geçen zamanlarına

Gözlerin beni arasın her yanlız kalışında

Sancılarsarsın tüm bedenini 

Saçlarına aklar düşsün hayatının baharında

Gözlerinden iki damla yaş aksın ilk kez birine

Beyaz gelinliğimle başkasının olduğumu gördüğün anda

İsyanlar savur kendi zalimliğine

Geceleri resmime bak, yatağının baş ucuna koy

Birgün kolumda başkasıyla geçtiğimde yanından 

Eğ başını önüne kendinden utanç duy

Bunlar son sözlerim olsun sana

Düşündükçe beni yankılansın kulaklarında

Gözlerini yumarken hayata tekrarla son nefesinde 

Herkese haykır sevgime geçiken sadakatini yeminlerle

Kazılsın bana ettiğin yeminler öldüğün gün

Başucundaki mermere', 'Sığınak olsun geceler kabuslarına Saatlerce beni düşün yanlız başına Aklına geldikçe bana ettiklerin  Kahrol hatta öl oracıkta Gülmek hayal ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oracikta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Galip Geldi Gurur', 'aska-galip-geldi-gurur-yasemin-dogrubakar-depgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi yalan sevgi basit sevgi umutsuz yarınlarda gizli

Yokla var arası sıkışmış derin boşluklarda

Her gece ağlasamda gizliden  gizliye ayrılığa 

Elden bir şey gelmez Aşka galip geldi gurur

Gülücükler yalan gülücükler basit gülücükler umutsuz artık

Sahipsiz dudaklarda gizlenmiş gözyaşlarıyla içiçe

Her an canımı yaksada amansız yokluğun 

Elden bir şey gelmez Aşka galip geldi gurur

Ayrılık zor ayrılık dile kolay ayrılık vefasız gözlerde gizli

Zehirli kan misali dolaşır durur canımda

Her nefeste bir ömür çalar götürür seni benden

Elden ne gelirki Aşka galip geldi gurur', 'Sevgi yalan sevgi basit sevgi umutsuz yarınlarda gizli Yokla var arası sıkışmış derin boşluklarda Her gece ağlasamda gizliden  gizliye ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aska-galip-geldi-gurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim', 'askerim-yasemin-dogrubakar-f9e4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerini düşlerimden hiç eksik etmem geceler boyu

Yanımdaymışsın gibi severim seni inan

Yorgun düşsede gözlerim gecelerce ağlamaktan

Seni özlemekten inan hiç bıkmam askerim

Kokun tenimde tutsak kalacak 18 ay

Ellerim ellere yasak olacak inan

Bir umut bir sevgi bir tutku kalacak senden bana hatıra

Bana uzak olsanda inan sözümü unutmam askerim

Sen gecelere sığın benden uzakken

Ayışıyla dertleş yokluğumu 

Fırsat buldukça beni hayal et bıkıp usanmadan

Ben seni hep beklerim inan askerim', 'Gözlerini düşlerimden hiç eksik etmem geceler boyu Yanımdaymışsın gibi severim seni inan Yorgun düşsede gözlerim gecelerce ağlamaktan Seni ö...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar Ne Bilir Seni Sevmenin Tadını', 'onlar-ne-bilir-seni-sevmenin-tadini-yasemin-dogrubakar-w7bye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlar hiç koca kalabalıklarda yapayalnız kaldımı ?

Geceler boyu yanlızlıklarıyla başbaşa ağladımı?

Hiç silip tüm gülücükleri masum yüzlerinden 

Heyecanını bir telefona mahkum bıraktımı 

Onlar hiç hasreti damarlarında hissetti mi ki?

Başını yastığa koyupta saatlerce uykuyla savaştı mı ?

Bakıp bakıp bir cansız resme seni seviyorum dedi mi

Onlar hiç kavuşmanın acı sabırsızlığını yaşadı mı ki?

Onlar hiç öksüz kaldımı ki hayatta 

Bir yanları eksik kaldımı can damarları kesildimi?

Bir yoksulluktur aldımı ki akıllarını

Onların hiç canı yandımı ki adını anarken

Onlar sevmenin aziz yanını tattımı ki 

Kilometrelerce uzaktan tenlerini hissettimi ki sevdiklerinin

Bir mektubu  usanmadan okudumu defalarca satır satır

Ya Bırakıp tüm kabusları geceye 

Rüyaların en güzelini sevdiğine ayırdımı ki onlar

Ne bilir  onlar bir telefonun verdiği mutluluğu

Onlar hiç asker yolu gözledimi ki

Ne bilir onlar vuslatın hava kadar nefes kadar değerini

Onlar hiç asker sevgilisi oldumu ki

Boşver onları onlar ne bilir seni, ne bilir candan sevmeyi

Bir sor bakalım;

Onlar benim seni sevdiğim kadar kimseyi sevdilermi?', 'Onlar hiç koca kalabalıklarda yapayalnız kaldımı ? Geceler boyu yanlızlıklarıyla başbaşa ağladımı? Hiç silip tüm gülücükleri masum yüzlerind...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/onlar-ne-bilir-seni-sevmenin-tadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulüm', 'zulum-yasemin-dogrubakar-3okhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanla alışıyor insan

Hangi yüze baksan ihanet

Sevgileri kim çaldı ki bizden 

Kimden bu zulüm bu eziyet

Bir damla gözyaşına sığınmış gülücükler

Sevgi hangi yürekte saklı görülmez

İblis olmuş dost bildiğin yüzler

Melekten geçtik, insanlık nerede bilinmez

Ağlamayı unutmuş gözler gülmeyide

Hasetlere bürünmüş, küflenmiş güzelim yürekler

Kim dert etti bize gülücükleri

Söyleyin kimin bu acı çığlıklar

Ne umutlar tükettik sevgi adına

Herbiri anı sadece yüreklerde

Bir kırık basamak kaldı geride

Bastımı göçecek bir ömür ile

Yüreklerdeki küflü bencillikte', 'Zamanla alışıyor insan Hangi yüze baksan ihanet Sevgileri kim çaldı ki bizden  Kimden bu zulüm bu eziyet Bir damla gözyaşına sığınmış gülücü...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zulum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerim Tekin', 'kerim-tekin-yasemin-dogrubakar-maj4k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğuna eşledim yalnızlığımı 

Gittin gideli sen kokuyorum buram buram

Her yanımda bir ölüm sayfası açtı o hayalin

Oysa varlığında da yoktun hayatımda

Zaten ben senin dünyadaki yokluğunda bende varolmanı sevdim.

Gidişindeki çığlık kaldı kulaklarımda 

Senden ilk ve son hatıra

Bir ölüm havası bir karanlık furyası saldın uykularıma

Oysa sen varlığında yoktun uykularımda

Zaten ben senin masumca ölümünü sevdim.

Sürekli bir senfoni bıraktın son deminde hayatının

Geceler gitmedi hayalin gözlerimden

Dinlerken ilahi bir ses misali melodi gibi sesini

Oysa sen varlığında kıymet bildiremedin

Zaten ben senin ölümünle bana yaklaşmanı sevdim

Bir çığlığın kaldı kulaklarımda bir soluk tebessümün yanımda

Bir resimlerin kaldı hatıra senden bana 

Oysa sen benim gibi dostu yaşarken bilemedin

Zaten ben senin hayata elveda derken bana merhaba demeni sevdim.

Ben senin karagözlüm derken ilah olmanı değil 

Göçüp giderken hayattan KERİM TEKİN’ liğini atıp kenara

Bir mucize ile bana ulaşmanı sevdim.

.

Gidişindeki çığlık kaldı kulaklarımda 

Senden ilk ve son hatıra

Bir ölüm havası bir karanlık furyası saldın uykularıma

Oysa sen varlığında yoktun uykularımda

Zaten ben senin masumca ölümünü sevdim.

Sürekli bir senfoni bıraktın son deminde hayatının

Geceler gitmedi hayalin gözlerimden

Dinlerken ilahi bir ses misali melodi gibi sesini

Oysa sen varlığında kıymet bildiremedin

Zaten ben senin ölümünle bana yaklaşmanı sevdim

Bir çığlığın kaldı kulaklarımda bir soluk tebessümün yanımda

Bir resimlerin kaldı hatıra senden bana 

Oysa sen benim gibi dostu yaşarken bilemedin

Zaten ben senin hayata elveda derken bana merhaba demeni sevdim.

Ben senin karagözlüm derken ilah olmanı değil 

Göçüp giderken hayattan KERİM TEKİN’ liğini atıp kenara

Bir mucize ile bana ulaşmanı sevdim.', 'Yokluğuna eşledim yalnızlığımı  Gittin gideli sen kokuyorum buram buram Her yanımda bir ölüm sayfası açtı o hayalin Oysa varlığında da yoktu...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kerim-tekin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-yasemin-dogrubakar-fhekk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bende başladı sende bitti sevdalar

Meğer sevdayı zalime yar etmişler

Gözlerimi kör ederken sevgin ve sen

Nerden bilirdim ben, zulmeti senle giydirmişler

Yüreğimi açtıkça sana dürüstükle mertçe 

Sen en  derin yerine hançer vurmuşsun

Ben, sen ağladıkça kahrımdan ölürken

Sen halime bakıp içten içe gülmüşsün

Sevgiyi zalime teslim etmişler geri vermez

Elini kolunu zincire vurmuşlar kaçıp gelemez

Uzaklaşıp gitmek istersin zulmünden izin vermez

Bilmezdim ben o yari zulümle beslemişler', 'Bende başladı sende bitti sevdalar Meğer sevdayı zalime yar etmişler Gözlerimi kör ederken sevgin ve sen Nerden bilirdim ben, zulmeti senle ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zalim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-yasemin-dogrubakar-h0ztx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'öylesine masum dizlerimde yatma içim eriyor,

seyre dalıp gözlerimi, düşünme içim gidiyor,

sevmeyi öğreniyoruz bir sevda boyu şuracıkta

gülümseyip gözlerime kaçıp gitme neolur

dayanamıyorum içim ölüyor.', 'öylesine masum dizlerimde yatma içim eriyor, seyre dalıp gözlerimi, düşünme içim gidiyor, sevmeyi öğreniyoruz bir sevda boyu şuracıkta gülüm...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bebegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-yasemin-dogrubakar-gepj4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlamalarım, yakarışlarım boşuna; gidiyorsun

Can gidiyor canımdan, sen gidiyorsun

Bir gül soluyor yanağımda 

Ben ağlıyorum sen gidiyorsun

Sen gidiyorsun bebeğim bütün yaşam gidiyor

Çiçekler soluyor bahçemde baharlar güze dönüyor

Öpmeye kıyamadığım dudakların  toprak oluyor

Nefesler tükeniyor sen gidiyorsun

Tutamadım ellerini yakalayamadım gidiyorsun

Ölümle pençeleşmeden usulca gidiyorsun

Direncin mi yok yoksa ölmek mi kolay 

Kal diyemem bir nefeslik candasın, işte gidiyorsun

Gitme bebeğim canımdan can gidiyor

Gülümseme giderayak ölüme içim nefret güdüyor

Silme yaşlarımı yaş değil kan gidiyor

Sen gidiyorsun bebeğim ömrüm gidiyor..........', 'Ağlamalarım, yakarışlarım boşuna; gidiyorsun Can gidiyor canımdan, sen gidiyorsun Bir gül soluyor yanağımda  Ben ağlıyorum sen gidiyorsun Se...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Doğrubakar']::text[], 8.5, '{"poet":"Yasemin Doğrubakar","poet_slug":"yasemin-dogrubakar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf''tan Tülay''a', 'yusuf-tan-tulay-a-yusuf-ziya-akalin-6tgw2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENİ SEVDİM AMA SENDE SEVMEKTEN ÇOK BİR ACI  BİR SIZI KALDI BANA

Tam iki sene biliyormusun 

senden gelecek cevapla 

Kendimi avuttum 

şimdi ise sadece senle karşılaşmama iki hafta kaldı

şuan ne yapıyosun bilmiyorum ama senin hasretinle kavrulan ama  hala ölmeyen birisi var

belkide sadece kendimi avutuyorum 

olsssun böylede güzel

İNSANI YAŞLANDIRAN YAŞADIGI YILLAR DEĞİL 

ULAŞAMADIĞI UMUTLARIDIR', 'SENİ SEVDİM AMA SENDE SEVMEKTEN ÇOK BİR ACI  BİR SIZI KALDI BANA Tam iki sene biliyormusun  senden gelecek cevapla  Kendimi avuttum  şimdi i...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Akalın']::text[], 8.5, '{"poet":"Yusuf Ziya Akalın","poet_slug":"yusuf-ziya-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yusuf-tan-tulay-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK''A NASİHAT', 'ask-a-nasi-hat-ersin-gurdal-om06a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Süzülürdü bulutların damlaları yanaklarından

Göz kırpardın hayata, yaşama sevinci varken gözlerinde..

Bir cansız resim vardı elimde.

Resmin içindekini yaşıyor ve görüyordum ya karşımda,

Seni sevdiğimi biliyor ve uyguluyordum seninle hayata karşı,

Gözgöze gelip bakışırdık ya arasıra.

Sanki kulaklarımda yaprakların hışırtısını duyar olurum mutlulukdan,

Hani seni seviyorum ya. Hani ara sıra söylüyorum ya gözlerimi konuşturup dudaklarımla,

İşte öyle bir şey ki bu sevmek, söylenmesi bile güç gelir insana

Ama sadece ''''seni seviyorum'''' diyebilirsin.

Oysa anlatmak isteyipte anlatamadıkların vardır aşk ve sevdaya dair.

Anlatmak istersin ama , kelimelerle anlatılamayacak olduğunu anlarsın zamanla.

HareketLerini denersin kuşkulanırsın..ya yapamassam diye.

Aşk öyle büyüktür ki..

Aynaya bakarak kendinle bile konuşabilirsin onun hakkında.

Sevgilinle buluşurken süslenmen,

El ele tutuşurken gülümsemen,

Gece yatarken aklında içini hoş yapan o duygu bile

Aşkın tohumlarındandır aslında.

Sevdiğin insanı yüceltmen, ona saygı duyman, ve gerçekten sevmen,

Aşkın sana getirdiği saadetin bir parçasıdır.

Dedim ya sevmek güzel şeydir diye,

Sevdiği ve sevildiğin zaman sende anlarsın sevdiğim.', 'Süzülürdü bulutların damlaları yanaklarından Göz kırpardın hayata, yaşama sevinci varken gözlerinde.. Bir cansız resim vardı elimde. Resmin ...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gürdal']::text[], 8.5, '{"poet":"Ersin Gürdal","poet_slug":"ersin-gurdal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-a-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümsüyor Maskeler', 'gulumsuyor-maskeler-onder-karadag-sr66l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'inadına güzel hava

ve ben içerdeyim

eski bir yağmur yağarken ömrüne

ardahanlı bir genç kızın

dalgasız saçlarında yalnızlık

ve gözlerinde hüzün

seni hala seviyorum

bütün çocukların yüzünde çocukluğum

anarşist gençliğim of...

ve ben içerdeyim

gülümsüyor maskeler..', 'inadına güzel hava ve ben içerdeyim eski bir yağmur yağarken ömrüne ardahanlı bir genç kızın dalgasız saçlarında yalnızlık ve gözlerinde hüz...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gulumsuyor-maskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeç Gönlüm', 'vazgec-gonlum-orhan-gencebay-h9xg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vazgeç gönlüm sen bu aşktan

sana kıymet verenmi var

unut dertten zevk almayı

seni ancak seven anlar

kapat çile kapısını girmesin o vefasızlar

dünya denen şu hanaden elbet seni biri anlar

sen attın bu kör düğümü

çare sende bende değil

kör olsun şu aşkın gözü

hata bende sende değil', 'vazgeç gönlüm sen bu aşktan sana kıymet verenmi var unut dertten zevk almayı seni ancak seven anlar kapat çile kapısını girmesin o vefasızla...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vazgec-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Görüşte Aşık Oldum', 'bir-goruste-asik-oldum-orhan-gencebay-c3ivl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir görüşte aşık oldum sana delice

bekliyorum gelmiyorsun bana bir gece

ıstırabım diner benim geldiğin gece

ağlıyorum gülmüyorum inan her gece

acı çektirmekmi bana maksadın zalim

senden başka yoktur benim tutacak dalım

gel elinle öldür beni çektirme yeter

hergün zulmunden perişan olmadan halim', 'bir görüşte aşık oldum sana delice bekliyorum gelmiyorsun bana bir gece ıstırabım diner benim geldiğin gece ağlıyorum gülmüyorum inan her ge...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-goruste-asik-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürdün Beni', 'oldurdun-beni-orhan-gencebay-avd9j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen bu aşka bu sevgiye laik değilsin

gönlüm yalan olan aşka neden eğilsin 

çekil artık yolumdan el sürme bana 

sen ellerin malısın benim değilsin

nerden gördüm seni nerden sevdim seni

bütün arzun bumuydu öldürdün beni

son ümidim sendin benim bana gülecek

şimdi bu ıstırabımı kim dindirecek

işlediğin günahları bir gün mahşerde

ben değil sevdiğim sensin çekecek', 'sen bu aşka bu sevgiye laik değilsin gönlüm yalan olan aşka neden eğilsin  çekil artık yolumdan el sürme bana  sen ellerin malısın benim değ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oldurdun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Güneşi', 'aksam-gunesi-orhan-gencebay-otbu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'batarken ufukta bir akşam güneşi

bırakıp gitmiştin beni sen sevgilim

yıllar yılı oldu hala dönmedin geri

ne olur neolur dönbana

bak batıyor yine akşam güneşi

aşkımı dillerde gözümü yollarda

kimsesiz bıraktın şu gurbet ellerde

sanki kara bulut seni saklıyor benden

ne olur neolur dön bana 

yine gölgelendi akşam güneşi', 'batarken ufukta bir akşam güneşi bırakıp gitmiştin beni sen sevgilim yıllar yılı oldu hala dönmedin geri ne olur neolur dönbana bak batıyor ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aksam-gunesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata', 'hayata-ahmet-sahin-soner-lb56n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün herşey geçer güzel olur hayat

Dönüp arkana baktığında gıcıklık olsun diye

Sırf çekilenlere inat sırıtırsın hayata

Hızını alamaz birde dil çıkartırsn 

Sokaklar boyu koşarsın mutluluğunla 

Çocuk olursun, çocuk yaşarsın

Mutluluğun sihrini unutmazsan eğer

Eğer sevgiyi hep resmedersen ellerinle 

Kızımın gülümsemesinde unutursan acıları 

Bu sence mutluluksa eğer

Sen yaşıyorsan eğer

Yıkılmazsın çünkü hayat yaşamaya değer

Sen gülümse, yüzün gülümsemesine doğsun

Doğsun yüreğine doğacak güzel günler', 'Bir gün herşey geçer güzel olur hayat Dönüp arkana baktığında gıcıklık olsun diye Sırf çekilenlere inat sırıtırsın hayata Hızını alamaz bird...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayata-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYIRSIZIM', 'hayirsizim-murat-eraslan-r4h64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüreğimi ayaklarının altına serdim

hediyem olsun.

bütün gecelerim sana adadım

beynimin her hücresi senindi

gururumu yok saydım  senin için

bir bakış bir satır bir kelime için

her anım seni beklemekle geçti

öyle büyük öyle ihtişamlı olan aşkım

şimdi yerini daha büyük daha acımasız bir nefrete bıraktı..

kutlarım seni.

nefretimi kazanmak için çok uğraşmıştın,

kazandın.', 'yüreğimi ayaklarının altına serdim hediyem olsun. bütün gecelerim sana adadım beynimin her hücresi senindi gururumu yok saydım  senin için b...', ARRAY['Türk Edebiyatı','Şiir','Murat Eraslan']::text[], 8.5, '{"poet":"Murat Eraslan","poet_slug":"murat-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayirsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Güller', 'yorgun-guller-kaan-ozbayrak-tjmx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün yorgun güllere

Üşenmeyip topluyorum ortalığı.

Öyle köşe bucak değil.

Ne heves, ne düs kırıklığı:

Geceden bırakıp yattıklarım.

Sabahla buluyorum kendimi.

Düşler öğlene dek gitmiyor.

Yanındayım. Mutluyum. Yalnızım.

Susman yoruyor beni. Konuşman

çamaşır serili bir bahçe,

yazın toplanmadan bırakılmış

bir hali gibi nemli

ve ağır.

''Herşeye varım'' diye

bağırmak geçiyor içimden.

Oysa bağırsam,

yorgun güllerin solmaya

yüz tuttuğu bu gecede,

her heves bir düş kırıklığı.', 'Bütün yorgun güllere Üşenmeyip topluyorum ortalığı. Öyle köşe bucak değil. Ne heves, ne düs kırıklığı: Geceden bırakıp yattıklarım. Sabahla ...', ARRAY['Türk Edebiyatı','Şiir','Kaan Özbayrak']::text[], 8.5, '{"poet":"Kaan Özbayrak","poet_slug":"kaan-ozbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yorgun-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalk Düğüne Gidelim', 'kalk-dugune-gidelim-i-smet-ozel-kztk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarardın üzüntüden, üç gün ağladın

baktım gözlerine şıçramış halkın gözleri

incesin

bardakta bir karanfile benzemiyor inceliğin

serçeler sekmiyor hayır, dudaklarında

ham demirden bir çanakta dövülmüş otlar olur

ısınmış taşlar olur yazları geceleyin

sazlar

kanımda Çiçek Dağı''nı vurur

doldurur öylece göz yerlerimi inceliğin

Tenimde iz bırakmış kar kokusu

terli, muğlak adamların hevesleriyle

harman edilmiş tenim

sevinçler artırmışım çiçekli

ve çiçeksiz bütün dağlardan.

Sarhoşken bağrıma akıtılan yıldızlar

özümü çekip ayırmış avuntulardan.

Şimdi sana bakıyorum, kalabalık gözlerin

ağlamasan bizi utandıracak sanki dünya

Valentina Tereşkova

ve çekik gözlü kadın komandolar

çünkü üç gün beslendiler senin gözyaşlarınla.

Sen ağlarken azığımız çoğaldı

elledik halkın ağrılarını cesurca

ağlamasan

kök inatla kavramıyor toprağı

boş umutlar içinde pervasız büyüyor kir

ağlıyorsun ihanete karşı şavkıyor pıçak

bir pıçak ki sevgilim, Sürmene işidir.

Bir şehrin uzak semtleri gibi gözlerin

üzgün, kara, ayaklanmaya hazır

ben yaralar kuşanıp katılırım onlara

onlara katılırım yedek mermi ve şarkılar alarak

seni alırım sonra her bir yanım çağıldar

bir oyuna kalkarız sıkılmış yumruklarla

yazarız duvarlara fırtınalı yazılar.

Bir gün burda, bu kalktığımız yerde

kendini yaşamakla taşıran bir güneş kabarcığı

zonklayan bir atardamar olduğu anlaşılır

el tutuşmuş çocuklar ki o zaman

senin gözyaşlarını heyecanla kapışır.

(1969)', 'Sarardın üzüntüden, üç gün ağladın baktım gözlerine şıçramış halkın gözleri incesin bardakta bir karanfile benzemiyor inceliğin serçeler sek...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kalk-dugune-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Frenk Havası', 'uc-frenk-havasi-i-smet-ozel-ulv95', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1. Capriccio Alum

Gülünç bir ölümle öldü deniyor Max Stirner için

çünkü mahvına sebep nihayet bir sinektir

ama Fanya Kaplan

nasıl öldü diye sorarsak sanırım

işimiz fazlasıyla ciddileşir.

Bize ne başkasının ölümünden demeyiz

çünkü başka insanların ölümü

en gizli mesleğidir hepimizin

başka ölümler çeker bizi

ve bazen başkaları

ölümü çeker bizim için.

Ölümle şaka olmaz diyenler

kıyasıya yanıldılar bu çağda

Taksitle Alum diye bir roman yazıldı artık

Önce Öl/Sonra Öde denilmek suretiyle

aşılıp geçildi bu roman da.

Doların dalgalanmasına bırakıldı bu çağda alum

geceleri şehrin varoşlarında ikamete mecbur edildi

gündüzün kimlik soruldu ona

sağcı mı solcu mu olduğu sorusuna cevap verdi

seken bir kurşun kadar

kurşuni bir kış denizi kadar bile

taraf tutmayan ölüm

2. Alum Cantabile

Ben ne büyük bir dalgınlıkla bakmış olmalıyım ki hayata

görmedim orda çinko damlar ve plastik sürahilerin tanrısını

yerime yadırgadım

yerim olmadı zaten kendi mezarımdan başka

çılgının biri sanılmaktan sakınmaya vaktim olmadı

durmadan beyaz bir aygırla taşardım derin göllerden

bir gebe kısrakla kaçardım derin ormanlara

güneşin zekasıyla doymak isterdim

kaba solgun kağıtlar sunardı

şehrin insanı bana

şehrin insanı, şehrin insanı, şehrin

kaypak ilgilerin insanı, zarif ihanetlerin

Ogün bugün, şehri dünyanın üstüne kapatıp bıraktım

kapattım gümüş maşrapayla yaralanmış ağzımı

ham elmalar yemekten göveren dudaklarım

mırıldanmasın şehrin mutantan ve kibirli ağrısını.

Azıcık gece alayım yanıma yalnız

serçelerin uykusuna yetecek kadar gece

böcekler için rutubet

örümcekler için kuytu

biraz da sabah sisi

yabani güvercin kanatları renginde

biz artık bunlar olarak gidiyoruz

eylesin neyleyecekse şehrin insanı

şehrin insanı, şehrin insanı, şehrin

bozuk paraların insanı, sivicelerin

işte öldüm, işte son kadife çiçekleri

son defneler, badıranlarla kefenlediler beni

bütün kaçaklar için inci bir melhem oldu benim ölümüm

bütün hoşnutsuzlar yanlarında saklayacak

benim ölümümden yayınlan kırpıntıları

boğaz tokluğuna çalışanlar

özenle kilitleyecek göğüslerine

benim ölmüş olmamı

hiç bir yaprak damarından

hiçbir su özünden atamayacak beni

ortaya benim ölümüm sürülecek

pey akçesi olarak

tanrıların ölümünü bir üstlenen çıkınca

ama neler olup bittiğini hiç bir ayetten

hiçbir vakit anlamayacak şehrin insanı

şehrin insanı, şehrin insanı, şehrin

pahalı zevklerin insanı, ucuz cesaretlerin

3. Requiem

Bozkırda yaz akşamları seni seyrederdi

seni seyrederdi ormanda gürbüz sabah

ağırkanlı bir güneşle yaşanan kış

ağır, kanlı bir güneşle yaşanan hasat zamanı

bekarların kaburgalarına gümleyen karanlık

isterik kokusu beyaz dantelaların

seni seyrederdi

sen diriyken sana bakmak

başlı ve sonlu bir uğraştı sanki.

Gövdene imrenirdi ok atmayı bilenler

gövden aklın gibi engebeli ve dakikti

sokaklarda kavga çıkardı senin yüzünden

sen topuğunu gösterirdin ve dövüş başlardı

ejderlerle çarpışırdı bey çocukları

müminler müşriklerle savaşırdı.

Toprak ve yağmur savaşırlardı

anahtar ve kilit

birbirlerine girerdi ekmekle bulutlar

kan ve su

nadirle zenit.

Isıtırdın salkımları bağlar bozulunca

tohumların bilgisine hısımdın

beyninde yelkenlerini açarak

serinlerdi kısır kadınlar

sen diriyken

sepetlerine çiçek doldurup insanlar

peşinden gelirlerdi

serüvenler peşinden yürürdü endazelerin

mekikler otlakların yörüngesindeydi

ayıklardı insanların rüyalarını

yaktıkları tütsü, okudukları yasin.

Sonra öldün, sonra ıslıkladılar seni

gösterişsiz tabutunu yuhaladılar

lahana yaprakları attılar sana

sonradan görme tombul ortayaşlılar

semiz, genç burjuvalar seni

tepeden tırnağa fermuarladı.

akşam gezmesine çıkan emekliler bile

duygusuzca silkeledi üzerlerinden

senin gözyaşlarını

Bir soğuk uzay

parıltısıyla anılıyorsun artık

kuru bir bilgisayar tıkırtısıyla

açıyorlar taçyapraklarını ancak

bir alkol koması sırasında

senin yorgunluklarını

hastanelere makbuz yaptılar

çekingen duruşunu intihara karşı

kullanıyorlar koğuşlarda

çünkü çoktan alum götürdü seni

alum alum

gündelik sözlerimiz arasında

geçecek kadar kaba.', '1. Capriccio Alum Gülünç bir ölümle öldü deniyor Max Stirner için çünkü mahvına sebep nihayet bir sinektir ama Fanya Kaplan nasıl öldü diye ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/uc-frenk-havasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüfenk', 'tufenk-i-smet-ozel-typkp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuk e harfine yaslanmış uyuyordu

sonra saçlarımız kapandı, denklerimiz bağlandı sonra

boyuna ateşler söndü dağlarda

bir yıldız boyuna söndü durdu

çocuk insan seslerine yaslanmış uyuyordu

o zaman ben atlıydım işte

saçlarımda geceler morarırdı

yorgun olamazdım çok uzaklardaydı yurdum çünkü

boyuna tüfenkler doldurmuştum sularım girilmezdi çığlıklardan

canavarlar besliyordum ulu bir askerdim sanki

ve artık çirkinim

uykularımda örümcekler üreyor şimdi

gelmiş geçmiş bütün gölgeleri denedim

ellerim hala pençe gibi

düşler, tüfenkler ve ayaklar

gözlerimi engel oluyor güneş.

(1962)', 'Çocuk e harfine yaslanmış uyuyordu sonra saçlarımız kapandı, denklerimiz bağlandı sonra boyuna ateşler söndü dağlarda bir yıldız boyuna sönd...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tufenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahrik', 'tahrik-i-smet-ozel-f9pk7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırakın ince kavak seslerini şehrin içinde

paralar yaşlı kızların koynunda yatarken

bırakın köprülerin üstüne yağmur

ve basma perdelerden lânet bize.

Şaşılacak bir dünyada yaşamaktı; öğrendik

şimdi külçeler yüklüyüz şaşılacak bir biçimde

külçeler yüklüyüz ve çıkmak istiyoruz yokuşu

Sokaklar gittikçe katı bizim adımlarımıza

peşimizde bütün bahçeleri boşaltan ter kokusu

yankımız soyunup sevap rahatlığı alınan yataklarda

yürek elbet acıyor esvap değiştirirken

bizden artık akması beklenilen kan da katı

kovulduk ölümün geniş resimlerinden.

Efsanelerden kovulduk

kan ve demir kelimeleri söyleyince

elbiseler içindeyiz, şehrin içinde

önümüz iliklenmiş, ayakkaplarımız bağlı

kimsenin uykusunun fesleğen koktuğu yok

altıkırkbeşte vapur ve sancı geç saatlerde

eski savaşçılar vesair geçmiyor bulutlardan

çiçek alıp eve götürüyoruz

bunun bir delilik olduğunu bile bile

en ıssız duyguların ucunda karakollar

asmaların altı tuzak ve tuzak caddelerde

külçeler yüklüyüz, çıkmak istiyoruz yokuşu

gözler kısılıp bakılıyor bize.

Biliniyor

bizim mahsustan yaşadığımız

biliniyor

şarkıların sırası bizde

biliniyor

hayat bizden razıdır

biliniyor

otların sarardığı yerlerde güneş

kurşunun değdiği tende heves kalmıştır.', 'Bırakın ince kavak seslerini şehrin içinde paralar yaşlı kızların koynunda yatarken bırakın köprülerin üstüne yağmur ve basma perdelerden lâ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tahrik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilime Bir Kefen', 'sevgilime-bir-kefen-i-smet-ozel-8o0a6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alçak sesle uçuyor üzerimden

saçları kına yakılmış bir kadının mihrabı

bu gövermiş güz günleri çıldırtır

çileden ve kitaplardan çıkartır insanı

urlar, karınca cesetleri

titreyişlerle örtülür üstüm

merak

bir devrimcinin hazırlığıdır

ve alçacık bir sesle uçar üzerimden

kanser, begonya, ölüm.

Beyaz tülbentler camın arkasında

ve çıkarılmış insan gözleri

kırk batman ağırlığında sahici insan gözleri

bağrına taş basan ana

o ananın ölüsünden kalkan toz

ey acılar gardiyanı, ey güz gündüzleri.

Bir isyankar çetecinin yağmuru altında

kendi kavruk güzelliğimi yumrukluyorum

kulunç gibi giriyor öğleden sonraki cumartesinin

umudum

ki hırçın bir hayvandır durmadan

kalgıtır banknotları, miting alanlarını.

Ve tarçın kokusu ve yorgunluklarla

oturduğumuz evleri tıkayan

merak

bir devrimcinin hazırlığıdır.

Yıkanır bazı bakır dövücüleri çarşılarda

şakırtılarla sürüklenir bazlama açan kadınlar

dibeklerinde inatlarını döven

hınzır umutlarını döven kadınlar şakırtılarla.

Benim harcım değil bir yar sevmek gizliden

her yanım bin türlü merakla dalanmakta

o loş buhur kokuları, analarımız

aşererken toprak yiyen analarımız

yüreğimin palamarlarını çözüyor aya karşı

gökçe sancım zonkluyor bileklerimde

zonkluyor talaşlar, talaşlar

şakağıma vuran balyozun talaşları.

(1965)', 'Alçak sesle uçuyor üzerimden saçları kına yakılmış bir kadının mihrabı bu gövermiş güz günleri çıldırtır çileden ve kitaplardan çıkartır ins...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevgilime-bir-kefen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Olan Yenilgi', 'seni-olan-yenilgi-i-smet-ozel-9jd6q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin karanlığına kanat vuran yarasalar

başka bir göğe germişler kendilerini

yürekli savaşçılar olmuşlar

gemilerini yakmışlar ve silahlarını bilerken

kanlarına yansımış gece

senin sularına inen yırtıcılar

ve piçler yani aşk çocukları

yanan gemilerin suya yankısı oluyorlarmış

yaşlı büyücüler söylediler

çingene çocukların gülleri mor olmadı

aşka bunaltıları onlar getirmediler

onlara dayanıyorum yürekli savaşçılara

saçları uzun bir unutkanlıkla örülmüş

kanlarının ardında tehlikeler yürüyen

korkunun gözlerini aradığı omuzlarında

gittiler, yittiler arasında boğuk seslerinin

tozuyan atlarının yelelerine baktılar ve

sen oldun

ve seni gördüm, eğninde bir mavi gözlerin vardı.

(1962)', 'Senin karanlığına kanat vuran yarasalar başka bir göğe germişler kendilerini yürekli savaşçılar olmuşlar gemilerini yakmışlar ve silahlarını...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-olan-yenilgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Propaganda', 'propaganda-i-smet-ozel-bm5d1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köleler gördüm, karavaşlar

hayaları burulmuş bir adamın ayaklarını yıkamaktalardı

artık kelimeleri kalmamış fiyatları sormaktan

saçları taranılmaktan usanmışlar

sinemalarda saklanıyor kışın

yaz olunca denizin yalayışlarına

kaldırımlarda demokrat

otobüslerde dindar

geceyi

saatlerine bakarak anlıyorlar

ve sabah

gökyüzünün karnını gerdiği zaman

dağların kokusundan fabrikalar

acıkınca

Köleler!

gözleri camekânlarda.

Silâhlar gördüm

namlusu akla çevrilmiş sahra topları

mürekkebin utandığını gördüm basılı kâğıtlarda

tetiğe basan parmaklarda çare yok, gördüm mürekkebi:

Çare yok, radyoları kapatsam

çare yok, secde etsem anılarıma

bu bozulmuş yeminlerin bayrakları altında

olacak şeymi duymak portakal bahçelerini

mermiler araya girmeden anlayabilir miyiz artık

hangi kızlar hangi serin yerlerimize değdi:

Sanırdık saçlarımız kumrularla kaplanır

bir çocuk, İşte ırmak! diyerek haykırınca

o zaman belki çocuklar zabıtalardan daha çoktu

belki biz daha çok ağlardık bir aşk pıhtılanınca:

Gördüm

gözlerinde zındanlarla bana baktıklarını

düşündüm yaslanarak şehrin kasıklarına

düşündüm kafa kemiklerimi eritinceye kadar

nedir bu kölelerin olanca silâhları

silahların köleleri olmaktan başka.

Bıkmadım

koyu renkler kullanıyorum hayatımda

koyu mavi, acıyı anlatırken

sessizce öperken, koyu beyaz

ve saçlarım hakaretlerle okşanırken

koyu bir itiraf sarıyor beni.

susmak elbette zehirlidir

ve rahatlık getirir yazıklanmak da.

Ey tenimde uzak yolculukların lekeleri!

Ey çocuklarda uyuyan intizamsız güneşler!

gelin ve boğdurun bu köleleri.', 'Köleler gördüm, karavaşlar hayaları burulmuş bir adamın ayaklarını yıkamaktalardı artık kelimeleri kalmamış fiyatları sormaktan saçları tara...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/propaganda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Partizan', 'partizan-i-smet-ozel-x8q22', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gırtlağımda bir harf büyüyor

buna dayanacağım

dişlerim kamaşıyor yıldızlardan

buna da.

Kabaran bir çarpıntı oluyor şehir.

Artık yırtarak açtığımız zarflarda

ne kargış, ne infilak

yalnız

koynunda çaresiz, çıplak

isyan işaretleri taşıyan

bir ergen cesedi.

Kabaran bir çarpıntı oluyor şehir

uyusam bir dağın benimle uyuduğu oluyor

her gün şehrin ortasında bir ergen ölüyor

domuzuna ölüyor bankerlere durarak

noterden onaylı kağıtlara durarak

mevlit ilanlarına durarak.

Yunmadık saçlarını okşuyoruz, yavrum.

- Yüzümüzde dolanan bir mayhoş kahkaha -

Gırtlağımda bir harf büyüyor

gırtlağımızda.

Sarp bir güvercin düşüyor yüreğimden

buna dayanmalıyım

ölünce bir partizan gibi ölmeliyim

sabahın kuşluk vaktine savrulan

savrulan savrulan ergen ölüleri gibi.

Şehrin şarkısını söylediğim zaman

yağız bir kımıltı oluyor sesim

korku ve cüzam

korku ve cüzam

korku…

Ne beklenebilir artık namlulardan.

Harçlar karılmış duruyordur

hem de kara

bir gerdek olarak yaşıyoruzdur kendimizi

ne beklenebilir.

Yırtarak açtığımız zarflarda

büyük tecimevlerinde, büyük çarşılarda

pokerde-sinemada-genelevlerde

ne bir suçlu çağrışımı, ne karabasan

yalnız o herkesler

o herkesler kendine akarak boğulan

ve sürdüren bir güleç kocamışlığı.

Bereketli kuşlar serpeceğim ayaklarıma

genzimi yakarak

bir cinayet türküsü söyleyeceğim ben de

ölürsem bir partizan gibi öleceğim

azgın bir gebelik halinde.

Beni dinmeyen bir mavilik kanırtıyor

buna dayanamam

bir çeteci dişleriyle söküyor kanımdaki çiviyi

buna da.

Radyodan silah sesleri geliyor

ter kokusu geliyor, ayak

aksayan bir şey örtüyor

yüreğimin kabzasını

olmadık sesler geliyor radyodan

beynimde korkunç bir vida olarak

ergen ölüleri

artık ellerimi bu rahlelerden ayırsam

boyunbağımın ve gülüşümün o kirli

rahatlığından, yırtık uğultusundan şehrin.

Umudunun ayak seslerini okşuyoruz, yavrum.

Kuşandığımız 

bu alkol kokusu bize ne getirdi ki!

ÇIKSAM

gök

şarlayarak devrilse ardımdan

- ölürsek bir partizan gibi ölmeliydik -

yürüsem parçalanmış bir ceset tazeliğinde

yürüsem beynimde kıpkızıl bir serinlik

sonra denizler devirebilirim dudaklarımdan

sonra aşk, sonra dirlik: partizan

(1965)', 'Gırtlağımda bir harf büyüyor buna dayanacağım dişlerim kamaşıyor yıldızlardan buna da. Kabaran bir çarpıntı oluyor şehir. Artık yırtarak açt...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/partizan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Asker İçin İlk Türkü', 'olu-asker-i-cin-i-lk-turku-i-smet-ozel-4v3vv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutları kovan hırçınım benim, büyücüm

doğrudur gebe kaldığım coşkun bir akarsudan

bir bıçak alnıma çizer o homurtuyu ağırdan

altın haykırışlarla kuşlar uçup gelir üstümüze

gelip geceyi biriktirirler üstümüze

ben ki otobüslerde sarışın sanmışım kendimi uzun zaman

uzun zaman terli bir erkeğin esneyişiyle

bir kaçağın övgüsüne saklanıp

akşam vakitleriyle oğunup uzun zaman

kanaryalarla kesmişim uzayan tırnaklarımı.

Yüzümden bir tilkiyi silenim benim, büyücüm

erkeksi kadınların yasını tutmuyorum, artık sevin

ellerimde madensi gürültüler taşıyorum

babam uçurtmalarımı benden çok severdi bilirsin

şimdi uçurtmalarım büyük, o homurtu (o insan)

eskiden her üzgün bakışımı Pegasus''a harcardım

her kapı gıcırtısından çocuklar dökülürdü, ne çirkin

ne çirkin, gövdemde ince bir zırh yara kabuklarından

derken hüzün! Kadın sesleri çıkaran o duman…

Büyücüm, aşkımı dürtenim benim

bir oyun kuralı değiliz artık, sevin.

(1963)', 'Bulutları kovan hırçınım benim, büyücüm doğrudur gebe kaldığım coşkun bir akarsudan bir bıçak alnıma çizer o homurtuyu ağırdan altın haykırı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olu-asker-icin-ilk-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazot', 'mazot-i-smet-ozel-0cavq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamadan

dillerim dolaşmadan

yumruğum çözülmeden gecenin karşısında

şafaktan utanmayıp utandırmadan aşkı

üzerime yüreğimden başka muska takmadan

konuşmak istiyorum.

Şehre neden

esmer ve dölek yüzümle döndüm dağlardan

kar vakti tarlaları kımıldatan soluğum

niyedir sarmalasın vites dişlilerini

defneler, nakışlar yok

alnımda neden.

Ağlamadan

etimin iğneli beşiklerde bıraktığı izlere aldırmadan

o mavi korularda ve dibektaşlarında

bırakıp sözlerimin kalıntılarını

açıkça konuşmak istiyorum.

Besbelli ki leşler koruyor şehrin bedenlerini

göğsünün kafesinde yalnızca pasak

biliyorsun

korkutulmuş bir kızın

yüreğinden fışkıran beyaz güvercinleri

sabahın köründe kalkan tirenlerdeki nefret

hergün aynı kalafat yerine çekilmenin nefreti

bunları

bütün bunları biliyorsun

dağlardan dönüyorsun o sağır yamaçlardan

çevik bacaklarını getiriyorsun, ne çiçek ne de ninni

boz şayaktan poturun dağlarda ne güzeldi

şehre varınca artık meşinler giymelisin

daha esmer

daha kankusturucu

sen o baygın sevgilerin adamı değilsin.

sana yaşamak düşer çarkların gövdesinde

bin demir kapıyla hesaplaşmaktan omzun çürümelidir

bin çeşit güneşle ovulmalıdır gaddar ellerin

yürü yangınların üstüne, kendi alevini de getir

çarpıntısız dakikası olur mu devrimcinin

ki

ölüm

her yerde uyanıktır

alestadır korkunun yardakçıları

tez kızaran güllerden kendini sakın

sevgiler ürkütsün seni, aşk ayrı-

Aşktır diye geri geldin o çekiç seslerine

bıraktın vazgeçilmez ırmakları

gönlüne kar yağdırıyorsa çocuk sesleri yetsin

dikkat et hiçbir şey ıslatmasın namluları.

(1970)', 'Ağlamadan dillerim dolaşmadan yumruğum çözülmeden gecenin karşısında şafaktan utanmayıp utandırmadan aşkı üzerime yüreğimden başka muska tak...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/mazot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Şiirler', 'kotu-siirler-i-smet-ozel-k3fie', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

Senin çağıltın evladım

sen denizi düşününce uğuldayan sokaklar

açık renk bir elbiseye yakışan alnın

sabah şehre henüz kamyonlar girerken

bir kadın kıvranışını hatırlayıp kuduran

ve zaten

bu terli, bu tozlanan bulutlar altında bile

saklı bir yerlerinde bir şeyler parıldatan

senin çağıltın.

Seni marifetli sanacaklardı

karşısında uçurumlar çağıldamayan herkes

seni marifetli sanacaklardı

kalbini

rehnedebilseydin eğer.

2.

Uçsuz bucaksız gözyaşları.

Dünyanın tımarlanmış ruhlara teslim edildiği günlere ait.

Uçsuz bucaksız gözyaşları.

Bir nehrin bir yüzyıla benzediği zamanlardan.

Yaşadıklarının hepsi göçmen kuşlara

bütün sevdiklerini

çocukların hepsine paylaştıran bir dostumun

gözlerini karartacak kadar

uçsuz bucaksız gözyaşları

3.

Bütün müsveddelerimi yırttım, göğsümün kıllarıyla

gövdemin kokusundan buharlaşıyor şiir.

Sana çok önceden, bir yaz sonu, bir parkta

sıkılmış yumruğumu ısırarak

buna benzer bir şeyler söylemiştim

milât yok

demiştim, milât yer almayacak hayatımızda.

İşte bütün müsveddelerimi yırttım

işte artık göğsümün kıllarıyla

gövdemin kokusundan buharlaşıyor şiir

işte onlar artık saçların kadar Boşnak

karşılıksız mektuplarım gibi yepyenidir.', '1. Senin çağıltın evladım sen denizi düşününce uğuldayan sokaklar açık renk bir elbiseye yakışan alnın sabah şehre henüz kamyonlar girerken ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kotu-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karoon', 'karoon-i-smet-ozel-aedlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne gümüş bir çocukluk ölümün mavi cinleri

uykusunda bıraktığı saçlarındaki yangın

o balçıkla beslenen saçlarındaki yangın

ona doğru uzanınca akşamın kanlı eli

sönmüş ateşlerini öptü tapınağımın

ona cinleri sığındıran ay korkusudur

ne gümüş bir çocukluk ölüler gibi sağlam

ölüler gibi soyunmuş artık korkularından

onu ben ne kadar buldum desem yok olur

çünkü girilmez tarlasına ay kokusundan

ya güneş ya da morluk onu ben yağmurladım

takvimlere kinle baktığı zamansızlık içinde

belki de yumuşak tüylerini öptü akşamın

ya da oğlaklar sığınıyor çiçekliğine.

(1962)', 'Ne gümüş bir çocukluk ölümün mavi cinleri uykusunda bıraktığı saçlarındaki yangın o balçıkla beslenen saçlarındaki yangın ona doğru uzanınca...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karoon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlı Bir Gece Vakti Bir Dostu Uyandırmak', 'karli-bir-gece-vakti-bir-dostu-uyandirmak-i-smet-ozel-rf02q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim adım insanların hizasına yazılmıştır.

Her gün yepyeni rüyalarla ödenebilen bir ceza bu.

Keşke yağmuru çağıracak kadar güzel olmasaydım

Ölüm ve acılar çatsaydı beni

Düşüncem yapma çiçekler kadar gösterişli ve parlak

Sözlerim ihanete varacak doğrulukta olsaydı.

Anmaya gücüm yetseydi de konuşsaydım

Diri-gergin kasları konuşsaydım

“Kardeşler! ” deseydim “Kardeşlerim! ”

“Bakın yaklaşıyor yaklaşmakta olan

“Bakın yaklaşıyor yaklaşmakta olan

“Bakın yaklaşıyor...”

Yazık, şairler kadar cesur değilim

Çocukların üşüdükleri anlaşılıyor bütün yaşadıklarımdan

Gövdem kuduz yarasalarla birazcık yatışıyor.

Benim gövdem yıllar boyu sevmekle tarazlandı

Öyle bir çalımlarla gecenin çitlerinden atlardım

Bir güneş sayardım kendimi denizin karşısında

Çünkü çam kokularına sürtünüp ağırlaşan ruhların

İnanmazdım dosyalara sığacağına

Gittikçe ışıldardım dükkânlar kararırken

Hüznün o beyaz etrafına sakallarım batardı.

Benim adım bilinen cevapların üstüne mühürlenmiş

Ellerim tütsülenmiş

Evlerin yeni yıkanmış serin taşlıklarında

Dirgenler, bakraçlar, tornavidalar

Bende kül, bende kanat, bende gizem bırakmadılar

Ve içinden bir baş ağrısı gibi çınlamaktansa

Gövdem açık bir hedef kılındı belâlara.

Ve bu yüzden yakışıksız oluyor

İnsanları hummalı baharlar olarak tanımlamak

Ve bu yüzden göğsümde dakikalar

İnce parmaklar halinde geziniyor

Konvoylar geçiyor meşelikler arasından

Bir yaprak kapatıyorum hayatımın nemli taraflarına

Ölümden anlayan, ciddi bir yaprak

Unutulacak diyorum, iyice unutulsun

Neden büyük ırmaklardan bile heyecanlıydı

Karlı bir gece vakti bir dostu uyandırmak.

(1972)', 'Benim adım insanların hizasına yazılmıştır. Her gün yepyeni rüyalarla ödenebilen bir ceza bu. Keşke yağmuru çağıracak kadar güzel olmasaydım...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karli-bir-gece-vakti-bir-dostu-uyandirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Kalesi', 'kan-kalesi-i-smet-ozel-rfvl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elbet bir hinlik vardır seni sevişimde

ey kanıma çakıllar karıştıran isyan

saçlarıma bin küsür yalnızlığı takıp girdiğim şehre

insan varlığımızdan tuhaf tohumlar bıraksam

günü geçmiş bir gazete, toprak bir çanak

bir daha gelmem belki diye bir not bakır maşrapanın yanında

şeytanlar da yürür benimle herhal ıslık çaldığım için

bir şahan tüylerini döker ardımsıra

artık bırakılmaktan yapılma bir adam sayılırım

böğrümde kambur çocuklardan bir payanda.

Gizemli bir dehliz gibi şehri dolaşıyorum

sıkıca tutuyorum kendimi şehre karışmaktan alıkoymaya

her yerimde urlar çıkıyor, biraz kürt, biraz köylü, biraz makina

kangren oluyorum bahar geldiği için

urlarımı kesiyorum kör bir usturayla

ama kopmuyor onlar ve bana şehri dolaştırıyor

bırakabileceğim her şeyi bıraktırıyor bana

kızlardan geçilmiyor köprüler, ayak bileklerime dek

yükseliyor kız tortuları

tülbentlerden kanı süzülürken körpe yavruların

bir bazı şeyler bulmalı yüzümüze tebelleş olan bu korkuya

-Avluya çık

-Avluya kara bir şey bırakılmış

(bir bomba) 

Kulaklarımız alışmıştı tıpırtısına yağmurun

şehre sıkıntının rahatlığı basmadan giriyorduk

filimler üç günde bir değişiyordu

bense ikircikliydim ama korkmuyordum

polis olan babamla tatil arasında uçuşup duruyordum durmadan

urlarım yoktu, suçum yoktu,

ve beyaz kuşlar kalkardı anamın hırkasından

şehre karışmayan bir dehliz değildim

sevinçle kovalıyordum kendimi

bunları ansımak başımı döndürüyor bazan

elbet bir hinlik vardır seni sevişimde

ey kanıma çakıllar karıştıran isyan.

Azan bir hevestir artık tanyeri

söküp gövdesinde bir cehennem parçalamak ister insan

şehrin defterini dürüp uzanmak ister yanına

üstümüzü kuş sesinden bir lekeyle örtmeli

umudumuzu kapmaya gelen makinaları

bütün çirkefini şehrin çarpıtıp aşkımıza

solumak gece

terlemek gece

gece çarşaflara…

Açıklanacak, belletilecek olan belki

milât öncesi ve sonrası lâkırdıları

karışık banka hesapları, navlun

yani öylesine açık değil pek

hatta

-şehir mi, değil mi burası-

kötürüm bir kurt çantamı karıştırıyor

neden karıştırıyor, ne hakla

direnmeler, erzurumlar, kalfalar

gecenin ipini koparan gece safaları

-Var mısın yok yere ağlamaya… Ki bir sis

yanık bırakılmış bir fısıltı

şehri sarıyor, bir dehliz olan bana ulaşamıyor ama

herkesin içinde iğdiş bir bahar

bacakları eriyor memurların, evkızlarının

ve saat 24 vardiyasının işçileri

inmiyor ocaklarına.

Yufka mıdır

yufka mıdır benim bakışım dünyaya

ki acılarıyla başlatırım insanları

derimi yalayarak geçen mevsim

beni alır şehirden yıpranmış bakışlarla

her askere gidenin, her tören yorgununun

kondurur kemerinin kaşına.

Böylece ben, o küskün, o karışmayan dehliz

koca bir tomruğu yüklenirim arkadaşlarla

koca bir tomruğu kaldırıp kaldırıp

kümbetlere, bitkinliğin bordasına…

Kanın çığırından çıktığı saattir bu

memelerini bana sıkıca bastırdığın

hercai bir yürek somurtkan kepenklerin ardında

şehri acıtan çocukluğumuza değdikçe

biz seviştikçe bizi acıtan

kukumav kuşları, mânilerle dolu bir yatak

zaç yağı şişeleri kocaman.

Sen şimdi sevincimin akranısın

ey kanıma çakıllar karıştıran isyan

doğrusu seni toprağı eller gibi sevdim

yaralarımı onduranımsın

yatağımı hiç boş bırakmayan…

Yüzümü ellerimle yine kapayayım mı? 

bekçi karısının belaltını mı anlatayım insanlara

yoksa onlara bilinmez bir toprak mı adayayım

değil

partizanlığım dalaşmak istiyor anla

bu sarsak hırgürüyle dünyanın

dalaşmak dalaşmak dalaşmak

böylece aşk akranım oluyor benim

ey bayırdan ve yokuştan uzaklara

ey çırpınan bir geyiktir memelerin

karnın ısırgan otları gibi aklımda.

(1966)', 'Elbet bir hinlik vardır seni sevişimde ey kanıma çakıllar karıştıran isyan saçlarıma bin küsür yalnızlığı takıp girdiğim şehre insan varlığı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/kan-kalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-i-smet-ozel-u8ywy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Serin karanlığıma bir çingene düşerdi

gökyüzüne birikirdi hazineleri kışın

dağların dağlarda birikirdi gölgeleri

ürkütülmüş gölgeler kapımda çoğaldıkça

yüreğime o tedirgin çocuklarda düşerdi

kar yürürdü gözlerime tüyden ayaklarıyla

kar yürürdü çünkü kar

o temiz eldiveni gökyüzünün

tüfengimin ıssızlığını büyütürdü

bir dönülmez kaçışa uzanırdı çocuklar

ve o üzünç bitkisi çocuklarda ölürdü

artık üşümek çince bir çiçektir oralarda

yolcuların taşıyamadığı bir çiçektir

çünkü kardan yorulunca biz sıcak sulara

inip sepet öreriz ve ''gecenin

uzun ağzı sulardı saksıları''

ve hala ay dağınık saçlara benzer oralarda

serçelerin ayaklarına bağladığı karanlık

kimseyi çağıramaz kendi adıyla.

(1963)', 'Serin karanlığıma bir çingene düşerdi gökyüzüne birikirdi hazineleri kışın dağların dağlarda birikirdi gölgeleri ürkütülmüş gölgeler kapımda...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kacis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jazz', 'jazz-i-smet-ozel-07lvq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu vapuru kaçırırsam beni belki de cinnet basar

belki kanser olurum bu yıl sınıfta kalırsam

nöbette uyursam eğer kitaplarımı yakarlar

etimde şirpençe çıkar bu kızı alamazsam

bu işi bitiremezsem şehirden beni kovarlar

izin kağıdım yanar konuşacak olursam

bu senet bankalar kapanmadan

ruhumun rengini kapatmayacak olursa

ölür kuyuya düşen çocuk

çocuğun mercan saati çatlar mutlaka

koşup haber vermeliyim

yetkili memura

bahar geliyor, ilerliyor yeminler

alnımı kapıp getirmeliyim

denizi karşılamaya

kırlangıcın kanadındaki kezzap

leylakta sıkışan buhar için

nabzımı bulmalıyım nerede bulacaksam

nabzımı çünkü ben kasadan fiş alarak

yağmuru, selvileri zor durumda bıraktım

benim yongalarımdan yapıldı bu çelenkler

ben papatyaları şımartmadım diye oldu

Mata Hari''ler casus, Al Capone''lar gangster

inmem gerek gözbebeklerimin altına

beynimin ortasına büzülmeliyim

genşeyip kımıldayabilirim oradan sonra

dum di dum

duridum dubida

kendi kalbimle zamanım arasındaki sarkaç

püskürtüyor beni dünyaya

bırakıyorum zerreciklerime kadar emsin beni

Atlantik ve Pasifik ve beş kıta

koşmam gerek

yetişmem gerek yazgıma

tutmam gerek, sormam gerek, bilmem gerek

esenlemem, kargışlamam, irkitmem gerek niçin

niçin, niçin, niçin

kuyuya düşen çocuk niçin ölmesin

(1981)', 'Bu vapuru kaçırırsam beni belki de cinnet basar belki kanser olurum bu yıl sınıfta kalırsam nöbette uyursam eğer kitaplarımı yakarlar etimde...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/jazz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Sızı', 'i-nce-sizi-i-smet-ozel-sii93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var mıdır nalçaları sevincin

gün tene değince kanatları uzar mı

derin bir secde gibi rüzgara aşılanmak

dostları düşünmenin çarpıntısından mı

Yokum arkadaş düşünmekle varılan tada

hayata yalnızca kafanı banmak

gövdende namusluca güdebilmek sevinci

elbet burkulup kalmaktan iyi.

Kara gözlerimde uğuldayan bu değil ancak

elde tüfek, elde alet, yürekte kor

cebelleşmek yalanla, kirle, tahvilatlarla

damarlarına papatyalar doldurarak

bir serinlik olup dünyaya sokulmak

ben bir deli fışkın değil miyim

sahibim Köroğlu''nun da sahibi değil mi

ve çocukların ezbere bildiği gömleğimin

kendirini kendim ekmedim mi

Öyleyse arkadaşım sinem kanayadursun

ta ki sürgün ya da mahpus kırışıklar yerine

yüzümüz köylü ve gurbetçi yanıklığa dursun

sevmekle doğrulanmıyor madem kalbimiz

girelim yarimizin avlusuna tam tekmil

ve mürdüm erikleri

ve dopdolgun elmalarıyla o bahçede

o geniş kalçalı yarimizi dört kere.

(1968)', 'Var mıdır nalçaları sevincin gün tene değince kanatları uzar mı derin bir secde gibi rüzgara aşılanmak dostları düşünmenin çarpıntısından mı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ince-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ils Sont Eux', 'ils-sont-eux-i-smet-ozel-esomr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağır ceza reisi duruşmaya girerken

safir bir göz yapışıyor kırmızı yakasına

kırmızı yakaları var yargıç cübbelerinin

Fransız ihtilalelinden kalma.

Burslu okuduğu yıllardan kalma ceza reisinin

garip bir tarafı var

kaşlarını çatınca bir çocukluk

dolduruyor yüzünü

ürkünç bir uğursuzluk

gülümsediği sıra.

Garip bir tarafı var valinin

makam arabasına binerken her seferinde

bakır bir dudak karışıyor kırmızı saçlarına

saçlarını parmaklarıyla taradığı zamanlar

bu dudak

öpüyor onu hain bir yumuşaklıkla.

Safir göz görünmüyor yargıca

kendini valiye vermiyor bakır dudak

görmüyor alay komutanı tekmil alırken

gömleğine bir damla civanın sızdığını

bir gözyaşı, bir ukde anlamı kazanarak.

Kimse görmüyor buruşuk pardesüsüyle bir babanın

kırılgan bir yelpaze olduğunu akşam eve girince

karısı

katlanmış kilimlerle uyum içinde

kolunu büküyor, dayıyor elini yanağına

büyük kız kanepede bu ara

bir göl gezintisine çıkmıştır

kelebek ölülerinden bir ırmakta

sürüklenmektedir lisebirdeki oğlan.

Kız için 

sırlara karışmaktır 

bir gölün ortasında olmak

erkek kardeşi bir türlü 

varamaz herhangi bir sırra…

İki yanında neden akar binlerce bu kelebek? 

Binlerce kanatlı çekirge neden uçar

beyninin yukarsında? 

Evde soba yanıyor

önce çalılar geçiyor çocukların boğazından

sonra ağaç kökleri yırtıyor damarlarını

bütün ailenin.

Dışarda soğuk

safirden, bakırdan, cıvadan bir gece uçuyor

gece uçarken kulaklarına dokunuyor bekçinin

bekçi

mavi zehir şiddetinde düdük çalarak

bir soru soruyor karanlığa

bütün cevaplar sendedir, saklama

diyor karanlık ona

bekçi en saklı yerinden bir banka broşürü

bir piyango bileti çıkarıp gösteriyor

copunu gösteriyor lisebirdeki oğlana

sonra acılı olduğu açıkça anlaşılan

bir kadına bıyık buruyor

buruk bir sabah

başlıyor acılı olduğu

açıkça anlaşılmayan

dünyada.

Ağır ceza reisi

santa luçia söylüyor traş olurken

maiyet memurluğundan beri aksatmadan

yaptığı gibi vali sabah sabah

parlatıyor

zaten pırıl pırıl olan siyah

kunduralarını.

Kışlada alay komutanı

barakaların kar altında öksüz

duruşlarına bakarak

susuyor, söylemiyor bildiği tek şiiri

''güzel olan hiçbir şey hülasa edilemez''

demiş çünkü Valéry.

Çünkü serbest düşünme zamanı geçti artık

şimdi mesai saati

disiplin kurulunun toplantısı var

arşivde sicil belgeleri damgalanacak

tayinler imzaya girecek

teftişe gidecek generaller

rüya, okşayış, Tevrat

gibi kelimeler

gündemin dışında.

Yurttaşlar uygunadım çalışmalarıyla

söktüler kariha yarımküresini yerinden

bir pusula koydular açtıkları boşluğa

titreyen, korkak ibresiyle bu pusula

kuzeyi gösteriyor serbest

düşünme zamanlarında; 

safir bir göz görünce karıştırıyor yönü

tırnaklarını yiyor bakır bir

dudak ona yaklaşınca; 

cıvadan bir gözyaşı 

bari olsun istiyor

bütün mesai boyunca.

Buruşuk pardesülü adam dalgın

gittikçe daha dalgın, elinde cetvel

masada hesap makinesi, pusula

yetmiyor dibe dalmasına

bağlıyor kalın bir urganla beline

ağır bir sandık

salıyor kendini

yeşil yosunların

kırmızı balıkların

uçan kabarcıkların

derinliklerine

orada

bir sandık buluyor

yakutlar, altınlar, pırlantalar

adam dibe inmek için beline bağladığı

sandığını keşfediyor dibe ulaştığında.

Öyleyse adamın eyvah ışıdı yüreği

eve dönmesine gerekçe

bulamıyacak bir daha.

Eyvah çattı kaşlarını, ayağa kalktı yargıç

elindeki kalemi

gülümsüyor, kıracak! 

Atıldı öne, denize doğru lisebirdeki oğlan

denize, yakuta, entegral hesaplarına.

Kardeşim! 

diye haykırdı ablası arkasından

fırladı kanepeden

kopardı kafasını bekçinin

safirden bir baltayla.

Anneleri

mutfakta kalan son bakır sahanı

alüminyum olanıyla değiştirdi.

Mesainin bitimine on kala

istifa etti vali

çamurlu bir yoldan

yayan yürüdü sınıf arkadaşı

olan nalbantın dükkanına.

Alay komutanı oğlu için

otomobil satın aldı

Mercury marka.

Kış geçti, öksürük haplarıyla

geçti cumartesi

hiçbirşey söylemeyen sözlere varmak için

herşeyin sonuna kadar söylenmesi gerekti

incir… yarpuz… karamela…

la havle ve la kuvvete illa billah.

(1981)', 'Ağır ceza reisi duruşmaya girerken safir bir göz yapışıyor kırmızı yakasına kırmızı yakaları var yargıç cübbelerinin Fransız ihtilalelinden ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":140,"source_url":"https://www.antoloji.com/ils-sont-eux-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Şu Zalim Şüpheyi Kaldır Ya SenGel Ya Beni Oraya Aldır', 'i-cimden-su-zalim-supheyi-kaldir-ya-sengel-ya-beni-oraya-aldir-i-smet-ozel-f0tmw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağzının bir kıvrımından cesaret bularak

ter yürekte susayışlar yaratan yağmurlara açıldım

kalmışsa tomurcuklar önünde sendeleyen çocuklar

kalmışsa bir kaç ısrar ölümle yarışacak

onların yardımıyla dünyamıza acıdım.

Dünya. Çıplak omuzlar üzerinde duran.

Herkes alışkın dölyatağı bersalarla ağulanmış bir dünyaya

Benimse dar

çünkü dargın havsalamın

gücü yok bazı şeyleri taşımaya.

Önce kalbim lanete çarpa çarpa gümrah

sonra kalbim gümrah ırmakları tanımaktan kaygulu

sakın Styks sularının heyulası sanmayın

er gövdesinde dolaşan bulutun simyası bu,

biraz üzgün ve Ömer öfkesinde biraz

öyle hisab katındayım ki katlim savcılardan sorulmaz

ne kireç badanalı evlerde doğmuş olmak

ne ellerin hırsla yaban tutuşu

ne fabrikalarda biteviye üretilmekte olan kahır

dev iştihasıyla bende kabaran aşkı

yetmez karşılamaya.

İnsanlar

hangi dünyaya kulak kesilmişse öbürüne sağır

o ferah ve delişmen birçok alınlarda

betondan tanrılara kulluğun zırhı vardır

çelik teller ve baruttan çatılınca iskeletim

şakaklarıma dayanınca güneş

can çekişen bir sansar edasıyla

uğultudan farkedilmez olunca konuştuğum

kadınların sahiden doğurduğuna

toprağın da sürüldüğüne inanmıyorum

nicedir kavrayamam haller içinde halim

demiri bir hecenin sıcağında eriyor iken gördüm

bir somunu bölünce silkinen gökyüzünü

su içtiğim tas bana merhaba dedi, duydum

duydum yağmurların gövdemden ağdığını.

Sen ol küçük bir kıvrımdan, bir heceden 

aşk için bir vaha değil aşka otağ yaratan

sen ol zihnimde yüzen dağınık şarkıları

bir harfin başlattığı yangın ile söndür

beni bir ses sahibi kıl, kefarete hazırım

öyle mahzun

ki hüzün ciltlerinde adına rastlanmasın.

(1975)', 'Ağzının bir kıvrımından cesaret bularak ter yürekte susayışlar yaratan yağmurlara açıldım kalmışsa tomurcuklar önünde sendeleyen çocuklar ka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/icimden-su-zalim-supheyi-kaldir-ya-sengel-ya-beni-oraya-aldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gececil Kuşların Ürkmediği Aydınlık', 'gececil-kuslarin-urkmedigi-aydinlik-i-smet-ozel-jxhno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerimize

o ilkel sesleri karışır ya

gemileri annelerinden çok seven çocukların

bir adam gelir ya

devinen bir sancıdır artık

gelir eski günlerden

ve uzar sanki uzar

ırzına geçilmiş bir kahramanlık.

Sinsi gülüşlerimizdir şimdi pis bir suda yıkanan

korkulardır katar katar inenler gökyüzünden.

Ay sürekli yükselirse içimizde

çirkin ama güçlü bir tanrıya taptığımızdandır

ondan ki sıkıcıyız bu eski ayaklarla

ondan ki ulu bir tiksintiye hazırlanmışız,

Kemerlerimizdeki en güzel geyik ölüm.

Ama kim? Ben miyim burda bir esrime mi

nedir bu kuşların uçuşunda gördüğüm?

Aptalca beklerim o hiç sökmeyecek şafağı.

Oysa yüreğimden akan o derin suda

kırmızılar öylesine yırtılır ki

siner kan, 

huysuz kemanlar dolar şahdamarıma,

yansır kin savaşçıları, gürül gürül ordular

utancın köpürttüğü yanaklarımdan.

Köz komamış ateşinden bize o adam

şimdi gülüşlerimiz yırtıcı, gülüşlerimiz korkunç

ağır, kara bir zırh taşıdığımızdan.

(1963)', 'Günlerimize o ilkel sesleri karışır ya gemileri annelerinden çok seven çocukların bir adam gelir ya devinen bir sancıdır artık gelir eski gü...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gececil-kuslarin-urkmedigi-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözülmüş Bir Sırrın Üzüntüsü', 'cozulmus-bir-sirrin-uzuntusu-i-smet-ozel-9i8ak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamaktan öte özür bulamayınca aşka

sonuçları bir bir gözden geçiriyorum

pulluklarla devrilen toprağın ıslaklığındaki can

madenlerin buharından elde edilen büyü

bazı yasak kitapların verdiği dinç duygular

nelerse ki yaşamak sözünü asi kılan

nelerse ki lekesiz, umutlu ve budala.

Denedim. Soğuk sular dökünüp fırladım sokaklara

sorular sordum nice kara sıfatları üstüme alaraktan

ipte boynum, ağzım şehvet yalaklarında

çapraştım, and içip ayna kırdım

doğadan bir vahiy bekledimse boşuna

baktım akşam herkesin kabul ettiği kadar akşamdı

hiç bir meşru yanı kalmamıştı hayatımın.

Sözlerimin anlamı beni ürkütüyor

böylesine hazırlıklı değilim daha.

Bilmek. Bu da ürkütüyor. Gene de biliyorum: 

Kapanmaz yağmurun açtığı yaralar çocuklarda.', 'Yaşamaktan öte özür bulamayınca aşka sonuçları bir bir gözden geçiriyorum pulluklarla devrilen toprağın ıslaklığındaki can madenlerin buharı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cozulmus-bir-sirrin-uzuntusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Celladıma Gülümserken Çektirdiğim Resmin Arkasındaki Satırlar', 'celladima-gulumserken-cektirdigim-resmin-arkasindaki-satirlar-i-smet-ozel-3qdms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben İsmet Özel, şair, kırk yaşında.

Her şey ben yaşarken oldu, bunu bilsin insanlar

ben yaşarken koptu tufan 

ben yaşarken yeni baştan yaratıldı kainat

her şeyi gördüm içim rahat

gök yarıldı, çamura can verildi

linç edilmem için artık bütün deliller elde

kazandım nefretini fahişelerin

lanet ediyor bana bakireler de.

Sözlerim var köprüleri geçirmez

kimseyi ateşten korumaz kelimelerim

kılıçsızım, saygım kalmadı buğday saplarına

uçtum ama uçuşum

radarlarla izlendi

gayret ettim ve sövdüm 

bu da geçti polis kayıtlarına.

Haytanın biriyim ben, bunu bilsin insanlar

ruhumun peşindedir zaptiyeler ve maliye

kara ruhlu der bana görevini aksatmayan kim varsa

laboratuvarda çalışanlara sorarsanız

ruhum sahte

evi Nepal''de kalmış

Slovakyalı salyangozdur ruhum

sınıfları doğrudan geçip

gerçekleri gören gençlerin gözünde.

Acaba kim bilen doğrusunu? Hatta ben

kıyı bucak kaçıran ben ruhumu

sanki ne anlıyorum?

Ola ki

şeytana satacak kadar bile bende ondan yok.

Telaş içinde kendime bir devlet sırrı beğeniyorum 

çünkü bu, ruhum olmasa da saklanacak bir şeydir

devlet sırrıyla birlikte insanın

sinematografik bir hayatı olabilir

o kibar çevrelerden gizli batakhanelere

yolculuklar, lokantalar, kır gezmeleri

ve sonunda estetik bir 

idam belki!

Evet, evet ruhu olmak

bütün bunları sağlayamaz insana.

Doğruysa bu yargı 

bu sonuç

bu çıkarsama

neden peki her şeyi bulandırıyor 

ertelenen bir konferans

geç kalkan bir otobüs?

Milli şefin treni niçin beyaz?

Ruslar neden yürüyorlar Berlin''e?

Ne saçma! Ne budalaca!

Dört İncil''den Yuhanna''yı

tercih edişim niye?

Ben oysa

herkes gibi

herkesin ortasında

burada, bu istasyonda, bu siyah

paltolu casusun eşliğinde

en okunaklı çehremle bekliyorum

oyundan çıkmıyorum

korkuyorum sıram geçer

biletim yanar diye

önümde bir yığın açalya

bir sürü çarkıfelek

gergin çenekli cesetleriyle

önümde binlerce çiçek

korkuyorum sıra sende

sen de başla ve bitir diyecek.

Yo, hayır

yapamaz bunu, yapmasın bana dünya

söyleyin 

aynada iskeletini

görmeye kadar varan kaç

kaç kişi var şunun şurasında?

Gelin

bir pazarlık yapalım sizinle ey insanlar!

Bana kötü

bana terkettiğiniz düşünceleri verin

o vazgeçtiğiniz günler, eski yanlışlarınız

ah, ne aptalmışım dediğiniz zamanlar

onları verin, yakınmalarınızı

artık gülmeye değer bulmadığınız şakalar

ben aştım onları dediğiniz ne varsa

bunda üzülecek ne var dediğiniz neyse onlar

boşa çıkmış çabalar, bozuk niyetleriniz

içinizde kırık dökük, yoksul, yabansı

verin bana 

verin taammüden işlediğiniz suçları da.

Bedelinde biliyorum size çek 

yazmam yakışık almaz

bunca kaybolmuş talan

parayla ölçülür mü ya?

Bakın ben, bir çok tuhaf

marifetimin yanısıra

ilginç ödeme yolları bulabilen biriyim

üstüme yoktur ödeme hususunda

sözün gelişi

üyesi olduğunuz dernek toplantısında

bir söyleve ne dersiniz?

Bir söylev: Büyük İnsanlık İdeali hakkında!

Yahut adınıza bir çekiliş düzenleyebilirim

kazanana vertigolar, nostaljiler

karasevdalar çıkar.

Yapılsın adil pazarlık 

yapılsın yapılacaksa

işte koydum işlemeyi düşündüğüm suçları

sizin geçmiş hatalarınız karşısına.

Ne yapsam

döl saçan her rüzgarın

vebası bende kalacak

varsın bende biriksin

durgun suyun sayhası

yumuşatmayı bilen ateş

öğüt sahibi toprak

nasıl olsa geri verecek

benim kılıcımı.

(1984)', 'Ben İsmet Özel, şair, kırk yaşında. Her şey ben yaşarken oldu, bunu bilsin insanlar ben yaşarken koptu tufan  ben yaşarken yeni baştan yarat...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":115,"source_url":"https://www.antoloji.com/celladima-gulumserken-cektirdigim-resmin-arkasindaki-satirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakmaklar', 'bakmaklar-i-smet-ozel-68j4a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Donyağından yapılmış sabunların

ürkütüp sindirdiği gözlerim vardı - ağır -

ağır yani çoraplı ve sürgün doğmanın

taşınmaz kıldığı.

Ben şenlikçisiydim pıhtı kanın

keten helvacılardan, bileycilerden

rugan çizme giyilen çağlardan geçerdim

barutun ve susamanın güzelliğiyle

tek yatmanın akmayan yüzüyle geçerdim.

Oraya, göğsüme iliklediğim hayvanı ayartmadan

direnmenin mayasını ellemeye.

Gün dönerdi, benzi solardı kahkahamın

kapardım kapımı gevşeyen bir yanımla

ve hergece yatağımda bir engerek bulmanın

süregen iğrentisiyle dolardım, sesim

öylece - Kusmuk Gibi - kalırdı ağzımda.

Çünkü heryerde bir göğün ufak kaldığı vardı

- akşama özgü göğsümü açardım

ey mutlu seri penceresi doğanın -

heryerde köpeksi koklaşmaların sürüp gittiği vardı

uyurken bir kadına doyar gibi kanardı ayaklarım

kanardı ve bir irin seliyle boğulurdum hersabah.

Oysa babam bilirdi yaşadığını aptes alırdı çünkü

anlatacak şeyleri vardı, eğilip kalkmaları

dualar okuması, doğum sancılarıyla bırakıp gitmesi anamı.

Ah, göğe uzatıyorum bir cumartesiyi

hayın bir çalgıyı kuşanıyorum göğün huysuz kuşlarıyla

GÖK! Bir kahkahaya geçirdikçe dişlerimi

bir tabut kalmıştır akşam olmaya

bir tabut beklenen bir aydınlıktır

beklenen bir ses gibi avlularda.

Anam kirliserin penceresinde doğanın

uykusu ayaklanır kanı birikir saçlarına

gözlerine uyuşuk bir hınç siner artık

ölü bir erkeği almıştır yatağına

o soğuk ölüyü, o kurutulmuş anıyı

birdenbire benim ağzıma takılır herşey

giderim akşama özgü göğsümü açmaya.

Ben nereye adımı yazsam

nereyi göstersem parmaklarımla

orası şapkalar yüklü bir vagondur,

nerede daralmış görsem bir adamı

akşamın güzel buğusunda eli-ayağı tutulmuş

bir çiçeğe uzanırken utandığını görsem

işte iğrentim yayılıyor derim, işte sırtlanlar soluyor ellerimde

kuşlar çoktan kapamışlar tarlalarını.

O zaman bir üzünç aralığında - herkes gibi - başlar korkum.

Ey irin mutluluğu!

Ey durmayıp ağrıyan kemiği usumun!

Uğunursam beni hazdan delirten hayvanın ortasında

ben koşarken derelerde birikirse çocukluğum,

piçliğim birikirse sesimin o hıncahınç boşluğunda

coşkunun en sağlam atıyla geliyorum

sövgüm büyüyor, ağartıyor günümü.

TAN! Ölü bir keçiyle saçlarımı taramanın vaktidir

sarı bir bilincin ötesini ellemek istemenin

bir üzünç aralığındayız artık TAN!

savulun, çıplaklığım geliyor ardımdan.

(1964)', 'Donyağından yapılmış sabunların ürkütüp sindirdiği gözlerim vardı - ağır - ağır yani çoraplı ve sürgün doğmanın taşınmaz kıldığı. Ben şenlik...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bakmaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Adam', 'ayni-adam-i-smet-ozel-wdacs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tozludur saçlarım, saçlarımdan

devrilmiş sarayların dumanları savrulur

yüzüm yanıktır

yüreğime bir karanfil sokuludur

ve partizanca darbelerin dünyaya ilen şavkı

benim göğsüme göğsüme vurup durur.

Ben dünyaya doğru yürümekle meşhurum

bahar da sürgülenir içime katranlar da

hem koşarak yarattığım sevgiler vardır

hem körlenmiş sevgilerin acısıyla koştururum.

Beni sular

kocaman taşları parçalayarak hatırlıyor dağlarda

ve beni hatırlatıyor çeltik tarlalarında aynı sular

umutlu sakinlikleri

lohusalıklarıyla.

Ben dünyaya doğru yürümekle meşhurum

kökten dallara yürüyen sular gibi

yürürüm kömür ocaklarına, çapalanan tütüne

yürürüm hüzün ve ağrılar çarelenir

dağların esmer ve yaban telaşından kurtula diye

torna tezgahlarında demir.

Yürürüm çünkü ölümdür yürünülmeyen

yürürüm yürüyüşümdür yeryüzünün halleri

kanla dolar pazuları tarladakinin

hızar gürültüsü içinde türkülenir bir öteki

gökleri göğsümden aşırtarak yürürüm

yağlı kasketimin kıyısında nar çiçekleri.

Aynı adam Ekim günlerinden beri gümbür gümbür gelirim

teneke damların üstüne safi sinirden doğan güneş

portakallar fırlatarak parlıyor benim adımlarımla

anladım neden yorgunluk

gülümserlik getiriyor insana

hayatın bana başat

bana avrat oluşunu öğrendim

işçiler bunu kurşunlanarak öğrendi

on beşinde bir arkadaş

inancını savunurken yargıca

anladı bulana durula akmakta olan şeyi.

Yürüyorum

azarlanıyorum fışkıran başaklarla

iki bomba gibi taşıyorum koltuğumdaki bir çift somunu

hurdahaş bir sancıyla geçiyorum badem çiçekleri altından

gözlerim nemli değil.

gözlerim namlu.

(1968)', 'Tozludur saçlarım, saçlarımdan devrilmiş sarayların dumanları savrulur yüzüm yanıktır yüreğime bir karanfil sokuludur ve partizanca darbeler...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ayni-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akla Karşı Tezler', 'akla-karsi-tezler-i-smet-ozel-ys5wr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

Gecenin üçüdür en uygun zaman, bahse girerim

düşünün: sabah çok yakın

oysa ışıltı yok ortalıkta

nerdeyse gece bitmiş ama sürmekte karanlık

henüz uyanmış bazıları

henüz uyumamış bazıları

bazıları uyanmış uykusuna doymadan

bazıları uykusuna varmadan doymuş

görüyorsunuz ilm-i hilaf ü cedel düzeniyle hayat

nasıl da sürüklüyor kendini

ve ben bunu kanıtlayabiliyorum

şu şair halimle

böylece size ey saygıdeğer erbab-i cumhuriyet

akıllı ve yetenekli olduğumu

kanıtlamış oluyorum

sizler de

bu derin bilgeliği kavrayarak

kendi değerinizi ortaya koymuş oluyorsunuz.

2.

Ütüsüz bir pantolon kadar tedbirliyim

tarihi bir gerçek kadar sıkılgan

bilmem ki Tesalya''daki Termofil

bir yiğitlik anısı

bir hayınlık anıtı mı olsa

yine bilmem quantum kuramını

öğrenen insan haklı mıdır

kendini ardıçkuşu sanmakta-

ben

yirminci yüzyılın sonlarında

en uzak uyanışlar ikliminde yaşadım

bir imparatorluk genişliğindeki gençliğim sırasında

kadınlardan daha çok birinci şubeye vardım.

3.

En mutlu insanlar belki de

baca temizleyicileridir

öyle dar, öyle kara karanlık bir yerdedirler ki

yüreklerini geniş, dayanıklı

aydınlık tutmak zorundadırlar

buna yükümlü sayarlar kendilerini.

Baca temizleyicileri başkalarını sevmekle kalmaz

başkalarınca sevilirler aynı zamanda

çünkü herkesi düşünmeyecek kadar mutlu

herkes tarafından düşünülmeyecek kadar mutludurlar.

4.

Köylüleri niçin öldürmeliyiz?

Bu sorunun karşılığını bulamıyorum

içinden çıkılmaz bi olay, ama önemsiz

köylüleri öldürmesek de olur

hatta onların kalın suratlarını

görmezlikten gelebiliriz

yapılacak çok şey var daha

sözgelimi ben, kendim

hiç hayıt ağacı görmemişim

görmeden ölürüm diye korkum da yok

değil mi ki albatrosu Baudelaire''den

Yves Bonnefoy''dan semenderi öğrendim

bir gün bakarsınız

şu güzelim bilgiç beynimi kırıp

teneşir tahtası olarak kullanabilirim.

(1974)', '1. Gecenin üçüdür en uygun zaman, bahse girerim düşünün: sabah çok yakın oysa ışıltı yok ortalıkta nerdeyse gece bitmiş ama sürmekte karanlı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/akla-karsi-tezler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdenizin Ufka Doğru Mora Çalan Mavisi', 'akdenizin-ufka-dogru-mora-calan-mavisi-i-smet-ozel-mxyj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '"Kim yeni terleyen bıyığına, sakalına sevdalanmışsa 

Ölünceye kadar bu daireden dışarıya ayak atamaz"

-Hafız-

Yaz günleri beni hatırlamıyor.

Salgılı bir hayvanla bitişiyorum yaz yaklaşınca

yayılıyorum ortasına sevgili tüylerimin

geniş uykulardayım, muazzam uykularda

yılların zulmünden haberim yok

ne de sürgün taşralı kızlar korosundan

geçiyor hazza yatkın dudaklarıyla gece

canımın ilmekleri arasından.

Beni artık kimseler arayıp da bulmasın

beyaz harmanilerin göklere açık sofrasında

yıktığım saltanatın dizinde inlediğim

aşkın en tabanında yattığım anlaşılmasın

çünkü ben çok gizli bir yanlışın

dehşetengiz yeteneğini ölçmek için

yepyeni bir hata için iniyorum Akdeniz''e

Meryemoğlu sanıp ben zavallı ademi

çarmıha çaktılar orda çok zaman önce.

Çok zaman önceydi ki otobüsler

mermer sütunlu şehirlerden sahil çardaklarına

nice yılgın havarilerle gidip geldi.

Hepimiz, yani taflan çiğnemekle güzelleşen çocuklar

havariler karşısında harami

gövdesinde hayvan kabarınca mecalsiz

kutlu bir tan çıkarmayı denedik

kayser makinasından

anneler

sevecen gözyaşlarıyla korurdular bizi.

Bizi sen ey beyhude ve baygın duyguların yırtıcısı

sen ey loş çalgıları uykulardan çıkarıp

Bahçelerin hayatına yerleştiren esrar

bizi bırakmıştın

acı güller salınırdı kanımın raddelerinde

ve ben güneş altında kendini bize öptüren neyse

gece onun kimlerle buluştuğunu araştırdım

o zaman yalın yürek kaldım şiddetin çölünde

aldanışların çölünde korkudan

denize dilimi soktum ayaklarımdan önce.

Bu kadar, bu kadardı Akdeniz

aslı yokmuş dinlediklerimin

eski moda güneş sanrılarından

bir şair cesedinden hiç farkı yok denizin.

Yok ve yaz günleri beni hatırlamıyor

boğulmuş hüznü gösteriyor bana memelerinden

geçiyorum bir yakıcı maviden derinleştirilmiş mora

geçiyorum ayaklarım altında kumları hıçkırtarak

Kara yaz! Karanlık yaz! Kararan vücutlardan

rıhtıma varmayan ceset elbette hatırlanmaz.

(1974)', '"Kim yeni terleyen bıyığına, sakalına sevdalanmışsa  Ölünceye kadar bu daireden dışarıya ayak atamaz" -Hafız- Yaz günleri beni hatırlamıyor....', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/akdenizin-ufka-dogru-mora-calan-mavisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer - 2', 'rubailer-2-omer-hayyam-1vs5q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya yıldıramazsın beni ne yapsan

Ölümden de korkmam, er geç ölür insan

Ölmemek elimizde değil ki bizim

İyi yaşamamak, beni tek korkutan', 'Dünya yıldıramazsın beni ne yapsan Ölümden de korkmam, er geç ölür insan Ölmemek elimizde değil ki bizim İyi yaşamamak, beni tek korkutan...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-sunay-akin-sgglk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dürüst olalım beyler

İlk adım sizden

Sökün savaş gemilerinden

Can simitlerini', 'Dürüst olalım beyler İlk adım sizden Sökün savaş gemilerinden Can simitlerini...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/davet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer - 4', 'rubailer-4-omer-hayyam-zg6ag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Barış istemiyorsa Felek, işte savaş

İster serseri deyin bana, ister ayyaş

İşte şarap duruyor ortada, kıpkızıl

İçmeyen taşa çalsın başını, işte taş', 'Barış istemiyorsa Felek, işte savaş İster serseri deyin bana, ister ayyaş İşte şarap duruyor ortada, kıpkızıl İçmeyen taşa çalsın başını, iş...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer - 5', 'rubailer-5-omer-hayyam-8bt48', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şarap küpü önünde serdik seccademizi

Şarap yakutuyla adam ettik kendimizi

Umudumuz, meyhanede yeniden bulmak

Camide, medresede yiten günlerimizi', 'Şarap küpü önünde serdik seccademizi Şarap yakutuyla adam ettik kendimizi Umudumuz, meyhanede yeniden bulmak Camide, medresede yiten günleri...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer - 6', 'rubailer-6-omer-hayyam-wct7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rintlerin yolunda kendini unut

Namazın, orucun kökünü rut

Ögütlerin iyisini Hayyam''dan işit

Şarap iç, yol kesme, yoksulları tut', 'Rintlerin yolunda kendini unut Namazın, orucun kökünü rut Ögütlerin iyisini Hayyam''dan işit Şarap iç, yol kesme, yoksulları tut...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer - 7', 'rubailer-7-omer-hayyam-enu2h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Felek ne cömert aşağılık insanlara

Han, hamam, dolap, değirmen, hep onlara

Kendini satmayan adama ekmek yok

Sen gel de yuf çekme böylesi dünyaya !', 'Felek ne cömert aşağılık insanlara Han, hamam, dolap, değirmen, hep onlara Kendini satmayan adama ekmek yok Sen gel de yuf çekme böylesi dün...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-metin-yalti-slr12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün gelir 

koşullar değişir sevgiler ölür

gün gelir

inançlar değişir fikirler ölür 

gün gelir 

ümitler yıklır ,imgeler ölür

gün gelir 

kurumlar yıkılır,kavramlar ölür

gün gelir

teknoloji  durur gelişme ölür 

gün gelir 

mücadele durur insanlık ölür 

gün gelir

doğa kirlenir canlılar ölür

gün gelir

değerler kirlenir toplumlar ölür

gün gelir

hoşgörü azalır dostluklar ölür

gün gelir

sevinçler azalır çoşkular ölür

gün gelir

çığlıklar başlar sükunet ölür

gün gelir

savaşlar başlar barışlar ölür

gün gelir

yobazlık çoğalır çağdaşlık ölür

gün gelir

aymazlık çoğalır demokrasi ölür

gün gelir,gün biter 

gücü tükenir METİN YALTI ölür 

gün gelir 

yepyeni bir ışık doğar aydınlanır ülkem 

gün gelir

Mustafa Kemal doğar ATATÜRK GELİR...

                       5/4/19994  İSTANBUL', 'gün gelir  koşullar değişir sevgiler ölür gün gelir inançlar değişir fikirler ölür  gün gelir  ümitler yıklır ,imgeler ölür gün gelir  kurum...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gun-gelir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altı', 'alti-can-yucel-levcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçen gün görüşe gelenlerin isimleri okunurken hoparlörde, 

Otobüs Terminalleri düştü aklıma;

Aynı çatlak ses, aynı nalça ağız:

Adana''dan İstanbul istikametine gitmekte olan

Gazanfer Bilge Turizm Otobüsü Yolcuları

Otobüsünüz hareket etmek üzeredir...

A, baktım, şaka maka derken, daldırıp gidiyorum

İstanbul istikametine!..

Tıp! Tıh! Tıh! Tıh! Tıh!

S...mışım ben böyle 1930 model ranzayla çıkılan 

İstanbul seyahatinin içine!', 'Geçen gün görüşe gelenlerin isimleri okunurken hoparlörde,  Otobüs Terminalleri düştü aklıma; Aynı çatlak ses, aynı nalça ağız: Adana''dan İs...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldandım', 'aldandim-erol-corlu-13uib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Candost''tan... candost''a

At sürdüm

Yüreğimin Orta Asyalarından

Zeytin karası gözlerine,

Dağ aştım

Dere geçtim

Çöl ortası

Serap sen sandım aldandım.

İz sürdüm

Zeytin karası gözlerinde

Bir yıldız sıra

Karanlıklarında gecelerin,

Dağ aştım

Dere geçtim

Gün ortası

Seher sen sandım

Aldandım.

Yıldız topladım

Zeytin karası gözlerinden,

Gecelerine

Ebem kuşağı gönlümün,

Dağ aştım

Dere geçtim

Gece ortası

Işık sen sandım,

Aldandım

Ve ağladı ay şafağım

Bir yağmur arkası,

gönlünde

Dağ kadar

Doğuramayıp düşüreceği

Bir SEVGİye

Gebelik sancısı ile,

Aşk sen sandım

Aldandım', 'Candost''tan... candost''a At sürdüm Yüreğimin Orta Asyalarından Zeytin karası gözlerine, Dağ aştım Dere geçtim Çöl ortası Serap sen sandım al...', ARRAY['Türk Edebiyatı','Şiir','Erol Çörlü']::text[], 8.5, '{"poet":"Erol Çörlü","poet_slug":"erol-corlu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/aldandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Ben Ya Sen', 'ya-ben-ya-sen-beril-dilek-k23qb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bakışla bin söz anlatamadım

Bir sözle sana sevgimi duyuramazdım

Bir an bir ömre değer sandım

Ya ben yanlış anlattım, ya sen yanlış anladın

Bir hayat adadım  sana bilmedin

Bir ölüm olacak sonunda, farketmedim

Hayatta ölüm arasında kısa çizgi sendin

Ya ben yanlış anlattım, ya sen yanlış anladın

Bazen nefessiz kaldığımda, nefesimdin

Bazan solan çiçeğimin nedeniydin

Ama sen hep sevildin

Ya ben yanlış anlattım, ya sen yanlış anladın

Bilinmeyenlere ulaştım seninle

Aşkın anlamını aradım sevginle

Bulduğum ise;

Ya ben yanlış anlattım, ya sen yanlış anladın.', 'Bir bakışla bin söz anlatamadım Bir sözle sana sevgimi duyuramazdım Bir an bir ömre değer sandım Ya ben yanlış anlattım, ya sen yanlış anlad...', ARRAY['Türk Edebiyatı','Şiir','Beril Dilek']::text[], 8.5, '{"poet":"Beril Dilek","poet_slug":"beril-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-ben-ya-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-beril-dilek-ffhk5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamayı seviyorum

Yaşamımda sen olduğun için

Dostluğu seviyorum

Dostum sen olduğun için

Gülmeyi, ağlamayı seviyorum

Seninle birlikte olduğu için

Seni seviyorum

Sen olduğun için

Sevmeyi seviyorum

Sevmeyi hakettiğin için.,', 'Yaşamayı seviyorum Yaşamımda sen olduğun için Dostluğu seviyorum Dostum sen olduğun için Gülmeyi, ağlamayı seviyorum Seninle birlikte olduğu...', ARRAY['Türk Edebiyatı','Şiir','Beril Dilek']::text[], 8.5, '{"poet":"Beril Dilek","poet_slug":"beril-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seviyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehirler', 'nehirler-seref-yellidag-jgd68', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nehirler akti gecti, 

Kurudu vakti gecti, 

Nice Hân, nice Sultân,

Tahti birakti gecti,

Su dünya bir penceredir,

Her gelen bakti gecti', 'Nehirler akti gecti,  Kurudu vakti gecti,  Nice Hân, nice Sultân, Tahti birakti gecti, Su dünya bir penceredir, Her gelen bakti gecti...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nehirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaccak', 'kaccak-seref-yellidag-mdp3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizliginin sinirlarina gizlenecegim;

Konusma!

Yoksa fark edilecegim..

Gögsümde,eski bir esmerin acisini biriktirdim.

Hüzünlerim,ondan yadigar..

Yagmurun saclarini ördüm,sacaklarda,

Bu ayrilik üsütüyor beni!

Kollarini ac,

Yoksa delirecegim..

Gürültüsünü tasimaktan yoruldugum,

Ve,karmasasin da kayboldugum sehrin,

Delice,korktugu bir sessizliktin,sen!

Sessizligine siginmistim isikli gözlerinin,

Simdi,zedeleme halini kelimelerle!

Gözlerini sun bana!

Gözlerinden her seyi ögrenecegim!

Konusma!

Gerceklerin kacagiyim ben.

Konusma!

Yoksa,bu siiri terk edecegim!', 'Sessizliginin sinirlarina gizlenecegim; Konusma! Yoksa fark edilecegim.. Gögsümde,eski bir esmerin acisini biriktirdim. Hüzünlerim,ondan yad...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kaccak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-seref-yellidag-p5jpz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susarak anlatt&yacute;n bütün gizliyi 

Saklad&yacute;m duygumu ben konu&thorn;arak 

Bir ac&yacute; tarlas&yacute; sessiz yüzünde 

A&thorn;k&yacute; yürürlü&eth;e koyma sava&thorn;&yacute; 

&Yacute;çimde bir düzen kayna&thorn;maktad&yacute;r

Büyük ve çekingen bak&yacute;&thorn;lar&yacute;ndan

En iyi anlat&yacute;&thorn; art&yacute;k susmakt&yacute;r 

Anlad&yacute;m bunu ben seni bilince', 'Susarak anlatt&yacute;n bütün gizliyi  Saklad&yacute;m duygumu ben konu&thorn;arak  Bir ac&yacute; tarlas&yacute; sessiz yüzünde  A&thorn;k&...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerdesin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-bir-garip-sair-urun6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'evler yanardı,

istanbul sokaklarının 

bitmeyen gecelerinde

ve sönmeye muhtaç güneşin

inadına parlardı yıldızlar,

sonra bir yelkenli ile açılırdı 

içtikten sonra kaldırımlar

kimi kaybetmiş aşkını,

kimi istanbulu arardı

istanbulun içinde

istanbul sokakları

hep kendimi kaybettiğim

sokaklar,

bilmiyorsunuz değil mi?

bende yalnızım sizin gibi

kalabalığın içinde....', 'evler yanardı, istanbul sokaklarının  bitmeyen gecelerinde ve sönmeye muhtaç güneşin inadına parlardı yıldızlar, sonra bir yelkenli ile açıl...', ARRAY['Türk Edebiyatı','Şiir','Bir Garip Şair']::text[], 8.5, '{"poet":"Bir Garip Şair","poet_slug":"bir-garip-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesişen Yazgılar', 'kesisen-yazgilar-cem-acar-kjrp4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tesadüflerin kesişme bileşkesinde

rastlaşan yaşamlarımız....

Grikentin renksiz bir binasında

iken

yaşanılanlar 

bazen renkler cumbüşü tadında

iken

bazen de

karlar altında,bembeyaz

ama

soğuk...

dostluk

sorgulamaları

kesişme bileşkelerinde

lakin...

dokuzlar dünyasındaki

dar alanlarda

kısa paslaşma misali...

sen

rengini yitirmeme telaşlarını 

taşır iken geleceğin umutlu

yarınlarına..

bilki

yanındayım

çok uzağındayken...

20 aralık 2000

-ankara-', 'Tesadüflerin kesişme bileşkesinde rastlaşan yaşamlarımız.... Grikentin renksiz bir binasında iken yaşanılanlar  bazen renkler cumbüşü tadınd...', ARRAY['Türk Edebiyatı','Şiir','Cem Acar']::text[], 8.5, '{"poet":"Cem Acar","poet_slug":"cem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kesisen-yazgilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Muhacir Kızı-2-', 'ah-muhacir-kizi-2-bayram-tunca-9w3ox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay’ım, Güneş’im yıldızım

Ah benim muhacir kızım

Bitmez ki artık içimdeki sızım

Aşk ateşin yakmakta be kızım

Muhacir Kızı, evin biricik kızı

Çok mu çok, çekilmiyor nazı

Ömrümün çoğu gitti, kaldı azı

Bahtıma yazılmış muhacir kızı

Benim yârim Muhacir Kızı

Görünce içime aldı bir sızı

Ailesinden isteteceğim, ben o kızı

Bahtıma yazılmış bu muhacir kızı

Muhacirin vardır böyle güzel kızı

Onu görünce içime düştü bir sızı

Vermezlerse, kaçırırım ben o kızı

Bahtıma yazılmış, o muhacir kızı

Ah Muhacir kızı, Muhacir kızı

Ne de çokmuş, çekilmiyor nazı

Ömrün çoğu gitti, kaldı çok azı

Hiç olmazsa, gelseydi bazı bazı

Alamadım, içimde vardır bir sızı

Acaba ne yaptılar ki o güzel kızı

Vermezlerse, kaçıracağım o kızı

Bahtıma yazılmış o muhacir kızı

Nasipmiş aldım, o Muhacir kızını

Ne de çokmuş, çekemedim nazını

Verin benim elime dudu dilli sazımı

Dostlarıma anlatayım o alın yazımı

Ah Muhacir kızı, Muhacir kızı

Kalbime bıraktın, dermansız bir sızı

Ömür boyu, hiç dinmez artık bu sızı

Ne edem, bahtıma yazılmış bu yazı

Nereden de çok sevdim, ben bu muhacir kızı

Bu güne kadar dinmedi, dinmez artık bu sızı

Siz söyleyin, ben ne yapayım bu muhacir kızı

Her şeyine rağmen, ne çok seviyorum bu kızı', 'Ay’ım, Güneş’im yıldızım Ah benim muhacir kızım Bitmez ki artık içimdeki sızım Aşk ateşin yakmakta be kızım Muhacir Kızı, evin biricik kızı ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ah-muhacir-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra', 'yillar-sonra-bayram-tunca-06z05', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar geçse de o sima değişmemişti

Yıllar geçse de o nida değişmemişti

Yıllar geçse de o kalb değişmemişti

Yıllar geçse de o aşk değişmemişti

Yıllar geçse de o damardaki kan değişmemişti

Yıllar geçse de o bedendeki can değişmemişti

Yıllar geçse de o kalbteki canan değişmemişti

Yıllar geçse de ondaki güzellik, değişmemişti

Yıllar sonra görmek nasıp oldu o aşına simayı

Hemen görür görmez hatırladım o nur simayı

O simayla birlikte, o anılarımızı da hatırladım

Boşanan bir yay gibi taa çocukluğuma gittim

Ne kadar değişse de, yine de farklıydı bu sima

Daha görür görmez, içimdeki o his” bu o sima”

Hemen sarıldım boynuna, o da hatırladı bana

Birlikte yâd ettik, o mazide kalan anılarımıza

Alında patika yollar oluşsa da o değişmemişti

Yıllar geçse de o günlerin anısı değişmemişti

O öyle bir sikke vurmuş ki karışmamıştı simalar

Yıllar sonra da karşılaşılsa, çok aşınaydı simalar

B. TUNCA/20.12.2000-12.43', 'Yıllar geçse de o sima değişmemişti Yıllar geçse de o nida değişmemişti Yıllar geçse de o kalb değişmemişti Yıllar geçse de o aşk değişmemiş...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yillar-sonra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Silifkeli Hacer Git...', 'git-silifkeli-hacer-git-halil-i-brahim-deveci-x41q6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '* Bu şiirim, Asrın aşkını uğruna feda ettiğim Silifke''li Hacer AYDIN''a ithafen yazılmıştır.

Ne kadar matemin varsa

Bana bırak da git...

Silme gözyaşlarımı

Sadece ardına bak da git!

Sakın pişman olma

O; ilk ve son gidişinden

Kâbuslarını elinle it!

Yorgun akşamların elemi,

Kalp çırpıntını etkilemesin

Kovduğun o kâbuslar geri gelmesin

Öyle bir gidişin olsun ki; Bu

Zamanda tek, mekânda meçhûl

Bir yağmur damlası gibi

Kalpten damara ak da git...

Geceleri perçinle, yalnızlığa

O gelen ilk şafak da git...

Tüm SEVGİLİLERİ yolcu et hatıralara

Kader gibi

                 Felek gibi

Sen de bir sille çak da git!..

Öylesine git ki; 

                         Kalmasın ümit

O doyumsuz ümitlerimi başıma kak da git...

Yalnız kakmakla kalma;

Sel olan gözyaşlarımın ardında

''HACER'' adlı bir şimşek olup;

Şimşek gibi çak da git!...

                           (14.04.1999-Tuzluca)', '* Bu şiirim, Asrın aşkını uğruna feda ettiğim Silifke''li Hacer AYDIN''a ithafen yazılmıştır. Ne kadar matemin varsa Bana bırak da git... Silm...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/git-silifkeli-hacer-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönme HACER', 'donme-hacer-halil-i-brahim-deveci-58akz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşlar dönse de yuvaya

              sakın

   Sen dönme canım!...

Hasretin yaşamıma devâ

Ben; hasretle onulmaz bir yarayım

Sen geri gelirsen

          Ben giderim senden

sakın

       dönme bir daha

Mâzinin serin uykularında 

                                         ağlıyor           

Sen; mâzinin ızdırabı

Ben;âtînin nabzı

Kaç asır kaç kahkaha da boğuldu

Mâzi ağlarken sen güldün

yaşananlar bir hayâldi

Ve sen, onu böldün

Kopmamalıydı hayatın şeridi

Git

     Durma

               Koş

Ardına bakma!

Menziller içiyor seni

menziller sana gebeyken

sen menzillerin olmalısın!

Artık açmıyor mazinin gülleri

Kaç gitmeye hapsettin bülbülleri

Ey kor gözlü Silifkeli HACER!

Sınırı ne idi yaşamanın

kuralda kuralsız olmak mı?

Sen tüm kuralları astın

bir aşığın son ağlamasına

Gözyaşı bulutları göklerde

''Seni ağlıyor gözbebeklerim!''

             sakın

Dönme geriye....

Geride kaldı gülmeleri

açan güllerin

Şimdi güller ağlıyor!

sabahı gelmez gecelerde

Bir kuytu siniş var

aşka dair düşüncelerde

onulmaz yarasına devâ bulamaz

kalbim seni bekler de!...

     Açık pencerelerde

Ve hiç kapanmadı

O sonsuz perde

Nerede?

İşte cevapsız kalan soru:

''AŞK NERDE?''

Karmakarışık duygular

Sardı yine beni

Ağlasam mı?

                    Gülsem mi?

Yaşasam mı?

                     Ölsem mi?

Sen vardın eskiden

Hayat anlam yüklüydü

Gözlerim gözlerindeyken 

Hayatın sancısı yoktu

      Gülen gözbebeklerimdi

Ümidi yeşertmiştim

Aşkın sahrasında

       Feleğin şafağında

Bir küheylandı menziller

Yaklaştıkça sana koşan

Ben değildim menzillerdi...

AH HACER!....

Benden gitmemeliydin

Beni terk etmemeliydin

      Yeni başlıyordu;

Aşkın Asrı....

Çağ çağ seni yaşayacaktı

Sevenlerin gözleri

Bir ılık meltem kaplayacaktı

                   Tüm gönülleri

Ve umut... 

             açacaktı

kapanan tülleri

Ve sen doğacaktın

Her giden günün ardından

Ben sana gelecektim

Gönül yurdundan

Kahkahası kaplayacaktı çocukların

Aşk yaşanan her yeri

Böyle solmayacaktı

Böyle bitmeyecekti

Gözlerin Ferî

                      (2000-AKSEKİ)', 'Kuşlar dönse de yuvaya               sakın    Sen dönme canım!... Hasretin yaşamıma devâ Ben; hasretle onulmaz bir yarayım Sen geri gelirsen...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/donme-hacer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yolu', 'sevda-yolu-bir-garip-sair-69kg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şakaklarımdaki yalnızlık

ve acılarım susukun hali

  anılmayacak bir tarihin içine 

  gömdüğüm

sanma ki seni de bulmaz

kahreden sevdalar

sanmaki acır sana

   ayrılıklar....

ve yabancı olduğun avuntular

onlarda mı 

bırakır seni

düşmeye gör

bir sevdanın peşine

ağlamaklı günler

sessizliği bozar şekilde

çoğalır ve içini dağlar

sayamazsın bile 

mutluluğunu 

yoktur çünkü ondan başka 

mutluluk

ve yükselir bir anda 

ölüm sessizliği

sonrası 

senin yokluğunu hisseder hayat

ve sende hayatın yokluğunu

acıyan yanlarınla,

sevdanla ama sevdasız 

hissedersin', 'şakaklarımdaki yalnızlık ve acılarım susukun hali   anılmayacak bir tarihin içine    gömdüğüm sanma ki seni de bulmaz kahreden sevdalar sanm...', ARRAY['Türk Edebiyatı','Şiir','Bir Garip Şair']::text[], 8.5, '{"poet":"Bir Garip Şair","poet_slug":"bir-garip-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevda-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Ayrılığı', 'yaz-ayriligi-metin-cengiz-eyaux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte yaz tükendi. O göçebe yaz

Güneşe kavuştu kırlangıçlar çoktan

Sokaklar azaldı, merhamet istiyor günler

Yine gece. Yaşıyoruz eski çilelerimizi

Seninle ayrı seninle beraber

Şimdi eski bahçelerdeyiz. Dualar içre...

Birer aşk şarkısıyız ayrı tınılı

Günler sayılı. Isındı gölgelikler

Sessizlik bir gölün nabzıyla atıyor

Şimdi eski bahçelerdeyiz. Dualar içre...

Duygular kış çiçeklerinde de açar

Elemli, kırılgan da olsalar...

Akşam olunca yaralar kanar

Solar kızıl gül bahçesi ufuklarla

Duygular kış çiçeklerinde de açar

Perdeleri çek kilitle kapıları

Kanma sakın ayın sihirli sesine

Bahar bahçene kuş gibi konsa da kanma

İşte yaz tükendi, o göçebe yaz

Sokaklar azaldı, merhamet istiyor günler', 'İşte yaz tükendi. O göçebe yaz Güneşe kavuştu kırlangıçlar çoktan Sokaklar azaldı, merhamet istiyor günler Yine gece. Yaşıyoruz eski çileler...', ARRAY['Türk Edebiyatı','Şiir','Metin Cengiz']::text[], 8.5, '{"poet":"Metin Cengiz","poet_slug":"metin-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yaz-ayriligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmge', 'i-mge-metin-cengiz-g9vzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Aşk bıçak gibidir, dedi, alışılmış

biçim verir insana yosunlu büyülerle

Bazen etinde dağlanır insanın söz

sarsılmış, saralı gövde gibi

altın külçe nasıl durursa asitte

öyle iner eski zaman türküsüne

İşte göksel giz, çözülemeyen

sürükler bizi peşinden saf gücüyle''

Ses, taş ve suyun soluğuydu, ıssız

koyları dolaştı durdu, fışkırıp gövdemde

akkor bir nü gösterdi duvara asılı

bir gül... kokusu tünellerden tünellerle gelen

yazla baygın ırmaklardan göllerden

''Aşkın iki ağzı dört gözü yoktur ama

sarışı bir sarışı var ki

saf isyan sözcüklerle

haykırır kendini kendine''

Tam böyle dedi işte, çıkıp yüreğimden

elyazılarına benzeyen kırlangıç sürüleriyle', '''Aşk bıçak gibidir, dedi, alışılmış biçim verir insana yosunlu büyülerle Bazen etinde dağlanır insanın söz sarsılmış, saralı gövde gibi altı...', ARRAY['Türk Edebiyatı','Şiir','Metin Cengiz']::text[], 8.5, '{"poet":"Metin Cengiz","poet_slug":"metin-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/imge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mevlut-serttas-ppqmp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için Güneşi tuttum yine ,

Gözlerimdeki iki damla yaşla beraber .

Acıları kederleri attım göğe ,

Her şeyi senin için ...

Sabahın ilk ışıklarında çıktım yola ,

Türküler söyledim dağlara taşlara .

Ağıtlar yaktım yüreklerdeki sevdalara ,

Her şeyi senin için ...

Gülü hep dikeninden kokladım ,

Yaralarımı sevdanla dağladım .

Gülerken her zaman ağladım ,

Her şeyi senin için ....', 'Senin için Güneşi tuttum yine , Gözlerimdeki iki damla yaşla beraber . Acıları kederleri attım göğe , Her şeyi senin için ... Sabahın ilk ış...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Serttaş']::text[], 8.5, '{"poet":"Mevlüt Serttaş","poet_slug":"mevlut-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-icin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylaklar', 'aylaklar-ahmet-telli-qav9r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün bir gün sırtüstü 

uzanıp dere kıyısında

dinledik suyun akışıyla

kavakların hışırtısını

Mor incirler kopardık

kuşluk vakti dallardan

soğuttuk soğuk sularda

ürküterek kurbağaları

Öğleye doğru köylüler

bir sepet kehribar üzüm

ve domates getirdiler

bir topak da peynir

Onlar işlerine döndüler

biz yalnız kaldık yine

umursamaz tarlakuşları

uçuşup durdu üstümüzde

İkindiye doğru derede

taş sektirdik, yüzümüzü yıkadık

bir taş atımı ötede

sıçrayıp kaçtı bir dağ tavşanı

Akşamın bir vaktinde

köylüler sepetleriyle

ve türküleriyle gelip

kondular dere kıyısına

Meşe dalları toplanıp

ateş yakıldı orta yere

çevirdik erafını hepimiz

konuştuk şundan bundan

Sonra kıvrılıp yattılar

uyuyakaldılar hemencecik

Ortada küllenen ateş

gökte yürüyen ay kaldı

Uyuyamadık biz bir zaman

Çobanların çok ötelerden

gelen türkülerini dinledik

bir de kendi nefeslerimizi

Sabah erkenden gittiler

biz kaldık yine orada

ve yine sırtüstü uzanıp

dinledik kendimizi bir süre

Ne köylüler yüz verdi bize

ne de bütün bir gün

dere kıyısında

düdüğünü öttüren çocuk', 'Bütün bir gün sırtüstü  uzanıp dere kıyısında dinledik suyun akışıyla kavakların hışırtısını Mor incirler kopardık kuşluk vakti dallardan so...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/aylaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Aklımda Yokken', 'hic-aklimda-yokken-okan-malgas-r46ig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç aklımda yokken ve senin bilmediğin bir yerde

yoluna çıksan seviyorum desem 

şu karşıki dağdan bağırsam nefesim tükenene dek

tüm şehre

canımsın desem.

koşsam kan ter içinde 

en uzakdaki en güzel çiçeği toprağıyla getirsem

kuş olsam uçsam kurumuş yanlızlığına bir damla su getirsem

en el değmemiş pınarların en derin yerinden

yada hiç aklımda yokken ve senin bilmediğin bir yerde

yoluna çıksam seviyorum desem olur mu', 'hiç aklımda yokken ve senin bilmediğin bir yerde yoluna çıksan seviyorum desem  şu karşıki dağdan bağırsam nefesim tükenene dek tüm şehre ca...', ARRAY['Türk Edebiyatı','Şiir','Okan Malgaş']::text[], 8.5, '{"poet":"Okan Malgaş","poet_slug":"okan-malgas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hic-aklimda-yokken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Kız', 'al-kiz-okan-malgas-6zfos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alkız yüreğini alda gel.

Umutların varsa yağrına taşınacak,

onlarıda getir.

Getirki koyalım üst üste,

koyalım ki görsün nağmert takımı

Umutsuz yaşanmaz bu dünyada.

Eğme başını alkız ölürüm ben eğme,

büsbütün ve dosdoğru gel

denize kavuşan asi bir ırmak gibi.', 'Alkız yüreğini alda gel. Umutların varsa yağrına taşınacak, onlarıda getir. Getirki koyalım üst üste, koyalım ki görsün nağmert takımı Umuts...', ARRAY['Türk Edebiyatı','Şiir','Okan Malgaş']::text[], 8.5, '{"poet":"Okan Malgaş","poet_slug":"okan-malgas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/al-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-ahmet-telli-rwurg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I/

Gün ağarmadan yola çık

sislenmeden bütün dağ taş

Dönüp dönüp bakma artık

bir ozan gibi ayrılığa düş

Dehşetli bir acıdır belki

uçurum, orman ve rüzgar

ve ağzında kuş tüyleri

taşıyarak geçen bulutlar

Neyi bırakmışsan geride

bir kül yığınıdır şimdiden

ömrün gibi savrulup gider işte

Ama ıslığını unutma sakın

bir türküdür yine de

yolcuya en çok yakışan

II/

Dağın eteklerine vardığında

şöyle bir dur ve soluklan

sonra meşeliklerin orada

sırtüstü uzan gün batarken

Dinle bir an ormanı ve suyu

başlayacaktır az sonra

doğanın yabanıl konçertosu

hışırtılar içinde kalacak ova

Kayıp giderken bulutlar

usulca sokulacak yüreğinin

gizli geçitlerine bir rüzgar

Buğulu türküler duyacaksın

ve aşk çılgınlıklar bekleyecektir

yolları uçurumla kesilenlerden

III/

Dizginlerinden boşanmış bir at

gibi soluk soluğayken doğa

soluğun yetiyorsa yaylanıp tut

yelesini ve katıl rüzgara

Unutma ki yalnız değilsin

yüreklendiriyor seni aşk

ve birdenbire boşanan

bu çılgın sağanak

Aşk ile sağanak

hep aynı kokuyu taşıyacak

hangi kentte bir koklasan

Yolculuklar özetleyecek ömrünü

Gülüşü ve hüznü sürükleyen büyü

elinde bir gül olacak sevdiğinin', 'I/ Gün ağarmadan yola çık sislenmeden bütün dağ taş Dönüp dönüp bakma artık bir ozan gibi ayrılığa düş Dehşetli bir acıdır belki uçurum, orm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yolcu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançerin Sapı', 'hancerin-sapi-metin-altiok-nr7py', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haksızlık etme 

Diyorum kendime;

Onurlandırıldın da,

Kınandın da sen.

Kendini kül dolu 

Bir küpe gömdün.

Tersyüz ettin 

Sevgini eskidikçe.

Güzel günler yaşadın.

Çiçeklerin oldu,

Bir evin örneğin;

Güneş gören,

Dağlara dönük balkonu.

İşte bu yüzden 

Ağlarım ben 

Kestaneler çatlarken.

Sabahın buğusu

Gözlerimi yaşartıyor,

Boynuma dolanıyor

Akşam zinciri.

Dağlardır beni avutan.

Söyleyin bana

Gözünüzü kırpmadan;

Sizce dönek midir zaman?

Eşkıyalar dağları 

Anlayamazlar.

Çünkü suçtur onları

Dağlara çıkartan.

Darasıdır suç oysa

Yaşadığımız dünyanın.

Dağlar sizi 

Pekmez ile kararım.

''Öyle yaralıyım ki;

Ölmem ben artık.''

Ölmem ya kanarım,

Kanarım seve seve.

Haksızlık etmem 

Suya ekmeğe

Hiç bir anahtar

Dönmese de kilidimde.

Bekliyorum kaç zamandır;

Uykusuzum,sabırsızım.

Başımı acıtıyor

Geceleri yastığım.

Dilim kurumuş

Bir su yatağı,

Katı sözcüklerle

Dolu tozlu ağzım.

Bakıyorum eski

Fotoğraflara.

Hfız Burhan dinliyorum

Taş plaklardan.

Bir pencere çarpıyor

Viran yüreğimde,

Sıvalar dökülüyor

Pervazından.

Dörtnal giden

Ürkek bir attan

Düşüyorum de sanki,

Takılı kalıyor

Ayağım üzengiye.

Sürükleniyorum

Sırtüstü

Çalılar,dikenler içinde.

Mevsim kışa dönüyor,

Hızar sesleri geliyor

Dörtbir yandan.

Odun taşıyor

Yorgun kamyonlar.

Kuşlar da gitti.

Çiçekler gelecek bahara

Tohum saçıyor.

Ey benim umudumu

Bölük bölük

Eden hızarlar,

Bu yıl da

Kalıcıyım burda

Verilmiş sözüm var.

Bensiz yapamaz

Lapa olur pirinç kar.

Elimden tutmuş 

Sevecen gençliğim,

Buzdan bir yolda

Düşe kalka

Yürümeyi öğretiyor

Yeniden bana.

Geçmiş deyince 

Sen geliyorsun aklıma.

Sahi sen yaşadın mı;

Var mıydın acaba?

Yaşadık mı seninle

Aynı zaman parçasında?

Ama ellerin aklımda.

İri gözlerin,

Sıcaklığın geceler boyu

Ve aklığın aklımda.

Senin ağzın tarçın kokardı,

Benimki karanfil.

Birbirine karışırdı

Soluklarımız.

Tek başınayız şimdi ikimiz.

Bende karanfil,

Sende tarçın kokusu

Yapayalnız,kimsesiz.

Ben seni yalansız

Bahar gibi sevdim.

Sevgi adınaydı

Milis beraberliğimiz.

Sabahtan akşama

Günü tarar örerdik

Ve kedileri

İkimizde çok severdik.

İkimiz de yıldız düşkünü;

Bakmaya doyamazdık 

Gökyüzüne.

Koynunda terli ferman

Bir atlı geçerdi

Samanyolundan,

Kimsenin göremediği

Kibrit çakımı bir an.

Hiç unutmam;

Adına sikke bastırırdı

Aşk o zaman.

Yani ay doğardı

Tepelerin ardından.

Güzel günlerimiz oldu,

Gecelerimiz

İpek ve kılabtan.

Omuzunda uzun saplı 

Eğri tırpan

Ot biçmeye gidiyor

Avurtları çökük

Bir gölge adam.

Karalar giyinmiş,

Ölüm simgesi gibi

Geçiyor sokaktan.

Kulaklarım uğulduyor,

Yapılar eğiliyor,

Çinko damlar

Daraltıyor gökyüzünü

Alaca bir bulut

Geliyor üstüme

Yuvarlana yuvarlana 

Kurşundan bir köpekle.

Haksızlık etme

Diyorum kendime.

Kılavuzun oldu rüzgar,

Su gibi dostun.

Eğer dumanlıysa

Kavruk dağlar;

Bil ki gülün ahı,

Hançerin sapı var.

Ey benim umudumu

Bölük bölük

Eden hızarlar,

Oluklu hançer,

Güle narh koyanlar;

Şahmaranın başı için 

Payınıza düşen ne?

Bir gün sorarlar.', 'Haksızlık etme  Diyorum kendime; Onurlandırıldın da, Kınandın da sen. Kendini kül dolu  Bir küpe gömdün. Tersyüz ettin  Sevgini eskidikçe. G...', ARRAY['Türk Edebiyatı','Şiir','Metin Altıok']::text[], 8.5, '{"poet":"Metin Altıok","poet_slug":"metin-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":160,"source_url":"https://www.antoloji.com/hancerin-sapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone VII', 'sone-vii-metin-altiok-i47jj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başımda siyah şapka, elimde çiçek; 

Bekliyordum ikide bir saatime bakarak.

Yüreğim dalından düştü düşecek, 

Çıplak bir ağaçta sanki tek yaprak.

Derken sen geldin bir sis içinden; 

Serildi dürülüm, dolaşığım çözüldü.

Bir mavilik yayıldı etrafa gözlerinden, 

Yalnızlığım çaresiz bir kenara büzüldü.

Ne ben bekledim oysa, ne de sen geldin; 

Gerçekleşmedi henüz söz ettiğim buluşma.

Çünkü sen benim hak edilmiş ecelimsin, 

Nasibim olacak ömrümün sonunda.

Herkes kendince göçer bu yeryüzünden; 

Kimse pay çıkarmasın başkasının ölümünden.', 'Başımda siyah şapka, elimde çiçek;  Bekliyordum ikide bir saatime bakarak. Yüreğim dalından düştü düşecek,  Çıplak bir ağaçta sanki tek yapr...', ARRAY['Türk Edebiyatı','Şiir','Metin Altıok']::text[], 8.5, '{"poet":"Metin Altıok","poet_slug":"metin-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerim', 'ozlerim-hamdi-ozer-bet1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlerim, özlerim seni özlerim.

Özlerim sendeki beni özlerim.

Neyleyeyim sensiz geçen bin yılı,

Seninle geçen bir günlük demi özlerim.', 'Özlerim, özlerim seni özlerim. Özlerim sendeki beni özlerim. Neyleyeyim sensiz geçen bin yılı, Seninle geçen bir günlük demi özlerim....', ARRAY['Türk Edebiyatı','Şiir','Hamdi Özer']::text[], 8.5, '{"poet":"Hamdi Özer","poet_slug":"hamdi-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dertler Benim Olsun', 'dertler-benim-olsun-orhan-gencebay-xunu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir zamanlar benim sevgilimdin

yanımdayken bile hasretimdin

şimdi başka bir aşk buldun

mutluluk senin olsun 

ben daha ne çile dertlere yolcuyum 

ben anlına dert yazılan kader mahkumuyum

farketmez yaşamak sen mesut ol yeter

dertler bana gönül vermiş ben aşk sarhoşuyum

bir gün daha geçti yine sensiz 

aşkım ağlıyor bak sessiz sessiz

çare bensiz ben ben çaresiz

ümidim senin olsun

dertler benim çile benim hayatım senin olsun

isterdim ömrümüz geçseydi beraber

istermiydim ayrılığı gülseydi şu kader

ben çile dert dolu sen ümitler yolu

şimdi sensiz bak seninle geçiyor mevsimler

dilerim her arzun gerçek olsun 

hayat bu şansın hep açık olsun

dertler benim çile benim ümidim senin olsun', 'bir zamanlar benim sevgilimdin yanımdayken bile hasretimdin şimdi başka bir aşk buldun mutluluk senin olsun  ben daha ne çile dertlere yolcu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dertler-benim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Yokluğuna Dair', 'onun-yokluguna-dair-mustafa-erol-cankaya-syy2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşündüm

Duvarlara baktım

Zaman devreden çıktı

Ya da ben zamanın dışına çıktım

Ne sevgisiz zamanlar

Ne zamansız sevgiler

Bir ara sesini duyar gibi oldum

Pencereye koştum

Baktım 

Yoktun

Gözlerimi kapattım

Yine düşündüm

Hani bir şeyi çok istersen olur

Allah biliyor ya

Ne çok istedim

İçimden 10''a kadar saydım

Gözlerimi açtım

Yoktun

Dışarı çıktım

Kimseler yoktu

(Aralık''99)', 'Düşündüm Duvarlara baktım Zaman devreden çıktı Ya da ben zamanın dışına çıktım Ne sevgisiz zamanlar Ne zamansız sevgiler Bir ara sesini duya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erol Çankaya']::text[], 8.5, '{"poet":"Mustafa Erol Çankaya","poet_slug":"mustafa-erol-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/onun-yokluguna-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Olunca', 'aksam-olunca-mehmet-ozturk-4-jje9i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'akşam olunca çöker üstüme hüzün

sen yoksun yanımda gülmüyor yüzüm

kavuşuruz belki yazın belki güzün

aşkımız bitmeyecek buda benim sana sözüm

sensiz değil gün geçmiyor saatler

seviyordun hani nerde o vaadler

sana verdiğim değer boşaymı meğer

yeni bir aşk buldum bu aşık yoluna gider', 'akşam olunca çöker üstüme hüzün sen yoksun yanımda gülmüyor yüzüm kavuşuruz belki yazın belki güzün aşkımız bitmeyecek buda benim sana sözüm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Öztürk 4']::text[], 8.5, '{"poet":"Mehmet Öztürk 4","poet_slug":"mehmet-ozturk-4","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aksam-olunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-kentin-kahini-exjsd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalemim Sen ve Ben

Dislerim demir parmaklık,

Dilimse suçsuz bir mahkum.

Düsünce suçundan yargılanan bir zavallı gibi,

Duygularımı anlatamadım.

Iste bu yüzden yazıyorum bos sayfalara,

Yazıyor yırtıyor ve atıyorum...

Seninle yürüdügüm yollara.

Belki bulup okursun diye,

Okuyup ta geri dönersin diye,

Durmadan yazıyor yırtıyor ve atıyorum...

Seninle yürüdügüm yollara.

Hani ölmemis bir insanı gömersin ya !

İste onun gibi gömüyorum.

Yosun tutmus anılarımı,

Karbeyaz sayfalara.

Kalememin her temasında,

Bir kazma daha vuruluyordu topraga.

Kendim için kazamadıgım mezarı,

Kalemim kazıyordu karbeyaz sayfalara...

Kentin kahini', 'Kalemim Sen ve Ben Dislerim demir parmaklık, Dilimse suçsuz bir mahkum. Düsünce suçundan yargılanan bir zavallı gibi, Duygularımı anlatamadı...', ARRAY['Türk Edebiyatı','Şiir','Kentin Kahini']::text[], 8.5, '{"poet":"Kentin Kahini","poet_slug":"kentin-kahini","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neden-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Ölme Yalvarırım Sana', 'sakin-olme-yalvaririm-sana-kentin-kahini-zeizu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi senden çok uzaklardayım.,

Sen, başına buyruk yaşar sanırsın beni,

Esmer serçem yuvadan uçtu dersin,

Kimbilir ne endişelerin vardır,

Kaygıların ve korkuların,

Buralarda günah işlemek zor değil,

ve sevgine ihanetama şuramdasın, göğsümün sol yarısında..

Kalbimde.....

Bildiklerim, inandıklarım, uğruna yaşadığım güvendiğim dallar yok artık,

Ben özgür değilim,

Ölme anne ne olur ya sana yalvarırım ölme....

Yaşadığım hayatın sahibi değilim,

Bu ben ben değil bir yangın var içimde,

içim içime küskün,

Ağlıyorum yokluğuna ve yalnızlığıma, kimsesizliğime,

Darılma, darılma ama Esmer Serçen yüzünü unuttu,

Nur inmiş yüzünü,

Ölme ölme,

Yalvarırım sakın ölme,yalvarırım sana beni bekle,

Birgün geleceğim,

Birgün,

çağlayanlar gibi biriken sevgimle,

gözlerimde ışık, avuçlarımda sevinçle, ben ben  olarak,

binyıllar önce beni bana nasıl emanet etmişsen,

Hasretimle, özlemlerimle, acılarımla geleceğim,

Bekle beni gözümün nuru,

Sakın ölme Anne...', 'Şimdi senden çok uzaklardayım., Sen, başına buyruk yaşar sanırsın beni, Esmer serçem yuvadan uçtu dersin, Kimbilir ne endişelerin vardır, Ka...', ARRAY['Türk Edebiyatı','Şiir','Kentin Kahini']::text[], 8.5, '{"poet":"Kentin Kahini","poet_slug":"kentin-kahini","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sakin-olme-yalvaririm-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-kentin-kahini-rpftn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Tenim aç ruhum aç ve,

Anlaşılmayan kalbim ve, 

Anlaşılmayan kafam ve, 

Anlaşılmayan vucudum,

Susuyorum hayata karşı,

O da bana karşı susuyor,

Birlikte karşılıklı iki insan susarsın da bazen,

Karşılıklı konuşmaktan daha anlamlı olur bu suskunluk,

Bizde böyleyiz. Hayatım ve ben....

Ve ölüm,

Ölümün hayatımın içindeki yerini biliyorum artık,

Onun varlığını bahçedeki vazgeçilmez bir ağaç,

Sokaktaki bir arkadaş gibi kabul edip, isyanı bıraktım,

Senin gözlerin beni yaşama bağlayan,

Gözlerinde ki anlam,

Gözlerinde ki yaşamın sihri,

Sen,

Resimli romanları hatırlayıp sevmeyide böyle öğrendim, 

ilk kitapların, ilk aşklar gibi hayatımdaki yerini de,

Çılgın ve kederli, otobüsleri de, 

Vahşi ülkemide zaten çocukluğumdan beri hep severdim...', 'Ben Tenim aç ruhum aç ve, Anlaşılmayan kalbim ve,  Anlaşılmayan kafam ve,  Anlaşılmayan vucudum, Susuyorum hayata karşı, O da bana karşı sus...', ARRAY['Türk Edebiyatı','Şiir','Kentin Kahini']::text[], 8.5, '{"poet":"Kentin Kahini","poet_slug":"kentin-kahini","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GerçekHikaye Taksim Parkı', 'gercekhikaye-taksim-parki-kentin-kahini-8nv09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bomboş yol aradım yürümek için,

Bir omuz aradım yaslanmak için,

Yağmurlu bir hava aradım gizlice akan gözyaşlarım için,

Her gün bomboş olan yollar bugün inadına sanki tıklım tıklım,

Ben de şansıma küsmüş doğacak güneşi bekliyorum parkın en ücra köşesinde,

yalnız ve kırık olan bir bankta,

Başka çarem kalmamış gibi tam dalmışken bir simitçinin sesini duyuyorum,

Yanıma yaklaşıp simit ister misiniz diyerek ve elinde son kalmış tek simidi bana uzatıyor,

Bayatlamış simide bakıyorum. 

Pek içimden gelmiyor almak...

İstemem demek için başımı kaldırdığım sırada karşımda soğuktan titreyen kısık bir sesle son bir simidim kaldı istemez misiniz diye tekrar soruyor... 

Gözlerim bayatlamış simide takılıyor.

Simit çocuğun elinde zor duruyor. 

Her an soğuktan hissetmeyen ellerinden düşme riski içinde olan simit duruyor karşımda... 

Çocuğun morarmış dudaklarınındaki sıcak gülümsemesi yağmura saklamaya çalıştığım gözyaşlarımın akmasına sebep oluyor. 

Yağmur yağmıyor, saklamıyorum ağladığımı ilk defa,

Çocuğun gülen gözlerinde gerçek güneşi görüyorum sanki... 

Ver bakalım son simidini diyerek  alıyorum ellerinden simidi... 

Parayı uzattığımda sıcak ve mahcup bir şekilde alıyor elimden...

Ellerindeki soğukluğu ilk defa o zaman hissediyorum. 

Sıcak tuttuğunu sandığım eldiven şapkam ve paltom bile onun elindeki soğukluğa karşı ısıtamıyor vücudumu... 

Ürperti geliyor birden tüylerim diken diken oluyor soğuktan..

Ayrılık vakti gelip çatıyor. Çok zor geliyor güneşi bırakıp ardımda , yürümek. Ama gitmek zorundayım... 

Yürüyorum saatlerce bomboş olmasını istediğim ama tıklım tıklım olan yolda... İlk defa rahatsız değilim kalabalıktan.. Hem yağmur da yağmasını istemiyorum artık gözyaşlarımı saklamak için, yaslanmak için sıcak bir omuz da. Güneş yakıyor aniden tepemi... 

Geriye baktığımda simitçi çocuğu göremeyecek kadar uzaklaştığımı hissediyorum,

Gökyüzüne kaldırıyorum başımı,

Sımsıcak güneşte çocuğun yüzünü görüyorum

Galiba uzun zamandır hissetmediğim bu güç , yaşama gücü ve yaşama sevinci...', 'Bomboş yol aradım yürümek için, Bir omuz aradım yaslanmak için, Yağmurlu bir hava aradım gizlice akan gözyaşlarım için, Her gün bomboş olan ...', ARRAY['Türk Edebiyatı','Şiir','Kentin Kahini']::text[], 8.5, '{"poet":"Kentin Kahini","poet_slug":"kentin-kahini","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gercekhikaye-taksim-parki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Yürekli', 'dar-yurekli-guray-yildiz-ff6m8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bana alışmış

Ben sana alışmışken

Terkedecek ne vardı

Hiç mi zamanın yoktu

Hiç mi bekleyemezdin

Vardı zamanın, vardı da

Yüreğin dardı senin

Adım bile sığmamışken 

Dudaklarına

Yüreğine aşkım nasıl sığardı...', 'Sen bana alışmış Ben sana alışmışken Terkedecek ne vardı Hiç mi zamanın yoktu Hiç mi bekleyemezdin Vardı zamanın, vardı da Yüreğin dardı sen...', ARRAY['Türk Edebiyatı','Şiir','Güray Yıldız']::text[], 8.5, '{"poet":"Güray Yıldız","poet_slug":"guray-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dar-yurekli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul', 'ah-i-stanbul-abdullah-kalender-sehit-ieev1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözleri vardı ya, istemese de anlatan sözlerini

Sözleri vardı ya, tutsam da ağlatan gözlerimi

Gülleri vardı ya, bilmese de benden geldiğini

Bir gün demiştim ya, istanbul  alacak hepsini

Bir cami vardı ya, avlusunda çay içilen hani

O otel vardı ya, penceresinden gözlediğim seni

Terminal vardı ya, en yakın ve en uzak hani

Ve ben demiştim ya, istanbul unutturur hepsini', 'Gözleri vardı ya, istemese de anlatan sözlerini Sözleri vardı ya, tutsam da ağlatan gözlerimi Gülleri vardı ya, bilmese de benden geldiğini ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Kalender Şehit']::text[], 8.5, '{"poet":"Abdullah Kalender Şehit","poet_slug":"abdullah-kalender-sehit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ah-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-abdullah-kalender-sehit-7ixis', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar uzaksın zalim

Sormuyorsun hiç halim

Durma artık çok özledim

Gel de, bitsin dertlerim', 'Ne kadar uzaksın zalim Sormuyorsun hiç halim Durma artık çok özledim Gel de, bitsin dertlerim...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Kalender Şehit']::text[], 8.5, '{"poet":"Abdullah Kalender Şehit","poet_slug":"abdullah-kalender-sehit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zalim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerken Seni', 'ozlerken-seni-abdullah-kalender-sehit-n6rqt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlüyorum  yine ilk günkü gibi

Beklemek ! çok zor, ölüm sanki

Önemli olan  aslında bu  değil ki

Mesele ! sevmek hala,delice seni

Soğuk ve soluk sarmaşıkların sarıldığı 

Cennet kokulu o asırlık çınar

Dile gelse anlatsa sana halimi

Hal ! senin bildiğin gibi değil ki', 'Özlüyorum  yine ilk günkü gibi Beklemek ! çok zor, ölüm sanki Önemli olan  aslında bu  değil ki Mesele ! sevmek hala,delice seni Soğuk ve so...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Kalender Şehit']::text[], 8.5, '{"poet":"Abdullah Kalender Şehit","poet_slug":"abdullah-kalender-sehit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlerken-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın1', 'uzaksin1-abdullah-kalender-sehit-bj8vj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Severken hala delice böyle

Soramam ki gözlerin nerede

Gözlerine vurulmadım görüp de

Ben yandım tertemiz gönlüne

Bilirim gözlerin kadar gönlün de

Uzaklarda, farklı hayallerde

Olsa da hepsi başka sinelerde

Aşkın hala benim kalbimde', 'Severken hala delice böyle Soramam ki gözlerin nerede Gözlerine vurulmadım görüp de Ben yandım tertemiz gönlüne Bilirim gözlerin kadar gönlü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Kalender Şehit']::text[], 8.5, '{"poet":"Abdullah Kalender Şehit","poet_slug":"abdullah-kalender-sehit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzaksin1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Geldiğinde', 'zamani-geldiginde-abdullah-kalender-sehit-sntyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanı geldiğinde, doyasıya sende seveceksin 

Yanmanın ne olduğunu, ağlayarak bileceksin

Acele etme çiçekleri bekle ne olur, erişeceksin

Kışta sevemeyeceğini bahar gelince göreceksin

Sana göre değil şimdilerde sevmek, pişeceksin

Bulutlu gözlerle bakma öyle alıngan, yağacaksın

Bulduğunda koparamayacağın gülü, güleceksin

Dönüp  gerilere utanarak, haklıymış diyeceksin

Hep almayı unuttuğunda, almayı hak edeceksin

İşte o zaman gerçekten sevip çok sevileceksin

Kapında, uzaklardan gelen beyaz gülü sezeceksin

Ben yeşille sarmaş dolaş; sen beyazlar giyeceksin', 'Zamanı geldiğinde, doyasıya sende seveceksin  Yanmanın ne olduğunu, ağlayarak bileceksin Acele etme çiçekleri bekle ne olur, erişeceksin Kış...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Kalender Şehit']::text[], 8.5, '{"poet":"Abdullah Kalender Şehit","poet_slug":"abdullah-kalender-sehit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamani-geldiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ab-ı Hayat ve Silifkeli Hacer AYDIN', 'ab-i-hayat-ve-silifkeli-hacer-aydin-halil-i-brahim-deveci-vn9ed', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelliğin tarlası; Hayat

Hayatın en nadide gülllerindendir; Hacer!;

Yaşamak ''Zor iştir'' derlerdi

Bildiklerim

kolaymış meğer yaşamak

ve bir yönüyle Hacer''i Hacerden ötesiyle 

tanımak

Zormuş meğer hayatı yaşamak

ve Hacer''i hayatta tanımak!

Eşyanın esrarını arayanlar

Haceri tanısınlar yaşamlarında

Hacer''de Hacer''den ötesine baksınlar;

Ab-ı hayatın seher yelini hissederler...

Ben Hacer''den ötesini yaşadım 

 bir zamanlar; Hacer''de....

Yaşamanın anlamına vardım!

Ve bir de Hacer''de Hacer''i yaşadım

Kâbûslara döndü hayat hikayem!

Ne kadar zormuş güzelde aldanmayı yaşamak

Hacer''i sorsalar bana,

O''ndan ötesini arıyorsan ''Bul, O''nu!'' derim

Lakin sadece Hacer''i istiyorsan

''Arama boşuna!'' demekle yetinirim...

İki Hacer vardır

Bilirim;

Biri Ab-ı hayatı anlatır gülümsemesiyle

seherlerde güzeldir o

hayallerde tatlıdır gülüşleri

kanayan yaraya merhemdir

bakışları, güllerde...

Hz. Aişe''yi hatırlatırdı bana

belki de bunun için sevmiştim O''nu

belki de O''nu sevdiğim için 

hatırlardım Hz. Aişe''yi....

Kesin bilemiyorum 

lakin bildiğim ab-ı hayatı öğretmişti bana

O''nunla geçen zaman

Tanıdığım ilk günde

kararsızdım

sevmeye kadını

kadın mı omalıydı hayatımda

yoksa hayatım mı kadınlı olmalıydı?

Kestirememiştim

kaderin cilvesini

Ve bir gün bir Allah Dostu

''Kadın seni Allah''ı zikirden alı koymasın!'' dedi

Ruhaniyetinin tılsımıyla

Pek anlamamıştım tılsımını Dostun

Lâkin zaman

ve yaşananlar gösterdi ki

''Kadın beni Allah''ı zikirden alı koydu....

Ben yanılmışım

Mevlâ''dan Hacer''e yönelmekle

Hem Hacer''i kaybettim, hem de.....

Keşke; Mevlâ''da kalsaydım ve...

Hacer benim için hâlâ hayal olsaydı da...

Kaybetmeseydim Hacer''i ve de....

O''nu ilk gördüğümde

zaman mekana gebeydi

asra hediye edilecek gibiydi

bir yeni aşk!...

Ve bir mâzi 

âtînin habercisiydi sanki..

Yarım kalacak diyordu, mâzi

Âti sancılanacak...

Izdıraba gebe kalacak bugün

dün inkisara tutulacak!

Ve öyle de oldu;

Şimdi mâzi 

hayallerin ve hatıraların ızdırabında

bugün; mazinin ağlamasında

ve de âti sancılarda...

kayboldu âtinin ab-ı hayatı...

Kimlerdedir kimbilir şimdi?

Ve sen ey mazinin hayal kızı;

Âb-ı hayatı bekleyenlerin yıldızı;

Evet sen başkasının olduğun gün;

ne sen benim olarak kalacaksın,

ne de ben....

Anlamı kalmayacak belki de;

yaşanan o ilklerin

üşüyecek ve titreyecek iliklerin

kan damlasında yitireceksin yeniden

beni terk etmene sebep olan hayallerini

yeniden yıkılacaksın

yeniden hayallerin sönecek

göreceksin ki;

sana getirilenler sende aranan ab-ı hayatın kaynağıydı...

Bir türlü anlayamadığına yanacaksın

o ilk günlerde erkeğinin döktüğü gözyaşlarını

keşke , diyeceksin:

senle kalsaydım ve 

cennetin kokularına dönüşecek yarınlar için 

ölenedek mânâ için 

aşk-ı ilâhi için 

ağlasaydım...

Ama o gün Allah için dökmediğin

ya da garipsediğin sevgilinin gözyaşlarını

sen karşılaştığın meşakkatler için dökeceksin

bir de bakacaksın ki;

Ağlamak anlamını yitirmiş

cennetetn kokular ve vaadler getiren ağlamalar

Halil İbrahimle gitmiş!...

Havva''ya sor;

neden ağlamıştı Sağlık Ocağın''da

hiç böylesine duymuş muydu;

O habib-i Peygamberi

bir başka ağızan

bir başka kitaptan

bir başka rayihadan...

Eminim ki;

Cevabı ''Hayır!''

Evet sen de,

evet demek için benden gittiğin şeyleri gördüğünde

bende olanları bulamadığın için ''Hayır!'' diyeceksin...

Ama anlamı olmayacak ''Hayır''larıyın ve GÖZYAŞLARININ!''

Söylesene kim ağlar;

bir vakit sabah namazına kalkamadığının ızdırabına

kim döker senin için 

cehennemin haram kılındığı gözyaşlarını?

Kim kendinden geçer senin için 

Namazlarında;

''Bize hidâyet ver, Yârabb!....''

derken ve BİZ olmanın anlamını kim yaşar bu günde

İnsanlık heveng heveng 

sen-ben savaşının meydanına koşarken

kim  döker kurtuluşun için

günahlarıyın keffaretine

kendisi için dökmediği göz yaşlarını...

Elbette benim gibi ;

Hacer''de Hacer''den ötesini yaşayan

Ab-ı hayat arayıcıları döker göz yaşlarını...

Ama sen belki anlayamamışsındır hâlâ

bir kadın nedenkendinden ötesi için sevilir

ve uğruna seherlerde gözyaşı dökülür?

Bende bulacaklarını anlaman için sor,

Havva''ya

Dememişmiydim ona

''Madem sevecek kalbin,

Allah''ı sevmeyeni sevme

Eğer sevecekse kalbin

Allah''ı sevsin

veyahut

Allah aşkına sevsin

sevilmesi gerekeni!...''

Dinlemedi,

hali nice sor, öğren 

Allh-ü âlem; kan ağlıyor

sevdiğine ve seveceğine...

N e dünyası kaldı ne ahireti;

Belki farkında değildir

belki de söylemek istemez

ama öldüğü gün haykıracak mezar taşı:

''Keşke Halil İbrahimi dinleseydim!'' diye

ama dönüşü olmayacak mezarın

Faydası da olmayacak 

mezardan beriye döktüğü gözyaşlarının!...

Belki de kurtuluşu olacak 

Peygamber''den verdiğim haberle döktüğü gözyaşları...

Sen de arayacaksın Hacer;

Yitik mâzide 

gelmeyecek âtiye bıraktığın  beni

''Dini baskı yapıyormu ha!''

Mezarda göreceksin

Dinin ne

ne olduğunu gözyaşının!

ANLAYACAKSIN HACER

Anlayavaksın 

Ve Yaşamana ağlayacaksın

Ağlayacaksın ananın haline

babanın haline

haline arzularıyın

ve umursamadan seyrettiği

düğünlerdeki göbek atanların haline!

AĞLAYACAKSIN....

Ama yine de duam:

Cennet-i âlâ''da gülmendir!

Ben senin hesabın için hâla AĞLIYORUM!

                                         (2000-Akseki)', 'Güzelliğin tarlası; Hayat Hayatın en nadide gülllerindendir; Hacer!; Yaşamak ''Zor iştir'' derlerdi Bildiklerim kolaymış meğer yaşamak ve bir ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":179,"source_url":"https://www.antoloji.com/ab-i-hayat-ve-silifkeli-hacer-aydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıplar İçinde Kendini Bul', 'kayiplar-i-cinde-kendini-bul-i-lhan-yuksel-2ww8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayata oynadım bir kumar gibi

Yaşadığım günler seneler kayıp

Birde şu hayattan kârım var gibi

Hem benliğim kayıp hemde ser kayıp

Tükendi ümidim bir bir tükendi

Insafsız bir avcı ağını gerdi

Bozguna uğrattı feleğin fendi

Ruh yorgun bedenim cansız fer kayıp

Kayıplar içinde kendini ara

Düşündüğüm hüzün giydiğim kara

Dayandı yollarım çıkmaz yollara

İçimde bir ses her şeyin der kayıp

Deli gibi binbir eser başımda

Viran vurmuş gibi şu genç yaşımda

Eser bir sam yeli eser başımda

Ver feleğe kayıpları ver kayıp

Başımda dolanır bir bağ bozumu

Esen sam mı? bu toz viran tozu mu? 

Şu kahbe feleğin bu son kozu mu? 

Yurdum yuvam kayıp hemde yer kayıp', 'Hayata oynadım bir kumar gibi Yaşadığım günler seneler kayıp Birde şu hayattan kârım var gibi Hem benliğim kayıp hemde ser kayıp Tükendi ümi...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kayiplar-icinde-kendini-bul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bir Kağıt Mendil', 'sevda-bir-kagit-mendil-tuncer-oral-ets1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda bir kağıt mendil;

Pembe ve hoş kokulu,

Islanmaya gelmeyen,

Ne kadar sakınsanda

En son ıslanıveren.

            20*12*2000

                  19:05', 'Sevda bir kağıt mendil; Pembe ve hoş kokulu, Islanmaya gelmeyen, Ne kadar sakınsanda En son ıslanıveren.             20*12*2000             ...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevda-bir-kagit-mendil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HACER ve Halil İbrahim', 'hacer-ve-halil-i-brahim-halil-i-brahim-deveci-kl9pi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '*Bu şiirimi bir zamanlar değerinin çok ötesinde gördüğüm ve yanıldığım Silifke''li Hacer AYDIN''a ithaf ediyorum.

Hacer; yaşam esrarının gizlendiği güzel...

Halil; bu esrara uzana, meçhûl garip el...

Sende, büyük sırra ermenin doymaz visâli

Bende gaibi kurcalayan kâşifin hali...

Sen, Ebedî olana giden yolun yolcusu

Ben, senle olamamanın dayanılmaz korkusu

Uzatmışsın elini Hazret-i Peygambere!

''İşte bu, gaye-insan diyorsun meleklere!''

Bu ne üstün anlayış, bu ne üstün idrak!

Sana gıpta ile bakıyorum..Ağlayarak!

Aç güzelim, esrarını bu garibe de aç!

Mekan kayıp, zaman durmuş, bilmem saat kaç?

Bana göre sırra ermenin basamağısın!

O kadar esrarlısın ki... Remz olmalısın;

Zamanı parçalamanın...Mekana geçmenin,

Erişilmez sırra götüren yolu seçmenin....

                                                    (1998-Tuzluca)', '*Bu şiirimi bir zamanlar değerinin çok ötesinde gördüğüm ve yanıldığım Silifke''li Hacer AYDIN''a ithaf ediyorum. Hacer; yaşam esrarının gizle...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hacer-ve-halil-ibrahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sevmemişim', 'hic-sevmemisim-riza-aslan-ff7ow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç sevmemişim bekletilmeyi

tahammülüm olmamış hiç

umutla umutsuzluk arasında

belirsizliklere alışamamışım

kahreden belirsizliklerle yaşamayı öğrenememişim

içimi çepe çevre sarmalayan sürgünlerden

kendini anlamadan , kendini çözemeden

kendinden kaçmalara alışamamışım

hep bir sebep aramışım

aranan sebep hep başka belirsizliklere yelken açmış

yelkenlerim dayanamamış fırtınalara

gemim su almış 

ve batmışım

21-12-2000  karacan dersanesi ankara', 'hiç sevmemişim bekletilmeyi tahammülüm olmamış hiç umutla umutsuzluk arasında belirsizliklere alışamamışım kahreden belirsizliklerle yaşamay...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-sevmemisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-metin-yalti-zhcf4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Hoş geldin,

                Beni tanımak içinse gelişin

                İçimde saklamam bir şey

                Varsıllığım göründüğümce...

                Yetmedi değil mi? 

                Üzülme, çok zenginim ben

                Umutlarımca...”

Hoş geldin

I

Hoş geldin

Nedir aradığın? 

Beni tanımaksa amacın

Zengindim umutlarımca

Dostlarım olmadan önce

İyi/kötü kazanırdım bir şeyler

Sevmek paylaşmaktır diye

Paylaştık ne varsa 

-Allah için-

Sevinçlerimi paylaştılar, 

Coşkularımı da dostlarım.

Acılarımı paylaşan yalnızlığımdı

Sıkıntılarımda 

Yanımda karım vardı...

Pek bir şey kalmadıysa da geriye 

Hoş geldin yine de

Bu yorgun  yüreğimde

Geç kalan dostlar için sakladığım

Sevgiyi paylaşalım seninle

Al dostum bir sana

Bir sana... 

II

Hoş geldin

Nedir ki aradığın? 

Hoş geldin ya geç kaldın.

Artık yoksulluğumca zenginim

Sana verecek, ne bir dilim peynirim

Ne de  üç tek zeytinim kaldı

Her şeyim ortadaydı

-İnan ki dostluk adına-

Her kes, her şeyimi aldı.

Hoş geldin

Hoş geldin ya geç geldin? 

Kırk yıldır beklemekteydim seni

Geç kaldın; kırk yıllık dostum benim

Kusuruma bakmazsın artık

Boşaldı dağarcığım 

Her şeyimi dostlarım aldı

Sana vereceğim 

Bir yüreğim vardı

Onu da.............

      

III

Hoş geldin

Kırk yıldır beklediğim

Geç kalsan da hoş geldin

Geldin ya ne getirdin? 

Aç yüreğini 

Bir tutam sevgi uzat

Hoş görü göster hele,

Dök dağarcığın orta yere

Sevgi ver, merhamet de

İçtenliğini gönlünce

Sevinçlerin senin olsun,

Zenginliğinde..

Varsa derdin, kederin

Onları paylaş benimle

Hadi kırk yıldır beklediğim 

Hadi kırk yıllık dostum,

Geç kaldın ya hoş geldin yine de

Bir anlam katmaksa amacın yaşama

Koy yüreğini orta yere...

Çekinme.

 Sevgi Türküleri

İzmir

14,05, 2000', '“Hoş geldin,                 Beni tanımak içinse gelişin                 İçimde saklamam bir şey                 Varsıllığım göründüğümce......', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/hosgeldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saplantı', 'saplanti-metin-yalti-a8fpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende saplantı olduğuna aldırma sen

Davran geldiği gibi içinden.

Her şeyin bir zamanı var

Ben böyle de severim seveceksem.', 'Bende saplantı olduğuna aldırma sen Davran geldiği gibi içinden. Her şeyin bir zamanı var Ben böyle de severim seveceksem....', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saplanti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlerce', 'mevsimlerce-metin-yalti-r5gyw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşilin sarıya duruşu 

Donmaya duruşu suyun

...Ve benim duyduklarım

Sonu mu yaşadığım baharın? 

Neydi o yaşadıklarımız? 

Bir fırtınaydı sanki.

Kış mıydı gönlümde mevsim? 

Kar yağmışcasına dağlarıma.

İçten bir gülüşmüydü çağrım? 

Anlamlı o bakışın mıydı evet? 

Koştum sevinçle sana 

''Dağlarına bahar gelmiş memleketimin.''

Seni her gördüğümde yar,

Sevinç içimde büyür ha büyür

Dudaklarımda öpüşler bahara

Gözlerimde yangınlar yaza dönüşür.', 'Yeşilin sarıya duruşu  Donmaya duruşu suyun ...Ve benim duyduklarım Sonu mu yaşadığım baharın?  Neydi o yaşadıklarımız?  Bir fırtınaydı sank...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevsimlerce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karım Diyeceğim Sana', 'karim-diyecegim-sana-metin-yalti-6v75v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili

Öylesine sevmişem ki seni

Gönlüme yer etmiş varlığın

Öylesine severim ki seni

Hiç solmayacak

Usuma yansımış güzelliğin.

Değerlisin

Dünyalara değersin.

Biçemem varlığına paha

Seni nasıl anlatayım sana

''Sen bir ömre bedelsin.''

Yıldızlar gibisin.

Onlar gibi de uzak.

Bir gün bir yıldız gibi kayarak

Sana geleceğim.

Bir kır çiçeği gibi 

Soluyup,koklayacağım seni.

Yayla yollarında seni göreceğim.

Makine başında fabrikalarda seni.

Başak gibi savrulacak esen yelde saçların

Buğday kokularında seni duyacağım.

Sen fabrikalarımın ürünü

Sen tarlalarımın ürünü

Karım diyeceğim sana 

Bu sözcük esenlik yayacak içime

Akşamlarda sevişircesine kırpışan

Sevişircesine mahzunlaşan

Yıldızları seyredeceğiz seninle.

Baktığı her yönde seni görecek gözlerim

Dolacak seninle her saniyem,her anım.

Bir gün,ak çarşaflar içinde

Bir kızıl yıldız gibi 

Yatağında oğlumla göreceğim seni.

Ak umutlarla, ak sabahlar için doğan oğlumla

Doyumsuz bir sevinç kapsayacak içimi 

Oğlumda göreceğim yurdumun kurtuluşunu.

Aman hey! 

Seninle göz göze geleceğim.

Diz çöküp usulca ellerinden öpeceğim

Sevgilerin en büyüğünü,

Sevgimi sunacağım sana

Bir ilahmışcasına tapacağım

Oğlumun anasına.', 'Sevgili Öylesine sevmişem ki seni Gönlüme yer etmiş varlığın Öylesine severim ki seni Hiç solmayacak Usuma yansımış güzelliğin. Değerlisin D...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/karim-diyecegim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi bir Devrimdir Gözlerinde', 'sevi-bir-devrimdir-gozlerinde-metin-yalti-ac2zm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin dalar ya hani? 

Koyu karanlığa döner ya bazen,

Işıl,  ışıl apaydınlık olur gene de

Gözl  göze geldiğimizde...

Öyleyse derim,

Yansıyan özdür,sevgi yani

Renkler değil.

Ve karanın suçu yok faşizmde

Sevi, bir devrimdir gözlerinde.', 'Gözlerin dalar ya hani?  Koyu karanlığa döner ya bazen, Işıl,  ışıl apaydınlık olur gene de Gözl  göze geldiğimizde... Öyleyse derim, Yansıy...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevi-bir-devrimdir-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ergüvan Akşamlar', 'erguvan-aksamlar-metin-yalti-n0ij8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz,

İlk günahına soyunmuş bakire gibi

Çokça istekli, biraz  da ürkekti

Küçücük dalgaları

Arzuya aralanan dudaklar gibi titrekti.

Güneş

İlk deneyimini uyanmış delikanlı gibi

Çokça istekli ama biraz da ürkekti.

Parlak ışıkları

Hedefi saplanmış ok gibi titrekti.

Beni görünceye kadar

Deniz ve güneş,

Bütün gözlerden uzak gibi

Çeşme Koyu’nda gün boyu seviştiler

Deniz şuh bir kadın gibi arzulu

Üstüme, üstüme geliyordu

Tanığım iğde ağacı ve hanımeli

Davetkar türküler söylüyordu.

Güneş bir suçlu gibi mahcup

Yüzü al,al mor, mor oldu

İnanmazsan o küçük buluta sor

Dağı aşarken az kalsın düşüyordu.

Niyedir bilmiyorum

Herkesi bir hal aldı

Sanki bir suçu gizler gibi

Aya Yorgi’yi erguvan bir akşam aldı.

28,5,2000 

Sevda Türküleri

Çeşme/izmir', 'Deniz, İlk günahına soyunmuş bakire gibi Çokça istekli, biraz  da ürkekti Küçücük dalgaları Arzuya aralanan dudaklar gibi titrekti. Güneş İl...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/erguvan-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gûller', 'g-ller-seref-yellidag-b2ahi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güller açmaz oldu,

Güzel yüzün soldu.

Unutamadım ben seni,

Sen unuttuğunda beni', 'Güller açmaz oldu, Güzel yüzün soldu. Unutamadım ben seni, Sen unuttuğunda beni...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guller-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki', 'uzaktaki-seref-yellidag-pbtxp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklarda hep bakip durdun,

Dönüp baktin gelmiyecek biliyorsun,

Ama bakip duruyorsun,

Ûmitle belki döner diyiyorsun,

Dönmiyecegini biliyorsun,

Kaderine bakiyorsun,

Evet ben kaderim diyiyorsun,

Zaman geliyor ölmek istiyorsun,

Yasam tatli güzel diyiyorsun,

Herseyden kacmak istiyorsun,

Dönup bakip özlüyorsun,

Dost ariyorsun,

Ama uzakta diyiyorsun, 

Ask ariyorsun,

Ama dönüp te bakmiyor diyiyorsun,

Hayata küsüyorsun,

Seviyorsun fakat 

Unutamiyorsun...... 

bana özel bir kisiden kalan siir.......', 'Uzaklarda hep bakip durdun, Dönüp baktin gelmiyecek biliyorsun, Ama bakip duruyorsun, Ûmitle belki döner diyiyorsun, Dönmiyecegini biliyorsu...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uzaktaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmasin', 'solmasin-seref-yellidag-uwo18', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül yanaklarinin rengi solmasin,

Tertemiz kalbine hüzün dolmasin,

Yolmasin saçini pamuk ellerin,

Yüzünden tebessüm eksik olmasin.', 'Gül yanaklarinin rengi solmasin, Tertemiz kalbine hüzün dolmasin, Yolmasin saçini pamuk ellerin, Yüzünden tebessüm eksik olmasin....', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/solmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-seref-yellidag-77dft', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutma

Güzellik her şey değildir

Önemli olan insanlık ve saygıdır

Unutma', 'Unutma Güzellik her şey değildir Önemli olan insanlık ve saygıdır Unutma...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmedi', 'donmedi-seref-yellidag-pxb8w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya durmaz oldu

İnsanlar gülmez oldu

Dünya yıllarca döndü

Döndü bana dönmedi', 'Dünya durmaz oldu İnsanlar gülmez oldu Dünya yıllarca döndü Döndü bana dönmedi...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/donmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvenlik', 'guvenlik-seref-yellidag-6buvz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün sende seversin,

cok ama cok,

Bilirsin sevmek kolaydir,

Ama sevilmesi zordur,

ônemli olan güvenlik,

Unutma Güvenlik bir hayat yürütür', 'Birgün sende seversin, cok ama cok, Bilirsin sevmek kolaydir, Ama sevilmesi zordur, ônemli olan güvenlik, Unutma Güvenlik bir hayat yürütür...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guvenlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adini Yazdim', 'adini-yazdim-seref-yellidag-bxq60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adini yazdim siir''lere,

Belki birgün okursun diye,

Adini yazdim duvarlara,

Belki birgün görürsün diye,

Seni seviyorum diye yazamadim,

Kahrolsun bu dünyaya.', 'Adini yazdim siir''lere, Belki birgün okursun diye, Adini yazdim duvarlara, Belki birgün görürsün diye, Seni seviyorum diye yazamadim, Kahrol...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adini-yazdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar', 'mezar-seref-yellidag-pd0vf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirmizi güller aski anlatir,

Mezar tasi tabutu anlatir,

Siyah carsaf ölümü anlatir,

---''Ôldügümde mezari ve taputu sen yaptir,

Eline kirmizi gülleri al,

Bu bizim askimiz icin de.!!!', 'Kirmizi güller aski anlatir, Mezar tasi tabutu anlatir, Siyah carsaf ölümü anlatir, ---''Ôldügümde mezari ve taputu sen yaptir, Eline kirmizi...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mezar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl', 'col-necip-fazil-kisakurek-w1x3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözüm,aklım,fikrim var deme hepsini öldür,

Sana çöl gibi gelen,o göl diyorsa göldür...', 'Gözüm,aklım,fikrim var deme hepsini öldür, Sana çöl gibi gelen,o göl diyorsa göldür......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/col-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey', 'hey-necip-fazil-kisakurek-vc3fh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neye baksam aynı şey,neyi görsem aynı şey,

Olan sensin hey gidi hakikat sultanı hey.', 'Neye baksam aynı şey,neyi görsem aynı şey, Olan sensin hey gidi hakikat sultanı hey....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı', 'kapi-necip-fazil-kisakurek-pck3m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapı kapı,bu yolun son kapısı ölümse!

Her kapıda ağlayıp,o kapıda gülümse.', 'Kapı kapı,bu yolun son kapısı ölümse! Her kapıda ağlayıp,o kapıda gülümse....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Arıyorum', 'bir-ask-ariyorum-seref-yellidag-nuqq7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ask ariyorum,

Kalbimi dolduracak, yuregimi sicacik edecek bir ask ariyorum.

Benim duygularimi paylasacak, dertlerime ortak olacak, göz yaslarimi silecek, bir ask ariyorum.

Benimle gülerken gözlerimin icine bakacak, kalbimi yerinden oynatacak icimi sicacik edecek, bir ask ariyorum.

Seni seviyorum diyecek, bana sicacik sarilacak,

beni koruyacak, bir ask ariyorum.

Beni güzel sözleriyle büyüliycek,siirler yazacak,

bana yabangülü diyecek bir ask ariyorum.

Bana herseferinde gül getirecek beni bekleyecek, bir ask ariyorum.

Beni ömür boyu sevecek gercek bir ask ariyorum.

Ben , Beni ben olarak sevecek bir ask ariyorum.', 'Bir ask ariyorum, Kalbimi dolduracak, yuregimi sicacik edecek bir ask ariyorum. Benim duygularimi paylasacak, dertlerime ortak olacak, göz y...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yellidağ']::text[], 8.5, '{"poet":"Şeref Yellidağ","poet_slug":"seref-yellidag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-ask-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırma', 'aldirma-tuncer-oral-7dg1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım cenneti çekiyorsa,

İntihar edecek değilim.

Korkma! 

O kadar çok sevmedin ki.

Ama kalıcıda değilim,

Ömür bir cam şişede.

Yol kısa

Vakit dar

Ve de hızlı.

Korkma! 

Ya da aldırma,

Gerçi 

Aldırmazsın ya....

15.12.2000', 'Canım cenneti çekiyorsa, İntihar edecek değilim. Korkma!  O kadar çok sevmedin ki. Ama kalıcıda değilim, Ömür bir cam şişede. Yol kısa Vakit...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aldirma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil', 'katil-tuncer-oral-68q0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Katil olmak için kurşun mu sıkmalı?

Merhameti öldürmek cinayet değil mi?

Katil olmak için hançer mi kullanmalı?

Saflığı kullanan katil değil mi?

Katil olmak için birini mi vurmalı?

İnsanı yaşatan yürek değil mi?

17*12*2000

9:55', 'Katil olmak için kurşun mu sıkmalı? Merhameti öldürmek cinayet değil mi? Katil olmak için hançer mi kullanmalı? Saflığı kullanan katil değil...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/katil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-ayse-unal-xtatq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşina olunası güzler yaşadık;

ama hep gökyüzüne döktük yapraklarını dallarımızın...

yüreğimizin kanatlanması dostum,

belki de bu yüzdendir...', 'Aşina olunası güzler yaşadık; ama hep gökyüzüne döktük yapraklarını dallarımızın... yüreğimizin kanatlanması dostum, belki de bu yüzdendir.....', ARRAY['Türk Edebiyatı','Şiir','Ayşe Ünal']::text[], 8.5, '{"poet":"Ayşe Ünal","poet_slug":"ayse-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzele...', 'bir-guzele-temmuz-ss-7i5sa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklımdan hiç çıkmadığın gibi..

(bir güzele...)

İnsanlara bağırıyorsun.

Bana da bağır.

Öylesine bağır,

Öylesine bağır ki;

Sesin kulaklarımı patlatsın.

Patlatsın ki duyduğum son ses,

Senin sesin olsun.

Gözlerime bak.

Öylesine bak,

Öylesine bak ki;

Gözlerin gözlerine saplansın.

Öylesine saplansın,

Öylesine saplansın ki;

Birdaha hiç çıkmasın.

Aklımdan hiç çıkmadığın gibi...

(İstanbul temmuz 99)', 'Aklımdan hiç çıkmadığın gibi.. (bir güzele...) İnsanlara bağırıyorsun. Bana da bağır. Öylesine bağır, Öylesine bağır ki; Sesin kulaklarımı p...', ARRAY['Türk Edebiyatı','Şiir','Temmuz Ss']::text[], 8.5, '{"poet":"Temmuz Ss","poet_slug":"temmuz-ss","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-guzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-aydin-korpe-h6e59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'esemedik delice rüzgar gibi

sevemedik delice mecnun gibi

bekleyemedik yıllarca kerem gibi

yaşayamadık şu hayatı insan gibi

eserdik belki rüzgar gibi 

sevseydik eğer mecnun gibi

beklerdik yıllarca bizde kerem gibi

şu hayatı yaşasaydık insan gibi.', 'esemedik delice rüzgar gibi sevemedik delice mecnun gibi bekleyemedik yıllarca kerem gibi yaşayamadık şu hayatı insan gibi eserdik belki rüz...', ARRAY['Türk Edebiyatı','Şiir','Aydın Körpe']::text[], 8.5, '{"poet":"Aydın Körpe","poet_slug":"aydin-korpe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Sözler', 'sessiz-sozler-bilsay-yildirim-8u1oz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk öyle bir şeyki;

Anlatmaya varmıyor düşlerim gülüm

Hani bir rüzgara kapılırsın ya

Esmesini istersin

Zor düşünceler vardır kafanda

Kendi rüzgarın sanarsın

Her ışığı kendin sanarsın karanlıkta 

Söylemek istediğin sözleri yutarsın

Her uykusuzluk anında şiir yazarsın ellerine

Küçük şiirler okursun sevdiğine

Kendini deli sanırsın

Kanıtlarsın dünyayı kendince

Ses çıkartmadığın zaman boğulursun kendi içinde', 'Aşk öyle bir şeyki; Anlatmaya varmıyor düşlerim gülüm Hani bir rüzgara kapılırsın ya Esmesini istersin Zor düşünceler vardır kafanda Kendi r...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sessiz-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Gözler', 'yalanci-gozler-sinem-baytas-5bsi0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep bana derdin ki

Hiç ayrılmayacağız

Bende o zaman inanırdım

Küçük bir çocuğun herkese inanması gibi

Her bana sarıldığında derdin ki 

Sana hep sarılıcam 

Bir ömür boyu sıkıca...

O zaman da sana inanırdım

Bir zavallını hayata sarıldığı zaman hissettiği duygularla

Ve o beni yanlızlıkla bırakıp gittiğin gün

Hep seni sevdim dedin

Ama o zaman sana inanmadım

Çünkü ayrılığın hüznüyle dolu değildi gözlerin

Yeni aşkının verdiği mutlulukla parlıyordu', 'Hep bana derdin ki Hiç ayrılmayacağız Bende o zaman inanırdım Küçük bir çocuğun herkese inanması gibi Her bana sarıldığında derdin ki  Sana ...', ARRAY['Türk Edebiyatı','Şiir','Sinem Baytaş']::text[], 8.5, '{"poet":"Sinem Baytaş","poet_slug":"sinem-baytas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalanci-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostduk Biz Eskiden', 'dostduk-biz-eskiden-deniz-i-stakozu-o4ugj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dostduk biz eskiden

deli dalgalı bir denizdi yüreğimiz

alabildiğine fırtınalı ve üçsuz buçaksız

yağmurda dolaşırdık hiç ıslanmadan

sonradan süslü lambalar

ve rengarenk kaldırımlar yapılan yolda

yıldızları seyrederdik  hiç konuşmadan 

taki en son yıldız gidene dek.

son sıgaramızıda paylaşırdık

umutsuz sevdalarımız gibi

bazen üç bazen dört kişi.

ve her dumanda ayrı bir hüzün kaplardı karanlık geceyi

gün olur patlamaya hazır volkan gibi

kıpır kıprı yerimizde duramazdık

başdan aşşağıya dolaşırdık koca şehri

kimseyle yokdu işimiz alıp veremediğimiz

kimsede bize bulaşmazdı ha

öylesineydik kendi halimizde

bilmeden otururduk  bazen bir köşede

çiğ düşerdi üstümüze 

üşümezdik umursamazdıkda bizeneydiki

daha bir sokulurduk birbirimize.

dostduk biz eskiden 

asi dağların en zirvesinde açmış kardelenler gibi', 'dostduk biz eskiden deli dalgalı bir denizdi yüreğimiz alabildiğine fırtınalı ve üçsuz buçaksız yağmurda dolaşırdık hiç ıslanmadan sonradan ...', ARRAY['Türk Edebiyatı','Şiir','Deniz İstakozu']::text[], 8.5, '{"poet":"Deniz İstakozu","poet_slug":"deniz-i-stakozu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dostduk-biz-eskiden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-sinem-baytas-cunc8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke kör olsaydım o an

Görmeseydim o iğrençlikleri

Daha az acı çekerdim 

Yine seni severdim

Yine sana inanırdım

Unuturdum herşeyi

Ama sen yok ettin sana olan aşkımı

Tutma ellerimi artık

Hissedemessin sana olan aşkımın sıcaklığını,

Nefretin verdiği soğukluğu hissedersin', 'Keşke kör olsaydım o an Görmeseydim o iğrençlikleri Daha az acı çekerdim  Yine seni severdim Yine sana inanırdım Unuturdum herşeyi Ama sen y...', ARRAY['Türk Edebiyatı','Şiir','Sinem Baytaş']::text[], 8.5, '{"poet":"Sinem Baytaş","poet_slug":"sinem-baytas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nefret-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunu Yaptım', 'bunu-yaptim-halil-i-brahim-deveci-9n8up', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tuzak hazırlıyordu,

Benim için

Kaç zamandır zaman,

Hedef tutmuştu kalbime,

nabız atışlarımın yalnızlığında

Yalnızlığımın yılgınlığını hecelemiş olacak ki,;

Tuzak hazırlamayı gerek gördü...

O da biliyordu;

Ne kadar zordur yalnızlık

Ve de 

Ne kadar mutluluk verici...

Zorlukta mutluluk verici tek şeydir,

Yalnızlık.

Kah gecede

Kah gece yarısında

Öyle değildir

Otobüs freni gibi.

Geliş ve gidiş saati ayarlı olsun...

Eminim ki,Zamanın frenine basarsınızda

Yalnızlığın kâhlarında ki ayara,

Ayarın mekan frenine basamazsınız...

Bunu yapabilmek için

Tanrı olmalısınız;

Bu da imkansız! 

Bu imkansızlık size aczi 

Acizliği dokuz doğurtarak getirir;

Acziyetiniz Tanrı’nın yüceliğini...

Usla usul usul boyun bükmeli

Bükmeli miydi bu tuzaklara?

Sanırım,

-Evet!

İşte ben, bunu yaptım!

(03.01.1999- Iğdır/Tuzluca)', 'Tuzak hazırlıyordu, Benim için Kaç zamandır zaman, Hedef tutmuştu kalbime, nabız atışlarımın yalnızlığında Yalnızlığımın yılgınlığını hecele...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bunu-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-bilsay-yildirim-5xp30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gideceğini hissediyorum..... hissediyorum ... galiba ağlarım bu akşam...... seni çok özlicem....... içime sinen kokun gibi .......bembeyaz ellerin gibi.....umutsuz anlarımda bana ışık tutan gözlerin gibi....... sen gibi kokan ay ............... bu akşam sen gibi olan herşey..... sana ait herşey kalbimde.......herşey sana ait kalbimde...........

seni inan çoık özlicem.....inan seni arıcam her odaya girişimde..... her sokağa girerken......senin sesini düşlicem her yanlız kaldığımda:........ saçlarına dokunurum  her düş kurduğumda....... 

eğer seni tekrar görseydim en soğuk kış gününde bile......ellerimin en soğuk olduğu anda bile......

deli gibi özlerken bile.....beklerken bile..... seni özlerim...... hiç yılmadan ... ismini haykırım 

 her rüzgar estiğinde..... tenimde  hissederim ellerini......ellerini okşarım... öperim doyasıya......

seni özlediğime dair bütün yeminleri ederim gıtmemen için.......gitmemen için...... bütün dünyamı veririm....... düşünmem kir kokmuş gurumu ağlarım ellerine...... sırf beni sarsınlar diye......!:..... sırf gitme diye..>!

yanacağını bildiğin halde ateşe atlamak budur galiba...... budur konuşamadığın anlarda... çaresizlikten ağlamak......karşısında büyülenip umutsuz kalmak..... özlediğini haykırmak isterken bile...fısııldıyamamak.......

hayata dair cümleler kurarken sende takıldım..... her virgülden sonra senle başladım......devrik cümleler kurdum sana......hepsi senden bahsediyordu......hepsinde sen anlatılıyordun......

her ünlemde san özlemim vardı...... her soru işaretinde bende açtığın yaralar......cevapsız sorular....... her noktada  gözyaşı vardı kana bulanmış kalbimden sana kopup giden.....

kahkaha atarken ağlamak galiba yanlızlık........ gerçekleri görmek belki......mutlu olamayı beklerken......bir kere bile gülümseyememek......hayattan onca şey beklerken. hep alamayacaklarını vermek gönlünden........ insana koyan tarafı bu....... belki sadece bana...... ama...... hayata dair çok cümle kurarım .....senden sonra çok yanlışlar yaparım  ........ çok ağlarım senden sonra.......

bu yara bir daha kapanmaz...... ne kadar uzaklaşsam da...... kapanamam senden uzağa.......kaçamam............ yüreğime kazınmışsın bir kere........... atamam seni.......

 her gözyaşımda sen varsın..... yavaş yavaş süzülen......sonra kanayan elllerimde......

herşey  yokolurken senin hayalin bile umut doldururdu içime..... 

 eski bir  anısın yıllara yorgun......aşka yenik düşmüş bir aşksın sen........ şarap kadar güzel ve sevmek kadar acısın......

 seni seviyorum............', 'Gideceğini hissediyorum..... hissediyorum ... galiba ağlarım bu akşam...... seni çok özlicem....... içime sinen kokun gibi .......bembeyaz e...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaşılmaz Acı', 'anlasilmaz-aci-sinem-baytas-1r7vh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana her bakışımda

İçimde bir yerde bir acı hissediyordum.

Bu acıyı hep kendime sordum

Bir aldatılma acısı mı diye

Anlamaya çalıştım,anlayamadım.

Ama şu an biliyorum ki;

O acıyı veren 

Sana her baktığımda 

Gördüğüm sevgisizlike bakan gözlerindi', 'Sana her bakışımda İçimde bir yerde bir acı hissediyordum. Bu acıyı hep kendime sordum Bir aldatılma acısı mı diye Anlamaya çalıştım,anlayam...', ARRAY['Türk Edebiyatı','Şiir','Sinem Baytaş']::text[], 8.5, '{"poet":"Sinem Baytaş","poet_slug":"sinem-baytas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlasilmaz-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakamadığım Düşler', 'birakamadigim-dusler-bilsay-yildirim-ewv27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımıza yenik düştük...

yalvarışlarımıza aldandık.

her bakışta.....

yalan söyledik..

her bakışta yanlış elleri tuttuk...

 her sokakta boş yere ağladık

 boş yere ıslandık yağmurlarda..yağmur olsa da umrumda değil artık ağlamak...

boş yere şiir yazdım ..

yalanlara .

bizi  aldatanlara...

 aşk acıtır gönlümü soğuk ve titrek...

mertçe ağlamaksa aşk.....

hasretım üşümeye hasret elleere...

kanıyor içim.....acıtıyor ta derinden...

ve gözlerin vuruyor...

en  beklenmedik düşlerimden..', 'Gözyaşlarımıza yenik düştük... yalvarışlarımıza aldandık. her bakışta..... yalan söyledik.. her bakışta yanlış elleri tuttuk...  her sokakta...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birakamadigim-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiştim Senden Ötesini', 'sevmistim-senden-otesini-halil-i-brahim-deveci-k1zwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretin sensizliğinde

Kanat çırpıyorum.

Sana ulaşmak

Ne mümkün?

Kanat çırptıkça

Sensizliğe varıyorum.

Sana kavuşmak 

ne mümkün? 

Olmayan aleme mi kaçtın*

Zalim Avitya...

Gitmemeliydin

Gözlerimin ufkundan öte

En azından

Hayalini bırakmalıydın

Solgun olsalar bile

En azından

İzin verseydin

Yıldızlarını toplamama

Siyah saçlarının

Gülen gözlerinin

Kıskandın onları da benden 

Zalim Avitya!

Kan kusturdun gecelerime

Yıldızlarını vurdun düşüncelerimin

Yetim bıraktın mehtabımı

Sonra da benden aldın

Mehtabımın yansımasını

Yetim bıraktın

Gülen göz yaşlarımdan...

Verdin dalgalarına dolunayı

Ağlayan göz bebeklerimin...

Vurdun ormanında sevgimin

Aşk! Aşk! Diye seken ceylanlarını

Öksüz koydun karacalarını

Seni sende senle seven gönlümün...

Çaldın mısralarını kalemlerimin

Harflerimi ağlattın

Şiirimin canına okudun

Hasret kabuslarınla...

Soldu tüm neş’esi

Hayat hikayemin

Bir gülüşe hasret bıraktın

Yarınlarımın ümidini

Verdin, son asrın mahkumluk

Kararını verdin, 

Zamanın bağımsızlığına

Ve bana...

Zalim Avitya!

İntiharını arzuladın

Düşlerimin özgürlüğünde,

İntiharını arzuladın

hülyalarımın 

                   pembeliğinin

                                      İntiharını 

                                                   arzuladın

Arzuladın;

 	      Kararmasını

Zifirileşmesini

İntiharla

Ey Avitya!

Ama bir şeyi unuttun:

“Ben Allah’a inanırım!”

BEN SENİ DEĞİL

SEVMİŞTİM

SENDEN ÖTESİNİ

SENDE

EY AVİTYA!

                     (01 Eylül 1998 –Tuzluca)', 'Hasretin sensizliğinde Kanat çırpıyorum. Sana ulaşmak Ne mümkün? Kanat çırptıkça Sensizliğe varıyorum. Sana kavuşmak  ne mümkün?  Olmayan al...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sevmistim-senden-otesini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardır', 'vardir-halil-i-brahim-deveci-xukju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Ben döktüm esrarımı, sırlarım ifşa oldu,

Ben, bir güzele yaver, güzelim paşa oldu!''

 	     *

Ey bülbül açma her sırrını güle,

Her gülün bir dikeni de vardır.

Aşığım deyip sır verme her güzele,

Güzelin elinden elem çekeni de vardır.

Akıtma kalbini güzelin gönlüne,

Güzellerden başkasına akanı da vardır.

Güvenme her bahçenin açan gülüne,

Her bahçenin bir diken ekeni de vardır.

Yalnız bir güzele bakmasın gözler,

Her güzelin bir başka bakanı da vardır.

Bir tek güzelin aşkıyla dolmasın özler,

Her aşığın bir bel bükeni de vardır.

Sevince sevileceğim sanmayasın,

Her güzelin bir sille çakanı da vardır.

Her gördüğün güzelin şavkıyla yanmayasın,

Aşıkların sevmekten dert çekeni de vardır.

Erim diye güvenme erkekliğine,

Erlerin bir güzele diz çökeni de vardır.

Hiçbir fani güzeli alma benliğine,

Her aşığın içine kibrit suyu dökeni de vardır.

Güzelde gül-i zârı görüp güle güvenme,

Her gül-i zârın bir ayrık dikeni de vardır.

Ben, Aşığım Arkadaş” diye övünme,

Aşk bağının dert çekeni de vardır.

Nazlı nâzlı yürür sanma her güzeli,

Bu güzellerin elbet bir sekeni de vardır.

Fazla haykırma;Aşığım!.. Diye, sanırlar deli,

Güzellerden okşarken bir sokanı da vardır.



Masum sanıp yanma bir güzelin aşkıyla,

Her aşığa bir teneke kuyruk takanı da vardır.

Gönül köşkü varken uğraşma elin köşküyle,

Güzellerden Gönül Köşkü yıkanı da vardır.

Masum tebessümler kandırmasın seni,aşık,

Güzellerden gül sunarken gül-i zarı yakanı da vardır.

Ek beni diye yalvarırsa gül... Gül alışık!

Hep ekilir sanma gülleri elbet bir ekeni de vardır.

                           (Tuzluca-1998)', '''Ben döktüm esrarımı, sırlarım ifşa oldu, Ben, bir güzele yaver, güzelim paşa oldu!''  	     * Ey bülbül açma her sırrını güle, Her gülün bir...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırılamayacak Aşk', 'haykirilamayacak-ask-sinem-baytas-rru5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırmak istiyorum içimdeki aşkı

Dağlara çıkıp koşmak bağırmak istiyorum

Sana olan aşkım heryere yazmak

Herkese anlatmak istiyorum...

Ama bunlar bana çok uzak arzular

Hiçbir zaman yapamayacağım arzular

Çünkü sana olan aşkımdan kaybettiğim bedenim

Ömür boyu mahkum

O karanlık zindana', 'Haykırmak istiyorum içimdeki aşkı Dağlara çıkıp koşmak bağırmak istiyorum Sana olan aşkım heryere yazmak Herkese anlatmak istiyorum... Ama b...', ARRAY['Türk Edebiyatı','Şiir','Sinem Baytaş']::text[], 8.5, '{"poet":"Sinem Baytaş","poet_slug":"sinem-baytas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/haykirilamayacak-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
