INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum İsmini', 'i-stemiyorum-i-smini-halil-i-brahim-deveci-vts4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin

Artık

İstemiyorum ismini hecelemek

Gül yaprağında

Doğan günün kızıllığıyla

Bir şairin yalnızlığında

Gülsuyuna karıştırmayacağım 

Rayihanı...

Sen 

Artık

Benim değilsin!

Mısralarımın gül-i zarında

Açmayacaksın

Bir daha....

Mısralarımın gül-i zârında

İsmin belki de nefret

Belki de bir hatıra

Kalacak dudaklarımda

Yalnız

Bilemeyeceksin artık

Ne değerde olduğunu

Kalp yansımalarımda

Değerin kaç?

Aynaların aksine

Bilemeyeceksin artık

Ne değerde olduğunu

Koşup gelemeyeceksin

Aşk bahçesindeki sesime

İzin vermeyeceğim

Aramana da....

Vardığın ilk sahilde

Son martının çığlığında

Unutamadığın yorgun hatıralarını

İzin vermeyeceğim aramana...

Buna beni sen ittin!

Herkes

Seni severken

Aynalardaki aksine bakıp

Ben, seni

Gâl-ü Belâ''daki halin için sevmiştim

Ya da

Âhiretlik ömrün aşkına!

Kandın sen,

Gölge sevgilerin tebessümlerine...

Bende bitmeyen aşkın

Göz yaşı hakikat iksiri vardı...

Onu sundum ben

Tüm çıplak realitesiyle sana

Ama sen;

Yaşamadın göz yaşında

Bilakis ilk göz yaşında 

boğuldun

Bütün gerçeklerin muhasebesinde...

Sahte gülüşlerin 

Kahkaha kızı oldun...

Aldatmaca gecelerin

Yanılgı yıldızı oldun...

Boğdurdun kendini

Parlaması bile karanlık olan

Fani hayat yaldızlarına...

Oysa ben;

Zifirilikleri,

Yok olmaktan var olmaya geçiren

Tüm karanlıkları öldüren

Nur-u Muhammed-i ikliminden haber

Getirmiştim sana!

Ufkunu mu kamaştırmıştı

Karanlık yıllardan sonra

Nûr''un aydınlığı?

Zormuş değil mi?

Hicret etmek

Aldanmışlık ülkesinden 

Hakikât semtine....

Zormuş değil mi?

Ey bahtsız Hacer’im!

Hakikatime gelmedin

Ama ben

Dikeceğim senin hakikatini

Mezarının başucuna!

İşte o zaman

Öğreneceksin:

Göz yaşı ne

Ne nimet olduğunu göz yaşının?

Kimin düşman

Kimin kahraman

Neyin gurbet

Neyin vatan

Neyin post

Neyin dost olduğunu

Öğreneceksin

İşte o zaman

EY HACER!', 'Gittin Artık İstemiyorum ismini hecelemek Gül yaprağında Doğan günün kızıllığıyla Bir şairin yalnızlığında Gülsuyuna karıştırmayacağım  Rayi...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/istemiyorum-ismini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzeldi Hayat', 'duzeldi-hayat-halil-i-brahim-deveci-nujmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senle güzeldi hayat,

Anlamı varda yaşamanın

Biliyordum neden varolduğumu

Ve neden vardı hayat

Güzeldi be her şey

Her şey ıtır kokuluydu

Yoktu kalbimin korkusu yaşamdan

Yarından

Geçmişten

Gelecekten

Ümidimdin sen benim

Yaşama azmimdin,

Cennet hayalimdin

Senle vardı cennetin cehennemin anlamı

Şimdi var mı yok mu?

Bilemiyorum

O haldeyim ki;

Kendi kendimin anlamını bile unuttum

Bulamıyorum kaybettiklerimi

Dünümü

bugünümü

yarınımı

her şey birden silindi sanki

kayboldu hayat

yitti bulunanlar

hatıra olarak kalanlar

ve o gezdiğimiz kaldırımlar

düşlerde yaşayan hayal kadınlar

anlamsızlaştı

şimdi inan yaşamak zor geliyor

dünya, gözümün ufkuna dar geliyor

gecelerin anlamı da bitti

seher vakitlerinde de ağlayamıyorum

niyazla

duayla

yalvarışla

özlemle

cennete varamıyorum

cehennemden de kaçamıyorum

kaldım arada

bir yorgunluk belirdi 

kalpteki yarada

sığdıramaz oldum acıları yıllara

asırlara da

şimdi hissedebildiğim sadece bir kalp ağrısı

ve biraz da buruk bir hatıra

zaten o da olmasa

gecelerin bile bir anlamı yok

uykular bile çare vermiyor

Azrail de “Gel!” demiyor

kıyamette çok uzak gibi gözüküyor

bilmem ki, neden?

Nedenler başımı ağrıtıyor

Ağrıyor göz bebeklerim

Arıyor seni ellerim

O yumuşacık ellerini

Son bir kez avuçlarımda tutmak istiyorum

Ama olmuyor

Olmuyor be Hacer

Yaşamak olmuyor

İnsan isteyince de ölemiyor

Ölmekte olmuyor

Olmak ta

Şöyle, bir gün karşıma çık da

Çıkınca ta kalbime bir bak da

Oracıkta huzurla can vereyim

Tekrar yaşamak için istemiyorum seni

Eskisi gibi

Ölmek için arzuluyorum

Eğer fırsatım olmazsa seni görmeye

Mezarıma gel 

Ve ağla başucumda

Gözyaşlarını koklarım belki

Yeter mi bilmem ama

Gözyaşlarını bile özledim

Gülüşlerini özlediğim gibi.', 'Senle güzeldi hayat, Anlamı varda yaşamanın Biliyordum neden varolduğumu Ve neden vardı hayat Güzeldi be her şey Her şey ıtır kokuluydu Yokt...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/duzeldi-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-celikhanli-veli-ahi-rr34w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onlar yürüdüler 

Asırlara yürüdüler 

Hükmettiler gönüllere 

Kainata yürüdüler

Ölüm yıldırmadı onları

Zulüm yıldırmadı

Asude ufuklar saçtılar

Gölgeleri kaldı sadece

Ve de çınlayan sesleri

Ağladılar ve ağlattılar

Onlar yürüdüler

Yudum yudum içtiler kaynağından

An be an yaşadılar

Ölüm bir şerbettir

Ölümü hicvettiler

Gölgelerinin düştüğü yere 

Yüzümü sürerdim

Gölgeleri ışık oldu 

Yükseldiler yükseldiler

Onlar birer yıldız

Demişti ya ... ''''O''''

Gök kubbeye perçinlendiler

Hep bir yeri gösterdiler

Hep biri söylediler

İşaretleri birdi 

Sevdikleri birdi 

Yaşadıkları birdi 

Birle bir oldular

Kırdılar zincirleri

Birken bini gösteren

Binler onludular

Ölüm bir şerbettir

Ölümü hicvettiler

Siper ettiler göğüslerini

Kızgın kumlarda 

Karnındaki taşı erittiler

Onlara işkence edenler

İşkence çektiler

Onlar güldüler

Onlar sadece  ''''ona '''' ağladılar

Onları onlar yapan ''''o'''' ydu 

Sadece ''''onun'''' için ağladılar

Küfreden dağlar üstüne çullanırken 

Zerre kadar korkmadılar', 'Onlar yürüdüler  Asırlara yürüdüler  Hükmettiler gönüllere  Kainata yürüdüler Ölüm yıldırmadı onları Zulüm yıldırmadı Asude ufuklar saçtılar...', ARRAY['Türk Edebiyatı','Şiir','Çelikhanlı Veli Ahi']::text[], 8.5, '{"poet":"Çelikhanlı Veli Ahi","poet_slug":"celikhanli-veli-ahi","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/onlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Olun', 'cabuk-olun-halil-i-brahim-deveci-wsyw5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapanmış bana, öteye açılan kapılar,

Bir ben mi kalmışım, o kapıların önünde?

İmanlılara verilmiş, mukaddes tapular,

Ayaklarım gitmez, mukaddesâtın yönünde.

Evvah! Kaöırdım mı, en son vagonu da birden?

Şimdi o boşlukta sallanıyor ayaklarım.

Kûtsî ilaçlar getirin mukaddes revirden,

Çabuk! Cehenneme yollanıyor ayaklarım...

Yok mu bana tövbeyi öğretecek hocalar?

Öğret, af dileyeyim, geri kalan ömrümde.

Geç kalırsanız bu kul daha da çok bocalar,

İmansız gitmeyeyim, ansızın öldüğümde.

                                            (Adana-1996)', 'Kapanmış bana, öteye açılan kapılar, Bir ben mi kalmışım, o kapıların önünde? İmanlılara verilmiş, mukaddes tapular, Ayaklarım gitmez, mukad...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cabuk-olun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyecekler', 'i-steyecekler-halil-i-brahim-deveci-xv75w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meyve topladım, yerden ve gökten,

Gelenler ne toplayacaklar, benden?

Şerre bulanmış, eriyen, bu bedenden,

Bir şeyler isteyecekler...İsteyecekler!

Onlara, meyhânedeki kokularımı mı vereyim?

Yoksa Fâhişeden kalma cenâbetliğimi mi?

''Utan!'' derlerse, onlara, ne söyleyeyim?

Yakama yapışan ellere sarılıp;

''Ben, boşa yaşadım!'' mı diyeceğim?

Çırıl-çıplak, orta yerde, görülüp;

''Namaz kılıyorum!'' mu diyeceğim?

Gülecekler, ağlayana dek gülecekler;

Belki de; Affım için yakarıp AĞLAYACAKLAR!

                                              (Silifke-1989)', 'Meyve topladım, yerden ve gökten, Gelenler ne toplayacaklar, benden? Şerre bulanmış, eriyen, bu bedenden, Bir şeyler isteyecekler...İsteyece...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isteyecekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Sevdam lila', 'sende-sevdam-lila-harun-makaryus-01hed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gönlümle  başbaşa düşündüm  seni  artık bir sihirsiz nefes  gibisin  şimdi bomboş kalbimin içinde dalgaları biten deniz gibisin maziye karışıp sevda  yeminim  bi anda unuttum seni eminim kalbimde kalbine yok bile kinim  BENCE  ARTIK  SENDE  HERKES GİBİSİN....!!!', 'gönlümle  başbaşa düşündüm  seni  artık bir sihirsiz nefes  gibisin  şimdi bomboş kalbimin içinde dalgaları biten deniz gibisin maziye karış...', ARRAY['Türk Edebiyatı','Şiir','Harun Makaryus']::text[], 8.5, '{"poet":"Harun Makaryus","poet_slug":"harun-makaryus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sende-sevdam-lila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlıştaki Değerlerim', 'yanlistaki-degerlerim-halil-i-brahim-deveci-g3eg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruh üstü, sineme bastığım;

Yarım elma, bir de üzüm...

Kum saatine astığım;

Ân ki; Üzülüp, güldüğüm

                           (1996-Adana)', 'Ruh üstü, sineme bastığım; Yarım elma, bir de üzüm... Kum saatine astığım; Ân ki; Üzülüp, güldüğüm                            (1996-Adana)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanlistaki-degerlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş', 'bos-halil-i-brahim-deveci-dhyek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğduğumdan beri hep koştum...yürüdüm...koştum...

İlk günkünden farklı olarak, kirli bir boştum.

Yüzde bir de olsa dünyada kalma ihtimâlim;

Neler yapardım, neler!

Hiç...Hiç ihtimâlim yokken, neleer yapıyorum;

Neden bunca hayâller?

                      (1990-Adana)', 'Doğduğumdan beri hep koştum...yürüdüm...koştum... İlk günkünden farklı olarak, kirli bir boştum. Yüzde bir de olsa dünyada kalma ihtimâlim; ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Övünürüz', 'ovunuruz-halil-i-brahim-deveci-93pba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dakikacık üzülür,

On dakika seviniriz.

Tabut kenarını tutar,

Ömür boyu övünürüz.

                     (1996)', 'Bir dakikacık üzülür, On dakika seviniriz. Tabut kenarını tutar, Ömür boyu övünürüz.                      (1996)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ovunuruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı', 'ani-halil-i-brahim-deveci-eemhs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boşluğa boş boş bakan bir-iki göz,

Geçmişini arıyor, boşluklarda...

Anısını anlatmaya yetmez, söz,

Kendisini kaybetmiş, boşluklarda.

Pişmanlık, geçmiş günaha, pişmanlık,

Bir şişe şarapla gelen baygınlık,

Şaraba değil kendine düşmanlık,

Son secdeye var, yokoluşluklarda!

                                         (1996-Adana)', 'Boşluğa boş boş bakan bir-iki göz, Geçmişini arıyor, boşluklarda... Anısını anlatmaya yetmez, söz, Kendisini kaybetmiş, boşluklarda. Pişmanl...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu-Mu-Dur?', 'bu-mu-dur-halil-i-brahim-deveci-2s8ic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Öp beni!'' diyen iri iri ..me uçları,

Şehvete davet eden dudakların gülüşleri...

Buydu göze gösterilen, bu (zinâ) göze eziyet,

Bu-mu-dur; Adillik, Bu-mu-dur; tüm meziyet?

Bu-mu-dur;  İnsanlık için atılan temel?

Bu-mu-dur; Mutlu yarınlara beslenen emel?

Bu-mu-dur;  Hayr için yaratılan gözün mükâfatı?

Bu-mu-dur;  Hakikâttan da hak olan HAKK''ın hakikâtı?

                                                                 (1996-Adana)', '''Öp beni!'' diyen iri iri ..me uçları, Şehvete davet eden dudakların gülüşleri... Buydu göze gösterilen, bu (zinâ) göze eziyet, Bu-mu-dur; Ad...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-mu-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum Seni', 'dusunuyorum-seni-harun-makaryus-jkbzx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman   Yine   Gece  Yarısı  Düşünüyorum  Seni

Islak  Gözlerim  Camda Belki  Gelir  Diye

Bekliyorum   Seni...

Hani  Bir  Şarkımız  Vardıya   Yine  Onu

Söylüyorum.....

Deli   Gibi   Sevmişim   ve 

UNUTAMIYORUM...!!!', 'Zaman   Yine   Gece  Yarısı  Düşünüyorum  Seni Islak  Gözlerim  Camda Belki  Gelir  Diye Bekliyorum   Seni... Hani  Bir  Şarkımız  Vardıya  ...', ARRAY['Türk Edebiyatı','Şiir','Harun Makaryus']::text[], 8.5, '{"poet":"Harun Makaryus","poet_slug":"harun-makaryus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusunuyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Olmaktayım', 'seytan-olmaktayim-halil-i-brahim-deveci-8ips2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her ân batan güneşe baktıkça,

Güneşle...Güneşle hep batmaktayım!

Allah Resûlünden uzaklaştıkça,

Ruhum ile şeytan olmaktayım

                               (1994-Adana)', 'Her ân batan güneşe baktıkça, Güneşle...Güneşle hep batmaktayım! Allah Resûlünden uzaklaştıkça, Ruhum ile şeytan olmaktayım                 ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seytan-olmaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak', 'seni-yasamak-hakan-yigit-9nqrp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni yaşamak yüzyılı yaşamak gibi

Karda açan narin çiçeğim

Seni bilmek hayatın anlamı

Ben yine özledim seni uğur böceğim...

          (21 Aralık 2000-20.35)', 'Seni yaşamak yüzyılı yaşamak gibi Karda açan narin çiçeğim Seni bilmek hayatın anlamı Ben yine özledim seni uğur böceğim...           (21 Ar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Mlalı', 'dunya-mlali-halil-i-brahim-deveci-3peta', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya malı, boğazımda bir düğüm,

Bir düğüm müydü, uğrunda öldüğüm?

                                         (1995-Adana)', 'Dünya malı, boğazımda bir düğüm, Bir düğüm müydü, uğrunda öldüğüm?                                          (1995-Adana)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dunya-mlali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ruhum', 'benim-ruhum-halil-i-brahim-deveci-as7h2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya günlerine baharlar geldi,

Benim ruhumun günü hâlâ kışta.

Âdem, HAKK YOLUNUN SONUNA VARDI,

Gaflette, benim ruhum, hâlâ başta.

                                         (1995-Adana)', 'Dünya günlerine baharlar geldi, Benim ruhumun günü hâlâ kışta. Âdem, HAKK YOLUNUN SONUNA VARDI, Gaflette, benim ruhum, hâlâ başta.          ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende sevdam', 'sende-sevdam-harun-makaryus-8z6ko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umudum   iskambil  fallarında

Bir  kırmızı  bir  siyah  dizilimlerinde

Umudum  bir  uçurum  ortasın

İncecik  bir  fidanın bir  dalında

Umudum  dosthane  dillerin ucunda

Umutlarım  ummalarım  sende

SENDE    SEVDAM    LİLA...!!!', 'Umudum   iskambil  fallarında Bir  kırmızı  bir  siyah  dizilimlerinde Umudum  bir  uçurum  ortasın İncecik  bir  fidanın bir  dalında Umudu...', ARRAY['Türk Edebiyatı','Şiir','Harun Makaryus']::text[], 8.5, '{"poet":"Harun Makaryus","poet_slug":"harun-makaryus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sende-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yer...', 'o-yer-halil-i-brahim-deveci-a5ktm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlığın yırtıldığı o yerde,

Devâ bulunacak, devâsız derde!

                                (1996-Adana)', 'Karanlığın yırtıldığı o yerde, Devâ bulunacak, devâsız derde!                                 (1996-Adana)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/o-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlıştaki Adamsız Giden Gemi...', 'yanlistaki-adamsiz-giden-gemi-halil-i-brahim-deveci-qio8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçinde ben yokum, bir gemi geçer ufuktan,

Sana  hasretim, o gemiyle, hep uzaklaşır.

Ben kıyıdayım, ağarmakta şu kızılca tan,

O gemi ki; Mü''minleri şol cennete taşır.

                                            (1996-Adana)', 'İçinde ben yokum, bir gemi geçer ufuktan, Sana  hasretim, o gemiyle, hep uzaklaşır. Ben kıyıdayım, ağarmakta şu kızılca tan, O gemi ki; Mü''m...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanlistaki-adamsiz-giden-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikir Ve Yaşantı', 'fikir-ve-yasanti-halil-i-brahim-deveci-63e4g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zifirî karanlık içinde, fikrim, aydınlık,

Yaşantım, en hoş aydınlık içinde, karanlık!

                                               (1993-Adana)', 'Zifirî karanlık içinde, fikrim, aydınlık, Yaşantım, en hoş aydınlık içinde, karanlık!                                                (1993-A...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/fikir-ve-yasanti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-halil-i-brahim-deveci-gj27s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen neymişsin deli gönül,

Sevecek nefsi mi buldun?

Doğuştan eşmiydi gül,

Yaratılışında kuldun.

Geç artık fâni ömürden,

Haberin var mı, o günden?

Elbette öleceğinden,

Fâni miydi hak buudun?

                     (1996-Adana)', 'Sen neymişsin deli gönül, Sevecek nefsi mi buldun? Doğuştan eşmiydi gül, Yaratılışında kuldun. Geç artık fâni ömürden, Haberin var mı, o gün...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deli-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beden Ve Dağlar', 'beden-ve-daglar-halil-i-brahim-deveci-wko5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bedenim, maddeye ağlar da ağlar,

Ruhum; ''ALLAH!'' dedikçe titrer, dağlar.

                                           (1996-Adana)', 'Bedenim, maddeye ağlar da ağlar, Ruhum; ''ALLAH!'' dedikçe titrer, dağlar.                                            (1996-Adana)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/beden-ve-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Tövbe', 'son-tovbe-halil-i-brahim-deveci-1hu4t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tövbe ettim günah işlememeye,

Yine işledim yine işliyorum.

Bu ne zıtlık, tam düştüm hengâmeye,

Nefs beni, bense nefsi dişliyorum.

Ne o beni, ne ben onu bitirdim,

Sanırım, demle benliği yitirdim,

O vaz geçti, ben ona şer götürdüm,

Oturmuşda cenneti düşlüyorum...

Bu ne gaflettir, bu ne sefâlettir?

Ben gibiler, hak İslâm''a külfettir,

YâRabb! Sen bâri ruhuma sabrettir,

Son Tövbeyle yaşamaya başlıyorum.

                                           (1996-Adana)', 'Tövbe ettim günah işlememeye, Yine işledim yine işliyorum. Bu ne zıtlık, tam düştüm hengâmeye, Nefs beni, bense nefsi dişliyorum. Ne o beni,...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-tovbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Yol', 'tek-yol-goksel-limbozdag-10d3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecelerimin sayısı,kalbimin her atışı                

Bilmiyorum ne olacak bu sevginin akışı 

Tek bildiğim bir doğru varsa

O da gözlerimin gözlerine bakışı

Hayal kurdum sana, yalnız uzun gecelerde 

Aşkımı anlatmak isterdim ,tüm hecelerde

Ama bir korku var içimde sanki

Kalbimdeki cesaret bilmemki nerelerde

Aşktır bu belkide gizlenmesi zordur

Alevi sönmemiş sıcacık bir kordur

Kaçacak yer yok artık

Seni seviyorum demesi tek yoldur', 'Uykusuz gecelerimin sayısı,kalbimin her atışı                 Bilmiyorum ne olacak bu sevginin akışı  Tek bildiğim bir doğru varsa O da gözl...', ARRAY['Türk Edebiyatı','Şiir','Göksel Limbozdağ']::text[], 8.5, '{"poet":"Göksel Limbozdağ","poet_slug":"goksel-limbozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Seni Seviyorum', 'neden-seni-seviyorum-metin-usengec-0pwfv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden seni seviyorum

Bunu bende bilmiyorum

Ama bir şey biliyorum

Seni çok seviyorum

    

Bir şey daha biliyorum

Çok zor bizimkisi

Olması imkansız gibi

Ama seni seviyorum

Hem de çok seviyorum

Bir gün ayrılacağız elbet

Bitecek aramızdaki her şey

Ama bitmeyecek tek şey

Seni sevdiğim gerçek

Ama o da bitecek

Çünkü her insan bir gün gelecek

Ölecek..', 'Neden seni seviyorum Bunu bende bilmiyorum Ama bir şey biliyorum Seni çok seviyorum      Bir şey daha biliyorum Çok zor bizimkisi Olması imk...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Gecelerime Serptim', 'gozlerini-gecelerime-serptim-ugur-yolak-15sk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerini serptim gecelerime.

Serptim ki her rüyamda bir parça olsun gözlerinden.

Bir sevgi özlemi yüreğimden

Ağlamaklı duygularla saklanmış gözyaşım

Akar içimden.

Sen sevginin düşmanı 

Acının şahı

Sen karanlığın dostu

Günün şarlatanı.

Yıllarımı senden kaçmakla geçirdim.

Değerleri değersiz saymakla avundum.

Artık sıkıldım,

Mutluluğu rüyalarda yaşamaktan

Yılları sahte duygularla doldurmaktan.

Sıkıldım sevgisizlikten, duygusuzluktan.

Yaşamak günleri, arkana bakmadan,

Güzelliklerden kaçmadan,

Yaşamak esir olmadan, kıral olmadan.

Sahteliğe sarılıp sevgiden kaçmakan sıkıldım sıkıntılardan,

Hayallerle yaşamaktan,

Özlemekten,

Özlemleri bekletmekten.

Gözlerini serptim gecelerime.

Serptim ki her rüyamda bir parça olsun gözlerinden.

Bir sevgi özlemi yüreğimden

Ağlamaklı duygularla saklanmış gözyaşım

Akar içimden.

Çabalar gözler kaçmak için düşlerden.

Savaşır esaretle,

Tam malubiyeti kabul ederken

Bir dala tutundum ben.

O dal sevgiydi,

O dal cesaretti,

O dal sendin.', 'Gözlerini serptim gecelerime. Serptim ki her rüyamda bir parça olsun gözlerinden. Bir sevgi özlemi yüreğimden Ağlamaklı duygularla saklanmış...', ARRAY['Türk Edebiyatı','Şiir','Uğur Yolak']::text[], 8.5, '{"poet":"Uğur Yolak","poet_slug":"ugur-yolak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gozlerini-gecelerime-serptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı Bile Ağlar', 'tanri-bile-aglar-umit-yasar-oguzcan-gggji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem yalnızlığım aklıma gelir

Bir ürperti gibi derinden derine duyarım çaresizliğimi

Nedir bu gürültüler derim,top patlamaları

Nedir bu şakaklarımda zonklayan ağrı

İçimden dalga dalga boşanan gözyaşları ne

Bu hangi nehir ki uzayıp gider alabildiğine

Nedir bu ümitsizlik dolu bu kahır dolu yaşlar

Bu denizler altında kopup gelen fırtına

Bu bir çağlayan gibi uğultulu yaşlar

Oysa zamandır ilerleyen imkansızlıklar içinde

Başlangıcı olmayan bir sondur yaklaştığım

Bu ipince nehir nereye gidiyor bilen var mı?

Ağlatan ne beni?

O doyamadığım dakikalar mı?

Düşen aksi mi gözlerime o bal rengi gözlerin

Ki içimde çalkantısıyla hıçkırır denizlerin

Sorarım;bu ağlamak ne kadar nereye kadar

O zaman rüzgar durur fırtına diner ansızın

Kapanır yorgun gözlerim bir gece başlar

Ve karanlık uykularla sürer ağlama saatleri

Uyanınca bir ıslak şafaktır gördüğüm

Bir büyük resimdir gökyüzü seyrederim

Yine özleminle yanıp tutuşur gözbebeklerim

Duyarım vurgularını başımda çaresizliğin

Ben ağlayacak adam değildim bir kadın için

Beni perişan edecek ne vardı bu kadar?

Bir de ''Erkekler Ağlamaz'' diyorsun

Tanrılığından utanmasa

Tanrı bile ağlar...', 'Ne zaman seni düşünsem yalnızlığım aklıma gelir Bir ürperti gibi derinden derine duyarım çaresizliğimi Nedir bu gürültüler derim,top patlama...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tanri-bile-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Baharmış', 'bir-baharmis-hami-fiskeci-pmuj4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat ve sevgi dolu bir kişinin, hiç ummadığı biriyle tanışması ve acıyı tatması ve sitemi.', 'Hayat ve sevgi dolu bir kişinin, hiç ummadığı biriyle tanışması ve acıyı tatması ve sitemi....', ARRAY['Türk Edebiyatı','Şiir','Hami Fiskeci']::text[], 8.5, '{"poet":"Hami Fiskeci","poet_slug":"hami-fiskeci","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bir-baharmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Baharmış Aşkın', 'bir-baharmis-askin-hami-fiskeci-37urp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni tanımadan meğer ne mutluymuşum.

Umutlarım bir güneş gibi parlak,

Seni tanımadan önce.

Ama hepsi bir baharmış.

Birden çıktın karşıma.

Tutuldum sana,hesapsızca.

Dalından kopmuş bir yaprak misali.

Ama hepsi bir baharmış.

Gözlerinle,sözlerinle bağladın beni.

Sözlerinle sardın beni.

Gülüşünle yaktın beni.

Ama hepsi bir baharmış.

Kışın açan bahar çiçekleri gibi,

Güneşte ,yağan kar gibi,

Gündüz sönen yıldız gibi,

Geldin ve gidiyorsun, ardına bakmadan.

          Ama hepsi bir baharmış aşkım,

          senin için.', 'Seni tanımadan meğer ne mutluymuşum. Umutlarım bir güneş gibi parlak, Seni tanımadan önce. Ama hepsi bir baharmış. Birden çıktın karşıma. Tu...', ARRAY['Türk Edebiyatı','Şiir','Hami Fiskeci']::text[], 8.5, '{"poet":"Hami Fiskeci","poet_slug":"hami-fiskeci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-baharmis-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldiğin Günün Hatırası', 'geldigin-gunun-hatirasi-okan-arsu-8hyzy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana nasıl anlatılır

Sensiz hayatın boşluğu

Bir zindanın ağır ağır

Çöker üstüme loşluğu

Dünya her minnete bedel

Hayat,hayal,ümit,emel

Sen olduğun için güzel

Senden alıyor hoşluğu

Arıyorum seni uzak

Bir şehirde sallanarak

Hala geldiğin günün bak

Üzerimde sarhoşluğu', 'Sana nasıl anlatılır Sensiz hayatın boşluğu Bir zindanın ağır ağır Çöker üstüme loşluğu Dünya her minnete bedel Hayat,hayal,ümit,emel Sen ol...', ARRAY['Türk Edebiyatı','Şiir','Okan Arsu']::text[], 8.5, '{"poet":"Okan Arsu","poet_slug":"okan-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geldigin-gunun-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An Anlarsın', 'o-an-anlarsin-okan-arsu-nnouu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün karşına deli gibi seveceğin biri çıkarsa

Sen kahrolurken O aldırmazsa

Seninle alay edelir gururun kırılırsa

İşte benim ne demek istediğimi O An Anlarsın

O kişi önce sever sonra terk ederse

Tüm umutlarını yıkıp hayatını mahvederse

Sen acı çekerken birde unut derse

İşte benim ne demek istediğimi O An Anlarsın

Ona nefretin sevgiye dönüşürse 

O unut dedikçe gönlün hala severse

Dostların düşmanların bu haline gülerse

Severken terk edilmek ne demek O An Anlarsın

Hergün çaresizliği yudum yudum içersen

Usanıp bu yaşamdan kendinden geçersen

Dertlerini unutmak için hep ölmek istersen

Benim neler çektiğimi O An Anlarsın

Bir gün ansızın onunla karşılaşırsan

Gözyaşlarını tutamayıp hergün ağlarsan

Özlem Ateşiyle günden güne yanarsan

Yaşarken Terkedilmek ne demek O An Anlarsın', 'Birgün karşına deli gibi seveceğin biri çıkarsa Sen kahrolurken O aldırmazsa Seninle alay edelir gururun kırılırsa İşte benim ne demek isted...', ARRAY['Türk Edebiyatı','Şiir','Okan Arsu']::text[], 8.5, '{"poet":"Okan Arsu","poet_slug":"okan-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-an-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Doğru', 'gunese-dogru-sair-verde-di65u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşe doğru çocuğum güneşe doğru 

Hayallerinde , umutlarında güneşe doğru olsun

Tıpkı ayçiceklerinin yaptığı gibi,

Ömrün güneşe doğru olsun çocuğum , güneşe doğru.

Yüzün hiç karanlık görmesin,

Yüreğin hep aydınlık olsun,

Hıçkırıklarla sev sevdiğini,

Heyecanların, aşkların güneşe doğru olsun,

Tıpkı ayçiceklerinin yaptığı gibi,

Ruhun hep güneşe doğru olsun , güneşe doğru..

Sabahı olmayan bir geceye gebe isen,

Açılmayan her  kapıyı  çalan sen isen,Vakitsiz akan gözyaşlarının sahibi isen,

Sakın üzülme çocuğum,

Alnın güneşe doğru olsun

düşüncelerin ise güneş gibi..

Soğuk mevsimler sonu bakışlarınla ısıt etrafı,

Varlığı öyle sev ki nefesinle getir mehtabı,

Çimenler halın olsun, yıldızlar ise baştacı,

Adın güneş konsun çocuğum,Sevdan ise güneşe doğru..

                          (12 şubat 2000)', 'Güneşe doğru çocuğum güneşe doğru  Hayallerinde , umutlarında güneşe doğru olsun Tıpkı ayçiceklerinin yaptığı gibi, Ömrün güneşe doğru olsun...', ARRAY['Türk Edebiyatı','Şiir','Şair Verde']::text[], 8.5, '{"poet":"Şair Verde","poet_slug":"sair-verde","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunese-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemiyet', 'cemiyet-halil-i-brahim-deveci-ot1f2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cemiyet! Gidilen yol, yol değil; bir bataklık,

Bu yolda da hüküm süren sahte kahramanlık,

Alp-erenliğe yer yok, bu çirkef zeminde,

Bir başı-boşluk var, gelen çağın gündeminde,

Göç yolunda namus, namussuzluk yerleşmekte,

Haklar ayrılırken, imânsızlık birleşmekte,

Namus ağacını kesiyor, şerli baltalar,

Sokakta kadın-erkek; üst-üste, alt-altalar,

Sarsılıyor, namus ağacının hak dalları,

Her dem ayrılıyor Mü''minlerin yolları.

Oturun, düşünün, nere gidiyoruz bizler?

Türk''e senaryodaki rol: Cetsiz kimsesizler!

Kopukluk, aile bağlarında bir kopukluk,

Evde kavga-gürültü ve sokakta sarhoşluk!

Sallanır ar abidesi asırlık çınarlar,

Namusun bekçisi oldu, kişisel çıkarlar!

Mini etekle işportacıya kaldı,namus,

Haya, gündüzün gözüyle, çağdaşlara kâbus(!)

Görünüş bu; yıkık, dökük, arsız, gamsız, şaşkın,

Fuhuşun, yüzsüzlüğün çeşidi bini aşkın,

Namussuzluk boğaz boyuna gelmiştir, lâkin,

Namuslu gaflette, durumu oldukça sakin!

Bir kıvılcım yeter, arsızlığı durdurur,

Hedefi tam isabetle onikiden vurur.

Ve sorar; ''Siz kimsiniz, neden bu hâkimiyet?

İşte o zaman, gerçeği görecektir elbet;

Buğulu cam ardında secde eden nineler,

Çır-çıplak; ''Yalnız namusluyum!'' diyen annneler!

Ve en kötüsü, ninelerden utanan kızlar,

Kızları, küfre boğan şu dünyalık yıldızlar!

Tüm olumsuzluğa rağmen yaşamaya sebep,

Tek-tük okunan Kur''ân-ı Kerîm midir acep?

Evet, evet!...Allah''ın lütufları, bunlardan,

Hafız doğurmasını bekliyoruz, analardan!

Doğurun... Doğurun analar, hak İslâm için!

Doğurmadan düşünün; İnsanlar doğar, NİÇİN?

                                                      (1996-Adana)', 'Cemiyet! Gidilen yol, yol değil; bir bataklık, Bu yolda da hüküm süren sahte kahramanlık, Alp-erenliğe yer yok, bu çirkef zeminde, Bir başı-...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/cemiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Sana Yazdim', 'geceyi-sana-yazdim-aydin-ozturk-rpygk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceyi sana yazdim, sizimi sana

Tutundum kusen sesine, teline tutundum

Caktim atesi sesime, atesi tenime

Ayaydinlik sana yandim

Gulen yuzune yandim

Yanarim sana

Sensizim, sana kostum iklimler boyu

Uykular, yanan liman uykular haram

Bir vapur gecer, dalgasinda savrulan ben

Don yurek yurduma

Gurbet  tenime don

Yanarim sana...', 'Geceyi sana yazdim, sizimi sana Tutundum kusen sesine, teline tutundum Caktim atesi sesime, atesi tenime Ayaydinlik sana yandim Gulen yuzune...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceyi-sana-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-aydin-ozturk-htfx8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Simdi uzak bir kenttesin

Ve yagmur yagiyorsa

Dusuyorsam yuregine tane tane

Gelirim, serilirim kiyilarina

Gelirim, karisirim cigliklarina

Sokulurum derin uykularina

Bak iste aksam oldu

Ve suskundur tum sokaklar

Cok uzaklarda bir kadin

Yureginin perdelerini simsiki kapatmisti

Belki de bu perdelerden bunalmisti

Karanliga alisan gozleri

Yureginin kaynarinda yaniyordu.

Icinde kopekbaliklarinin boguldugu 

Bir Kizildeniz sakliyordu

Kirpiklerinin kiyisindaydi

Ilk damla ayrildi buluttan

Sonra ikincisi...Ucuncusu

Issiz sokaklardan, kirmizi kiremitlerden

Toz yukseliyordu

Hangi kacis ugultusunu dindirebilir

Icinizdeki mavi karli ormanin

Hangi cinar

Dallarinin kirildigi yerden inlemez

Sonunda dagalyani olmussa omrunuzun

O sagnaktan orda kalan

Sargilar sarabilir mi yaralarinizi

O liman yurekte degilse eger

Artik nereye siginir insan

Bir irmagin sesini alip

Gitmek istiyorum

Sevdigim hoscakal

Gelirim, serilirim kiyilarina

Gelirim, karisirim cigliklarina

Sokulurum derin uykularina

Bak iste aksam oldu

Ve suskundur tum sokaklar', 'Simdi uzak bir kenttesin Ve yagmur yagiyorsa Dusuyorsam yuregine tane tane Gelirim, serilirim kiyilarina Gelirim, karisirim cigliklarina Sok...', ARRAY['Türk Edebiyatı','Şiir','Aydın Öztürk']::text[], 8.5, '{"poet":"Aydın Öztürk","poet_slug":"aydin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''dan Bu Gece Ayrılıyorum', 'ankara-dan-bu-gece-ayriliyorum-hami-fiskeci-n7qkg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ankara''dan bu gece ayrılıyorum.

Sessizce terk ediyorum kenti,

Hiç arkama bakmadan yaşadığım ve,

yaşadıklarımı umursamadan.

Oysa bir zamanlar caddelerinde gezdiğim.

Kafelerinde çay içtiğim.

Kalesinden baktığım.

Güzel kızlarıyla gezdiğim.

Ankara''dan bu gece ayrılıyorum.

Ne dostlarımdan

Ne yalnızlığımdan

Ne de kıskanç bir sevgiliden kaçıyorum.

Yolumuz düştü artık sılaya,

Geri ne zaman dönerim bilmem.

Gidip dönememek,

Gelip görememek her zaman var.

         Ama ben bu gece ayrılmak zorundayım

         zor olsada Ankara''dan.', 'Ankara''dan bu gece ayrılıyorum. Sessizce terk ediyorum kenti, Hiç arkama bakmadan yaşadığım ve, yaşadıklarımı umursamadan. Oysa bir zamanlar...', ARRAY['Türk Edebiyatı','Şiir','Hami Fiskeci']::text[], 8.5, '{"poet":"Hami Fiskeci","poet_slug":"hami-fiskeci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ankara-dan-bu-gece-ayriliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamlar', 'adamlar-ahmet-muhip-diranas-ufmqi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sönmüş saçlarında son damla ışık,

Bir düş''ün içinde gibi her akşam

-Ve yüzleri duman kadar dağınık-

Geçer bu sokaktan b
..........
..........', 'Sönmüş saçlarında son damla ışık, Bir düş''ün içinde gibi her akşam -Ve yüzleri duman kadar dağınık- Geçer bu sokaktan b .......... ............', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sokak', 'bir-sokak-ahmet-muhip-diranas-y5rmw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece lambaların kör ışığı içinde

-----Herkes ömründe bir kez olsun o yoldan geçer___

