INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sorarlarsa', 'beni-sorarlarsa-atabay-guveloglu-gcanw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden böyle erken gitti derlerse,

Bu çağa bir türlü uyamadı de!

Her yeri sağlamdı ama nedense

Kalbi gidenlere dayanmadı de!

Gezer idi dünyanın üst katında,

Sanki evren çöktü,kaldı altında.

Ayrılıklar varmış onun bahtında

Sevdiği canlara doyamadı de!

Bunca haksızlığı görüp ve duyup,

Sebat edemedi,düzene uyup.

Sitemler ederek şiir okuyup

O akşam ilk defa ağlamadı de!

İki rakı içti,sitem eyledi,

''Olmaz ilaç''şarkısını söyledi.

Sonra''Haydi yalan dünya,eyvallah''dedi,

Uyudu,bir daha uyanmadı de!', 'Neden böyle erken gitti derlerse, Bu çağa bir türlü uyamadı de! Her yeri sağlamdı ama nedense Kalbi gidenlere dayanmadı de! Gezer idi dünyan...', ARRAY['Türk Edebiyatı','Şiir','Atabay Güveloğlu']::text[], 8.5, '{"poet":"Atabay Güveloğlu","poet_slug":"atabay-guveloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-sorarlarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sandal', 'eski-sandal-nurettin-ay-1bavo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski bir sandaldı yüreğim

Ümitle çürümüş tahtaları

Sonra batmış sevda denizinin en dibine

Birlikte götürmüş içindeki sevgiyi de

--

Şimdi eşsiz bir hazine sevgim

Kalmadı onu kaldıracak kuvvetim

Son kez denedi taşımayı şu kalbim

Ona da izin vermedi ZALİM YARİM...', 'Eski bir sandaldı yüreğim Ümitle çürümüş tahtaları Sonra batmış sevda denizinin en dibine Birlikte götürmüş içindeki sevgiyi de -- Şimdi eşs...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eski-sandal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymaz Dünya', 'doymaz-dunya-nurettin-ay-1dgiz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatımdan aldıkların yetmedi mi

En güzel yıllarımı, içimdeki sevgimi

Gözlerimdeki ümidimi, gülümsememi

Daha ne istersin doymaz dünya

--

Artık senle mücadele gücüm

Verdiğin dertleri kaldıracak yüreğim

Senin peşinden koşacak nefesim kalmadı

Daha ne istersin doymaz dünya

--

Ama yenik düşmeyeceğim senin eline

Hep dimdik çıkacağım karşına

Bir canım kaldı geride

Daha ne istersin doymaz dünya

--

Sana son bir sözüm var iyi dinle

Yılardır yıkadın yanaklarımı yaş ile

Gönlümü biledin aşk ile

Eğer yenik düşersem eline

Senide beraber götürürüm ben ile', 'Hayatımdan aldıkların yetmedi mi En güzel yıllarımı, içimdeki sevgimi Gözlerimdeki ümidimi, gülümsememi Daha ne istersin doymaz dünya -- Art...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/doymaz-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Denizkızı', 'kucuk-denizkizi-nurettin-ay-wbrow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizli bir kıyıda rastladım sana

Öyle güzel duruyordun ki o kayada

Tatlı bir gülümseme vardı dudaklarında

İşte o anda kalbim vuruldu sana

--

Sonra dalıp gittin o masmavi sulara

Geride dalgalara bıraktığın buse kaldı bana

Yakalayabilmek için o masum buseyi

Daldım meskenin olan masmavi sulara

--

Artık seni düşünmeden geçmiyor bir an

Bir kez daha görebilmek için seni

Geliyorum her gün o kayalıklara

Gözümde canlanıyor hep seni gördüğüm o an

--

Fırtınalı bir günde gene geldim oraya

Kalbimde kanayan hiç durmayan yaramla

Kayalıklara doğru giderken Azrail’ le kol kola

Çıkıverdin o kasvetli sulardan gözlerindeki ışıltıyla

--

Kurtardın beni o azgın sulardan

Bir buse ile merhem oldun kanayan yarama

Sen KÜÇÜK DENİZKIZI aldın beni

Sevgi ve umut saçan o deniz kokan kollarına

Sonra daldık beraber sevgi okyanuslarına...', 'Gizli bir kıyıda rastladım sana Öyle güzel duruyordun ki o kayada Tatlı bir gülümseme vardı dudaklarında İşte o anda kalbim vuruldu sana -- ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Ay']::text[], 8.5, '{"poet":"Nurettin Ay","poet_slug":"nurettin-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kucuk-denizkizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-rabia-yener-uauzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Batan bir gün olsada

Doğacak olan malüm.

Kapılar kapalı belki,

Açılınca ardındaki malüm,

Güneş kadar sıcak

Bir o kadar aydınlık

Fakat neden fikrin, 

Hisse verdiği bu zulüm...', 'Batan bir gün olsada Doğacak olan malüm. Kapılar kapalı belki, Açılınca ardındaki malüm, Güneş kadar sıcak Bir o kadar aydınlık Fakat neden ...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ol', 'sen-ol-rabia-yener-nwjle', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir düzen var hayatımda ama

Benim düzenim, çılgınlıklarım,

Olur yaptığım olmazlarım.

Hiç aramadığım ama aradığımı sandığım,

Bir düzenim var olduğunu sandığım.

Bak şimdi darmadağın,

Korkacak kadar uzak, görünmiyecek kadar,

Hah toplasan birkaç metre ama taa...

Ardında, aşmak istediğim tek dağın.

Anlatacaklarımda var hani,

Ne sanıyorumki, anlatınca benden

Kopacaklar sanki, diyorumki;

Boş bir ukala zannetme yani...

Boşver kopsun diycem...!

Ne demek dedim bile,

Belki kalbimden dilime,

Dilimden kopsalar al senin olsun diyce...

Kulaklarımla işitmeden, inandığım,

Bana göstermeden...

Keşke kalbimi yerinden ayıracak gibi olsa,

Biliyorum ne dediğimi ama,

Hissettiğimi anlatamam seni su gibi içmeden.

Gördüğümü sandım seni,

Yada seni gördüğümü sandım,

Ne farkeder şimdi bunu yazdım.

Çok uzak... mekanım kadar

Kimbilir önceden ne yazdım...

Sen ordayken çıkıp gelmek, ama...

Yapabileceğim kadar istemek.

İşte yapmam gereken bu,

Belki dün gibi

Dahası, yapabileceğimi bilmek.

Dışarı baktığımda, bu gece

Belki ayı göremesemde...

Birisi var bu yaptığımı bilen

Nolur bilen sen ol yine...', 'Bir düzen var hayatımda ama Benim düzenim, çılgınlıklarım, Olur yaptığım olmazlarım. Hiç aramadığım ama aradığımı sandığım, Bir düzenim var ...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sitem', 'sevgiliye-sitem-mefail-ozbek-skjzl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı beyaz renkler bayrak misali, 

Çokta yakışmıştı kıyafeti, 

Boş boş bakıp geçti içim cız etti, 

Gülüm beni tanımadı. 

Kırmızı karanfil takmış göğsüne, 

Rengi de canlı mı canlı. 

Köşede karşılaştık, 

Kalbim duracaktı. 

Boş boş bakıp geçti, 

Gülüm beni tanımadı. 

Yoluna turabolam, 

Hiç mi izi kalmadı anıların. 

Hikâyelerde böyle bitmez sanırdım, sevdaların. 

Hatırladı sandım, sevindim. 

Boynunu büktü güldü geçti, 

Gülüm yine tanımadı.', 'Kırmızı beyaz renkler bayrak misali,  Çokta yakışmıştı kıyafeti,  Boş boş bakıp geçti içim cız etti,  Gülüm beni tanımadı.  Kırmızı karanfil...', ARRAY['Türk Edebiyatı','Şiir','Mefail Özbek']::text[], 8.5, '{"poet":"Mefail Özbek","poet_slug":"mefail-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla Olsam', 'damla-olsam-rabia-yener-9v0pr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gelince aklıma :))

Bir yalan söylüyorum kendime,

İçimle alakası yok, öyle bir yalan;

Yalan şu seni sevmediğim...

Yinede arıyorum seni ellerimde,

Gördüğümü sandığım düşümde,

Ama biliyorum, uyanınca,

Gerçek ; seni görmediğim...

Tutunduğum bir dal var ya...

O senin güzelliğin, senin sesin

Senden bile korkuyorum,

Korktuğum ; o dalı keseceğin...

Dün gece beni kanatlandırdın,

Uçtuğumu sandırdın

Bulutlara bak, bekle beni

Yağmur olup yağacağım...

Islanacak saçların, yürüdüğün yolların,

Ayak izlerindeyim

Toprak kokusunda, olduğunca yakın,

Ve o an güneş doğacak,

Her damlamda sana yansıyacağım,

Sen beni gökkuşağı sanacaksın...

Oysaki etrafındayım.

Sana ondan yakın olacağım...

Işık büyüyecek, nur olacak belki

Bulacaksın gökkuşağının

Altındaki altını...

O an göreceksin beni,

Yüzüm sana uzak diilki...

Soluduğum...

Yaşadığım...

Ve her duyduğum olacaksın

Ulaşmak için çırpındığım

Toprağım olacaksın...

Yeşereceksin, göreceksin

Herşey bitti diyeceksin,

Toprağım olacaksın...

Herşeyi yeniden başlatacaksın.

Tamamına yalan de...

Her damlama sıradan de...

Gökkuşağını bekleme ve

Beklediğini söyleme...

Dur... söylediğin neydi?

Hayatın ne renkti?

Siyah ve beyaz idi

Bu senin söylediğindi...

Benimki tek renkti...

Artık çok renkli

Tek rengim senindi, senin diil,

Tek rengim sensin belki.

Çok yüksekteysem,

Düşecem diye düşünsem,

Kanat olacaksın bana...

Yinede düşecem desem,

Deniz olursun bana.

Parmaklarımdaki kalemmi

Buna sebep, yoksa...

Sencede seviyormuyum seni

Buzun dağı sevdiği gibi,

Yada benim seni...', 'Sen gelince aklıma :)) Bir yalan söylüyorum kendime, İçimle alakası yok, öyle bir yalan; Yalan şu seni sevmediğim... Yinede arıyorum seni el...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/damla-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesafe', 'mesafe-rabia-yener-96nzp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aramdaki mesafe bir metreydi seninle

Hiç olmadım böyle, konuştuğumdan korkmadım

Kimseyle,

İki dudak, arasında bir nefes

Konuşsaydım belkide, gülermiydim seninle...?', 'Aramdaki mesafe bir metreydi seninle Hiç olmadım böyle, konuştuğumdan korkmadım Kimseyle, İki dudak, arasında bir nefes Konuşsaydım belkide,...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mesafe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-rabia-yener-1fjry', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum...

ne düşündüğümden habersiz.

Şu ana bile görememek seni,

uzaklaşacağını bilmek ve

hissetmek evet... korkuyorum...

Ellerini tutamamaktan korkuyorum...

aşık olduğum ellerini...

dokununca titreten bedenimi...

doyamadığım ellerini ve

bilmek evet... korkuyorum...

Gözlerine bakamamaktan korkuyorum...

ışığın her deminde gözlerine,

derin denizler gibi...

büyüleyen ve ağlatan gözlerimi,

görebilmek evet... korkuyorum...

Sesine uzak olmaktan korkuyorum...

aşık olduğum vurgularına,

dinlemek istiyorum uzunca...

her zaman yakınlarında,

duymak evet... korkuyorum...', 'Seni düşünüyorum... ne düşündüğümden habersiz. Şu ana bile görememek seni, uzaklaşacağını bilmek ve hissetmek evet... korkuyorum... Ellerini...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korkuyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrı Bir şeysin...', 'ayri-bir-seysin-rabia-yener-hffsk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Damla damla bir deniz topladım senden

Ellerim cennet tuttu uzak bir yerden

Yıldızlı gecesiyle bir demet gülden

Beşinci mevsim gibi ayrı bir şeysin

Özledim rüya kızım, güldür içimi

Sesleniş yetmez oldu, hergün sesimi

Büyüler ülkesinde, masal biçimi

Aklımın ermediği ayrı bir şeysin.

Dua ettim olmadı seni bulmaya

Çocukluğum depreşti, deliyim yada

Başkası bana göre yalancı dünya

Anlayıp yaşadığım ayrı bir şeysin.

Gitme otur yanımda, öldür vedayı

Düşmanım yapma ne olur benim aşkımı

Her günümde her nefes, her mart ayı

Burcu burcu can kokan ayrı bir şeysin.', 'Damla damla bir deniz topladım senden Ellerim cennet tuttu uzak bir yerden Yıldızlı gecesiyle bir demet gülden Beşinci mevsim gibi ayrı bir ...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayri-bir-seysin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VII', 'vii-deniz-ulas-ana7a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Adı olmayan bir yazgıydın sen

Yazgıların en farklı yazılanı''

Konuştuğun alfabede bir harf hep eksikti

Ömründeyse hep eksik kalmıştı bir şeyler

Bu yüzden sözcükler

Öyle kolayca içine giremezdi.

Konuştuğun alfabe kadar masum gelirdi bana sadeliğin.

Patlamalı seslerde zorlanan dilin,

En patlamalı sarsıntıları büyütürdü içinde.

Ve ''seviyorum'' demek;

Biliyorum,

Hep zor gelirdi diline.

Bunun için ''sevdim'' demeyi,

Daha kolay sindirirsin içine.

Ben ''seviyorum'' u bu kadar temiz,

                                 bu kadar güçlü,

                                 bu kadar sevdalı duymamıştım ömrümde.

Ve duyduklarım yetiyor;

bunu di''li geçmişten yayıyorum 

tüm ömrüme.

Biliyorum,

İstekler için çok geç,

Sen alışkınsın eksik harflere.

Şimdi eksik bir harfmişim gibi

Yok ediyorsun beni

Hem sözcüklerde, hem de içinde

Bense eksilen harflerimle

Alfabeler yakıyorum,

Harfleri kül edip,

Sevdamı susuşlarla yaşıyorum.', '''Adı olmayan bir yazgıydın sen Yazgıların en farklı yazılanı'' Konuştuğun alfabede bir harf hep eksikti Ömründeyse hep eksik kalmıştı bir şey...', ARRAY['Türk Edebiyatı','Şiir','Deniz Ulaş']::text[], 8.5, '{"poet":"Deniz Ulaş","poet_slug":"deniz-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VI', 'vi-deniz-ulas-nwipr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimdeki ağaçsız orman yangınlarım

hükmünü sürdürürken tüm hararetiyle

Ben oturup çöllerimde düşünüyorum

vahalarda gördüğüm sen 

acaba serap mıydı? diye

Kendi sezgilerine

Kendi  bilgilerine

Kendi  hislerine

Kendi  bedenine

Yani tepeden tırnağa kendine yabancılaşmış beynimle

Tutarsız ritmime rağmen düşünüyorum

Sesinden duyduğum ezgiler 

Acaba sanrı mıydı diye?

Biliyorum 

Artık pırıl pırıl rezervesiz sabahlar yok artık

Kumrular uğramayacak,sabah ezanının sesiyle pencereme

Biliyorum o iki kişilik

Ölçüsüz,pürüzsüz ezgilerin, düeti yok artık

Sözcüklerin-m bile gülmüyor yüzüme

İçimdeki denizsizliğin alaborasında

Tutunacak bir parça nesne yok batan sevda gemisinden

Ben dalgalarla boğuşurken 

Biliyorum yüzmeyi hiç öğrenemeyeceğim

Öğrensem de ne fark eder

Seninle

Sularda sevişmenin tadı ile 

Yüzemeyeceğim.

(19-20 Eylül ''98)', 'İçimdeki ağaçsız orman yangınlarım hükmünü sürdürürken tüm hararetiyle Ben oturup çöllerimde düşünüyorum vahalarda gördüğüm sen  acaba serap...', ARRAY['Türk Edebiyatı','Şiir','Deniz Ulaş']::text[], 8.5, '{"poet":"Deniz Ulaş","poet_slug":"deniz-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni-andim', 'seni-andim-rabia-yener-jfph2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak,

Yine seni andım durup dururken.

Hani insan,

Çayır kokusunda bulur bazen sevgiyi...

Tırmanırken,

İnmenin ferahlığını duymak ister,

Dduyamaz...

Özlemleri yazarken kalemin ucunda,

Yüreği şaha kalkar da

Haykıramaz...

Sen;

Özlemlerin en yücesi değilsin belki,

Ama en anlaşılmazı

Ve ulaşılmazısın nedense...

Bilsen;

Kaç kez unutmak istedim seni,

Kaç kez...

Unutamadım.

Çünkü kalbim buna

Dayanamaz...', 'Bak, Yine seni andım durup dururken. Hani insan, Çayır kokusunda bulur bazen sevgiyi... Tırmanırken, İnmenin ferahlığını duymak ister, Dduya...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-andim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Demet Gül', 'bir-demet-gul-rabia-yener-zc90u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir demet gül olmak isterdim şimdi,

Bir demet gül...

Tenin kadar canlı,

Dudakların kadar kırmızı,

Gözlerin kadar büyüleyici olan...

Bir avuç kum olmak isterdim;

Parça parça, lime lime

Pare pare ıslak bir avuç kum...

Hatta,

Bir tutam kül olmak isterdim,

Ama nefesin gibi ılık,

Sesin gibi taze olmalı

Her bakışında savrulmalıyım

Saçların gibi. darmadağın...', 'Bir demet gül olmak isterdim şimdi, Bir demet gül... Tenin kadar canlı, Dudakların kadar kırmızı, Gözlerin kadar büyüleyici olan... Bir avuç...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-demet-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyecan', 'heyecan-mefail-ozbek-r8xd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Heyecan var adında

Bal tadı var tadında

Bir buse alıverdim 

Seni benim sandımda

    Hep kalbimde saklardım

    Gül yerine koklardım

    Bir elime geçirsem

    Öper sever okşardım

Sevgi yumağı olsam sana

Öpsem sevsem kana kana

Düğünümüz var diyebilsem

İlan etsem tüm cihana

    Kalpte yazılıdır adı

    Baldan tatlıdır tadı

    Sevginin olmaz soyadı

    İster yoksul,ister zengin,ister kadı', 'Heyecan var adında Bal tadı var tadında Bir buse alıverdim  Seni benim sandımda     Hep kalbimde saklardım     Gül yerine koklardım     Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mefail Özbek']::text[], 8.5, '{"poet":"Mefail Özbek","poet_slug":"mefail-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/heyecan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Gelince', 'zamani-gelince-rabia-yener-72ts3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün bir fırtına bu

Başından sonuna kadar yaşanan

Eski bir fırtına

Unutulmaz ama heybetli

Nasıl doğdu yada 

Neden doğdu unutulan

İçindeyim sadece...

Ama ne güzel fırtına

Meleklerin dansettiği

Hüzme hüzme ışıklarda

Lirik bir melodide

Ama kulakların duymadığı

Eşik ötesi tınısıyla

Karanlık gibi hava ve bu son tenha

Eski değil artık tanıdık sedasıyla

Korkardım önceden sensizlikden ya

Veda ederdim kendime senden önce

Ilık nefesinle geldin ya

Laleler gibi hızlı yaşayıp , ölebilirim yanında

Meğer olabilirmiş , köpük köpük sevgiler

Eskiden duyardım yalnızca ama

Yaşıyorum şimdi seni , bütün fırtınada. 

Nisanda yağmur gibi değil,

Olabildiğince derin

İzini bulman mümkün her adımımda

Körkütük sarhoşken bile 

Rabia yazabiliyorum bakdığım her yere

Tozlanmış bakışlarımla bile

Med gibi cezir gibi kalbim

Ufuktan görünür ancak

İzle bir gün takip et

Alıp götürsün seni bırak

Soluklarımı keser , nede olsa

Mesafe yok aramızda

İzlerinde adın var , peşlerinde kanımla

Azar azar izler var

Nakış nakış adında , Kalbimdeki tahtında...

                      ?', 'Bütün bir fırtına bu Başından sonuna kadar yaşanan Eski bir fırtına Unutulmaz ama heybetli Nasıl doğdu yada  Neden doğdu unutulan İçindeyim ...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/zamani-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmayım...', 'durmayim-rabia-yener-nv4bg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çırpıntı

Pardon bir çarpıntı kalbimde...

Ama yağmurdan değil , rüzgardan

Bana şöyle der ;

Bir bahar ver kendine

Ama belli olmasın ne zaman yaz olacağı

Ve baharda yaşa tatlı kızı

Sonra um ki ! Bitmesin bahar

Um ki ! Yazı istemesin

Ve um ki ben durmayım.', 'Bir çırpıntı Pardon bir çarpıntı kalbimde... Ama yağmurdan değil , rüzgardan Bana şöyle der ; Bir bahar ver kendine Ama belli olmasın ne zam...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/durmayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Yol', 'toprak-yol-rabia-yener-47dxs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gelişimde yapboza bir tahta

Sonra gidişim...

Mutlu bir hüzün

Ve ondan örülmüş toprak yol

Üzerinde ben ama yalnız

Sudan bir sandalyedeyim

Çok hareketliyim ama...

Korkutuyor hareketi havanın , 

Sonra gidişim...

Sonra gidişim geliyor

Gidişim gidinceye kadar mutlu hüzün

Ve değilken yanında onun!

Yürüyorum ve yaşıyorum tam üstünde

Mutlu hüzünden toprak yolun...

İşte...

İşte bu yüzden seviyorum

Yada sevdiğim için bu yüzden

Elindeyken , sevincim bile

Buluyorum aramadan en tatlı mutluluğumu

Mutlu hüzünden toprak yolun...', 'Her gelişimde yapboza bir tahta Sonra gidişim... Mutlu bir hüzün Ve ondan örülmüş toprak yol Üzerinde ben ama yalnız Sudan bir sandalyedeyim...', ARRAY['Türk Edebiyatı','Şiir','Rabia Yener']::text[], 8.5, '{"poet":"Rabia Yener","poet_slug":"rabia-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/toprak-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet Var...', 'davet-var-halil-i-brahim-deveci-qwsfp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim nazlı yârim!

Bir kulak dayasan,

maverâdan ne sesler geliyor!

Hacer''i çağıran nağmeler yükseliyor...

Arş-ı âlâ''nın esrar yerine

Hâlâ yaşlar gelmez mi gözlerine?

Canım...Bir tanem...

İşte o âlemdedir asıl yaşamak

Heran Hakk''ın cemâline bakmak!

Bakıp bakıp mest eylemek kalbi!

Nice sevgili kulu le Allah''ın...

Hasret o yerlerde biter,

İnsan asıl O''na duymaz mı hasreti?

Bilirsin, ne sonsuzdur O''nun rahmeti!

Ananın şefkati, O''nunkinin yanında zerre..

Rahmet nazariyle tecelli etsin bir kere;

Ne dert kalır be de gam...

Anlatamam ömür boyu mest olup, sevinçten ağlasam..

O''nun rahmeti gazabından üstün!

Anlayacaksın O''na vardığın gün!

Hacer''im kulak ver Yunus''lar;

Doğruluğu onlarda gör ve ara;

''Zmana onlar beygir diye bierler,

Bu âlemde binip öbür âlemde inerler!''

Riyadan bucak  bucak kaçar ve sinerler!

Tasavvuf yolcusu o nûr erler,

Seni çağırıyorlar Hacer''im, seni...

Koş...Koş, ardına bakmadan koş!

O âlemde nûr ile olsana sarhoş,

Göz yaşında yaşamanın zevkine er!

Evliyalar gönül açmış seni beklerler!

Keşke bana da açılsa idi o gönüller...

Göz yaşı deryasında boğulurdum!

O erenlerin kapılarına köle olurdum!

Ey benim Hacer''im!

Sen kutlu kulsun ki, seni çağırıyorlar!

Ve geliyor Maverâ''dan bir nûrlu rüzgâr!

Bin o rüzgâra, git âlemin ötesine...

Kulak ver, seni çağıran nûr sesine!

O sesler, her saniye nûr ummanına dalmışlar!

O sesler, cennet suyu ile yıkanmışlar!

Ve yine nûr havlularıyla, zikirle durulanmışlar!

''Anlamıyorum Halil''im!'' deme,

Anlayacağın günler de gelecektir!

Bana anlatacağın günler de....

Ben, bir elçiyim, haber getirdim erenlerden!

Seni çağıran Muhammed-î(s.a.v.) yârenlerden!

Onlara katılacağın günün kutlu olsun...

Nûr ile dolacak gönlün, umutlu olsun!....

                                                   (1997-Tuzluca)', 'Benim nazlı yârim! Bir kulak dayasan, maverâdan ne sesler geliyor! Hacer''i çağıran nağmeler yükseliyor... Arş-ı âlâ''nın esrar yerine Hâlâ ya...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/davet-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-i-brahim-duman-2-qgc42', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgilim senden ayrıldıktan sonra

Üsküdar''dan vapura bindim

Martılara simit attım 

Oralı bile olmadılar

bana seni sordular, ''O nerede'' diye

''Gelecek merak etmeyin'' dedim

Açlıklarını senin atacağın 

Simitle gidereceklerini söylediler

Sevgilim senden ayrıldıktan sonra

Üsküdar''dan vapura bindim

Kız Kulesi''nin gözlerini gördüm

Boş kalan ellerimin üzerinde

Sana selam söyledi

ve 

en güzel manzarasını senin için ayırmış

Sevgilim senden ayrıldıktan sonra

Eminönü''nde vapurdan indim

Karıştım kalabalıkların arasına

Ama yüreğim kıpır kıpır

Omuzlarım dimdik', 'Sevgilim senden ayrıldıktan sonra Üsküdar''dan vapura bindim Martılara simit attım  Oralı bile olmadılar bana seni sordular, ''O nerede'' diye ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Duman 2']::text[], 8.5, '{"poet":"İbrahim Duman 2","poet_slug":"i-brahim-duman-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senden-sonra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıgın rengi', 'ayriligin-rengi-i-brahim-duman-2-75ew3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haseki''de durdu tramvay

Ve ben

Açılan kapının arkasında 

Ticari bir taksinin

Sarı renginde

Ayrılığı gördüm

Yusufpaşa''da açılan kapıdan

Sarmaş dolaş bir çift bindi

Kızın ellerinde kırmızı bir gül

Ve ben

O Kırmızı gül de sevgiyi gördüm

Laleli durağında ise

omuzları düşmüş

Yorgun bir Rus kadın bindi 

Ve ben

Yeşil gözlerinde çöküşü gördüm

Üniversite durağında

Anılarım tazelendi

Öğrenci İbrahim dalıverdi içeri

Henüz sararmamış dişleriyle

Beyazıt''a geldiğimizde

Ömrünü Gedikpaşa yokuşunun

yüksek eğiminde

yıllarını ayakkabı yaparak 

Geçiren nasırlı bir çift el ilişti gözlerime

Ve benim

Sessizliğin senfonisini

Gönül gözümü açarak dinlediğim

Huzura kanat çırptığım yer

Sultanahmet durağı...', 'Haseki''de durdu tramvay Ve ben Açılan kapının arkasında  Ticari bir taksinin Sarı renginde Ayrılığı gördüm Yusufpaşa''da açılan kapıdan Sarma...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Duman 2']::text[], 8.5, '{"poet":"İbrahim Duman 2","poet_slug":"i-brahim-duman-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ayriligin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceremdeki Gelecek...', 'penceremdeki-gelecek-halil-i-brahim-deveci-79g7i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelecği gösteren bir pencere;

Çerçeve; Segi, barış ve Hakk''a teslimiyetler,

camdan gözüken vahşetti birdenbire,

Bu Filistin''deki bir yer!

Güzelim çocukları, 

masum çocukların,

oynadığı sokaklardan, 

şimdi paramparça etlerle

akan kanlar

vardı!!!

Eskiden misket

oynayan çocukları,

eskiden bisiklet 

süren çocukları,

kucaklayan kanlı 

kaldırımlar

vardı!!!

Eskiden, sevgiden akardı

çocukların mavi gözlerinden yaş.

Eskiden, seven eller okşardı,

ondan gururluydu, bu küçük baş!

Şimdi penceremde çocukların

eski gururlu başlarına

kurşun denen nesneler dokunuyor

yine kurşunlar öldürüyor

arkadaşlarını!!!!!!

Çepeçevre kurşunlar sarmışken etrafını

mavi gözlü

sarı saçlı bir yetim çocuk

kurşunlar arasından

mavi gökyüzüne kitabı kaldırmış

bağırıyordu

güzel çocuk!!!

Kurşunlar sirkinde

masmavi gökyüzüne

uzanan kanlı ellerin

tuttuğu kitabın ismi;

''Yitik Hayaller Şehrinin Hayâl Şiirleri- Halil İbrahim''

dikkatlice baktığımda

anladım ki; Bu kitap

Halil İbrahimin Kudüs''e dair 

çilesini doldururken yazdığı şiirlerinin derlendiği

kitaptı...kitap...

Hayallerinde saklamıştı onu,

gelecekte şimdi onu

Filistin''li yetim çocuklar okuyordu

Ve şu türküyü söylüyorlardı

hep bir ağızdan

ölürken ÇOCUKLAR:

.......

''BIRAKALIM TÜFEKLERİ, BOMBALARI,

GÜLLERLE SEVİNDİRELİM ÇOCUKLARI!''

                                               (1986-Silifke)', 'Gelecği gösteren bir pencere; Çerçeve; Segi, barış ve Hakk''a teslimiyetler, camdan gözüken vahşetti birdenbire, Bu Filistin''deki bir yer! Gü...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/penceremdeki-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmez sanma', 'degismez-sanma-riza-aslan-n70ea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'değişmez sanma 

biter , geçer

unutulmaz sanma

unutulur.

nerede , nasıl olursan ol

kabulümdün ama ;

artık bekleme,

gelemem 

gelmem

20-12-2000', 'değişmez sanma  biter , geçer unutulmaz sanma unutulur. nerede , nasıl olursan ol kabulümdün ama ; artık bekleme, gelemem  gelmem 20-12-2000...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/degismez-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Nefsim-2-', 'ey-nefsim-2-bayram-tunca-bvqak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey nefsim, aynen mızmız çocuklar gibisin

Öğleye kadar hep feryad-ı figan ediyosun

Bakıyorsun ki. isteklerini cevap veren yok

Uykuya dalan çocuk misali ses sedan yok

Bak eğer ki bayrama kadar uslu durursan

Eğer bayramda da elimi öpmeye gelirsen

O an belki çıkolata falan ısmarlayabilirim

Hatta bel ki de bayram harçlığı da veririm

B. TUNCA/14.12.2000-11.05', 'Ey nefsim, aynen mızmız çocuklar gibisin Öğleye kadar hep feryad-ı figan ediyosun Bakıyorsun ki. isteklerini cevap veren yok Uykuya dalan ço...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ey-nefsim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-arif-karakum-uod4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatımdaki son kadına...

Yine sensiz bir gece daha başladı,

Yine yatağım sensiz ve soğuk,

Yine kollarım hayalini kucaklıyor,

Yine mahkumum  karanlığına gecenin,

Yine üşüyorum sıcacık odamda.

KAHRETSİN.......

Neden yoksun yanlız gecelerimde

Neden yoksun güzel günlerimde

Neden kapkara geceler mehtapsız

Neden günler bulutlu puslu

Neden sadece içimde,hayalimdesin

LANET OLSUN YOKSUN......

Ruhumu dalgaların beyaz köpüklerine, 

Sevgimi ak güvercin kanatlarına,

Yüreğimi kırmızı gül yapraklarına, 

Bedenimide kasırgalara yükledim. 

Sana ulaşabilmek uğruna.

Aslında biliyormusun bi tanem

Sana ait’im seninim vede 

SENİ SEVİYORUM', 'Hayatımdaki son kadına... Yine sensiz bir gece daha başladı, Yine yatağım sensiz ve soğuk, Yine kollarım hayalini kucaklıyor, Yine mahkumum ...', ARRAY['Türk Edebiyatı','Şiir','Arif Karakum']::text[], 8.5, '{"poet":"Arif Karakum","poet_slug":"arif-karakum","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seviyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burdayım Sözümde', 'burdayim-sozumde-ahmet-telli-rtvoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...Düşüyorum

Karıncanın peşine minik depremler oluyor

Yabanıl ot kokuları,sonra düşler,düşüyorum...

Puslu bir görüntü tarih dediğimiz ve kirli

Sular buharlaşıyor buluşalım dediğin denizde

Burdayım sözümde,yanlışsa da bu istasyon

Bir ben yitirmedim galiba belleğimi bir de

Şiir yazanlar, ne kadardılar ve nerdeydiler

Hatıralar üretiyorum telgraf tellerinden

Akşamüstleri fesleğenleri suluyorum

Bekle demiyorum kimseye,unutma demiyorum

Acı soysuzlaşınca tiranlaşıyor belleksizlik

İnat ve öfke,kaybediş ve kayboluş oluyoruz

Komikti dıştan bakınca dünya ama hırçın

Ayışığı,telgraf direkleri ve fesleğenler

Burdayız işte durgun bir sessizlikteyiz şimdi

Unutulan bir şey kaldı mı diye soruyor tiran

Kampana çalarken çöldeyiz o geniş çevrende

Mısır''ı soyun diyordu Musa belleksizdir firavun

Babil ve burası iki istasyon iki uzak nokta

Belki bir imgede düzlem olabilen iki grilik

Düşler ve tarih inilecek son istasyon

Burdayım işte güzel bir yanlıştayım şimdi

Beklemesini bilmiyor acalesi olan ve nedense

Çekip gidiyorlar, kalanlar o kadar azız ki

O kadar azız ki mutluluk bile bizden çok', '...Düşüyorum Karıncanın peşine minik depremler oluyor Yabanıl ot kokuları,sonra düşler,düşüyorum... Puslu bir görüntü tarih dediğimiz ve kir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/burdayim-sozumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karda İzler', 'karda-i-zler-ahmet-telli-5guyl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karda izler bırakıyorum avcılar peşime düşsün

Bir uçurum kıyısında vursunlar beni ki dünya

Uğuldayıp duran bir uçurum değil miydi zaten

Karda izler bırakıyorum avcılar peşime düşsün

Adımı yazıyorum kar üstüne ve ıslığını çığlık

Gibi incelterek yetişiyor ardımdaki tipi bana

Siliyor adımı bir dal kırarak çam ormanından

Geçmişim kar sessizliğiyle özetleniyor artık

Anılarım buz tutmuştur aşklarım kar yangını

Ömrüm parmak uçlarımda eriyen bir kar tanesi

Karda izler bırakıyorum avcılar peşime düşsün

Kar yağıyorken milyon bekerel hüzün yağıyordur

Derim ki kar ve hüzün bir aşkın seyir defteridir

Yolculuklar ve ayrılıklarla anlatılabilir ancak

Karda izler bırakıyorum avcılar peşime düşsün

Bir uçurum kıyısında vursunlar beni, vursunlar

Bir kahkahayla çekip giderim karlı ovalardan

Şairler vurulmalıdır, hayat yakışmıyor onlara', 'Karda izler bırakıyorum avcılar peşime düşsün Bir uçurum kıyısında vursunlar beni ki dünya Uğuldayıp duran bir uçurum değil miydi zaten Kard...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karda-izler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidim', 'yigidim-mustafa-nomal-ui89r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elbet yiğidim bir gün sende haykıracaksın;

Güneş''e hasret çiçek,

Su''ya hasret toprak gibi,

Elbet yiğidim bir gün sende haykıracaksın!..

Elbet yiğidim bir gün sende ağlayacaksın;

Uzun ve soğuk gecelerde,

Sırtını örten bir ana eli görmediğinde,

Elbet yiğidim birgün sende ağlayacaksın!..

Elbet yiğidim bir gün sende seveceksin;

Tüm özlemlerini,hayallerini,umutlarını,

Onda bularak,

Elbet yiğidim bir gün sendeseveceksin!..', 'Elbet yiğidim bir gün sende haykıracaksın; Güneş''e hasret çiçek, Su''ya hasret toprak gibi, Elbet yiğidim bir gün sende haykıracaksın!.. Elbe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nomal']::text[], 8.5, '{"poet":"Mustafa Nomal","poet_slug":"mustafa-nomal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yigidim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer!...', 'eger-osman-celik-2-76j7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer!....

Birgün düşerse yolun ayrılığa

Yaklaşma, kötürüm kollarıma.

Gülmesin gözlerin öyle yüzüme,

Koşmak istercesine yanıma.

Ben, yalnızlığı bir yudum bardakta içtim.

Hasretini yüreğime, resmimi toprağa gömdüm.

Gözyaşlarımı gönlüme, kanımı aşkıma akıttım...

Birgün düşerse yolun yalnızlığa,

Acılar benimdir, yaklaşma bana,

Umutların, ümitlerin acımda erir sonra,

Ben yalnızlığı bir yudum bardakta içtim.

Hasretini yüreğime, resmimi toprağa gömdüm.

Gözyaşlarımı gönlüme, kanımı aşkıma akıttım...

Birgün düşerse yolun yalnızlığa

Bilki ben; yalnızlığın tohumunu senden aldım

Ayrılığın meyvasını sendetopladım

Umursamazlığın onurunu kendimde buldum

Ben yalnızlığı bir yudum bardakta içtim

Hasretini yüreğime, resmimi toprağa gömdüm

Gözyaşlarımı gönlüme, kanımı aşkıma akıttım...', 'Eğer!.... Birgün düşerse yolun ayrılığa Yaklaşma, kötürüm kollarıma. Gülmesin gözlerin öyle yüzüme, Koşmak istercesine yanıma. Ben, yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Osman Çelik 2']::text[], 8.5, '{"poet":"Osman Çelik 2","poet_slug":"osman-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eger-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliğin Uzaklığı', 'diriligin-uzakligi-halil-i-brahim-deveci-t1y9x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine göz yaşı göründü

Uzun ve ıssız gecelerin

Bağrında gecelerin... 

Çağlayıp geliyor

Hayal hayâl.... 

Çağlayan olup bir damlada

Ağlayıp geliyor...

Hayal hayâl....

Kim bilir sen hangi gülmedesin

Kim bilir?

Hangi kahkahanın göbeğindesin...

Çoktan unuttun değil mi?

Hatıralarımızın rüya yeleli hayallerini

Kabrini bile kazmadan

Attın maziye

Dünümüzü...

Söylesene Hacer ;

Sen vicdansız mısın?

Böylesine 

Ölgün müydü?

Atimize verdiğin değer

Böylesine alçak olur mu?

Zamanımı baltalayan sevgililer...

Aşk asırlarını ayırdın

Zalimce

Son bakışında

''bakmakta, görmeyi idam ettin

görmekte, sükutu evrensel kıldın!''...

Kirpiklerine hedef tuttun

Varoluş gayemin vahasında

Sana susamışlığımı...

Cenderesine hapsettin

Hülyalarımı

Karanlığın göz yaşı bulutuna

Ismarladın

Sana dair

Umutlarımın katarını

Saman yolumu geceme yıktın

Yıldızsız bıraktın

Sensizliğimi...

Ufuklarımı gasp ettin

Güneşim gözükmüyor artık...

Her zaman 

kaçtığım gölgeme bile

hasret koydun Hacer!

Kavgaya tutuşturdun

Canımla-tenimi

Ruhumla-bedenimi

Yaya bıraktın

Olmakla-ölmek arasında

Varlığımı...

Susuz çöller gibi...

Zamansız bıraktın

Sendeyken

Sana hasretliğimi...

Şimdi ben,

Hangi yıldızsız gecede

Karanlığın bekçisi olacağım

Hükümranlığına kadar

Güneşin!...

Sen, mum ışıklarına kaçtın

Beni yıldızsızlığa hapsedip

Alsaydın canımı

Giderken...

Bıraksaydın

Bedenimi...

Sensizliğin feza boşluğuna

İnan;

Bu kadar sancılanmazdım

''canım,

canınla sağ olsun!''

derdim:

'' Ölmek,

seninle

olmamaksa eğer yaşam

sensizlikte güzel olur,

Ölmek!''

Ama olmadı

Canımı bile titrettin

Cansızlığın sensiz karanlığında

Hasret hiç böyle zulüm olmamıştır!

''Olmamıştır

hasret

hiç böyle

 zulüm!

Sen de

Böylesine

 Zalim!

Kıyametten önce

Ve sonra...

'' Ölümün yakınlığı değil midir,

Sendeki

Diriliğin uzaklığı!''

               (1999', 'Yine göz yaşı göründü Uzun ve ıssız gecelerin Bağrında gecelerin...  Çağlayıp geliyor Hayal hayâl....  Çağlayan olup bir damlada Ağlayıp gel...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/diriligin-uzakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüm-1+', 'dustum-1-bayram-tunca-hat0v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlkin meleğin eline güçtüm

Sonra feleğin eline düştüm

Daha sonra da zalim beşerin eline düştüm

Evvel bir güçtüm, şimdi ele ayağa düştüm

Önce ana kucağına düştüm

Sonra baba ocağına düştüm

Daha sonra, İzmir’de asker ocağına düştüm

Evvelin bir güçtüm, şimdi ele ayağa düştüm

Önce Yörük çadırına düştüm

Sonra Kula Ortaköy’e düştüm

Daha sonra da ülkede sayısız şehre düştüm

Eskiden bir güçtüm şimdi ele ayağa düştüm

Önce gurbet ellere düştüm

Sonra vefasız dosta düştüm

Ahirinde, merhametsiz bir sevgiliye düştüm

Eskiden bir güçtüm şimdi ele ayağa düştüm

Önce gözden düştüm

Sora gönülden düştüm

Daha sonra da tüm dostun dilinden düştüm

Eskiden bir güçtüm şimdi ele ayağa düştüm

Önce dizden düştüm

Sonra güçten düştüm

Daha sonra da çelmelere takılarak sürçtüm

Eskiden bir güçtüm şimdi ele ayağa düştüm

Önce karaya düştüm

Sonra saraya düştüm

En sonunda çileme yenilerek mezara düştüm

Eskiden bir güçtüm, şimdi ele ayağa düştüm

Bayram der, her beşer az veya çok şaşar

Kimi düşerek, kimi de düşmeyerek yaşar

Ama her âdemoğlu eninde sonunda düşer

Hiç düşmeyen, en son Azrail’in eline düşer

Nice âlimler ve zalimler vardı, hepsi de düştü

Nice nebiler ve veliler vardı, onlar dahi göçtü

Nice güçlü insanlar vardı, bir bir onlar da düştü

Bütün bunları düşüren güç, ne büyük bir güçtü

27.11.2000-10:20

''Aşk Ateşten Gömlek''', 'İlkin meleğin eline güçtüm Sonra feleğin eline düştüm Daha sonra da zalim beşerin eline düştüm Evvel bir güçtüm, şimdi ele ayağa düştüm Önce...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dustum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınır', 'sinir-guray-unal-omt2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yitirilmiş zaman artıklığı

bataklıklardan  yayılan.. 

Ölü gözlerle izlenmiş ölgün siluetler

iç içe geçmiş, 

içlerin içi geçmiş.

yokluğun sarmaladığı

hiçliği

şimdi kaybolma zamanı

boyalı simaların

lanetinden..', 'Yitirilmiş zaman artıklığı bataklıklardan  yayılan..  Ölü gözlerle izlenmiş ölgün siluetler iç içe geçmiş,  içlerin içi geçmiş. yokluğun sar...', ARRAY['Türk Edebiyatı','Şiir','Güray Ünal']::text[], 8.5, '{"poet":"Güray Ünal","poet_slug":"guray-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Aşkı Keşfedelim', 'gel-aski-kesfedelim-fatih-tuzun-djliv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendini boşu boşuna zorlama

Düşeceksin yollarıma

Göreceksin sen gerçeği

Geleceksin kollarıma

Geçti gider yıllar yazık

Ardında derin izler bırakıp

Unuturum geçmişi,durdurum zamanı,dağatırım heryanı 

Yeterki gel bana

Yeterki gel bana

Gel aşkı keşfedelim seninle

Bir kibrit çak geçmişe

Uzat elini ver kalbini

Gönlüm dolsun sevginle

Gel aşkı keşfedelim seninle

Mutlu günler önümüzde

Uzat elini ver kalbini

Gönlüm dolsun sevginle', 'Kendini boşu boşuna zorlama Düşeceksin yollarıma Göreceksin sen gerçeği Geleceksin kollarıma Geçti gider yıllar yazık Ardında derin izler bı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gel-aski-kesfedelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Vakitler', 'dar-vakitler-nevzat-gurmen-yz53r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dar vakitlere sığdırma beni 

O vakitler bol olduğunda gel.

Zordur bir insanın bir insanı 

Bu dar vakitlerde anlaması.

Saklı yüreğe sığdırma beni 

O yürek tam açıldığında gel.

Hiç kolay değildir bir yüreğin

Öyle kendi kendine ermesi.

Kör karanlığa sığdırma beni 

O aydınlığa çıktığında gel.

Zor olan gecenin aydınlığı

Şu gündüzün aydınlığı ne ki.

Vefasız günlere sığdırma beni

O yalnız günün dostluğunda gel.

Dosttur hep insanlar çoğu zaman 

Nasılsa sen yalnız kalana dek

Zorlama kendini benden uzak

Bu göçmen kuşlar gidecek güzün.

Erguvanlarsa açar bahara;

Gerçeği görene dek dur, bekle

Ben burada olmayabilirim

Gitmesini bilmek te bir erdem.

Ama emin ol göreceğimden

Senin yüreğinin erdiğini.

Ve işte silkinip atacaksın,

Gerçek yalnızlığını o zaman.', 'Dar vakitlere sığdırma beni  O vakitler bol olduğunda gel. Zordur bir insanın bir insanı  Bu dar vakitlerde anlaması. Saklı yüreğe sığdırma ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dar-vakitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söndü Lambaları....', 'sondu-lambalari-halil-i-brahim-deveci-e92id', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gittin, söndü, 

Tüm lambaları gündüzün...

Karanlığa büründü yarınlar

Gözler görmüyor aşkı 

Ve de yarınları....

Umut kuşları terk etti yurdu

Yurtta yurtluktan çıktı

Kurt oldu gönlümde

Benliğimi kemirdi

Kalmadı aşkın ümidi

Kalmadı yarınlarımın gereği

Şimdi bir zalim elinde çaresizim

Kimsesizim kalabalıklarda

Yalnız ve yorgunum

Ayrıca durgunum

Kime gitsem

Kime dert yansam

Bunu da bilmiyorum

Bilmiyorum artık;

Dün ne

Bugün nedir

Yarın ne olabilir?

Gerçi umurumda da değil

Sensiz dün

Sensiz bugün

Sensiz yarın

Sensiz yarın mı olurmuş ki?

Benim değil başkalarının olsun 

Eğer varsa dün,bugün ve yarın sensiz

İstemiyorum...

''ne güzeldi değil mi?

Sevmek 

Sevilmek

Ve de sevmekte yaşamak

Hayatı; 

Dünü

Bugünü

Yarını...

Bir anlamı vardı yaşamanın

Senin için özlerdim hayatı

Senin için verirdim verdiğim nefesi

Bilirdim ki,

Verdiğim nefes fotosentezden sonra dolacak

Senin ciğerlerine...

Ve senindir diye alırdım aldığım nefesi...

NEREESİN EY SEVGİLİ?

Karardı gündüz ve geceyi doğurdu yine,

Neredesin ey sevgili, gelmedin hâlâ?

Geri mi döndüm yaksa kaybettiğin mazine?

Neredesin ey sevgili, gelmedin hâlâ?

                                            (2000-Akseki)', 'Sen gittin, söndü,  Tüm lambaları gündüzün... Karanlığa büründü yarınlar Gözler görmüyor aşkı  Ve de yarınları.... Umut kuşları terk etti yu...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sondu-lambalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Dünyada....', 'ah-su-dunyada-halil-i-brahim-deveci-6z1yi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah şu dünya

Ah şu dünyada neler yaşamadım ki;

Önce soran olmadı

doğmak ister misin diye

sonra ister misin demediler 

çocukluğunu yaşamak 

yaşatmadılar çocukluğunu

görmedim ömrümde 

annemin sevgiyle buğulamnan gözlerini

hele babamı hiç tanımadım

onun beni azarlamasına karşın

herşey herkes yabancıydı

ıssızlıktaki yalnızlığımda

bu nasıl bir dünyaydı

bu nasıl bir yaşamdı?

Anlayamadım

Saçlarım bir kez okşanmadı

Ağladığımda silen olmadı

Sevgiye hasret döktüğüm göz yaşlarımı

Hep ben ağladım

Ve hep ben sildim göz yaşlarımı

Ne dünyalar vardı

Her bir damla gözyaşımda

Umutlarım beklentilerim

Sevgiye hasret özlemlerim

Vardı...vardı lakin hiçbir olmnadı

Olmadı yaşamak bende benliğimde

Yaşaadım ben

Ben;

Sevgisizliğe yaşamak demem

Sandılar ki;

Karnı doyurulunca

Bir çocuğun

Kıçına bir don giydirilince

Yapılırdı babalık

Analık

Kardaşlık

Bilmezler ki

Ben aç 

Susuz

Ve de donsuz gezebilirim

Ama sevgisiz asla

Ben bir çocuktu

Mayamda tanrının sevgisi vardı

Lakin tanrının bana verdiği

Sevgiyi çok gördüler bana

Tanrının aksine

Zalimdir bu insanlar

Ve zaman böyle geçti

Ve de mekan beni böyle tüketti

Ve de nin ve si;

İnsanlar beni böyle bunalıma itti...

Günün birinde

Tanrıya inancım doruğa ulaştı

Benliğimde hissettim O''nu

Şah damarımdan daha yakındı bana

Ve bir gün bir güzeli sevdim 

Sevmek ne kelime

Şah damarım sandım onu

Tanrıya benden daha yakın

Şah damarım sandım onu

Ve sandım ki

Şah damarımı seversem tanrı beni alır bu alemden

Ve olan oldu

O zalim güzel benden şah damarımı aldı

Kaldım orta yerde şahdamarsız

Ve tanrısız!

O zalimin adı;

Silifke''li HACER!(2000)', 'Ah şu dünya Ah şu dünyada neler yaşamadım ki; Önce soran olmadı doğmak ister misin diye sonra ister misin demediler  çocukluğunu yaşamak  ya...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/ah-su-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu', 'duygu-murat-soysal-sf4eg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatılamamış duygular var senden bana kalan...

Dağlar kadar yüce,

sevmek kadar asil...

Bir de söylenememiş sözcükler

Ağızlarda yarım kalan...

Seni duymak kadar güzel,

Senin olmak kadar özel...', 'Anlatılamamış duygular var senden bana kalan... Dağlar kadar yüce, sevmek kadar asil... Bir de söylenememiş sözcükler Ağızlarda yarım kalan....', ARRAY['Türk Edebiyatı','Şiir','Murat Soysal']::text[], 8.5, '{"poet":"Murat Soysal","poet_slug":"murat-soysal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duygu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıltı', 'yanilti-ayse-unal-ki7wy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duy yüreğini dostum;

bir  şelale değilse gürültüyle kapına gelen,

aşktır, bilesin...', 'Duy yüreğini dostum; bir  şelale değilse gürültüyle kapına gelen, aşktır, bilesin......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Ünal']::text[], 8.5, '{"poet":"Ayşe Ünal","poet_slug":"ayse-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yanilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-hami-fiskeci-n7qrf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alpaslan ile değişti tarihin.

Geldi akın akın, Türk milleti.

Önünde duramadı ordular,kaleler.

Önce donattılar dört bir tarafını,

Tarih boyu silinmeyecek eserlerle.

Aş oldun,katık oldun,su oldun,ev oldun,

yurt oldun Türk milletine ve olmaya devam edeceksin.

Benim güzel ve aziz Anadolu''m.', 'Alpaslan ile değişti tarihin. Geldi akın akın, Türk milleti. Önünde duramadı ordular,kaleler. Önce donattılar dört bir tarafını, Tarih boyu ...', ARRAY['Türk Edebiyatı','Şiir','Hami Fiskeci']::text[], 8.5, '{"poet":"Hami Fiskeci","poet_slug":"hami-fiskeci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anadolu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-sair-bien-56f3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geri dönüp arkana bakma,

Baktığında da sadece gülümse,

Ne kadar güzel anlar geçirmiş olduğun....

Günleri hatırlayarak.', 'Geri dönüp arkana bakma, Baktığında da sadece gülümse, Ne kadar güzel anlar geçirmiş olduğun.... Günleri hatırlayarak....', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulumse-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çayın Tadı', 'cayin-tadi-serkan-yildirimturk-2ljqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oturuyorum bir çay bahçesinde,

Uzun kavak ağaçlarının altında,

Gölgede, hasır minyatür sandalyenin üstünde.

Türkiyemin özlemi ile.

Burası Kadıköy iskelesi; martıların sesi ile,

Denizin kokusu ile,

Vapurların sesi ile,

Özlüyorum ülkemi yine.

Bakıyorum ısmarladığım çayın tadına?

Bir meltem eser püfür püfür o sıcak havada,

Gözlerimi kapatıp, içimi çekerim,

İstediklerim belki hepsi düş olsada.

Varamam o çayın tadına,

Baktıkça insanların yüzüne,

Düşünürüm nedir dertleri diye,

Mesut olsun, dertli olsun ama onurlu olsun.

Nedir hayat dediğimiz şurda,

İçtiğim çayın tadıyla,

Yok olur gider zamanla,

Benim özlemim gibi, zamanla?', 'Oturuyorum bir çay bahçesinde, Uzun kavak ağaçlarının altında, Gölgede, hasır minyatür sandalyenin üstünde. Türkiyemin özlemi ile. Burası Ka...', ARRAY['Türk Edebiyatı','Şiir','Serkan Yıldırımtürk']::text[], 8.5, '{"poet":"Serkan Yıldırımtürk","poet_slug":"serkan-yildirimturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cayin-tadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Günleri', 'sevda-gunleri-bunyamin-kepez-lxkc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünürüm karanlığa kendimi bırakınca

Beraber olduğumuz sevda günlerini

Düşünürüm dertler beni boğarcasına yıpratırken

El ele gezdiğimiz sevda günlerini

Hatırlarmısın sevgilim sevda günlerini

Çocuklar gibi gezip dolaştığımız sokakları

İki sevgiliye bakıp yürüğimin karadığı

O günlerdi GÜLÜM sevda günleri

Ayrılık olur diye korkardık başları 

Leyla ve mecnun gibiydik sonraları

Taki beni sana unutturana kadar 

Birbirimizi candan seven iki sevgiliydik

İte bu yüzden ararım sevda günlerini

Anladınmı GÜLÜM...!', 'Düşünürüm karanlığa kendimi bırakınca Beraber olduğumuz sevda günlerini Düşünürüm dertler beni boğarcasına yıpratırken El ele gezdiğimiz sev...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Kepez']::text[], 8.5, '{"poet":"Bünyamin Kepez","poet_slug":"bunyamin-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevda-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Devrim...', 'en-buyuk-devrim-halil-i-brahim-deveci-qne9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mü''mindeki ses:

''Yaşasın sevgi!

Yaşasın Hakk''a teslimiyet!

Yaşasın insanca hürriyet!

Yaşasın İslâmiyet!

Örümcek kafalıdaki ses:

''Şu mü''min''in, şu mü''min''in...

Sık kafasına bir kaç kurşun

Al, intikamını üç-beş kuruşun!

                                    (1988)', 'Mü''mindeki ses: ''Yaşasın sevgi! Yaşasın Hakk''a teslimiyet! Yaşasın insanca hürriyet! Yaşasın İslâmiyet! Örümcek kafalıdaki ses: ''Şu mü''min''i...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/en-buyuk-devrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-halil-i-brahim-deveci-ppev0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günah deryasına dalar insanlar,

Nefse selam verdikleri anlarda.

Küfre götürür insanı yalanlar,

Boşluğa düştükleri zamanlarda.

Zerre zerre küfrün çocuğu olur,

Peş-peşe söylediği yalanlarda.

Her türlü çareyi küfürde bulur,

Kurtuluş bilinen, o ummanlarda.(1996)', 'Günah deryasına dalar insanlar, Nefse selam verdikleri anlarda. Küfre götürür insanı yalanlar, Boşluğa düştükleri zamanlarda. Zerre zerre kü...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insanlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünüm', 'gorunum-halil-i-brahim-deveci-2mmvc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Genci, yaşlısı çırıl-çıplak, hep curcuna,

Yaşamlar, sanki desenli bir muşamba.

Hiç olmazsa muşambada ölçü belli,

İnsanların ölçüsü kalmamış temelli.(1988)', 'Genci, yaşlısı çırıl-çıplak, hep curcuna, Yaşamlar, sanki desenli bir muşamba. Hiç olmazsa muşambada ölçü belli, İnsanların ölçüsü kalmamış ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gorunum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zikirde İş...', 'zikirde-i-s-halil-i-brahim-deveci-yaygu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zikirde iş; yalanı bile hakka çevirmek,

Bu hale gelene dek zikir, zikir devirmek!(1996)', 'Zikirde iş; yalanı bile hakka çevirmek, Bu hale gelene dek zikir, zikir devirmek!(1996)...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/zikirde-is-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaip Nesil...', 'acaip-nesil-halil-i-brahim-deveci-4eamz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onları gör, hayattan bık ve yaşamdan kesil,

İşte size, yeni gelen, acaip bir nesil;

Anasına binip, babasıyla evlenenler,

Şu devler arasında cüceyken devlenenler.

Zaman utanıyor onlar ile geçmekten,

Onlarsa utanmadı küfrü, şerri şeçmekten,

Kesilse boyunları oluk olûk şer akar,

Biri çırıl-çıplak gezer, binlercesi bakar!

Ey şanlı(!) meydana getirdiğin eserine bak,

Kabrinde huzurluysan kına vereyim de yak,

Medeni nesil anasını düzerken geliyor şafak,

Belletiğin şeyleri sayıklıyorlar; .M, G.T, Y......k!(1996)', 'Onları gör, hayattan bık ve yaşamdan kesil, İşte size, yeni gelen, acaip bir nesil; Anasına binip, babasıyla evlenenler, Şu devler arasında ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acaip-nesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken', 'beklerken-sair-bien-6mr0c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aradım kimseyi bulamadım

Bulunmadığım yerde arandım

Arandığımda kuşkulandım

Kimse aramadı beni.

Şarap

Düşünmeye başladım

Düşümde sen vardın

Vardığınyere bir göz attım

gözümden yaş çıktı

Çıktığın yere bastım

Bastığım yer kaydı

Kaydığınm yerde bekliyorum

Belki gelecek

Deve genuine taste

Gelmeyecek

Ben mi geç geldim

Peşinden geçmişi

Geçmişimde gelecek

Gelmeyecek', 'Aradım kimseyi bulamadım Bulunmadığım yerde arandım Arandığımda kuşkulandım Kimse aramadı beni. Şarap Düşünmeye başladım Düşümde sen vardın ...', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Sesleniyorum', 'sana-sesleniyorum-sair-bien-ydpgy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki ışık ısıtıyor beni

Her akşam yatağıma girdiğimde

Yanlızlığım dağılıyor

Sorunlarım çözülüyor

Sana seslendiğimde

Biliyorum , hissediyorum o gün gelecek

Sana sevgimi daha çok gösterecek

Seninle daha çok konuşacak ve paylaşacağım.....', 'İçimdeki ışık ısıtıyor beni Her akşam yatağıma girdiğimde Yanlızlığım dağılıyor Sorunlarım çözülüyor Sana seslendiğimde Biliyorum , hissediy...', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-sesleniyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Demeli', 'ne-demeli-sair-bien-zy7r0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimler geçiyor

İnsanlar soluyur

İnsanlar soruyorlar

Ne demeli?

Ne terliyor, ne üşüyor 

Gözlerim', 'Mevsimler geçiyor İnsanlar soluyur İnsanlar soruyorlar Ne demeli? Ne terliyor, ne üşüyor  Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Şair Bien']::text[], 8.5, '{"poet":"Şair Bien","poet_slug":"sair-bien","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ne-demeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dev Şarkısı', 'dev-sarkisi-emin-bulent-serdaroglu-fn3gx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TÜRKÜM ben...                                                                

         Oğuz nesli benim nesli vakurum...                                    

         Altaylar''a bağlar beni alnımdaki nurum..

Parlak güneşin doğduğu yerlerde doğan ben,

İlk ateşi içtimdi bir ARSLAN memesinden..

Şahin gibi cenk atları kişnerken uyandım..

Ejder gibi kaplanları boğdum oyalandım..

Yalçın döşeğim vardı küheylan yelesinden,

Aldımdı bu sert ismimi gök gürlemesinden..

TÜRKÜM ben...                                                                

        Oğuz nesli benim nesli vakurum..                                      

        Altaylar''a bağlar beni alnımdaki nurum..

(Vatan şairi ve Galatasaray Spor Kulübünün 

2 numaralı kurucusu...)', 'TÜRKÜM ben...                                                                          Oğuz nesli benim nesli vakurum...                    ...', ARRAY['Türk Edebiyatı','Şiir','Emin Bülent Serdaroğlu']::text[], 8.5, '{"poet":"Emin Bülent Serdaroğlu","poet_slug":"emin-bulent-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dev-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KiN', 'kin-emin-bulent-serdaroglu-l89b2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göster sema-yi mağribe yüksel de alnını ,

Dök kalb-i saf-ı millete feyz-i beyanını !

Al bayrağınla çık,yürü sağken zafer nüma ,

Bir gün şehit olunca sen , olsun kefen sana !

Ey makber-i muazzam-ı ecdadı titreten ,

Düşman sadası,sus, yine yükselme gölgeden !

Kafir ! Hilal-i rayet-i İSLAM'' a hürmet et ,

Toplar boğar hitabını dağlarda akibet..!

Dağlar lisana gelse de anlatsa hepsini ,

Binlerce can dirilse de nakletse geçmişini !

Garbın cebin-i zalimi affetmedim seni ,

TÜRK''üm ve düşmanın sana kalsam da bir kişi..!

Ben şurezar-ı kalbimi kinimle süslerim ,

Kalbimde bir silah ile ferdayı beklerim .

Kabrinde müsterih uyu ey namdar atam !

Evladının bugünkü adı sade intikam..!

(Vatan Sairi ve Galatasaray Spor Kulubu 2 Numarali Kurucusu)', 'Göster sema-yi mağribe yüksel de alnını , Dök kalb-i saf-ı millete feyz-i beyanını ! Al bayrağınla çık,yürü sağken zafer nüma , Bir gün şehi...', ARRAY['Türk Edebiyatı','Şiir','Emin Bülent Serdaroğlu']::text[], 8.5, '{"poet":"Emin Bülent Serdaroğlu","poet_slug":"emin-bulent-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-fatih-tuzun-skitn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün gelir ah sende terk edermisin beni

Bırakırmısın bu dünyada yanlız başıma

Düşünme dersin,düşünmemek eldemi

Bilemezsin seni ne çok sevdiğimi

Gökyüzünde yıldızları seyreder gibi

Yağmurda çılgınca dans eder gibi

Mecnun`un  Leyla`ya  olan aşkı gibi

Sırılsıklam aşığım sana of   sırılsıklam aşığım sana

Sensiz bir gün azap ızdırap gibi

Kanatsız bir kuş misali

Sensizlik artık zor geliyor bana

Sırılsıklam  aşığım sana oof  sırılsıklam aşığım sana', 'Gün gelir ah sende terk edermisin beni Bırakırmısın bu dünyada yanlız başıma Düşünme dersin,düşünmemek eldemi Bilemezsin seni ne çok sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asigim-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Sevgilim', 'gidiyorum-sevgilim-emrah-binici-xj07u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir operasyon var bu gece 

Yüksek ovaya Şemdinli ye

Gidiyorum ıssız mayınlı yollarda 

Sanki zirvede sen varsın

Açmışsın kollarını işte burdayım koş sevgilim koş diyorsun

Koşuyorum yorulmak nedir bilmiyorum

Ama seni bulamıyorum, seni bulamıyorum

Yine bir operasyon var bu gece

İsmim okunuyor beni çağırıyorlar

Gel silahın başına Emrah diyorlar

Sanki onlar değilde sen çağırıyorsun beni

Bir silahım, bir de sen varsın yanımda

İkinizde can dostum, hayat arkadaşım, tek namusumsunuz

Bir tek güvendiğim, sır verdiğim, dert ortağımsınız

Yine bir operasyon var bu gece dinazor sırtına

Gidiyorum gecenin alaca karanlığında

Beni çağırıyorsun işte burdayım diyorsun

Geliyorum ama bulamıyorum, bulamıyorum

Bir haber geliyor kavga tepesi basıldı diye

Hemen apar topar hazırlanıp çıkıyoruz

Birden çatışmanın ortasında buluyorum kendimi 

Kafamın üstünden geçen mermiler sanki sanki o şarkımızı çalıyor

Yine bir operasyon var bu gece, yine belalı gündek vadisine

Gidipte dönmeyenlerin, dönüpte gidipte  istenmeyen bir yere

Gidiyoruz ama nereye söylemiyorlar

Belki döneriz, belki dönmeyiz diye adresimizi alıyorlar

Sonra söylüyorlar gideceğimiz yer ta Irak sınırında

Her zaman beraberdik sevgilim hakkını helal et

Tekbir getirip dualar et

Gidiyoruz bu gece bilinmeyen yere

Bir marşımız vardı hep beraber onu söylüyoruz

Biz dağların garip yolcuları, bin gider, bin geliriz

Toprakta yatar toprak kokarız

Yatağımız toprak, yorganımız yaprak, yastığımız ise taşlar

Biz gökteki kayan yıldızlar

Bir gün buraya, yarın başka bir yere kayarız 

Bir gün olur öbür tarafa kayar gideriz.

Biz sosyete jandarması değiliz

Her ne kadar lüks yerlerde yaşamasakta

Her arazi şartında Apocularla dans etmesini iyi biliriz

Sana bir mektup bırakıyorum ve seni Allah''a emanet ediyorum

Canım diye başlayan seni seviyorum diye süren

Bir gün döneceğim diye biten,

Dönemezsem hakkını helal  et diye son bulan bir mektup

Zarfın içine birde mendil bırakıyorum

Seni düşünürken gözyaşlarımı sildiğim

Sırrımı verdiğim,sana olan duygularımı dile getiren bir mektup

Gidiyorum o meçhul yere

Bir an gözümün önünde sen

O beyaz gelinliğin içinde kollarını açmış beni çağırıyorsun

Sana bir mektup bırakıyorum sevgilim

Sevgimin ebedi olduğu,ben ölürsem sevgimin ölmeyeceği

İki satır bir mektup bırakıyorum

Bir gün şehit olursam şayet 

o beyaz gelinliği kapat üzerime diyorum

Soldurma üstümde açan gülleri

Esirgeme dualarını sevgilim diyorum

Sakın üstüme kapanıp ağlama sevgilim

Ela gözlerinden gözyaşların akmasın

Senden tek bir şey istiyorum

Tek bir şey..

Beni unutma sevgilim Evet gidiyorum;şimdi gidiyorum

Bu sefer eller üstünde

Tekbir Allahuekber sesleriyle

Gidiyorum o meçhul yere

Bilinmeyen sırlarım ile

Göğsümde kör bir kurşun,elimde silahım ile

Gidiyor olsamda dönmemek üzere 

Seni her zaman sevdiğimi unutma sevgilim;

Unutma diyorum.', 'Yine bir operasyon var bu gece  Yüksek ovaya Şemdinli ye Gidiyorum ıssız mayınlı yollarda  Sanki zirvede sen varsın Açmışsın kollarını işte ...', ARRAY['Türk Edebiyatı','Şiir','Emrah Binici']::text[], 8.5, '{"poet":"Emrah Binici","poet_slug":"emrah-binici","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/gidiyorum-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz mı?', 'olmaz-mi-fatih-tuzun-eq49j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bilsen bebeğim neler geçiyor aklımdan

Sensin tek sebebim uğruna eridiğim

Hırçın düşünceler kuşatmış tüm çevremi

Bedenim alev almış kaybettim ben olan dengemi

Bir gece yarısı çalsam kapını

Girsem odana olmazmı

Sarsam tenini o ince belini

Yatsam yanına olmazmı

Olmazmı yar olmazmı

Ruhun benim olmazmı

Olmazmı yar olmazmı

Kalbin aşk`a doymazmı', 'Bir bilsen bebeğim neler geçiyor aklımdan Sensin tek sebebim uğruna eridiğim Hırçın düşünceler kuşatmış tüm çevremi Bedenim alev almış kaybe...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmaz-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş Adam', 'unutulmus-adam-umit-yasar-oguzcan-m5o9e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen unutulmuş bir adamsın 

şu yarım milyonluk  şehirde

gençligini bir deli rüzgar götürmüş

umutların kim bilir nerede 

hangi sevgilinin kollarında kalmış

sen çok gezmiş çok görmüş

şimdi alabildiğine yanlız adam

hatıralar eski bir şarkıdır dudaklarında

söylemek istersin söyleyemezsin

kahreder kahreder seni zaman 

bu şehrin aşina sokaklarında

ölesiye ağlamak istiyordun

bilmedigin bir şey değildi ağlamak

kaderinin agırlıgınca sarhoştun 

hayalerinin genişligince 

dünyadan uzak

seni tozlu aynalarda tanıdım

sacların anlına dökülmüştü tel tel

gözlerin göz olduklarından uzak

kederliydin sonbahar akşamları gibi

ve sonbahar akşamları kadar güzel

yorgun ellerin ceplerindeydi

varlıgından utuanırcasına saklı

ellerin ki bir keman kadar hassas

bir şarkı gibi dokunaklı

sen unutulmuş bir adamsın

anlaşılmamış şiirlerim gibi

bütün güzelligiyle unutulmuş

şiirlerim ki yanlızlıga benzer

öylesine mahsun öylesine kahrolmuş 

ümit yaşar oguzcan', 'sen unutulmuş bir adamsın  şu yarım milyonluk  şehirde gençligini bir deli rüzgar götürmüş umutların kim bilir nerede  hangi sevgilinin koll...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/unutulmus-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmin Dudaklarımda', 'i-smin-dudaklarimda-fatih-tuzun-5a45u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok zamandır unutmak istedim

Seni unutmak canım kolay olmuyor

Kendime başka aşklar aradım

Başka aşklarda canım sen olmuyor

Anladımki kalbimin tek hakimi

Sensiz olmuyor

Anladımki gönlümün prensesi

Bana artık güneş doğmuyor

Haydi gel bana haydi yana yana

Aşkın`ın  ateşi damarlarımda

Haydi gel bana aşk`a  kana kana

Hala ismin var dudaklarımda

Çok zaman geçti ben hep seni düşündüm

Yaptığım hatalarıma üzüldüm

Suç bendemiydi yoksa sendemi

Artık gülüm ne farkederki

Haydi gel bana haydi yana yana

Aşkın`ın ateşi damarlarımda

Haydi gel bana aşk`à kana kana

Hala ismin var ,hala ismin var

Hala ismin var dudaklarımda', 'Çok zamandır unutmak istedim Seni unutmak canım kolay olmuyor Kendime başka aşklar aradım Başka aşklarda canım sen olmuyor Anladımki kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ismin-dudaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sevgiydi', 'adi-sevgiydi-metin-yalti-1c6f5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akşamdan çıktı dolaşmaya 

Kıyılarda gezindi önce 

Çay içti bahçelerde 

Barlara uğradı tek, tek 

Geceydi evlere girdiğinde

Kiminde yakıcı bir nefesti 

Fısıltıydı kiminde sessiz. 

Kiminde yalnızlıktı, kimsesiz 

Bezginlikti kiminde 

Gün geceye devrildiğinde

Sıcağa sığınmışlardı

Yorgansız yatıyordu bebekler

Geceyle sarılmışlardı 

Üstsüz uzanmıştı kadınlar 

Çıplaktı çoğunlukla kocalar. 

Sevginin bir adı da uykuydu 

Marmara uyuyordu

Sevgi hasadındaydı Sakarya 

Fındık topluyordu Değirmendere 

Denize topuk vuruyor Gölcük 

Vapur kalktı mı? Soluk soluğa Yalova 

Biriyle saklambaç oynuyor Düzce

Yaşamın düşmanı ölüm 

Sevginin belalısı öfke 

Tanıyamazsınız ki, kalleş ikisi de 

Azrail diye gelirdi ölüm hep 

Zelzele giyinmiş bu gece. 

Demedi bu yaşlı, bu genç 

Demedi çoluk çocuk 

Hoyratça çöktü üstüne yaşamın 

Harmanı yerde kaldı Sakarya''nın 

Fındığını kıramadı Değirmendere 

Soluksuz kaldı Türkiye 

Soluksuz kalınca Gölcük, Yalova. 

Bir adı sevgiydi uykunun 

Marmara uyuyordu 

Sabaha yakındı gece 

Türkiye’m ağlıyordu', 'Akşamdan çıktı dolaşmaya  Kıyılarda gezindi önce  Çay içti bahçelerde  Barlara uğradı tek, tek  Geceydi evlere girdiğinde Kiminde yakıcı bir...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/adi-sevgiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-metin-yalti-0ibmf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşümde gördüm seni

En gizli yerlerine dek 

soydum seni

Bir yontu oyar gibi

seviye şiir yazar gibi

Ufka dalıp gider gibi

Doyumsuz sevdim seni.

Gözlerinde utanç büyüdü

Kızıla devrildi yüzün

-Yapma günah mı dedin

Bir gizi taşıyordu sesin.

Düşüncem dalgalandı

Yüreğimdeki isyan

Şiirimde çoğaldı.

İşte bak!

İnkar ediyorum tanrıyı

Ölene dek.

En güzel gecelerde

Günahsa seni sevmek.

 Şiirler

Arnavutköy', 'Düşümde gördüm seni En gizli yerlerine dek  soydum seni Bir yontu oyar gibi seviye şiir yazar gibi Ufka dalıp gider gibi Doyumsuz sevdim sen...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Nerde', 'simdi-nerde-fatih-tuzun-td9vt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevgi cahilisin ,bunu şimdi anladım

Sever gibi görünüpte beni sevdaya saldın

Uyku tutmaz oldu artık beni hayalin vardı beynimde

Gözlerim görmez oldu gözlerindi kalan gözlerimde

Yalanmış tüm sözlerin

Kıskançlık yeminlerin

İçten gülen o gözlerin

Şimdi nerde,hani nerde

Şimdi nerde,hani nerde

Karanlık gecelerin laneti üzerimde

Uykusuz  düşlerin hayali gözlerimde

Senle geçen günlerin anıları kalbimde

Şimdi söyle,susma söyle neden,niye böyle

Sen benimleydin be canım sen benimle

Herşeyinle be canım herşeyinle

Şimdi nerdesin söyle  NERELERDE', 'Sen sevgi cahilisin ,bunu şimdi anladım Sever gibi görünüpte beni sevdaya saldın Uyku tutmaz oldu artık beni hayalin vardı beynimde Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simdi-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolardayım', 'yolardayim-fatih-tuzun-nf1az', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık sokakta gözlerim doluyor

Soğuk bir havada içim eriyor

Yaktığım sigara beni hatırlatıyor

Sigaramın dumanında hayalin var bebeğim

Sigaramın dumanında aşkımız var meleğim

Beynimde yankılanıyor tüm sözlerin

Kaldırımlar dost bana bu kör gecede

Hasretin çökmüş içime

Yıldızlar dost bana bu kör gecede

Kararsız bedbaht yüzüm yollardayım

Gece kokar sanki hüzün yollardayım

Beni yıkan bir tek sözün yollardayım

Umutların tükendiği yollarda........', 'Karanlık sokakta gözlerim doluyor Soğuk bir havada içim eriyor Yaktığım sigara beni hatırlatıyor Sigaramın dumanında hayalin var bebeğim Sig...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yolardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersizdim', 'habersizdim-ethem-vayvayli-vrdy1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Habersizdim

oysa 

ben seni sevmenin

hazırlık aşamasını tamamlamıştım

çiçekçiye uğrayıp

kırmızı bir gül almıştım

bir şişe de  gözyaşı bulmuş

açılmıştım denizlere

balıkçı teknesiyle

habersizdim kuzey rüzgarlarından

gemici kızlarından....

hele bir mevsimi vardı sevmenin

hepten habersizdim

ayağımın altındaki çimenlerden

kırmızı ışıklardan;gelip geçenlerden

oysa

suç ne bende ne aşkımdaydı

polisler sevdiğimin farkındaydı

belliydi

salıncak ipleriyle gül taşımıştım

limanlara..', 'Habersizdim oysa  ben seni sevmenin hazırlık aşamasını tamamlamıştım çiçekçiye uğrayıp kırmızı bir gül almıştım bir şişe de  gözyaşı bulmuş ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/habersizdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekledim', 'bekledim-cemal-safi-yb01r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saymadım hasretinle bu kaçıncı yılbaşı

Bir ihtimal de olsa döner diye bekledim

Ne bir demet karanfil ne bir damla gözyaşı

Bir hal hatır sormayı dener diye bekledim

Şu kışta kıyamette ömrüme düşen karda

Bir dostuma uğrayıp ahvalimi sorar da

Belki de bir merhamet duyar da

Yenilmez gururunu yener diye bekledim

Bir yanda gözlerimde ebediyet uykusu

Bir yanda seni son kez görememek korkusu

O güzel ellerinden içersem bir damla su

Bütün ızdıraplarım diner diye bekledim

Perdesiz pencereme şafakla söktüğün an

Gelip de başucumda boynunu büktüğün an

Pınar dudaklarından ismimi döktüğün an

İçimdeki yanardağ söner diye bekledim

Ne sıkmağa gücüm var versen bile elini

Ne sarmağa mecalim var o incecik belini

Alnımda hayal edip o minicik mendilini

Gül kokusu tenime siner diye bekledim

Dudaklarımda tekbir ellerim göğe açık

Sen diye irkilirim ses duysam en ufacık

O mavi gözlerini bir daha son defacık

Dünya gözüyle görmek hüner diye bekledim..', 'Saymadım hasretinle bu kaçıncı yılbaşı Bir ihtimal de olsa döner diye bekledim Ne bir demet karanfil ne bir damla gözyaşı Bir hal hatır sorm...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bekledim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sor', 'beni-sor-fatih-tuzun-m5d1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam içiyorum,içiyorum kalbim sarhoş

Artık o sözlerin,yalanların hep bomboş

Yanlızlık masamda alıştım ben ona

Şimdi bir daha gelme uzakdur benden

Bedenim donuk,ellerim buz gibi

Bana sorma halimi şimdi uzakdur benden

Beni sor dalgalara neden böyle hırçın diye

Beni sor balıklara neden böyle suskun diye

Beni sor güneşe her gece batarım niye

Beni sor beni sor yine

Beni sor kader`e neden böyle bahtsız diye

Beni sor gözlerime neden hüzün dolu diye

Beni sor bulutlara zaman zaman ağlarım niye

Ben sor beni sor yine

Çünkü sensizim', 'Bu akşam içiyorum,içiyorum kalbim sarhoş Artık o sözlerin,yalanların hep bomboş Yanlızlık masamda alıştım ben ona Şimdi bir daha gelme uzakd...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-hakan-sengorun-cl3nr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk bir gece, sakin bir düşe doğru gözlerimi kapadım

Bir an içindi tüm gördüklerim bi an için çekip gittim

Gece karanlığına bürünüp kayboldu o an

Tüm YANLIZLIK buradaydı ve onu anlamlı kılan SENSİZLİK zannetmemdi

Zaman yine kendi başınaydı ve bizler her şeyi saatlerden gördüğümüz kadarıyla biliyorduk

Gökyüzü bir renk daha buldu zaman diye bir bahanesi var sebeplerin

bir yerden tutunmalı yaşama tutunmasa sanki devam etmeyecek

Ve başlamış çoktan benim yaşamım ben hatırlamıyorum ancak sonuna tanık olabilirim her saniyemden sorumluyum her şarap bardağındanda ama ben hiç saniyeleri saymadım yaşarken bardaklarıda benim için sayan biri vardır nasılsa

Zamansız bir ölümüm ben zamansız ölüm yoktur ama tam zamanında ölür hep yada birileri öldürür gerçeği

VE  ben öldüğümde tüm yalanı ortaya çıkacak yaşamın zamansızlığı zamanın olmadığından...', 'Soğuk bir gece, sakin bir düşe doğru gözlerimi kapadım Bir an içindi tüm gördüklerim bi an için çekip gittim Gece karanlığına bürünüp kaybol...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengörün']::text[], 8.5, '{"poet":"Hakan Şengörün","poet_slug":"hakan-sengorun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zamansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler Yapmalı', 'bir-seyler-yapmali-fatih-tuzun-hw7c7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koştum peşinden senin gül yüzünden

Tutamadım elinden sarılamadım sana

Yollar hep aynı kader zàlimkar

Günahmı,yasakmı  mutluluk uzakmı yar

Birşeyler yapmalı,birşeyler

Bir yol bulunmalı mutlaka bulunmalı

Aşk kaçmadan pencerelerden aşkı tutmalı

Aşk`la yaşamalı yar

Yok olmalı sevdamızda gözü olanlar

Kahrolmalı aşklara zincir vuranlar

Uyanmalı uykulara hüzünle dalanlar

Bir  çıkış bulmalı aşk`a doymalı yar

    (SeNi SeViYoRuM  EcE  ^^sQUirReL^^)', 'Koştum peşinden senin gül yüzünden Tutamadım elinden sarılamadım sana Yollar hep aynı kader zàlimkar Günahmı,yasakmı  mutluluk uzakmı yar Bi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-seyler-yapmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-fatih-tuzun-ufczb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen hayat çok anlamsız geliyor

Herşey karanlık ve anlamsız

Tek anlamım sen vardın bak işte sensiz kaldım

Gülmüyor yüzüm yanlızım

Yine doğuyor güneş,yine batacak yine

Veda ediyor yıldızlar senden yoksun

Kapılarım kapanmış geceler seni söyler

Beni sarmış hüzünler sen yoksun

Yalancı bahar,yalancı insanlar

Unutuldu verilen sözler

Şimdi sende beni unutup gittin değilmi

Hani bi tanendim peki şimdi neredesin', 'Bazen hayat çok anlamsız geliyor Herşey karanlık ve anlamsız Tek anlamım sen vardın bak işte sensiz kaldım Gülmüyor yüzüm yanlızım Yine doğu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalanci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofia', 'sofia-ethem-vayvayli-ykrbd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her tren gelişinde

Gel istasyona demiştin

Trenlerden önce geldim Sofia

Yaz,kış,kar,yağmur demedim yetişdim

Bir aşk uğruna bunlar çekilir mi ya?

Her zaman aynı yerde demirliyordum

İnenleri saydım birer birer Sofia

Emin ol senden güzelleri de vardı

Ama ben seni seviyorum ya...

Bekleme odasında bir kız vardı

Neleri vardı bir bilsen...

Bakışları,gülüşleri vardı senden alâ

Ama ben seni seviyorum ya...

Beş yolcu treni gelirdi bu istasyona

Birinde gelmedin birinde gelseydin ya

Nihayet beklediğim trenden indin

Valizini taşıdım Sofia

El açtım ekmek parası için ben sana

Dün bu garda beni öpen sendin

Bugün unuttun

Söyle Sofia söyle

Seven unutur mu ya?

                  Bir rus generali''nin', 'Her tren gelişinde Gel istasyona demiştin Trenlerden önce geldim Sofia Yaz,kış,kar,yağmur demedim yetişdim Bir aşk uğruna bunlar çekilir mi ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sofia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Neden Ağlattın', 'beni-neden-aglattin-fatih-tuzun-rx51f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için çarpan şu kalbi göremedinmi

Issız geçen gecelerimi hissetmedinmi

Seni ne kadar sevdiğimi bilemedinmi

Beni  neden ağlattın bitanem 

Beni niye ağlattın

Ne suçum ne günahım vardı ki benim

Tüm güllerimi sana vermiştim

Oysa neler neler ümit etmiştim

Beni neden ağlattın bitanem

Beni niye ağlattın

Bak işte sevin şimdi

Ellerim titrer oldu

Ömrümün sonbaharında

Yapraklarım soldu

Gözlerim senden başkasını zaten görmüyordu

Hiç görmez oldu', 'Senin için çarpan şu kalbi göremedinmi Issız geçen gecelerimi hissetmedinmi Seni ne kadar sevdiğimi bilemedinmi Beni  neden ağlattın bitanem...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-neden-aglattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşeyler Var', 'birseyler-var-fatih-tuzun-dew2c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir kitap gibisin okudukça içine çeken

Bir şiir,roman sanki beni mest eden

Yalancı dünyada yüzümü güldüren

Bir şeyler var

Yaşadığım her anda onu hatırlatan

Bir gözler var beni kendime getiren

Anlamsızlığıma anlam katan 

Bir şeyler var

Bir şeyler var bir şeyler

Beni sana çeken

Bir şeyler var bir şeyler

Seni bana iten

Ruhumu titreten o ılık rüzgar

Karşıma çıksada sıra sıra dağlar

Nehirler göller bana değil engel

Bir duygu var içimde

Bir şeyler var

Coşmakta taa derinde birşeyler var......', 'Sen bir kitap gibisin okudukça içine çeken Bir şiir,roman sanki beni mest eden Yalancı dünyada yüzümü güldüren Bir şeyler var Yaşadığım her ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birseyler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Sen', 'i-cimdeki-sen-fatih-tuzun-mwfmc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bir kitap gibisin okudukça içine çeken

Bir şiir,roman sanki beni mest eden

Yalancı dünyada yüzümü güldüren

Bir şeyler var

Yaşadığım her anda onu hatırlatan

Bir gözler var beni kendime getiren

Anlamsızlığıma anlam katan 

Bir şeyler var

Bir şeyler var bir şeyler

Beni sana çeken

Bir şeyler var bir şeyler

Seni bana iten

Ruhumu titreten o ılık rüzgar

Karşıma çıksada sıra sıra dağlar

Nehirler göller bana değil engel

Bir duygu var içimde

Bir şeyler var

Coşmakta taa derinde birşeyler var......', 'Sen bir kitap gibisin okudukça içine çeken Bir şiir,roman sanki beni mest eden Yalancı dünyada yüzümü güldüren Bir şeyler var Yaşadığım her ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icimdeki-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acizim Yar', 'acizim-yar-fatih-tuzun-4ke72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorsun değilmi seni ne kadar sevdiğimi

Anlamazdan geliyorsun sence bu suç değilmi

Hiç olurmu seven kalp ayrı durur mu

Hasret denen o kötü his yerinde durur mu

Acizim yar acizim sana derdimi anlatmaktan

Acizim yar acizim sana sevgimi anlatmaktan

Hani her anında onu görürsün

Kendinden çok onu düşünürsün

Her gece yatakta döner durursun

Uyku tutmaz  seni o aklındayken

Bir tiryakiliktir aşk asla bırakamazsın

O seni unutsada sen unutamazsın

Yıllar geçse bile anlayamazsın

Anlaşılmazdır aşk rüya sanırsın

Acizim yar acizim sana derdimi anlatmaktan

Acizim yar acizim sana sevgimi anlatmaktan', 'Biliyorsun değilmi seni ne kadar sevdiğimi Anlamazdan geliyorsun sence bu suç değilmi Hiç olurmu seven kalp ayrı durur mu Hasret denen o köt...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acizim-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Düş Yakamozları', 'nazli-dus-yakamozlari-ethem-vayvayli-h613l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin yolların

Bir denizin kıyısında son bulur

Geceden uyuklayıp kalan sisler

Ağır ağır doğrulurken soğuk limanlardan

Martılar ilk çığlıklarıyla karşılamış olur sabahı

Akşamdan düşlerinle kolkola dolaştığın sokaklar

Saatlerce oturduğun sahil taşları

ve deli dalgalar

Bu kez işte yalnızlıklarıyla sana dost 

Sana yürekten el uzatmaktalar

Belki umutsuzluğunu belki ilk heyecanını 

İlk defa aşka uyanmanın şaşkınlğını taşırdın

Omuzlarında ürperti

Dudaklarında tatlı biçimsizlikler

Yavaş yavaş kapanırdı işte kirpiklerin,gözlerin

Koklardın sonsuzluğunu denizlerin

Seni deniz kıyısında sevdim

Mercan adalarına götüreceğimi söyleyip

O soylu maviliğe ortaklığımı hileme katıp

Seni denizler gibi sevdim

Sen denizlerin kızıydın

Sen belki de deniz kızıydın', 'Senin yolların Bir denizin kıyısında son bulur Geceden uyuklayıp kalan sisler Ağır ağır doğrulurken soğuk limanlardan Martılar ilk çığlıklar...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nazli-dus-yakamozlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın', 'varmisin-fatih-tuzun-vn1r4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni doğan dünyama güneşim olmaya

Geceleri yıldızlarda hayallere dalmaya

Kalbinde bana bir ömür yer açmaya

Varmısın benimle varmısın ECE

Gecelerim bitmiyor artık,kabuslar pusuda

Hayat artıjk tat vermiyor sen yokken yanımda

İlk gördüğüm anda başladı kalbim yanmaya

Varmısın ECE benimle yani baştan hayata

Dur çatma kaşlarını hele bir dinle

Ne yapsın bu kalp sevdalanmış bir kere

Dünyada olmazsa ahirette bile

Haykıracak bu kalp  seni seviyorum ECE diye

Açtım kollarımı şimdi bekliyorum seni

Gelirmisin bilmem ama çok seviyorum seni

Ağlayan gözlerime sen getirdin neşeyi

Hadi tut ellerimi ECE yaşayalım birlikte sevgiyi

 ((SeNi SeViYoRuM EcE  ^^sQUirReL^^))', 'Yeni doğan dünyama güneşim olmaya Geceleri yıldızlarda hayallere dalmaya Kalbinde bana bir ömür yer açmaya Varmısın benimle varmısın ECE Gec...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/varmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Demir Gövdesi', 'ozlemin-demir-govdesi-ethem-vayvayli-5ffkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen yokluğunu

demir gövdesine

örterdin körfezin

dem özüne girer girmez nane

kekik ve damlardan kalkan

kırağı ıslaklığı

ayak bileklerinde çimlenmiş

soylu nergis çiçeklerinin

güne dönük merhaba haykırışlarını

uyuturdun nemli yüreğinde

salkım dağlarında,ay ışıklarında

bekleyiş

gürgen dallarında rüzgar

hasretinin

ve pınarlarda boynu bükük 

özlemlerin

ağladığı ikindi gölgelerinde

sen yokluğunu emdirirdin

kiraz çubuğu parmaklarınla

saban inmemiş toprak özlerine

ki bulurdun beni

sen yokluğunu

getirirdin yoksul ayak izlerinle

minicik bir ceylanın gözlerine

ki bulurdun beni

sen yokluğunu 

demir gövdesine

örterdin körfezin', 'sen yokluğunu demir gövdesine örterdin körfezin dem özüne girer girmez nane kekik ve damlardan kalkan kırağı ıslaklığı ayak bileklerinde çim...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlemin-demir-govdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-fatih-tuzun-6li9y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bana ne yaptın böle

Geldim hiç ummadığım hale

Gözlerim gülüyor,mutluyum yine

Nedenmi?neden olabilir sence?

Çünkü seni seviyorum delice

Unuttum her an ağlamayı

Unuttum kahrolmayı

Yanlızlıktan boğulmayı unuttum artık  senle

Nedenmi?neden olabilir sence?

Çünkü sonuna kadar gitmeliyiz seninle

Hadi gel hadi giriver gönlüme

İçindeki çocuğu uyandıralım birlikte

Sonumuzu beraber çizelim göklere

Nefreti,yalanı ve düşmanı silelim birlikte

Sadece aşkımızla yürüyelim güzel günlere

Nedenmi?neden olabilir sence?

Aşkımsın,birtanemsin

Kısaca aldığım her nefessin desem yetermi söle

 ((SeNi SeViYoRuM EcE ^^sQUirReL^^))', 'Sen bana ne yaptın böle Geldim hiç ummadığım hale Gözlerim gülüyor,mutluyum yine Nedenmi?neden olabilir sence? Çünkü seni seviyorum delice U...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Çekirdeklerindeki Pembemsi Neşve', 'mevsim-cekirdeklerindeki-pembemsi-nesve-ethem-vayvayli-35kru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hazirandır,dileklerimizin mevsimi

iğde dallarında parlayan ay akşamlarında

salkım tığları gibi kalbkalbeyiz

yine de duyamazsın sesimi

göremezsin incir topraklarında yeşeren bebeğimizi

biz birbirimizin içine girmiş körebeyiz

seni anlamak için

çözmeliler beni;

                            dağıtmalılar umut tuğlalarını

ayrık köklerini koparmalılar;

                                               turp öbeklerini

soymalılar;

                   biçmeliler sultanlık ırmağını testereyle

ay akşamlarında yırtmalılar;

                   gecenin ağzını hem

beni anlamsızlığa dönüştürüp;muğlak kılıp

seni anlamalılar...

bizim

nevruz çoskusu alevler pençelerimizde

ruhumuzda 

mevsim çekirdeklerinden pembemsi neşve

içiçe geçmiş boşluk oyununda mutluyuz

hem aşığız birbirimize kime ne

hazirandır,dileklerimizin mevsiminde', 'hazirandır,dileklerimizin mevsimi iğde dallarında parlayan ay akşamlarında salkım tığları gibi kalbkalbeyiz yine de duyamazsın sesimi göreme...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevsim-cekirdeklerindeki-pembemsi-nesve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Hüzün', 'ask-ve-huzun-fatih-tuzun-5vcjq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani;

İnsanın içi kıpır kıpır olur ya

İçindeki gülücük gözlerinde parlarya

Nefesin bile değişir kalbin hızlı çarparya

işte o aşk  işte o sensin

Hani;

Hergün yeni bir umutla doğar

Ama her akşam batar ya

Yüzü hiç gülmez kalbi kan ağlar ya

Neşeyi bilmez dertlerle avunur ya

işte o hüzün işte oda benim

 ((SeNi SeViYoRuM EcE  ^^sQUirReL^^', 'Hani; İnsanın içi kıpır kıpır olur ya İçindeki gülücük gözlerinde parlarya Nefesin bile değişir kalbin hızlı çarparya işte o aşk  işte o sen...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-ve-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çukurova Zıncırıkları', 'cukurova-zinciriklari-ethem-vayvayli-kq10f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ki bazen buğulanır da

akşam sefasına başlamış gözlerim

sen düşersin aklıma

çuıkurova zıncırıkları kadar keskin

vurgun emdirisin bana

özlediğim şurupsu kızıllık kokan

dudaklarından...

ki bazen nemlenir de

derin kaygılara batırılmış kirpiklerim

sen çığlık atarsın bu kaygıların ortasından

toros kayalıkları kadar bencil

yorgun gezdirirsin beni

özlediğim korsu kızıllık dağılan

kollarında...', 'ki bazen buğulanır da akşam sefasına başlamış gözlerim sen düşersin aklıma çuıkurova zıncırıkları kadar keskin vurgun emdirisin bana özlediğ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cukurova-zinciriklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-fatih-tuzun-untz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece sana uyandım yine

Aklımdan seni çıkartamadım

Sağa döndüm sen 

Sola döndüm sen

Gözlerimi kapadım hayalimde sen

Benliğin sarmıştı odamı gizlice

Ve sen yoktun sessizliğini yaşıyordum sensiz

Çözmeye çalışıyordum düşüncelerini

Uykusuzluktan şişmiş gözlerimle

Sabaha kadar çocuklar gibi

Hıçkıra hıçkıra ağlayıp yalvardım allah`a

Ne olur ver bana onu diye.............

 ((SeNi SeViYoRuM EcE  ^^sQUirReL^^))', 'Bu gece sana uyandım yine Aklımdan seni çıkartamadım Sağa döndüm sen  Sola döndüm sen Gözlerimi kapadım hayalimde sen Benliğin sarmıştı odam...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklerken', 'seni-beklerken-metin-yalti-bdlij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerce bekledim,

Aylar geçti.

Aylarca bekledim

Yıllar geçti.

Yıllarca bekledim

Ömrüm geçti.

her şey istediğim gibi olacaktı

Ne yazık

İş İşten geçti.', 'Günlerce bekledim, Aylar geçti. Aylarca bekledim Yıllar geçti. Yıllarca bekledim Ömrüm geçti. her şey istediğim gibi olacaktı Ne yazık İş İş...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-beklerken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kolye Beyaz Gerdan', 'beyaz-kolye-beyaz-gerdan-ethem-vayvayli-pus3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nerdesin 

beyaz ayaklarınla

kar yağmış odama girsen

seni bekler beyaz perdeler

hepsi ak,hepsi beyaz

fotoğraflar dağınık

umutlar siyah-beyaz

hepsi bıraktığın yerde

ortada beyaz yatak

etrafında beyaz güller

beyaz kolye,beyaz gerdan

şafak atmak üzere

ortalık süt beyaz

seni özledim

dişler inci,kız beyaz!...', 'nerdesin  beyaz ayaklarınla kar yağmış odama girsen seni bekler beyaz perdeler hepsi ak,hepsi beyaz fotoğraflar dağınık umutlar siyah-beyaz ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beyaz-kolye-beyaz-gerdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kültablası', 'kultablasi-can-yucel-ymmo8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendi kendimi sakınıyorum, sıkılıyorum

Ömür, uzun ömürlü bir kutu süt

Tezelden gitmeli bari

Kalafatsız bir kayık içre

Çaparide tutulmuş yetmişinci izmarit olarak

Bir kültabağına basılmak üzere...', 'Kendi kendimi sakınıyorum, sıkılıyorum Ömür, uzun ömürlü bir kutu süt Tezelden gitmeli bari Kalafatsız bir kayık içre Çaparide tutulmuş yetm...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kultablasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşsiz Günler', 'gunessiz-gunler-ethem-vayvayli-mvlm9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnızım nüveylâ yalnızım

akrebin boğumunda kalmışım

topraktan başını çıkartamamış

nevnihâllerden örgüsüz kalmışım

senin cici ayakların ezmiş içimi

koparmış yaşamdan sensiz kalmışım

yalnızım nüveylâ yalnızım

ben vaveylâma mağlup kalmışım', 'yalnızım nüveylâ yalnızım akrebin boğumunda kalmışım topraktan başını çıkartamamış nevnihâllerden örgüsüz kalmışım senin cici ayakların ezmi...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunessiz-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Kenarı Ağacı', 'yol-kenari-agaci-ethem-vayvayli-niyht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oturduğum sokaktan

geçti bütün atlılar

önümde birer birer

durup bana baktılar

saçları kara,saçları ak

kırbaçları yağlı-kaypak

beni yalnız koyarak

seyyâle olup aktılar', 'oturduğum sokaktan geçti bütün atlılar önümde birer birer durup bana baktılar saçları kara,saçları ak kırbaçları yağlı-kaypak beni yalnız ko...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yol-kenari-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznü Üşüten Yaz Yağmuru', 'huznu-usuten-yaz-yagmuru-ethem-vayvayli-kvnam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '17 Ağustos''a

şimdi yaz yağmuru yağıyor durmadan

gözyaşım gibi sessiz ve durmadan

sen seni kurtarmadan ve evini kurmadan

hem yedi günlük ölüyü bile koymadan

yaz yağmuru yağıyor şaşkın ve durmadan

deniz üzerine gelirken biraz daha doluyor

biraz daha gün yüzüne acı vuruyor

şimdi yaz yağmuru yağıyor durmadan', '17 Ağustos''a şimdi yaz yağmuru yağıyor durmadan gözyaşım gibi sessiz ve durmadan sen seni kurtarmadan ve evini kurmadan hem yedi günlük ölüy...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/huznu-usuten-yaz-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlardaki Işınlanma Ve Bizimki...', 'onlardaki-isinlanma-ve-bizimki-halil-i-brahim-deveci-b1zin', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhsuz maddenin esiri olmuş, ruhsuz insan,

Gerçek yolu tarif eder mi sendeki lîsan?

Rakibini bilmeyen, mânâsız, ruhsuz mahluk,

Maddelere hükmemek mi sence gerçek kulluk?

Sen, arsızlığı namusluluk sayanlardansın,

Maddeye hükmedişle küfre kayanlardansın,

Zamanı, mekanı gerçek sahibine bırak,

Aslında maddeye hükmetmek de sana ırak,

Bırak, zaman ve mekanın sahipleri gelsin,

Onların nûru zamanı ve mekanı delsin.

Kıyasla, Hakk yolcusu dervişle kendini,

Bul, o zaman âlemdeki dengini,

Yapacağın en mükemmel iş nedir? Ölç ve biç!

Sence, maddeciyle mânacı bir olur mu hiç?

Madde kafasıyla yapılacak en mükemel iş;

Işınlanma yoluyla göklerden yere iniş(!)

Siz, ampullerle aydınlatmacılık oynarken,

Akıl içerisinde akılsızca kaynarken,

Bizse yıldızlarla karanlıkları yırtarız,

Nûrumuzla güneşe aydınlıklar katarız!

Sizler, ata araba diye binerken...Sizler,

Ay''ı âlemlere taşırdı bizdeki izler,

Sizleri ararken, ışının sözlük anlamını,

Bizimkiler, boş görünen dolu zamanını,

Yatalak velî evde namaz kılarken, sessiz,

Ruhu, Kâbe''yi tavaf eder, belli-belirsiz,

İşte sana ışınlanmanın mâna cephesi,

Bin zırha bedeldir, Mü''min''in bir kaç cübbesi!(1996)', 'Ruhsuz maddenin esiri olmuş, ruhsuz insan, Gerçek yolu tarif eder mi sendeki lîsan? Rakibini bilmeyen, mânâsız, ruhsuz mahluk, Maddelere hük...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/onlardaki-isinlanma-ve-bizimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Irayan Nihâl', 'sensizlige-irayan-nih-l-ethem-vayvayli-42hb9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sunduğum badede soldu gülşenler

Gündüz ufku aştı yolu çekenler

Hep ah edip ocağına gelenler

Sarılır sazının teline nihâl

Yüce dağlar aşar sevgi nâharı

Yürekler kanadı kalmadı hârı

Yoksul köylü gibi aşk kapı kapı

Dolaşır yokluğun ilinde nihâl

Sükûtun rengine erdi bülbüller

Kâtreyi deryaya saldı sürgünler

Bir gamzeyle yüreyini bölerler

Uçuşur boşluğa keklikler nihâl

Bin atlıyla geçtin karlı belleri

Şafak ile çektin kışta göçleri

Aştığın sırtlarda ayak izleri

Irar sessizliğe karışır nihâl

Vayvaylı sevdaya çaldı kalemi

Buldu cihanda dertlerden veremi

Güllerle yurt etti sevdiğin öreni

Güller sensizlikten ağlaşır nihâl', 'Sunduğum badede soldu gülşenler Gündüz ufku aştı yolu çekenler Hep ah edip ocağına gelenler Sarılır sazının teline nihâl Yüce dağlar aşar se...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensizlige-irayan-nihal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden...', 'yeniden-halil-i-brahim-deveci-qz34u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeniden hortladı, dünya malına rağbet,

Dindeki ilahî aşk rafa kaldırıldı.

Yalnız Hazret Allah''a yapılan ibâdet,

Katıksız riya yemeğine bandırıldı.

Binbir yolla sokuldu, ümmete fitne,

Eski dert değil; Mü''min''in hali kime ne?

Karıştırır olduk, Allah ne, soysuz put ne?

Saygı duruşu! diye ümmet kandırıldı.

Kılı kırk yarardık biz, kul hakkı uğruna,

Şimdi hep helâl yemek gidiyor zoruna,

Bilmezler, neler götüreceğiz yarına,

Allah aşkıyla değil, puta yandırıldı.(1996)', 'Yeniden hortladı, dünya malına rağbet, Dindeki ilahî aşk rafa kaldırıldı. Yalnız Hazret Allah''a yapılan ibâdet, Katıksız riya yemeğine bandı...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Deveci']::text[], 8.5, '{"poet":"Halil İbrahim Deveci","poet_slug":"halil-i-brahim-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeniden-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Ölümü', 'sairin-olumu-ethem-vayvayli-mr30o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-can yücel''e-

renk,

bir hülya tohumunun

dallarını göklere vurmasıyla

                               koyulaşır

ruh,

iki dağın ortasında

ingin ırmak arar

                            doygunlaşır

kalb,

bir yıldız koparsa gökten

dogrulur yerinden yanaklarına Tanrı''nın

Tanrı yardımını esirgemez

                                    ululaşır

aşk,

gök rüzgarıdır dalga dalga

güneşin omuzlarında yükselir

bir serçenin bacaklarıyla

                                soylulaşır

ses,

sessiz bir koroya konuk dil olur

turnaların her güz gidişinde

sıcak memleketlere

gül,

çığ çığ yuvarlanır

hilâl,

turuncu renk verir

                               dargınlaşır

                 ''can''

yolların bittiği yer olsa gerek

uçurumun başı ve denizler evlek evlek

gök kanatlarında acı taşır

bize boğça boğça zevk

                            sunulur

nar ve dağdağan

sam ve günebakan

     iğrilir

                 ve

                          doğrulur', '-can yücel''e- renk, bir hülya tohumunun dallarını göklere vurmasıyla                                koyulaşır ruh, iki dağın ortasında ingin...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sairin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara Özlem', 'uzaklara-ozlem-ethem-vayvayli-j5wod', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün buralardan gideceğim nüveylâ

Toprağın üzerine bir gül uzatarak

Ufkun dolaplarından çıkartıp kasketimi

Gözlerinden dökülen yağmura tutarak

Bu benim son yolculuğum nüveylâ

İçimdeki gitme arzusunu yenemedim

Senin yanında kilitlendi yaşamın dili

Sana kendimden hiç söz edemedim', 'Birgün buralardan gideceğim nüveylâ Toprağın üzerine bir gül uzatarak Ufkun dolaplarından çıkartıp kasketimi Gözlerinden dökülen yağmura tut...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzaklara-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Göründü', 'yol-gorundu-ethem-vayvayli-jb6sp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ince dağlar,uzun dağlar

yol göründü,yar bitti

yüreğim kırgın ağlar

sapa vurdu hayat beni

kırdan sarı kuşum uçtu

gurbet oldu,yol göründü

dert dediğin bir avuçtu

sen gidince çok büyüdü', 'ince dağlar,uzun dağlar yol göründü,yar bitti yüreğim kırgın ağlar sapa vurdu hayat beni kırdan sarı kuşum uçtu gurbet oldu,yol göründü dert...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yol-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarpız Kokulu Şiir', 'yarpiz-kokulu-siir-osman-bulent-manav-morw8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaylayı bilmeyenler, yarpızı da bilmezler,

      Bilmezler sadra şifa tütsülü yokuşları...

      Kaf Dağı Ülkesi''nin yolu yayladan geçer,

      Cevizlerin başında döner anka kuşları...

Gün akşama döndü mü Toros yaylalarında

Çakallar tempo tutar, dellenir kuru poyraz,

Bir gam musallat olur kavakların başına...

Masallar, yaylalarda hayat bulur, can bulur

Uçan halı yayladan başka yerde uçamaz!

Şahmaran''n sarayı sarp dağlara kurulur...

Su yengeçleri yan yan yürürler biteviye,

-Çocukların gözüne ilişmenin korkusu-

Yaylada her ağaçtan bir yol uzar öteye.

Ben gaz lambalarına yaylada sevdalandım,

Yüreğimde yer etti yanık fitil kokusu

Ve bütün masallara loşluklarda inandım...

Her yayla bir çocuktur; gücenince ağlayan,

Her yayla bir yiğittir; gözü pek kalbi temiz

Ve her yayla bir sevda; gürül gürül çağlayan...

      Şimdi bağlar tarümar ve gökyüzü bulutlu,

      Fecr-i sadık bezminde uyanmaz oldu ufuk...

      Aratmazdı yaylanın akşamı İstanbul''u,

      Akşamla kan rengine boyanmaz oldu ufuk...

Böğürtlenler, yarpızlar, kuşburnular nerede?

Nerede çekirgeler? Baykuşlar nerdesiniz?

Göçüp gittiniz mi hep masallar ülkesine?

Oysa bana sevmeyi sizler öğretmiştiniz;

Sevgiyi, gözyaşını, tefekkürü, korkuyu!

Yaylanın yerlileri, sahipleri sizsiniz...

Öylesine özledim o büyülü diyarı,

Kekik öbeklerini, karpuz çatlatan suyu,

Yıllardır yorulmadan şakırdayan pınarı...

Ömre bedel şafakta ufku tutan bayraklar,

Seherlerde okunan iki rekatlık namaz,

Geciken çocukları bekleyen bir çift şamar...

Yayla denince bende bir ılık rüzgar eser,

Keyifle dalgalanır binbir hatıra ve haz.

Sonbahar hüznü gibi sararır düşünceler...

Ne gece sükuneti ne bahar sarhoşluğu

Ne yayla mevsimleri ne bad-ı saba kaldı.

Buz edip dondurdular gözlerdeki buğuyu;

Yarpız kokulu şiir, başka bahara kaldı...', 'Yaylayı bilmeyenler, yarpızı da bilmezler,       Bilmezler sadra şifa tütsülü yokuşları...       Kaf Dağı Ülkesi''nin yolu yayladan geçer,   ...', ARRAY['Türk Edebiyatı','Şiir','Osman Bülent Manav']::text[], 8.5, '{"poet":"Osman Bülent Manav","poet_slug":"osman-bulent-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yarpiz-kokulu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzeylere Gidelim', 'kuzeylere-gidelim-ethem-vayvayli-o457a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Bachmann''a-

Rüzgar dövüyor kapılarımızı

Kalk hadi kuzeye gidelim

Topla içindeki barhanaları

Durmayıp burda kuzeye gidelim

kuşlara inat,sulara mürteci

dağların buzunu kırıp kuzeye gidelim

Güneş yalın çıplak ayaklarımızda

yalayacak sıcaklık arasın

kalk hadi kuzeye gidelim', '-Bachmann''a- Rüzgar dövüyor kapılarımızı Kalk hadi kuzeye gidelim Topla içindeki barhanaları Durmayıp burda kuzeye gidelim kuşlara inat,sula...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kuzeylere-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambası ve Yalnız Adam', 'sokak-lambasi-ve-yalniz-adam-ethem-vayvayli-6bvvj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerinde büyüyen hasret

mektup kelimeleri kadar buğulu

gökyüzü gibi benzer ikimize

kumruların çığlık çığlığa

sevişmelerini anımsatır

bir gece yarısı gördüğümüz

o kucaklaşan lambalar

ıslak cam önlerinde büyür hayat

merdiven merdiven yükselir göğe

dudakalrın ezer bir gülün yalnızlığını

buluşur renkler tüm cam önlerinde

sen bunları yaşarsın yeniden yeniden

ben gitgide daralan sokaklardan

kırık kapılı evime dönerim

soğukla birlikte karşılar açlık beni

beklemeden yatağıma girerim

ellerinden benimle birlikte düşer

sana verdiğim tüm güller

sende susar haykırışlar

ve lambalar sende söner', 'gözlerinde büyüyen hasret mektup kelimeleri kadar buğulu gökyüzü gibi benzer ikimize kumruların çığlık çığlığa sevişmelerini anımsatır bir g...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sokak-lambasi-ve-yalniz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-ethem-vayvayli-6wgai', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gidiyorsun

uzaklar seni çağırıyor

ellerini ellerine vurarak

bütün sendelikleri alarak

ve seninleliklere yağıyor yağmur

üşüyor kaldırımlarda korku

önümüz açık gönlümüz açık

bakmadan

                  anlamadan

                                      anmadan

gidiyorsun', 'gidiyorsun uzaklar seni çağırıyor ellerini ellerine vurarak bütün sendelikleri alarak ve seninleliklere yağıyor yağmur üşüyor kaldırımlarda ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gidiyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Beraberdik', 'hani-beraberdik-ethem-vayvayli-kr5xv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akşam olur,karanlık çöker kapımıza

Sen ağlarsın,ben susarım

Yitik şarkılarımız mırıldanılır kulaklarımıza

Sen ağlarsın,ben susarım

Günbatımı kuşları gelip çöker arkamıza

Sen ağlarsın,ben susarım

Kızgın gül değmiştir beyaz avuçlarına

Sen ağlarsın,ben susarım

Gün gelir,kırar kapılarını gireriz kentimize

Sen ağlarsın,ben susarım

Akşam olur,mürfeze sarar her yanımızı

Sen kaçarsın,ben yakalanırım', 'Akşam olur,karanlık çöker kapımıza Sen ağlarsın,ben susarım Yitik şarkılarımız mırıldanılır kulaklarımıza Sen ağlarsın,ben susarım Günbatımı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-beraberdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum', 'seni-cok-seviyorum-fatih-tuzun-d5z70', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman gece yarısı

Yine seni düşünüyorum

Islak gözlerim camda

Belki geçer diyorum

Hani bir şarkımız vardı ya

Onu mırıldanıyorum

Biliyormusun kahverengi gözlüm

Seni çok seviyorum', 'Zaman gece yarısı Yine seni düşünüyorum Islak gözlerim camda Belki geçer diyorum Hani bir şarkımız vardı ya Onu mırıldanıyorum Biliyormusun ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tüzün']::text[], 8.5, '{"poet":"Fatih Tüzün","poet_slug":"fatih-tuzun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmara,Kaçak Dostları ve Şehrin Işıkları', 'marmara-kacak-dostlari-ve-sehrin-isiklari-ethem-vayvayli-53h8k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldırımların çaldığı bakışların vardı marmara

Yıldızlarca kuşatılmış gece romanını okuyan

Tutuklu yüreklerden indirip sisli kandilleri

Ateşle buluşturan ellerin vardı marmara

Kurşun kurşun parlardı sularında raks

Gemiyle dalgaların,kanatla gagaların raksı

Sökülürdü iliklerinden kanayan derinlik

Gökyüzüne karışan gözlerin vardı marmara

Gece vakti közleri üflerdi soğuk nefesin

Şehrin ışıkları kaçak dostlarındı marmara

Rüzgarın sende yıkandığı çılgın zamanlarda

Fırtına koparan saçların vardı marmara

Aydedenin eşkiyaları basardı sularını

Kumruların tüfek sesleri öterdi o vakit

Sarayburnu''ndan başlardı en kesif ayrılık

Sultanları kaçıran yolların vardı marmara

Geceydi,sevdanın konağında beraberdik

Saçlarını çözdün,sükûtunu çözmedin marmara

Lav dökülü kucağına serpilen gemileri

Sıcacık saran kolların vardı marmara', 'Yıldırımların çaldığı bakışların vardı marmara Yıldızlarca kuşatılmış gece romanını okuyan Tutuklu yüreklerden indirip sisli kandilleri Ateş...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/marmara-kacak-dostlari-ve-sehrin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstanbul Günlüğü / Beyaz Martı', 'son-i-stanbul-gunlugu-beyaz-marti-ethem-vayvayli-te7rr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beyaz martı beni özlemeyeceğini umarak

İlk ışıklarıyla beraber ; telaş dolu

Kuytu ve acı sulardan iz umarak

Dalıp gitti marmaranın gözlerine

Beyaz martı benim bıraktığını sanarak

Kan dökülü sahil taşlarını bekledi

Kimi kez pişman ve yaralı uçarak

Kalbini yeniden yeniden yokladı

Beyaz martı soluk güneşe bakarak

Şarkılar söyledi ki ne şarkılar

Beni ve geleceği içinde uyutarak

Gökyüzünü dostlarıyla kuşattılar

Beyaz martı; akşam oldu,beyaz akşam!

Süt kayığına doğru yürüyerek

Bayat ekmek istedi benden amcam

Deyip uzaklara çekti/çekti kürekleri', 'Beyaz martı beni özlemeyeceğini umarak İlk ışıklarıyla beraber ; telaş dolu Kuytu ve acı sulardan iz umarak Dalıp gitti marmaranın gözlerine...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-istanbul-gunlugu-beyaz-marti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Renk', 'tek-renk-ethem-vayvayli-i5hnb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir beyaz demir olsaydı

Uzatırdık süt denizine

Tutar tutmaz balıkları

Boyardık süt rengine', 'Bir beyaz demir olsaydı Uzatırdık süt denizine Tutar tutmaz balıkları Boyardık süt rengine...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tek-renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Adam Tehlikeli Şiirler Okur', 'kotu-adam-tehlikeli-siirler-okur-ethem-vayvayli-64jxv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

Benim boynuma sarılma

Boynum incedir

Ellerimden tutma

Ellerim gevşektir

Dışarıya aldanma

Kar,fırtına ve barandır

Bahar gülücükleridir

Saçaklarda asılı duran

Aldanma ilk değil

Sonbahar gülücükleridir

II.

Beni bırak,benden kaç

Hangi mevsimi donattımsa

Odama

Senin için zor geçti

Anlaşılmaz oldu şiirler

Geceler vazgeçilmez

Sen kentin sultanısın

Ben kaldırım işçisi

Ellerimde manolyalar

Tehlikeli şiirler okuyup

Şarap içiyorum

Beni bırak,benden kaç

Ben kötü adamım nüveylâ', 'I. Benim boynuma sarılma Boynum incedir Ellerimden tutma Ellerim gevşektir Dışarıya aldanma Kar,fırtına ve barandır Bahar gülücükleridir Saç...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kotu-adam-tehlikeli-siirler-okur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göklere Ağan Martılar', 'goklere-agan-martilar-ethem-vayvayli-3ew1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkmayın çocuklarım

Bildiğiniz kadar yalnız değiliz

Oğlum,kızım,zavallı karım

Biz bir aileyiz

Denizlere,dağlara ve ırmaklara

Bir ağaç bedeni gibi sırt vermiş

Beraber çıkıp güzel havalarda

Evcilik oynamış çocuklarız

Aynı sokağın yokuşunu tırmanmış

Sert ve kaba rüzgarlarda

Sabahları beraber uyanmış

Göklere ağmış martılarız', 'Korkmayın çocuklarım Bildiğiniz kadar yalnız değiliz Oğlum,kızım,zavallı karım Biz bir aileyiz Denizlere,dağlara ve ırmaklara Bir ağaç beden...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/goklere-agan-martilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-ethem-vayvayli-nq99m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O kadar tatlısın ki

Ah hayat!

Seni yaşamaktan korkuyorum

Bitmeni,tükenmeyi unutuyorum

Bir diriliş gibisin

İçten ve tutkun

Ah hayat.ah hayat!

Seni yaşamaktan korkuyorum', 'O kadar tatlısın ki Ah hayat! Seni yaşamaktan korkuyorum Bitmeni,tükenmeyi unutuyorum Bir diriliş gibisin İçten ve tutkun Ah hayat.ah hayat!...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Kentlinin Şehir Maceraları', 'yeni-kentlinin-sehir-maceralari-ethem-vayvayli-p3zvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorarlarsa bir gece

Niye ketten döndüğümü

Yağmurun ıslattığı caddelerde

Bendim mutsuz

Şişli''de bir göz gördüm

Uykumdan önce

Hala gözlerim

O gözden beri uykusuz

Daracık andı

Bir kapı girişinde

Ellerim suçlu

Kırdı cam ve aynaları

Suratımdaki yeni kentli duruşuna

Mıhlandı kızgın ve acımaklı gözler

Daracık andı

Bir kapı girişinde

Bir göz ki heryanı alev dolu

Alevler yağmurla 

Boy atmış,büyümüş

O gözler gecenin

İlk iki siyah devi

Şimdi anlarım

Onlar beni ketten sürmüş

Daracık andı

Bir kapı girişinde', 'Sorarlarsa bir gece Niye ketten döndüğümü Yağmurun ıslattığı caddelerde Bendim mutsuz Şişli''de bir göz gördüm Uykumdan önce Hala gözlerim O ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-kentlinin-sehir-maceralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-ethem-vayvayli-8lqs6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Huzur sade bir gümüştür

Tahtımız kadar yüce ve gür

Çamlık havalarıyla dolu

Ve çamlık havaları gibi

Huzur gökte başlar

Gözlerimize  yağmurun girmesiyle

Kalbimize inanç dolar

Adım atılır hürriyetimize', 'Huzur sade bir gümüştür Tahtımız kadar yüce ve gür Çamlık havalarıyla dolu Ve çamlık havaları gibi Huzur gökte başlar Gözlerimize  yağmurun ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korsan Arkadaşlık', 'korsan-arkadaslik-ethem-vayvayli-k93ar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül çizilmez demirlere

Salkar üzerimize asma dalları

Mey kokar iğdeler

İğdeler arasında

Korsan arkadaştık seninle

Senin beyaz çiçeklerin vardı küçük

demirlerde değil

Elde ve yürekteydi

Camlarda kızgın acılar büyütürdü

Karanfil yaprakların benim için

Su tutardın camlara

Acılar içindeydi korsanlık

Beden bedene sokulurduk

Sıkardı,sarardı bizi

İğde dalları

Sabahlar geç olurdu

İğdelikte yatardık gece

İki tek alırdık

Beyaz çiçeklerinde susardı

Beyaz susuzluğumuz

Başlardık akşamları

Şiirler,şiirler okumaya

Küçük!

Ki

Unuturduk bedenlerimizi', 'Gül çizilmez demirlere Salkar üzerimize asma dalları Mey kokar iğdeler İğdeler arasında Korsan arkadaştık seninle Senin beyaz çiçeklerin var...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/korsan-arkadaslik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Kuyruklu Yıldız', 'ask-ve-kuyruklu-yildiz-akgun-akova-273kq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gittiğim bütün hekimler aynı şeyleri söylediler

söz birliği etmişcesine

''aşk hastalığıdır bunun adı

 ve çok sarsar insanı bu yaştan sonra''

oysa ne yalan söyliyeyim,

ben yalnızca

bir kuyrukluyıldıza

çarptığımı sanmıştım

yaşamın çıkmaz sokaklarında yürürken

yüreğim bir patlamayla aydınlanınca', 'gittiğim bütün hekimler aynı şeyleri söylediler söz birliği etmişcesine ''aşk hastalığıdır bunun adı  ve çok sarsar insanı bu yaştan sonra'' o...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-ve-kuyruklu-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizemli Gözler', 'gizemli-gozler-ethem-vayvayli-fifzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hergün her akşam güneş

Batar senin gözlerinden

Ufuklara gemiler

Aşar senin gözlerinden

                      

                            Anladım ki deniz

                            Anladım ki yıldız

                            Anladım ki bir giz

                            Varmış senin gözlerinde

Hergün her sabah kuşlar

Kalkar senin gözlerinden

Hicran dolu acı yaşlar

Akar senin gözlerinden

                         

                            Anladım ki deniz

                            Anladım ki yıldız

                            Anladım ki bir giz

                            Varmış senin gözlerinde

Hergün her gece yağmur

Tutar senin gözlerinden

Alev alev şimşekler

Yağar senin gözlerinden

                            Anladım ki deniz

                            Anladım ki yıldız

                            Anladım ki bir giz

                            Varmış senin gözlerinde', 'Hergün her akşam güneş Batar senin gözlerinden Ufuklara gemiler Aşar senin gözlerinden                                                    An...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gizemli-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Kanatlı Kuş Sürürleri Diliyorum Sana', 'uzun-kanatli-kus-sururleri-diliyorum-sana-akgun-akova-zrlqu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşk çılgınlığının köprülerinden geçelim seninle

sevgilim, yaban otları arasında bulduğum yeşim

yüreğimdeki su birikintisinde okyanusu arayan nehir

sevgilim, unutmabeni çiçeğinin tuttuğu günlük

gözlerimle sarıldığım kuğu bulutlu gökyüzü

ellerini ayrılıklardan kaçırdığım

dalgın deniz feneri duruşlu

ilkbaharda gezinen sis saçlı sevgilim

mevsimlerin ilkokulundan kışı silelim seninle

yaz yağmurlarına yakalanalım

kumsalında sevişmek istediğin Kız Kalesi''nin önünde

açık hava sinemalarının yıkıntılarında uyuyalım

yer gösterici uyandırsın bizi

gözümüze sıktığı el feneriyle

''hadi kalkın sevdalılar,

Aşk Hikayesi filminde oynayan çift yaşlanmış,

seyirci sizi görmek istiyor!''

binlerce, onbinlerce kemanla çağırdığım dolunay

elektriğin gümüş suyuna ışığını değdiren yıldız

yeraltı kentimde biten güzelavrat otu

geçmiş sevdalarımı erittiğin geceler için

yeniden birini sevmenin ne olduğunu anımsattığın

yüzümde tahtlar devirdiğin,

saraylar yıktığın için

düşlerinin içinden geçecek

uzun kanatlı kuş sürüleri diliyorum sana

ve severken seni,

sevdikçe seni

hep çocuk kalacağım, biliyorum', 'aşk çılgınlığının köprülerinden geçelim seninle sevgilim, yaban otları arasında bulduğum yeşim yüreğimdeki su birikintisinde okyanusu arayan...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uzun-kanatli-kus-sururleri-diliyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böcekleri', 'ates-bocekleri-akgun-akova-x5try', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ışıkla ilgili bir yazı okuyordum, elektrikler kesildi

boğazından geçerek midesine indi kent gecenin

mum aramadım, oysa vardı

pencereye gittim kalkıp çalışma masamdan

iki sevgiliden söz ediyordu ağaçlar fısıldaşarak bahçede

ağaçların yalnızlıklarından korktum

sonra yollardan söz açtılar, düşledikleri yollardan

işte o zaman ateşböceklerini,

birbirini kovalayan iki yanarsöner ışığı gördüm

gezinen son yıldızlarıydılar yeryüzünün

çaldıkları ağustosböceklerini tahta kafeslere dolduran

bir hırsız çetesi geçti sokaktan

ay siliyordu, siliyordu camlarını terleyen evlerin

bir ırmak kente geri dönmeyeceğini bildiren

bir mektup yazıp akıp gitmişti sudan gerekçelerle

yerçekimini aşk yoksunlarına bırakıp

bir bir çıkardım giysilerimi

ve kapısını araladım uyuduğun odanın

sonra açılmak için dokunmamı bekleyen

pembe gülleri gezdirmeye gittik

ağaçların gözlerini yumduğu küçük koruda

gökyüzümü sarsıyordu ıslak kelebek kanatların

ve geceyi

şu ısırıp durduğun geceyi

gitgide derinleşen karanlıkta gitgide sertleşen geceyi

yıldızların gökfişekleri gibi içimizde patladığı geceyi

çiğlenmiş sabahla birleşen ve küçülen geceyi

her güne böyle başlayalım sevgilim

böyle, ateşböceklerine teşekkür ederek', 'ışıkla ilgili bir yazı okuyordum, elektrikler kesildi boğazından geçerek midesine indi kent gecenin mum aramadım, oysa vardı pencereye gitti...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ates-bocekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya,Kıza ve Zamana Dair', 'suya-kiza-ve-zamana-dair-ethem-vayvayli-bz8ll', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tepelere çıkardık

Akşam ve ufkun odacıları

Olarak

Ellerimizde buz halkaları

Yangın dudakalarına sürerdik

Bıçak gibi keskin dağların

Tepelerde oyun kurardık

Avuç dolusu taşlarla

İlk o zaman ellerini tuttum

İlk o zaman sarmaş-dolaş

yaşadım dağlarla

Benim de sevdiğim olur muymuş?

Ben de dalar gider miymişim?

Bir kızın gözlerine

İlk o zaman anladım

Dalıp gittiğimde

Vadi diplerine

Sular ne parlak akardı

Kız ne berrak bakardı

Zaman ne çabuk geçerdi

Tepelere çıktığımızda', 'Tepelere çıkardık Akşam ve ufkun odacıları Olarak Ellerimizde buz halkaları Yangın dudakalarına sürerdik Bıçak gibi keskin dağların Tepelerd...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suya-kiza-ve-zamana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kent Şiirleri', 'kent-siirleri-nihat-ates-vliwm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

Uçurumları dağlarını anlatırken kentin

boğulmuş sözlerimiz yankılanıyordu

-uyumuştu ellerimiz

öyleyse sevgilim 

bu koca kente

bunca yalanı nasıl söyledik biz

II.

Bütün anlarını kent içi yaşadığımız

bıkkın sevişmelerimiz

sessiz varırken uykularına

düşlerinde kırılan goncayı anlamaz

-Şimdi ayrılırsak sevgilim

bu koca kent

bunca yalnızı taşımaz.

III.

Uçurumlar kendilerini de anlattı

karlı bir gök parçası kılığında

girip uykularımıza

Anlamak ve sayıklamak arasında sezdik

Uçurumlar dağlarsız olmaz.', 'I. Uçurumları dağlarını anlatırken kentin boğulmuş sözlerimiz yankılanıyordu -uyumuştu ellerimiz öyleyse sevgilim  bu koca kente bunca yalan...', ARRAY['Türk Edebiyatı','Şiir','Nihat Ateş']::text[], 8.5, '{"poet":"Nihat Ateş","poet_slug":"nihat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kent-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çince', 'cince-akgun-akova-igdak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayrıldık ya, ateşini söndürdüm, uçuçböceklerini yaktım

içim cız etmedi mi, etti, allah kahretsingözlerime uçaklar düşmedi mi, düştü, allah kahretsin

gül yapraklarını tuvalet kağıdı yaptım, yıldızların

bodrumda

Nuh''un gemisi sırtımda paramparça

cami kedilerinin yalnızlığından geçindim ve daha bilmem

nelerden

seni unutmak istedim bunca kıskançlığımla

ezogelin çorbanı, arapsaçını

sigara külünü unutmak istedim

unuttum mu, unutamadım, allah kahretsin

ayrılık taş duvar

ayrılık Çin Seddi aramızda

Çin Seddi ne kadar uzun, allah kahretsin', 'ayrıldık ya, ateşini söndürdüm, uçuçböceklerini yaktım içim cız etmedi mi, etti, allah kahretsingözlerime uçaklar düşmedi mi, düştü, allah k...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ikimiz', 'ikimiz-ethem-vayvayli-he8ta', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kuytu bu kentte

Sen yalnızsın,ben ayyaş

Bulunmaz kapı önü

Pencerelerden sarkık

Ha düştü ha düşecek

Birer yağmur damlası

Senin ellerinden tuttuğun

Son yolculuk vagonumuzu

Bekliyorum,bekliyorum

Çıktı çıkacak diyorum

Görünür görünmez kalbim

Durdu duracak diyorum', 'Bir kuytu bu kentte Sen yalnızsın,ben ayyaş Bulunmaz kapı önü Pencerelerden sarkık Ha düştü ha düşecek Birer yağmur damlası Senin ellerinden...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ikimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Gökyüzü', 'denizin-gokyuzu-ethem-vayvayli-mkzny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne kadar suskun bir dünyada yaşadık

ne farkına vardık yaşadığımızın

ne de yaşamak paylaştı acımızı

ne yanımızı döneceğimizi bilemedik güneşe

ne nefesler soğudu ayaz gecelerde

ne kristal heykelcikler oluştu kirpiklerimizde

ne çok dargınlıklar yığıldı ki üstümüze

ne farkına vardık yaşadığımızın

ne de yaşamak azalttı acımızı

ne dipsiz ummanı boylamış ki teknemiz

ne güzel günleri görmeden geçirmişiz

ne sedefler birikmiş ki üstümüze

ne saklı incilerle saklanmışız

ne vurgun mavisi girmiş ki kalbimize

ne ise uyandıramamış bizi yıllardır

ne karanlık mürekep boşaltmış balıklar

ne zamandır açılmamış denizin gökyüzü

ne dipsiz ummana batmış ki teknemiz

ne güneşli günler kaçırılmış bi temiz', 'ne kadar suskun bir dünyada yaşadık ne farkına vardık yaşadığımızın ne de yaşamak paylaştı acımızı ne yanımızı döneceğimizi bilemedik güneşe...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/denizin-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğrafa Bakarak', 'fotografa-bakarak-asli-durak-fm49l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'birazı kış bu resmin

kalanı yaz

evler begonvil giyinmiş

pervazlar beyaz

ışık öyle kırılmış ki

sanki buz tutmuş havuz

kadının teni

sonbaharın kızılından yaza soyunmuş

yüzünde birikmiş güzlerin hüznü

doğrular yanlışlarda boğulmuş

siyah mı en kötüymüş? 

beyaz mı çabucak kirli? 

çözülememiş düğüm

açılamamış kutu..

bu yüzden mi bakışı

böyle gride tutuklu?', 'birazı kış bu resmin kalanı yaz evler begonvil giyinmiş pervazlar beyaz ışık öyle kırılmış ki sanki buz tutmuş havuz kadının teni sonbaharın...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fotografa-bakarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-ethem-vayvayli-z3577', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Sezai Karakoç''a-

Sevda lambalara tutunan kar çiçeği

Zayıf ve sarı  benizli yoksul bir çocuk

İçimde dinyandan varolan diriliş resmi

Ellerin rüyanın kanatları,ince ve pamuk

Sevda lambalara tutunan kar çiçeği

Erkenden gelir bu geceye iğri yağmur

Bir geceyi devirir tutar kanadından kuş

Gözlerin kalbimin kırsalında en derin uykusunu uyur

Öter her gece karanlığa karşı baykuş

Erkenden gelir bu geceye iğri yağmur

Kırılır köy deresinde unutulan ay ışkları

Bir damlada buluşan hayatlarımız barışır

Dolaşır hayallerin zülfünde kelebek ayakları

Elleri yıldızları kalbimize taşır

Kırılır köy deresinde unutulan ay ışıkları', '-Sezai Karakoç''a- Sevda lambalara tutunan kar çiçeği Zayıf ve sarı  benizli yoksul bir çocuk İçimde dinyandan varolan diriliş resmi Ellerin ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızları söndürmüş fırtına', 'yildizlari-sondurmus-firtina-cemil-meric-89if0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızları söndürmüş fırtına

Batan bir gemidesin

Senden ne kalacak yarına

Kıyılardan imdat isteyen,sesin', 'Yıldızları söndürmüş fırtına Batan bir gemidesin Senden ne kalacak yarına Kıyılardan imdat isteyen,sesin...', ARRAY['Türk Edebiyatı','Şiir','Cemil Meriç']::text[], 8.5, '{"poet":"Cemil Meriç","poet_slug":"cemil-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yildizlari-sondurmus-firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendin Sanarak', 'kendin-sanarak-asli-durak-4mt1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kapandı bir kitap daha

yorumsuz kaldı satır araları

öksede saka mıydı bu kadın? 

isyanın sularında şimdi böyle başı dik

sen yine iklimleri kendin kılarak git

gün gelir hatırlanır belki:

hiç bir şeyi anlamak için aşıp geldik her şeyi 

ve yok artık kendimizden başka geçeceğimiz

dercesine yaşadık biz...

göğüs kafesinde çırpınırdı tutsak bir kuş

şaşardık nasıl da unutmuştuk derin ürperişleri

sen belki de hiç bilmeden 

öperdin incinmişliğimi..

aradığımız ne varsa şimdi uzak ve yabancı

boşuna mı tutunduk umudun gök kuşağına

yine dolduramadı boş kareleri 

umarsızca beklenen 

bilmece tutkunu birileri

ben

yine

nereye göç etti kuşların

ey yitik ülke derim kendime

süzülürüm direnişin sularında başım dik

sen

iklimleri kendin sanarak

git.', 'kapandı bir kitap daha yorumsuz kaldı satır araları öksede saka mıydı bu kadın?  isyanın sularında şimdi böyle başı dik sen yine iklimleri k...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kendin-sanarak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmihlal', 'i-zmihlal-necati-karaman-hipzm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter artık bu milletle fazla oynamayın

Kendi elinizle kendi kuyunuzu kazmayın

Tarihin süzgeçinden geçmiştir bunun encamı

Suskun durduysa millet bunu gaflet sanmayın

Bu imana bu mefkure bir sel gibi akmakta

Gönlümüzdeki heyecan şimşek gibi çakmakta

Biz biliriz yolumuzu düşmandan rehber gerekmez

Bir kükredik mi artık bize bu ufuklar yetmez

Tarihten alıp ilhamı yöneliriz istikbale

Yürüyen sürüye saldıranı almayız kaale

Bizimle fazla uğraşmak kimseye fayda vermez

Ezemez kimse bizi sokamaz izmihlale', 'Yeter artık bu milletle fazla oynamayın Kendi elinizle kendi kuyunuzu kazmayın Tarihin süzgeçinden geçmiştir bunun encamı Suskun durduysa mi...', ARRAY['Türk Edebiyatı','Şiir','Necati Karaman']::text[], 8.5, '{"poet":"Necati Karaman","poet_slug":"necati-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/izmihlal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyorsun', 'guluyorsun-ethem-vayvayli-q5ro6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ikindi gölgesi gibi

Uzuyor,uzuyor,uzuyorsun

Sonra tüm bedeninle

Bir şehre giriyorsun

                 gülüyorsun

Parmak uçlarından geçen nehir

Yüreğine demirleyen o ölüm vurgunu gülüşler

Umursama vuslatı;

                                üç belki beşgünlük zehir

Daha içirir ayrılık deminde', 'Bir ikindi gölgesi gibi Uzuyor,uzuyor,uzuyorsun Sonra tüm bedeninle Bir şehre giriyorsun                  gülüyorsun Parmak uçlarından geçen...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guluyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sergerde Gidiş', 'sergerde-gidis-necati-karaman-x0ypz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağa sola bakma sen mesul olan kişisin

Çağladığın tarihin yarın ki öyküsüsün 

Yokuşta sanma yolu çoktan geçmiş inişe

Topyekün dur diyelim bu bigane gidişe

Tarihse senin adın istikbaldir kanadın 

Görse elbet ağlardı o kahraman ecdadın

Arz ve sema hayrandı o sendeki sezişe

Nasıl ilgisiz kaldın bu pejmurde gidişe

Kimden korkarsın bilmem hak daim yanındadır

Ol serverin bakışı her zaman karşındadır

Sığın ve güven ona o muindir her işe

Yeter artık sen dur de bu keşmekeş gidişe

Toplumda okuma aşkı gittikçe azalıyor

Gönüldeki boşluklar ufka tasa sarıyor

Bir yerden başlamalı düzeltmek için işe

Hep birden dur demeli bu sergerde gidişe', 'Sağa sola bakma sen mesul olan kişisin Çağladığın tarihin yarın ki öyküsüsün  Yokuşta sanma yolu çoktan geçmiş inişe Topyekün dur diyelim bu...', ARRAY['Türk Edebiyatı','Şiir','Necati Karaman']::text[], 8.5, '{"poet":"Necati Karaman","poet_slug":"necati-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sergerde-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patişahım ve Gerçeğim', 'patisahim-ve-gercegim-ethem-vayvayli-rc5rh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Nun Masalları''na-

Gölgede kan kıprıyor

Kanda mavi kelebekler

Arkasında ben varım

Ben ve patişahım

Gerçeğim ve gül kurusu

Bir ufkun gün güzeli

Parmakları kana değdi

Kanadı yalnız geceler

Yalnız ve yanıldık şeyler

Düşünmez misin laleyi

Yanıp sönen pencereyi

İçinde kirmen eğrisi

Kaşların bölünür ya

O yere eğdiğin kaşların

O sehere değin kaşların

Unutma bu kez mezarına

Bir yıllığına beni ek

Beni ve patişahımı

Avuç avuç,tek tek', '-Nun Masalları''na- Gölgede kan kıprıyor Kanda mavi kelebekler Arkasında ben varım Ben ve patişahım Gerçeğim ve gül kurusu Bir ufkun gün güze...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/patisahim-ve-gercegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ethem-vayvayli-5v5a1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk dediğin nedir ki

Tenden bedenden sıyrık

Çocukların içinde 

Yaşadığı bir çığlık

Aşk dediğin nedir ki

Histen nefesten varlık

Umutsuzluk içinde 

Karanlığa son ıslık', 'Aşk dediğin nedir ki Tenden bedenden sıyrık Çocukların içinde  Yaşadığı bir çığlık Aşk dediğin nedir ki Histen nefesten varlık Umutsuzluk iç...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-halil-silan-17f5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanadına bir gülün eller

                             Ellerin dokunmus, kırmızı deniz 

                                                                Yesil deniz

                             Basımı dizlerinde unutmusum

                             Bir uykudayım simdi senli sen renkli

                             Dokunuyorsun alnıma ellerinle

                             Kırılıp kalıyor içimde seslerin kalbi

                             Üstüste birikiyor yalnızlık birden, oysa

                             Biliyorum basımı dizlerinde unutmusum

                             Ve silemiyor gözlerimden sen, kara deniz

                                                                                     Mor deniz

                             Ellerim ellerim diyor, aglıyorsun

                             Sesinin kırılmıs kenarına bakıyor, aglıyorum

                             Istemiyor hiçbir kus hiçbir agacı

                             Kuslar konuyor saçlarına artık aglama

                             Ellerim ellerim diyor aglıyorsun, aglama

                         Istersen basım dizlerinde ellerin alnımda kalsın

                             Bir yer var bir sen var bir ben var

                             Bir ellerin bir deniz bir kuslar

                             Aglama artık !

                             Annem duyar, konukomsu duyar sonra

                             Kuslar deniz gelmez

                             Issız kalırız sen ben biz...', 'Kanadına bir gülün eller                              Ellerin dokunmus, kırmızı deniz                                                       ...', ARRAY['Türk Edebiyatı','Şiir','Halil Şilan']::text[], 8.5, '{"poet":"Halil Şilan","poet_slug":"halil-silan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ellerin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Ufuk', 'derin-ufuk-necati-karaman-doi4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İman asli cevherin ufkun derin mi derin

Tarihteki nevayı inlemede sözlerin

Bu keşmekeş ahvali sergiledikçe günler

Maziyi hal içinde görmek ister gözlerin

Gün peşpese uçuyor ömür ne tez geçiyor

Hercai olan kalpler her gün bir yön seçiyor

Geçmiş hayat sayfanı çevirdikçe mevsimler

Yüklenmiş maziyi hal kıvrılarak gidiyor

Dağ yüce ova engin değişim rengin rengin

Hedef sana ram olur eğer buluşsan dengin

Rehberin olmasın ha sakın mutsuz gönüller

Yol almak kolay olur gönlün olmuşsa zengin

Gel ey rehber-i hayat ahvâl berbat mı berbat

Senden uzak durdukça olduk böyle malamat

Toplumu altüst etti bu meymenesiz yüzler

Tek ümidimiz sensin lütfunla eyle imdat', 'İman asli cevherin ufkun derin mi derin Tarihteki nevayı inlemede sözlerin Bu keşmekeş ahvali sergiledikçe günler Maziyi hal içinde görmek i...', ARRAY['Türk Edebiyatı','Şiir','Necati Karaman']::text[], 8.5, '{"poet":"Necati Karaman","poet_slug":"necati-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derin-ufuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-halil-silan-eky3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gittin !

Saçlarıma kırlangıçlar konsun istedim

                        

Gittin !

Üç gün üç gece oldu sensizliğim

Sensizliğin her soluğuna sessizliği ekledim

                         

Gittin !

Geceydi karanlıktı yağmur kusuyordu gökyüzü           Yüzümde kurumamış ayrılık acısı                               Yüreğimde yakılmaya hazır türküler bıraktın

Gittin !

Ne varsa sana ait bavulunda arkana bakmadan                Yüreğimin aynasından suretini çalarak                                Seni benden uzaklaştıran her adımında gözümü kırptım

Yalnızlıktan, geceden, dumandan usulca içime aktın

Gittin !

Bir bakışın bende kaldı bir de gülüşün

Susuşlarıma yükledim aşkımı ardından gönderdim                  “ Bir değeri olsun istedim sensizliğin bir anlamı”

Bir seni sevdim ben en çok seni

Sözüm söz bir seni özleyeceğim ben en çok seni', 'Gittin ! Saçlarıma kırlangıçlar konsun istedim                          Gittin ! Üç gün üç gece oldu sensizliğim Sensizliğin her soluğuna se...', ARRAY['Türk Edebiyatı','Şiir','Halil Şilan']::text[], 8.5, '{"poet":"Halil Şilan","poet_slug":"halil-silan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gittin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzeye Gidiyoruz', 'kuzeye-gidiyoruz-ingeborg-bachmann-91hzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarkı söylüyoruz,göğsümüzdeki ezgiyi

Orada,hiçbir zaman çıkmadı.

Yalnızca kimileyin bildi biri.

Kimse bizi kalmaya zorlamadı.

Duruyoruz.Kesiyoruz adımlarımızı

Yoksa sonu da bozulur

Gözlerimizi tanrıya çeviriyoruz.

Biz istedik bunca ayrılığı.', 'Şarkı söylüyoruz,göğsümüzdeki ezgiyi Orada,hiçbir zaman çıkmadı. Yalnızca kimileyin bildi biri. Kimse bizi kalmaya zorlamadı. Duruyoruz.Kesi...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg-bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kuzeye-gidiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Zaman', 'dar-zaman-ingeborg-bachmann-4z0zw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha katı günler yolda,yakın

Dönekliğe ayarlanmış zamanlar

Görünür gitgide çevren çizgisinde.

Çekip bağlarsın yakında ayakkabılarını,

Köpekleri avlularına geri kovarsın

Balıkların içi

Çoktan buza kesmiştir.Çünki yelde.

Yoksulca yanar ışığı kandillerin

Sisi tarar bakışların.

Dönekliğe ayarlanmış zamanlar

Görünür gitgide çevren çizgisinde', 'Daha katı günler yolda,yakın Dönekliğe ayarlanmış zamanlar Görünür gitgide çevren çizgisinde. Çekip bağlarsın yakında ayakkabılarını, Köpekl...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg-bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dar-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sempati', 'sempati-ozdemir-asaf-xz743', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yaprak, ağaca takma.

Bir damla, buluta takma.

Bir bulut, maviye takma.

Bir yağmur, havaya takma.

 Ben sana bakıyorum,

 Bir rüzgâr esiyor.

 Sözü uzatıyorum,

 Ben, sana takma.', 'Bir yaprak, ağaca takma. Bir damla, buluta takma. Bir bulut, maviye takma. Bir yağmur, havaya takma.  Ben sana bakıyorum,  Bir rüzgâr esiyor...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sempati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Bir Geziye Çıkalım', 'haydi-bir-geziye-cikalim-ingeborg-bachmann-wwrsu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi bir geziye çıkalım

Haydi selviler altında

ya da palmiyeler altında

ya da narenciye bahçelerinde

Ucuzlatılmış fiyatlarta gün batımlarını izleyelim

Eşi benzeri olmayan günbatımlarını', 'Haydi bir geziye çıkalım Haydi selviler altında ya da palmiyeler altında ya da narenciye bahçelerinde Ucuzlatılmış fiyatlarta gün batımların...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg-bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/haydi-bir-geziye-cikalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadululuyum', 'anadululuyum-i-lker-polat-4mrm0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anadoluluyum.

Deniz görmedim, dalga bilmem.

İlk sözüm, son sözümdür.

Azrail gelse dönmem,

Dönemem.', 'Anadoluluyum. Deniz görmedim, dalga bilmem. İlk sözüm, son sözümdür. Azrail gelse dönmem, Dönemem....', ARRAY['Türk Edebiyatı','Şiir','İlker Polat']::text[], 8.5, '{"poet":"İlker Polat","poet_slug":"i-lker-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/anadululuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandırmak İçin Seni', 'uyandirmak-i-cin-seni-ayten-mutlu-ftwu0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uyandırmak için seni

ayışığı sonatından geceyi çaldım

ıssız bir şehre gittim hiç gitmediğin

sessizliğe bilmediğin şiirler fısıldadım

rüzgârların dindiği kıyılarda

öykünü dinledim ıslak kumlardan

deniz uyuyordu ayak ucunda

aramızda tüy gibi uçarken zaman

aralık perdelerden yüzüne düşen

ayın tenha seslerini okşadım

açıklarda yitmiş bir yelkenliden

eğilip sulara gölgeni öptüm

kimsesiz çocukların ince parmaklarıyla

dokundum düşlerinin kırılmış aynasına

eski resimlerin soluk çizgilerinden

ellerini seyrettim mağaralarda

uyandırmak için seni

bütün geçmişini yeniden yazdım

bir gül iliştirip yalnızlığına

unuttum ne varsa unutmadığın

uçucu bir kokuyla sardım yalnızlığını

bir dağ gecesi gibi ürperdi tenin

soluğundan soluğuma uzanan

uzun bir yol diledim

uyandırmak için seni 

alnına solgun düşen saçlarını seyrettim

sonsuzluğu çağırdım avuçlarından

kayan bir yıldız gibi ölürken kalbim', 'uyandırmak için seni ayışığı sonatından geceyi çaldım ıssız bir şehre gittim hiç gitmediğin sessizliğe bilmediğin şiirler fısıldadım rüzgârl...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uyandirmak-icin-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Gibi', 'ruzgar-gibi-serhan-karaduman-cul6z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tenimi  okşardı  akşam  rüzgarı

Koltuğumun  yaşlı  kollarına  tutunurdum

Ansızın  çıkagelen  rüzgar içimi  gıcıklardı

Avucumu  açtığımda  hep  bir  gül  yaprağı karşılardı  beni...

Kokusu  sen  gibi...

Keskın  ama  yıldırmadı

Karşısında  duramadığım  yüzün  gibi

Güzel  ama  acımasızdı.

Artık  bütün  pencereleri  açar  oldum.

Biliyormusun ceryan yapıyor aşkın

Bunu  ancak  öldüğümde  anladım..', 'Tenimi  okşardı  akşam  rüzgarı Koltuğumun  yaşlı  kollarına  tutunurdum Ansızın  çıkagelen  rüzgar içimi  gıcıklardı Avucumu  açtığımda  he...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ruzgar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Dönerim', 'belki-donerim-riza-aslan-0r67c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'belki  dönerim

kayıp yılların ardından

anlamını yitirmiş 

donmuş 

nice eziyetler çekmiş

sabırsız isteksiz 

geçen onca yılın ardından

bittiğinde ve anlat denildiğinde 

bitenene ilişkin hiç bir 

açıklamanın yapılamayacağı bir gün

belki dönerim

belki dönerim 

değişmiş başkalaşmış

içindeki belirsizlik 

hainliğe dönüşmüş

belki dönerim

kendimi bile tanıyamadığım

bir uzaklıkta 

belki dönerim 

döndüğüde kendimi bulamasamda', 'belki  dönerim kayıp yılların ardından anlamını yitirmiş  donmuş  nice eziyetler çekmiş sabırsız isteksiz  geçen onca yılın ardından bittiği...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/belki-donerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-riza-aslan-e6khy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ansızın içimdeki boşluğa 

bir kuşku düştüğünde 

dayanamayıp kendimi vurduğumda

apansız derinliklere

başıboş ve serseri 

düşünmeden düşünemeden 

kendimi parçaladığında 

yapılan eziyetin karşılıksız olduğunu anladığında 

tek taraflı sevdaların hiç bir anlamı 

kalmamıştır artık', 'ansızın içimdeki boşluğa  bir kuşku düştüğünde  dayanamayıp kendimi vurduğumda apansız derinliklere başıboş ve serseri  düşünmeden düşünemed...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ansizin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-serhan-karaduman-c6gpk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki iki damla gözyaşı var gözümde.

Sanki sıksam kendimi dökülecekler.

Bıraksam onlarda terk edecekler.

Hemde bir elveda bile demeden.

Ama ben alıştım yokluklara.

Alıştım ağlamalara.

Ya insanlar? Onlarda alıştılar.

Vurmaya , yıkmaya ,kaçmaya...

Acınmalımı bana bilmemki,

Belkide susmalıyım artık

Öğrenmelimiydim ayrılığı, belkide

Yinede yaşamalıyım

En azından daha kuru bir dalım', 'Sanki iki damla gözyaşı var gözümde. Sanki sıksam kendimi dökülecekler. Bıraksam onlarda terk edecekler. Hemde bir elveda bile demeden. Ama ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayata-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindan', 'zindan-serhan-karaduman-p8i8a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman en iyi ilaçtır dediler,

Ellerimi bağladılar,

Gün yüzü göstermediler,

Acı en iyi ilaç oldu yanlızlığımda,

Bir zindandayım, karanlık mı karanlık,

Bağlıyım o pis kokan ışıksız duvara,

Acele etsemde nafile,

Kaçış yok sokaklara,

Kaçsam ne farkederki, zindan hep yanımda.', 'Zaman en iyi ilaçtır dediler, Ellerimi bağladılar, Gün yüzü göstermediler, Acı en iyi ilaç oldu yanlızlığımda, Bir zindandayım, karanlık mı ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefes Mi?', 'son-nefes-mi-serhan-karaduman-ubbm2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'son nefes,

ayrılıktan öte,

senin aşkın yaramdır bedende,

kapanırmı bilmem zamanla,

yada acır mı daha,

ama bildiğim bir şey varsa oda ,

yolcuyum yürürüm sevda pınarında', 'son nefes, ayrılıktan öte, senin aşkın yaramdır bedende, kapanırmı bilmem zamanla, yada acır mı daha, ama bildiğim bir şey varsa oda , yolcu...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-nefes-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gönlün Sevgili,', 'senin-gonlun-sevgili-onder-karadag-f13kr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senin gönlün sevgili,

dağları kadar yüksek

tüm ovaları gibi geniş dünyanın

ve okyanusları kadar engin

mavi bir ak deniz sıcaklığı

yüzünde sevgisi insanlığın.

Senin ellerin sevgili,

mart ayazının kardelen çiçeği

muştucusu ilk baharın

harmansonu rüzgarı saçların

at koştursun diye çocuklar

ve sıcak ekmek kokusu tenin

karşısında zulmün...', 'senin gönlün sevgili, dağları kadar yüksek tüm ovaları gibi geniş dünyanın ve okyanusları kadar engin mavi bir ak deniz sıcaklığı yüzünde se...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senin-gonlun-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Üstüne', 'olum-ustune-serhan-karaduman-xu2ny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bende öleceğim sonunda,

belki arkamdan ağlayacaklar,

belkide sızlayacaklar,

ama sen suz , sakın ağlama,

sadece ziyarete gel her akşam mezarıma,

bir hafta boyunca hep gel,

sula toparağımı,

son gün elindebir çiçek olsun olurmu,

ve birdaha uğrama ,

o çiçeği toprağıma at öyle git,', 'bende öleceğim sonunda, belki arkamdan ağlayacaklar, belkide sızlayacaklar, ama sen suz , sakın ağlama, sadece ziyarete gel her akşam mezarı...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyevi Şeyler', 'dunyevi-seyler-serhan-karaduman-5e74m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün ağladığında

 en son nezaman güldüğünü düşünürsün

 sayıkladığında aşk diye

 o vefasız surat gelir aklına

 belki çok geçtir

 belkide erken

 ne içinmi?

 seni sewenler için

 sewmeyi bilmeyipte ağlatanlar için

 neden dersin, hayat neden?

 bilmez ki, kaderde bilmez

 sende bilmessin

 kum saati aktıkça

 sen ağlar delirirsin

 söyleyemessin sewdiini ama 

 gözyaşından bellidir

 bilirsin ya

 aşk bir anlık bir şeydir

 acısı gibi uzun sürer 

                     aşk  ölümle eş gibidir

 her aşık sonunda ölür

 ama

 unutma aşık! 

 ölmekte yeniden doğmak gibidir', 'bir gün ağladığında  en son nezaman güldüğünü düşünürsün  sayıkladığında aşk diye  o vefasız surat gelir aklına  belki çok geçtir  belkide e...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dunyevi-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru ve Cevap', 'soru-ve-cevap-necip-fazil-kisakurek-18dqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soru

Bir yumak gibi hayat, kör düğümlerle dolu

Ömür süreli sınav, sonsuz meçhul sorulu

Avutmak mı kendini, yumakla kedi gibi?

Uyumak mı, ölmek mi? Yokmu kurtuluş yolu

Cevap

Bulunmaz sorulara raflarda bazen cevap

Bulunmazsa raflarda âleme rahmet kitap

Düğümlenmiş kalplere, şaraptan beter şarap

Mü''min''e nur afitap zümrüt köşklerin holü', 'Soru Bir yumak gibi hayat, kör düğümlerle dolu Ömür süreli sınav, sonsuz meçhul sorulu Avutmak mı kendini, yumakla kedi gibi? Uyumak mı, ölm...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soru-ve-cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara', 'kara-emin-duru-v5fwu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahmet hiç sevmezdi karayı

Siyah ayakkabı giymezdi

Siyah arabaya binmezdi

İstemezdi kara parayı

Dişlerini karartan sigarayı

Karayollarından nefret ederdi

Denizden havadan giderdi

Çok severdi kara sevda çekmezdi

Tarlasına kara tohum ekmezdi

Yinede Ahmet''e kara çaldılar

Zavallının günahını aldılar

Bu dertten böylece öldü gitti

Beyaz toprağı vasiyet etti.', 'Ahmet hiç sevmezdi karayı Siyah ayakkabı giymezdi Siyah arabaya binmezdi İstemezdi kara parayı Dişlerini karartan sigarayı Karayollarından n...', ARRAY['Türk Edebiyatı','Şiir','Emin Duru']::text[], 8.5, '{"poet":"Emin Duru","poet_slug":"emin-duru","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi Kadar', 'kedi-kadar-fahri-aydos-s3rhc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir kediye gülümsedin

Ben kediyi kıskandım

Sen bir kediyi kucağına alıp sevdin

Ben boş yere umutlandım

Nankör kedi seni bıraktı kaçtı gitti

Ben bir kedi kadar olamadım

1 Nisan 2000', 'Sen bir kediye gülümsedin Ben kediyi kıskandım Sen bir kediyi kucağına alıp sevdin Ben boş yere umutlandım Nankör kedi seni bıraktı kaçtı gi...', ARRAY['Türk Edebiyatı','Şiir','Fahri Aydos']::text[], 8.5, '{"poet":"Fahri Aydos","poet_slug":"fahri-aydos","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kedi-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günsineği ( * )', 'gunsinegi-necip-bozdoganoglu-j549m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen, yıllar sığar bir ömre,

Bazense, bir ömür tek bir güne.

İşte sen ve ben günsineği,

İkimiz de yaşarız bir ömür.

Seninki bir gün, benimki yıllar sürse de

İkisine de bir ömür diyorlar yine de.

Bilemezsin sen asla!

Ayların, yılların da olduğunu.

Belki de onun için yaşarsın

Sadece tek bir sabahta

Benim yıllar süren çocukluğumu.

Ömür uzun da olsa, kısa da

Herkes ölüm korkusunda.

Ben senin gençliğini tüketirim halbuki

Bir tek öğle paydosunda.

Bir de bakmışsın günsineği

Vakit ikindi.

İşte sana sonbahar,

Senin kanatlarına yağmaya başlar artık,

Benim saçlarıma

Kırk beşinde yağan kar.

Akşam olunca günsineği,

Hayal kurarım yıllar ötesine ben.

Seninse ömrün bitiverir,

Güneşin battığını görmeden.

( * ) : Ömrü sadece bir gün olan bir sinek türü', 'Bazen, yıllar sığar bir ömre, Bazense, bir ömür tek bir güne. İşte sen ve ben günsineği, İkimiz de yaşarız bir ömür. Seninki bir gün, benimk...', ARRAY['Türk Edebiyatı','Şiir','Necip Bozdoğanoğlu']::text[], 8.5, '{"poet":"Necip Bozdoğanoğlu","poet_slug":"necip-bozdoganoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gunsinegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardanadam', 'kardanadam-fahri-aydos-z3sc9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne bir bebekteki hayat

Canlı ama yabancı gözleri

Ne bir güzeldeki aşk

Kanı kadar sıcak sözleri

Ölümüne taşır beni güneşe

Kardanadamın ayak izleri

11 Şubat 2000', 'Ne bir bebekteki hayat Canlı ama yabancı gözleri Ne bir güzeldeki aşk Kanı kadar sıcak sözleri Ölümüne taşır beni güneşe Kardanadamın ayak i...', ARRAY['Türk Edebiyatı','Şiir','Fahri Aydos']::text[], 8.5, '{"poet":"Fahri Aydos","poet_slug":"fahri-aydos","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kardanadam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-fahri-aydos-3t9vc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülünce güzel olsun

Ağlayınca masum

Sevinince bebek olsun

Üzülünce anne

Dupduru su olsun

Ateş değince

Çocuk olsun büyüsün

Kurdu sevince

16 Eylül 1999', 'Gülünce güzel olsun Ağlayınca masum Sevinince bebek olsun Üzülünce anne Dupduru su olsun Ateş değince Çocuk olsun büyüsün Kurdu sevince 16 E...', ARRAY['Türk Edebiyatı','Şiir','Fahri Aydos']::text[], 8.5, '{"poet":"Fahri Aydos","poet_slug":"fahri-aydos","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgili-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-mehmet-ozturk-4-tjpgo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni düşünüyorum yine bu akşam

yanımda olsanda yüzüne baksam

ateş olur içim yanar bir kez sarılsam

aşkımı ilan edip herkese duyursam

çıkmıyor bir kes olsun ismin aklımda

senin sevgin damarımda kanımda

aşkın için veririm  iste bu canımıda

seni seviyorum bunu hiç unutma', 'seni düşünüyorum yine bu akşam yanımda olsanda yüzüne baksam ateş olur içim yanar bir kez sarılsam aşkımı ilan edip herkese duyursam çıkmıyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Öztürk 4']::text[], 8.5, '{"poet":"Mehmet Öztürk 4","poet_slug":"mehmet-ozturk-4","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-dusunuyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmin Hayatımdı', 'resmin-hayatimdi-bayram-karaali-jishj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resminde gördüğün fotojenik adammıydım ben,

Ellerini tuttuğumda,tanırmıydın beni?

Heyhatt belki bu değildi beklediğin.

Kadere kırkbeş buna derler bahtına  bu adam.

Kötü; yalnızlığını arayan, belkide adamdı,

Yalnız yapayalnız,göğsünde sığınma arayan

Bir yanlış ,ama ; adam gibi ,bohem ve o kadarda,

Yalnız ve kötülükleriyle yapayalnız bir kötü adam...

Görmek istediğin gibi göremedin beni,

Göremeyeceksinde;bu kötü,yalnız adamı,,,,

Çünkü:O yalnız, Çünkü o kötü,

Sensiz ,seninle görmeye çalışırken dramı....

Arenalarında gördü bu adam,

Savaşmayı,kalleşliği,sırtından vurulmayı,

Bıçağını koynumda istedim oysa;

Yüreğim açık,onurlu dimdik bıçakla dedim.

Yanılgımı, yanlışımı,bir eğrimi saklamadım,

Şiirlerimde yazarken,sesimin tonunu nasılda ayarlamıştım,

Dinlenmeyen  bunlardı,anlatamadım nedense?

Sana yalan söylemedim ben,yalancı olmadım....

İhanet.!!! Alçakça ...dayanmak  nasıl olur...???

Bebeğim;sana : yüreğimin yaylalarından getirdim,

Sadakat denilen bir inanılmazı, neye yarar,

Senindir , bendendir eğer dersen kabul ettim....

24.Aralık.2000', 'Resminde gördüğün fotojenik adammıydım ben, Ellerini tuttuğumda,tanırmıydın beni? Heyhatt belki bu değildi beklediğin. Kadere kırkbeş buna d...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/resmin-hayatimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım İkiledi', 'yalnizligim-i-kiledi-bayram-karaali-lbkp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı bir ben yazarım alabildiğince,

Bir ben bilirim,bir ben yazarım yalnızlığımı,

Sen yoksun,Olamadağın yıllar boyunca,

Bir ben yazarım,yanımda olduğunca.

Ben seni istemiştim oysa ,tükettiğim yıllarımda,

Yoksun,varlığınla;nedense acılarımda,

Ben seni istemiştim,seni;olmadığın kadar,

Ağlamalıyım,Kahretmeliyim seninle sonuna kadar..

Ben sana;bir şey demiştim halbuki;

Sana yalnızlıklarımdan geldim,çırılçıplak,

Gönderme beni,İtme beni,o uzak denizlere,

Boğulup yok olurum,tanımadığım,kulaç atamadığım.

Sensiz deniz ve  nehirlerde...

25.12.2000

Bayram Karaali', 'Yalnızlığımı bir ben yazarım alabildiğince, Bir ben bilirim,bir ben yazarım yalnızlığımı, Sen yoksun,Olamadağın yıllar boyunca, Bir ben yaza...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizligim-ikiledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sen', 'son-sen-kucuk-i-skender-5pzyr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şiddetle ihtiyacım var beni öpmene

dudakların dudaklarımı hacize gelsin

dokun! dokun! dokun etime,

etimle süslensin ardıç gözlerin

akşam olup da delikanlılar siyah giydiler mi

(dışavurumcu zifir ve seni seviyorum)

turuncu soyundu mu orospu karılar ve dönmeler

bir şelale çalarım en yakın vitrin camını kırıp

ceplerimde bahar şiirleri ve ilkokul öğretmenleri

en güzel sesleri çizip anahtarımın kenarıyla

ağlarım! ağlarım ulan sana ne, sen 

soyun -mumları söndür- yatağına uzan!

süte aşkı üfle!(*)', 'şiddetle ihtiyacım var beni öpmene dudakların dudaklarımı hacize gelsin dokun! dokun! dokun etime, etimle süslensin ardıç gözlerin akşam olu...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elini Bana Ver', 'elini-bana-ver-bayram-karaali-wbb6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hemen yanıbaşımda,yakınımdasın ,

Elimi uzatsam dokunabilirim,

Ama:Elim uzanamaz o kadar da uzaksın,

Farkındamısın...??????

Be eyy yar  ne derim sana söyle..??

Elim yetmez sana,gönlüm yetmez sana,

Uzaklarda bırakma beni,itme beni,

Ta uzaklara gömme beni  ağlamaklı...

Gönderme beni bulutlu,karanlık,

Acılarımın ortasına bırakma beni,

Hüznüme ortak,hüznüme  tapınanan,

Yüreğimdeki yalnızlığıma...

Elini ver bana,yüreğinde bir küçük yer,

Sakınırsan,sanmaki  küçülürüm,

Yücelir,yücelir bir daha büyürüm,

Omuzumdaki  sadece bir elin....

24.Aralık.2000', 'Hemen yanıbaşımda,yakınımdasın , Elimi uzatsam dokunabilirim, Ama:Elim uzanamaz o kadar da uzaksın, Farkındamısın...?????? Be eyy yar  ne de...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/elini-bana-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yan Çizdim', 'yan-cizdim-osman-oztunc-ztjd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'On sekiz yaş çağlarımdı

Sokaklarda bu ilk kavgam

Girdim delice dövüştüm

Kimseye bir şey sormadan

İki can bir beden olduk

Bulmuştum o gün sevdamı

Beynimi tırmalıyordu

Okuduğum o son kitap

Yan çizdim 

Jandarmaya hürriyete

Çok sevdiğim bir millete yan çizdim

Yan çizdim

Başım döndü vurdum öldü

Sebep oldu adalete Yan çizdim

Uzun tren raylarında 

Yanıyordu son bir ışık

Alıp götürdüler beni 

Çaremdir çok uzaklarda

On sekiz yaş ilk cigaram

Ağlıyordum gülüyordu

Kurtuluş var var diyordu

Okuduğum o son kitap

Yan çizdim, 

Hem anama Hem babama

Karıma Kızkardaşıma Yan çizdim

Gidiyorum sizin olsun öz yurdum 

Kudurdum, Kudurdum...!', 'On sekiz yaş çağlarımdı Sokaklarda bu ilk kavgam Girdim delice dövüştüm Kimseye bir şey sormadan İki can bir beden olduk Bulmuştum o gün sev...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yan-cizdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor Babam', 'agliyor-babam-osman-oztunc-x0alj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bileğimde kelepçe

Dudağımda sigara

Yaslandığım duvarda

Onun ismi yazılı.

Ağlıyor hep böyle

Ağlıyor gülmez yüzüm.

Ağlama gül bebek

Ağlama iki gözüm.

Bir elinde 14''lü 

Bir elinde güller var

Ağlıyor ağlıyor Babam.

Gözüm gibi karanlık

Sözüm gibi daracık

Yaslandığım odada

Onun resmi kazılı.

Bakıyor hep böyle

Bakıyor rengi solmuş.

Dalıp gidiyor böyle

Yıllar onda kaybolmuş.

Bir elinde  14''lü 

Bir elinde güller var

Ağlıyor ağlıyor Babam.', 'Bileğimde kelepçe Dudağımda sigara Yaslandığım duvarda Onun ismi yazılı. Ağlıyor hep böyle Ağlıyor gülmez yüzüm. Ağlama gül bebek Ağlama iki...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agliyor-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davullar Çalındı', 'davullar-calindi-osman-oztunc-jplky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her zaman gün ortasında gelirlerdi.

Bu sefer gece yarısında geldiler.

Ölçüsüz bir kötülük ve merhametsiz kalplerle geldiler.

Söküldü bütün kapıların kilitleri.

Ve köpeklerle kovalanan bir militan.

İhanetin elleri ensesinde, vurdumduymazlığın elleri ensesinde,

Soluk soluğa, yüreğinde cehennem acıları ile

Koşuyordu tepelere doğru.

Ve bir ayin başlıyordu.

Gecenin ortasında

Gözleri kör, kulakları sağır eden

Kalleşliğin üstüne kalleşlikler ekleyen

Utanmaz bir ayin.

Ve elleri bağrında anneler

Evlatlarını göndermek istemezlerdi 

Yemene gönderir gibi gecenin bir yarısında

Ama biliyorlardı. 

Bu toprak onları kabul eder

Onlar için şahitlik ederdi

Bir mermi sesi karanlığı tam ortasından ikiye böldü

Gecenin derinliğinde cansız bir beden

Helal süt emmiş dudaklardan kan damlıyordu...', 'Her zaman gün ortasında gelirlerdi. Bu sefer gece yarısında geldiler. Ölçüsüz bir kötülük ve merhametsiz kalplerle geldiler. Söküldü bütün k...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/davullar-calindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Adam', 'bu-adam-osman-oztunc-ufcb8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sere serpe bir yağmur gelir üstüne

Ne kadar gamsız bu adam

Sırtında pardesü yüzünde sakal

Ayağında postal adam

Ne kadar solgun, ne kadar mahsun

Yaklaştı yanıma gözgöze geldik

İkimizde tedirgindik.

Bana gelir bana gider, bende güler bu adam

Hep mi ağlayacak bu adam.

Çaresi ben umudu ben, her şeyi ben bir adam

Hep mi ağlayacak bu adam.

Dalından koparılmış bir çiçek gibi

Hep örselenmiş bu adam.

Hesapsız kitapsız halk arasında

Bir beni bulmuş bu adam.

Ne kadar ne kadar benziyor bana

Yaklaştı yanıma göz göze geldik

İkimizde tedirgindik.

Bana gelir bana gider, bende güler bu adam

Hep mi ağlayacak bu adam.

Çaresi ben umudu ben, her şeyi ben bir adam

Hep mi ağlayacak bu adam.', 'Sere serpe bir yağmur gelir üstüne Ne kadar gamsız bu adam Sırtında pardesü yüzünde sakal Ayağında postal adam Ne kadar solgun, ne kadar mah...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sevdiğimde', 'ben-seni-sevdigimde-hayrullah-pasalioglu-0efgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdiğimde 

Yüzünde dalga  dalga

Kırmızı utangaçlık vardı

Ben seni sevdiğimde

Hilalin şekli vardı kaşlarında

Kirazın rengi vardı dudaklarında

Güneşin rengi saklıydı teninde

Ben seni sevdiğimde

Ben seni sevdiğimde

Henüz mevsim başıydı 

Dallara yeni yeni koşuyordu yumrular

Duygu yüklüydü bulutlar 

Yağmur yerine 

Ben seni sevdiğimde

Ben seni sevdiğimde

Sevda şarkıları vardı dillerde 

Sevdaları daha vurmamıştı ayrılık

Sokaklara daha düşmemişti çığlık

Ben seni sevdiğimde

Katran renginde değildi dağlar

Katran rengi yoktu boya kutularında 

Ben seni sevdiğimde

Sevdayı gördüm gözlerinde

Gözbebeklerinin yerinde 

Ben seni sevdiğimde.', 'Ben seni sevdiğimde  Yüzünde dalga  dalga Kırmızı utangaçlık vardı Ben seni sevdiğimde Hilalin şekli vardı kaşlarında Kirazın rengi vardı du...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-seni-sevdigimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Can', 'bir-can-hayrullah-pasalioglu-avox2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir can düştü yola

Sevda yoluna

Bir can düştü çöle

Susadı aşka

Bir can düştü denize

Hasret kaldı sevda bahçesine

Bir can çıktı gurbete

Mola verdi sevda dolu yürekte

Bir can ruha inat

Göğe çırptı kanat

Ulaştı semaya

Girdi duygu yüklü bulutlara

Yağmur oldu

Düştü, Düştü, Düştü

Sevenler diyarına

Bir can aradı aşkı 

Aradı cananı

Aradı mutluluğu

Bir can düştü yola

Sevda yoluna

Mutluluk yoluna

Çok canlar gitti bu uğurda.', 'Bir can düştü yola Sevda yoluna Bir can düştü çöle Susadı aşka Bir can düştü denize Hasret kaldı sevda bahçesine Bir can çıktı gurbete Mola ...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine sen Rümeysa', 'yine-sen-rumeysa-hayrullah-pasalioglu-9jf4e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kopartarak takvim yapraklarını

Ümitsizlik biriktiriyorum

Aşksız kalbim put kesilmiş

Damla damla kan sızıyor 

Her damla aşkın acı veren yanı

Bendeki aşk başıbozuk bir duygu

İçimde kaynayan tezatlar kazanı

İçinde aşk, acı, mutluluk ve kan

Derdime derman değil zaman

Eğer bu yaşadığım hayatsa

Sürüklenen rüyalarıma

Giripte sürüklenme RÜMEYSA

İçimde gökkuşağı, senden bana uzanır

Bağlanmaz ruhum, tanımaz sınır

Eyyüb’ün kurtları kemirsinler içimi

Dokunmasınlar kemirmesinler dilimi

Çünkü sana

Seni sevdiğimi söyleyeceğim

Taşta açan çiçeğe şahit olacaksın.

Eğer aşık duygularım intihar ederse 

Beni Nemrut’un  ateşinde yak

Yusuf’un kuyusuna at

Duvarları kederi özümleyen

Gündüzün bile geceden öteye gitmediği

Canilerle aynı saftaki zindanlara at.

Bu gönül sensiz olacağına

Değirmene taş olsun RÜMEYSA.', 'Kopartarak takvim yapraklarını Ümitsizlik biriktiriyorum Aşksız kalbim put kesilmiş Damla damla kan sızıyor  Her damla aşkın acı veren yanı ...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yine-sen-rumeysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla Sureti', 'leyla-sureti-hayrullah-pasalioglu-5rs8y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki dağlar şehirlere yürür

Sular akar oluklardan inatla

Ey Leyla’nın sureti gittiğin yere beni de götür

O an sevenler diyarına uçarız bir çift kanatla

Aşksız kalmış beş yapraklı gonca

Duygu yoğunluğu koparılan her yaprakta

Ey vefasız söyle; yaşar mı çiçek koparılınca

Sensiz gönül yaşar mı, yaratıldığı toprakta

Bir teselli var mı rüzgarın ıslığında

Doğru mu? Kaç varmış gönül dağında

Seni seven kaç kişi var solunda sağında

Benden başka ey Leyla''nın sureti.', 'Yüreğimdeki dağlar şehirlere yürür Sular akar oluklardan inatla Ey Leyla’nın sureti gittiğin yere beni de götür O an sevenler diyarına uçarı...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/leyla-sureti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelene Ağıt', 'kardelene-agit-hayrullah-pasalioglu-eohga', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kara kalem beyaz kağıt

Yalnız analar mı yakar ağıt

Aşk dolu sitemli sözlerimi

Gör ağıtlarımda KARDELENÇİÇEĞİ

Ağıt , kalem beyaz kağıt

Merhamet var her anada

Her dişide, dişi kurtta, kanaryada

Aşkla dolu nemli gözlerimi

Merhametinle sil KARDELENÇİÇEĞİ

Merhamet vardır, her dişide,  her anada

Gün gece, zaman böyle geçer

Hayat basamakları çıkılır birer ikişer

Bitmeden ömür, ben olmadan deli

Gel artık bana KARDELENÇİÇEĞİ

Çünkü zaman hızlı hızlı geçer.

Suçum neydi Allah''ım işledim bu günahı

Unutma kardelenim arşa çıkar sevenin âhı

Yap bir sevap, sende sev beni

Benimle gülsün yüzün KARDELENÇİÇEĞİ

Senin için çekerim her cezayı, her cefayı

Aşk kurbanıyım sana adandım

Dayanıyor bıçak kemiğe adım adım 

Yok mu? duygularında  bana yer 

KARDELENÇİÇEĞİ kalbinde bana da yer ver

Senin kurbanınım sana adandım 

Sevda şarkıları böler uykumu 

Sensiz gecelerin gelmez sonu

Yorgun gözlerimde aşkın dertleri 

Bitir dertlerimi KARDELENÇİÇEĞİ 

Dertli şarkılar böler uykumu

Bülbül güllere olmuş aşık

Hayallerim duygularım karmakarışık 

Bu karışıklıkta kaybettim kendimi

Ara bul beni KARDELENÇİÇEĞİ

Bülbül güle,  ben sana aşık 



Gündüzlerim yok, geceler kara leke

Aşk yolunda yürürüm seke seke

Hayatı yaşamak, aşkı, her şeyi

Yalnız seninle olur KARDELENÇİÇEĞİ

Sensiz günü napayım, geceler kara leke

Durgun sularda derinlere bak

Orda göreceksin aşkımı, ak ve pak

Oysa yüzümde aşkın ızdırap çizgileri

Sil onları sil KARDELENÇİÇEĞİ

Aşkım derinlerde,  derinlere bak.

Bir yavrunun dramıyla ağlarsa dünya

Anlatsam! derdimle taşar Sakarya 

Bir sen göremedin şu halimi 

Aç gözlerini de bak KARDELENÇİÇEĞİ

Bir feryat etsem çınlar dünya

Gel artık zamansız, bir iş dönüşü 

Gel öğle vakti veya bir akşam üstü

Ansızın gir kapıdan içeri 

Dönmemek üzere KARDELENÇİÇEĞİ

Gel artık zamansız, bir iş dönüşü

Kuşlar uçmuyor, gök sisli

Katran rengi çayımın buğulu kiri

Gönlümü çalan, vefasız sevgili 

Sevgimi anlamayan KARDELENÇİÇEĞİ

Sensiz hayat sisli, gök sisli.

Bilirmisin kardelenler nerede açar 

Açmak için beklemez gelsin diye bahar

Munzur’un Torosların doruklarında

Karlı dağlarda açar KARDELENÇİÇEĞİ

Buz koyduğun gönül dağlarımda açar.

Kara kalem beyaz kağıt

Yalnız analar mı yakar ağıt

Aşk dolu sitemli sözlerimi

Gör ağıtlarımda KARDELENÇİÇEĞİ

Kara kız işte sana yaktığım ağıt 

Kara kader, işte sana yaktığım ağıt.', 'Kara kalem beyaz kağıt Yalnız analar mı yakar ağıt Aşk dolu sitemli sözlerimi Gör ağıtlarımda KARDELENÇİÇEĞİ Ağıt , kalem beyaz kağıt Merham...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/kardelene-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen Çiçeğim', 'kardelen-cicegim-hayrullah-pasalioglu-ndd58', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KARDELEN ÇİÇEĞİM

Sana olan duygularım haramdan uzak

Aşkım anaların sütü gibi ak ve pak

Dileğim ölene dek seninle yaşamak

Sen de seversen beni KARDELEN ÇİÇEĞİM

Şüphen olmasın sevginle dolu gönlümden

Acı, sevgi dolu yüreğimi delmeden

Seven kalbim “eyvah”  demeden

Sen de sev artık beni KARDELEN ÇİÇEĞİM

Yok sözlerimde yalan, yok yüreğimde kir

Onca ağıt, onca söz, hepsi sana dair

Mecnun’lar Leyla’lar beni sevenler bilir

Ben seni seviyorum KARDELEN ÇİÇEĞİM', 'KARDELEN ÇİÇEĞİM Sana olan duygularım haramdan uzak Aşkım anaların sütü gibi ak ve pak Dileğim ölene dek seninle yaşamak Sen de seversen ben...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kardelen-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sevdim Seni', 've-sevdim-seni-hayrullah-pasalioglu-krv81', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cesaretimin kurbanı oldum

Seni severken

Kalbimdeki ihtiyaçtın

Sen umutsuzluğun umuduydun

Sevgiye muhtaçtın

Ve sevdim seni

Gururumu kurşuna dizdim

Seni severken

Köklerin toprağa bağlanışı gibi

Bağlandım sana

Tüm köklerin inadına

Ve sevdim seni

Aşkımı kalbime kilitledim

Seni severken

Sen Leyla oldun 

Ben Mecnunu yaşadım

Ve sevdim seni.', 'Cesaretimin kurbanı oldum Seni severken Kalbimdeki ihtiyaçtın Sen umutsuzluğun umuduydun Sevgiye muhtaçtın Ve sevdim seni Gururumu kurşuna d...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ve-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Mektup Gibi', 'anneme-mektup-gibi-hayrullah-pasalioglu-ntxqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine ben varım duanda  

 değilmi anne

Yine beni düşünüyorsun şu anda

değilmi anne

Düşünmekle mi geçiyor gecen gündüzün

beni anne

Bırak üzülmeyi, benide üzüyor üzüntün

beni de anne

Gurbetin dağları var aramızda

biliyorsun anne

Sebepler mani oluyor kavuşmamıza 

biliyorsun anne

Gözlerin yine yaşlı,  yine kanlı 

bildim mi anne

Hasretten gönül dağların karlı

bildim mi anne

Ben sensiz, sen bensiz, perişan

bir haldeyiz anne

Bir gün kavuşma umuduyla yanan 

bir haldeyiz anne.', 'Yine ben varım duanda    değilmi anne Yine beni düşünüyorsun şu anda değilmi anne Düşünmekle mi geçiyor gecen gündüzün beni anne Bırak üzülm...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anneme-mektup-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz', 'uykusuz-muveddet-turkugur-fpnnw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siz uyuyorsunuz dostum

Ben uykusuzum...

Geceden güne köprü kuruyorum

Köprünün altında uyukluyorum..', 'Siz uyuyorsunuz dostum Ben uykusuzum... Geceden güne köprü kuruyorum Köprünün altında uyukluyorum.....', ARRAY['Türk Edebiyatı','Şiir','Müveddet Türkuğur']::text[], 8.5, '{"poet":"Müveddet Türkuğur","poet_slug":"muveddet-turkugur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uykusuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En İyisi...', 'en-i-yisi-kemal-ural-5ewcg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağ tepesinde bir çam olamazsan

Vadide bir çalı ol,

Fakat oradaki en iyi küçük çalı Sen olmalısın....

Çalı olamazsan bir ot parçası ol,

Bir yola neşe ver.

Bir misk çiçeği olamazsan bir saz ol

Fakat gölün içindeki en canlı saz Sen olmalısın...

Hepimiz kaptan olamayız,tayfa olmaya mecburuz

Dünyada hepimiz için birer şey var

Yapılacak büyük işler,küçük işler var

Yapacağınız iş,size en yakın olan iştir...

Cadde olamazsan patika ol

Güneş olamazsan yıldız ol

Kazanmak ya da kaybetmek ölçü ile değildir

Sen her ne isen,onun en iyisi olmalısın!', 'Dağ tepesinde bir çam olamazsan Vadide bir çalı ol, Fakat oradaki en iyi küçük çalı Sen olmalısın.... Çalı olamazsan bir ot parçası ol, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Ural']::text[], 8.5, '{"poet":"Kemal Ural","poet_slug":"kemal-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/en-iyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İnsan!', 'ey-i-nsan-kemal-ural-wrhlm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey insan!

Yeri doldurulamayacak bir enstrümansın sen de........

Yerini,görevini,değerini iyi bil.....

Kendine ait parçayı çalmak için,

Bu muhteşem konserde

koş sen de yerini al..

Ey insan!

Dışta kalmamalısın...

''Flüt nerede?'' diyen sesi

sürekli duymalısın...

Eğer bu ahenkten kopar da ayrılırsan,

Hiçliğin ortasında

yapayalnız kalırsın.....

Bir rüya gibi geçer burada günlerimiz...

Yerini,görevini,değerini iyi bil...

İnsanın çalacağı parça

ONUN GERİDE BIRAKABİLECEĞİ TEK İZ!!!....', 'Ey insan! Yeri doldurulamayacak bir enstrümansın sen de........ Yerini,görevini,değerini iyi bil..... Kendine ait parçayı çalmak için, Bu mu...', ARRAY['Türk Edebiyatı','Şiir','Kemal Ural']::text[], 8.5, '{"poet":"Kemal Ural","poet_slug":"kemal-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-insan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Şey...', 'kucuk-sey-kemal-ural-ojn8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçük şey bir önsezi

Küçük şey bir uyarı

Küçük şeydir hayata,hayat veren öğreti...

Küçük şey,basamakları sırayla çıkmada metot

Küçük şey amacı açıklayan şifredir...

Küçük şey sevgi ve huzur ortamına katkı;

Bazen de felakete sefalete nedendir...

Küçük şeyler bir yerde ''tarih'' olur konuşur

Küçük şeyler bir yerde ''haliç'' olur kokuşur

Bazen de başkaldırır ''kanser''olur korkutur

Bakarsın küçük şeyler güneş olur gülümser,

Bir başka yerde ise,fırtına olur sarsar...

Sonra da ''Herşeyin bedeli vardır'' gerçeğine,

gelir imzasını atar..................', 'Küçük şey bir önsezi Küçük şey bir uyarı Küçük şeydir hayata,hayat veren öğreti... Küçük şey,basamakları sırayla çıkmada metot Küçük şey ama...', ARRAY['Türk Edebiyatı','Şiir','Kemal Ural']::text[], 8.5, '{"poet":"Kemal Ural","poet_slug":"kemal-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kucuk-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seç Al', 'sec-al-kemal-ural-dqjz4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oyun başlamış,herkes rol almış,yollar ayrılmış,

     Seç  al!   Seç  al!

Gündüz geceyle,iyi kötüyle komşu; o, bu ya da şu.

     Seç  al!  Seç  al!

Durmadan yanıp sönüyor,trafik lambaları,özgür iraden var.

     Seç  al!  Seç  al!

Sevgi ve nefret,zulüm adalet,erdem ve günah.

     Seç  al!  Seç  al!

Bir kum saatidir hayat,gittikçe ıssızlaşır,geride bir rüya kalır.

     Seç  al!  Seç  al!

Hayat yanlışlıklar,aldanışlarla dolu,soru sor,cevap ara.

     Seç  al!  Seç  al!

Davranışlarımız,bizim kim olduğumuzu söyler,soru sor,cevap ara

            Seç  al!  Seç  al!

Mektubun altına atılan imza,soru sor,cevap ara.

     Seç  al!  Seç  al!

Bize not verilecek,son fırsatı yakala.

     Seç  al!  Seç  al!

Orkestrayı yönetecek küçük çocuk büyüyor;zaman daralıp,kısalıp küçülüyor.

           Seç  al!  Seç  al!

Durmaz yol alır günler,harman mevsimine.

     Seç  al!  Seç  al!

''Hesap'' , ''hesap''  diye uğulduyor bir rüzgar.

     Seç  al!  Seç  al!

Güneş batıyor...Ömür geçiyor..Fırsat bitiyor.

     Seç  al!  Seç  al!

Almak değil,seçmektir hüner.

     Seç  al!  Seç  al!

Durmadan açılıyor,kapanıyor sınavlar..

Hep aynı yanlışlar tekrarlanıp duruyor..

Her şey tohumların şarkısıdır dinlersen! 

   

     Seç  al!  Seç  al!', 'Oyun başlamış,herkes rol almış,yollar ayrılmış,      Seç  al!   Seç  al! Gündüz geceyle,iyi kötüyle komşu; o, bu ya da şu.      Seç  al!  Se...', ARRAY['Türk Edebiyatı','Şiir','Kemal Ural']::text[], 8.5, '{"poet":"Kemal Ural","poet_slug":"kemal-ural","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sec-al-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kent Öldürüldü Diyorlar', 'bu-kent-olduruldu-diyorlar-ahmet-telli-68r1p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kent öldürüldü diyorlar

Kurşuna dizildi bir gece yarısı

Hayaletler geziniyormuş şimdi

Sokak aralarında ve caddelerde

Baykuş tüneği olmuş alanlar

Ve yarasalar uçuşuyormuş...

Silah ve esrar kaçakçıları 

Altın çağını yaşarlarken

Artıyormuş bir yandan da

Kumarhaneler,meyhaneler

Borsa oyunları hileli iflaslar 

Birbirini kovalayıp dururken 

Nasıl çıkmışsa pek bilinmiyor 

Yaygınmış şimdilerde rus ruleti

İntiharların sayısı bilinmiyor

Çoğalıp duruyormus fahişeler

Ve artık bunların hiç biri 

Olay bile sayılnıyormuş şimdi

Bu kent öldürüldü diyorlar

Bahar gelmez artık buraya

Bir kent nasıl öldürülür göz göre göre

Ben inanmıyorum kim ne derse desin

Sodon ve Gomore efsanelerde kaldı

Yaşanan bir başka tarih şimdi

Şöyle bir dokunsak toprağa yalın ayak

Duyacağiz belki tarihin akışını

Baharda gecikebilir unutmayalım

Böyle okuduk tarihin kitaplarından

Hele vakit gelsin,sevda dal versin

Uzanacağiz bir sabah çiçekli bir ağaca

Unutmayalım aşkın sımsıcaklığını

Suskun bekleyişlerini varoşların

Kitapları,fabrikaları unutmayalım

Unutmayalım dağların öyküsünü

Zincirlerini kırmasını bilir bir kent

Aovrayı unutmayalım

Kışlık saray ne kadar dayanabilir

Hayatı kollamasını bilenlere

Ölüm suretini gezdiren serseriler

Sızıp kalacaklar birazdan

Ve bir tül gibi yırtılırken çevren

Bu kent yeniden yaşanacaktır

Bir kent nasıl öldürülür göz göre göre

Ben inanmıyorum kim ne derse desin.', 'Bu kent öldürüldü diyorlar Kurşuna dizildi bir gece yarısı Hayaletler geziniyormuş şimdi Sokak aralarında ve caddelerde Baykuş tüneği olmuş ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bu-kent-olduruldu-diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bir Üçtür', 'bu-bir-uctur-enis-akin-tdzet', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu bir üç çok diyorum

Alın şu birçoku götürün saraylıların suratına çarpın

Çünkü bazen bir daha çoktur birçoktan

Bu üç, çok hiç midir? 

Bana bir gece verin, meğer ben bir deniz içmişim habersiz

Sahilde benim yedilerim ıslansın

Bunu bir kağıt oyunu sandılar, papazlarla kızlar

Oysa tanrı bilgisayarlar aracılığıyla konuşuyor diyorum

Öyledir, domatesler aydan gelir

Bana bu üç çok diyorum, birkaçını da Nes alsın Li-Han’sın

Çatalca’da bir askerlik şubesi, Ortaköy’de bir telefon kulübesi

Eski sevgililer birbirini niye kandırsın? 

Bana bu tanrı çok, sen üçten haber ver,

''Serin peynir tadındaydı elleri'' ver

Bunun bundan sonrasını en pasaklı olan kazansın

Madem ki ''çekip gider'',                           Sarstım ve kurtuldum

''çekip gider'',                                              Çektim ve kurtuldum

''bir gözleri sürmeli''                 Etrafımda döndüm ve kurtuldum

Çatalımı bir ''önüm arkam sobe''ye batırıyorum

Her göz bir kırpılmaya kapılmalıdır 

ki kırışmadan

Gassaraylı Gökmen’in voleyle topu 2 metreden auta attığı 

Pozisyonları hatırlıyorum

(Siz)  14 inçlik bir bilgisayar ekranına bakarken

Dışarıda bir ay kanar ve aryalar

Okyanuslarım sızlıyor, 

Apış aramı yalıyorum, en köpek yerlerimi

Bunun bundan sonrasını yağmurda ıslananlar kazansın! 

Madem ki ''ötüp gider, ötüp gider, bir gözleri sürmeli''

Ben ki olmam, madem ki Hayırsız çıktım Ustamı affedemedim

Ölmekten korkanı ekmek çarpsın, 

Bize üç tanrıtanır lazım, bu bir üçtür

O da bana çok diyorum, çok güç, üç', 'Bu bir üç çok diyorum Alın şu birçoku götürün saraylıların suratına çarpın Çünkü bazen bir daha çoktur birçoktan Bu üç, çok hiç midir?  Bana...', ARRAY['Türk Edebiyatı','Şiir','Enis Akın']::text[], 8.5, '{"poet":"Enis Akın","poet_slug":"enis-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-bir-uctur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terci-i Bend IX', 'terci-i-bend-ix-ziya-pasa-at1gl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pek rengine aldanma felek eski felektir

Zira feleğin meşreb-i nasazı dönektir

Ya bister-i kemhada ya viranede can ver

Çün bay u geda hake beraber girecektir

Allah''a sığın şahs-i halimin gazabından

Zira yumuşak huylu atın çiftesi pektir

Yaktı nice canlar o nezaketle tebessüm

Şirin dahi kasdetmesi cana gülerektir

Bed-asla necabet mi verir hiç üniforma

Zerduz palan ursan eşşek yine eşşektir

Bed-maye olan anlaşılır meclis-i meyde

İşret güher-i ademi temyize mihenktir

Nush ile yola gelmeyeni etmeli tekdir

Tekdir ile uslanmayanın hakkı kötektir

Nadanlar eder sohbet-i nadanla telezzüz

Divanelerin hemdemi divane gerektir

Afv ile mübeşşir midir eshab-ı meratib

Kanun-i ceza acize mi has demektir

Milyonla çalan mesned-i izzete serefraz

Birkaç kuruşu mürtekibin cay-i kürektir

.................', 'Pek rengine aldanma felek eski felektir Zira feleğin meşreb-i nasazı dönektir Ya bister-i kemhada ya viranede can ver Çün bay u geda hake be...', ARRAY['Türk Edebiyatı','Şiir','Ziya Paşa']::text[], 8.5, '{"poet":"Ziya Paşa","poet_slug":"ziya-pasa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/terci-i-bend-ix-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-adem-keven-f5esf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başını eğdi çocuk

Babam dedi.

Şey dedi.

Yutkundu

Öğretmen soğuktan morarmış elleriyle

Okşadı öocuğun başını

Sildi boncuk boncuk akan gözyaşını.

Öğretmenin ellerini

Sımsıcak hissetti çocuk başında.

Bir el dedi.

Evet bir el.

İlk defa okşadı başımı

Babam yok ki okşasın başımı

Babam,

Varsın yine dövsün beni

Adam ol desin.

Ekmeğini taştan çıkarmalısın evlat desin

Saysın emirlerini bir bir,

Hepsini yapmaya hazırım

Heyhat!

Yok ki...,

Acıların doldurduğu gönlümde

Bir boşluk,

Hem de kocaman

Ne doldurabilen var ne dolduran

İlk sen oldun

Gözyaşımı silen,

İlk değen el senin elin,

Sen uzandın kalbime

Öğretmenim...', 'Başını eğdi çocuk Babam dedi. Şey dedi. Yutkundu Öğretmen soğuktan morarmış elleriyle Okşadı öocuğun başını Sildi boncuk boncuk akan gözyaşı...', ARRAY['Türk Edebiyatı','Şiir','Adem Keven']::text[], 8.5, '{"poet":"Adem Keven","poet_slug":"adem-keven","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cocuk-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Şiir', 'geceye-siir-necip-fazil-kisakurek-0iimw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Kalbim bir çiçektir, gündüzler ölgün; 

Gelin, gelin, onu açın geceler! 

Beni yâdedermiş gibi, bütün gün

Ötün kulağımda, çın, çın, geceler! 

Geceler çekmeyin benimçin hüzün,

Gelin siz, ruhumu tenimden süzün; 

Bırakın nâşımı yerde gündüzün,

Gölgemi alın da kaçın geceler! 

2

İnsanlar içinde en yalnız insan; 

Düşün, taş duvara başın gömülü! 

Ve kapan sükûta, granitten, taştan,

Mazgallı bir kale gibi örülü.

Gözünü tavandan ayırma ki, sen,

Üşürsün, gölgeni yerde görürsen.

Dikilir karşına, mumu söndürsen,

Ölüler içinde en yalnız ölü…

3.

Sesimi alıp da kaybetse rüzgâr,

Versem gözlerimi bir sonsuz renge! 

İçimde bir mahşer uğultusu var; 

Ruhumdur çağıran, tenimi cenge.

Gözlerim bir kuyu, dilim kördüğüm,

Bir görünmez âlem olsa gördüğüm; 

Mermer bir kabuğa girip, ördüğüm,

Kapansam içimden gelen âhenge…', '1 Kalbim bir çiçektir, gündüzler ölgün;  Gelin, gelin, onu açın geceler!  Beni yâdedermiş gibi, bütün gün Ötün kulağımda, çın, çın, geceler!...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/geceye-siir-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler', 'oluler-necip-fazil-kisakurek-8tdw7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüler bağrıyor mezarlarından;

Yolcular, oturun taşlarımızda!

Onları deviren biziz toprağa,

Biz attık onları böyle ayağa;

Sakın atlamayın kenarlarından!

Ölüler bağrıyor mezarlarından...

Yolcular, uzanın yere upuzun;

Dayayın taşlara başlarınızı!

Tüy yastıklar gibi rahat başımız!

Birleşsin bir lâhza orda başımız!

Bizdedir cevabı kuruntunuzun;

Yolcular, uzanın yere upuzun!

Ben de bir gün böyle haykıracağım:

Yolcular, oturun mezar taşımda!

Yolcular önemde fısıldaşacak,

Yolcular aşılmaz yollar aşacak.

Taşımı yerlere yatıracağım;

Ben de bir gün böyle haykıracağım!

(1935)', 'Ölüler bağrıyor mezarlarından; Yolcular, oturun taşlarımızda! Onları deviren biziz toprağa, Biz attık onları böyle ayağa; Sakın atlamayın ke...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oluler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh', 'ruh-necip-fazil-kisakurek-dybbx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya bin yıl, ya bin asır sonra o gün gelecek.

Koklarken küllerimi mezarımda bir böcek

O kadar yanacak ki, bir yüksüklük toprağım,

Yerden bir damar gibi kopup fışkıracağım!

Ve birden bakacağım, her tarafım bitişmiş,

Başım, toprak altında bir mâden gibi pişmiş.

Nefesten daha ince bir ipek kumaş derim;

Fosfordan daha parlak, ince uzun ellerim.

Dalacağım kendimin hayran seyrine,

Diyeceğim: Bu dönen şeyler eski yerine,

Benim diye baktığım şeyler miydi bir zaman?

Külümün rüyası mı yoksa gördüğüm?.. Aman!

Başımda açılacak fânilerin seması

Ve onların taprağa gerçek diye teması,

Bir tatlı vehim gibi içimi bayıltacak;

Toprağın, koşacağım, üzerine yalnayak;

Şehrin, dolaşacağım kuş gibi etrafında;

Bir beyaz hayaletim upuzun çarşafında,

Gezeceğim, doğduğum evin odalarını,

Geceleyin, koskoca şehrin lâmbalarını,

Bir keksin üfleyişim söndürmeye yetecek;

Korku, şehrin çelikten sesini tüketecek.

Herşey susacak o ân, çalınacak kapılar;

Kiremitleri yaprak yaprak alan bir rüzgâr,

Ağzamdan haykıracak, uzun, gizli, çapraşık...

Erişilmez fikir ki, düğüm düğüm dolaşık...

Sarıldıkça boşanan yumak, çözülen demet;

Başı görünmez hayâl, sonu gelmez nedamet...

(1931)', 'Ya bin yıl, ya bin asır sonra o gün gelecek. Koklarken küllerimi mezarımda bir böcek O kadar yanacak ki, bir yüksüklük toprağım, Yerden bir ...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ruh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablam için Gazel', 'ablam-icin-gazel-ahmet-ada-l78tb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ablam çiçekli basma giyerdi.

Gurbet ustasıydı,

Sıla mı,hüzün saatlerimi?

Eylülün ilk haftasıydı.

Saçlarını tarasa akıp giderdi onlarca keder.

Darılsa bana kumral bir yalnızlığa başlardı.

Verandanın köşesinde siyah- beyazdı sesi.

Ablam yaşasaydı solgun şarkılar söğlerdi.

Eylül müydü albümden düşmüş sonbahar mı?

Ne güzel güldü bütün özlemi sarardı.

Bir gün kalbi kuş uçmayan  atlaslara gömüldü.

Yaşasaydı kuş olup Cezayir menekşelerine konardı.', 'Ablam çiçekli basma giyerdi. Gurbet ustasıydı, Sıla mı,hüzün saatlerimi? Eylülün ilk haftasıydı. Saçlarını tarasa akıp giderdi onlarca keder...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ablam-icin-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Ayrılalı', 'senden-ayrilali-alev-sunak-el1hg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabaha bes var guzelim

Senden ayrilali

Gozlerim uykuyu

Dudaklarim ufak bir tebessumu unuttu!

Sabaha bes var guzelim

Beni saran kollarin

Beni bensiz birakan kahkahalarin olmadan

Bu hayat yasanmaz oldu!

Sabaha bes var guzelim

Karsimda yarim bir resim

Dilimde surekli mirildandiğim sarkımız

Ve ben istanbulda yapayanliz!

Sabaha bes var guzelim

Her saniye artan sevgimle,sevgimizle

Ben yine sensiz yine yanliz!', 'Sabaha bes var guzelim Senden ayrilali Gozlerim uykuyu Dudaklarim ufak bir tebessumu unuttu! Sabaha bes var guzelim Beni saran kollarin Beni...', ARRAY['Türk Edebiyatı','Şiir','Alev Sunak']::text[], 8.5, '{"poet":"Alev Sunak","poet_slug":"alev-sunak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-ayrilali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak için - 1', 'unutmak-icin-1-riza-aslan-ou3w7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'unutmak için en kolay yolmuş

nefret etmek

nefret ediyorum senden

- edemiyorum -', 'unutmak için en kolay yolmuş nefret etmek nefret ediyorum senden - edemiyorum -...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/unutmak-icin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Alışkanlıklar', 'eski-aliskanliklar-riza-aslan-c427w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine başladık

eski alışkanlıklara

yine başladık hayatı

'' ti '' ye almaya

yine başladık 

kendinden kaçıp

beklenmedik bir anda 

kendini yakalamaya', 'yine başladık eski alışkanlıklara yine başladık hayatı '' ti '' ye almaya yine başladık  kendinden kaçıp beklenmedik bir anda  kendini yakalam...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eski-aliskanliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor olacak', 'zor-olacak-riza-aslan-6g0fa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'alışmak zor olacak

sorun yok derken bile

yine arayacağım sıcaklığını

yine arayacağım

masumiyetini - hiyanetini -

bitti derken bile', 'alışmak zor olacak sorun yok derken bile yine arayacağım sıcaklığını yine arayacağım masumiyetini - hiyanetini - bitti derken bile...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zor-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelinlik', 'gelinlik-unal-gul-l0n1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Spil''de çam ağaçları beyaz gelinliklerini giymişler

Hepsi birbirinden alımlı, bakmaya doyamıyor insan

Aklıma senin gelinlikler içindeki resmin geldi.

Ne kadar benziyor her bir  sana

Eşsiz güzel . 

Sonra güneş çıktı 

Acımızca eridi şekilsizleşti o tabloluk görüntü.

Acı gerçeklerin ruhumuzu çırılçıplak bırakması gibi.

Üzücü ama olmak zorunda.

Karların pırıl pırıl temizlediği yaprakların güneşle dansı da güzel.', 'Spil''de çam ağaçları beyaz gelinliklerini giymişler Hepsi birbirinden alımlı, bakmaya doyamıyor insan Aklıma senin gelinlikler içindeki resm...', ARRAY['Türk Edebiyatı','Şiir','Ünal Gül']::text[], 8.5, '{"poet":"Ünal Gül","poet_slug":"unal-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gelinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek düzelik', 'tek-duzelik-riza-aslan-rd7ae', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşamın değil bu tek düzelik

bu tek  düzelik , geçmişimizde saklı

bu geçmiş ki , üzerine hep sünger çekilip

her defasında yenilerini ekleyip ,

bir türlü silemediğimiz 

yaşadığımız 

yaşadığımızı sandığımız şu an

bugüne ait değil

yaşadıklarımız üç boyutlu bir tek düzelik', 'yaşamın değil bu tek düzelik bu tek  düzelik , geçmişimizde saklı bu geçmiş ki , üzerine hep sünger çekilip her defasında yenilerini ekleyip...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tek-duzelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün ben de', 'bir-gun-ben-de-riza-aslan-6ah25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir gün ben de

sırtımı dönüp acılara

içimi döküp yalnızlığıma 

- gideceğim -', 'bir gün ben de sırtımı dönüp acılara içimi döküp yalnızlığıma  - gideceğim -...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gun-ben-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş 22', 'yas-22-riza-aslan-mmwkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaş yirmi iki

on beşini çocukluğa çık

yedisini gençliğe

yaş şimdi onbeş

gerisi mi ?

kayıp', 'yaş yirmi iki on beşini çocukluğa çık yedisini gençliğe yaş şimdi onbeş gerisi mi ? kayıp...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yas-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrımlaşmamış Düşünceler', 'ayrimlasmamis-dusunceler-riza-aslan-v976e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ayrımlaşmamış düşüncelerle

sahipsizdim , bir yaz boyu', 'ayrımlaşmamış düşüncelerle sahipsizdim , bir yaz boyu...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ayrimlasmamis-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışarıdaki Hayat', 'disaridaki-hayat-riza-aslan-kwryc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dışarıda bir hayat

acı yüklü 

kin dolu

dışarıda bir hayat

benle beraber

benden ayrı', 'dışarıda bir hayat acı yüklü  kin dolu dışarıda bir hayat benle beraber benden ayrı...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/disaridaki-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Akşamlar', 'sahipsiz-aksamlar-riza-aslan-xl8yb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sahipsiz akşamların

bitmek bilmeyen

gün batımındayım

yorgunum

biraz da bitkin', 'sahipsiz akşamların bitmek bilmeyen gün batımındayım yorgunum biraz da bitkin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sahipsiz-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıl', 'cakil-riza-aslan-zfwbx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çakıl taşları gibi

paramparça bir geçmiş 

birleşmez

birleşemez bir toz yığını', 'çakıl taşları gibi paramparça bir geçmiş  birleşmez birleşemez bir toz yığını...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cakil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmak İstemediğim', 'alismak-i-stemedigim-riza-aslan-do7h5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'neye alışmak istemediysem

alışmak zorunda kaldım

sana alışmak istedim

alışamadım', 'neye alışmak istemediysem alışmak zorunda kaldım sana alışmak istedim alışamadım...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/alismak-istemedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temas', 'temas-riza-aslan-kzcl4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir temas olur

bir sıcaklık,

bir ten kokusu

koklarsın ama; izinsiz

senin olmayan bir gülüşe

senin olmayan bir bedene kapılırsın

ve o bilmez bunu

çünkü söyleyemezsin', 'bir temas olur bir sıcaklık, bir ten kokusu koklarsın ama; izinsiz senin olmayan bir gülüşe senin olmayan bir bedene kapılırsın ve o bilmez ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/temas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simge', 'simge-riza-aslan-gdj8n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geçen zamanı simgeleyen,

hiç bir anı yok şimdi

anılar seninle başladı,

gidince bitti', 'geçen zamanı simgeleyen, hiç bir anı yok şimdi anılar seninle başladı, gidince bitti...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/simge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki parça', 'i-ki-parca-riza-aslan-yfoc3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birbirini tamamlayan

iki parça , değiliz artık', 'birbirini tamamlayan iki parça , değiliz artık...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/iki-parca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece', 'oylece-riza-aslan-2w065', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öylece ve alımlıca

karşımdasın

yakınımdasın yanımdasın

gözlerin alev alev

kıvrılarak, salınarak

ne güzel de oynamıştın

kokunu hisstmiştim

omuzların omuzlarıma değdiğinde 

öylece ve alımlıca

karşımdasın

yakınımdasın,yanımdasın

benim değilsin,olamazsın', 'öylece ve alımlıca karşımdasın yakınımdasın yanımdasın gözlerin alev alev kıvrılarak, salınarak ne güzel de oynamıştın kokunu hisstmiştim om...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oylece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizliğin Anlatımı', 'caresizligin-anlatimi-riza-aslan-ua2hf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çaresizliğin farklı bir anlatımıydı bu

güneşin hep aynı yerden doğup

hep aynı yerden batması gibi bir şey bu

zamana zamanında kafa tutamayıp

yok oluşun sadece başalngıcı bu

semeresi belki yıllar sonra alınacak

bir hakedişin sadece görünen yüzü bu

yalnızlığın o korkunç yüzünün

dostluk maskesi takmış güzelliği bu', 'çaresizliğin farklı bir anlatımıydı bu güneşin hep aynı yerden doğup hep aynı yerden batması gibi bir şey bu zamana zamanında kafa tutamayıp...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/caresizligin-anlatimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Karışırken', 'huzun-karisirken-riza-aslan-yuc4j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüzün karışırken mısralara

yoksun

sağnak yağmur yağıyor

caddeler bomboş

sırılsıklamım

tek tük ışıklar beliriyor uzaklarda', 'hüzün karışırken mısralara yoksun sağnak yağmur yağıyor caddeler bomboş sırılsıklamım tek tük ışıklar beliriyor uzaklarda...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/huzun-karisirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koluma Girmiş', 'koluma-girmis-riza-aslan-5lb7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'koluma girmiş

soğuk bir kış yeli

bitmek bilmeyen bir akşamdayım

hiç bir akşam bu kadar uzun olmamıştı oysa

ağzıma bulaşmış bilinen bir şarkı

hiç bir şarkı bu kadar kötü söylenmemişti

oysa', 'koluma girmiş soğuk bir kış yeli bitmek bilmeyen bir akşamdayım hiç bir akşam bu kadar uzun olmamıştı oysa ağzıma bulaşmış bilinen bir şarkı...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/koluma-girmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkıydı Bizimkisi', 'bir-sarkiydi-bizimkisi-riza-aslan-n6nnq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir şarkı gibiydi bizimkisi

hiç bitmeyen bir nakaratın

en beğenilen bir kelimesiydi

bitmezdi

bitemezdi', 'bir şarkı gibiydi bizimkisi hiç bitmeyen bir nakaratın en beğenilen bir kelimesiydi bitmezdi bitemezdi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-sarkiydi-bizimkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum*', 'seni-bekliyorum-bayram-tunca-if57x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bugün, akmayan su misali durgunum

Bugün yine, aynen o günkü gibi vurgunum

Senelerce seni beklemekten çok yorgunum

Geçse de gençliğim yine de seni bekliyorum

Sensiz geçen her günde derdime dert ekliyorum

Ne kadar yaşlansam da, yine de seni bekliyorum

Nasıl bir sevgin varmış ki hiç içimden atamıyorum

Ne geceleri, ne de gündüzleri sensiz yatamıyorum

Belki bir gün gelirsin diye, başkalarına bakamıyorum

Vefasızlık olur diye de, yüreğimden silip atamıyorum

Gözüm, gönlüm, kolum bütün bedenimle bekliyorum

Ne olursun gel artık, tüm benliğimle seni bekliyorum

25.12.2000-16.25', 'Yine bugün, akmayan su misali durgunum Bugün yine, aynen o günkü gibi vurgunum Senelerce seni beklemekten çok yorgunum Geçse de gençliğim yi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-bekliyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-yasar-ciger-vjl59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çırpınışmış biçare yaşam

Oysa yaprakta çırpınır

,Rüzgarın karşısında 

Fakat...

İnsan suya girince çırpınır,

Balık sudan çıkınca.

Çırpınmak yaşamsa,

İnsan suda yaşamalı

EY AZİZİM!

Dağa taşa bak,

Bırak suları yerinde kalsın.

Sen suları ıslatamazsın 

Toprak ol azizim toprak 

Sular seni ıslatsın', 'Çırpınışmış biçare yaşam Oysa yaprakta çırpınır ,Rüzgarın karşısında  Fakat... İnsan suya girince çırpınır, Balık sudan çıkınca. Çırpınmak y...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-yasar-ciger-zi58f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen bana her şey oldun,

damla damla göl,

yağmur olup sel

sellerle birlikte deniz,

denizleri birleştiren okyanus.

bense...

sana açılan bir yelkenli,

sonuç mu?

BATTIM.', 'sen bana her şey oldun, damla damla göl, yağmur olup sel sellerle birlikte deniz, denizleri birleştiren okyanus. bense... sana açılan bir ye...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan', 'yasayan-yasar-ciger-ux59h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gecenin bir yarısı 

düşünüyorum.

karanlıklarda düşünmek , karanlık

sabırtaşı olmak ne demek

bu düşüncelere bu beden sabır taşı demek

gece benim , sabaha kadar

yarasalar bana en vefalı dost.

yaşadığım hayatta benim 

ama...

yaşayan ben değil.', 'gecenin bir yarısı  düşünüyorum. karanlıklarda düşünmek , karanlık sabırtaşı olmak ne demek bu düşüncelere bu beden sabır taşı demek gece be...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerde', 'hayallerde-yasar-ciger-ik32h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yer kurdum kendime,

tahkimi yok, tahriri yok

derdim çok kederliyim , üzgünüm.

dost yok akraba yok.

kalbimi vurdum yerden yere,

sevgi yok , şefkat yok.

cezaların en büyüğü bende,

vicdan yok, muhasebe yok.

düşünür gibi olursun,

akıl yok , zeka yok.

insanların hepsi bakar gibi bakar,

hasret yok , vuslat yok.

bin kez kurup bin kez yıktığım ülkemde

vatan yok, bayrak yok.

yokların içinde yok yok,bir ben var,

bendeki bende, yok olan yoklar var.', 'bir yer kurdum kendime, tahkimi yok, tahriri yok derdim çok kederliyim , üzgünüm. dost yok akraba yok. kalbimi vurdum yerden yere, sevgi yok...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayallerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık', 'yanlizlik-yasar-ciger-j9z8k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanlık bir yolda

yürüyorum

sokak lambaları nöbette

bir de ben.

gölge üstüne gölge,

sokaklar kalabalık,

insan çok, insanım yok

her şey bana yakın benden ayrı,

tek dostum kaldırımlar

düşmanım oldu sizi kaldıranlar.

karanlıklar çöküyor üstüme,

ardımda gecenin sessiz çığlığı

lambalarda gizlemiyor ,bendeki yanlızlığı

vakit doldu tan ağarmakta,

umudum başka bir sokakta.', 'karanlık bir yolda yürüyorum sokak lambaları nöbette bir de ben. gölge üstüne gölge, sokaklar kalabalık, insan çok, insanım yok her şey bana...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yanlizlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Gökyüzümsün', 'sen-benim-gokyuzumsun-yasar-ciger-kn5de', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıldızları sayıyorum ,

bir, iki, üç...

sabahı bekliyorum,

ve...

gökyüzü seni kucaklıyorum', 'yıldızları sayıyorum , bir, iki, üç... sabahı bekliyorum, ve... gökyüzü seni kucaklıyorum...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-benim-gokyuzumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana', 'sen-bana-yasar-ciger-m1egf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gülen yüz aynalara hasret,

ben sana

zühhad kevsere talip,

ben sana.

gündüz geceye muhtaç,

ben sana.

güneş gökyüzüne eş,

ben sana.

Leyla Mecnun''a aşık ,

ben sana

hastaya çare ilaç,

sen bana.', 'gülen yüz aynalara hasret, ben sana zühhad kevsere talip, ben sana. gündüz geceye muhtaç, ben sana. güneş gökyüzüne eş, ben sana. Leyla Mecn...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-yasar-ciger-jeonl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'örnek olacağım tüm insanlara.

bir farkla...

benim gibi olmaları için değil,

olmamaları için.', 'örnek olacağım tüm insanlara. bir farkla... benim gibi olmaları için değil, olmamaları için....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Ciğer']::text[], 8.5, '{"poet":"Yaşar Ciğer","poet_slug":"yasar-ciger","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''e', 'eylul-e-hayrullah-pasalioglu-sgwyp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçekler sevdalıdır

Sonbaharın hüzünlü şarkılarına

Ve en güzel sonbahar şarkısıdır eylül

Ve bir eylül sevdasıdır 

Gül tohumunda sakladığım.

Ve bir eylül akşamında

Bedirden kalma bir ay ışığıyla

Aydınlandı yüreğim.

Ve sen sonbahar akşamının gözüyle

Ufuklara son bakışımsın 

Sütten beyaz martıların kanatlarında

Eylüle yazdığım son bestemsin

Son kez yankılandı eylülün nakaratlarında

O ipeksi kadife sesin

Ve nefesin

Eylül akşamının son esintisiydi', 'Çiçekler sevdalıdır Sonbaharın hüzünlü şarkılarına Ve en güzel sonbahar şarkısıdır eylül Ve bir eylül sevdasıdır  Gül tohumunda sakladığım. ...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eylul-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pek Hazin Bir Mevlid Gecesi', 'pek-hazin-bir-mevlid-gecesi-mehmet-akif-ersoy-92xwa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar geçiyor ki, yâ Muhammed,

Aylar bize hep muharrem oldu! 

Akşam ne güneşli bir geceydi...

Eyvah, o da leyl-i mâtem oldu! 

Âlem bugün üç yüz elli milyon

Mazlûma yaman bir âlem oldu! 

Çiğnendi harîm-i pâki şer''in; 

Nâmûsa yabancı mahrem oldu! 

Beyninde öten çanın sesinden

Binlerce minâre ebkem oldu.

Allah için, ey Nebiyy-i mâsûm,

İslâm''ı bırakma böyle bîkes,

İslâm''ı bırakma böyle mazlûm.

(30 mayıs 1330) 

(1914) 

* * *

Bize “Dînî, Felsefî Musâhabeler” gibi muazzam bir eser yazan yâr-ı cânım, üstâd-ı hâkîmim Hazret-i Ferîd’in kıymetdâr bir hâtıra-i iltifâtıdır:

“Enîs-i rûhum Akif’e,

Safahât’ın üçüncü kısmını neşre muvaffakiyetinden dolayı seni hâlisâne tebrîk eder; diğer kısımlarının da peyderpey neşrine muvaffak olmanı Cenâb-ı Hak’tan temennî eylerim.

Lisân-ı nazma -mâhiyetini tağyîr etmeksizin- müstaid olduğu inkişâfı verdin. Türkçe’nin nazma gâyet elverişli olduğunu eserlerin ile isbât ettin. Bir müddetten beridir lisânımızda herkes istediği gibi tasarrufâta kıyâm eylediğinden, lisânımız bütün Osmanlıların lisânı olmak derecesinden lisân-ı şahsî olmak derekesine düşmüştür. Filhakîka, üslûb, şahsın malı, ta’bir-i dîgerle sâhibinin timsâlidir; fakat lisânın rûhuna dokunulmamak şartıyle.

Herkesin lisânda bir tasarruf-i mahsûs icrâsına salâhiyetdâr olması bir hadde kadar mücâz olabilir; o haddi tecâvüz edenlere: “Dur! ” demek lâzım gelir. Halbuki lisânımızda icrâ-yı tasarrufâta kıyam edenler, teceddüd gösterenler, hiçbir hadde riâyet etmiyorlar, hiçbir mikyâsa tâbi’ olmuyorlar, onun için lisânımız da günden güne çığırından çıkıyor.

Meselâ bir heykeltraş, tasarrufât-ı hayâliyesiyle eserini kemâl-i mümkine îsâle çalışır. Lâkin hiçbir zaman tabîatin ta’yin ettiği haddi tecâvüz edemez. Eserini o had dâhilinde kemâl-i mümkine îsâl eder. O haddi tecâvüz ettiği anda, eseri bir eser-i san’at değil, bir nümûne-i garâbet olur. Zîrâ sanâyie hâs olan kemâl nev’înin zevk-i sahîh denilen bir mikyâsı vardır. Âsâr-ı san’atte gösterilecek kemâl dâimâ o mikyâs ile ölçülür.

Ressamlık da böyledir. Ressam, eserinde göstereceği kemâli, anâsır-ı san’atin nazm-ı tabî’îlerini bozmamak şartıyle gösterebilirse mahâret ibrâz etmiş olur; gösteremezse tabîati kaba bir sûrette istinsâh ederek âdî bir mukallid derekesinde kalır.

Anâsır-ı san’ati vaz’-ı tabî’îlerinden çıkaran kimse, kavânîn-i san’ati ihlâl etmiş demektir. Vâkıâ bu hâl ender olarak duhâttan sudûr eder. Halbuki nazar-ı sahîh ile bakılacak olursa dehâ-yı hakîkînin, bu hareketiyle kavânîn-i san’ati ihlâl etmediği, belki san’atin kavânîn-i mevcûdesine bir kânun daha ilâve eylediği görülür. Dehâya has olan bu tasarrufu taklîde kıyâm edenler dâimâ aldanırlar, dâimâ muvaffakiyetsizlik girdâbına düşerler.

Mûsikînin de o gibi tasarrufât-ı mübdiâneye aslâ tahammülü yoktur. Heykeltraş olsun, ressam olsun, mûsikîşinâs olsun dâimâ san’ate hâs olan mikyâs-ı nev’îyi elinde tutmağa, san’atinde göstereceği eser-i kemâli o mikyâs ile ölçmeğe mecburdur.

Bu şarîtaya riâyet etmeyen san’atkârların eserleri âsâr-ı san’atten ma’dûd olamaz. Ne fâide ki şiirde bu dakîka asla nazar-ı i’tibâre alınmıyor. Çok kimseler sâha-i nazmı tasarrufât-ı mübdiâneleri için gâyet vâsi’, gâyet müsâid buluyorlar. O vâdîde gösterdikleri garâbetleri herkese birer bedîa-i ma’rifet sûretinde kabul ettirmek istiyorlar. Yeni şiirlerde bunun pekçok numûneleri görülüyor. Çok kimseler de şi’rin hakîkatini, şi’rde gösterilebilecek tasarrufâtın hadd-i tabî’îsini ta’yînden âciz olduklarından bu başkalıklara teceddüd, yâhud kemâl-i san’at nazarıyle bakıyorlar.

Elhâsıl öteki san’atlerin kabûl etmedikleri o gibi tasarrufât-ı dâhiyâneyi zavallı şi’r kolayca kabûl ediyor. Eğer şi’rimizde gösterilen keyfî tasarruflar bil-farz heykeltraşlıkta, ressamlıkta gösterilmiş olsaydı, heykeltraşın elinden çıkan bir heykel her halde bizim bilmediğimiz bir mahlûk olur idi! Kezâ bir ressamın böyle bir tasarruf netîcesinde vücûda getireceği eserler de bize görmediğimiz, bilmediğimiz bir âlemin menâzırını tasvîr eder idi. Şi’rimizde bu garâbet çoktan ta’ayyün etti. Fakat onun temyîzi diğer san’atlerdeki garâbetlerin temyîzi kadar kolay olmadığından bugün o garâbetlere yukarıda söylediğim gibi, teceddüd, yâhud kemâl-i san’at nâmı veriliyor. Bakalım bu hâl ne zamana kadar devam edecek? Fakat sen lisân-ı şi’ri, mâhiyet-i nev’iyesine hâs bir tekâmüle namzed kıldın; muvaffak da oldun; daha da olacaksın.

Gelelim ikinci mülâhazaya: İhtimâl ki “San’at san’at içindir; san’atten maksad yine san’attir; san’atte dinî, ahlâkî, siyâsî bir gâye aramak abestir” diye senin mesleğine i’tirâz edenler, onu hoş görmeyenler vardır. Fakat o halde, ya’ni san’at hakkındaki bu düstûr kabul edildiği takdirde, onu dinsizliğe, ahlâksızlığa da âlet ittihâz etmemek lâzım gelir. Zîrâ san’at, bu sûretle kayıddan âzâde edilmiş olmayıp, belki kuyûdun en berbâdıyle takyîd edilmiş olur. Ben, senin eserlerinde bu düstûra muhalefetini gösterecek bir şey görmüyorum. Çünkü sen san’atte gâye aramıyorsun; lâkin gâyede san’at arıyorsun. Mesleğin tamâmıyle maksadını te’mîne kâfîdir. Hemen feyyâz kalemine istediği cevelânı ver, ciddî eserlere teşne olanları feyz-i kaleminle reyyân et! Safahât’ın bu kısmını teşkîl eden manzûmelerin menbaı, Furkân-ı Hakîm olduğundan hepsinin ilhâm-ı mahz eseri olduğunu söylemek zâiddir. Hemen söyle, hemen yaz! Tevfîk-i Hudâ refîkin olsun azîzim.

30 Mayıs 1329 (12 Haziran 1913) 

Ferîd”', 'Yıllar geçiyor ki, yâ Muhammed, Aylar bize hep muharrem oldu!  Akşam ne güneşli bir geceydi... Eyvah, o da leyl-i mâtem oldu!  Âlem bugün üç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/pek-hazin-bir-mevlid-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Mektup', 'yeni-mektup-ali-cengizkan-mmt4v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni severim dediğinde duydum

İplerde parça parça sevgimi.

Ne zaman mektup alsam..,

Sonuçsuz ve saçma kederimi

Senin sözlerinde kuruttum.

Mektupları yakmalı

Sevgilerden yoruldum.

Hergün güneşin doğuşu var ya,

Sabah beşte şehri koklayacaksın.

Nerde bir güzellik görsem...

Her an yeniden başlayacaksın,

Sürükleyecek yürek var ya.

Pulları ne yapmalı?

Pulları kullanmalı.', 'Seni severim dediğinde duydum İplerde parça parça sevgimi. Ne zaman mektup alsam.., Sonuçsuz ve saçma kederimi Senin sözlerinde kuruttum. Me...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengizkan']::text[], 8.5, '{"poet":"Ali Cengizkan","poet_slug":"ali-cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeni-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-arif-karakum-8cb8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gözümdeki ışık,

Sen yüreğimdeki sevgi,

Sen gönlümdeki sultan,

Sen kulağımdaki şarkı

Sen dallarımdaki çiçek

Sen ruhumdaki fırtına,

Sen içimdeki liman,

Sen beynimdeki şimşek,

Sen gecemin mehtabı,

Sen günümün parlak güneşi,

Sen yolumdaki sondurak,

Sen yaşamımdaki en güzel,

VELHASIL SEVGİLİM

Sen herşeyim herşeyimsin.', 'Sen gözümdeki ışık, Sen yüreğimdeki sevgi, Sen gönlümdeki sultan, Sen kulağımdaki şarkı Sen dallarımdaki çiçek Sen ruhumdaki fırtına, Sen iç...', ARRAY['Türk Edebiyatı','Şiir','Arif Karakum']::text[], 8.5, '{"poet":"Arif Karakum","poet_slug":"arif-karakum","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Asu', 'olmaz-asu-ali-cengizkan-rclda', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuşlar insan değildir, ötmüyorum.

On mu vardı ayrılığa,oniki miydi?

Fıstığı rakıyla soyarak yiyin.

Bir miydi yaşanılan yoksa iki miydi?

Yalan da söylerim,kuşları anlıyorum,

Her şey yaşanmalı mı bilmiyorum.

Kendimi senin yerine koyuyorum.

Ankara''nın havası bir yapışkan,

Çekerim,çekerim hiç bitmez

Yaprak ve yoğun siste savrulan

Seni ayrılacak kadar seviyorum,

Her şey söylenmeli mi bilmiyorum.', 'Kuşlar insan değildir, ötmüyorum. On mu vardı ayrılığa,oniki miydi? Fıstığı rakıyla soyarak yiyin. Bir miydi yaşanılan yoksa iki miydi? Yala...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengizkan']::text[], 8.5, '{"poet":"Ali Cengizkan","poet_slug":"ali-cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmaz-asu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Düşün', 'once-dusun-oguz-celik-lnk2d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmişinde en çok neye güldün, 

Seni en çok ağlatan neydi.

Önceleri çok sevdin, sevildin.

öncesinin bir sonrası; 

nefret ettin, edildin.

Gülen gözlerin ağlamaktan usandı.

Allaha yalvaran ellerin hiç kapanmadı.

Diğer insanlardan çok farklıydın.

Farklı düşündün, farklı hareket ettin.

Farklı, farklı...

Hiç gerçek sen olamadın, 

Kendine hakim olamadın hiç.

Sevmeyi bile beceremedin, bazı zamanlarda

Farklı sevdin.

Kaç kere dua ederken ağladın, banyoda, 

Kirlerinden arınırken; günahlarından arınmak için..

Ama hiç bir zaman; 

Affedilen günahların hafifliğini hissedemedin üstünde.

Hep ağır hissettin kendini.

Artık düşün geleceğini, 

İlk önce sevmeyi öğren, bilen birinden; 

Sonra aynada kendini izle, 

En son öğrendiklerini uygula ki; 

Geçmişini hatırlama', 'Geçmişinde en çok neye güldün,  Seni en çok ağlatan neydi. Önceleri çok sevdin, sevildin. öncesinin bir sonrası;  nefret ettin, edildin. Gül...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/once-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kösnül Sevgi', 'kosnul-sevgi-ali-cengizkan-mpkp9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim gönlüm hep sendedir anımsarım.

İlk görüşümdür ceren isimli dükkanı.

Gümüşçünün önünde iki sevgili bekler,

Menekşe kokusudur duyduğum bayram sabahı.

İçilen çaylar ve sevgiler hep yarım.

Onbire doğru bir telefon umarım,

Kulübede çocuktur kulaklığa ulaşan.

Her görüşmemiz birleşmeydi, şimdi

Kumrunun gölgesidir kaldırıma yapışan.

Benim gönlüm hep sendedir,anımsarım.

Elimde değildir,çünkü,sen unutsan,

Kumrunun gölgesidir kaldırıma yapışan.', 'Benim gönlüm hep sendedir anımsarım. İlk görüşümdür ceren isimli dükkanı. Gümüşçünün önünde iki sevgili bekler, Menekşe kokusudur duyduğum b...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengizkan']::text[], 8.5, '{"poet":"Ali Cengizkan","poet_slug":"ali-cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kosnul-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Atımlık Sevgi', 'tek-atimlik-sevgi-oguz-celik-fv318', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıkıldım yalancı seni seviyorumlardan.

Sahte aşklardan usandım.

Sevmeye aşık olmaya dermanım kalmadı...

Tek atımlık sevgim kalmıştı, 

Onuda sana verdim.

Garip geldi çoğu zaman hayat; 

Yaşamakla ölmek arasında gidip geldim, 

Yalnızlığımda.

Ben, seni sevdim

Yaşamaya karar verdim.

Yağmurdan sonra ki toprak kokusu gibi, 

Alıştım kokuna.

Yağmur; gözyaşım, tenin; toprak, 

Her dokunuşumda bir ağaç gibi, 

Nefes aldım senden, 

ve hayat buldum bedeninde.

Ben sonbaharda solmayan tek ağacım..', 'Sıkıldım yalancı seni seviyorumlardan. Sahte aşklardan usandım. Sevmeye aşık olmaya dermanım kalmadı... Tek atımlık sevgim kalmıştı,  Onuda ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tek-atimlik-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-oguz-celik-exelo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahilde oturmuşum, 

Karşımda deniz, bogaz ve ışıklı bir avrupa

Elimdeki birayı denize kaldırarak içiyorum, 

Daha sonra boğaza, 

ve en son ışığa kaldırıyorum.

Seni unuturmuyum hiç dostum; 

Senin için kaldırıyorum içkimi bundan sonra.

Aklımda sen ve senin gibi olanlar, 

Ama senin gibi kimse olamaz.

Bunu anlamak hiçte zor değil.

Ben seni, beni senin gibi seven, 

ve beni seven herkesi 

Seviyorum dostum...!', 'Sahilde oturmuşum,  Karşımda deniz, bogaz ve ışıklı bir avrupa Elimdeki birayı denize kaldırarak içiyorum,  Daha sonra boğaza,  ve en son ış...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer', 'deger-riza-aslan-hif1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç bir insan değerli değildir

onları değerli kılan 

bizleriz...', 'hiç bir insan değerli değildir onları değerli kılan  bizleriz......', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-oguz-celik-5y9e8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizin memleketin Leyla ile Mecnun''u yaz bana, 

Gördüğün rüyanın yorumunu yap mektubunda, 

Annenden, babandan, çevrenden bahset.

Etrafına çiçek resimleri yap, 

En altına bir kalp çiz sonra, 

Bizim baş harflerimizi yaz iki yanına.

Mektubu yazarken bir liseli gibi davran, 

İlk kez mektup yazıyormuş gibi heyecanlı ol.

Defalarca baştan yaz ama öncekileri atma.

Gözyaşlarını sakın akıtma mektubuna, 

Okurken bende ağlıyorum.

En sonuna ''Seni seviyorum'' yazmayı unutma, 

Sen en iyisi beni unutma! ! 

Uzak olabilir adresim, 

Unutmaki kalbim hep seninle, 

Sen en iyisi kalbime konuş...', 'Sizin memleketin Leyla ile Mecnun''u yaz bana,  Gördüğün rüyanın yorumunu yap mektubunda,  Annenden, babandan, çevrenden bahset. Etrafına çiç...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektup-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Düşen', 'kendi-dusen-riza-aslan-syn36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendi düşen ağlamaz 

- ağlayamaz-

çünkü o 

doğanın ona tanıdığı

en doğal hakkını

kaybetmiştir', 'kendi düşen ağlamaz  - ağlayamaz- çünkü o  doğanın ona tanıdığı en doğal hakkını kaybetmiştir...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kendi-dusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuş Diyemediğimden', 'konus-diyemedigimden-riza-aslan-i5gnv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'konuş diyememek

ilk kez bu kadar zordu

kelimeler düğüm düğümdü 

boğazımda

ve anladım - geçde olsa -

gidenin dönüşünün olmadığını', 'konuş diyememek ilk kez bu kadar zordu kelimeler düğüm düğümdü  boğazımda ve anladım - geçde olsa - gidenin dönüşünün olmadığını...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/konus-diyemedigimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız', 'anlamsiz-riza-aslan-cq3wg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'anlamsız olan şeylerin bile

anlamı kalmadı artık...', 'anlamsız olan şeylerin bile anlamı kalmadı artık......', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/anlamsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Gelincik Koydum', 'adini-gelincik-koydum-ali-cengizkan-k29uu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonra yürüdüm hiç geriye bakmadan

Piyangocuları, kebapçıları, biracıları bırakarak

Bacaklarının kalınlığını falan bırakarak.

Kendimi sorguladım çırılçıplak.

Bağırsam dağlar bağırırdı, yatsam odalar

Sigara sardı beni, korku sardı, ama işte o kadar.

Babasına giydirdiği mavi tulumlar...

Kirpiklerinin kendinden boyalı gibi duruşu...

Gövdesinin bir anaya andaç oluşu...

Yatsam her saat erkendi, kalksam geç,

Bir kızı sevmek buydu işte, üzgün ve güleç.', 'Sonra yürüdüm hiç geriye bakmadan Piyangocuları, kebapçıları, biracıları bırakarak Bacaklarının kalınlığını falan bırakarak. Kendimi sorgula...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengizkan']::text[], 8.5, '{"poet":"Ali Cengizkan","poet_slug":"ali-cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adini-gelincik-koydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Hayat', 'bir-baska-hayat-riza-aslan-ohknb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir başka hayata

bir başka mekana geçiş

isteyerek ve nedensiz...', 'bir başka hayata bir başka mekana geçiş isteyerek ve nedensiz......', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-baska-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk Bitermi', 'yolculuk-bitermi-riza-aslan-skfo9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yine değişirmi?

hep aynıyken

değişmesi istenen

bu yolculuk biter mi?

bitmesi gereken yerde', 'yine değişirmi? hep aynıyken değişmesi istenen bu yolculuk biter mi? bitmesi gereken yerde...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yolculuk-bitermi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimden Akan', 'gozlerimden-akan-riza-aslan-8cdhj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerimden akan

akan bu son yaşlar

hayallere sarılıp yattığım

son gecem bu', 'gözlerimden akan akan bu son yaşlar hayallere sarılıp yattığım son gecem bu...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerimden-akan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-riza-aslan-ltxja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yapılan

yapılmaya çalışılan

hiçbir şeyden sonra

dönüp ardıma bakmadım

- pişman olmaktan korktum-', 'yapılan yapılmaya çalışılan hiçbir şeyden sonra dönüp ardıma bakmadım - pişman olmaktan korktum-...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pisman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimden kaçtım', 'kendimden-kactim-riza-aslan-e0jhu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kendimden kaçtım

kendi gerçeklerimden kaçtım

yaşamdan kaçtım

yine yaşama sığındım', 'kendimden kaçtım kendi gerçeklerimden kaçtım yaşamdan kaçtım yine yaşama sığındım...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kendimden-kactim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-riza-aslan-pkkr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üzgünüm ,

kimse için değil

kendi adıma

çünkü yaşanmayan

yaşanamayan bu hayat

benim hayatım', 'üzgünüm , kimse için değil kendi adıma çünkü yaşanmayan yaşanamayan bu hayat benim hayatım...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uzgunum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Bardaktan İçmeyeceğiz', 'ayni-bardaktan-i-cmeyecegiz-anna-ahmatova-w0j8c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynı bardaktan içmeyeceğiz,

Ne suyu,ne tatlı şarabı,

Şafakta öpüşmeyeceğiz

Ve akşam çöktüğünde pencereden bakmayacağız.

Sen güneşle soluklanıyorsun ben ay ile

Ama aynı aşkla yanıyoruz ikimiz de.

Benim yanımda sadık,sevgili yarim,

Senin yanında neşeli eşin,

Ama okuyorum gri gözlerindeki korkuyu

Çünkü sensin acım.

O arada bir buluşmalarımız bundan böyle

Daha bir aradabir olsun.

Gönlümüz rahat olsun,o zavallı gönlümüz.

Şiirlerimde yalnız senin sesin var

Senin şiirlerinde,biliyorum benim soluğum esiyor

Ah bir ateş ki cesareti yok

Ne unutuşa,ne korkuya dokunmaya...

Bir bilsen nasıl seviyorum şu an

O kuru dudaklarını,gül rengi! 

(çev: Güneş Acar)', 'Aynı bardaktan içmeyeceğiz, Ne suyu,ne tatlı şarabı, Şafakta öpüşmeyeceğiz Ve akşam çöktüğünde pencereden bakmayacağız. Sen güneşle soluklan...', ARRAY['Türk Edebiyatı','Şiir','Anna Ahmatova']::text[], 8.5, '{"poet":"Anna Ahmatova","poet_slug":"anna-ahmatova","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayni-bardaktan-icmeyecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-ahmet-kutsi-tecer-9spx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceleyin bir ses böler uykumu,

İçim ürpermeyle dolar: - Nerdesin? 

Arıyorum yıllar var ki, ben onu,

Aşıkıyım beni çağıran bu sesin.

Gün olur sürüyüp beni derbeder,

Bu ses rüzgarlara karışır gider.

Gün olur peşimden yürür beraber,

Ansızın haykırır bana: -Nerdesin? 

Bütün sevgileri atıp içimden,

Varlığımı yalnız ona verdim ben.

Elverir ki bir gün bana derinden,

Ta derinden bir gün bana ''''Gel'''' desin.', 'Geceleyin bir ses böler uykumu, İçim ürpermeyle dolar: - Nerdesin?  Arıyorum yıllar var ki, ben onu, Aşıkıyım beni çağıran bu sesin. Gün olu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kutsi Tecer']::text[], 8.5, '{"poet":"Ahmet Kutsi Tecer","poet_slug":"ahmet-kutsi-tecer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukça', 'cocukca-metin-yalti-6jsmd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevindim

Çocuklar gibi sevindim

Buluşacağız diye

Akşamı iple çekmiştim.

Sevindim,

Çocuklar gibi sevindim

sevdiğim giysilerini giyinmiştin.

Usul usul dolaşıyordu eteklerinde rüzgar.

Sevindim

Çocuklar gibi sevindim

Yanaklarında gülüşler

Gözlerinde yakomozlar vardı

Çapkınca kırpışıyorlardı

Sevindim

Çocuklar gibi sevindim

Öpüştük

dünyanın dönüşü değişti

bütün bunlara sevindim

Çocuk gibiydim üstelik.

14/7/1999- Mecidiyeköy', 'Sevindim Çocuklar gibi sevindim Buluşacağız diye Akşamı iple çekmiştim. Sevindim, Çocuklar gibi sevindim sevdiğim giysilerini giyinmiştin. U...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocukca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bogazı Boydan Boya Yürüyorum', 'bogazi-boydan-boya-yuruyorum-metin-yalti-8ppj8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğaz''ı boydan boya yürüyorum

Her adımla bir anıyı yineliyor belleğim

Boğaz''ı boydan boya yürüyorum

Sevişmeye arzulu bir gelin gibi deniz

Bilmiyorum kaç saat geçiyor aradan

Gözlerim hep seni arıyor, nedensiz.

Hisar''da Özdemir Asaf''ı anımsıyorum

Ne güzel tanımlardı sevgiyi

Böylesini daha tanımıyorum

Acıtıyor yüreğimi ölüm

Ezik adımlarla uzaklaşıyorum.

Bebek''te tanıdıklara rastlıyorum

Nasıl da hızlı geçiyor zaman

Çoğunu anımsıyamıyorum

Belleğim mi nankör,bende mi bir şey var? 

Özlem ne de güzelmiş meğer

İçlerinde yıllardır görmediklerim var.

Sarıyer''de bir börekçi var

Böreği güzel mi? Bilemiyorum.

Ama bir havası var ki bayılıyorum

Duvarlarında adsız ozanların şiirleri var

Boğazı boydan boya yürüyorum

Usul usul gün dağlara devriliyor

Doyuma ulaşmış bir gelin gibi

Eşsiz bir güzelliğe bürünüyor deniz.

seni düşünüyorum hala

Geri dönerken çaresiz.

17/6/1981', 'Boğaz''ı boydan boya yürüyorum Her adımla bir anıyı yineliyor belleğim Boğaz''ı boydan boya yürüyorum Sevişmeye arzulu bir gelin gibi deniz Bi...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bogazi-boydan-boya-yuruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ders Çalışırken', 'ders-calisirken-metin-yalti-vuk9r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Her anımsayış biraz arayıştır.''

Ne zaman ders çalışmaya dursam

Usulca gelirsin gözlerime

Bir sürü anı gelir belleğime

Okurum kitaplar yerine..

Bu sıra öyle sıkıştıki sınavlar

Bir kaç gün ara versen diyorum

On günde dokuz sınava gireceğim

Romayı bir versem Hukuk''u bitereceğim.

İşlerde bozuk bu ara, biraz da ondan

Kafamı topluyamıyorum bir türlü

O kadar zor değil,elbet başaracağım

Özlemin sorun,Onu ne yapacağım.? 

Yarınki sınava çalışırken geldi usuma

Bir  dal orkide görmüştüm çiçekçi vitrininde

Söz verdim kendime bu sınavı başaracağım

O güzel çiçeği sana göndereceğim.

 15,2,1981 /', '''Her anımsayış biraz arayıştır.'' Ne zaman ders çalışmaya dursam Usulca gelirsin gözlerime Bir sürü anı gelir belleğime Okurum kitaplar yerin...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ders-calisirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Allahasen.', 'git-allahasen-metin-yalti-rehjl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışarıda yağmur

Aklımda sen

Dışarıda kar

Aklımda sen

Dışarıda güneş

Aklımda yine sen

Bir saatin

Bir saatime uymaz

İstanbul musun? 

Git Allahasen.

28/2/2000  /Sevda Türküleri', 'Dışarıda yağmur Aklımda sen Dışarıda kar Aklımda sen Dışarıda güneş Aklımda yine sen Bir saatin Bir saatime uymaz İstanbul musun?  Git Allah...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/git-allahasen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Olurken', 'baba-olurken-metin-yalti-paeoo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Doğdun

Üçgün aç tuttuk

üç gün meme vermedik sana

adiloş bebem

hasta düşmiyesin diye

töremiz böyle diye

Saldır şimdi memeye

Saldırda büyü''

DOĞUM  YADA BABA OLMAK

Doğum tanrılaşmasıdır kadının

sancılar önce hafif hafif

Coşkuludur yürekler

sevinç büyük mü büyük

Kadınlığın yaratışa duruşudur bu büyüklük.

Zaman durağan değil

Bebek sabrın sınırını zorlamakta

sancılar acıya devrilirken.

Çığlıklar sık ve kesik kesik

İç parçalıyor çığlıklar

dayanılır gibi değil.

Çözülen bir giz sanki

Yaşamın anlamıymış bu duygular?

Yoksa yaşam yaşanılası değil.

Doktor hemşire ve diğerleri

Hiç bir şey yokmuş gibi

Öyle kayıtsızlar ki.

Ne sakin duruşları var?

Sağır değilsin,yüreğin mi soğuk?

Yakışırmı güzelliğine senin,

Hey hemşire böyle kayıtsız duruş.?

Deli olmak işten değil

Şimdi gülüyor çığlıkları duydukça.

Yaklaşıp sormak gerek,

-Genç annenin çektiği acıyı duyuyorsunuz.

Böyle kaygısız ve gamsız olunmaz,

bayan siz sadist misiniz.?

Böyle sorarsam eğer

Yüzü dalgalanır mı bilmem.

Nasıl bir yanıt verir birden.?

Doğum devrimsel bir olaydır.

Aklımı okudu sanki

Sustu gülüşü birden

bana dönüp dediki

-Bu gördüğünüz yüz 

acının mutluluğunu taşır.

her doğumda bir devrime tanıktır.

bayım biraz bekleyiniz.

sizde bu mutluluğu duyacaksınız.

Bakın işte doğdu oğlunuz.

Kutlarım sizi

Artık Baba oldunuz.

21,9,1985', '''Doğdun Üçgün aç tuttuk üç gün meme vermedik sana adiloş bebem hasta düşmiyesin diye töremiz böyle diye Saldır şimdi memeye Saldırda büyü'' D...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/baba-olurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Bedeli', 'hasretin-bedeli-sevgisiz-sair-lgc5x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzaklardasın

aramız soğuk karlı dağlarla dolu

ve bende ki sevgin 

üşümeye başladı

gidilmeyecek en uzak yere doğru

ayrılığa doğru....

ve yalnız 

sensiz ve yakında sevgisiz,

hasret bu ,

inanılmayacak 

en uzak sevgilere gebe

ama sen ;

''sevgi''

üzmek te istemem seni

ne olur bağışla beni

seni mısralarımda anacağım

sonsuzlukla bütünleşecek en son mısralarımda', 'uzaklardasın aramız soğuk karlı dağlarla dolu ve bende ki sevgin  üşümeye başladı gidilmeyecek en uzak yere doğru ayrılığa doğru.... ve yaln...', ARRAY['Türk Edebiyatı','Şiir','Sevgisiz Şair']::text[], 8.5, '{"poet":"Sevgisiz Şair","poet_slug":"sevgisiz-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasretin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ellerimden', 'tut-ellerimden-metin-yalti-4vsoz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tut Ellerimden

Ne seni özlediğim yalan

Ne de çekip gideceğim hayatından

Bir mazgalın demirlerinden

Çıkarıp kafasını 

Şaşkın bakınan fare misali

Baka kalsam da yaptıklarına...

Burnunu okşar gibi

Saçlarını okşamak geçer içimden

Suçum buysa

Gitmedim,gitmeyeceğim de hayatından

Yalan seni özlemediğim yalan.

Bir oyun sayma yaşamı

Doğru kişiyim yanlış zamanda

Sahte hiçbir şey yok bende

İçtenim tüm söylediklerimde..

Hala başaracağım imkansızı

Hissediyorsun bunu sende

Şimdi bir zaman yumağındayız

Vaktimiz var daha......

Haykıracağım

Seni sevdiğimi

Bütün gücümle hem de

Peşini sakın ha bırakma sende

Aşkla yüklen, hep yeniden

Dolduğunu sanma içindeki boşluğun

Unutamazsın asla.

Yalanlarla kendini avutma.

Başarabilirsin.Barış içindeki düşmanla

Seviş.İster tutkularınla,istersen benle

Arama beni bir başkasında

Yüreğim bâkir

Umutlarımda...

Saklama artık, söyle sevgini sende

Azat ettiğin acının

Sevince dönüştüğünü göreceksin

Özgürlüğün deli sarhoşluğunda..

Sevgim büyük

Seninkince

............

Hadi tut ellerimi.

2000,03,21', 'Tut Ellerimden Ne seni özlediğim yalan Ne de çekip gideceğim hayatından Bir mazgalın demirlerinden Çıkarıp kafasını  Şaşkın bakınan fare mis...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/tut-ellerimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül İçin', 'bir-gul-i-cin-onder-karadag-8ppqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Savrulupta gelme öyle

ceplerinde şiir kırıntıları

bela tadında

ağrısı başımın

bir nefes teneffüs

tebessümün

şi(n)irleniyorum.', 'Savrulupta gelme öyle ceplerinde şiir kırıntıları bela tadında ağrısı başımın bir nefes teneffüs tebessümün şi(n)irleniyorum....', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-gul-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Devrimcinin Armonikası', 'bir-devrimcinin-armonikasi-i-smet-ozel-6mqfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Binlerce binlerce çocuk

koşarak dokumuş benim kumaşımı

hançeremdeki bu şehrin

o geçimsiz mushafı

vardım dayandığım parmaklığına o büyük hesapların

Hazırım ey kalaycı çırakları ve güyümcüler

ey rakı sürülmüş yaralarım gövdeleşin

kırçıl acılarım benim

gök de bir mendil takınsın boynuna

benim kağşayan umutlarım gövdeleşin

çünkü ben oraya gidiyorum : boğulmaya.

Nasıl birer suç çağrışımıyız dünyada

adamlar,kadınlar,şehre indirdikleri bakraçları

ne kadar uydurma

ne kolay öpüşüyorlar yıllar süren intiharlarla

Oysa

insan zemheriyi

ve kadının doğurma vaktini bilir

hergün kalkıp öpüşebilir sabahın üniformasıyla

yeni şeyler,yeni şeyler yaratmak için tabi.

İşte potin bağlıyor çocuk

bütün uykularından sürülmüş kurşunlar

tütün gibi bakıyor nisanlara

ve ben sahici kılmak için öpüşlerimi

oraya gidiyorum : boğulmaya.

Ben ki gövdemi bütünüyle ne yapmalıyım

tahta bir bavul

gibi duruyorum insan kıyısında

makina

çok acemi buluyor beni sanırım

seyrek bir ölü vurdular alnıma,ekşi

1300 tarihli şehbenderlere dair talimata

ve anamın kanserine alıştım

ve de bir simsar gibi asvalta ve otobüslere

bir vitrin gibi

bir bıçak,bir

setre.

Tutuşan bir bıçak.

içerimde tozuyan bağırtılar vardır

Ondan işte gidiyorum oraya : boğulmaya.

Oraya gidiyorum boğulmaya

BOĞULMAYA

bir partizanın armonikasında.

Artık mazgallardan fırlamak

büyük kamalar saplamak

böğrüne coşarlığın

büyük bir çatırtının ayaklarını ovmak

armonikamla.

Ey çatlayan tohumun hengamesi!

İnsan,gülümsemeyi

ve ürün kaldırmasını bilir

çünkü derbeder bir okul çantasından

serin ve sevişli bir ırmağa girilir

ve benim o boğulduğum armonika

halklara seğirtir,coşar

o,korkunç bir yekinmedir buralarda

Hannoy''da bir uçaksavar.', 'Binlerce binlerce çocuk koşarak dokumuş benim kumaşımı hançeremdeki bu şehrin o geçimsiz mushafı vardım dayandığım parmaklığına o büyük hesa...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/bir-devrimcinin-armonikasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dişlerimiz Arasındaki Ceset', 'dislerimiz-arasindaki-ceset-i-smet-ozel-8w2ba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz şehir ahalisi, kara şemsiyeliler! 

Kapçıklar! Evraklılar! Örtü severler! 

Çığlıklardan çadır yapmak şanı bizdedir

Bizimdir yerlere tükürülmeyen yerler

Nezaketten, haklılardan yanayızdır hepimiz

Sevinmemiz çapkıncadır, ağlatır bizi küpeşteler

Yaşamak deriz -Oh, dear- ne kadar tekdüze

Katliamlar ne kötü be birader

Güneş neredeysek orada bulur bizi

Ya cünup ve yalancı veya miskin ve ülser

Falımız neyse çıksın diye açarız indeksleri

Sayılar bizi bulur, o ayıp işaretler

Saframızla kesemizi birleştiren anatomi bilgisi

Hadım tarih, kundakçı matematik, geri kafalı gramer

Evet bunlar gizlice örgütlenerek alnımıza

Verem Olmak Üretimi Düşürür ibaresini çizer

Biz şehir ahalisi, üstü çizilmiş kişiler

Kalırız orda senetler, ahizeler ve tren tarifesiyle

Kimbilir kimden umarız emr-i b''il-ma''ruf

Kimbilir kimden umarız neyh-i ani''l-münker

Bize yalnız oğulları asılmış bir kadının

Memeleri ve boynu itimat telkin eder.', 'Biz şehir ahalisi, kara şemsiyeliler!  Kapçıklar! Evraklılar! Örtü severler!  Çığlıklardan çadır yapmak şanı bizdedir Bizimdir yerlere tükür...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dislerimiz-arasindaki-ceset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-hakan-firen-xvxob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluk geç yatar

Erken kalkar

daha fazla insanla

Buluşmak için...', 'Mutluluk geç yatar Erken kalkar daha fazla insanla Buluşmak için......', ARRAY['Türk Edebiyatı','Şiir','Hakan Firen']::text[], 8.5, '{"poet":"Hakan Firen","poet_slug":"hakan-firen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mutluluk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilime İftira', 'sevgilime-i-ftira-i-smet-ozel-ld8cf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dudaklarından kalkarken boynun kurcalar beni

bir yanımı kara çıbanlara saldılar,ıslak

bir yanım hiç ayrılmamıştır,gümeçlerde saklıdır

ondan ki nefret içinde omzunu okşuyorum

ama bana şimdi gerçekten zor gelen şey

bir grevin çocuklara kazınmış izlerini hatırlamak

sözlerimi etime bastırıyorum

içimde çalılıkları yaran bir postalın tortusu

benim bu sası karanlığa zorla,zorlayarak

tutuşmuş bir gül sıkıştırmak boynumun borcu

yeter ki

sağlam senetler verilmiş sanılırken aşkı karartmak için

sen bir daha beni saçlarınla sıyır

ağdalanmış sevincimi hışırdat,bunu yapabilirsin

çünkü bütün bankalar,silah fabrikaları

her gün bacaklarımıza sırnaşan kara köpük

senin sessiz gururunda homurdanan tufanı

hesabetmiş değil

bilmemişler hıncımın yaban otlar suladığını

çalakalem sevebilmek elimden gelmiyor

belki evet

onların mühürlerini kımıldatan barut dumanlarını

solumaktan biraz çopurlanmıştır sesim

senin göğsünü ağartırken yıpranılacak elbet

bakışlar tozlanacak dolukmuş sofalardan

ezikliğin şehveti yayılınca

taptaze yaşlanmayı da öğrenmem gerekecek

iştedir yalanı seyreltiyor uykusuzluklar

aklımın köşesinden atlılar geçiyor

değil mi ki beni şımartan gökyüzüdür

ve ben o tanyerlerinin sulbünden gelmekteyim

hiç bir dostumu kalebent saymam parmaklıkların ardında

kan değildir dostlarımın çakrışına bulaşan

kan değil,mürekkep lekesi ben bilirim

çünkü birgün gerçekten kan aktığında

ölüm çiçeklerin yırtıcı dülgerliği sanılacaktır

karaysam şimdi öfkenin payı vardır karanlığımda

aşktandır titrediğim eğer ki titriyorsam

sözlerim öcalan ağza misvak,iyice anlaşılsın

bu dağlanmış toprağa süzülen ayaklarımdan

keşke kan olsa

o zaman 

senin çardağına çıkarken

karıştırırken şarapla kendimi sana

varsın gün geçtikçe herşeyde biraz kahır

biraz bakır çalığı olsun lokmamızda

bana soru sor artık

beni kurtarma,konuştur

beni yaz geceleri patlayan sağnaklara bağışla.', 'Dudaklarından kalkarken boynun kurcalar beni bir yanımı kara çıbanlara saldılar,ıslak bir yanım hiç ayrılmamıştır,gümeçlerde saklıdır ondan ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sevgilime-iftira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki Sen İste', 'yeterki-sen-i-ste-idhem-kadub-2ed9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben senin hastretine dayanamam artik,

Her saniye benim yanimda olmani isterim artik,

O saniyeler senin yaninda olmam cok zor,

Ama o zorlari asmak kolay gibisi bir sey yok,

Yeterki sen istedikten sonra.

Yeterki sen iste, Seni SEVEYIM

Yeterki sen iste, Ugrunda can vereyim

Yeterki sen iste, Gullu kokladigim gibi seni koklayim

Yeterki sen iste, Bu siiri kalemle yazdigim gibi seni kalbime yazayim,

Yeterki sen iste, Her saniye senin yaninda olayim

Yeterki sen iste, Su buyuk HASRETIMI SENINLE GIDEREYIM,

''Yeterki sen iste'' baska sana ne soyleyim.', 'Ben senin hastretine dayanamam artik, Her saniye benim yanimda olmani isterim artik, O saniyeler senin yaninda olmam cok zor, Ama o zorlari ...', ARRAY['Türk Edebiyatı','Şiir','Idhem Kadub']::text[], 8.5, '{"poet":"Idhem Kadub","poet_slug":"idhem-kadub","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeterki-sen-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-sair-veco-3kaj9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen sensizliği hiçbir zaman bilemeyeceksin

oysa ben onu 

ona alışacak kadar iyi biliyorum', 'sen sensizliği hiçbir zaman bilemeyeceksin oysa ben onu  ona alışacak kadar iyi biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Şair Veco']::text[], 8.5, '{"poet":"Şair Veco","poet_slug":"sair-veco","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sensiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-adnan-zeki-celebi-gdljj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yapraklar dökülürken birer birer 

Kabristandaki ölüler gibiydiler 

Son yaprakta düşerken 

Kanatsız kuşlar gibiydiler

Sonbaharı fırtınalı gecelerden 

Sonbaharı sarı yapraklardan hatırlarım

Sonbaharı ayrıldığımız o günden 

O mehtaplı gecelerden hatırlarım

Sonbaharı hasret çekenlere 

Sonbaharı yuvasız kuşlara sorarım

Hafif yağan yağmurlarından 

Bana verdiği ilhamından anarım

(Suluova / 14.09.1984 Cuma)', 'Yapraklar dökülürken birer birer  Kabristandaki ölüler gibiydiler  Son yaprakta düşerken  Kanatsız kuşlar gibiydiler Sonbaharı fırtınalı gec...', ARRAY['Türk Edebiyatı','Şiir','Adnan Zeki Çelebi']::text[], 8.5, '{"poet":"Adnan Zeki Çelebi","poet_slug":"adnan-zeki-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonbahar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yaprak', 'son-yaprak-adnan-zeki-celebi-cb4pz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar yağmuruyla

Dökülen son yaprak

Son hatıraydı o yeşil meşeden 

Son izdi o sonbahar kızıllığından 

Ayrılacaktım ki o meşenin altından

Kaldırdım başımı yukarılara

Doğan mehtabın ışığıyla 

Koptu dalından son yaprak 

Esti dallarda son rüzgar 

Bir yanlızlık çöktü içime birden 

Sanki bir yetimin yanındaydım

Acısıyla, yanlızlığıyla onlaydım

Ayrılmak gelmedi içimden 

Ayrılmak istemedim o garip meşeden

İşte o günden o meşeden hatıradır; 

Bu kuru, cılız son yaprak', 'Bir sonbahar yağmuruyla Dökülen son yaprak Son hatıraydı o yeşil meşeden  Son izdi o sonbahar kızıllığından  Ayrılacaktım ki o meşenin altın...', ARRAY['Türk Edebiyatı','Şiir','Adnan Zeki Çelebi']::text[], 8.5, '{"poet":"Adnan Zeki Çelebi","poet_slug":"adnan-zeki-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Gül', 'sari-gul-adnan-zeki-celebi-3x98b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bahar yağmuruyla açtın kalbimde 

Bir mehtaplı gecede onun elinde 

Tek yaprağın kaldı artık elimde 

Benim güzel gülüm, sarı gül

Şebnem taneleri senin üstünde, 

Benimse ruhumun derinlerinde

Filizlenmiş dalın, benim gönlümde

Benim güzel gülüm, sarı gül

Dalını bükme sakın sert dolularda 

Kırdırma dalını fırtınalarda 

Sen solma sakın sonbaharda 

Benim güzel gülüm, sarı gül

Şimdi herşey bitti, artık ayrıldık

Ondan tek hatırasın elimde kalan 

Ellerine değen, onunla olan 

Benim güzel gülüm, sarı gül

(Suluova / 17.01.1986 Cuma)', 'Bir bahar yağmuruyla açtın kalbimde  Bir mehtaplı gecede onun elinde  Tek yaprağın kaldı artık elimde  Benim güzel gülüm, sarı gül Şebnem ta...', ARRAY['Türk Edebiyatı','Şiir','Adnan Zeki Çelebi']::text[], 8.5, '{"poet":"Adnan Zeki Çelebi","poet_slug":"adnan-zeki-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sari-gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuğum', 'tomurcugum-adnan-zeki-celebi-emgok', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açmamış bir tomurcuksun sen, 

Filizlenmiş bir dal

Şebnem taneleri arasında 

Esrarengiz güzelliğin durur karşımda 

Canlı bir abidesin,

Solmasın güneşin

Açma çeneğini hep böyle saf kal 

Nazlı dallarına değmesin rüzgar 

Esmesin fırtına çıkmasın bulut 

Rengarenk kal dallarının arasında 

Mis kokulu güzel çiçeğim', 'Açmamış bir tomurcuksun sen,  Filizlenmiş bir dal Şebnem taneleri arasında  Esrarengiz güzelliğin durur karşımda  Canlı bir abidesin, Solmas...', ARRAY['Türk Edebiyatı','Şiir','Adnan Zeki Çelebi']::text[], 8.5, '{"poet":"Adnan Zeki Çelebi","poet_slug":"adnan-zeki-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tomurcugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkmıydı', 'askmiydi-adnan-zeki-celebi-yq6vq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylar yıllar geçti anılarımızın üzerinden 

El ele tutuştuğumuz o günler 

O tozlu okul sıralarından 

Şimdi neredesin kimlerlesin bilmiyorum

Ama hayalimde yaşattığım sen benlesin

Aşkmıydı o duygu o hisler bilmiyorum

Kalbimdeki çırpınış o heyecan

Sesimin titreyişi sana olan  saygım 

Sevgimin ifadesimiydi bilmiyorum

Hatırlarmısın senden bakışlarımı saklardım 

Gözlerim sana değmesinden korkardım

Sakladığım sevgimmiydi bilmiyordum 

Sana duyduğum hislerim 

Hayalimdeki hatıraların sevgi dolu bakışın 

Üzerimde hala var özlüyorum

Seni o güzel anılarımızla bekliyorum

(Suluova / 29.11.1987)', 'Aylar yıllar geçti anılarımızın üzerinden  El ele tutuştuğumuz o günler  O tozlu okul sıralarından  Şimdi neredesin kimlerlesin bilmiyorum A...', ARRAY['Türk Edebiyatı','Şiir','Adnan Zeki Çelebi']::text[], 8.5, '{"poet":"Adnan Zeki Çelebi","poet_slug":"adnan-zeki-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askmiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-tugba-akin-ae2yr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yine eski mazinin 

Hüzün rüzgarları esiyor

Yine yapraklarını döküyor

Yıllanmış bir ağaç

Eski maziye dönül dilekler tutuluyor

Yine ağlanıtor ağıtlar gibi

Yine çalıp,söyleniyor düğün gibi

Sayfalar tek tek açılıyor

Eski şarkılar dillerde

Efkarla yazılan şiirler ve

Yine gözyaşları akıtılıyor

İçindeki boşluğu anlıyorsun biranda

Kuvvetli bir rüzgarın ardından

Öfkeyle sayfalar kapanıyor

Ve yine yaşama buruk bir maziyle

Devam ediliyor..', 'İşte yine eski mazinin  Hüzün rüzgarları esiyor Yine yapraklarını döküyor Yıllanmış bir ağaç Eski maziye dönül dilekler tutuluyor Yine ağlan...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Akın']::text[], 8.5, '{"poet":"Tuğba Akın","poet_slug":"tugba-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-tugba-akin-uaf9s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim seni 

Özledim yine maziyi

Yine sen geldin aklıma yıkıldım

Bir hüzün çöktü içime

Belki de oyunun bittiğini gösteren

Sahte gülücüklerdi

Aslında sen sahte gülücüklerin arkasında

Nefretle kinin birleştiği yerde olan birisi

İşte yini söylüyorum,

Özledim seni 

Özledim yine o yalan maziyi

Gözlerimden dudaklarıma süzülen yaşlarla

Seni bekledim ve bekleyeceğim..', 'Özledim seni  Özledim yine maziyi Yine sen geldin aklıma yıkıldım Bir hüzün çöktü içime Belki de oyunun bittiğini gösteren Sahte gülücüklerd...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Akın']::text[], 8.5, '{"poet":"Tuğba Akın","poet_slug":"tugba-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozledim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-tugba-akin-qo69c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılık vakti geldi bebeğim

Benim gzlerimden senin sözlerinden belli

Artık tamamen yitirdik birbirimizi

Senle ben bir bütün olamadık

Ay ışığında dans edip

Ölümsüz aşkımızı serenat yapamadan

Doğan güneşin sisli ışıkları arasında,

Kaybolup gittik.

Yaşanılan o koskoca yılları

Bir dakikada toprağa gömdük

Yakılan herşeyin küllerini savurduk

Mühürledik gökyüzüne.

Lanetler yağdırdık o eşsiz gözlerimize

Meğersem herşey bittikten sonra

Acıda olsa daha çok andık adımızı..', 'Ayrılık vakti geldi bebeğim Benim gzlerimden senin sözlerinden belli Artık tamamen yitirdik birbirimizi Senle ben bir bütün olamadık Ay ışığ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Akın']::text[], 8.5, '{"poet":"Tuğba Akın","poet_slug":"tugba-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayrilik-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berkan Ve Tuğba', 'berkan-ve-tugba-tugba-akin-4amoi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buğulu bir denizin içinde

Erişilmez bir limandın

Rayına oturmuşken herşey

Kaçıp gittin 

Ansızın

Ne olduğunu anlayamadan

Tüttü dumanı

Uğutular içinde

Belli belirsiz

Ay ışığında kaybolup gittin..', 'Buğulu bir denizin içinde Erişilmez bir limandın Rayına oturmuşken herşey Kaçıp gittin  Ansızın Ne olduğunu anlayamadan Tüttü dumanı Uğutula...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Akın']::text[], 8.5, '{"poet":"Tuğba Akın","poet_slug":"tugba-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/berkan-ve-tugba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulvar İti', 'bulvar-i-ti-hasan-huseyin-korkmazgil-iftc5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne zaman sevmek desem bir tedirgin bulvar iti gecede

biraz müzik biraz içki ve çok çok resim

kim sarmalar bu bebeği

kimler taşır bu ölüyü belirsizliğe

nerelerde kalır gözüm/nerelerden döner sesim

bu ne biçiim hayvan ki bu/beslenir acılardan

tohum atar kuşaklara kan göllerinde

bu ne biçim oyun ki bu/gizlenir gölgesine gerçeğin

mutluluklar aranır ateş çemberlerinde

bir umarsız bulvar iti vitrin ışıklarında

anladım ki birdenbire/kopmuşum toprağımdan

kopmuşum masallara süt emziren akşamlarımdan

köklerim orda sızlar/yapraklarım bulvarda

resim diye duvarlarda müzik diye ıslıklarda

o çıldırtan deniz orda/balıklar tablalarda

özlemek orda kalmış özlemi sevmek burda

ferhat''sa mendil açmış dileniyor güvenparkta

taradım bütün sözlükleri aşka yer yoktu

bir kaygulu bulvar iti karanlık çıkmazlarda

koşuyordu masallarda/koşuyordu imgelerde

başka yer yoktu

başımdaki ağrı sendin sesimdeki kuşku sen

ne düşünsem dört boyuttu ne ağrısam dört boyut

kopmak belki bir ülkeydi tutkular eski zindan

heerkes kendi bukağısının tutkulu demircisi

bu evleri bizmi yaptık bu yolları bizmi çizdik

ölümlerden bizmi kaçtık bizmi düştük ölümlere

senleştirip giriyorum koynuna gecelerin

senleştirip açıyorum gözlerimi sabaha

bir şey eksik biliyorum bir şey artık sen değil

şafak diye söken sendin sendin gülen penceremde

çayımdaki bahçe sendin içkimdeki bulut sen

içimdeki kuş sürüsü çabamdaki arılardınnere gitsem karşımdaydın ama sen yoktun

sen sahi niçin yoktun

senleştirip biniyordum külüstür taşıtlara

senleştirip okşuyordum osmanlı sokakları

kan bulaşmış caddeleri ölülerli alanları

tepelenmiş çiçekleri kanatılmış mavileri

senleştirip seviyordum bütün çirkinlikleri

telefonlar sensin diye koşturuyordum

kanıyordum

sensin diye karanlık çağrılara

susuyordum senleştirip kahpelikleri

nere gitseem karşımdaydın ama sen yoktun

sen sahi niçin yoktun

duruyordum seni sanıp yangın çığlıklarına

yaşaamak belki buydu belki de öbür yüzü

unutmaktı belki güzel aramaktı belki sevmek

belkideki varsıllıktı kesindeeki yoksulluktu

yitirmek buydu belki yakalamak belki bu

bu kafesi biz süsledik biz aldandık bu süslere

içimdeki sızı sendin yüzümdeki merak sen

gitmelerden beklediğim kalmalardan korktuğum

nere gitsem karşımdaydın ama sen yoktun

sen sahi niçin yoktun

ikibulvar itiyiz biz reklere dolaşmışız

ağzımızda ölüm tadı tüylerimiz kanlı çamur

ikimiz iki yandan bir koca yanlızlığı

bir amansız şaşkınlığı ikimiz iki yandan

dolaştırıp duruyoruz eski zamanlar gibi

müzelik bir inanmanın ören kapılarında

anlamamak elde değil anlamaksa soykırım

uçup uçup düşmek kalır inanmaklardan

kelebekler konuyor yaşlı salyongozlara

ölülerin gölgesinde diriler güneşleniyor

yakın artık gemileri köprüleri atın artık

kim ne derse desin vazgeçin onarımdan

ne seçilen renklerdeyiz ne gidilen yerlerde

danışıklı gözyaşları yapmacık mutluluklar

soykırımsaal bir çoğalma solucanımsı bir eşleme

bir yanımız doğum evi bir yanımız hiroşima

iki bulvar itiyiz biz koşulların kölesiyiz

zincir sesi duydukça sızlar bileklerimiz

bir kenti tanır gibi tanıdım seni ancak

eetine değdi etim/otuzaltı onda yedi/çok değil

elini buldu elim/otuzaltı onda yedi/çok değil

öptüm seni/otuzaltı onda yedi/dudaklarından

bir kenti yaşar gibi yaşadım seni ancak 

yaşamadım kendimi

ellerin ellerimdeydi ellerin yoktu

gözlerin gözlerimdeydi gözlerin yoktu

iki portre gibi yanyanaydık albümde

uykunda sevmiştin haberin yoktu

bir kaçağı tanır ggibi tanıdım seni ancak 

tanımadım kendimi

şarkılarda buldum seni yitirdim

yılgılarda buldum seni yitirdim

resimler bir türlü konuşmuyordu

fotoğraflar kaçıyordu ben yaklaştıkça

bir yalanı anlar ggibi anladım seni ancak

anlamadım kendimi

evin de mi yoktu senin sokağındamı

adresini silip silip yazıyorlardı

düşlerin türkçe miydi hotantoca mı

çincee mi arıyordun eskimoca mı

herkesste mi arıyordun ne arıyordun

neden öyle gülüp gülüp yaşlanıyordun

bir yüzünü buluyordum öbün yüzün yok

birçizgini buluyordum öbür çizgin yok

olgörüp gelmiyordu adın fırçama

düş müydün düşüncemi anlamıyordum

uzattıkça ellerimi dağılıp gidiyordun

kendimden korkuyordum yoksa yokmuydum

binlerce göz binlerce yüz binlerce biçim

aradığım yerde yoktun sormadığım yerde var

etimdeki acı sendin kanımdaki kuşku sen

nere gitsem karşımdaydın ama sen yoktun

sen sahi niçin yoktun

SEN

SAHİ

NİÇİN

YOKTUN?', 'ne zaman sevmek desem bir tedirgin bulvar iti gecede biraz müzik biraz içki ve çok çok resim kim sarmalar bu bebeği kimler taşır bu ölüyü be...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/bulvar-iti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam ve Çocuk', 'aksam-ve-cocuk-hilmi-yavuz-g6epb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman iyice alçaldı… aşklar

görünür oldular ve ‘mazi kalbimde yara…’

o konak, yıkık, harap, anımsıyorum,

bulutlar ağır ağır inerdi odalara…

beklerdim, aşklar birer türküydü! 

bir kızak, sanki saplanmış kara; 

hiç bir şey kımıldamaz, öyle dururdu,

annemsi bir sessizlik çökmüş duvara…

o konakta herkes, büyük aile,

koştururdu, yazlar sanki bir sara

nöbeti gibi yaşanır, bir çırpınıştır

çocukluk, orada, boş akşamlara.', 'Zaman iyice alçaldı… aşklar görünür oldular ve ‘mazi kalbimde yara…’ o konak, yıkık, harap, anımsıyorum, bulutlar ağır ağır inerdi odalara… ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmeyi Sevmem', 'gecikmeyi-sevmem-serhan-karaduman-itq3j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dediğimden dönmem arkadaş,

ne yapsan ne etsen dönmem,

bu saatten sonra ölüm yakışır bu işe yaramaz vücuda,

bu saatten sonra gitmek yakışır,

silahını çekip te güneşe doğru yürüyen yanlız kovboy gibi,

artık hesap verme zamanı geldide geçiyor be arkadaş,

kimseye küskün değilim, insanlarıda hep sevdim,

bazen ağladım ama güldüm elbette,

işte benimde gitme zamanım ;

her fani gibi,

her şeyim hazır ,

dostlarla vedalaştım,

eski segililere mektup yazdım,

adresleri değişmediyse tabi,

bir de şişede yanlız kalmasın diye son kadehide devirdim,

artık hazırım,

ey ölüm, gel al beni ,

bilirsin gecikmeyi sevmem..', 'dediğimden dönmem arkadaş, ne yapsan ne etsen dönmem, bu saatten sonra ölüm yakışır bu işe yaramaz vücuda, bu saatten sonra gitmek yakışır, ...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gecikmeyi-sevmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matem', 'matem-nurullah-fidan-0u00f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık düşünceler ardından

Son bir haykırışım yükselir

Ve rüzgarın arkasından 

Seni seviyorum diye inlenir

Karanlık düşünceler ardından

Bir düşünce seni hatırlatır

Gece gündüz yaşlı gözlerim

Kan ile bürünmüş örtülür

Damarlarımdan akan kanım 

Kopkoyu kesilip adeta donar

Ki seni unutmamak hayaliyle 

Aklıma gelen hayalini tutar', 'Karanlık düşünceler ardından Son bir haykırışım yükselir Ve rüzgarın arkasından  Seni seviyorum diye inlenir Karanlık düşünceler ardından Bi...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Fidan']::text[], 8.5, '{"poet":"Nurullah Fidan","poet_slug":"nurullah-fidan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/matem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum...', 'usuyorum-sair-doktor-3zxaw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk ve karanlık bir Aralık

keskin bir bıçak gibi sızıyor ayaz

kalbimin ışıksız kırıklarından...

Güneşin bulutunda gizli,

ve de sıcağın ikliminde...

Bilmem ne çare bulmalı uzaklığına?

ya da sıcağı senden yoksun ışıksızlığıma...

Güneşinim diyordun,al işte zaman

üşüyorum birtanem

teninden biraz sıcak,

ve o güneş dolu gözlerinden

biraz ışık ver bana!', 'Soğuk ve karanlık bir Aralık keskin bir bıçak gibi sızıyor ayaz kalbimin ışıksız kırıklarından... Güneşin bulutunda gizli, ve de sıcağın ikl...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usuyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Arifesi', 'bayram-arifesi-bayram-tunca-5p98v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl da çarçabuk gelip geçti, Ramazan

Arefe gelmese, anlamazdı gittiğini insan

Ne de çabucacık geliverdi, şu güzel arife

Hiç gitmeseydi, bayramın müjdecisi arife

Tâ arefeden başlanırdı bayram hazırlığına

O gün, doyulurdu, börek, çörek kokusuna

O gün, kim ne yaparsa dağıtırdı komşuna

Ziyarete gidilirdi, mezarlıktaki mevtalara

Küçüklere tutturulurdu, arefe günü kuş oruçlar

Daha bayram gelmeden bayram ederdi çocuklar

Çünkü, her yakın komşu, bir şeyler getiriyorlardı

Çocuklar, sevinçten hangisini yiyeceğine şaşardı

O gün çocuklar, ümitle yatıp, neşeyle kalkardı

Sabah büyüklerle, bayram namazına giderlerdi

Bayram namazı sonrasında el öpmeler başlardı

Tabi ki cepler şeker, çıkolata ve parayla dolardı

Gün geçtikçe azalmaktadır, o güzel adetlerimiz

Nerede kaldı, o eski güzel ramazan günlerimiz

Nerede kaldı, o eski bulunmaz arefe günlerimiz

Nerede kaldı, o eski güzelim örf ve âdetlerimiz

Bayram der, keşke yaşatabilseydik o güzelliği

Keşke yeni nesile gösterebilseydik o güzelliği

Belki o zaman olmazdı,  bu günkü bu soğukluk

Belki de komşuluk bağının artmasını sağlardık

Şair der, ben eski ramazan ve arefeyi arıyorum

Ben eski dost ve o günün özlemiyle yanıyorum

O günlerin hatıralarıyla, yaşamaya çalışıyorum

Günümüzün âdetlerine, alışmaya çalışıyorum

B. TUNCA/26.12.2000-14.14', 'Nasıl da çarçabuk gelip geçti, Ramazan Arefe gelmese, anlamazdı gittiğini insan Ne de çabucacık geliverdi, şu güzel arife Hiç gitmeseydi, ba...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bayram-arifesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem ve Akşam', 'annem-ve-aksam-hilmi-yavuz-g0fpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir kapı açıldı, ansızın, baktık:

akşam!.. kimse benzemez oldu kendine;

kimbilir ne kadar hüzünlü artık,

bir odadan ötekine geçmek bile...

sen neysen o kadarsın, ey akşam!

annem içini çekiyor kimi ansa;

ürkü!.. biri ansızın bir gül koparsa;

şimdi uzak olandır neye ulaşsam...

ah, akşamdan bile ürküyor çocuk;

her yer alacakaranlık gurbet;

soldu annem, solarken goblen ve tülbent;

ve akşamın ucuna doğru yolculuk...

bir türkü söylendi, neyin tadı var?

akşam bile bitti, kalmadı çünkü...

çekildik, bir başına kaldı o türkü;

kapılar arkamızdan kapanmadılar...', 'bir kapı açıldı, ansızın, baktık: akşam!.. kimse benzemez oldu kendine; kimbilir ne kadar hüzünlü artık, bir odadan ötekine geçmek bile... s...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annem-ve-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam ve Kandil', 'aksam-ve-kandil-hilmi-yavuz-kovsk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mevsimidir,

kendi hüznüme döndüm...

akşam annemle aramda 

		 bir süs

gibi dururdu;

saatler rikkatle vururdu;

		 özensiz		

bir eşya kuraklığı

dağılmış bahçemize;

ve her şey kandil...

hangi ağacın yapraklarını 

siyah kadifeyle örttün Ölüm?

hangi Söz’ü bana verdin

de benden geri aldın,

		     ey Dil?

Birden mevsimler selsebil

Aktılar; görünmemekti dileğim;

Siyah kadife sızdırıyor,

Işıkta yağlanıyor gül,

Odamda kirli meleğim...

Annem kandili siliyor:

                              ‘mendil,

mendil nereder?’

akşam, annemle aramda bir süs!', 'mevsimidir, kendi hüznüme döndüm... akşam annemle aramda  		 bir süs gibi dururdu; saatler rikkatle vururdu; 		 özensiz		 bir eşya kuraklığı...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aksam-ve-kandil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Ve Sen Ve Ben', 'aksam-ve-sen-ve-ben-hilmi-yavuz-it0gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ikimizdik, sen ve ben, bir çiçekle

onun tomurcuğu arasında bir yerde;

öylece durur muyduk, ikimiz gibi?

dâima birlikte olurduk  hüzünlerde...

anımsar mısın, yaz günü, bir bahçeyle

gizledikti kendimizi birbirimizden;

sen ve bahçe, ben ve bahçe, sen ve ben:

akşamlar derlerdik her ikimizden...

üşürüz, çünkü uzağız şimdi o yazdan;

ey, birazdan bir yazdan geçer olan, ey!

kimbilir ne anlama geliyor artık,

şu eskiden “hüzün” dediğimiz şey?', 'ikimizdik, sen ve ben, bir çiçekle onun tomurcuğu arasında bir yerde; öylece durur muyduk, ikimiz gibi? dâima birlikte olurduk  hüzünlerde.....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-ve-sen-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Ağrısı', 'kalp-agrisi-hakan-yigit-91v9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabaha kadar gözlerim kapanmıyor

Bir özlem bu içimde yıllardır kaynıyor

Ne bir çare buldum bu belirsizliğe

Ne bir arkadaş;kalbim şimdi ağrıyor...

     

 (26 Aralık 2000 15.50)', 'Sabaha kadar gözlerim kapanmıyor Bir özlem bu içimde yıllardır kaynıyor Ne bir çare buldum bu belirsizliğe Ne bir arkadaş;kalbim şimdi ağrıy...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kalp-agrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlanış', 'canlanis-hakan-yigit-38akj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız gözlerin var gözlerimin önünde

Beni sana bağlayan bir köprü gerçekte

Cansız vücuduma hayat veren sensin

Seni seviyorum bisen de bilmesen de...', 'Yalnız gözlerin var gözlerimin önünde Beni sana bağlayan bir köprü gerçekte Cansız vücuduma hayat veren sensin Seni seviyorum bisen de bilme...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/canlanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-hakan-yigit-kq2fw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesini duymak da güzel görmeden seni

İyiyi,güzeli paylaşmak kırmadan seni

Sensiz olmuyor be,olmuyor dostum

Yine seni arıyor bu gözler,yine seni...', 'Sesini duymak da güzel görmeden seni İyiyi,güzeli paylaşmak kırmadan seni Sensiz olmuyor be,olmuyor dostum Yine seni arıyor bu gözler,yine s...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dostum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-hakan-yigit-l39ln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeşilin kokusunu,sevginin tadını özledim

Yağmurun yağışını,karların eriyişini özledim

Daha kapanmadı kapılar ışık var uzaklarda

Ben yaşamayı,ben sevneyi özledim...', 'Yeşilin kokusunu,sevginin tadını özledim Yağmurun yağışını,karların eriyişini özledim Daha kapanmadı kapılar ışık var uzaklarda Ben yaşamayı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozledim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-hakan-yigit-0gijj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimde top,yüzümde gülücüklerle koşuyorum

Sayıyı atıp,hayali yeniden yaşamak için koşuyorum

Hem uzakta da değil oldukça yakın

Aslında...Zor bile yürüyorum

Rüyadayım,özgür olduğum için koşuyorum...', 'Elimde top,yüzümde gülücüklerle koşuyorum Sayıyı atıp,hayali yeniden yaşamak için koşuyorum Hem uzakta da değil oldukça yakın Aslında...Zor ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ruya-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Dakika', 'her-dakika-hakan-yigit-xw678', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar tıkandı seni ararken karanlıklarda

Beni özlemin sardı sensiz geçen dakikalarda

Bir sesin bile yeterdi hasretini hafifletmeye

Oysa ben seni isterdim her anımda yanımda...', 'Yollar tıkandı seni ararken karanlıklarda Beni özlemin sardı sensiz geçen dakikalarda Bir sesin bile yeterdi hasretini hafifletmeye Oysa ben...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-dakika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpkırmızı Bir Kalp', 'kipkirmizi-bir-kalp-hakan-yigit-38vf0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sende kırmızının en koyusunu yaşıyorum

Tüm yıldızlara inat seninle birlikte parlıyorum

Senin için en parlak kumaştan sevgiyi dikip

İçine de yalnız sana çarpan kalbimi koyuyorum...', 'Ben sende kırmızının en koyusunu yaşıyorum Tüm yıldızlara inat seninle birlikte parlıyorum Senin için en parlak kumaştan sevgiyi dikip İçine...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kipkirmizi-bir-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk Kadar', 'sonsuzluk-kadar-hakan-yigit-3755a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni yaratabileceğin en sonsuz hayallerle seviyorum!

Belki okyanusta toprağa gömülü ufak bir taşım

Belki bir karıncanın ayak ucundayım

Belki de sadece bir ekmek kırıntısıyım

Gönlümün hiçbir şekle sığmayan dünyasıyla 

Seni en küçük noktalarda bile yaşıyorum...

Seni çizebileceğin en kalın çizgiler kadar seviyorum!

Sanki bardakta tek başına duran su damlası

Yeryüzüne düştü mü suskun kalan dolu tanesi

Seni en küçük umutların çokluğuyla seviyorum...

Seni aşkların en güzeli en safıyla seviyorum!

Yıldızlar kadar parlak,güneş kadar sıcak,

Bir şiir gibi tarifsiz,bir şiir gibi sınırsız,

Gün doğumunda beklenen,ay ışığında özlenen...

Güzelliğin adını sana taşıyan sıfatların imzasıyla

Yitirdiği anlamını seninle kazanan hayatımı

Sonsuzluğun şahitliğinde,sana adıyorum...', 'Seni yaratabileceğin en sonsuz hayallerle seviyorum! Belki okyanusta toprağa gömülü ufak bir taşım Belki bir karıncanın ayak ucundayım Belki...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yiğit']::text[], 8.5, '{"poet":"Hakan Yiğit","poet_slug":"hakan-yigit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonsuzluk-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk...', 'ask-ejdat-ertas-czqx6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dipsiz bir kuyuymuşcasına;

Düşüyormuş gibi hissediyorum kendimi

Herseferinde yalnızlık,

Herseferinde acı çekiyorum.

Nedendir bilinmez ama;

Yinede seviyorum Aşık olmayı,

Acı çekmeyi,yalnızlığı,

Ve...

Nefret etmeyi...

(25-12-2000)', 'Dipsiz bir kuyuymuşcasına; Düşüyormuş gibi hissediyorum kendimi Herseferinde yalnızlık, Herseferinde acı çekiyorum. Nedendir bilinmez ama; Y...', ARRAY['Türk Edebiyatı','Şiir','Ejdat Ertaş']::text[], 8.5, '{"poet":"Ejdat Ertaş","poet_slug":"ejdat-ertas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıltaşı', 'cakiltasi-i-lhan-tulman-w3po2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kenarda dururdum ben

durup dururken bir hüzün

ince bir tuz izi gibi rahlede

ellerimde kıvranan bir akdeniz gibi

küçük bir çakıltaşı gibi severdim seni

küçücük bir çakıltaşı gibi

paramparça, rengarenk

Ben rengarenk diyorum ya

sen hüzün de

denizi beslemekten yorulan gözlerim

ayetlerden kaçan şeytan

Kanım kurudu. aynalar sırlarını verdi

bir deniz üstünde. ah bir deniz üstünde.

yürüdüm. yetmedi şarkılar

Dün gece düşlerdi, sıcak bir kedi

sıcak bir dokunuş, ah med cezir

ah ateşti dudakların

yağmur yağıyormuydu, yoksa o ses

Bu ses, çingeneler gibi atakta duran bıçak

boynımda yağlanan kokun dolu eşarp

derin dehlizlerde sır, işte sır

sarılmak, ah sarılmak yalın ve korkak

Küçük bir çakıltaşı gibi sevdim seni

aynalarda durdum

ah ben ne kadar sen', 'Bir kenarda dururdum ben durup dururken bir hüzün ince bir tuz izi gibi rahlede ellerimde kıvranan bir akdeniz gibi küçük bir çakıltaşı gibi...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cakiltasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşlerin Uslanmaz Zamanı', 'ateslerin-uslanmaz-zamani-i-lhan-tulman-a9cx3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben sabah bir koltuktan kalkmıştım

bir pencereden fırlatmıştım kendimi

yorgundum,zaten ben hep öyle

en uzak neresidir diye bakınıyordum çıkmaz sokaklara

ellerim yağlı ve kirliydi

bu hep böyleydi

aylardan ihtimal ki bahardı

ben bunu kedi seslerinden

içimde biriken sızılardan

bütün gözlerin aşka açık duruşundan

maria''dan biliyordum

ateşlerin uslanmaz kızından

maria;sabahları duran denizlere benzerdi

akşamları içinden masallar geçen ateşlere

uzanıp yatardı

bacakları uzun bıçaklar gibi

gergin telaşlı cüretkar

ben böyle kahverengi görmemiştim

maria;ateşlerin uslanmaz kızı

ben bu sabah bir koltukta oturuyordum

yani içime doğru genişliyordum

içime toparlıyordum kendimi

ıssızlıkla başlayıp

ıssızlıkla bitiyordu gün

aynalara benziyordum

sessizliğine

maria;

gözlerine geliyorum

aşka açılan dehlizlere

kemanın son sesine benzeyen sevişmelerine

bekle maria

unutma

en uzak şehir ancak sevişmemeiz olur

biz ancak ateş

ve en çılgın iki kahverengi', 'ben sabah bir koltuktan kalkmıştım bir pencereden fırlatmıştım kendimi yorgundum,zaten ben hep öyle en uzak neresidir diye bakınıyordum çıkm...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ateslerin-uslanmaz-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakalşör', 'sakalsor-i-lhan-tulman-bxfzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yokluğun içinden geçtiydik

bir adam bir adamın ense kökü ve sardunya

ben eklemlenmiş bişeylerdim o zamanlar

bir yap bozun unutulan o meşum parçası

hangi dilde hangi şey nasıl söylenirse söylensin

yokluğun içinde o siyasi duruşun

şehrin en dehşetengiz saatiydik

sakallarımızda patlıcan,haydari

ve mevsimine göre kavun

meyhanelerin sessiz iki çığlığı

şairler abartmasaydı aşkı

belkim aşık bilem olabilirdik

neyse neydi,neydim,meydik

can''dık taklid-i içer', 'yokluğun içinden geçtiydik bir adam bir adamın ense kökü ve sardunya ben eklemlenmiş bişeylerdim o zamanlar bir yap bozun unutulan o meşum p...', ARRAY['Türk Edebiyatı','Şiir','İlhan Tülman']::text[], 8.5, '{"poet":"İlhan Tülman","poet_slug":"i-lhan-tulman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sakalsor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Ayrıntı', 'mavi-ayrinti-ahmet-ocal-fcwqh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçinden iftar sesizliğiyle geçen

O ince ayrıntı ; sır değil artık...

Yüzünü sana dönmüş ne kadar mavi varsa 

Ben kandırdım hepsini

Sen geçerken gecemin sabaha karşı yanından

İçimin senfoni orkestrası

En davullu şarkısını çalıyor...

Eğik bir yeşilim var osıra

Dalım doğru , güzüm düz

İnat yüklü kervanım

Ahım develerim sırtında...

Gökkuşağından karşı tarafa

Eksi-k olarak geçiyorum

Sonbahar kadar ekmek

Ölecek kadar sevmek istiyorum...', 'İçinden iftar sesizliğiyle geçen O ince ayrıntı ; sır değil artık... Yüzünü sana dönmüş ne kadar mavi varsa  Ben kandırdım hepsini Sen geçer...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öcal']::text[], 8.5, '{"poet":"Ahmet Öcal","poet_slug":"ahmet-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mavi-ayrinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-ali-kirgic-bgh9e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni ansızın terk ettin 

Kalbim dayanmaz bu acıya.

Kin kusmaktan midem bile 

Kan ağlarken sen bide 

Kalbimi düşün.

Unutma elbet birgün sende

Anlayacaksın terkedilmeyi

İnanki dışardan gözüktüğü gibi değil

Anlamak isyoyorsuın ama 

Anlayamıyorsun.

Anlatmak istiyorusn ama

Anlatamıyorsun.

Gülmek zor geliyor 

Ağlamak çözüm gibi.

Tutmak istemiyor dizleri insanın 

Görmek ise anlamsız

Manasız geliyor herşey 

Anlayamıyorsun.

Kabir azabı derler

Asıl azap burada 

Gerçi ölüm bile kolay geliyor insana 

Dokunası geliyor insanın eli tetiğe

Çare bulunmamış güzelim bu derde 

Unutmak ise hiç mümkün değil

Baktığın heryerde onu hissetmek 

Ona dokunuyormuş gibi 

Bebeği sevmek 

Unutturmuyor insana.

Ve ansızın bitmesi herşeyin 

Yaşama arzusunun,

Tutkunun bitişi gibi oluyor

Ama yinede ansızın bitiveriyor herşey.', 'Beni ansızın terk ettin  Kalbim dayanmaz bu acıya. Kin kusmaktan midem bile  Kan ağlarken sen bide  Kalbimi düşün. Unutma elbet birgün sende...', ARRAY['Türk Edebiyatı','Şiir','Ali Kırgiç']::text[], 8.5, '{"poet":"Ali Kırgiç","poet_slug":"ali-kirgic","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ansizin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Hiç Bir Şeydir', 'unutulan-hic-bir-seydir-ali-kirgic-dyv4i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim unuttum diyorsa yalandır

Yalancıdır bunu söyleyenler.

Onlar ya sevmemişlerdir yada

Sevgiyi yanlış tanımışlardır 

Kim unutmuş söyleyin bana

Aşık Veysel, Karacaoğlan

Unutmuşmudurki bende 

Unutabileyim.

Karanlıksa gece 

Onu düşünür aydınlanırız

Rengi kötüyse gökyüzünün

Birazcık onu süreriz

Güzelleşir.

Yağmur damlacıklarına bile 

Onun resmini çizeriz.

Bir başkadır bulutlar gökyüzünde.

Heryer kararsa bile o aydınlıktır.

Yalanmıdır ki bunlar 

Kim bunları hissetmişte unutmuş ki

Kibir bile yenememiş sevgiyi 

Değilki biz aşıklar yenelim.....', 'Kim unuttum diyorsa yalandır Yalancıdır bunu söyleyenler. Onlar ya sevmemişlerdir yada Sevgiyi yanlış tanımışlardır  Kim unutmuş söyleyin ba...', ARRAY['Türk Edebiyatı','Şiir','Ali Kırgiç']::text[], 8.5, '{"poet":"Ali Kırgiç","poet_slug":"ali-kirgic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unutulan-hic-bir-seydir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sila Aşktır', 'sila-asktir-sezai-karakoc-po3ja', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ülkedeki kuşlardan ne haber vardır

Mezarlıklardan yükselen bir bahar vardır

Aşk celladından ne çıkar madem ki Yar vardır

Yoktan da vardan da Öte bir var vardır

Hep suç bende değil

Beni yakıp yakan bir nazar vardır

O şarkıya özenip söylenecek mısralar vardır

Sakın kader deme

Kaderin üstünde bir kader vardır

Ne yapsalar boş

Göklerden gelen bir karar vardır', 'Ülkedeki kuşlardan ne haber vardır Mezarlıklardan yükselen bir bahar vardır Aşk celladından ne çıkar madem ki Yar vardır Yoktan da vardan da...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sila-asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai', 'rubai-hurol-yucel-varm1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanılmış bir çınar gibi açyık yeşil yaprakları

Çınarsız şehirlere taktık yeşil yaprakları

Biz aslında yeşildik yapraktık biz aslında 

Aslında ayrılmıştık

              yaktık yeşil yaprakları', 'Yanılmış bir çınar gibi açyık yeşil yaprakları Çınarsız şehirlere taktık yeşil yaprakları Biz aslında yeşildik yapraktık biz aslında  Aslınd...', ARRAY['Türk Edebiyatı','Şiir','Hürol Yücel']::text[], 8.5, '{"poet":"Hürol Yücel","poet_slug":"hurol-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Yine Gece Oldu', 'i-ste-yine-gece-oldu-ugur-acikgoz-6365m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte gece oldu,sessiz ve karanlık

Yalnızlıgımı paylaşan sadece yalnızlık

Bana sorulmadan çizilmiş yolum

Ne kadar gidebilirim,bilmiyorum

Çıldırma dürtüsü tehdit ediyor aklımı

Bagırmak istiyorum yırtınırcasına

Ve aglamak haykırırcasına

Bogulacaksam düşüncelerimde degil;

Gözyaşlarımda  bogulayım istiyorum;

Olmuyor ne yazık ki; aglayamıyorum

Bir mezar başında ettigim yemin geliyor aklıma

Bir daha aglamayacagıma dair yeminim

Böyle, anılarla dolu geçer hep gecelerim

Usulca çöker içime bir buruk kimsesizlik

Ve işte yine gece,yine sessizlik...

                                   m.ugur açıkgöz', 'İşte gece oldu,sessiz ve karanlık Yalnızlıgımı paylaşan sadece yalnızlık Bana sorulmadan çizilmiş yolum Ne kadar gidebilirim,bilmiyorum Çıld...', ARRAY['Türk Edebiyatı','Şiir','Uğur Açıkgöz']::text[], 8.5, '{"poet":"Uğur Açıkgöz","poet_slug":"ugur-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-yine-gece-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lethe', 'lethe-hilmi-yavuz-6q0iq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiir, şiirin kurdudur

işte zümrüt ve sürüngen

		bir dize

gidiyor;-gidişi

öteki şiire doğru’dur

şiirdir seni saran sur

kalbim, usul bir düden

ve sanki bir büyüden

artakalandı ve aktıydı

yazları söylete söylete

lethe! yeşil bellek!

sen de unuttundu yurdunu

		ve birdenbire

kendi suyunu terk eden

bir ırmak gibi aktındı

şiirden şiire', 'şiir, şiirin kurdudur işte zümrüt ve sürüngen 		bir dize gidiyor;-gidişi öteki şiire doğru’dur şiirdir seni saran sur kalbim, usul bir düden...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/lethe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Dedikleri', 'sevgi-dedikleri-mehmet-ozturk-4-fqrx5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sesini duyduğumda kalbim çarpar

seni gördüğümde heyecan basar

elini tuttuğumda bedenim titrer

sensiz olmaksa ölümden beter

sen gelince aşka var çeyrek

benim sevdiğim tam bir melek

sevgi dedikleri bu olsa gerek', 'sesini duyduğumda kalbim çarpar seni gördüğümde heyecan basar elini tuttuğumda bedenim titrer sensiz olmaksa ölümden beter sen gelince aşka ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Öztürk 4']::text[], 8.5, '{"poet":"Mehmet Öztürk 4","poet_slug":"mehmet-ozturk-4","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen veya Baskasi', 'sen-veya-baskasi-sair-erhan-53dxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Sensiz'' gecen gunler var aklimda

Soğuk ayaz geceler var

içimde bosluk var

bir umut..

sanki geri gelicekmissin gibi

bak ellerim soğuk

rengim bile soldu ''seni'' düşünmekten

günün her saati , her dakikasi , her anı yanimdasin

kalbimde öyle bir yerin varki;

söküp atsam seni ölecekmisim gibi

aklimda bi yerin varki ;

''Seni'' ''senin'' kadar düsünen 

gözlerimi her kapattigimda,

''sen'' varsin karsimda

gozlerin var

öyle bi bağliyimki sana

koparsalar..

Yasamak zor gelir bana

Yasasamda bedenim yasar.

Ruhum ''senin''

kalbim,aklim ''senin''

istemezdim böyle olmasini

aradiğim yillardir istediğim 

bir seyler var ''sende''

gozlerinde..

yasamak istediğim.

geride guzel seyler birakmak istediğim

anilar var ''sende''

öyle bi yaraladinki beni

Kanadi kirilan Kus gibi 

caresiz öksüz kaldim

Ama Asla vazgecmedim ''senden''

yada sevginden

''sen'' olmasan bile sevgin var

beni yasatan , hayata baglayan

umudum var..

hayatimin sonuna kadarda sürse 

beklicem ''seni.''

Sadece bunu bil.

ve bilki Sadece ''seni'' sevdigimden beklemicem

O arnavut damarimdan inadimdan beklicem seni.

''SEN'' dediğim bir sevgili değil..

Sadece biri ile yasamak istediğim Duygulardir.

bir Sevgili yada bir arkadas önemsiz.

Zaten guvenim yok insanlara

sirtimi dayadiğim her insan 

yikti beni mahfetti.

Benim aradiğim sadece

gercek Sevgili yada arkadas

Ama inanmiyorum

Yok böle bi zihniyet.

Ve iste bu yuzden beklicem hayatimin sonuna kadar

''SEN'' veya ''O'' anlami yok benim için

Inandiğim tek iki kaldi

DOSTLUK VE SEVGİ 

ama buna layik insan varmi ?', '''Sensiz'' gecen gunler var aklimda Soğuk ayaz geceler var içimde bosluk var bir umut.. sanki geri gelicekmissin gibi bak ellerim soğuk rengim...', ARRAY['Türk Edebiyatı','Şiir','Şair Erhan']::text[], 8.5, '{"poet":"Şair Erhan","poet_slug":"sair-erhan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sen-veya-baskasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Ben', 'belki-ben-nazim-hikmet-ran-p278k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki ben 

         o günden 

         çok daha evvel,

         köprü başında sallanarak

         bir  sabah vakti gölgemi asfalta salacağım.

Belki ben

         o günden

                     çok daha sonra ,

matruş çenemde ak bir sakalın izi

                                             
..........
..........', 'Belki ben           o günden           çok daha evvel,          köprü başında sallanarak          bir  sabah vakti gölgemi asfalta salacağım...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/belki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-murat-aslan-citir-riw6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gecemidir insana hüznü veren 

yoksa insanmıdır 

hüzünlenmek için 

geceyi bekleyen

gecemidir seni bana düşündüren

yoksa benmiyim seni düşünmek için 

geceyi bekleyen', 'gecemidir insana hüznü veren  yoksa insanmıdır  hüzünlenmek için  geceyi bekleyen gecemidir seni bana düşündüren yoksa benmiyim seni düşünme...', ARRAY['Türk Edebiyatı','Şiir','Murat Aslan Çıtır']::text[], 8.5, '{"poet":"Murat Aslan Çıtır","poet_slug":"murat-aslan-citir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemezdim', 'donemezdim-riza-aslan-xbz7k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dönemezdim,

bu yoldan dönemezdim

ben,ben değildim artık

bu yolculuk boyunca ben,

beni kaybetmiştim

dönemezdim,

yıkmıştım geçtiğim köprüleri

yakmıştım yattığım otelleri

dönemezdim

anılarım artık yoktu benimle

sen yoktun 

ve artık olmayacaktın kesinlikle

dönemezdim

ben ,ben değildim artık

yıkmıştım geçtiğim köprüleri

yakmıştım yattığım otelleri

dönemezdim...', 'dönemezdim, bu yoldan dönemezdim ben,ben değildim artık bu yolculuk boyunca ben, beni kaybetmiştim dönemezdim, yıkmıştım geçtiğim köprüleri ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/donemezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah-Beyaz', 'siyah-beyaz-riza-aslan-n7khv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'belleğimde belli belirsiz bir kız

adı yok ve siyah-beyaz

ama onu sevdiğimi bilmek

hoşuma gidiyor.', 'belleğimde belli belirsiz bir kız adı yok ve siyah-beyaz ama onu sevdiğimi bilmek hoşuma gidiyor....', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siyah-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulaşılmaz bir hayal', 'ulasilmaz-bir-hayal-riza-aslan-jw3xi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ulaşıl( a )maz bir hayaldi bizimkisi

hem de biz bu kadar yakınındayken', 'ulaşıl( a )maz bir hayaldi bizimkisi hem de biz bu kadar yakınındayken...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ulasilmaz-bir-hayal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın yerdeyim', 'biraktigin-yerdeyim-riza-aslan-6yl8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bıraktığın yerde kaldım

kaç kış geçti aradan,yine öyle soğuk

kaç bahar geçti,hep mayısta başlayan

kaç yaz geçti, yaşanmayan

ben bıraktığın yerde kaldım', 'bıraktığın yerde kaldım kaç kış geçti aradan,yine öyle soğuk kaç bahar geçti,hep mayısta başlayan kaç yaz geçti, yaşanmayan ben bıraktığın y...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biraktigin-yerdeyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figür', 'figur-riza-aslan-yfx7a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşüncelerimde

başka birileri var başka duygularla

sen,o çok sevdiğim tablo

ve sen hergün silinen bir figür

ve sen kaybolan bir hayal', 'düşüncelerimde başka birileri var başka duygularla sen,o çok sevdiğim tablo ve sen hergün silinen bir figür ve sen kaybolan bir hayal...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/figur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
